INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1599, 67, 20200347, NULL, NULL, '', NULL, NULL, NULL, '2、岐伯对曰：必以稻米。炊之稻薪。稻米者完。稻薪者坚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957144887366, '75A22A2BCF22E707ABE7A2BE6C4A8C43', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1600, 67, 20200348, NULL, NULL, '', NULL, NULL, NULL, '3、帝曰： 何以然？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957144887367, '4256CCA53A23A46403E0EAA94D875EB5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1601, 67, 20200349, NULL, NULL, '', NULL, NULL, NULL, '4、岐伯曰：此得天地之和。高下之宜。故能至完。伐取得时。故能至坚也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957144887368, '70494889D24E43B6E14E94422B81FB53', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1602, 67, 20200350, NULL, NULL, '', NULL, NULL, NULL, '5、帝曰：上古圣人作汤液醪醴。为而不用何也？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957144887369, '53FBA5818637ED135CD1D61A960F1793', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1603, 67, 20200351, NULL, NULL, '', NULL, NULL, NULL, '6、岐伯曰：自古圣人之作汤液醪醴者。以为备耳。夫上古作汤液。故为而弗服也。中古之世。道德稍衰。邪气时至。服之万全。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957144887370, 'E54961EAFBEB96F2F804B64FC5951CE8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1604, 67, 20200352, NULL, NULL, '', NULL, NULL, NULL, '7、帝曰：今之世不必已何也？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957144887371, 'F3E5C51AC5A329F7C432927E606D2DD4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1605, 67, 20200353, NULL, NULL, '', NULL, NULL, NULL, '8、岐伯曰：当今之世。必齐毒药攻其中。石针艾治其外也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957144887372, 'FE4F947ACD273031CABE277E14ED2F1E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:11', NULL, NULL, NULL);
