INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1780, 72, 20200528, NULL, NULL, '', NULL, NULL, NULL, '16、岐伯曰：其气来。毛而中央坚。两旁虚。此谓太过。病在外。其气来。毛而微。此谓不及。病在中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957146308692, '6B91FCF6FF02249C7328A82FECB5E591', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:12', NULL, NULL, NULL);
