INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3121, 121, 20201869, NULL, NULL, '', NULL, NULL, NULL, '93、岐伯曰：出入废则神机化灭。升降息则气立孤危。故非出入。则无以生长壮老已。非升降。则无以生长化收藏。是以升降出入。无器不有。故器者生化之宇。器散则分之。生化息矣。故无不出入。无不升降。化有小大。期有近远。四者之有。而贵常守。反常则灾害至矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957158719590, '63C2D659B3598F1E9C47948D9D84C8C3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3122, 121, 20201870, NULL, NULL, '', NULL, NULL, NULL, '94、故曰：无形无患。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957158719591, '8A1F2055346A3BEE7BF43C217335D1B8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3123, 121, 20201871, NULL, NULL, '', NULL, NULL, NULL, '95、帝曰：善。有不生不化乎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957158719592, '2505F83F793843F65E16C80B30078FA5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
