INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3303, 124, 20202051, NULL, NULL, '', NULL, NULL, NULL, '39、凡此阳明司天之政。气化营运后天。天气急。地气明。阳专其令。炎暑大行。物燥以坚。淳风乃治。风燥横运。流于气交。多阳少阴。云趋雨府。湿化乃敷。燥极而泽。其谷白丹。间谷命太者。其耗白甲品羽。金火合德。上应太白荧惑。其政切。其令暴。蛰虫乃见。流水不冰。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159657579, '6B35B31AD4F1879BE2C9B0E37DC46CE6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
