INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3312, 124, 20202060, NULL, NULL, '', NULL, NULL, NULL, '48、故食岁谷以安其气。食间谷以去其邪。岁宜以咸以苦以辛。汗之清之散之。安其运气。无使受邪。折其郁气。资其化源。以寒热轻重少多其制。同热者多天化。同清者多地化。用凉远凉。用热远热。用寒远寒。用温远温。食宜同法。有假者反之。此其道也。反是者。乱天地之经。扰阴阳之纪也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159657588, '1E4D92C54E62CBF3BA4C6BC6CD6A5282', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
