INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3494, 124, 20202242, NULL, NULL, '', NULL, NULL, NULL, '230、岐伯曰：太过者暴。不及者徐。暴者为病甚。徐者为病持。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159669886, '5A5DF0D4E7DB3BC0F37CC0A8C3786CD4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3495, 124, 20202243, NULL, NULL, '', NULL, NULL, NULL, '231、帝曰：太过不及。其数何如？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159669887, '978D5F913B18E9E72372CBDC300E37DA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3496, 124, 20202244, NULL, NULL, '', NULL, NULL, NULL, '232、岐伯曰：太过者其数成。不及者其数生。土常以生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673925, '1144DC5C905F7935A8CE2BFF4543E48C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3497, 124, 20202245, NULL, NULL, '', NULL, NULL, NULL, '233、帝曰：其发也何如？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673926, 'AC680EE51CEF0825DA1A4038D51B66F5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3498, 124, 20202246, NULL, NULL, '', NULL, NULL, NULL, '234、岐伯曰：土郁之发。岩谷震惊。雷殷气交。埃昏黄黑。化为白气。飘骤高深。击石飞空。洪水乃从。川流漫衍。田牧土驹。化气乃敷。善为时雨。始生始长。始化始成。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673927, '0FA59680CB8D188A1D8B16F49E73CEF2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3499, 124, 20202247, NULL, NULL, '', NULL, NULL, NULL, '235、故民病心腹胀。肠鸣而为数后。甚则心痛胁䐜。呕吐霍乱。饮发注下。胕肿身重。云奔雨府。霞拥朝阳。山泽埃昏。其乃发也。以其四气。云横天山。浮游生灭。怫之先兆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673928, 'E6BFF44201394EB18A91BC79A1CF3DDC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3500, 124, 20202248, NULL, NULL, '', NULL, NULL, NULL, '236、金郁之发。天洁地明。风清气切。大凉乃举。草树浮烟。燥气以行。霿雾数起。杀气来至。草木苍干。金乃有声。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673929, '2A975539F5B8B21BA4E1CB515F3E6481', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3501, 124, 20202249, NULL, NULL, '', NULL, NULL, NULL, '237、故民病咳逆。心胁满引少腹。善暴痛。不可反侧。嗌干面尘色恶。山泽焦枯。土凝霜卤。怫乃发也。其气五。夜零白露。林莽声凄。怫之兆也。  水郁之发。阳气乃辟。阴气暴举。大寒乃至。川泽严凝。寒结为霜雪。甚则黄黑昏翳。流行气交。乃为霜杀。水乃见祥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673930, 'A376D25A2C798C06510C5BE4C2EF1877', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3502, 124, 20202250, NULL, NULL, '', NULL, NULL, NULL, '238、故民病寒客心痛。腰脽痛。大关节不利。屈伸不便。善厥逆。痞坚腹满。阳光不治。空积沉阴。白埃昏瞑。而乃发也。其气二火前后。太虚深玄。气犹麻散。微见而隐。色黑微黄。怫之先兆也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673931, 'FFA7D27CBC3071C590322545AFAB60A4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3503, 124, 20202251, NULL, NULL, '', NULL, NULL, NULL, '239、木郁之发。太虚埃昏。云物以扰。大风乃至。屋发折木。木有变。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673932, '178370AB67090771DC0735FC5A21AE88', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3504, 124, 20202252, NULL, NULL, '', NULL, NULL, NULL, '240、故民病胃脘当心而痛。上支两胁。膈咽不通。食饮不下。甚则耳鸣眩转。目不识人。善暴僵仆。太虚苍埃。天山一色。或气浊色。黄黑郁若。横云不起雨。而乃发也。其气无常。 长川草偃。柔叶呈阴。松吟高山。虎啸岩岫。怫之先兆也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673933, 'F16E264BD93FCA831209DBE3BDB8B5A7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3505, 124, 20202253, NULL, NULL, '', NULL, NULL, NULL, '241、火郁之发。太虚曛翳。大明不彰。炎火行。大暑至。山泽燔燎。材木流津。广厦腾烟。土浮霜卤。止水乃减。蔓草焦黄。风行惑言。湿化乃后。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673934, '0B44D77DB2F833E2025DF68E5FCA6043', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3506, 124, 20202254, NULL, NULL, '', NULL, NULL, NULL, '242、故民病少气。疮疡痈肿。胁腹胸背。面首四肢。䐜愤胪胀。疡痱呕逆。瘛疭骨痛。节乃有动。注下温疟。腹中暴痛。血溢流注。精液乃少。目赤心热。甚则瞀闷懊憹。善暴死。刻终大温。汗濡玄府。其乃发也。其气四。动复则静。阳极反阴。湿令乃化乃成。华发水凝。山川冰雪。焰阳午泽。怫之先兆也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673935, '1FDAB6E4AA37B939A75680A9913EE790', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3507, 124, 20202255, NULL, NULL, '', NULL, NULL, NULL, '243、有怫之应而后报也。皆观其极而乃发也。木发无时。水随火也。谨候其时。病可与期。失时反岁。五气不行。生化收藏。政无恒也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673936, '48655D22979DE7FA10B3ABFE828DDC15', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3508, 124, 20202256, NULL, NULL, '', NULL, NULL, NULL, '244、帝曰：水发而雹雪。土发而飘骤。木发而毁折。金发而。清明。火发而曛昧。何气使然？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673937, '9213C55E6C86C653E1F9F92A5BA21D7D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3509, 124, 20202257, NULL, NULL, '', NULL, NULL, NULL, '245、岐伯曰：气有多少。发有微甚。微者当其气。甚者兼其下。征其下气而见可知也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673938, '595C9ACDE141BFE71B1ECF4C475F8633', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3510, 124, 20202258, NULL, NULL, '', NULL, NULL, NULL, '246、帝曰：善。五气之发。不当位者何也？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957159673939, '53A841C31D52A99FCFA1670B46EB8D56', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:17', NULL, NULL, NULL);
