INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4094, 132, 20202842, NULL, NULL, '', NULL, NULL, NULL, '29、秋三月之病。三阳俱起。不治自已。阴阳交合者。 立不能坐。坐不能起。三阳独至。期在石水。二阴独至。期在盛水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957162356833, '214B6FAEAF2D26860DD8BCF9BD6B04B6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:53:18', NULL, NULL, NULL);
