INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4514, 160, 20300379, NULL, NULL, '', NULL, NULL, NULL, '28、痿厥为四末束悗。乃疾解之。日二。不仁者。十日而知。无休。病已止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209047136, '8B8C4EFE0BA200AC123B7C1ACBBDDDA6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4515, 160, 20300380, NULL, NULL, '', NULL, NULL, NULL, '29、哕以草刺鼻。嚏。嚏而已。无息。而疾迎引之。立已。大惊之。亦可已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209047137, '0E0748C53556A8EFE56560D9535FF2D8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4516, 161, 20300381, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。周痹之在身也。上下移徒随脉。其上下左右相应。间不容空。愿闻此痛。在血脉之中邪。将在分肉之间乎。何以致是。其痛之移也。间不及下针。其慉痛之时。不及定治。而痛已止矣。何道使然。愿闻其故。岐伯答曰。此众痹也。非周痹也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209280581, 'F7F6B57610B5117D6181E58BD309F2D3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4517, 161, 20300382, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。愿闻众痹。岐伯对曰。此各在其处。更发更止。更居更起。以右应左。以左应右。非能周也。更发更休也。黄帝曰。善。刺之奈何。岐伯对曰。刺此者。痛虽已止。必刺其处。勿令复起。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209280582, '8CA6DCA803BF5A83DBA1CE5B463EB085', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4518, 161, 20300383, NULL, NULL, '', NULL, NULL, NULL, '3、帝曰。善。愿闻周痹何如。岐伯对曰。周痹者。在于血脉之中。随脉以上。随脉以下。不能左右。各当其所。黄帝曰。刺之奈何。岐伯对曰。痛从上下者。先刺其下以过之。后刺其上以脱之。痛从下上者。先刺其上以过之。后刺其下以脱之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209280583, '10C581FA68565002EF668A7AB41D5BE7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4519, 161, 20300384, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。善。此痛安生。何因而有名。岐伯对曰。风寒湿气。客于外分肉之间。迫切而为沫。沫得寒则聚。聚则排分肉而分裂也。分裂则痛。痛则神归之。神归之则热。热则痛解。痛解则厥。厥则他痹发。发则如是。帝曰。善。余已得其意矣。此内不在藏。而外未发于皮。独居分肉之间。真气不能周。故名曰周痹。故刺痹者。必先切循其下之六经。视其虚实。及大络之血结而不通。及虚而脉陷空者而调之。熨而通之。其瘈坚转引而行之。黄帝曰。善。余已得其意矣。亦得其事也。九者经巽之理。十二经脉阴阳之病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209280584, '31850942D94319BFEE8E9612EBDF61F8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4520, 162, 20300385, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝闲居。辟左右而问于岐伯曰。余已闻九针之经。论阴阳逆顺。六经已毕。愿得口问。岐伯避席再拜曰。善乎哉问也。此先师之所口传也。黄帝曰。愿闻口传。岐伯答曰。夫百病之始生也。皆生于风雨寒暑。阴阳喜怒。饮食居处。大惊卒恐。则血气分离。阴阳破败。经络厥绝。脉道不通。阴阳相逆。卫气稽留。经脉虚空。血气不次。乃失其常。论不在经者。请道其方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509957, 'E153365781E7B9872395317AF4D1268F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4521, 162, 20300386, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。人之欠者。何气使然。岐伯答曰。卫气昼日行于阳。夜半则行于阴。阴者主夜。夜者卧。阳者主上。阴者主下。故阴气积于下。阳气未尽。阳引而上。阴引而下。阴阳相引。故数欠。阳气尽。阴气盛。则目瞑。阴气尽而阳气盛。则寤矣。泻足少阴。补足太阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509958, '3C2BE31D9505842EA494863A1EA04D81', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4522, 162, 20300387, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。人之哕者。何气使然。岐伯曰。谷入于胃。胃气上注于肺。今有故寒气与新谷气。俱还入于胃。新故相乱。真邪相攻。气并相逆。复出于胃。故为哕。补手太阴。泻足少阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509959, '1FF1EF8871FFCCAA01ECE9EE99BD6F7D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4523, 162, 20300388, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。人之唏者。何气使然。岐伯曰。此阴气盛而阳气虚。阴气疾而阳气徐。阴气盛而阳气绝。故为唏。补足太阳。泻足少阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509960, '2A907E1142DADBA17665E774BA4D5D32', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4524, 162, 20300389, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。人之振寒者。何气使然。岐伯曰。寒气客于皮肤。阴气盛。阳气虚。故为振寒寒栗。补诸阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509961, '1110F17C4C249B1D8A2938D37A41F4A6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4525, 162, 20300390, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。人之噫者。何气使然。岐伯曰。寒气客于胃。厥逆从下上散。复出于胃。故为噫。补足太阴阳明。一曰补眉本也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509962, '340D48E3A6DC59A2E0EDE0A702B1AB3F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4526, 162, 20300391, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。人之嚏者。何气使然。岐伯曰。阳气和利。满于心。出于鼻。故为嚏。补足太阳荣眉本。一曰眉上也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509963, '79FDD73BFE06A2F77004B0B3D3164391', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4527, 162, 20300392, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。人之亸者。何气使然。岐伯曰。胃不实则诸脉虚。诸脉虚则筋脉懈惰。筋脉懈惰则行阴用力。气不能复。故为亸。因其所在。补分肉间。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509964, 'AB975D3CEB7F76BD87ABDD55B60DCB2F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4528, 162, 20300393, NULL, NULL, '', NULL, NULL, NULL, '9、黄帝曰。人之哀而泣涕出者。何气使然。岐伯曰。心者。五藏六府之主也。目者。宗脉之所聚也。上液之道也。口鼻者。气之门户也。故悲哀愁忧则心动。心动则五藏六府皆摇。摇则宗脉感。宗脉感则液道开。液道开。故泣涕出焉。液者。所以灌精濡空窍者也。故上液之道开则泣。泣不止则液竭。液竭则精不灌。精不灌则目无所见矣。故命曰夺精。补天柱经侠颈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509965, 'BA6B1BCEAFE55A67A1155F24B5006A33', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4529, 162, 20300394, NULL, NULL, '', NULL, NULL, NULL, '10、黄帝曰。人之太息者。何气使然。岐伯曰。忧思则心系急。心系急则气道约。约则不利。故太息以伸出之。补手少阴心主。足少阳留之也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509966, '34C57C57D43413AA745B965A9CE666B4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4530, 162, 20300395, NULL, NULL, '', NULL, NULL, NULL, '11、黄帝曰。人之涎下者。何气使然。岐伯曰。饮食者。皆入于胃。胃中有热则虫动。虫动则胃缓。胃缓则廉泉开。故涎下。补足少阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509967, 'A5055EB4B25C025C2C4FD7E5EA66CD29', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4531, 162, 20300396, NULL, NULL, '', NULL, NULL, NULL, '12、黄帝曰。人之耳中鸣者。何气使然。岐伯曰。耳者。宗脉之所聚也。故胃中空则宗脉虚。虚则下溜。脉有所竭者。故耳鸣。补客主人。手大指爪甲上与肉交者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509968, '8DF787B9EF13ABE5A3C56301555B7523', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4532, 162, 20300397, NULL, NULL, '', NULL, NULL, NULL, '13、黄帝曰。人之自啮舌者。何气使然。岐伯曰。此厥逆走上。脉气辈至也。少阴气至则啮舌。少阳气至则啮颊。阳明气至则啮唇矣。视主病者。则补之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509969, '0883273769ADE397D80A3890C671760C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4533, 162, 20300398, NULL, NULL, '', NULL, NULL, NULL, '14、凡此十二邪者。皆奇邪之走空窍者也。故邪之所在。皆为不足。故上气不足。脑为之不满。耳为之苦鸣。头为之苦倾。目为之眩。中气不足。溲便为之变。肠为之苦鸣。下气不足。则乃为痿厥心悗。补足外踝下留之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509970, '8E4CB1CE80EC2108BC3144B8C12B9C93', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4534, 162, 20300399, NULL, NULL, '', NULL, NULL, NULL, '15、黄帝曰。治之奈何。岐伯曰。肾主为欠。取足少阴。肺主为哕。取手太阴。足少阴。唏者。阴与阳绝。故补足太阳。泻足少阴。振寒者。补诸阳。噫者。补足太阴阳明。嚏者。补足太阳眉本。亸。因其所在。补分肉间。泣出补天柱经侠颈。侠颈者。头中分也。太息。补手少阴。心主。足少阳。留之。涎下补足少阴。耳鸣补客主人。手大指爪甲上与肉交者。自啮舌。视主病者。则补之。目眩头倾。补足外踝下留之。痿厥心悗。刺足大指间上二寸。留之。一曰足外踝下留之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209509971, '988948E468FC58B6B01EF94769395CFD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4535, 163, 20300400, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余闻先师。有所心藏。弗着于方。余愿闻而藏之。则而行之。上以治民。下以治身。使百姓无病。上下和亲。德泽下流。子孙无优。传于后世。无有终时。可得闻乎。岐伯曰。远乎哉问也。夫治民与自治。治彼与治此。治小与治大。治国与治家。未有逆而能治之也。夫惟顺而已矣。顺者。非独阴阳脉。论气之逆顺也。百姓人民皆欲顺其志也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743429, 'C92C1272B2A9E67F301A5A573FD617BF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4536, 163, 20300401, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。顺之奈何。岐伯曰。入国问俗。入家问讳。上堂问礼。临病人问所便。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743430, '28C2766249064E31030CCABC11442001', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4537, 163, 20300402, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。便病人奈何。岐伯曰。夫中热消瘅。则便寒。寒中之属。则便热。胃中热则消谷。令人悬心善饥。脐以上皮热。肠中热。则出黄如糜。脐以下皮寒。胃中寒。则腹胀。肠中寒。则肠鸣飧泄。胃中寒。肠中热。则胀而且泄。胃中热。肠中寒。则疾饮。小腹痛胀。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743431, 'B7BB53A3C84B5708DD9B4726B0EC88C0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4538, 163, 20300403, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。胃欲寒饮。肠欲热饮。两者相逆。便之奈何。且夫王公大人。血食之君。骄恣从欲轻人。而无能禁之。禁之则逆其志。顺之则加其病。便之奈何。治之何先。岐伯曰。人之情。莫不恶死而喜生。告之以其败。语之以其善。导之以其所便。开之以其所苦。虽有无道之人。恶有不听者乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743432, '17C98E67B79663C06D0B16907C2BB944', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4539, 163, 20300404, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。治之奈何。岐伯曰。春夏先治其标。后治其本。秋冬先治其本。后治其标。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743433, 'F814628CC10DA1058C2915A0AC8C71D4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4540, 163, 20300405, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。便其相逆者奈何。岐伯曰。便此者。食饮衣服。亦欲适寒温。寒无凄怆。暑无出汗。食饮者。热无灼灼。寒无沧沧。寒温中适。故气将持。乃不致邪僻也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743434, '94197B60BE6ABC0BD202DFBFE60024B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4541, 163, 20300406, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。本藏以身形肢节䐃肉。候五藏六府之大小焉。今夫王公大人。临朝即位之君。而问焉。谁可扪循之。而后答乎。岐伯曰。身形肢节者。藏府之盖也。非面部之阅也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743435, 'F1D7A4B45817B3F2E713927CEC8AE1EA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4542, 163, 20300407, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。五藏之气。阅于面者。余已知之矣。以肢节知而阅之。奈何。岐伯曰。五藏六府者。肺为之盖。巨肩陷咽。候见其外。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743436, '28E9C3D044450D39C5142D7982D30DD0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4543, 163, 20300408, NULL, NULL, '', NULL, NULL, NULL, '9、岐伯曰。五藏六府。心为之主。缺盆为之道。骷骨有余以候𩩲骬。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743437, '5D12D81F7A557867F9592CCB59467877', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4544, 163, 20300409, NULL, NULL, '', NULL, NULL, NULL, '10、岐伯曰。肝者。主为将。使之候外。欲知坚固。视目小大。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743438, '5EE31B7054FF61EC0623397899A4CCF2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4545, 163, 20300410, NULL, NULL, '', NULL, NULL, NULL, '11、岐伯曰。脾者。主为卫。使之迎粮。视唇舌好恶。以知吉凶。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743439, 'FCC565FC176166E23AE24841BFEC7CB3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4546, 163, 20300411, NULL, NULL, '', NULL, NULL, NULL, '12、岐伯曰。肾者。主为外。使之远听。视耳好恶。以知其性。黄帝曰。善。愿闻六府之候。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743440, '958A58F5C2CFB53D949CEB6D878F5844', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4547, 163, 20300412, NULL, NULL, '', NULL, NULL, NULL, '13、岐伯曰。六府者。胃为之海。庞骸。大颈。张胸。五谷乃容。鼻隧以长。以候大肠。唇厚。人中长。以候小肠。目下果大。其胆乃横。鼻孔在外。膀胱漏泄。鼻柱中央起。三焦乃约。此所以候六府者也。上下三等。藏安且良矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209743441, '2D5A00437AA780D8052A18DE36953C29', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4548, 164, 20300413, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余闻人有精。气。津。液。血。脉。余意以为一气耳。今乃辨为六名。余不知其所以然。岐伯曰。两神相搏。合而成形。常先身生。是谓精。何谓气。岐伯曰。上焦开发。宣五谷味。熏肤。充身。泽毛。若雾露之溉。是谓气。何谓津。岐伯曰。腠理发泄。汗出溱溱。是谓津。何谓液。岐伯曰。谷入气满。淖泽注于骨。骨属屈伸。泄泽补益脑髓。皮肤润泽。是谓液。何谓血。岐伯曰。中焦受气。取汁变化而赤。是谓血。何谓脉。岐伯曰。壅遏营气。令无所避。是谓脉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209976901, '65E1ED49BB196598546B195387DDB650', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4549, 164, 20300414, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。六气有。有余不足。气之多少。脑髓之虚实。血脉之清浊。何以知之。岐伯曰。精脱者。耳聋。气脱者。目不明。津脱者。腠理开。汗大泄。液脱者。骨属屈伸不利。色夭。脑髓消。胫痹。耳数鸣。血脱者。色白。夭然不泽。其脉空虚。此其候也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209976902, 'B48F0F5E7074A5D0AD8695CD1C348C08', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4550, 164, 20300415, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。六气者。贵贱何如。岐伯曰。六气者。各有部主也。其贵贱善恶。可为常主。然五谷与胃为大海也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957209976903, 'BA6638873BBC6B15988E1596991893CD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4551, 165, 20300416, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于伯高曰。余愿闻六府传谷者。肠胃之大小长短。受谷之多少奈何。伯高曰。请尽言之。谷所从出入浅深远近长短之度。唇至齿长九分。口广二寸半。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十两。广一寸半。至胃长一尺六寸。胃纡曲屈。伸之。长二尺六寸。大一尺五寸。径五寸。大容三斗五升。小肠后附脊。左环回日迭积。其注于回肠者。外附于脐上。回运环十六曲。大二寸半。径八分分之少半。长三丈三尺。回肠当脐左环。回周叶积而下。回运还反十六曲。大四寸。径一寸寸之少半。长二丈一尺。广肠传脊。以受回肠。左环叶脊上下。辟大八寸。径二寸寸之大半。长二尺八寸。肠胃所入至所出。长六丈四寸四分。回曲环反。三十二曲也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210189893, '6F16FD9FE081906BA2697DA0A69D07E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4552, 166, 20300417, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。愿闻人之不食。七日而死。何也。伯高曰。臣请言其故。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210411077, 'A4D1B86A260BE7F5CCADE6F9D1A393EC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4553, 166, 20300418, NULL, NULL, '', NULL, NULL, NULL, '2、胃大一尺五寸。径五寸。长二尺六寸。横屈受水谷三斗五升。其中之谷。常留二斗。水一斗五升而满。上焦泄气。出其精微。慓悍滑疾。下焦下溉诸肠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210411078, '0A8A094C5E43D02D430A401807AFEB36', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4554, 166, 20300419, NULL, NULL, '', NULL, NULL, NULL, '3、小肠大二寸半。径八分分之少半。长三丈二尺。受谷二斗四升。水六升三合合之大半。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210411079, '40D4F984320B36B2CEAC554CDB9BE221', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4555, 166, 20300420, NULL, NULL, '', NULL, NULL, NULL, '4、回肠大四寸。径一寸寸之少半。长二丈一尺。受谷一斗。水七升半。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210411080, '65394E9FE08FED5F967549E7099DCFB2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4556, 166, 20300421, NULL, NULL, '', NULL, NULL, NULL, '5、广肠大八寸。径二寸寸之大半。长二尺八寸。受谷九升三合八分合之一。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210411081, 'B0D4B9DBE4EE13D19B4F7ED5E7DC4C73', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4557, 166, 20300422, NULL, NULL, '', NULL, NULL, NULL, '6、肠胃之长。凡五丈八尺四寸。受水谷九斗二升一合合之大半。此肠胃所受水谷之数也。平人则不然。胃满则肠虚。肠满则胃虚。更虚更满。故气得上下。五藏安定。血脉和利。精神乃居。故神者。水谷之精气也。故肠胃之中。当留谷二斗。水一斗五升。故平人日再后。后二升半。一日中五升。七日五七三斗五升。而留水谷尽矣。故平人不食饮七日而死者。小谷精气津液皆尽故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210411082, '0A2C404DA1BEB7BD09CBEB1D217ED3C4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4558, 167, 20300423, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余闻刺法于夫子。夫子之所言。不离于营卫血气。夫十二经脉者。内属于府藏。外络于肢节。夫子乃合之于四海乎。岐伯答曰。人亦有四海。十二经水。经水者。皆注于海。海有东西南北。命曰四海。黄帝曰。以人应之奈何。岐伯曰。人有髓海。有血海。有气海。有水谷之海。凡此四者。以应四海也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210636357, '083851091D3315313146CC69954E9575', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4559, 167, 20300424, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。远乎者。夫子之合人天地四海也。愿闻应之奈何。岐伯曰。必先明知阴阳表里荥输所在。四海定矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210636358, '8D677642C0D2FF2D00A96C9802D2F919', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4560, 167, 20300425, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。定之奈何。岐伯曰。胃者水谷之海。其输上在气街$a{冲}。下至三里。冲脉者。为十二经之海。其输上在于大杼。下出于巨虚之上下廉。膻中者。为气之海。其输上在于柱骨之上下。前在于人迎。脑为髓之海。其输上在于其盖。下在风府。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210636359, '2E0FAF57627F5C86DFE72657CD492ED1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4561, 167, 20300426, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。凡此四海者。何利何害。何生何败。岐伯曰。得顺者生。得逆者败。知调者利。不知调者害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210636360, 'BF62F8B21BC66919C1793CA713A7D903', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4562, 167, 20300427, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。四海之逆顺奈何。岐伯曰。气海有余者。气满胸中。悗息面赤。气海不足。则气少不足以言。血海有余。则常想其身大。怫然不知其所病。血海不足。亦常想其身小。狭然不知其所病。水谷之海有余。则腹满。水谷之海不足。则饥不受谷食。髓海有余。则轻劲多力。自过其度。髓海不足。则脑转耳鸣。胫酸眩冒。目无所见。懈怠安卧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210636361, '7E371AAFE7DDA5B7784DF9D8BFC0822F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4563, 167, 20300428, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。余已闻逆顺。调之奈何。岐伯曰。审守其俞。而调其虚实。无犯其害。顺者得复。逆者必败。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210636362, '49FF79DA80FFA39846122002F307B32E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:46', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4564, 168, 20300429, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。经脉十二者。别为五行。分为四时。何失而乱。何得而治。岐伯曰。五行有序。四时有分。相顺则治。相逆则乱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210857541, '21E4E46EFFBE8AFF434BA44E3E574EE1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4565, 168, 20300430, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。何谓相顺。岐伯曰。经脉十二者。以应十二月。十二月者。分为四时。四时者。春秋冬夏。其气各异。营卫相随。阴阳已知。清浊不相干。如是则顺之而治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210857542, 'C99D00DB94A0A335ED46A5E96DFABF00', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4566, 168, 20300431, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。何为逆而乱。岐伯曰。清气在阴。浊气在阳。营气顺脉。卫气逆行。清浊相干。乱于胸中。是谓大悗。故气乱于心。则烦心密嘿。俛首静伏。乱于肺。则俛仰喘喝。接手以呼。乱于肠胃。是为霍乱。乱于臂胫。则为四厥。乱于头。则为厥逆。头重眩仆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210857543, '33C22581B5AD97F7DFB232B9C3E1B6A0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4567, 168, 20300432, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。五乱者。刺之有道乎。岐伯曰。有道以来。有道以去。审知其道。是谓身宝。黄帝曰。善。愿闻其道。岐伯曰。气在于心者。取之手少阴心主之俞。气在于肺者。取之手太阴荥。足少阴俞。气在于肠胃者。取之足太阴阳明。不下者。取之三里。气在于头者。取之天柱大杼。不知。取足太阳荥俞。气在于臂足。取之先去血脉。后取其阳明少阳之荥俞。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210857544, '041B7FDA35AD5209EFF1DBA97C68E323', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4568, 168, 20300433, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。补泻奈何。岐伯曰。徐入徐出。谓之导气。补泻无形。谓之同精。是非有余不足也。乱气之相逆也。黄帝曰。允乎哉道。明乎哉论。请着之玉版。命曰治乱也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957210857545, 'B794BF738EC973E7D27231B5EC585FB9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4569, 169, 20300434, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。脉之应于寸口。如何而胀。岐伯曰。其脉大坚以涩者。胀也。黄帝曰。何以知藏府之胀也。岐伯曰。阴为藏。阳为府。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211082821, 'B3526DA903D47D61E9A085873896B0E2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4570, 169, 20300435, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。夫气之令人胀也。在于血脉之中耶。藏府之内乎。岐伯曰。三者皆存焉。然非胀之舍也。黄帝曰。愿闻胀之舍。岐伯曰。夫胀者。皆在于藏府之外。排藏府而郭胸胁。胀皮肤。故命曰胀。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211082822, '1450E55370F904292D8E543448CA3A03', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4571, 169, 20300436, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。藏府之在胸胁腹里之内也。若匣匮之藏禁器也。名有次舍。异名而同处。一域之中。其气各异。愿闻其故。黄帝曰。未解其意。再问。岐伯曰。夫胸腹。藏府之郭也。膻中者。心主之宫城也。胃者。太仓也。咽喉。小肠者。传送也。胃之五窍者。闾里门户也。廉泉。玉英者。津液之道也。故五藏六府者。各有畔界。其病各有形状。营气循脉。卫气逆为脉胀。卫气并脉循分为肤胀。三里而泻。近者一下。远者三下。无问虚实。工在疾泻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211082823, 'E1217B06B9CB316CC9723B4D02B60E54', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4572, 169, 20300437, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。愿闻胀形。岐伯曰。夫心胀者烦心短气。卧不安。肺胀者。虚满而喘咳。肝胀者。胁下满而痛引小腹。脾胀者。善秽。四肢烦俛。体重不能胜衣。卧不安。肾胀者。腹满引背央央然。腰髀痛。六府胀。胃胀者。腹满。胃脘痛。鼻闻焦臭。妨于食。大便难。大肠胀者。肠鸣而痛濯濯。冬日重感于寒。则餐泄不化。小肠胀者。少腹慎胀。引腰而痛。膀胱胀者。少腹而气癃。三焦胀者。气满于皮肤中。轻轻然而不坚。胆胀者。胁下痛胀。口中苦。善太息。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211082824, '8CCD7928F7D7E8A96465C69C7A32FF0B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4573, 169, 20300438, NULL, NULL, '', NULL, NULL, NULL, '5、凡此诸胀者。其道在一。明知逆顺。针数不失。泻虚补实。神去其室。致邪失正。真不可定。粗之所败。谓之天命。补虚泻实。神归其室。久塞其空。谓之良工。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211082825, 'CA5D94178EFBD4339CF88883540D83CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4574, 169, 20300439, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。胀者焉生。何因而有。岐伯曰。卫气之在身也。常然并脉。循分肉。行有逆顺。阴阳相随。乃得天和。五藏更始。四时循序。五谷乃化。然后厥气在下。营卫留止。寒气逆上。真邪相攻。两气相搏。乃合为胀也。黄帝曰。善。何以解惑。岐伯曰。合之于真。三合而得。帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211082826, '6C959AFED3FBDACC8B5E8B38349994C2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4575, 169, 20300440, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝问于岐伯曰。胀论言无问虚实。工在疾泻。近者一下。远者三下。今有其三而不下者。其过焉在。岐伯对曰。此言陷于肉肓。而中气穴者也。不中气穴。则气内闭。针不陷肓。则气不行。上越中肉。则卫气相乱。阴阳相逐。其于胀也。当泻不泻。气故不下。三而不下。必更其道。气下乃止。不下复始。可以万全。乌有殆者乎。其于胀也。必审其弥。当泻则泻。当补则补。如鼓应桴。恶有不下者乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211082827, '5F696C2999FC1ED5616AD23B72DE299B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4576, 170, 20300441, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。水谷入于口。输于肠胃。其液别为五。天寒衣薄。则为溺与气。天热衣厚则为汗。悲哀气并则为泣。中热胃缓则为唾。邪气内逆。则气为之闭塞而不行。不行则为水胀。余知其然也。不知其何由生。愿闻其道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304005, '02F649101757ECF4CD6824EB4E7A380A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4577, 170, 20300442, NULL, NULL, '', NULL, NULL, NULL, '2、岐伯曰。水谷皆入于口。其味有五。各注其海。津液各走其道。故三焦出气。以温肌肉。充皮肤。为其津。其流而不行者为液。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304006, '5EF40B4D6042F7110FD1F7705CFCCF2D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4578, 170, 20300443, NULL, NULL, '', NULL, NULL, NULL, '3、天暑衣厚则腠理开。故汗出。寒留于分肉之间。聚沫则为痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304007, '35A1A7D8A8D06FD54A795F3172C99B98', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4579, 170, 20300444, NULL, NULL, '', NULL, NULL, NULL, '4、天寒则腠理闭。气湿不行。水下留于膀胱。则为溺与气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304008, '171D1F98806FC5BFCCD761C196F3744B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4580, 170, 20300445, NULL, NULL, '', NULL, NULL, NULL, '5、五藏六府。心为之主。耳为之听。目为之候。肺为之相。肝为之将。脾为之卫。肾为之主外。故五藏六府之津液。尽上渗于目。心悲气并。则心系急。心系急则肺举。肺举则液上溢。夫心系与肺。不能常举。乍上乍下。故欬而泣出矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304009, '1C1117649D806F4AC17EA9E472A5881C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4581, 170, 20300446, NULL, NULL, '', NULL, NULL, NULL, '6、中热则胃中消谷。消谷则虫上下作。肠胃充郭。故胃缓。胃缓则气逆。故唾出。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304010, '8173119792307469632AC99D0069B626', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4582, 170, 20300447, NULL, NULL, '', NULL, NULL, NULL, '7、五谷之津液。和合而为膏者。内渗入于骨空。补益脑髓。而下流于阴股。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304011, '238A784AD12DF73D67EECE3F9643E32D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4583, 170, 20300448, NULL, NULL, '', NULL, NULL, NULL, '8、阴阳不和。则使液溢而下流于阴。髓液皆减而下。下过度则虚。虚。故腰背痛而胫酸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304012, 'C0BA6722570153118820B4203FBD9C85', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4584, 170, 20300449, NULL, NULL, '', NULL, NULL, NULL, '9、阴阳气道不通。四海闭塞。三焦不泻。津液不化。水谷并行肠胃之中。别于回肠。留于下焦。不得渗膀胱。则下焦胀。水溢则为水胀。此津液五别之逆顺也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211304013, '925C2DBB84C9FB59997FA19ADF586400', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4585, 171, 20300450, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余闻刺有五官五阅。以观五气。五气者。五藏之使也。五时之副也。愿闻其五使当安出。岐伯曰。五官者。五藏之阅也。黄帝曰。愿闻其所出。令可为常。岐伯曰。脉出于气口。色见于明堂。五色更出。以应五时。各如其常。经气入藏。必当治理。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211537477, 'D7299FB2D615389B4BEF8280F41E85A2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4586, 171, 20300451, NULL, NULL, '', NULL, NULL, NULL, '2、帝曰。善。五色独决于明堂乎。岐伯曰。五官已辨。阙庭必张。乃立明堂。明堂广大。蕃蔽见外。方壁高基。引垂居外。五色乃治。平搏广大。寿中百岁。见此者。刺之必已。如是之人者。血气有余。肌肉坚致。故可苦以针。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211537478, 'D8E4552AA6799EC2EF1A8A0DB9DE7767', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4587, 171, 20300452, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。愿闻五官。岐伯曰。鼻者。肺之官也。目者。肝之官也。口唇者。脾之官也。舌者。心之官也。耳者。肾之官也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211537479, '39A67DED140E8238F738510B5642E364', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4588, 171, 20300453, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。以官何候。岐伯曰。以候五藏。故肺病者。喘息鼻张。肝病者。眦青。脾病者。唇黄。心病者。舌卷短。颧赤。肾病者。颧与颜黑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211537480, 'F847112A1E967F927D2ADCCC7396903F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4589, 171, 20300454, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。五脉安出。五色安见。其常色殆者如何。岐伯曰。五官不辨。阙庭不张。小其明堂。蕃蔽不见。又埤其墙。墙下无基。垂角去外。如是者。虽平常殆。况加疾哉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211537481, '34CD698AE38D2ECE697E316738FD5D0B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4590, 171, 20300455, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。五色之见于明堂。以观五藏之气。左右高下。各有形乎。岐伯曰。藏府之在中也。各以次舍。左右上下。各如其度也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211537482, 'E911784ABCF87C817EA3F3039D474C1D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4591, 172, 20300456, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余闻针道于夫子。众多毕悉矣。夫子之道。应若失。而据未有坚然者也。夫子之问学熟乎。将审察于物而心生之乎。岐伯曰。人之为道者。上合于天。下合于地。中合于人事。必有明法。以起度数。法式检押。乃后可传焉。故匠人不能释尺寸而意短长。废绳墨而起平水也。工人不能置规而为圆。去矩而为方。知用此者。固自然之物。易用之教。逆顺之常也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754565, 'E4A0417DC7C1FB2F0DA96881BF68A642', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4592, 172, 20300457, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。愿闻自然奈何。岐伯曰。临深决水。不用功力。而水可竭也。循拙决冲。而经可通也。此言气之滑涩。血水清浊。行之逆顺也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754566, '3610E421D253500D4975B9C119957AF4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4593, 172, 20300458, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。愿闻人之白黑肥瘦小长。各有数乎。岐伯曰。年质壮大。血气充盈。肤革坚固。因加以邪。刺此者。深而留之。此肥人也。广肩腋项。肉薄厚皮而黑色。唇临临然。其血黑以浊。其气涩以迟。其为人也。贪于取与。刺此者。深而留之。多益其数也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754567, '9BB4BF008F670D407BC635A3283E9197', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4594, 172, 20300459, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。刺瘦人奈何。岐伯曰。瘦人者。皮薄色少。肉廉廉然。薄唇轻言。其血清气滑。易脱于气。易损于血。刺此者。浅而疾之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754568, 'D85E64BB7B9B841A89F3A1360811778D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4595, 172, 20300460, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。刺常人奈何。岐伯曰。视其白黑。各为调之。其端正敦厚者。其血气和调。刺此者。无失常数也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754569, '76BE45FE0AD4CBAAD0F11D20D84F11D6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4596, 172, 20300461, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。刺壮士真骨者。奈何。岐伯曰。刺壮士真骨。坚肉缓节。监监然。此人重则气涩血浊。刺此者。深而留之。多益其数。劲则气滑血清。刺此者。浅而疾之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754570, '394BE6B6E37B081B3D9B9F60B044E78F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4597, 172, 20300462, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。刺婴儿奈何。岐伯曰。婴儿者。其肉脆。血少气弱。刺此者。以豪刺。浅刺而疾拔针。日再可也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754571, '92DFD329678C326418DBE77BA3744B60', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4598, 172, 20300463, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。临深决水。奈何。岐伯曰。血清气浊$a{滑}。疾泻之则气竭焉。黄帝曰。循拙决冲。奈何。岐伯曰。血浊气涩。疾泻之。则经可通也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754572, '7CA5158FF595CD949554DAFDF310BB35', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4599, 172, 20300464, NULL, NULL, '', NULL, NULL, NULL, '9、黄帝曰。脉行之逆顺。奈何。岐伯曰。手之三阴。从藏走手。手之三阳。从手走头。足之三阳。从头走足。足之三阴。从足走腹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754573, '37842459CBEE63BE808651B6A88B6F7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4600, 172, 20300465, NULL, NULL, '', NULL, NULL, NULL, '10、黄帝曰。少阴之脉独下行。何也。岐伯曰。不然。夫冲脉者。五藏六府之海也。五藏六府皆禀焉。其上者。出于颃颡。渗诸阳。灌诸精。其下者。注少阴之大络。出于气街。循阴股内廉入腘中。伏行骭骨内。下至内踝之后属而别。其下者。并于少阴之经。渗三阴。其前者。伏行出跗属。下循跗。入大指间。渗诸络而温肌肉。故别络结则附上不动。不动则厥。厥则寒矣。黄帝曰。何以明之。岐伯曰。以言导之。切而验之。其非必动。然后仍可明逆顺之行也。黄帝曰。窘乎哉。圣人之为道也。明于日月。微于毫厘。其非夫子。孰能道之也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211754574, '2A06C5BB82DF822360AE5747759F1A93', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4601, 173, 20300466, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。愿闻其奇邪而不在经者。岐伯曰。血络是也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996229, '68A12577D83921EAA40B8D577DAD29C5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4602, 173, 20300467, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。刺血络而仆者。何也。血出而射者。何也。血少黑而浊者。何也。血出清而半为汁者。何也。拔针而肿者。何也。血出若多若少而面色苍苍者。何也。拔针而面色不变而烦悗者。何也。多出血而不动摇者。何也。愿闻其故。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996230, '7D270A1E8917F518CDBCD96E3678B691', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4603, 173, 20300468, NULL, NULL, '', NULL, NULL, NULL, '3、岐伯曰。脉气盛而血虚者。刺之则脱气。脱气则仆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996231, '7BAA17E8B58B47C6BF22E36468CEA01A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4604, 173, 20300469, NULL, NULL, '', NULL, NULL, NULL, '4、血气俱盛而阴气多者。其血滑。刺之则射。阳气蓄积。久留而不泻者。其血黑以浊。故不能射。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996232, '1DC485C33CBAB217FE2ACC0452419341', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4605, 173, 20300470, NULL, NULL, '', NULL, NULL, NULL, '5、新饮而液渗于络。而未合和于血也。故血出而汁别焉。其不新饮者。身中有水。久则为肿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996233, '7A956309C7570E0F41A8B313B8127224', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4606, 173, 20300471, NULL, NULL, '', NULL, NULL, NULL, '6、阴气积于阳。其气因于络。故刺之血未出而气先行。故肿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996234, '5146A9E2D5D03852C90D4E7ACCBB272D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4607, 173, 20300472, NULL, NULL, '', NULL, NULL, NULL, '7、阴阳之气。其新相得而未和合。因而泻之。则阴阳俱脱。表里相离。故脱色而苍苍然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996235, '82A0AB3297B3DEEEB16C9D62058197FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4608, 173, 20300473, NULL, NULL, '', NULL, NULL, NULL, '8、刺之血出多。色不变而烦悗者。刺络而虚经。虚经之属于阴者。阴脱。故烦悗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996236, 'D6C2C4D95794471FA684E9EFE7001BB5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4609, 173, 20300474, NULL, NULL, '', NULL, NULL, NULL, '9、阴阳相得而合为痹者。此为内溢于经。外注于络。如是者。阴阳俱有余。虽多出血而弗能虚也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996237, 'C34B169E31D250D8D8D3FCCE6BE32B8F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4610, 173, 20300475, NULL, NULL, '', NULL, NULL, NULL, '10、黄帝曰。相之奈何。岐伯曰。血脉者。盛坚横以赤。上下无常处。小者如针。大者如筋。则而泻之万全也。故无失数矣。失数而反。各如其度。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996238, '502BB39696B77765532327255681BA90', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4611, 173, 20300476, NULL, NULL, '', NULL, NULL, NULL, '11、黄帝曰。针入而肉著者。何也。岐伯曰。热气因于针。则针热。热则内着于针。故坚焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957211996239, 'B8B8B908E22C254543006C034DB9F10F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4612, 174, 20300477, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余闻十二经脉。以应十二经水者。其五色各异。清浊不同。人之血气若一。应之奈何。岐伯曰。人之血气。苟能若一。则天下为一矣。恶有乱者乎。黄帝曰。余问一人。非问天下之众。岐伯曰。夫一人者。亦有乱气。天下之象。亦有乱人。其合为一耳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212221509, '549331D72B31B9E38944EAF2921E6AF7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4613, 174, 20300478, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。愿闻人气之清浊。岐伯曰。受谷者浊。受气者清。清者注阴。浊者注阳。浊而清者。上出于咽。清而浊者。则下行。清浊相干。命曰乱气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212221510, 'CA5EC3F603AED805D9B125384246AFEE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4614, 174, 20300479, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。夫阴清而阳浊。浊者有清。清者有浊。清浊别之奈何。岐伯曰。气之大别。清者上注于肺。浊者下走于胃。胃之清气。上出于口。肺之浊气。下注于经。内积于海。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212221511, 'B1E92BA65B65F3E4A64F9266C2351E44', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4615, 174, 20300480, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。诸阳皆浊。何阳浊甚乎。岐伯曰。手太阳独受阳之浊。手太阴独受阴之清。其清者上走空窍。其浊者下行诸经。诸阴皆清。足太阴独受其浊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212221512, '09F410E77F0F0E151971177C4A555A8D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4616, 174, 20300481, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。治之奈何。岐伯曰。清者其气滑。浊者其气涩。此气之常也。故刺阴者。深而留之。刺阳者。浅而疾之。清浊相干者。以数调之也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212221513, 'D72CE0AB4EA400AF074674A299D022D3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4617, 175, 20300482, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余闻天为阳。地为阴。日为阳。月为阴。其合之于人。奈何。岐伯曰。腰以上为天。腰以下为地。故天为阳。地为阴。故足之十二经脉。以应为十二月。月生于水。故在下者为阴。手之十指。以应十日。日主火。故在上者为阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212438597, 'ED54823B2F617491FA6ECDACC00B7D91', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4618, 175, 20300483, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。合之于脉。奈何。岐伯曰。寅者。正月之生阳也。主左足之少阳。未者。六月。主右足之少阳。卯者。二月。主左足之太阳。午者。五月。主右足之太阳。辰者。三月。主左足之阳明。巳者。四月。主右足之阳明。此两阳合于前。故曰阳明。申者。七月之生阴也。主右足之少阴。丑者。十二月。主左足之少阴。酉者。八月。主右足之太阴。子者。十一月。主左足之太阴。戌者。九月。主右足之厥阴。亥者。十月。主左足之厥阴。此两阴交尽。故曰厥阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212438598, '7C5C487AF75DBB5CA6497B162BF06A80', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4619, 175, 20300484, NULL, NULL, '', NULL, NULL, NULL, '3、甲主左手之少阳。己主右手之少阳。乙主左手之太阳。戊主右手之太阳。丙主左手之阳明。丁主右手之阳明。此两火并合。故为阳明。庚主右手之少阴。癸主左手之少阴。辛主右手之太阴。壬主左手之太阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212438599, '6AAB8858A42B00A1484F1BF592CF81C2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4620, 175, 20300485, NULL, NULL, '', NULL, NULL, NULL, '4、故足之阳者。阴中之少阳也。足之阴者。阴中之太阴也。手之阳者。阳中之太阳也。手之阴者。阳中之少阴也。腰以上者为阳。腰以下者为阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212438600, '6967905AD676443D6812B0AAE55C4F4B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4621, 175, 20300486, NULL, NULL, '', NULL, NULL, NULL, '5、其于五藏也。心为阳中之太阳。肺为阴中之少阴。肝为阴中少阳。脾为阴中之至阴。肾为阴中之太阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212438601, '50680511FD5BDC51F28640B4E9B485F7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4622, 175, 20300487, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。以治之奈何。岐伯曰。正月二月三月。人气在左。无刺左足之阳。四月五月六月。人气在右。无刺右足之阳。七月八月九月。人气在右。无刺右足之阴。十月十一月十二月。人气在左。无刺左足之阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212438602, '4FA820F481021073B10E3A0D9047AE2F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4623, 175, 20300488, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。五行以东方为甲乙木主春。春者。苍色。主肝。肝者。足厥阴也。今乃以甲为左手之少阳。不合于数。何也。岐伯曰。此天地之阴阳也。非四时五行之以次行也。且夫阴阳者。有名而无形。故数之可十。离之可百。散之可千。推之可万。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212438603, '7B93827B27DD3FA5BFEF6AC20A4F6492', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4624, 176, 20300489, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余受九针于夫子。而私览于诸方。或有导引行气。乔摩。灸。熨。刺。焫。饮药之一者。可独守耶。将尽行之乎。岐伯曰。诸方者。众人之方也。非一人之所尽行也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672069, '36A5393DD7A8A101CE64FB30DA5AE169', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4625, 176, 20300490, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。此乃所谓守一勿失。万物毕者也。今余已闻阴阳之要。虚实之理。倾移之过。可治之属。愿闻病之变化。淫传绝败而不可治者。可得闻乎。岐伯曰。要乎哉问也。昭乎其如日醒。窘乎其如夜瞑。能被而服之。神与俱成。毕将服之。神自得之。生神之理。可着于竹帛。不可传于子孙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672070, 'EA36A0B9F4B402EE8537404617446A5A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4626, 176, 20300491, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。何谓日醒。岐伯曰。明于阴阳。如惑之解。如醉之醒。黄帝曰。何谓夜瞑。岐伯曰。瘖乎其无声。漠乎其无形。折毛发理。正气横倾。淫邪泮衍。血脉传溜。大气入藏。腹痛下淫。可以致死。不可以致生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672071, '779824A1742C282BC16F2814720A10F1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4627, 176, 20300492, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。大气入藏。奈何。岐伯曰。病先发于心。一日而之肺。三日而之肝。五日而之脾。三日不已。死。冬夜半。夏日中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672072, 'CD182E9040B4D45088C9E8241143852E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4628, 176, 20300493, NULL, NULL, '', NULL, NULL, NULL, '5、病先发于肺。三日而之肝。一日而之脾。五日而之胃。十日不已。死。冬日入。夏日出。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672073, '5B6A2F4C38D7454FE642B8349F0CD7D6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4629, 176, 20300494, NULL, NULL, '', NULL, NULL, NULL, '6、病先发于肝。三日而之脾。五日而之胃。三日而之肾。三日不已。死。冬日入。夏蚤食。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672074, '80F8733FE6B0C7C1F9F5ECC46801C2B1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4630, 176, 20300495, NULL, NULL, '', NULL, NULL, NULL, '7、病先发于脾。一日而之胃。二日而之肾。三日而之膂膀胱。十日不已。死。冬人定。夏晏食。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672075, '39173343A29B1283A09E7F56016A2D23', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4631, 176, 20300496, NULL, NULL, '', NULL, NULL, NULL, '8、病先发于胃。五日而之肾。三日而之膂膀胱。五日而上之心。二日不已。死。冬夜半。夏日昳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672076, '66D990DE6EE60D6C6DC24895EFEFC656', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4632, 176, 20300497, NULL, NULL, '', NULL, NULL, NULL, '9、病先发于肾。三日而之膂膀胱。三日而上之心。三日而之小肠。三日不已。死。冬大晨。夏晏晡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672077, '31DDD34D037FBFF68A5235C7A3473AAF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4633, 176, 20300498, NULL, NULL, '', NULL, NULL, NULL, '10、病先发于膀胱。五日而之肾。一日而之小肠。一日而之心。二日不已。死。冬鸡鸣。夏下晡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672078, '8354D37EC70F72BD89EB554BF41E4437', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4634, 176, 20300499, NULL, NULL, '', NULL, NULL, NULL, '11、诸病以次相传。如是者。皆有死期。不可刺也。间一藏及二。三。四藏者。乃可刺也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212672079, '6F85364AF49BF067BB309EEDA0F03686', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4635, 177, 20300500, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。愿闻淫邪泮衍。奈何。岐伯曰。正邪从外袭内。而未有定舍。反淫于藏。不得定处。与营卫俱行。而与魂魄飞扬。使人卧不得安而喜梦。气淫于府。则有余于外。不足于内。气淫于藏。则有余于内。不足于外。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212893253, 'EA65861FCC8D98295BA2EA084A019BC8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4636, 177, 20300501, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。有余不足。有形乎。岐伯曰。阴气盛。则梦涉大水而恐惧。阳气盛。则梦大火而燔焫。阴阳俱盛。则梦相杀。上盛则梦飞。下盛则梦堕。甚饥则梦取。甚饱则梦予。肝气盛。则梦怒。肺气盛。则梦恐惧。哭泣。飞扬。心气盛。则梦善笑恐畏。脾气盛。则梦歌。身体重不举。肾气盛。则梦腰脊两解不属。凡此十二盛者。至而泻之。立已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212893254, '9A0D292C587516E255E514E549E93171', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4637, 177, 20300502, NULL, NULL, '', NULL, NULL, NULL, '3、厥气客于心。则梦见丘山烟火。客于肺。则梦飞扬。见金铁之奇物。客于肝。则梦山林树木。客于脾。则梦见丘陵大泽。坏屋风雨。客于肾。则梦临渊。没居水中。客于膀胱。则梦游行。客于胃。则梦饮食。客于大肠。则梦田野。客于小肠。则梦聚邑冲衢。客于胆。则梦斗讼自刳。客于阴器。则梦接内。客于项。则梦斩首。客于胫。则梦行走而不能前。及居深地窌苑中。客于股肱。则梦礼节拜起。客于胞䐈。则梦溲便。凡此十五不足者。至而补之立已也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957212893255, 'EC4FEEBF1ED0990F5951089C680F58B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4638, 178, 20300503, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。夫百病之所始生者。必起于燥温寒暑风雨阴阳喜怒饮食居处。气合而有形。得藏而有名。余知其然也。夫百病者。多以旦慧昼安。夕加夜甚。何也。岐伯曰。四时之气使然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143109, 'B10B759DB67B44823D82FF430C2E851A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4639, 178, 20300504, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。愿闻四时之气。岐伯曰。春生。夏长。秋收。冬藏。是气之常也。人亦应之。以一日分为四时。朝则为春。日中为夏。日入为秋。夜半为冬。朝则人气始生。病气衰。故旦慧。日中人气长。长则胜邪。故安。夕则人气始衰。邪气始生。故加。夜半人气入藏。邪气独居于身。故甚也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143110, '498B6ACC4C9769CA68BE31F10A7337B1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4640, 178, 20300505, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。有时有反者何也。岐伯曰。是不应四时之气。藏独主其病者。是必以藏气之所不胜时者甚。以其所胜时者起也。黄帝曰。治之奈何。岐伯曰。顺天之时。而病可与期。顺者为工。逆者为粗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143111, '13B6790CE92DB7CBD4069F41E252954D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4641, 178, 20300506, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。善。余闻刺有五变。以主五输。愿闻其数。岐伯曰。人有五藏。五藏有五变。五变有五输。故五五二十五输。以应五时。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143112, '3F7BF1FF0A91E75738292577FD09387C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4642, 178, 20300507, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。愿闻五变。岐伯曰。肝为牡藏。其色青。其时春。其音角。其味酸。其日甲乙。心为牡藏。其色赤。其时夏。其日丙丁。其音征。其味苦。脾为牝藏。其色黄。其时长夏。其日戊己。其音宫。其味甘。肺为牝藏。其色白。其音商。其时征。其日庚辛。其味辛。肾为牝藏。其色黑。其时冬。其日壬癸。其音羽。其味咸。是为五变。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143113, '498E24210F16807E67C686772D0F0930', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4643, 178, 20300508, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。以主五输奈何。藏主冬。冬刺井。色主春。春刺荥。时主夏。夏刺输。音主长夏。长夏刺经。味主秋。秋刺合。是谓五变。以主五输。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143114, '6F7C0375685ACC7029FA02CDAD1874BF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4644, 178, 20300509, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。诸原安和。以致五输。岐伯曰。原独不应五时。以经合之。以应其数。故六六三十六输。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143115, '618266A7DD433A625555D79A6477D2BF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4645, 178, 20300510, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。何谓藏主冬。时主夏。音主长夏。味主秋。色主春。愿闻其故。岐伯曰。病在藏者。取之井。病变于色者。取之荥。病时间时甚者。取之输。病变于音者。取之经。经满而血者。病在胃。及以饮食不节得病者。取之于合。故命曰味主合。是谓五变也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213143116, 'ABBE1BDB4DD7ED1E6648F60AA7C8F435', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4646, 179, 20300511, NULL, NULL, '', NULL, NULL, NULL, '1、余闻九针九篇。余亲受其调。颇得其意。夫九针者。始于一而终于九。然未得其要道也。夫九针者。小之则无内。大之则无外。深不可为下。高不可为盖。恍惚无窍。流溢无极。畲知其合于天道人事四时之变也。然余愿杂之毫毛。浑束为一。可乎。岐伯曰。明乎哉问也。非独针道焉。夫治国亦然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213372485, 'B65271C9E0F2BAAD7E4061A255408AEC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4647, 179, 20300512, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。余愿闻针道。非国事也。岐伯曰。夫治国者。夫惟道焉。非道。何可小大深浅。杂合而为一乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213372486, '3A7087676B4688E17962230135EDD4D9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4648, 179, 20300513, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。愿卒闻之。岐伯曰。日与月焉。水与镜焉。鼓与响焉。夫日月之明。不失其影。水镜之察。不失其形。鼓响之应。不后其声。动摇则应和。尽得其情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213372487, '1F4DE6E523F840A331B7F4B455AEE2B1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4649, 179, 20300514, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。窘乎哉。昭昭之明不可蔽。其不可蔽。不失阴阳也。合而察之。切而验之。见而得之。若清水明镜之不失其形也。五音不彰。五色不明。五藏波荡。若是则内外相袭。若鼓之应桴。响之应声。影之似形。故远者。司外揣内。近者。司内揣外。是谓阴阳之极。天地之盖。请藏之灵兰之室。弗敢使泄也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213372488, '71AC147889DEB3989794DFC2921310AA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4650, 180, 20300515, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于少俞曰。余闻百疾之始期也。必生于风雨寒暑。循毫毛而入腠理。或复还。或留止。或为风肿汗出。或为消瘅。或为寒热。或为留痹。或为积聚。奇邪淫溢。不可胜数。愿闻其故。夫同时得病。或病此。或病彼。意者天之为人生风乎。何其异也。少俞曰。夫天之生风者。非以私百姓也。其行公平正直。犯者得之。避者得无殆。非求人而人自犯之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593669, '3FC837598DB9E9A0BA06364D06F8FC32', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4651, 180, 20300516, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。一时遇风。同时得病。其病各异。愿闻其故。少俞曰。善乎其问。请论以比匠人。匠人磨斧斤。砺刀削断材木。木之阴阳。尚有坚脆。坚者不入。脆者皮弛。至其交节。而缺斤斧焉。夫一木之中。坚脆不同。坚者则刚。脆者易伤。况其材木之不同。皮之厚薄。汁之多少。而各异耶。夫木之蚤花先生叶者。遇春霜烈风。则花落而叶萎。久曝大旱。则脆木薄皮者。枝条汁少而叶萎。久阴淫雨。则薄皮多汁者。皮漉而浅。卒风暴起。则刚脆之木。根摇而叶落。凡此五者。各有所伤。况于人乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593670, '5C30E638B18FE1C0C552848A5BD37AD2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4652, 180, 20300517, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。以人应木。奈何。少俞答曰。木之所伤也。皆伤其枝。枝之刚脆而坚。未成伤也。人之有常病也。亦因其骨节皮肤腠理之不坚固者。邪之所舍也。故常为病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593671, 'C93048869001E09BB4986E426BBAF1EC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4653, 180, 20300518, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。人之善病风厥漉汗者。何以候之。少俞答曰。内不坚。腠理疏。则善病风。黄帝曰。何以候肉之不坚也。少俞答曰。腘肉不坚。而无分理。理者粗理。粗理而皮不致者。腠理疏。此言其浑然者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593672, 'BE43D6252E434DE3F518AC2001C2E229', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4654, 180, 20300519, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。人之善病消瘅者。何以候之。少俞答曰。五藏皆柔弱者。善病消瘅。黄帝曰。何以知五藏之柔弱也。少俞答曰。夫柔弱者。必有刚强。刚强多怒。柔者易伤也。黄帝曰。何以候柔弱之与刚强。少俞答曰。此人薄皮肤。而目坚固以深者。长冲直肠。其心刚。刚则多怒。怒则气上逆。胸中蓄积。血气逆留。髋皮充肌。血脉不行。转而为热。热则消肌肤。故为消瘅。此言其人暴刚而肌肉弱者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593673, '4C6B0960E911C08391A2FAD1F5FA94A1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4655, 180, 20300520, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。人之善病寒热者。何以候之。少俞答曰。小骨弱肉者。善病寒热。黄帝曰。何以候骨之小大。肉之坚脆。色之不一也。少俞答曰。颧骨者。骨之本也。颧大则骨大。颧小则骨小。皮肤薄而其肉无䐃。其臂懦懦然。其地色殆然。不与其天同色。污然独异。此其候也。然后臂薄者。其髓不满。故善病寒热也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593674, 'AA33C9B1E62754008CCA4F765BCD5FCF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4656, 180, 20300521, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。何以候人之善病痹者。少俞答曰。粗理而肉不坚者。善病痹。黄帝曰。痹之高下有处乎。少俞答曰。欲知其高下者。各视其部。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593675, '075C0EC089090A9452505CD7C966E23F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4657, 180, 20300522, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。人之善病肠中积聚者。何以候之。少俞答曰。皮肤薄而不泽。肉不坚而淖泽。如此。则肠胃恶。恶则邪气留止。积聚乃伤脾胃之间。寒温不次。邪气稍至。蓄积留止。大聚乃起。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593676, 'B57A661320D123ECBAE346784D163104', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4658, 180, 20300523, NULL, NULL, '', NULL, NULL, NULL, '9、黄帝曰。余闻病形。已知之矣。愿闻其时。少俞答曰。先立其年。以知其时。时高则起。时下则殆。虽不陷下。当年有冲道。其病必起。是谓因形而生病。五变之纪也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213593677, '5F87A7B92F507150D26ED3E109493EA0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4659, 181, 20300524, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。人之血气精神者。所以奉生而周于性命者也。经脉者。所以行血气而营阴阳。濡筋骨。利关节者也。卫气者。所以温分肉。充皮肤。肥腠理。司开阖者也。志意者。所以御精神。收魂魄。适寒温。和喜怒者也。是故血和则经脉流行。营复阴阳。筋骨劲强。关节清利矣。卫气和则分肉解利。皮肤调柔。腠理致密矣。志意和则精神专直。魂魄不散。悔怒不起。五藏不受邪矣。寒温和则六府化谷。风痹不作。经脉通利。肢节得安矣。此人之常平也。五藏者。所以藏精神血气魂魄者也。六府者。所以化水谷而行津液者也。此人之所以具受于天也。无愚智贤不肖。无以相倚也。然有其独尽天寿。而无邪僻之病。百年不衰。虽犯风雨卒寒大暑。犹有弗能害也。有其不离屏蔽室内。无怵惕之恐。然犹不免于病。何也。愿闻其故。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823045, '1D4CEDE80FF773E8F13AB360491F90D7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4660, 181, 20300525, NULL, NULL, '', NULL, NULL, NULL, '2、岐伯对曰。窘乎哉问也。五藏者。所以参天地。副阴阳。而运四时。化五节者也。五藏者。固有小大。高下。坚脆。端正。偏倾者。六府亦有小大。长短。厚薄。结直。缓急。凡此二十五者。各不同。或善或恶。或吉或凶。请言其方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823046, '37B3C3907FD7ECDB653AA5750A036310', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4661, 181, 20300526, NULL, NULL, '', NULL, NULL, NULL, '3、心小则安。邪弗能伤。易伤以忧。心大则忧。不能伤。易伤于邪。心高则满于肺中。悗而善忘。难开以言。心下。则藏外。易伤于寒。易恐以言。心坚。则藏安守固。心脆则善病消瘅热中。心端正。则和利难伤。心偏倾则操持不一。无守司也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823047, 'BFA3036C02DC3A2749E675547EA4EAEE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4662, 181, 20300527, NULL, NULL, '', NULL, NULL, NULL, '4、肺小。则少饮。不病喘喝。肺大则多饮。善病胸痹。喉痹。逆气。肺高。则上气。肩息咳。肺下则居贲迫肺。善胁下痛。肺坚则不病。咳上气。肺脆。则苦病消痹易伤。肺端正。则和利难伤。肺偏倾。则胸偏痛也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823048, '0C8C2F595F2C4B25ADEB46C9E6CAAD36', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4663, 181, 20300528, NULL, NULL, '', NULL, NULL, NULL, '5、肺小则藏安。无胁下之病。肝大则逼胃迫咽。迫咽则苦膈中。且胁下痛。肝高。则上支贲切。胁挽为息贲。肝下则逼胃胁下空。胁下空则易受邪。肝坚则藏安难伤。肝脆则善病消痹。易伤。肝端正。则和利难伤。肝偏倾。则胁下痛也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823049, 'CE71FBA4FA557CC83F2DC9FF7E146CB8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4664, 181, 20300529, NULL, NULL, '', NULL, NULL, NULL, '6、脾小。则藏安。难伤于邪也。脾大。则苦凑䏚而痛。不能疾行。脾高。则䏚引季胁而痛。脾下则下归于大肠。下加于大肠。则藏苦受邪。脾坚。则藏安难伤。脾脆。则善病消痹易伤。脾端正。则和利难伤。脾偏倾。则善满善胀也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823050, '5A1F20C603D2F150DC99CAD5F6958C1D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4665, 181, 20300530, NULL, NULL, '', NULL, NULL, NULL, '7、肾小。则藏安难伤。肾大。则善病腰痛。不可以俛仰。易伤以邪。肾高。则苦背膂痛。不可以俛仰。肾下则腰尻痛。不可以俛仰。为狐疝。肾坚。则不病腰背痛。肾脆。则善病消瘅。易伤。肾端正。则和利难伤。肾偏倾。则苦腰尻痛也。凡此二十五变者。人之所苦常病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823051, 'DDA17D427F15825C6D6A3B6492D11C09', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4666, 181, 20300531, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。何以知其然也。岐伯曰。赤色小理者。心小。粗理者。心大。无𩩲骬者。心高。𩩲骬小。短。举者。心下。𩩲骬长者。心下坚。𩩲骬弱小以薄者。心脆。𩩲骬直下不举者。心端正。𩩲骬倚一方者。心偏倾也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823052, '83A6E652ECDF98CFCEDEDAB26B61643A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4667, 181, 20300532, NULL, NULL, '', NULL, NULL, NULL, '9、白色小理者。肺小。粗理者。肺大。巨肩反膺陷喉者。肺高。合腋张胁者。肺下。好肩背厚者。肺坚。肩背薄者。肺脆。背膺厚者。肺端正。胁偏疏者。肺偏倾也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823053, '63CE7C591FD2846742A2493AD02D9823', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4668, 181, 20300533, NULL, NULL, '', NULL, NULL, NULL, '10、青色小理者。肝小。粗理者。肝大。广胸反骹者。肝高。合胁兔骹者。肝下。胸胁好者。肝坚。胁骨弱者。肝脆。膺腹好相得者。肝端正。胁骨偏举者。肝偏倾也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823054, 'FF101C878951166137430FFCB92CE202', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4669, 181, 20300534, NULL, NULL, '', NULL, NULL, NULL, '11、黄色小理者。脾小。粗理者。脾大。揭唇者。脾高。唇下纵者。脾下。唇坚者。脾坚。唇大而不坚者。脾脆。唇上下好者。脾端正。唇偏举者。脾偏倾也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823055, '886D7E0A056E43B8581FF46E4ED2503B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4670, 181, 20300535, NULL, NULL, '', NULL, NULL, NULL, '12、黑色小理者。肾小。粗理者。肾大。高耳者。肾高。耳后陷者。肾下。耳坚者。肾坚。耳薄而不坚者。肾脆。耳好前居牙车者。肾端正。耳偏高者。肾偏倾也。凡此诸变者。持则安。减则病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823056, 'A7F068CB0B7F1106A5F609AF18EF7F8C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4671, 181, 20300536, NULL, NULL, '', NULL, NULL, NULL, '13、帝曰。善。然非余之所问也。愿闻人之有不可病者。至尽天寿。虽有深扰大恐。怵惕之志。犹不能减也。甚寒大热。不能伤也。其有不离屏蔽室内。又无怵惕之恐。然不免于病者。何也。愿闻其故。岐伯曰。五藏六府。邪之舍也。请言其故。五藏皆小者。少病。苦憔心。大愁扰。五藏皆大者。缓于事。难使以扰。五藏皆高者。好高举措。五藏皆下者。好出人下。五藏皆坚者。无病。五藏皆脆者。不离于病。五藏皆端正者。和利得人心。五藏皆偏倾者。邪心而善盗。不可以为人平。反复言语也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823057, 'F2068542CD402D8B228E1E6CF158D500', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4672, 181, 20300537, NULL, NULL, '', NULL, NULL, NULL, '14、黄帝曰。愿闻六府之应。岐伯答曰。肺合大肠。大肠者。皮其应。心合小肠。小肠者。脉其应。肝合胆。胆者。筋其应。脾合胃。胃者。肉其应。肾合三焦膀胱。三焦膀胱者。腠理毫毛其应。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823058, 'C1B77287D5394111B1A37D00EA2115CD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4673, 181, 20300538, NULL, NULL, '', NULL, NULL, NULL, '15、黄帝曰。应之奈何。岐伯曰。肺应皮。皮厚者。大肠厚。皮薄者。大肠薄。皮缓。腹里大者。大肠大而长。皮急者。大肠急而短。皮滑者。大肠直。皮肉不相离者。大肠结。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823059, '2885C2D72C8CA4514789A0D1426466C8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4674, 181, 20300539, NULL, NULL, '', NULL, NULL, NULL, '16、心应脉。皮厚者。脉厚。脉厚者。小肠厚。皮薄者。脉薄。脉薄者。小肠薄。皮缓者。脉缓。脉缓者。小肠大而长。皮薄而脉冲小者。小肠小而短。诸阳经脉皆多纡屈者。小肠结。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823060, 'AAAD2D748ED31C1F9D7751802653DB64', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4675, 181, 20300540, NULL, NULL, '', NULL, NULL, NULL, '17、脾应肉。肉䐃坚大者。胃厚。肉䐃么者。胃薄。肉䐃小而么者。胃不坚。肉腘不称身者。胃下。胃下者。下管约不利。肉脾不坚者。胃缓。肉䐃无小里累者。胃急。肉䐃多少里累者。胃结。胃结者。上管约不利也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823061, '32F3B8D25B9ED9FE8E0E12E4B0BA88E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4676, 181, 20300541, NULL, NULL, '', NULL, NULL, NULL, '18、肝应爪。爪厚色黄者。胆厚。爪薄色红者。胆薄。爪坚色青者。胆急。爪濡色赤者。胆缓。爪直色白无约者。胆直。爪恶色黑多纹者。胆结也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823062, '0D7FB7E16C4372CAE06FBF0EC157E7B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4677, 181, 20300542, NULL, NULL, '', NULL, NULL, NULL, '19、肾应骨。密理厚皮者。三焦膀胱厚。粗理薄皮者。三焦膀胱薄。疏腠理者。三焦膀胱缓。皮急而无毫毛者。三焦膀胱急。毫毛美而粗者。三焦膀胱直。稀毫毛者。三焦膀胱结也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823063, '149A2366256734A7B9C179A4C4070FA2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4678, 181, 20300543, NULL, NULL, '', NULL, NULL, NULL, '20、黄帝曰。厚薄美恶。皆有形。愿闻其所病。岐伯答曰。视其外应。以知其内藏。则知所病矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957213823064, '9A313414A3C444657B0118458FCD9D75', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4679, 182, 20300544, NULL, NULL, '', NULL, NULL, NULL, '1、雷公问于黄帝曰。细子得受。通于九针六十篇。旦暮勤服之。近者编绝。久者简垢。然尚讽诵弗置。未尽解于意矣。「外揣」言浑束为一。未知所谓也。夫大则无外。小则无内。大小无极。高下无度。束之奈何。士之才力。或有厚薄。智虑褊浅。不能博大深奥。自强于学若细子。细子恐其散于后世。绝于子孙。敢问约之奈何。黄帝曰。善乎哉问也。此先师之所禁。坐私传之也。割臂歃血之盟也。子若欲得之。何不斋乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214056517, 'F6ED21D8C9D72CFAC84B6A52FE63F4D7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4680, 182, 20300545, NULL, NULL, '', NULL, NULL, NULL, '2、雷公再拜而起曰。请闻命于是也。乃斋宿三日而请曰。敢问今日正阳。细子愿以受盟。黄帝乃与俱入斋室。割臂歃血。黄帝亲祝曰。今日正阳。歃血传方。有敢背此言者。反受其殃。雷公再拜曰。细子受之。黄帝乃左握其手。右授之书曰。慎之慎之。吾为子言之。凡刺之理。经脉为始。营其所行。知其度量。内刺五藏。外刺六府。审察卫气。为百病母。调其虚实。虚实乃止。泻其血络。血尽不殆矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214056518, '8EB441E25F45478C31485213F815BC56', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4681, 182, 20300546, NULL, NULL, '', NULL, NULL, NULL, '3、雷公曰。此皆细子之所以通。未知其所约也。黄帝曰。夫约方者。犹约囊也。囊满而弗约。则输泄。方成弗约。则神与弗俱。雷公曰。愿为下材者。勿满而约之。黄帝曰。未满而知约之以为工。不可以为天下师。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214056519, '15997A2656F39DBAB2E4726E8F83ADEE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4682, 182, 20300547, NULL, NULL, '', NULL, NULL, NULL, '4、雷公曰。愿闻为工。黄帝曰。寸口主中。人迎主外。两者相应。俱往俱来。若引绳大小齐等。春夏人迎微大。秋冬寸口微大。如是者。名曰平人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214056520, '7711C82A163C8C479413760694DDD9F9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4683, 182, 20300548, NULL, NULL, '', NULL, NULL, NULL, '5、人迎大一倍于寸口。病在足少阳。一倍而躁。在手少阳。人迎二倍。病在足太阳。二倍而躁。病在手太阳。人迎三倍。病在足阳明。三倍而躁。病在手阳明。盛则为热。虚则为寒。紧则为痛痹。代则乍甚乍间。盛则泻之。虚则补之。紧痛则取之分肉。代则取血络。且饮药。陷下则灸之。不盛不虚。以经取之。名曰经刺。人迎四倍者。且大且数。名曰溢阳。溢阳为外格。死不治。必审按其本末。察其寒热。以验其藏府之病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214056521, '018ABE11F91842373EFB9696CF80CD5E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4684, 182, 20300549, NULL, NULL, '', NULL, NULL, NULL, '6、寸口大于人迎一倍。病在足厥阴。一倍而躁。在手心主。寸口二倍。病在足少阴。二倍而躁。在手少阴。寸口三倍。病在足太阴。三倍而躁。在手太阴。盛则胀满。寒中。食不化。虚则热中。出糜。少气。溺色变。紧则痛痹。代则乍痛乍止。盛则泻之。虚则补之。紧则先刺而后灸之。代则取血络。而后调之。陷下则徒灸之。陷下者。脉血结于中。中有着血。血寒。故宜灸之。不盛不虚。以经取之。寸口四倍者。名曰内关。内关者。且大且数。死不治。必审察其本末之寒温。以验其藏府之病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214056522, 'C7EF9D77ADA8E44A55279298CB70D3B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4685, 182, 20300550, NULL, NULL, '', NULL, NULL, NULL, '7、通其营输。乃可传于大数。大数曰。盛则徒泻之。虚则徒补之。紧则灸刺。且饮药。陷下则徒灸之。不盛不虚。以经取之。所谓经治者。饮药。亦曰灸刺。脉急则引。脉大以弱。则欲安静。用力无劳也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214056523, '29C58C344B2C5EC352E5181F39A7FA8D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4686, 183, 20300551, NULL, NULL, '', NULL, NULL, NULL, '1、雷公问于黄帝曰。五色独决于明堂乎。小子未知其所谓也。黄帝曰。明堂者。鼻也。阙者。眉间也。庭者。颜也。蕃者。颊侧也。蔽者。耳门也。其间欲方大。去之十步。皆见于外。如是者寿。必中百岁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289989, '4118EC64EDA5A4D47CB3AA993FFC4E99', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4687, 183, 20300552, NULL, NULL, '', NULL, NULL, NULL, '2、雷公曰。五言之辨。奈何。黄帝曰。明堂骨高以起。平以直。五藏次于中央。六府挟其两侧。首面上于阙庭。王宫在于下极。五藏安于胸中。真色以致。病色不见。明堂润泽以清。五官恶得无辨乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289990, '1465B34DC8F2AEF30DDB922F03CFE750', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4688, 183, 20300553, NULL, NULL, '', NULL, NULL, NULL, '3、雷公曰。其不辨者。可得闻乎。黄帝曰。五色之见也。各出其色部。部骨陷者。必不免于病矣。其色部乘袭者。虽病甚。不死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289991, '0F256B2020C114584BB69728BEDFF266', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4689, 183, 20300554, NULL, NULL, '', NULL, NULL, NULL, '4、雷公曰。官五色奈何。黄帝曰。青黑为痛。黄赤为热。白为寒。是谓五官。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289992, '22A72408DEEAFB641C5D7ED249065AE8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4690, 183, 20300555, NULL, NULL, '', NULL, NULL, NULL, '5、雷公曰。病之益甚。与其方衰。如何。黄帝曰。外内皆在焉。切其脉口。滑小紧以沉者。病益甚。在中。人迎气大紧以浮者。其病益甚。在外。其脉口浮滑者。病日进。人迎沉而滑者。病日损。其脉口滑以沉者。病日进。在内。其人迎脉滑盛以浮者。其病日进。在外。脉之浮沉及人迎与寸口气小大等者。病难已。病之在藏。沉而大者。易已。小为逆。病在府。浮而大者。其病易已。人迎盛坚者。伤于寒。气口盛坚者。伤于食。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289993, '271F93A725A51E35032D23507856E228', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4691, 183, 20300556, NULL, NULL, '', NULL, NULL, NULL, '6、雷公曰。以色言食之间甚。奈何。黄帝曰。其色粗以明。沉夭者为甚。其色上行者。病益甚。其色下行。如云彻散者。病方已。五色各有藏部。有外部有内部也。色从外部走内部者。其病从外走内。其色从内走外者。其病从内走外。病生于内者。先治其阴。后治其阳。反者益甚。其病生于阳者。先治其外。后治其内。反者益甚。其脉滑大。以代而长者。病从外来。目有所见。志有所恶。此阳气之并也。可变而已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289994, '2378BE34AAEF595E930A0A7D99F3938A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4692, 183, 20300557, NULL, NULL, '', NULL, NULL, NULL, '7、雷公曰。小子闻风者。百病之始也。厥逆者。寒湿之起也。别之奈何。黄帝曰。常候阙中。薄泽为风。冲浊为痹。在地为厥。此其常也。各以其色言其病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289995, 'EA4CA1E6C45C967FE3073A20CC30EC14', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4693, 183, 20300558, NULL, NULL, '', NULL, NULL, NULL, '8、雷公曰。人不病卒死。何以知之。黄帝曰。大气入于藏府者。不病而卒死矣。雷公曰。病小愈而卒死者。何以知之。黄帝曰。赤色出两颧。大如拇指者。病虽小愈。必卒死。黑色出于庭。大如拇指。必不病而卒死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289996, '6298B0EF6881B587F47269B84888F8DE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4694, 183, 20300559, NULL, NULL, '', NULL, NULL, NULL, '9、雷公再拜曰。善哉。其死有期乎。黄帝曰。察色以言其时。雷公曰。善乎。愿卒闻之。黄帝曰。庭者。首面也。阙上者。咽喉也。阙中者。肺也。下极者。心也。直下者。肝也。肝左者。胆也。下者。脾也。方上者。胃也。中央者。大肠也。挟大肠者。肾也。当肾者。脐也。面王以上者。小肠也。面王以下者。膀胱子处也。颧者。肩也。颧后者。臂也。臂下者。手也。目内眦上者。膺乳也。挟绳而上者。背也。循牙车以下者。股也。中央者。膝也。膝以下者。胫也。当胫以下者。足也。巨分者。股里也。巨屈者。膝膑也。此五藏六府肢节之部也。各有部分。有部分。用阴和阳。用阳和阴。当明部分。万举万当。能别左右。是谓大道。男女异位。故曰阴阳。审察泽夭。谓之良工。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289997, '60AF14440F0699729E47EFA9AE625AF3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4695, 183, 20300560, NULL, NULL, '', NULL, NULL, NULL, '10、沉浊为内。浮泽为外。黄赤为风。青黑为痛。白为寒。黄而膏润为脓。赤甚者为血痛。甚为挛。寒甚为皮不仁。五色各见其部。察其浮沉。以知浅深。察其泽夭。以观成败。察其散搏。以知远近。视色上下。以知病处。积神于心。以知往今。故相气不微。不知是非。属意勿去。乃知新故。色明不粗。沉天为甚。不明不泽。其病不甚。其色散。驹驹然。未有聚。其病散而气痛。聚未成也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289998, 'FFED3A32C74D7475FFBAE098851E78B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4696, 183, 20300561, NULL, NULL, '', NULL, NULL, NULL, '11、肾乘心。心先病。肾为应。色皆如是。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214289999, 'FF2A49F98D90BC8983F5072CEA0D943E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4697, 183, 20300562, NULL, NULL, '', NULL, NULL, NULL, '12、男子色在于面王。为小腹痛。下为卵痛。其圜直为茎痛。高为本。下为首。狐疝㿉阴之属也。女子在于面王。为膀胱子处之病。散为痛。搏为聚。方员左右。各如其色形。其随而下至胝。为淫。有润如膏状。为暴食不洁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214290000, '60D078E869CB636EBB21CEE646213F12', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4698, 183, 20300563, NULL, NULL, '', NULL, NULL, NULL, '13、左为左。右为右。其色有邪。聚散而不端。面色所指者也。色者。青黑赤白黄。皆端满有别乡。别乡赤者。其色赤。大如榆荚。在面王为不日。其色上锐。首空上向。下锐下向。在左右如法。以五色命藏。青为肝。赤为心。白为肺。黄为脾。黑为肾。肝合筋。心合脉。肺合皮。脾合肉。肾合骨也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214290001, 'E60916477350A069B062632674C158FD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4699, 184, 20300564, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于少俞曰。有人于此。并行并立。其年之长少等也。衣之厚薄均也。卒然遇烈风暴雨。或病或不病。或皆病。或皆不病。其故何也。少俞曰。帝问何急。黄帝曰。愿尽闻之。少俞曰。春青风夏阳风。秋凉风。冬寒风。凡此四时之风者。其所病各不同形。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214519365, '8C46522503B4500E25D6186448707821', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4700, 184, 20300565, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。四时之风。病人如何。少俞曰。黄色薄皮弱肉者。不胜春之虚风。白色薄皮弱肉者。不胜夏之虚风。青色薄皮弱肉。不胜秋之虚风。赤色薄皮弱肉。不胜冬之虚风也。黄帝曰。黑色不病乎。少俞曰。黑色而皮厚肉坚。固不伤于四时之风。其皮薄而肉不坚。色不一者。长夏至而有虚风者。病矣。其皮厚而肌肉坚者。长夏至而有虚风。不病矣。其皮厚而肌肉坚者。必重感于寒。外内皆然。乃病。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214519366, 'D6B70B6F053DEBEF44D0FCADCFC99C48', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4701, 184, 20300566, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。夫人之忍痛与不忍痛。非勇怯之分也。夫勇士之不忍痛者。见难则前。见痛则止。夫怯士之忍痛者。闻难则恐。遇痛不动。夫勇士之忍痛者。见难不恐。遇痛不动。夫怯士之不忍痛者。见难与痛。目转面盻。恐不能言。失气。惊。颜色变化。乍死乍生。余见其然也。不知其何由。愿闻其故。少俞曰。夫忍痛与不忍痛者。皮肤之薄厚。肌肉之坚脆。缓急之分也。非勇怯之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214519367, '987B7C457B1F705DB06CC7FC0EC3D1A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4702, 184, 20300567, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。愿闻勇怯之所由然。少俞曰。勇士者。目深以固。长冲直扬。三焦理横。其心端直。其肝大以坚。其胆满以傍。怒则气盛而胸张。肝举而胆横。眦裂而目扬。毛起而面苍。此勇士之由然者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214519368, '3ABCE8F4AFDB7A4561C6A6C5D12B0769', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4703, 184, 20300568, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。愿闻怯士之所由然。少俞曰。怯士者。目大而不减。阴阳相失。其焦理。纵𩩲骬短而小。肝系缓。其胆不满而纵。肠胃挺。胁下空。虽方大怒。气不能满其胸。肝肺虽举。气衰复下。故不能久怒。此怯士之所由然者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214519369, '64E6C7AD25A046D306BC71DB1A57F024', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4704, 184, 20300569, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。怯士之得酒。怒不避勇士者。何藏使然。少俞曰。酒者。水谷之精。熟谷之液也。其气慓悍。其入于胃中。则胃胀。气上逆。满于胸中。肝浮胆横。当是之时。固比于勇士。气衰则悔。与勇士同类。不知避之。名曰酒悖也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214519370, '17A78BAA156AA454A1644641D75E1F1A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4705, 185, 20300570, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。愿闻五藏之腧。出于背者。岐伯曰。背中大腧。在杼骨之端。肺腧在三焦之间。心腧在五焦之间。膈腧在七焦之间。肝腧在九焦之间。脾腧在十一焦之间。肾腧在十四焦之间。皆挟脊相去三寸所。则欲得而验之。按其处。应在中而痛解。乃其输也。灸之则可刺之则不可。气盛则泻之。虚则补之。以火补者。毋吹其火。须自灭也。以火泻之。疾吹其火。传其艾。须其火灭也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214740549, 'D927E6F091283C0A4AFE70E75B038C95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4706, 186, 20300571, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。五藏者。所以藏精神魂魄者也。六府者。所以受水谷而行化物者也。其气内干五藏。而外络肢节。其浮气之不循经者。为卫气。其精气之行于经者。为营气。阴阳相随。外内相贯。如环之无端。亭亭淳淳乎。孰能窃之。然其分别阴阳。皆有标本虚实所离之处。能别阴阳十二经者。知病之所生。候虚实之所在者。能得病之高下。知六府之气街者。能知解结契绍于门户。能知虚石之坚软者。知补泻之所在。能知六经标本者。可以无惑于天下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214957637, '578F74A29BBC1FF2D3E56B5465173F7B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4707, 186, 20300572, NULL, NULL, '', NULL, NULL, NULL, '2、岐伯曰。博哉。圣帝之论。臣请尽意悉言之。足太阳之本。在限以上五寸中。标在两络命门。命门者。目也。足少阳之本。在窍阴之间。标在窗笼之前。窗笼者。耳也。足少阴之本。在内踝下上三寸中。标在背输与舌下两脉也。足厥阴之本。在行间上五寸所。标在背腧也。足阳明之本。在厉兑。标在人迎。颊挟颃颡也。足太阴之本。在中封前上四寸之中。标在背腧与舌本也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214957638, 'B59FAF43338B9A1C9E7C6DF15180A854', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4708, 186, 20300573, NULL, NULL, '', NULL, NULL, NULL, '3、手太阳之本。在外踝之后。标在命门之上一寸也。手少阳之本。在小指次指之间上二寸。标在耳后上角下外眦也。手阳明之本。在肘骨中。上至别阳。标在颜下合钳上也。手太阴之本。在寸口之中。标在腋内动也。手少阴之本。在锐骨之端。标在背腧也。手心主之本。在掌后两筋之间二寸中。标在腋下下三寸也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214957639, '0EB68A242AD8B3962C9ACD7442220CAA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4709, 186, 20300574, NULL, NULL, '', NULL, NULL, NULL, '4、凡候此者。下虚则厥。下盛则热。上虚则眩。上盛则热痛。故石者。绝而止之。虚者。引而起之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214957640, 'C6917469417FFCD0F809D9C13C504AF5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4710, 186, 20300575, NULL, NULL, '', NULL, NULL, NULL, '5、请言气街。胸气有街。腹气有街。头气有街。胫气有街。故气在头者。止之于脑。气在胸者。止之膺与背腧。气在腹者。止之背腧。与冲脉于脐左右之动脉者。气在胫者。止之于气街。与承山踝上以下。取此者。用毫针。必先按而在久应于手。乃刺而予之。所治者。头痛眩。腹痛中满暴胀。及有新。痛可移者。易已也。积不痛。难已也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957214957641, 'F31F964242715263CD009C70939C0DEB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4711, 187, 20300576, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于少俞曰。筋骨之强弱。肌肉之坚脆。皮肤之厚薄。腠理之疏密。各不同。其于针石火焫之痛何如。肠胃之厚薄坚脆亦不等。其于毒药何如。愿尽闻之。少俞曰。人之骨强。筋弱。肉缓。皮肤厚者。耐痛。其于针石之痛火焫亦然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215178821, '23230C54F8481011150CC40D4AD61F92', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4712, 187, 20300577, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。其耐火煤者。何以知之。少俞答曰。加以黑色而美骨者。耐火焫。黄帝曰。其不耐针石之痛者。何以知之。少俞曰。坚肉薄皮者。不耐针石之痛。于火焫亦然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215178822, '93FEE1E484E581D23FFAA9684CBB2F53', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4713, 187, 20300578, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。人之病。或同时而伤。或易已。或难已。其故何如。少俞曰。同时而伤。其身多热者。易已。多寒者。难已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215178823, '24FBC9206809ED111314CC2AFCB52DE4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4714, 187, 20300579, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。人之胜毒。何以知之。少俞曰。胃厚。色黑。大骨及肥骨者。皆胜毒。故其瘦而薄胃者。皆不胜毒也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215178824, '1CFDC6C505FA60CFE8164560E50CE7B1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4715, 188, 20300580, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。愿闻人之始生。何气筑为基。何立而为楯。何失而死。何得而生。岐伯曰。以母为基。以父为楯。失神者死。得神者生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215400005, '16ED04152352EB5620DB46CBB8D5882D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4716, 188, 20300581, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。何者为神。岐伯曰。血气已和。营卫已通。五藏已成。神气舍心。魂魄毕具。乃成为人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215400006, 'A7280D06C782B69D3F0B33972B41E8E0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4717, 188, 20300582, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。人之寿夭各不同。或夭寿。或卒死。或病久。愿闻其道。岐伯曰。五藏坚固。血脉和调。肌肉解利。皮肤致密。营卫之行。不失其常。呼吸微徐。气以度行。六府化谷。津液布扬。各如其常。故能长久。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215400007, '02BD76BB337F8DDC3A760A3C6D651661', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4718, 188, 20300583, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。人之寿百岁而死。何以致之。岐伯曰。使道隧以长。基墙高以方。通调营卫。三部三里起。骨高肉满。百岁乃得终。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215400008, 'A98B1EF0F045D7ABFBA41FBB2D28F54D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4719, 188, 20300584, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。其气之盛衰。以至其死。可得闻乎。岐伯曰。人生十岁。五藏始定。血气已通。其气在下。故好走。二十岁。血气始盛肌肉方长。故好趋。三十岁。五藏大定。肌肉坚固。血脉盛满。故好步。四十岁。五藏六府十二经脉。皆大盛以平定。腠理始疏。荣华颓落。发颇斑白。平盛不摇。故好坐。五十岁。肝气始衰。肝叶始薄。胆汁始减。目始不明。六十岁。心气始衰。若忧悲。血气懈惰。故好卧。七十岁。脾气虚。皮肤枯。八十岁。肺气衰。魄离。故言善误。九十岁。肾气焦。四藏经脉空虚。百岁。五藏皆虚。神气皆去。形骸独居而终矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215400009, '52368AA0138DC8EB4EC61CBE154928E7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4720, 188, 20300585, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。其不能终寿而死者。何如。岐伯曰。其五藏皆不坚。使道不长。空外以张。喘息暴疾。又卑基墙薄。脉少血。其肉不石。数中风寒。血气虚。脉不通。真邪相攻。乱而相引。故中寿而尽也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215400010, '06F8DEA104B0C211A78C2C3734014EC5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4721, 189, 20300586, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于伯高曰。余闻气有逆顺。脉有盛衰。刺有大约。可得闻乎。伯高曰。气之逆顺者。所以应天地阴阳四时五行也。脉之盛衰者。所以候血气之虚实有余不足。刺之大约者。必明知病之可刺。与其未可刺。与其已不可刺也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215617093, '0746A6CD8D27C59AE23AFCCA9C33949A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4722, 189, 20300587, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。候之奈何。伯高曰。兵法曰无迎逢逢之气。无击堂堂之阵。刺法曰。无刺熇熇之热。无刺漉漉之汗。无刺浑浑之脉。无刺病与脉相逆者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215617094, 'A6CD41971062359670316781570ACCD9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4723, 189, 20300588, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。候其可刺奈何。伯高曰。上工。刺其未生者也。其次。刺其未盛者也。其次。刺其已衰者也。下工。刺其方袭者也。与其形之盛者也。与其病之与脉相逆者也。故曰。方其盛也。勿敢毁伤。刺其已衰。事必大昌。故曰。上工治未病。不治已病。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215617095, 'E736DC0133B025EF8E5CF97B72CC5A17', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4724, 190, 20300589, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。愿闻谷气有五味。其入五藏。分别奈何。伯高曰。胃者。五藏六府之海也。水谷皆入于胃。五藏六府。皆禀气于胃。五味各走其所喜。谷味酸。先走肝。谷味苦。先走心。谷味甘。先走脾。谷味辛。先走肺。谷味咸。先走肾。谷气津液已行。营卫大通。乃化糟粕。以次传下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215842373, '466094FFBEC3C86D8135C6F34FBD7023', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4725, 190, 20300590, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。营卫之行奈何。伯高曰。谷始入于胃。其精微者。先出于胃之两焦。以溉五藏。别出两行。营卫之道。其大气之搏而不行者。积于胸中。命曰气海。出于肺。循咽喉。故呼则出。吸则入。天地之精气。其大数常出三入一。故谷不入。半日则气衰。一日则气少矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215842374, '9C18A78AACA15CD678DB7F6932E7492D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4726, 190, 20300591, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。谷之五味。可得闻乎。伯高曰。请尽言之。五谷。糠米甘。麻酸。大豆咸。麦苦。黄黍辛。五果。枣甘。李酸。栗咸。杏苦。桃辛。五畜。牛甘。犬酸。猪咸。羊苦。鸡辛。五菜。葵甘。韭酸。藿咸。薤苦。葱辛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215842375, '8AAD376FED3FA92317BCB79BC9007A31', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4727, 190, 20300592, NULL, NULL, '', NULL, NULL, NULL, '4、五色。黄色宜甘。青色宜酸。黑色宜咸。赤色宜苦。白色宜辛。凡此五者。各有所宜。五宜所言五色者。脾病者。宜食糠米饭。牛肉枣葵。心病者。宜食麦羊肉杏薤。肾病者。宜食大豆黄卷猪肉栗藿。肝病者。宜食麻犬肉李韭。肺病者。宜食黄黍鸡肉桃葱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215842376, 'C8BC590E09AE171AB302FE789AD4F8B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4728, 190, 20300593, NULL, NULL, '', NULL, NULL, NULL, '5、五禁。肝病禁辛。心病禁咸。脾病禁酸。肾病禁甘。肺病禁苦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215842377, '7D213011C8D5FA48A4D4A02A7416D2B0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4729, 190, 20300594, NULL, NULL, '', NULL, NULL, NULL, '6、肝色青。宜食甘。糠米饭。牛肉。枣。葵皆甘。心色赤。宜食酸。犬肉。麻。李。韭皆酸。脾黄色。宜食咸。大豆。猪肉。栗。藿皆咸。肺白色。宜食苦。麦。羊肉。杏。薤皆苦。肾色黑。宜食辛。黄黍。鸡肉。桃。葱皆辛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957215842378, '76F984D7BAD88946CC5F198979DF2716', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4730, 191, 20300595, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。水与肤胀。鼓胀。肠覃。石瘕。石水。何以别之。岐伯曰。水始起也。目窠上微肿。如新卧起之状。其颈脉动。时咳。阴股间寒。足胫肿。腹乃大。其水已成矣。以手按其腹。随手而起。如裹水之状。此其候也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216067653, 'D7794BDB72BE17CB94D34EDEB6C24CA4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4731, 191, 20300596, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。肤胀何以候之。岐伯曰。肤胀者。寒气客于皮肤之间。冬冬然不坚。腹大。身尽肿。皮厚。按其腹。窅而不起。腹色不变。此其候也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216067654, '203381807405185A4E3ADDA80EAFB8D5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4732, 191, 20300597, NULL, NULL, '', NULL, NULL, NULL, '3、鼓胀何如。岐伯曰。腹胀身皆大。大与肤胀等也。色苍黄。腹筋起。此其候也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216067655, 'BD5C4B92344FAE962C2A70C9F4B3F56F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4733, 191, 20300598, NULL, NULL, '', NULL, NULL, NULL, '4、肠覃何如。岐伯曰。寒气客于肠外。与卫气相搏。气不得荣。因有所系。癖而内着。恶气乃起。瘜肉乃生。其始生也。大如鸡卵。稍以益大。至其成。如怀子之状。久者离岁。按之则坚。推之则移。月事以时下。此其候也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216067656, '353F99D6D83D9CF704529BC4BED0712D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4734, 191, 20300599, NULL, NULL, '', NULL, NULL, NULL, '5、石瘕何如。岐伯曰。石瘕生于胞中。寒气客于子门。子门闭塞。气不得通。恶血当泻不泻。衄以留止。日以益大。状如怀子。月事不以时下。皆生于女子。可导而下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216067657, '1A9B8494FE6BEE4AE972EAD620E9B75A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4735, 191, 20300600, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。肤胀鼓胀。可刺邪。岐伯曰。先泻其胀之血络。后调其经。刺去其血血络也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216067658, 'D40928BE7D7C7D60B9993C829A5ED246', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4736, 192, 20300601, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。夫子言贼风邪气伤人也。令人病焉。今有其不离屏蔽。不出室穴之中。卒然病者。非不离贼风邪气。其故何也。岐伯曰。此皆尝有所伤于湿气。藏于血脉之中。分肉之间。久留而不去。若有所堕坠。恶血在内而不去。卒然喜怒不节。饮食不适。寒温不时。腠理闭而不通。其开而遇风寒。则血气凝结。与故邪相袭。则为寒痹。其有热则汗出。汗出则受风。虽不遇贼风邪气。必有因加而发焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216288837, '1E407BC011F724C9098E42230D6E7DBF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4737, 192, 20300602, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。今夫子之所言者。皆病人之所自知也。其毋所遇邪气。又毋怵惕之所志。卒然而病者。其故何也。唯有因鬼神之事乎。岐伯曰。此亦有故邪留而未发。因而志有所恶。及有所慕。血气内乱。两气相搏。其所从来者微。视之不见。听而不闻。故似鬼神。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216288838, '30EF820D4BD873321ECE9AD128590368', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4738, 192, 20300603, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。其祝而已者。其故何也。岐伯曰。先巫者。因知百病之胜。先知其病之所从生者。可祝而已也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216288839, '60145F88127D19E93C5D414FA915549B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4739, 193, 20300604, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。卫气之留于腹中。搐积不行。菀蕴不得常所。使人支胁胃中满。喘呼逆息者。何以去之。伯高曰。其气积于胸中者。上取之。积于腹中者。下取之。上下皆满者。旁取之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518213, '62CCC59F328A6E2D96E76CCF8DEEAAF7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4740, 193, 20300605, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。取之奈何。伯高对曰。积于上。泻人迎。天突。喉中。积于下者。泻三里与气街。上下皆满者。上下取之。与季胁之下一寸。重者。鸡足取之。诊视其脉大而弦急。及绝不至者。及腹皮急甚者。不可刺也。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518214, '73F6E47A15C30221D6FE2E04E40B13BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4741, 193, 20300606, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝问于伯高曰。何以知皮肉气血筋骨之病也。伯高曰。色起两眉薄泽者。病在皮。唇色青黄赤白黑者。病在肌肉。营气濡然者。病在血气。目色青黄赤白黑者。病在筋。耳焦枯受尘垢。病在骨。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518215, 'BEAB3D5990A06F2D2781F2E0F5DDE7E7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4742, 193, 20300607, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。病形何如。取之奈何。伯高曰。夫百病变化。不可胜数。然皮有部。肉有桂。血气有输。骨有属。黄帝曰。愿闻其故。伯高曰。皮之部。输于四末。肉之柱。有臂胫诸阳分肉之间。与足少阴分间。血气之输。输于诸络。气血留居。则盛而起。筋部无阴无阳。无左无右。候病所在。骨之属者。骨空之所以受益而益脑者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518216, '0453F8473E43B523F3F01D5231E2A6EF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4743, 193, 20300608, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。取之奈何。伯高曰。夫病变化。浮沉深浅。不可胜究。各在其处。病间者浅之。甚者深之。间者小之。甚者众之。随变而调气。故曰上工。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518217, '64BF10F2A803F3DB77102FB1C7CB7161', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4744, 193, 20300609, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝问于伯高曰。人之肥瘦大小温寒。有老壮少小。别之奈何。伯高对曰。人年五十已上为老。二十已上为壮。十八已上为少。六岁已上为小。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518218, '384B4849F753AFBA3E8E2069711D11AD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4745, 193, 20300610, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。何以度知其肥瘦。伯高曰。人有肥。有膏。有肉。黄帝曰。别此奈何。伯高曰。腘肉坚。皮满者。肥。腘肉不坚。皮缓者。膏。皮肉不相离者。肉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518219, 'BC19CF2865BEB5A78BD826F2917F041C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4746, 193, 20300611, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。身之寒温何如。伯高。膏者。其肉淖而粗理者。身寒。细理者。身热。脂者。其肉坚。细理者热。粗理者寒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518220, 'D52693D136DB712B9987E9C0269DF408', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4747, 193, 20300612, NULL, NULL, '', NULL, NULL, NULL, '9、黄帝曰。其肥瘦大小奈何。伯高曰。膏者。多气而皮纵缓。故能纵腹垂腴。肉者。身体容大。脂者。其身收小。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518221, 'AED28F67D0D9BE87C25B26A353BE881D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4748, 193, 20300613, NULL, NULL, '', NULL, NULL, NULL, '10、黄帝曰。三者之气血多少何如。伯高曰。膏者。多气。多气者。热。热者耐寒。肉者。多血则充形。充形则平。脂者。其血清。气滑少。故不能大。此别于众人者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518222, 'A83D900DD16FF197781511363C5DC609', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4749, 193, 20300614, NULL, NULL, '', NULL, NULL, NULL, '11、黄帝曰。众人奈何。伯高曰。众人皮肉脂膏。不能相加也。血与气。不能相多。故其形不小不大。各自称其身。命曰众人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518223, 'C19F7BE46AAE349949D1EBB10C08F965', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4750, 193, 20300615, NULL, NULL, '', NULL, NULL, NULL, '12、黄帝曰。善。治之奈何。伯高曰。必先别其三形。血之多少。气之清浊。而后调之。治无失常经。是故膏人纵腹垂腴。肉人者。上下容大。脂人者。虽脂不能大者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216518224, '0EF1C270F9229CD5E49C3169B0049D39', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4751, 194, 20300616, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余以小针为细物也。夫子乃言上合之于天。下合之于地。中合之于人。余以为过针之意矣。愿闻其故。岐伯曰。何物大于天乎。夫大于针者。惟五兵者焉。死之备也。非生之具。且夫人者。天地之镇也。其不可不参乎。夫治民者。亦唯针焉。夫针之与五兵。其孰小乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759877, '952E799750C31400F93A0575181D807A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4752, 194, 20300617, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。病之生时。有喜怒不测。饮食不节。阴气不足。阳气有余。营气不行。乃发为痈疽。阴阳不通。两热相搏。乃化为浓。小针能取之乎。岐伯曰。圣人不能使化者为之。邪不可留也。故两军相当。旗帜相望。白刃陈于中野者。此非一日之谋也。能使其民令行。禁止士卒无白刃之难者。非一日之教也。须臾之得也。夫至使身被痈疽之病。脓血之聚者。不亦离道远乎。夫痈疽之生。脓血之成也。不从天下。不从地出。积微之所生也。故圣人自治于未有形也。愚者遭其已成也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759878, '4BD49A8BB10AE0E5157A81BD5D48AF0E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4753, 194, 20300618, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。其已形。不予遭。脓已成。不予见。为之奈何。岐伯曰。脓已成。十死一生。故圣人弗使已成。而明为良方。着之竹帛。使能者踵而传之后世。无有终时者。为其不予遭也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759879, 'B160286C73D81C3D9A2872AE5C8388DF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4754, 194, 20300619, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。其已有脓血而后遭乎。不导之以小针治乎。岐伯曰。以小治小者。其功小。以大治大者。多害。故其已成脓血者。其唯砭石铍锋之所取也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759880, 'B5F1F578508B0B7519A51620F48B9224', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4755, 194, 20300620, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。多害者其不可全乎。岐伯曰。其在逆顺焉。黄帝曰。愿闻逆顺。岐伯曰。以为伤者。其白眼青。黑眼小。是一逆也。内药而呕者。是二逆也。腹痛渴甚。是三逆也。肩项中不便。是四逆也。音嘶色脱。是五逆也。除此五者。为顺矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759881, '0AF4E14E6FB657990305B662E13D24B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4756, 194, 20300621, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。诸病皆有逆顺。可得闻乎。岐伯曰。腹胀。身热。脉大。是一逆也。腹鸣而满。四肢清泄。其脉大。是二逆也。衄而不止。脉大。是三逆也。咳而溲血脱形。其脉小劲。是四逆也。咳脱形。身热。脉小以疾。是谓五逆也。如是者。不过十五日而死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759882, 'B49D16FB8FCA372D7FE5D2848DC31C13', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4757, 194, 20300622, NULL, NULL, '', NULL, NULL, NULL, '7、其腹大胀。四末清。脱形。泄甚。是一逆也。腹胀便血。其脉大。时绝。是二逆也。咳溲血。形肉脱。脉搏。是三逆也。呕血。胸满引背。脉小而疾。是四逆也。咳呕。腹胀且飧泄。其脉绝。是五逆也。如是者。不及一时而死矣。工不察此者而刺之。是谓逆治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759883, '479D091F9A294476636D4E645F004CBD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4758, 194, 20300623, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。夫子之言针甚骏。以配天地。上数天文。下度地纪。内别五藏。外次六府。经脉二十八会。尽有周纪。能杀生人。不能起死者。子能反之乎。岐伯曰。能杀生人。不能起死者也。黄帝曰。余闻之。则为不仁。然愿闻其道。弗行于人。岐伯曰。是明道也。其必然也。其如刀剑之可以杀人。如饮酒使人醉也。虽勿诊。犹可知矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759884, '87E84A123B82E14973F50960AF9230AC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4759, 194, 20300624, NULL, NULL, '', NULL, NULL, NULL, '9、黄帝曰。愿卒闻之。岐伯曰。人之所受气者。谷也。谷之所注者。胃也。胃者。水谷气血之海也。海之所行云气者。天下也。胃之所出气血者。经隧也。而隧者。五藏六府之大络也。迎而夺之而已矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759885, 'E725D15F98F9FAC659D4317931C771E2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4760, 194, 20300625, NULL, NULL, '', NULL, NULL, NULL, '10、黄帝曰。上下有数乎。岐伯曰。迎之五里。中道而止。五至而已。五往而藏之气尽矣。故五五二十五。而竭其输矣。此所谓夺其天气者也。非能绝其命而倾其寿者也。黄帝曰。愿卒闻之。岐伯曰。窥门而刺之者。死于家中。入门而刺之者。死于堂上。黄帝曰。善乎方。明哉道。请着之玉版。以为重宝。传之后世。以为刺禁。令民勿敢犯也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957216759886, 'C47DF395F58307A84E3F212F89FC57E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4761, 195, 20300626, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余闻刺有五禁。何谓五禁。岐伯曰。禁其不可刺也。黄帝曰。余闻刺有五夺。岐伯曰。无泻其不可夺者也。黄帝曰。余闻刺有五过。岐伯曰。补泻无过其度。黄帝曰。余闻刺有五逆。岐伯曰。病与脉相逆。命曰五逆。黄帝曰。余闻刺有九宜。岐伯曰。明知九针之论。是谓九谊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217005637, '2EA1AE88AD0F3883102DBDF706FFD16B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4762, 195, 20300627, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。何谓五禁。愿闻其不可刺之时。岐伯曰。甲乙日自乘。无刺实。无发蒙于耳内。丙丁日自乘。无振埃于肩喉廉泉。戊己日自乘四季。无刺腹。去爪泻水。庚辛日自乘。无刺关节于股膝。壬癸日自乘。无刺足胫。是谓五禁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217005638, '2F8EC4F31F8C6BC5CCD9B52416DB7BF0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4763, 195, 20300628, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。何谓五夺。岐伯曰。形肉已夺。是一夺也。大夺血之后。是二夺也。大汗出之后。是三夺也。大泄之后。是四夺也。新产及大血之后。是五夺也。此皆不可泻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217005639, '00075BB3DAAC997626ADE996488CA255', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4764, 195, 20300629, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。何谓五逆。岐伯曰。热病脉静。汗已出。脉盛躁。是一逆也。病泄。脉洪大。是二逆也。着痹不移䐃肉破。身热。脉偏绝。是三逆也。淫而夺形。身热。色夭然白。乃后下血衄。血衄笃重。是谓四逆也。寒热夺形。脉坚搏。是谓五逆也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217005640, '79ED70F3C01E56C7838AE91D5D424DF0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4765, 196, 20300630, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。经脉十二。而手太阴。足少阴。阳明。独动不休。何也。岐伯曰。是明胃脉也。胃为五藏六府之海。其清气上注于肺。肺气从太阴而行之。其行也。以息往来。故人一呼。脉再动。一吸脉亦再动。呼吸不已。故动而不止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217230917, '095DD57E54D81E23962FC667B9150DE1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4766, 196, 20300631, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。气之过于寸口也。上十焉息。下八焉伏。何道从还。不知其极。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217230918, '55AA6B28CEA0605AFB1C2B56A2AEAAF9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4767, 196, 20300632, NULL, NULL, '', NULL, NULL, NULL, '3、岐伯曰。气之离藏也。卒然如弓弩之发。如水之下岸。上于鱼以及衰。其余气衰散以逆上。故其行微。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217230919, '271567C6C2869DFD12D0F5DC82A6F725', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4768, 196, 20300633, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。足之阳明。何因而动。岐伯曰。胃气上注于肺。其悍气上冲头者。循咽。上走空窍。循眼系。入络脑。出顑。下客主人。循牙车。合阳明。并下人迎。此胃气别走于阳明者也。故阴阳上下。其动也若一。故阳病而阳脉小者。为逆。阴病而阴脉大者。为逆。故阴阳俱静俱动。若引绳相倾者病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217230920, 'B2FBCCB7AAB6E2D8ABECD48BE46AFA46', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4769, 196, 20300634, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。足少阴何因而动。岐伯曰。冲脉者。十二经之海也。与少阴之大络。起于肾下。出于气街。循阴股内廉。邪入腘中。循胫骨内廉。并少阴之经。下入内踝之后。入足下。其别者。邪入踝。出属附上。入大指之间。注诸络。以温足胫。此脉之常动者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217230921, 'B8740CF6738E6944BE7BB03B3C72DD40', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4770, 196, 20300635, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。营卫之行也。上下相贯。如环之无端。今有其卒然遇邪风。及逢大寒。手足懈惰。其脉阴阳之道。相输之会。行相失也。气何由还。岐伯曰。夫四末阴阳之会者。此气之尤络也。四街者。气之径路也。故络绝则径通。四末解则气从合。相输如环。黄帝曰。善。此所谓如环无端。莫知其纪。终而复始。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217230922, 'C706A5AD10988981B8A1EA8E627BB176', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4771, 197, 20300636, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于少俞曰。五味入于口也。各有所走。各有所病。酸走筋。多食之。令人癃。咸走血。多食之。令人渴。辛走气。多食之。令人洞心。苦走骨。多食之。令人变呕。甘走肉。多食之。令人挽心。余知其然也。不知其何由。愿闻其故。少俞答曰。酸入于胃。其气涩以收。上之两焦。弗能出入也。不出即留于胃中。胃中和温。则下注膀胱。膀胱之胞薄以懦。得酸则缩绻。约而不通。水道不行。故癃。阴者。积筋之所终也。故酸入而走筋矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217472581, 'F376DB0AB0C1C86692C63E865E2DAC53', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4772, 197, 20300637, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。咸走血。多食之。令人渴。何也。少俞曰。咸入于胃。其气上走中焦。注于脉。则血气走之。血与咸相得。则凝。凝则胃中汁注之。注之则胃中竭。竭则咽路焦。故舌本干而善渴。血脉者。中焦之道也。故咸入而走血矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217472582, 'CA2E1270077D7C4FF82DBCDB68A7E662', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4773, 197, 20300638, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。辛走气。多食之。令人洞心。何也。少俞曰。辛入于胃。其气走于上焦。上焦者。受气而营诸阳者也。姜韭之气熏之。营卫之气。不时受之。久留心下。故洞心。辛与气俱行。故辛入而与汗俱出。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217472583, '1B88908654C131E9508C251B1BC371A6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4774, 197, 20300639, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。「苦走骨。多食之。令人变呕。何也。」少俞曰。苦入于胃。五谷之气。皆不能胜苦。苦入下脘。三焦之道。皆闭而不通。故变呕。齿者。骨之所终也。故苦入而走骨。故入而复出。知其走骨也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217472584, '72DE12BA30A00714DDE211DC9D4B2272', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4775, 197, 20300640, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。甘走肉。多食之。令人悗心。何也。少俞曰。甘入于胃。其气弱小。不能上至于上焦。而与谷留于胃中者。令人柔润者也。胃柔则缓。缓则虫动。虫动则令人悗心。其气外通于肉。故甘走肉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217472585, '44AE222194B1F819163302BD47DBD523', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4776, 198, 20300641, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余闻阴阳之人何如。伯高曰。天地之间。六合之内。不离于五。人亦应之。故五五二十五人之政。而阴阳之人不与焉。其态又不合于众者五。余已知之矣。愿闻二十五人之形。血气之所生。别而以候。从外知内。何如。岐伯曰。「悉乎哉问也。此先师之秘也。虽伯高犹不能明之也。黄帝避席遵循而却曰。余闻之得其人弗教。是谓重失。得而泄之。天将厌之。余愿得而明之。金柜藏之。不敢扬之。岐伯曰。先立五形金木水火土。别其五色。异其五形之人。而二十五人具矣。黄帝曰。愿卒闻之。岐伯曰。慎之慎之。臣请言之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714245, 'ADF4C06DFDED3370BA15A0242D91EA57', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4777, 198, 20300642, NULL, NULL, '', NULL, NULL, NULL, '2、木形之人。比于上角似于苍帝。其为人苍色。小头。长面大肩背直身小。手足好。有才。劳心少力多忧。劳于事。能春夏不能秋冬感而病生。足厥阴。佗佗然。大角之人比于左足少阳。少阳之上遗遗然。左角之人比于右足少阳。少阳之下随随然。钛角之人。比于右足少阳。少阳之上推推然。判角之人比于左足少阳。少阳之下枯枯然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714246, 'BA033A91AA920E714F12742086E9C118', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4778, 198, 20300643, NULL, NULL, '', NULL, NULL, NULL, '3、火形之人。比于上征。似于赤帝。其为人赤色广䏖脱面小头。好肩背。髀腹小手足。行安地疾心。行摇肩背肉满。有气轻财少信多虑。见事明好颜。急心不寿暴死。能春夏不能秋冬。秋冬感而病生。手少阴核核然。质征之人。比于左手太阳。太阳之上。肌肌然。少征之人比于右手太阳。太阳之下慆慆然。右征之人比于右手太阳。太阳之上鲛鲛然。质判之人。比于左手太阳。太阳之下支支颐颐然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714247, 'C3D53E21C22DDA4512FA8E58169916B9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4779, 198, 20300644, NULL, NULL, '', NULL, NULL, NULL, '4、土形之人。比于上宫。似于上古黄帝。其为人黄色圆面。大头。美肩背。大腹。美股胫。小手足。多肉。上下相称行安地。举足浮。安心。好利人不喜权势。善附人也。能秋冬不能春夏。春夏感而病生。足太阴。敦敦然。大宫之人比于左足阳明。阳明之上婉婉然。加宫之人。比于左足阳明。阳明之下坎坎然。少宫之人。比于右足阳明。阳明之上。枢枢然。左宫之人。比于右足阳明。阳明之下。兀兀然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714248, 'FDB6483AC7384FD7195FB4BDAE5B27EC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4780, 198, 20300645, NULL, NULL, '', NULL, NULL, NULL, '5、金形之人比于上商。似于白帝。其为人方面白色。小头。小肩背小腹。小手足如骨发踵外。骨轻。身清廉。急心静悍。善为吏。能秋冬。不能春夏。春夏感而病生。手太阴敦敦然。釱商之人比于左手阳明。阳明之上。廉廉然。右商之人。比于左手阳明。阳明之下脱脱然。左商之人比于右手阳明。阳明之上监监然。少商之人。比于右手阳明。阳明之下。严严然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714249, '020695EC97F7680A8C57E47F17630E58', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4781, 198, 20300646, NULL, NULL, '', NULL, NULL, NULL, '6、水形之人。比于上羽。似于黑帝。其为人。黑色面不平。大头廉颐。小肩大腹动手足。发行摇身下尻长。背延延然。不敬畏善欺绍人。戮死。能秋冬不能春夏。春夏感而病生。足少阴汗汗然。大羽之人。比于右足太阳。太阳之上。颊颊然。少羽之人。比于左足太阳。太阳之下洁洁然。桎之为人。比于左足太阳。太阳之上安安然。是故五形之人二十五变者。众之所以相欺者是也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714250, 'EF653D637917DD083A24A1996E2CC5F2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4782, 198, 20300647, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。得其形。不得其色何如。岐伯曰。形胜色。色胜形者。至其胜时年加。感则病行。失则忧矣。形色相得者。富贵大乐。黄帝曰。其形色相当胜之时。年加可知乎。岐伯曰。凡年忌下上之人。大忌常加七岁。十六岁。二十五岁。三十四岁。四十三岁。五十二岁。六十一岁皆人之大忌。不可不自安也。感则病行。失则忧矣。当此之时。无为奸事。是谓年忌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714251, 'A6B3653F8EF216F885714E45B2B2E214', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4783, 198, 20300648, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。夫子之言脉之上下。血气之候似知形气。奈何。岐伯曰。足阳明之上血气盛则髯美长。血少气多则髯短。故气少血多则髯少。血气皆少则无髯。两吻多画。足阳明之下血气盛则下毛美长至胸。血多气少则下毛美短至脐。行则善高举足。足指少肉足善寒。血少气多则肉而善瘃。血气皆少则无毛有则稀。枯悴。善痿厥。足痹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714252, '025CB9564689F235360885C011676AE2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4784, 198, 20300649, NULL, NULL, '', NULL, NULL, NULL, '9、足少阳之上。气血盛则通髯美长。血多气少则通髯美短。血少气多则少髯。血气皆少则无须。感于寒湿则善痹。骨痛爪枯也。足少阳之下。血气盛则胫毛美长。外踝肥。血多气少则胫毛美短。外踝皮坚而厚。血少气多则胻毛少。外踝皮薄而软。血气皆少则无毛。外踝瘦无肉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714253, '6E4B0A6D0AE51D53007FF1F92F0BDFE5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4785, 198, 20300650, NULL, NULL, '', NULL, NULL, NULL, '10、足太阳之上。血气盛则美眉。眉有毫毛血多气少则恶眉。面多少理。血少气多则面多肉。血气和则美色。足太阳之下。血气盛则肉满。踵坚。气少血多则瘦。跟空。血气皆少则善转筋。踵下痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714254, 'B9EE28C04B05C7B87923B013D9A0C857', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4786, 198, 20300651, NULL, NULL, '', NULL, NULL, NULL, '11、手阳明之上。血气盛则髭美。血少气多则髭恶。血气皆少则无髭。手阳明之下血气盛则腋下毛美。手鱼肉以温。气血皆少则手瘦以寒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714255, '67DD6A1AF59E54789A643FCF4CD2FD03', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4787, 198, 20300652, NULL, NULL, '', NULL, NULL, NULL, '12、手少阴之上。血气盛则眉美以长。耳色美。血气皆少则耳焦恶色。手少阳之下。血气盛则手卷多肉以温。血气皆少则寒以瘦。气少血多则瘦以多脉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714256, '68827F0C29E73B5E8A22FC6EB28D1ADD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4788, 198, 20300653, NULL, NULL, '', NULL, NULL, NULL, '13、手太阳之上。血气盛则多须。面多肉以平。血气皆少则面瘦恶色。手太阳之下。血气盛则掌肉充满。血气皆少则掌瘦以寒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714257, 'F90EFC98C8DD82A9CA24D48B1AC49C10', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4789, 198, 20300654, NULL, NULL, '', NULL, NULL, NULL, '14、黄帝曰。二十五人者。刺之有约乎。岐伯曰。美眉者。足太阳之脉。气血多。恶眉者。血气少。其肥而泽者。血气有余。肥而不泽者。气有余。血不足。瘦而无泽者。气血俱不足。审察其形气有余不足而调之。可以知逆顺矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714258, '78AD2091B7D6295E9F95D60302087F05', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4790, 198, 20300655, NULL, NULL, '', NULL, NULL, NULL, '15、黄帝曰。刺其诸阴阳奈何。岐伯曰。按其寸口人迎。以调阴阳。切循其经络之凝涩。结而不通者。此于身皆为痛痹。甚则不行。故凝涩。凝涩者。致气以温之血和乃止。其结络者。脉结血不和。决之乃行。故曰。气有余于上者。导而下之。气不足于上者。推而休之。其稽留不至者。因而迎之。必明于经隧。乃能持之。寒与热争者。导而行之。其宛陈血不结者。则而予之。必先明知二十五人则血气之所在。左右上下。刺约毕也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217714259, 'F20D08E4424B841781C1210BB5BA22B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4791, 199, 20300656, NULL, NULL, '', NULL, NULL, NULL, '1、右征与少征。调右手太阳二。左商与左征。调左手阳明上。少征与大宫。调左手阳明上。右角与大角。调右手少阳下。大征与少征。调左手太阳上。众羽与少羽。调右足太阳下。少商与右商调右手太阳下。桎羽与众羽。调右足太阳下。少宫与大宫。调右足阳明下。判角与少角。调右足少阳下。釱商与上商。调右足阳明下。釱商与上角。调左足太阳下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955909, '1BE126466F6286E88CE574460579DC99', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4792, 199, 20300657, NULL, NULL, '', NULL, NULL, NULL, '2、上征与右征同谷麦。畜羊。果杏。手少阴藏心。色赤味苦。时夏。上羽与大羽。同谷大豆。畜彘。果栗。足少阴藏肾。色黑味咸。时冬。上宫与大宫同谷稷。畜牛。果枣。足太阴藏脾。色黄味甘。时季夏。上商与右商同谷黍。畜鸡。果桃。手太阴藏肺。色白味辛。时秋。上角与大角。同谷麻。畜犬。果李。足厥阴藏肝。色青味酸。时春。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955910, '33589AD7407809F15123E40DDFD16A20', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4793, 199, 20300658, NULL, NULL, '', NULL, NULL, NULL, '3、大宫与上角。同右足阳明上。左角与大角。同左足阳明上。少羽与大羽同右足太阳下。左商与右商。同左手阳明上。加宫与大宫同左足少阳上。质判与大宫。同左手太阳下。判角与大角同左足少阳下。大羽与大角。同右足太阳上。大角与大宫同右足少阳上。右征。少征。质征。上征。判征。右角。釱角。上角。大角。判角。右商。少商。釱商。上商。左商。少宫。上宫。大宫。加宫。左角宫。众羽。桎羽。上羽。大羽。少羽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955911, '4244AB2F08CD82AE8F0253CFC267E569', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4794, 199, 20300659, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。妇人无须者。无血气乎。岐伯曰。冲脉任脉皆起于胞中。上循背里。为经络之海。其浮而外者。循腹右上行。会于咽喉。别而络唇口。血气盛则充肤热肉。血独盛者澹渗皮肤。生毫毛。今妇人之生有余于气。不足于血以其数脱血也。冲任之脉。不荣口唇。故须不生焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955912, '14930A241DF8661DAD47630737BB8C2B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4795, 199, 20300660, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。士人有伤于阴。阴气绝而不起。阴不用。然其须不去。其故何也。宦者独去何也。愿闻其故。岐伯曰。宦者去其宗筋。伤其冲脉。血泻不复。皮肤内结。唇口内荣故须不生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955913, '7817F008076F983528BD0A6EA7827F96', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4796, 199, 20300661, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。其有天宦者。未尝被伤。不脱于血。然其须不生其故何也。岐伯曰。此天之所不足也。其任冲不盛。宗筋不成。有气无血。唇口不荣。故须不生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955914, 'A9C2988F72A1B7C94B9AF349209D8888', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4797, 199, 20300662, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。善乎哉。圣人之通万物也。若日月之光影。音声鼓响。闻其声而知其形。其非夫子。孰能明万物之精。是故圣人。视其颜色黄赤者。多热气。青白者少热气。黑色者多血少气。美眉者。太阳多血。通髯极须者。少阳多血。美须者阳明多血。此其时然也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955915, '9978851B24F9BB340EAA7F6CEC3742BB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4798, 199, 20300663, NULL, NULL, '', NULL, NULL, NULL, '8、夫人之常数。太阳常多血少气。少阳常多气少血。阳明常多血多气。厥阴常多气少血。少阴常多血少气。太阴常多血少气。此天之常数也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957217955916, 'D57FA591E2DAEDFEB2416E6C9A486EC2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4799, 200, 20300664, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。夫百病之始生也。皆于风雨寒暑。清湿喜怒。喜怒不节则伤藏。风雨则伤上。清湿则伤下。三部之气所伤异类。愿闻其会。岐伯曰。三部之气各不同或起于阴或起于阳请言其方。喜怒不节则伤藏。藏伤则病起于阴也。清湿袭虚。则病起于下。风雨袭虚。则病起于上。是谓三部。至于其淫泆。不可胜数。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218189381, 'A360B762E61C7897E6CD73287132A4E4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4800, 200, 20300665, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。余固不能数。故问先师愿卒闻其道。岐伯曰。风雨寒热不得虚。邪不能独伤人。卒然逢疾风暴雨而不病者。盖无虚。故邪不能独伤人。此必因虚邪之风。与其身形。两虚相得。乃客其形。两实相逢。众人肉坚。其中于虚邪也因于天时。与其身形。参以虚实。大病乃成。气有定舍。因处为名。上下中外。分为三员。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218189382, '140F02030C2FA0CF2CF5BBB8C4B798E1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4801, 200, 20300666, NULL, NULL, '', NULL, NULL, NULL, '3、是故虚邪之中人也。始于皮肤。皮肤缓则腠理开。开则邪从毛发入。入则抵深。深则毛发立。毛发立则淅然。故皮肤痛。留而不去。则传舍于络脉。在络之时。痛于肌肉。故痛之时息。大经代去。留而不去。传舍于经。在经之时。洒淅喜惊。留而不去。传舍于俞。在俞之时。六经不通四肢。则肢节痛。腰脊乃强。留而不去。传舍于伏冲之脉。在伏冲之时体重身痛。留而不去。传舍于肠胃。在肠肾之时。贲响腹胀。多寒则肠鸣飧泄。食不化。多热则溏出糜。留而不去。传舍于肠胃之外。募原之间。留着于脉。稽留而不去。息而成积。或着孙脉。或着络脉。或着经脉。或着俞脉。或着于伏冲之脉。或着于膂筋。或着于肠胃之募原。上连于缓筋。邪气淫泆。不可胜论。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218189383, '73D4B9079B54197F5028E8C92B51CBC0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4802, 200, 20300667, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。愿尽闻其所由然。岐伯曰。其着孙络之脉而成积者。其积往来上下。臂小孙络之居也。浮而缓。不能句积而止之。故往来移行肠胃之间。水凑渗注灌。濯濯有音。有寒则䐜。䐜满雷引。故时切痛。其着于阳明之经则挟脐而居。饱食则益大。饥则益小。其着于缓筋也。似阳明之积。饱食则痛。饥则安。其着于肠胃之募原也。痛而外连于缓筋。饱食则安。饥则痛。其着于伏冲之脉者。揣之应手而动。发手则热气下于两股。如汤沃之状。其着于膂筋。在肠后者饥则积见。饱则积不见。按之不得。其着于输之脉者。闭塞不通。津液不下。孔窍干壅。此邪气之从外入内。从上下也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218189384, 'BB038B08267903DE2EC6E52204201C36', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4803, 200, 20300668, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。积之始生。至其已成。奈何。岐伯曰。积之始生。得寒乃生。厥乃成积也。黄帝曰。其成积奈何。岐伯曰。厥气生足悗。悗生胫寒。胫寒则血脉凝涩。血脉凝涩则寒气上入于肠胃。入于肠胃则䐜胀。䐜胀则肠外之汁沫迫聚不得散。日以成积。卒然多食饮。则肠满。起居不节。用力过度。则络脉伤。阳络伤则血外溢。血外溢则衄血。阴络伤则血内溢。血内溢则后血。肠胃之络伤则血溢于肠外。肠外有寒。汁沫与血相搏。则并合凝聚不得散。而积成矣。卒然中外于寒。若内伤于忧怒。则气上逆。气上逆则六俞不通。温气不行。凝血蕴里而不散。津液涩渗。着而不去。而积皆成矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218189385, '5B55ECCDC2ABCE9D139BDFF0EBE3BF78', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4804, 200, 20300669, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。其生于阴者。奈何。岐伯曰。忧思伤心。重寒伤肺。忿怒伤肝。醉以入房。汗出当风伤脾。用力过度。若入房汗出浴。则伤肾。此内外三部之所生病者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218189386, '203AC1CF340578C60DA7617566D8F621', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4805, 200, 20300670, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。善治之奈何。岐伯答曰。察其所痛。以知其应。有余不足。当补则补。当泻则泻。毋逆天时。是谓至治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218189387, 'F7015C7778F7CFB4CACCAAF12A28AAF9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4806, 201, 20300671, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余闻九针于夫子。而行之于百姓。百姓之血气。各不同形。或神动而气先针行。或气与针相逢。或针已出。气独行。或数刺乃知。或发针而气逆。或数刺病益剧。凡此六者。各不同形。愿闻其方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218414661, '4343E1DB2801E7ADAA9E9F3A59167F4B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4807, 201, 20300672, NULL, NULL, '', NULL, NULL, NULL, '2、岐伯曰。重阳之人。其神易动。其气易往也。黄帝曰。何谓重阳之人。岐伯曰。重阳之人。熇熇高高。言语善疾。举足善高。心肺之藏气有余。阳气滑盛而扬。故神动而气先行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218414662, '77F2F645B5915702CE9C95ED0376B096', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4808, 201, 20300673, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。重阳之人而神不先行者。何也。岐伯曰。此人颇有阴者也。黄帝曰。何以知其颇有阴者也。岐伯曰。多阳者。多喜。多阴者。多怒。数怒者。易解。故曰颇有阴。其阴阳之离合难。故其神不能先行也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218414663, 'FAEBD824147F4EB52C72A2D67773E3A4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4809, 201, 20300674, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。其气与针相逢。奈何。岐伯曰。阴阳和调。而血气淖泽滑利。故针入而气出。疾而相逢也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218414664, '814349B34796BEE791D6D7D5C3D818BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4810, 201, 20300675, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。针已出而气独行者。何气使然。岐伯曰。其阴气多而阳气少。阴气沉而阳气浮者内藏。故针已出。气乃随其后。故独行也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218414665, '55A3AB2B2F5A4F49AE62D7DFB0D049C3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4811, 201, 20300676, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。数刺乃知。何气使然。岐伯曰。此人之多阴而少阳。其气沉而气往难。故数刺乃知也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218414666, 'AC6BF587E73CF9B1EEBEBAA614471346', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4812, 201, 20300677, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。针入而气逆者。何气使然。岐伯曰。其气逆与其数刺病益甚者。非阴阳之气。浮沉之势也。此皆粗之所败。工之所失。其形气无过焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218414667, 'F90DAEE494CAFB5FD24E5E523510893D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4813, 202, 20300678, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。气为上膈者。食饮入而还出。余已知之矣。虫为下膈。下膈者。食焠时乃出。余未得其意。愿卒闻之。岐伯曰。喜怒不适。食饮不节。寒温不时。则寒汁流于肠中。流于肠中则虫寒。虫寒则积聚。守于下管。则肠胃充郭。卫气不营。邪气居之。人食则虫上食。虫上食则下管虚。下管虚则邪气胜之。积聚以留。留则痈成。痈成则下管约。其痈在管内者。即而痛深。其痈在外者。则痈外而痛浮。痈上皮热。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218635845, '5661B8D7A0E410EB2CB661FF31E8C162', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4814, 202, 20300679, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。刺之奈何。岐伯曰。微按其痈。视气所行。先浅刺其傍。稍内益深。逐而刺之。毋过三行。察其沈浮。以为深浅。已刺必熨。令热入中。日使热内。邪气益衰。大痈乃溃。伍以参禁。以除其内。恬憺无为。乃能行气。后以咸苦。化谷乃下矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218635846, '377ECD490B4737D810A0EC3B92357D3F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4815, 203, 20300680, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于少师曰。人之卒然忧恚。而言无音者。何道之塞。何气出行。使音不彰。愿闻其方。少师答曰。咽喉者。水谷之道也。喉咙者。气之所以上下者也。会厌者。声音之户也。口唇者。声音之扇也。舌者。声音之机也。悬壅垂者。声音之关者。颃颡者。分气之所泄也。横骨者。神气所使主发舌者也。故人之鼻洞涕出不收者。颃颡不开。分气失也。是故厌小而疾薄。则发气疾。其开阖利。其出气易。其厌大而厚。则开阖难。其气出迟。故重言也。人卒然无音者。寒气客于厌。则厌不能发。发不能下。至其开阖不致。故无音。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218873413, '724541C706B8097CA967C0FD012F2F54', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4816, 203, 20300681, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。刺之奈何。岐伯曰。足之少阴。上系于舌。络于横骨。终于会厌。两泻其血脉。浊气乃避。会厌之脉。上络任脉。取之天突。其厌乃发也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957218873414, 'B2315FF2C9A6B8701BAF95F676665868', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4817, 204, 20300682, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。寒热瘰疬在于颈腋者。皆何气使生。岐伯曰。此皆鼠瘘寒热之毒气也。留于脉而不去者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219078213, '7FD441EAB34C06D0183298A658274562', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4818, 204, 20300683, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。去之奈何。岐伯曰。鼠瘘之本。皆在于藏。其末上出于颈腋之间。其浮于脉中。而未内着于肌肉。而外为脓血者。易去也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219078214, 'EC2F9DE28B954719CF00D40D96D8077C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4819, 204, 20300684, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。去之奈何。岐伯曰。请从其本引其末。可使衰去。而绝其寒热。审按其道以予之。徐往徐来以去之。其小如麦者。一刺知。三刺而已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219078215, 'ADF01AE8616412009FB0ADFBCAF54B5E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4820, 204, 20300685, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。决其生死奈何。岐伯曰。反其目视之。其中有赤脉。上下贯瞳子。见一脉。一岁死。见一脉半。一岁半死。见二脉。二岁死。见二脉半。二岁半死。见三脉。三岁而死。见赤脉不下贯瞳子。可治也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219078216, '144F7C57A3C77987ACE682A489C4EF96', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4821, 205, 20300686, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于伯高曰。夫邪气之客人也。或令人目不瞑不卧出者。何气使然。伯高曰。五谷入于胃也。其糟粕津液宗气。分为三隧。故宗气积于胸中。出于喉咙。以贯心脉。而行呼吸焉。营气者。泌其津液。注之于脉。化以为血。以荣四末。内注五藏六府。以应刻数焉。卫气者。出其悍气之慓疾。而先行于四末分肉皮肤之间。而不休者也。昼日行于阳。夜行于阴。常从足少阴之分间。行五藏六府。今厥气客于五藏六府。则卫气独卫其外。行于阳。不得入于阴。行于阳则阳气盛。阳气盛则阳桥陷。不得入于阴。阴虚。故目不瞑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319877, '354ECBA1C2F64C4A166475480CDC5704', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4822, 205, 20300687, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。善。治之奈何。伯高曰。补其不足。泻其有余。调其虚实。以通其道。而去其邪。饮以半夏汤一剂。阴阳已通。其卧立至。黄帝曰。善。此所谓决渎壅塞。经络大通。阴阳和得者也。愿闻其方。伯高曰。其汤方以流水千里以外者八升。扬之万遍。取其清五升。煮之。炊以苇薪火。沸置秫米一升。治半夏五合。徐炊。令竭为一升半。去其滓。饮汁一小杯。日三稍益。以知为度。故其病新发者。复杯则卧。汗出则已矣。久者。三饮而已也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319878, '67C3646579AD70C4208E3589F8BA0E0C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4823, 205, 20300688, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝问于伯高曰。愿闻人之肢节以应天地奈何。伯高答曰。天圆地方。人头圆足方以应之。天有日月。人有两目。地有九州岛。人有九窍。天有风雨。人有喜怒。天有雷电。人有声音。天有四时。人有四肢。天有五音。人有五藏。天有六律。人有六府。天有冬夏。人有寒热。天有十曰。人有手十指。辰有十二。人有足十指。茎垂以应之。女子不足二节。以抱人形。天有阴阳。人有夫妻。岁有三百六十五日。人有三百六十五节。地有高山。人有肩膝。地有深谷。人有腋腘。地有十二经水。人有十二经脉。地有泉脉。人有卫气。地有草蓂。人有毫毛。天有昼夜。人有卧起。天有列星。人有牙齿。地有小山。人有小节。地有山石。人有高骨。地有林木。人有募筋。地有聚邑。人有腘肉。岁有十二月。人有十二节。地有四时不生草。人有无子。此人与天地相应者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319879, '316A533F8283A91095D2A1423FA4246A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:49', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4824, 205, 20300689, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝问于岐伯曰。余愿闻持针之数。内针之理。纵舍之意。扞皮开腠理。奈何。脉之屈折。出入之处。焉至而出。焉至而止。焉至而徐。焉至而疾。焉至而入。六府之输于身者。余愿尽闻其方。岐伯曰。帝之所问。针道毕矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319880, '235A2A3CEFD582005124447A29D05466', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4825, 205, 20300690, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。愿卒闻之。岐伯曰。手太阴之脉。出于大指之端。内屈。循白肉际。至本节之后太渊。留以澹。外屈。上于本节下。内屈。与阴诸络会于鱼际。数脉并注。其气滑利。伏行壅骨之下。外屈。出于寸口而行。上至于肘内廉。入于大筋之下。内屈。上行臑阴。入腋下。内屈。走肺。此顺行逆数之屈折也。心主之脉。出于中指之端。内屈。循中指内廉以上。留于掌中。伏行两骨之间。外屈。出两筋之间。上至肘内廉。入于小筋之下。留两骨之会。上入于胸中。内络于心脉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319881, '0FFB4C15C950360D4E465623BEFC8A41', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4826, 205, 20300691, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。手太阴之脉。独无俞。何也。岐伯曰。少阴。心脉也。心者。五藏六府之大主也。精神之所舍也。其藏坚固。邪弗能容也。容之则心伤。心伤则神去。神去则死矣。故诸邪之在于心者。皆在于心之包络。包络者。心主之脉也。故独无俞焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319882, 'F5F94B26C6C8D1F26111D2C872C1AB5D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4827, 205, 20300692, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。少阴独无俞者。不病乎。岐伯曰。其外经病而藏不病。故独取其经于掌后锐骨之端。其余脉出入屈折。其行之徐疾。皆如手少阴心主之脉行也。故本俞者。皆因其气之虚实疾徐以取之。是谓因冲而泻。因衰而补。如是者。邪气得去。真气坚固。是谓因天之序。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319883, 'DB26F3C8D22AAA6290080E84B2274BE4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4828, 205, 20300693, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。持针纵舍奈何。岐伯曰。必先明知十二经脉之本末。皮肤之寒热。脉之盛衰滑涩。其脉滑而盛者。病日进。虚而细者。久以持。大以涩者。为痛痹。阴阳如一者。病难治。其本末尚热者。病尚在。其热以衰者。其病亦去矣。持其尺。察其肉之坚脆。大小滑涩。寒温燥湿。因视目之五色。以知五藏。而决死生。视其血脉。察其色。以知其寒热痛痹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319884, '15B378745D0255306BCAD3DB41234C9F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4829, 205, 20300694, NULL, NULL, '', NULL, NULL, NULL, '9、黄帝曰。持针纵舍。余未得其意也。岐伯曰。持针之道。欲端以正。安以静。先知虚实而行疾徐。左手执骨。右手循之。无与肉果。泻欲端以正。补必闭肤。辅针导气。邪得淫泆。真气得居。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319885, 'D8F9693136577A2B6211FBBA8F810509', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4830, 205, 20300695, NULL, NULL, '', NULL, NULL, NULL, '10、黄帝曰。扞皮开腠理奈何。岐伯曰。因其分肉。左别其肤。微内而徐端之。适神不散。邪气得去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319886, 'B03C0A2C392B7EDCB452F20E78B2E1F0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4831, 205, 20300696, NULL, NULL, '', NULL, NULL, NULL, '11、黄帝问于岐伯曰。人有八虚。各何以候。岐伯答曰。以候五藏。黄帝曰。候之奈何。岐伯曰。肺心有邪。其气留于两肘。肝有邪。其气流于两腋。脾有邪。其气留于两髀。肾有邪。其气留于两腘。凡此八虚者。皆机关之室。真气之所过。血络之所游。邪气恶血。固不得住留。住留则伤筋络骨节。机关不得屈伸。故痀挛也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219319887, '1359592FCA6CF2F5E1A6BECC47887AEA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4832, 206, 20300697, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于少师曰。余尝闻人有阴阳。何谓阴人。何谓阳人。少师曰。天地之间。六合之内。不离于五。人亦应之。非徒一阴一阳而已也。而略言耳。口弗能遍明也。黄帝曰。愿略闻其意。有贤人圣人。心能备而行之乎。少师曰。盖有太阴之人。少阴之人。太阳之人。少阳之人。阴阳和平之人。凡五人者。其态不同。其筋骨气血各不等。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565637, '531C738D479FC67364F02AAD4B431382', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4833, 206, 20300698, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。其不等者。可得闻乎。少师曰。太阴之人。贪而不仁。下齐湛湛。好内而恶出。心和而不发。不务于时。动而后之。此太阴之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565638, '72C3301B35F3964BCF83034BE353107B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4834, 206, 20300699, NULL, NULL, '', NULL, NULL, NULL, '3、少阴之人。小贪而贼心。见人有亡。常若有得。好伤好害。见人有荣。乃反愠怒。心疾而无恩。此少阴之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565639, '3D1D772BD2814F79065F9713178CC01D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4835, 206, 20300700, NULL, NULL, '', NULL, NULL, NULL, '4、太阳之人。居处于于。好言大事。无能而虚说。志发乎四野。举措不顾是非。为事如常自用。事虽败。而常无悔。此太阳之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565640, 'AE9DC1C9917B742AFE5B9AE14C56970B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4836, 206, 20300701, NULL, NULL, '', NULL, NULL, NULL, '5、少阳之人。諟谛好自责。有小小官。则高自宜。好为外交。而不内附。此少阳之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565641, 'A2E57FC1AD3BC43E65D11C104EEC7853', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4837, 206, 20300702, NULL, NULL, '', NULL, NULL, NULL, '6、阴阳和平之人。居处安静。无为惧惧。无为欣欣。婉然从物。或与不争。与时变化。尊则谦谦。谭而不治。是谓至治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565642, '893AD8E8DA60C4AC8B48D3582C66487C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4838, 206, 20300703, NULL, NULL, '', NULL, NULL, NULL, '7、古之善用针艾者。视人五态。乃治之。盛者泻之。虚者补之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565643, '2C93AB0D43A5D33A4396269BC30E6592', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4839, 206, 20300704, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。治人之五态奈何。少师曰。太阴之人。多阴而无阳。其阴血浊。其卫气涩。阴阳不和。缓筋而厚皮。不之疾泻。不能移之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565644, '6988E82503AC9F3F166B6A9FC61A27F9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4840, 206, 20300705, NULL, NULL, '', NULL, NULL, NULL, '9、少阴之人。多阴少阳。小胃而大肠。六府不调。其阳明脉小。而太阳脉大。必审调之。其血易脱。其气易败也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565645, '3C0430055D6448E11234064D346C6D29', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4841, 206, 20300706, NULL, NULL, '', NULL, NULL, NULL, '10、太阳之人。多阳而少阴。必谨调之。无脱其阴。而泻其阳。阳重脱者易狂。阴阳皆脱者。暴死。不知人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565646, '509BF61CB3C282F80BB64857321B9B7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4842, 206, 20300707, NULL, NULL, '', NULL, NULL, NULL, '11、少阳之人。多阳少阴。经小而络大。血在中而气外。实阴而虚阳。独泻其络脉。则强气脱而疾。中气不足。病不起也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565647, '5C97BBB2E30C0F6995AD044FDE0F3FDF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4843, 206, 20300708, NULL, NULL, '', NULL, NULL, NULL, '12、阴阳和平之人。其阴阳之气和。血脉调。谨诊其阴阳。视其邪正。安容仪。审有余不足。盛则泻之。虚则补之。不盛不虚。以经取之。此所以调阴阳。别五态之人者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565648, '8AEF1F0E6D022B8091F5718D21536FC1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4844, 206, 20300709, NULL, NULL, '', NULL, NULL, NULL, '13、黄帝曰。夫五态之人者。相与毋故。卒然新会。未知其行也。何以别之。少师答曰。众人之属。不知五态之人者。故五五二十五人。而五态之人不与焉。五态之人。尤不合于众者也。黄帝曰。别五态之人。奈何。少师曰。太阴之人。其状黮黮然黑色。念然下意。临临然长大。腘然未偻。此太阴之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565649, 'F2F07CCA84E057050FA22DF5A5D25845', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4845, 206, 20300710, NULL, NULL, '', NULL, NULL, NULL, '14、少阴之人。其状清然窃然。固以阴贼。立而躁崄。行而似伏。此少阴之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565650, '19575C9399845B0D1C06E7369FEB244E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4846, 206, 20300711, NULL, NULL, '', NULL, NULL, NULL, '15、太阳之人。其状轩轩储储。反身折腘。此太阳之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565651, '3076E6635D08B39B92D2980F10196F7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4847, 206, 20300712, NULL, NULL, '', NULL, NULL, NULL, '16、少阳之人。其状立则好仰。行则好摇。其两臂两肘。则常出于背。此少阳之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565652, 'F7EFA9DA816450FCAC2584F7927F3811', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4848, 206, 20300713, NULL, NULL, '', NULL, NULL, NULL, '17、阴阳和平之人。其状委委然。随随然。颙颙然。愉愉然。䁢䁢然。豆豆然。众人皆曰君子。此阴阳和平之人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219565653, '8448CF4852871E212700A7AC7BE1AE7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4849, 207, 20300714, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余闻九针于夫子。众多矣不可胜数。余推而论之。以为一纪。余司诵之。子听其理。非则语余。请正其道。令可久传后世无患。得其人乃传。非其人勿言。岐伯稽首再拜曰。请听圣王之道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790917, 'E37BCA41F7DC3AFABCDBA3E4B214D026', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4850, 207, 20300715, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。用针之理。必知形气之所在。左右上下。阴阳表里。血气多少。行之逆顺。出入之合。谋伐有过。知解结。知补虚泻实。上下气门。明通于四海。审其所在。寒热淋露以输异处。审于调气。明于经隧。左右肢络。尽知其会。寒与热争。能合而调之。虚与实邻。知决而通之。左右不调。把而行之。明于逆顺。乃知可治。阴阳不奇。故知起时。审于本末。察其寒热。得邪所在。万刺不殆。知官九针。刺道毕矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790918, '123FC016AE6C6F66957C3CAC23B42AB7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4851, 207, 20300716, NULL, NULL, '', NULL, NULL, NULL, '3、明于五俞徐疾所在。屈伸出入。皆有条理。言阴与阳。合于五行。五藏六府。亦有所藏。四时八风。尽有阴阳。各得其位。合于明堂。各处色部。五藏六府。察其所痛。左右上下。知其寒温。何经所在。审皮肤之寒温滑涩。知其所苦。膈有上下。知其气所在。先得其道。稀而疏之。稍深以留。故能徐入之。大热在上。推而下之。从上下者。引而去之。视前痛者。常先取之。大寒在外。留而补之。入于中者。从合泻之。针所不为。灸之所宜。上气不足。推而扬之。下气不足。积而从之。阴阳皆虚。火自当之。厥而寒甚。骨廉陷下。寒过于膝。下陵三里。阴络所过。得之留止。寒入于中。推而行之。经陷下者。火则当之。结络坚紧。火所治之。不知所苦。两蹻之下。男阴女阳。良工所禁。针论毕矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790919, '829815E01912CC0C64E6EC575234F5F7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4852, 207, 20300717, NULL, NULL, '', NULL, NULL, NULL, '4、用针之服。必有法则。上视天光。下司八正。以辟奇邪。而观百姓。审于虚实。无犯其邪。是得天之灵。遇岁之虚。救而不胜。反受其殃。故曰必知天忌。乃言针意。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790920, '5C072194B838B3B00CF98CE07DB6E843', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4853, 207, 20300718, NULL, NULL, '', NULL, NULL, NULL, '5、法于往古。验于来今。观于窈冥。通于无穷。粗之所不见。良工之所贵。莫知其形。若神髣佛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790921, '80E3A4DCDA36B2EA4E0FEF078393B4E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4854, 207, 20300719, NULL, NULL, '', NULL, NULL, NULL, '6、邪气之中人也。洒淅动形。正邪之中人也。微先见于色。不知于其身。若有若无。若亡若存。有形无形。莫知其情。是故上工之取气。乃救其萌芽。下工守其已成。因败其形。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790922, '2F2CAA345F7EAAC02C26B859CD8F5604', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4855, 207, 20300720, NULL, NULL, '', NULL, NULL, NULL, '7、是故工之用针也。知气之所在。而守其门户。明于调气。补泻所在。徐疾之意。所取之处。泻必用员。切而转之。其气乃行。疾而徐出。邪气乃出。伸而迎之。遥大其穴。气出乃疾。补必用方。外引其皮。令当其门。左引其枢。右推其肤。微旋而徐推之。必端以正。安以静。坚心无解。欲微以留。气下而疾出之。推其皮。盖其外门。真气乃存。用针之要。无忘其神。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790923, '91E27D9C4340BD232EAFF52636A4011C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4856, 207, 20300721, NULL, NULL, '', NULL, NULL, NULL, '8、雷公问于黄帝曰。针论曰。得其人乃传。非其人勿言。何以知其可传。黄帝曰。各得其人。任之其能。故能明其事。雷公曰。愿闻官能奈何。黄帝曰。明目者。可使视色。聪耳者。可使听音。捷疾辞语者。可使传论。语徐而安静。手巧而心审谛者。可使行针艾。理血气而调诸逆顺。察阴阳而兼诸方。缓节柔筋而心和调者。可使导引行气。疾毒言语轻人者。可使唾痈呪病。爪苦手毒。为事善伤者。可使按积抑痹。各得其能。方乃可行。其名乃彰。不得其人。其功不成。其师无名。故曰。得其人乃言。非其人勿传。此之谓也。手毒者。可使试按龟。置龟于器下。而按其上。五十日而死矣。手甘者。复生如故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957219790924, 'B6B071DE8FFE8A908666E7E92F7A30AE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4857, 208, 20300722, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问岐伯曰。余欲无视色持脉。独调其尺。以言其病。从外知内。为之奈何。岐伯曰。审其尺之缓急小大滑涩。肉之坚脆。而病形定矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032581, 'B60B92012DB412635FC2B3DC95B9079B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4858, 208, 20300723, NULL, NULL, '', NULL, NULL, NULL, '2、视人之目窠上微痈。如新卧起状。其颈脉动。时咳。按其手足上。窅而不起者。风水肤胀也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032582, '84A829C170951BEBE01546F565529D94', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4859, 208, 20300724, NULL, NULL, '', NULL, NULL, NULL, '3、尺肤滑。其淖泽者。风也。尺肉弱者。解并。安卧脱肉者。寒热。不治。尺肤滑而泽脂者。风也。尺肤涩者。风痹也。尺肤粗如枯鱼之鳞者。水泆饮也。尺肤热甚。脉盛躁者。病温也。其脉甚而滑者。病且出也。尺肤寒。其脉小者。泄。少气。尺肤炬然。先热后寒者。寒热也。尺肤先寒。久大之而热者。亦寒热也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032583, 'D8F431F9DFBA8B1E26B7E5EB91F8DB97', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4860, 208, 20300725, NULL, NULL, '', NULL, NULL, NULL, '4、肘所独热者。腰以上热。手所独热者。腰以下热。肘前独热者。膺前热。肘后独热者。肩背热。臂中独热者。腰腹热。肘后粗以下三四寸热者。肠中有虫。掌中热者。腹中热。掌中寒者。腹中寒。鱼上白肉有青血脉者。胃中有寒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032584, '4396F43E13F8B9EBCB015BA8881A3526', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4861, 208, 20300726, NULL, NULL, '', NULL, NULL, NULL, '5、尺炬然热。人迎大者。当本血。尺坚大。脉小甚。少气。免有加。立死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032585, '7B12F8CFAA2DE57F2C278178B9FCEA2B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4862, 208, 20300727, NULL, NULL, '', NULL, NULL, NULL, '6、目赤色者病在心。白在肺。青在肝。黄在脾。黑在肾。黄色不可名者。病在胸中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032586, 'F49E7BB327E70C8C443EF88A30284749', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4863, 208, 20300728, NULL, NULL, '', NULL, NULL, NULL, '7、诊目痛。赤脉从上下者。太阳病。从下上者。阳明病。从外走内者。少阳病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032587, '2F1654CB3BBCB35DBECA8C8E5BF25ABB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4864, 208, 20300729, NULL, NULL, '', NULL, NULL, NULL, '8、诊寒热。赤脉上下至瞳子。见一脉一岁死。见一脉半。一岁半死。见二脉。二岁死。见二脉半。二岁半死。见三脉。三岁死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032588, '027D6DDBDC4D934D5C331186BB17CD8C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4865, 208, 20300730, NULL, NULL, '', NULL, NULL, NULL, '9、诊龋齿痛。按其阳之来。有过者独热。在左左热。在右右热。在上上热。在下下热。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032589, '833E24526D000A9174B7C3D10313EE51', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4866, 208, 20300731, NULL, NULL, '', NULL, NULL, NULL, '10、诊血脉者。多赤多热。多青多痛。多黑为久痹。多赤。多黑。多青皆见者。寒热。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032590, '1AC67CC1566730CD2BEC2C5595010E52', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4867, 208, 20300732, NULL, NULL, '', NULL, NULL, NULL, '11、身痛而色微黄。齿垢黄。爪甲上黄。黄疸也。安卧小便黄赤。脉小而涩者不嗜食。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032591, 'B02F587B7433E4BDBE686899FF224955', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4868, 208, 20300733, NULL, NULL, '', NULL, NULL, NULL, '12、人病。其寸口之脉。与人迎之脉小大等。及其浮沉等者。病难已也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032592, '456D6821F4E5569B4945E2112910A32E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4869, 208, 20300734, NULL, NULL, '', NULL, NULL, NULL, '13、女子手少阴脉动甚者妊子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032593, 'C607F0982D9FD2026E6E4D99563303D4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4870, 208, 20300735, NULL, NULL, '', NULL, NULL, NULL, '14、婴儿病。其头毛皆逆上者必死。耳间青脉起者掣痛。大便赤瓣飧泄。脉小者。手足寒。难已。飧泄。脉小。手足温。泄易也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032594, '0EC47174899C43686018D8D21F288273', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4871, 208, 20300736, NULL, NULL, '', NULL, NULL, NULL, '15、四时之变。寒暑之胜。重阴必阳。重阳必阴。故阴主寒。阳主热。故寒甚则热。热甚则寒。故曰寒生热。热生寒。此阴阳之变也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032595, '2759E7BDFEF5352B69E87C155E574C63', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4872, 208, 20300737, NULL, NULL, '', NULL, NULL, NULL, '16、故曰。冬伤于寒。春生病热。春伤于风。夏生飧泄肠僻。夏伤于暑。秋生疟。秋伤于湿。冬生咳嗽。是谓四时之序也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220032596, '0188FC1C439F9F71933E3018AA879323', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4873, 209, 20300738, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余闻刺有五卫。奈何。岐伯曰。固有五卫。一曰振埃。二曰发蒙。三曰去爪。四曰彻衣。五曰解惑。黄帝曰。夫子言五卫。余未知其意。岐伯曰。振埃者。刺外经去阳病也。发蒙者。刺府俞。去府病也。去爪者。刺关节肢络也。彻衣者。尽刺诸阳之奇俞也。解惑者。尽知调阴阳。补泻有余不足。相倾移也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253765, '3F3548578DE37B4F2E4B74AC5F5B6A42', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4874, 209, 20300739, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。刺卫言振埃。夫子乃言刺外经。去阳病。余不知其所谓也。愿卒闻之。岐伯曰。振埃者。阳气大逆。上满于胸中。愤瞋肩息。大气逆上。喘喝坐伏。病恶埃烟。饲不得息。请言振埃。尚疾于振埃。黄帝曰。善。取之何如。岐伯曰。取之天容。黄帝曰。其咳上气穷拙胸痛者。取之奈何。岐伯曰。取之廉泉。黄帝曰。取之有数乎。岐伯曰。取天容者。无过一里。取廉泉者。血变而止。帝曰。善哉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253766, 'F6DF5928E5CDEAD248CEBDEE35439F0D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4875, 209, 20300740, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。刺卫言发蒙。余不得其意。夫发蒙者。耳无所闻。目无所见。夫子乃言刺府俞。去府病。何输使然。愿闻其故。岐伯曰。妙乎哉问也。此刺之大约。针之极也。神明之类也。口说书卷。犹不能及也。请言发蒙耳。尚疾于发蒙也。黄帝曰。善。愿卒闻之。岐伯曰。刺此者。必于日中。刺其听宫。中其眸子。声闻于耳。此其输也。黄帝曰。善。何谓声闻于耳。岐伯曰。刺邪以手坚按其两鼻窍。而疾偃其声。必应于针也。黄帝曰。善。此所谓弗见为之。而无目视。见而取之。神明相得者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253767, '02B33FBD0A1A05C7F46C75C03F762EC3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4876, 209, 20300741, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。刺卫言去爪。夫子乃言刺关节肢络。愿卒闻之。岐伯曰。腰脊者。身之大关节也。肢胫者。人之管以趋翔也。茎垂者。身中之机。阴精之候。津液之道也。故饮食不节。喜怒不时。津液内溢。乃下留于睪。血道不通。日大不休。俛仰不便。趋翔不能。此病荣然有水。不上不下。铍石所取。形不可匿。常不得蔽。故命曰去爪。帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253768, '2E52F6D177746C187475EB8CAD1B8692', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4877, 209, 20300742, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。刺卫言彻衣。夫子乃言尽刺诸阳之奇俞。未有常处也。愿卒闻之。岐伯曰。是阳气有余。而阴气不足。阴气不足则内热。阳气有余则外热。内热相搏。热于怀炭。外畏绵帛近。不可近身。又不可近席。腠理闭塞。则汗不出。舌焦唇槁。腊干益燥。饮食不让美恶。黄帝曰。善。取之奈何。岐伯曰。取之于其天府大杼三痕。又刺中膂。以去其热。补足手太阴。以去其汗。热去汗稀。疾于彻衣。黄帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253769, '2BB6D4009A30E6BE3E842A61D6AB0763', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4878, 209, 20300743, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。刺卫言解惑。夫子乃言尽知调阴阳。补泻有余不足。相倾移也。惑何以解之。岐伯曰。大风在身。血脉偏虚。虚者不足。实者有余。轻重不得。倾侧宛伏。不知东西。不知南北。乍上乍下。乍反乍复。颠倒无常。甚于迷惑。黄帝曰。善。取之奈何。岐伯曰。泻其有余。补其不足。阴阳平复。用针若此。疾于解惑。黄帝曰。善。请藏之灵兰之室。不敢妄出也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253770, 'FC33B46959994A668AD8CDAF074765DC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4879, 209, 20300744, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。余闻刺有五邪。何谓五邪。岐伯曰。病有持痈者。有容大者。有狭小者。有热者。有寒者。是谓五邪。黄帝曰。刺五邪奈何。岐伯曰。凡刺五邪之方。不过五章。瘅热消灭。肿聚散亡。寒痹益温。小者益阳。大者必去。请道其方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253771, '8E7F88C331F18F91472FC40FCA70C7CB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4880, 209, 20300745, NULL, NULL, '', NULL, NULL, NULL, '8、凡刺痈邪。无迎陇。易俗移性。不得脓。脆道更行。去其乡。不安处所乃散亡。诸阴阳过痈者。取之其输泻之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253772, '7A2B0F2BEBCFDAADA76B5116DD1E4B38', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4881, 209, 20300746, NULL, NULL, '', NULL, NULL, NULL, '9、凡刺大邪。日以小。泄夺其有余。乃益虚。剽其通。针其邪。肌肉亲视之。毋有反其真。刺诸阳分肉间。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253773, '6221ECCCB2F2B214AC04529DC3C8F063', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4882, 209, 20300747, NULL, NULL, '', NULL, NULL, NULL, '10、凡刺小邪。日以大。补其不足。乃无害。视其所在。迎之界。远近尽至。其不得外侵而行之。乃自费。刺分肉间。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253774, 'F5E4A94AA4AA278F9B36DEDC9257F9C8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4883, 209, 20300748, NULL, NULL, '', NULL, NULL, NULL, '11、凡刺热邪。越而苍。出游不归。乃无病。为开通。辟门户。使邪得出。病乃已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253775, 'D947CF5FBBEA91689DA6E8032C283D88', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4884, 209, 20300749, NULL, NULL, '', NULL, NULL, NULL, '12、凡刺寒邪。日以温。徐往徐来。致其神。门户已闭。气不分。虚实得调。其气存也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253776, '1DACB08818BC5DC6AC7FA2631A513BDA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4885, 209, 20300750, NULL, NULL, '', NULL, NULL, NULL, '13、黄帝曰。官针奈何。岐伯曰。刺痈者。用铍针。刺大者。用锋针。刺小者。用员利针。刺热者。用纔针。刺寒者。用毫针也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253777, 'E960C95A8BD2E21FB38C0E7F7F1D7D94', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4886, 209, 20300751, NULL, NULL, '', NULL, NULL, NULL, '14、请言解论。与天地相应。与四时相副。人参天地。故可为解。下有渐洳。上生苇蒲。此所以知形气之多少也。阴阳者。寒暑也。热则滋雨而在上。根茎少汁。人气在外。皮肤缓。腠理开。血气减。汗大泄。皮淖泽。寒则地冻水冰。人气在中。皮肤致。腠理闭。汗不出。血气强。肉坚涩。当是之时。善行水者。不能往冰。善穿地者。不能击冻。善用针者。亦不能取四厥。血脉凝结。坚搏不往来者。亦未可即柔。故行水者。必待天温。冰释冻解。而水可行。地可穿也。人脉犹是也。治厥者。必先熨调和其经。掌与腋。肘与脚。项与脊以调之。火气已通。血脉乃行。然后视其病。脉淖泽者。刺而平之。坚紧者。破而散之。气下乃止。此所谓以解结者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253778, '8D4F65A5329006C6CDFCBD6AFADB516B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4887, 209, 20300752, NULL, NULL, '', NULL, NULL, NULL, '15、用针之类。在于调气。气积于胃。以通营卫。各行其道。宗气留于海。其下者。注于气街。其上者。走于息道。故厥在于足。宗气不下。脉中之血。凝而留止。弗之火调。弗能取之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253779, 'C52A4A5951FF1E6E372BB45FAA916621', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4888, 209, 20300753, NULL, NULL, '', NULL, NULL, NULL, '16、用针者。必先察其经络之实虚。切而循之。按而弹之。视其应动者。乃后取之而下之。六经调者。谓之不病。虽病。谓之自已也。一经上实下虚而不通者。此必有横络盛加于大经。令之不通。视而泻之。此所谓解结也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253780, '6009864B04D6CD8832CFD8165BEF7DF0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4889, 209, 20300754, NULL, NULL, '', NULL, NULL, NULL, '17、上寒下热。先刺其项太阳。久留之。已刺则熨项与肩胛。令热下合乃止。此所谓推而上之者也。上热下寒。视其虚脉而陷之于经络者。取之。气下乃止。此所谓引而下之者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253781, 'C962F15535B45ABDBFD1381EFCB3647F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4890, 209, 20300755, NULL, NULL, '', NULL, NULL, NULL, '18、大热遍身。狂而妄见妄闻妄言。视足阳明及大络取之。虚者补之。血而实者泻之。因其偃卧。居其头前。以两手四指挟按颈动脉。久持之。卷而切。推下至缺盆中。而复止如前。热去乃止。此所谓推而散之者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253782, 'E89AE22C440DC5628F1E6E9CF496EAEE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4891, 209, 20300756, NULL, NULL, '', NULL, NULL, NULL, '19、黄帝曰。有一脉生数十病者。或痛。或痈。或热。或寒。或痒。或痹。或不仁。变化无穷。其故何也。岐伯曰。此皆邪气之所生也。黄帝曰。余闻气者。有真气。有正气。有邪气。何谓真气。岐伯曰。真气者。所受于天。与谷气并而充身也。正气者。正风也。从一方来。非实风。又非虚风也。邪气者。虚风之贼伤人也。其中人也深。不能自去。正风者。其中人也浅。合而自去。其气来柔弱。不能胜真气。故自去。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253783, '8C865D5D29031F2738C81A07E90A41B4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4892, 209, 20300757, NULL, NULL, '', NULL, NULL, NULL, '20、虚邪之中人也。洒晰动形。起毫毛而发腠理。其入深。内搏于骨。则为骨痹。搏于筋。则为筋挛。搏于脉中。则为血闭。不通则为痈。搏于肉。与卫气相搏。阳胜者。则为热。阴胜者。则为寒。寒则真气去。去则虚。虚则寒搏于皮肤之间。其气外发。腠理开。毫毛摇。气往来行。则为痒。留而不去。则痹。卫气不行。则为不仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253784, '6AFF85599DFEE1ABE23B9783DB564D2F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4893, 209, 20300758, NULL, NULL, '', NULL, NULL, NULL, '21、虚邪偏容于身半。其入深。内居荣卫。荣卫稍衰。则真气去。邪气独留。发为偏枯。其邪气浅者。脉偏痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253785, 'B8114FFBA2D8D02CEA69BE7554A5C4A7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4894, 209, 20300759, NULL, NULL, '', NULL, NULL, NULL, '22、虚邪之入于身也深。寒与热相搏。久留而内着。寒胜其热。则骨疼肉枯。热胜其寒。则烂肉腐肌为脓。内伤骨。内伤骨为骨蚀。有所疾前筋。筋屈不得伸。邪气居其间而不反。发为筋溜。有所结。气归之。卫气留之。不得反。津液久留。合而为肠溜。久者。数岁乃成。以手按之柔。已有所结。气归之。津液留之。邪气中之。凝结日以易甚。连以聚居。为昔瘤。以手按之坚。有所结。深中骨。气因于骨。骨与气并。日以益大。则为骨疽。有所结。中于肉。宗气归之。邪留而不去。有热则化而为脓。无热则为肉疽。凡此数气者。其发无常处。而有常名也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220253786, '4F82B603E962676CC67D419E104F6A8D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4895, 210, 20300760, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。愿闻卫气之行。出入之合。何如。岐伯曰。岁有十二月。日有十二辰。子午为经。卯酉为纬。天周二十八宿。而一面七星。四七二十八星。房昴为纬。虚张为经。是故房至毕为阳。昴至心为阴。阳主昼。阴主夜。故卫气之行。一日一夜五十周于身。昼日行于阳二十五周。夜行于阴二十五周。周于五藏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220491333, '32E9322A8067D6B48FC390CD79338B54', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4896, 210, 20300761, NULL, NULL, '', NULL, NULL, NULL, '2、是故平旦阴尽。阳气出于目。目张则气上行于头。循项下足太阳。循背下至小指之端。其散者。别于目锐眦。下手太阳。下至手小指之间外侧。其散者。别于目锐眦。下足少阳。注小指次指之间。以上循手少阳之分侧。下至小指之间。别者以上至耳前。合于颔脉。注足阳明以下行。至跗上。入五指之间。其散者。从耳下下手阳明。入大指之间。入掌中。其至于足也。入足心。出内踝。下行阴分。复合于目。故为一周。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220491334, 'B0DCD18FAF2BD3D591751EA7E22BD20F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4897, 210, 20300762, NULL, NULL, '', NULL, NULL, NULL, '3、是故日行一舍。人气行一周与十分身之八。日行二舍。人气行三周于身与十分身之六。日行三舍。人气行于身五周与十分身之四。日行四舍。人气行于身七周与十分身之二。日行五舍。人气行于身九周。日行六舍。人气行于身十周与十分身之八。日行七舍。人气行于身十二周在身与十分身之六。日行十四舍。人气二十五周于身有奇分与十分身之二。阳尽于阴。阴受气矣。其始入于阴。常从足少阴注于肾。肾注于心。心注于肺。肺注于肝。肝注于脾。脾复注于肾为周。是故夜行一舍。人气行于阴藏一周与十分藏之八。亦如阳行之二十五周。而复合于目。阴阳一日一夜。合有奇分十分身之四。与十分藏之二。是故人之所以卧起之时。有早晏者。奇分不尽故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220491335, '8F99CB138900474A9AF719E023169C24', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4898, 210, 20300763, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。卫气之在于身也。上下往来不以期。候气而刺之。奈何。伯高曰。分有多少。日有长短。春秋冬夏。各有分理。然后常以平旦为纪。以夜尽为始。是故一日一夜。水下百刻。二十五刻者。半日之度也。常如是毋已。日入而止。随日之长短。各以为纪而刺之。谨候其时。病可与期。失时反候者。百病不治。故曰。刺实者。刺其来也。刺虚者。刺其去也。此言气存亡之时。以候虚实而刺之。是故谨候气之所在而刺之。是谓逢时。在于三阳。必候其气在于阳而刺之。病在于三阴。必候其气在阴分而刺之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220491336, '0FBFA1BE956932F72BB60953D33A22C0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4899, 210, 20300764, NULL, NULL, '', NULL, NULL, NULL, '5、水下一刻。人气在太阳。水下二刻。人气在少阳。水下三刻。人气在阳明。水下四刻。人气在阴分。水下五刻。人气在太阳。水下六刻。人气在少阳。水下七刻。人气在阳明。水下八刻。人气在阴分。水下九刻。人气在太阳。水下十刻。人气在少阳。水下十一刻。人气在阳明。水下十二刻。人气在阴分。水下十三刻。人气在太阳。水下十四刻。人气在少阳。水下十五刻。人气在阳明。水下十六刻。人气在阴分。水下十七刻。人气在太阳。水下十八刻。人气在少阳。水下十九刻。人气在阳明。水下二十刻。人气在阴分。水下二十一刻。人气在太阳。水下二十二刻。人气在少阳。水下二十三刻。人气在阳明。水下二十四刻。人气在阴分。水下二十五刻。人气在太阳。此半日之度也。从房至毕一十四舍水下五十刻。日行半度。回行一舍。水下三刻与七分刻之四。大要曰。常以日之加于宿上也。人气在太阳。是故日行一舍。人气行三阳行与阴分。常如是无已。天与地同纪。纷纷纷纷。终而复始。一日一夜水下百刻而尽矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220491337, 'D4A498783F6FBC8BA557F5F32A66D289', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4900, 211, 20300765, NULL, NULL, '', NULL, NULL, NULL, '1、太一常以冬至之日。居叶蛰之宫四十六日。明日居天留四十六日。明日居仓门四十六日。明日居阴洛四十五日。明日居天宫四十六日。明日居玄委四十六日。明日居仓果四十六日。明日居新洛四十五日。明日复居叶蛰之宫。曰冬至矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220724805, '241D94F3804520FB29BCD0BFF8D805D2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4901, 211, 20300766, NULL, NULL, '', NULL, NULL, NULL, '2、太一日游。以冬至之日。居叶蛰之宫。数所在日。从一处至九日。复返于一。常如是无已。终而复始。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220724806, '664A83C7007DB591243C3F15A49FDE23', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4902, 211, 20300767, NULL, NULL, '', NULL, NULL, NULL, '3、太一移日。天必应之以风雨。以其日风雨则吉。岁美民安少病矣。先之则多雨。后之则多汗。太一在冬至之日有变。占在君。太一在春分之日有变。占在相。太一在中宫之日有变。占在吏。太一在秋分之日有变。占在将。太一在夏至之日有变。占在百姓。所谓有变者。太一居五宫之日。病风折树木。扬沙石。各以其所主。占贵贱。因视风所从来而占之。风从其所居之乡来为实风。主生。长养万物。从其冲后来为虚风。伤人者也。主杀。主害者。谨候虚风而避之。故圣人日避虚邪之道。如避矢石然。邪弗能害。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220724807, '3A77D6927DCCD0A91B5E54CF057529BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4903, 211, 20300768, NULL, NULL, '', NULL, NULL, NULL, '4、是故太一入徙立于中宫。乃朝八风。以占吉凶也。风从南方来。名曰大弱风。其伤人也。内舍于心。外在于脉。气主热。风从西南方来。名曰谋风。其伤人也。内舍于脾。外在于肌。其气主为弱。风从西方来。名曰刚风。其伤人也。内舍于肺。外在于皮肤。其气主为燥。风从西北方来。名曰折风。其伤人也。内舍于小肠。外在于手太阳脉。脉绝则溢。脉闭则结不通。善暴死。风从北方来。名曰大刚风。其伤人也。内舍于肾。外在于骨与肩背之膂筋。其气主为寒也。风从东北方来。名曰凶风。其伤人也。内舍于大肠。外在于两胁腋骨下及肢节。风从东方来。名曰婴兀风。其伤人也。内舍于肝。外在于筋纽。其气主为身湿。风从东南方来。名曰弱风。其伤人也。内舍于胃。外在肌肉。其气主体重。此八风皆从其虚之乡来。乃能病人。三虚相搏。则为暴病卒死。两实一虚。病则为淋露寒热。犯其两湿之地。则为痿。故圣人避风。如避矢石焉。其有三虚而偏中于邪风。则为仆偏枯矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220724808, '8B897DE48D0D90A66AE5A0FB16A9D72E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4904, 212, 20300769, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余闻九针于夫子。众多博大矣。余犹不能寤。敢问九针焉生。何因而有名。岐伯曰。九针者。天地之大数也。始于一而终于九。故曰。一以法天。二以法地。三以法人。四以法时。五以法音。六以法律。七以法星。八以法风。九以法野。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941893, '09F398A4AB5A14551CF1CFE0B63CE1D6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4905, 212, 20300770, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。以针应九之数。奈何。岐伯曰。夫圣人之起天地之数也。一而九之。故以立九野。九而九之。九九八十一。以起黄钟数焉。以针应数也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941894, '0586FB37AD6C2CD6968F86B0CEAD4ED5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4906, 212, 20300771, NULL, NULL, '', NULL, NULL, NULL, '3、一者。天也。天者。阳也。五藏之应天者肺。肺者。五藏六府之盖也。皮者。肺之合也。人之阳也。故为之治针。必以大其头而锐其末。令无得深入而阳气出。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941895, '7097260DAB20B67D36315D12DCBB353B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4907, 212, 20300772, NULL, NULL, '', NULL, NULL, NULL, '4、二者。地也。人之所以应土者。肉也。故为之治针。必筩其身而员其末。令无得伤肉分。伤则气得竭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941896, 'CA3B502AEB0B32DD5A8DC763F7948D68', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4908, 212, 20300773, NULL, NULL, '', NULL, NULL, NULL, '5、三者。人也。人之所以成生者。血脉也。故为之治针。必大其身而员其末。令可以按脉物陷。以致其气。令邪气独出。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941897, 'E5E78B888A76FEB6C880534CF1C12729', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4909, 212, 20300774, NULL, NULL, '', NULL, NULL, NULL, '6、四者。时也。时者。四时八风之客于经络之中。为瘤病者也。故为之治针。必筩其身而锋其末。令可以泻热出血。而痼病竭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941898, '7B795D963849153097A7BA3E4443C98A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4910, 212, 20300775, NULL, NULL, '', NULL, NULL, NULL, '7、五者。音也。音者。冬夏之分。分于子午。阴与阳别。寒与热争。两气相搏。合为痈脓者也。故为之治针。必令其末如剑锋。可以取大脓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941899, '2F19994479733D66709F98AA5067EA39', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4911, 212, 20300776, NULL, NULL, '', NULL, NULL, NULL, '8、六者。律也。律者。调阴阳四时而合十二经脉。虚邪客于经络而为暴痹者也。故为之治针。必令尖如厘。且员其锐。中身微大。以取暴气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941900, '07A89FDC59F6E9FF2D5496597BC14332', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4912, 212, 20300777, NULL, NULL, '', NULL, NULL, NULL, '9、七者。星也。星者。人之七窍。邪之所客于经。而为痛痹。合于经络者也。故为之治针。令尖如蚊虻喙。静以徐往。微以久留。正气因之。真邪俱往。出针而养者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941901, '56398D75FAEA21249BCB27E9C8312722', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4913, 212, 20300778, NULL, NULL, '', NULL, NULL, NULL, '10、八者。风也。风者。人之股肱八节也。八正之虚风。八风伤人。内舍于骨解腰脊节腠理之间为深痹也。故为之治针。必长其身。锋其末。可以取深邪远痹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941902, 'D9FB19C317396FBEB4A3E15A8B0C80B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4914, 212, 20300779, NULL, NULL, '', NULL, NULL, NULL, '11、九者。野也。野者。人之节解皮肤之间也。淫邪流溢于身。如风水之状。而留不能过于机关大节者也。故为之治针。令尖如挺。其锋微员。以取大气之不能过于关节者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941903, 'D2A6E519BD8DA737562B2CB06BC2D1B0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4915, 212, 20300780, NULL, NULL, '', NULL, NULL, NULL, '12、黄帝曰。针之长短有数乎。岐伯曰。一曰铁针者。取法于巾针。去末寸半。卒锐之。长一寸六分。主热在头身也。二曰员针。取法于絮针。其身而卵其锋。长一寸六分。主治分间气。三曰提针。取法于黍粟之锐。长三寸半。主按脉取气。令邪出。四曰锋针。取法于絮针。其身。锋其末。长一寸六分。主痈热出血。五曰铍针。取法于剑锋。广二分半。长四寸。主大痈脓。两热争者也。六曰员利针。取法于厘针。微大其末。反小其身。令可深内也。长一寸六分。主取痈痹者也。七曰毫针。取注于毫毛。长一寸六分。主寒热痛痹在络者也。八曰长针。取法于綦针。长七寸。主取深邪远痹者也。九曰大针。取法于锋针。其锋微员。长四寸。主取大气不出关节者也。针形毕矣。此九针大小长短法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941904, 'DE3011DC1497CF89F5C594F9DBF10530', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4916, 212, 20300781, NULL, NULL, '', NULL, NULL, NULL, '13、黄帝曰。愿闻身形。应九野。奈何。岐伯曰。请言身形之应九野也。左足应立春。其日戊寅己丑。左胁应春分。其日乙卯。左手应立夏。其日戊辰己巳。膺喉首头应夏至。其日丙午。右手应立秋。其中戊申己末。右胁应秋分。其日辛酉。右足应立冬。其日戊戌己亥。腰尻下窍应冬至。其日壬子。六府下三藏应中州。其大禁。大禁太一所在之日。及诸戊己。凡此九者。善候八正所在之处。所主左右上下身体有痈肿者。欲治之。无以其所直之日溃治之。是谓天忌日也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941905, 'F1F07AC540CD933BF307B2483310B699', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4917, 212, 20300782, NULL, NULL, '', NULL, NULL, NULL, '14、形东志苦。病生于脉。治之于灸刺。形苦志东。病生于筋。治之以熨引。形东志东。病生于肉。治之以针石。形苦志苦。病生于咽喝。治之以甘药。形数惊恐。筋脉不通。病生于不仁。治之以按摩谬药。是谓形。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941906, 'A55C0824154F1C57C1742D7AAAECCFC9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4918, 212, 20300783, NULL, NULL, '', NULL, NULL, NULL, '15、五藏气。心主噫。肺主咳。肝主语。脾主吞。肾主欠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941907, '2BFEE22A645F083046ED03403C9CA518', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4919, 212, 20300784, NULL, NULL, '', NULL, NULL, NULL, '16、六府气。胆为怒。胃为气逆秽。大肠小肠为泄。膀胱不约为遗溺。下焦溢为水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941908, '80F21BE84A7384B464D292063E140657', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4920, 212, 20300785, NULL, NULL, '', NULL, NULL, NULL, '17、五味。酸入肝。辛入肺。苦入心。甘入脾。咸入肾。淡入胃。是谓五味。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941909, '243DD1F99D22070AA452A66EAAF1D26E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4921, 212, 20300786, NULL, NULL, '', NULL, NULL, NULL, '18、五并。精气并肝则忧。并心则喜。并肺则悲。并肾则恐。并脾则畏。是谓五精之气。并于藏也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941910, '39700F122030EBB6C7A5E6C10F4C00D3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4922, 212, 20300787, NULL, NULL, '', NULL, NULL, NULL, '19、五恶。肝恶风。心恶热。肺恶寒。肾恶燥。脾恶湿。此五藏气所恶也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941911, 'AB00320F4E3E509A9173B4AA664B2D23', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4923, 212, 20300788, NULL, NULL, '', NULL, NULL, NULL, '20、五液。心主汗。肝主泣。肺主涕。肾主唾。脾主液。此五液所出也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941912, 'D312368AA45CF5EABCA4C6E8F485F17C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4924, 212, 20300789, NULL, NULL, '', NULL, NULL, NULL, '21、五劳。久视伤血。久卧伤气。久坐伤肉。久立伤骨。久行伤筋。此五久劳所病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941913, '9BF5C5DCB228D7D56487B34FD73ACB79', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4925, 212, 20300790, NULL, NULL, '', NULL, NULL, NULL, '22、五走。酸走筋。辛走气。苦走血。咸走骨。甘走肉。是谓五走也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941914, '299C79723D93B67200F4CF38189C22CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4926, 212, 20300791, NULL, NULL, '', NULL, NULL, NULL, '23、五裁。病在筋。无食酸。病在气。无食辛。病在骨。无食咸。病在血。无食苦。病在肉。无食甘。口嗜而欲食之。不可多也。必自裁也。命曰五裁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941915, 'CAE9AFCB1CE3F725DC2DEC77B32A00C1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4927, 212, 20300792, NULL, NULL, '', NULL, NULL, NULL, '24、五发。阴病发于骨。阳病发于血。阴病发于肉。阳病发于冬。阴病发于夏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941916, 'B4108B037C4435747A94BCD37EB3ADDF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4928, 212, 20300793, NULL, NULL, '', NULL, NULL, NULL, '25、五邪。邪入于阳。则为狂。邪入于阴。则为血瘅。邪入于阳。转则为癫疾。邪入于阴。转则为瘖。阳入于阴。病静。阴出之于阳。病喜怒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941917, 'FEA9B60C5C37909A4062448C75B572EF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4929, 212, 20300794, NULL, NULL, '', NULL, NULL, NULL, '26、五藏。心藏神。肺藏魄。肝藏魂。脾藏意。肾藏精志也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941918, '167D6EDA70B9B817399709D089ED8130', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4930, 212, 20300795, NULL, NULL, '', NULL, NULL, NULL, '27、五主。心主脉。肺主皮。肝主筋。脾主肌。肾主骨。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941919, 'ECFA529B6379AFD500F10CCFF90980CE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4931, 212, 20300796, NULL, NULL, '', NULL, NULL, NULL, '28、阳明多血多气。太阳多血少气。少阳多气少血。太阴多血少气。厥阴多血少气。少阴多气少血。故曰刺阳明出血气。刺太阳出血恶气。刺少阳出气恶血。刺太阴出血恶气。刺厥阴出血恶气。刺少阴出气恶血也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941920, '99FF16D12DF94B85A90BCEF50D89EC3F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4932, 212, 20300797, NULL, NULL, '', NULL, NULL, NULL, '29、足阳明太阴为里表。少阳厥阴为表里。太阳少阴为表里。是谓足之阴阳也。手阳明太阴为表里。少阳心主为表里。太阳少阴为表里。是谓手之阴阳也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957220941921, '4C9318DAF9F759D191DF7E0B681A98F8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4933, 213, 20300798, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。经言夏日伤暑。秋病疟。疟之发以时。其故何也。岐伯对曰。邪客于风府。病循膂而下。卫气一日一夜。常大会于风府。其明日日下一节。故其日作晏。此其先客于脊背也。故每至于风府则腠理开。腠理开则邪气入。邪气入则病作。此所以日作尚晏也。卫气之行风府。日下一节。二十一日下至尾底。二十二日入脊内。注于伏冲之脉。其行九日。出于缺盆之中。其气上行。故其病稍益至。其内搏于五藏。横连募原。其道远。其气深。其行迟。不能日作。故次日乃蓄积而作焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183557, 'AAC08B6F49BC7CC624C03C0598057934', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4934, 213, 20300799, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。卫气每至于风府。腠理乃发。发则邪入焉。其卫气日下一节。则不当风府。奈何。岐伯曰。风府无常。卫气之所应。必开其腠理。气之所舍节。则其府也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183558, 'D302A764D74AD19E792587D9FEB25FDD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4935, 213, 20300800, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。善。夫风之与疟也。相与同类。而风常在。而疟特以时休。何也。岐伯曰。风气留其处。疟气随经络。沉以内搏。故卫气应。乃作也。帝曰。善。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183559, '8055D18EB3F7D6C315B3C99D531EB6DD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4936, 213, 20300801, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝问于少师曰。余闻四时八风之中人也。故有寒暑。寒则皮肤急而腠理闭。暑则皮肤缓而腠理开。贼风邪气。因得以入乎。将必须八正虚邪。乃能伤人乎。少师答曰。不然。贼风邪气之中人也。不得以时。然必因其开也。其入深。其内极病。其病人也。卒暴。因其闭也。其入浅以留。其病也。徐以迟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183560, '293C576A1284AA99E98825AC314F3527', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4937, 213, 20300802, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。有寒温和适。腠理不开。然有卒病者。其故何也。少师答曰。帝弗知邪入乎。虽平居其腠理开闭缓急。其故常有时也。黄帝曰。可得闻乎。少师曰。人与天地相参也。与日月相应也。故月满则海水西盛。人血气积。肌肉充。皮肤致。毛发坚。腠理郗。烟垢着。当是之时。虽遇贼风。其入浅不深。至其月郭空。则海水东盛。人气血虚。其卫气去。形独居。肌肉减。皮肤纵。腠理开。毛发残。胶理薄。烟垢落。当是之时。遇贼风则其入深。其病人也。卒暴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183561, '33DDAA891ABAF9C59427DB22E112F023', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4938, 213, 20300803, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。其有卒然暴死暴病者。何也。少师答曰。三虚者。其死暴疾也。得三实者邪不能伤人也。黄帝曰。愿闻三虚。少师曰。乘年之衰。逢月之空。失时之和。因为贼风所伤。是谓三虚。故论不知三虚。工反为粗。帝曰。愿闻三实。少师曰。逢年之盛。遇月之满。得时之和。虽有贼风邪气。不能危之也。黄帝曰。善乎哉论。明乎哉道。请藏之金匮。命曰三实。然。此一夫之论也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183562, '92675312EDB39D75AB902AD9FAECE2DE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4939, 213, 20300804, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。愿闻岁之所以皆同病者。何因而然。少师曰。此八正之候也。黄帝曰。候之奈何。少师曰。候此者。常以冬至之日。太一立于叶蛰之宫。其至也。天必应之以风雨者矣。风雨从南方来者。为虚风。贼伤人者也。其以夜半至也。万民皆卧而弗犯也。故其岁民少病。其以昼至者。万民懈惰而皆中于虚风。故万民多病。虚邪入客于骨而不发于外。至其立春。阳气大发。腠理开。因立春之日。风从西方来。万民又皆中于虚风。此两邪相搏。经气结代者矣。故诸逢其风而遇其雨者。命曰遇岁露焉。因岁之和。而少贼风者。民少病而少死。岁多贼风邪气。寒温不和。则民多病而死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183563, 'ECF5420A15601F9BD34032975F18BA07', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4940, 213, 20300805, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。虚邪之风。其所伤贵贱何如。候之奈何。少师答曰。正月朔日。太一居天留之宫。其日西北风。不雨。人多死矣。正月朔日。平旦北风。春。民多死。正月朔日。平旦北风行。民病多者。十有三也。正月朔日。日中北风。夏。民多死。正月朔日。夕时北风。秋。民多死。终日北风。大病死者十有六。正月朔日。风从南方来。命曰旱乡。从西方来。命曰白骨。将国有殃。人多死亡。正月朔日。风从东方来。发屋。扬沙石。国有大灾也。正月朔日。风从东南方行。春有死亡。正月朔日。天和温不风粜贱。民不病。天寒而风。粜贵。民多病。此所谓候岁之风。残伤人者也。二月丑不风。民多心腹病。三月戌不温。民多寒热。四月已不暑。民多瘅病。十月申不寒。民多暴死。诸所谓风者。皆发屋。折树木。扬沙石起毫毛。发腠理者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221183564, '9097A57B6BF1A6AD3F7815A4257D23BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4941, 214, 20300806, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝问于岐伯曰。余尝上于清冷之台。中阶而顾。匍匐而前。则惑。余私异之。窃内怪之。独瞑独视。安心定气。久而不解。独博独眩。披发长跪。俛而视之。后久之不已也。卒然自上。何气使然。岐伯对曰。五藏六府之精气。皆上注于目而为之精。精之窠为眼。骨之精为瞳子。筋之精为黑眼。血之精为络。其窠气之精为白眼。肌肉之精为约束。裹撷筋骨血气之精。而与脉并为系。上属于脑。后出于项中。故邪中于项。因逢其身之虚。其入深。则随眼系以入于脑。入于脑则脑转。脑转则引目系急。目系急则目眩以转矣。邪其精。其精所中不相比也。则精散。精散则视歧。视歧见两物。目者。五藏六府之精也。营卫魂魄之所常营也。神气之所生也。故神劳则魂魄散。志意乱。是故瞳子黑眼法于阴。白眼赤脉法于阳也。故阴阳合传而精明也。目者。心使也。心者。神之舍也。故神精乱而不转。卒然见非常处精神魂魄。散不相得。故曰惑也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429317, '67A5B8DFB3B96BAFDEB26C32ADD0E992', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4942, 214, 20300807, NULL, NULL, '', NULL, NULL, NULL, '2、黄帝曰。余疑其然。余每之东苑。未曾不惑。去之则复。余唯独为东苑劳神乎。何其异也。岐伯曰。不然也。心有所喜。神有所恶。卒然相惑。则精气乱。视误。故惑。神移乃复。是故间者为迷。甚者为惑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429318, '32B2C870C07FEA43DFDEDC6F3D2AE9E2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4943, 214, 20300808, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。人之善忘者。何气使然。岐伯曰。上气不足。下气有余。肠胃实而心肺虚。虚则营卫留于下。久之不以时上。故善忘也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429319, 'A8AC039DF312F98DB0667896080B5A73', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4944, 214, 20300809, NULL, NULL, '', NULL, NULL, NULL, '4、黄帝曰。人之善饥而不嗜食者。何气使然。岐伯曰。精气并于脾。热气留于胃。胃热则消谷。谷消故善饥。胃气逆上。则胃脘寒。故不嗜食也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429320, '5DC89F7D946C8C51B031BCEBA1FFF329', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4945, 214, 20300810, NULL, NULL, '', NULL, NULL, NULL, '5、黄帝曰。病而不得卧者。何气使然。岐伯曰。卫气不得入于阴。常留于阳。留于阳则阳气满。阳气满则阳蹻盛。不得入于阴则阴气虚。故目不瞑矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429321, '4E5268047FE8C017AC2033A378E69133', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4946, 214, 20300811, NULL, NULL, '', NULL, NULL, NULL, '6、黄帝曰。病目而不得视者。何气使然。岐伯曰。卫气留于阴。不得行于阳。留于阴则阴气盛。阴气盛则阴蹻满。不得入于阳则阳气虚。故目闭也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429322, '7F7EE8799F9E11E514BCE43788B89688', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4947, 214, 20300812, NULL, NULL, '', NULL, NULL, NULL, '7、黄帝曰。人之多卧者。何气使然。岐伯曰。此人肠胃大而皮肤湿。而分肉不解焉。肠胃大则卫气留久。皮肤湿则分肉不解。其行迟。夫卫气者。昼日常行于阳。夜行于阴。故阳气尽则卧。阴气尽则寤。故肠胃大。则卫气行留久。皮肤湿。分肉不解。则行迟。留于阴也久。其气不清。则欲瞑。故多卧矣。其肠胃小。皮肤滑以缓。分肉解利。卫气之留于阳也久。故少瞑焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429323, '3401C43D633E9F74B270E297774912FC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4948, 214, 20300813, NULL, NULL, '', NULL, NULL, NULL, '8、黄帝曰。其非常经也。卒然多卧者。何气使然。岐伯曰。邪气留于上焦。上焦闭而不通。已食若饮汤。卫气留久于阴而不行。故卒然多卧焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429324, 'A5560CDA4C7FF03960C9FD1B652D3EE9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4949, 214, 20300814, NULL, NULL, '', NULL, NULL, NULL, '9、黄帝曰。善。治此诸邪。奈何。岐伯曰。先其藏府。诛其小过。后调其气。盛者泻之。虚者补之。必先明知其形志之苦乐。定乃取之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221429325, '997B8C557470A8763E050E8792E65872', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4950, 215, 20300815, NULL, NULL, '', NULL, NULL, NULL, '1、黄帝曰。余闻肠胃受谷。上焦出气。以温分肉。而养骨节。通腠理。中焦出气如露。上注溪谷。而渗孙脉。津液和调。变化而赤为血。血和则孙脉先满溢。乃注于络脉。皆盈。乃注于经脉。阴阳已张。因息乃行。行有经纪。周有道理。与天合同。不得休止。切而调之。从虚去实。泻则不足。疾则气减。留则先后。从实去虚。补则有余。血气已调。形气乃持。余已知血气之平与不平。未知痈疽之所从生。成败之时。死生之期。有远近。何以度之。可得闻乎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662789, '6F1F46E4AF997E86274ED6832C33DC7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4951, 215, 20300816, NULL, NULL, '', NULL, NULL, NULL, '2、岐伯曰。经脉留行不止。与天同度。与地合纪。故天宿失度。日月薄蚀。地经失纪。水道流溢。草萓不成。五谷不殖。径路不通。民不往来。巷聚邑居。则别离异处。血气犹然。请言其故。夫血脉营卫。周流不休。上应星宿。下应经数。寒邪客于经络之中。则血泣。血泣则不通。不通则卫气归之。不得复反。故痈肿。寒气化为热。热胜则腐肉。肉腐则为脓。脓不泻则烂筋。筋烂则伤骨。骨伤则髓消。不当骨空。不得泄泻。血枯空虚。则筋骨肌肉不相荣。经脉败漏。熏于五藏。藏伤故死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662790, '5E2A1113BE2492CE33EB014A3B00FD08', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4952, 215, 20300817, NULL, NULL, '', NULL, NULL, NULL, '3、黄帝曰。愿尽闻痈疽之形。与忌曰名。岐伯曰。痈发于嗌中。名曰猛疽。猛疽不治。化为脓。脓不泻。塞咽。半日死。其化为脓者。泻则合豕膏。冷食。三日而已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662791, '76EDD56DCBAF19E0A9CAA9BC94F3BCB5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4953, 215, 20300818, NULL, NULL, '', NULL, NULL, NULL, '4、发于颈。名曰夭疽。其痈大以赤黑。不急治。则热气下入渊腋。前伤任脉。内熏肝肺。熏肝肺。十余日而死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662792, 'D94447751FA090929A300155A4FBF94C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4954, 215, 20300819, NULL, NULL, '', NULL, NULL, NULL, '5、阳留大发。消脑留项。名曰脑烁。其色不乐。项痛而如刺以针。烦心者。死不可治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662793, 'F0322C9B4D19BE4AD203C3CABC61813D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4955, 215, 20300820, NULL, NULL, '', NULL, NULL, NULL, '6、发于肩及臑。名曰疵痈。其状赤黑。急治之。此令人汗出至足。不害五藏。痈发四五日。逞焫之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662794, 'B4718713652B6D70AA4FC905A58FBF4E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4956, 215, 20300821, NULL, NULL, '', NULL, NULL, NULL, '7、发于腋下赤坚者。名曰米疽。治之以砭石。欲细而长。疏砭之。涂以豕膏。六日已。勿裹之。其痈坚而不溃者。为马刀挟瘿。急治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662795, '0260A3E6CC27018CF9FFDA5D0012287A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4957, 215, 20300822, NULL, NULL, '', NULL, NULL, NULL, '8、发于胸。名曰井疽。其状如大豆。三四日起。不早治。下入腹。不治。七日死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662796, '3CA9C40599AE9B3CEB3142FFE410EC82', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4958, 215, 20300823, NULL, NULL, '', NULL, NULL, NULL, '9、发于膺。名曰甘疽。色青。其状如谷实𦸈𧁾。常苦寒热。急治之。去其寒热。十岁死。死后出脓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662797, '8BDA61EA0E5025130C5007170A019740', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4959, 215, 20300824, NULL, NULL, '', NULL, NULL, NULL, '10、发于胁。名曰败疵。败疵者。女子之病也。灸之。其病大痈脓。治之。其中乃有生肉。大如赤小豆。坐陵翘草根各一升。以水一斗六升煮之。竭为取三升。则强饮厚衣。坐于釜上。令汗出至足已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662798, 'C9120D1BD284CC13E37FC7F228CD4631', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4960, 215, 20300825, NULL, NULL, '', NULL, NULL, NULL, '11、发于股胫。名曰股胫疽。其状不甚变。而痈脓搏骨。不急治。三十日死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662799, '63DB8A6C1BBC398C0295E747073D65D5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4961, 215, 20300826, NULL, NULL, '', NULL, NULL, NULL, '12、发于尻。名曰锐疽。其状赤坚大。急治之。不治。三十日死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662800, 'A539FB11F129E965FBFEE564ABA918B0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4962, 215, 20300827, NULL, NULL, '', NULL, NULL, NULL, '13、发于股阴。名曰赤施。不急治。六十日死。在两股之内。不治。十日而当死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662801, '058C0B43F9B984A89F87B49CB1B60871', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4963, 215, 20300828, NULL, NULL, '', NULL, NULL, NULL, '14、发于膝。名曰疵痈。其状大。痈色不变。寒热。如坚石。勿石。石之者死。须其柔。乃石之者。生。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662802, 'ACF2614FA02B8A4C0D0938D70AB7362D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4964, 215, 20300829, NULL, NULL, '', NULL, NULL, NULL, '15、诸痈疽之发于节而相应者。不可治也。发于阳者。百日死。发于阴者。三十日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662803, '26B8B80AC9F8E57D339782A0F15ED10F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4965, 215, 20300830, NULL, NULL, '', NULL, NULL, NULL, '16、发于胫。名曰兔啮。其状赤至骨。急治之。不治害人也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662804, 'C3D3ACC5D1700AB40DB9896A047AE012', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4966, 215, 20300831, NULL, NULL, '', NULL, NULL, NULL, '17、发于内踝。名曰走缓。其状痈也。色不变。数石其输。而止其寒热。不死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662805, '812445BE064D4240DDA3CD8FCEE2D98A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4967, 215, 20300832, NULL, NULL, '', NULL, NULL, NULL, '18、发于足上下。名曰四淫。其状大痈。急治之。百日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662806, '1B41A0A36FE437A95DF88F13CB77DDAD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4968, 215, 20300833, NULL, NULL, '', NULL, NULL, NULL, '19、发于足傍。名曰厉痈。其状不大。初如小指。发。急治之。去其黑者。不消辄益。不治。百日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662807, 'F0728676639A9AB47DFC22AF3BA5D85A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4969, 215, 20300834, NULL, NULL, '', NULL, NULL, NULL, '20、发于足指。名脱痈。其状赤黑。死不治。不赤黑。不死。不衰。急斩之。不则死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662808, 'E0B05F01F6171AD1FA840A4E8251F217', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4970, 215, 20300835, NULL, NULL, '', NULL, NULL, NULL, '21、黄帝曰。夫子言痈疽。何以别之。岐伯曰。营卫稽留于经脉之中。则血泣而不行。不行则卫气从之而不通。壅遏而不得行。故热。大热不止。热胜。则肉腐。肉腐则为脓。然不能陷。骨髓不为焦枯。五藏不为伤。故命曰痈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662809, '25E2C2AB928BE9947A88EA33D5C62BAC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4971, 215, 20300836, NULL, NULL, '', NULL, NULL, NULL, '22、黄帝曰。何谓疽。岐伯曰。热气淳盛。下陷肌肤。筋髓枯。内连五藏。血气竭。当其痈下。筋骨良肉皆无余。故命曰疽。疽者。上之皮夭以坚。上如牛领之皮。痈者。其皮上薄以泽。此其候也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957221662810, '420A298CB318C2D0CE0ADCD93C6C73F6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:54:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4972, 216, 20100001, NULL, NULL, '', NULL, NULL, NULL, '1、曰。十二经皆有动脉。独取寸口。以决五脏六腑死生吉凶之法。何谓也。然。寸口者。脉之大会。手太阴之脉动也。人一呼脉行三寸。一吸脉行三寸。呼吸定息。脉行六寸。人一日一夜。凡一万三千五百息。脉行五十度。周于身。漏水下百刻。营卫行阳二十五度。行阴亦二十五度。为一周也。故五十度复会于手太阴。寸口者。五脏六腑之所终始。故法取于寸口也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957109669957, 'B632D76A2315FDF9B3B8A7ED3462AC20', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4973, 217, 20100002, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有尺寸。何谓也。然。尺寸者。脉之大要会也。从关至尺是尺内。阴之所治也。从关至鱼际是寸内。阳之所治也。故分寸为尺。分尺为寸。故阴得尺内一寸。阳得寸内九分。尺寸终始。一寸九分。故曰尺寸也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957109862469, '8B35C4C2394C8C21A543EEEB0772DAFA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4974, 218, 20100003, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有太过。有不及。有阴阳相乘。有覆有溢。有关有格。何谓也。然。关之前者。阳之动也。脉当见九分而浮。过者。法曰太过。减者。法曰不及。遂上鱼为溢。为外关内格。此阴乘之脉也。关之后者。阴之动也。脉当见一寸而沉。过者。法曰太过。减者。法曰不及。遂入尺为覆。为内关外格。此阳乘之脉也。故曰覆溢。是其真脏之脉。人不病而死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110063173, 'F4A9218CE4F89D4B8085AD995BB0BB9B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4975, 219, 20100004, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有阴阳之法。何谓也。然。呼出心与肺。吸入肾与肝。呼吸之间。脾也其脉在中。浮者阳也。沉者阴也。故曰阴阳也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110243397, '4EFCE319242CA951F1C730DEED16E974', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4976, 219, 20100005, NULL, NULL, '', NULL, NULL, NULL, '2、心肺俱浮。何以别之。然。浮而大散者心也浮而短涩者肺也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110243398, '03779A90277058895CE82D200275C227', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4977, 219, 20100006, NULL, NULL, '', NULL, NULL, NULL, '3、肾肝俱沉。何以别之。然。牢而长者肝也。按之濡。举指来实者肾也。脾者中州。故其脉在中。是阴阳之法也。脉有一阴一阳。一阴二阳。一阴三阳。有一阳一阴。一阳二阴。一阳三阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110243399, '895D63C7857A20BAE3D918B2DEB4DAE3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4978, 219, 20100007, NULL, NULL, '', NULL, NULL, NULL, '4、如此之言。寸口有六脉俱动邪。然。此言者。非有六脉俱动也。谓浮。沉。长。短。滑。涩也。浮者阳也。滑者阳也。长者阳也。沉者阴也。短者阴也。涩者阴也。所谓一阴一阳者。谓脉来沉而滑也。一阴二阳者。谓脉来沉滑而长也。一阴三阳者。谓脉来浮滑而长。时一沉也。所谓一阳一阴者。谓脉来浮而涩也。一阳二阴者。谓脉来长而沉涩也。一阳三阴者。谓脉来沉涩而短。时一浮也。各以其经所在。名病顺逆也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110243400, '37719645C18079331F75EE5B8E2EA0EE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4979, 220, 20100008, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有轻重。何谓也。然。初持脉。如三菽之重。与皮毛相得者。肺部也。如六菽之重。与血脉相得者。心部也。如九菽之重。与肌肉相得者。脾部也。如十二菽之重。与筋平者。肝部也。按之至骨。举指来疾者。肾部也。故曰轻重也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110435909, 'FFB3B73CCA0DFA22992D51406CF201E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4980, 221, 20100009, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有阴盛阳虚。阳盛阴虚。何谓也。然。浮之损小。沉之实大。故曰阴盛阳虚。沉之损小。浮之实大。故曰阳盛阴虚。是阴阳虚实之意也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110624325, '979FAAF5018ADC175546FAB62B2CF2C8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4981, 222, 20100010, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言少阳之至。乍大乍小。乍短乍长。阳明之至。浮大而短。太阳之至。洪大而长。少阴之至。紧大而长。太阴之至。紧细而长。厥阴之至。沉短而紧。此六者。是平脉那。将病脉耶。然。皆王脉也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110853701, '461EE5B1566335F5E83C390283CB6948', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4982, 222, 20100011, NULL, NULL, '', NULL, NULL, NULL, '2、其气以何月。各王几日。然。冬至之后。初得甲子少阳王。复得甲子阳明王。复得甲子太阳王。复得甲子少阴王。复得甲子太阴王。复得甲子厥阴王。王各六十日。六六三百六十日。以成一岁。此三阳三阴之王时日大要也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957110853702, '294E52DEE73FF027C2220B0FAD5D8AEC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4983, 223, 20100012, NULL, NULL, '', NULL, NULL, NULL, '1、曰。寸口脉平而死者。何谓也。然。诸十二经脉者。皆系于生气之原。所谓生气之原者。谓十二经之根本也。谓肾间动气也。此五脏六腑之本。十二经脉之根。呼吸之门。三焦之原。一名守邪之神。故气者。人之根本也。根绝则茎叶枯矣。寸口脉平而死者。生气独绝于内也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957111042117, 'FEBB3B7D174BF16E9737A63ED8041CBE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4984, 224, 20100013, NULL, NULL, '', NULL, NULL, NULL, '1、曰。何以别知脏腑之病耶。然。数者腑也。迟者脏也。数则为热。迟则为寒。诸阳为热。诸阴为寒。故以别知脏腑之病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957111226437, '724E248049C21F035EF89356F3AB7E76', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4985, 225, 20100014, NULL, NULL, '', NULL, NULL, NULL, '1、曰。一脉为十变者。何谓也。然。五邪刚柔相逢之意也。假令心脉急甚者。肝邪干心也。心脉微急者。胆邪干小肠也。心脉大甚者。心邪自干心也。心脉微大者。小肠邪自干小肠也。心脉缓甚者。脾邪干心也。心脉微缓者。胃邪于小肠也。心脉涩甚者。肺邪干心也。心脉微涩者。大肠邪干小肠也。心脉沉甚者。肾邪干心也。心脉微沉者。膀胱邪干小肠也。五脏各有刚柔邪。故令一脉辄变为十也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957111423045, '007382D2C36C62B20FD85367F8B16AB6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4986, 226, 20100015, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言脉不满五十动而一止。一脏无气者。何脏也。然。人吸者随阴入。呼者因阳出。今吸不能至肾。至肝而还。故知一脏无气者。肾气先尽也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957111636037, 'A8DAB867C1A97AE3AEFB7160387DDB93', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4987, 227, 20100016, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言五脏脉已绝于内。用针者反实其外。五脏脉已绝于外。用针者反实其内。内外之绝。何以别之。然。五脏脉已绝于内者。肾肝气已绝于内也。而医反补其心肺。五脏脉已绝于外者。心肺气已绝于外也。而医反补其肾肝。阳绝补阴。阴绝补阳。是谓实实虚虚。损不足而益有余。如此死者。医杀之耳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957111840837, 'EC55DE11C04A544EB86FBAEC1B7FBC1E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4988, 228, 20100017, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言见其色而不得其脉。反得相胜之脉者即死。得相生之脉者。病即自己。色之与脉当参相应。为之奈何。然。五脏有五色。皆见于面。亦当与寸口。尺内相应。假令色青。其脉当弦而急。色赤。其脉浮大而散。色黄。其脉中缓而大。色白。其脉浮涩而短。色黑。其脉沉濡而滑。此所谓五色之与脉。当参相应也。脉数。尺之皮肤亦数。脉急。尺之皮肤亦急。脉缓。尺之皮肤亦缓。脉涩。尺之皮肤亦涩。脉滑。尺之皮肤亦滑。五脏各有声。色。臭。味。当与寸口。尺内相应。其不应者病也。假令色青。其脉浮涩而短。若大而缓为相胜。浮大而散。若小而滑为相生也。经言知一为下工。知二为中工。知三为上工。上工者十全九。中工者十全七。下工者十全六。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112025157, 'EF9D802E90BF3797BE75823A032BE914', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4989, 229, 20100018, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有损。至。何谓也。然。至之脉。一呼再至曰平。三至曰离经。四至曰夺精。五至曰死。六至曰命绝。此至之脉也。何谓损。一呼一至曰离经。再呼一至曰夺精。三呼一至曰死。四呼一至曰命绝。此损之脉也。至脉从下上。损脉从上下也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213573, '2DCF758DCF72216FB1F741A385411B75', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4990, 229, 20100019, NULL, NULL, '', NULL, NULL, NULL, '2、损脉之为病奈何。然。一损损于皮毛。皮聚而毛落。二损损于血脉。血脉虚少。不能荣于五脏六腑。三损损于肌肉。肌肉消瘦。饮食不能为肌肤。四损损于筋。筋缓不能自收持。五损损于骨。骨痿不能起于床。反此者。至脉之病也。从上下者。骨痿不能起于床者死。从下上者。皮聚而毛落者死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213574, 'BC4CCE89F24DB4B8C6A7DD228E5670BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4991, 229, 20100020, NULL, NULL, '', NULL, NULL, NULL, '3、治损之法奈何。然。损其肺者。益其气。损其心者。调其荣卫。损其脾者。调其饮食。适其寒温。损其肝者。缓其中。损其肾者。益其精。此治损之法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213575, '2697CB4F3AAC85685914CC7C726FA0CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4992, 229, 20100021, NULL, NULL, '', NULL, NULL, NULL, '4、脉有一呼再至。一吸再至。有一呼三至。一吸三至。有一呼四至。一吸四至。有一呼五至。一吸五至。一呼六至。一吸六至。有一呼一至。一吸一至。有再呼一至。再吸一至。有呼吸再至。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213576, 'C69F7161FA5F125C54A329E4E2AA60F4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4993, 229, 20100022, NULL, NULL, '', NULL, NULL, NULL, '5、脉来如此。何以别知其病也。然。脉来一呼再至。一吸再至。不大不小曰平。一呼三至。一吸三至。为适得其病。前大后小。即头痛。目眩。前小后大。即胸满。短气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213577, '893CD469E73839EE94D8FDBC07A29DBB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4994, 229, 20100023, NULL, NULL, '', NULL, NULL, NULL, '6、一呼四至。一吸四至。病欲甚。脉洪大者。苦烦满。沉细者。腹中痛。滑者。伤热。涩者。中雾露。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213578, 'A25856F2916273F29807CB15DDF56F76', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4995, 229, 20100024, NULL, NULL, '', NULL, NULL, NULL, '7、一呼五至。一吸五至。其人当困。沉细夜加。浮大昼加。不大不小。虽困可治。其有大小者。为难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213579, '8186FF6DDD210010DBA869353F72048C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4996, 229, 20100025, NULL, NULL, '', NULL, NULL, NULL, '8、一呼六至。一吸六至。为死脉也。沉细夜死。浮大昼死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112213580, '42569F7C8BA000032E7C91C0E59E96F0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4997, 229, 20100026, NULL, NULL, '', NULL, NULL, NULL, '9、一呼一至。一吸一至。名曰损。人虽能行。犹当着床。所以然者。血气皆不足故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112217669, '578284B4D9158C19C9D7882F59A21126', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4998, 229, 20100027, NULL, NULL, '', NULL, NULL, NULL, '10、再呼一至。再吸一至。$l{呼吸再至}名曰无魂。无魂者当死也。人虽能行。名曰行尸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112217670, '552AEAC03074076180C6D4B69188A097', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4999, 229, 20100028, NULL, NULL, '', NULL, NULL, NULL, '11、上部有脉。下部无脉。其人当吐。不吐者死。上部无脉。下部有脉。虽困无能为害。所以然者。人之有尺。譬如树之有根。枝叶虽枯槁。根本将自生。脉有根本。人有元气。故知不死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112217671, 'CD625DD3C51D5CB27AC58A6218577037', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5000, 230, 20100029, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言春脉弦。夏脉钩。秋脉毛。冬脉石。是王脉耶。将病脉也。然。弦。钩。毛。石者。四时之脉也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430661, '5A1360788EB8939FE50D494462DEBA27', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5001, 230, 20100030, NULL, NULL, '', NULL, NULL, NULL, '2、春脉弦者。肝东方木也。万物始生。未有枝叶。故其脉之来。濡弱而长。故曰弦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430662, 'CB76D8D913CA9A4D4C6455AF4F45BF58', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5002, 230, 20100031, NULL, NULL, '', NULL, NULL, NULL, '3、夏脉钩者。心南方火也。万物之所茂。垂枝布叶。皆下曲如钩。故其脉之来疾去迟。故曰钩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430663, '623E835B6BAC2CDE8C664D95EE9F0353', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5003, 230, 20100032, NULL, NULL, '', NULL, NULL, NULL, '4、秋脉毛者。肺西方金也。万物之所终。草木华叶。皆秋而落。其枝独在。若毫毛也。故其脉之来。轻虚以浮。故曰毛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430664, '94874C4A66F88D3DFF7DCDD6C07848E0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5004, 230, 20100033, NULL, NULL, '', NULL, NULL, NULL, '5、冬脉石者。肾北方水也。万物之所藏也。盛冬之时。水凝如石。故其脉之来。沉濡而滑。故曰石。此四时之脉也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430665, '474705DA83EAB8E27EB1529C0DB6DD48', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5005, 230, 20100034, NULL, NULL, '', NULL, NULL, NULL, '6、如有变奈何。然。春脉弦。反者为病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430666, 'A71FCC9063331BFBE0D8BDCBB4C5CD19', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5006, 230, 20100035, NULL, NULL, '', NULL, NULL, NULL, '7、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。气来厌厌聂聂。如循榆叶曰平。益实而滑。如循长竿曰病。急而劲益强。如新张弓弦曰死。春脉微弦曰平。弦多胃气少曰病。但弦无胃气曰死。春以胃气为本。夏脉钩。反者为病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430667, '9831C281BAD0064FC0F9EE6C7DBD213D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5007, 230, 20100036, NULL, NULL, '', NULL, NULL, NULL, '8、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来累累如环。如循琅玕曰平。来而益数。如鸡举足者曰病。前曲后居。如操带钩曰死。夏脉微钩曰平。钩多胃气少曰病。但钩无胃气曰死。夏以胃气为本。秋脉毛。反者为病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430668, 'F844AD4BA4F82C5B44584720C9857835', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5008, 230, 20100037, NULL, NULL, '', NULL, NULL, NULL, '9、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来蔼蔼如车盖。按之益大曰平。不上不下。如循鸡羽曰病。按之萧索。如风吹毛曰死。秋脉微毛曰平。毛多胃气少曰病。但毛无胃气。曰死。秋以胃气为本。冬脉石。反者为病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430669, '45804F6FFBC4DE3A5D7CD76ADC268FCC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5009, 230, 20100038, NULL, NULL, '', NULL, NULL, NULL, '10、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。脉来上大下兑。濡滑如雀之喙。曰平。啄啄连属。其中微曲。曰病。来如解索。去如弹石。曰死。冬脉微石。曰平。石多胃气少。曰病。但石无胃气。曰死。冬以胃气为本。胃者。水谷之海。主禀。四时皆以胃气为本。是谓四时之变病。死生之要会也。脾者。中州也。其平和不可得见。衰乃见耳。来如雀之啄。如水之下漏。是脾衰之见也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112430670, 'E3F533BFC119FEEFC5A1CB31762204F3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5010, 231, 20100039, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有三部九候。有阴阳。有轻重。有六十首。一脉变为四时。离圣久远。各自是其法。何以别之。然。是其病。有内外证。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112643653, 'E1DCEBF0B46B719EE45FDC7BC1A622C1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5011, 231, 20100040, NULL, NULL, '', NULL, NULL, NULL, '2、其病为之奈何。然。假令得肝脉。其外证。善洁。面青。善怒。其内证。脐左有动气。按之牢若痛。其病。四肢满。闭淋$l{一作癃}。溲便难。转筋。有是者肝也。无是者非也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112643654, 'A0249930A599DDDD6E2382826092BCCD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5012, 231, 20100041, NULL, NULL, '', NULL, NULL, NULL, '3、假令得心脉。其外证。面赤。口干。喜笑。其内证。脐上有动气。按之牢若痛。其病。烦心。心痛。掌中热而啘。有是者心也。无是者非也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112643655, '7F4F601FD01C73EE8C94B4F9C3896432', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5013, 231, 20100042, NULL, NULL, '', NULL, NULL, NULL, '4、假令得脾脉。其外证。面黄。善噫。善思。善味。其内证。当脐有动气。按之牢若痛。其病。腹胀满。食不消。体重节痛。怠惰嗜卧。四肢不收。有是者脾也。无是者非也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112643656, '790A508ED06BEB07D9D88EAE3938BB24', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5014, 231, 20100043, NULL, NULL, '', NULL, NULL, NULL, '5、假令得肺脉。其外证。面白。善嚏。悲愁不乐。欲哭。其内证。脐右有动气。按之牢若痛。其病。喘咳。洒淅寒热。有是者肺也。无是者非也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112643657, '7369DFEBD4E88F6C1DFB355FC37CA36B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5015, 231, 20100044, NULL, NULL, '', NULL, NULL, NULL, '6、假令得肾脉。其外证。面黑。善恐欠。其内证。脐下有动气。按之牢若痛。其病。逆气。小腹急痛。泄如下重。足胫寒而逆。有是者肾也。无是者非也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112643658, 'F33C58243B6EA7E3F0A8AF271F05ADAD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5016, 232, 20100045, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言病或有死。或有不治自愈。或连年月不已。其死生存亡。可切脉而知之耶。然。可尽知也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112844357, 'CDE87856FED12F29EA6B8B96D0FA794B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5017, 232, 20100046, NULL, NULL, '', NULL, NULL, NULL, '2、诊病若闭目不欲见人者。脉当得肝脉强急而长。反得肺脉浮短而涩者。死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112844358, '933E0A387BA85E2D3F33FC587D75C76F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5018, 232, 20100047, NULL, NULL, '', NULL, NULL, NULL, '3、病若开目而渴。心下牢者。脉当得紧实而数。而反得沉涩而微者。死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112844359, '0A81A5796B5095C97168105ABDD685B8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5019, 232, 20100048, NULL, NULL, '', NULL, NULL, NULL, '4、病若吐血。复鼽衄血者。脉当沉细。而反浮大而牢者。死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112844360, '88A5259812516C9E0F7C202FB754667F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5020, 232, 20100049, NULL, NULL, '', NULL, NULL, NULL, '5、病若谵言妄语。身当有热。脉当洪大。而反手足厥逆。脉沉细而微者。死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112844361, 'BCA05DBE6A38312CDFF2EB62424BCBA4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5021, 232, 20100050, NULL, NULL, '', NULL, NULL, NULL, '6、病若大腹而泄者。脉当微细而涩。反紧大而滑者。死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957112844362, 'E5D7A1E9D0EB228D72A4E8DD5A83C470', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5022, 233, 20100051, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有三部。部有四经。手有太阴。阳明。足有太阳。少阴。为上下部。何谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159749, '790DA3945D0EE920E4E781FDC71FD93F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5023, 233, 20100052, NULL, NULL, '', NULL, NULL, NULL, '2、然。手太阴。阳明金也。足少阴。太阳水也。金生水。水流下行而不能上。故在下部也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159750, 'B6F438E211FC5C5C896732F990A6DBFF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5024, 233, 20100053, NULL, NULL, '', NULL, NULL, NULL, '3、足厥阴。少阳木也。生手太阳。少阴火。火炎上行而不能下。故为上部。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159751, '054F006E601C2427611C33EF3B9BB96C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5025, 233, 20100054, NULL, NULL, '', NULL, NULL, NULL, '4、手心主。少阳火。生足太阴。阳明土。土主中宫。故在中部也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159752, '3856C04FB1EDCC0D072F5F46BB94E339', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5026, 233, 20100055, NULL, NULL, '', NULL, NULL, NULL, '5、此皆五行子母更相生养者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159753, 'D69EA8CF446D202B144407918ADAD545', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5027, 233, 20100056, NULL, NULL, '', NULL, NULL, NULL, '6、脉有三部九侯。各何主之。然。三部者。寸。关。尺也。九侯者。浮。中。沉也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159754, '02DF9A5D79E8A05F7F376E924B58CFCF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5028, 233, 20100057, NULL, NULL, '', NULL, NULL, NULL, '7、上部法天。主胸上至头之有疾也。中部法人。主鬲以下至脐之有疾也。下部法地。主脐以下至足之有疾也。审而刺之者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159755, '52A33F629B21BE67E742CE7AE9377B67', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5029, 233, 20100058, NULL, NULL, '', NULL, NULL, NULL, '8、人病有沉滞久积聚。可切脉而知之耶。然。诊病在右胁有积气。得肺脉。结脉。结甚则积甚。结微则气微。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159756, 'DAAC32DBC1A185407457BD5FFB2671D5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5030, 233, 20100059, NULL, NULL, '', NULL, NULL, NULL, '9、诊不得肺脉。而右胁有积气者。何也。然。肺脉虽不见。右手脉当沉伏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159757, '343429A93F1B28B716F2C5D6DB7F6A6D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5031, 233, 20100060, NULL, NULL, '', NULL, NULL, NULL, '10、其外痼疾同法耶。将异也。然。结者。脉来去时一止。无常数。名曰结也。伏者。脉行筋下也。浮者。脉在肉上行也。左右表里。法皆如此。假令脉结伏者。内无积聚。脉浮结者。外无痼疾。有积聚脉不结伏。有痼疾脉不浮结。为脉不应病。病不应脉。是为死病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113159758, '43D024C89D74AABA574EAA79CD413676', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5032, 234, 20100061, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言脉有逆顺。男女有恒$l{一本作常}。而反者。何谓也。然。男子生于寅。寅为木。阳也。女子生于申。申为金。阴也。故男脉在关上。女脉在关下。是以男子尺脉恒弱。女子尺脉恒盛。是其常也。反者。男得女脉。女得男脉也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113385029, '7F9CDB8B02C22C41CF7FE4C56342BBCD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5033, 234, 20100062, NULL, NULL, '', NULL, NULL, NULL, '2、其为病何如。然。男得女脉为不足。病在内。左得之。病在左。右得之。病在右。随脉言之也。女得男脉为太过。病在四肢。左得之。病在左。右得之。病在右。随脉言之。此之渭也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113385030, 'E6918BFFE061FC92A57D0DEF1EAC602B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5034, 235, 20100063, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言脉有伏匿。伏匿于何脏而言伏匿耶。然。谓阴阳更相乘更相伏也。脉居阴部而反阳脉见者。为阳乘阴也。虽阳脉时沉涩而短。此谓阳中伏阴也。脉居阳部而反阴脉见者。为阴乘阳也。虽阳脉时浮滑而长。此谓阴中伏阳也。重阳者狂。重阴者癫。脱阳者。见鬼。脱阴者。目盲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113606213, '0D1B6249022F094D7F3EB298FDD0C863', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5035, 236, 20100064, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言人形病。脉不病。曰生。脉病。形不病。曰死。何谓也。然。人形病。脉不病。非有不病者也。谓息数不应脉数也。此大法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957113811013, 'C5969116BF232E85F277E017EA81809D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5036, 237, 20100065, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言脉有是动。有所生病。一脉辄$l{一本无辄字}变为二病者。何也。然。经言是动者。气也。所生病者。血也。邪在气。气为是动。邪在血。血为所生病。气主呴之。血主濡之。气留而不行者。为气先病也。血壅而不濡者。为血后病也。故先为是动。后所生$l{一本有病字}也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114007621, '437C9CCE2552C1EE1B7FF4C21D9F6AD7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5037, 238, 20100066, NULL, NULL, '', NULL, NULL, NULL, '1、曰。手足三阴三阳。脉之度数。可晓以不。然。手三阳之脉。从手至头。长五尺。五六合三丈。手三阴之脉。从手至胸中。长三尺五寸。三六一丈八尺。五六三尺。合二丈一尺。足三阳之脉。从足至头。长八尺。六八四丈八尺。足三阴之脉。从足至胸。长六尺五寸。六六三丈六尺。五六三尺。合三丈九尺。人两足跷脉。从足至目。长七尺五寸。二七一丈四尺。二五一尺。合一丈五尺。督脉。任脉。各长四尺五寸。二四八尺。二五一尺。合九尺。凡脉长一十六丈二尺。此所谓经脉长短之数也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114191941, '2FD157B91FA1E7783886D79124153B95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5038, 238, 20100067, NULL, NULL, '', NULL, NULL, NULL, '2、经脉十二。络脉十五。何始何穷也。然。经脉者。行血气。通阴阳。以荣于身者也。其始从中焦。注手太阴。阳明。阳明注足阳明。太阴。太阴注手少阴。太阳。太阳注足太阳。少阴。少阴注手心主。少阳。少阳注足少阳。厥阴。厥阴复还注手太阴。别络十五。皆因其原。如环无端。转相灌溉。朝于寸口。人迎。以处百病。而决死生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114191942, '8A3A12DFBCFB087AAA573A08DF411788', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5039, 238, 20100068, NULL, NULL, '', NULL, NULL, NULL, '3、经云。明知始终。阴阳定矣。何谓也。然。终始者。脉之纪也。寸口。人迎。阴阳之气通于朝使。如环无端。故曰始也。终者。三阴三阳之脉绝。绝则死。死各有形。故曰终也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114191943, 'C75CA79EEC852E8EB3C531B04A55B0EF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5040, 239, 20100069, NULL, NULL, '', NULL, NULL, NULL, '1、曰。手足三阴三阳气已绝。何以为候。可知其吉凶不。然。足少阴气绝。则骨枯。少阴者。冬脉也。伏行而濡于骨髓。故骨髓不濡。即肉不着骨。骨肉不相亲。即肉濡而却。肉濡而却。故齿长而枯。发无润泽。无润泽者。骨先死。戊日笃。己日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114409029, '96E2C8A4FAF3409AF9325853C876FC67', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5041, 239, 20100070, NULL, NULL, '', NULL, NULL, NULL, '2、足太阴气绝。则脉不营其口唇。口唇者。肌肉之本也。脉不营。则肌肉不滑泽。肌肉不滑泽。则人中满。人中满。则唇反。唇反。则肉先死。甲日笃。乙日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114409030, '79E5554924C44A0047B83295282BDD73', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5042, 239, 20100071, NULL, NULL, '', NULL, NULL, NULL, '3、足厥阴气绝。即筋缩引卵与舌卷。厥阴者。肝脉也。肝者。筋之合也。筋者。聚于阴器而络于舌本。故脉不营。则筋缩急。即引卵与舌。故舌卷卵缩。此筋先死。庚日笃。辛日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114409031, '254B12911257462364B395C67402C978', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5043, 239, 20100072, NULL, NULL, '', NULL, NULL, NULL, '4、手太阴气绝。即皮毛焦。太阴者。肺也。行气温于皮毛者也。气弗营。则皮毛焦。皮毛焦。则津液去。津液去。则皮节伤。皮节伤。则皮枯毛折。毛折者。则毛先死。丙日笃。丁日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114409032, '57995BE0082059FE8E69234D9113826F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5044, 239, 20100073, NULL, NULL, '', NULL, NULL, NULL, '5、手少阴气绝。则脉不通。脉不通。则血不流。血不流。则色泽去。故面色黑如黧。此血先死。壬日笃。癸日死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114409033, '22D4C10A718E927E7E54FF8694976B8F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5045, 239, 20100074, NULL, NULL, '', NULL, NULL, NULL, '6、三阴气俱绝者。则目眩转。目瞑。目瞑者。为失志。失志者。则志先死。死即$l{一本作则}目瞑也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114409034, '9A5BDDA575BDC2D837EF22B3354741FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5046, 239, 20100075, NULL, NULL, '', NULL, NULL, NULL, '7、六阳气俱绝者。则阴与阳相离。阴阳相离。则腠理泄。绝汗乃出。大如贯珠。转出不流。即气先死。旦占夕死。夕占旦死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114409035, '161799197A403F6E5D2AE6E9B6B1BEC5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5047, 240, 20100076, NULL, NULL, '', NULL, NULL, NULL, '1、曰。有十二经。五脏六腑十一耳。其一经者。何等经也。然。一经者。手少阴与心主别脉也。心主与三焦为表里。俱有名而无形。故言经有十二也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114597445, 'BC12E5E9BAB750307F326ADF42503496', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5048, 241, 20100077, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经有十二。络有十五。余三络者。是何等络也。然。有阳络。有阴络。有脾之大络。阳络者。阳跷之络也。阴络者。阴跷之络也。故络有十五焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957114802245, '30568D5FF41ABDE7BDFCA522A87C5BCC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5049, 242, 20100078, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脉有奇经八脉者。不拘于十二经。何也。然。有阳维。有阴维。有阳跷。有阴跷。有冲。有督。有任。有带之脉。凡此八脉者。皆不拘于经。故曰奇经八脉也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115019333, '9682993AFA7B35BC0F63E88AFA1D8FC2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5050, 242, 20100079, NULL, NULL, '', NULL, NULL, NULL, '2、经有十二。络有十五。凡二十七。气相随上下。何独不拘于经也。然。圣人图设沟渠。通利水道。以备不虞。天雨降下。沟渠溢满。当此之时。留需妄行。圣人不能复图也。此络脉满溢。诸经不能复拘也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115019334, 'E14E14E111E4DC9AEE715FBC0D49707C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5051, 243, 20100080, NULL, NULL, '', NULL, NULL, NULL, '1、曰。其奇经八脉者。既不拘于十二经。皆何起何继也。然。督脉者。起于下极之俞。并于脊里。上至风府。入属于脑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115199557, '8B576196B03FA1B013FB53A48D5364F8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5052, 243, 20100081, NULL, NULL, '', NULL, NULL, NULL, '2、任脉者。起于中极之下。以上毛际。循腹里。上关元。至咽喉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115199558, 'DE072ED57D6DFE1A6CDD5050E92E22A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5053, 243, 20100082, NULL, NULL, '', NULL, NULL, NULL, '3、冲脉者。起于气冲。并足阳明之经。夹脐上行。至胸中而散也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115199559, '05B18C0E28AB9CF59C5589D3CE881BF2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5054, 243, 20100083, NULL, NULL, '', NULL, NULL, NULL, '4、带脉者。起于季胁。回身一周。阳跷脉者。起于跟中。循外踝上行。入风池。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115199560, '33F58ADC887BEC8BDF817EF636AC6668', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5055, 243, 20100084, NULL, NULL, '', NULL, NULL, NULL, '5、阴跷脉者。亦起于跟中。循内踝上行。至咽喉。交贯冲脉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115199561, '49EC1BEBAF7913630FE8B9B6D0826A55', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5056, 243, 20100085, NULL, NULL, '', NULL, NULL, NULL, '6、阳维。阴维者。维络于身。溢蓄。不能环流灌溉诸经者也。故阳维起于诸阳会也。阴维起于诸阴交也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115199562, 'E34410341CE7E334FB2F0A9953984DDC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5057, 243, 20100086, NULL, NULL, '', NULL, NULL, NULL, '7、比于圣人图设沟渠。沟渠满溢。流于深湖。故圣人不能拘通也。而人脉隆盛。入于八脉。而不还周。故十二经亦有不能拘之。其受邪气。畜则肿热。砭射之也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115199563, 'B08B8F30721506C1F5200A9125F4719E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5058, 244, 20100087, NULL, NULL, '', NULL, NULL, NULL, '1、曰。奇经之为病。何如。然。阳维维于阳。阴维维于阴。阴阳不能自相维。则怅然失志。溶溶不能自收持。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115404357, '3EE12E9A0BE8E856AD9230AC32B2F053', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5059, 244, 20100088, NULL, NULL, '', NULL, NULL, NULL, '2、阳维为病苦寒热。阴维为病若心痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115404358, '6E3D69816AFAF7556A3F68ACBDA3A1F8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5060, 244, 20100089, NULL, NULL, '', NULL, NULL, NULL, '3、阴跷为病。阳缓而阴急。阳跷为病。阴缓而阳急。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115404359, '6D3793BD751F3EF37B54B21B3868E4C6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5061, 244, 20100090, NULL, NULL, '', NULL, NULL, NULL, '4、冲之为病。逆气而里急。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115404360, 'A2D4DA963436D77AE354C7372307B518', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5062, 244, 20100091, NULL, NULL, '', NULL, NULL, NULL, '5、督之为病。脊强而厥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115404361, 'E811CD929CC19242C0B119CFA929CED6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5063, 244, 20100092, NULL, NULL, '', NULL, NULL, NULL, '6、任之为病。其内苦结。男子为七疝。妇子为瘕聚。带之为病。腹满。腰溶溶若坐水中。此奇经八脉之为病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115404362, '4914FCAADE2E00930DB1ABD9F4F0E345', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5064, 245, 20100093, NULL, NULL, '', NULL, NULL, NULL, '1、曰。营气之行。常与卫气相随不。然。经言人受气于谷。谷入于胃。乃传于五脏六腑。五脏六腑皆受于气。其清者为营。浊者为卫。荣行脉中。卫行脉外。营周不息。五十而复大会。阴阳相贯。如环之无端。故知营卫相随也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115592773, '1D89851778CAC091ECC22331E0207E5F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5065, 246, 20100094, NULL, NULL, '', NULL, NULL, NULL, '1、曰。三焦者。何禀何生。何始何终。其治常在何许。可晓以不。然。三焦者。水谷之道路。气之所终始也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115785285, '0CFE074B8684C26EA2905183BAB3B95C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5066, 246, 20100095, NULL, NULL, '', NULL, NULL, NULL, '2、上焦者。在心下。下膈。在胃上口。主内而不出。其治在膻中。玉堂下一寸六分。直两乳间陷者是。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115785286, 'F9B80BB22EDF90AAD0DEBA5A8F642D4B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5067, 246, 20100096, NULL, NULL, '', NULL, NULL, NULL, '3、中焦者。在胃中脘。不上不下。主腐熟水谷。其治在脐傍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115785287, '3B491A49324CCFFAD0343D972AA45990', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5068, 246, 20100097, NULL, NULL, '', NULL, NULL, NULL, '4、下焦者。当膀胱上口。主分别清浊。主出而不内。以传导也。其治在脐下一寸。故名曰三焦。其府在气街。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115785288, '72913E591BE0A318A3391C8EBF04A4E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5069, 247, 20100098, NULL, NULL, '', NULL, NULL, NULL, '1、曰。五脏俱等。而心肺独在鬲上者。何也。然。心者血。肺者气。血为荣。气为卫。相随上下。谓之荣卫。通行经络。营周于外。故令心肺独在鬲上也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957115985989, 'E8E893B0DC83259368B38DF563C75976', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5070, 248, 20100099, NULL, NULL, '', NULL, NULL, NULL, '1、曰。肝青象木。肺白象金。肝得水而沉。木得水而浮。肺得水而浮。金得水而沉。其意何也。然。肝者。非为纯木也。乙角也。庚之柔。大言阴与阳。小言夫与妇。释其微阳。而吸其微阴之气。其意乐金。又行阴道多。故令肝得水而沉也。肺者。非为纯金也。辛商也。丙之柔。大言阴与阳。小言夫与妇。释其微阴。婚而就火。其意乐火。又行阳道多。故令肺得水而浮也。肺熟而复沉。肝熟而复浮者。何也。故知辛当归庚。乙当归甲也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116182597, 'F9DE5453AB545F8C9ABA14053EE0124B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5071, 249, 20100100, NULL, NULL, '', NULL, NULL, NULL, '1、曰。五脏各有声。色。臭。味。液。皆可晓知以不。然。《十变》言。肝色青。其臭臊。其味酸。其声呼。其液泣。心色赤。其臭焦。其味苦。其声言。其液汗。脾色黄。其臭香。其味甘。其声歌。其液涎。肺色白。其臭腥。其味辛。其声哭。其液涕。肾色黑。其臭腐。其味咸。其声呻。其液唾。是五脏声。色。臭。味。液也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116375109, 'F3F312F8947C1E78B86829654B61927A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5072, 249, 20100101, NULL, NULL, '', NULL, NULL, NULL, '2、五脏有七神。各何所藏那。然。脏者。人之神气所舍藏也。故肝藏魂。肺藏魄。心藏神。脾藏意与智。肾藏精与志也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116375110, '59DCC4036E32214B4A010DA3817A795E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5073, 250, 20100102, NULL, NULL, '', NULL, NULL, NULL, '1、曰。五脏各有所腑皆相近。而心。肺独去大肠。小肠远者。何谓$l{一本无谓字}也。然。经言心营。肺卫。通行阳气。故居在上。大肠。小肠。传阴气而下。故居在下。所以相去而远也。又诸腑皆阳也。清净之处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116584005, '4DAFE1588E2B768D128AECDE9FB446EA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5074, 250, 20100103, NULL, NULL, '', NULL, NULL, NULL, '2、今大肠。小肠。胃与膀胱。皆受不净。其意何也。然。诸腑者。谓是非也。经言。小肠者。受盛之腑也。大肠者。传泻行道之腑也。胆者。清净之腑也。胃者。水谷之腑也。膀胱者。津液之腑也。一腑犹无两名。故知非也。小肠者。心之腑。大肠者。肺之腑。胆者。肝之腑。胃者。脾之腑。膀胱者。肾之腑。小肠谓赤肠。大肠谓白肠。胆者谓青肠。胃者谓黄肠。膀胱者谓黑肠。下焦之所治也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116584006, '26F10F39945E816F35525D8F43627168', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5075, 251, 20100104, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脏各有一耳。肾独有两者。何也。然。肾两者。非皆肾也。其左者为肾。右者为命门。命门者。诸神精之所舍。原气之所系也。男子以藏精。女子以系胞。故知肾有一也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116768325, '935593F01C20CACA9C08AC2022525B02', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5076, 252, 20100105, NULL, NULL, '', NULL, NULL, NULL, '1、曰。五脏之气。于何发起。通于何许。可晓以不。然。五脏者。常内阅于上七窍也。故肺气通于鼻。鼻和则知香臭矣。肝气通于目。目和则知黑白矣。脾气通于口。口和则知谷味矣。心气通于舌。舌和则知五味矣。肾气通于耳。耳和则知五音矣。五脏不和。则七窍不通。六腑不和。则留结为痈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116985413, '5C8B17721078BAA3383260A62CE2F02E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5077, 252, 20100106, NULL, NULL, '', NULL, NULL, NULL, '2、邪在六腑。则阳脉不和。阳脉不和。则气留之。气留之。则阳脉盛矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116985414, '1DD1071EF73C74D18C947FF070CBB5FC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5078, 252, 20100107, NULL, NULL, '', NULL, NULL, NULL, '3、邪在五腑。则阴脉不和。阴脉不和。则血留之。血留之。则阴脉盛矣。阴气太盛。则阳气不得相营也。故曰格。阳气太盛。则阴气不得相营也。故曰关。阴阳俱盛。不得相营也。故曰关格。关格者。不得尽其命而死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116985415, '02F70F95B418D255214406E19CEC8A4E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5079, 252, 20100108, NULL, NULL, '', NULL, NULL, NULL, '4、经言气独行于五脏。不营于六腑者。何也。然。夫气之所行也。如水之流。不得息也。故阴脉营于五脏。阳脉营于六腑。如环无端。莫知其纪。终而复始。其不覆溢。人气内温于脏腑。外濡于凑理。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957116985416, 'D57F7B758185A5FA952939ED9ECBA82D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5080, 253, 20100109, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脏唯有五。腑独有六者。何也。然。所以腑有六者。谓三焦也。有原气之别焉。主持诸气。有名而无形。其经$l{一本无经字}属手少阳。此外腑也。故言腑有六焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957117182021, '51944BFC4D1DCFF3C8ACE4FEC449C484', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5081, 254, 20100110, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言腑有五。脏有六者。何也。然。六腑者。正有五腑也。五脏亦有六脏者。谓肾有两脏也。其左为肾。右为命门。命门者。谓精神之所舍也。男子以藏精。女子以系胞。其气与肾通。故言脏有六也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957117358149, 'DAB7A06C8D791F35677BD8F9DEF69816', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5082, 254, 20100111, NULL, NULL, '', NULL, NULL, NULL, '2、腑有五者。何也。然。五脏各一腑。三焦亦是一腑。然不属于五脏。故言腑有五焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957117358150, 'FF64D0DA8C4CD7AF9E88CE9A03538B97', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5083, 255, 20100112, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。肝主色。心主臭。脾主味。肺主声。肾主液。鼻者。肺之候。而反知香臭。耳者。肾之候。而反闻声。其意何也。然。肺者。西方金也。金生于巳。巳者南方火。火者心。心主臭。故令鼻知香臭。肾者。北方水也。水生于申。申者西方金。金者肺。肺主声。故令耳闻声。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957117571141, '781A122E1206E8CD072CAE4417737349', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5084, 256, 20100113, NULL, NULL, '', NULL, NULL, NULL, '1、曰。肝独有两叶。以何应也。然。肝者。东方木也。木者。春也。万物始生。其尚幼小。意无所亲。去太阴尚近。离太阳不远。犹有两心。故有两叶。亦应木叶也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957117759557, 'F135E8AFCB1413E183311BB3201C3EFE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:10', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5085, 257, 20100114, NULL, NULL, '', NULL, NULL, NULL, '1、曰。人肠胃长短。受水谷多少。各几何。然。胃大一尺五寸。径五寸。长二尺六寸。横屈。受水谷三斗五升。其中常留谷二斗。水一斗五升。小肠大二寸半。径八分。分之少半。长三丈二尺。受谷二斗四升。水六升三合。合之大半。回肠大四寸。径一寸半。长二丈一尺。受谷一斗。水七升半。广肠大八寸。径二寸半。长二尺八寸。受谷九升三合。八分合之一。故肠胃凡长五丈八尺四寸。合受水谷八斗七升六合。八分合之一。此肠胃长短。受水谷之数也。肝重四斤四两。左三叶。右四叶。凡七叶。主藏魂。心重十二两。中有七孔三毛。盛精汁三合。主藏神。脾重二斤三两。扁广三寸。长五寸。有散膏半斤。主裹血。温五脏。主藏意。肺重三斤三两。六叶两耳。凡八叶。主藏魄。肾有两枚。重一斤一两。主藏志。胆在肝之短叶间。重三两三铢。盛精汁三合。胃重二斤一两$l{一本作二斤二两，《史记正义》作二斤十四两，多本从此}。纡曲屈伸。长二尺六寸。大一尺五寸。径五寸。盛谷二斗。水一斗五升。小肠重二斤十四两。长三丈二尺。广二寸半。径八分。分之少半。左回叠积十六曲。盛谷二斗四升。水六升三合。合之大半。大肠重二斤十二两。长二丈一尺。广四寸。径一寸。当脐右回十六曲。盛谷一斗。水七升半。膀胱重九两二铢。纵广九寸。盛溺九升九合。口广二寸半。唇至齿长九分。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十二两$l{《灵枢·肠胃》：咽门重十两，多本从之}。广二寸半。至胃长一尺六寸。喉咙重十二两。广二寸。长一尺二寸。九节。肛门重十二两。大八寸。径二寸大半。长二尺八寸。受谷九升三合。八分合之一。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957117935685, 'AEBD94D5E2BB555790D40257147C26CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5086, 258, 20100115, NULL, NULL, '', NULL, NULL, NULL, '1、曰。人不食饮。七日而死者。何也。然。人胃中当留谷二斗。水一斗五升。故平人日再至圊。一行二升半。一日中五升。七日五七三斗五升。而水谷尽矣。故平人不食饮七日而死者。水谷津液俱尽。即死矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957118132293, 'CAA2887C3EF00CBD136A526D184A08D5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5087, 259, 20100116, NULL, NULL, '', NULL, NULL, NULL, '1、曰。七冲门何在。然。唇为飞门。齿为户门。会厌为吸门。胃为贲门。太仓下口为幽门。大肠小肠会为阑门。下极为魄门。故曰七冲门也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957118332997, 'D12EA74D20A1DC43EA06B5D7A22C1965', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5088, 260, 20100117, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言八会者。何也。然。腑会太仓。脏会季胁。筋会阳陵泉。髓会绝骨。血会鬲俞。骨会大抒。脉会太渊。气会三焦外。一筋直两乳内也。热病在内者。取其会之气穴也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957118509125, '98E596462C493B56E8D5A4567D4B629F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5089, 261, 20100118, NULL, NULL, '', NULL, NULL, NULL, '1、曰。老人卧而不寐。少壮寐而不寤者。何也。然。经言少壮者。血气盛。肌肉滑。气道通。营卫之行不失于常。故昼日精。夜不寤也。老人血气衰。肌肉不滑。营卫之道涩。故昼日不能精。夜不得寐也。故知老人不得寐也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957118722117, '29A2C06C9582BA8C7B5BFDB5C901E3F3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5090, 262, 20100119, NULL, NULL, '', NULL, NULL, NULL, '1、曰。人面独能耐寒者。何也。然。人头者。诸阳之会也。诸阴脉皆至颈。胸中而还。独诸阳脉皆上至头耳。故令面耐寒也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957118914629, '57B37DDB2B2ECDAD5F6714E4600E1D59', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5091, 263, 20100120, NULL, NULL, '', NULL, NULL, NULL, '1、曰。人有三虚三实。何谓也。然。有脉之虚实。有病之虚实。有诊之虚实也。脉之虚实者。濡者为虚。牢者为实。病之虚实者。出者为虚。入者为实。言者为虚。不言者为实。缓者为虚。急者为实。诊之虚实者。痒者为虚。痛者为实。外痛内快。为外实内虚。内痛外快。为内实外虚。故曰虚实也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119131717, '348A8854D88F38C54569A9AEEF8A7CC2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5092, 264, 20100121, NULL, NULL, '', NULL, NULL, NULL, '1、曰。有正经自病。有五邪所伤。何以别之。然。经言忧愁思虑则伤心。形寒饮冷则伤肺。恚怒气逆。上而不下则伤肝。饮食劳倦则伤脾。久坐湿地。强力入水则伤肾。是正经之自病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119328325, 'CD97DF68A10F1B8E1FBC4953D706BA66', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5093, 264, 20100122, NULL, NULL, '', NULL, NULL, NULL, '2、何谓五邪。然。有中风。有伤暑。有饮食劳倦。有伤寒。有中湿。此之谓五邪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119328326, '4B51064EE7AF185341E202C3B5101894', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5094, 264, 20100123, NULL, NULL, '', NULL, NULL, NULL, '3、假令心病。何以知中风得之。然。其色当赤。何以言之。肝主色。自入为青。入心为赤。入脾为黄。入肺为白。入肾为黑。肝为心邪。故知当赤色。其病身热。胁下满痛。其脉浮大而弦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119328327, '59046BADAC9E7A5D41FAF2021634C9A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5095, 264, 20100124, NULL, NULL, '', NULL, NULL, NULL, '4、何以知伤暑得之。然。当恶焦臭。何以言之。心主臭。自入为焦臭。入脾为香臭。入肝为臊臭。入肾为腐臭。入肺为腥臭。故知心病伤暑得之。当恶焦臭。其病身热而烦。心痛。其脉浮大而散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119328328, '830EE0570F21525AB8F23846A5061CA8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5096, 264, 20100125, NULL, NULL, '', NULL, NULL, NULL, '5、何以知饮食劳倦得之。然。当喜苦味也。何以言之。脾主味。入肝为酸。人心为苦。入肺为辛。入肾为咸。自入为甘。故知脾邪入心。为喜苦味也。其病身热而体重。嗜卧。四肢不收。其脉浮大而缓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119328329, '3643CB13358F5A57446546254A648931', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5097, 264, 20100126, NULL, NULL, '', NULL, NULL, NULL, '6、何以知伤寒得之。然。当谵言妄语。何以言之。肺主声。入肝为呼。入心为言。入脾为歌。入肾为呻。自入为哭。故知肺邪入心。为谵言妄语也。其病身热。洒洒恶寒。甚则喘咳。其脉浮大而涩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119328330, '89C9368891971BFD0C50D2494D99F62A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5098, 264, 20100127, NULL, NULL, '', NULL, NULL, NULL, '7、何以知中湿得之。然。当喜汗出不可止。何以言之。肾主液。入肝为泣。入心为汗。入脾为涎。入肺为涕。自入为唾。故知肾邪入心。为汗出不可止也。其病身热。而小腹痛。足胫寒而逆。其脉沉濡而大。此五邪之法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119328331, 'BB9C5F017983150F82D82BAD39003E6B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5099, 265, 20100128, NULL, NULL, '', NULL, NULL, NULL, '1、曰。病有虚邪。有实邪。有贼邪。有微邪。有正邪。何以别之。然。从后来者为虚邪。从前来者为实邪。从所不胜来者为贼邪。从所胜来者为微邪。自病者为正邪。何以言之。假令心病。中风得之为虚邪。伤暑得之为正邪。饮食劳倦得之为实邪。伤寒得之为微邪。中湿得之为贼邪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119524933, '2A83B2180C5E80AF3BE4588D02D3E9CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5100, 266, 20100129, NULL, NULL, '', NULL, NULL, NULL, '1、曰。病有欲得温者。有欲得寒者。有欲得见人者。有不欲得见人者。而各不同。病在何脏腑也。然。病欲得寒。而欲见人者。病在腑也。病欲得温。而不欲见人者。病在脏也。何以言之。腑者阳也。阳病欲得寒。又欲见人。脏者。阴也。阴病欲得温。又欲闭户独处。恶闻人声。故以别知脏腑之病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119729733, 'A74AB6730AC772AB25ECD82B29BE186D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5101, 267, 20100130, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脏腑发病。根本等不。然。不等也。其不等奈何。然。脏病者。止而不移。其病不离其处。腑病者。仿佛贲响。上下行流。居处无常。故以此知脏腑根本不同也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957119909957, '0D78A6FBDA659F15067EA21766110F70', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5102, 268, 20100131, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言七传者死。间脏者生。何谓也。然。七传者。传其所胜也。间脏者。传其子也。何以言之。假令心病传肺。肺传肝。肝传脾。脾传肾。肾传心。一脏不再伤。故言七传者死也。间脏者。传其所生也。假令心病传脾。脾传肺。肺传肾。肾传肝。肝传心。是母子相传。竟而复始。如环无端。故曰生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957120094277, '774B8331C2EC31775BBD138A88210A71', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5103, 269, 20100132, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脏病难治。腑病易治。何谓也。然。脏病所以难治者。传其所胜也。腑病易治者。传其子也。与七传。间传同法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957120290885, 'DDA3AAF4C3A7BD8718EE2BA1423BDCE1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5104, 270, 20100133, NULL, NULL, '', NULL, NULL, NULL, '1、曰。病有积。有聚。何以别之。然。积者。阴气也。聚者。阳气也。故阴沉而伏。阳浮而动。气之所积。名曰积。气之所聚。名曰聚。故积者。五脏所生。聚者。六腑所成也。积者。阴气也。其始发有常处。其痛不离其部。上下有所终始。左右有所穷处。聚者。阳气也。其始发无根本。上下无所留止。其痛无常处谓之聚。故以是别知积聚也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957120487493, '9EFB9961F1E39331FB85E29106E036D4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5105, 271, 20100134, NULL, NULL, '', NULL, NULL, NULL, '1、曰。五脏之积。各有名乎。以何月。何日得之。然。肝之积。名曰肥气。在左胁下。如覆杯。有头足。久不愈。令人发咳逆。疟。连岁不已。以季夏戊己日得之。何以言之。肺病传于肝。肝当传脾。脾季夏适王。王者不受邪。肝复欲还肺。肺不肯受。故留结为积。故知肥气以季夏戊己日得之。心之积。名曰伏梁。起脐上。大如臂。上至心下。久不愈。令人病烦心。以秋庚辛日得之。何以言之。肾病传心。心当传肺。肺以秋适王。王者不受邪。心复欲还肾。肾不肯受。故留结为积。故知伏梁以秋庚辛日得之。脾之积。名曰痞气。在胃脘。覆大如盘。久不愈。令人四肢不收。发黄疸。饮食不为肌肤。以冬壬癸日得之。何以言之。肝病传脾。脾当传肾。肾以冬适王。王者不受邪。脾复欲还肝。肝不肯受。故留结为积。故知痞气以冬壬癸日得之。肺之积。名曰息贲。在右胁下。覆大如杯。久不已。令人洒淅寒热。喘咳。发肺壅。以春甲乙日得之。何以言之。心病传肺。肺当传肝。肝以春适王。王者不受邪。肺复欲还心。心不肯受。故留结为积。故知息贲以春甲乙日得之。肾之积。名曰贲豚。发于少腹。上至心下。若豚状。或上或下无时。久不已。令人喘逆。骨痿少气。以夏丙丁日得之。何以言之。脾病传肾。肾当传心。心以夏适王。王者不受邪。肾复欲还脾。脾不肯受。故留结为积。故知贲豚以夏丙丁日得之。此五积之要法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957120704581, 'F0240B97D4640ED97AB33FE23F158E79', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5106, 272, 20100135, NULL, NULL, '', NULL, NULL, NULL, '1、曰。泄凡有几。皆有名不。然。泄凡有五。其名不同。有胃泄。有脾泄。有大肠泄。有小肠泄。有大瘕泄。名曰后重。胃泄者。饮食不化。色黄。脾泄者。腹胀满。泄注。食即呕吐逆。大肠泄者。食已窘迫。大便色白。肠鸣切痛。小肠泄者。溲而便脓血。少腹痛。大瘕泄者。里急后重。数至圊而不能便。茎中痛。此五泄之要法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957120909381, '8F98841A0604CDAA081316DDF5D0F9B8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5107, 273, 20100136, NULL, NULL, '', NULL, NULL, NULL, '1、曰。伤寒有几。其脉有变不。然。伤寒有五。有中风。有伤寒。有湿温。有热病。有温病。其所苦各不同。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121093701, '7B2DFD266E159DA95AA8EC8518A29746', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5108, 273, 20100137, NULL, NULL, '', NULL, NULL, NULL, '2、中风之脉。阳浮而滑。阴濡而弱。湿温之脉。阳濡而弱。阴小而急。伤寒之脉。阴阳俱盛而紧涩。热病之脉。阴阳俱浮。浮之而滑。沉之散涩。温病之脉。行在诸经。不知何经之动也。各随其经所在而取之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121093702, 'BFDCA7FBE06130C1A6D42507764A0EDC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5109, 273, 20100138, NULL, NULL, '', NULL, NULL, NULL, '3、伤寒有汗出而愈。下之而死者。有汗出而死。下之而愈者。何也。然。阳虚阴盛。汗出而愈。下之即死。阳盛阴虚。汗出而死。下之而愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121093703, '02489B371D1AF9EE80D714A962BFBF64', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5110, 273, 20100139, NULL, NULL, '', NULL, NULL, NULL, '4、寒热之病。候之如何也。然。皮寒热者。皮不可近席。毛发焦。鼻槁。不得汗。肌寒热者。肌痛。唇舌槁。无汗。骨寒热者。病无所安。汗注不休。齿本槁痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121093704, 'CAE7733B83C8B63BB2F7F1D5822FFA0F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5111, 274, 20100140, NULL, NULL, '', NULL, NULL, NULL, '1、曰。狂癫之病。何以别之。然。狂疾之始发。少卧而不饥。自高贤也。自辨智也。自贵倨也。妄笑好歌乐。妄行不休是也。癫疾始发。意不乐。僵仆直视。其脉三部阴阳俱盛是也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121290309, 'C05B79670DDA4611E832D1E6BD7283A2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5112, 275, 20100141, NULL, NULL, '', NULL, NULL, NULL, '1、曰。头心之病。有厥痛。有真痛。何谓也。然。手三阳之脉。受风寒。伏留而不去者。则名厥头痛。入连在脑者。名真头痛。其五脏气相干。名厥心痛。其痛甚。但在心。手足青者。即名真心痛。其真心痛者。旦发夕死。夕发旦死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121478725, '2DF143671162D50442496A7F48F9C57F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5113, 276, 20100142, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。望而知之谓之神。闻而知之谓之圣。问而知之谓之工。切脉而知之谓之巧。何谓也。然。望而知之者。望见其五色。以知其病。闻而知之者。闻其五音。以别其病。问而知之者。问其所欲五味。以知其病所起所在也。切脉而知之者。诊其寸口。视其虚实。以知其病。病在何脏腑也。经言。以外知之曰圣。以内知之曰神。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121667141, 'BAA4510DA3F0ECA24C7D659403A243B6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5114, 277, 20100143, NULL, NULL, '', NULL, NULL, NULL, '1、曰。脏井。荥有五。腑独有六者。何谓也。然。腑者。阳也。三焦行于诸阳。故置一俞。名曰原。腑有六者。亦与三焦共一气也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957121876037, '33185622FF47A5B6BDEF12D34F9A627A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:12', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5115, 278, 20100144, NULL, NULL, '', NULL, NULL, NULL, '1、曰。《十变》言。五脏六腑荥。合。皆以井为始者。何也。然。井者。东方春也。万物之始生。诸蚑行喘息。蚏飞蠕动。当生之物。莫不以春生。故岁数始于春。日数始于甲。故以井为始也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957122068549, 'BD4C9DC4C760846BAF833F28B84A5100', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5116, 279, 20100145, NULL, NULL, '', NULL, NULL, NULL, '1、曰。《十变》又言。阴井木。阳井金。阴荥火。阳荥水。阴俞土。阳俞木。阴经金。阳经火。阴合水。阳合土。阴阳皆不同。其意何也。然。是刚柔之事也。阴井乙木。阳井庚金。阳井庚。庚者。乙之刚也。阴井乙。乙者。庚之柔也。乙为木。故言阴井木也。庚为金。故言阳井金也。余皆仿此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957122310213, '18F049D3875828EEBD20E77AB49C8927', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5117, 280, 20100146, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。所出为井。所入为合。其法奈何。然。所出为井。井者。东方春也。万物之始生。故言所出为井也。所入为合。合者。北方冬也。阳气入藏。故言所入为合也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957122498629, 'C37AA3809442775DD838CD32AB2CC2BB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5118, 281, 20100147, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。肺之原。出于太渊。心之原。出于太陵。肝之原。出于太冲。脾之原。出于大白。肾之原。出于太溪。少阴之原。出于兑骨。胆之原。出于丘墟。胃之原。出于冲阳。三焦之原。出于阳池。膀胱之原。出于京骨。大肠之原。出于合谷。小肠之原。出于腕骨。十二经皆以俞为原者。何也。然。五脏俞者。三焦之所行。气之所留止也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957122723909, 'CCEBC8FB199D76EE5A85AAF0C626DDA4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5119, 281, 20100148, NULL, NULL, '', NULL, NULL, NULL, '2、三焦所行之俞为原者。何也。然。脐下肾间动气者。人之生命也。十二经之根本也。故名曰原。三焦者。原气之别使也。主通行三气。经历于五脏六腑。原者。三焦之尊号也。故所止辄为原。五脏六腑之有病者。皆取其原也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957122723910, '2FAE752F6043B665A67BC4E052DBCC58', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5120, 282, 20100149, NULL, NULL, '', NULL, NULL, NULL, '1、曰。五脏募皆在阴。而俞皆在阳者。何谓也。然。阴病行阳。阳病行阴。故令募在阴。俞在阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957122904133, 'A41C6442C855233CE89C2E8CE1F0CB1B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5121, 283, 20100150, NULL, NULL, '', NULL, NULL, NULL, '1、曰。五脏六腑。皆有井。荥。俞。经。合。皆何所主。然。经言所出为井。所流为荥。所注为俞。所行为经。所入为合。井主心下满。荥主身热。俞主体重节痛。经主喘咳寒热。合主逆气而泄。此五脏六腑井。荥。俞。经。合所主病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957123092549, '9A29524DDB9223D55F678C0E96A0CE36', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5122, 284, 20100151, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。虚者补之。实者泻之。不实不虚。以经取之。何谓也。然。虚者补其母。实者泻其子。当先补之。然后泻之。不实不虚。以经取之者。是正经自生病。不中他邪也。当自取其经。故言以经取之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957123338309, '69D9005F922C63FF8BFFFC5AD9BEF046', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5123, 285, 20100152, NULL, NULL, '', NULL, NULL, NULL, '1、曰。春夏刺浅。秋冬刺深者。何谓也。然。春夏者。阳气在上。人气亦在上。故当浅取之。秋冬者。阳气在下。人气亦在下。故当深取之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957123534917, '64620CA8D955244F39CB80C4A07D4DEC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5124, 285, 20100153, NULL, NULL, '', NULL, NULL, NULL, '2、春夏各致一阴。秋冬各致一阳者。何谓也。然。春夏温。必致一阴者。初下针。沉之至肾肝之部。得气。引持之阴也。秋冬寒。必致一阳者。初内针。浅而浮之至心肺之部。得气。推内之阳也。是谓春夏必致一阴。秋冬必致一阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957123534918, 'BCA3F432636A158A29487991861E2256', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5125, 286, 20100154, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。刺荣无伤卫。刺卫无伤荣。何谓也。然。针阳者。卧针而刺之。刺阴者。先以左手摄按所针荥俞之处。气散乃内针。是谓刺荣无伤卫。刺卫无伤荣也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957123747909, 'D537EA84AFF9128CFBCC63E2E04059E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5126, 287, 20100155, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。能知迎随之气。可令调之。调气之方。必在阴阳。何谓也。然。所谓迎随者。知荣卫之流行。经脉之往来也。随其逆顺而取之。故曰迎随。调气之方。必在阴阳者。知其内外表里。随其阴阳而调之。故曰调气之方。必在阴阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957123956805, '8B95E09F513B58D9D470E4D557A2FAB2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5127, 288, 20100156, NULL, NULL, '', NULL, NULL, NULL, '1、曰。诸井者。肌肉浅薄。气少不足使也。刺之奈何。然。诸井者。木也。荥者。火也。火者。木之子。当刺井者。以荥泻之。故经言。补者不可以为泻。泻者不可以为补。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957124141125, '93AD4560E454474E9E6CCCA1F4D04F73', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5128, 289, 20100157, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。春刺井。夏刺荥。季夏刺俞。秋刺经。冬刺合者。何谓也。然。春刺井者。邪在肝。夏刺荥者。邪在心。季夏刺俞者。邪在脾。秋刺经者。邪在肺。冬刺合者。邪在肾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957124337733, '4066AEFA6046D5518D1759437F02F51F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5129, 289, 20100158, NULL, NULL, '', NULL, NULL, NULL, '2、其肝。心。脾。肺。肾。而系于春。夏。秋。冬者。何也。然。五脏一病。辄有五也$l{一本言五色}。假令肝病。色青者肝也。臊臭者肝也。喜酸者肝也。喜呼者肝也。喜泣者。肝也。其病众多。不可尽言也。四时有数。而并系于春。夏。秋。冬者也。针之要妙。在于秋毫者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957124337734, '7CD0F317255B09B5274F14266523EDCF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5130, 290, 20100159, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。东方实。西方虚。泻南方。补北方。何谓也。然。金。木。水。火。土。当更相平。东方木也。西方金也。木欲实。金当平之。火欲实。水当平之。土欲实。木当平之。金欲实。火当平之。水欲实。土当平之。东方肝也。则知肝实。西方肺也。则知肺虚。泻南方火。补北方水。南方火。火者。木之子也。北方水。水者。木之母也。水胜火。子能令母实。母能令子虚。故泻火补水。欲令金不得平木也。经曰。不能治其虚。何问其余。此之谓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957124542533, '9F37D483C09996E4334A0062B298F275', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5131, 291, 20100160, NULL, NULL, '', NULL, NULL, NULL, '1、曰。何谓补泻。当补之时。何所取气。当泻之时。何所置气。然。当补之时。从卫取气。当泻之时。从荣置气。其阳气不足。阴气有余。当先补其阳。而后泻其阴。阴气不足。阳气有余。当先补其阴。而后泻其阳。营卫通行。此其要也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957124751429, '2B61AD6ADE8D41B079390E36BCC42A9C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5132, 292, 20100161, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。上工治未病。中工治已病。何谓也。然。所谓治未病者。见肝之病。则知肝当传之与脾。故先实其脾气。无令得受肝之邪。故曰治未病焉。中工者。见肝之病。不晓相传。但一心治肝。故曰治已病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957124952133, 'C6D14A41AA2833DF6310E3BB9EF4E3C3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5133, 293, 20100162, NULL, NULL, '', NULL, NULL, NULL, '1、曰。针有补泻。何谓也。然。补泻之法。非必呼吸出内针也。知为针者。信其左。不知为针者。信其右。当刺之时。先以左手厌按所针荥。俞之处。弹面努之。爪而下之。其气之来。如动脉之状。顺针而刺之。得气。因推而内之。是谓补。动而伸之。是谓泻。不得气。乃与。男外女内。不得气。是为十死不治也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957125140549, '37E9F25ECEAA3C444F94FD0EDCB24FF4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5134, 294, 20100163, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。迎而夺之。安得无虚。随而济之。安得无实。虚之与实。若得若失。实之与虚。若有若无。何谓也。然。迎而夺之者。泻其子也。随而济之者。补其母也。假令心病。泻手心主俞。是谓迎而夺之者也。补手心主井。是谓随而济之者也。所谓实之与虚者。牢濡之意也。气来实牢者为得。濡虚者为失。故曰若得若失也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957125341253, '6D3980401A5F20C98B1B6A8592D536A6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5135, 295, 20100164, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。有见如入。有见如出者。何谓也。然。所谓有见如入。有见如出者。谓左手见气来至。乃内针。针入。见气尽。乃出针。是谓有见如入。有见如出也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957125537861, '48965167285B0519E237F61FBCE4DF9B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5136, 296, 20100165, NULL, NULL, '', NULL, NULL, NULL, '1、曰。经言。无实实虚虚。损不足而益有余。是寸口脉耶。将病自有虚实耶。其损益奈何。然。是病。非谓寸口脉也。谓病自有虚实也。假令肝实而肺虚。肝者木也。肺者金也。金木当更相平。当知金平木。假令肺实而肝虚。微少气。用针不补其肝。而反重实其肺。故曰实实虚虚。损不足而益有余。此者。中工之所害也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599957125754949, 'BF78D01115771B1FC801B17E75F0A214', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-26 21:56:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5187, 314, 902000101, NULL, NULL, NULL, NULL, NULL, NULL, '我国自古相传有三坟，最是深奥难懂，历代以来所有名家都认为能解此三坟者就是最懂中华文化的人，这三坟就是《易经》，《黄帝内经》与《神农本草经》，今我收集历代各名家对本草所做之论述，再加上我个人自临床经验中所获得的知识，虽完成这部神农本草经的解说，但是必然有不足之处，敬请读者见谅，后来之高手名医必然可以再增加许多有效之说明与批注，个人期待所有有志学习中医的人士，能够自此书中得到一定的药物学知识，经方之用药是超出原书许多。因此我在本书之后增添许多经方的用药，以备将来研习经方时，能有药性之根据。本书虽未完善，但是已经包含所有将来研究伤寒与金匮所需的药性知识在内，因此如能熟读本书，将来研究经方时必然事半功倍，替研习经方者省去许多不必要的查询药物时间，将来一看到处方时，就可以心知肚明处方原因，剂量使用，用药原则等等，所谓开卷有益，即使看完全书后，只能得到一小点药物知识，这也是值得。期望我人纪班学员与购买者，在看完此书之后，能更上层楼，学无止尽，大家以此为基础，再向上向外发展研究，就不会迷失用药方向了。\n                                                                                                                                  汉唐中医 倪海厦谨记 06/18/2006 于佛州深夜丑时自家书房', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599943428763717, 'AC331F240775927934C88809BE41C3EF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 22:41:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5188, 315, 902000201, NULL, NULL, NULL, NULL, NULL, NULL, '         神农本草经成书年代，说法不一，有人认为是战国时期，有人认为是秦汉时期，也有人认为是东汉时期，经过许多医家综合整理，不断收集秦汉时期资料，再整理而成，之后再托名神农而成之书。姑且不论源起于何时期，但它是我国最早的一部本草药典。其地位是无庸置疑的，其原著早于唐代初年已经失传，现在流传的版本是明清以后的学者根据宋代《太平御览》《证类本草》，和明代的《本草纲目》等书，进行整复编辑后，重新出刊的，以清代孙星衍，孙冯冀合辑本（1799）最为广传。\n        原书共载药物三百六十五种，其中植物药二百五十二种，动物药六十七种，矿物药四十六种，这些药大多疗效确实，至今仍被使用，其中涉及病症约一百七十多种，包括了内、外、妇、眼、耳、喉、齿等各科的疾病。对于有毒性的药物，强调必须以小剂量开始。逐渐增加剂量，以免造成药物中毒的后果，其原则是“若用毒药疗病，先起黍粟，病去即止，不去，倍之；不去，十之，取去为度”，对于服药法也有规定，“病在胸膈以上者，先食后服药，病在心腹以下者，先服药而后食，病在四肢血脉者，宜空腹而在旦；病在骨髓者，宜饱满而在夜”，因东汉时期盛行签纬神学，故书中时见如“久服神仙不死”、“主杀鬼”、“能行水上”等用词，这些都是我们可以舍弃不用的。\n         本书所引用的药物药性学，都来自历代的伤寒家，也就是经方家，如陶弘景编录之《名医别录》，雷公之《雷公炮制论》，唐之名医甄权对药性说明。陈藏器的《本草拾遗》，孟铣的《食疗本草》，王好古（1200—1264），字进之，号海藏老人，元代越州人，其著有《汤液本草》，其好经方，善用硫磺、附子、肉桂、干姜、乌头等峻药，清唐容川的《本草问答》，日本东洞吉益先生的《药征》，清徐灵胎的《神农本草经百种录》等等，千年以来温病与伤寒之争论不休，由于二派所认定的药性有所出入，是故选用药物的方式也大异其趣、剂量多少也完全不同，而张仲景所研究的《胎胪药录》早已失传，经方中的药物应该都是出自此书。我们除了在孙思邈的《千金要方》与《千金翼方》二书中可以略窥一二外，在其它药典之中实在无法找出关于《胎胪药录》的药性解说，因此现代有志研习经方的中医们，想更了解经方之中的每味药性，唯一最有效的方式，就是利用伤寒与金匮中的处方方向与使用剂量大小，反过来推知这些药物在东汉时期《胎胪药录》一书对于药性的说明了，然而此法必须要非常了解《黄帝内经》的素问与灵枢、八十一难与阴阳大论，才有可能将这《胎胪药录》重新还其原貌。\n           由于原神农本草经中之药物，有些己经无人识得，有些不切实际。我将之保留不做说明，同学们可以自行查看市面上的有关本草药性的说明，与此同时我增加在伤寒金匮中张仲景所使用之药物，这些药物并不见于原神农本草经中，但是必然出现在《胎胪药录》之中，我将以我对伤寒金匮中处方内的每味药所理解的药性，为之补强说明，希望后来之学者能将之发扬光大。更加能够增润本书的内容。\n          前言：我国医学始于神农、有谓神农尝百草，一日遇七十毒，复命僦贷季（歧伯之师）理色脉，所以上古是先有药而后有医也，是故治病之道必先于用药，而用药之道必先于识药，此书共分上中下三种药物的说明。其中上药一百二十味，中药一百二十味，下药一百二十五味，一共定三百六十五味药，合于天数一年之日数。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599943905443909, '543BA03C001925D41999F282968698C7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 22:50:00', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5189, 316, 902000301, NULL, NULL, NULL, NULL, NULL, NULL, '1、五味之义──凡药酸属木入肝，苦属火入心，甘属土入脾，辛属金入肺，咸属水入肾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152508485, 'D8C963F3D28E3B49C69DB453A6F49185', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 22:51:17', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5190, 316, 902000312, NULL, NULL, NULL, NULL, NULL, NULL, '12、五味所伤──\n        多食咸，则脉凝泣而变色。\n        多食苦，则皮槁而毛拔。\n        多食辛，则筋急而爪枯。\n        多食酸，则肉消皮厚而唇开。\n        多食甘，则骨痛而发落。\n药之为物，各有其形性气质，其入诸经，有因形相类者，有因性相从者，有因气相求者，有因质相同者，自然之理，可以以意得也。\n药有以形名者，人参狗脊之类是也，有以色名者，黄连黑参之类是也，有以气名者，稀签香薷之类是也，有以味名者，甘草苦参之类是也，有以质名者，石膏石脂归身归尾之类是也，有以时名者，夏枯款冬之类是也，有以能名者，何首乌骨碎补之类是也。\n    凡药火制四，煨炙炒煅也。\n            水制三，浸泡洗也，水火共制二，蒸煮也，酒制升提，姜制温散。\n            入盐走肾而软坚。\n            用醋注肝而收敛。\n            童便制，除劣性而降下，\n            米泔制，去燥性而和中，\n            乳制润枯生血，蜜制甘缓益元。\n            陈壁土制，藉土气以补中州。\n            面裹曲制，抑酷性勿伤上膈。\n 黑豆甘草汤渍，并解毒致平和，羊酥猪脂涂烧，咸渗骨容易脆断，去穰者免胀，去心者除烦，此制治各有所宜也。\n         一药之为用，或地道不真，则美恶迥别，或市肆饰伪，则气味全乖，或收采非时，则良楛异质，或头尾误用，则呼应不灵，或制治不精，则功力大减，用者不察，顾归咎于药之罔功，譬之兵不精炼，思以荡寇克敌，适以覆众舆ㄕ也，治疗之家，其可忽诸。\n        千金云：凡药须治择熬泡毕，然后秤用，不得生秤，湿润药先皆增分两，燥乃秤之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537157, 'FDBE65F904A7B970D4601C35C8BB3214', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5191, 316, 902000311, NULL, NULL, NULL, NULL, NULL, NULL, '11、五病所禁──\n       酸走筋，故筋病勿多食酸，筋得酸则拘急，收引益盛。\n       苦走骨，故骨病勿多食苦，骨得苦则阴益盛，令人重而难举。\n       甘走肉，肉痛勿多食甘，肉病得甘则壅气，臃肿益甚。\n       辛走气，气病勿多食辛，气得辛则散，而益虚。\n       咸走血，血病勿多食咸，血得咸则凝涩，而口渴也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537158, 'BF98CEBC500A44DD5B63E2EFC81CAFF8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5192, 316, 902000310, NULL, NULL, NULL, NULL, NULL, NULL, '10、五行相克──酸伤筋，辛胜酸；苦伤气，咸胜苦；甘伤肉，酸胜甘；辛伤皮毛，苦胜辛；咸伤血，甘胜咸。因为酸主收敛，敛则筋缩，苦能泻气，辛能疏散肌理，咸能渗泄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537159, '0DD8917DCA64FD9B85166B1A2012DBA9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5193, 316, 902000309, NULL, NULL, NULL, NULL, NULL, NULL, '9、五行相生──人之五藏应五行，子母相生，\n经曰：虚则补其母，实则泻其子。又曰：子能令母实，母能令子虚，\n        如肾为肝母，心为肝子，故入肝者并入肾与心。\n         肝为心母，脾为心子，故入心者并入肝与脾。\n         心为脾母，肺为脾子，故入脾者并入心与肺。\n         脾为肺母，肾为肺子，故入肺者并入脾与肾。\n         肺为肾母，肝为肾子，故入肾者并入肺与肝。\n此五行相生子母相应之义也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537160, '51D7DDD9CE48A996F0F1DE6333EF395F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5194, 316, 902000308, NULL, NULL, NULL, NULL, NULL, NULL, '8、六淫主治──\n      风淫于内，治以辛凉，佐以苦甘，以甘缓之，以辛散之。\n      热淫于内，治以咸寒，佐以甘苦，以酸收之，以苦发之。\n      湿淫于内，治以苦热，佐以酸淡，以苦燥之，以淡泄之。\n     火淫于内，治以咸冷，佐以苦辛，以酸收之，以苦发之。\n     燥淫于内，治以苦温，佐以甘辛，以苦下之。\n     寒淫于内，治以甘热，佐以苦辛，以咸泻之，以辛润之，以苦坚之。\n此六淫主治，各有所宜，故药性须明，而施用贵审也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537161, '8F9DB245F1A69595EC05687411844BE0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5195, 316, 902000307, NULL, NULL, NULL, NULL, NULL, NULL, '7、五脏补泻之义──\n       肝苦急，急食甘而缓之；肝欲散，急食辛以散之，以辛补之，以酸泻之。\n       心苦缓，急食酸以收之；心欲软，急食咸以软之，以咸补之，以甘泻之。\n       脾苦湿，急食苦以燥之；脾欲缓，急食甘以缓之，以甘补之，以苦泻之。\n       肺苦气上逆，急食苦以泻之；肺欲收，急食酸以收之，以酸补之，以辛泻之。\n       肾苦燥，急食辛以润之；肾欲坚，急食苦以坚之，以苦补之，以咸泻之，此是其义也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537162, '2C86CE3F95C129029C48BE0B74A18E4F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5196, 316, 902000306, NULL, NULL, NULL, NULL, NULL, NULL, '6、药色之入经脉──\n   凡药色青，味酸，气臊，性属木，皆入足厥阴肝，足少阳胆经。\n   色赤味苦，气焦，性属火者，皆入手少阴心，手太阳小肠经。\n   色黄味甘，气香性属土者，皆入足太阴脾，足阳明胃经。\n   色白味辛，气腥，性属金者，皆入手太阴肺，手阳明大肠经。\n   色黑味咸，气腐性属水者，皆入足少阴肾，足太阳膀胱经。\n   十二经中唯手厥阴心包，手少阳三焦经无所主，其经通于足厥阴少阳，而厥阴主血，诸\n   药入肝经血分者，并入心包，少阳主气。诸药入胆经气分者并入三焦，命门相火，散行于胆\n   三焦心包，故入命门者并入三焦，此诸药入诸经之分布也。药有相需者，同类而不可离者。\n   相使者，我之佐使也。相恶者，夺我之能也。相畏者，受彼之制也，相反者。两不相合也。\n相杀者，制彼之毒也，此异同之义也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537163, 'B57296BE74CFBC874D8488D98C6EED06', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5197, 316, 902000305, NULL, NULL, NULL, NULL, NULL, NULL, '5、药之相从──凡药清虚者浮而升，重实者沉而降，味薄者升而生如春季，气薄者降而收象秋季。气厚者浮而长象夏天，味厚者沉而藏象冬天，味平者化而成象长夏，气厚味薄者浮而升，味厚气薄者沉而降，气味俱厚者能浮能沉，气味俱薄者可升可降，酸咸无升，辛甘无降，寒无浮，热无沉，此升降浮沉之义也，凡药根在土中者，半身以上则上升，半身以下则下降，药为枝者达四肢，为皮者达皮肤。为心为干者内行脏腑，质轻者上入心肺，重者下入肝肾，中空者发表，内实者攻里，枯燥者入气分，润泽者入血分，此上下内外之相从也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537164, 'E4D79E5F0020CC14A3422172676E35E7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5198, 316, 902000304, NULL, NULL, NULL, NULL, NULL, NULL, '4、阴阳之义──寒热温凉是气也，酸苦甘辛咸是味也，气为阳味为阴，其气厚者为阳中之阳，薄者阳中之阴也。味厚者阴中之阴，薄者阴中之阳，气薄主发泄散表，厚则发热与温，味厚则泄降，薄则通窍，利渗湿，辛甘发散为阳，酸苦涌泄为阴，咸味涌泄为阴，淡味渗泄为阳，轻清升浮为阳，重浊沉降为阴，阳气出上窍， 阴味出下窍，清阳发肌理。浊阴走五脏。清阳实四肢，浊阴归六腑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537165, 'ACD7F1CE2A69C48DC063382934F586A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5199, 316, 902000303, NULL, NULL, NULL, NULL, NULL, NULL, '3、五味之用──凡药酸者能涩能收，苦者能泻能燥能坚，甘者能补能和能缓，辛者能散能润能横行，咸者能下能软坚，淡者能利窍能渗泄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537166, '78B56D2888486F3EF461C572804222C9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5200, 316, 902000302, NULL, NULL, NULL, NULL, NULL, NULL, '2、五色之义──青属木入肝，赤属火入心，黄属土入脾，白属金入肺，黑属水入肾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152537167, 'ABF9390416E31533C9CED588B8613F90', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:03:02', 1, '超级管理员', '2024-09-29 16:40:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5201, 317, 902000401, '\n【本经原文】性味甘，微寒无毒，主治身体五脏百病，可以养精神安魂魄。益气明目，杀精魅邪恶鬼，久服通神明，不老能化为汞，畏磁石恶盐水，其色真珠光色如云母，可折者良。又名朱砂。\n\n【产地】在我国四川湖南等山中。以辰州为最佳，故又号辰砂，属石类。\n\n【主治】丹砂为安神要药。\n\n【别录】通血脉，止烦满，消渴，益精神，悦泽人面。除中恶腹痛，毒气疥廔诸疮。\n\n【甄权】镇心，主抽风传ㄕ痨痵等。\n\n【大明】润心肺，治疮痂息肉，可外涂之。\n\n【灵贻】入心镇怯，定魂除邪。\n\n【用量】一般水飞用以拌合他药，单服时可用二，三分。以至钱许。\n\n【禁忌】丹砂只可生研水飞用。火炼则为水银而有毒。不可用，多服丹砂因其性质重坠，使人神定目呆。坊间名为朱砂，一般使用方式是用来拌合他药或做丸衣用，因为其功用在安神镇静，所以多被加入一些安神药中，海藏曰“如同龙骨牡蛎合用，可以养心气，同当归丹参合用，可以养心血。同枸杞地黄合用可以养神，同厚朴川椒等合用可以养脾，同南星川乌同用可以却风。可以明目安胎，也可以解毒，可以发汗，端视医师如何使用而见其功”。因其色红，内合真汞之水，属火中有水之药性，故其象心之性，而其性属微寒，得治心病所必须之寒性，服之使人心神内敛神守，故能安眠。为补心之要药。即朱砂，由天地自然熔铸而成，阳中含阴，外露火色，内含水阴，具硫磺水银之相合之性，因属火体中含有水气，故丹砂能入心，益阴以安神，养血安神为之最。有阳中之阴药称，与人参南北称王。一般言北方属水，故多气分之药，南方属火，故多血分之药。\n\n【炮制】取朱砂打碎，选去夹石，用磁石吸尽铁削。研成粉未。置砵内，加入适量清水研磨成糊状，然后再加入清水搅拌，使之沉淀。倒出悬浮液。只取下沉粉末，如此反复多次。至手捻之细腻则止，倒出水后，将粉末晒干即得。瓦罐装，置干燥处。', NULL, NULL, '1', '丹砂,朱砂', NULL, '1、丹砂,朱砂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 599956152799301, '1EA6AE23FFB209544A738D4727497CAD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-09-28 23:05:43', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5202, 317, 902000404, '\n【本经原文】味甘，主咳逆上气，明目益精，安五脏，通百节利九窍，下乳汁，又名虚中。  神农辛，黄帝甘，扁鹊甘无毒，如乳汁黄白色，空中相通，计然云出武都黄白者善。 \n\n【产地】中国日本俱有出产，生于山中石洞穴中，我国以广西陕西等省多此洞。 \n\n【性味】味甘，性温，无毒。 \n\n【主治】石钟乳为补阳益精要药，主治肺气虚损，咳逆上气，明目利窍，补髓疗弱，消渴引饮。 \n\n【别录】益气补虚损，疗脚弱疼冷，下焦伤竭，强阴。 \n\n【甄权】主泄经，寒嗽，壮元气，益阳事，通声。 \n\n【括要】补五劳七伤。补骨髓，治消渴引饮。 \n\n【灵胎】入肺降逆，利窍下乳。 \n\n【用量】普通水飞用，五分至一钱。 \n\n【禁忌】石药性悍，不宜久服。 其下垂象天，石又属金，故主镇降肺气。 \n\n【炮制】拣去杂质。洗净晒干，置铁锅内煅透，取出放凉，研粉即得。', NULL, NULL, '1', '石钟乳,虚中', NULL, '4、石钟乳,虚中', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605218331406405, '41324E34C38194A6D320827CA79D4319', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:19:44', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5203, 317, 902000403, '\n【本经原文】味甘平，主五脏百病，柔筋强骨，安魂魄，长肌肉益气，久服耐寒暑，不饥渴，不老神仙，人临死服五斤，三年色不变，一名玉桃。 畏款冬恶青竹，白玉桃如白头公。玉为阳精之纯者，食之以御水气。 古传食玉之法来自抱朴子仙药篇云：玉可以乌米酒及地榆酒化之为水，亦可以葱浆消之为液。亦可饵之为丸，亦可以烧以为粉，服之一年以上，入水不沾，入火不灼，刃之不伤百毒不犯也。不可用已经做成玉器之物必伤人也，璞玉乃可用也。  \n\n【产地】玉乃石之美者，产山中，我国西南深山中多有之，以钟山蓝田产者最良，于阗国之白玉最好。  \n\n【性味】甘平，无毒。  \n\n【主治】清热解渴，安神养肌。  \n\n【别录】除胃中热，喘息，烦满，止渴，明耳目。  \n\n【大明】润心肺，助喉声，滋毛发。  \n\n【括要】面身瘢痕，真玉日日磨之则自灭。 \n\n【炮制】取净生玉，置砂罐内，煅至火红透，取出，冷却研粉即得。  ', NULL, NULL, '1', '玉泉,玉桃', NULL, '3、玉泉,玉桃', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605218331406406, 'BEE8420F4AA320510964278A0C2A047B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:19:44', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5204, 317, 902000402, '\n【本经原文】味甘平，主身皮死肌，中风寒热，古时在车船上可以除邪气，安五脏，益子精， 明目，久服轻身延年，又名云华，云英，云液，云沙，磷石。  \n        按：抱朴子迁药篇云──云母有五种，其多五色并具，如见青色多者名云英，宜春服之，见赤色多者名云珠，宜夏服之，多白色者名云液，宜秋服之，多黑色者宜冬服之，如见只有青黄二色者名云沙， \n        宜长夏服之，如见晶莹剔透纯白者，可以四时常服之。  \n\n【产地】产四川及各省山中，种类甚多，有黑云母及白云母等，白者良，属玉类。 \n\n【性味】味甘性平，无毒。 \n\n【主治】云母主补肺下气，补中坚肌，除邪气，安精神。 \n\n【别录】下气坚肌，续绝补中，疗五痨七伤，虚损少气，止痢，久服悦泽不老，耐寒暑。  \n\n【甄权】主下痢肠澼，补肾冷。 \n\n【括要】生产不下，用云母细末，调酒涂于阴门。  \n\n【灵胎】清肺明目。  \n\n【用量】一般内服数分起。  \n\n【禁忌】古称云母治百病，服食无忌，但制炼须慎，不可过量服食。 \n\n【炮制】取净生云母，置铁锅内，煅至火红透，取出，冷却研粉即得。 ', NULL, NULL, '1', '云母,云华,云英,云液,云沙,磷石', NULL, '2、云母,云华,云英,云液,云沙,磷石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605218331406407, '1674DAB52B087BA0F298AC5384C4271E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:19:44', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5205, 317, 902000411, '\n【别录】养肝胆，除寒热，杀白虫，疗头风，脑中寒，止烦渴，补不足，盛阴气。味酸性小寒无毒，目痛止泪出，风痹，利关节，通九窍，破症瘕积聚。  \n\n【本经】养肝胆，除寒热，杀白虫，疗头风，脑中寒，止烦渴，补不足，盛阴气。  \n\n【炮制】拣去杂质即可。 ', NULL, NULL, '1', '曾青', NULL, '11、曾青', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605219645268038, '97F1E2DD9AD5D367405D92D67FB079F8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:25:04', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5206, 317, 902000410, '\n【本经原文】味甘寒，主青盲，耳聋明目利九窍，通血脉，养精神益肝，久服轻身延年不老，能化铜铁铅锡作金。吴普曰空青神农甘一经酸，久服有神仙玉女来侍，使人志高。  \n\n【产地】产河南山西陕西山中，色青质轻，近罕见。今名丹青。  \n\n【主治】空青为一切眼目要药，主治目赤目痛，青盲耳聋，利九窍通血脉，养神益肝。  \n\n【别录】疗目赤痛，去肤翳止泪出，利水道，下乳汁，通关节，破坚积。  \n\n【甄权】治头风镇肝，瞳仁破者，得再见物。 \n\n【大明】钻孔取浆，点多年青盲，内障翳膜，养精气，其壳摩翳。  \n\n【用量】内服外用，分许至一、二钱，外用点目可以与贝母同用。  \n\n【禁忌】勿过量使用。一日点二次即止。\n\n【炮制】拣去杂质即可。  ', NULL, NULL, '1', '空青', NULL, '10、空青', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605219645268039, 'FDD67DDC91B31115352183DA15965AEB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:25:04', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5207, 317, 902000409, '\n【本经原文】味酸寒，主明目目痛金创，诸痫痉，女子阴蚀痛，石淋寒热，崩中下血，诸邪毒气，令人有子，炼饵服之不老，久服增寿神仙。能化铁为铜成金银。 神农酸小寒，扁鹊苦无毒，周礼疡医凡疗疡以五毒攻之，石胆丹砂雄黄矾石慈石其中烧之三日三夜，其烟上着以鸡羽扫取之，以注创恶肉破骨则尽出。  \n\n【产地】产山中，为蓝色结晶。  \n\n【性味】味酸辛，性寒，有小毒。 \n\n【主治】胆矾为腐蚀催吐要药，功能蚀恶疮散症积，涌吐风痰，治咽喉口鼻疮毒及目患。  \n【大明】治虫牙，鼻内息肉。  \n\n【苏颂】入吐风痰药最快。  \n\n【用量】入煎剂一钱至二钱，研末服一分许。  \n\n【禁忌】胃弱人不宜多服。  \n\n【吴克潜】胆矾有腐蚀性与收敛性，故能治恶疮，吐顽痰，喉痹欲死，研末醋调灌之，大吐胶痰而愈，治狐臭，胆矾枯矾各一钱，轻粉百药煎各五分，为细末敷之效，著名方剂有铁桶膏（铜绿胆矾五倍子白芷轻粉郁金麝香）治发背将溃时，根脚走散不收者，用以涂疮四周根上效。  \n\n【炮制】拣去杂质即可。  ', NULL, NULL, '1', '石胆,胆矾', NULL, '9、石胆,胆矾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605219645268040, 'A38D5DFAC23BB17E1E79922FC8EFD513', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:25:05', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5208, 317, 902000408, '\n【本经原文】味甘寒，主身热泄澼，女子乳难癃闭，利小便，荡胃中积聚寒热，益精气，久服轻身耐饥长生。  \n\n【产地】产我国山东及西南诸省山中。色青白或黄白及银灰色。  \n\n【性味】味甘性寒无毒。  \n\n【主治】滑石为去湿热利小便要药，主通六府九窍津液。上开肌理下通膀胱，治淋疾，水肿，黄疸。  \n\n【丹溪】燥湿，分水道，实大肠，化食毒，行积滞，逐凝血，解燥渴，补脾胃，降心火，偏主石淋为要药。  \n\n【容川】为去暑之要药，去暑只宜清气利湿，不可用燥药，如黄连亦然，甘草也可。  \n\n【药征】主治小便不利，旁治渴也。  \n\n【灵胎】荡肠胃热，利大小便。  \n\n【用量】普通一钱至三四钱。  \n\n【禁忌】凡阴精不足内热，以致小便短少赤涩，或不利，及烦渴身热，由于阴虚火热水涸者，均忌，脾胃俱虚者虽不做泄亦忌，因其性滑也。  \n\n【炮制】拣去杂质，洗净，研细粉，即可。', NULL, NULL, '1', '滑石', NULL, '8、滑石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605219645268041, '44CE79CD54A13F144A247921F6195B5E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:25:05', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5209, 317, 902000407, '\n【本经原文】味苦寒，主百病，除寒热邪气，逐六府积聚，结固留癖，能化七十二种石，炼饵服之轻身神仙。 吴普曰朴硝，神农歧伯曰无毒。  \n\n【产地】生于盐卤之地，凡煎炼水硝，结出细芒者为芒硝，结出马牙状者为马牙硝，其凝于底成块者，通为朴硝。  \n\n【性味】味咸辛苦，性寒无毒。 \n\n【主治】朴消主软坚化积，逐六腑积聚结固留癖。清热泻下，外用消食化积。  \n\n【甄权】治腹胀，大小便不通，女子月经不通。 \n\n【大明】通泄五脏百病，及症结，天行热疾，头痛消肿毒，排脓润毛发。  \n\n【容川】咸味虽重，尚未至于极，故犹有寒水石之性，能大下其火。凡盐味之咸。内皆有火热之性，而水中之火即是命门之火也。微咸之味者，皆能引火下行。大咸者能助火升发也。芒硝得水中阴凝之性，味咸能软坚，下气分之热，以其得水之阴味，未得水中之阳气，故降而不升，能降气分之热，是治热要药，与大黄入血分治火要药不同。  \n\n【药征】主软坚，治心下痞坚，心下石鞭，小腹急结，结胸燥屎，大便鞭，旁治宿食腹满，小腹肿痞，诸般难解之毒。  \n\n【用量】普通三五分。  \n\n【禁忌】辛香走窜，不宜多用。  \n\n【炮制】拣去杂质即可。  ', NULL, NULL, '1', '朴消 ', NULL, '7、朴消 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605219645268042, 'CB972D69AEEA035D1E17D6CF02011DDE', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:25:05', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5210, 317, 902000406, '\n【本经原文】味苦寒，主五脏积热，胃张闭，涤去蓄结饮食，推陈致新除邪气，炼之如膏，久服轻身。 吴普曰消石，农曰苦，扁鹊曰甘，名医曰一名芒消。今之硝石。  \n\n 【产地】产于东印度埃及等热带地方及我国西北。投入火中则爆鸣，立即燃烧而发鲜明之焰。\n\n【性味】味苦性寒，无毒， \n\n【主治】硝石主清积热利小便，治五淋。 \n\n【别录】疗五脏十二经脉中百二十疾，暴伤寒，腹中大热，止烦满消渴利小便，及瘘蚀疮，能化七十二种石。 \n\n【甄权】破积散坚，治腹胀，破血下瘰疬。泻得根出。 \n\n【大明】含咽治喉痹。黑疸，周身皮肤眼目俱现黑色，为疸症之最重者。 \n\n【灵胎】消积解癖。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】忌火。 \n\n【炮制】拣去杂质即可。 ', NULL, NULL, '1', '芒硝,硝石,消石', NULL, '6、芒硝,硝石,消石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605219645268043, 'AFC8A8D269FEF4BDAEDF4AD0BB5C707E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:25:05', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5211, 317, 902000405, '\n【本经原文】味酸寒，主寒热，泄利白沃，阴蚀恶创，目痛，坚筋骨齿，炼饵服之轻身不老，增年寿。  吴普曰矾石，一名羽泽，神农歧伯酸，扁鹊咸，雷公酸无毒。歧伯曰久服伤人骨。  \n\n【产地】产我国四川陕甘，我国南省诸山亦多有之，色白净者为明矾。 \n\n【性味】味酸性寒无毒。 \n\n【主治】矾石为收湿解毒止血要药，功能除湿化痰，追延坠浊，主明目坚齿，除风杀虫，蚀恶肉，生好肉，治蛇虫咬伤。 \n\n【别录】除固热在骨髓，去鼻中息肉。 \n\n【大明】除风去热，消痰止渴，暖水脏。治中风失音，和桃仁葱汤浴可出汗。 \n\n【甄权】生含咽津治急喉痹。疗鼻漏鼻血，瘰疬疥癣。 \n\n【宗奭】又名枯矾。贴嵌甲牙缝中治血出如衄。 \n\n【灵胎】敛气固精，杀虫止利。 \n\n【用量】普通内服数分至一钱，外用无定量。 \n\n【禁忌】虽可常用无所忌，但不可多服。 \n\n【吴克潜】编药性字典曰矾石用之甚广。今南方人多用置水缸中以解毒，其水澈底澄清。陈师古曰矾石之用有四，吐利风热痰延，取其酸苦涌泄也。治诸血痛，脱肛阴挺疮疡，取其酸涩而收也。治痰饮泄痢，崩带风眼，取其收而燥湿也。治喉痹中蛊蛇虫伤蛰，取其解毒也，矾石经火炙后为枯矾，研细用做敷扑良，渗小儿脐眼，防腐收湿，矾石治一切疮痈恶毒，或 为蛇虫所伤，配黄蜡二倍，溶化研细，外用亦可内服。其它配合方剂很多，举凡矾石色暗者不入药，以白而明最佳，故色白者曰白矾：色光明者曰明矾。 \n\n【倪注】枯矾可与麝香合用，因为麝香无孔不入，配合之则可去脑鼻之间的风寒与瘀伤。 \n\n【炮制】取净生白矾，研粉即得。 枯矾：  \n\n【炮制】取净生白矾，置炽锅内，煅至全部泡松呈白色蜂巢状，取出放凉研粉即得。二矾极酸，变为涩味，酸则收而引津，涩则止而不流。 胆矾：生铜中，有酸木之味，正得铜中金收之性，金性缓，能平木气。  ', NULL, NULL, '1', '涅石,羽泽', NULL, '5、涅石,羽泽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 605219645268044, '7AF151E125ECAC50C9E6F1C1F1A169F9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-10-26 22:25:05', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5212, 53, 904000403, '        太阳病，或已发热，或未发热，暂且不管，“必”，就是一定有的症状，一定有恶寒，体痛，呕逆，脉阴阳俱紧者，这就叫作伤寒。或已发热，或未发热，这在临床上有的时候有，有的时候没有，因为人的体质不一样，体质好的人，得到伤寒会发热，体质不好的人，看不到发热，病直接进到里面了，但一定有的症状是恶寒，怕冷的现象。水停在表面上，会感觉到冷，水停滞，造成温度下降。人的神经，血脉系统，都是一直在循环，突然这部分被寒束到，产生障碍，神经没有好的营养去供应，病人会感觉到痛，这个痛就是因为压力而且冷，所以要把水排掉，如何把水排出去，同时把病毒排出去？因为人有百分之六十以上的水分，如果攻的太过，结果感冒好了，人也脱水了，所以在排水的同时，要把丧失的津液同时补足。 为什么会呕逆？一般来说，当病情进入少阳的以后，会有呕逆的现象，但在这里并不是进入少阳，而是病人本身肠胃有问题的人才会产生的现象，或平常肠胃很好，而大饱大饥之后或吃坏肚子上吐下泻的时候，感冒进来，才会呕逆，呕逆就是东西吃不下去，并不是每个人得到伤寒都会有呕逆的现象。脉阴阳俱紧，阴阳脉，过去有两派说法，一说左手为阴，右手为阳；左手为血，右手为气。一说轻轻摸到表面上跳得紧数强，重按到骨边，跳的更强，表是 阳，里是阴，这二说法皆可。现在我们来做个总结，所谓阴阳脉，所谓寸为阳，尺为阴，这在临床上是最有用的，所以临床上摸到寸脉与尺脉都是又浮又紧，就是脉阴阳俱紧。  \n\n       太阳病，有一种会流汗，没有恶寒，但风吹的很难过，病人会发热、发烧（中风），有一种没有流汗、恶寒、怕冷、全身骨节酸痛，这是因为水排不出去（伤寒）。中风为什么不会骨节酸痛，因为水排得出去，所以滤过性病毒千百种，只分这两种就好了，按症处方，就是辨症论治。  \n\n        若以节气来看，“从霜降以后，至春分以前，凡有触冒霜露，体中寒即病者，谓之伤寒 也。”所以在霜降到春分这段期间，被寒气所伤，就称为伤寒。因为寒气乃是冬天的正气，所以被冬天的正气所伤而产生的伤寒，并非疫病，所以不会传染。  \n\n         在南方一样有伤寒证，在美国佛罗里达很多，例如长时间在冷气房工作，或是游泳突然跳进冷水中，都可能出现伤寒证。如果是身体很强的人，吹了冷气，可能只是皮肤痒一下就好了，所以平常要保养身体，除了食物选择以外，就是要把肠胃保养好；人体要清灵，天是虚灵，人是清灵的意思，就是食物进入身体，二十四小时就要排出去，新陈代谢很好，就是  “清”而能够“灵”动。  \n\n我们临床使用麻黄或桂枝，就是看病人有汗或是无汗，就是中风与伤寒这两种病症的区别。', NULL, NULL, NULL, NULL, NULL, '3、太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名 曰伤寒。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613712719196230, '4C9C270A1986523BF2F6E442CD63C573', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 14:23:29', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5213, 53, 904000402, '        太阳病的中风证，就有下面的症状：发热、汗出、恶风、脉缓。如果肠胃功能很好，体力很好，也会有得到感冒的时候。如果不动，不会得，如果运动后，汗大量流失的一剎那，突然受风、受寒，感冒了，就会摸到很浮的脉，浮的脉，就是有外证，有表证。所以如果摸到很浮，很紧的脉，就代表这病人的身体很好。所以如果摸到浮缓的脉，就代表这病人的身体素虚。为什么会发热，免疫系统产生相抗的时候，会有热能散发出来。这里的汗出是主证，是一种“病汗”，平常没事，天气很好，大家都不流汗，只有他一个人流汗，也是一种“汗出”的症状。这里的发热，有时候会发热，有时候没有发热；中风证的发烧，一般不是高烧，温度不是很高。所谓的风，并不会把皮肤毛孔收敛起来，寒，会把皮肤毛孔收敛起来。有一种滤过性病毒，会引起病人的皮肤毛孔收束起来，病人完全没有汗，嘴巴讲好冷，摸身体是滚烫的，热能散不出来，但是病人感觉是冷的，这种就是。有一种是病人会流汗，但是汗流出来，病人的症状并没有纾解。怕风，就是不喜欢吹到风，就是恶风。  ', NULL, NULL, NULL, NULL, NULL, '2、太阳病发热，汗出，恶风，脉缓者，名为中风。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613712719196231, '99F3B375F571CC84A239316ED1296C62', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 14:23:29', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5214, 53, 904000410, '        头痛，如果自己会好，一个星期就好了，感冒到第七天还没好，就要赶快去看医生了。太阳病，有时候传阳明或少阳，或从阳明进入少阳，或从少阳进入阳明，不一定的，如果太阳病，在还没到足阳明之前，先扎足阳明本穴足三里就不会传了，在还没到足少阳之前，先扎胆经的本穴临泣就不会传了，如果到了第六天满第七天还没好，可能传阳明或少阳了。如果小孩到了第七天还没好，变成恶心呕吐就是传少阳了。阳明热就是大肠经，因为津液干了，大便会堵在大肠里，如果小孩变成烦躁、不吃、东西乱丢、晚上发狂奔走、捻衣摸床，就是传阳明了，阳明壮热其实就是大便的浊气跑到脑子里面去造成的。  ', NULL, NULL, NULL, NULL, NULL, '10、太阳病，头痛，至七日以上自愈者，以行其经尽故也；若欲作再经者，针足阳明，使经不传则愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613752411639877, '93B18581A5B3D5D19BDC1E78819A1314', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:04:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5215, 53, 904000409, '       如果白天得到的病，就是发于阳，过一个晚上，就是第二天了，所以如果足足六天之后，也就是第七天的白天会痊愈，所以说“七日愈”。如果晚上得到的病，就是发于阴；到白天了，才开始算天，所以得病的隔天才算是第一天，足足六天之后，也就是第六天的半夜，会自己痊愈，所以说“六日愈”。不管是阴病或阳病，得到感冒，正常的话，六天一定会好，所以如果感冒不吃药，一个礼拜会好。  \n\n       阴阳二字释义颇泛，以寒热分阴阳，寒为阴，热为阳。以表里分阴阳，表为阳，里为阴。以脏腑分阴阳，脏为阴，腑为阳。以上下分阴阳，上为阳，下为阴。以左右分阴阳，左为阳，右为阴。以气血分阴阳，气为阳，血为阴。以实虚分阴阳，虚为阴，实为阳。其它以身体组织之内分泌液、水分、血浆等有物质者谓之阴，身体之抵抗力、细胞之新陈代谢力、各脏腑之自然机能等无形者谓之阳。  ', NULL, NULL, NULL, NULL, NULL, '9、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳者七日愈，发于阴者六日愈，以阳数七、阴数六故也。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613752411639878, '64A7551592D2E267AED4581334E19D16', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:04:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5216, 53, 904000408, '        风温为病，脉阴阳俱浮，阴阳脉都浮起来的时候，代表病在表，是风温，病人津液本来就比较少，血比较多，在水分少的状况，病人会出现表热，所以阴阳脉俱浮的时候，左右手的脉都浮缓，病在表上面，而且是热；人的水源，当吃了食物到胃里面去的时候，因为胃很热，所有的水会气化掉了，胃是土，土生金，肺主皮毛，水气到了肺，马上就发到表面了，所以喝水，喝热汤的时候会流汗，另外成形的食物会到小肠去，食物中的水到达小肠之后，才能被吸收成为血液循环系统中的养分。身重，为什么身体感觉到很重？脾脏主四肢，主肌肉，身重是脾脏受到影响了，水和血是同源的，身体里面的水有一定的比例，要由水来带动血里面的营养，到身体的关节组织末稍去，如果水不够，血的循环速度就会减缓，人就会感觉到身体很沉重，精神不好，睡觉会打鼾，话都懒的讲了，这就是为什么多眠睡。西医只有验血报告，没有验水报告，所以光看验血报告不是很准。中医如果看验血报告来看病，也是不对的。  \n\n      伤寒论里有汗、吐、下三法，当病在表的时候，属太阳证取汗法，如果病在里的时候，取下法，吐法用的不多，一般病在膈上，就是胸膈以上的时候，才会采用吐法。  \n\n      若发汗者，小便不利，如果这时候再发汗，病人的水本来就已经不够了，汗流太多，当然津液不足，尿就少了。  \n\n      若被下者，直视，失溲，张仲景伤寒论的精神是，病人有表证的时候，一定是先解表再攻里，发表发太多的话，津液会伤到，攻里攻太快的话，津液也会伤到，没先解表却先攻里，结果把胃、小肠、大肠里面所有的东西都清出来，营养顿失，一下子身体里面的营养都没有了。保持在身体的食物一直在消化，一直在提供我们能量，人的身体在慢慢用它的能量，一下子清出来，源头没了就会没有体力，病人眼睛就直了，小便流出来，失溲，这小便，不是小出来的，是漏出来的，肝主血，肝藏神，肝在管眼睛。我们有五分之一的血在肝里面，这血不是固定在里面，而是一直在循环的，突然源头没有了，肝血就枯掉了，眼睛能看到，都是靠肝脏的血供应的，结果眼睛就直直的不会转动了，很危险的。  \n\n       若被火者，微发黄色，北方的人睡在炕上，如果生病了没有用药，用火烤一烤让汗出来，烤出来的汗和用药攻出来的汗是不一样的，用火烤出来的汗。只有津液出来了但是病毒还在里面，所以不要用烤的，火一烤，病人的皮肤表面发黄色，看起来是黄色，其实是血的颜色，血管里看血液是红的。经过一层皮肤，看到的血液的颜色会是黄的，这就告诉你血里面的水  \n没有了，透过皮肤看到的是血的颜色？所以这种发黄，不是肝胆病的发黄，不要弄错了，这种是失水导致的发黄，严重的话，津液丧失太多的时候，脑里面得不到正常的血来滋润，会 发惊痫。肝主筋，筋也靠血来养，没有充分的血来供应，就会抽筋，会时瘛瘲，抽搐一下又松开来，抽搐一下又松开来， 瘈就是筋松开来， 疭就是收紧。若火熏之，一逆尚引日，再逆促命期，错了也罢，还可以救，如果再用火去烤他，血里面的水如果完全没有就完了。打点滴，只能暂时缓解，水还是会从小便流失，一定要从嘴吃下去食物中的水，由肠胃吸收后人体才能受用。  ', NULL, NULL, NULL, NULL, NULL, '8、风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，息必鼾，言语难出。若发汗者，小便不利；若被下者，直视，失溲；若被火者，微发黄色，剧则如惊痫，时瘈疭；若火蒸之，一逆尚引日，再逆促命期。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613752411639879, '4FC18BD10BFC9A7C2E752C060C30184D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:04:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5217, 53, 904000407, '        如果人一直流汗，体液一直在丧失，摸他的身体很烫，这有一个特别的名称就是风温。过去环境不同，是因体力透支造成，例如在我在佛州有一个案例，一个木工在伤寒快痊愈的时候，结果因为工作出汗很多，于是得到风温。现在看到的风温，多是医生开给病人发汗去水的药太重了，补足津液的药太少了，才会看到这种脱水的现象。', NULL, NULL, NULL, NULL, NULL, '7、若自汗出，身灼热者，名曰风温。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613752411639880, '30E4E54024C7A0DA659F3840FEBCA5C3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:04:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5218, 53, 904000406, '       内经：“冬伤于寒，春必病温”，所以温病跟时疫有关系，譬如夏天的霍乱疟疾，在中医再推衍到因此冬天伤于寒，冬天本来是要保护收敛的，结果不小心伤于寒，病没有好，到春天就变成温病，这是内经上讲的。如果我们用二十四节气来计算，从霜降到来年的夏至之前，这一段时间发出来的有热证的病，是因为伤于寒所产生的温病；如果是夏至以后所发出的有热证的病，才能算是热病、或湿热病。  \n\n        临床上看到，如果大量汗流失的时候，例如运动完或工作环境大量流汗的，在这身体  \n水分很少的时候，得到的感冒都是温病，像小儿感冒多是如此，因为病的来源就是太皮了，小儿好动所以津液流失很多。所以张仲景治疗温病的处方，一定都加上很多生津液的药，把津液补足，病人发热而渴，不恶寒者，自身津液本来就不够了，滤过性病毒进来的时候，残余的津液都跑到表面上去了，而津液就是我们的抵抗力，为什么发热而渴？因为津液跑到表面来和病毒相抗的时候，体内津液不够就会令人觉得口渴。为什么不恶寒？人的身上，有百分之七十的水和百分之三十的血，人的体温都是在血里面，所以如果失血过多的时候，会发冷，所以血量不足的时候，会怕冷，如果血里面的水不够，病人会发热，就不会恶寒了。\n\n       太阳病分三种，一为中风，一为伤寒，一为温病。  ', NULL, NULL, NULL, NULL, NULL, '6、太阳病，发热而渴，不恶寒者，为温病。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613752411639881, '3FF7A03B4296F090AF58FA6DAC22134C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:04:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5219, 53, 904000405, '       太阳症状，分中风和伤寒，太阳病进入身体的时候，有的时候是进入少阳再进入阳明，有的时候是进入阳明再进入少阳，阳明证主要的症状是但热不寒，在太阳少阳的时候，有时候还会觉得冷、寒，进入阳明的时候就看不到寒证了，全部是热证。少阳，就是往来寒热，好像打摆子一样，忽冷忽热，一下冷一下热，这是主证。伤寒二三日，阳明、少阳证不见者，为不传也，一进入一条经的时候是一候，就是六天，如果经过了二三候，本来是伤寒无汗关节酸痛，看不到阳明证和少阳证，代表表证还在，并没有传经，颇欲吐，若烦躁者，为传也，很想呕吐、烦躁，少阳证的时候，胸胁苦满，如果想呕吐，有吐的症状、恶心感觉的时候，这就是少阳证才有的症状。阳明证，因为是但热不寒，病人一定会烦躁，烦就是心情郁，心情很不好，压力很大的感觉，躁就是情绪很不稳定，看到人就很火大，很容易发脾气，动作上没有办法定下来，情志上没有办法安定下来，晚上失眠反复，通通可以称为烦躁。所以看到颇欲吐，就是少阳证，看到烦躁的，就是代表阳明证。', NULL, NULL, NULL, NULL, NULL, '5、伤寒二三日，阳明、少阳证不见者，为不传也；颇欲吐，若烦躁者，为传也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613752411639882, 'B39DA37613229119674BE94E4E725871', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:04:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5220, 53, 904000404, '       一开始初得病，是在人体的表面，也就是太阳，如何知道病有没有入里，如果是进入阳明，就是肠胃，阳明无死证，也就是病进入阳明就停住，不会再进，到此结束。如果是进入少阳，就可能继续进入太阴、少阴、厥阴。  \n\n       一日，是一候，差不多不足七天，正确算起来，足足六天，为什么六天？人和大自然是相通的，中医的观念是天人合一，在风水地理上，有节气，从立春到雨水，这中间相隔十五天，如果把十五天当定数，每十五天分成上元、中元、下元，如果把四十五天定数，每四十五天分成上元、中元、下元如此累积起来，在易经八卦来讲，这是宇宙间的东西，在节气上也可以看到，台风来的时候，没有连吹五天的台风，也没有连热五天，到第六天还没改变节气的。大寒，也没有连冷五天的，到第六天一定会热起来，阳会回复过来，这是自然界的现象，世间没有一样东西在转变中间，超过六种转变，所以易经是六个爻，所以一候，是阳六，人的阳数回复回来了，人也是这样反应。脉静者，为不传也，脉静就是脉没有变化，如果摸到脉是浮缓，到第六天还是浮缓，这病不会传经，一直停留在太阳上面，不会再进入里面了，静就是脉没有变。若脉数急者，为传也，如果脉本来是浮缓的，突然跳的很数很急，就是往里面传了，传到少阳或阳明或少阴，不一定的，为什么不一定？临床上绝大多数都是心脏受到影响而使病情传经，例如情志受到影响，因为人的情志不一样，如果正好感冒，却遭小偷，被吓一跳，恐伤肾，就进入少阴了，如果正好感冒，跟老公吵架，怒伤肝，就进入蹶阴了；这就是传经，传到那一部位不一定的。还有一种是被西药所伤，例如吃了抗生素，结果舌苔变成地图舌，就是心脏功能受损了。所以保持平常心，不要吃西药，就算病进来了也只能在表，百病风之始，所有的病刚开始的时候都是风引起的。', NULL, NULL, NULL, NULL, NULL, '4、伤寒一日，太阳受之，脉静者，为不传也;若脉数急者，为传也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613752411639883, '73D25FDFC2FF017BB1BA905B56A4A5AE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:04:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5221, 53, 904000413, '        此条就是中医在辨症寒与热，如果摸病人，身体很烫，病人还要穿衣服，就是热在皮肤，寒在骨髓，这是“$g{真寒假热}”，表面上是热，其实里面是寒，表示病是往里面走的。人的身体里面是纯阴，纯阴里面有阳，六天以后，阳会复出，所以纯阴中间还有阳在里面。如果滤过性病毒跑到很深的身体里面，元阳就会往外散了，造成里面会更冷，因为体力往外散，外面就成为热的。人的身体能保持一定的恒温，就是阴和阳协调，简单说阳多阴少就会发热，阴多阳少就会发寒，这是阴阳的观念。如果寒在里面，里面的阳会往外走，因为阳被挤出来了，所以热在皮肤，寒在骨髓，所以这时候摸病人会身体很烫，而病人还要穿衣服，这是因为冷在里面。\n      如果身大寒，摸病人的身体是冰的，而病人不要穿衣服，要脱掉，就是热在里面，这就是表寒里热，热在骨髓，$g{真热假寒}的现象。 ', NULL, NULL, NULL, NULL, NULL, '13、病人身大热，反欲近衣者，热在皮肤，寒在骨髓也。\n14、身大寒，反不 欲近衣者，寒在皮肤，热在骨髓也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613754118508614, 'CFB91A8F13E8C49F70485F2C568A35FF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:11:56', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5222, 53, 904000412, '        如果得到伤寒中风，吃了药，表证去掉了，病人还不了了，也就是精神萎靡，很不爽，精神还没完全恢复，如果不吃药，十二天会好，如果吃开心汤，心情好，病马上就好了，所以情志上要注意一下。  ', NULL, NULL, NULL, NULL, NULL, '12、中风表解而不了了者，十二日愈。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613754118508615, 'BA2C377B17C6B035048B6AB3BE387187', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:11:56', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5223, 53, 904000411, '       因为病在阳，六天足尽，到第七天的中午，事实是足六天，就是巳时到未时，中午的时候解掉，所以开给病人处方的时候，如果是太阳病，晚上九点吃药下去，十点的时候，症状都去掉了，还有一点头昏，到了明天中午的时候，精神完全恢复回来，就是病完全好了，如果是病在阴，譬如少阴证，到晚上三更半夜，开始找东西吃，就是好了，如果是病在阳，到第二天中午，胃口大开猛吃，就是好了。 ', NULL, NULL, NULL, NULL, NULL, '11、太阳病欲解时，从巳至未上。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613754118508616, '97AA7C8A4C8448558C6D8ED8E26E968B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:11:56', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5224, 53, 904000414, '        伤寒金匮中的方剂，大概有百分之六十的处方都是用桂枝汤做加减，经方家认为桂枝汤是调和阴阳的第一方，这个汤方是古代圣贤历代相传的经方，张仲景将它归经到治疗太阳中风来使用。读伤寒金匮的时候，会遇到三种剂型，有汤剂、散剂、丸剂。什么时候用汤剂、散剂、丸剂？汤者荡也，就是说扫荡的力量很强，取它的迅捷之性。当我们要涤荡五脏六腑的病邪的时候，通关活络的时候、阴阳不平衡的时候，这些情况都用汤剂。怎么知道阴阳不平衡？白天昏昏沉沉，晚上精神很好，就是阴阳不平衡；或者是你跟大多数人不一样，也是阴阳不平衡，例如十个人吃虾子，结果九个人没事，一个人有事，那一个人就是阴阳不平衡。 如果倒过来，吃了虾子，九个人都拉肚子，一个人没事，那就是虾子有问题，或者是那一个 人做了什么事。学中医跟侦探一样要有common sense。还有，病情沉重的时候、病人有痿症、肌肉枯槁的时候、皮肤干枯的时候、要增益气血的时候，都用汤剂。  \n\n       例如桂枝汤，如果做成桂枝丸，结果桂枝丸吃下去等很久才会发汗，桂枝汤一喝下去就  发汗，不一样的效果。煮汤也有技巧，大火煮取其“气”，小火煮取其“质”，发表的药，例如桂枝汤要用大火煮，所有发表的药方都用大火煮。攻里的药、温里的药用小火煮，取其“质”。  \n\n        散剂用在久病，或病在四肢，像是风湿的痹症，或者表里游走的病，都可以用散剂。丸剂最主要的可以逐破积聚，或者不进饮食的人，胃口不好的情况下，可以用丸剂，丸剂药缓力专，效力缓慢但力量专一，可以集中于一处病灶，所以如果病邪扩散全身的时候，就要用汤剂才有办法。例如要打虫的时候，用到乌梅丸，集中攻击一个定点，引诱虫来吃，如果做成乌梅汤，乌梅是用醋泡过两天，乌梅汤又酸又辣又苦，怎么喝？勉强喝下去结果虫没吃到，只有你吃到，虫没事只有觉得很爽。以后会慢慢介绍方剂的运用，有很多技巧在里面。  \n\n       阳浮而阴弱，阳浮者热自发，代表病在表，脉浮在表面上就是热自发，代表身体的免疫系统出来和病毒相抗，阴弱者汗自出，阴弱就是身体素虚的人，本身身体常年不好，瘦瘦的，肠胃不好，身体的固表能力不够，就不能保持身体的津液，而一直往外散，流出来的就是汗，汗是从血里面的水出来的，血因为有水，可以很容易的在身体里面跑，来供应身体里面的能量，表不固的时候水散出去了，相对的血液循环就会受到影响，病人就感觉到啬啬恶寒，一阵一阵的冷，淅淅恶风，风吹得很难过，翕翕发热，一阵一阵的热，要发烧也是一阵一阵的热，鼻鸣、干呕者，这些副证，桂枝汤主之，张仲景的第一个方剂。  \n\n       为什么设计这方子？因为仲圣知道病人津液不断的在丧失，所以桂枝汤证一定有汗，桂枝汤的主证是病人有汗而且恶风，如果无汗，病人感冒发烧高热且完全没汗，就不是桂枝汤证，因为有汗，所以体液一直在丧失，要赶快利用红枣补足，肠胃里面有很多黏液，体液一直在耗散的时候，胃、小肠、大肠的黏液都会跟着出去，红枣表面是红的，里面是黄的，火生土，而且红枣煮出来的汤液黏黏的，所以喝之后，等于是肠胃的津液，举凡在肠胃的津液快干掉的时候，要赶快用红枣补足。为什么用甘草？本草里面写甘草解百毒，但解释不清楚，病人得到伤寒可能已经一段时间了，在感冒的这段时候里，胃口一定不好，因为本身的能量跑去抵抗外邪，能量减少了，肠胃的蠕动就减缓，有很多食物就会坏死在里面，而甘草可以解百毒，可以把食物分解掉，好的留下来坏的分解掉。为什么用生姜？因为肠胃蠕动的能源都跑到表面了，生姜下去马上刺激肠胃所以生姜有发阳的功能，阳就是动能，它能让肠胃马上蠕动，这三种大枣、甘草、生姜下去，跟感冒没有关系，只是固本。  \n\n        桂枝这药可以壮心阳，所以心脏病的药一定会用到桂枝，桂枝一下去的时候，心脏的阳，也就是心脏的动能会加速，血一加速，我们的免疫系统就全部出去了，把滤过性病毒赶出去。但是不能光让动脉加速流动，还要让静脉加速回来，所以为什么用白芍，在神农本草经里面说：白芍轻用的时候，可以补血，重用的时候，可以活血、破血，就是破瘀。所以张仲景只要病人有腹痛，肚子痛，妇人的肚子痛，通通用白芍，芍药重用的时候可以活血化瘀，所以芍药在静脉里面走，可以让静脉的血加速流回心脏。桂枝、白芍这两味让血液循环加速，一加速把免疫系统带出去，很快的把滤过性病毒赶出去，但是加速产生的后遗症是排出汗来，为了怕津液丧失掉，后面又加了三味药同时补足它，并可以同时把肠子中已经坏死的食物分解掉。  \n\n       因为人身上的动脉和静脉是等长的，所以桂枝白芍用等量，胖子用五钱，桂枝白芍等量，都用五钱，瘦子用三钱，小孩子可以开半钱。如果阳不足加重桂枝，阴不足加重白芍，所以可以调阴阳。生姜开两片，不用开三片会太辣了，桂枝已经很辣了，不过辣些也无所谓，辣一下让肠胃的蠕动加强起来。如果病人得到感冒比较久了，甘草就用重一点，五钱，如果只两三天，就用二钱，甘草尽量少些，因为甘草会把其它药的药性减缓下来，甘草在本草里写有缓和的作用。所以有时候为了让药走的快些，不加甘草，炙甘草就是把甘草用蜂蜜炒过，甘草炙过后性很热，所以甘草炙过后可以增加发汗的力量，就会进入胸阳，胸是诸阳的通路，所以炙甘草马上跑到肺上面，马上把阳气发散到四肢，如果小孩吃桂枝汤太辣了，红枣可以加个十枚，让它甜一点？如果不用红枣，吃完桂枝汤后容易便秘，因为汗都发掉了，肠胃里的津液不足，所以后面三味完全是为了保持肠胃功能而设计的。  \n\n      根据清代名医王朴庄的考证，汉制的八两约等于现在的六钱，所以汉制三两约等于现在的2.3 钱。汉制的一升王朴庄说是“六杓七杪”，约是现代的五钱。  ', NULL, '桂枝汤', NULL, NULL, NULL, '15、太阳中风，阳浮而阴弱，阳浮者热自发，阴弱者汗自出，啬啬恶寒，淅淅恶风，翕翕发热，鼻鸣，干呕者，$f{桂枝汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 613755931799622, 'AE0002BB1189257344A645687B6F2904', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:19:19', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5225, 53, 904000416, '        项背强几几，脖子绷得很紧，绷得很紧表示此处的代谢循环系统不是很正常。平常感冒进来的时候，桂枝汤就可以了，但是如果项背强几几，这时就要加点葛根，葛根能升提水液，人体的水从肌肉排到皮肤毛孔，出来就变成汗了，水在血管里面是热的，离开血就变成冷的，肌肉里面有一定的水，表水有时候没办法排出去，就会陷在肌肉里面，等于不正常的水在肌肉，就会硬梆梆的，感觉背后到项部冰冷冷的，这时候靠葛根把水提升上来，然后靠桂枝把水排出去变成汗，这样子肌肉中的水就能正常代谢出去，于是项背强几几就解除掉了。  \n\n        葛根这药可以升水，这水除了把肌肉的水提升到表面上发汗发掉以外，最重要的是葛根可以从肠胃里面一路通出来，还有喉咙很干燥的时候，葛根也可以生津，让下面的津液往上走，上到喉部来。本草写葛根可以通痹、发痈；通痹，肌肉麻痹没有感觉，用葛根；发痈疽，可能是长肿瘤在里面，可能只是发炎在里面很深的地方，不在皮肤表面上，葛根可以把它推出来，所以葛根很好用。葛根可以升水，把水升到头面上来，所以面部中风、口歪眼斜、肌肤麻木不仁，处方里面一定加葛根，葛根可以通痹，让肌肤活络起来，把肌肉纾解开来， 所以葛根功能是往上升，在头、面、颈、脖子的部分。葛根有升引水气，解散凝滞之力，故葛根有通痹、解毒、排脓、破血诸功。  \n\n     如果用针灸，下后溪、申脉，大椎放血去热，上下强硬处再拔火罐。只下后溪、申脉也可以。', NULL, '桂枝加葛根汤', NULL, NULL, NULL, '17、太阳病，项背强几几，及汗出，恶风者，$f{桂枝加葛根汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614064494166085, '596EA1F649156181D4229128C33E282F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:14:51', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5226, 53, 904000415, '        桂枝汤证就是这四个症状头痛，发热，有汗，恶风，风吹得很难过，为什么？因为病在肌肉上面的时候，肌肉被束缚住了，皮肤表面的能源（固表力）没了，所以吹了风会很难过，风的性是阳的，阳都是往上走，所以感冒的时候病人会头痛，人正常的阳气一直往上走，如果得了桂枝汤证，肌肉被滤过性病毒束缚住，使正常的体温无法往外散，阳出不去就往上冲，所以会头痛。发热，是一种本身的抵抗力和滤过性病毒相抗的现象，这四个症状出现肯定是桂枝汤，两个症状出现就可以了，如果临床上听起来是桂枝汤，但里面的病是淋病、梅毒，不一定的，如果症状是这样，桂枝汤下去就好了，只要是症状一样，汤剂都行得通。', NULL, NULL, NULL, NULL, NULL, '16、太阳病，头痛，发热，汗出，恶风者，桂枝汤主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614064494166086, '21574675C85F5421189383C21258FE55', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:14:51', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5227, 53, 904000423, '​        这些都是桂枝汤的变证，如果开药量太过，或喝太急，应该二小时后才喝第二剂，造成汗流太多止不住，汗一直往外流，这病人有恶风，因为表虚，毛孔都开着，小便难，小便少了，因为水都被汗排掉了，所以病人脱水，津液不够了，造成四肢微急，因为四肢都靠水分血液来营养它，一旦不足，就会有抽筋的现象，所以难以屈伸者，这时就用桂枝加附子汤。  \n\n       附子就是玄武，这里的附子是炮附子，附子本身是在中药里最黑最咸的药，附子是乌头的根，平常三年采收的就叫做附子，附子是非常阳热的药，所以叫附子为玄武，附子入肾，生附，就是附子采收后，用明矾泡一下、晒干就入药；附子有毒，因为附子的表皮上黑黑的毛会黏在气管，造成一直咳，所以要刮皮，或用棉布包住。\n\n​         生附子是通经温里寒的，此经指 的是全身的血脉神经的经，一吃下去，全身的血脉神经都会打通。\n\n​         炮附子专门温肾阳的，肾阳不足，小便就会很清白、腰酸、遗精、脸色白黄得很虚弱。肾阴不足，就是肾水不够，精子就不是很好，肾和膀胱相表里，膀胱经是人身体中主表的最大的一条经脉，所以炮附子除了温肾阳还能固表，所以一吃下去，皮肤毛孔马上收起来，一滴汗都不流出去，汗会马上止掉。但是单吃炮附子是不行的，必须加在桂枝汤中，靠桂枝的力量把炮附子带到皮肤表面，才能发挥固表的作用。  \n\n​        破八片大约三钱，这是救逆的，平常两钱就够了，像十岁小孩五分就够了。炮附子就是生附子皮剥掉切片，直接在铁锅上面干炒。  \n\n​      二四条这人就是发汗太过了，表里两虚，汗流不止恶风，就是表虚了，小便难，四肢微急，就是里也虚了，这时可用桂枝汤加附子。  \n\n​      临床上有一种情形，从北方寒冷地区来的病人，天生毛孔腠理比较密实，结果开了麻黄汤给他，他不会发汗，一直在小便，这个时候我们不必硬要发汗。  ', NULL, '桂枝加附子汤', NULL, NULL, NULL, '24、太阳病，发汗、遂漏不止，其人恶风，小便难，四肢微急，难以屈伸者，$f{桂枝加附子汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614071837962310, 'A60D7B777084824675C5E4092D6DE20F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:44:44', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5228, 53, 904000422, '      吐家，没事会呕吐的人，常常会恶心呕吐的，肠胃不好，没事吃完东西会呕酸的人，不要开桂枝汤，因为吐家可能是胃破了，桂枝汤一下去，桂枝芍药发阳的力量很强，血液循环会加速，本来只是胃溃疡的小洞，变成大洞，就吐血出来了，所以桂枝汤不要吃。有胃癌、胃溃疡者，其平素会有胃痛欲吐之证，所以没事胃隐隐作痛、恶心想吐的人要小心注意，不要给桂枝汤。  ', NULL, '桂枝汤', NULL, NULL, NULL, '23、凡吐家，服$f{桂枝汤}，其后必吐脓血也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614071837962311, 'A645898536D0C9546282914B99DC2EDA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:44:44', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5229, 53, 904000421, '       厚朴、杏仁的量和桂枝一样就可以了，杏仁可以加多，李子和杏子的果仁都可以用。喘家，就是本来就有咳嗽，喘包括咳，咳久就变喘。只要是主证是桂枝汤证，有咳嗽或气喘。就先想到桂枝汤加厚朴杏仁。  \n\n        如果得到桂枝汤证，就是太阳中风、有恶风、有汗、头痛，开桂枝汤吃，结果病人喘气， 咳得很厉害，就代表这人本来就是其它问题，这时候就用桂枝汤加厚朴、杏仁，为什么这样?这病人的中焦素有湿热，这湿热是平常累积起来的、就像喝酒的人一样，不用葛芩连汤，用桂枝汤加厚朴杏仁也可以。所以舌苔很黄就是很热，热就是发炎，舌苔很厚，口水很多黏黏的，就是湿，平常就有这种病的人，得到桂枝汤证的时候，桂枝汤喝下去。病人会喘，这时候的处方要同时开去湿、去热的药，有会喘就是肺有问题，所以这热一定是热在肺上面，咳嗽痰黄黄浓浓的，舌苔黄的，就是肺家太热了，这时候加杏仁，杏仁的功能在《本草》上写它可以去肺热，第二能够化痰，第三润肤，杏仁会使皮肤变得很光润，因为肺主皮毛，皮肤毛孔的润泽是靠肺来的，杏仁润肺，所以杏仁是很好的保养的药。去湿药厚朴，厚朴能去脾脏的湿，脾本身就主湿，脾有一定的湿度，湿太过了，用厚朴去收敛它。张仲景的意思就是，如果这人有桂枝汤证，吃了桂枝汤，桂枝汤证清除了，变成咳嗽有点气喘，再拿桂枝汤给他吃，里面加厚朴杏仁，就可以了。反过来说，如果有桂枝汤证还有气喘咳嗽，且咳黄痰，就吃桂枝汤加厚朴杏仁，如果喝完酒回来，得到桂枝汤证，就是酒客病。于此可见仲景之治病，注重新病，其旧恙则兼及之而已。如果本身的旧病没发现症状就不管它，以新病为主，吃药后发起来了，就顺便治。所以有主证、兼证同时出现的时候，以主证为主就好了。', NULL, '桂枝加厚朴杏子汤', NULL, NULL, NULL, '22、若喘家作，桂枝汤加厚朴、杏子仁。 $f{桂枝加厚朴杏仁汤}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614071837962312, '566112478F2D95CE994479741FBE20BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:44:44', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5230, 53, 904000420, '       所谓酒客，就是平常喜欢喝酒的人，酒喝多了，胃的神经都被酒麻痹了，成了习惯以后，吃饭之前一定要先喝酒，等酒精浓度够了，胃才会开始蠕动，所以酒客一定先喝酒才吃饭。酒客一定不喜欢吃甜的，因为酒本身表热里寒，酒喝下去的时候感觉很热很热，这是当时感觉起来热，实际喝到身体里面酒是寒，这就是酒的性。阳热跑到上面，就是胃阳跑到上面了，造成胃阳不够，当化水的力量不够的时候，水会停在胃里面，水停久了，就变成湿，桂枝汤里面有红枣，红枣黏黏甜甜的会增湿增腻；酒客喝酒多伤到胃以后，吃到桂枝的时候胃会感觉到很不舒服，内经中有苍朮加泽泻可以解酒，治酒客病；那如果酒客得到中风证，能不能把苍朮、泽泻加到桂枝汤来治疗?还是不行。因为他已经伤到胃了，桂枝汤加上苍朮、泽泻还是会让胃不舒服。所以喜欢喝酒的人，最好不要用桂枝，这里的以酒客不喜甘故也，这里的甘指的是桂枝，不是炙甘草。  \n\n      酒客的病人，一喝桂枝汤会吐出来，喝桂枝汤会吐的一定是酒客病或是有胃癌、胃长肿瘤人或胃溃疡，所以喝桂枝汤会吐的人，胃一定有问题。酒客不给桂枝汤，可给葛芩连汤，黄芩黄连化湿热，酒量的大小，可看舌苔，如果舌苔浊腻，乌乌浊浊的，又黄又厚，这种不用桂枝汤，正常的舌头的颜色是很红清很亮，很新鲜的感觉，舌头上一层薄薄的白苔，舌苔 薄白就是胃消化能力比较强的。  \n\n       平常桂枝汤可做补药，张仲景认为药就是药，所以张仲景的处方，大多开的是药，因为人的阴阳是平衡的，阴不足的时候，不用滋阴要壮阳，阳一壮就把阴拉起来了，阳不足的时候，也是要壮阳的。所以张仲景都是在阳上面治疗，不管病在哪里，开的大多是用阳药。 ', NULL, '桂枝汤', NULL, NULL, NULL, '21、若酒客病，不可与$f{桂枝汤}；得汤则呕，以酒客不喜甘故也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614071837962313, 'BC218FA670610CB39C9B74AF7DB8471E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:44:44', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5231, 53, 904000419, '     中风束肌的状况，就是病人有恶风，有流汗的现象，所以小孩感冒，一摸有流汗，就是桂枝汤证。\n     如果病证在肌，就会有汗，如果病证在皮肤表面上，寒束到表面了，这时候一滴汗都没有的。这就是寒证，若其人脉浮紧，浮就是表，紧代表寒，寒就代表痛。\n     脉分上、中、下，上就是皮表，就是诊他浮，中就是皮肌，皮和肌肉之间，下就是肌骨，骨和肌肉之间。按到骨边了，就是沉，如果按到骨边，就是沉，如果按到骨边，发现脉很紧，这就是沉紧，沉就是里，紧是寒，就是里寒。\n     若这人脉浮紧，就是表寒，不是表风，因为表风会有汗且脉浮缓，表寒，发热，汗发不出来，病人感觉冷，寒都在表，这是伤寒，应用麻黄汤，误用桂 枝汤，桂枝汤是解肌的，让血液循环加速，桂枝的力量达不到皮肤表面，力量只能达到肌肉，结果血只到达肌肉，不但汗不能出来，病人会增逆，会更烦躁。因为血出去更多，血都集中在四肢上，胸口的血液减少，病人会觉得胸闷甚至气喘。  ', NULL, '桂枝汤', NULL, NULL, NULL, '20、$f{桂枝汤}本为解肌，若其人脉浮紧，发热，汗不出者，不可与也。常需识此，勿令误也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614071837962314, '3EF380D4D49009A5D1EC84BEE77A0251', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:44:44', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5232, 53, 904000418, '       一般的原则来说，当病邪在表，例如有头痛、项强、脉浮、恶风、恶寒、发热等，我们用汗法，当病在上膈，例如吃坏东西、胸腔痰涎很多、鼻黏膜痰很多，我们想要把病邪清掉，用吐法；当病邪堵在下焦，我们用承气汤类攻下，也就是下法。  \n\n       如果是太阳中风，给桂枝汤了，已发汗以后，如果医师再误用吐法、下法、温针，结果病人病一直不解，此为坏病，桂枝汤就没用了，这时候要看它的脉证，到底有什么问题，照理原本桂枝汤就可以解掉了，但被吐、被下、被温针，所以这时候桂枝汤证已没有了，随证治之，随所变之症状依法治之。临床上，有时候处方与治法是对的，但是病人的症状没有解掉，这时候要想到可能有别的问题在里面，要做到知犯何逆，随证治之，就要熟悉金匮治疗杂病的原则。  ', NULL, NULL, NULL, NULL, NULL, '19、太阳病，三日，已发汗，若吐、若下、若温针，仍不解者，此为坏病，桂枝不中与也。视其脉证，知犯何逆，随证治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614071837962315, '2BCEF576D131A96B7DE32265BB6EA5A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:44:44', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5233, 53, 904000417, '        张仲景立法：第一原则，有表证时不可攻里。张仲景讲的汗、吐、下、和，有表证的时候，就是刚开始感冒，病还在表的时候，也就是在太阳的时候，要解表用汗法，有表证的第一禁忌，绝对不可攻里，也就是不可攻下，所以太阳病解法是发汗，下之后，就是医师误攻下，本来是桂枝汤证，如果误用了承气汤，在大下时候，血会往下集中，也就是血往下的力量会很强，往下的力量很强，它回头的力量也会很强，流回心脏的力量也会很强，一流回心脏，气就往上冲，下去很快，回来也很快，就代表心脏的力量很强，肠胃很强，体力很强，再给桂枝汤，没关系，此误下未伤也。第二，如果不上冲，被下而气不上冲，此误下成伤也，这时候就不可以给桂枝汤了。  \n\n        但是在临床上的情形，有时候，发表与攻里可以同时使用，例如病人现在有表证需要发表，但是已经便秘了两三天，这个时候，我们可以开两个药方给病人，告诉他先吃这帖药，等表证去除之后，再吃另外一帖药把便秘治好，省得病人舟车往返。如果遇到病人已经一个礼拜没有大便，现在有表证，也许是中风证或伤寒证等等，我们也可以把发表的药与攻里的  \n药同时开在一个药方里，发表与攻下同时进行。  \n\n张仲景误下的必辨证：  \n          一、表寒下陷，如果表面是寒证的时候，误攻下，会造成利下不止。 \n          二、表热下陷，就是表阳下陷，会造成胁热痢，就是大便很脓稠很臭，就是病往肠胃里面跑了。 \n          三、寒热并下，表同时有寒热，攻下的以后，造成大小结胸，用陷胸汤。 \n          四、表寒，攻下后没有痢下不止，就停在胃的地方，心下就是胃，造成心下痞，用泻心汤。  ', NULL, '桂枝汤', NULL, NULL, NULL, '18、太阳病，下之后，其气上冲者，可与$f{桂枝汤}，用前法；若不上冲者，不可与之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614071837962316, '086CB4373189B430CE471EB888168A31', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:44:44', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5234, 53, 904000424, '        张仲景说太阳病就是太阳中风，就是桂枝汤证，发表就好了，如果医生开错了，开成攻下的药，造成病人脉促，胸满者，促脉就是搏动数时一止，就是一下跳得很快，突然没了，脉摸不到，过一下又回来了，胸满，因为攻下的药一下去，身上的血大量往下走，往腹腔走，回流的力量会增强，一回流到心脏的时候，第一个会胸满，就是心脏有胀满的感觉。为什么脉促，因为下去的速度很快。而心脏的血来不及喷，下面的血已经走了，这时候中间有间歇性的停下来，所以脉会跳跳跳很快，突然停一下，遇到这种情形，病人桂枝汤证还在，就把桂枝汤的芍药拿掉，否则静脉流回来的太快了，心脏喷出去的力量不够，所以桂枝去芍药汤，用桂枝加强心脏喷出的力量，拿掉芍药让血回来慢点，整个平缓下来。若微恶寒者，桂枝去 芍药方中加附子汤主之，如果病人除了刚刚的现象还有点怕冷，怕冷代表阳虚了，阳就是人身上的活动力，新陈代谢的力量、生命力，这恶寒，是从里面冷出来的，病人身体里面一阵一阵冷，就是心阳虚了，因为攻下，津液伤太多了，这时候加些附子下去，补心阳的药，所以心脏病的药里面绝没有芍药，只要有胸满的症状，张仲景一律去白芍。  \n\n脉法：  \n\n       一、胃：病人的脉摸上去，如何知道病人的胃气，就是消化系统好不好，正常的脉一息四至，代表有胃脉，不管摸到表面或骨边胃脉都是要一息四至，像癌症的病人脉一息九下十 下，急数壮热，就是胃气没了，所以第一要有胃脉。  \n\n      二、神：就是脉弹起来要有力，脉管是中空的，摸下去弹起来要有力量，摸脉的表面上就是摸气，摸脉就像摸水管，要压压看，摸到脉里面就是知道血足不足，如果摸到芤脉，感觉就像摸葱，扁扁的中空的，就是贫血了，所以脉的弹性就是神。  \n\n       三、根：摸脉的时候，寸脉关脉都没了，尺脉还有一点点，就还有救，病人还不会死。  \n\n       正常的脉，要常年的一息四至，冬天，如果摸到弦脉，而且是一息六至，肝有问题，弦脉多胃脉少，就是肝有问题，如果摸到毛脉，轻飘飘的轻按才有，重按就找不到了，像羽毛一样，肺有问题了。如果摸到洪脉，很洪大速度很快，或一息二三至，心脏没有力了，心脏有问题的时候，寸关尺的脉会变得很洪，脉形变得很大，但是如果是夏天摸到洪脉，且一息四至就是正常的。如果摸肾脏的脉，它是沉脉，结果春夏秋冬都沉在骨边，如果跳的速度很缓，表示已经没有胃气了，如果一息四至，代表肾脏功能很好。如果一息六七下，肾脏有问题了，肾结石，尿毒…。', NULL, '桂枝去芍药汤,桂枝去芍药加附子汤', NULL, NULL, NULL, '25、太阳病，下之后，脉促，胸满者，$f{桂枝去芍药汤}主之。若微恶寒者，桂枝去芍药方中加附子汤主之。 $f{桂枝去芍药加附子汤}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614072764940358, '2C8E39F47E2FC4BA1D4274DC5EFCEA1B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:48:31', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5235, 53, 904000425, '       太阳病，得之八九日，得到一段时间以后，如疟状，就是忽冷忽热的现象，发热、恶寒、热多、寒少，发热，又会怕冷，热比较多，寒比较少，就是这人的抵抗力比较强，其人不呕，清便欲自可，病人不呕，且大小便很正常，张仲景在伤寒论中言及病在刚开始的时候，所得的是太阳病，如果病进入少阳的时候，病人马上会产生呕，病进入阳明的时候，病人会便秘或燥渴。所以如果有呕，病就是进入少阳了。如果口渴，大便有问题了，就是进入阳明了。所以其人不呕，清便欲自可，就是这个病不在少阳，也不在阳明，病还在太阳。一日二三度发，有的时候一天两三次发，突然发热，突然发冷，如果脉微缓者，脉慢慢缓下来了，本来脉是浮弱俱紧，现在一息四至，为欲愈也，表示这人快好了。望诊上可看眼睛的眼白，某一段开始黄，就是身体要恢复了，黄是脾胃的颜色，胃气回来了，只有一点点黄，就不用吃药，让他慢慢恢复；如果脉微而恶寒者，此阴阳俱虚，脉跳的很弱，一息二三至，跳得很慢，代表身体的内脏功能消弱了，而且感到身体里面一阵阵冷出来，这是阴和阳都虚，身体虚掉了，这个时候，千万不可以发汗，或攻下，或用吐的。  \n\n       面色反有热色者，就是脸色发红发赤，这病还没有解掉，以其不能得小汗出，因为不能得汗出，所以身必痒，宜桂枝麻黄各半汤，此条说如果要用汗法的时候，一定要先确定病人有足够的津液，体力很够，才能去发汗，病人脉很微弱，代表病人津液都没了，本身身体很虚，再去发汗，他会更虚弱，面色反有热色者，还有热就是感冒还没完全去掉，代表还需要服药，为什么不能得小汗出，就是汗已经离开汗腺，但是还没离开皮肤表面，停在皮肤下方，风吹一吹，皮肤毛孔封到了，就开始痒了。所以洗完澡或平常没事，风吹皮肤会痒的，其实在痒的时候，发微汗就可以了。张仲景设计桂枝麻黄各半汤，此汤发汗的时候，不会把正常的津液发掉，只把皮肤下面的多余水排掉，所以会用到桂枝麻黄各半汤的，一定有发痒的现象，就是表汗没有发透，光用桂枝汤，力量达不到皮肤，这是就把麻黄拿出来了，所以是桂枝麻黄各半汤。有时候我们也用发汗的方式来利尿，就好像用吸管吸水，一旦把上端放开，下端的水就流出来了。发汗的时候都是用热药，更热的药例如说硫磺，消水肿的力量更强。  \n\n      麻黄又名青龙，麻黄在药房中，拿出来是一节一节细细的，像牙签一样，青色的，麻黄有节枝的，麻黄的节可以止汗，节要拿掉，麻黄的枝可以发汗，所以用于发汗的时候，要去节，像当归一样，当归的身补血，但是当归的须是破血的。所以怀孕的人吃当归身是补血，吃当归须是堕胎。', NULL, '桂枝麻黄各半汤', NULL, NULL, NULL, '26、太阳病，得之八九日，如疟状；发热、恶寒、热多、寒少，其人不呕，清便欲自可，一日二三度发。脉微缓者，为欲愈也；脉微而恶寒者，此阴阳俱虚，不可 更发汗，更下，更吐也。面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜$f{桂枝麻黄各半汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614112764973126, '022D5FDBFBBFA8A77BE020711D1C78C4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 17:31:16', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5236, 53, 904000427, '       服了桂枝汤之后，没有流汗，脉反而洪大的，这就是桂枝汤的力量不够，病人心脏的力量不够，要发发不出来，力量发不到肌表，还在胸腔里面，脉管变大，血一直往外冲，遇到这种病人再给他桂枝汤吃，如果出现如疟，就是忽冷忽热的现象，就是风寒都有了，桂枝汤证是不会有忽冷忽热的现象，桂枝汤的症状是有汗、恶风、头痛、日再发者，一天发一次的，汗出必解，这时用桂枝二麻黄一汤。  \n\n桂枝麻黄各半汤、桂枝二麻黄一汤如何区分：  \n\n      如果病人发热发冷的时候差下多，发热一个小时完就开始发冷一个小时，就是桂枝麻黄各半汤。  \n\n      如果病人发热的时候比较多，发冷的时候比较少，代表病人的元阳很足（免疫系统足），这时桂枝加重，麻黄减少，所以桂枝二麻黄一汤，桂枝三，芍药二，麻黄一。 ', NULL, '桂枝汤,桂枝二麻黄一汤', NULL, NULL, NULL, '28、服$f{桂枝汤}，不汗出，脉洪大者，与$f{桂枝汤}如前法，若形如疟，日再发者，汗出必解，宜$f{桂枝二麻黄一汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614426735448134, '73C6AA0DB356F3D7F6A3AD216F43D597', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 14:48:49', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5237, 53, 904000426, '        如果太阳病，开桂枝汤吃，没好，结果病人反成烦躁，先刺风池、风府，再给桂枝汤就好了。为什么会烦躁?因为病人本身就是虚的，虚在心脏，吃了桂枝汤之后，桂枝是发表的，结果发表的力量不够，就停在这地方，头是诸阳之会，所有的阳都会在头部，身上所有的阳气、动能出来的时候，一定先给头部，到头部之后，才会灌到四肢上去，到头部的力量不够，就停在胸口，扎风池、风府，就是通关活络，让它能通上去，让桂枝汤能发表。  \n\n        汤剂内服，每见有烦、或闷、或眩、或惊惕、寒战等现象，有两种情形：\n       一、为药不对症而引起之变病。\n       二、为服药而起之瞑眩现象。所谓药石不瞑眩，厥疾不瘳，此种瞑眩症状，为正邪相争之现象，药证相合。所以如果处方开得好，药吃下去，头不瞑眩，病不会好的，感冒，吃完药，胃气大多在白天恢复，如果是阴证，病人瞑眩的时候，大多在晚上半夜的时候，半夜胃气恢复，瞑眩就像针灸引起的晕针，这种状况出现时，表示一次就好了。', NULL, '桂枝汤', NULL, NULL, NULL, '27、太阳病，初服$f{桂枝汤}，反烦不解者，先刺风池、风府，却与$f{桂枝汤}则愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614426735448135, '74FE6983BC6DCB04C58FC5F114C5664E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 14:48:49', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5238, 53, 904000428, '       服桂枝汤以后，病人大汗出后，大烦渴不解，脉洪大者，白虎加人参汤主之。这就是由太阳证进入阳明了，病人原是桂枝汤证，喝第一碗时，就好了，结果把剩余的药都喝了，可能炙甘草、生姜、大枣剂量不够，造成津液丧失了，也就是服用桂枝汤过量，产生之后遗症；也可能是病人太晚喝桂枝汤来发汗，结果病邪进入阳明而化热，或是病人来找你的时候，已经快要进入阳明了，所以喝完桂枝汤，就转成白虎汤证。桂枝汤利用肠胃的津液来发汗，因为里面已经用炙甘草、生姜、大枣来补肠胃中的津液，因此不会使体内津液耗损而产生白虎汤证；但是如果是服用麻黄汤过量，或麻黄汤中的杏仁不够，使得肺中津液不足，就比较容易转化成白虎汤证。  \n\n        阳明证分经热和腑热，经是血脉神经，腑是肠胃消化系统，如果力量过强于是发汗发太多，造成血管里面的水不足了，便产生经热，就是白虎汤证，如果发汗的时候，把肠胃里面的津液都发掉了，造成大便干掉了，就是腑热，也就是承气汤证。  \n\n        白虎汤的白虎就是石膏，石膏是清凉润肺，阳明经热的时候，用来退热的，病人病进入阳明后，病人显现的阳明症状一定是但热不寒，持续的发烧，不会有冷的现象，不管是经热或是腑热，尤其是在黄昏的时候，下午三点到五点，病人开始发壮热，看舌苔黄黄黑黑的，整个嘴巴干的，如果没有大便，就开承气汤，如果大便很好，就知道腑里面没有热，热在血里面，就用白虎汤，所以血里面的水不够的时候，用白虎汤去滋润。由于人身体的体热在血里面，所以手术失血的时候或大量失血的人，会发冷栗，一般状况，如果发烧、嘴唇干裂，白虎汤就好了，烧就退了。  \n\n        大汗、大烦渴、脉洪大，方书称为阳明经病；谓阳明主里，阳明病即主病在里，且主实热。故以白虎汤清高热为主治，加人参防心脏之衰弱，补助津液之消耗。阳明病有经证，有腑证。经证者，热在神经血液二系，肠胃未结实。经证以白虎汤为主方，本条是也。腑证者，病在肠已结实，则以承气为主剂。', NULL, '桂枝汤,白虎加人参汤', NULL, NULL, NULL, '29、服$f{桂枝汤}，大汗出后，大烦渴不解，脉洪大者，$f{白虎加人参汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614430427029574, 'C6C37A46A7AAFF4EBC5BF656CFB21E6E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 15:03:51', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5239, 53, 904000429, '        平常感冒不会有烦躁的现象，烦躁是因为肺里面太热，肺藏魄，魄主静，所以肺阳很正常的时候人很静，过热的时候，魄就失守了，病人才会有烦躁的现象。一般肺很燥热的时候，给的处方就是石膏，石膏色白专门去肺热，肺热去掉以后，胸阳才能回头。而且这种烦躁的现象，都发生在半夜的时候，发热恶寒，热多寒少，表示病人有表证，脉微弱者，此无阳也，就是告诉你，小心点，张仲景在开处方，给病人发汗剂的时候，一定先检查病人有没有条件发汗，本来已经虚掉了，一发汗就更凶，如果病人有烦躁，脉微弱，就代表里面虚掉了，也就是津液不足了，就是因为津液不足，所以病人才会肺过热。肠胃的津液，土生金，津液就像云雾一样排到肺上面，当津液少了，摸到的脉就会变的微弱。阳的作用在于固守阴，阳气 要固而密，阴才会停在里面，如果阳不足，又发汗，阳会丧失更多，会汗出过度。  \n\n        人的胃气不动，正常的脉一息四至，代表胃气很足，如果脉一息二三至，脉很弱，代表胃的功能没有了。代表肠里面的津液没了，上面的肺像太阳一样很热，很燥热，这就是无阳，不可以发汗，在给病人发汗的时候，先看看舌头，很干燥的就不可以发汗，舌头的津液就是从肺上面来的，此条辨就是病人里虚的状况，津液不够，又有表证的时候，就用桂枝二越婢一汤，是桂枝二麻黄一汤的变方。杏仁换石膏，桂枝二越婢一汤是麻黄和石膏在并用，石膏能清肺热，让上焦虚热降下来，所以不会发汗。临床上看，会用到桂枝二越婢一汤的，还有一种情形，忧能伤肺，心胸很狭窄，怕死，烦躁，嘴巴干的，查又查不出病来，因为心里有病，所以一种是外表看到运动过量或津液丧失掉了而无阳，一种是心里胡思乱想的人。  \n\n       桂枝二越婢一汤前面是桂枝汤，麻黄少用些，桂枝用三，麻黄就不超过二。石膏可多用些，能去肺热，这里的烦躁最主要是脾土不生金，所以桂枝、芍药、甘草、生姜、大枣可以解肌健脾阳，因为他的脾湿不够，所以病人如果津液不足，病人有表证，就可考虑桂枝二越婢一汤。病人情绪烦躁，半夜不能睡觉，胡思乱想，就是标准的桂枝二越婢一汤  ', NULL, '桂枝二越婢一汤', NULL, NULL, NULL, '30、太阳病，发热恶寒，热多寒少，烦躁，脉微弱者。此无阳也，不可发汗，宜$f{桂枝二越婢一汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614440998883397, '84C2E244D8BF9D5F60B3F019A05D5F63', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 15:46:52', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5240, 53, 904000430, '        服了桂枝汤后，或桂枝汤喝完后又攻下，病人仍头项强痛，一阵一阵的发热，没有汗，心下满，微痛，小便不利者，桂枝去桂加茯苓白术汤，张仲景讲的心下满和胸满不一样，胸 满就是胸部胀满的时候，指的是整个胸，静脉流回心脏的速度太快了，所以桂枝汤把芍药拿掉，所以有胸满要去芍药。心下满，张仲景讲的是心的下方，就是胃，胃里面难过，感觉胃不舒服，胃里面胀胀满满的。此三一条就是桂枝汤的变证。  \n\n       平常人吃桂枝汤，吃下去就好了，有一种人不会好，就是他本身有中湿的人，中焦的地方太湿了，脾主湿，脾在胃左侧，脾整个都是湿，白白的津液都存在脾脏里面，中湿太盛的时候，脾脏会没有蠕动且撑大，胃一蠕动就顶到脾，所以病人就会心下满，感觉到胃胀的现象，实际胃没问题，是胃的蠕动过不去，被脾脏压到了，这脾湿是素有的，平常舌苔又白又厚，或是肚子比较大，或是大便比较黏稠，就是中湿。正常的舌苔是薄白的，桂枝汤里面没有去湿的药，张仲景对中湿的病人，一定是利小便。为什么加白术?白术这药就是中药里面专门去湿的药，而且还专门去中湿，所以在《本草》写白术是燥剂，所以白术放着，一下就变成硬硬的，湿就是黏液，糖尿病的病人，四肢末梢如果有破洞，就不会收口，西药都是用消炎的药，中医认为炎就是热，石膏、黄芩、黄连都是消炎的药，但是在消炎的同时，还加了去湿的药，伤口流出来的脓，黏黏稠稠的体液一直往外流，臭臭的，就是坏掉的湿。如果把去湿的药和消炎的药并在一起，就是最好的外科敷剂，西药只有去热没去湿，所以不会收口。身体的中湿在里面，不能用发汗发掉，所以小便利掉，白术是燥剂，但是湿不会凭空不见了，用白朮集中，然后加茯苓，茯苓就是利尿剂，茯苓专门健脾整胃，把中焦的水消导出来的药，所以茯苍白术等量，胖子茯苓开六钱，白术就开六钱，如果白术开太多，就会太干了，如果茯苓开太多，会把正当的津液利掉了，所以白朮茯苓都是等量在用的药。常常如果胃口不开，很可能是中湿太盛了，常常用茯苓白术把湿用小便利出来，此方如果是去芍药留桂枝的话，若桂枝用太重，这湿就不是从小便排掉，而是从汗发掉的，结果会使湿往上走，脸会红得跟桃子一样，这就是为什么去桂枝而不是去芍药，因为此处方是要利小便，所以只要芍药就好了，因为芍药可以止腹痛。  \n\n       茯苓和茯神，都是长在松树的正下面，只要树根有被山猪咬过的，它的下方就有茯苓，附在松树主根的是茯神，附在松树支根的是茯苓，很大黑黑的，剥开来里面白白的，好的茯苓切开来，里面可以看得到筋，拿到灯光下看，可以看到筋，茯苓用在消导利尿健脾的。茯 神常常用在失眠睡不着、定心剂、宁心用的。  ', NULL, '桂枝汤,桂枝去桂加茯苓白术汤', NULL, NULL, NULL, '31、服$f{桂枝汤}，或下之，仍头项强痛。翕翕发热、无汗，心下满，微痛，小便不利者，$f{桂枝去桂加茯苓白术汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614445794017350, '933DCDF23A71A9BC06921ED28F214730', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 16:06:22', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5241, 53, 904000431, '       伤寒，脉浮起来，代表病在表，自己会流汗，就是太阳中风的现象，如果小便数，心烦，微恶寒，照说流汗流多了，小便应该不多，只是中风证，不会有心烦，但是现在心烦，微恶寒，反与桂枝汤以攻其表，此误也，此条在说给病人桂枝汤时要小心，病人里面已经阴虚了，汗流出去，小便又流出去，津液一直在丧失掉，代表里虚已经很甚了，怎么知道里虚很甚，第一心烦，第二恶寒，体能一直在丧失，体温跟着在下降，病人会感觉到稍微怕冷，就好像失血一样，血水同源。实际上这个冷是里虚引起的，所以这微恶寒，病人感觉从里面冷出来的，这时候再用桂枝汤攻表，再发汗，津液会伤得更多，病人会更虚，如果这样，得之便厥，病人手脚冰冷，所以如果给病人喝桂枝汤，会手脚冰冷的，原来这病人本来就是阴虚的人，就是津液原本就不够的人，桂枝汤一发表，津液更不够了，所以得之便厥，咽中干，津液都没了，当然咽中干了，烦躁，胸阳也没了，吐逆，胃里面的津液都没了，会有反胃的现象，谵语，脚挛急，这时候知道里阳不够了，就以甘草干姜汤与之。  \n\n        甘草干姜汤，就是误饮桂枝汤的时候，救急的处方，甘草、干姜这两味药专门是健脾阳的，马上让脾脏恢复功能，脾脏的阴虚掉了，阴就是脏，虚掉就是没有力了，无津液，功能衰退，所以就是脾脏蠕动变缓，因为脾主四肢，这时候会手脚冰冷。肠的津液不足，利用炙甘草，甘草被蜂蜜炙过以后，就变成厚味带着苦味，除了会把肠的津液补足以外，也能够入心，甘草、干姜这两味药非常的阳性，干姜和生姜是一样的东西，生姜的水去掉后就是干姜 了，甘草、干姜的比例是二比一，平常干姜开二钱就已经很重了，严重的时候，用到四五钱都可以，干姜很热是温中的药，可以强化肺阳，炙甘草用两倍，是为了把肠的津液补足，炙甘草的蜂蜜的黏液，会把津液补足，肺就不会那么燥热，因此这两味药可以强心、强肺、健脾阳。若厥愈，足温者，足温而已，并不代表脚的功能回来，所以脚还会有挛急，这是因为桂枝汤津液发太多了，人的肌肉、筋都是要靠津液来供养的，甘草干姜汤恢复脾阳，热就会传到肌肉上，可是津液还不足，所以肌肉还有挛急的现象，有点抽筋的现象，脚没办法踩在地上，这时候用芍药甘草汤，当然这甘草也是用炙甘草。  \n\n        平常用的时候，炙甘草用二两，芍药用一两，此芍药甘草汤又名去杖汤，为什么?老太太拄着拐杖走，喝了芍药甘草汤拐杖就丢了，马上会走路了，为什么?因为芍药可以让阴，就是静脉的血流回心脏的速度很快，炙甘草可以健心阳，因为炙甘草让脾旺起来，土生金，就是进入肺，所以炙甘草可以壮胸阳，让心肺功能加强，如果有静脉瘤，可以大剂的吃，如果吃药后有头晕现象，是瞑眩反应，表示药很对症，效果会很好，很严重的用二两都可以，用汤剂比较好。药行有白芍赤芍两种，严格讲两种的功能差不多，大多开白芍来用。双脚离 心脏最远，如果脚是冰冷的，就是制造血管中瘀血块的主因，因此我们看脚是热的，心血管中瘀血块就会被化掉。用芍药甘草汤可以让脚热起来，也就是可以去除心血管中的瘀血块，加上附子更好，已经靠热药就把瘀血去掉了，不一定都靠活血化瘀的药。如果只有手脚末端冷，那么瘀血块不会制造得很快，所以有人手脚冰冷了很久，也还没有发心脏病；如果到了四逆的情形，也就是冷到手肘、膝盖，那么瘀血块就制造得很快，就会造成心脏病。我们也可以由手脚冷的情况，来判断病情的进步与否。如果每个人都晓得这种判断的准则，就可以预防心脏病的发生；靠西医的仪器是没有用的，等到仪器检查出来，病人已经死在仪器上面。  \n\n       如果当初开桂枝汤加附子就没有此后遗症，没注意到而造成，因为病人脉浮，自汗出，小便数，心烦；病人阳虚的时候，自汗很多，明明是桂枝汤证，这时候应开桂枝汤加附子，有阳虚时应固表让津液不发掉。因为津液不够，大便就干在里面，通常食物停在胃和十二指肠的地方，食物磨碎后，本来要顺着津液下去，可是津液被桂枝汤发掉了，结果就和胃壁缠  \n在一起了，胃壁没有黏液，当胃里面的水没了，臭气就往上跑，顺着血液跑到脑里，谵语，就是胡说八道，遇到这种情形，就给他吃调胃承气汤，为什么叫调胃承气汤，胃把它当成肠，调胃承气汤就是可以把小肠最上面的食物清出来，病人胸满谵语的时候，压病人胃的下方肚脐的上方，大约是下脘、建里的地方顶在这，压会痛，就是实，就可以攻，这时候给他一点调胃承气汤就好了。大黄在中药里是属于通便剂，是去实用的，芒硝，性味咸而苦寒，是攻坚用的，如果光用大黄，会硬把它拉出来，病人会很难过，会里急后重，排得胃很难过，因为胃里面没有津液，胃会痛，所以先加些甘草下去和解，因为甘草解毒，把坏的排掉，好的留下，然后用大黄消导下来，食物有硬块的，用芒硝打散掉，所以芒硝生用，芒硝放在碗里，煮完后，汤冲下去，这样最强，如果要稍微缓些，把芒硝倒到汤剂里，和一和马上关火，如果没甘草，只有大黄芒硝，一吃下去，速度太快，药还没吃完，已经要跑厕所了，所以用甘草让它慢一点。大小承气汤没有用甘草，就是取它的快速。临床上看到皮肤红疹，舌苔黄黄的，大便不是很好，但是还有大便，摸胃下，会痛，就是食物堵在中焦，食物产生的浊气上到肺，肺主皮毛，所以皮肤发斑，所以误食桂枝汤的时候，第一个救逆的方子就是甘草干姜汤，第二就是芍药甘草汤，第三个是调整胃气的，就是调胃承气汤，调胃的意思就是把中焦清理干净，让上下可以调和，让病人重新再吃新的食物，再去治疗。  \n\n       仲景立法，凡表证兼有里证之虚寒者，必先温其里而后攻表，就是如果有表证兼有里面虚寒的人，一定要先温里再攻表，如果里证是实的，就可以先攻表再攻里，如果里证是虚的，先把里寒温起来，再去解表，如果病人身体素虚，体力津液不足的时候，不能用桂枝汤发表，因为津液不够，这时候先把里阳壮起来，再去解表，像炮附子就是壮里阳的药。温里阳的四逆汤，攻表的桂枝汤，表里两治的桂枝汤加附子。阴虚还有很多望诊可以看，譬如，舌头伸出来，校对厚厚的，舌头越肥越厚，身体就越虚。虚到命危时，舌头会像气泡一样，遇到这种现象时，不要马上开桂枝汤。 ', NULL, '桂枝汤,甘草干姜汤,甘草干姜汤,调胃承气汤', NULL, NULL, NULL, '32、伤寒，脉浮，自汗出，小便数，心烦，微恶寒，反与$f{桂枝汤}以攻其表，此误也，得之便厥，咽中干，烦躁，吐逆，谵语，脚挛急，作$f{甘草干姜汤}与之，以复其阳。若厥愈，足温者，更作$f{芍药甘草汤}与之，其脚得伸。若胃气不和，谵语者，少与$f{调胃承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614449913831494, '0AB460B498A61D9E1D3F19BF9BEF840B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 16:23:08', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5242, 53, 904000432, '      若重发汗，复加烧针者，就是重发汗后再加烧针的，烧针就是燔针，冰天雪地，冻疮，关节的地方坏死掉的时候，把针烧的通红，从阳陵泉对阴陵泉刺下去，可以把骨头救回来，就是燔针术，所以燔针术刺完后，身上一个洞一个洞的。还有去脓疡的时候，也会用到烧针，在针灸中已经教过。为什么叫四逆汤，手脚都冰冷掉，到了手肘、膝盖就是四逆，体温急速下降，或失血过多的时候，会造成手脚都冰冷掉，所用到救逆的方子。  \n\n四种用四逆汤的外证：  \n\n   一、骨节身体疼痛。  \n\n  二、四肢厥逆，手脚冰冷。  \n\n  三、小便清利，白白的没有颜色温度。  \n\n   四、下利清谷，吃到什么就拉什么，肠胃完全不会吸收，没有蠕动。  \n\n        炙甘草、干姜，针对脾阳，生附子对肾阳，所以四逆汤在用的时候，脾阳肾阳能够恢复，先天之本再加上后天之本，就能恢复他的生机，所以肾阳不足的时候，精排出来很冷，生附子下去可以壮他的天癸水，使天癸水很热，对妇科也很好。生附子在这里用，完全在壮肾阳，实际上生附子下去的时候，心脏的力量就会跳起来，为什么前条不加生附子，因为肾阳还很足。  ', NULL, '四逆汤', NULL, NULL, NULL, '33、若重发汗，复加烧针者，$f{四逆汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614687616471110, '08E619C6245FA54BCC27D0B7A321FCDF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 08:30:21', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5243, 53, 904000433, '       问：看起来像桂枝汤证，按法治之而增，结果四肢冰冷，咽中干，两胫抽筋而谵语， 张仲景说：夜半手足当温，两脚伸直，后如师言，为什么?\n\n       张仲景说：寸口脉浮而大，浮则为风，浮在表面上代表风寒感冒进来了，大则为虚，脉应该是缓脉，结果脉却很大，人虚掉了，脉很细是虚，很大也是虚，脉形变的很粗大，就是血虚掉了，风则生微热，虚则两胫挛，因为血不够了，病证像桂枝，因为没有加附子在桂枝汤，增加桂枝，结果汗出亡阳，厥逆，咽中干，烦躁，阳明内结，谵语烦乱，更饮甘草干姜汤，夜半阳气还，两足当温，胫尚微拘急，重与芍药甘草汤，尔乃胫伸，以承气汤微溏，则止其谵语，故病可愈。  ', NULL, '芍药甘草汤,甘草干姜汤', NULL, NULL, NULL, '34、问曰：证象阳旦，按法治之而增剧，厥逆，咽中干，项胫拘急而谵语。师言夜半手足当温。两脚当伸。后如师言，何以知此?  \n\n       答曰：寸口脉浮而大，浮则为风，大则为虚，风则生温热，虚则两胫挛，病证象桂枝；因未加附子参其间，增桂令汗出亡阳故也，厥逆，咽中干，烦躁，阳明内结，谵语烦乱，更饮$f{甘草干姜汤}，夜半阳气还，两足当温，胫尚微拘急， 重与$f{芍药甘草汤}，尔乃胫伸，以承气汤微溏，则止其谵语，故病可愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614715427463238, '7E266137A066EEE459A47729D9957A6A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 10:23:31', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5244, 53, 904000434, '        张仲景在太阳篇出了三个代表方，第一是$f{桂枝汤}，第二是$f{葛根汤}，第三是$f{麻黄汤}，为什么会有葛根汤证，所谓的中风，中寒，平常中风的时候没有什么感觉的，中了风或许都不知道，摸脉才知道的，因为风吹的很舒服的。中寒的时候有感觉，有警戒心的时候，就是$f{麻黄汤}证了。当中风的时候，恰逢汗流很多，津液都伤掉了，就变成$f{葛根汤}证了，所以$f{葛根汤}可以说是温病的方子，因为只有南方比较热，才会大量流汗，津液才会伤到，这时候感冒的话，项背强几几，人背后是太阳经，几几像鸟羽毛竖起来，背后太阳经整个冰冷的，可以刮痧，或$f{葛根汤}就可以了，$f{葛根汤}的症状就是无汗，恶风，因为是中风，所以风吹的很难过。或是用$f{桂枝汤}，桂枝汤加一些麻黄再加葛根，称之为$f{葛根汤}，这时候重用葛根。', NULL, '葛根汤', NULL, NULL, NULL, '35、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614716475330630, 'CDCE75353F655F31EC44692848D45A9B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 10:27:47', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5245, 53, 904000436, '      太阳与阳明合病，有下利的现象，有呕吐的现象要加半夏。  \n\n       有呕吐的现象要加半夏。《本草》写半夏止呕去水，所以半夏也是一种利尿剂，茯苓不能止呕，所以往往有水饮的时候，用半夏，呕吐的时候，半夏是很好的止呕的药，所以妇女妊娠呕吐的时候会用到半夏。临床上看状况，如果是葛根加半夏，是妇人怀孕得到这症状，半夏就要用到八钱一两的，顺便把害喜的恶心止掉。  \n\n       张仲景在伤寒论里面，所用的半夏是生半夏，因为半夏生用有毒，所以现在在药行买的都是姜半夏，所以如果开半夏，生姜就不用加了，生姜是解半夏毒的。生姜和半夏煮过后再晒干性就不一样了，生半夏在用的时候，可以治至高的水，水最高到脑积水，如果用姜半夏就没效了。因为医圣张仲景用的是生半夏，没有晒干的，我们买到的半夏是晒干的，所以我们不能参考他的剂量，一般来说，用干的生半夏三钱。  ', NULL, '葛根加半夏汤', NULL, NULL, NULL, '37、太阳与阳明合病，不但下利，而呕者，$f{葛根加半夏汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614721334431814, '09D06010123162E9E689361FE36C736C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 10:47:33', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5246, 53, 904000435, '        无汗、恶风、项背强、喉咙痛、咽干、口渴，就是葛根汤证。太阳与阳明合病，必自下利，葛根汤也可以治疗下利，为什么叫太阳与阳明合病者，太阳代表表，阳明代表里，表被寒束到了，水到表面出不去，就回流，水出去再回来，温度就不够，水就到小肠，小肠是火， 小肠本身不是受水的，水一到小肠就听到咕噜咕噜的拉出来了，中医叫作热利，病人的大便浓稠、散的、很臭，如果有表证又兼有了利，这时候也是葛根汤证，就是太阳、阳明并病。  \n\n        靠葛根把肠胃中的水拉上来，下利就止掉了，葛根汤为下利初起兼有表证之特效良方。这是一种治痢的方法；以后还会教到其它方式，例如和解的方法，还有利尿的方法等等。用葛根汤治疗表证兼有下利，有一种情况要注意，遇到中焦很湿热的人，舌苔黄而湿腻，用了葛根汤，结果脸都红起来，湿热都被升提上来了；所以素有中湿之人，喜欢吃油腻的东西，比较胖的人，应该加茯苓下去，让湿热从小便排出来。  \n\n       治小儿惊风角弓反张，属于刚痉，就是小孩脑膜炎、昏迷、抽筋，这时候葛根汤重用到六七钱的，麻黄用四钱，桂枝用三钱，大剂的下去。  \n\n      凡表里两病皆实者，当先解表而后治其里，如果表实里虚的时候，先解表再治里，临床上，有的时候一起用，有的时候病人已经三四天不大便了，又得到葛根汤证，一起攻出来没有关系。  \n\n       后面我们会学到，太阳与少阳合病，就是用小柴胡汤；少阳与阳明合病，就是用大柴胡汤。  ', NULL, '葛根汤', NULL, NULL, NULL, '36、太阳与阳明合病，必自下利，$f{葛根汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614721334431815, '0D08A476198E26B4758B3848F18AA45B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 10:47:33', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5247, 53, 904000437, '        原本有桂枝表证，被医生攻下，或不小心吃坏肚子造成下利，结果利下不止，脉促，喘而汗出者，表未解也，也就是病人被攻下，血都往下跑，血往下力量很强，脉会跳得很快稍微停一下，这时葛根汤没用，要用葛根黄芩黄连汤，有表证，误下，造成表邪，就是表面的病毒渗透到汗腺里，进入肠子，血往下走，病毒跟着下来，像阿米巴痢疾，可以用葛根黄芩黄连汤。  \n\n       黄芩、黄连是非常寒凉的药，所以它能去热，热就是炎，所以也是消炎的药，黄芩黄连不仅可以内服，还可以外敷，如果皮肤破，可用黄芩黄连。如果化脓，可以加去湿的药，黄芩杀菌的力量很强，阿米巴痢疾的时候，大肠的壁都破洞了，下利都是血，下利久了人会脱水，所以用葛根升水，用炙甘草，把肠子的津液补足，用黄芩、黄连解毒，黄芩、黄连等量，小儿之痢疾炽热难用下剂之证多效。  \n\n       表邪未陷者，重于解表，已陷而成为里热者，重于清里，本来是桂枝汤证，结果下利，这时候要重于清里，改成葛芩连汤，虚寒者为脉微无力，实热者为脉数有力，为什么摸到脉数？就是里面有东西堵到了，发炎了，病人会发烧。虚寒者舌苔淡白，实热者为舌红苔黄，实热者为舌苔黄的，黄的再进就红，再进就黑了，就是壮热了。虚寒者为下利不热，色黄淡，实热者下利热灼，色黄赤而臭热，肛门没有灼热的感觉，就是不热，实热的大便很臭，而且肛门有灼热的感觉。  ', NULL, '葛根黄芩黄连汤', NULL, NULL, NULL, '38、太阳病桂枝证，医反下之。利遂不止，脉促，喘而汗出者，表未解也，$f{葛根黄芩黄连汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614725865422918, 'F100CDF0E951EDAEBCA8B325CB96B388', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:05:59', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5248, 53, 904000438, '        讲到伤于寒，就是麻黄汤证，又名还魂汤，为什么？就是人死了，脉都没了，下回阳九针后，再灌麻黄汤下去，所以麻黄汤可以从阴间回到阳间，过去有很多伤寒重症，麻黄汤一下去，就救回来了。不需要用到大剂四逆汤，有些中医师用炮附子几百克去回阳救逆，实际上不需要，用麻黄汤就好。  \n\n       张仲景这条辨没写脉证，一般来说，伤寒病在表，抵抗出来和病毒相抗，脉浮且紧，浮代表表，紧代表寒，所以麻黄汤证需解表发汗，如果只有脉浮紧才用麻黄汤，张仲景早就写在里面了，葛根汤、桂枝汤都有写，为什么麻黄汤没写，就是当遇到危急的时候，病人气息都快没了，照样可以用到麻黄汤。  \n\n       病毒趁人身体改变的时候进来，人身上的热度，一直都在调节，汗发不出来的时候，就会发热，为什么头痛，免疫系统就是阳，阳会往上冲，而头是诸阳之会，所以会头痛。水到皮肤表面排不出去，这水就渗到肌肉，就感觉身疼，腰痛，骨节疼痛，全身关节都会痛，有时严重到像是被鞭打一样。为什么恶风？就是表寒，这种怕冷的程度，可以在夏天的车子里面，不开冷气，关上窗户，穿着大衣躲在里面。为什么无汗而喘，肺主皮毛，皮肤毛孔肺在管，现在皮肤毛孔被寒束到了，就是肺也受寒了，肺在身上的功能是布施津液到五脏六腑及全身上下，现在肺一受到寒，肺的津液散不出去，肺也被束到了，肺的呼吸自然受到影响，而有喘气的外证，所以得到麻黄汤证的人，可以说皮毛和肺俱闭，不能宣泄了。我们在问诊的十问里问到汗出情形，就是要知道他的肠胃系统、心脏功能、肾脏功能；例如说，心脏功能好，才能正常出汗，如果心脏功能不好，有两种情形，一种是出不了汗，一种是没事盗汗很多。肾脏有问题的人，也不会出汗。水肿的病人，治疗以后只要有汗，就不会有水肿。麻黄汤证不是疫病，不会传染的。一般来说，麻黄汤证是被冬天的寒气所伤，冬天的正气是寒气；但是现在的人可能吹冷气，或者是突然跳到游泳池中，只要伤于寒就可能出现麻黄汤证。', NULL, '麻黄汤', NULL, NULL, NULL, '39、太阳病，头痛，发热，身疼，腰痛，骨节疼痛，恶风，无汗而喘者，$f{麻黄汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614728251863109, '3D1F977BFCCBEAC7AA6A71E0E63F78E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:15:42', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5249, 53, 904000439, '        ー、太阳证的时候，寒水在背后是冰的，如果渗入肠间，引起下利，处方就是葛芩连汤。\n\n        二、水气侵入心下，就是胃，在胃的外面的淋巴上，病人会呕逆，处方葛根加半夏汤。  \n\n        三、太阳与阳明合病，喘而胸满者，处方麻黄汤。太阳有病，代表有表证，有寒束在身上。阳明有病，就是热发散不出来，集中在胸，往上冲，冲到肺上，而肺又被束到，所以喘而胸满者，不可下，绝对不可以攻里。如果麻黄汤证， 表寒很厉害，怕冷，病人陈述很冷、全身骨节酸痛、没有汗，如果攻下就会结胸，要确定病人没表证，才可以攻里。如果感冒、$m{有汗，往桂枝汤、葛根汤去想}。如果感冒、$n{无汗，就要想到麻黄汤，怕冷、关节酸痛，就是麻黄汤了}。因为，麻黄汤很强，所以特别要注意病人可不可以开麻黄汤。  ', NULL, '麻黄汤', NULL, NULL, NULL, '40、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614731423502406, 'BDC18138243F89EC99531AA2251FDAC7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:28:36', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5250, 53, 904000440, '       太阳病，一段时间过了以后，脉浮细而嗜卧者，浮代表病还有一点点，但脉已经细下来了，就是没有那么强了，一般病人病情刚恢复的时候，会想睡一下，所以外已解也。如果胸满，胁痛者，与小柴胡汤，胸满胁痛为少阳病主证之一，此为太阳转入少阳之候，故用少阳主方小柴胡汤治之。如果脉还在表面，而且有胸满的现象，因为肺要舒张，可是还是被寒束到，所以再给麻黄汤。  ', NULL, '小柴胡汤，麻黄汤', NULL, NULL, NULL, '41、太阳病，十日已去，脉浮细而嗜卧者，外已解也。设胸满，胁痛者，与$f{小柴胡汤}，脉但浮者与$f{麻黄汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614731423502407, 'FFC70E97C1212168B0079B74275004DF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:28:36', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5251, 53, 904000441, '      麻黄又名青龙，大青龙汤，实际就是麻黄汤的变证，脉浮紧，发热，恶寒，身疼痛，不汗出，这些都是麻黄汤证，而烦躁，就改成大青龙汤了，就是麻黄汤里面加了生姜、大枣、石膏。感冒的时候，身体会痛的，马上要想到麻黄汤，而多了生姜、大枣、石膏就是为了烦躁，烦躁的症状就是代表邪已经化热了，如果刚开始是麻黄汤证，病人不会烦躁，病人会很冷发抖，等到得了麻黄汤一两星期，他可能证就变掉了，变到比麻黄汤还要深的地方，肺的津液丧失，肺太热了，已经转成肺炎了，所以用石膏，石膏性甘寒清凉润肺，能去肺热、降逆，把肺热往下导，因为病人本身体能已经很虚，加生姜、大枣把肠胃的津液补一下。\n  \n       麻黄汤里面，麻黄用三钱，大青龙汤的时候、肺热高的时候，麻黄用到六钱，因为有石膏在里面，所以麻黄可以用到六钱，六钱，因为是分三次服用，每次只用到两钱。麻黄和石膏组在一起的时候，石膏会收敛麻黄，不让麻黄发汗， 会把热往下导。为什么吃麻黄，有的流汗，有的小便出来？张仲景的意思，大青龙汤里面一半的麻黄和杏仁走表，如果没有增加麻黄的重量，麻黄和石膏走里，杏仁不能发表，表就解不掉了，所以麻黄一半和石膏往下走，一半和杏仁走表，脑里面的病毒从小便排出去。  \n\n        像越婢汤，里面用麻黄石膏，不用杏仁，吃了越婢汤小便一大堆，不是发汗，所以桂枝二越婢一汤的时候，取小便，因此越婢汤是伤寒论里面第一个水肿的方子，所以最初的水肿，用的是桂枝二越婢一汤。而麻黄桂枝各半汤的时候，是要让病人微微发汗，而不要发太多，所以病人平常一定有身痒。  \n\n      凡是看到病人表寒里热的时候，就用大青龙汤，病人曰喉咙痒痒的，问病人有没有咳嗽?有咳嗽，问口有没有渴?答有渴，问有没有痰，答有痰且痰黄黄浓浓的，黄浓就代表病人里面热，问会不会怕冷?答有，且有鼻塞的现象，所以这病人表是寒的里是热的，这热是肺热，所以用大青龙汤。  \n\n        为什么喉咙会痒痒的，因为水喝到胃里面，正常的管道是水从胃的津液发散到肺，再到皮肤毛孔流汗流出去，有一天皮肤毛孔被寒束到了，这个水要回头，可是水不会回到胃中，水顺着三焦淋巴系统到胃的下方，这水气已经离开汗腺，但又不在胃中，也不在消化系统中，水在横膈膜中，一呼吸水气就往上冲，就痒痒的。肺里面太热了，舌苔会黄的，所以开石膏，把水往下导，小便排出去。  \n\n       麻杏甘石汤和大青龙汤的分辨，如果咳嗽，胃口好不好？如果胃口很好，开麻杏甘石汤，咳嗽咳得都没胃口了，开大青龙汤，所以大青龙汤就是病人的肠胃已经伤到了。所以平常肠胃很好的人，得到咳嗽的时候，麻杏甘石汤证。平常肠胃不好的人，得到咳嗽的时候，大青龙汤证。  \n\n       科学中药的药粉，在真正危险的时候，整罐吃下去，也没用，因为汤者，荡也，熬汤剂的时候，可能一剂下去就好了，所以经方说一剂知，二剂已，指的是汤剂，因为汤的热力，所以下去的力量很强。  \n\n        有一种状况不可以吃大青龙汤，就是脉微弱，汗出，恶风者，不可服之，先不管什么症状，如果他的脉很微弱就是里虚了，汗出就是津液不够了 ，风吹得很难过，表示这人里面已经很冷了，石膏一下去，就更冷，本来津液就已经不够了，麻黄杏仁一发汗，这样津液就会伤的更多，这时会造成病人贫血，因为血水同源，结果病人的手脚会冰冷掉，所以如果很虚的人绝不可给大青龙汤，这病人脉微弱，汗出，恶风者，是桂枝汤证，又因表虚里寒，所以应是桂枝汤加附子。  \n', NULL, '大青龙汤', NULL, NULL, NULL, '42、太阳伤寒，脉浮紧，发热，恶寒，身疼痛，不汗出而烦躁者，$f{大青龙汤}主之。\n43、若脉微弱，汗出，恶风者，不可服之；服之则厥逆，筋惕肉润，此为逆也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614773333291078, 'B6E4D24A2AF80431951EB9A739749871', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 14:19:08', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5252, 53, 904000442, '       少阴证的人，也会脉浮缓身重，少阴证有一点最重要的就是但欲寐，脉浮缓就是外有表证，为什么但重，就是病人素有湿在中焦，湿在中焦，肌肉关节都会感到重重的，身重，就是四肢很重，就代表湿很盛，如果湿只在脾胃里面，用白朮茯苓，白朮是干燥剂，茯苓利尿，把湿从小便小掉，如果这湿除了在脾胃中间，还有在关节上面，也可以用大青龙汤，如果光开桂枝汤、麻黄汤，解表的力量太快了，表去了，这湿去不掉，用大青龙汤来发，就是得汗解，全身的湿，用汗解，把这湿导到小便太远了，直接皮肤出去比较快。所以大青龙汤除了治疗疫病，也治疗全身水肿沉重。如果单是中焦脾胃的湿，舌苔很白很稠很厚，用白朮茯苓，得小便解，平常白朮茯苓开等量，如果水比较多，就茯苓加重，如果湿比较多，就白朮加重。 ', NULL, '大青龙汤', NULL, NULL, NULL, '44、伤寒，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，$f{大青龙汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614773333291079, '3AAB1634FD5D47A5DB85163F78A2B1CE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 14:19:08', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5253, 53, 904000443, '       小青龙汤是由麻黄、芍药、干姜、细辛、桂枝、半夏、甘草、五味子组成的，细辛是一味非常热的药，细辛是有毒的，临床上，细辛只开一钱，细辛长得细细的一根，下面有很多根茎，用它的根部，细辛一根独阳往上走，所以很热。因为里寒很盛，所以开细辛和干姜，把里寒去掉，让里面温热起来，把水气去掉，心下有水气，往上冒，所以会喉咙痒。五味子药没有寒热，五味子是止咳的，所以《本草》写五味子润肺，有时咳得很厉害的时候，气管都会咳破，用五味子。有时候咳得太厉害，会呕，用半夏，半夏会降逆也可以去水，所以胸腔的水，半夏也可以去，半夏还可以化痰，所以半夏与五味子合起来就能化痰止咳，张仲景的半夏是生半夏，半夏洗完就入药，生半夏有毒，也就是靠这毒把水排掉，能解半夏的毒就靠生姜和干姜，所以干姜与半夏并用在里面。生姜是散胃中之寒，干姜是温中去肺中之寒。桂枝、芍药、甘草此三味药是从桂枝汤来的。  \n\n       小青龙汤的用法，就是表寒里寒的时候用的，开小青龙汤的时候，表里双解，所以表面上可以看到麻黄汤证，大小青龙汤都可以看到咳嗽，而且都有痒咳，都有水气在里面。小青龙汤，一种是本身素体虚寒的人，得到麻黄汤证的时候用的，还有一种，本来是麻黄汤证的，没服用麻黄汤，而从麻黄汤证转成小青龙汤证，所以是麻黄汤证失治，而变成大小青龙汤证的，大或小则视病人身体的症状而变。  \n\n       本来身体就是里寒的人，舌苔伸出来白白的，平常不会口渴，想喝热水，里面寒很盛，就代表水很多，水发散不掉，停在里面，自然不会口渴，小便白白的，里寒很盛的人，一得到麻黄汤证，就表寒里寒了，水停在里面，呼吸的时候，横膈膜会上下移动，水气跟着一阵一阵往上冲，往上冲就会痒，所以咳一咳，会比较舒服。小青龙汤吐出来的痰是白色的泡沫，大青龙汤吐出来的是黄色的浓稠的，所以服小青龙汤会使里寒和水从表及小便解掉，所以小青龙汤下去的时候，会发汗发很多，用炙甘草把汗回逆回来，肠胃功能的恢复，就靠细辛和干姜，所以病人吃了小青龙汤，好了以后会很饿，因为肠胃功能恢复了。  ', NULL, '小青龙汤', NULL, NULL, NULL, '45、伤寒，表不解，心下有水气，干呕，发热而咳，或渴，或利，或噎，或小便不利，少腹满，或喘者，$f{小青龙汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614773333291080, '2F38B568A5B476E9449264C1F1F04BEA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 14:19:08', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5254, 53, 904000444, '       所以小青龙汤证的病人，这时候有发热的现象，但是不会口渴，表示里面水很多，肺里面有积水，水饮很多。小青龙汤用发汗的把水去掉后，服汤已渴者，此寒去欲解也，喝了小青龙汤会口渴的，就是水去掉了，常常病人呕吐或有什么病，病人吐掉或发汗发掉，病人开始口渴了，口渴就代表胃气回来了，自己会痊愈，病自已会好。这个观念我们也可以延伸到肾脏病的病人，肾脏病的病人，不流汗也不口渴，如果吃了药以后，结果会发汗也会口渴，就是里寒去掉了。  \n\n以上讲的是太阳证上篇。  \n\n初者，病邪初起，正气尚强，邪气尚浅，则宜速攻。中者，受病较久，邪气渐深，正气渐弱，宜攻兼扶。 末者，病已经久，邪气侵凌，正气消残，宜扶正气。 \n', NULL, '小青龙汤', NULL, NULL, NULL, '46、伤寒，心下有水气，咳而微喘，发热不渴，$f{小青龙汤}主之。服汤已，渴者，此寒去欲解也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614773770997830, '99706D8611C05C1BCD9D31F1264BFD88', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 14:20:55', 1, '超级管理员', '2024-11-22 14:48:53');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5255, 318, 904000514, '       脉浮紧，不发汗，就知道是麻黄汤证，表寒很盛了，因致衄者，如果得到了流鼻血，一般来说，鼻血流出来之后，症状就没有了，热就退掉了，为什么？因为肺开窍在鼻，所以肺的血管直接进入鼻，因为麻黄入肺，肺被寒束到了，肺的热没办法宣泄就往上走，所以就会流鼻血了，这条辨讲的是，如果得衄还是没解的，可再用麻黄汤。所以如果小孩感冒流鼻血，不要急，这是因为小孩阳比较亢，才流得出来。  \n\n       周禹载曰夺汗无血也；病人流鼻血的时候，一发表，鼻血就停掉了，为什么？血本来就在血管里面，一发汗以后，表没被束到，血液循环就会很流畅，血管里面有瓣膜不让血往回流，而且血管都有一定的弹性，血过不去的时候，血管就会破裂，在鼻子上就是流鼻血，在脑里面就是脑中风，所以平常有不和的时候，常常吃桂枝汤，让营卫和就不会出血，所以北 派预防脑中风的，除了灸足三里以外，就是吃桂枝汤了。桂枝、白芍让血管的弹性很好，遇到寒血管会收缩，遇到热血管会扩张，所以补血管的药都是两热药，因为西医没有分寒热的，西医治疗头痛的时候，开止痛药，就是血管舒张剂，舒张血管就是硬把血管撑开来，一撑开来血就流通了，当时纾解了，但是药效十二小时过了以后，痛回来了以后，血管会绷得更紧，头会更痛。  ', NULL, '麻黄汤', NULL, NULL, NULL, '60、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066246, 'CD3663724721B6BE93A1040047BB51C6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5256, 318, 904000508, '       脉浮数者，浮就是表，一息跳六七下，数代表热，发烧了，法当汗出而愈，看到表热，汗一出就解掉了，若下之，应该发表，结果攻下，这病人身重心悸，因为攻下得太厉害了，造成病人气血两虚，为什么身重？因为所有好的食物营养，本来是血的源头，通通攻掉了，造成血不够了，所以到四肢肌肉关节的营养不足，就会有身重，心脏缺血就会有心悸的现象，这时候病人已经血虚，就不要再发汗了，当自汗出乃解，遇到这种情形，让他慢慢的自己恢复，自己流汗，胃气慢慢恢复就好了，为什么？尺中脉微，此里虚，须表里实，津液自和，便自汗出而愈。尺脉的地方，讲男人的精宫，女人的子宫，也就是胞中，胞中是下焦阳聚的地方，也就是精的来源，摸到尺脉很虚很弱，重按就没有了，就是下焦虚掉了，血化成热，到下焦后成为精，就是我们的体力，所以精血是同源的，因此要确定病人里面津液很足的时候，才可以发表。遇到这种情形的时候，让他肠胃功能慢慢恢复，自己会流汗就好了。有的人身体很虚，回来得比较慢，这样等不是办法，过去经方家在里虚很盛的时候，用小建中汤加黄芪，为什么用小建中汤？小建中汤就是桂枝汤加饴糖，这饴糖就是麦芽糖，如果饴糖太麻烦，用普通的方糖也可以，这是专门治疗肠比较冷的状况，有的小孩喜欢吃冰，吃冰后，饭就不吃了，因为吃冰后肠胃都冷掉了，肠胃都不蠕动了，当然不喜欢吃钣，吃了小建中汤以后，看到冰就没兴趣，小建中汤在经方是拿来作补药的，小建中汤加黄芪让它固表，黄芪这药是固表，属于气药，气不足的时候，用来补气的。例：孕妇，怀孕正常的状况是血旺气衰，如果流产的时候，就是气旺血衰，所以怀孕的人不可能开黄芪给她吃的，但是如果要下胎就要把黄芪加重。黄芪本身是走表的，走皮肤表面上，所以皮肤病的药，都要加黄芪。所以遇到这种情形，看他有表证，又不可以发表，因为里虚，所以先去把里扶正，再让他发一点表，所以用小建中汤加黄芪。  \n\n       如果是有脉浮有汗的桂枝汤证，而且尺脉微、舌苔白而厚，我们知道里虚而且中湿很盛，我们可以在发表的药中加些加些茯苓白术，就可以避免这种现象。  \n', NULL, NULL, NULL, NULL, NULL, '54、脉浮数者，法当汗出而愈。若下之，身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚，须表里实，津液自和，便自汗出而愈。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066247, 'D72557F0FDC4452AEBA39427FAB6290D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5257, 318, 904000513, '        这就是说平常没有桂枝汤证，如果营卫气血不和的时侯，都可以吃桂枝汤，像这种时发热自汗出的人，常常觉得一阵一阵的热汗流出来，就是卫气不调和，卫气不调和的时候，血管外面的膜会干会破掉，东西缺水，反一下就破了，例如塑胶水管，常常有水就不容易坏，放在太阳下没水，很快就干掉破了，所以容易没事发发热流一点汗的人，就吃桂枝汤，把桂枝汤当作补药来吃，北派的补药不是注重滋补，而是注重调理，调整得很好，吃下去的食物才是真正的营养。  \n\n        桂枝汤名为发汗之剂，实为补气益血之剂。所以对气血很有帮助，非常的好，草枣亦为补养之品，加以啜粥补养津液，所以在早餐之前，先吃个几勺桂枝汤，再吃稀饭，可以让气血调得很好。  ', NULL, '桂枝汤', NULL, NULL, NULL, '59、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066248, 'AE656AE5EDCC9E90DE8712260646DB28', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5258, 318, 904000512, '        中医对营卫的观念，营就是血，卫就是气，营在肌肉里面，营的路线，从动脉血管到小血管到孙络，中医讲的孙络就是微血管的部分；气就是我们的动能，所以气虚掉的时候，就没有什么力气，讲话都懒得讲，卫气的路线就从腑，往往这个气从肠胃吸收营养后从淋巴系统一直走，走在皮肤毛孔；所以有流汗和流血两种，在血管里面看到的是血，血管的外面有一层薄膜圈到了，这层网膜就是中医讲的气的走向，网膜的力量很强，常见心脏的动脉血管破掉的时候，网膜会把它包到，在没有完全破裂之前，还有一段时间可以急救，而且在破掉之前会有症状，病人的症状就是心痛彻背背痛彻心，或心口绞痛、刺痛。五六十岁的人常常在副主动脉上面破裂，在心脏的上方有一副主动脉，血出来很多，往往有网膜包到，就是被气包到了，病人不会马上死，可是很危险，病人不能动，一动就喷出来了，中医的方法是让血急速的流回去，加强网膜的力量，让血管愈合，西医的方法就是把这一段割掉，接个血管上去，在接的时候，把动脉导到维生机上面，很快的接完血管再导回来，接个人工血管这样没有网膜了，就没有第二次机会了。往往再发病的时候，血已经喷出来了，所以中医讲的气血同源，讲的就是血管外面的网膜。  \n\n       病人常常自汗出，病人本身平常就在流汗。营行脉中，卫行脉外，复发其汗，营卫和则愈，人的气血要两和，血管的网膜和淋巴系统的气是相通的，如果血管里面的水少了，它会自动供应水，如果血管里面的水太多，水自然会出来，给淋巴系统传到皮肤毛孔，发汗发掉了，互相有协调作用，所以两者的管路是通的，当气和血不协调的时候，桂枝汤最大的功能就是调和营卫，汤剂下去后，本来不协调的变得协调了，本来淋巴系统里面的水分要进入血管里面的，如果气太旺了，水太过了发到皮肤表面，这水原本应进入血的，结果跑出去，就代表营卫不协调，所以平常没事流汗的人，气候又没变化，突然流虚汗，就是代表营卫不协调，这时候没有病无所谓，有症状就可以吃桂枝汤，让它协调。中风证是伤到卫分，只需要用到桂枝；而伤寒是营卫两伤，因此麻黄与桂枝必须并用。  \n\n        新药物学知道麻黄素有刺激中枢神经的效能，是作用于交感神经兴奋药，我们用作发汗药。麻黄素，西医用在急救、兴奋上面，也知道麻黄会发汗，但是西医只用单味的麻黄，用麻黄素发汗和安非他命造成很多的问题，吃单味的麻黄素并不能发汗，如果麻黄素没有桂枝，只是个宣肺的药，不能得到真的汗，因为麻黄素是阳药，能把气管打开来，性轻而且升，一下就跑到脑部去了，头部阳气很盛，当然会睡不着觉，所以张仲景在汤剂用麻黄的时候，一定把麻黄素先煮掉。  \n\n        中药讲气和味，所以《神农本草经》上面一定讲气和味，药有的时候要取药的气，有的时候要取药的味，例：大黄用来泻头面五官的热，大黄是寒凉的药，是消炎的药，如果牙齿痛、头上的病、眼睛红肿，取大黄的性就要用开水烫，所以麻沸汤就是用滚水烫下去，这消炎的药就走上面，就是取它的气。如果把大黄煮两个小时，药味都煮出来了，这是取它的味，这时候大黄是往下走，而不是走到头上，所以大承气汤就一定是取它的味，因为要攻下。所以麻黄煮过以后，就不取它的气，取它的味了，麻黄直接进入肺，用麻黄发表流汗的时候，一定加桂枝在里面，因为没有桂枝，麻黄不会流汗，麻黄进入肺让气管打开来，不论寒证热证都用得到麻黄，所以小青龙大青龙都有麻黄。 \n', NULL, '桂枝汤', NULL, NULL, NULL, '58、病常自汗出者，此为营气和。营气和者，外不谐，以卫气不共营气和谐故尔。以营行脉中，卫行脉外，复发其汗，营卫和则愈，宜$f{桂枝汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066249, '34C238BB38DB083A0E4B7C7A86145554', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5259, 318, 904000510, '       这条是在尺脉很壮盛的时候会用得到。如果是下针给病人发汗，就下合谷，合谷下针的时候要飞针引气，起针的时候转针，一边起针一边转，下去的时候直直的下，引到第三次的时候，病人就冒汗了。  \n\n     头痛、印堂痛用承气汤；偏头痛就是小柴胡汤；整个头痛、头顶最痛用葛根汤。  ', NULL, '麻黄汤', NULL, NULL, NULL, '56、脉浮者，病在表，可发汗，宜$f{麻黄汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066250, 'F0090200F35C87639F7C94079855FE02', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5260, 318, 904000511, '        发汗，有它必要的条件，如果说病人已经在发汗了，不会开麻黄汤的，因为病人的表已经开了，病人的症状除了脉浮数以外，一定兼有恶寒和无汗，所以麻黄汤和桂枝汤最简单的区分就是一个无汗，一个有汗。麻黄汤证一般发烧温度比较高，无汗，怕冷比较严重。  ', NULL, '麻黄汤', NULL, NULL, NULL, '57、脉浮数者，可发汗，宜$麻黄汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066251, '853177BA335D8FA88B9170AEC2ECEBEB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5261, 318, 904000509, '      脉浮紧就是寒，法当身疼痛，他应该感觉到全身痛，宜以汗解之，要用汗来解他，假令尺中迟者，尺中脉很迟的时候，就是血不足了，血里面有百分之六十的水，血不够代表血里面的津液不足了，这时候不可以发汗，所以在开麻黄汤之前，要确定病人有没有足够的津液来发汗，张仲景提供一个方法，就是摸一摸尺脉，平常开麻黄汤，病人的尺脉都很大，又浮又紧，摸寸脉是阳，也就是胸、肺、皮肤表面、上焦，摸关脉就是肝、胆、脾、胃、中焦，尺脉是阴，就是肾、膀胱、下焦，平常开麻黄汤给病人发汗的时候，一定是寸、关、尺三脉都浮在上面的，才用麻黄汤，这是用脉证来确定病人的身体虚不虚，如果吃了麻黄汤会手脚厥逆，就是病人变成甘草干姜汤证了。一般来说，如果吃了麻黄，不会感觉到心悸的人，都是心脏比较好的。  ', NULL, NULL, NULL, NULL, NULL, '55、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以知其然？以营气不足，血少故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066252, '3309958BE46AD9D8E623163B5341DCB0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5262, 318, 904000507, '        二阳并病，就是太阳阳明并病，太阳初得病时，发其汗，太阳病刚得到的时候，发病人的汗，如果发透了就好了，如果发得没有透，汗先出不澈，开处方的时候心软，药剂开得太少，病邪没有去，慢慢的太阳证的时间过了以后，病的热邪转到阳明去了，续自微汗出，不恶寒，阳明证的话，还会流汗，因为肠的津液还会往外走，但是阳明证没有寒都是热证，表证已经没有了，入到里去了，如果这种情形的时候，若太阳病证不罢者，不可下，要先看病人到底在阳明还是在太阳，问病人还有没有怕风？答有，有没有怕冷？答有，还有没有流汗？答有，就是表证还没有去，甚而摸他的脉很浮，有表证的时候，绝对不要攻下，下之为逆。这种状况的时候，给他小发汗，就是桂枝汤加葛根就可以了。用葛根把津液补一补，前面已然发过汗了，后面怕发汗发太多了。设面色缘缘正赤者，阳气怫郁在表，脸色红赤的时候，代表胃的热气往上冲，阳气浮在皮肤表面上，发又发不出来，当解之熏之，熏为古人用一种药草熬水，蒸其水气以取汗之法。就是用煮药草，病人坐在旁边，熏病人，让病人流一点汗，因为怕喝药喝太多，而病人津液已经不够，因为有阳明证表示津液不够了，肠胃的津液再伤  \n到的话，大便一旦堵到了，就变成承气汤证，如果是血里面的水不够的话，就变成白虎汤证，怕吃药吃太多不好控制，所以用药去熏他，用外在的方法使病人流一点汗，这是比较浅的方法。若发汗不澈，不足言阳气怫郁不得越，当汗不汗，其人烦躁，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气，但坐，以汗出不澈故也。这条辨讲的是，如果病刚好介在阳明和太阳之间，无法分辨，就问病人大便正不正常？如果还很正常，就不用管阳明，先解表再攻里，解表的同时，如果怕太重伤到津液，可以同时采用增加津液的药，吃稀饭或杏仁多加一点，或吃完麻黄汤以后，多吃些水梨，把肺的津液补回去。  \n\n        刚刚讲的就是汗发得不够透澈，所以在太阳证的时候，给病人多一点发汗不会有事，因为桂枝汤里面有甘草、大枣，麻黄汤里面有杏仁，张仲景设计的方子不会伤到津液的，所以麻黄汤里面麻黄开到五钱，杏仁也要开到五钱，如果吃了麻黄汤，因发汗发太过造成贫血，就是杏仁用太少了。所有的症状都是汗出不澈故也，更发汗则愈。为什么知道汗出不澈呢？脉涩，涩脉，摸到的脉是扁的，所以脉迟而细就是涩脉。汗出不澈，从脉可以看得出来，还有病人的陈述也可以看得出来，皮肤痒痒就是汗出不澈，最明显就是皮肤痒，风吹得很难过，这也是汗出不澈，汗发不透的时候，有时候是皮肤痒，有时候是皮肤有很紧的感觉，整个脸色是红润的，眼睛两边红红赤赤的，因为汗是从胃里面的津液来的，要发发不出来，胃气一直往上跑，整个冲在脸上，所以脸就会红红的，可是又流不出汗来。  \n\n        如果要很重的透发，太阳证的时候，就桂枝汤加重一些。如果表束到了，没有汗了，加麻黄汤进去。如果病人全部是热证，脉洪大、燥渴，用白虎汤，病人吃石膏的时候，也是得汗则解，因此不单单只有桂枝汤、麻黄汤、葛根汤才有流汗的现象。', NULL, NULL, NULL, NULL, NULL, '53、二阳并病，太阳初得病时，发其汗。汗先出不澈，因转属阳明。续自微汗出，不恶寒，若太阳病证不罢者，不可下，下之为逆。如此可小发汗。设面色缘缘正赤者，阳气怫郁在表，当解之熏之。若发汗不澈，不足言阳气怫郁不得 越，当汗不汗，其人烦躁，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气，但坐，以汗出不澈故也，更发汗则愈。何以知汗岀不澈，脉涩，故知也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066253, 'CC8348BA45817A6C7401EEDBE5F72AE7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5263, 318, 904000506, '       这因本身的体能比刚刚的更强，刚才的阳气还只是中级强，还需要麻黄汤来把寒发出来，这个不用麻黄汤，常见的是小孩子，而且是男孩子，很皮，跑来跑去，妈妈还在煮麻黄汤，小孩子流鼻血好了，所以不用紧张，血会自己停掉，一般容易发生在十四岁以下的孩童，因为是纯阳之体，所以在针灸课程中讲过，十四岁以下的孩童如果流鼻血，不需要治疗。  \n\n       温度因衄血而降低，故中医谓之红汗。故多血家之有脑充血象征者，不但无害，反而有益。$m{《内经》}$n{有夺血者无汗，夺汗者无血。}就是平常容易流鼻血的都不会有汗的，还有平常流汗很多的人，就不会流鼻血。  ', NULL, NULL, NULL, NULL, NULL, '52、太阳病，脉浮紧，发热，身无汗，自衄者愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066254, '3E97AFC341D6A8189AAB6F8C76394431', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5264, 318, 904000505, '       太阳病，脉浮紧这代表伤寒，无汗发热，身疼痛，这就是太阳病的麻黄汤证，如果八九日后，表证还在，还是冷得要死，必要发病人的汗，开麻黄汤给他吃了以后，微除，稍微除了一点。开麻黄汤给病人有两种情形，一种是医师的过失，一种是病人的过失，什么是医师的过失？前面讲了，方子的剂量很重要，是麻黄汤证，开麻黄汤，病人吃下去发汗了，如果开太轻了，发汗的力量不够，微除，就是一点点除掉了，还有症状在里面，这是一种情形。还有就是医生的剂量开得很足，病人喝得不够，只喝了第一碗，这一种是病人的过失，就是剂量吃得不够，造成病人发烦，目瞑，突然感到情绪暴躁，头有点昏花，剧者必衄，衄乃解。所以然者，阳气重故也。有这种状况是这病人本身体能很强，体能很强的人得到麻黄汤证，喝麻黄汤的剂量不够，但麻黄汤已经带动血的奔腾，已经把免疫系统带出一部分，结果阳气整个往上冲，血往上冲，冲到头部，结果昏弦，严重的血叛离经脉，造成流鼻血，汗和血是同源的，有的时候给病人发汗的药，一发汗烧就退烧了，还有时给病人发汗的药，结果病人流鼻血烧就退掉了，所以小孩子发烧，流鼻血烧就退了，小孩子阳气很重，有时候感冒，流鼻血烧就退了。这时候看到鼻血已经流出来了，表示病人已好了，再开麻黄汤就太过了。  \n\n       临床上有一个案例，两个木工的兄弟，大热天把父亲用棉被包起来，带到诊所来看病，说已经中风一个礼拜，结果我一看，麻黄汤证，照样用麻黄汤，心想仲景必不我欺；为了小心，隔天打电话去求证，结果家人说，不在！原来是不在家里，出门去玩了；问家人说麻黄汤喝了几碗，回答说只喝了一碗，药效就是这么快；而且吃了麻黄汤还是睡的很好，不因为麻黄而有失眠现象。虽然八九日不解，不管病名是中风还是感冒，只要还是麻黄汤证，就用麻黄汤，这就是辨症论治。 ', NULL, '麻黄汤', NULL, NULL, NULL, '51、太阳病，脉浮紧，无汗发热，身疼痛，八九日不解，表证仍在，此当发其汗。$f{麻黄汤}主之。服药已，微除，其人发烦，目瞑，剧者必衄，衄乃解。所以然者，阳气重故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066255, '60BCA3E0BE0DAF47CD3BA14ABBE1621F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5265, 318, 904000504, '       如果刚开始桂枝汤，给病人发汗没有好，又误攻下，攻下了以后，病人脉还是浮的，代表表证还在，没有好。浮为在外，而反下之，故令不愈。病在表如果攻里，走错方向了，今脉浮，故知在外，须当解外则愈，宜桂枝汤主之，所以桂枝汤非常的好用。  ', NULL, '桂枝汤', NULL, NULL, NULL, '50、太阳病先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故知在外，须当解外则愈，宜$f{桂枝汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066256, '51211EF52D2BB8E1B9771AA9E79EB4CB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5266, 318, 904000503, '       太阳病，外证未解，就是还有表证，不可下也，千万不可攻下，下之为逆，医生的过失，欲解外者，桂枝汤。当医生在决定攻下的时候，就是知道病人肚子里面有干大便，才会攻下，攻下之前，看还有桂枝汤证，先不要攻下，怕下陷入胸，所以要先去解表，再去攻里。 ', NULL, '桂枝汤', NULL, NULL, NULL, '49、太阳病外证未解，不可下也，下之为逆。欲解外者，宜$f{桂枝汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066257, 'CA1FC8D915BB783D931AE491749273E7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5267, 318, 904000502, '      平常太阳证的时候，一定是解表发汗，如果医生开错药攻下，攻下的药一吃了以后，全身的感觉很明显，血整个往下走，如果是体力比较好的人，下去以后又会回来一下，结果病人感觉微喘，病人没有结胸，如有微喘，代表病还在表还没有解，攻下攻错了，就是桂枝加厚朴杏仁，前面的酒客也是用厚朴来燥脾的湿，杏仁润肺润气。  \n\n       如果伤寒感冒里寒表寒，又咳很久，检查没有小青龙汤证，也没有大青龙汤证，问怕不怕冷？不怕冷，也不怕热，风吹得很难过，有一点流汗，有咳嗽，桂枝汤没有讲咳嗽？有！就是桂枝加厚朴杏仁汤。所以常常小青龙、大青龙还没有好的时候，就是桂枝加厚朴杏仁汤，所以久咳不愈，小孩百日咳，桂枝加厚朴杏仁汤就好了，因此桂枝汤证，本身又带有咳嗽的加厚朴、杏仁就好了。', NULL, '桂枝加厚朴杏仁汤', NULL, NULL, NULL, '48、太阳病，下之微喘者，表未解故也，$f{桂枝加厚朴杏仁汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066258, '56B118E09AEF13E648AC1D367D221449', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5268, 318, 904000501, '      这条辨的意思在说：治病是以脉证为重，时间再久，如果还是桂枝汤证，照样开桂枝汤，不是只有七天，病情不一样，所以北极的人和非洲的黑人得到感冒，开的药不一样，中医用症状来区分，来开药，像登革热刚开始时开葛根汤就好了。  \n\n    可见本条在侧重外证未解这句，不论病之时日多少，苟无里有虚寒，概与汗解，即里有实证热证，亦以汗解为先，此为仲师之心法。  ', NULL, '桂枝汤', NULL, NULL, NULL, '47、太阳病，外证未解，脉浮弱者，当以汗解，宜$f{桂枝汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614817926066259, '1D0269DC5F3B5167681ADA06ED6CE8B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:20:35', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5269, 318, 904000520, '    $m{《内经》}$n{昼是气，夜是血，昼是阳，夜是阴}。如果一个人晚上很好，白天有问题的时候，一定是阳不足。如果一个人白天很好，晚上有问题的时候，一定是阴不足，所以利用病人的昼夜好坏，来断他是阳不足还是阴不足。  \n\n        下之后，复发汗，这病人被攻下了后又发表，造成病人昼日烦躁不得眠，就是阳虚了，阳虚了以后虚热就往上跑，往上冲冲到头部，冲到胸部，冲到头部就是不能睡觉，冲到胸部就烦躁，夜而安静，到了晚上又很好，不呕，代表肠胃没有问题，不渴，津液也没有丧失掉，无表证，脉沉微，身无大热者，就是阳虚掉了而已，干姜附子汤主之，干姜是壮脾阳的，附子是壮肾阳与心阳的，阳不足补阳就好了，不需要用炙甘草来补津液，所以这条辨是完全的阳虚证，阴完全正常没有问题，所以药不必多用。  \n\n       阴虚者，当救阴。阴阳两虚者当阴阳两救之。只有阳虚，则当救其阳，救阳急不宜缓，以阳主生化，无阳则不化，各组织机能有立绝之危，故本条以四逆汤去甘草之缓，但取姜附之迅烈以救之。  \n\n尤在泾曰：大法昼静夜剧，病在肾阴；夜静昼剧，病在胃阳。所以气喘病人如果白天很好，晚上发病，就是阴不足。  \n\n《三因方》曰：干姜附子汤治中寒，卒然昏倒，或吐逆涎沫，状如中风，手挛搐，口噤，四肢厥逆，或腹燥热。这时候牙关绷得很紧，用灌的，所以用在急救救逆的时候。  \n\n《圣济总录》曰：附子散治小儿冻足烂疮，以附子二枚，干姜二两，捣罗为散，入绵中，如装袜；若有疮腰，即以腊月猪脂涂之。就是用干姜和附子，把它磨成粉以后，把它敷在小孩的脚疮旁，用外敷的。内服用的是当归四逆汤。', NULL, '干姜附子汤', NULL, NULL, NULL, '66、下之后，复发汗，昼日烦躁不得眠，夜而安静，不呕，不渴，无表证，脉沉微，身无大热者，$f{干姜附子汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614820607811654, 'D7D8C0D0844945569328255E89F20092', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:31:29', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5270, 318, 904000519, '      攻下了以后，里面阴就虚掉了，然后又复发汗，阳也虚掉了，如果病人有振寒的现象，发冷、手脚冰冷的现象，这时候摸病人的脉，可能一息二三至，脉跳得很慢又很微弱，就知道内外俱虚，内外都虚掉了，这时候常常用到四逆汤。  \n\n       内外俱虚，即阴阳两虚，轻则四逆汤重则四逆加人参汤。人参在这是补气的，在张仲景的观念人参是专门对肠胃功能的，所以心下痞的时候常常用人参，甘草干姜是对脾阳，附子是对肾，让脾阳和肾阳恢复，因为胃功能不好，所以再加人参下去，让胃也好。', NULL, NULL, NULL, NULL, NULL, '65、下之后，复发汗，必振寒，脉微细。所以然者，以内外俱虚故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614820607811655, 'C675E04B03AB145FE2A9F85E26EBE561', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:31:29', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5271, 318, 904000518, '      攻下再发汗，大下了之后，会造成里虚，所以开承气汤不能开太重，要恰当，如果发表太过，造成病人里虚，里面就是阴虚，表就是阳虚，这时候津液亡了，肠里面都没有津液了，怎知病人没有津液了？因为病人小便减少了，小便只有一点点，如果病人精神好，就不用开药，让病人自己好，等到小便正常了，就好了。如果病人精神不好，才开药去治疗，如果很危险了，如人已昏厥了，开四逆汤去救他。  \n\n        用了吐法与下法之后，怎么知道病邪去掉了没有，就是看病人口渴与否，如果病人口渴，就是病邪已经去了，不再给药了；如果没有口渴，才考虑再攻。所以像是开十枣汤这种药，一般都只开一剂，一剂吃完之后，问病人口渴不渴，口渴就不再给药。 ', NULL, NULL, NULL, NULL, NULL, '64、大下之后，复发汗，小便不利者，亡津液故也。勿治之，得小便利，必自愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614820607811656, 'C9954B93C5B470119C439CF703762B45', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:31:29', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5272, 318, 904000517, '       若吐，吐法的应用，可以用在病人中风的时候，痰涎塞住，被西医在天突的地方开洞抽痰，无法下针，只能用药，汤熬得很浓，药下去的时候，一边喝一边痰就喷出来了，把药也喷出来了，再灌再喷，再喷再灌，喷到后来没有痰了，药就进去了，这就是用药去急救，这就是吐法。  \n\n       阴阳自和者，就是胃气自己回复回来了，所以小孩感冒发烧，都没胃口，大青龙、小青龙在用了后，一旦小孩说肚子饿，就是有救了。也可以从寸脉与尺脉都有胃气，来看病人阴阳自和与否。这个时候虽然亡津液，但是张仲景的观念是，让病人自己痊愈之后，不开滋补的药；等到病人健康的时候，才可以吃补药调养。  \n\n      被汗、被吐、被下的时候，津液就很少了，如何知道脾胃功能恢复了？第一摸脉，一息四至，就是有胃脉，第二，病人会微微的发汗，第三，病人感觉到饿，第四，舌苔变的比较薄白的现象。  ', NULL, NULL, NULL, NULL, NULL, '63、凡病若发汗，若吐，若下，若亡津液，阴阳自和者，必自愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614820607811657, '58380DE1AD14001F210DF93718A9256A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:31:29', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5273, 318, 904000516, '       给病人麻黄汤发汗后，半天以后烦起来了，这时候脉浮数者，脉很浮数就代表前面的麻黄汤开太轻了，麻黄汤一下去发了一些表寒，结果还有一些表寒在里面，没有排掉，但已十二小时，半天了，麻黄汤药力没有了，药力差不多也是十二小时，病现在又回头了，病人有点烦，就代表血液还是很热，没有全发出来，但是前面已经被发表了，毛孔已经开了，就不需要再用麻黄了，因为脉浮数，就代表还是有表证，用桂枝汤来去它。', NULL, '桂枝汤', NULL, NULL, NULL, '62、伤寒，发汗，解半日许，复烦，脉浮数者，可更发汗，宜$f{桂枝汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614820607811658, 'D1040DAF8B35F2882B9958174AF7D0A9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:31:29', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5274, 318, 904000515, '        如果人得到伤寒，这病人已经六七天没大便了，气色已经黑了，看他的脸色像有一层灰， 没有光，整个人很躁，这时候病人头痛有热，这头痛已经不是感冒的头痛了，大便不出来的头痛和感冒的头痛不一样，两眉的中间这一块是阙上，头痛的时候刚好在印堂这一块痛，就是阙上痛，就是有便秘，所以头痛痛在这个位置上的时候，就是标准的阳明痛，手阳明大肠经、足阳明胃经，阳明经就是在腑的系统里面，大便堵到的时候，肠气冲到头上，就是大便的浊气一直上冲，刚好冲到阙上这个地方，所以在印堂上面有看到红丝就是有痔疮，就给承气汤。  \n\n       小便清者，知不在里，仍在表也，如果大便燥屎，堵在里面的时候，病人的小便一定是黄浊，因为下焦非常的热，所以张仲景在提醒攻大便的时候，要问病人小便是什么颜色？如果小便很清，代表下焦不热，病不在里，还在表，就代表这头痛在表，并不是阙上痛，发表用桂枝汤来发，如果不发汗，热上来的时候，一样会造成鼻衄。如果临床上遇到病人有表证，又五六天没大便了，先不考虑里证，承气汤的症状是热实，有热也有实，所以承气汤里面有 去热的药，也有去实的药。如何知道是寒还是热，看小便，小便白就是寒，小便黄就是热，我们用承气汤，怎么知道什么时候停止，就是看小便颜色。大黄张仲景并没有真正去分寒热，去实一定要加大黄，把去热的药加上大黄，就可以去热实，所以承气汤里面的大黄是去实，黄芩黄连都是去热的药，如果病人是寒实，也是实，也是有东西堵到，但是这个堵到的乃因为肠子不蠕动，所以如果是寒让大便堵到不通的，要开去寒的药，让肠胃蠕动恢复功能才行，把去寒的药加上大黄就可以去寒实，譬如细辛、附子都是热的药，这样大便就清出来了。所以处方的时候，要确定到底是寒实还是热实。 ', NULL, '桂枝汤', NULL, NULL, NULL, '61、伤寒，不大便六、七日，头痛有热者，与承气汤。其小便清者，知不在里，仍在表也，当须发汗。若头痛者，必衄，宜$f{桂枝汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 614820607811659, '5E64F67DF517B884BFA6D1D401F681A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:31:29', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5275, 318, 904000521, '       发了汗，身体还在痛，照理说伤寒的时候，因为寒束在表上，所以身体会痛，发了汗身体还在痛为什么？就是因为处方开太过了，发汗的药开太强了，这个疼痛是因为津液伤到了，孙络没有津液干掉了造成的，病人的脉沉迟，沉代表病在里，迟代表寒，这时候如何把发太过的津液补回来，就是用新加汤，还是桂枝汤的加减，桂枝是融和营卫，它是非常好补气血的药，因为身体的四肢末稍都在疼，所以加重芍药，让静脉流回心脏的力量加强，\n为什么用生姜？药吃到胃里面的时候，生姜的功能就是让胃一吸收到以后，散开来进入到肺里面去，生姜的功能就是能够散寒，把药力发得更强，能够透到肌表去，\n为什么加人参？津液因为发汗散失太多了，用人参把津液补足，这时候用大枣、甘草来补津液都来不及了，桂枝汤里面重用芍药，重用生姜，再加人参就是新加汤，专门用在发汗发太过了以后吃的处方。但是如果发汗发太过，汗流不止的时候，就不是这个方，是用桂枝汤加附子。  ', NULL, '新加汤', NULL, NULL, NULL, '67、发汗后，身疼痛，脉沉迟者，桂枝加芍药、生姜各一两，人参三两，$f{新加汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615043353403462, 'B07FFCB5CF838069AECD3DD08C459854', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 08:37:51', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5276, 318, 904000522, '       这条是讲发汗以后的辨症，如果病人已经发汗了，为什么不能再给桂枝汤？汗出而喘，无大热者，可与麻黄杏仁甘草石膏汤主之，就是麻杏甘石汤。平常在临床看的时候，如果一个人得病，得到太阳证，桂枝汤证或麻黄汤证或葛根汤证，病人星期三得病的，本来只是感冒，星期六才来医，病的表邪已经进入肺了，就是西医讲的滤过性病毒已经进入肺了，结果桂枝汤下去，表证没了，病人开始胸腔有问题，西医就说是病人得了肺炎，本来是感冒，太阳证来不及治，一发完就会有这个现象，因为病在肺上面，所以病人汗出而喘，病人流汗，肺主皮毛主表，所以这时候用麻黄，麻黄入肺，可是已经表虚了，不可以再发汗，所以不可能用桂枝；\n       为什么用石膏？石膏的性非常的寒凉，石膏就是白虎，白色很寒凉的药，石膏和麻黄碰在一起的时候，麻黄把石膏带到肺，本来有肺炎，就是肺有壮热，石膏能够去热，麻黄和石膏并用，病人不会流汗，是小便解掉的，因为痰很多，肺很热，所以加了杏仁去痰。这三味药下去，怕麻黄还来不及发散，胃还来不及吸收药，药就到大肠小肠去了，所以加甘草，\n      甘草有两个功能，一是停在胃，让药能停在胃上直接到肺上面去，一就是为了没消化的食物，所以张仲景常常在感冒药里面加甘草，就是让胃里面还没消化的食物，不好的分解掉，好的留下来，因为甘草可以解百毒的。故以麻黄扩张肺管，使肺中之郁热得以排泄，用石膏消肺中发炎，杏仁下气平喘，甘草缓肺急迫。  ', NULL, '桂枝汤,麻黄杏仁甘草石膏汤', NULL, NULL, NULL, '68、发汗后，不可更行$f{桂枝汤}。汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615057124622406, 'F5E407A77BA35251B4DDDD27E37594B2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 09:33:53', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5277, 318, 904000523, '      69条的发汗发太多的，一定是麻黄汤，麻黄汤把胸腔的水都发汗发掉了，并使肚脐下面，下焦的水往上冲，冲上来的力量太大的时候，病人就感觉到心下悸，为什么叉手自冒心？就是很难过想压下去，所以就是心下悸，按着就比较舒服。  \n\n       69条和70条，这两条都是发汗以后，但是发汗的力量不一样，69条是麻黄汤发汗以后，胸阳没了，所以感觉到心下悸，70条是桂枝汤发汗发太多，肠胃的津液没了，水不够，肚脐的地方就开始跳，就准备发奔豚了。中医的心下悸，并不是临床上看到的心脏在慌，而是中脘的地方在跳动，因为天阳在上面干掉了，把水硬往上吸，所以梗在中脘的地方，这时候桂枝甘草汤。  \n\n诸位要有一个概念，肚脐中间属脾，肚脐上方属肾，肚脐以下属心，肚脐左边属肝，肚脐右边属肺；举例来说，如果肚脐上方有动悸，就要从肾脏下手去治疗；其它依此类推。  ', NULL, '桂枝甘草汤，茯苓桂枝甘草大枣汤', NULL, NULL, NULL, '69、发汗过多，其人叉手自冒心，心下悸欲得按者，$f{桂枝甘草汤}主之。 \n70、发汗后，其人脐下悸者，欲作奔豚，$f{茯苓桂枝甘草大枣汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615058323578950, '7271D9AB09F155E06C224B63A86B7CA5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 09:38:46', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5278, 318, 904000526, NULL, NULL, '芍药甘草附子汤', NULL, NULL, NULL, '73、发汗，病不解，反恶寒者，虚故也。$f{芍药甘草附子汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615069333962822, '48B352806E544596D67EFEB1C6946E15', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:23:34', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5279, 318, 904000525, '       伤寒，如果吐了又大下，肠胃就伤到了，结果心下逆满，就是胃的地方感觉到胀满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者。\n为什么会这样子?这人平素就有水饮，水停在横膈膜，\n         一种是平常喝水喝太快，慢慢累积在这里；\n        一种是思，思能伤脾，造成脾的运化不好，结果水的运化不好，土生金的时候，一部分会气化上来，一部分会停在这横膈膜上，横膈膜像海绵一样，里面都是水。\n\n    被吐、被下了以后，上下的水都没有了，这水就开始要动起来，这水不在胃的里面，如果在胃的里面，胃就会把它气化掉，这水停在胃的旁边，病人一动的时候，这水就开始晃了，头就昏了，西医说这是中耳不平衡，因为头在晕眩，和贫血不一样，贫血是眼前发黑，他是天旋地转，苓桂朮甘汤下去，把这水排掉，就 好了。所以起则头眩，移动或站起来的时候会晕眩，就是苓桂朮甘汤证；如果是躺在床上不动会晕眩，就不是苓挂朮甘汤证，后面会提到真武汤的时候，再说明。  \n\n     白朮就是因为湿太盛了而用的，健脾整胃最好的药就是伏苓、白朮，白朮能去湿，茯苓能把水利掉，桂枝甘草在中膈，如果在脐下就加茯苓大枣，所以这是桂枝甘草汤演变出来的，先是桂枝甘草汤，再来是桂枝甘草加茯苓大枣，再来是苓桂朮甘汤，所以苓桂朮甘汤专门去 中膈的水。  \n\n       伤寒，若吐若下后被吐被下后，水饮就跑出来了，平常不会的，结果心下逆满，胃里面胀满得很难过，然后气往上冲，因为这水没能气化上来，是水停在这里，当然感觉气下不去，呼吸的时候，气会往回逆，一般来说，横膈膜会下降，气才会充满，吐气的时候，横膈膜会上升，结果横膈膜都是水，它根本不下降，一吸它就满了，满了就会有气逆的现象。起则头眩，脉沉紧，沉代表病在里，紧就是塞，水就是塞的，因为水在中膈，没有在皮肤表面上，一发汗会动经，因为身体的血脉、经络、肌肉，都要靠我们的水分来滋养，一发汗就没有水分了，他就抽筋，所以身为振振摇，就是晃来晃去的，就中膈的水在晃，就用苓桂朮甘汤。临床上看到，晕眩得很厉害的时候会吐的，就可用苓桂朮甘汤里面再加半夏。 \n', NULL, '茯苓桂枝白术甘草汤', NULL, NULL, NULL, '72、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615069333962823, '5207FCC6D489C002C721B8A21AAF9BF3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:23:34', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5280, 318, 904000524, '        有两种情形腹胀满，一种是虚胀，一种是实胀，虚胀的病人感觉是$m{喜按}，实胀是$n{拒按}， 我们可以按天枢穴，实胀就是大便堵到了，虚胀是肠子的瓦斯气在里面，就是肠气很多在里面，所以厚朴生姜半夏甘草人参汤病人吃下去以后，病人会一直在嗝气，一直在放屁，然后肚子就消掉了，所以虚胀的时候是厚朴生姜半夏甘草人参汤证，如果是实胀的时候就是承气汤证。有一种人是平常大便就不太好，发汗发太过的时候，肚子真的大便干掉了就是实胀；还有一种就是肠胃虚弱的人，平常就不爱吃。津液一发，肠胃都空掉，没有津液，都是肠气在里面，就是虚胀。我们也可以问小便：小便淡白是虚胀；小便很黄是实胀。小便为什么加厚朴?厚朴能够宽肠降逆除气，所以病人会放屁，实胀一放屁，大便就下来了，虚胀就不会，虚胀会一直在放屁，让嗳气从放屁排出来；因为病人本来就太虚了，一发表，脾的功能就弱掉了，厚朴入脾，能健脾，能去脾的湿，但是厚朴去脾湿没有白朮强，厚朴去脾湿的时候，能利用脾湿来润肠，不像白朮让脾脏的湿干掉了，所以肠如果干掉了，厚朴可以润肠，可以增加肠里的黏液，让肠子蠕动，再加生姜，生姜能让胃很快的恢复；为什么人参甘草?因为病人的肠胃都虚掉了，把肠胃的津液补回去。为什么加半夏?降逆用的，不加半夏的话，气冲不出来，后面全部都是降逆、开胃、健脾的药；常常老太太，肚子很大，是虚胀，肠子总 是有问题，放屁很多，可以用这汤方，如果是实胀就用承气汤攻出来。承气汤证还有两种特别情形，一种是大便如鞭，因为大肠的内壁被燥屎遮蔽住了，所以大肠不吸收水分，因此下利，但是这种病人天枢穴会拒按，而且下利臭秽，另一种，大便如鞭状，那是因为大肠的通道被燥屎给堵住了，只剩下一个很小的通道，因此大便从很小的通道挤出来，所以像一条长长的鞭子一样。这些在后面讲承气汤的时候，还会有更详细的说明。', NULL, '厚朴生姜半夏甘草人参汤', NULL, NULL, NULL, '71、发汗后，腹胀满者，$f{厚朴生姜半夏甘草人参汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615069333962824, '6AA11D501B4F8FC987DDD52758D18F87', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:23:34', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5281, 318, 904000527, '    ', NULL, '茯苓四逆汤', NULL, NULL, NULL, '74、发汗，若下之，病仍不解，烦躁，四逆者，$f{茯苓四逆汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615072228024390, 'B19E274F999A85C89441EADA6EB5422A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:35:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5282, 318, 904000528, '       发汗后，恶寒者，虚故也，汗发太多后，身体虚掉了，这恶寒是表的恶寒，人身体虚掉了就有怕冷的现象，这种人用温药，桂枝加附子都可以，不恶寒，但热者，实也，发汗了以后，如果不恶寒，很热，这是实证，所以如果发了汗以后，身体怕冷代表是虚证，发了汗以后，寒还在的有两种情形，一种是寒没有发透，一种是人虚掉了，人虚掉时看得出来的，人会没有力气讲话，就不可以再发汗，还有一种是身体素壮的人，发了汗以后津液没了，但热不寒的，就进入了阳明证，阳明证是看不到寒证的，阳明证的时候，看到病人两眼很亮，因为阳气很旺，这就是实证，实就是东西堵到，因为桂枝汤发汗了以后，胃的津液没了，堵在胃里面，所以当和胃气，这时候用调胃承气汤。  \n\n       只热不恶寒者，产热机能亢进也。见烦渴者，为白虎证；见腹满者，为小承气汤证，见 腹满而谵语者，为大承气汤；只见热而不烦，为本方证。以病虽在阳明，尚不为重，故不曰 下而曰和。阳明指肠胃；仲师言胃，肠亦包括在内。人的胃，平常都有囤积食物在里面，在胃和十二指肠这一段，在下脘穴与建里穴有压痛，这就是所谓的调胃承气汤，调胃承气汤是承气汤里面最轻的一种，如果食物堵在小肠里面的时候，会少腹满，压压小肠募穴关元会很痛，平常大便很少，屁放得很多，就是堵在小肠里面，就是小承气汤证。小肠是经九转后出来，大肠很宽的，从升结肠到横结肠到降结肠到直肠，如果堵在大肠，就不会放屁了，天枢穴会有压痛，这时候就用大承气汤。  \n\n       临床上看到所谓的艾滋病，在西药治疗之前，都是阳明证，阳明无死证，是很好治疗的，西药治疗了之后，就会出现厥阴证，所以我们可以判断病人是死在西药的副作用上，不是死在HIV 病毒上。', NULL, '调胃承气汤', NULL, NULL, NULL, '75、发汗后，恶寒者，虚故也。不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615076508192838, '71537C885D387D69C05CE2F079245681', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:52:45', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5283, 318, 904000529, '       张仲景的胃就是肠，汗的来源就是肠胃的津液，为什么烦躁不得眠?因为胃中干只是胃里面比较干燥而已，并没有大便结实到，喝一点点水就好了，欲得饮水者，少少与饮之，如过大量灌下去就成水饮了，因为发汗了，肠胃的力量没有那么大了，如果只喝一点点刚好蒸发掉，如果大量的水下去，在肠胃的功能很衰弱的时候热力不够把水化掉，会梗在中间就变成水饮，就变成苓桂朮甘汤证了，头会昏眩。  \n\n       平常针灸在治疗便秘的时候，下支沟、照海，支沟、照海是通便的，奇穴用肠关，肠关不管是大便不通或下利，都可以用。如果病人没有下利，用葛根汤就去掉了，如果有下利就用葛芩连汤，葛根汤证没有治好，化热转到里面去就变成葛芩连汤证。下利的时候，肚脐上灸一灸也可以。如果是寒实，肠胃功能没有蠕动，如果舌头里面津液很多，舌苔白白的，这时候可以灸天枢，大肠的募穴，如果舌头干燥，舌苔黄黄的，就是热实，这时候就不能灸，用下针的，一般来说大约下针后，三到四个小时，大便就出来了。  \n\n        当病人吃下发汗剂，如桂枝汤、麻黄汤、葛根汤发汗的时候，汗一发到表面，就是我们的白血球，免疫系统把病毒排到表面，这废水在中医来讲是病邪，邪已经出表了，邪出表后，正的、好的津液，自然会顺着三焦油网回到身体里面来，这是正常的；如果病人的身体不是很好，结果药一下去后，水跑掉了，而感冒也去掉了，结果病人产生了一种现象，脉浮，小便不利，照理说麻黄汤吃下去，有的发汗，有的小便会比较多，都是一种排解的功能。浮脉并不是真正有表邪，而是这水到表面以后，没有力量回来了，会遇到这种情形就是这是本来体虚之人，这身体就是讲肠胃，消化系统比较虚弱的人就会有这种现象，水停在皮肤表面以后，病人感觉肠胃的元气还是没有恢复，病人自然口渴，所谓消渴就是喝水喝很多，还是不能止渴，脾胃功能差，胃里面化水的力量不够，喝再多的水，还是口渴，喝下去的只是水，并没有经过脾胃的经脉，水经过经脉会从舌的下方慢慢生出津液，所以水喝下去并没有变成津液，因此水喝下去消渴不能止渴，实际上是肠胃的津液没有回头，没有回头的时候，水就停在皮肤表面上，其它的水停在中焦，如果喝得太多，会从大肠排掉，并没有完全吸收，所以小便量自然减少了；为什么病人会有微热的感觉?因为全身上下肠胃的地方是最热的，跟炭炉一样，所以水喝下去，马上就气化掉了，当胃热不够的时候，这热跑到哪去了?前面发汗的药把它都带到皮肤表面上去了，胃的热跑到皮肤表面上去了以后，所以病人感觉到微热，所以开了发汗药后，病人发汗发到表后，水回头的力量没有了，这现象就是五苓散证。散就是用粉剂。如果用汤剂，速度太快了，皮肤的水会来不及被带走。\n  \n      小便不利，张仲景想把皮肤表面的水拉回来，让它从小便排掉，有两种状况；一种是皮肤水肿，上半身水肿的时候，有些妈妈们早上起来手脚都肿，就是五苓散证，如果摸他的脉很虚弱，五苓散吃下去，让表面的水从小便排掉，五苓散证就退了；还有一种是很扎实的，脉很强很足的，把水肿去掉的是用汗法，肚脐以上的用发汗；如果体虚得津液不够的就不可以用发汗的，这时候就要把津液带回到胃里面，然后气化出来，由小便出来，所以五苓散也是利尿剂。  \n\n        泽泻本身是很苦寒的药，最主要的功能是利尿利水，全身上下的水都可以用泽泻去利，泽泻本身入肝经，所以它通利的力量很强，临床上有病人光吃一味药泽泻，西医叫脂肪肝，就好了，都清利出来了，所以在处理肝病的时候，像肝积水，用泽泻把小便利出来，全身上中下表面都可以用泽泻来利，所有苦寒的药，就是消炎的药，所以肝炎可以用泽泻，小便黄 黄的很粘稠的就可以用泽泻，泽泻不但可以清汗，把肝里面的病毒清出来以外，同时把脏的排掉把新的留在里面；茯苓利中焦，猪苓利下焦，猪苓专门利下焦的水，中药一般的利尿剂有五苓散和猪苓汤，下焦的用猪苓汤，会用到猪苓汤的大多是膀胱结石、肾结石；茯苓利中焦的水，茯苓和白朮并用的时候，可以健脾整肠，让肠胃的功能马上恢复，最后加桂枝，桂枝不要加太多，因为不是用来发表，因为这几味药做成散剂，吃到肚子的时候，靠桂枝的力量把泽泻带到皮肤表面上去，泽泻和麻黄刚好相反，麻黄往外走，泽泻是往里带，把所有的表水都带回来，带回到中焦后，再带回到肠胃后，靠茯苓把它利到下焦，再靠猪苓把它从小便排出去。  \n\n        剂量的时候，猪苓三钱，泽泻六钱，茯苓三钱，桂枝二钱，白朮三钱，所以猪苓、茯苓、白朮的剂量是一样的，为什么重用泽泻?因为其它的药，都没有办法把皮肤表面最高的水清出来，为什么会有这现象?因为病人素体虚，最重要的是他的脾脏是虚的，且湿很重，如果病人是桂枝汤证，吾人开发表药的时候，要再看舌苔，如白白厚厚的，湿的，就知道脾脏是素湿的，这时候如果桂枝汤下去没有加茯苓白朮的话，一发就会变成五苓散证。一般来说白朮是等量的，所以糖尿病、虚胖、有水肿现象的病人。五苓散就可以解决掉；泽泻苦寒能生津止渴利小便，猪苓可以利下焦的水，茯苓可以除烦利中焦的水，桂枝能把泽泻带到表面上，所以五苓散如果没有桂枝，利尿的效果就不会很好，小便可以解，但是皮肤水肿还是会在里面；所以如果年纪大的人，早上起来，脸手都肿，问他有没有口渴?有，不能止渴，就是五苓散证。  \n\n      成无己曰：发汗已解，胃中干，烦躁不得眠，欲饮水者，少少与之，胃气润则愈。若脉  \n浮者，表未解也，饮水多而小便少者，谓之消渴，里热甚实也，微热成实，上焦燥也，与五苓散生津液，和表里。  \n\n      五苓散证的消渴还算不严重，如果口很渴，并没有小便不利，皮肤上并没有肿，五苓散就去不掉了，大部分是白虎汤或承气汤，五苓散没那么强。  \n\n      五苓散在过去是出门在外随身携带的药，用来预防疫病，也就是瘟疫；如果遇到病人有表证，但是又不能用发汗来解的时候，病人已经胃中干、烦躁不得眠了，这种不能发汗的情况，就要想到五苓散，把病毒从小便排出。五苓散的主证是小便不利而且口渴。  \n', NULL, '五苓散', NULL, NULL, NULL, '76、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水者，少少与饮之，令胃气和则愈。\n77、若脉浮，小便不利，微热，消渴者，$f{五苓散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615079051243590, '0AA4C41A42ADD946D9058B8F51DD5EF9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:03:06', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5284, 318, 904000536, '      栀子，这药专门能去上焦的热，上焦就是讲肺、心，栀子去上焦的热和石膏不同，石膏去的是实热，栀子去的是虚热，实热和虚热病人都会感觉烦躁，但是虚热的人舌苔是淡黄，实热的舌苔黄而且干燥，还有看脉的力量如果是比较无力，重按就不见了，就是虚热。临床上看到病人有黄疸的时候，看到的是虚热，现代说的急性肝炎也可能用到栀子，豆豉这药本身也会发汗，但是没有桂枝麻黄那么强，是介于补药和发表中间的药。  \n\n       发汗吐下，会给病人发汗一定是有表证，汗吐下就是水已经去掉了，水去掉的同时，病人身体是很虚弱的，因为津液伤到了，如果半夜津液慢慢回来，胃口开了，吃东西就好了，就不用管他了，有的人没有办法恢复，就变成虚烦不得眠，如果严重的时候，就会反复颠倒，就是在床上睡不着，翻来覆去，心中很懊憹，就是心中很烦闷，胃里面怪怪的，所以栀子豉汤，这个药是病后调理的药。少气就是四肢没有力量，手脚的力量不够，加甘草进去，甘草能健脾胃，能解百毒，除去胃中坏死的食物。若呕者，加生姜，生姜本来就是除烦止呕的，\n       为什么不加半夏?因为这剂药是调理的，半夏是治病的，不需要用半夏那么强的药，因为胃中没有停水，发汗吐下后，津液才刚回来，还不是很足，用了半夏又会把津液去掉，所以只用生姜；金匮中治疗妊娠呕吐不止的干姜人参半夏丸，孕妇吐水不止，就一定要用到生半夏。\n      临床上用这栀子豉汤一个礼拜，急性肝炎的指数就退掉了，还有更好的药在后面，这只是最初期的。\n      虚烦不得眠，心中懊憹，小便黄黄的，吃东西吃不下去，手脚没有力，恶心，想吐，都是肝炎的症状，所以一般身体虚的时候，一发表。发完后才会有这种现象，就用这方，所以这方是病后调理的汤剂。  \n\n       因为血虚，常常晚上睡不着的时候，灸灸三毛，睡不着，虚烦的时候，魂在眼睛上面，三毛刚好在肝经脾经交会的地方，因为脾是生血的，肝是藏血的，灸它的时候，血马上就进入肝，魂就归肝，自然就睡了。  \n\n       栀子豆豉两者皆属苦寒之品，苦可清心除烦，寒可消炎退热，且栀子能降血压，使脑神经宁静，豆豉能生水液，以滋胃阴，两者合用，成为清心宁神之良方。虚烦不眠，大多起于热病之后，余热未清，正气未复之时，栀子豉汤实有特效。  \n\n        栀子豉汤，为温病汗吐下后余热未尽之佳方。凡温病最容易耗散阴液。阴液既伤，虽经 汗或吐或下后，病邪虽解，残余之热毒往往不净，成为午后潮热或五心烦热、失眠、心烦等证；所以这个证是发汗吐下以后才会有的，没有发汗吐下的话，就看不到这个证。还有一种情形，就是服用发表药以后，如果吃肉类食物所产生的虚热，也会出现这种症状。  \n', NULL, '栀子豉汤,栀子甘草豉汤,栀子生姜豉汤', NULL, NULL, NULL, '84、发汗吐下后，虚烦不得眠，若剧者，必反复颠倒，心中懊憹，$f{栀子豉汤}主之。若少气者，$f{栀子甘草豉汤}主之。若呕者，$f{栀子生姜豉汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615090575097926, '77F8709AD47F3A7D0E8C56B6639B4189', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:49:59', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5285, 318, 904000535, '        发汗了以后，肠胃的津液发光了，肠胃整个虚掉了，胃阳不足了，胃的功能就停住了，煮药喝汤他不受，若再给他吃发汗的药，胃里面的东西会吐出来，会更严重，这是提醒发汗的药不要开太过了，病人的胃整个干掉了，就像好几天没吃东西了。整个胃黏在一起，药一下去就吐掉。', NULL, NULL, NULL, NULL, NULL, '83、发汗后，水药不得入口为逆。若更发汗，必吐下不止。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615090575097927, '388395F3306AC478F3FBD672C0F7E7A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:49:59', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5286, 318, 904000534, '       这大多是发汗发太过了，所以喝水少少与之就好了；喝太多了，胃没有办法把水消化掉：水停在中焦，肺气就没有办法下降，正常的津液应该要自肺下到五脏六腑，但是中焦堵到了，水气下不去，就会喘，如果遇到这种情形用五苓散来解。  \n\n      柯韵伯曰：未发汗因风寒而喘，是麻黄证。下后微喘者，桂枝加厚朴杏仁证。喘而汗出者，葛根黄芩黄连证，此汗后津液不足，饮水多而喘者，是五苓散。平常感冒药桂枝汤、麻黄汤、葛根汤剂量如果开得很好，刚好把病毒赶出去，没有进入身体，然后让好的津液留着，如果开的剂量不足，汗一发出去，四分之三的病毒发出去了，发汗之后津液还会回胃中，四分之一的病毒随着津液进入肠胃，结果变成肠胃发炎下利，用葛芩连汤下去解利，津液不足，用葛根把津液补足。  ', NULL, NULL, NULL, NULL, NULL, '82、发汗后，饮水多，必喘，以水灌之，亦喘。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615090575097928, 'E68A0617DD8B3EC5C4850A8D7F069E64', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:49:59', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5287, 318, 904000533, '       消化系统里，平常食物里面的水，被胃吸收了以后，进入脾脏，水一部分进入上焦，一部分进入肾脏的下焦黏膜，一部分进入脑，一部分再进入肺到全身四肢上去，重发汗，医生发汗太过了，津液伤到了，到脑部去的津液就伤到了，结果脑没有收到营养，病人就耳聋了，耳聋是因为肾脏虚掉了，所以肾主脑，脑为髓海，所以重发汗，虚，故也。  \n\n        津虚即阴虚，阴虚则为脑转耳鸣或耳聋矣。所以津液虚掉就是阴虚，阴虚就要把津液补足，所以常常用人参、红枣、茯苓、炙甘草、生姜来把津液补回去，临床上作加减。张仲景在补虚的时候，如果是轻补用生姜、炙甘草、大枣；中补用白芍、生姜、炙甘草、大枣；重补时用人参、白芍、生姜、炙甘草、大枣。如此而已，不会滥用厚腻滋阴的补药来补虚。  \n\n    《内经》谓 $m{精脱者耳聋}，盖即此理，总观此条，叉手自冒心。为阳虚水停心下作悸，与69条同，可以桂枝甘草汤治之；耳聋无闻为重汗阴虚，宜附子汤或苓桂朮甘汤治之。加附子就能把肾阳壮起来，让肾的功能很快恢复，所以年纪大的人，耳背就是肾阳不足了，这就是附子证。', NULL, NULL, NULL, NULL, NULL, '81、未持脉时，病人叉手自冒心，师因教试令咳，而不咳者，此必两耳聋无闻也。所以然者，以重发汗，虚，故如此。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615090575097929, 'E0720E5689F2B3145380649C8B5ACFEE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:49:59', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5288, 318, 904000532, '       胃里面的水，发表发到表面以后，阳往上冲，阳被发到皮肤上去，阳就居上居外，下面的水就往上吸，下焦的水应该小便小掉的，结果虹吸原理被往回头走，这样就有间隙，有表里证，喝水就吐出来了，下面的水往上走，胃又没有办法蒸发掉，喝进来的水，就不能受，所以用猪苓、茯苓、泽泻，把下焦的水利掉，又健脾整胃，恢复脾胃的功能，所以用五苓散。临床上常看到有些病人因为喝水喝得太多太快，结果水停在中膈，也变成五苓散证。五苓散 里面用到少量的桂枝，配伍非常精妙，桂枝有温阳化水的功能，这温化的功能是温胃，如果五苓散少了桂枝，像温病派那样不敢用桂枝，那么效果就差多了。', NULL, '五苓散', NULL, NULL, NULL, '80、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆，$f{五苓散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615090575097930, 'E784B2A1055099F24F24E2EA17ADE26D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:49:59', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5289, 318, 904000531, '       所以在病人感觉很渴而且脉浮的时候，就要想到五苓散，如果渴而且壮热，午后潮热，那是白虎汤证，平常看到渴很容易误解为阳明证；不渴而心下悸，中焦有饮会动悸的，动悸的时候用茯苓，把水利掉，所以用茯苓甘草汤。以茯苓治悸，桂枝降冲，桂、苓化水，生姜温胃，甘草缓中；桂枝降逆，这最主要的逆是冲脉，心脏的血往下从子宫出来就是月经，如果心脏的血下行的力量不够，或心脏需要的血量不够，土生金，血变成乳汁，血停在上焦就会燥热，所以怀孕或喂母乳的时候，比较燥热，所以退奶的时候用桂枝让冲脉的力量加强往下走，桂枝可以通利冲脉，让心血往下导到子宫，所以桂枝不仅可以走肌肉，还有这功能。桂枝与茯苓等量来把水利掉，然后借着生姜与炙甘草把津液补回来。  \n\n       如果我们用汗吐下的方法，本来病人不口渴，用了汗吐下的方法以后口渴了，代表病邪已去，我们给水让病人少少饮之就好。但是如果津液已经伤到，或是发汗以后，因病人体虚导致还有部分的水还停留在皮肤表面，有脉浮数、汗出、烦渴、小便不利的时候，就想到五苓散。  ', NULL, '五苓散,茯苓甘草汤', NULL, NULL, NULL, '79、伤寒，汗出而渴者，$f{五苓散}主之。不渴而心下悸者，$f{茯苓甘草汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615090575097931, '2254ACA86D532E8895C00EAB203B7E7C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:49:59', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5290, 318, 904000530, '     汗发了以后，病人口渴，脉浮数，病人就是五苓散证，因为水都在皮肤表面上，中焦没有水了，所以病人会烦躁。  ', NULL, '五苓散', NULL, NULL, NULL, '78、发汗已，脉浮数，烦渴者，$f{五苓散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615090575097932, '67EAD9AC4C621BB1C0EC0CD8AC07F1AF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:49:59', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5291, 318, 904000539, '       此条和71条：$n{发汗后，腹胀满者，厚朴生姜半夏甘草人参汤主之。}作比较，厚朴可以宽肠，生姜、半夏、甘草、人参都能健脾整胃，吃了病人会一直放屁，这只是发汗了以后造成的腹胀，只是胀满；通常大便堵到的时候有承气汤剂，虚满的时候有厚朴生姜半夏甘草人参汤；\n      87条是伤寒攻下以后的心烦，腹满不一样，除了心烦，腹满，还有卧起不安，心中躁烦，就是上焦心肺的地方，用栀子来除烦，去虚烦产生的虚热，腹胀满的时候用厚朴，厚朴把脾脏的湿移到肠间，可以排气，把所有的肠气通通排出来；枳实这药可以去结实，结实就是东西结成一块，实际上，枳实并不是把它打散，也不是把它排出来，因为肠子里面已经有干燥的大便，大便干了跟肠壁黏在一起了，遇到这种情形要靠枳实，枳实可以把肠子打开来，肠一宽起来，让肠壁的黏液增加，燥屎就会离开来，枳实的功能在这里，所以大小承气汤都有用到枳实，枳实除了可以把肠的结毒去掉以外，连胸腔的结毒也可以去，所以枳实不单单是打开肠壁，枳实这药一片一片的、一圈一圈的，切出来像肠壁一样，连血管、胆管也可以扩张起来，所以心脏病的时候，会用到枳实，枳实专门打开通道、去除管子里面的脏东西，\n      《本草》写枳实去$m{结毒}，结就是有东西：在胸闷、胸痛、胸满的时候，张仲景一律去白芍用枳实。枳实也长得像心脏，把心脏通到小肠的血管打开，如此大肠小肠的蠕动就会增加，所以承气汤会用到枳实。  \n\n栀子厚朴枳实汤没有用到大黄。因为并不是大便结到，它只是一部分结到，小小的一点点结到，所以吃了这药也是从大便排出来，因为没有大黄，所以不会拉肚子，只是大便上很好而已。', NULL, '栀子厚朴枳实汤', NULL, NULL, NULL, '87、伤寒下后，心烦，腹满，卧起不安者，$f{栀子厚朴枳实汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615123804373062, '78BAE46A0C570626F3F70FD840F1D02C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:05:12', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5292, 318, 904000538, '   都是余热未去，攻下了以后造成的，心中结痛者，不是心脏痛，是胃里面难过，也就是胃痛，伤寒论里面讲心就是胃，讲胃就是肠。刚刚讲的汤剂都是病后调理用的，不是用来治病的。  ', NULL, '栀子豉汤', NULL, NULL, NULL, '86、伤寒，五六日，大下之后，身热不去，心中结痛者，未欲解也，$f{栀子豉汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615123804373063, '7666B60F88A25F0907F409804B81A207', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:05:12', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5293, 318, 904000537, '发汗，被攻了以后，感觉烦热，胸中窒者就是呼吸呼不过来，就是栀子豉汤。  ', NULL, '栀子豉汤', NULL, NULL, NULL, '85、发汗，若下之，而烦热，胸中窒者，$f{栀子豉汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615123804373064, 'D3F6C933CBCECB5A538E3F8B1FBE5B77', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:05:12', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5294, 318, 904000540, '       这是治疗虚证，病后虚烦主要的处方。医生一定是看到病人有承气汤证，譬如午后潮热或大便不通的情形，才会用攻下的药；攻下了以后，把大便都清掉，病人的身热并没有完全去掉，反而造成微烦，代表里面虚掉了，通大便的药都是寒凉的药，寒凉的药一下去，排东西以后，身热还没有去，代表里面寒很盛，本来就是寒，再用寒药下去，虚寒就更严重了，这寒一定在肠子里面，所以在病后要让他恢复加干姜就好了，干姜这药完全是$m{温中}的$fm{中}就是$n{肠胃消化系统}，干姜的温就是让肠胃的热度恢复，所以肠胃的蠕动功能恢复就是靠干姜；生姜是散寒，把寒散掉，但是没有温的力量。所以干姜的热力比生姜大很多；开这处方的时候，病人的舌苔一定是很薄白，脉一定是很微很弱，平常摸不管是浮中沉，摸到跳一息四至的时候代表是胃的脉，结果摸虽然是四至，但是脉形很细，很弱，弹起来没有力量，就知道胃寒很盛了，这时候知道寒在胃上面，单纯是胃寒而已，所以加干姜在里面。当上焦与中焦有虚寒的时候，我们会用到干姜；如果是下焦虚寒，就会用到附子。 ', NULL, '栀子干姜豉汤', NULL, NULL, NULL, '88、伤寒，医以丸药大下之，身热不去，微烦者，$f{栀子干姜豉汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615127744532550, '6674732FB3D1544A378D31E31279CBCB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:21:14', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5295, 318, 904000544, '      中医讲的淋家，不单单是包含了西医的淋病、性病在内，小便有石淋，下消有石头在里面也算，\n         石淋，西医可能讲成膀胱结石或肾脏结石；\n         膏淋，小便浓浓的，浓浊白白的，可能里面发炎了，可能是把精液都小出来了，因为禁不住了；\n         血淋，小便出来带很多血，小便有问题的人，大部分平常血就素虚了，\n这时候不可以发汗，一发汗的时候，一定会便血，因为汗会使水没有了，只剩下血了，血里面的水不够了，单纯只有血的时候，体温会升高，温度一升高，血管就破掉了，血就出来了，所以这种病常常用猪苓汤。', NULL, NULL, NULL, NULL, NULL, '92、淋家不可发汗，发汗必便血。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615131592368198, 'B992C1A1602EA235C85B78D87CA4DE6B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:36:53', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5296, 318, 904000543, '       在《内经》里面说咽喉的部位是三阴所会，足少阴、足太阴、足厥阴三阴经都会在咽喉的地方，咽喉平常就是很干燥的人，不可发汗，所以喉咙常常觉得口渴的，就是阴虚了，这种人不可以发汗，一发汗就变成真武汤证了；这种人需要补足他的阴虚，可常喝麦门冬汤，喉咙是三阴所会，肺的上口，所以要开润肺的药，这麦门冬汤专门是润肺的，麦门冬汤单纯润肺而已，常吃麦门冬汤的人，肺的津液一定很足，肺的功能会很好，只是咽喉干燥的，麦门冬汤很好，而阳明证的大烦渴，就要用白虎汤了。感冒的时候，病人若喉咙痛，属于太阳 温病，就要想到葛根汤。这里的咽喉干燥，不是葛根汤证，不要混淆。  ', NULL, NULL, NULL, NULL, NULL, '91、咽喉干燥者，不可发汗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615131592368199, '5FF497D8B07494FE0C4B10709E4A7407', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:36:53', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5297, 318, 904000542, '      这条辨讲的是病人本身就是素虚，医生不知道，桂枝汤一下去发汗了，没有好，造成病人发热，心下悸，头眩、身润动，发汗的药吃到胃里面去的时候，所有发出来的力量，从肠胃脏腑都会动，动的时候，肾脏三焦的水全部往外走去发汗，这是很好正常人的体格，但是如果病人素虚的，里面寒湿很盛的人，汗一发掉以后，病证没有解，成为寒湿兼有发热，这发热不是伤风感冒的热，是虚热，发汗就是刺激免疫系统让它发出来，所以一发汗的时候，脏腑的能源通通跑到外面了，里面是空的，但还有一部分的水在底下，没有完全发掉，这时候会心下悸，水要往上走，就是寒在里面，发汗后胃阳功能没有了，水没有办法化掉，水就动悸在这边；头眩，为什么会昏眩?因为水在中膈，就像苓桂朮甘汤证一样昏眩；振振欲擗地者，就是头重脚轻的现象，为什么?人身上有阴有阳，阳虚就是比正常的阳少很多的时候，阳本身性很轻，阴比较重，阴阳混在一起才能停在中膈下膈，一发汗，阴阳分开来，阳就往上冲，冲上去的阳，中医就叫作浮阳，头会很重，阳气在上面下不来了，这种症状大多是少阴证，少阴讲的是肾，肾虚的人就可以看到，平常如果不注意到肾虚，或不知道，一发汗就有这现象：万一吃了发表的药，吃完以后病人有头重脚轻的感觉，又心下悸，常常昏昏沉沉的，这是真武汤证。为什么身润动?本来身体虚就是津液不足的现象，筋和肌肉是靠津液来滋养的，津液不够就会润动跳动。 ', NULL, '真武汤', NULL, NULL, NULL, '90、太阳病，发汗，汗出不解。其人仍发热，心下悸，头眩，身润动，振振欲擗地者，$f{真武汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615131592368200, '127D06AAEF7CDAB0A977C62DACDDB32D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:36:53', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5298, 318, 904000541, '   凡用「栀子豉汤」其病人旧有肠胃虚寒,大便微溏者,不可与服之。溏就是很稀,像泥巴浆一样,拉出来有水的,大便溏的人,大多是寒湿,里面有寒湿,栀子本身是寒凉的药,遇到这种寒湿的病人,再开寒凉的药,寒湿会下陷下去,跑到更深的地方,病人就越虚,大部份这种症状的时候,加点干姜进去,或加白朮去里湿,加茯苓让湿从小便排掉,加在栀子豆豉汤里面无所谓,所以中医在看病的时候,是以寒热为主,后面还有一些情形很特殊,有的病人上焦很热,摸脉有很细很沉,下面是冷的,小便是白的,处方的开法,如何让热药往下走。寒药往上走,这就是开处方的技巧。', NULL, '栀子豉汤', NULL, NULL, NULL, '89、凡用$f{栀子豉汤}，病患旧微溏者，不可与服之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615131592368201, '301B7CAA3E5DC33B40171DF172069758', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:36:53', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5299, 318, 904000551, '      常常在伤寒的时候，本来是麻黄汤证，结果攻下，一攻下的时候，伤寒陷下去了，如果没有下利就是寒实结胸，如果得到下利，结果病人一直下利停不下来，清谷不止。吃进去什么，拉什么出来，吃东西下去都没有消化的时候，表示肠胃已经虚寒掉了，寒就是没有蠕动了，没有吸收功能了，因为前面有攻下的药，攻下的药都比较寒凉，寒一遇到寒就更盛，一吃就拉，这就比较危险，身疼痛者，急当救里，像这种虚证会身体疼痛，因为身上的肌肉血脉筋骨都是靠营养来供应的，结果食物营养吃下去就排掉而造成的，救里的时候用四逆汤，救里了以后，里证没了，大便也很正常了，这时候身疼痛，清便自调者，谓小便正常的，会身疼痛代表有表证，常常小孩下利的时候，没有小便，因为水都从大便排掉了，所以利小便，大便下利就可以止掉了，所谓清便自调者，代表小便正常了，里阴回来了，津液也回来了，这就给他桂枝汤，如果证是麻黄汤，就给他麻黄汤。  \n\n     伤寒应先解外，而医误下之，成为下利清谷不止者有之，成为阳邪下陷，协热下利者有之；一为虚寒，一为肠热。虚实寒热绝对不同，应详细而分别之。虚寒者宜温里，四逆汤为主方。肠热者宜清里，葛芩连汤为主方。大便很臭的就是肠热，一般会得到葛芩连汤的，大部分他的表证都是葛根汤，葛根汤证本来就是津液不足之人才会有的，很多小孩平常跑来跑去的，汗流得很多，一得到感冒就是葛根汤证，因为津液没了；临床上看，葛根有预防的功能，预防病传到阳明，所以如果葛根汤开错了，开成麻黄汤、桂枝汤，病人就转到阳明证，因为发汗发太多了；病人病在表的时候，不一定病毒在哪个位置，桂枝汤、麻黄汤发表了，表的病毒去了，可是病毒已经进入阳明了，结果病人就下利，就转成葛芩连汤证。  \n\n     同为误下，一为虚寒，一为肠热，则视其人之秉赋如何而异。秉赋素薄，肠胃消化机能不强者，每为虚寒下利；素有湿热，平时喜膏粱厚味者，每成肠热下利。  ', NULL, '四逆汤,桂枝汤', NULL, NULL, NULL, '100、伤寒，医下之，续得下利，清谷不止，身疼痛者，急当救里；后身疼 痛，清便自调者，急当救表，救里宜$f{四逆汤}，救表宜$f{桂枝汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615145620291654, '438BA31531D02D47F43B232630E6D8C3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:33:58', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5300, 318, 904000550, '此条辨说可能是误诊，或病人自己吃坏的。学者至此，必知何时当可汗或吐或下了。  ', NULL, NULL, NULL, NULL, NULL, '98、本先发汗，反而下之，此为逆也；若先发汗，治不为逆。\n99、本先下之，反而汗之，为逆；若先下之，治不为逆。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615145620291655, '507EED3F6994BA5976C0C14CD738AF4D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:33:58', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5301, 318, 904000549, '       必吐蛔，不会这么快的，而是人身上有虫的时候，有虫的人大多胃中寒，胃里面寒冷的人虫才会生，这虫的体温跟人的体温一起动，如果体温很冷的是时候，虫、虫卵就开始发了，如果体温很热的时候，它还不会发，如果病人是肠胃虚寒、素体虚寒的人、肠胃比较冷的人，开桂枝汤的时候，生姜要改成干姜，结果没换，一发掉了以后，胃的津液就更少了，里寒会更盛，这时候胃里面冷掉了，一段时间后虫就出来了；所以张仲景在桂枝汤里面要用甘草，因为甘草可以解百毒，把肠胃里面不好的东西清掉，因为感冒一段时间后，肠胃里面的东西会坏死掉，变成虫跑出来了。中药有巴椒就是蜀椒，可以杀虫的。  \n\n      张隐庵曰：夫阴阳气血皆生于胃府水谷。病人有寒，胃气虚矣；若复发汗，更虚其中焦之气，则胃中冷，必吐蛔。  ', NULL, NULL, NULL, NULL, NULL, '97、病人有寒，复发汗，胃中冷，必吐蛔。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615145620291656, '2377CDAF7F986E0952A882C81E957521', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:33:58', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5302, 318, 904000548, '     此条意味着本阳明有余之人，平时就是多汗之人，遇到这类人时，使用发汗药物，就等于是汗上加汗，重发汗后，血中水不足。  \n\n       是心神无所依，就出现恍惚心乱，更且胃中津液必竭，燥气上升，大肠传热于膀胱，造成小便短赤，因而阴疼。此段言与禹余粮丸，方已失传，后有王日休补曰：用禹余粮，赤石脂各三两，赤小豆半升，为末，制丸。其实临床上用人参、甘草、生姜、红枣把津液补回来就可以了。  \n\n     此条就是遇到很容易出汗的人时，又必须使用发汗药时，可以仿照桂枝汤法，在服完汤药后，喝点稀饭以助发汗就可以，不需要使用大剂的发汗药，以免伤到正常人的津液。  \n', NULL, NULL, NULL, NULL, NULL, '96、汗家重发汗,必恍惚心乱,小便已阴疼,与$f{禹余粮丸}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615145620291657, '6A5E52D30B0BDCF3FB9695AB6606609E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:33:58', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5303, 318, 904000547, '       所谓亡血家就是指脱血之人，因此遇到素有咳血，便血、贫血，或是有内出血之病人时，我们是不用发表之药物的，简单说就是如果遇到已经贫血之人，看上去脸色苍白，嘴唇血色不足，误服用发表的中药时，病人就会出现怕冷而全身战栗的现象。亡血之人呈现的症状就是所谓的阴虚，此时唯人参四逆汤或附子理中汤可以救，如果亡血家遇到表证时又非用发汗药时，我们可以给予像小建中汤加葱豉之类，或用小柴胡汤来和解这表证，一定要避免使用辛温发散的药物。  ', NULL, NULL, NULL, NULL, NULL, '95、亡血家，不可发汗，发汗则寒栗而振。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615145620291658, '03CEE38786B8FBF9634253412AF7BDB6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:33:58', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5304, 318, 904000546, '       衄家就是经常容易流鼻血的的人，称为衄家。由于三阳经聚会于额上，今此处易出血，已经明示三阳经血俱虚，由于发汗药物的药性都是向上向外发散的，中医认为汗血同源，意即此人本已失血，此际如果给予发汗的药物，必然加重亡阴，因此额上天仓位下陷，这是气血两虚之候。脉急紧，是因为阳气受到发汗药物的激发而产生阳亢的现象，这种阳亢的现象是阳虚产生，因为发汗亡阴所导致的阳虚（校正注：疑为“阴虚”）而阳亢，造成脉急紧。  \n\n       人的眼睛受血滋润，原本血不足之人，因为误受汗药，使血更伤，因此血下贯目，造成双目无法合住。又因为阳虚而血少，使得卫气不行于阴，阴阳不相合作，于是失眠不寐。  \n\n       一般如果时常流鼻血之人得到表证需要发汗时，吾人多给予像黄连阿胶鸡子黄汤，加上葱豉汗之，利用黄连苦寒来降虚热，使热血不升，阿胶鸡子黄滋阴补血，柔和血管，令血不外溢，葱豉稍微汗之，就可以解之，或小柴胡汤亦可。 ', NULL, NULL, NULL, NULL, NULL, '94、衄家不可发汗，汗出额上陷，脉急紧，直视不眴，不得眠。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615145620291659, '95732F5EA3A6242C308D9278013FD1C2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:33:58', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5305, 318, 904000545, '       什么叫疮家?一个是未化脓，一个是已化脓，现在讲的是第二个，已化脓的不可发，未化脓的疮家，必须用解表，就是疮家反而要用表药来让他好，指的是没有化脓的时候，化脓就不可以用表药了，化脓的定义是脓疮已经破掉了，脓水流出来了，这时候就不要发汗，但是平常在还没有破的时候，就要用表药，例：病人的皮肤表面，一块一块的脓疮，但是都没有化脓，用桂枝汤发表?一发让药到皮肤表面上来，这时候用白朮附子，白朮附子令皮肤表面上消炎的力量很强，把脓逼出来，反而是最好的药，《内经》说疮家要发汗，这里面的定义是还没有化脓。即使虽身疼痛，就是疮家有表热的时候，也不可以发汗。  \n\n       疮家有二说：一为受金疮流血过多之贫血症，一为久患溃疡脓血过多之血虚症或淋巴外 漏之液亏症；总之，属于血虚、液虚，发汗则阴愈亏，致组织干燥，成血不养筋之窒病，故不可发汗。所以有用小建中汤来温补取微汗，或用小柴胡汤来和解之。  ', NULL, NULL, NULL, NULL, NULL, '93、疮家虽身疼痛，不可发汗，发汗则窒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615145620291660, '5CB5DB4F12B5728D137DC52A64A7D359', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:33:58', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5306, 318, 904000560, '身热，恶风，颈项强，这三样是太阳证，胁下满是少阳证，手足温而渴者是阳明证，所以这条辨是说明三阳并病，必须合解少阳，小柴胡汤主之。这就好像针灸里面所教过的担法。  ', NULL, '小柴胡汤', NULL, NULL, NULL, '110、伤寒四五日，身热，恶风，颈项强，胁下满，手足温而渴者，$f{小柴胡汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384198, 'A86EC67967A0489D7C0EE83027AC4711', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5307, 318, 904000559, '       这条辨是说，医生看错了，病人得病一段时间以后，医生以为病人已经进入阳明证了，脉迟浮弱是说病人的脉浮、弱、迟，所谓的迟脉，就是一息二下很慢，病人本来就是身体虚的，阳明证的时候，手掌与脚是热的，医生看病人手足温，就以为病人是阳明证而攻下，医二三下之，攻下了以后，病人本来身体就虚掉了，攻下的药都是寒凉的药，造成胃里面更寒，胃里面都没有蠕动，食物都吃不下去了，所以胁下满痛，造成脸孔和身体都发黄了，\n      《内经》讲五脏的正色：肝是青色，心是赤色，脾是黄色，肺是白色，肾是黑色，当病人病重的时候，一看到病人脸整个是黑的，就是肾，很多人脸色发青都就是肝，但是这些颜色都是枯燥干干的，所以肝病到后来，整个脸色都发青，就是肝脏的原色，就很危险，同理尿毒的病人身体脸色都是黑的。因为被攻下，所以面目及身黄，就是脾脏的颜色，因为脾主运化，是造血的地方，是食物进来消化了以后产生血的地方，结果脾脏受到伤害，病人面目身黄，病人在气血两虚的时候，因为造血功能失调了，津液也不够，这时候病人身上的黄，是透过皮肤看过去血的颜色，病人身体很虚弱的时候，看到皮肤上的黄，实际上是血的颜色，如果是胆有问题的黄，是阳黄，发起来是光鲜的黄，流出来的汗都是黄的；病人小便难者，这时候脾就不能运化了，水从大便被攻掉了，如果在这种状况下，再开柴胡汤给病人，结果柴胡汤吃下去后，造成下重，因为病人身上已经寒凉了，小柴胡汤里面有黄芩，黄芩是去热寒凉的药，还有半夏去水，病人已经没津液了，下重就是脱肛的现象，大完便后，肛门收不起来了，下重不渴而饮水呕者，不是不渴，病人会渴，喝了水又吐出来，因为胃的火已经没有了，胃已经寒凉了，喝了水，根本不能化为气进入肺滋润到四肢，所以饮水会吐出来，柴胡汤不中与也，食谷者哕，柴胡汤没用了，哕就是打嗝，有哕证的时候，就代表胃气已绝，遇到这种情形的时候用茯苓四逆汤。  ', NULL, NULL, NULL, NULL, NULL, '108-109、得病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，而胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤后必下重不渴而饮水 呕者，柴胡汤不中与也，食谷者哕。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384199, '69792F6577CD9D054F03EF8FF81959E8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5308, 318, 904000558, '      一看病人是少阳证，药熬出来的时候，病人已经进入阳明证了，喝了药汤后，少阳证好了，阳明证出来了，这是好现象，因为阳明无死证，就是吃完小柴胡汤后，病人有口渴现象；照理说，小柴胡汤里面有生津的大枣、人参、甘草，病人应该不会口渴的，所以渴就是进入阳明了，阳明的主证就是渴，大承气汤也会有渴证，白虎汤也会有渴证，如为渴而小便不利者，则以五苓散主之；如为渴而烦热者，白虎汤主之，这个烦热是壮热，高烧到三九、四十度，平常的麻黄汤证、桂枝汤证、葛根汤证不会壮热四十度，这么高温都是白虎汤证了；如 烦渴而胃阴虚者，人参白虎汤主之，胃阴虚就是胃的津液不够了，所以会用到人参，本身是 白虎汤证，再加上心下痞，胃里面很难过，闷闷的不好消化，才会加人参下去；如渴而腹满者，调胃承气汤主之；如渴而谵语大便闭结者，大小承气汤主之；烦渴而少阳证仍旧者，则 柴胡白虎汤主之，就是小柴胡汤和白虎汤的加减；渴而少阳证仍在，大便实者，大柴胡汤主之。  ', NULL, NULL, NULL, NULL, NULL, '107、服柴胡汤已，渴者，属阳明也，以法治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384200, '6D66293C21DE366506318A2A1F92FA45', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5309, 318, 904000557, '       血弱气虚，表示这人本来身体就此较虚弱，血不够，气也不够，腠理开，邪气因入，与正气相搏，结于胸下；平常身体好的，一定停在表上，也就是停在太阳证上，就是桂枝汤证或麻黄汤证或葛根汤证，如果这人身体比较虚，或是女性遇到经期来，病毒一进来就结在胸胁的下方淋巴结的地方，正邪分争，往来寒热，休作有时，默默不进食，就是不想吃东西了，胸胁相连，其痛必下，邪高痛下，故使呕也，痛在中焦，造成呕，邪在上焦淋巴系统里面，故名邪高，小柴胡汤主之。我们用小柴胡汤来增强人体的免疫力，然后把病毒排除，中医不去管哪一种病毒，用邪字来代表是最好的。  ', NULL, '小柴胡汤', NULL, NULL, NULL, '106、血弱气虚，腠理开，邪气因入，与正气相搏，结于胸下；正邪分争， 往来寒热，休作有时，默默不欲饮食；胸胁相连，其痛必下，邪高痛下，故使呕也，$f{小柴胡汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384201, '145D9B95FDD65E2FCBC100B88C09ECC0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5310, 318, 904000556, '  这条辨，太阳证也有，少阳证也有，起因是表证没有好。105条简单的讲了一下少阳证，伤寒五六日，如果得到感冒一段时间后，或是副证，参考就可以了，\n主证有四个：  \n   一、往来寒热，  \n   二、胸胁苦满，  \n   三、默默不欲食，  \n   四、心烦喜呕。  \n\n    病在表有太阳、少阳、阳明，如果是病在太阳和少阳中间的时候，就是小柴胡汤；如果太阳进入阳明，比较偏重阳明的时候，就是承气汤，如果是在少阳和阳明中间，就是大柴胡汤。  \n\n    例：小孩感冒发烧，西医开退烧药，又开很强的镇静剂给小孩睡觉，一个星期后，这小孩的淋巴结整个肿起来，又感觉往来寒热，就是一天来好几次的忽冷忽热，跟疟不一样，疟有隔日疟，或间日疟，有时间性的，中医的少阳就是淋巴系统，太阳表证在人的皮肤表面，进入皮表的时候，就是桂枝汤证，没有治疗好，就进入半表半里，就是淋巴系统上，淋巴系统也是人的防卫系统，怎么知道进入淋巴系统了？\n       中医讲的辨症论治，第一往来寒热，第二胸胁苦满，为什么？胸胁的地方，纵膈膜、横膈膜、胸腔里面都是淋巴系统，严重的还有水声，很胀满，肋骨会痛；第三默默不欲食，人的五脏六腑外面都有淋巴和神经，自然肠胃的蠕动会受到影响；第四心烦喜呕，为什么喜呕？第一食物没有完全消化掉，第二淋巴系统里面有很多水分，淋巴系统里面的水和血常常在互换，就是内分泌系统，病邪进入的时候，水隔在中间，胸胁苦满，纵膈膜、横膈膜、胸腔里面都是淋巴系统包到，水太重的时候，通通梗在这，这水又不在胃里面，而在淋巴系统里面，所以中医讲半表半里，没有进入内脏，就是少阳，全部进到里面就是阳明。  \n\n       柴胡，长在地上的时候，一半在上面，一半在下面，柴胡拉起来，根和身体是一样高，所以一半在表，一半在里，所以甲状腺亢进，内分泌系统的问题，都用柴胡，内分泌全部包括在少阳里面，只要不入脏的，脑部、淋巴结、大脖子都算在内，柴胡是主要的药，所以叫柴胡汤。大柴胡汤就是病邪进入少阳和阳明之间用的，太阳证刚刚好进入少阳就是小柴胡汤证，开柴胡汤的时候，因为胸胁苦满，所以一定开半夏，本身呕，就一定是柴胡证。如果是呕，就代表少阳证，少阳证的主证是呕，如果是渴就是阳明证，为什么往来寒热？因为进入淋巴系统的时候已经不在表了，这时候人的免疫系统出来抗，打赢的时候就是热，打输的时候就是冷，所以一来一往，因为近距离交战，这样一天好几次，没有限定时间的即是柴胡证，所以有热的现象就加了黄芩在里面，因为黄芩能够去热，因为默默不欲食，就加人参、甘草、大枣，这七味药就是小柴胡汤。北派用人参的时候，专门治心下满，就是胃不好的时候吃人参，所以泻心汤中有人参就是专治肠胃的，柴胡把黄芩带到半表半里，就是淋巴系统里面，人参、生姜、甘草、大枣，进入体内以后肠胃一吸收，免疫系统增强，所以小柴胡汤也会有流汗的现象，汗一出来也解掉了。  \n\n       但是如果小柴胡汤证，开的是表药桂枝汤、麻黄汤、葛根汤，就是开成太阳证的药，就进入纯少阳了，把阳发掉后，少阳马上转阳明，因为一发表的时候，津液会伤得更多，津液伤了却没有把病毒清掉，反而把正常的体液丧失掉了，结果转移到体内，就会有肠胃发炎下利的现象。  \n\n   如果三阳并病，项强、头痛、中风、太阳证，还有恶心、胃口不开、口渴，三阳并病的时候，合解少阳，中医叫担法，不要柴胡桂枝开在一起。  \n\n    小柴胡汤有人参、甘草、大枣在里面，不欲食症状马上去掉；心烦喜呕，半夏能够止呕，黄芩能去热，胸胁苦满的现象，靠柴胡把黄芩带进去，如果烦而不呕，就不用半夏了，张仲景用半夏的时候，单单是为了止呕，如果病人口渴的，半夏就拿掉，因为半夏是利水的，吃半夏会越吃越渴，例如怀孕害喜，恶心想吐，就一定会用到半夏，为什么有人会害喜有的人不会？害喜的人平常胃中水饮比较多。  \n\n      柴胡苦辛，专疏泄淋巴管，解三焦之郁，开胸膈之塞，退寒热。解烦渴，小柴胡汤以之为君，黄芩苦寒，清火郁，姜、夏辛温，降水逆， 参、草、枣则为补助津液，以为佐耳。 \n ', NULL, '小柴胡汤', NULL, NULL, NULL, '105、伤寒五六日，中风，往来寒热，胸胁苦满，默默不欲食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞鞕，或心下悸，小便不利，或不渴，身存微热，或咳者，$f{小柴胡汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384202, 'BE8077F505B5971503F5BA8BDBC1DD65', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5311, 318, 904000555, '       营就是讲血，如果一个人的血很弱的时候，汗就流不出来的，因为血不够了，汗的来源就是血，血是从肠胃吸收的能量来的；卫就是气，如果卫比较弱的时候，表汗就是皮肤上表面的汗会洞泄，看到一个人汗一直流不停，就是气不足了，卫气就是人的免疫系统，就是中医的固表力，气不足的时候，固表力就会比较差，一差的时候毛孔就会开，气就一直往外跑， 这就是气弱，要固起来用炮附子，一下去就把表固起来了。营弱卫强，血比较弱，气比较强，欲救邪风者，宜桂枝汤，桂枝汤可以调和营卫。  ', NULL, '桂枝汤', NULL, NULL, NULL, '104、太阳病，发热汗出者，此为营弱卫强，故使汗出，欲救邪风者，宜$f{桂枝汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384203, '066507E97ACC33F4C8037A789AFE66FB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5312, 318, 904000554, '       太阳病未解，就是表证还有，摸病人的脉，脉阴阳俱微，这阴阳脉应该指的是寸尺脉，如果这病人是太阳证，为什么未解，一定是开了发表药给病人，病人吃完了药，结果病没有好，这时候摸病人的脉，他的表脉已经没有了，结果阴阳脉俱微；原来的太阳证脉都是比较浮数，阴阳脉俱微，就是寸尺脉都缓下来了，摸脉的时候，如果一息四至，代表他胃气正常，这种就不要管他，稍微等一下，慢慢恢复就好了。我们讲阳脉就是寸脉，一般人讲的是尺脉，寸指胸阳，如果是阳脉微者，先汗出而解，胸阳比较热，要等他，病人会流汗出来，如果阴脉微者，就是肚子堵到东西，没有办法消化掉，并不是真正的很虚，若气血不足，下之而解，若欲下之，宜调胃承气汤。\n      调胃承气汤是攻下的药中最初浅的方子；大黄酒洗之后，药性比较缓，而且有升提作用，刚好可以清十二指肠的积滞，这种大多发表药下去后，没有完全好，过一阵子慢慢好起来，看到心情不够开心的人、郁闷的人，都会有这种情形，情绪的关系，这不是很严重。  ', NULL, '调胃承气汤', NULL, NULL, NULL, '103、太阳病未解，脉阴阳俱微，必先振栗汗出而解。但阳脉微者，先汗出而解；但阴脉微者，下之而解；若欲下之，宜$f{调胃承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384204, '2DA01A6A9467BE66B9321FC4AB934DE1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5313, 318, 904000553, '       冒，就是头昏眩或者是头上冒汗;如果病人发汗和攻下，程序弄错了，应该先发汗的时候结果开成攻下，攻下后马上再发汗，次序弄反了，结果病人头昏还有点流汗就是胃的津液 回来了，人头上流的汗就是胃肠的津液而来，这是阳明经的热证，所以汗出表和故也，如果里面还有，再去攻下，所以得里未和，然后复下之，这是说方子开错的时候，如果病人有这种现象，就不用再去开方，让他自愈', NULL, NULL, NULL, NULL, NULL, '102、太阳病，其人冒，先下之而不愈，因复发汗，以此表里俱虚，因冒症汗出自愈，所以然者，汗出表和故也，得里未和，然后复下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384205, 'E31DA18D22B8EE2480A40B5AC4DFC5E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5314, 318, 904000552, '      这条就是看到病人有表证的时候，病发热头痛，身体疼痛，这看起来病人有表证，处方开错了或误用了，或是剂量开太重，结果解表以后，病人没有好，病人脉反沉，就表示表证没有了，身体里面虚掉了，即免疫系统不行了，发表了以后，肠胃功能马上虚弱下来，脉摸到越细越沉，就代表身体越虚弱，虚弱就是免疫系统太差了，救里的时用四逆汤，四逆汤最主要的症状就是手脚冰冷，有时里面寒到吐出来的气都是冷的。', NULL, '四逆汤', NULL, NULL, NULL, '101、病发热，头痛，身体疼痛，若汗之不差，而脉反沉，当救其里，宜$f{四逆汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615155294384206, '4424CCE2E0AE3000C81BBF6E7EF86854', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:13:20', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5315, 318, 904000564, '       如果是柴胡证，而误下了，或刚好吃坏肚子，攻下了以后，柴胡汤证还在，照样给柴胡汤就可以了。凡属三阳之证，其里气未虚，则抗拒外邪之力量仍有。柴胡汤为施转少阳之枢，使淋巴水道油膜等通畅，内外之交通无梗，本身之抗拒力量即可发展，故本方之运用甚广，功效亦倍于它方。观仲师于本方下立出加减一法，统治一切外感证，于上条再叮咛只其一证 即可用之，其重视本方也，可以见矣。 ', NULL, NULL, NULL, NULL, NULL, '114、凡柴胡汤病证而下之，若柴胡汤不罢者，复与柴胡汤，必蒸蒸而振，却发热，汗出而解。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615163419631686, '60085097C62D7974D4E71A53B61D5AB3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:46:24', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5316, 318, 904000563, '      小柴胡汤证，只看到有一个症状就可以开处方了，就代表病邪在淋巴系统里了，如果有恶心就可以用小柴胡汤了，如果不喜欢吃甜的，就把小柴胡汤里面的红枣拿出来，如果这人已经很胖了，就把人参、红枣这些健胃整脾的药去掉。  ', NULL, NULL, NULL, NULL, NULL, '113、伤寒中风，有柴胡证，但见一证便是，不必悉具。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615163419631687, 'CD1F0A4E817FF45E5F88A38C3B70D1F6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:46:24', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5317, 318, 904000562, NULL, NULL, NULL, NULL, NULL, NULL, '112、呕家不可用「建中汤」,以甘故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615163419631688, '9D8C7581A9E72D0B2405E56A42C3A0AB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:46:24', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5318, 318, 904000561, '伤寒的时候，病人的脉应该是弦紧，结果病人的脉，阳脉涩，阴脉弦，阳脉是寸口的脉讲的是表，涩代表虚，所以表是虚的，寸、关、尺又叫做上焦、中焦、下焦，寸又可以叫做  \n表，尺又可以叫做里，阳脉寸脉比较浮的时候，就知道病在表，寸脉比较沉下去的时候，就知道表虚掉了，阴脉是指尺的脉讲的是里，阴脉比较弦的时候，第一表示里有水，第二表示病人有痛的感觉，这痛一定是水，最主要是寒，弦的脉摸的时候感觉很细像吉他弦，按下去的时候跳的很强，代表里寒了，里寒代表腹部寒痛，法当腹中急痛，应该是腹中急痛，绷得很紧，抽筋那样，先与小建中汤。  \n\n       如果不摸脉，如何知道里寒?像小孩鼻子的山根，就是鼻子的尾巴，山根如果是青色的，代表里寒，里不但寒而且痛，十个小孩九个山根青的，小孩体格很差的话，蚊虫咬到皮肤就肿一块，没病的小孩，还不喜欢吃东西的话，根据经方，桂枝汤是桂枝、白芍、生姜、甘草、大枣，桂枝用三钱的话，白芍用六钱，白芍是桂枝的两倍，因为会腹痛，所以小建中汤和桂枝汤不一样的地方，就是小建中汤重用白芍，这人本来脾脏的功能就比较差，桂枝汤本来就是健脾阳，张仲景加饴糖在里面，饴糖就是麦芽糖，加饴糖在里面小孩就会喜欢吃，脾脏本来就主湿主热，饴糖很黏稠，药一下去。脾阳马上就壮起来，就是靠桂枝汤，饴糖的功能一是甜，让小孩爱吃外，一是脾的津液不足的时候靠饴糖在里面；小建中汤一下去的时候，胃口大开，肚子痛就没了，小孩就开始肯吃东西，开始喜欢吃谷类的食物，所以常常小孩不喜欢吃东西的时候，就给他小建中汤。  \n\n       这个条辨，换个角度讲，当看到病人有伤寒中风的表证的时候，可是这人里虚掉了，最轻剂，刚开始用的就小建中汤；吃了小建中汤好了变成纯表证的时候，再去看证，开桂枝汤或葛根汤或……，这一本经方里面，只有两个专门治疗里虚的方；人如果得到感冒表证的时候，要里实才能发表，如果发现病人是里虚，第一个就是小建中汤，第二就是炙甘草汤；一般的人小建中汤就好了，炙甘草汤是注重在脉结代的病人，吃完小建中汤再看病人有没有表证，如果没有就算了，有的话再对证开药，所以先与小建中汤，先把里虚补足，再给他小柴胡汤，如果小柴胡汤吃完，肚子还痛，这就不是里虚，是小肠下方静脉血流不顺畅，就把小柴胡汤里面的黄芩拿掉，改成白芍。  ', NULL, '小建中汤,小柴胡汤', NULL, NULL, NULL, '111、伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与$f{小建中汤}。不差者，与$f{小柴胡汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615163419631689, 'EBF5C31E80C3A07E1044EE528D740E66', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:46:24', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5319, 318, 904000567, '       胸胁满而呕，就知道病情已有少阳证了，日晡所发潮热，黄昏的时候发潮热，阳明证上有一个很特殊的现象，就是到了下午三点到五点开始发热，潮热是一阵一阵热上来，按照气血流注的时间，申时开膀胱，实际上堵在大肠里面，大肠会移热到膀胱，一移热就从背后到脑里去了，所以是大肠移热，到下午的时候就会发热；胸满而呕是少阳证，到日晡发潮热，就是阳明证，所以是柴胡证。本不得利，今反利者，柴胡汤本来是没有下利的，现在在下利，可能是前面医生攻的，前面医生用丸药下的，丸药下的时候利水利得很快，水跑掉了，大便还在里面，所以用汤剂，汤剂下的时候，整个打下来了，所以攻下的药大部分都是用汤剂在攻的，潮热者，实也，先宜小柴胡汤以解外，后以柴胡加芒硝主之。原来是大柴胡汤证，因为已经被攻下了，所以变成小柴胡汤证，被攻下了阳明证就没了，变成少阳证，所以是小柴胡汤证治疗，117条就是说少阳证被误下了以后的辨证，小柴胡解外后，就是柴胡加芒硝，有燥屎的时候这种燥屎常年累积在里面没有出来，这时候只能用芒硝攻下来，打出来是黑的。怎知有燥屎呢？黄昏的时候会发热就是了，用小柴胡汤加芒硝治疗，不用再加枳实、大黄，因为前面的医生已经攻下，所以小柴胡汤加芒硝就可以了，就是小柴胡汤加减。  \n\n       东洞翁曰：本方为小柴胡汤证而苦满难解者，又曰小柴胡汤证而有坚块者。柴胡加芒硝就是本身是小柴胡汤证兼有坚块，中医是辨证论治，这硬块可能是大肠癌的出血硬块，不管是什么，芒硝可以散掉，\n\n   《本草》里面没有提芒硝可以把燥屎打散，芒硝是攻坚的峻药，坚就代表肠里面的硬块。  ', NULL, '小柴胡汤,柴胡加芒硝汤', NULL, NULL, NULL, '117、伤寒十三日不解，胸胁满而呕，已而微下利，日晡所发潮热，此柴胡证，本不得利，今反利者，知医以药丸下之，非其治也。潮热者，实也，先宜$f{小柴胡汤}以解外，后以$f{柴胡加芒硝汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615170891579462, '8764D7966C725CDE3448863D79C3BE62', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 17:16:48', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5320, 318, 904000566, '       过经十余日，就是拖了十几天了，照理已经进入别的经了，结果表证还在的时候，医生没有开给病人表药，却攻下，攻下了以后，原本太阳证应该解表，让病从外表发，结果太阳病跑到里面去了，如果再过四五天以后，柴胡证仍在的时候，先给小柴胡汤，小柴胡汤下去以后，病人如果还是呕不止，心下急，郁郁微烦者，胃里面胀满难过为未解也，与大柴胡汤下之则愈。  \n\n       大柴胡汤本身是介于少阳和阳明之间，兼有少阳、阳明才会用大柴胡汤，呕不止，心下急，郁郁微烦者，就是肠胃里面被大便堵到了，有宿食堵在里面，所以大柴胡汤证最主要的症状有腹满，肚子胀满而呕，呕属少阳，腹满是阳明，腹满、恶心是大柴胡汤的主证，现代人的气满是厚朴生姜半夏甘草汤证；实满是承气汤证；腹满又恶心就是大柴胡汤证；如果没有腹满光呕就是小柴胡汤证，为什么?因为被攻下了，下利的药太快了，病人水分都出来了，大便出来的都是水，结果大便没有排出来，于是便堵在里面。临床上看到大肠癌的病人，一开始有些是承气汤证，有些是大柴胡汤证，不是在阳明就是介于少阳与阳明之间，阳明无死证，这种情况是不危险的。结果西医治疗过的病人，开刀以后，移转肝癌或肺癌，症状不是少阴证就是厥阴证，所以我们当然反对西医开刀。如果是大肠癌的病人，还没有给西医开过刀，如果是在大肠的末端，也就是直肠附近堵到，我们要加芒硝来攻坚。我们遇到实证的便秘，病人有拒按，不会放屁，就考虑要用到芒硝了。', NULL, '小柴胡汤，大柴胡汤', NULL, NULL, NULL, '116、太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与$f{小柴胡汤}。呕不止，心下急，郁郁微烦者，为未解也，与$f{大柴胡汤}下之则愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615170891579463, '46BABE48EEEAA1116F6E8A97E5625DF9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 17:16:48', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5321, 318, 904000565, '        如果是心中悸，虚烦不得卧，茯苓甘草汤可以把它治好去掉，如果是心中悸而烦者，这是里虚，里面虚燥，也是小建中汤，所以小建中汤是阴虚的时候用的。这条辨专门讲的是中风素虚，这人得到感冒，本来正常是桂枝汤，除了有汗、恶风、发热、头痛，再加上心中悸而烦，就知道里虚了，还是小建中汤，所以应该伤寒二三日，表证仍在，心中悸而烦者，小建中汤主之。这样比较完整。  \n\n      阴虚者，稍有劳倦身热，即心烦不安，纵有表邪，不可发汗，以小建中汤重用芍药引血内行，以治其烦。所以阴虚的人，要等到里虚恢复了，有表证再开发表的药，所以遇到里虚的人，在发表之前，一定要先治里虚。  ', NULL, '小建中汤', NULL, NULL, NULL, '115、伤寒二三日，心中悸而烦者，$f{小建中汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615170891579464, '89187CADB0DFE379A6412239919FD9DE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 17:16:48', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5322, 318, 904000569, '       太阳病不解就是还有太阳病的表证，还有表热没好，桂枝汤、葛根汤、麻黄汤发表的时候没有发出去，这病毒直接从经进入腑，从皮肤表面直接进入膀胱，腹部的前面是膀胱，中间是精宫，后面是大肠，正常小便出来的水是气化出来的，气化的时候，一部分的水再跑到胆里面，水生木，变成胆汁，气化本来就很热了，当热进入膀胱里面，移热到膀胱，足太阳膀胱经，经络络到膀胱里面，热再进来，太热了血管会破裂，小便就会带血出来，这是一种外证没有好的时候传到里面的现象，还有一种是打架被踢或运动伤害伤到小便的地方，结果小便堵到了小不出来，里面瘀血，也是一种外伤，用桃核承气汤；热结膀胱就是小便太热了，小便带血，桃核承气汤是治疗血症的第一个方子，很浅的方子，其人如狂，并不是发狂，只是情绪烦躁不安，如已发狂的话，桃核承气汤就来不及了，所以是近狂还没到发狂的状态；血自下，下者愈，如果这个时候小便自己带血下来，就没有关系了，这血通了，其外不解者，尚未可攻，当先解其外，解外的时候，用小柴胡汤，因为碰到腑上的时候，一定经过中间的三焦，外解已，但少腹急结者，少腹就是在中极关元一带绷得很紧，病人感觉很痛，很难过，小便小不出来，看皮肤上也是绷得很紧，整个抽筋起来，由这些症状，可以确定血堵在膀胱里面，血下不来。瘀血者，血液已越出血管之外，失其血液之性能而成为死血，在医学名词上为瘀血；死血在生理上不但已失作用，且能遗害于全身，一但化成毒质，刺激脑神经使其发生错乱，或使血液不清洁，发生种种病变，如皮肤病、疡疮、潮热，以及攻冲性、游走性之疼痛诸疾病；凡属一切急慢性病证与奇病怪疾，临床上久看不好的病，一定是有瘀血在里面，吾人有很多方法，教导如何去辨别$g{判断瘀血}，如何知道里面血瘀到了，桃核承气汤、下瘀血汤、抵当丸汤、桂枝茯苓丸、大黄蟅虫丸等，皆为治瘀血之良剂。桂枝茯苓丸专门用作妇人子宫肌瘤、卵巢瘤的时候用，大黄蟅虫丸腹腔里面有瘀血的时候用，下瘀血汤胸腔里面有瘀血内伤的时候用。  \n\n        临床上遇到少腹痛的时候，记得先问小便是否正常；举例来说，如果有妇女在月经期间腹痛来找你治疗，你忘了问小便，结果以为是月经引起的腹痛，其实可能是刚好这几天她的膀胱结石引起腹痛，如此处方用药就不正确了。  ', NULL, '桃核承气汤', NULL, NULL, NULL, '119、太阳病不解，热结膀胱，其人如狂，血自下，下者愈；其外不解者，尚未可攻，当先解其外，外解已，但少腹急结者，仍可攻之，宜$f{桃核承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615768543371334, '9B847BF33B3BB787D2D0B0910507FBF0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 09:48:39', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5323, 318, 904000568, '       伤寒，两个星期，太阳证应该过去了，结果过了太阳证的时候，病已经进入阳明了，病没有解掉，病人就谵语，谵语就是胡言乱语，谵语怎么来的？大便堵在肠里面，进入阳明以后，变成纯热证，燥屎就像放在太阳底下晒，大便的燥气就往头上冲，脑部受到大便浊气的影响，讲话就胡言乱语。以有热也，当以汤下之，肠胃里面有热，要用汤剂来攻；若小便利者，肠壁变得很小，大便出来便细细长长的，有一种，大便堵在小肠转角的地方，大便就像羊大便，出来像六味地黄丸；照理说小便利者，大便当鞕，而反下利，脉调和者，照理说应该没有大便，结果反而下利，就知道是前医之过。若自下利者，脉微当厥，若平常虚利，下利清谷，病人有点昏迷的现象，脉都很虚弱，手脚都冰冷掉了，这是虚寒，开承气汤，病人会死掉，应该是四逆汤。应该是很虚弱的，病人下利，结果精神很好，从这知道里面有东西堵到，今反和者，知为内实也，调胃承气汤主之，开轻剂，用调胃承气汤。如果看到病人发烧发热，病人的脉是虚弱的，知道里面寒凉掉了，用四逆汤把他救回来；如果是实热，病人也会下利，下利拉出来是水，实际上大便堵在里面，如果不仔细会以为是下利，这时候攻它，清出来后，津液自然会回来，张仲景说喝承气汤后，病人会口渴，喝点水就好了；这条辨是说：明明看到病人是下利，以为里面没有堵到，结果病人是因为里面堵到而下利，因为堵的太实了。  \n\n       热病，肠中干燥而大便不行，常以汤剂解之；以药物之刺激与推动，固可通便，而水液亦为推荡之一助，如多饮开水，其便亦通。若用丸剂，每多辛热之品所成，只有刺激肠蠕动之力，无清润肠壁之力，故所下者，多剩余之水分。所以西药或甘油锭没有办法让肠胃产生津液。  ', NULL, '调胃承气汤', NULL, NULL, NULL, '118、伤寒，十三日不解，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，脉调和者，知医以丸药下之，非其治也。若自下利者，脉微当厥，今反和者知为内实也，$f{调胃承气汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615768543371335, '09F639974E9B60A1B9C5A8AD3212545B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 09:48:39', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5324, 318, 904000570, '        伤寒八九日，在医生的眼里，病已经六七天，可能已经传里了，不是传阳明就是传少阳，所以医生才会下之，一攻下以后，病人胸满，惊烦，小便不利，谵语，一身尽重，不可转侧，为什么？因为要传不传，并没有进入少阳，被攻下得太早了，表邪陷下去，陷在半表半里中间，因为被攻下，而跑到三焦淋巴系统里面去，因为在半表半里中间，三焦跟心包是表里，所以病人会胸满，惊烦，因为胸口这里淋巴系统整个都会在这里，小便不利，因为三焦是水道出焉，三焦管水道，由油网来排，因为滤过性病毒是由攻下进来的，所以堵在三焦，水道就不能通行了。有谵语就代表说胃里面还有余热，胃里面还有干的大便，没有完全排掉，一身尽重，不可转侧者，攻下的时候，身体的气血往下走，一攻下病人的身体虚掉了，其实本来身体很好，把病毒顶在外面的，表面的症状慢慢没了，结果被庸医攻下，免疫系统被攻下，就往下走，因为体能很好，进来的时候就停在少阳，这进来不是病人不行，而是被医生误下的，所以柴胡加龙骨牡蛎汤主之；因为在半表半里之间，有胸满，靠柴胡加桂枝来解表，柴胡本身和解，桂枝走肌肉皮肤表面去表，已经在三焦里面的东西，把它清利出来，这汤方加龙骨牡蛎，还有铅丹，铅丹现在很少用，龙骨牡蛎和铅丹是治疗惊烦，受到惊吓的时候用，因为三焦和心包是表里的，所以这三味药是用来镇惊止烦的；又因为有谵语，因为人虚了，大肠的浊气就往上跑就发生谵语，所以加了大黄，大黄来攻下，用大黄把堆积在胃的大便排 出来；这时候又加半夏，因为这人素体比较壮的，平常比较壮的人，胸腔比较湿热一点，能湿热才能够胖；这时候再加生姜、人参、大枣，来把里虚补足；此方表证里证一剂来清，同时攻下，同时解表，同时把前医造成的下攻中气不足，把它补足，中气就靠人参、生姜、红枣补足，解表靠柴胡、桂枝。这个药方常用在体质素虚之人，误下之后，阴虚而津液不能自回；如果是体质强壮的人，误下之后津液回自回，就不会用到这个药方。  ', NULL, '柴胡加龙骨牡蛎汤', NULL, NULL, NULL, '120、伤寒八九日，下之，胸满，惊烦，小便不利，谵语，一身尽重，不可转侧者，$f{柴胡加龙骨牡蛎汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615780080267334, '478666116C15F95161D13321520E223F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 10:35:36', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5325, 318, 904000575, '       中药对烫伤内服的第一方就是桂枝去芍药加蜀漆龙骨牡蛎救逆汤，我们可以在火灾的现场煮这个汤来救人，烧伤的时候，皮肤一块一块的，有时候还会翻裂起来，很大的水泡很痛，病人会惊狂，因为被火吓了，水都跑到皮肤表面上去了，痛又没办法睡，会惊扰烦躁。张仲景写救逆，就是急救的时候用的；因为脉浮，知道病在表，火一烧起来，水都往皮肤表面上跑，水并没有变成汗，造成很大量的水在皮肤表面上，桂枝去芍药加蜀漆龙骨牡蛎救逆  \n汤一剂喝下去的时候，大约一个小时，药发散到皮肤表面的时候，痛会大减，因为是救逆，要很迅速的把药发到皮肤表面上去，所以桂枝汤去芍药，芍药本身性是酸收的。比较能收敛，如果桂枝里面加了芍药的话，药力就没有办法很迅速的达到皮肤表面上去，所以把芍药拿掉；药到了皮肤表面后加蜀漆，蜀漆又叫常山苗，蜀漆去痰，人的津液正常在肠胃里面，遇到大火，一部分津液跑到皮肤表面，马上起水泡的时候，因为速度太快太热了，一部分津液就堵在中焦，津液离开正常管道，堵在横膈膜的下方以后，马上就化生成痰，所以看到烫伤的病人，常常痰都很多；龙骨牡蛎，这两味药本来就是收敛的药，同时它能利水壮肾阳，牡蛎能收浮阳，因为病人惊狂，起卧不安者，就是阳浮在头上面，阳气往上冲，牡蛎下去能把阳往下降，龙骨牡蛎在收皮肤水泡的时候，是从内来收，桂枝汤能健脾阳，让脾正常运转，因为龙骨牡蛎已经在收敛了，所以不需要芍药来收敛、芍药会让桂枝变慢，所以不用芍药了。  \n\n        现在吃安眠药的副作用，也会引起焦虑、失眠，也可能用到这个方，只要有惊狂、起卧不安，严重焦虑就想到此方。这种安眠药的副作用，如果给西医开抗忧郁的药，结果就是很开心的去自杀。  \n\n        外敷：过去用牡蛎打粉，磨得很细，加麻油，更好的用硫磺、大黄，硫磺就是在火山口的东西，硫磺本身外用时非常的寒凉，西医就把硫磺跟膏药一起用，变成硫磺膏、中医把硫磺、大黄、麻油配在一起用，如果是皮肤红肿这药就可以了，起水泡的时候要加菖蒲在里面，菖蒲是皮肤表面利水的大剂，菖蒲就是灌木类的水草，把这草晒干烧成灰，这灰敷在皮肤表面上，一敷上去，就开始去水，病人会小便，如果化脓了，就是变成湿了，就要加白朮；如果已经发炎了，就加黄芩，这就是加减；西医的硫磺膏只能去热，不能去水去湿。为什么要赶快去水?因为水绷久了，皮肤就会皱掉，会有疤难看。  \n', NULL, '桂枝去芍药加蜀漆龙骨牡蛎救逆汤', NULL, NULL, NULL, '125、伤寒，脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安者，$f{桂枝去芍药加蜀漆龙骨牡蛎救逆汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615788315168838, '03C0455E637D9EE9D4D72FA55EF9D7E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:09:06', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5326, 318, 904000574, '       已经有感冒的热在身体里面，然后又有火气进来了，用火熏他，这是两个阳热在互相熏灼，结果造成病人津液丧失过多，其身发黄，血里面百分之六十的水，水分丧失很多的时候，从皮肤上看到血的颜色是黄色的，实在这是血的原色，其实是液不足了，这时候吃水梨最好；阳盛则欲衄，阳气是往上走的，如果病人会流鼻血，血里面的热就会散出来，就会好；如果病人阴虚小便难，因为津液不够了，阴阳俱虚竭，身体则枯燥，如果病人阴阳两虚，身体就枯燥了，瘦干干的，但头汗出，为什么有这现象?身上一点汗都没有，但是满头大汗，就是头流汗，中医叫作浮阳，浮阳就是免疫系统，就是肠胃的功能，就是肠胃的热气，正常时阴阳是相交的，为什么阳热能停在中焦不会散出去？因为人有阴阳，有津液，按一定比率存在，所以可以停在中焦。有一天如果津液少了，津液少的原因，可能被攻下，可能被火烤，津液一少，胃里面的阳热就冲到头上去了，头就在流汗，中药里面能把浮阳降下来，最好的就是牡蛎的壳，牡蛎会收浮阳，相书上蒸笼头这种人只能干校官干不了将官，因这人太急躁了。另外一种情形，阳明热也会容易头汗出，与这里的但头汗出不同，这里是阴阳都虚掉才会但头汗出。腹满，里面的大便都干掉了，微喘，口干、咽烂，喉咙都烂掉了，或不大便，久则谵语，甚者至哕，严重到打嗝的时候更虚，有打嗝现象的时候，就是胃气绝了，很危险了，如果再进去手足躁扰，捻衣摸床；小便利者，其人可治。捻衣摸床就是沿着床边摸过去，这时候大便整个干在肠子里面了；如果小便还通利，代表他元阳还有，因为小便是气化出来的，代表津液还有，如果小便都没有了，就真的很危险了。  \n\n       例：小孩感冒，麻黄汤证，一剂下去小孩发汗太过，烧退了就转白虎汤证了，结果误诊，看他还发烧给大青龙汤，小孩一直在发汗，原来是太阳表证，立刻转成阳明燥证，就捻衣摸床，这代表津竭了，而阳明燥热证，对小孩摸脉不准，因为小孩的脉，正常时都跳得很快，摸肚子拒按，表示大便堵在里面，阳明证应该考虑大承气汤或白虎汤?结果因拒按而用大承气汤，大承气汤一下去，烧就退了，还有，这小孩从小就黄疸，大便不好，常常阳明燥热，常常口渴，常常便秘，脑子反应慢，大承气汤一攻都好了。  \n\n       孙斋氏曰：本条宜对证用药：黄疸病用茵陈蒿汤；腹满而喘、谵语、下大便用承气汤。独躁扰循摸一症为神经濒绝之现象，法在不治。这现象用大承气汤，如果白虎汤证造成的壮热，用犀角地黄汤可能会好，大便不通的，就不会好。', NULL, NULL, NULL, NULL, NULL, '124、太阳病，中风，以火劫发汗，邪风被火热，血气流溢，失其常度，两阳相熏灼，其身发黄。阳盛则欲衄，阴虚小便难，阴阳俱虚竭，身体则枯燥，但头汗出，剂颈而还。腹满、微喘，口干、咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床；小便利者，其人可治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615788315168839, '82ECBEBD81D2FDA23CDE21A2C397F54C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:09:06', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5327, 318, 904000573, '       过去因为在北方，拿瓦烫协助病人发汗，用烤的方式让病人大汗出，因为不是药汗，不是免疫系统从里面推出来的汗，所以没用，因为病人的大汗出，所以病人里面的津液伤到了，刚刚烤火的热跑到肠胃里面去了，肠胃里面就相对的更干了，结果肠胃津液伤到了，大便都堵在里面，食物在里面坏掉了。十几天以后，突然感觉到发冷，自下利者，此为欲解也，照 理说谵语的时候大便没有了，结果大便来了，就是病人的津液自己调养回来了，津液返回胃里面了，自己会好。其汗从腰以下不得汗，肚脐以上有汗，肚脐以下没有汗。故欲小便不得，反呕，此段顺序有错，先把反呕拿掉，先欲失溲，就是急着想小便又小不出来。水堵在里面，足下恶风，脚下冰冷，风吹得很难过，为什么？人的手脚会有热度都是靠胃的阳气，胃气往下注，到脚指头，脚整个热起来，足下恶风代表胃气没有下注，堵到了；如果把胃的津液伤到的时候，胃里面干掉了，张仲景说先不要管它，先少少与之，慢慢让他津液回来，或先吃一点稀饭，让他自己调理回来，这样最好；在这种状况下要不要开处方？先观察病人，如果病人大便鞕，小便量应该会增加，大便鞕，小便当数，而反不数及不多，代表水还是没有回来，如果大便已，大便正常了，头卓然而痛，为什么？因为大肠和脑是连到的，大便堵在大肠里面，因为前面用瓦去烫过发汗，这大肠的津液回来的时候，阳明燥屎突然通一下，一下子浊气往上头，头会突然痛一下，痛一下就没有了，大便也出去了，因为在里面太久了，其人足心必热，谷气下流故也，脚会热起来，因为胃气往下走了，胃气往下走就是胃气能达到四肢，能布达津液了；因为病人的津液已经伤到了，这时候用承气汤去攻的话，津液会更伤，所以要在旁边看病人，看病人的大小便如何，小便没有就代表他津液没了，这时候要赶快给他一些补津液的药，小便很多就没有关系了，他自己会好；现在临床上也会看到，在火场里面逃出来的会看到。  \n\n    过去有些派系把123、124条拿掉，因为这两条上下条文比较不通。 ', NULL, NULL, NULL, NULL, NULL, '123、太阳病一日，反烧瓦熨其背，大汗出，火热入胃，胃中之水竭，躁烦，必发谵语。十余日振栗，自下利者，此为欲解也。其汗从腰以下不得汗，故欲小便不得，反呕。先欲失溲，足下恶风，大便鞕，小便当数，而反不数及不多，大便已，头卓然而痛，其人足心必热，谷气下流故也。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615788315168840, 'B33C2DAB8618A7E98DBA1C7B49218EA4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:09:06', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5328, 318, 904000572, '       这两条讲，如果伤寒没有立刻治好的时候，它传经的一种症状。啬啬恶寒就是肺虚了，皮肤怕冷就是表虚掉了，肺的功能比较差，肺是诸阳之会，皮肤毛孔的能量都是靠肺；这时候大渴欲饮水，因为肺虚掉的时候，肺不能行水了，这时候嘴巴就很燥渴，这时候就会肚子胀满，因为水不能气化，胃里面的火不够，土不能生金，水就停在中焦；自汗出，小便利，这时候如果病人自己会流汗，小便正常的话，代表脾胃的元气功能自己恢复回来，自己会好的，就不用去治疗他了;没有好的，这种症状中医称为横，刺期门。这现象一般来说，比较危险，会造成腹水，肝也是肿起来，一是影响脾胃，一是影响水的排泄系统，\n    张隐庵曰：大渴欲饮水者，肝主木火之气，肝是动病，甚则嗌干而渴也。其腹必满，这种肝癌都有的现象，口渴去喝水，喝了都不能止渴，水喝下去，只是让腹水更大，这水并没有办法气化成津液上来，就是从舌头下方冒出津液上来，所以嘴巴永远是干的，人小便出来的水是气化出来的，嘴巴里面的口水也是气化出来的，气化后的水才是能让身体受用的水。  ', NULL, NULL, NULL, NULL, NULL, '122、伤寒，发热，啬啬恶寒，大渴欲饮水，其腹必满；自汗出，小便利，其病欲解；此肝乘肺也，名曰横，刺期门。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615788315168841, 'EABF4E3C93B6EDB24040D67A59F5E00F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:09:06', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5329, 318, 904000571, '       只有阳明证才会有发谵语的，谵语代表阳明证，阳明就是胃，太阴篇第一个主证就是腹满，所以腹满代表太阴证，太阴就是脾，寸口脉就是阳脉，寸口脉浮而紧，此肝乘脾也，就是肝血太旺了，顶到胃；得到急性肝病的人，肝肿起来，胃被压迫到了，木克土，因为脾胃被肝压到了，肝里面充血充得很旺，脾胃的血就不够了，当人血不足的时候，就会比较肥大，为什么会肥大?就是要吸收更多，所以气血虚的人，舌头又肥又大，脾胃也是一样，血都跑到肝里面了，没有血能让脾脏蠕动的时候，脾脏就像死肥肉一样，堵在胃下方，就叫作纵，纵的意思就是木克土，病人就不能吃东西，要把肝血输开来才行，这时候张仲景说扎期门，实际上不能光靠期门，如果用脏会、脾募的章门穴会更好。这在针灸课中已经讲过。', NULL, NULL, NULL, NULL, NULL, '121、伤寒，腹满，谵语，寸口脉浮而紧，此肝乘脾也，名曰纵，刺期门。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615788315168842, '1DE57CCA431227271DEFCC6A314C5025', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:09:06', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5330, 318, 904000581, '      对皮肤表面上的脓头，可以用火罐拔掉，有的脓头在肌肉很深的地方，在过去的脓疡科，把针烧红了以后，刺进皮肤里面，直接刺到脓头里面，来发它的脓疡，北派的医生用白朮和附子，就是朮附汤，金匮里面还有一个阳和汤，都是能够让内部的脓疡发表发出来，不管是癌症，骨头烂掉的，都能让里面的浊物清出来，浮到皮肤表面上，应该要这样做才对。  \n\n        烧针令其汗，针处被寒，医生用烧针来烫，让病人发汗，其实病人原本有伤寒，譬如有寒证，要从里面发出来比较好，用药去攻比较好，结果医生用烧针，例如温针，艾草放在针上面烧，一烧，寒一遇到热，寒就往里面走，而不是往外走；临床上看，发奔豚的时候，都是在右边的天枢开始发，其实奔豚是大肠里面本来有燥屎，干燥的大便在里面，平常不知道，有的时候大便鞕，或大便像羊屎一样，没注意它，实际临床上，此类病人都是惊发的，病人本身很胆小一扎针的时候本来就很怕了，又担心艾草掉下来会烫到，一直在惊，实际上奔豚证就是惊发，奔豚气从腹部一直上来，像手臂一样粗，一直冲上来，看起来像心脏病，痛得受不了，但又不会死，心脏本身好好的，因为人一受惊发，肠子必会筋挛起来，大便的燥气因而跑到肠壁外面的三焦油网里面去了，进入三焦油网渗入血管里面，大便的废气如果跑到脑里面，就会捻衣摸床、谵语、发狂奔走。如果透过血管跑回肝脏，由肝脏就会影响到心脏跑到血管里面，顺沿着血脉流回心脏，流回心脏以后，就会有发奔豚的现象，因为血里面不受气，大肠的燥气流到心脏去了，就发奔豚，所以张仲景看这人原本没有便秘，肠胃功能可能比较差一点，处方开桂枝加桂汤，本身用桂枝汤和解营卫，因为是肠子的问题，肠子的浊气从静脉血管跑到心脏里面去了，桂枝加桂汤，这桂就是肉桂，平常肉桂加五分八分一点点就够了，加肉桂让心脏喷射力量很强，浊气一进到心脏以后，马上从动脉喷走，硬把浊气逼回肠子里去，然后桂枝汤去和解营卫，让肠胃蠕动很好，同时因为他还有伤寒表证；临床上，看到发奔豚的时候，知道是大肠气在发，要把肠气逼回到血管里面去，从血里面再回三焦，再回肠子里面去，就是靠心脏喷出来进入动脉血管的力量，所以是靠桂枝加桂汤。所以第一个处理奔豚的汤方就是桂枝加桂汤。另一种奔豚的症状，是本来有宿便的人，受到惊吓以后，燥屎的沼气透过肝脏与大肠的血管进入肝脏，所以肝脏送给心脏的血中就会有沼气，心脏就 想把沼气往外推，于是就动悸的很厉害，就发奔豚。  \n\n方中行曰：奔豚肾之积名也。肾从少腹上冲心，奔豚证发作之状也；盖人之素有肾积者，因针穴处寒得入之，其积遂发，则气自少腹上逆而冲心，状若惊豚突前而奔走，故曰奔豚。实际上就是大肠里面的燥屎，其浊气进入肠壁里面，进入血管冲到心脏里面，才会有这种现 象。还有一种乃针孔发生炎肿或成破伤风症也；看起来像奔豚，实际上是破伤风症，病毒侵入身体里面去了，这时候要加强心脏力量，把免疫系统带出来的时候，也是靠桂枝加桂汤，然后可以配合针灸课程中提过的灸法，用隔姜灸；临床上桂枝加桂汤，如果用桂枝，就是桂枝汤里面原本桂枝是三钱，白芍三钱，现在桂枝用六钱，这样力量不好，所以要同样用桂枝汤，桂枝白芍等量，但是加桂是加肉桂，桂枝肉桂是同样的东西，肉桂是桂树的心，桂枝是桂树的皮；肉桂很油很香很浓，肉桂喷发的力量才够，有时候重用桂枝三四剂下去，病人还是奔豚，加肉桂下去一剂就去掉了，二者差很多。  ', NULL, '桂枝加桂汤', NULL, NULL, NULL, '131、烧针令其汗，针处被寒，核起而赤者，必发奔豚，气从少腹上冲心者，灸其核上各一壮，与$f{桂枝加桂汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615798191652934, 'C8982735B0FB2E001B503603EF6015C7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:49:17', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5331, 318, 904000580, '        脉浮，病在表，要用汗解，本来是表热，靠肺的阳在攻表解表，因为火太盛，再一灸，阳就离开了，水还在下面，水还来不及气化，一灸，阳都往上走，水都停在下焦，结果腰以下重而痹，什么叫痹? 就是没有汗又干枯的状况，这就叫做火逆。如果病人体能很好，会自己好的，在好之前病人一定会先烦燥，津液再慢慢回来，自汗，就是胃的津液回来了，为什么会有汗? 就是津液已经出来了才会有汗，何以知之，因为病人脉浮起来，会流汗了，代表体能慢慢回来，水跑回到皮肤表面上去了，之前的脉浮是被误治的，因为用灸去烧他。  ', NULL, NULL, NULL, NULL, NULL, '130、脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也，欲自解者，必当先烦，乃自汗而解。何以知之? 脉浮，故知 汗出解也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615798191652935, '441B0946BE6F31C3FF5F8D2AC956CA56', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:49:17', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5332, 318, 904000579, '       微代表是虚，但跳的是数脉，数代表的是热，所以微数之脉就是病人是虚热的体质。白虎汤证是讲阳明经热，热在经脉里面。就是白虎汤；如果是阳明腑热，热在腑里面，热在大肠、小肠、膀胱，热在消化系统里面，就是承气汤证，白虎汤和承气汤都是实热的范围，脉都是很数，但是脉会洪大，不会微细。实热跟虚热不一样，实热要攻实，把去实和去热的药加在一起，就可以攻了；虚热要把去热的药加在里面，还要把补虚的药加在里面，像吃六味地黄丸，六味地黄丸没有什么补，桂附八味丸里面的肉桂和附子下去会很热，像虚热的人吃桂附八味丸，虚热会更热，会嘴巴燥裂，桂附八味丸本来是为了补虚的，所以吃桂附八味丸要加些去热的药在里面，可以加黄连、黄芩在里面;如果是热在血里面，口渴阳明热的话，就加白虎在里面。  \n\n      虚热的病人不要灸，要寒湿或纯虚的病人才灸，因为火是邪的不是正的，会造成病人虚热而生烦逆。追虚逐实，血散脉中，并不是虚热的病人灸了以后，血就离开脉了，而是血里面有热力，本来是虚热的人，血量已经不足了，肝里面很热，血的热就要往外跑，一加热的时候，血里面更热，津液更少了，这时候热已经离开血管，跑到旁边的经脉里面去，血还在血管里面，火气虽微，内攻有力，焦骨伤筋，血难复也，结果病人更虚，骨头、筋就都会变 得比较枯瘦。  ', NULL, NULL, NULL, NULL, NULL, '129、微数之脉，慎不可灸；因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615798191652936, '885EABA1EF795FC174BFCE81BF211F0D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:49:17', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5333, 318, 904000578, '       现在已经脉很浮了，热又很盛，反灸之，灸不要用在这时候，灸用在寒湿比较盛的时候，灸是治疗虚证的，病人脉浮且热，这是实，实证的病以虚治，用灸来治，结果病人因火而动，必咽燥吐血，这就是伤到阳，两阳相亢才会喉咙干燥吐血出来，所以平常给病人加灸的，一定是身体虚寒的人。从内经的理论来说，伤到阳会吐血，伤到阴会下血：这是吐血与下血有差异的地方。', NULL, NULL, NULL, NULL, NULL, '128、脉浮，热甚，反灸之，此为实。实以虚治，因火而动，必咽燥，吐血。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615798191652937, '2506EBA7FD0ACD4D328744B64640FF43', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:49:17', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5334, 318, 904000577, '      太阳病应该是汗解的，如桂枝汤、葛根汤、麻黄汤来解，过去取汗的方法很多，因为拿不到药，所以用火烤来得汗，一烤的时候，病人反没有汗了，不但没有把汗烤出来，反而令伤寒往里面走，结果滤过性病毒往里面跑，其人必躁。必躁，就是表邪进入阳明系统，也就是在肠胃里面，肠胃干掉了，到经不解，就是平常感冒应该一个星期就好了，阳病六日、阴病七日解了，结果时间到了没有解，必圊血就是大便里面带血，名为火邪，就是表热已经传到里面去了。$m{《内经》}$n{阳伤则吐血}，血如果太多，津液伤到了，血会逆经、会叛经，如果伤到阳，就是伤到胸腔、肺、胃的地方，病人会吐血，如果是阴伤，就是伤到五脏，伤到子宫、膀胱、大肠，就大便带血。  ', NULL, NULL, NULL, NULL, NULL, '127、太阳病，以火熏之，不得汗，其人必躁，到经不解，必圊(校正注：“圊”通“清”)血，名为火邪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615798191652938, 'B8E8F7F58A1E346E437F3F1674FCFDC6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:49:17', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5335, 318, 904000576, '      形作伤寒，外形看起来像伤寒，其实不是伤寒，平常脉很弱的人大多是血不够，血不够代表津液不足了，营养不足了，代表免疫系统不够强，这种人一定口渴，因为本身津液已经不足了，再被火一烤，一定发谵语；如果脉浮起来，就代表津液回来了，津液一回来的时候，免疫系统出来到皮肤表面上去，脉就浮起来了，病如果在表的时候，不管是免疫系统的问题，滤过性病毒的问题，或感冒的问题，病如果在表就一定会摸到浮脉，就像火烫伤的，他没有病，但是皮肤被烫伤了，所以脉一定是浮起来的。  ', NULL, NULL, NULL, NULL, NULL, '126、形作伤寒，其脉不弦紧而弱，弱者必渴，被火者，必谵语，弱者发热，脉浮，解之，当汗出而愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615798191652939, 'C2145B677DA3829BCAD0BF9E0FF13118', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:49:17', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5336, 318, 904000582, '      桂苓甘草龙骨牡蛎汤和桂枝去芍药加蜀漆龙骨牡蛎救逆汤不一样，救逆汤是非常紧急的时候大剂的救逆用的，桂苓甘草龙骨牡蛎汤是一般性的，前面的是烫伤、惊狂不得卧，这个只是烦躁而已，火逆烧针，还有流汗。  \n\n        桂枝甘草汤条云发汗过多，其人叉手自冒心，心下悸欲得按者，桂枝甘草汤主之。这132条也是发汗过多的明证，从桂枝甘草汤变证而来的，用到龙骨牡蛎的时候，病人一定有浮阳在上，浮阳在上最简单的辨症就是头部一直在流汗，身体不流汗，整个肠胃的阳气都跑到上头去了，肠胃蠕动都减缓。像烧针造成的烦躁，都是水的系统不是很好，因为烧针造成气化的系统改变了，使水停在中焦，所以要加茯苓把水排掉，如此可以补充新的水到心脏，所以可以生津除烦；这汤剂临床上在用甲状腺亢进最多，西医的名词，西医用放射性碘来治疗，就是甲状腺大脖子一直手抖、心颤、盗汗、心悸、很紧张，放射性碘一吃下去。甲状腺干掉了，但是同时子宫也干掉了，会终身不孕，此病中医叫蟹眼证，就是眼睛像螃蟹一样突出来，它的症状有第一心悸，心脏跳动的非常快，第二手抖，第三嘴巴口燥，嘴巴里面非常的燥渴，第四盗汗得非常严重，牡蛎常常用在攻坚，所以有硬块的时候，牡蛎用一两二两都没有关系。牡蛎是蚵的壳，所有身体里面的脑瘤、淋巴瘤都可以用，所以牡蛎用于攻硬块时一定比龙骨重用。平常用桂枝加牡蛎龙骨就好了，桂枝汤可以和解营卫，气血就会旺，免疫系统很好，肠胃就好，固表能力很强，这时候再加牡蛎龙骨，精子的生化过程就会很好，当男人的精子太淡时，太太不容易怀孕，用桂枝汤加龙骨牡蛎让精成熟得非常好，所以这是用在男人身上的。  \n', NULL, '桂苓甘草龙骨牡蛎汤', NULL, NULL, NULL, '132、火逆，烧针汗之，因烦躁者，$f{桂苓甘草龙骨牡蛎汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615799898996806, '69FCB0623C491FD3057826D2E99E672D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:56:14', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5337, 318, 904000583, '      人身上皮肤表面有一定的温度，皮肤表面有一层水气在上面，叫太阳表水，还有一个太阳的表热，两个不一样，这两个混在一起就是体温；当热没有了，只剩水就会感觉冷，如果水没了，病人流虚汗的时候就会感觉到热；当伤到寒以后，皮肤表面的水会很多，加温针的时候，水就会逆流进去，水逆流回胸就会动悸，病人像受到惊吓一样，惊惶就是水逆流的现象，所以永远禁用温针去取汗，或三温暖（校对注：台湾语，即桑拿）去取汗。以上讲的是太阳证中篇。  \n\n        中药的辨症论治是临床上不可缺少的基本知识，取法都自《伤寒》和《金匮要略》两书。赵情初说：古人随证以立方，非立方以待病。祖国医学的可贵处就是统一整体观念的。仲景的学说就是最可贵的辨症论治。 ', NULL, NULL, NULL, NULL, NULL, '133、太阳、伤寒者，加温针，必惊也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615836554055750, 'A7C7E4C35727849BE2FD4777EB0EE1D6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 14:25:23', 1, '超级管理员', '2024-11-25 14:25:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5338, 319, 904000601, '     关讲的是脾胃的脉，胃气的脉，关的脉很细很数，摸到病人的脉很细，就代表身体很虚，数代表热，就代表病人虚热了。\n     何谓虚，虚就是无物，没有东西堵到，张仲景特别讲关上，讲的就是胃，胃里面虚就是胃里面已经没东西了，胃气在上面，空在那边并没有消化，从这一点知道张仲景说，以医吐之过也，前面医生可能开了吐药给他，或是病人有伤寒表证，来不及吃桂枝汤却吃了坏东西，一吐，结果把肠胃里面的东西都吐光了；\n     中医里面有汗法、下法、吐法，都是中医治病的方法，通常采汗法、下法，吐法很少用，病人吐的时候，可以把脏东西吐出来，所以有时候会采吐法，过去有医师专门用吐法，他们的观念是，一吐掉后胃里面没有东西了，胃的元气会起来，就是免疫系统会起来，抵抗力的来源都靠胃里面一直消化食物，一直在吸收营养，结果一得到感冒，胃不吸收营养了，这时候医生又不敢攻下，攻下怕引起其它的变证，干脆把胃里面腐败的食物吐出去，肠胃的津液马上就成为固表的抵抗力；吐可以，但是张仲景说吐太过了，如果一二日吐之者，如果刚开始吐，只吐一两天，腹中饥，口不能食，病人有饥饿的感觉，但是嘴巴吃不下东西，就是胃的津液伤到了，但是脾脏的功能还很好，不管在什么地方，只要有腹中饥，口不能食就是如此，就是胃的津液都吐掉了，脾脏的功能正常，脾胃是相表里的，想吃东西，感觉到肚子饿就是脾脏的功能恢复了，脾脏的功能没有恢复的时候，病人不会想吃东西的，所以小孩子一得到感冒的时候，第一就是没有胃口了，桂枝汤一下去的时候，第一个反应就是胃口恢复了，小建中汤一下去，为什么胃口会恢复，当胃的功能受到损害，口不能吃东西，吃东西吃下去，胃不能吸收，可是肚子又很饿；吐了三四天之后，不但胃伤到了，脾脏也伤到了，脾脏也伤到的状况下，胃里面整个冷了，没有胃阳，因为吐光了，冷掉以后稀饭也吃不下去了，此时要吃冷的东西比较舒服，因为胃里面很冷，没有功能没有蠕动，热的下不去了，但是吃了冷的东西，下去到胃里面又朝食暮吐，所谓的寒，就是没有蠕动了，一吃食物就停在胃里面，也没有磨碎就停在里面，吃完就感觉胀胀的，从早上吃的东西都不消化，到了黄昏的时候，就吐出来了，就是冷太过了，脾胃都伤到了。  \n\n       如果腹中饥，口不能食，就是吐伤到胃液了，这是虚证，处方有大半夏汤，大半夏汤的方子里面，有半夏来止呕开胃，有人参把胃的津液补足，所以小柴胡汤有呕，小柴胡汤里面也有人参，所以只有这两味药，一个止呕，一个增加胃液，摆明的就是胃液伤到了，让这药停在胃里面，还加了白蜜，就是蜂蜜，蜂蜜生用会加强药的效果，像芒硝滚一滚就停了，不可以滚六碗水到两碗水的时间，有的时候烫一下就好了。如果吃到朝食暮吐，就是西医的胃下垂、胃酸反逆、火烧心，朝食暮吐就是吴茱萸汤里面有四味药，人参、生姜、红枣，这几味都是健胃整脾的，把胃液补足的，再加吴茱萸，这药很热，让脾脏功能马上恢复，让胃马上热起来，生姜可以换成干姜，温中的力量比较强。大半夏汤是专门对胃，吴茱萸汤更强，吴茱萸汤是进入脾脏的，平常小孩子如果吃坏肚子，吐的太过了，就给他大半夏汤，吐得已经不想吃东西了，早上吃的稀饭到晚上吐出来还是稀饭，就给吴茱萸；嗳气很厉害的时候，加上旋覆花代赭石汤。  \n\n      怎么知道胃下垂了？朝食暮吐就是了，摸脉也可以摸到，一般心脉没了，即左手的寸脉没了，右手的关脉很大，心脏摸不到就代表胸阳没了，右手的关脉就是脾胃脉，脉大就表示停在那边没有功能，结果脉会胀大，因为胃阳没有往上升变成胸阳，上焦整个冷的。  \n\n       在美国，看到很多胃病的例子，都是因为吃过多的精制过的糖所做的甜食所造成，开药方给病人的时候，必须同时叫病人甜食不能吃，巧克力不能吃，可乐不能喝，咖啡不能喝了；喝茶最好。治胃病的时候，用粉剂比较好。  \n\n       吐法为古代医家治疗法则之一。张载人以吐治宿疾，名噪一时。现在很少用吐法了，秉照《内经》的原意，病在胸膈以上采吐法，病在中焦采和解，病在下焦采攻下的方法把它清掉。\n  ', NULL, NULL, NULL, NULL, NULL, '134、太阳病，当恶寒发热，今自汗出，不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，以医吐之所致也，此为小逆。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615846970077254, '07F768B840B04634CB984EEEB4C6A062', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 15:07:46', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5339, 319, 904000602, '       因为吐太过了，胃的津液伤到了，胃太干燥了就化成热，化成虚热往上走，病人就会烦燥，这也是可以用大半夏汤；吐太过了，还有几个变证：如果吐太过了以后，病人口渴，胃里面没有水了，全吐光了，如果渴而烦燥者，就是胃里面的水没有了，胸腔里面的水也没了，大太阳在胸腔，这时候用人参白虎汤；如果病人吐了半天但热不渴，代表胃的津液没有伤到，但是还有表热，所以用桂枝白虎汤，因为兼有表热阳明热，但是胃的津液没有伤到，所以把人参拿掉，把人参换成桂枝；北派会用到人参的时候，大多都是在肠胃科，平常不用的，因为人参很珍贵的，肠胃的津液不足的时候，正好用人参来补足，这是补津，如果黏液不足的时候则用红枣来补。  ', NULL, NULL, NULL, NULL, NULL, '135、太阳病，吐之，但太阳病当恶寒，今反不恶寒，不欲近衣者。此为吐之内烦也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615850876407878, '939ABC063897E8B94553E002EF92C255', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 23:23:40', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5345, 319, 904000607, '       热结在膀胱应该小便不利，现在小便很正常，病人陈述少腹中极、关元一带很痛，不通则痛，小便很好，就是血堵到了，小便不利，可能是结石，五苓散就可以通出来了，现在病人感觉到很痛，摸病人的肚子又是软的，就是瘀血瘀在里面，辨症有没有血，就是看小便利不利，不可余药，宜抵当丸，其它药都没有用，一定要用抵当丸，用丸剂，它的症状看起来比较轻，比抵当汤证轻，剂量一样，虽然看起来比较轻，但是他的病比较深。', NULL, '抵当丸', NULL, NULL, NULL, '140、伤寒，有热，少腹满，应小便不利，今反利者，为有血也，当下之。不可余药，宜$f{抵当丸}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615860645310534, '1FC0A26250D0B10AF6675DBA9DCEDE31', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 16:03:25', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5346, 319, 904000606, '       这又分两个，一个小便利，一个小便不利，来分有血无血，如果没有血的话，身黄，脉沉结，少腹鞕，小便不利者，为无血也，后面会用茵陈蒿汤，茵陈蒿汤专门去膀胱的热，火 在下面烧，膀胱气化之后，一部分不好的小便小掉，一部分好的水进入胆，分泌胆汁帮助消化，胆汁是黄色的，如果膀胱里面太热了，胆汁分泌太热的时候，病人会身黄；不要小看血证，X 光看不到血，结果病人发狂，这瘀气有时候会跑到脑部去，有时候是大承气汤，有时候是抵当汤，所以要看小便利不利，利就是用抵当汤，如果小便出来很黄，就是下焦很热，大便又没有了，就用大承气汤去攻。  ', NULL, '当汤主', NULL, NULL, NULL, '139、太阳病，身黄，脉沉结，少腹鞕，小便不利者，为无血也；小便自利者，其人如狂者，血证谛也，抵$f{当汤主}之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615860645310535, '500128AEB474B379F1F90697E36603B7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 16:03:25', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5347, 319, 904000605, '       水蛭就是吸血虫，现在市面上买到的水蛭，尺寸像手指头大的没用，水蛭要小小的才有用，以前的人抓水蛭，就是把脚伸到水里面，不吸的不要，要吸血的水蛭就是了，市面上买到的虻虫是在粪坑旁边飞的虫，小小的不可以用，虻虫就是牛虻，吸牛血的虻虫，要用像指甲大的虻虫。遇到抵当汤证的时候，一定是少腹鞕满，确定血瘀在里面，小便一定是顺利的，这时候如果病人大便正常，就不要用大黄；病人如果身体很虚弱，已经奄奄一息了，这时候把大黄改成地黄，去补病人的血，破血就是靠水蛭、虻虫这两味药，小动物咬血咬得最厉害的就是这两种东西，水蛭、虻虫的炮制，放在铁片上烤焦黄就可以了，不要变黑的，翅膀和脚都去掉，只要身体就可以了。  \n\n水蛭、虻虫三十个，大约三钱左右，桃仁二钱，大黄三钱；如果用地黄，用一两，地黄是补虚的，用五钱就补不到了；用五碗水下去煮三碗，喝了第一碗，没有下再喝，下就是拉血，不要紧张，腹中的小孩不会伤到。  \n\n      东洞翁本方定义曰：治有瘀血者，凡有瘀血者有二：少腹鞕痛而小便快利者，其一；腹不满而其人自觉满者，其二。急则以汤，缓则以丸。小便不利者就是瘀血在膀胱，就是桃核承气汤，小便快利者就是抵当汤，还有腹部摸起来软软的，病人感觉腹部难过也是血证，急的用汤剂，比较不急的用丸剂，一般来说，如果病在表比较浅，会痛得很急，病比较深的，痛起来反而比较不急。所以用丸剂，为什么作丸？丸取它的药缓力重，急性的要很快的赶出 去，就用汤剂，汤者荡也，肠胃科的问题，则用粉剂比较好。  \n\n       方与輗曰：上症凡体虚者多患之。夫体虚者，虽瘀血在少腹，但不可攻。然不攻则病又不去。善哉！陈自明与此方中去大黄加地黄用之，名曰气通经丸，仅一味之加减，克尽守攻之能事，孙吴兵法，亦不足过。余尝以此四味，水煎以治干血劳甚效。干血劳就是血已经干掉了，干在腹腔里，病人表现的表证就是肌肤甲错，女孩子很多在腿和腹部每到冬天就要蜕皮，皮肤就像蛇皮一样，会干掉，夏天就好好的，其实就是干血劳。  ', NULL, '抵当汤', NULL, NULL, NULL, '138、太阳病，六七日表证乃在，下之，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈。所以然者，以太阳随经，瘀热在里故也。$f{抵当汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615860645310536, '7DBD467C195E88E9BC17BB8740D81156', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 16:03:25', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5348, 319, 904000604, '       本来太阳应该已经进入少阳、阳明了，如果病人感觉到心下温温，心下就是胃，如果胃里面闷闷的，感觉到食物消化不了，就是病进入阳明了，欲吐，而胸中痛，就是进入少阳、阳明的时候，病人有恶心的现象，肠胃的功能受到滤过性病毒的影响，胃的功能不是很正常，病人胃的蠕动不是很好的时候，病人就会恶心想吐，或水气进入的时候也会这样，因为胃的地方和胸的地方，这整个部分就叫做阳，是诸阳之通路，所有的阳都经过它，阳就是身体的动能，大便反溏，照理说应该是进入阳明证了，会燥结，结果反而大便很黏稠，腹微满，郁郁微烦，肚子胀满，但是胃里面很难过，郁郁微烦就是脾胃不和，消化不是很好的感觉，如果病人在这种症状下，病人的感觉是自欲极下吐者，就是胃里面很难过，把这一口吐掉会比较好一点，喝酒喝多了就会有这种感觉，自己想把它吐掉会比较舒服点，有时候不见得是喝酒，所陈述的就是在这里，如果遇到这种情形，不用去吐，调胃承气汤一下去，通通清出去了；食物一半在胃的下方，一半在十二指肠里面，腹诊按中脘穴以下的建里、下脘有压痛反应，调胃承气汤下去把它清出来，如果吃了调胃承气汤没有好，就代表他是虚证，因为调胃承气汤是去实热的，有东西堵到了才会用调胃承气汤；但欲呕，胸中痛，微溏者，此非柴胡证，以呕极吐下，故知也。病人自己吐太多了，会有这现象，为什么非柴胡证？因为张仲景写只要有一个症状就可以用柴胡汤，可是这里的恶心不是柴胡汤证的恶心，是食物不消化的恶心，就是自欲极吐下。', NULL, '调胃承气汤', NULL, NULL, NULL, '137、太阳病，过经十余日，心中温温，欲吐，而胸中痛，大便反溏，腹微满，郁郁微烦，先此时，自欲极吐下者，与$f{调胃承气汤}；若不尔者，不可与；但欲呕，胸中痛，微溏者，此非柴胡证，以呕极吐下，故知也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615860645310537, '7620978AE6068021DC7F98824DBC2EDF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 16:03:25', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5349, 319, 904000603, '       摸到病人的脉跳得很快，代表胃蠕动太快了，所以消谷引食就是一直吃，胃口非常的好，消化得很快，正常的脉数应该为消谷引食，结果病人反吐，数为客热，不能消谷，脉数是热，因为发汗太过了，这热不是真正的热，是假的热，这热是发汗发太过的虚的现象，因为不是真正胃蠕动引起的热，所以它不能消化食物，发汗发太过了以后，阳气伤到了，胃气虚了，就是甘草干姜汤，炙甘草干姜用在当发汗发太过，阳虚的时候用的，胃中虚冷，最好用的是甘草、干姜，如果遇到病人朝食暮吐、胃下垂，舌苔整个白的，用吴茱萸汤把生姜换干姜，干姜比生姜热，干姜是温中，生姜是散寒，用生姜是希望吃药后把药散到四肢上去，所以生姜是发散用；把药推到四肢用的，如果胃里面已经没有火了，干姜是让胃里面的火烧起来，所以干姜点火用的，可以用此角度去考虑。这种情形可能是医师用吐法来发汗，所以会脉数；或者是病人有表证的时候，刚好吃到坏死的食物，吐了以后导致胃中虚冷。  \n\n      如果是真正的消渴，现代所说的糖尿病，喝水吃东西很快的消化掉，没有吐出来，我们分三种，上消是渴饮千杯不能止渴，中消饥食百碗不能解饥，下消就是性功能丧失了。  \n\n      萧万兴曰：盖数本属热，而真阴亏损之脉，亦急数也。癌症的病人也可以摸到急数的脉，一息九至十至，真阴亏损的时候，元气大伤，病人内脏功能开始消退，然愈数则愈虚，而愈虚则愈数，一有差误，生死反掌。  ', NULL, NULL, NULL, NULL, NULL, '136、病人脉数，数为热，当消谷引食，而反吐者，此以发汗，令阳气微，胃气虚，脉乃数也。数为客热，不能消谷，以胃中虚冷，故吐也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 615860645310538, 'D6220D3D0B82B84EF195ABC21F5995F2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 16:03:25', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5350, 319, 904000612, '     会造成结胸，是因为本来有表证，结果被攻下，表热跑到里面去了，外邪内陷，阳没有办法舒张，所以脖子就会项强，如柔痉状，看起来像抽筋，大陷胸丸主之。  \n\n     大黄是去实的药，芒硝是攻坚的药，如果光吃这两味药，马上就到直肠去了，张仲景为了让药停在胸里面，第一加葶苈，葶苈下去的时候，吐痰吐一大块，有痰所以加杏仁，因为胸腔很热，痰、热、水三个加在一起叫结胸，葶苈子去痰，杏仁去热，因为堵在中膈，所以肺的下方还很多，所以一方面往下走，一方面吐出来，这四个剂量相等，胖子可用葶苈子三钱。', NULL, '大陷胸丸', NULL, NULL, NULL, '145、结胸者，项亦强，如柔痉状，下之则和，宜$f{大陷胸丸}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616124787875910, '6CB712F821F7483B6FB3CBBA53C5DC29', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 09:58:13', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5351, 319, 904000611, '       病发于阳，而反下之，是讲强壮的人，应该是发表结果攻下，表热跑到里面去，结果热邪入里，造成结胸。病发于阴，本来是身体很弱的人，他的肠胃虚弱，结果攻下了，就变成心下痞证了，痞是胃里面的，所以成结胸者，以下之太早故也，造成结胸的就是攻下攻太早了；这条辨是说，伤寒太阳中风的时候，如果有表证要先解表，要去攻里的时候，第一个一定要确定他没有表证，一旦确定里实了，二三天不大便了才去攻，所以攻要有攻的时机。痞有泻心汤，结胸有大小陷胸汤。  \n\n        结胸有大结胸、小结胸、水结胸、热实结胸、寒实结胸之分。\n                大结胸与热实结胸不按而痛。胸就是胃脘的部分，巨阙和中脘的地方，不按都会痛，实际是有东西堵到了。\n                结胸热实，脉沉而紧，心下痛，按之石鞕；大陷胸汤主之是也。\n               小结胸按之乃痛。小结胸就比较轻了，抽烟的人常常有，小陷胸汤随时可以吃的，小结胸病，正在心下，按之则痛，脉浮滑者，宜小陷胸汤是也，小结胸一定会有的症状就是恶心的现象。\n               水结胸则无大热而头汗出。头一直在流汗，是相书上的蒸笼头，像猪的大肠，拉起来就倒下去了，像扶不起的阿斗，如结胸无大热者，此为水结在胸胁也，但头微汗出者，大陷胸汤主之是也。\n               寒实结胸则无热。如寒实结胸无热证者，与三物小白散是也。\n\n              简单的区分，结胸就是痰和表热进来和湿梗在中间，这就是热实结胸，就是大结胸，\n              寒实结胸，例：晚上很口渴，连吃了三种冰，冷的在胃里面， 胃没有蠕动，又去吃猪油炒饭，吃完又口渴，拿冰水又喝，结果食物从食道一路堵到大肠，整个没有蠕动，这就是寒实结胸，很危险的。  ', NULL, NULL, NULL, NULL, NULL, '144、病发于阳，而反下之，热入，因作结胸。病发于阴，而反下之，因作痞。所以成结胸者，以下之太早故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616124787875911, 'FE758C9EBD541183DF3BF86927783FBB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 09:58:13', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5352, 319, 904000610, '       脏结，就是所谓的阴寒证，寒湿很盛的，没有阳证，往来寒热是少阳证，所以没有往来寒热，阴证的人很安静，这种里面寒湿很重，不可以攻，中药的攻药，都是比较寒凉的药，里面已经很寒了，再用寒凉的药，会很危险。  \n\n      成无己曰：脏结于法当下，无阳证为表无热，不往来寒热为半表半里无热，其人反静为里无热。以表里皆寒，故不可攻。  \n\n      柯韵伯曰：脏结是积渐凝结为阴，五脏之阳已竭也，外无烦躁潮热之阳，舌无黄黑芒刺 之苔，虽有鞕满之证，慎不可攻，理中、四逆辈温之，尚有可生之义。其实理中、四逆都不够力的。  ', NULL, NULL, NULL, NULL, NULL, '143、藏结，无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616124787875912, 'D9612361A2296BD26C6A2871D9F3E18F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 09:58:13', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5353, 319, 904000609, '       寸是指胸，是阳，寸脉浮代表结在上面，关脉沉代表病在胸膈以上，不过中焦，何谓藏结?如果脾藏的湿渗到关节里面就是风湿，如果湿很盛，病人的体质寒冷，就是没有什么功能，动能不够。本身湿再遇到寒，慢慢把五脏肝、心、脾、肺、肾，整个外面的一层被黏液都包住了，这时候脏都没有吸收功能了，腑是消化系统，饮食如故，所以腑没有问题，脏有问题，腑和脏之间的管道都被寒湿包住，时时下利，腑的食物营养要给脏，脏不受，所以通通跑出来了，下利出来的都是食物的精华，所以关脉小细沉紧，舌头白白滑滑，舌苔黏厚，黏滑代表湿，舌苔上的白代表寒，寒湿结在里面，这种很难治。要开很热的药，用生附，炮附，生姜等热药，病人吃下去的时候很冷，半夜的时候胃气回来，会饿代表脾脏功能恢复了。  ', NULL, NULL, NULL, NULL, NULL, '142、问曰：病有结胸，有藏结，其状何如?\n         答曰：按之痛，寸脉浮，关脉沉，名曰结胸也。\n         何谓藏结? \n         答曰：如「结胸」状,饮食如故,时时下利,寸脉浮,关脉小细沉紧,名曰「藏结」；舌上白苔滑者,难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616124787875913, 'AF4A91E48595EE9DFF703758D68A2300', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 09:58:13', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5354, 319, 904000608, '       太阳病本来表热很盛，病人会想喝水，但是太阳病是表热不是胃热，喝水太多没办法消化掉，一部分小便排掉了，一部分水会停在胃上面，所以就会心下悸；如果喝水喝得很多，结果小便少了，就知道水结在膀胱里面，膀胱里面的热很大，水结膀胱有两汤方：五苓散、猪苓汤，猪苓汤就是膀胱结石或肾结石堵到了，小便小不出来痛，如何辨肾结石？在太溪和复溜这一侧有压痛点就是有肾结石。  ', NULL, NULL, NULL, NULL, NULL, '141、太阳病，以饮水多，小便利者，必心下悸；小便少者，必苦里急也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616124787875914, '4A780B4AF7E3FD2A9315AF16A4D2AC1F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 09:58:13', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5355, 319, 904000615, '        中风发热才会脉浮则为风，数则为热，热跑到血里面，脉就会数了，脉跳得很数的时候，就代表热在血里面，还有一种是微细数，代表血里面的津液没了，血里面的水不够了，血很热就会有虚的热，表未解也，应该是攻表才对，医反下之，一攻下的时候，病人的血往下走，身体上的血就虚掉了，结果表阳就下陷了，动数变迟，脉就变慢了，这水正常应该是透发出去，结果这水没有发透，流回来了，流回到胸腔里面来，入内了，这水往里面跑的时候，变成了客气动膈，水在皮肤表面叫做水，进入身体里面就是成为湿了，膈内拒痛，就是膈上面，湿在胸膈横膈的地方，里面还有痰，痰和湿和水整个梗在胸膈的地方，硬梆梆的，硬块吐不出来，整个结在这地方，病人短气烦躁，就是因为人呼吸的时候，横膈要下降，胸膈梗到了，又降不下来，因为梗到了，一吸气就要吐出来，就变成短气，病人烦躁，阳没有办法下降，阳在上面当然会烦躁，心中懊憹，就是胃里面很难过，胃中空虚因为被误下了，肠胃里面空了，所以误下才会有结胸，平常不会的；若不结胸，为什么没有结胸?就是病人上焦没有湿热，没有湿痰，湿痰很盛的人，开桂枝汤的时候，看病人的舌头很湿，就桂枝汤加白朮、茯苓；但头汗出，余处无汗，剂颈而还，小便不利，身必发黄也，胸里面没有湿热，水一进来就只是水，因为被胃蒸掉了，阳气往上跑了。因为被攻下了，胃虚掉了，只有头有汗，就是津液伤到了，因为一攻下的时候，肠胃的津液也跟着出去了，这时候津液伤到的话，津液只剩下一点点，头上只剩一点点阳，所以只有头上有一点点汗，其它身上都没有汗，因为津液不够了，被攻下了，那小便当然不利了，身必发黄，因为人本身津液伤到不足了，这黄就是透过皮肤看到血的颜色。  ', NULL, '大陷胸汤', NULL, NULL, NULL, '148、太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，头痛发热，而微汗出，及恶寒者，表未解也，医反下之，动数变迟，客气动膈，膈内拒痛， 短气躁烦，心中懊憹，胃中空虚，阳气内陷，心下因鞕，则为结胸，$f{大陷胸汤}主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616133505417286, '990DC2A08B6F7EC1E342AE6F3613745E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:33:41', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5356, 319, 904000614, '        烦躁者，就是胸阳脱了，阳离开身体的时候，阴阳相隔，阳在头上面，阴一直在下面，烦躁到不但晚上睡不着，到后来死前一个星期，眼睛都闭不起来，还在喘，这都是癌证末期了。这里的烦躁，可以用茯苓四逆汤来救逆。  \n\n        尤在泾曰：结胸证悉具，其脉沉紧，心下痛，按之石鞕，及不大便，舌燥而渴，日哺潮热，还有一种也是结胸证，少年的时候喜欢打架，打到胃地方瘀血，或胃出血渗到淋巴系统，日久后变成硬块，里面的血管和淋巴纠在一起，胃被挤压得很小，查病人的胃里面没有胃癌，但是胃的地方硬硬的，也是用大陷胸汤；当决定要用大陷胸汤的时候，要快，趁病人还有体力承担药的时候用，所以用峻剂的时候，要趁病人元气还在的时候赶快用。  ', NULL, NULL, NULL, NULL, NULL, '147、结胸证悉具，烦躁者，亦死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616133505417287, 'FC3F4F0117A7DB191E0C9BA5BCC803B0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:33:41', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5357, 319, 904000613, '       结胸证，脉应该很沉很紧在里面，结果摸到病人脉是浮大的，病人的真阳要脱了，元气已经快没有了，一般来说，到了这种情况都已经不能睡觉了，坐着等死。这是阴阳分隔的现象，这里条文说不可下，但是不得已的时候，还是要下，必须跟病人与家属说明清楚情况。  ', NULL, NULL, NULL, NULL, NULL, '146、结胸证，其脉浮大者，不可下，下之则死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616133505417288, '105CF84FFEC4E24F08465796C0454F83', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:33:41', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5358, 319, 904000618, '      重发汗、而复下之，就是用很强烈的发表药，津就伤到了，然后又攻下，好狠；平常如果是太阳病，如果经过发汗了以后，再攻下，一般是不会造成结胸的，结胸是没有发汗而攻下才会造成结胸的，重发汗攻下为什么会造成结胸?照理说发汗以后会攻下，一定是看到大肠里面堵到了，有燥屎了才会去攻它，不大便五六日，舌上燥而渴，如果五六天快一个星期不大便，舌上又渴又燥，这就是大承气汤证，日晡所小有潮热，到了黄昏的时候有点热，从心下至少腹鞕满而痛不可近者，大承气汤证一定是在两个天枢的地方有压痛点，心下就是从胃的地方到少腹这一条中间硬梆梆的堵到了，就是结胸，所以结胸和大承气不一样，大承气是大便堵到了，结胸是痰和热和水梗在这个地方，所以大陷胸汤是去痰去水去热的药混在一起用的。这一条是在分辨大承气汤和大陷胸汤，大陷胸汤一定是在中间，大承气汤一定是在两边，所以大陷胸汤也有五六日不大便的。  \n\n      大黄芒硝、厚朴、枳实就是大承气，如果把厚朴、枳实拿掉换甘遂，就变成大陷胸汤，一个是去痰水结在胸膈间，一个是去大便。  \n\n      方书说：喜按为虚，拒按为实；此为实热，不管是大陷胸或是大承气都是拒按，结胸的时候，不按他，他都很痛了，按他才痛，那是小结胸。大承气也是一样，不按都痛，按他更痛，例：倪爷爷吃减肥药，拉肚子造成疝气复发，按着很舒服，还可以把它塞回去，所以是虚证，里面没有东西只有气在里面，开厚朴生姜半夏人参甘草汤，放几个屁就收回去了。  ', NULL, '大陷胸汤', NULL, NULL, NULL, '151、太阳病，重发汗，而复下之，不大便五六日，舌上燥而渴，日哺所小有潮热，从心下至少腹鞕满而痛不可近者，$f{大陷胸汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616136136659014, 'A6905B1E212EB07C624B68B1385514EA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:44:24', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5359, 319, 904000617, '       伤寒十余日，本来有表证，麻黄汤就好了，结果热结在里，如果热结在里，大便没有了，热结到了，所以这是阳明证，便秘了，复往来寒热者，就是少阳证，阳明和少阳兼有，所以是大柴胡汤。小柴胡是介乎少阳和太阳之间。大柴胡汤下去的时候，表里双解，因为大柴胡汤里面有枳实、大黄。但结胸无大热者，此与水结在胸胁也，但头微汗出者，大陷胸汤主之。  \n这热和水结在胸腔里面，如果热结在里，就是结在大肠里面，结在下焦，就是大柴胡汤证；但结胸无大热者，就是结在上焦，胸口就是大陷胸汤证。', NULL, '大柴胡汤,大陷胸汤', NULL, NULL, NULL, '150、伤寒十余日，热结在里，复往来寒热者，与$f{大柴胡汤}。但结胸无大热者，此与水结在胸胁也，但头微汗出者，$f{大陷胸汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616136136659015, '20215F7FC01E8452D345E54FFFD1BB96', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:44:24', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5360, 319, 904000616, '      伤寒隔了一段时间以后，结胸热实，脉沉而紧，心下痛，这证并不是由误下而成的，本来这病人就是上热下寒，本来肺里面就很热，结果一得到伤寒，六七日没有好，为什么会结胸?因为伤寒，寒束在表面上，肺的热又不去掉，很热的时候，热会发散到四肢上去、结果寒去不掉，没有办法流汗，汗流不出来，热把汗推出汗腺，到了皮肤表面遇到寒，它又回头，又回到三焦里面，又跑回到胸里面来了，胸腔里面有痰有水有热结在里面，胃痛，大陷胸汤最重要的就是胃这地方按着硬梆梆的，就是痰，大便一通利，当场就软掉了。  ', NULL, '大陷胸汤', NULL, NULL, NULL, '149、伤寒六七日，结胸热实，脉沉而紧，心下痛，按之石鞕者，${大陷胸汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616136136659016, '07E0A85EDC5382DD0A1056C259E04C6D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:44:24', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5361, 319, 904000622, '       病在阳，就是病在表，阳就是表，应以汗解之，应该用发汗来解，反以冷水潠之，病在表身发热然后就是用水喷他，结果皮肤表面被束到了，汗发不出来，若灌之，还有一种状况是灌水下去，身很 热灌水下去也会，其热被却不得去，热被固在表上面散不掉，弥更益烦，热要出去又出不去，热在里面就越来越烦，肉上粟起，皮肤上鸡皮疙瘩起得很多，水要发发不掉，意欲饮水，反不渴者，为什么?因为他本身热在胸阳、在肺里面，胃并没有热，胃有热的话一定会燥渴，他很热又不想喝水，就是胃里面没有热，热在肺上面，这种状况下服文蛤散，是单纯的水饮证，水排不掉，是经方里面最轻剂的排水利尿剂；水发不掉用利尿，若不差者，与五苓散，如果还没好，就用五苓散，五苓散就是把表水从小便走掉，所以五苓散是很好治疗水肿的方剂', NULL, '五苓散,文蛤散', NULL, NULL, NULL, '155、病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，$g{肉上粟起}，意欲饮水，反不渴者，服$f{文蛤散}；若不差者，与$f{五苓散}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616147899248710, '5388D819BB81D7B4EB00B5D83C28F304', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:32:15', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5362, 319, 904000621, '这一条辨是说，医生光摸脉去诊断病人到底能到什么程度？太阳病，应该是发表，结果医生开错了误用攻下法。  \n\n   （一）脉浮，不结胸者，此为欲解也  \n\n如果病人变成结胸，脉就沉下去了，现在病人其脉浮，就不会结胸，本来表病就有浮脉，此为欲解也，代表病人身体很好，他的免疫系统没有因为攻下让表邪下陷到身体里面。  \n\n     （二）脉促者，必结胸也  \n\n为什么叫脉促?促脉跳跳跳跳，突然停掉，速度很快、突然停掉，然后又跳回来，跳六七八下停一下，为什么?因为被攻下后，血往下走，下利以后血要回流回来，可是血流回来力量又不够，回溯力量够的时候，就跳得很快，不够的时候，突然血空掉了，因为是下利造成身体里面虚掉了，血空的时候脉就没有跳起来，遇到这种情形，就知道病人的体能没有办法恢复，所以现在摸到促脉就知道一定会结胸了。  \n\n    （三）脉细数者，必咽痛  \n\n何谓细?细脉代表里虚掉了；何谓数?数代表热。本来寒束在表面上，攻下以后有一种情形，寒束在肺的外方，胸是诸阳之会，阳要发散出来，流汗就是肺的功能正常，寒束到表了，肺热出不去，热本来性就是轻的，热气往上冲到皮肤表面，发散不出去就冲到喉咙，遇到这种情形的时候，要把肺寒去掉要靠麻黄、杏仁，这热从哪来?胃，胃本来就是土生金，所以热的源头就是胃，要把胃热降下去就加石膏、甘草，所以麻黄、杏仁是去肺寒去表，石膏、甘草降胃热，所以有麻杏甘石汤。  \n\n     （四）脉弦者，必两胁拘急  \n\n弦脉代表水，弦脉也是少阳的脉，因为肝胆的脉正常是弦，肝是厥阴，胆是少阳，所以少阳的脉本身是弦的，弦脉不但主水也主少阳，一被攻下以后，没有进入身体，没有进入肠胃，这水一回流进入胸肋中焦，进入两胁的地方，当然两胁拘急，这时候开小柴胡汤，因为胸胁苦满。  \n\n    （五）脉紧者，头痛未止  \n\n何谓脉紧?就是寒还在表上面没有陷进来，这紧脉代表寒束在表面，束得很厉害，绷得很紧，摸到的脉很硬，这时候还是开发表的药，为什么病人感冒会头痛?人身体里面本来就有热气，这热气就是阳气，就是免疫系统，我们的体能，寒束在表面的时候，免疫系统自然会冲上来，第一个就是冲到头部，热发散不出来，就闷在头上面，结果头在痛，中医的讲法是固表力跟表邪在相抗，西医的讲法是免疫系统跟滤过性病毒相抗、产生的痛，这时候要用药去辅助它，让他发表流汗就好了。  \n\n （六）脉沉紧者，必心下痛  \n\n何谓沉?按到骨边才摸得到脉就是沉，按得很深，沉代表病在里；何谓紧?紧代表寒，所以是里寒，如果浮且紧就是表寒，怎么变里寒？因为攻下的药都是寒凉的药，芒硝是很寒凉的药，寒凉的药下去后，造成里面寒掉了，心下痛就是胃里面痛，这时候肠胃冷掉了，如果病人恶心、呕吐还是小柴胡汤，如果里面痛，确定病人胃里面有没有东西？如果没有东西，就用甘草干姜汤下去，如果有东西堵在里面的话，就用热的药加一点大黄下去，把里面滑出来，譬如甘草干姜汤里面加一点大黄，大黄无所谓寒热，只是去实，用甘草干姜把胃热起来。  \n\n （七）脉沉滑者，协热利  \n\n沉脉代表里，滑脉代表有痰饮，滑脉摸上去像锯子一样跑的，还有血过热的时候也会有滑脉，血流速度很快，血里面有一定的温度，就是靠水，血过热的时候一定是水不够了，热就是发炎，发炎所以水分会丧失很多，因为下利把水分都排掉了，所以燥热起来了，要把利止掉津液才能补回去。  \n\n （八）脉数滑者，必下血  \n\n滑已经是血里面有热了，再加数就是壮热了，壮热到极限的时候，血管会破裂，破在肛门的话就便血，破在膀胱的话就会小便带血，心脏血管破裂外面有网膜包着，心脏下来有肾 主动脉，就是到肾脏有一个大动脉，如果破裂，旁边还是有一个网膜包着，西医是把这段剪掉，换一人工血管，为什么会破裂?因为壮热，阳明证没有好而造成的，所以有时候看到小孩发高烧，要赶快退烧，用白虎汤或承气汤，如果只是津液伤到，西医打点滴是会退烧，但如果大便堵在里面，西医就没有办法了。  ', NULL, NULL, NULL, NULL, NULL, '154、太阳病，下之，其脉浮，不结胸者，此为欲解也；脉促者，必结胸也；脉细数者，必咽痛；脉弦者，必两胁拘急；脉紧者，头痛未止，脉沉紧者，必心下痛；脉沉滑者，协热利；脉数滑者，必下血。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616147899248711, '7347F61E050D10BAF3A893CD4A5B9C89', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:32:15', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5363, 319, 904000620, '       平常太阳病怎会不能卧?睡觉照样睡，二三天以后，病人不能睡觉了，不能躺下去，要坐起来比较舒服，所以胸中有水饮的时候，病人无法卧，因为一躺下去的时候，水就逆上来了，他会吐；第二，水进入肺胸腔的时候会咳嗽，所以一躺下去会更咳，如果水饮不是很强，在横膈膜的地方就是苓桂朮甘汤证，会引起晕眩，心下必结，就是胸里面有堵到，脉微弱者，本有久寒也，如果病人只是有水在里面，用苓桂朮甘汤去，如果病人脉微弱，就是本身身体很虚寒的，胸寒的人，遇到这种症状的时候，知道胸里面寒掉了，水又聚在胸里面不下，就会但坐不得卧。  \n\n        如何知道是水，问病人渴不渴?不渴，就是水了，还有看舌头，如果舌苔湿湿的，摸脉脉是弦的，细细的，所有的水病，脉一定是弦，脉如果细细的像吉他弦一样的跳，就代表身体里面有不正常的水，正常的要用温化，把胃里面温起来，然后能把水化掉，如果没有胃寒，只是水饮搁在胃的外面的时候，苓桂朮甘汤就去掉了；所以要取温化，最好的温胃药是干姜，有的时候干姜、生姜并用，干姜让胃热起来，生姜把它打散开来，因为明知道有水在里面，病人不渴有水，所以要把水去掉，要加半夏。胃为什么会冷掉?脾的功能一定不好，所以要加白朮、茯苓等量的用，来加强脾脏的功能，这时候胃就开始动了，胃里面热起来后水气才会到肺上面，水气会像云雾一样，后面要加炙甘草可使胸阳壮盛，等于甘草干姜汤的加减，这就是把胃里面的水温化掉。  \n\n        如果遇到这种情形肠胃已经是寒的，医生没有开温化的药，反下之，为什么会用攻下法?因为病人心中结，胃里面很难过，医生以为是食物堵起里面，不知道是水，开错药了，如果攻下去以后，他太阳表证还有，太阳病还没好，如果止利，必作结胸，因为他里面本来就有水饮在里面。  \n\n        未止者，四日复下之，此作协热利也，张仲景这里的意思是说，如果下利的状况不止，寒会跟着利一起走，寒跟着利走的时候，太阳表热，前面讲的太阳病二三日，皮肤表面上的滤过性病毒就陷进来了，顺着水道系统进入肠子，本来应该吃桂枝汤发表的药，把肠胃的津液发出去，这肠胃和皮肤的管道是通的，结果一攻下，表邪都进来，到肠胃里面来，就变成协热利，协热利就是大便很臭，滤过性病毒是一定的量，它经过皮肤到肠胃里面，引起肠炎，这时候就不是太阳表证的药了，到时候开譬如葛根汤、五苓散，协热利严重的用葛芩连汤，临证上来开。  \n寒湿是有形的，我们的白津就是寒，黏黏的，食物进入消化系统就是腑。腑供给脏营养，如果被寒结到，就会挡在外面，就是这白白的湿，平常去湿的时候就是采攻下从大便排出，像脏结，要把脏结的寒去掉，让脏腑间的功能能够结合在一起的时候，开给病人的处方，里面没有大黄、芒硝攻下的药，结果病人一直在下利，拉出来的大便黏黏稠稠湿湿的，这就是寒湿都排出来。  ', NULL, NULL, NULL, NULL, NULL, '153、太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，本有久寒也，反下之，若利之，必作结胸；未止者，四日复下之，此作协热利也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616147899248712, 'FC7CB3468381A824AC31F2159D2E0C32', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:32:15', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5364, 319, 904000619, '       心下指的是胃，小结胸和大结胸梗在这地方不一样，大结胸的痰热湿整个梗在这，不按它都痛，所以大结胸不按都痛，如果结得比较轻微，没有那么强，变成小结胸，所以小陷胸汤比大陷胸汤稍微缓一点，比较轻的要按才痛，按之则痛，脉浮滑者，所谓脉滑代表有痰在里面，脉浮就是病比较表比较轻，大结胸证的话，脉沉且紧，沉就是病很深在肺的下方，紧就是很扎实。  \n\n       小结胸之症状仅在胃中，与痞略同，但按之痛，痞则不痛耳，为胃中痰热互结黏膜发炎之病也。主用苦降泄热涤痰之小陷胸汤之法，以黄连清热，半夏降水，栝蒌实开结滑痰。小陷胸汤里面有三味药，黄连、半夏、栝蒌实，用黄连去热，黄连有消炎的作用，因为里面有热有痰，栝蒌实能够破结，能把痰打开，用栝蒌实来攻它，然后用生半夏把它利下来，所以一般来说结胸就是痰和热并结在一起，大陷胸汤不但痰热还有水三个并结在一起，生半夏除了利水之外还利痰，所以栝蒌实把痰打散后，半夏把它利下来。  \n\n      柯韵伯曰：结胸有轻重，立方分大小。从心下至少腹，按之石硬而痛可近，为大结胸。正在心下，未及胁腹，按之则痛，未曾石硬，为小结胸。大结胸是水结在胸腹，故脉沉紧。小结胸是痰结在心下，故脉浮滑。水结宜下，故用甘遂、葶、杏、硝、黄等下之。痰结宜消，故用黄连、栝蒌、半夏以消之。水气能结为痰，其人阳气重可知矣。大陷胸汤从胃的地方到肚脐这一段，硬得很紧，给西医看，他可能是胃癌或淋巴癌或肿瘤，不管它是什么，一样攻，对证不对病。  \n\n        为什么张仲景分这两味药？进入大陷胸汤都是很危险的，要很快的把它攻掉，如果不敢，开成小陷胸力量不够，结果看着病人坐在那里死掉，如果是小陷胸汤，开成大陷胸汤就太过了，病人元气大伤，甘遂一吃下去马上成皮包骨，水分都没了，病人大燥渴，吃一钱甘遂，要吃十斤石膏还有人参，津液才补得回来，张锡驹曰：汤有大小之别，证有轻重之殊，今人多以小陷胸汤治大结胸证，皆致不救，遂谓结胸为不可治之证。不知结胸之不可治，只有二节，大结胸有两种不可治，就是表邪过盛的时候，如果脉很浮大，如果病人烦燥，就是病人津液已经伤到了，看到这个症状可能里面是胃癌、胃长肿瘤、淋巴肿瘤，中医讲痰在里面。痰已经变成硬块，西医看是肿瘤，遇到这种情形，为什么病人如果烦燥而死，因为病人已经没有条件可以攻了，已经壮热了，吃药也是死，不吃药也是死，遇到这种情形，宁可吃药死，也不要不吃药等死，刚开始还没有到烦燥的阶段就要下手了，不能等到烦燥危症出现才用。  \n', NULL, '小陷胸汤', NULL, NULL, NULL, '152、小结胸病，正在心下，按之则痛，脉浮滑者，$f{小陷胸汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616147899248713, 'E376C1C92F7E01AB7CFC4E0315CCE794', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:32:15', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5365, 319, 904000623, '       实代表有物，有东西在里面，实分成寒热，热的症状很简单，病人会渴会烦燥，脉会数，舌苔会很黄；如果是寒也是有东西在里面，这时候不能开大小陷胸汤，因为陷胸汤是对热实结胸，陷胸汤里面都是比较寒凉的药，如果寒实再用陷胸汤，寒会实得更紧，这时候要靠三物小白散；为什么叫三物小白散?就是说用的剂量很少，一点点而已。  \n\n      巴豆在中药里面是很毒的药，有人吃巴豆吃得肝肠寸断，肠子都断掉了，所以要小心用，对证就没关系，一般来说，如果病人被西医处理过，就尽量不用巴豆，因为诊断上容易有盲  \n点；桔梗用三分，张仲景前面的剂量用两，在这里用分，巴豆用一分或两颗就够了，巴豆像黑豆、豆豉大小，外面还有一层壳，吃的时候还要把壳拿掉，巴豆仁两片剥开，心要去掉，放在热锅上面，一烧就焦了就变成黑豆，很油，放在砵上一磨就变成巴豆霜，桔梗、贝母等 量，中药里面的桔梗用在两个地方，一是排脓，一是去寒痰，所以桔梗甘草汤又名排脓汤，因为桔梗去痰的力量很强；贝母也是攻坚去痰降逆的药，贝母可以通利喉结，不管是甲状腺肿瘤、鼻咽癌、淋巴腺肿瘤、扁桃腺肿瘤，只要是喉咙这一段有硬块，只有两味药在用，就是桔梗和连翘，连翘又名连壳，桔梗、连翘等量，还有巴豆。  \n\n       为什么叫寒实结胸?为什么用这么强的药?有一个人阳明热很渴，先喝很多冰的东西，吃完后肚子饿了，又吃了很多不消化的东西，就堵到了，堵到后，口还是渴，又喝水，水一喝就把肠里面的东西往下走，就堵到大肠里去了，然后中间空出来了，又饿了又吃，吃了又堵到了，结果从食道到大肠满满的都是食物，这就是寒实结胸，病人的症状是昏迷的，他呼吸很均匀很正常，气息很微弱，西医找不到原因，其实是吃撑到了，这时候要问他的亲人他昨晚吃了什么东西?确定是肠胃堵到了，再看舌头，舌苔是白的，因为肠胃都不蠕动了。因为食物太多了，蠕动的力量都没有了，这时候要靠三物小白散，这巴豆很热，巴豆一吃下去，从食道到大肠一路清出来，出来的东西还有排列顺序，如果临床上病人没办法吃下去的话，可以从鼻子喷进去。  \n\n经方里面最重的药是巴豆，张仲景只用在这几个地方（巴豆都是磨成粉在用的）：  \n\n（一）巴豆、桔梗等量同用，巴豆一颗或两颗，专门使毒化成脓，有的时候身体里面的结毒、硬块、痞块在身体里面很深的地方，发不出来，要让它化成脓排出来：例如肺中的脓疡属寒实者。  \n\n（二）巴豆和贝母同用，专门去喉咙、咽喉之堵塞，癌症到末期的时候，东西都没有办法吞下去，这通关利结的力量很强。  \n\n轻症用半夏苦酒汤、严重的用硝石，或用经方中的巴豆和贝母。但是如果是西医开刀或化疗过的病人，再肿起来的，用了就效果不好。  \n\n（三）巴豆、杏仁同用，叫走马汤，也是用在心胸的结毒，有的时候癌症到末期，梗在肺的地方，食道里面都长满癌，东西吞不下去了，巴豆和杏仁同用的时候是生用，后面介绍泻心汤的时候再说明生用的功能，把巴豆和杏仁磨碎，巴豆二粒和杏仁五六粒，杏仁可以多一点，用棉布包起来，用热水泡着，一拧汁就出来了，这汁就可以了，食道癌、胃癌到后期无法吞东西，巴豆杏仁一下去，堵到的癌细胞都可以被打开一条通道。  \n\n（四）巴豆和大黄、干姜并用，专门用在下腹结痛，目前用在大肠癌的就是这味方剂，大肠癌到后期都不大便，癌细胞长满了，西医可能做个人工肛门，巴豆下去可以打个洞，用这药要有必死的决心，这是很危险的时候用。  \n\n（五)巴豆和炮附子、吴茱萸同用，专门治心胸寒痛，胃里面冰凉的，病人的陈述说胃里面有冰块在里面，可是摸他的皮肤是烫的，检查胃的形状又很好，胃里面被寒气、白津液塞得满满的，没有办法吃东西，也不口渴，因为白津在里面。  \n\n（六）巴豆与芫花同用，能去大腹积水与痞块积聚。两颗巴豆与配上l/3 钱芫花做成药丸。  \n\n用到巴豆，必须病人没有被西医处理过，而且病人家属相信中医；否则如果救不回来，病人家属忘了重病难治，会以为是病人是吃药死的。  \n\n陷胸汤万不可服，以寒实结胸，为寒饮凝痰，结于胸中，如与黄连、半夏、栝蒌之三物苦寒剂，益使其坚凝不得化也。白散为巴豆，桔梗、贝母，药为三味而色白，所服极少，称之为三物小白散亦合。  \n\n本条之脉证、舌证：脉当沉微或沉迟，舌当白滑。张仲景说过舌白滑病极难治，就是脏结。  \n\n 巴豆黄连膏灸（倪氏）  \n\n巴豆十四个 黄连七寸去皮用  \n\n右捣细，津唾成膏，填入脐中，以艾火灸其上，腹中有声，其病去矣。不拘壮数，病去为度。也就是将巴豆和黄连作成饼放在肚脐上面灸，也可以去掉，但是力量没有吞服的强。 \n', NULL, '三物小白散', NULL, NULL, NULL, '156、寒实结胸，无热证者，与$f{三物小白散}，陷胸汤不可服。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616150647877702, '31484779313E9B7B6497BB5EC218D83E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:43:26', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5366, 319, 904000624, '        太阳与少阳并病，张仲景只有这一条不能用小柴胡汤，照理说太阳与少阳并病，小柴胡汤就好了，如果病人头项强痛，太阳病证有了，或眩冒，头昏，时如结胸，并不是真正的结胸，看起来好像结胸，胃里面很难过，心下痞鞕者，胃里面硬硬的，看起来是，这里为什么是小柴胡汤的禁忌?这病人在没有得病的时候，本来他胃的津液就是虚的，胃肠津液虚掉的人，平常喝水喝的很多，喝多了又不能止渴，一直在喝的人，就是胃肠津液本来就不够的人，前面讲的就是胃的津液虚，所以如果开小柴胡汤和解的方子，小柴胡汤大剂下去，病人也会流汗的，遇到这种情形的时候，先刺大椎第一间，泄太阳的热，大椎穴放血，三阳会在大椎，所以大椎穴放血的时候，太阳的热会退掉，为什么扎肺腧？头项强痛，因为肺气无法出，表热不能散，这时候胸阳的热往上冲，造成头痛，扎肺俞让他能解表；为什么扎肝俞？因肝肿起来；平常为什么胃的津液不足要去补足它?因为津液如果不足，血里面会太热，血里面的水不够，这时候肝会肿起来，因为肝是最后的血脏，血藏在肝里面，心生血、肝藏血，其实是肝肿起来了，不是小柴胡汤证，肝肿起来顶到胃了，所以胃的地方会硬，这时候扎肝俞，让血里面的热出来，肝里面的血会出来，所以他不是真正的少阳证，病人津液伤到的时候，可以看的到，所以给病人发汗剂的时候，要先看病人的嘴唇，嘴唇干，就不可以给发汗，发  \n汗则谵语，为什么一发汗会谵语?一般来说，病人壮热的时候，脑神经就不是很正常，会胡言乱语，脉弦，五六日谵语不止，当刺期门，就是肝肿起来了。  \n\n       例：有个病人，整个嘴都干裂掉了，脸上冒青春痘，开炮附子三钱，生附一个，干姜三钱，三帖，这个病人平常喝水都不能止渴，因为是虚热，这么热的药下去后就不渴了，这个病人的舌苔是白滑，所以是脏结药下去后，会大下，湿从大便排出来了。  ', NULL, NULL, NULL, NULL, NULL, '157、太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗。发汗则谵语，脉弦，五六日谵语不止，当刺期门。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616154418643014, '458FC04597C14B8D413C314C0E09ECC3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:58:47', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5367, 319, 904000625, '      妇人，专讲女人，中风，发热恶寒，就是有了表证了，得之八九日，刚好得了七八天以后，还没好的时候，月经来了，经水适来，热除而脉迟身凉，为什么?平常胃里面吸收营养造成的血，抵抗力在血中，一旦受了表邪，抵抗力会到皮表上去相抗，相抗的时候，正值月经来了，血往下走，热也跟一起着下来了，这邪热跟着一起进入了子宫，肝脏，这血室二字到现在吵，有的人说是子宫，有点人说是肝脏，其实两者都是血室，张仲景并没有区分，胸胁下满，因为淋巴系统是三焦，子宫算下焦，胸胁算中焦，如结胸状，看起来像结胸，谵语者，如果有谵语，代表病人血不够了，此为热入血室也，子宫里面发炎，或肝炎，当刺期门，随其实而泻之，期门可以泄肝热的，张仲景只知道这穴道。  \n\n       血室，指肝脏，肝脏腔门静脉总会之所，其血最多，其热最高，故曰血室。吴氏《瘟疫论》曰：血室一名血海，即冲任之脉也。方书指为子宫者，以其谵语适在经行或经止之时，随指子宫即血室。  ', NULL, NULL, NULL, NULL, NULL, '158、妇人中风，发热恶寒，得之八九日，经水迟来，热除而脉迟身凉，胸胁下满。如结胸状，谵语者，此为热入血室也，当刺期门，随其实而泻之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616154981417030, 'AB6F278F992A89C3984FF6C87228FDC5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 12:01:04', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5368, 319, 904000628, '      感冒六七日以后，病人发热微恶寒，代表还有表证，支节烦疼，关节疼痛，心下支结，胃里面梗到的感觉，吃不下东西，外证未去者，柴胡桂枝汤主之。一但有少阳证的时候，就不用麻黄了，所以经方中看不到柴胡麻黄汤。  \n\n        阳经有三，一太阳，一少阳，一阳明，只有在少阳这一圈的时候，就是半表半里，太阳就是表，阳明就是里，太阳少阳重迭的地方就是外，就是有太阳表证，也有少阳表证，这时候如果用小柴胡汤去和解，和解不掉，要用柴胡桂枝汤，有少阳证也有太阳证，最主要是少阳证比较重一点，太阳证比较轻一点，所以柴胡用四钱、桂枝、黄芩、人参各一钱半，重用柴胡，再加甘草、半夏、芍药、大枣、生姜，刚好是柴胡汤和桂枝汤的并在一起，大枣、生姜重复。  ', NULL, '柴胡桂枝汤', NULL, NULL, NULL, '161、伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，$f{柴胡桂枝汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616182324662342, 'D2B089501995E6D9515EF10BECFD8B06', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 13:52:20', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5369, 319, 904000627, '       妇人伤寒发热，感冒，麻黄汤证，来不及吃，月经来了，到晚上就发谵语，因为病毒在血里面，昼日明了，暮则谵语，如见鬼状者。白天的时候血结在阴，晚上的时候血结在阳，所以病人白天很好，代表气没有问题，晚上的时候病人胡言乱语，代表病在血里；平常没有来月经的时候，得到感冒，麻黄汤、葛根汤就好了，不会有谵语，无犯胃气及上下焦，必自愈，如果不治疗，她也会自己好，用小柴胡汤好得快一点而已，这三条专讲女人，因为男人没有月经，男人的月经在胡子上表现。  ', NULL, NULL, NULL, NULL, NULL, '160、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，无犯胃气及上下焦，必自愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616182324662343, '13201645D42BBAACAEA786A855412832', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 13:52:20', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5370, 319, 904000626, '       扎了期门，后面就是小柴胡汤证，前一条得了感冒以后，中间来了月经，这条是妇人得了感冒，本来已经好了，刚好月经停的时候，那天又得了感冒这也是热入血室，其血必结，血液循环就不是很好，包括肝脏的循环不是很好。滤过性病毒跑进去了，如果这血结在那边，一定带有很多病毒，堵到了，肝里面有很多血管，要把血输出来，通利的时候病人就发热，不通的时侯，就是出不来的时候病人就发冷状，所以看起来有往来寒热的现象，故使如疟状，发作有时，小柴胡汤主之，所以不管是感冒以后月经来了，或是刚好月经断的时候，得到感冒，都是用小柴胡汤来解。如果开发表的药，可能月经会停掉，因为汗血同源，发汗血就少了，于是月经就停了，也有可能造成逆经，经血从鼻孔来了。  ', NULL, '小柴胡汤', NULL, NULL, NULL, '159、妇人中风，七八日，续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，发作有时，$f{小柴胡汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616182324662344, '81205CB8CE77176A681031E8F9725279', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 13:52:20', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5371, 319, 904000629, '        如果病人发汗而复下之就不会结胸了，就是没有发汗攻下才会结胸，现在发汗复下之就代表里面虚掉了，因为攻下的药一定是寒凉的药。攻下的时候血液往下走，肠胃就虚冷掉了，胸胁满，汗发掉以后，很多还没有发出去的汗，因为攻下复又回头，结在胸膈的地方，这汗不在胃里面，如果在胃里面一下子就发散掉了、这汗在胃的外面，停在胸膈这儿，所以胸胁满。微结，就是一点点结，如果没发汗攻下会大结，小便不利，因为攻下水跑掉了，发汗水也跑掉了，当然会小便不利，渴而不呕，嘴巴很口渴，但是人不会恶心，但头汗出，往来寒热，胃在中间，如果胃里面没有水，病人会口渴，如果胃里面有水，不但不渴还会呕吐，胃里面没有水，胃热往上冲，头就一直冒汗，但头汗出。水一直往上跑，其实这水就是胃里面的津液，常人如果饿过头，手脚一直发抖，头会开始冒冷汗，西医说血糖太低了，心烦者，此为未解也，柴胡桂枝干姜汤主之，胸胁满，往来寒热，就是半表半里所以用柴胡，发汗而复下之，还有伤寒脉证，所以要用桂枝，还有加上甘草这几味能温中达表，这就是前面柴胡桂枝汤的意思，能让中焦温起来，让抵抗力到表面上去，把还没有进来的滤过性病毒就排掉了；因为发汗又下利的状况下，滤过性病毒没有随发汗发掉，又顺着汗液回来，所以滤过性病毒是散的，不是集中在表上面，而是停在三焦散开来的，如果这病毒只在肌肉皮肤表面上用桂枝就够了，但是因为滤过性病毒已经进入三焦淋巴系统，所以要用柴胡把它推出来，再用桂枝把它透发了，因为胃的津液已经没了，所以要用甘草补足胃的津液。渴，张仲景在治渴的时候，喜欢用栝蒌根，栝蒌根能去热止渴，病人只要有渴就可以加栝蒌根，可以把肺的津液补足，不渴的话用半夏，决定用半夏就要问病人渴不渴，渴就不要用半夏，不渴就可以用半夏。胃虚热无大渴往上冲用黄芩，而不是用石膏，石膏是实热证，病人会大渴饮多。但头汗出，牡蛎专门降浮阳，胃的阳气浮在头上面，就像热气球浮在上面降不下来，牡蛎一下去把它整个往下导。  ', NULL, '柴胡桂枝干姜汤', NULL, NULL, NULL, '162、伤寒五六日，已发汗而复下之。胸胁满，微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，$f{柴胡桂枝干姜汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616188952793158, '449E8221E7625B68504713167510D740', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 14:19:18', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5372, 319, 904000633, '       浮就是病在表，紧就是寒，就是表有寒，按伤寒的法则，应该是先发表再攻里，结果先攻下，造成病反而入里，痞证就出现了，有表证的时候要发汗，开桂枝汤、葛根汤下去的时候，会出表汗，这汗是从肠胃的津液来的，所以肠胃的津液是汗的源头，肠胃的津液应该是走皮肤出来，结果反攻里的话，肠胃的津液就往下走了，往下走的时候，本应在表的免疫系统就跑进肠胃里面来，所以肠胃里面的津液，可以从肠胃达到表，表的津液也可以顺着同样的管道进入肠胃；肠胃科的病人一定要特别注意，为什么要按之自濡，连张仲景都要去按他，就是要你作腹诊，就是要确定一下，肚子有没有长了硬块在里面?如果有硬块可能是硬大便，如果压下去软绵绵的，代表里面没有堵到东西，按之自濡，但气痞耳，只是气堵到了，为什么?因为胃里面有热度有动能，热气应该是往上走的，走到头上，走到四肢表面的，结果被攻下的时候，热就往下走，堵塞在下面，所以这气体是热气，所有肠胃科的病，后面所介绍的泻心汤，大多是寒热并见，寒热胶结的情形。  \n\n       人体内从胃一直摸到十二指肠、小肠、大肠，胃的下方就是胰脏，中医叫做膵肉，旁边是脾脏，中间有脾之大络（大血管），脾脏有血管通到胃的下方，胃的蠕动就是靠下面的血管充血帮忙它蠕动的，中脘穴正好在胃的上方，肚脐的两边就是天枢，刚好就是在大肠的两个上头，小肠的正中心就是关元穴，如果按下去胃里面软绵绵的就是没有东西堵到。  ', NULL, NULL, NULL, NULL, NULL, '166、脉浮而紧，而复下之，病反入里，则作痞，按之则自濡，但气痞耳。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616200207601734, 'BAD30720ECF5E20E008D1907CC012734', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:05:06', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5373, 319, 904000632, '       照理说太阳少阳并病，应该是小柴胡汤，或外证比较多的话，柴胡桂枝汤也可以，而反下之，成结胸，心下硬，下利不止，水浆不下，其人心烦，这状况就不好了，是一种预兆，所谓的结胸，代表的是实结，有东西堵到了，结胸的时候硬梆梆的兼有阳明里实，根本没有大便了，整个梗到了，这好治，大便一下去就好了，现在结胸又下利不止，知道肠胃津液不够，又水喝不下去，又一直在下利，大陷胸汤就不能用了，那什么结到?胃癌或者胰脏癌，整个里面长东西堵到了，其人心烦，烦，代表病人虚的时候会烦，这就比较危险。胰脏癌的处方在厥阴篇的干姜黄连黄芩人参汤会说明。  \n\n        临证时我们按照经方来开，用葛根来生水，葛芩连汤治疗下利、协热利的时侯，就是用葛根来生水的。水结在中膈的地方，所以用柴胡来通利三焦，就能进入淋巴系统里面，有长东西、长瘤的时候，柴胡是很好的攻坚引药，能通利淋巴系统的药。因为病人有呕吐，所以加半夏；肠胃的津液伤到了，所以加甘草，把肠胃的津液补回去；心烦、胃口都没有了，用白朮、茯苓来开他的脾胃；因为久下利，肠的津液伤到了，所以加人参、大枣；如果胃里面是寒的用干姜，如果胃里面是热的用生姜，这两者可交换一下，临证决定\n\n胃癌专论：\n治胃癌汤方 \n       葛根     柴胡     半夏    甘草     白朮    茯苓  人参    大枣   干姜    生姜     加上金匮中的黄土汤加减就可以治胃癌 \n\n        这处方下去的时候，如果要加减，葛根重用至六钱，再来是柴胡五钱，半夏三钱，甘草二钱，白朮、茯苓等量五钱，家里钱多的人参就用多一点。如果下利得很厉害。红枣用十枚都没关系，干姜、生姜视状况各两钱。  \n\n     这是很好治疗胃癌的方子，因为病人现在已经不能攻了，所以等胃口开了，饮食正常的时候，再开一些攻坚的药。  \n\n     如果这方子下去，病人还是水浆不得下，还在下利的话，就差不多了，吐和下利出来的都是药味，他已经到了药不收受了，全部排掉了，很危险。  \n\n   《类聚方广义》本方条曰：疝瘕，积浆，痛侵心胸，心下痞鞕，恶心呕吐，肠鸣下利，皆治之。若大便秘者，兼用消块丸或陷胸丸。（消块丸即硝石丸之别名，《千金方》：硝石六 两，大黄八两，人参、甘草，各三两。）硝石用芒硝，破坚的力量很强，如果没有加人参、甘草，光用芒硝，药一下就跑到大肠里头去了，用甘草来顶在中焦，用芒硝去破癌细胞，让痞块消掉，像附子也是很好攻坚的药，现在学过的牡蛎也是攻坚的药。  ', NULL, NULL, NULL, NULL, NULL, '165、太阳少阳并病，而反下之，成结胸，心下硬，下利不止，水浆不下，其人心烦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616200207601735, '27B6926BFB389FD12586F509C0026320', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:05:06', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5374, 319, 904000631, '     呕就是进入少阳了，用小柴胡汤来解，\n\n     而以他药下之，柴胡汤证看错了被攻下，\n\n     柴胡证仍在者，复与柴胡汤，攻下之后，如果还是柴胡汤证，就再给柴胡汤，\n\n    此虽已下之，不为逆，下并没有把内脏功能下坏掉，\n\n   必蒸蒸而振，却发热汗出而解，柴胡汤下去脾胃功能马上恢复，脾胃功能恢复一定会流汗，流出来的汗是本身正常的汗，这汗本来在太阳应该要解掉，结果在太阳没有解掉进入少阳了， \n   \n   进入少阳后用柴胡汤来去，排出来的汗是原来太阳证的汗，\n\n   若心下满而硬痛者，此为结胸也，硬痛往下走是大陷胸汤，硬痛往上走的是大陷胸丸。不单单是麻黄汤证、桂枝汤证、葛根汤证被攻下会结胸，柴胡汤证被攻下也会结胸。\n\n   但满而不痛者，此为痞，张仲景讲的痞是一种症状：现在进入五个泻心汤证。会用这五个泻心汤，所有肠胃 科的病就都会看了，\n\n   满而不痛，常常感觉胃里面胀胀的，又不会痛，可是胃又有胀胀闷闷的感觉，这原因就是表证没有好，进入到胃里面，只有水停在胃的周围，胃的周围并没有热，也没有湿，柴胡不中与也，宜半夏泻心汤，如果只是水而已，半夏就可以了，但是病人常常有吃食物下去，因为肠胃的蠕动不好，有水饮，食物堵在里面，有一部分的食物被吸收了，有一部分的食物坏掉了，所以半夏泻心汤是张仲景设计的第一个肠胃科的药。', NULL, '大陷胸汤.半夏泻心汤', NULL, NULL, NULL, '164、伤寒五六日，呕而发热者，柴胡汤证具，而以他药下之，柴胡证仍在者，复与柴胡汤，此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解；若心下满而硬痛者，此为结胸也，$f{大陷胸汤}主之；但满而不痛者，此为痞，柴胡不中与也，宜$f{半夏泻心汤}。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616200207601736, '8B20BC62648714063D690F4330A2BDFA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:05:06', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5375, 319, 904000630, '       头汗出，微恶寒，这两个就是有表证，手足冷，心下满，就是病邪内里了，就是表有邪里面也有邪，口不欲食，吃东西吃不下去，就是里面虚掉了，大便硬，大便为什么硬?就是蠕动量不够了，大便自己流出来，大肠是一节一节的，所以正常的大便是一段一段的，不会出成一条状，此为阳微结。什么叫阳结到了？人的身体，阴寒在内，阳浮在外，消化系统，因为有寒结在内，所以蠕动就减缓了，这特候胃里面还有一点余热，这胃的余热会往上冲，冲到头上去了，热会出来第一个就是到头。所以人流汗第一个就是头，手脚还没流汗之前，头就会先流汗。我们手脚的温度都是从胃热来的，脾主四肢，因为里面冷掉了，所以手足冷，所以微热在上面，里面整个是阴寒掉了。心下满，口不欲食，里面胀满闷闷的、肠胃都没有蠕动了，肠胃没有蠕动就不想吃东西，必有表复有里也，有伤寒表证也有里寒证。脉沉细，病在里也，如果摸到脉沉细就是病在里，这条辨就是为后面要介绍的铺路，有汗必为阳，阴证无汗，后面要介绍的少阴、太阴、厥阴都是没有汗的，就好像阳明证都是但热不寒，看不到寒证是纯热证，到了阴证完全没有汗，所以头还有汗就是阳还，病就很好治，最怕是没有汗，没有汗并不是伤寒表证的无汗，而是根本津液都没有了，病进入阴证，就是太阴、少阴、厥阴，阴证就是在讲脏了。所以头汗出，病在表也，代表阳微结；如果纯阴结，必无汗，完全没有汗的，一般来说摸到病人的脉，如果是很微细的时候，就是少阴证，少阴病的脉很细很弱，阳明、少阳、太阳的脉很洪大，麻黄汤证的无汗脉是很洪大的，所以这一条辨就是说在太阳证也可以看到脉微细，脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴。遇到这种危急的时候，里面阴寒很盛的话，照理说可以开少阴证的药，像麻黄 附子细辛汤，少阴证的主证就是脉微细，要确定是少阴证就是无汗，有汗小柴胡汤就好了，所以整个条辨讲的就是阴证没有表汗，阳证才会有汗。', NULL, '小柴胡汤', NULL, NULL, NULL, '163、伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉沉细者，此为阳微结，必有表复有里也，脉沉细，病在里也；头汗出，病在表也，假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也；脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴；可与$f{小柴胡汤}，设不了了者，得屎而解。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616200207601737, '491FC4886E05F03E2679521CBE5FFE16', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:05:06', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5376, 319, 904000634, '       如果太阳中风，感冒了，同时有下利有呕吐，太阳中风下利是葛根汤，有呕吐就葛根加半夏，如果表解者，乃可攻之：要先解表再攻里。攻他的时候，结果病人其人漐漐汗出，发汗有时，头痛，心下痞鞕满，引胁下痛，呕即短气，汗出不恶寒者，当解了表以后有这种现 象，这种现象平常看到的时候，一定是湿气很重的人、还有肠胃功能很差的人。为什么会严重到用十枣汤?平常解表的时候，一定是开发汗剂，这汗一发以后，滤过性病毒和不要的水离开体表以后，好的水分还会顺着三焦淋巴系统回到胃里面来，津液会自行返回胃里面，如果津液没有回到胃里面，病人会燥渴，小便就没有了，这时候就是五苓散证。现在这种情形是水回来了，居然并没有回到胃里面，回到肺里面，因为肺主皮毛，为什么回到肺里面？因为土挡到了，脾土太旺，脾伤到了，脾就胀起来，这表水一发出去以后，没有办法回到肠胃里面，就慢慢渗到横膈上去；如果水不多，就头眩就是苓桂朮甘汤证；如果渗得更多，愈来愈严重，就是用十枣汤。  \n\n       还有一种现象就是这病人本来是麻黄汤证表寒，结果没有开麻黄汤，如果病人抵抗力很强，自己会好，有的病人不会好，这时候麻黄汤证转成里寒了，变成小青龙汤证，里面发炎了，没有用麻黄汤发表，里面的免疫系统出来相抗，滤过性病毒往里面走，走到肺里面化热了，病人一直咳嗽，咳嗽的同时，表面有寒里面有痰，这痰就是水，就是表面的滤过性病毒顺着水道系统到肺里面来的，应该是小青龙汤一剂就去掉的，因为小青龙汤是心下有水气，结果又没开小青龙汤，这水就慢慢堆积起来，造成十枣汤证。  \n\n       十枣汤中医叫朱雀汤，是伤寒论里面，目前最峻最强的排水攻水的药，如果这水在皮肤表面上用越婢汤，肠里面的水是表水汗水回头的，水正常应该进入肠胃，结果不入肠胃入肺了，所以整个胸膛里面全部都是水，还有一些水渗到脏和腑中间的间膈膜上，就是三焦网膜。所以脏没有积水，可是脏和腑中间的三焦网络全部充水，病人会心下痞鞕满，胃里面胀满的很难过硬硬的，引胁下痛，整个胁肋都积了水，两胁下很痛，呕即短气，恶心想吐，吐又吐 不出来，因为水不在胃里面，为什么短气?横膈膜都充水了，像海绵一样，吸气又不能下降被顶着，呼气就吐出来，自然气就很短，汗不出恶寒者，代表他还有流汗没有恶寒，就是没有表证了，所以在喝十枣汤之前一定要确定他没有表证，所以肺里面积水，心脏积水，肝积水，肝硬化末期的腹水，十枣汤都可以用的。  \n\n       临床上要注意一点，这里的汗出，病人阳气虚脱的时候，会流出油油的汗，这个时候就不能用十枣汤了。  ', NULL, '十枣汤', NULL, NULL, NULL, '167、太阳中风，下利，呕逆，表解者，乃可攻之。其人漐漐汗出，发作有时，头痛，心下痞鞕满，引胁下痛，呕即短气，汗出不恶寒者，此表解里未和 也，$f{十枣汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616206611370054, 'C92460E62BA24F954B069E666E13F989', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:31:09', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5377, 319, 904000637, '      心下痞，就是胃里面难过，就是肠胃科的问题，恶寒，就是怕冷，汗出就是表虚掉了；本身肠胃发炎，结果表又虚掉了，痞证要先解表再去攻里，这时候寒热药要并用，心下痞的部分，用大黄、黄连、黄芩，恶寒、汗出要用固表去寒，这时候用炮附子，附子的性善守。所以用附子泻心汤。病人盗汗不止的时候，用附子一下去，汗马上就止掉了。失血很多的时候，可以用炮附子来固阳；遗精频尿也可以用炮附子来配合龙骨、牡蛎。  ', NULL, '附子泻心汤', NULL, NULL, NULL, '170、心下痞，而复恶寒，汗出者，$f{附子泻心汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616213650055238, 'B42D1545110FDFE8325AA29A59CC7E08', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:59:48', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5378, 319, 904000636, NULL, NULL, '大黄黄连泻心汤', NULL, NULL, NULL, '169、心下痞，按之濡，其脉关上浮者，$f{大黄黄连泻心汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616213650055239, 'B326713F8B43DE60CD1B8E77639688F5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:59:48', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5379, 319, 904000635, '      太阳病，发热恶寒，医生给他发汗就好了，无阳而阴独，结果发汗发多了病人的阳气都没了，胃里面的津液都没了，血里面的津液都没了，完全剩下阴了，因复下之，又攻下，遂心下痞，造成心下痞了，表里俱虚，阴阳气并竭，表被发汗发掉了，里又被攻下，所以阴阳都消掉了，复加烧针，再加上烧针，结果病人胸烦，面色青黄，讲青色的时候已经是果了，中医看到青色的时候，就知道他血凝到了，血停止下来了，也就是血缺氧了，临床上看到冻死的人是发青的，还有心脏休克、人缺氧的也是，所以看到病人面色发青，基本上病人的感觉是痛，且血液循环停止下来了，才会青色的，如果看到黄色的，黄色是湿聚，就是湿聚在一起太盛的时候，病人显现在面上的是黄色，象小孩子的脸上，山根一带有青的一块，这是腹部，所以小孩的血凝在小肠里面，这时候要用小建中汤重用芍药，小建中汤是桂枝汤里面芍药加倍再加饴糖，小建中汤进入肠胃把静脉血打出来，所以小建中汤下去以后，胃口大开；另外嘴唇上有一点一点的白点，就是肚子里面有虫；为什么肤润者，因为阳脱而油脂往外走，难治，今色微黄，手足温者，因为脾主四肢主肌肉，如果手脚还有温度，代表胃气并没有丧失掉，只要病人的胃气没有丧失掉，在张仲景的理论都是可以治的，一直到胃气没了再好的药都不收的时候才放弃。  ', NULL, NULL, NULL, NULL, NULL, '168、太阳病，发热恶寒，医发汗，无阳而阴独，因复下之，遂心下痞，表里俱虚，阴阳气并竭，复加烧针，因胸烦，面色青黄，肤润者，难治，今色微黄，手足温者，易愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616213650055240, '531533F72D9D2BB52D2760A044A20A37', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:59:48', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5380, 319, 904000640, '       伤寒，本来应该发表，结果下之，造成谷不化，就是吃进什么就拉什么，完全不消化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，这时候医生看到心下痞，以为是里面还有堵到宿食，就再攻，造成越痞了，变成大痞子了，这时候肠里面已经没有东西了，并不是热结，但是胃中虚，客气上结，故使鞕也，甘草泻心汤主之。\n\n      临床上，甘草泻心汤常常用在急性的肠胃炎，甘草是解毒的。为什么不用半夏泻心汤或生姜泻心汤?因为有的食物还有用，把它通通排掉，身体会虚掉，这甘草下去，除了缓和肠胃的蠕动以外，最重要的，甘草还可以把药停在肠胃里面，让它停久一点，坏的食物把它分解排掉，好的食物把它留下来。甘草泻心汤也会有噫气恶心，但是没有食臭，闻不到臭味，所以甘草泻心汤是胃气虚掉了，没有东西在里面，所以只听到噫气打咯但是没有闻到臭味，生姜泻心汤有闻到臭味还有拉肚子，这是两者区分的地方，半夏泻心汤比较好区分，有呕就是半夏泻心汤。  ', NULL, '甘草泻心汤', NULL, NULL, NULL, '173、伤寒、中风，医反下之，其人下利，日数十行，谷不化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，谓病不尽，复下之，其痞益甚，此非热结，但以胃中虚，客气上结，故使鞕也，$f{甘草泻心汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616226487210054, '9CD414AFD69A85969975BDD80484B072', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 16:52:02', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5381, 319, 904000639, '       伤寒，发表之后结果胃不和，所以肠胃科的病常常发生在，开发表的药给病人的时候，病人会好就好了，或发生肠胃科的问题，就是表证好了，结果胃不舒服，引出了其它肠胃的病；伤寒论里面讲的胃就是肠，心下就是胃；心下痞鞕，就是气结在胃里面，胃里面胀胀的堵到了很难过，干噫食臭，常常噫气出来，嘴巴里面很臭，就是里面有宿食，胁下有水气，腹中雷鸣，下利者，平常不会有这种现象，只有肠胃有问题的才会有，一般来说情形是，发表了以后开了麻黄汤或桂枝汤或葛根汤，把肠胃的津液发到表面上来，结果水回来的时候，它没有回到胃里面因为胃里面有脏东西堵到了，水直接渗到肠子里面去，水不应该渗到小肠的，因为小肠是火。水火不容，小肠一渗到水的时候，火就没有了，这水就从小肠直接进入大肠，就听到咕噜噜的水在里面响，就下利了，在这种情形就是，生姜泻心汤。伤寒论里面，从172条开始，治疗下利最好的方子就是生姜泻心汤，最常用到下利的方子就是生姜泻心汤，肠鸣下利，肚子里面都是水就是标准的生姜泻心汤证。  ', NULL, '生姜泻心汤', NULL, NULL, NULL, '172、伤寒，汗出，解之后，胃中不和，心下痞鞕，干噫食臭，胁下有水气，腹中雷鸣，下利者，$f{生姜泻心汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616226487210055, '12669692652B924715ECA453E9B85424', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 16:52:02', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5382, 319, 904000638, '      有表证反被攻下，造成心下痞，给泻心汤，这条辨是说，不是痞不能解，而是他本身有水饮停蓄在下焦，泻心汤下去，不是泻心汤不解，而是他有水饮所以没解掉，这时候用五苓散把水排掉，所以五苓散证一定是病人有口渴、烦躁、小便不利，水停在下方不利，表水又回不到胃里面，停在表面上，所以造成口渴、小便不利；如果口渴、小便不利，先检查有没有肾结石或膀胱结石，都没有再问口渴不渴?有，就是五苓散证，五苓散也是消水肿的药，病人没有口渴，代表病人的肠胃津液很足。  ', NULL, '五苓散', NULL, NULL, NULL, '171、表以下之，故心下痞，与泻心汤。痞不解，其人口中渴，而烦躁，小便不利者，$f{五苓散}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616226487210056, '68A74A9FBCD33B6A999DC3B55A3F46DD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 16:52:02', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5383, 319, 904000643, '一个人伤寒，发汗，若吐，若下，只有心下痞鞕，噫气，没有其它症状，单纯的噫气。  ', NULL, '旋覆代赭石汤', NULL, NULL, NULL, '176、伤寒，发汗，若吐，若下，解后心下痞鞕，噫气不除者，$f{旋覆代赭石汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616231762563142, '924B10A0FA20419A55AA2D0C081FD4C3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:13:30', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5384, 319, 904000642, '       伤寒八九日后，病人有吐下，吐很多以后肠胃里面的食物没了，所以吐多了以后，血会伤到，因为没有了食物营养，血的源头没了，病人会虚烦，所以产生虚烦是因为心主血，血不够了，胃里面空掉了，胃里面的津液也不够了，结果病人心下痞鞕，病人感觉胃里面硬硬的，如果压到胃里面有硬块，就是有宿食，如果压起来软绵绵的，就是里面没有东西，胃壁粘起来了，胁下痛，气上冲咽喉，因为吐下伤到了，胃气本来应该下降的，就是食物进入胃，胃磨碎再进入小肠再到大肠，食物是往下走的，就是胃蠕动力是往下走的，因为吐很多了，胃气往上走了，胃里面又没有东西，胃气就往上冲到咽喉，病人就感觉到一直有一股气往上冲，冲到咽喉，病人眩冒头昏，因为血不够了缺血，如果在这种状况再发汗的话，血里面的水更少更伤，血里面的水一旦量不足的时候，病人会有高热的现象，结果脉微了，病人经脉动惕，因为血不足了，不足以养筋，久而成痿，小儿麻痹就是这样来的，很多初期都是发烧感冒处理不好，《内经》：诸痿取阳明，所有痿证、肌肉痿缩、痿靡无力、小儿麻痹的起源在这里，要独取阳明。  ', NULL, NULL, NULL, NULL, NULL, '175、伤寒八九日，吐下后，虚烦，心下痞鞕，胁下痛，气上冲咽喉，眩冒，复发汗，脉甚微，经脉动惕者，久而成痿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616231762563143, '80C8CE19169861EC67F06F0E6AF506BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:13:30', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5385, 319, 904000641, '         伤寒了，如果服了汤药，造成胃里面胀胀的，下利不停，服泻心汤好了，好了以后，医生认为里面可能又堵到了，再用其它药攻下，结果又下利不止，医生用理中汤，就是用白朮、干姜、人参、炙甘草，让肠胃功能很快的恢复，结果吃了理中汤越利越甚，理中汤是理中焦 的虚，被攻下了以后是下焦的虚，所以把中焦壮起来没有用的，这时候赤石脂禹余粮汤主之。复利不止者，当利其小便。在伤寒金匮里面有一原则，治利的时候，处方下去不能止利的时候利小便，想办法把大肠小肠里面的水导到膀胱小便出来，利就止掉了，所以临床上，包括霍乱、痢疾的上吐下泻、下利不止，都可以利小便把利止掉，利小便最好的药是猪苓、泽泻，所以把猪苓、泽泻加到止利的药里面。  \n\n       一般来说下利太厉害的时候，先用赤石脂禹余粮，这两味药是涩剂，石类药，现在禹余粮很少了，大部分市面上看到的是赤石脂，临床上下利不止，不需要用赤石脂禹余粮汤，因为禹余粮不容易买到，用白朮、赤石脂，白朮在药房里的炮制，一般来说是把白朮炒黄土，还有一种是白朮和赤石脂炒在一起，平常拿白朮来健胃整脾的时候是用炒黄土的，用在止利的时候是用炒赤石脂的，加在小建中汤里面或半夏泻心汤里，利就止掉了。  \n\n       下利出血的类似症状如何鉴别?先便后血，这不是大肠炎出血，是外痔出血；先血后便，这是内痔出血；血与便混合，这才是大肠炎下利。  \n\n       成无己曰：《圣济经》曰：滑则气脱，欲其收也，如开肠、洞泄、便溺、遗矢、涩剂所以收之此利由下焦不约，与赤石脂禹余粮汤以涩洞泄。下焦主分清浊，下利者，水谷不分也，若服涩剂而利不止，当利小便以利其气。  \n\n      临床上也可以灸大肠俞，腰俞，中极、关元、水道、水分都可以。', NULL, '赤石脂禹余粮汤', NULL, NULL, NULL, '174、伤寒，服汤药，下利不止，心下痞鞕服泻心汤已，复以他药下之，利不止，医以理中与之，利益甚；理中者，理中焦，此利在下焦，$f{赤石脂禹余粮汤}主之，复利不止者，当利其小便。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616231762563144, '0BA6C7A5811EFA2E8F7E185DBE2C3A56', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:13:30', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5386, 319, 904000645, '       外证没有除，一直在攻下，造成邪热下利，利下不止。表热一直往里面走，且心下痞鞕，有表证也有里证，所以桂枝人参汤是表里双解；桂枝人参汤和桂枝加人参汤不一样，桂枝加人参汤是津液不足了所以加进去的，桂枝人参汤是特例的方子是寒利在用的，胃里面也难过。 ', NULL, '桂枝人参汤', NULL, NULL, NULL, '178、太阳病，外证未除，而数下之，遂协热而利，利下不止，心下痞鞕， 表里不解者，$f{桂枝人参汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616235304656966, '09CEAB62F04349CBAC7BC8C817248F93', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:27:54', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5387, 319, 904000644, '里面热太过了而失津，因为内热盛，津液会丧失掉，病人的表会一直在流汗，胸腔的热太盛了，里面就是肺发炎了，像肺炎的第一方就是麻杏甘石汤，初期的麻杏甘石汤没好，到最后壮热就是肺炎了。反之，如果无汗而喘咳，有大热者，就是发高烧而肺热苔黄者，就要考虑大青龙汤了。', NULL, '桂枝汤,麻黄杏仁甘草石膏汤', NULL, NULL, NULL, '177、下后，不可更行$f{桂枝汤}；若汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616235304656967, '8436A21147621E586D4194CEA310033C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:27:54', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5388, 319, 904000651, '      表面上看没有大热，摸他身体冰冰凉凉，但是里面口燥渴，心烦，背微恶寒者，背稍微有点恶寒，因为胃上面有很多交感神经包着，直接络到后面的脊椎骨，脊椎骨又直接络到后面的汗腺，白虎汤证津液会丧失很多，因为胃气热气往上跑，津液一直往上发，汗不断的流，津液丧失了以后，体表的水分不够了，病人会感觉到寒、冷的现象，这冷并不是阳虚的恶寒，而是津液丧失的现象，所以白虎加人参汤很好用。  \n\n       阳明病病发的时候是申时到戌时，中医叫日晡，就是黄昏的时候，因为胃阳就是阳明，全身最热的就是阳明，到了黄昏的时候，太阳渐渐下山了，阴气渐渐起来，阳气渐渐衰的时候，阴气会来到胃，因为他本身是胃的问题，所以阴气渐升上来的这段时间当中，会看到白虎汤证，就是会看到阳明证，所以每到黄昏的时候，就开始发热。例：小孩发烧，本来是晚上发烧，治疗一个星期后没好，结果晚上现在不烧了，变成每到黄昏的时候，就开始发烧。就是西医没治好，本来是太阳证，治了一、二个星期后变成阳明证，病往前进，更严重了。一般来说，阳明证的发烧温度会比太阳证的发烧温度来的高。  \n\n       白虎汤和承气汤的区别，人身上的血都散布在全身血脉里，流汗流太多的时候，血里面的水流掉了，所以血里面的热就自然而然增加了，人能保持身体的恒温，就是因为血里面有一定比率的水分和热，水是冷的，如果水去掉了，热就会增加，病人就会发高烧，壮热，热到四十度，如果每天傍晚的时候热，就知道是热在阳明经上面，这时候的热只有两种，一种是血的壮热，一种是大便不通也会引起壮热，所以一个是热在腑里面，一个是热在血里面，如果热在腑里面，大便不通就是承气汤证，如果热在血里面就是白虎汤证，问有没有大便就可以区分了。  ', NULL, '白虎加人参汤', NULL, NULL, NULL, '184、伤寒，无大热，口燥渴，心烦，背微恶寒者，$f{白虎加人参汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616484092506182, 'A610CAB8255E729B1ADA9D47B7D9B278', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:20:14', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5389, 319, 904000650, '      伤寒应该是用表法、汗法，结果吐下后，胃的津液一定会伤到，七八天都没有好，结果热结在里，表里俱热，里面有病，表也有病，里面的热哪来?因为津液伤了。人的热停在津液里面，也停在血里面，血里面有一部分是热的能源，津液伤了以后，有一部分的热就离开了津液，离开了血就浮上来了，所以里面会很热，第一个受到伤害的就是肺，肺主皮毛，这时候病人常常感觉会流汗、怕风，大渴而烦，上焦太燥热的时候，因为津液没有了，上焦就像天上没有云了，太阳直射很烫很热，这是白虎汤证，因为胸阳在上面，心脏和肺有一定的湿度，本来胸口就很热了，胃热又往上冲，津液都丧失掉了，流汗流掉了，结果舌上干燥，舌头伸出来一点口水都没有，严重到舌苔都翻起来，欲饮水数升者，渴想喝水，喝了半天都不能止渴，因为水到了胃里面是往下走，本人并不能吸收，因为真正吸收的水是靠胃液把它化解的，结果胃液都被吐光了，没了，所以没有办法把水变成水蒸气上来，水就直接往下走。不能止渴，所以是白虎加人参汤证。  \n\n        白虎加人参汤是中医对上消糖尿病的方子，也是中医对心热最好的方子，外面甚至有表证都没关系，里面太热，热在胸上面的时候，用白虎加人参汤，白虎汤证就是燥渴烦燥，所以开到白虎汤给病人的时候，他的外病可能是精神病，没事就发脾气，结果被西医认为是精神病，中医看他燥渴，津液都没了，没办法控制情绪。为什么加人参?平常人不用吃人参，除非津液不足了，才需要用到人参，人参常常用在肠胃科里面，所以泻心汤常常用人参，人参一下去，津液马上就补足了，补足了以后，白虎汤再把热退下去，退热真正好的是石膏。现在说的糖尿病有一种情形，很容易血糖太低，很快就饿，常常需要吃糖才可以的病人，也是用白虎汤。  \n\n       现在食物中的味精，吃了以后，一直口渴喝水不止，这也是白虎汤证；味精一吃下肚子，还没经过表证，就直接入里变成白虎汤证，从这点就可以知道它对人体有伤害，所以我们才说食物中不要加味精。  ', NULL, '白虎加人参汤', NULL, NULL, NULL, '183、伤寒，若吐，若下后，七八日不解，热结在里，表里俱热，时汗，恶风，大渴而烦，舌上干燥，欲饮水数升者，$f{白虎加人参汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616484092506183, '4F41623B72D7811C6EEC5BD75C568AD3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:20:14', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5390, 319, 904000649, '       过去中医没有外科手朮，很多病人得了这种病就死了，其实讲的就是疝气，有时候在肚脐的左边，有时候在肚脐的右边，耻骨、曲骨穴的地方突起来，有时候男子的阴囊膨起来；现在已经看不到了，医书上有记载，有的人肠子坠出来了以后，疲劳的时候肠子就坠出来，好的时候或推推可以推回去，就是疝气，可以推回去的没有什么关系，可是如果当疝气的时候，又得到重感冒，过去很多病人就死掉了，为什么?因为肠子整个结在下方，肠子的循环不是很好，大便堵在里面，刚开始病人吐黄水酸水，到最后下面不通，往回逆，把大便都吐出来，西医开刀时把腹膜接起来，遇到这种情形的时候，到医师手上已经很晚了，因为平常不会发现，可是当有疝气的时候，临时又得到重感冒，马上就看到这种现象。  \n\n        因为张仲景不懂针灸，不能急救，所以说死，实际临床上在做的时候不需要开刀，因为人阴部的地方只有一条经，就是肝经，肠子都堆在鼠蹊部了，很难过都陷在那里了，所以下针大敦，肝经上的井穴，针一下马上就缩回去了，因为很痛，痛得他吓回去了，右边痛就扎左边，左边痛就扎右边，平常中医的俗名叫脱肠，脱肠到严重的时候，西医叫坎顿脱肠，就是肠子都烂掉了，有时候会小肠挂在肾的上面，下针大敦、曲泉，平常可以灸，因为是小肠坠下去，大肠不会坠下去，所以灸小肠的关元穴。内服的药有当归四逆汤，过去临床上用当归四逆汤配合针灸，效果很好；如果给西医开刀也可以，因为是急救，开在体外没有进入体内，但是西医开刀只是塞回去，肠子里面还是堵的。  \n\n 脏结专论：  \n\n        脏结为邪结在脏，与阴相结。邪结在胸，与阳相结为结胸。脏结证见白滑舌苔者，难治。无阳证，不往来寒热，其人反静，舌苔滑者，不可攻。病者若胁下素有痞，连在脐旁，痛引少腹，入阴筋者，死。结胸证，脉浮大者，下则死。结胸证悉具，烦躁者死。病名曰结，脏器有硬变，或内部肿瘤所致，古称癥瘕积聚故预后不良，或为癌瘤，则死期可待。  \n\n       脏结就是脏腑之间联络的网络，被寒与湿固结了，结果腑里面吸收的营养没有办法给脏，脏没有营养，脏的功能慢慢的衰弱，所以脏结的病人，舌苔都白白的，很厚很滑，皮肤很黄，暗暗黑黑的，没有什么精神，不爱讲话，静静的。刚开始西医检查都正常的，等到检查出来的时候，已经尿毒了，肝硬化了，中医治疗三天舌苔就变回来，中医为什么看舌苔?就是看看病人有没有胃气，脏结的人舌苔白掉了，吃东西淡而无味，食同嚼蜡，搞不好四五十岁还在生青春痘，因为在三焦油网上，所以一定要大剂的用柴胡，利用柴胡把药导到三焦油网上面，因为是全身性的寒且湿，去湿靠白朮，可以用五钱，这是胖子用量，湿要有出路，靠茯苓，由小便导出来，去寒靠炮附，用三钱，加些生姜在胃里面和，最重要的是生附，生附一枚，炮附把里阳壮起来，里寒去掉了，肌肉上和三焦油网上的寒，全部靠生附去掉，生附下去，病人除了小便量增加以外，大便出来溏的，大便稀稀的，吃了三付后，舌苔就变回来，胃口大开，临床上尿毒的病人，吃一剂，尿毒指数从二百八降到一百三了，炮附温中，生附温经，血脉、神经都温到，这是主方，临床上看病人还有何症状作加减，若胃口不好常常恶 心就加半夏，依此类推。有些久病的病人，在吃药去除寒湿以后，因为脏与腑开始可以沟通了，会有吐白津或大便溏的现象，这种情形在病人开始出现口渴的时候就会好转。  \n\n脏结汤方\n        柴胡五钱    白朮五钱    茯苓五钱    炮附三钱    生附一枚\n主方在此,其余需临证视情况而定。 \n\n', NULL, NULL, NULL, NULL, NULL, '182、病胁下素有痞，连在脐旁，痛引少腹，入阴筋者，此为藏结，死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616484092506184, '49EECA238B0D081EE04C494E0A15A5CF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:20:14', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5391, 319, 904000648, '寸关尺所代表的脏腑（校对：原文无，为了索引方便增加的。）\n\n  寸上寸——喉咙 \n\n  寸  寸——胸阳位 \n\n  寸下寸——横膈膜，冲脉 \n\n  关上关——中焦，最上位 \n\n  关  关——中焦之肝、胆、脾、胃 \n\n  关下关——中焦之下肠部 \n\n  尺上尺——三焦之源，左为肾，右为焦源 \n\n  尺  尺——肾、膀胱、子宫、精宫 \n\n  尺下尺——尿道、肛门、两足胫位  \n\n       整个伤寒论就是这一条在讲吐剂，张仲景并不很赞成吐剂，内经里面讲病在膈上的时候去不掉，采吐法，\n       病如桂枝证，像桂枝汤证，可是不是桂枝汤证，头不痛，项不强，寸脉微浮，寸脉讲的是胸、上焦，寸下寸指的是胸到横膈的地方，寸指的是心窝的地方，寸上寸指的是喉咙的地方，所以如果把病人的寸脉，寸脉跳到寸上寸的地方来了，就是喉咙梗到了，吞咽困难，喉咙发炎，所以寸脉微浮就是病在阳上面，胸中痞鞕，气上冲咽喉，不得息者，此为胸有寒也，胸有寒应该解释为胸有实，就是胸有痰，这痰梗在很上方，咳又咳不出来，吞又吞不进去，用攻下的药攻也去不掉，这种状况就把它吐掉，这是一种有痰的情形；还有一种是东西梗到不动了，譬如铜板梗到了，所以寒除了痰以外、还有不动了也是寒，用瓜蒂散太累了，用肥皂也可以。  \n\n      胸有热的时候，大黄黄连汤证，如果是肺热咳嗽，麻杏甘石汤证，如果胸里面太冷了寒证，有大建中汤，大建中汤里面有三味药，干姜、人参、蜀椒，蜀椒就是腌泡菜的巴椒，如果肚子太冷了，有小建中汤，如果真正胸有寒不会用到瓜蒂散，瓜蒂散是用在有东西堵到了的时候。 \n', NULL, '瓜蒂散', NULL, NULL, NULL, '181、病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上冲咽喉，不得息者，此为胸有寒也，当吐之，宜$f{瓜蒂散}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616484092506185, '0ACE6CD057EA361699EB4EDC6056A134', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:20:14', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5392, 319, 904000647, '       如果病人发热，汗出不解，就知道病不在表了，一般来说如果在表，汗出就解掉了，汗出不解就是病进入半表半里或进入某处了，要看其它的症状，心下痞鞕，胃里面胀满，呕吐而不利，大便没有了，心下痞鞕不利又代表阳明热，肠堵到了，病人呕吐现象代表少阳，会用到大柴胡汤一定是有少阳证兼有阳明证，大柴胡汤专门用在少阳和阳明中间，如果病情在太阳和少阳中间是小柴胡汤，如果少阳阳明兼有利呢?阳明热有时候不是大肠堵到，而是血里面太热了，有下利的话把大柴胡汤里面的大黄拿掉就好了。 ', NULL, '大柴胡汤', NULL, NULL, NULL, '180、伤寒，发热、汗出不解，心下痞鞕，呕吐而下利者，$f{大柴胡汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616484092506186, '998E07186DF99EBEC04B447A31DA366A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:20:14', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5393, 319, 904000646, '      被攻下了以后又发汗，结果造成心下痞，如果病人有恶寒，就是病人还有表证，看到有表证的时候，还是要照伤寒论的原则，一定要先解表再攻痞，解表用桂枝汤，攻痞用大黄黄连泻心汤，会用到大黄黄连泻心汤的，舌苔一定是黄的，是热痞，上焦的脉很数，反过来说，摸到病人的脉很数，就知道病人里发炎了。', NULL, '桂枝汤,大黄黄连泻心汤', NULL, NULL, NULL, '179、伤寒，大下后，复发汗，心下痞，恶寒者，表未解也，不可攻痞，当先解表，表解乃可攻痞，解表宜$f{桂枝汤}，攻痞宜$f{大黄黄连泻心汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616484092506187, '34B59CC72721B048FCCB1187ACD2518E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:20:14', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5394, 319, 904000654, '       前面介绍如果太阳证，病在表的时候，被误下或自己吃坏肚子了以后，变成肠利是热利，就是葛芩连汤；这里是太阳和少阳的合并病，被误下后，这种状况是黄芩汤；若呕者，黄芩加半夏生姜汤主之；半夏生姜汤常常在用的，恶心的时候会用到，所以小柴胡汤最重要的就是半夏。  \n\n        前面介绍下利的方子有葛芩连汤、桂枝人参汤，葛芩连汤是热利用的，桂枝人参汤寒利用的，现在又一方子黄芩汤，桂枝人参汤的下利不臭，白水很多，食物都没有消化，寒利的原因是它并没有病毒，而是肠胃都没有蠕动了，所以东西就滑出来了，因此桂枝人参汤里面加很重的白朮去湿，干姜温肠；如果拉出来热利，大便很脓稠，肚子不痛，就是葛芩连汤，拉出来会绞痛的，也是很热的就是黄芩汤，葛芩连汤和桂枝人参汤都没有腹痛现象，而且并不是真正的病毒，真正病毒的下利、急性肠炎要靠黄芩汤；像肠套迭属于肠热证的可以用黄芩汤。  \n\n       黄芩汤里面有芍药，葛芩连汤和桂枝人参汤都没有芍药，芍药是专门止腹痛的，所以当一个人表证都没有，只是肚子很绞痛的下利，这时候用葛芩连汤、桂枝人参汤都没用，因为病毒已经深入到肠子的血管里面去了，所以黄芩汤常常是用在急性肠炎的方子，不是一般的寒利或热利，它是介在太阳和少阳中间，黄芩这药专门是在肠炎的时候一定要用的药，大黄泻上焦头目的热、黄连去中焦的热、黄芩清小肠与大肠的热；所以胃热发炎会先想到大黄、黄连；肠炎会想到黄芩；如果表面有恶心、呕吐还有腹痛，可以黄芩汤加半夏生姜，半夏是止呕去水的，半夏有毒，所以用生姜去解半夏的毒，干姜也可以解半夏的毒，因为他拉水，水很多所以用生姜，如果是寒利就改用干姜。', NULL, '黄芩汤,{黄芩加半夏生姜汤', NULL, NULL, NULL, '187、太阳与少阳合病，自下利者，与$f{黄芩汤}；若呕者，$f{黄芩加半夏生姜汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616486560161862, '8C258030C03B7A876BAD17EBEF0EADC6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:30:16', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5395, 319, 904000653, '       本身有太阳证又有少阳证，譬如看到病人有太阳证，如恶寒、发热、流汗、脉浮的现象，又有少阳证的恶心、胸胁苦满，和解法就是小柴胡汤，当刺大椎、肺俞、肝俞，慎勿下之， 不管怎样，最重要是绝对不要去攻下。  ', NULL, NULL, NULL, NULL, NULL, '186、太阳少阳并病。心下鞕，头项强而眩者，当刺大椎、肺俞、肝俞，慎勿下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616486560161863, 'BBB8640E27BEE956F88DE251FB7BA2C6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:30:16', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5396, 319, 904000652, '       平常表证很壮盛的时候不可以给白虎汤，白虎汤以清里热为主，并不是以解表为主，如果吃了白虎汤以后还有表证，譬如吃了白虎汤后比较好了，但胃口比较差些，风吹了难过，就可以给桂枝汤，就是从白虎汤变成桂枝汤了，知道从阳明进入太阳了，这是治病的过程；渴欲饮水，无表证者，白虎加人参汤主之。临床上如果同时有桂枝汤证与白虎汤证，可以两方合用，表里双解。', NULL, '白虎加人参汤', NULL, NULL, NULL, '185、伤寒，脉浮，发热，无汗。其表不解者，不可与白虎汤。渴欲饮水，无表证者，$f{白虎加人参汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616486560161864, '9639405C0FFC09E472DD1ABFC03F9902', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:30:16', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5397, 319, 904000658, '     浮脉就是有表证，表热脉就浮起来了，滑脉代表热在筋，就是血热，血里面太热了，滑脉好像摸到急流的水一样，速度很快，这时候是白虎汤证。  ', NULL, '白虎汤', NULL, NULL, NULL, '191、伤寒脉浮滑，此表有寒，里有热，$f{白虎汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616500024455238, 'A258FAC16DFA8B3355FCDDFAE4EBFC2F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:25:03', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5398, 319, 904000657, '掣痛，痛得很厉害，抽筋的痛，不得屈伸，弯都会痛，近之则痛剧，碰到都会痛，汗出，病人痛得一直流汗，短气，小便不利，恶风不欲去衣被、或身微肿者，甘草附子汤主之。  ', NULL, '甘草附子汤', NULL, NULL, NULL, '190、风湿相搏，骨节烦疼，掣痛，不得屈伸，近之则痛剧，汗出，短气，小便不利，恶风不欲去衣被，或身微肿者，$f{甘草附子汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616500024455239, 'A3293680C44F6D775B5830B837E452B8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:25:03', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5399, 319, 904000656, '      从这条开始连续三个方子是伤寒论里面治疗风湿关节炎的方子，伤寒八九日，八九天了应该传少阳或阳明了，结果没有传经，风湿相搏身体烦疼，不能自转侧，滤过性病毒本来要进入少阳或阳明的，结果被湿挡到了，所以风湿的人刚开始得到感冒的时候，全身关节很痛，不能转身，又不呕，没有进入少阳，不渴，没有进入阳明，所以没有传经，可是也没排出去，病人的脉浮虚而涩者，浮代表风、涩代表湿，涩的脉就像葱一样，压下去扁扁的中间空的，这是脉证，肌肉关节很酸痛，很紧，翻个身都没有力气，病人还有表证，还兼了风湿，就用桂枝附子汤；如果大便溏，大便稀稀黏黏的，代表湿，脾主湿，当湿很盛的时候，脾脏功能不好，脾主运化，肠子蠕动仰赖脾脏，一旦脾湿过盛，湿就渗到肠子里面去了，结果大便出来就黏答答的，同样的，开给病人去湿的药的时候，病人的大便就应该是黏答答的，小便自利者，去桂枝加白朮汤主之。这种风湿关节炎，现在人如果体质素有中湿，在劳动以后，又吹冷气导致不能出汗，就容易发生。 ', NULL, '桂枝附子汤,去桂加白术汤', NULL, NULL, NULL, '189、伤寒，八九日，风湿相搏，身体烦疼，不能自转侧，不呕，不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若其大便溏，小便自利者，$f{去桂加白术汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616500024455240, '26CDD613826E9EB09AB0F32CFB7EBAB8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:25:03', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5400, 319, 904000655, '      肠子发炎的时候用黄芩汤，胸膈发炎的靠黄连汤，除了生姜泻心汤以外，黄连汤过去抗战时大多用来治疗霍乱的，为何胸中有热?病人呈现的症状是上热下寒，病人吐很多，胃里面的虚热往上走，胸膈里面有很多水、湿，胃热往上走的时候，碰到水、湿会变成痰，因为热在上面把水、湿烤得很黏稠，就变成痰了，因为胸膈的热邪在烧，东西吃下去就吐，看舌苔黄黄的，喝水又吐掉，因为肠胃有很多病毒在里面，所以一直在下利，吃什么拉什么，看到病人是上面燥热的，下面是寒的，黄连汤就是专门用在这种状况。  \n\n    不管病人是纯热、表实里虚、里实表虚、上热下寒、上寒下热，处方的时候去寒的药要开，去热的药也要开，煮在一起。  ', NULL, '黄连汤', NULL, NULL, NULL, '188、伤寒，胸中有热，胃下有邪气，腹中痛，欲呕吐者，$f{黄连汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616500024455241, '302924076977189C7C4EA537BAA92432', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:25:03', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5401, 319, 904000660, '       促脉、结脉、代脉都很难治，都是人身体很虚的状况之下，平常促脉在身体的气血不是很流畅的时候会摸到，促脉属于阳脉，并不是很危险的，结、代属于阴脉，就很危险了。促脉就是脉跳得很快，突然停一下，有时候三下停一下，有时候五下停一下，有时候四五十下才停一下。内经中提到，如果跳五十四次以上才停一次，属正常。  \n以上讲的是太阳证下篇。  ', NULL, NULL, NULL, NULL, NULL, '193、脉，按之来缓，而时一止复来者，名曰结，阴也。又脉来数，而中止更来，及小数中止能自还者，名曰促，阳也。脉来缓，而中止不能自还，因而复动者，名曰代，阴也；得此脉者，必难治。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616507625001030, '9411F8494BB8847E32D097E6850AD83B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:55:59', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5402, 319, 904000659, '        整本伤寒论里面就两个方子治里虚，不管有没有表证。里虚有两种状况，一种是病人腹痛，就是小建中汤，所以看到病人是小建中汤证，就先予小建中汤给他吃，还有一种是炙甘草汤，不管病人什么病，只要摸到病人脉结代，心动悸，就给他炙甘草汤，何谓心动悸？就是心慌、想哭，脉结代，脉结代就是西医说的心律不整，就是脉跳二下停一下，或跳三下停一下，结就像绳子上面打很多结，结的距离不一定，然后手摸上去就是结脉，代脉就像滴水，久久才滴一滴，结脉和代脉都是一种症状，脉结代了就是里虚，里虚的时候，不管表证是什么，如果脉结代就是炙甘草汤，另外一个就是小建中汤。  \n\n        摸到病人脉的跳跳停停，不要用粉剂，炙甘草汤用汤剂，大约三剂就好了，为什么会脉结代？肠胃本虚之人容易看到，肠胃虚的人，消化不好，所以常常在妇人身上看到有，思能伤脾，脾就肿起来了，吃下食物后，因小肠蠕动太慢而有间隔，人的肠胃吸收了食物之后，才变成血，血再供应给心脏，如果有时候给血，有时候又不给血，心脏有时候抓得到血，有时候又抓不到血就停一下，所以本虚的人就会有脉结代的现象。小肠套迭的病人，阻塞的地方有时候通有时候不通，也会发生结代脉的情形。  \n\n        张仲景发现这心律不整是肠胃引起的，当胃的津液不足的时候可以看到，因为知道是肠胃本虚，所以处方用到甘草、人参、大枣、生姜，这四味药是固定的，脾脏本身有动能，把脾的血挤出来到脾之大络，就是胰脏，胰脏的血管到胃的下方，胃得到由脾脏过来的血、热，胃开始蠕动，如果热度不够了，蠕动没了，胃本来存在的热气就往上走，这热气本来在胃的津液里面的。因为胃的燥气往上走，肺也会跟着燥，所以心情会不好，肺和大肠相表里，所以知道这人的大便一定不会好。并不是便秘，但大便不是很好，要下焦的大便好，上源一定要滋润，否则肺太热，热到后来会没有大便，所以加麦门冬，麦门冬专门是润肺的，让肺里面的湿度够，然后加麻子仁，因为他不是便秘，肠子里有宿食，虽然肠子有在走，但是走太慢了，宿食有些坏了，如果用大黄、芒硝又太强，所以用麻子仁慢慢的把肠子清出来，中药的仁剂，杏仁、薏仁，都是油质比较多的，可以润滑，本来血就不够了，加生地，生地专门是补血的，阿胶是驴皮熬成的胶质，现在最好的是山东的阿胶，深咖啡色，阿胶专门补心血，阿胶止血的功能非常好，所以女人月经来的时候不能吃阿胶；北派平常不开补药给病人的，要病人肠胃功能恢复，自己吸收食物滋养身体最好，这时候如果光靠甘草、人参、大枣、生姜、再吃食物去补太慢了，所以把补血的药加在里面，要让它进入心脏进入动脉，所以重用桂枝，这九味药加起来就叫炙甘草汤，重用炙甘草让胸阳壮起来。  ', NULL, '炙甘草汤', NULL, NULL, NULL, '192、伤寒，脉结代，心动悸，$f{炙甘草汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616507625001031, 'AC078DB499D08208E7FB4EF4FC77E169', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:55:59', 1, '超级管理员', '2024-11-27 11:56:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5403, 320, 904000701, '       什么叫做太阳阳明?这个阳明病是从太阳转过来的，病人原来是太阳病，桂枝汤或麻黄汤或葛根汤，吃太过了，津液发散太多，肠胃里面的津液没了，大便干在里面，就叫做太阳阳明。 \n\n       什么叫做正阳阳明?胃家实是也，本来就是大便堵在肠子里的，伤寒论中要把胃当作肠来看，胃肠子都是阳明。\n\n       经上面的少阳经，腑上面指三焦和胆，三焦是水道出焉，水道的系统，所以如果水利太多了，三焦油网有问题的时候，也会造成胃中燥实，利小便，胃中燥实，大便难是也，就叫做少阳阳明。  \n\n       为什么靠药下去，能把肠胃里面的津液，顺着三焦油网到皮肤表面上变成汗出来?就是靠刺激脾脏，所以桂枝汤下去了以后，就是靠桂枝和白芍，然后生姜、甘草、大枣把肠胃的津液补足，如果药开得不对，津液伤得太多了以后，脾脏的运动功能就缓下来了，脾脏的血就没办法正常的跑到胃的下方，胃的蠕动功能就渐渐缓下来，食物就慢慢掉下去了，食物掉 下来不是因为消化磨碎下来的，食物若堵在肠子里面，大便出来就像六味地黄丸一样，像羊大便一样，所以脾约就是脾脏因为发汗发太过，脾脏的功能受到约束。', NULL, NULL, NULL, NULL, NULL, '194、问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也?答曰：太阳阳明者，发汗脾约是也；正阳阳明者，胃家实是也；少阳阳明者，利小便，胃中燥实，大便难是也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616561999765575, '149D9DCCA1396B78DCDE8FF8906161F7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 15:37:14', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5404, 320, 904000702, '胃家实证：  \n\n（一）舌苔黄燥：舌苔伸出来又黄又干燥。\n（二）大渴饮冷：猛灌冷水。 \n（三）中脘痛而拒按：肚子痛，天枢穴压了很痛，代表大便堵到了。 \n（四）阙上痛：因为肠子里面有干燥大便堵到的话，燥气往上跑，燥气正好跑到头上就是印堂痛，正头顶痛也是阳明、侧边痛是少阳，后面项痛是太阳。  \n\n      如果大便堵在小肠出来到大肠头这一段，就是盲肠的地方，病人会有一个特殊现象，右腿弓起方可入眠，就是晚上睡觉的时候，右腿要弓起来才能睡，因为右腿伸直筋会抽到，要弯起来才比较舒服。  ', NULL, NULL, NULL, NULL, NULL, '195、阳明之为病，胃家实是也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616561999765574, 'BA51CFF1AA88945705CED7B9D291703F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 15:37:14', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5405, 320, 904000703, '太阳或少阳病，如果发汗或攻下太过了，造成肠胃的津液没了。造成干燥才转成阳明，不更衣，就是不上厕所。', NULL, NULL, NULL, NULL, NULL, '196、问曰：何缘转阳明病?答曰：太阳、少阳病，若发汗，若下，若小便利与亡津液，胃中干燥，因转属阳明，不更衣，内实，大便难者，此名阳明也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616562968543302, '9B41AEB6A6B4915DC555D21EB98E014A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 15:41:11', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5406, 320, 904000716, '        申是下午三点到五点，戌是七点到九点，从申至戌上，中医叫日晡，太阳病欲解时，巳至未，上午九点到下午一点。阳明病欲解时，从申至戌上，下午三点到晚上九点。平常阳明有病的时候，也会在这段时间发热、中医叫做发潮热，到了傍晚的时候，就是日晡的时候发潮热，就是标准的阳明热，有一种发烧，每天下午的时候就发烧，烧到晚上七点就退了，这时候问病人大便好不好?大便好就是白虎汤，大便不好就是承气汤。  ', NULL, NULL, NULL, NULL, NULL, '209、阳明病，欲解时，从申至戌上。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761286, '16C6B1189D4BBA702E5AB984A55C6B5F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5407, 320, 904000715, '        阳明病，欲食，想吃东西就是脾脏功能很好，但是不见得已经开始吃东西了，大便自调，大便正常，小便反不利，其人骨节疼，因为吃进去的食物没有办法供应营养，翕翕有如热状，胃的蠕动不是很好，蠕动正常的时候，就把营养消化给四肢。有时候又没有，所以会感觉一阵一阵的热，就像冬天的时候，很冷，肚子饿的时候，会觉得更冷，吃了东西，纵使东西是冷的，也会马上觉得热起来，所以体温的恢复就是胃的功能，奄然发烦，濈然汗出而解者，就是胃气要回来了，产生这样的原因就是此水不胜谷气，水和食物不一样，水到胃里面，是靠胃的热力把它蒸发出来的，食物吃到胃里面磨碎是靠脾脏的功能，水道和谷道不一样，水不胜谷气就是脾脏的功能很好，胃的热量不够，脉紧则愈，脉一紧代表里实起来了，里面一实，代表胃热回来了，胃开始消化东西了，这种人不需要治疗，这条辨讲病人的体力很好，自然而然恢复的现象，小便不利只是一时的。  \n\n      临床上，病从太阳进入少阳或进入半阳明的时候，看病人自己会不会恢复，如果自己的胃气会恢复最好，宁可不给他吃药，如果只有两个选择，一是吃抗生素，一是不吃药自己好，宁可选择不吃药自己好，中西医的讲法是一样的，阳明篇有时候不需要处方。不管是轻病或重病，一吃完药胃口大开，这病就回来了，如果没有就很危险。', NULL, NULL, NULL, NULL, NULL, '208、阳明病，欲食，大便自调，小便反不利，其人骨节疼，翕翕如有热状，奄然发烦，濈然汗出而解者，此水不胜谷气，与汗共并，脉紧则愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761287, 'F27CF8BFCC376FF62FD4AA6513993901', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5408, 320, 904000714, '      如果胃里面不能蠕动了，食物堵在里面，不能吃东西了，小便不利，为什么?因为肠胃不蠕动，胃火太小了，水喝下去都不能气化，水都停在里面、东西下不来，水下不去，运化的功能不好，小便也不能正常了，手足濈濈然汗出，手脚汗出，手脚汗出代表胃虚掉了，固瘕，固瘕就是顽固的下利，这肠胃都没有蠕动，为什么会拉出来？因为食物烂掉慢慢的流出来，实际上是因为胃没有蠕动，但是胃没有蠕动并不代表胃里面没有津液，遇到这种情形的时候，病人准备变成长久的下利，所以如果这人只有手脚有汗，其它没有汗，肠胃很虚，胃气不足才会有这现象，这人必大便初鞕后溏，刚开始大便很硬，后来就溏泻下来了，里面没有办法消化，食物就腐烂掉了，所以然者，以胃中冷，水谷不别故也，因为胃里面太寒了，不会蠕动了。喝进去的水和吃的五谷杂粮混在一起，喝的水没办法气化，吃的食物又没完全消化，水和谷就一起从大便出来。所以遇到这种长年下利，大便又没有什么味道就是胃寒。这种情形，我们可以用到甘草干姜汤或者是吴茱萸汤，依照症状来决定。', NULL, NULL, NULL, NULL, NULL, '207、阳明病，若中寒，不能食，小便不利，手足濈濈然汗出，此欲作固瘕，必大便初鞕后溏，所以然者，以胃中冷，水谷不别故也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761288, '0A30C28A296A078776B6D787E7E19599', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5409, 320, 904000713, '       阳明证如果能吃东西代表中热，胃的蠕动很快，如果不能食，就是胃寒了。攻下的时候分寒实、热实，寒实就是有东西堵到，堵到的原因是肠胃没蠕动了，舌苔白的；热实是东西堵在里面，因为津液干掉了堵在里面，舌苔黄的，严重的舌苔都翻起来了。  ', NULL, NULL, NULL, NULL, NULL, '206、阳明病，若能食，名中风;不能食，名中寒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761289, '3B95CF82614E9799834D9127E4F50094', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5410, 320, 904000712, '        风当成热来看，阳明如果很热，病人口苦，咽干，代表经热，属于少阳，\n        腹满，太阴证主证就是腹满，因为脾脏肿大，脾脏功能衰弱以后，脾主运化，造成肠子蠕动减缓，所以腹满。\n        为什么会微喘?正常的气，阳气往上升，阴气往下走，如果堵在这不动的时候，上焦下焦不通利，就会有微喘。\n        发热，恶寒，代表有表证，\n        脉浮而紧，浮代表有表热，紧代表实，如果浮紧代表表实，等于表寒里实的现象，如果这病人有少阳证，有太阴证，又有伤寒表证，兼有阳明证，不管是太阳兼有阳明或少阳兼有阳明，只要是阳明证兼有太阳少阳热，绝对不 可以用阳明证攻下，因为阳明还没有结实。如果结实了就是全身会流汗，如果还没有结实，有太阳证或少阳证，一定要先解太阳或先解少阳，\n       若下之，一攻下，人的免疫系统抵抗力都是靠肠胃，结果一攻下，免疫系统的来源都被干掉了，结果免疫系统倒退，表邪入里，一入里，进入三焦、横膈，\n       胃中空虚，客气动膈，一攻掉，肠胃都空了，一入里就进入膈间，此时绝对不可以直接解阳明，如果要表里一起解的话，一般来说，太阳兼有阳明是桂枝汤加大黄，桂枝汤解太阳表证，大黄去阳明的实。少阳兼有阳明是用大柴胡汤，这条辨反过来说，要确定阳明证全部是实证的时候，而且没有表证才可以攻下。  ', NULL, NULL, NULL, NULL, NULL, '205、阳明中风，口苦，咽干，腹满，微喘，发热，恶寒，脉浮而紧，若下之，胃中空虚，客气动膈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761290, 'A01575C44BAF3260C35C7830D43DE3C5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5411, 320, 904000711, '      汗的来源是肠胃，病进入阳明的时候，此病是里实证，胃里面堵到了，这汗出来是实热，是全身性的出来，濈然微汗出，所以阳明证，看到病人的时候一定是全身性的汗，如果只有手脚有汗，就是虚，胃虚的时候会手脚有汗，手脚汗多的病人大多以胃虚来治疗，因为胃虚的人，阳气比较常人衰弱，脾主四肢，胃只剩一点点气，出来的时候一定到四肢去了。  ', NULL, NULL, NULL, NULL, NULL, '204、伤寒转系阳明者，其人濈然微汗出也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761291, 'EAC5325C4AF3226F6A7BFE7184607509', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5412, 320, 904000710, '       浮讲的是表，缓就是表里有点热而已，手足自温者，就是胃气非常的足，所以当胃气没有的时候，四肢厥逆，手脚冰冷，这时候用四逆汤，所以四逆汤用干姜附子，让胃马上热起来、所以手脚有温度就是胃气很正常，就是阳明，就是肠胃的功能没问题，而脉浮而缓，如果人食欲不振，就知道病在太阴。  \n\n      太阴讲的是脾脏，太阴有问题的时候，病人会有腹满的现象，腹满是太阴病的主证，吃东西可以吃，但是不想吃，想吃就是脾脏的功能正常，想吃正常，不想吃就是不正常，所谓思能伤脾，所以如果舌头吃东西没有味道的时候，就代表脾脏有问题了，如果脾脏功能缓下来，脾脏一肿大，蠕动就减少了，就是中医所谓寒，脾脏一肿起来，就代表脾的血没有办法充分供应胃的下方了，胃就不能正常的蠕动，所以肠胃受到脾脏的影响，就会腹满，肚子就会胀满，不想吃、如果病人想吃东西就是脾脏恢复了，所以想吃或不想吃都是脾脏在管。  \n\n        太阴者，身当发黄，为什么?脾脏本身是脾土，主黄色，三焦里面的都是油，所以水走在油上很快，三焦油网的来源来自脾脏，如果三焦油网中的油质不够，用白朮、茯苓来健脾，白朮、茯苓的健脾和桂枝、白芍的健脾不一样，桂枝、白芍健脾是加强血的循环，这时胃口会开，白朮、茯苓的健脾是让脾脏分泌黄油，让三焦很好，所以加白朮、茯苓能够去湿，增 加脾脏的黄油，所以它能调理三焦。这里说病在太阴，代表脾脏的湿土太盛的时候，脾脏的黄油会溢出来，若小便自利者，不能发黄，如果小便很顺，三焦油网里面的水能跟着小便走的话，脾的黄油也会跟着小便下来，所以小便会带一点黄，如果小便没有了，脾脏的黄油会跟着水散到皮肤表面上，这时候就会看到黄油色，脾脏的黄色会看到黄汗，虚的黄是血的颜色。反过来说，治疗发黄证就是利小便，像后面去黄的药、茵陈蒿汤都是利尿，湿有地方渲泻，小便一出来，黄马上就退掉了。所以小便如果很好，就不会发黄，如果小便不好，黄就起来了。  \n\n        至七八日，大便鞕者，为阳明也，这地方讲的就是从太阳证进入到阳明证，经过太阴的时候，如果太阴有湿土很盛的现象，这是病在传经过程。这条辨最主要讲的是如何分辨他到底有没有进入阳明，为什么在介绍承气汤前，讲这么多条辨?是强调要明辨什么时机可以攻下?攻下时候要小心，有时候病人还没完全纯阳明证，就不要急着去攻他，阳明还没有真正到结实的时候，一攻，病人反而会虚掉，就会产生很多后遗症。临床上看到的时候，不是很简单。  ', NULL, NULL, NULL, NULL, NULL, '203、伤寒脉浮而缓，手足自温者，是为系在太阴；太阴者，身当发黄；若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761292, '3B3182C510DF07F8560665AAFF06B51D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5413, 320, 904000709, '三日，就是三候，差不多是二十一天，摸到阳明的脉都是很大很扎实的。什么叫做脉大?就是摸上去力量很强，弹起来很强，脉形比较大，痨脉也很大，但是中空的。  \n\n如果脉是浮的，代表表。就是太阳，如果脉是弦，就是少阳，如果脉是大，就是阳明，如果把到脉是又浮又大又弦，代表太阳阳明少阳三阳并病。  ', NULL, NULL, NULL, NULL, NULL, '202、伤寒三日，阳明脉大。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761293, '95EE1D55F3B1DA77AB0D013AFE4EEDCE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5414, 320, 904000708, '       伤寒发热，无汗，就是太阳证，呕不能食，是少阳证，如果只有这样子就是太阳少阳兼证，现在反而流汗出来很多，病人又感觉发热，汗出濈濈然者，就是热而汗出状，这情形就是病人在发热又一直在流汗，照理说，伤寒表证不会有汗的，现在有汗就知道病要传阳明了，会进到阳明的病毒都很厉害，病毒进来的时候，肠胃的津液会去相抗，津液就会一直丧失，病人免疫系统一直在丧失，病毒又赶不出去，津液就会伤到，所以汗一直往外流，就知道传阳明了。  ', NULL, NULL, NULL, NULL, NULL, '201、伤寒发热，无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761294, '378D8CA4CF60915075F46DEB3D572187', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5415, 320, 904000707, '       发汗发过了会转阳明，还有一种是发汗发不透也会转阳明，为什么?滤过性病毒在皮肤表面和抵抗力相抗的时候产生热，一发汗的时候发掉一部分，还有一部分停在底下，热邪往里面走了，造成阳明证。所以麻黄汤、葛根汤要开得恰到好，不伤到津液又把滤过性病毒排掉，如果怕开不准，可以先开大剂的药分三次喝，喝第一碗没好再喝第二碗，好了就不要喝了，再喝当场就变成阳明证了。从胃口是否恢复，我们就可以判断病人好了没有。  ', NULL, NULL, NULL, NULL, NULL, '200、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761295, '144A1EFF31EA75B0E0E06D3E2B281E98', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5416, 320, 904000706, '        到阳明的时候，无所复传，当病邪进入肾脏或成肝癌的时候，其实里面都是堆积来的，并不是传经进来的，里面堆积了太多新陈代谢物，所以最好的方法就是把它清出来，所以道家、修道的人的观念断食，如果三天不吃东西光喝水，这三天还是会有大便，三天以后就没有大便了，因为没有吃东西，所以要保持肠胃里面不要有浊物，身上要清得干干净净的，身上会有东西堆积，都是肠胃有东西累积起来，再慢慢渗出来的。阳明居中土也，万物所归，无所复传，所以在中医的观念，阳明是腑里面的最后一道系统。  ', NULL, NULL, NULL, NULL, NULL, '199、 问曰：恶寒何故自罢?  \n 答曰：阳明居中土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761296, '967A38D5F3FEF9195E606C5E40AEAB5A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5417, 320, 904000705, '    为什么病有得之一日，不发热而恶寒者?阳明病刚开始得到的时候，太阳阳明在转交的时候，还有怕冷的现象，等汗一流出来，表证都没了，全部变成里证了。  ', NULL, NULL, NULL, NULL, NULL, '198、问曰：病有得之一日，不发热而恶寒者，何也? 答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761297, '99E78B5844EDCEBA2F139B739E1821B0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5418, 320, 904000704, '        阳明病，外证是什么样子?身热，汗自出，身体发壮热，汗一直流出来，津液一直在丧失，不恶寒，反恶热，阳明无寒证，全是热证，有寒证的时候一定是在太阳和阳明之间，为什么汗一直流出来?因为胃太热了，胃的津液一直在丧失中。 ', NULL, NULL, NULL, NULL, NULL, '197、问曰：阳明病，外证云何?答曰：身热，汗自出，不恶寒，反恶热也。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616578234761298, '291DDD75173A33BDC914DC5481D7F54B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 16:43:18', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5419, 320, 904000727, '      就是呕多，常常恶心吐的人，常常在恶心呕酸的人，酒客病的人不可以攻下，呕多代表病邪在少阳，在三焦，如果是呕家再进入阳明证，大柴胡汤就可以了。  ', NULL, NULL, NULL, NULL, NULL, '220、伤寒呕多，虽有阳明证，不可攻之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120390, '3A87F5DEFC46B6E044646DA146BBE4E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5420, 320, 904000729, '阳明证本来就是攻下治疗的，从220条辨开始，阳明证有四种症状不能攻下：       \n（一）220：伤寒呕多，虽有阳明证，不可攻之。就是呕多，常常恶心吐的人，常常在恶心呕酸的人，酒客病的人不可以攻下，呕多代表病邪在少阳，在三焦，如果是呕家再进入阳明证，大柴胡汤就可以了。  \n\n（二）221：阳明病，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。心下鞕满就是心下痞，用泻心汤来治疗，一攻肠胃就会伤到，泻心汤是寒热并结，肠胃里面发炎了，而不是燥屎堵到，一攻下的时候，会把肠胃的津液都攻出来，结果利遂不止者死，下利不止会死掉的，利止者愈，如果下利停下来，不会死，自己会好，如果下利不止的可以用四逆汤救回来。  \n\n（三）222：阳明病，发热，面含赤色，不可攻之。攻之，小便不利者，必发黄也。面赤，脸孔发红不可以攻下，脸色红代表胃气上冲，手掌红才是胃气好，如果手掌白白的，脸色红红的就不可以攻，全身红都没关系，不可以只有脸红；面含赤色。第一代表病在表，第二胃气快要没的时候，就是除中，就是回光返照的时候，不可以攻；攻之，小便不利者，必发黄也，此津液不足，而见血之本色也。  \n\n（四）阳明中风，这阳明中风就是阳明证还兼有太阳兼有少阳，不可以攻。  \n\n因此张仲景的意思是，必须是十足的阳明证方可攻下。  ', NULL, NULL, NULL, NULL, NULL, '222、阳明病，发热，面含赤色，不可攻之。攻之，小便不利者，必发黄也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120391, '4C75A359E97768D238C94DD7693470E4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5421, 320, 904000728, '     心下硬满是陷胸证，不可以用承气汤来攻下。如果误攻下以后下利不止，应当尽力用四逆或理中来救逆。  ', NULL, NULL, NULL, NULL, NULL, '221、阳明病，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120392, '888390D111751A92D51C7962D8AC9A25', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5422, 320, 904000726, '       阳明病，本自汗出，医更重发汗，病已瘥，尚微烦不了了者，此大便必鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，故知大便不久出。今为小便数少，以津液当还入胃中，故知不久必大便 也。', NULL, NULL, NULL, NULL, NULL, '219、阳明病，本自汗出，医更重发汗，病已瘥，尚微烦不了了者，此大便必鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，故知大便不久出。今为小便数少，以津液当还入胃中，故知不久必大便 也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120393, '3BFE4232FC52F625B8660911F686CE6C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5423, 320, 904000725, '       阳明热在张仲景把它分两个，第一经热，经讲的是血脉神经，热在血脉神经里面，第二腑热，肠子里面堵到的热，小肠、大肠、膀胱，就是消化系统堵到，不管是胆结石或大便堵到，腑热用的是承气汤，经热用的是白虎汤，阳明证只有这两个处方。  \n\n        口燥，就是嘴巴很干燥，代表津液不足了，但欲漱水，不欲咽者，想喝水，但是漱漱口又吐掉了，不想吞下去，吞又吞不下去，嘴巴又干燥，代表热不在腑上面，热在经上面，所以白虎汤证的病人，嘴巴都干裂了，舌苔却白白的，代表肠子里面没有堵到，完全热在血里面，这种发高热的时候，西医说是脑膜炎，这时侯热往上冲，会有流鼻血的现象，这鼻血一出来的时候，热就出来了，热会随衄好了。遇到这种情形的时候，不一定是流鼻血，也可能会是眼睛出血；例如有病人外证是皮肤流脓，湿热在上面，病人叙述口很渴，每天下午三点到五点就发高烧，喝白虎汤好了，皮肤也好了，因为热在血脉上，经热往下走，肺主皮毛，整个烧伤了，如果皮肤没有溃烂，而是热在脑里面，这病人早就昏倒了。  ', NULL, NULL, NULL, NULL, NULL, '218、阳明病，口燥，但欲漱水，不欲咽者，此必衄。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120394, '1B8C4C86C5F7ACBBEF8A5EF95FABF93F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5424, 320, 904000724, '       脉浮紧者，代表表实无汗，表太实了，毛孔都闭住了发不出来，因为汗没有办法宣泄，如果阳明证能够流汗，热就不会发起来，遇到这种情形的话，病人的主证是阳明证，病人一定会潮热，发作有时，这热是下午才会热，所谓的潮就是一阵一阵的来，下午三点的时候开始涨潮，到五点的时候最热，这热一直持续着，病人感觉热一阵一阵的来，像潮水一样的上来，如果是小柴胡汤的热是往来寒热，一下冷一下热，太阳证也会有忽冷忽热的现象，但浮者，必自汗出，这时候热有出来的话，阳明热就有地方宣泄。  \n\n      平常看到病人阳明证自汗，代表胃实，如果是阳明证，病人盗汗，就是胃虚。  ', NULL, NULL, NULL, NULL, NULL, '217、阳明病，脉浮紧者，必潮热，发作有时；但浮者，必自汗出。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120395, '44415E0BA56F518EF36E8AF4408A3A2A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5425, 320, 904000723, '      阳明病本来就是中焦过热，燥实，如果被火，就是用火去烤，可能被灸或遇到火灾，阳明病本来就是津液不足了，肠胃太热，一遇到这种情形的时候，额上微汗出，小便不利者，必发黄，阳明病本来就是燥热的病，再用火去竭汗，病人就会有这现象，像这种黄大多是因为津液少了，血里面的水不足了，隔着皮肤看到血液的颜色，可利用竹叶石膏汤，把血里面的津液补回去，热就会退掉，小便也会正常，小便不利就是根本没有津液了，头上还有一点微汗，表示胃里面还有一点津液，都从头上跑掉了。  ', NULL, NULL, NULL, NULL, NULL, '216、阳明病，被火，额上微汗出，小便不利者，必发黄。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120396, '6A559415A04EC36DBBB59B0AA2CF0F27', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5426, 320, 904000722, '      无汗的原因就是阳明病的热无法出表，阳明病应该是汗很多的，小便不利，湿太盛的时候，湿堵在腹腔的下方，湿像浆糊一样，很浓稠的挤压膀胱，所以没有汗代表热排不出来，小便不利代表里面湿热很盛，一般来说这种情形，在脉诊或舌诊上看得很清楚、里面热很盛的时候，舌苔一定是黄的，这代表热，舌苔很厚很腻，腐质比较多，这代表湿，舌苔里面黄的很厚，代表湿热在中间，中焦湿热太盛的时候，心中懊憹，胃里面糟糟的，吃东西吃不下去，因为热发散不出来，这时候身必发黄，因为三焦的运化系统不好，水道没有排出来，湿热在中间很闷，湿热会逆行到肝胆里面去，一进入肝，马上顺着血液跑到全身造成黄色，像这种用栀子豆豉汤去治疗他。', NULL, NULL, NULL, NULL, NULL, '215、阳明病，无汗，小便不利，心中懊憹者，身必发黄。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120397, '5FFDA4000D24EB957882CEA1B37923F2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5427, 320, 904000721, '       阳明病就是肠胃的问题，为什么张仲景讲不恶寒就是病在阳明，如果恶寒就是病在太阳或少阳，阳明证看不到怕冷的，故能食，所以肠胃的蠕动很正常。若咳，其人必咽痛，若不咳者，咽不痛，为什么要讲喉咙痛和喉咙不痛?因为人的胃气是上冲的，当胃气过热的时候，肺本身在胃的上方，肺在中医里是燥金，本来肺就已经很燥了、所以它可以分布水分到四肢，胃热再往上，肺的燥会增加，病人会咳嗽，热就是炎，也冲到喉咙，喉咙就会发炎，热一定要先经过肺才能到喉咙，所以肺要先咳嗽才会喉咙痛，肺都没有咳嗽就不会喉咙痛了，这咽痛完全是胃热引起的，所以胃如果蠕动得太快的时候就会有这种现象。  \n\n       阳明篇介绍很多，但是只有几个方子，因为肠胃的蠕动分不同的阶段，肠胃的蠕动如过太快或太慢会有哪些现象，临床上，只分虚、实、寒、热，第一看里面有没有堵到东西，有堵到就是实，没有堵到就是虚，还有寒热，蠕动快就是热，蠕动慢就是寒，马上可以辨出来。  ', NULL, NULL, NULL, NULL, NULL, '214、阳明病，但头眩，不恶寒，故能食；若咳，其人必咽痛，若不咳者，咽不痛。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120398, 'ABBEE1C93AD4065A70C2266E38D80ADE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5428, 320, 904000720, '        汗和尿同源，例如冬天天气寒冷的时候，衣服穿少些，小便量就会多，因为皮肤和外界的空气是相通的，皮肤毛孔受到空气的冷，就收敛起来，水一定要发散，发散不掉就会从小便排出来，如果夏天衣服穿得多，一定会流汗，小便就少了，所以汗和尿属同源；而现在阳明病应该汗很多，现在反无汗，而小便利，二三日呕而咳，阳明病一定没有呕，呕一定在少阳，咳是在太阳，手足厥者，必苦头痛；手脚四肢禀气于胃，所以手脚一冰冷的时侯，代表胃气不足了，虚掉了，所以手足厥者，代表胃气虚掉了，必苦头痛。胃气正常的，第一食物残渣往下走，吸收营养往头部走，所以吃东西第一头会流汗，如果胃气不足了，就是寒了，遇到这种情形的时候，病人的头会痛，这不是热气往上冲，而是寒气，寒气往上冲病人也会头痛，如果是热气往上升的话，病人是阙上痛，如果是寒的头痛，是整个头在痛；若不咳，不呕，手足不厥者，头不痛，不呕代表肠胃没有问题。  ', NULL, NULL, NULL, NULL, NULL, '213、阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳，不呕，手足不厥者，头不痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120399, 'FD62B4B33FBEC112FBAA87BC85D4F36A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5429, 320, 904000719, '         阳明病应该是汗很多，这流汗不是但头汗出，而是全身性的流汗，所以常常没事全身性的流汗就是阳明病，其它的病不会这样的流汗，现在反无汗、为什么？因为里面虚了，肠胃津液没了，其身如虫行皮中状者，此以久虚故也，胃里面的津液先到皮肤再到外面，但津液不足时，汗出了汗腺但是并没有离开毛孔，汗就停在皮肤表面下很痒，这种痒，让胃的津液一回来就没了，所以可用桂枝汤加黄芪。 \n\n       汪琥曰：阳明无汗证，仍宜用葛根汤主之，参考就好了，临证处方会变。  ', NULL, NULL, NULL, NULL, NULL, '212、阳明病，法当多汗，反无汗，其身如虫行皮中状者，此以久虚故也。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120400, 'BD424CD6D9D6286201B69A76EF7A398A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5430, 320, 904000718, '      阳明病是肠胃的问题，脉迟，就是胃虚掉了，若脉数，照理说就是里面发炎了，或肠里面堵到了，如果脉数，问有没有大便?答曰：有而且下利，就是他有虚热；食难用饱，吃一点就饱了，饱则微烦，头眩，必小便难，此欲作谷疸，造成这些现象大部分的原因是肝、胆、胰分泌的消化液不够，使肠胃的消化不是很好，肠胃就虚寒掉了，饱则微烦，胃里面的东西不能消化，吃下去的东西撑在胃里面，人会感觉到微烦。为什么会头眩?人吃东西后，营养第一供应到脑部，现在胃虚寒掉了，食物不能消化，没有营养供应头部，就会有缺血的现象，所以会头昏。消化系统不正常的时候，小便也会不正常，必小便难，这不正常不见得是量多 量少，可能次数多量少，或小便小几滴出来，消化不好，因为脾脏功能不好，湿会越来越盛，湿是往下的，一般来说湿会往下停在下焦，造成腹满，如果湿太多堵到了，小便自然会减少，如果小便很正常，代表湿有管道排掉，造成虚寒的原因就是里面湿太盛了，湿气太重了，湿堵在里面就全身发黄，就是谷疸，因为消化系统里面有肝、脾、胆的分泌液进来消化，现在肝脏和脾脏的功能都不好，脾主湿，湿就会越来越盛，功能不好的时候就是肿起来，虽下之腹满，攻下了就应该不会腹满，这腹满是脾脏的肿大，是湿堵在里面，脉会变得很缓，如果有这类肿的现象、病人一定会发黄，甚至可说发黄的病人必是中湿的。  ', NULL, NULL, NULL, NULL, NULL, '211、阳明病，脉迟，食难用饱，饱则微烦，头眩，必小便难，此欲作谷疸， 虽下之，腹满如故，所以然者，脉迟故也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120401, 'FEEE81047564B7B2588649E3D3C3A4E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5431, 320, 904000717, '       阳明病是肠胃科的问题，阳明病，不能食，阳明病不能吃东西了，代表胃不蠕动了，就是胃虚寒的时候，攻其热必哕，中药里所有攻热的药都是寒凉的，像白虎汤里的石膏、知母，其它如大黄、黄芩、黄连、茵陈、栀子、连翘、银花、薄荷、犀角等都是寒凉的药，胃本来就是寒了，再一攻就更寒了，就会哕，哕就是嗝气，哕在胃气将绝的时候会看到，因为胃刚好在膈的地方，平常胃的蠕动刚好跟着膈的蠕动，人自己没有感觉而已，呼吸的时候，横膈膜会上下，当吸气的时候，横膈膜降下去正好顶到胃。若一吸气横膈膜就反弹回来，就会一直在嗝，也就是寒凉的药把胃的蠕动减缓了。  \n\n       胃完全虚掉的时候，最重的用茯苓四逆汤，再轻的用理中汤，更轻的用吴茱萸汤，吴茱萸汤是治疗胃下垂，用理中汤已经是比较危险了，茯苓四逆汤是已经快挂了，胃里面不受五谷了才会用到。  \n\n     这条辨是讲千万不要把不吃东西就以为是阳明堵到东西，若不明辨寒热，一开寒凉的药造成病人打嗝，反过来说，吃到寒凉药会打嗝，就知道胃本来就是寒凉的。  ', NULL, NULL, NULL, NULL, NULL, '210、阳明病，不能食，攻其热必哕，所以然者，胃中虚冷故也，以其人本虚，故攻其热必哕。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616586408120402, '2841E0BF77E0614E621881E4EC550ABD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:16:33', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5432, 320, 904000731, '       脉迟，就是病邪往里面跑了，代表肠胃寒冷掉了，虽汗出，不恶寒，代表没有表证了，其身必重，脉迟、身重都是代表病邪往里面走了，病邪往里面走才会有脉迟的现象，短气，腹满而喘，有潮热者，此外欲解，可攻里也，这就是要攻里以前，要先确定病人有没有外证，如果病人有汗出，可是不恶寒，桂枝汤是有汗但怕冷，阳明热也是有汗，麻黄汤无汗怕冷有喘，这喘和腹满而喘的喘不一样，这几项讲的就是病人没有表证，且病人有潮热；病人有一、潮热，二、不恶寒，三、燥渴，四、腹满，这腹满是大便堵到的腹满，这四项就是阳明证的主证，为确定腹满要做腹诊，如果是实则拒按，譬如在胃的地方，喜按就是虚的，这虚证的腹满是脾脏的关系，属于太阴证。  \n\n       手足濈然而汗出，如果手脚汗已经出来了，就是胃的津液已经快完了，阳明证如果全身都有汗，就没有关系，但是如果胃的津液快没了的时候，剩一点点津液，只看到四肢手脚上出汗，就没有关系，但如果是胃的津液快没了的时候，剩一点点津液，只看到四肢手脚上出汗，然后病人有潮热，又没有恶寒，肚子又胀满，张仲景说遇到这种情形的时候，大便已经干掉硬掉了，从这些症状可以判断出来，大肠里面被燥屎堵到了，这时候就是大承气汤证。  \n\n       阳明证本来应该全身有汗，到后来只有手脚有汗，这时候胃已经燥化了，肠胃里面极燥，张仲景在用大承气汤的时候，一定是要等到肠胃里面的津液完全没了，造成大便干燥在里面，才会用到大承气汤，如果只是大便不通不会用到大承气汤，因为大承气汤很峻很强，如果大承气汤吃了还不大便，就是得到大肠癌，除非是寒实，否则没有不下的。  \n\n      若汗多，微发热恶寒者，外未解也，其热不潮，未可与大承气汤。全身都有汗，微发热恶寒者，这代表有外证，并不是很潮热，代表大便并没有结实在里面，不可以给大承气汤，若腹大满不通者，可与小承气汤，所以从这条辨可以看出张仲景的心态，一定要确定大便整个干燥的，才可以用大承气汤攻，如果潮热没有很厉害，大便没有鞕，用小承气汤就好了。  \n\n       临床上看小承气汤的腹满，在肚脐下，中极关元一带胀满，小承气汤专门通利堵在小肠里面的，如果进入大肠，会在天枢有压痛点，就用大承气汤，如果堵在中脘建里的地方，就是调胃承气汤，最常用到的就是调胃承气汤，譬如小孩会得到感冒，然后又吃了很不好消化的东西，免疫系统跑到皮肤表面去跟滤过性病毒相抗，这时候肠胃的功能在应付皮肤表面的滤过性病毒，所以大部分的能量都在上面，因而胃的力量减少了，就没有办法正常消化，东西就哽在里面，因为肠胃蠕动不是很好，有时候大便出来的是水，这水是漏出来的，因为肠胃没有吸收，所以从大肠跑出来，身体里面的温度很高，食物在里面容易坏掉，嘴巴很臭，遇到这种情形的时候要去解表不能攻下，就用桂枝汤，利用桂枝汤里面的甘草，再加一点点大黄，一点点芒硝，表里可同时解掉。', NULL, '大承气汤,小承气汤', NULL, NULL, NULL, '224、阳明病，脉迟，虽汗出，不恶寒，其身必重，短气，腹满而喘，有潮热者，此外欲解，可攻里也。手足濈然而汗出者，此大便已鞕也，$f{大承气汤}主之。若汗多，微发热恶寒者，外未解也，其热不潮，未可与$f{大承气汤}。若腹大 满不通者，可与$f{小承气汤}，微和胃气，勿令大泄下。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616588110942278, '99A3B9DB086C8FF73085B2EC5D8A0125', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:23:29', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5433, 320, 904000730, '       调胃承气汤是阳明病最浅的第一方，如果病人不吐，代表病人没有少阳证，不下，大便没有，又心烦，胃里面难过，情绪不稳定，过到这种情形的时候，可以给他调胃承气汤看看，大便可能堵在小肠，就是十二指肠下来，近小肠这一段，所以调胃承气汤就是堵在肠子，调胃承气汤里面有炙甘草、大黄、芒硝，芒硝攻坚破瘀，大黄去实，炙甘草让药停在肠胃里面，芒硝把它打散掉，大黄把它清出来，没有潮热、发汗、恶心、燥热，什么症状都没有，只是大便不下，就给调胃承气汤。', NULL, '调胃承气汤', NULL, NULL, NULL, '223、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616588110942279, '8E03015E84FD1747A8727497B4C69CF9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:23:29', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5434, 320, 904000745, '      脉浮而紧，代表的是有表证、表寒，\n      咽燥口苦，肠胃里面太热，喉咙就干燥了，照理说胆汁应该往下走，遇到肠胃里面太热了，胆汁就逆行往上，就会口苦，\n      腹满而喘，有可能是太阴的湿证胀满，也有可能是大便堵到的胀满，\n      发热汗出，有表证，但是病人又不恶寒，但恶热，身重，只有湿很盛的时候，病人会身重，遇到这种情形，表示太阳、少阳、阳明都有了病，\n      若发汗，则燥，如果发汗，只去太阳，就没管到少阳、阳明，发汗后会燥，因为里面已经有阳明证，这时候小柴胡汤最好，\n      愦愦及谵语，不但燥而且谵语；\n      若加烧针，必怵惕烦躁不得眠，如果烧针，津液丧失会很多，血里面会更热，会燥不得眠，\n      若下之，则腹如故。小便难也，攻下的时机一定要确定大便结实，现攻下后腹如故，就是攻太早了，因为他并不是真正大便结实，结果把津液都攻出来了，小便就没有了。\n\n如果临床上遇到不得已的情形，有本条的症状但又必须攻下的时候，可以在攻下的时候，加上一些固阳的药。', NULL, NULL, NULL, NULL, NULL, '239、阳明病，脉浮而紧，咽燥口苦，腹满而喘，发热汗出，不恶寒，但恶热，身重；若发汗，则燥，愦愦及谵语，若加烧针，必怵惕烦燥不得眠；若下之，则腹如故，小便难也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391430, 'C6A9BCEF775506D2E0621B604DF5A9AE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5435, 320, 904000744, '如果确定没有太阳证的时候，就可以攻下了，再不攻下就会潮热，手足漀漀汗出，大便难而谵语者，这就已经很危险了。  ', NULL, '大承气汤', NULL, NULL, NULL, '238、二阳并病，太阳证罢，但发潮热，手足漀漀汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391431, '6FFB654CA6FD04AC8D4392885EE90737', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5436, 320, 904000743, '       三阳合病，腹满，身重，难以转侧，就是湿很重，腹满，肚子胀满，怎么知道肚子里面有没有大便?有的时候湿很盛，太阴证肚子也会胀满，只有两个地方肚子会胀满，一是太阴肚子会胀满，肚子湿很盛，二是阳明实证肚子会胀满，肚子堵到大便，口不仁而面垢，嘴巴吃东西没有味道，面色看起来好黑，好像几天没有洗脸，灰尘一片，遇到这种情形的时候，谵语，病人会有谵语的现象，就代表病人是阳明证了，发汗则谵语甚，本来谵语只是讲几句话，一发汗，谵语更严重了，遇到这种情形的时候，攻下，结果病人额上出汗，手足厥冷，遗尿，这都是被攻下，津液被伤到了，就叫做阴虚了，阴就是肠液，这时候手脚冰冷，手脚的温度从肠胃来的，冬天的时候，手脚冰冷，食物吃下去，第一个感觉就是手脚温起来了，病人有遗尿的现象产生就很危险了；这就是说要确定病人里实了，才可以攻下，他三阳合病，并不代表里面结实，如果三阳合病，和解是独取少阳，小柴胡就解掉了；若自汗出者，白虎汤主之，病人自己会流汗，代表并没有完全虚掉，津液伤到的时候，产生烦躁的时候，这津液就是血里面的水，肠里面的水，最好补津液回去的，就是白虎汤，生小孩，生完后得白虎汤证，因为生的时候，汗流好多，生完小孩出来脸都黄的，因为津液伤太多了，水分不够了，这时候病人大多很热，真正吃白虎汤是汤剂，白虎汤里面的粳米把肠胃里面的黏液补足，靠石膏知母把血里面的水补足，还可以再加些人参在里面，所以心下痞、肠胃科、救逆的药里面一定会用到人参，张仲景的观念，人参的药性非常的阴柔，阳绝的时候，不可以开阴药，要用炮附、干姜、炙甘草等热药，如果加人参会阻碍药力，茯苓四逆汤里面有的人参，因为茯苓四逆汤是用在阴虚症了。  ', NULL, '白虎汤', NULL, NULL, NULL, '237、三阳合病，腹满，身重，难以转侧，口不仁而面垢，谵语，发汗则谵 语甚；下之，则额上出汗，手足厥冷，遗尿；若自汗出者，$f{白虎汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391432, '03FB720F8E59071ACFE9D07B6DA11300', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5437, 320, 904000742, '       照理说伤寒的时候，脉应该浮而紧，代表表寒，结果摸他脉的时候，脉沉而喘满，病人看起来是喘满，照理说麻黄汤证是喘证，肺跟皮毛是相表里，因为伤寒的时候，寒束在皮毛上就等于束在肺上，所以麻黄汤证的病人会喘，呼吸不过来，胸口胀满，一点汗都没有，脉一定浮，轻轻摸在皮肤表面，就摸到脉很强的弹上来，但是脉沉而喘满，沉为在里面，就不是麻黄汤证，沉就是病在里，攻下就好了，小承气汤就可以了，结果反发其汗，津液越出，大便为难，结果反发他的汗，大便就更难了，发了汗之后就变成表虚里实，久则谵语，这种症状就变成表虚里实，这症状拖久了就变成谵语了，久，有时候四五天或一个星期。这条辨就是说，要确定有表证才可以发汗，没有表证一发汗，本来没有承气汤证就变成承气汤证。 ', NULL, NULL, NULL, NULL, NULL, '236、伤寒四五日，脉沉而喘满，沉为在里，反发其汗，津液越出，大便为难，表虚里实，久则谵语。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391433, '720B30996BAD6BF69F6FD8483AA7EBA6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5438, 320, 904000741, '       流汗，汗出来很多，此为风也，风就是热，这里的风当然热，不要当桂枝汤的中风，所以多汗的人，没事汗流浃背的人，其体有热，有的人汗流的很少，就是体有寒，\n      谵语者，如果病人已经胡说八道了，又流汗很多，就可以确定有干燥的大便在肠里面，张仲景讲的胃就是讲肠，这就是表虚里实故也，\n      须下之，下之则愈，宜大承气汤。过经乃可下之，下之若早，语言必乱，这就是讲要用大承气汤之前要确定病人没有表证，因为大承气汤走的很快，大概喝下去十分钟，芒硝就到肛门了，它把血往下导，所以大承气汤一下，整个血往下降，所以高热会退下来，如果有表证，一喝大承气汤，滤过性病毒会很快的从皮表进来，结果大便出来会引起后遗症，所以下之若早，语言必乱，就变成谵语了，本来是实的就会变成虚证。  ', NULL, '大承气汤', NULL, NULL, NULL, '235、汗出，此为风也，谵语者，以有燥矢在胃中；此表虚里实故也，须下之，下之则愈，宜$f{大承气汤}。过经乃可下之，下之若早，语言必乱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391434, 'D745DE9F7EE86CCDD20900F25673E840', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5439, 320, 904000740, '        阳明病，如果病人大小便带血，谵语，就是热入血室，热入血室在小柴胡汤的时候有介绍，整本伤寒论里面，就小柴胡汤证和阳明热的时候有谵语，为什么大便下血的时候，会有谵语的现象？男人也会有，本来大便里面带血，有痔疮或跌打瘀血的时候，就像女人月经来的时候，结果刚好得到感冒，血往下走，滤过性病毒进来，如果滤过性病毒顺着淋巴系统进入肠胃，这病毒就转化成热，这时候也会有谵语的现象，女人最多的就是月经中间得到感冒，所以如果月经来的时候得到感冒，就先给小柴胡汤断后，不要等到谵语的时候才吃，要先给小柴胡汤，有表证再去解表，张仲景说月经来的时候，谵语，这时候小柴胡汤已迟，就要下针期门，所以常见女的病人本是桂枝汤证，刚好逢到月经来潮的时候，就小柴胡汤和桂枝汤并用，一起解掉。有时候解表，刚好月经来，解完表，开始谵语，就是热入血室了。  ', NULL, NULL, NULL, NULL, NULL, '234、阳明病，下血，谵语，此为热入血室，但头出汗者，刺期门，随其实而泻之，濈然汗出而愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391435, 'BDB8F3ECDF6C27C0B5D9106E05152D5B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5440, 320, 904000739, '      如果有潮热，谵语，不能吃东西就给他大承气汤，如果能吃东西，大便不通就是小承气汤，这是用饮食胃口来确定大小承气汤，所以只要问他能不能吃东西，只要胃口还在就用不到大承气汤。除了硬以外，大便如鞕也是小承气汤证，因为肠子里面有燥屎堵到，大便经过的时候，变成细细长长的，像鞭子一样；大承气汤是完全堵到了，根本没有东西出来了。  ', NULL, '大承气汤,小承气汤', NULL, NULL, NULL, '232、233、阳明病，谵语，有潮热，反不能食者，宜$f{大承气汤}下之，胃中必有燥屎五六枚也；若能食者，但鞕耳，宜$f{小承气汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391436, '9E099C8282895A8B41A2F7826E7F5FB8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5441, 320, 904000738, '      如果病人即使发谵语，发潮热，还没有到循衣摸床，还用不到大承气汤，如果脉滑而虚者，小承气汤主之。  \n\n       脏有结则脉滑，脏即肠有东西堵到了脉会滑，如何区分；有时候小孩会有滑脉，也表示肺里面有痰，痰很盛的时候，也会把到滑脉，肠胃里面有宿食，也会摸到滑脉，何谓滑脉? 感觉血管里面的血走的很急，不是上下走。  \n\n        如果脉滑而虚者，小承气汤主之；应与承气汤一升，汤入腹中转矢气者，小承气汤吃到 肚子里面以后，肚子里面转成矢气，开始放屁了，就是对证了，这时候再给他小承气汤，若不转矢气，勿更与之，如果吃了小承气汤，没有放屁，就不要再给了，等一下再看看，明日不大便，脉反微涩者，到第二天还是不大便，摸到脉变得微小很细，这就是里虚者，为难治，因肠中空无一物，很难治，最严重的里虚用四逆汤，再浅的理中汤。  ', NULL, '小承气汤', NULL, NULL, NULL, '231、阳明病，谵语，发潮热，脉滑而虚者，$f{小承气汤}主之，因与承气汤一升，汤入腹中转矢气者，更服一升；若不转矢气，勿更与之。明日不大便，脉反微涩者，里虚者，为难治，不可更与承气汤也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391437, '2E98BA48D513C7D25A1DE4C0A4096B7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5442, 320, 904000737, '       有阳明证的人本来汗就流的很多，津液外出，胃中燥，不单单指胃，肠子里面都没有津液了，大便必鞕，大便一定很硬，鞕则谵语，大便硬一定有谵语，就小承气汤主之，如果服了小承气汤，谵语没了就不要再服了，攻下的药不要攻太过，大便攻出来就好了。  ', NULL, '小承气汤', NULL, NULL, NULL, '230、阳明病，其人多汗，以津液外出，胃中燥，大便必鞕，鞕则谵语，$f{小承气汤}主之。若一服谵语止，更莫再服。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391438, '8E7EF242557AF6068878C4C5002666BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5443, 320, 904000736, '       本来是伤寒，表证而已，被吐、被吃了下药或吃坏肚子，结果里虚掉了，\n       不解，就是不大便五六天了，因为大肠里面干掉了，\n       日晡所发潮热，就是黄昏的时候，病人开始发潮热了，病人不恶寒，阳明证是看不到寒证，临床的时候，问病人怕不怕冷？怕冷，阳明证已经不考虑了，热的要死就是阳明证，阳明无寒证，不恶寒就是阳明证，\n       独语如见鬼状，一个人讲话，就好像看到鬼，如果严重的时候，发则不识人，发起惊狂的时候，人都不认得了，两眼直视，这是阳明燥热，为什么？大肠里面整个干掉了，津液没有了，因为被发汗被吐下，大便干掉以后，燥气上冲，大便的浊气顺着肠子进入血管，跑到心脏，跑到脑去了，所以发狂，人都不认得了，其实只是大便的浊气而已，\n      循衣摸床，循衣就是折衣服，然后沿着床边摸着走，\n     惕而不安，微喘，直视，到这种症状很危险了，如果脉弦者生，涩者死，弦是实证，涩是虚证，实代表东西堵到了，虚的就是血不足了，很危险的，会死，微者，但发热，谵语者，大承气汤主之，比较轻微的，只有看到发潮热、谵语的，赶快下大承气汤，到病人循衣摸床，手足躁扰的时候，再喝大承气汤，就一翻两瞪眼了，大承气汤是最严重的才用。  \n\n例：照理说承气汤是走大肠的，临床上可见承气汤下去的时候，病人还没有上厕所，人就清醒过来了，烧就开始退了，精神就好起来了。  ', NULL, '大承气汤', NULL, NULL, NULL, '229、伤寒，若吐，若下后，不解，不大便五六日，日晡所发潮热，不恶寒，独语如见鬼状；若剧者，发则不识人，循衣摸床，惕而不安，微喘，直视；脉弦者生，涩者死。微者，但发热，谵语者，$f{大承气汤}主之，若一服利，止后服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391439, 'E8300AF860A9A3E04734E5E016D70212', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5444, 320, 904000735, '       病人平常没有病的时候，汗很多，一直在流汗，表示病人本身就是阳虚自汗的人，发汗很多，若重发汗者，如果遇到这种人，你开重发汗的药，结果亡其阳，亡其阳者轻者昏眩，如果汗伤的比较轻的，病人头会昏，如果发的比较重的时候，重者惊狂，所以如果不该吃麻黄汤的时候，却大剂的喝下去，病人就会发狂奔走，古人就是有这过失，所以南派的医生麻黄不敢用，用一分二分的，亡阳就是流汗、体能流失掉了，谵语，脉短者，死，汗丧失太多， 津液伤到的时候，病人有脱水的现象，如果病人谵语，脉短促，代表津液不能回头了，救不回来了，如果脉自和者，脉很正常，脉还是一息四至，代表津液会慢慢回来，就只有这一条辨，倪子赞成打点滴，但仍须配合大剂的独参汤。  \n\n        如果看到病人讲话都讲不清楚了，又一直在下利，代表人虚的肛门都收不起来了，已经差不多了，肠子完全没有蠕动，所以练功夫的时候，要提肛，小便的时候，小完以后，最后再把肛门提起来，用力再小最后一滴，相书云小便小的很直流的就是一辈子贫穷到老，如果小便散开的大富大贵，所以为什么大肠和肺是表里的，所有排泄出去的力量就是靠肺气往下降。  ', NULL, NULL, NULL, NULL, NULL, '228、发汗多，若重发汗者，亡其阳；谵语，脉短者，死；脉自和者，生。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391440, '472227112AA83D3F09BEA6C81D013DC9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5445, 320, 904000734, '      这就是阳明证的两个死证，阳气就是人的动能，就是心脏的力量、肠胃蠕动的力量、所有内脏的动能。阳气将脱的时候，阳往上走，病人会直视、谵语、喘满，会眼睛瞪直不动，不能躺下来，谵语，临床上看到的时候，病人有癌症、肝癌、大肠癌等，看他脸红红的，不能睡觉，人将死的时候，阳气一直上走，阳浮在上面，阴沉在下，病人的眼睛一直瞪得大大的，连眨一下都不会，因为人的所有精力全部要耗掉，才死；人的水、津液，就是阴，阴液将亡的时候，病人也是直视，谵语，但是病人下利，也是死证，张仲景为什么提出来?平常如果是承气汤证，大便不通引起的谵语，病人也会直视，捻衣摸床，发狂，但是病人不会下利，意思是说应该是堵塞到了，应该是没有大便，结果下利，表示津液竭了，就非常的危险了。  ', NULL, NULL, NULL, NULL, NULL, '227、谵语，直视，喘满者，死；下利者，亦死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391441, '4B342357F668B5A8985AB4A8AEAB6A16', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5446, 320, 904000733, '什么叫做谵语?就是胡说八道，属实证， 谵语有以下的症状： \n\n（一）卧榻侧，如见鬼：就是床旁边看到有鬼，别的地方都看不到。 \n\n（二）骤见刀兵水火：有人拿刀要杀他。 \n\n（三）途遇蛇虎：走在路上，忽然不要走过去，说有老虎。 \n\n（四）似梦似醉：看起来好像清醒，又好像在作梦。  \n\n（五）惊呼号叫。  \n\n以上这几种现象中医统称谵语，所以谵语不只是胡说八道。\n\n什么叫做郑声?讲话反复重复，这是阳明的虚证，肠里面虚掉了，也就是空无一物，在极虚的时候病人会有郑声， 郑声的症状表现： \n\n（一）忽在通衢：忽然感觉人在马路上。 \n\n（二）忽浮大海：忽然感觉前面荒凉一片。 \n\n（三）恍惚变迁：一直在交待事情。 \n\n（四）欲回不得：可以感觉病人想跟你沟通，但是病人都没有办法回神。  \n\n（五）口中呶呶不休：不是唠叨不休，是一直一直在讲话，又讲不清楚自己在讲什么。\n\n 所以中医用听的，也可以知道病人的虚实。  ', NULL, NULL, NULL, NULL, NULL, '226、夫实则谵语，虚则郑声，郑声，重语也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391442, '6767247C084B52BABAF0D7E714238071', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5447, 320, 904000732, '       阳明病，潮热，大便已鞕者、大便已经结硬了，潮热一定是下午开始热，严重的时候二十四小时都在热，这时候一定要确定大便已经结硬了才可以给大承气汤；\n      不鞕者，不可与之。鞕把它当成硬，大便并没有结硬的不可以给大承气汤，承气汤都是所谓的热实，承气汤的病人脉一定很数，发热，舌苔黄的，甚至严重到黑，\n      不大便六七天了，怎么知道他有没有燥屎?张仲景就说少与小承气汤，先给他吃少少的小承气汤看看，\n      汤入腹中，转矢气者，一吃到胃里面的时侯，大便还没出来，但是放屁了，此有燥屎，乃可攻之，这代表里面有燥屎了，这时候可以攻，这时候小承气汤再喝下去，\n      若不转矢气，如果小承气汤吃了没有放屁，此但初头鞕，后必溏，只是刚开始的大便硬的，硬的大便被小承气汤攻出来以后，后面出来的大便会像泥浆一样，不可攻之，这时候不可以攻，如果大便是先鞕后溏，就是大便不结条，整个散开来的，就是里面湿很盛，这时候不要攻，湿会很盛是脾脏来的，因为脾主运化，所以食物吃进去消化然后排出大便，这排的力量都是靠脾脏，肠里面黏液的根源就是来自脾脏，脾脏功能运化不好的时候就看到大便是溏的，攻下的药都是寒凉的药，一攻下，寒与湿一结就腹满，就不能吃东西了，一喝水就打嗝，因为水是寒的，这条辨张仲景是说确定热实不通才可以攻，里面有湿的时候不可以攻下。  ', NULL, '大承气汤,小承气汤', NULL, NULL, NULL, '225、阳明病，潮热、大便已鞕者，可与$f{大承气汤}；不鞕者，不可与之。若不大便六七日，恐有燥屎，欲知之法，少与$f{小承气汤}，汤入腹中，转矢气者，此有燥屎，乃可攻之，若不转矢气者，此但初头鞕，后必溏，不可攻之，攻之必胀满，不能食也，欲饮水者，与水则哕。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616841269391443, '3AB9D9A1A1CCDFB97120B4DA52A86545', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 10:33:35', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5448, 320, 904000756, '    如果病人阳明病，又兼有脉浮，无汗而喘者，喘就是伤寒，麻黄汤证，就需要发汗，发汗则愈，宜麻黄汤，249和250这两条辨讲的就是，在阳明病攻下前，如果病人确定有表证，一定要先解表后再攻下。  ', NULL, '麻黄汤', NULL, NULL, NULL, '250、阳明病，脉浮，无汗而喘者，发汗则愈，宜$f{麻黄汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720646, '8B11C42B559C81225602BEC5AF17BE9E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5449, 320, 904000755, '       如果不管表证，病人脉迟恶寒，一般来说会判断这病人里虚掉了，脉迟就是虚了，汗出乃表不固，现在阳明病的人，本身再带有脉迟，汗出多，微恶寒者，这些症状，就是表未解也，可发汗，可以发汗，平常阳明病是不可以发汗的，阳明病本就是因为津液少了，造成高热、大便硬掉了，现在阳明病在有表证的状况下，还是需要给他发汗，要先解表再攻里。  ', NULL, '桂枝汤', NULL, NULL, NULL, '249、阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜$f{桂枝汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720647, 'DC663B1447E9EA4B6B2BABF32CC832B6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5450, 320, 904000754, '      阳明病的人必会自汗，医师不明却又给他发汗剂，津液就伤到了、小便又出的很多，就代表水分没了，这时候大便虽鞕不可攻之，这条辨讲的就是，病人如果里虚了，绝对不要去攻下，所以临床上蜜煎导法大多用在病人很虚弱的时候，因为虚弱没有能力把大便排出来，蜜煎导法为协助大便用的，大猪胆汁很难弄，用甘油锭也可以，甘油锭和蜜煎导法一样。  ', NULL, '蜜煎导,土瓜根,大猪胆汁', NULL, NULL, NULL, '248、阳明病，自汗出，若发汗，小便自利者，此为津液内竭，虽鞕不可攻之，当须自欲大便，宜$f{蜜煎导}而通之，若$f{土瓜根}及$f{大猪胆汁}皆可为导。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720648, '9285B930D6148C906080EF7BCC0D5BED', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5451, 320, 904000753, '       阳明中风，是热证，脉弦浮大，一般来说，浮是太阳的脉，弦是少阳的脉，大是阳明的脉，代表少阳太阳阳明都有了，\n       病人有短气的现象，呼吸比较急促，腹满，胁下及心痛，肚子胀满，胃又难过，久按之气不通，按下去又没有放屁，大便不通，鼻子是断生死的地方。鼻子上的油代表我们的生命，鼻干不得汗，就是鼻子都没有油了，就很危险，\n     嗜卧，一身面目悉黄，全身都发黄了，小便难，有潮热，时时哕，这病人很惨了，耳前后肿，刺之稍瘥，代表扁桃腺发炎或淋巴系统肿大、腮腺炎，就刺它，放一点血，\n    病过十日，外不解，脉续弦者，与小柴胡汤，大部分是小柴胡汤证，\n    脉但浮，无余证者，与麻黄汤，如果脉是浮的，没有其它里证，就是麻黄汤证，就是解表。  \n\n        若不尿，腹满加哕者，小便没了，肚子又胀满，东西又吃不下，吃下了又打嗝，腹满就是腹水了，腹水加哕嗝就是肝癌的末期，很多癌证末期都如此，肚子肿大，东西又吃不下，压肚子又不会放屁，小便又没了，肚子一直肿起来，遇到这种没有胃气了，已经打嗝了，都是死证，肝癌和肝硬化不一样，但是症状是一样的。  \n\n        肝癌初期还可以治疗，中期就没有办法了，在治疗如水进入肺的时候，可采隔日用十枣汤排水，如果每天排水会死在十枣汤上，再开健脾整胃的药。  \n\n       为协助他肠子能通润，开柏子仁，因为怕他没有力量排出来，又没有体力承受承气汤，所以用仁剂，肝癌里面一定有热，所以加黄芩，所有的癌证到末期，病人会血虚，所以加当归，因为要健脾胃，所以加白朮、茯苓，虚寒的时候有打哕的现象，所以加炙甘草，基本上是用这方子，如果黄疸很高，如果是热用茵陈蒿汤，如果热在上焦，痰很多，舌苔也是黄黄的就加栀子，这些都是治疗肝癌的药，以上是主要的方子，临证再加减，例如有表证，就加桂枝、白芍，如果胸满就把白芍拿掉，痰多的就多加点杏仁、桔梗。\n\n    健胃整脾汤方  \n\n柏子仁    黄芩    当归    白朮    茯苓    炙甘草  \n\n        治疗的时候，用十枣汤把水攻出来，水再回来就没有那么多了，如果小便通利，都没有腹水了，这病人就救回来了，救回来以后，想要让他再快一点好，加了南派的药，像娱蚣、血竭等，结果病人被攻死了，因为病人血虚了，药里面有很多破瘀的，但那是伤科用的，让病人自己慢慢恢复比较好，因为血已经虚了，硬去攻，死的更快，结果病人是死在贫血上。  \n\n        十枣汤在三个小时内就把水排掉了，排掉了后马上吃健脾的药，平常三餐饭前吃，然后正常的饮食，水来的时候，再用十枣汤攻，百分之九十九的肝硬化、腹水的病人都可以救回。  \n\n', NULL, '小柴胡汤,麻黄汤', NULL, NULL, NULL, '247、阳明中风，脉弦浮大，而短气，腹满，胁下及心痛，久按之气不通，鼻干不得汗，嗜卧，一身面目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之稍瘥。病过十日，外不解，脉续弦者，与$f{小柴胡汤}。脉但浮，无余证者，与$f{麻黄汤}。若不尿，腹满加哕者，不治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720649, '4895BBE8091D36F09902654E55E858BD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5452, 320, 904000752, '       不大便而呕，阳明证没有呕的，有恶心的现象就是少阳证，舌上白苔者，可与小柴胡汤，阳明证的舌苔是焦黄的，上焦得通，津液得下，胃气因和，身濈然而汗出也，所以有的人便秘不是承气汤证，吃承气汤没有用，结果是小柴胡汤证，不管大不大便，只要他有一少阳症状就要先和解少阳，所以有时候是小柴胡汤或大柴胡汤把便秘治好的。  ', NULL, NULL, NULL, NULL, NULL, '246、阳明病，胁下鞕满，不大便而呕，舌上白苔者，可与$f{小柴胡汤}，上焦得通，津液得下，胃气因和，身濈然而汗出解也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720650, '06B402A4CDDE5AE9D9EE072446F80842', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5453, 320, 904000751, '        阳明病，发潮热，就肯定胃实了，大便溏，小便自可，大便还是有，小便也可以，就知道病人不是阳明的燥实，不见得要阳明药燥实才会有潮热的现象，胸胁满不去者，小柴胡汤主之，这条辨张仲景就是要说，阳明证攻下的时候，一定是纯阳明证，如果兼有少阳的时候，胸胁苦满，就要先和解少阳，不要随便攻下，像胸胁苦满、往来寒热、口苦咽干、恶心，就是少阳，滤过性病毒的邪在三焦淋巴系统里面，像腮腺炎就是小柴胡汤证。', NULL, '小柴胡汤', NULL, NULL, NULL, '245、阳明病，发潮热，大便溏，小便自可，胸胁满不去者，$f{小柴胡汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720651, '4A52D9AD699CCD126E0063735CE926CE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5454, 320, 904000750, '    热在中焦，所以用栀子豉汤，如果热在上焦的时候，用去中焦或下焦热的药都不会好，所以要分上、中、下。如果结胸的话就是大小陷胸汤', NULL, '栀子豉汤', NULL, NULL, NULL, '244、阳明病，下之，其外有热，手足温，不结胸，心中懊憹，饥不能食，但头汗出者，$f{栀子豉汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720652, 'D77B16B9F63284864C7F922D836D54F2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5455, 320, 904000749, '       登革热一发烧就死掉的，西医说是出血性的死亡，因为血太热了，一热，热会往上，脑部里壮热，烧没有办法退掉的时候，血管会破裂，就死掉了，脑膜炎也是这样死掉的，热到达血管让血管破掉，有一种情形，如果本来身体很好，一流鼻血热就退掉了，流鼻血都来不及退掉就很危险，所以登革热高烧就是白虎汤，脉浮，发热，口干，鼻燥，能食者，则衄。口干就代表津液干掉了，能食就是肠胃功能很好，免疫系统很强，此种人一流鼻血热就解掉了。  ', NULL, NULL, NULL, NULL, NULL, '243、脉浮，发热，口干，鼻燥，能食者，则衄。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720653, '54E134892B5465F17E9BE083732F2A0D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5456, 320, 904000748, '        脉浮而迟，表虚掉了，结果病人表热里寒，下利清谷者，完全里虚掉了，大便出来清谷，就是吃什么拉什么就是什么，则四逆汤主之，如果若胃中虚冷，不能食者，饮水则哕，喝了水就会打嗝，因为水是寒冷的，所以一般打嗝都是寒凉的，平常在治疗哕证用茯苓四逆汤，哕证还没有到很危险的时候，即用茯苓四逆汤，里面的人参能去心下痞，茯苓能把寒水利掉，干姜、炙甘草等热药，能把胃、脾脏的功能恢复。  ', NULL, '四逆汤', NULL, NULL, NULL, '242、脉浮而迟，表热里寒，下利清谷者，$f{四逆汤}主之。若胃中虚冷，不能食者，饮水则哕。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720654, 'DDDF3DE97CB2626A5442ADADFF826638', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5457, 320, 904000747, '      这人本来津液就不够了，渴就代表津液不够了，猪苓汤是利水的，水再利掉会燥热、发烧，因为汗多胃中燥，所以汗的来源是肠的津液，猪苓汤再利小便会加速失水，本来口渴缺水而已，猪苓汤一下去，就变成脱水了。 ', NULL, '猪苓汤', NULL, NULL, NULL, '241、阳明病，汗出多而渴者，不可与$f{猪苓汤}，以汗多胃中燥，$f{猪苓汤}复利其小便故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720655, '933D3F65BB013A484408221DF7BB16B2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5458, 320, 904000746, '        中焦燥热的时候用栀子豉汤，栀子豉汤是对中焦火盛，所以心中懊憹，舌上胎者，宜栀子豉汤主之。\n       若渴欲饮水，口干舌燥者，嘴巴很口渴，喝水又不能止渴就知道津液伤到了，所以白虎加人参汤，能止渴，有些上消糖尿病的，喝了水，小便就跑掉了，因为水不能进入血里面，血里面的水不够就燥渴，燥渴喝了水又不是进入血里面，血里面的浓度越来越高，糖的浓度就会增加，所以白虎汤加人参汤一下去，血糖就下来了，白虎加人参汤就是热伤上焦，对上焦的热；若脉浮发热，热除了发高烧以外，还有发炎，身体里面发炎了或伤口化脓也会摸到脉浮发热，以为是伤寒表证，结果不是，这时候病人渴欲饮水，小便不利的现象，就是喝了水小便又下不来，滴滴答答的，这时候张仲景说猪苓汤主之，白虎加人参汤证的是喝一碗水小便一碗。  \n\n        所以上焦热是白虎加人参汤，中焦是栀子豉汤，下焦热是猪苓汤，热把它当作炎的话，里面有石头肾结石、膀胱结石，小便的时候石头把输尿管刮破了，里面发炎了，还有性病，小便小不出来，小便的时候会赤痛，尿道炎都是用猪苓汤。  \n\n      猪苓汤和五苓散里面都有猪苓、泽泻、茯苓，但猪苓汤特别重用猪苓，猪苓专门是利下焦的水，猪苓、茯苓、泽泻这三味都是利尿的，肾结石不是只有一颗，结石里面有很多，像沙一样，只是比较大的一颗堵到了。所以小便不利，西医开刀只去大颗的，小的又没去掉，所以加滑石让石头跑的比较快，因为石头不是光滑的，会把管子刺破，所以加阿胶止血，小便出来，石头也出来了，血也止掉了，在复溜穴一带可以找到压痛点，就在痛点下针，扎下去会感觉到有东西在跑，刺下去就不痛了，再去熬猪苓汤。  \n\n        脸部水肿，如果没有其它的症状，精神还很好，五苓散就去掉了，五苓散就是用在表水没有办法回到肠胃里面，吃了发汗药以后，让肠胃的津液把滤过性病毒推出去，推出去以后，脏的津液流汗流掉了，好的津液还要慢慢顺着三焦油网流回胃，如果水没有力量回头，停在表面上，这时候病人口渴，因为肠里面的津液都发到表上去了，第一个出现的是小便不利，皮肤表面的水没有办法流回去，用五苓散去收水，如果光是下焦肿，就是猪苓汤证，如果只是四肢肿或头肿，大多是五苓散证，因为五苓散有桂枝。\n', NULL, '栀子豉汤,白虎加人参汤,猪苓汤', NULL, NULL, NULL, '240、阳明病，心中懊憹，舌上胎者，宜$f{栀子豉汤}主之。若渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。若脉浮发热，渴欲饮水，小便不利者，${猪苓汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 616944413720656, 'B08041350A5014AE1B69D012407FB0DA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:33:17', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5459, 320, 904000758, '       平常阳明证，病人发狂奔走，已经全无意识了，其人善忘者，$m{灵枢第八十篇大惑论}：$n{上气不足，下气过实，其人善忘}，平常有阳明证，常常东西记不清，年龄大的人，善忘可能被西医判定为老人痴呆证，刚刚讲的可能马上忘了，最近的事都忘了，可是很久以前的事会记得，如果是大承气汤就攻大承气汤，如果是抵当汤就攻抵当汤，这条辨就是说善忘就是必有蓄血，一定有瘀血瘀在里面，所以然者，本有久瘀之血，故令善忘；矢虽鞕，大便反易，其色必黑，大便颜色黑了代表有瘀血，从舌证上看，舌上有青紫色的，就是舌头全红而且有青紫色的瘀点，表示体内有瘀，有点白苔在舌头上才正常的。前面提过的三阴交穴压痛、舌苔齿痕明显、渴而不欲饮水，都可以用来诊断是否内有瘀血。  \n\n     如果病是太阳蓄血，血蓄在膀胱里面，就是桃核承气汤，如果是阳明蓄血，蓄在肠胃里面，就是抵当汤，如果胃出血，西医灌流质入胃里面，一直洗胃，西医治疗完后，大都变成抵当汤证了，因为血干燥在里面，如果是大便干燥用芒硝一打就碎了，如果是血块，芒硝打不下来，就要用虻虫、水蛭才打得出来。  \n\n张隐庵曰：太阳蓄血，验其小便；阳明蓄血，验其大便；不用桃仁而用抵当者，以久瘀故也。', NULL, '抵当汤', NULL, NULL, NULL, '252、阳明证，其人善忘者，必有蓄血，所以然者，本有久瘀之血，故令善忘;矢虽鞕，大便反易，其色必黑，宜$f{抵当汤}下之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617185768816710, 'AF91AB7BA792F98DAE4AE1CEDB86BE96', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 09:55:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5460, 320, 904000757, '       一定是肠子里面热很盛才叫阳明病，如果病人有发热汗出，此为越热，就是热有地方渲泻，流汗出来了，就不会发黄，\n       如果但头汗出，身无汗，剂颈而还，就是只有头流汗，脖子以下都没有汗。\n       小便不利，重点就是小便不利，因为小便堵到了，热没有地方渲泻，汗又流不透，只有头上有汗，\n       所以渴饮水浆者，此为瘀热在里，身必发黄，因为脾湿太盛了，阳明证的时候，胃、大肠就是属于阳明，病人一定是阳明过热，热气一直往上冲，第一个受到的一定是头。所以如果病人有燥屎，就会阙上痛，胃气往上走，胃里面一定空掉了，胃一空掉。脾就过来了，脾湿堵在中间，湿一堵到的时候，小便就出不来了，脾脏之湿太过了，食物没有办法完全运化，大便又堵在里面，宿食没有去，湿又很盛梗在中焦，湿一盛，水就不好渲泻出来，整个湿和热和实都瘀在里面，结果病人就发黄，病人的舌苔会很厚黄。  \n\n       张仲景说去湿靠茵陈蒿，去热靠栀子，去实靠大黄，如果湿在肌肉里面靠白朮，三焦上的湿靠茵陈蒿，肝胆的湿也靠茵陈蒿，所以茵陈蒿入肝胆，只要是肝胆的实热，也就是发炎或西医的溶血性黄疸，就用茵陈蒿。  \n\n       病分阴阳表里虚实寒热，分阴证阳证，如果病人全身发黄，有阴黄和阳黄，茵陈蒿汤是属于阳黄的药，茵陈蒿汤一下去，小便有出路了，小出来黑黑的很浓稠，茵陈蒿能去湿是因为它能利水，湿是从小便出来的，大黄是把里面的燥屎清出来，如果怕太苦加甘草，就完了，不可以随便加甘草。  \n\n       脾太燥了就是麻子仁丸，脾太湿了就是茵陈蒿汤，所以麻子仁丸和茵陈蒿汤是相表里的药。  \n\n茵陈蒿汤方     先煮茵陈蒿，再煮其它两味。茵陈蒿在胖子或刚发病黄很盛的时候，可以开到五六钱，瘦人三钱就够了，栀子的量和茵陈蒿差不多，大黄约茵陈蒿的三分之一即可。     《勿误药室方函口诀》本方条曰：此方为治发黄之圣剂；茵陈蒿专治发黄，盖有解湿热及利水之效。  ', NULL, '茵陈蒿汤', NULL, NULL, NULL, '251、阳明病，发热汗出，此为越热，不能发黄也。但头汗出，身无汗，剂颈而还，小便不利，渴饮水浆者，此为瘀热在里，身必发黄，$f{茵陈蒿汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617185768816711, '13B8C7CAE1A0A1437685A58ED2D46F61', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 09:55:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5461, 320, 904000764, '       胃下垂，酒客病、胃常常呕酸的，最好的方子就是吴茱萸汤，食谷欲呕者，就是不吃就不呕，吃东西就会呕，吃下去东西就想吐，属阳明也，吴茱萸汤主之。  \n\n有三个方子，\n    第一、里寒重，里寒最重的时候用四逆汤，寒就是不动了，胃肠里面都不蠕动了；\n    第二，寒稍轻的用理中汤；\n    第三、更浅的就是吴茱萸汤，吴茱萸汤的主证是吐酸呕酸；胃寒的原因是肝太寒了，肝寒了影响到胃，让胃变寒了，所以大部分临床上看到吴茱萸汤证的时候，都是酒客病，喝酒喝多了，还有肝硬化的病人、慢性肝炎的、胃下垂的，都会看到吴茱萸汤证，所以在治疗肝病、肠胃病的时候，常常用到吴茱萸汤，吴茱萸本身入肝经，足厥经肝经，吴茱萸温中焦的，跟干姜一样是温中焦的，但是干姜是温脾胃，治疗胃的时候靠人参、甘草、大枣，吴茱萸是温肝，但是不补中，所以吴茱萸汤加入人参来补中，中气虚掉了，胃的功能没了，治疗起因是肝寒的，酒喝到身体里面感觉是热的，实际上到了身体里面是变冷的，酒最后就停在肝里面，所以肝就变冷了，喝酒的人常常到半夜不能睡觉，胃里面很难过，胃里面常常呕酸，所以吴茱萸汤是止呕的圣药，药书上的止呕是病人吐酸，实际上这酸是从肝里来的，肝液进入胃里面的时候是酸的，肝生酸，东方木，所以肠胃科，平常呕酸呕的很厉害的，服泻心汤都不会好，吴茱萸汤下去就好了。  \n\n       胃下垂的症状，摸左手的寸脉没了，表示心脉胸阳的脉没了；右手的关脉特别壮，代表胃下垂，吴茱萸汤温中焦的，如果服了吴茱萸汤病反剧者，属上焦，病在上焦，因为上焦如果是热，东西下去也会吐，结果吴茱萸汤温中的药下去，中焦加热，上焦会更热，就会更严重，就知道热在上焦，在上焦用栀子豆豉汤了。\n', NULL, '吴茱萸汤', NULL, NULL, NULL, '258、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之。得汤反剧者，属上焦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617196091056198, '63472AE0E8042B04AA8D25C556D68042', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 10:37:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5462, 320, 904000763, '       一看到病人小便不利，就知道津液已经没有了，大便乍难乍易，大便有时候好，有时候不好，时有微热，没有寒，喘冒不得卧者，有燥屎也，这些都是大承气汤的症状。  \n\n      喘冒不得卧者，为什么会喘?大肠在下方，因为大肠和肺是相表里的，所以看肺家证实的时候，有时候会误诊，看到病人舌质苔黄、喘，开麻杏甘石汤，看起来麻杏甘石汤很对证，可是没有好，病人喘的不能躺下去。病人述说五六天没大便了，才想到大承气汤，所以开处 方之前，一定是先问大小便的，饮食习惯如何?还有睡眠如何?这是高明医生的习惯动作。  ', NULL, '大承气汤', NULL, NULL, NULL, '257、病人小便不利，大便乍难乍易，时有微热，喘冒不得卧者，有燥屎也，宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617196091056199, 'C706E2FF5CB14FCE226F582A5414FFCF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 10:37:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5463, 320, 904000762, '        病人阳明证，给他攻下，下完了以后，结果六七天又不大便，腹满者，此有燥矢也，所以然者，又有宿食故也，宜大承气汤，攻了大承气汤之后，燥屎还在，就是药剂不足，出手太软，开的处方太轻，再开大承气汤给他，没有关系。  \n\n      大承气汤证的时候，如果没有用大承气汤攻掉，后遗症很多，到捻衣摸床、手足燥扰的时候，再下大承气汤就一翻两瞪眼了，如果死掉，病人家属会以为是吃大承气汤死的，所以要先讲清楚，与其坐以待毙，不如含药而亡。  ', NULL, '大承气汤', NULL, NULL, NULL, '256、大下后，六七日不大便，烦不解，腹满者，此有燥矢也，所以然者，又有宿食故也，宜$f{大承气汤}。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617196091056200, '1AF55DC9BF5DDC53A0528C5BE66F58DB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 10:37:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5464, 320, 904000761, '       本来病人烦热，汗出后好了一点，又忽冷忽热，到了黄昏以后可以发热，承气汤和白虎汤都有潮热，必属阳明也；但热不寒，完全没有寒证，就是阳明证，阳明热分经热和腑热，热在肠子里面就是承气汤，热在血脉神经上的就是白虎汤，如果脉实者，代表就是里实很盛了，宜下之；脉浮虚者，脉浮虚代表还有表证，先发汗再去攻里。宜发汗，发汗还是可以用桂枝汤，下之与大承气汤，所以给病人大承气汤的时候，一定要确定病人没有表证的时候，才可以去攻。  ', NULL, '大承气汤,桂枝汤', NULL, NULL, NULL, '255、病人烦热，汗出则解，又如疟状，日晡所发热者，属阳明也；脉实者，宜下之；脉浮虚者，宜发汗。下之与$f{大承气汤}。发汗宜$f{桂枝汤}。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617196091056201, '0B5BDD736C3B00D92A031EB148CC766A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 10:37:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5465, 320, 904000760, '      怎么知道肚子里面有干燥的大便？就是有硬块在里面，病人不大便五六日，第一绕脐痛，绕着肚脐一圈痛，第二烦燥，生气，想骂人。发作有时者，有的时候痛，有的时候不痛，此有燥矢，故使不大便也，这条辨就是说，有干燥大便堵在大肠里面的几个症状。', NULL, NULL, NULL, NULL, NULL, '254、病人不大便五六日，绕脐痛，烦燥，发作有时者，此有燥矢，故使不大便也。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617196091056202, '565659E53523A102B2F45EEA3A52B06F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 10:37:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5466, 320, 904000759, '        阳明病攻下了以后，心中懊憹而烦，胃里面很难过，还是会有烦躁，病如果进入阴的时候，都不会有烦躁的，\n        胃中有燥矢者，可攻。攻了若没有清干净，里面还是有东西，可以再攻，若有燥矢者，宜大承气汤，里面有干燥的大便在里面，用大承气汤去攻，\n        腹微满，初头 硬，后必溏，不可攻之，如果刚开始大便比较硬，后面是稀时都软掉了，代表里湿很重，确定阳明是燥的时候，才会用大承气汤，如果里面还有湿，就不会用大承气汤，大便溏就是里面有湿，湿还没有完全化燥，用小承气汤就可以了。  ', NULL, '大承气汤', NULL, NULL, NULL, '253、阳明病，下之，心中懊憹而烦，胃中有燥矢者，可攻。腹微满，初头硬，后必溏，不可攻之。若有燥矢者，宜$f{大承气汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617196091056203, '38B6142C46A75CDD8CBE8DFE5D472E31', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 10:37:21', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5467, 320, 904000782, '      为什么用麻黄?因为表寒束到了，热没有办法渲泻，湿热没有出路，造成全身发黄，麻黄连翘赤小豆汤除了身发黄在用之外，最常用在疥癣、皮肤科。经方中另外一个常用在皮肤病的药方是麻杏薏甘汤。 ', NULL, '麻黄连轺赤小豆汤', NULL, NULL, NULL, '276、伤寒身黄发热者，$f{麻黄连轺赤小豆汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572742, '19D28B7FD387FB35425F31DA7C34AE1F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5468, 320, 904000781, '       黄柏能清下焦的药，中医的热就是西医的炎，如尿道炎常常用黄柏，栀子能去上焦的热，黄芩、黄连、甘草能去中焦的热，所以栀子蘗皮汤是另外一个去黄的药，和茵陈蒿汤不一样，茵陈蒿汤是大便湿堵在肠子里面，所以茵陈蒿汤有大黄，这栀子蘗皮汤的热是瘀在三焦里面，上焦、中焦、下焦的热瘀在三焦油网里面，所以是淋巴系统发炎了，栀子蘗皮汤的病人小便利，腹部胀满，茵陈蒿汤是瘀热在肠子里面。所以茵陈蒿汤有小便不利，所以这是两个阳黄的方子，病人全身发黄，肚子很胀，大小便不利，就是茵陈蒿汤，大小便很正常，肚子也没有胀满，就是栀子蘗皮汤，这两个方都是比较寒凉的，所以是栀子蘗皮汤常常也用在眼睛的洗剂，眼睛赤痛发炎，栀子蘗皮汤煮好后，用滤网滤过，洗眼睛用的。  \n\n《类聚方广义》本方条曰：眼球黄赤热痛甚者，洗之有效，所以栀子蘗皮汤可以用来洗眼睛。  \n\n  在伤寒里面一共三个方子，治疗全身发黄发高热者:  \n\n       1、无汗，病人没有汗的时候，用麻黄连翘赤小豆汤。 \n       2、病人有汗且实热在里，就是茵陈蒿汤。 \n       3、无表证无里实而身发黄，栀子蘗皮汤。  \n', NULL, '栀子蘗皮汤', NULL, NULL, NULL, '275、伤寒瘀热在里，身必发黄，$f{栀子蘗皮汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572743, '91ACDF19712371C7389657D4609C6968', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5469, 320, 904000780, '身黄如橘子色，就是阳黄表示热，小便不利，腹微满者，湿无法宣泄而紧于少腹，湿堵到了，小便不出来了，此热湿并结下焦，则用茵陈蒿汤主之。  ', NULL, '茵陈蒿汤', NULL, NULL, NULL, '274、伤寒七八日，身黄如橘子色，小便不利，腹微满者，$f{茵陈蒿汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572744, 'ADDC96F5FD2EFB00916ABB3194CCED74', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5470, 320, 904000779, '       病人本来是伤寒，如果单纯伤寒，麻黄汤发汗就好了，可是病人有湿在里面，麻黄汤一发汗、汗发的只是表证，可是里湿还是没有去掉，湿是脾脏，脾是土黄，是阴黄的，发汗是从肠胃的津液来的，因为发汗带动了里湿，湿一上来，所以看到黄；寒湿的时候，方剂有朮附汤和五苓散，都是可以去寒湿的。', NULL, NULL, NULL, NULL, NULL, '273、伤寒，发汗已，身目为黄。所以然者，以寒湿在里不解故也。以为不可下，于寒湿中求之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572745, '6FCAFED8AF49E44140DBA760C79166A2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5471, 320, 904000778, '       病人表证里证都没有，没有寒热，大便也正常，但是脉又浮又数，浮是表，数是代表热，可是病人又没有症状。先不管他，没有关系的，\n      假令已下假如已经被攻下了，脉数，不解，不大便者，有瘀血，宜抵当汤。如果已攻下而仍然脉大，大便仍有问题，表示有瘀血用抵当汤，\n      若脉数，不解，而下不止，必协热而便脓血也，如果大便出来有血，有的可能是痔疮，可能是内痔，不开刀生完小孩的太太，大部分是内痔，临床上看有痔疮女人比男人多，压孔最或承山，会有压痛点的就有痔疮，另种造成大便脓血的，就是血里面热太盛，血里面的津液太少，血一但过热必叛离经道，造成血管破裂，血跑到腑里面去，所以大便出来有血，大便有脓血的时候有白头翁汤可用。  ', NULL, '抵当汤', NULL, NULL, NULL, '272、病人无表里证，脉浮数者，虽发热六七日至七八日，勿下之。假令已下，脉数，不解，不大便者，有瘀血，宜$f{抵当汤}。若脉数，不解，而下不止，必协热而便脓血也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572746, '5C1E087C586DF1408C90384CADD5F687', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5472, 320, 904000777, '       如果单纯的阳明少阳合病是大柴胡汤，太阳少阳合病是小柴胡汤，阳明病的时候脉一定大，少阳病的时候脉一定是弦，为什么必下利，病进入少阳的时候是胆，病随胆汁分泌出来，进入阳明腑病的时候，等于肠子发炎，如果单纯阳明热没有少阳证，热到最后就变成燥屎，津液就没了，所以有胆汁在里面的时候，因为胆汁会帮助消化，所以胆汁因病而分泌太多，就一直在下利，下利的时候会看到青黄相间的浊物。  \n\n     何谓克，脉完全弦的时候，就是木盛，木会克到土，少阳脉大于阳明，就叫作克，何谓贼，如果脉大，阳明脉盛，土会反侮辱到少阳，反侮就叫做贼。  \n\n     其脉不负者，顺也；负者，失也，阳明少阳合病应该是脉弦又大，这是正常的，有的时候脉很弦而不大，有的时候脉很大又一点点弦，都是不正常；阳明少阳合病的时候，只须大柴胡汤就可去掉了。确定没有少阳证，只有阳明证的时候，才会用承气汤。  \n\n      脉滑而数者，摸到病人滑脉代表有实，数脉代表有热，滑脉就像摸拉动中的绳子一样，实就是有东西，所以病人如果身上有长东西，摸到的脉就是滑的，弦脉的滑，代表长在淋巴系统里面，像腋下或腮下或甲状腺或胸，如果脉大而且滑，就是肠子里面堵到了。  ', NULL, '大承气汤', NULL, NULL, NULL, '271、阳明少阳合病，必下利。其脉不负者，顺也；负者，失也；互相克贼，名为负也；脉滑而数者，有宿食也，当下之，宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572747, '2E5D9DDE7660DC8BF0A967009687A451', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5473, 320, 904000776, '    什么叫减不足言，肚子胀满，摸到燥屎了，大承气汤攻下去后，病人有舒服点，但是还是胀满，就是先前开的大承气汤太轻了，要开重一点，所以这条辨讲的就是大承气汤剂量不够，要再用大承气汤。  ', NULL, '大承气汤', NULL, NULL, NULL, '270、腹满不减，减不足言，当下之，宜$f{大承气汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572748, 'C78A1658A6C940FEAC7BE480AD03A3D4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5474, 320, 904000775, '整个腹部胀满已经大痛了，大承气汤证痛的时候，到不要按都会痛了，赶快攻，不攻的话，运气好转盲肠炎，运气不好的脑膜炎。', NULL, '大承气汤', NULL, NULL, NULL, '269、发汗，不解，腹满痛者，急下之，宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572749, '8E5C4F957AD2281EB0966570C4286F6C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5475, 320, 904000774, '这时候已经燥热了，汗流很多了，就要速下，所以只要确定是大承气汤证，就要速攻，不要怀疑。这就是急下存阴的观念。  ', NULL, NULL, NULL, NULL, NULL, '268、阳明病，发热汗多者，急下之，宜承气汤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572750, 'C35B6C698FC2648122AAD4993C42FBE1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5476, 320, 904000773, '       太阳表证传热的时候，已经变成没有寒证了，目中不了了，睛不和，眼神已经痴呆了，高热了，无表里证，大便难，身微热者，身微热因为热都在里面，此为实也，急下之，赶快下，再不下危险了，这是脑膜炎先期的预兆，用承气汤或白虎汤，所以脑膜炎的病变在阳明篇也可以治。  ', NULL, '大承气汤', NULL, NULL, NULL, '267、伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572751, '4F5830C86594E53755AAE4649FFFB12D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5477, 320, 904000772, '        脉弱，代表表虚了，无太阳柴胡证，太阳证看不到了，少阳证也没有了，代表邪入里了，如果邪入少阳会往来寒热，\n       病人烦躁，心下鞕，胃里面胀满，胃里面硬硬的，会烦躁代表胃已经生燥了，伤寒的时候，在表上看到的是寒，这寒传到肠胃来的时候，会变成热，原来里面就已经很热了，再进入会更热，津液就会丧失掉，病人就会烦躁，\n      至四五日，虽能食，以小承气汤少少与微和之，令小安，先去攻他的大便，至五六日，与小承气汤一升，五六日再给他小承气汤，\n     还是不大便，若不大便，小便少者，虽不能食，但初头鞕，后必溏，未定成鞕，攻之必溏。须小便利，矢定鞕，乃可攻之，宜大承气汤。初头鞭，后必溏，就是湿太盛了，免疫系统、抵抗力、营养都是来自于中焦，当伤寒的时候，表热走到里面来，胃已经虚掉了，热就是发炎，热一下来，发炎的更厉害，炎一定往上走，所以有后来变成脑膜炎等，人的身体是密闭的腔，热力往上走，胃就缩小，脾脏就横逆过来，脾湿就过来了，就堵在这了，所以有初头鞕，后必溏，刚开始大便是硬的，后来大便是溏的，遇到这种情形的时候，大便只要有溏，里面一定有湿，不要去攻，给小承气汤就好了，要确定他小便利，代表湿已经有地方渲泻了，代表大肠里面全部化热了，所以大承气汤证的小便还是利的，矢定鞕，因为小便利出来，脾脏的湿已经完全没了，才可以用大承气汤。其实这里小便少、腹满便溏的症状，就是有湿在里面，可以五苓散与大承气汤合用。  \n\n       有时候病人讲不清楚，可以看病人的舌头，舌头上口水津液很多，代表湿很盛，如果很黄，代表湿且热，如果苍白的就是寒而且湿，如果舌头已经干掉了，表示肠里面干掉了，大承气汤的舌头干干的，里面没有津液了，舌苔有时候严重到都翻起来了，湿在里面下利的时候，一定抱着肚子，如果按压下腹部会痛，就是大便干在里面了，如果按压不痛，就是湿在肠子里面，表示大便还没有干燥。  ', NULL, '小承气汤,大承气汤', NULL, NULL, NULL, '266、得病二三日，脉弱，无太阳柴胡证，烦躁，心下鞕，至四五日，虽能食，以$f{小承气汤}少少与微和之，令小安。至五六日，与$f{小承气汤}一升。若不大便，小便少者。虽不能食，但初头鞕，后必溏，未定成鞕，攻之必溏。须小便利，矢定鞕，乃可攻之，宜$f{大承气汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572752, 'C05B230FEC01028C254B29EA5D7F6415', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5478, 320, 904000771, '太阳病解表就好了，结果攻下，吐，发汗，就是津液伤到了，小承气汤的腹满一定在少腹，关元一带。  ', NULL, '小承气汤', NULL, NULL, NULL, '265、太阳病，若吐，若下，若发汗，微烦、小便数，大便因鞕者，与$f{小承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572753, '687B24A9D7EE77B415CECBA6FCEC8063', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5479, 320, 904000770, '       伤寒应该发汗解掉，如果病人刚好吃坏肚子，吐，嘴巴一吐，吐出来的黏液，黏黏的，就是湿，如果湿去掉了，可是燥没有去，所以还是调胃承气汤主之。因为腹胀满者，肚子还是胀满，代表大便还堵到，不管是小承气汤、大承气汤，肚子一定会有胀满，因为里面有堵到大便，只是堵到小肠或大肠，位置不一样，所以处方也不一样。 ', NULL, '调胃承气汤', NULL, NULL, NULL, '264、伤寒吐后，腹胀满者，与$f{调胃承气汤}和之则愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572754, '1DCA1C9CFE6C5213689C07369ED5CF2A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5480, 320, 904000769, '      这是刚开始表热进入阳明的主证，刚开始太阳病的时候，发汗就去掉，在发汗的同时病进入阳明了，病人流了汗，汗出来了烧却没退，烧是蒸蒸发热者，一阵一阵的上来，就知道这是在胃里面，就在十二指肠的地方，所以调胃承气汤主之，就是刚开始起阳明证的时候。', NULL, '调胃承气汤', NULL, NULL, NULL, '263、太阳病三日，发汗不解，蒸蒸发热者，属胃也，$f{调胃承气汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572755, 'A59EB3D6FFDE34703FD4016D92EE34F4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5481, 320, 904000768, '趺阳脉讲的就是冲阳的地方，脚背的地方。为什么叫脾约?食物进入胃，经过十二指肠到小肠，小肠很小，残渣一个一个堵在小肠转折的地方，因为脾太燥，思能伤脾。孟子说：思而不学则怠，倪子说：思而不学，大便就像六味地黄丸，像羊大便。  \n\n       人喝水，正常的时候，水在阳明发散，一部分的水在胃里面发散成津液，一部分的水到小肠或大肠。在大肠的时候在发散，这是经过两道步骤，当脾太燥的时候，水一进入到胃里面就蒸发掉了，脾脏把水拿走了，脾本身是湿不要水，这水就直接给膀胱，就小便出来了，所以小便数，食物的水应该到大肠里面的时候才完全吸收，结果进入小肠的时候，就完全被脾脏拿走了，大便干在小肠里面，大便就变成一颗一颗的，本来应该是一条的，堵在大肠的燥屎像核桃那么大，堵在小肠里面的像六味地黄丸，燥屎就是堵在小肠里面的九转回肠的地方。  \n\n       因为知道结在小肠里面，用芒硝就太快了。所以靠麻子仁，仁就是有油质，都可以润肠，所以又用杏仁，健脾的时候用桂枝汤，因为脾已经太燥了，桂枝很热，桂枝下去脾会更燥，所以不用桂枝用白芍，白芍能让脾脏里面，静脉的血管活络起来，能生湿并止腹痛，这三味药再加上小承气，小承气汤是通小肠的，所以小承气汤里面加麻子仁、杏仁、白芍，才能把  \n小肠的燥屎通出来，光用小承气汤大便清出来了，可是小粒的清不出来，因为大便黏在小肠壁转折处，这就靠仁剂把它清出来，靠丸剂的药缓力专，把它慢慢清干净。  \n\n       张仲景用丸剂，取它的药缓力专，汤剂的速度太快了，清不干净，用丸剂慢慢的全部把它清出来。这种症状女性比较多，用了麻子仁丸，症状有改善但如果还不太通畅，可加少量芒硝冲服。  ', NULL, '麻仁丸', NULL, NULL, NULL, '262、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相搏，大便则难，其脾为约，$f{麻仁丸}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572756, 'B6A125F5066E0BA3126668FE20842FC0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5482, 320, 904000767, '     芤脉代表脉是中空的。中空的脉又代表失血，所以病人开完刀或大量失血的时候，摸他的脉，脉会变的很大，然后按下去中间是空的就是芤脉。  \n\n      脉浮为芤，浮代表有表证，脉又浮又里面又中空的，浮为阳，芤为阴，浮代表阳，芤代表阴就是血不足了，一个是气，一个是血，浮芤相搏，因为血虚不够的时候，阴阳不和，病人失血的时候可以看到，正常胃的热应该停留在胃里面，胃才会蠕动，如果血不够的时候，胃的热气会往上升，像热气球一样，会浮起来，热气之所以停在下方没有浮起来，是因为血在中焦，就是我们的体能，血一少的时候，虚热就往上冲了，所以胃气生热，其阴则绝，就知道这病人大量失血，血不够了。所以这病人有表病，血又不够，表病还没有去掉，血又受伤了。  ', NULL, NULL, NULL, NULL, NULL, '261、脉浮而芤，浮为阳，芤为阴。浮芤相搏，胃气生热，其阴则绝。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572757, '8076940C1EC2BA39D67EAA3FC001F291', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5483, 320, 904000766, '       阳脉就是右手的脉，寸脉也是阳脉，阳脉微，阳脉缓下来了，代表阳已经归根了，阴阳和了，而汗出少者，为自和也，汗出少者，代表自己好了，如果病人汗出多者为太过，津液发散太多的时候就知道太迟了，如果阳脉实，因发其汗出多者，亦为太过，发汗太多也会太过，太过为阳绝于里，亡津液，大便因鞕也，汗出来太多以后，水没有了血热会增加，这就是白虎汤证，如果发汗发太多，把肠胃里面的津液发干掉了，大便也会硬。', NULL, NULL, NULL, NULL, NULL, '260、阳脉微而汗出少者，为自和也；汗出多者为太过。阳脉实，因发其汗出多者，亦为太过。太过为阳绝于里，亡津液，大便因鞕也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572758, 'DE6C6AA046270956CBE5ED6AA67664EC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5484, 320, 904000765, '       太阳病，寸缓，关浮，尺弱，寸关是脾胃的脉，固表的能力就是靠脾脏，关浮就代表病在表，\n       其人发热汗出，复恶寒，有恶寒就不是阳明证，\n       不渴，但心下痞者，病人不渴，但是胃很难过，此以医下故也，这是医生攻下了，应该要解表、结果医生攻下了，一般来说如果没有伤寒证的时候，病人汗出而渴，流汗流很多又渴就是五苓散证，\n       如其不下者，病人不恶寒而渴者，此转属阳明也，如果这病人恶寒的现象完全没有了，全进入热的症状，就转阳明了，本来进来的寒，由表一直通到现在半表半里，进入肠胃了，转化成热了，整个燥热起来了。\n      小便数者，大便必硬，转阳明证了，就知道津液不足了，小便又多，下焦的津液不足了，大便会干掉，\n     不更衣十日，无所苦也，十天不大便都不会难过，由此可知是属于寒实便秘，若是热实便秘，十几天下来早就发狂谵语了。\n     渴欲饮水，少少与之，但以法救之，像前面讲的心下痞不恶寒就开泻心汤，\n     小便不利而渴者五苓散，像五苓散证的病人，大部分会看到水肿，渴的原因就是肠胃的水发到皮肤表面上，但是力量不够，没有办法回头，里面的水没了，外面的水又出不了汗，汗出来一点但又不多，舌头下没有津液可以生出来，所以会渴，因此五苓散有用到桂枝。这五苓散条辨应该放在太阳篇末来讲。  ', NULL, '五苓散', NULL, NULL, NULL, '259、太阳病，寸缓，关浮，尺弱，其人发热汗出，复恶寒，不渴，但心下痞者，此以医下故也。如其不下者，病人不恶寒而渴者，此转属阳明也。小便数者，大便必鞕，不更衣十日，无所苦也；渴欲饮水，少少与之，但以法救之。小便不利而渴者，宜$f{五苓散}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617215532572759, '304EBF02C5DFFB95FD2E5A922A3F6398', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:56:28', 1, '超级管理员', '2024-11-29 11:56:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5485, 321, 904000810, '因为东方甲乙寅卯木，少阳属木，所以少阳病欲解时，从寅至辰上。 以上讲的是少阳。  ', NULL, NULL, NULL, NULL, NULL, '286、少阳病欲解时，从寅至辰上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631494, '3E95F5936F7AE33279E23A6505C079E0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5486, 321, 904000809, '    不管是少阳、阳明，脉一缓下来了，病就是要好了。如果病人的脉很正常，一息四至而  \n    恶心是怀孕的现象，没有病的，正常的人，脉正常而有不适症状就是受孕了，不要随便开药。  ', NULL, NULL, NULL, NULL, NULL, '285、伤寒三日，少阳脉小者，欲已也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631495, 'EF4FA8E86300C2C06C0D525FB7A91CE6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5487, 321, 904000808, '       伤寒三日，半个多月，二十一天以后，三阳为尽，三阴当受邪，这病进入少阳、阳明以后，如果没有治好，应该会进入阴脏了，其人反能食而不呕，反过来，病人可以吃东西了，又没有恶心，就是三阴不受邪也，病还是在阳，有时候不用给病人吃药，病不一定会传，各人的体能不一样，一般来说，常年不吃西药，免疫系统很强的人，病不会进入阴的，因为西药会让免疫系统退化很多。  ', NULL, NULL, NULL, NULL, NULL, '284、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631496, '443662D6243AFB9C974800282A74E384', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5488, 321, 904000807, '        照理说伤寒六七日，无大热，病人发热的现象没有了，没有发烧了，结果其人烦燥者，有烦燥的现象产生的时候，就知道病人的病由表进入里了，此为阳去入阴故也，阳就是表，阴就是里，所以阳入阴不一定是进入阴脏，由少阳证进入阳明证也会烦燥。  ', NULL, NULL, NULL, NULL, NULL, '283、伤寒六七日，无大热，其人烦燥者，此为阳去入阴故也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631497, '439E634CAF1506DE6E8B51C585D94493', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5489, 321, 904000806, '       三阳合病，应该和解少阳，如果病人脉浮，就是太阳证，脉大就是阳明证，上关上，关脉跳到上面了，右边的关是脾胃，左边的关是胆，关脉已经跳到寸了，就是阳热往上焦走的现象，因为胆胃太热了，所以胆汁上逆，病人会口苦，就知道胃热和胆热往上跑，代表小柴胡汤，所以在摸脉的时候可以知道身体的过程；但欲眠睡，病人体力在太阳的时候已经耗掉很多，进入少阳的时候，肠胃吸收又不好，食物不能化生成血，因为被三焦阻隔到，所以精血的来源不够，病人就会有但欲眠睡的现象，目合则汗，眼睛闭起来会流汗，就是人很虚的现象，正常的流汗一定是在运动或动过后，可是现在病人躺着都会流汗，代表津液一直在丧失的阶段，这就是和解少阳，这时候用小柴胡汤。  \n\n       如果查到病人胃里面有燥实、大便很少，津液一直在丧失，就知道病是介在少阳和阳明之间，所以是大柴胡汤，大柴胡汤里面有大黄。可以同时解少阳阳明并病。', NULL, NULL, NULL, NULL, NULL, '282、三阳合病，脉浮大，上关上，但欲眠睡，目合则汗。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631498, 'D69147A76CCBEF7D39EBCAB3AD11DA58', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5490, 321, 904000805, '本来是柴胡汤证，结果被吐、下、发汗、温针，就没有柴胡汤证了，此为坏病；知犯何逆，此为庸医误诊，造成病情传变，看他到什么阶段，以法救之。', NULL, NULL, NULL, NULL, NULL, '281、若已吐、下、发汗、温针，柴胡汤证罢者，此为坏病；知犯何逆，以法救之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631499, 'D54907BBA85B522C6DE675C94687A883', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5491, 321, 904000804, '     本来是太阳病，结果没有好，已经进入少阳的，胁下鞕满，干呕不能食者，往来寒熟，尚未吐、下，脉弦紧者，可以给小柴胡汤。  \n\n      柴胡这药，本身就是进入三焦淋巴系统，柴胡也能够清热去寒，所以柴胡属于半表半里的药，半夏能去水止呕，因为是有水隔在中间，滤过性病毒跑到中膈的水里面，靠半夏把它赶出去，所以用半夏的时候，小便会增加，阳病一定有热，所以一定有黄芩、黄连，黄芩常常用在去中焦的热，胸腔里面有热的时候常常用黄连、黄芩、人参、甘草。大枣专门固脾胃固中焦，不让少阳病再传阳明，同时增强免疫系统，同时加强胃的五谷的能力，让中焦强起来，这就是张仲景的预防医学。  \n\n     所以小柴胡汤的方义是用人参、甘草、大枣断后，让病毒停在少阳，柴胡把黄芩、半夏带到淋巴系统，用黄芩杀菌消炎。半夏把病毒赶出去。  \n\n         喝酒前用小柴胡汤，重用半夏利水，先把胃里面的水清干净了，再喝酒的时候就会千杯不醉，因为小便量会增加，一喝完小便就小出来了，这样酒不会入肝，因为小柴胡汤是少阳的主证，少阳和厥阴是表里，这一下去把肝固得很好，半夏的比例是乘二；如果喝酒喝太过量了，解酒的就是苍朮、泽泻。苍朮泽泻就是苍朮如果五，泽泻就是六。酒精跑到头上去，苍朮会去上湿气，酒里面的湿热很盛用苍朮。但是湿要有去路，泽泻本身能利尿，就靠泽泻把湿利掉，所以湿靠小便就排掉了；所以今天以前喝酒喝多的如果变成胃下垂，就用吴茱萸汤把胃治好，每次喝酒再用小柴胡汤重用半夏，因为半夏止呕，就不会恶心想吐，喝酒就小便小掉了，喝太多了就用苍朮泽泻。  ', NULL, '小柴胡汤', NULL, NULL, NULL, '280、本太阳病，不解，转入少阳者，胁下鞕满，干呕不能食，往来寒热，尚未吐、下，脉弦紧者，与$f{小柴胡汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631500, 'B8FE7BB9412813BA9DAA77806FF76B28', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5492, 321, 904000803, '      这条辨是以脉来作主，病人本来只是伤寒而已，取发汗的时候，一定是诊察到病人病在表才会去发汗，结果摸到病人脉弦细，就是病已经入里了，怎么知道？因为看不到口苦咽干，看到脉弦细，弦细代表水脉，弦脉出现的时候代表少阳证。  \n\n        所以摸到脉弦细，就知道滤过性病毒进入水道系统了，以脉证来看是少阳证，\n       头痛、发热者，就是有太阳证的现象，如果是麻黄汤证的时候脉浮且紧，桂枝汤证的时候脉浮且缓，现在病人不是浮脉，而是弦细的脉。代表病人表证已经没有了，病入里了，\n      属少阳，不可发汗，这时候看到太阳证都要属于少阳。绝对不可发汗，因为发汗是为了把病毒排出去，把皮肤表面的病毒发出去，但是病毒已经进入三焦淋巴系统了，发汗只是把津液更伤而已。\n     发汗则谵语。此属胃，胃和则愈，胃不和则烦而躁，谵语的原因发汗太过，肠胃津液受损，造成就是大便堵到了。  ', NULL, NULL, NULL, NULL, NULL, '279、伤寒，脉弦细、头痛、发热者，属少阳，不可发汗，发汗则谵语。此属胃，胃和则愈，胃不和则烦而躁。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631501, '987B76CABA3F24D165025209F42EA2E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5493, 321, 904000802, '        如果是少阳就兼有太阳的表证，本来得到中风的时候，是太阳证，在太阳病的同时，肠胃里面的阳气，就是免疫系统，也就是固表能力。发挥了一部分的体力去抵抗表邪，就已经开始流汗了，津液为了抵抗表邪已经不够了，在这条件下，本身的病没有好，病进入少阳，进入少阳的时候，是在津液已经伤到的状况了，因为肠胃的津液，在太阳证的时候出去相抗，病会进入少阳就是抗不过才进来的，所以用汗法就是为了加强免疫系统、在津液不足的状况下，这时候两耳无所闻，因为耳朵靠津液来滋润，\n      目赤，眼睛是靠血上来滋润的，血里面的水不够了，血就热起来，热就是炎，第一个就会看到眼睛红赤肿痛，\n      胸中满而烦者，因为他本来就已经受邪了，过去看到胸满，一般来说病在上焦采吐法，所以医生使用吐法误诊了，因为不是哽到，不应该用吐的，因为津液已经不够了，吐很多的话会伤到气，所谓伤到气就是伤到津液的源头，因为吐出来很多黏液、食物，攻下的时候会伤到血，因为血是肠胃从小肠里面生化出来的，本来食物应该化成血供给身体用的，在还没化成血就被干掉了，所以攻下会伤到血，病人元气一伤到，造成里虚的状况有两种有小建中汤证，另一炙甘草汤证，如果心脏动悸，就是上焦受损了，就是炙甘草汤证，\n     吐、下则悸而惊，心和小肠相表里，心是 君主之官，心血不足的时候，病人容易受到惊吓，受到惊吓的时候给柴胡加龙骨牡蛎汤，这是惊，如果是悸，除了有动悸的现象，脉还可以看到结代，惊可以看到病人印堂、山根的地方有青紫色，小儿科中，小孩可以看到大便变成绿色的，耳朵后有鸡爪血丝，可以在上面点刺放血，这条辨就是说，少阳不可吐也不可下，少阳证的时候必须采和解的方式。  \n\n 补充：灵枢决气第三十  \n\n       黄帝曰：余闻人有精、气、津、液、血、脉，余意以为一气耳，今乃辨为六名，余不知其所以然。\n       岐伯曰：两神相搏，合而成形，常先身生，是谓精。\n              何谓气?岐伯曰：上焦开发，宣五谷味。熏肤、充身、泽毛，若雾露之溉，是谓气。\n              何谓津?岐伯曰：腠理发泄，汗出溱溱，是谓津。\n              何谓液?岐伯曰：谷入气满，淖泽注于骨，骨属屈伸，泄泽补益脑髓，皮肤润泽，是谓液。\n              何谓血?岐伯曰：中焦受气，取汁变化而赤，是谓血。\n              何谓脉?岐伯曰：壅遏营气，令无所避，是谓脉。  \n\n     黄帝曰：六气有，有余不足，气之多少，脑髓之虚实，血脉之清浊，何以知之?\n     岐伯曰：精脱者，耳聋；气脱者，目不明；津脱者，腠理开，汗大泄；液脱者，骨属屈伸不利、色夭，脑髓消，胫痹，耳数鸣；血脱者，色白，夭然不泽，其脉空虚，此其候也。  \n\n    黄帝曰：六气者，贵贱何如?\n    岐伯曰：六气者，各有部主也，其贵贱善恶，可为常主，然五谷与胃为大海也。  ', NULL, NULL, NULL, NULL, NULL, '278、少阳中风，双耳无所闻，目赤，胸中满而烦者，不可吐、下，吐、下则悸而惊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631502, '58E9F8F831DEC707EA06277EE901BCD1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5494, 321, 904000801, '      人有两个少阳。手少阳三焦经，足少阳胆经，太阳的表邪进入少阳的时候，胆附在肝旁边，病邪一进来的时候，第一个就是碰到胆。胆受邪的时候，胆汁就会回逆。如果胆汁跑到血里面去的时候，人身上就会比较黄，如果胆汁往上冲，跑到喉咙里面，就会感觉嘴里面苦，所以口苦；因为病在阳，所以所以一定会看到有热的现象，所以咽干，因为喉咙靠血脉神经来滋润，一受邪的时候，血脉干掉了，津液不足，喉咙一定会发干；目眩，眼睛会发昏，因为眼睛也是靠血液来滋润，所以表症马上可以变为这些症状，实际上这些还不够，前面有介绍，一定会往来寒热，胸胁苦满，往来寒热的原因，因为病邪在淋巴系统里面跑，如果抵抗力很强，打赢的时候就热，打输的时候，病邪往里进的时候就冷，所以有忽冷忽热，突然来的热，突然来的冷，因为三焦受病的时候，第一个就是胸胁的地方，胸里面水分津液很多，邪一进入胸里面以后，胸里面的水运转就不会正常，而且还要分出很多体力来相抗，所以自然而然堵在这，病人还有恶心、呕的现象，所以只要病人有呕的现象，马上就想到少阳，为什么呕？水道系统不是很正常的时候，胃吸收的营养没有办法进入三焦油网，进入脏腑，$m{《内经》}：$n{“三焦者水道出焉，决渎之官”}，所以三焦是疏导的系统，在这状况下，旧的食物没有去，因为三焦有病邪了，新的血生不出来，而新的食物又不受，停在肠胃中，所以会有恶心的现象，这些都是三焦少阳的主症。  ', ' 人有两个少阳。手少阳三焦经，足少阳胆经，太阳的表邪进入少阳的时候，胆附在肝旁边，病邪一进来的时候，第一个就是碰到胆。胆受邪的时候，胆汁就会回逆。如果胆汁跑到血里面去的时候，人身上就会比较黄，如果胆汁往上冲，跑到喉咙里面，就会感觉嘴里面苦，所以口苦；因为病在阳，所以所以一定会看到有热的现象，所以咽干，因为喉咙靠血脉神经来滋润，一受邪的时候，血脉干掉了，津液不足，喉咙一定会发干；目眩，眼睛会发昏，因为眼睛也是靠血液来滋润，所以表症马上可以变为这些症状，实际上这些还不够，前面有介绍，一定会往来寒热，胸胁苦满，往来寒热的原因，因为病邪在淋巴系统里面跑，如果抵抗力很强，打赢的时候就热，打输的时候，病邪往里进的时候就冷，所以有忽冷忽热，突然来的热，突然来的冷，因为三焦受病的时候，第一个就是胸胁的地方，胸里面水分津液很多，邪一进入胸里面以后，胸里面的水运转就不会正常，而且还要分出很多体力来相抗，所以自然而然堵在这，病人还有恶心、呕的现象，所以只要病人有呕的现象，马上就想到少阳，为什么呕？水道系统不是很正常的时候，胃吸收的营养没有办法进入三焦油网，进入脏腑，$f{《内经》}：$n{“三焦者水道出焉，决渎之官”}，所以三焦是疏导的系统，在这状况下，旧的食物没有去，因为三焦有病邪了，新的血生不出来，而新的食物又不受，停在肠胃中，所以会有恶心的现象，这些都是三焦少阳的主症。  ', NULL, NULL, NULL, NULL, '277、少阳之为病，口苦，咽干，目眩也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617277510631503, '76D014ACAEBE07E927F609FB8A09DB22', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:08:39', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5495, 322, 904000906, '      如果只是浮而缓就是桂枝汤证，如果是浮而紧就是麻黄汤证，病人应该是手脚冰冷，现在手足自温者，就知道表邪已经入里了，因为里主脾，就知道病在太阴里面，\n      太阴当身发黄，病在太阴里面身体应该发黄的，所以脾脏有病的人，脸应该是很黄的，手足自温就是胃气外散，到手脚上面去了，正常的胃气不应该外散，应该在中间消化食物，胃一受邪，胃弱掉了，胃的热气就跑到四肢上面去了，被逼出来的，照理说得到伤寒表证的时候，手脚是冰冷的，结果胃气散出来就知道病已经进入太阴了，进入太阴的时候，病人会发黄。这黄不是流汗黄的，而是整个人是枯黄，全身都像枯木一样，\n       若小便自利者，不能发黄，这代表这黄有地方泄去，就不会发黄，\n       至七八日，虽暴烦，下利日十数行，如果到了七八天以后，病人感觉烦闷且烦躁不安，又一天下利几十次，这种情况下，\n       必自止，为什么?在看病人下利的时候，进入阴证一定大便都不好会下利，下利完精神还是很好，就自己会好，下利完虚脱了就是真正虚证，如果下利自己会好的代表他是脾家实，实代表功能还是很好，脾湿跟着大便排掉了，因为腐秽当去故也，治疗脾脏最主要就是去它的湿，将脾湿自小便排出，湿热因为一直下利，而没有办法停留在中焦，脾脏就不会肿起来，慢慢的自己就会好起来了。  ', NULL, NULL, NULL, NULL, NULL, '292、伤寒，脉浮而缓，手足自温者，系在太阴；太阴当身发黄；若小便自利者，不能发黄；至七八日，虽暴烦，下利日十数行，必自止，以脾家实，腐秽当去故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617293549957190, '53C6838611F80F418E17D3CCE49CD85C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 17:13:55', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5496, 322, 904000905, '      如果自利而渴就是进入少阴了，不断的下利一定是进入阴证了，如果湿在下焦，水一直在往下走的时候，这时候反而上面会口渴的，\n      自利不渴者，属太阴，下利的时候如果中焦的湿很盛，不会口渴的，所以不渴就是湿在中间，\n      以其脏有寒故也，当温之，病人有寒就是脾脏肿大，肠胃蠕动功能都没有了，寒就是缓，人的一呼一吸，脉跳四下，肠胃也是蠕动四下，脉跳二下，肠胃蠕动也是二下，这代表肠胃的消化太慢了，肠胃的蠕动减慢了，这时候病人不口渴就是湿很盛，因为下利不止，所以里面又寒又湿，舌苔整个白厚的，津液很多，这时候用四逆辈，像通脉四逆汤、四逆汤等。  \n\n       张仲景用药的时候，在用干姜一定用生附，用生姜的时候一定用炮附，像真武汤，干姜本身是温中，能去中焦的寒，干姜加生附的时候能够去经脉、血脉神经里面的寒，生姜和炮附是散饮，有水饮的时候，水堵到了，不管是水肿在那里，会用到生姜和炮附，所以真武汤里面会用到生姜和炮附，来破饮积。  ', NULL, NULL, NULL, NULL, NULL, '291、自利不渴者，属太阴，以其脏有寒故也，当温之，宜服四逆辈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617293549957191, '5F777B366580AFEA68ACE452EA44FC7E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 17:13:55', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5497, 322, 904000904, '不管太阴、少阳、阳明，只要脉浮的就代表有表证。所以用桂枝汤解表。 ', NULL, NULL, NULL, NULL, NULL, '290、 太阴病，脉浮者，可发汗，宜$f{桂枝汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617293549957192, 'A40BF417496A4B90D91E0B705D11356B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 17:13:55', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5498, 322, 904000903, ' 太阴病会恢复时必在半夜的时候好起来，亥至丑时，张仲景说夜半胃气复，这病人就救回来了，丑时由一点到三点，脾脏功能恢复的时候，感觉饿的时候是午夜三点钟左右。 ', NULL, NULL, NULL, NULL, NULL, '289、太阴病，欲解时，从亥至丑时。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617293549957193, 'A98346A60A4252A29628D538C9DB0191', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 17:13:55', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5499, 322, 904000902, '   中医的观念，左脉是阴，右脉是阳，太阴中风，四肢烦疼，受病的时候，如果脉阳微阴涩而长者，代表气血流注很强，阳脉就是免疫系统抵抗力，不需要怎么相抗，就是病已经在消退了，在抗的时候，阳脉会跳的很快，如果摸到阴脉快没了，血已经衰了，剩下气脉跳的很旺就是残余的力量在相抗。', NULL, NULL, NULL, NULL, NULL, '288、太阴中风，四肢烦疼，脉阳微阴涩而长者，为欲愈。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617293549957194, '3436019E39A0082BA3B438EBF9AB6E76', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 17:13:55', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5500, 322, 904000901, '       脾主腹，为什么吐?因为津液累积太多了，呕吐出来，为什么食不下?胃弱掉了，胃变小了，东西吃不下去，正常脾脏的血到胃的下方以后，产生的热能中医叫做胃阳，若下之，必胸下结鞕，会采攻下法一定是诊断到有东西堵到了，人的身体里面是没有间隙的，现在是湿堵在脾里面，攻下的时候，就会必胸下结鞕，自利益甚，下利会更严重，所以脾脏受病的人，腹满，胃口没有，下利的现象，大便是溏的，时腹自痛，肚子常常会隐隐作痛。足太阴脾经里面只有几个药方，如果是实痛，查到大便堵到才会攻实，拒按就是实，如果是虚痛，就补虚，喜按就是虚，用腹诊来确定虚实。  ', NULL, NULL, NULL, NULL, NULL, '287、太阴之为病，腹满而吐，食不下；若下之，必胸下结鞕，自利益甚，时腹自痛。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617293549957195, '8DC1189875AF9E41940336CF0EE93232', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 17:13:55', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5501, 322, 904000907, '      本来太阳病应该解肌的，结果医反下之，攻下的药一下去，就伤到肠胃了，肠胃的功能减缓了，脾脏肿大起来，造成腹满时痛者，肚子胀满偶尔会痛，就是属于太阴，如果只要感觉肚子里面胀胀的，舌苔黄的；大便没有就是阳明证，感觉肚子里面胀满的，舌苔白的，下利，就是太阴，为什么桂枝加芍药汤，就是芍药加倍，若桂枝三，白芍就是六，张仲景在用白芍，白芍的药味是酸的，酸主收敛，所以重用白芍的时候，主收敛，脾脏一肿大的时候，芍药让脾脏收敛起来，因为脏里面静脉很多，动脉大部分是在腑里面，白芍让静脉活起来，马上收敛起来，因为加重白芍，酸主收敛，所以往往需要固表的时候，或人虚的时候重用白芍，像真武汤里面有芍药，当归四逆汤里面也有芍药，譬如芍药甘草附子汤，光靠附子把阳 壮起来的时候，怕附子太刚烈太猛烈，用芍药固起来，不要让它发阳发太过，所以芍药有固阴的功能，所以简单的讲芍药止腹痛，只要腹痛就一定加芍药，除非是大便不通的腹痛，所以小建中汤里面加重芍药，如果桂枝汤里面加饴糖没加重芍药、就只是桂枝汤加饴糖，不是小建中汤，要桂枝汤里面再加重芍药，才是小建中汤，一般制药厂做的药粉不是真正的小建中汤，大实痛者，前面是按之舒服，隐隐作痛，痛不是很强，大实痛就是不按都会痛，拒按，就是桂枝加大黄汤主之。', NULL, '桂枝加芍药汤,桂枝加大黄汤', NULL, NULL, NULL, '293、本太阳病，医反下之，因而腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617562090168390, 'AEA93D35DDF0F0DAB3D7F7BF57BB4036', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 11:26:37', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5502, 322, 904000908, '      如果病在太阴，病人就可以看到脉很弱，跳的很缓慢，其人续自便利、大便还是继续在下利的时候，设当行大黄、芍药者，宜减之，假如这人还需要大黄、芍药的时候，要减量，因为胃气弱，易动故也，胃气本身太弱了，又需再攻实的时候，剂量要减轻，强力下攻的话，胃阳会虚掉了，所以易动故也。这时候开大黄只是协助蠕动功能而已，帮助他去实的力量，往往一般性的下利，桂枝汤重用芍药就好了。  \n\n以上讲的是太阴证。  ', NULL, NULL, NULL, NULL, NULL, '294、太阴为病，脉弱，其人续自便利，设当行大黄、芍药者，宜减之，以其人胃气弱，易动故也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617565182881862, '6CEA4E17057A8444A7F3DFB77A766FB3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 11:39:12', 1, '超级管理员', '2024-11-30 11:39:11');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5503, 323, 904001022, '       因为有表证，所以不要麻黄走小便，就得把细辛拿掉，换成甘草，麻黄遇到甘草不是往下走，会停在中间，有一点表证但是里寒又很盛，在这状况下，不通利小便的时候，纯的少阴证，少阴脉一定微细，平常少阴证，脉微细，但欲寐，处方就是麻黄附子细辛汤，如果不是少阴证，吃麻黄附子细辛汤，第二天鼻子也干掉了。眼泪也没了，嘴巴也干掉了，因为正常的津液被小便排掉了。', NULL, '麻黄附子甘草汤', NULL, NULL, NULL, '316、少阴病，得之二三日，$f{麻黄附子甘草汤}微发其汗，以二三日无里证，故微发其汗也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820742, 'F7D8100A98117BE60F7D92FCFC8964A8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5504, 323, 904001021, '       少阴病，始得之，刚开始得到少阴病的时候，\n       反发热，代表病人有表证，少阴病应该是里寒，病人的病情会进入少阴，一定是太阳、少阳、阳明还没好，进入太阴没好，才会进入少阴，所以在刚开始起证的时候，第一里寒很盛，就是下焦脉很细，张仲景会加附子，附子专门是温肾壮心阳的，所以心脏的力量不够，肾阳不足都是靠炮附子，少阴病有心和肾的问题，所以附子一下去，心脏马上壮起来，附子性烈，跑的很快，怕附子跑太快，就规定附子跑的方向，所以用细辛，细辛性上升，细辛长的就一根长长的，没有叶子，它是往上走的，附子一遇到细辛的时候，阳就往上冲，让里寒去掉，里面就热起来了，炮附也固表，像桂枝附子汤，汗发太过的时候，病人表虚掉了，桂枝汤加附子进去固表，附子会走表、如果希望附子停在中间。因为里寒很盛，要附子不要离开，细辛一下去，里面就热起来，就不会散到表面上，如果光附子下去，摸到皮肤烫的，里面还是寒的，所以选用细辛，麻黄是发汗的药，实际上，麻黄还有一个功能，就是利尿，有的人吃小青龙汤的时候，没发汗，反从尿解掉了，这是体质的关系，有的人皮毛比较扎实，小青龙汤、麻黄汤下去都没流汗，所以有时候，用麻黄不会得汗，会得小便，在这里用麻黄，小便会小出来很多，里寒很盛，这寒要去，用小便解，走小便排掉，如果是表，滤过性病毒在皮肤表面上的时候，汗一流就去掉了，这样距离最近，如果在身体里面呢？滤过性病毒在脏里面，还用发表的方法，就不行了，虽然有很多利尿剂，问题是这些利尿剂没有阳性，不是阳药，猪苓、茯苓不是阳药、三黄泻心汤，大黄去实，真正去热是靠黄连、黄芩，所以去寒要靠热药，麻黄是很热的药，用这三味热药，麻黄附子细辛汤一下去，病人小便出来，因为这时候要把滤过性病毒排出体外，唯小便最近。  \n\n       细辛遇到附子是温中，麻黄遇到附子，性就不会走表，它往下面走，如果病人是热且实，会开给病人去热及去实的药，承气汤就是这样来的，如果是少阴证的时候，是寒实，同样是有大便堵在里面，承气汤的热实是津液丧失，干掉了，寒实，是肠子没有蠕动，大便淤积在里面，就要靠附子细辛去让它蠕动，所以变成大黄附子细辛汤，大黄是去实的。  ', NULL, '麻黄附子细辛汤', NULL, NULL, NULL, '315、少阴病，始得之，反发热，脉沉者，$f{麻黄附子细辛汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820743, 'AA75CC2F5897D0756AF40C2C2D0922E2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5505, 323, 904001020, '       这种就是失治，如果少阴病，脉微细而沉，但欲寐，汗出不烦，自欲吐，这种状况下，一剂四逆汤下去就去掉了，但是如果不及时服用，至五六日，自利，自利就是利光了，营养能源都没了，烦燥，就是已经不受药了，阳虚在上面，阳没有根了，这看起来好像阳气恢复，实际上是死证，热快绝的时候，可以看到这些现象。  ', NULL, NULL, NULL, NULL, NULL, '314、少阴病，脉微细而沉，但欲寐，汗出不烦，自欲吐，至五六日，自利，复烦躁不得卧寐者，死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820744, '19FE73F74AE58BA2706B7521CA249A6A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5506, 323, 904001019, '       为什么息高？因为心脏都没有力量了，下焦都寒掉了，都没有蠕动了，气吸到喉咙就吐出去了，都没到横膈膜，代表下面功能整个都丧失掉了，临床上，癌症的病人，阴阳都分开了，就危险了，死的时候，最后的一气，会吐的很长。', NULL, NULL, NULL, NULL, NULL, '313、少阴病，六七日，息高者，死。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820745, 'D7BD9525760A7947ED37B29C8BC20A58', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5507, 323, 904001018, '        少阴病，四逆，手脚都冰冷掉了，在阴证，只要手脚还有温度，就有救，因为胃气都在，所以胃阳败绝掉，就是后天都没有了，\n       不烦而躁者，烦就是情绪不好，燥就是干掉了，嘴巴都干掉了，就是伤到津液，脉又摸不到，一般来说心脏衰弱到后来没有力量，尿毒的病人，心脏病的病人，到后来都可以看到。  ', NULL, NULL, NULL, NULL, NULL, '312、少阴病，四逆，恶寒而身蜷，脉不至，不烦而躁者，死。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820746, 'BF2FC8D923CE96E996137462B95E3245', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5508, 323, 904001017, '        为什么下利止，已经没有津液可以流了，完全流失掉了，而头眩时时自冒者，头晕眩的厉害，病人一定是极度的贫血，人在缺血的时候，脑就会昏，血造出来的第一个就是到头部，心脏的力量不够了，肠胃中生血的源头又没有，就会有晕眩的现象，如果这时候，看到病人，脸色有红红的，中医叫做戴阳，就是只剩一口气了，这时候用大剂的药，譬如四逆汤，开的时候用两计，不用钱来计。  ', NULL, NULL, NULL, NULL, NULL, '311、少阴病，下利止，而头眩时时自冒者，死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820747, '3025D4A7AE6DCB7870408EEC4F836D75', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5509, 323, 904001016, '      不管病在那一个阶段，病人又吐又下利，给的药根本不受受，吃了炙甘草汤，拉的吐的又是炙甘草汤，脾胃的功能都没了，肠胃都没有蠕动，遇到这种情形的时候，病人会躁烦，为什么？真阳剩一点点，最后的时候，坐着死的，眼睛都闭不起来，摸他的脉又很微细，照理说烦躁应该是脉洪大，所以现在脉证不合，如果烦躁，手脚热的再加脉洪大，就是承气汤证，现在脉证相逆，就是死证。  ', NULL, NULL, NULL, NULL, NULL, '310、少阴病，吐，利，躁烦，四逆者，死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820748, '2B7935D7F3B1448C4DCF1680E0F2CF56', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5510, 323, 904001015, '         身蜷而利，身疲倦下利者，手足逆冷者，代表胃的元气都没了，代表脾脏的功能完全没了，死证；这条辨就是独阴无阳，看不到阳证了，所以少阴证看到病人手脚温的，通通可以治，手脚已经都冷掉了，就完蛋了。', NULL, NULL, NULL, NULL, NULL, '309、少阴病，恶寒，身蜷而利，手足逆冷者，不治。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820749, '632F0A0AF8BBF08C5D35836AE062DFC9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5511, 323, 904001014, '         少阴病，但厥，无汗，遇到这种情形的时候，前面已经讲是少阴证了，就是告诉你脉微细，但欲寐，病人又有手脚冰冷没有汗，这时候应该温中才对，结果误用发汗走表药，会引动他的血，津液一离开了以后，血就会逆行经脉，因为水被误攻了，一发汗血就乱跑，这时候未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治，本来很好治的，就变成难治，血会流失很多，因为进入阴证的时候，他本身已经不能生血了，造血功能都衰退了，在这情况下再发汗，会动到仅剩的一些阴血，会很难治，在经方里面，遇到这种情形的时候，张仲景没有出方，大多用炙甘草汤去救逆，里虚掉了，血不足的时候，有两个方子，一炙甘草汤，一小建中汤。  ', NULL, NULL, NULL, NULL, NULL, '308、少阴病，但厥，无汗，而强发之，必动其血，未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820750, '5ABB304884411E2C9E9E8F0F026B7B10', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5512, 323, 904001013, '       一般来说，如果手脚开始热起来的时候，一直往身上热，代表胃气一直在恢复中，都是很好的现象，这是会恢复，如果热在膀胱，会小便带血，这可能是个人体质的关系，或肾里面有结石，肾结石在通过尿道的时候，会刮破很多地方，所以会有便血的现象，还是一种现象是肾脏病邪解掉的时候，会进入太阳，少阴和太阳是表里，会进入太阳的表证，如果热进入表证就流汗解掉了，这是在经脉上面就是汗解掉了；如果是在内脏上面，从肾脏传到腑上面的时候，膀胱会受热，肾脏的石头跑到膀胱里面去了，膀胱堵到发炎，都会有血的现象，如果是单纯的血结在膀胱里面，猪苓汤就来不及了，膀胱结石，用桃核承气汤把它打出来，如果只是单纯的小便有血的时候，在太溪穴的附近，肾结石穴有压痛点，可以摸到，这时候可以用猪苓汤攻。  ', NULL, NULL, NULL, NULL, NULL, '307、少阴病，八九日，一身手足尽热者，若热在膀胱，必便脓血也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820751, 'BA2E40B7C617A1D42BDFCF03E426CC48', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5513, 323, 904001012, '       少阴病，吐，本来就会吐，吐是从太阴传过来的，手足不逆冷，反发热者，不死，代表胃气还在，中土还没有败绝，脾土还在，所以不会死，脉不至者，灸少阴七壮，就是太溪穴。 ', NULL, NULL, NULL, NULL, NULL, '306、少阴病，吐，利，手足不逆冷，反发热者，不死；脉不至者，灸少阴七壮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820752, 'A75BDFD12B307F026C66EBA716839576', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5514, 323, 904001011, '       阴证要恢复的时候，都可见半夜的时候胃气回来，如果开始给病人吃治疗脏的药的时候，病人如果在午夜的时候，元气回来，半夜回元气的时候，第一个回来的就是胃气，病人感觉到饿，所有的任何药，不管轻重，不管药好不好，突然胃口大开就是病好了，所以药开对了，病人吃了一定胃口很好，表病在白天胃气回来，里病在半夜肚子饿。', NULL, NULL, NULL, NULL, NULL, '305、少阴病，欲解时，从子至寅上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820753, '94D8F95CC36043445FAF58F5658BCFA0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5515, 323, 904001010, '     少阴中风证，本来是应该是脉很沉且微细，如果阴脉浮起来了，代表阳气回头了，阴脉就是血脉，就是血脉回来了，代表病人自己会好。 ', NULL, NULL, NULL, NULL, NULL, '304、少阴中风，脉阳微阴浮者，为欲愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820754, '7A46F29172D45C81A3425F0B01E04FE3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5516, 323, 904001009, '        恶寒而蜷，少阴证也和麻黄汤证一样会怕冷，但是没有麻黄汤证的关节痛，他来不及痛，因为他根本没有动，倦怠在一边，如果病人开始时自烦，欲去衣被者，可治，常常会自己烦恼，把衣被踢掉，这代表阳气还在，胃气仍在，所以看到小孩没事在踢被的，没有事；少阴证到很严重的时候，呼吸出来的气，都是凉的，就危险了。 ', NULL, NULL, NULL, NULL, NULL, '303、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820755, '9ADA7470F50B61F1759A25281431F7A1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5517, 323, 904001008, '      反过来，如果利不止的时候，在这种条件下，观察，就死掉了，为什么手足温者，可治，中医的理论，以阴阳来看，病人独阴无阳，不治，全部是阴证，没有一点阳，没有一点动能，即死，如果手足温的，代表胃气还在，脾胃主四肢，就有救，治疗的时候用通脉四逆汤、四逆汤等，这时候要用很重的剂量。  ', NULL, NULL, NULL, NULL, NULL, '302、少阴病，下利，恶寒而蜷卧，若利自止，手足温者，可治。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820756, 'C6F45221CEBEDFC89C759631F6E75855', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5518, 323, 904001007, '       少阴病，如果脉紧，就是里寒很盛，到七八日，自下利，如果病人有下利的现象，胸暴烦，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈，这是阴寒要去了，阴寒从下利排掉了，这种排的现象一定是自己体能恢复了，一般来说，少阴病会有自愈的现象，常见的是肠胃功能恢复了，一旦肠胃功能恢复，脾脏太阴土一旺起来的时候，土能生金，肺就跟着好，金生水，跟着心脏和肾马上就好起来了，像这种肠胃功能很好的病人，他自己会恢复，食物一下去，变成血，到心，心火一蒸，胸阳肺津就壮起来，照理说如果进入厥阴的时候，手脚就越来越冰冷了，脉紧反去者，本来是紧脉，突然就缓和下来了，就是里寒已经去 掉了，为欲解也，此条辨里面没有处方，所以为什么练功夫很好，练功夫的呼吸吐纳，就是让肠胃蠕动，在练功夫时，当吐气的时候，此气是被手指打出来的，平常要练功打肚子，可以促进肠胃的消化功能，此为后天之本。  ', NULL, NULL, NULL, NULL, NULL, '301、少阴病，脉紧，至七八日，自下利，胸暴烦，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820757, '0C5204212642BE33426ACCCD0D668200', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5519, 323, 904001006, '      少阴病一发汗就会亡阳，阳已虚，尺脉弱涩者，阳已虚的时候，摸尺脉下焦的脉又弱又涩，涩就是血不够了，涩脉的脉形是扁扁的，复不可下之，这时候绝对不可以攻下，开处方给病人攻下的时候，一定要确定病人的血很足，怎样知道血足？摸左手的脉就知道了，开给病人发汗的药的时候，一定要摸摸他的气足不足，摸右手的脉，就是气，就知道足不足了。  \n\n解曰：少阴病，其脉微，原为阳虚，心脏无力，不可发汗，心和肾都是少阴，很微弱的状况下，再发汗会受不了，像发汗的药，像麻黄汤里面的麻黄、桂枝都是壮心的药。  ', NULL, NULL, NULL, NULL, NULL, '300、少阴病，脉微，不可发汗，亡阳故也；阳已虚，尺脉弱涩者，复不可下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820758, '1D36297C0B3E67840D7E2D1B0DA7BB55', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5520, 323, 904001005, '这条就讲少阴病不可汗法。  ', NULL, NULL, NULL, NULL, NULL, '299、少阴病，脉细沉数，病为在里，不可发汗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820759, '9D9440D59FB9D55E64124A6BAEC54EC3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5521, 323, 904001004, '       少阴证的时候病在少阴，病在很里面，阴很盛，这时候如果病人呈现的咳而下利，\n      谵语者，为什么谵语？被火气劫故也，小便必难，以强责少阴汗也，这条辨最主要讲少阴病，虽然里面阴寒很盛但不可以发汗，只有在太阳表证的时候，才用汗法，少阴证的人不可能强发汗，强发汗的结果，不但没有把少阴病治好，反而会让表更虚，阳会更虚，因为发汗的药全部是阳药，一发汗阳气就散掉了，阴证的时候已经是阴比较盛，阳比较少了，还在去阳，阴会更盛阳会更少，这时候被火气劫，小便会更少，如果强发汗，津液会枯竭掉，这是很危险的动作，所以少阴病绝对不可以发汗。  \n\n     少阴证的时候小便难，下焦虚寒，肾的阳火没有办法把膀胱的水蒸化出来的时候，病人小便不通利，这时候开真武汤，这是中医的辨症论治，西医来看是摄护腺肥大时，都可以看到真武汤证。', NULL, NULL, NULL, NULL, NULL, '298、少阴病，咳而下利，谵语者，被火气劫故也，小便必难，以强责少阴汗也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820760, 'E70CDE5B36AA64CF8AA53086B620AA8D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5522, 323, 904001003, '       左右手的脉又紧又浮。照理说是表寒应该无汗，结果摸到有汗，\n      就是亡阳：中医的亡阳观念，人身上的阳和阴是交接的，当阴寒很盛的时候，阳就离开了，阳就慢慢的浮出来，就是我们的体力精神慢慢的离开身体，很快走人了。这时候阳浮上来，可以摸到脉很浮，但是重按到里的时候就没有脉了，伤寒表证的浮脉，轻轻的就摸到脉，重按的时候脉跳的更强，摸到脉很浮很紧。重按就没了，这脉没有力，就知道里面完全虚掉了，病人应该没有汗，结果汗流很多，这就是亡阳，所以病人在大虚大弱的时候，脉会变的很芤很大，因为要血，又没有血，就会撑大，此际病人反而一直流汗，流汗不止，这就是脉证不合，脉证不合就很危险，所以如果看病人很虚弱，摸他的脉也很虚弱，就没有关系，来得及。如果刚好相反的，人很虚弱，脉却很大，就是亡阳了。\n     此属少阴，法当咽痛，这种状况，阳热就是讲发炎的病毒，热是很轻的，热往上走，走到喉咙，喉咙就发炎，喉咙会痛，这喉咙痛和太阳证的喉咙痛又不一样，这喉咙痛是因为身体虚掉了，里面的滤过性病毒没有地方待了，往上跑了，发炎的现象往上跑了，\n     而复吐、利，阴病一定会有下利的，为什么会吐？少阴证是从脾，从太阴传进来的，始受在太阴，本来就是津液堵在中焦，日久没有好才会进入少阴，造成上下不通利。  ', NULL, NULL, NULL, NULL, NULL, '297、病人脉阴阳俱紧，反汗出者，亡阳也；此属少阴，法当咽痛，而复吐、利。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820761, 'AA4A3F74546136D4EF18F0847EA5C822', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5523, 323, 904001002, '       太阴证的时候是自利不渴，太阴、少阴、厥阴都会下利，只是下利的程度有深浅，如果自利不渴，就知道病在太阴，寒湿在上焦，所以他不会渴，\n      如果自利而渴者，是少阴，寒在下焦，下焦肾虚的时候，会一直在下利小便，\n      虚，故引水自救，所以会有口渴，病人会想喝水，\n      若小便色白者，少阴病形悉具，小便颜色整个变成淡白色，就是标准的少阴证，\n     为什么?因为下焦虚，有寒，不能制水，故令色白也，寒的观念就是根本没有温度了，根本不气化了，蠕动整个停摆，膀胱像一块死肉没有用，他的小便根本是漏出来的，中医有分寒热，西医就没有分寒热，西医只管发烧。  ', NULL, NULL, NULL, NULL, NULL, '296、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故引水自救；若小便色白者，少阴病形悉具。小便白者，以下焦虚，有寒，不能制水，故令色白也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820762, '17ACC92C7869C46323F1FDA97641E6D2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5524, 323, 904001001, '         微脉是代表气很衰弱了，细脉代表血不够了，脉微细就是气血不足的状况，但欲寐，是少阴的主证。例：脉微细，且下焦寒到小便无法自禁，没有办法控制一直往外流，因为都没有蠕动了，膀胱口都开着，人的水是经过肾阳气化出来的，所以尿有点黄，现在他小便是白的，所以要用大剂的附子下去，现在西医连尿失禁都治不好，因为不知寒热也。  ', NULL, NULL, NULL, NULL, NULL, '295、少阴之为病，脉微细，但欲寐也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617624737820763, '6AA5237BF94AAE2759D659C71B13FA15', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:41:32', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5525, 323, 904001031, '       所谓少阴病摸他的脉一定很微细，二三日咽痛者，单纯咽痛的可与甘草汤，就是单味的甘草，用甘草解毒就好了，这喉咙痛是因为阳热冲到喉咙来，如果是在胸腔的话是黄连阿胶汤，\n      不差者，吃了甘草汤没好的，一定是有痰在里面，痰在最高的地方会加桔梗，前面的甘草加桔梗就好了。  ', NULL, '甘草汤，桔梗汤', NULL, NULL, NULL, '325、少阴病，二三日咽痛者，可与$f{甘草汤};不差者，与$f{桔梗汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030534, '7E9A179A4BDEB6C85FFA595A44F9154F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5526, 323, 904001030, '      喉咙痛有几种处理的方式，像太阳伤寒表证的喉咙痛，吃桂枝汤，感冒好了，喉咙也好了，不用吃喉咙药，阳明篇也有喉咙痛，下焦燥热，燥气往上冲，冲到脑里就是手足躁扰、发狂奔走，冲到喉咙，喉咙发炎，这时候吃喉咙药没有用，把大便清出来就好了，现在的猪肤汤是治疗少阴证的喉咙痛，后面还有甘草汤也是治疗喉咙痛的。', NULL, '猪肤汤', NULL, NULL, NULL, '324、少阴病，下利，咽痛，心烦者， $f{猪肤汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030535, 'F469F6CCA3F6AF8014F2D50C16EB4750', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5527, 323, 904001029, '         吴茱萸汤是止吐的圣药，这就是少阴证从太阴进入少阴，少阴证没好将进入厥阴的现象，少阴证已经是很虚了，快到厥阴的时候，肝脏的血要出来，人最后的免疫系统要作最后的抵抗之前，在要出来还没出来的时侯，这时候要把肝脏的血逼出来，肝就膨胀起来，所以肝脏一肿起来顶到胃，胃受压迫就吐。手足厥冷，手脚冰冷。因为血虚掉了，因为少阴证到后来，肠胃虚掉了，没有造血的功能，所以这时候手脚一定是冰冷，烦燥欲死者，因为东西吃不下去，一直恶心想吐，情绪一定不好的，因为热在上面，本来食物因为胃的蠕动应该往下走的，胃的气就往上跑，所以吴茱萸汤主之，吐的很厉害的时候，开吴茱萸汤去止呕，吃人参、甘草、大枣，把吐过伤到的津液补回去。  ', NULL, '吴茱萸汤', NULL, NULL, NULL, '323、少阴病，吐剧。手足厥冷，烦燥欲死者， $f{吴茱萸汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030536, 'DCCB7448D9A83E77CEB0A65A050DD1C9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5528, 323, 904001028, '刺关元穴，关元是止下利很好的穴道，为什么不用灸?因为里面已经肠炎了，再灸会增热，造成病毒蠕动的更快，散播的更快。  ', NULL, NULL, NULL, NULL, NULL, '322、少阴病，下利便脓血者，可刺。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030537, '5858E2D77BB375FB192903A388C5028E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5529, 323, 904001027, '       这是发炎的太严重了，到后来肚子都痛了，外证是肚子痛了，里面肠子已经破了，小便不利，下利不止，因为膀胱里面的水都从大便走了，太阳篇介绍猪苓汤的时候，张仲景说如果利不止的时候，利小便就好了，反过来，水从大肠出来，也会小便不利，所以还是桃花汤主之。  ', NULL, '桃花汤', NULL, NULL, NULL, '321、少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者， $f{桃花汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030538, '9F1A04A173749740645A104BBB3EE662', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5530, 323, 904001026, '      为什么叫桃花汤?桃花是红色的，所以桃花汤煮起来整个是鲜红的，因为里面有赤石脂，少阴证本来就是阴寒的证，如果病人下利便脓血的时候就变成危证了，本来里寒很盛，蠕动不行，这时候得到肠炎，感染滤过性病毒便脓血，会变成肠出血或肠穿孔出血，很危险的，桃花汤和黄连阿胶汤刚好相反，黄连阿胶汤是热往上冲，所以心中烦不得卧，造成病人睡不着，热就是发炎坏死的东西，如果热往下走就是桃花汤，造成病人下利带血。  \n\n     桃花汤是里寒下血的时候用的。下利分热利、寒利，最轻的一般的热利用葛芩连汤可以治好，还有黄芩汤都是热利用的，桃花汤是里寒下利，也是受到感染而来的。', NULL, '桃花汤', NULL, NULL, NULL, '320、少阴病，下利便脓血者， $f{桃花汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030539, 'AF451AF026A2B1BF1D5235515A064C5E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5531, 323, 904001025, '       如果是身体寒，骨节痛，怕冷恶寒，脉弦浮紧者，就是麻黄汤，代表这寒是在表，产生全身的骨节疼痛，所以有时候得到感冒，很怕冷，摸到皮肤都会痛，就是免疫系统很好，把滤过性病毒抗在外面；附子汤的症状很像麻黄汤，但是摸到的脉是沉的，附子汤的全身痛，就是因为少阴证本来就是里寒很盛，寒就是血冷掉了，血为什么冷掉?因为水太多了，血里面有百分之七十以上是水。约百分之三十是血，如果水太多了，血太少了，水的温度是冰的，所以摸水肿的病人皮肤是冰的，就是水太盛了，水太盛造成手脚没有温度，真正供应营养到细胞的是靠血，结果里寒很盛的时候，血液循环就会受到障碍，四肢关节没有得到正常新鲜的血，造成了手足寒，骨节痛，脉沉，所以附子汤主之。  \n\n       附子汤里面有炮附，炮附本身能壮里阳，里寒很盛的时候用炮附，因为水太多了，造成少阴证，所以加茯苓，茯苓是利尿剂，实际上，全身的水能运行就是靠脾脏，因为脾是土，土能治水，所以加白朮。茯苓和白朮常常一起用，为什么用人参?人参专门健脾胃，因为水多的病人，到后来脾肾的功能就差掉了，在这虚弱的状况下得病，人参下去把脾胃的功能健起来，在经方里面，所有的胃不和，心下痞的时候，一定会用到人参，因此肠胃功能不好的时候，人参是来健肠胃的，所以有泻心汤里面一定会用到人参，最后一味药是白芍，因为静脉血液循环太慢了不动了，白芍加强它让它流回心脏，因为里面有壮心阳附子，所以再用壮心阴的白芍，方义就是如此设计的，如果加甘草，甘草一下去，结果病人肠胃的功能很好，四肢还是冷的，所以不加甘草，让药一下去马上跑到皮肤表面了。人体中动脉即阳，静脉即阴。', NULL, '附子汤', NULL, NULL, NULL, '319、少阴病，身体痛，手足痛，骨节痛，脉沉者，$f{ 附子汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030540, 'B7C59BDB4ECDBBDAD9A218FCC3B6E0CC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5532, 323, 904001024, '      过去很多医家在注解灸背后的某某穴，不需要，张仲景的意思，背那儿寒就灸那儿就好了，例如膏肓寒就灸膏肓，中极寒就灸中极，灸的功能就是引阳外越，因为里阳不足了，所以灸能让脏腑肠胃的功能激发起来。  \n\n      为什么口中和，就是津液还没有伤到，如果津液伤到就燥渴了。', NULL, NULL, NULL, NULL, NULL, '318、少阴病，得之一二日，口中和，其背微恶寒者，当灸之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030541, '413C01076EED23856472B4E6717EABE8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5533, 323, 904001023, '       得到二三日，一定津液伤到了，第二，心中烦，不得卧者，少阴证本来就是里寒，里寒很盛才会成为少阴，我们身体里面都是寒的，我们的阳热、体能、营养液下到里，这阳应该和寒相交，才会为身体所用，才会把营养的东西吸收下来，里面寒很盛的时候，就是肠胃功能蠕动太慢了，根本没有办法吸收营养，结果食物在里面坏死掉了，在肠里面会变成肠炎，少阴证再下利就危险了，所以用消炎的药，就是黄连、黄芩，黄连、黄芩，都是清热的药，杀菌力很强的，起因是肠蠕动太缓慢，鸡子黄就是鸡蛋里面的蛋黄，阿胶是驴皮熬成的膏，阿胶完全是滋阴的药，就是补阴血不足，完全补心血，少阴证的病人，脉微细，但欲寝，代表心脏已经衰落了，一定血虚了，因为肠胃蠕动太慢，没有办法正常的吸收营养，产生新的血，造血的功能不是很好，在治疗病的同时，要把血补足，因为自己来不及造血，所以开补血的药，用阿胶、鸡子黄。为什么用白芍？白芍的性是酸的，酸性的药有固摄的功能，阿胶、鸡子黄在补心脏和肾阳的血，药下去以后，因为病人的体能太差，补进去会散出来，所以用白芍把它固到。', NULL, '黄连阿胶汤', NULL, NULL, NULL, '317、少阴病，得之二三日以上，心中烦，不得卧者，$f{黄连阿胶汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617640836030542, 'B7F5BBBE79F5F1FCF3F0E6A733D513C4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:47:02', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5534, 323, 904001035, '       这时候已经很危险了，所以白通加猪胆汁汤主之，很多伤寒、疟疾、霍乱后期就是这样子，拉到没有东西拉了，肠胃整个停滞，这时候为什么病人会有干呕烦者?只剩一点点的生命力了，病人完全虚掉了，虚掉的时候会有烦躁的现象。\n\n     白通加猪胆汁汤就是白通汤加猪胆汁，过去的看法，这已经是很危险的时候了，阴阳相隔了，不管原因是什么病，照理说脉微弱下利病人应该虚掉了，结果病人烦躁，这是逆证，脉证不合，有的人只剩一口气了，摸他脉一息十至，这人快死了，很多癌症的病人就是这样，这时候白通汤下去，必然没有感觉，为什么加猪胆汁和人尿?因为这两个不但有滋补的功能，最重要的是这二个是非阴寒的药，他能把阴阳相隔的东西打开来，把白通汤引到阴去，尿用童子尿，若无胆亦可用，所以人尿比胆汁重要，用胆汁是为了帮助消化。  \n\n      脉暴出者死，微续者生，什么叫暴出?喝了汤药以后，如果脉突然跳的很强，这是药力发出来的脉，不是真正元气回来的脉，脉微微出来，代表病人收到了，有的人不受药就完了，受药的时候，脉会微微的跳起来。  \n\n学者到此再学会用白头翁汤，桃花汤。伤寒、疟疾、霍乱没有不会治的。', NULL, '白通汤,白通加猪胆汁汤', NULL, NULL, NULL, '329、少阴病，下利，脉微者，与$f{白通汤}。利不止，厥逆无脉，干呕烦者，$f{白通加猪胆汁汤}主之。服汤，脉暴出者死，微续者生。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617648074047558, '7ADC1DD34EF0B82E79D830685D36D2CF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:16:29', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5535, 323, 904001034, NULL, NULL, '白通汤', NULL, NULL, NULL, '328、少阴病，下利，$f{白通汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617648074047559, '373AE8DEC8E5FD169F610934A67B0FB9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:16:29', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5536, 323, 904001033, NULL, NULL, '半夏散及汤', NULL, NULL, NULL, '327、少阴病，咽中痛，$f{半夏散及汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617648074047560, 'C89C3CC64E289E8CC1C7C7194D8F4670', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:16:29', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5537, 323, 904001032, '喉咙痛的现象再进一步，严重到生疮，不能语言，声不出者，这时候桔梗甘草汤已经来不及了，要用苦酒汤，苦酒就是醋，为什么叫苦酒?酒变成酸的就是醋，酒不好喝就是苦酒', NULL, '苦酒汤', NULL, NULL, NULL, '326、少阴病，咽中伤，生疮，不能语言，声不出者，$f{苦酒汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617648074047561, '6606F3DA6CE9AE0DCE7277AA456E8D39', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:16:29', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5538, 323, 904001036, '      或，是副证，不一定看得到的现象，主证是腹痛，小便不利，四肢沉重疼痛，少阴病本来就是里寒很盛，水湿很盛，如果小便很正常出来的话，小便一定是白的，四肢很痛就是附子汤，现在小便不利了，已经是水堵在里面了，属于虚寒的积水，为什么腹痛，水通通堵在下焦，下焦肠子里面的水分太多，肠壁上的血液循环一定不好，所以肚子会痛，这时候用真武汤主之。  \n\n      茯苓三钱，芍药三钱，生姜二片，白朮二钱，用白芍止腹痛，腹痛的原因是因为肠壁上的静脉血管的血，没有办法回流心脏，身上五脏六腑的血通通要回到肝，再从肝的静脉出来，这时候开白芍，白芍能让血很快地归肝。  ', NULL, '真武汤', NULL, NULL, NULL, '330、少阴病二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气，其人或咳，或小便利，或下利，或呕者，$f{真武汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 617649787678790, '016FDED82EB6EB46E451D81D5322DE5C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:23:27', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5539, 323, 904001045, '       如果少阴病，下利，脉微涩，呕而汗出，代表肠胃的阳虚掉了，胃的津液一直在丧失，一直在下利，\n       数更衣，就是一天到晚跑厕所，\n       反少者，津液丧失很多，肚子里面根本没有东西拉了，\n       当温其上，灸之，可以用温灸的方法，下利很严重的时候，灸神阙，会用到灸一定是寒利，寒就是拉出来的很多，可是没有味道，灸神阙的时候隔盐灸。  \n\n以上讲的是少阴证。  \n\n       例：有一西医是小儿科医生，下利清谷，又全身肌肉、关节酸痛，半年了，下利清谷代表肠胃太寒了，没有热度没有胃阳，所以没有办法消化，寒到后来全身关节会痛就是虚寒，附子汤，刚开始用生姜泻心汤，如果用泻心汤，这种症状，甘草泻心汤比生姜泻心汤好，因为生姜泻心汤比较着重在湿热的部分，甘草泻心汤比较着重在虚寒的部分，病人早上吃了生姜泻心汤，下午说半年来第一次感觉食物停在胃里面，到晚上十点又发病了，所以要用附子汤，附子汤里面重用干姜，加炙甘草，这是少阴证的下利。如果是实寒就是大黄附子细辛汤证。  \n', NULL, NULL, NULL, NULL, NULL, '339、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297478, '78EE05BA46B4A779310618EE976E31E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5540, 323, 904001044, '       这条辨讲的是寒实，寒代表不动了，实代表有东西堵到了，有东西梗到的时候，饮食入口则吐，吃东西下去就吐出来了，心中温温，就是胃里面很难过，欲吐复不能吐，吃东西吃不下去，想吐又吐不出来，始得之，刚开始得到的时候，手足寒，脉弦迟者，手脚冰冷，弦脉就是有水，脉迟代表没有蠕动代表寒，是寒实结在上焦，此胸中饮实，实是隔在胸口上焦，不可下也，当吐之，不要用攻下的，采吐法，没有药，用肥皂水也可以，针灸也可以，扎内关，心里想吐，就吐出来了，内关是心包经的，管心意的；若膈上有寒、干呕者，干呕就是恶心，但是里面空的，根本没有东西，连水都没有，空就是虚的，这时候不可吐也，急温之，宜四逆汤，根本没有东西，所以不可以用吐的，用温法，用四逆汤来温它。 ', NULL, '四逆汤', NULL, NULL, NULL, '338、少阴病，饮食入口则吐，心中温温，欲吐复不能吐，始得之，手足寒，脉弦迟者，此胸中饮实，不可下也，当吐之；若膈上有寒、干呕者，不可吐也，急温之，宜$f{四逆汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297479, '04CAB2FA3EA3CB2F074E57712EBF8044', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5541, 323, 904001043, '      血脉通通冷掉了，手脚冰冷掉了，赶快用四逆汤。', NULL, '四逆汤', NULL, NULL, NULL, '337、少阴病，脉沉者，急温之，宜$f{四逆汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297480, '30F50E2D60C8B7B41AF6A4F0526B7008', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5542, 323, 904001042, '      大承气汤和大黄附子细辛汤是表里药，要会区别会用，一个是热实，一个是寒实用的。  ', NULL, '大承气汤', NULL, NULL, NULL, '336、少阴病，六七日腹胀不大便者，急下之，宜$f{大承气汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297481, 'DF4FEE9021C514156261B8EA0218E323', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5543, 323, 904001041, '      本身是少阴证，所以肠胃蠕动就不是很好，大便堵在里面，结果大便干掉了变成硬块，这时候胆汁一直流出来胆汁是帮助消化的，胆汁并没有办法攻坚，把大便打散要靠芒硝，胆汁是青色的，胆汁通过大肠出来，所以自利清水，色纯青，青水就是胆汁，心下必痛，胃里面难过，胃痛，口干燥者，急下之，至此已可确定是肠中有燥屎，立下大承气汤，不可犹豫。  ', NULL, '大承气汤', NULL, NULL, NULL, '335、少阴病，自利清水，色纯青，心下必痛，口干燥者，急下之，宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297482, 'C692CCDA0B1CCFC9531F7C6E5EECF3CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5544, 323, 904001040, '       少阴病里面本来就已经是阴寒很盛了，如果转成口燥咽干，就是病人已经从阴转成阳了，从少阴证转成阳明证的现象，这是好的现象，这时候赶快把它去掉，刚从阴回到阳的时候，元气还没有很恢复，结果大便燥结在肠里面，还是用大承气汤攻，所以不管病从那来，只要症一样，少阴篇里面还是有用到大承气汤的；如果病人没有口燥咽干，里面津液很多，舌苔白的，大便不通，就是大黄附子细辛汤证，这是寒实的时候用。口燥咽干就是热实，口不燥咽不干就是寒实。  \n\n       这些都是张仲景预防的设施，从阴证转成阳证的时候，照理说是有治，结果进入阳明证的时候，津液还会再耗损，本来阴证已经很虚热了，进入阳明证大承气汤不攻掉，津液一直没有办法恢复，反而会很危险。 ', NULL, '大承气汤', NULL, NULL, NULL, '334、少阴病，得之二三日，口燥咽干者，急下之，宜$f{大承气汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297483, '4EC87451037A735D29BEEA14EC4C9190', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5545, 323, 904001039, '        猪苓汤是用在水和热并结，猪苓汤在太阳篇里面讲到病人上焦口渴烦躁、小便不利；小便不利就是热堵到了，热就是发炎了，内症可能是膀胱炎或肾结石堵到了，少阴证也有猪苓汤，其原因不一样，症是一样的，也是一样水热并结，下利六七日，小便不利，咳而呕，渴，心烦不得眠者，也是热，但是少阴证是虚热，太阳证是移热，同样是水堵到了，所以用猪苓汤主之。 \n\n 利水的方子：  \n\n        一：五苓散，如果是表热造成的小便不利，表太热了水气不得下降就是五苓散。 \n        二：如果是表寒，寒束在表上面，水没有办法发散，水结在下焦就是小青龙汤。 \n        三：如果是里面虚寒掉的造成小便不利的就是真武汤。 \n        四：猪苓汤是水热并结，里面发炎了，西医用试纸测小便里有红血球，因为结石把输尿管刮破了，造成小便带血，所以猪苓汤里面有阿胶止血。  \n', NULL, '猪苓汤', NULL, NULL, NULL, '333、少阴病，下利六七日，小便不利，咳而呕，渴，心烦不得眠者，$f{猪苓汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297484, '02573D3BAA40167AC8EAF423943B682C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5546, 323, 904001038, '      四逆散里面有炙甘草、枳实、柴胡、芍药，实际上四逆散是大柴胡的变方，大柴胡汤里面把大黄和黄芩拿掉，就变成四逆散，为什么有四逆散?因为是少阴证，少阴证寒里较多，发炎的现象比较少，四逆散和四逆汤不一样，四逆散很轻的，四逆汤很重的，四逆散实际上在临床上看的时候是胆结石，胆结石的病人手脚冰的，痛的冒冷汗，四肢厥逆，因为是胆结石堵到的，不是肠炎，不是有病毒，所以不用黄芩，也不是大便堵到所以不用大黄，用柴胡，柴胡入少阳，入半表半里中间，用白芍止腹痛，枳实专门去在十二指肠、胃下方、消化系统刚开始的地方堵到的时候用的，炙甘草让药停在上焦。  \n\n      四逆散用散剂，四味药等量捣成粉，用米汤来服，如果确定病人是胆结石，四逆散里面再加滑石、五倍子、海金沙，因为加了滑石大便出来会很快，会有下利，所以治疗胆结石的时候，四逆散要饭后吃，饭后吃是为了让食物顶在下面，药粉在上面，让药尽量入胆，不要走太快，用炙甘草就是不希望药走太快，再饭后吃就是让药停的更久，不然会药走了，石头还没有完全排出来。胆结石的来由，可能是三餐不定时，或者吃得太油腻，结果胆汁没有正常分泌，胆汁的分泌是来自心脏搏动的压力，我们治疗的时候。用炙甘草来强心、用柴胡通利三焦、用黄芩去除湿热，用枳实打开胆管，这个处方就已经是治疗胆结石的基本处方；我们可以再加上神农本草经上面的滑石、五倍子、海金沙等，处方就开好了。  \n\n胆结石的主证： \n      一：在阳陵泉下一寸的胆结石穴有压痛点。 \n\n      二：痛起来的时候，胸痛彻到背后去，从胆的地方痛到肩膀上去。 \n\n       三：腹诊的时候，胆经的日月会有压痛点。 \n', NULL, '四逆散', NULL, NULL, NULL, '332、少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，$f{四逆散}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297485, 'B89C9E7F0CEBC3AAF6E1F137066D71BA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5547, 323, 904001037, '      要内外通达就是用通脉四逆汤，下利清谷，吃进去的食物通通跑掉了，这时候里寒外热，就是肠胃通通没有蠕动了，吃进去的食物直接流出来的，不是大出来的，阳虚的时候，肛门的口都收不了直接流出来的。  \n\n      通脉四逆汤里重用炙甘草，再加生附，配合干姜在用，像通脉四逆汤、白通汤、桃花汤大部分都是用在伤寒、霍乱、瘟疫的时候，但有的时候是五苓散，要临症上辨症论治。  ', NULL, '通脉四逆汤', NULL, NULL, NULL, '331、少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止，脉不出者，$f{通脉四逆汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618276177297486, '49B89F0E640CB113015F1CC5B37D8570', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:52:14', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5548, 324, 904001107, '       看到厥阴证的时候，如果昏迷、精神不好、手脚冰冷的时间，和发热的时间差不多，譬如厥五天热五天，或者是热比较多冷比较少，代表免疫能力还很强，自己慢慢会好，如果昏厥或逆冷的现象比较多，\n       始发热六日，厥反九日而利，就是病很深了，抵抗力不够了，如果手脚冰冷是四逆，如果冰冷到手肘就是厥了，阴寒到极限了，厥就是阴之尽，就很危险了，这种症状当不能食，\n      今反能食者，恐为除中，除中讲的就是回光返照，当胃气完全停顿的时候，冲阳脉都没有了，摸他手脚冰冷的，病人开始吃点东西，就是老天爷不希望病人作饿死鬼；\n     食以素饼，微发热者，知胃气尚在，必愈，吃了东西以后，开始微发热，热慢慢起来的，知道胃气尚在，还有机会好；\n     恐暴热来出而复去也，这热就是食物所产生的热能，\n     后三日脉之，其热续在者，期之旦日夜半愈，过三天再摸脉，如果热还在，就会晚上的时候恢复回来，胃气会正常，这就可以救，\n     为什么?所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，为厥相应，厥相应就是热和冷厥的时间相同的，这病人不会死，故期至旦日夜半愈。又三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也，为什么会痈脓？热就是免疫系统赢了，因为病在厥阴，热气发出来的时候，会把病毒赶出去以后，病毒不会马上离开身体，病毒进入某处，譬如进入肠子里面就会化脓的现象，就是邪热太过了。  \n', NULL, NULL, NULL, NULL, NULL, '346、伤寒，始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中。食以素饼，微发热者，知胃气尚在，必愈；恐暴热来出而复去 也。后三日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，为厥相应，故期至旦日夜半愈。又三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618278735331398, '0A56E3F0FD61383067F110524349C98A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 12:02:39', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5549, 324, 904001106, '       一般来说，伤寒就是表寒，可是厥阴证的时候，因为病毒已经进入到身体里面，看不到表证的，看不到发热恶寒，所以感冒有症状的，代表免疫系统很好，伤寒，先厥，厥阴证的病人得到感冒没有症状的，一得到感冒，马上就昏迷过去了，后发热而利者。病人又发热回来，发热代表免疫系统强起来了，把病毒排出去，排出去会下利，下利的时候代表病毒跟着大便清出来，肠胃功能恢复的时候利会自止，如果又昏迷过去的时候，代表抵抗力又输了，又会下利。', NULL, NULL, NULL, NULL, NULL, '345、伤寒，先厥，后发热而利者，必自止，见厥复利。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618278735331399, '5D57749419D8EE5393207E2FA94899C9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 12:02:39', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5550, 324, 904001105, '这是废话，这条辨可能是从别的地方来的，前面已介绍过许多了。', NULL, NULL, NULL, NULL, NULL, '344、诸四逆厥者，不可下之，虚家亦然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618278735331400, 'CAD618DFE22347BEF7D924F1B4ECB765', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 12:02:39', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5551, 324, 904001104, '     厥阴病的时候，如果想喝水，渴欲饮水，代表内脏功能慢慢恢复中，因为免疫系统强起来了，把病毒赶出去了，自然而然就会好起来，不需要用药的。  \n', NULL, NULL, NULL, NULL, NULL, '343、厥阴病，渴欲饮水者，少少与之，愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618278735331401, '79D5766A6C9D6AD71C4E8AC9DBEEC3B4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 12:02:39', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5552, 324, 904001103, '       所以阴证要恢复的时候都是在半夜。  ', NULL, NULL, NULL, NULL, NULL, '342、厥阴病，欲解时，从丑至卯上。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618278735331402, '2A155C444ABE3433DC2626A3996F4324', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 12:02:39', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5553, 324, 904001102, '      如果病人厥阴证的时候中风，脉微浮，微浮代表免疫系统恢复了，代表阳气回来了，所以这时候肝血很足，身体很好的人，如果不幸病进入厥阴的时候，他会痊愈的，因为肝脏是最强的。  ', NULL, NULL, NULL, NULL, NULL, '341、厥阴中风，脉微浮，为欲愈；不浮，为未愈也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618278735331403, '7ADB0FDB37F5B41ADB60C380032D9DD4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 12:02:39', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5554, 324, 904001101, '       太阴影响到中焦，少阴影响到下焦，到了厥阴的时候，中焦、上焦都冷掉了，肠胃里面都冷掉了以后，里面没有消化的能力，没有抵抗力在里面的时候，人吃的东西里面的寄生虫就开始躲在身体里面，因为肠胃常年不好，没有办法把它消化掉排出去，虫卵就在身体里面生成虫，遇到这种情形的时候，寒热并结，通通列入厥阴证，所以到了有虫的阶段就会看到厥阴证。  \n\n        中医小儿科中望诊上，唇上有白点，很整齐的排列，眼睛下方稍微黑黑的，脾开窍在唇，有白点代表中寒，上面有黑黑的代表上热，寒热并结了，有虫的时候腿上的虫区（百虫窝）会有压痛点，病人的症状消渴，就是上焦有热，热在上焦所以口渴，气上撞心，热气往上冲，因为热气被下面的寒顶上来的，心中疼热，感觉胃里面辣辣的很烫，好像吃到大蒜一样，饥而不欲食，肚子感觉到饿，却吃不下东西，代表脾脏的功能还在，但是胃里面不好了，虫在里面所以吃不下去，食则吐蚘，因为东西吃下去，虫也在吃，下之，利不止，本来就是肠胃比较寒了，如果攻下，就下利不止了，就更危险了。  ', NULL, NULL, NULL, NULL, NULL, '340、厥阴之为病，消渴，气上撞心，心中疼热，饥而不欲食，食则吐蚘，下之，利不止。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618278735331404, 'E80C3995714A2361276A947739961B06', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 12:02:39', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5555, 324, 904001119, '       照理说伤寒就是发热，如果发热的现象兼有下利，厥逆，躁不得卧者，这种就是死，在厥阴证里面，最担心的就是烦躁不得卧，人到最后关卡的时候，到肝脏里面的时候，如果肝的功能没有办法把癌细胞排出体外的时候，元阳要离开的时候，都会看到这种烦躁的现象，下利就是体能一直排出来，厥阴篇讲的都是下利，平常看到这情形，除了大肠癌外，病人都是大小便不禁了，要赶快把利止掉，不止掉就很危险了。有时候看他利止了，结果是里面没有东西利了，遇到这种情况的时候，一般用大剂的四逆汤，下利的话用赤石脂禹余粮汤，用涩剂去止利。', NULL, NULL, NULL, NULL, NULL, '360、伤寒发热，下利，厥逆，躁不得卧者，死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815686, '21737A0349EC25E46D67F931E1C9A02D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5556, 324, 904001118, '      伤寒六七候以后，从太阳、少阳、太阴、少阴，进入厥阴了，这时候脉微，手足厥冷，摸到脉很微细，手脚冰冷，烦燥，灸厥阴，厥不还者，死，看到病人手脚冰冷，照理说病人里面阴寒很盛了，肠胃功能都不好了，身体都虚弱了，结果病人烦躁，这烦躁就是人处于心脏正要衰弱的时候，病人会有这种情绪很烦躁的现象，这就是阳气要脱的现象，如果烦躁了以后，起脉，脉微微的回来了，胃口开起来了，手脚热起来了，这手脚一热起来代表胃气回头了，就是这人有救了。胃气如果不回头了，手脚还是冰冷的，一般来说这种比较难治，很危险。癌症的末期都可以看到，尤其是肝癌。  ', NULL, NULL, NULL, NULL, NULL, '359、伤寒六七日，脉微，手足厥冷，烦燥，灸厥阴，厥不还者，死。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815687, 'C1CD468657B18C8AF99BBF0F50D68913', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5557, 324, 904001117, '     如果冷的时间比较多，热的时间比较少，复厥五日，冷的时间越来越延长，这病为进，病越来越重；寒多热少，阳气退，故为进也，病在加深。  ', NULL, NULL, NULL, NULL, NULL, '358、伤寒厥四日，热反三日，复厥五日。其病为进；寒多热少，阳气退，故为进也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815688, 'FF1C90A75C09A219323DA15E8BC7F2FB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5558, 324, 904001116, '       厥阴病的时候，病人发热的时间比手脚冰冷的时间多，代表病人的体能很好，其病当愈，一般来说自己会痊愈，如果没有痊愈，代表热没渲泻的地方，小便没有清出来，厥阴证是肝里面的滤过性病毒，如果没办法完全清出来，就会在身体里面，病毒如果在表就发汗发掉了，如果在厥阴就由小便跑出来了，如果从小便出不去了，病毒就往大肠跑，大便就会带脓血。  ', NULL, NULL, NULL, NULL, NULL, '357、伤寒发热四日，厥反三日，复热四日，厥少热多，其病当愈。四日至七日，热不除者，其后必便脓血。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815689, 'C706C8440085D33D55CDFB99D9DC9C17', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5559, 324, 904001115, '       膀胱结到的时候，小腹痛是主证，就是中极到关元这一带剧痛，\n膀胱结有四种状况： \n      一：水结膀胱，少腹痛，最明显的状况是小便不利，这时候用五苓散。 \n      二：血结膀胱，少腹痛，小便不利，用桃核承气汤。 \n      三：热结膀胱，少腹痛，小便红涩，小便出来有刺刺的感觉，用猪苓汤。 \n      四：冷结膀胱，也是少腹痛，小便色白，用真武汤。  ', NULL, NULL, NULL, NULL, NULL, '356、病者手足厥冷，言我不结胸，小腹满，按之痛者，此冷结在膀胱关元也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815690, '9E33FDFDF5CF6221EF821E908FDF5E0B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5560, 324, 904001114, '       在进入肝脏的时候，就是进入人的最近一道的抵抗系统，在检查病人的时候，发现病人的热慢慢的回头，病人在虚寒的时候，摸病人是冰冷，且病人的脉很弱很细，代表脉证相符，这就没有危险，如果病人一点元气都没有，摸到病人的脉很大很壮，就不好了，这就是《内经》里面的真脏脉，就是元阳快没有了，如果脉证合，病人热慢慢回头，体力慢慢恢复、\n     热少，厥微，刚开始热很少，手脚一点点冰冷，指头寒，默默不欲食，烦躁，这种人就是人元气要恢复的时候，就是这种现象，肝病的人，小便看的很清楚，厥阴也是热，得到急性肝炎的，一得到肝病小便就变成茶的很热，\n    数日小便利色白者，此热除也，发炎的现象没有了；欲得食，胃口开了，这几种现象代表厥阴证要痊愈了，只要看到病人体能慢慢的回头，胃口慢慢的打开，都是好的，突然吃东西都是不好的，\n    如果，若厥多而呕。手脚一天到晚都冰冷，恶心又吃不下东西，\n    胸胁烦满者，其后必便血，这是热太过了，里面发炎的现象很厉害，为什么呕?因为厥阴是肝脏，一热起来的时候，肝肿起来就顶到胃，此即木克土，实际上胃并没有问题，热太多的时候，就会胸胁烦满，热没有地方渲泻，就往肠子里面跑，大便就会带血。  ', NULL, NULL, NULL, NULL, NULL, '355、伤寒，热少，厥微，指头寒，默默不欲食，烦躁，数日小便利色白者，此热除也；欲得食，其病为愈；若厥多而呕，胸胁烦满者，其后必便血。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815691, '4ADDD859F44EE97240656F348CE85F05', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5561, 324, 904001113, '       病人有烦躁的现象，脉微弱，少阴，厥阴都有，少阴证的是烦躁不得卧是持续的，厥阴证的烦躁，有时候躁有时候不躁，这是脏厥和蛔厥的不一样，\n      蛔厥者，其人常自吐蛔，虫就从嘴巴吐出来，现在病者静，而复时烦，有的时候静，有的时候烦躁，此为蛔厥，所以肚子里面有虫，病人就会有这种现象，\n      蛔上入膈，故烦，虫往上冲的时候造成烦的现象，得食而呕，吃东西进去又呕吐出来，因为蛔闻食臭出，其人当吐蛔也。\n      蛔厥者，乌梅丸主之，又主久利，乌梅丸除了打虫以外又可以用在久利上，实际上病人会产生蛔厥的，就是胃里面太寒了，胃里面太冷的时候容易生虫，为什么列入厥阴证里面?他的胃冷，就是因为肝脏，肝是解毒的脏，人身上的毒，肝都会排掉，可是如果肝脏寒的话，在中医讲肝寒的时候，就是肝的解毒功能并不是很强，进入厥阴证的时候，很多病毒都跑到肝里面去了，肝脏的解毒功能又不很正常，这时候造成虫很容易在胃里生长，虫的体温是跟着人的体温的，人吃东西的时候虫也跟着吃东西。胃寒的时候又不吃东西，虫在里面就饥寒交迫，虫肚子饿的时候，虫往上跑，一上来病人的情绪就会很烦躁，在病人的嘴唇上可以看到白白的点，还有病人会肚子痛，一般来说肚子痛就是里寒，里寒的时候用小建中汤重用芍药，芍药是桂枝的两倍，里寒的话脉应该是沉紧，如果肚子痛摸到脉是浮大就是肚子里面有虫，为什么脉会很大?因为虫在动，一吃东西虫也跟着抢就会吐出来，这就是蚘厥。  \n\n     虫的性，虫闻到酸则静，本来虫都在动，一吃到酸的就静下来了，\n     得辛则服，虫吃到很辛辣的东西就乖了，\n     得苦则泄。吃到苦的就往下走，苦就是中药消炎的药，\n乌梅丸就是从这三个角度来设计去虫。  ', NULL, '乌梅丸', NULL, NULL, NULL, '353、354、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为藏厥，非若蛔厥也。蛔厥者，其人常自吐蛔。今病者静，而复时烦，此为蛔厥。蛔上入膈，故烦。须臾复止，得食而呕又烦者，蛔闻食臭出，其人当吐蛔也，蛔厥者，$f{乌梅丸}主之，又主久利。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815692, '3FC79FFDAE191FC73F9CB83DF61D625B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5562, 324, 904001112, '      厥就是手脚冰冷到手肘、膝盖，阴阳气不相顺接，就是血液循环产生障碍，血液循环通的时候，人就发热了，不通的时候，心脏衰弱的时候人就昏迷了。  ', NULL, NULL, NULL, NULL, NULL, '352、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815693, '2688745730BCE91D1CBD961AA24AB6BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5563, 324, 904001111, '     昏迷了五天，又热五天，到第六天的时候应该发冷的，结果病人不冷了，就是病会好了，代表胃气恢复了，就不会冷了。  ', NULL, NULL, NULL, NULL, NULL, '351、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈。厥终不过五日，以热五日，故知自愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815694, '4582646DC063364622B90E1C1C33A411', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5564, 324, 904001110, '      这条辨对应前面的条辨，张仲景的意思是如果进入厥阴证，得到中风伤寒表证的时候，因为里面已经虚掉了，肠胃津液已经不够了，肠胃津液不够的状况下，切记不要发汗，汗的来源是肠胃的津液，误汗的时候，造成口伤烂赤，会把肝里面的黏液发到嘴巴上来了，感冒发烧的时候用汗解，如果是厥阴证的时候就不可以汗解，厥阴证的时候滤过性病毒在肝里面，发皮肤的汗，跟肝没有关系，反而让肠胃的津液更伤，免疫系统受到伤害。  ', NULL, NULL, NULL, NULL, NULL, '350、伤寒，一二日，至四五日，前厥者，必发热；前热后厥者，必厥深热亦深，厥微者热亦微。厥应下之，而反发汗者，必口伤烂赤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815695, 'CB54AE93F2F6D1D6B143CCB3C5D2210D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5565, 324, 904001109, '      伤寒，如果是先厥后发热，手脚冰冷到手肘的地方，突然发热，代表胃的元气还在，下利必自止。\n     如果下利没有止，而反汗出，厥阴证的时候津液已经伤到了，因为免疫系统就是在津液里面，津液伤到的状况之下，病人在流汗，就变成是表虚掉了，这是很危险的状况，临床上看病人，病人已经很虚弱了，可是病人又一直在流汗，就代表病人的皮肤不能固表，人的元气、元阳、精神，高蛋白的东西一直往外流失，体力通通流失掉\n     如果咽中痛者，其喉为痹，病毒移转跑到喉咙上，喉咙就会发痛，\n     如果发热，无汗，利必不自止，热散不掉，热会往下走，利必自止。\n     若不止，便脓血，这肝炎的东西出来，到喉咙上，就喉咙痛，如果没有到喉咙往下走的时候，下利就会便脓血。\n     其喉不痹，便脓血的话，喉咙就不会痛，所以发炎的滤过性病毒，中药也杀不掉它，免疫系统也杀不掉它，它一定要有出路，出去的时候从大便或往上跑，想尽办法把滤过性病毒赶出去。  ', NULL, NULL, NULL, NULL, NULL, '348、349、伤寒：先厥后发热，下利必自止。而反汗出，咽中痛者，其喉为痹，发热，无汗，利必自止。若不止，便脓血。便脓血，其喉不痹。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815696, 'E4993EDFC1DD6D6F4EEC0C3365F81CA0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5566, 324, 904001108, '       伤寒的表证都有，恶寒怕冷，全身骨节酸痛都有，可是摸病人的脉迟，脉证不合，\n       而反与黄芩汤彻其热，靠黄芩汤来去他的热，\n       脉迟为寒，今与黄芩汤，复其热，黄芩汤是去热下利的药，结果腹中应冷，当不能食，今反能食，此为除中，这是说看到的是真寒假热，以为发热恶寒是有热，结果开寒凉的药下去，一攻，里面的寒更寒，造成除中，就是胃气完全没有了，这时候用大剂四逆汤来救逆，不可见死不救。  ', NULL, '黄芩汤', NULL, NULL, NULL, '347、伤寒：脉迟，六七日，而反与$f{黄芩汤}彻其热。脉迟为寒，今与黄芩汤，腹中应冷，当不能食，今反能食，此为除中，必死。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618322360815697, '6A65790302A1601F6C740FF494928902', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 15:00:10', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5567, 324, 904001148, '        如果大便不通有燥屎的话，应该是小承气汤，现在已经严重到谵语了，就应该是大承气汤，即使下利也是用大承气汤攻，因为大便堵在肠子里面，有间隙产生，看起来是下利，实际上是大便干在里面，只要确定有燥屎在里面，就须用大承气汤、所以有时候会用大承气汤去止利，因为有谵语的症状，谵语的产生，就是大便的浊气跑到脑里面去了。', NULL, '大承气汤', NULL, NULL, NULL, '390、下利，谵语者，有燥矢也，宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476422, 'C2249ADEF797570544A408CCB340D081', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5568, 324, 904001147, '   拉肚子，口又渴，这是热利，寒利不会口渴的，因为津液都跑光了，所以用白头翁汤。  ', NULL, '白头翁汤', NULL, NULL, NULL, '389、下利，欲饮水者，以有热故也，$f{白头翁汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476423, 'FFB9B39CE50E815053AA087825715084', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5569, 324, 904001146, '       照理说腹胀满，如果是承气汤证，应该不会下利还会便秘的，下利很多，肚子又胀满，就知道里面寒湿很盛，遇到这种里面寒湿很盛的，一定先去里寒去湿，再去解表。', NULL, '四逆汤,桂枝汤', NULL, NULL, NULL, '388、下利，腹胀满，身体疼痛者，先温其里，乃攻其表，温里宜$f{四逆汤}，攻表宜$f{桂枝汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476424, 'B3942C2F025C5A3717FD83270495568E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5570, 324, 904001145, '        痢疾、急性的肠炎，白头翁汤是很常用的方子，热利大便出来很臭，白头翁汤是非常好用的方子，几乎是一剂知二剂已，第一碗喝了就不利了，第二碗喝了就胃口大开，精神好起来了，寒利用通脉四逆汤、热利就用白头翁汤。  \n\n热利的主证：  \n\n    一：手脚不寒  \n\n    二：便臭  \n\n    三：脉数，数代表热代表发炎了 像痢疾的症状就是白头翁汤证，像霍乱、伤寒是下利清谷为主证。  ', NULL, '白头翁汤治', NULL, NULL, NULL, '387、热利下重者，$f{白头翁汤治}之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476425, '7C613D4AEC286948F89A350F5EAF05A6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5571, 324, 904001144, '    本来是里寒才会下利清谷，汗出而厥者，里寒外热表示有虚热，通脉四逆汤主之，通脉就是通行上下。  ', NULL, '通脉四逆汤', NULL, NULL, NULL, '386、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476426, '2E82EEC1B56ECC6929B9729397E0F125', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5572, 324, 904001143, '     伤寒就若是进入厥阴证了，下利的话脉应是微弱，结果脉反实，病人很虚弱，摸到的脉 很实，这就是真脏脉，一般来说癌症的病人有这种脉，摸到的脉跳的很强很硬，就是东西堵到了，过不去了，都是死，所以体内有长肿瘤，脉都跳的很速。  ', NULL, NULL, NULL, NULL, NULL, '385、伤寒，下利日十余行，脉反实者，死。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476427, '9A8D9E0E2C865C92D7FC0D1DD60CC6CC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5573, 324, 904001142, '       拉肚子拉到脉都没有了，就是心脏衰竭了，手脚冰冷，就是脾脏的功能都没有了，晬时，就是一周时，差不多二十四小时，脉还，手足温者生，胃气回头了生，脉不还者死，这就是辨症，协助断生死用的，遇到这种情形的时候，大剂的四逆汤就下去了，不可以等他死。', NULL, NULL, NULL, NULL, NULL, '384、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476428, 'DE1D860F0CC23E883161C1A5E7619FDF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5574, 324, 904001141, '      下利虚寒的人，脉数而渴，脉变的数而且口渴，渴就是自己想要喝水，代表寒已经化热了，厥阴证都是寒没有热的。从阴证进入阳证的时候，病人会口渴，阴寒很盛的人都不会口渴，所以病人没事口渴喝水的，不会死，都是阳证，所以喝水就好了，\n     如果设不差，必圊脓血，以有热，喝水没有好，会大便便脓血，因为热太多了，热太过的时候，血会从肠子走，病毒会往肠子里面跑。 ', NULL, NULL, NULL, NULL, NULL, '383、下利，脉数而渴者，令自愈。设不差，必圊脓血，以有热故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476429, 'B3A1C5A8443BC663F10DD349EFB4FB89', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5575, 324, 904001140, '      沉代表里，迟代表寒，人里寒了，舌苔白的，因为里太虚的时候，会戴阳，就是两颧的地方红红的，这是因为下利太盛，或里寒太盛的时候，阳没有根了，阳气浮起来了，就会看到脸上红红的，主因都是下焦太虚寒。  ', NULL, NULL, NULL, NULL, NULL, '382、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，病人必微厥。所以然者，其面戴阳，下虚故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476430, 'B02A4323FDAF4EA418F18ED9EF57F7D6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5576, 324, 904001139, '      沉代表里，弦代表急也代表水，所以下利，脉沉弦者，下重也，下利完，脉要到骨边才摸到，细细的一根，病人拉完还想再拉，但是拉不出来，拉出来也是水，就是里急后重，脉一定是沉弦的，如果病人是脉大，代表里面热还是很盛，肠里面还有发炎的现象，利还不会止，脉微弱数者，为欲自止，虽发热，不死，脉微弱，就是阳气慢慢回头的时候，这是好的现象。', NULL, NULL, NULL, NULL, NULL, '381、下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476431, '7BFE70183017372127108E5325C79638', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5577, 324, 904001138, '      下利清谷，代表肠子里面虚寒了，里寒很盛的时候，绝对不可以攻表，因为攻表是靠里面的阳，肠胃的津液来的，如果误攻了，汗出，必胀满。一攻的时候，里寒会更盛了，腹就是胀满，就是整个肿在里面了，肠胃都没有蠕动，松张了。所以病人有呕吐、下利，里虚的时候，绝对不可以攻表。  ', NULL, NULL, NULL, NULL, NULL, '380、下利清谷，不可攻表，汗出，必胀满。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476432, 'EA32255040F3655B5FAEE54242380E18', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5578, 324, 904001137, '       涩代表血虚了，寸脉反浮数是上热，尺中自涩者，代表血往下走，必圊脓血，病人在拉血的时候，还有精神就没关系，他可能是痔疮出血、如果下血人很虚弱，就是体能不够了，血离经了，因为肠子破了，霍乱、疟疾的时候，肠壁被腐蚀掉了，破洞了，真正的血跑出来了，遇到这种情形的时候，病人一定极度的虚弱。  ', NULL, NULL, NULL, NULL, NULL, '379、下利，寸脉反浮数，尺中自涩者，必圊脓血。（校正注：“圊”同“清”）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476433, 'B3EFD38867FAE084F000D1C1F88B9D7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5579, 324, 904001136, '      人一直在下利，人就虚弱掉了，手足厥冷，这手脚冰冷都是冷到手肘边了，无脉者，脉没有了，就是心脏衰竭了，灸之不温，灸关元都不会温，若脉不还，反微喘者。死，灸了半天还没有回来，就是寒极了。脏腑的功能都衰竭掉了，所以西医讲的肾衰竭、心脏衰竭，都是寒。为什么微喘?因为寒到上面来了，气进不去，但是可以出来，吸少呼多', NULL, NULL, NULL, NULL, NULL, '377、下利，手足厥冷，无脉者，灸之不温，若脉不还，反微喘者，死。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476434, '42EC55428EFEBEE56874B63294C1417D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5580, 324, 904001135, '     如果脉又紧回来了，就是免疫系统和病毒相抗，代表余毒没有去掉，为未解。  ', NULL, NULL, NULL, NULL, NULL, '376、下利，脉缓，有微热，汗出，令自愈；设复紧，为末解。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476435, '3A358A0727771BC1FD9283DCD5DBF853', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5581, 324, 904001134, '      这就是很好的现象，病人下利，脉弱，脉弱代表肠子里面的病毒跟着利通通跑掉了，如果脉跳的数，代表病毒还在里面，这病毒包括霍乱、疟疾的病毒，微热，就是肠胃的功能慢慢恢复了，脉弱者，令自愈，脉弱的自己会好，所以霍乱、疟疾都要参考厥阴证，在难民营里，常常霍乱、疟疾一来就死很多人，因为难民营里的人饮食不好，固表力没了，病毒一下子就到了厥阴证，就会死一大堆人。  ', NULL, NULL, NULL, NULL, NULL, '375、下利，有微热而渴，脉弱者，令自愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476436, '0B141E1F2367ED3692A21FFC2CF9F314', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5582, 324, 904001133, '      本自寒下，本来有寒在下焦，医复吐、下之，寒格，更逆吐、下，若食入口即吐者，这也是上热下寒的症状、但是并没有下利。  \n\n     张仲景讲食入口即吐有一个是大黄甘草汤证，大黄二甘草一，这是胃家的热实，热而且有实在中间，东西吃下去马上吐掉，这里的饮食入口即吐也是，但是这个入口即吐是虚热，病人本身已经被吐、下，肠胃津液已经伤到了，本来就是寒的、所以用干姜来去寒，又有虚热，热就是炎，本身有发炎，有病毒，但是没有食物堵在里面，所以用黄芩、黄连来消炎，这人被吐被下肠胃津液一定伤到了，所以加人参，这种病人的症状有的时候舌苔白的有的时候黄的，不一定，下利臭，有的时候下利臭舌苔白的，代表寒盛里面又有热，这是虚热不是实热。这个方常用来治疗现在说的胰脏癌，另外一个胰脏癌常用的处方是旋覆代赭汤加干姜吴茱萸，这是用在病人严重呕吐、呕酸很多的时候；胰脏癌的病人如果还有往来寒热，就会用到小柴胡汤。  \n\n     手术开刀，手术前不能吃东西，手朮后又没吃东西，要等到放屁出来才能吃，由于肠子都黏在一起，这时候最好用的就是独参汤，单独一味人参。\n', NULL, '干姜黄连黄芩人参汤', NULL, NULL, NULL, '374、伤寒，本自寒下，医复吐、下之，寒格，更逆吐、下，若食入口即吐者，$f{干姜黄连黄芩人参汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476437, '9754DDF1FD2166CA262CE62E6F57E932', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5583, 324, 904001132, '      肚子里面有痛的话，代表里寒很盛了，寒湿很盛，转气下趋少腹者就是肠鸣，就是水渗到肠子里面去了、此欲自利也。  ', NULL, NULL, NULL, NULL, NULL, '373、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476438, '3762343579E1F6204D72235D76402393', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5584, 324, 904001131, '      麻黄升麻汤专门治疗上热下寒，所以麻黄升麻汤是寒热并用的汤剂，而且是补泻寒热并用在一个方子里面，为什么张仲景设计这方子?就是担心病人进入厥阴的时候，被医生误下了，误下了之后，如何去救他?伤寒六七日，大下后，如果是太阳伤寒表证的时候，被攻下会变成结胸或心下痞，不会有寸脉沉而迟的现象，这是直接进入厥阴了，寸脉讲的是阳脉，所以阳脉很弱了，里面的阳气很弱了，手足厥逆，手脚冰冷，这时候下部脉不至，尺部的脉没有了，这时候咽喉不利，唾脓血，肝是藏血的脏，人的血进入肝以后，肝过滤血后，血再从肝的静脉出来到身上来，肝脏有血管直接到子宫、大肠、到下焦里来，下焦一寒掉后，下焦凝固了，血没有办法下来，血就往上冲逆了，一冲到喉咙，喉咙就肿起来，这是血逆行经脉，严重的话就会吐血，所以肝病到后来会吐血，就是肝血逆往上走，全身只有一条血管没 有倒勾，就是肝脏到大肠的血管，就是没有瓣膜，所以肝病就是利用这管道把病毒排出去，泄利不止，就是肠胃都冷掉了，麻黄升麻汤主之。  \n\n        有当看到病人，嘴巴吐血，肝血往上，舌苔有热，又下利清谷，脉又很弱，又寒又热，这时候用麻黄升麻汤，这方子是经方里面用药最多的。如果是胃癌的病人半夜吐血的症状，则是用黄土汤加减来治疗。升麻，顾名思义，升麻是向上的，升麻性向上，有升提的作用，所以如果病人有坠症，譬如脱肛、疝气，腹膜如果破了，小肠坠出来了，一般是开刀，但是开刀只有治标，这儿好了可能那儿又破了，这是因为腹膜没有力量了，张仲景在金匮里面立蜘蛛散，用住家屋檐下的蜘蛛，把蜘蛛在铁皮锅烤干，磨成粉，作散剂吞服，慢慢腹膜就长出来了，可是腹膜长出来之前，要先把肠子收回去，一节肠子漏在外面，到时候堵到了烂掉了，张仲景说少腹疼痛入腹。就是讲疝气，针灸的时候，左边腹痛扎右脚，右边腹痛扎左脚，肝经的大敦穴下针，一痛就收回去了，然后下肝经的母穴曲泉，因为只有肝经络过阴器，大敦一下，一痛就收回去了。然后曲泉一下，肠子就开始蠕动循环了，开疝气的药里面再加润肠的药，把大便通出来，譬如开当归四逆汤里面加升麻，因为脱肠所以加升麻，加过药后，临床上，如果小便不利、摄护腺肥大，就是真武汤加减，如果手脚冰冷用当归四逆汤作加减。  \n\n白朮是利三焦油网。  \n\n     葳蕤专门治咽喉不利、喉咙痛、喉咙肿胀，麦门冬和麻子仁是相表里，麦门冬和天门冬 都是润肺的，因为肝的血逆流上来的时候，血带来了很大的热度，就是炎，上焦会热起来了，舌苔会黄，这时候会吐血，靠天门冬润肺，葳蕤止血把热往下降，通利喉咙，因为下焦太寒了，所以有干姜等，药物是寒热并用，因为上焦太热了，所以用石膏。 ', NULL, '麻黄升麻汤', NULL, NULL, NULL, '382、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{麻黄升麻汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476439, '39C857663E759E48B3BD3288400C5EF4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5585, 324, 904001130, '      伤寒本来就是肠胃的功能缓掉了，手脚冰冷就是进入厥阴证，还有心下悸胃已经没有吸收的功能了，胃不能吸收水分，这时候水跑到胃里面，水停在中间就会有动悸，就是水饮很多，所以像肌肉跳动、眼皮跳，就是有水饮，都是真武汤证就是水逆行离开血了，遇到这种情形的时候，要先治水，中焦的水最好的药就是茯苓，下焦的水用猪苓，上焦的水就用半夏，胸腔里面用十枣汤，现在水在胃里面所以用茯苓甘草汤，加甘草让药停在胃里面，真正的主药是茯苓，所以茯苓二，甘草一，吃了茯苓甘草汤，水排掉了后，再治手脚冰冷，来不及治的话，水跑到胃里面，这胃要把它当成肠，就会变成下利。小肠是火，水火不容，水这下去就水火未济，大便出来全部都是水。  ', NULL, '茯苓甘草汤', NULL, NULL, NULL, '371、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔，水渍入胃，必作利也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476440, '0FA434D3AD34306EA837950A2A94C107', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5586, 324, 904001129, '       什么叫乍紧?有的时候紧，有的时候不紧，病人手足厥冷，病人手脚冰冷的时候，摸到脉应该是微细的，代表虚掉了，结果脉变的乍变，一下子紧，一下子不紧，代表邪结在胸中，这时候心下满而烦，饥不能食者，病在胸中，当须吐之，这是寒实，要确定有东西才会采吐法，如果是虚的，病人没有东西，病人会虚烦，虚烦的脉就不会紧，紧代表有东西堵到了，宜用瓜蒂散，这是从脉证来知道胸中有实。', NULL, '瓜蒂散', NULL, NULL, NULL, '370、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜用$f{瓜蒂散}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476441, '4FB2306F3A7C1AE260B4F0D9486B5EA3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5587, 324, 904001128, '        汗和津液就是中医讲的阳，所以大汗出的时候就是亡阳了，阳就是人的体能营养液，若大下利而厥冷者，下利很多，食物没有了，就是血的源头都没有了，就是亡阴了，阳没了阴也没了，就是四逆汤主之，所以在伤寒表证的时候，汗出不止是桂枝汤加附子，用炮附收表阳。  ', NULL, '四逆汤', NULL, NULL, NULL, '369、大汗，若大下利而厥冷者，$f{四逆汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476442, '2C091448FC1ECFF37458C657D0084516', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5588, 324, 904001127, '       如果有发热，应该汗出就都解掉了，现在大汗出，\n      热不去，就是津液伤到了，四肢痛而拘急，关节会痛，就是津液不足了，血液循环就不好，四肢关节就会痛，\n     又下利，厥逆而恶寒者，已经血液循环不好了，\n     又下利，代表里寒很强，这时候又手脚冰冷，这里的恶寒和太阳的恶寒不一样，麻黄汤的恶寒是怕冷，这里的恶寒是虚掉的冷，四逆汤主之，四逆汤都是救逆的，里寒很盛的时候用，所谓里寒就是里面的功能都没有了，四逆汤里面用干姜和生附，很危险的时候，可以炮附生附并用，生附可以壮心阳，炮附使关节打通，同时有壮肾阳之功。  ', NULL, '四逆汤', NULL, NULL, NULL, '368、大汗出，热不去，四肢痛而拘急，又下利，厥逆而恶寒者，$f{四逆汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476443, 'A2CB99AB867F10CE0A502D11CA118D74', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5589, 324, 904001126, '       当归四逆汤是中医治疗冻疮的主方，处方还是桂枝汤的加减，手足厥寒，脉细欲绝者，实际上心脏极度的衰竭了，所以加护病房里面，靠维生机的病人都是当归四逆汤证，摸他的手脚都是冰冷的，心脏的血没有办法运行到四肢的末梢，四肢就缺氧，会坏死掉，这就是造成冻疮，除了冻疮外，紧急的时候也在用的，桂枝和白芍等量，由于动脉和静脉两个相等长，血液就会加速，平常胖子开三钱，人都昏迷了，靠维生机的时候用三两都不过分，因为身体里面完全没有功能，完全要靠药力，桂枝和白芍一定等量，如果桂枝少白芍重，会造成血管爆裂，因为出去的力量不够，人已经极虚了，肠胃的功能不够了津液也不够了，怕里面的东西梗到，所以用通草，通草是很轻的润肠剂，连麻子仁对病人来说都太强了，可是不攻又不行，因为怕里面有脏的东西，所以用通草，同时再加炙甘草、大枣，把津液都补回来，平常张仲景很少用补药，因为病人需要，病人在失血的状况下，所以用当归，把血补足，细辛壮里阳，让下焦的阳往上升，下面的阳往上走，整个人能循环起来，为什么不用生姜?生姜是散胃里面的水，病人有恶心呕吐的时候才会用生姜，现在要把水补回来，所以不用生姜。  \n     \n      若其人内有久寒者，宜当归四逆加吴茱萸生姜汤主之。\n             这内有久寒，讲的是胃寒，在厥阴篇里面讲的，实际上是肝太寒了，引起的胃的功能不正常，所以用当归四逆加吴茱萸生姜汤主之、吴茱萸是最好止呕的圣剂，寒就是有水，所以加生姜把水排掉。  ', NULL, '当归四逆汤,当归四逆加吴茱萸生姜汤', NULL, NULL, NULL, '367、手足厥寒，脉细欲绝者，$f{当归四逆汤}主之。若其人内有久寒者，宜$f{当归四逆加吴茱萸生姜汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476444, '741DED8EE331D8FB3A2F0A7C0F379CD9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5590, 324, 904001125, '       只要对证，不管病在太阳、少阳、阳明，都会有白虎汤证。只要确定里面是热，是经热，就是血脉神经的热，一旦病人血里面的水不足的时候，就会用到白虎汤，如果厥阴证的病人，伤寒，吐、利太多了，病人的水不够了，也是属于白虎汤。  ', NULL, '白虎汤', NULL, NULL, NULL, '366、伤寒脉滑而厥者，里有热也，$f{白虎汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476445, '4BD7314FCF2B8AEDA67C736762B45D69', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5591, 324, 904001124, '       灸中脘关元，如果是一般的伤寒表证，脉浮紧，不会用灸。用麻黄汤去发表，现在脉促，手足厥逆者，脉跳的数，手脚又冰冷，这都是进入厥阴证了，所以厥阴证的寒证，代表肝脏的功能衰弱下去了，就会看到这现象，还有下利，厥阴和少阴一样，主的是吐、利。 ', NULL, NULL, NULL, NULL, NULL, '365、伤寒，脉促，手足厥逆者，可灸之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476446, '97E69C874EB24BD6FE7EC52156C05A9B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5592, 324, 904001123, '        照理说发热手脚冰冷都是里阳不足了，里面的肠胃功能没有了，肠胃没有蠕动，这时候手脚都是冰的，这种发热的现象都是人体最后一道系统，遇到这种情形的时候，人已经极虚了，若再碰到下利。代表阳气都没有了，大肠和肺相表里，肺就是胸阳，一直下利就是肺气不够了。  ', NULL, NULL, NULL, NULL, NULL, '364、发热而厥，七日，下利者，为难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476447, 'F276177E78E7AE35DB258CA2C1E77BC4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5593, 324, 904001122, '一般来说，有伤寒表证下利的话，会结胸，不结胸就是病往里面走了，腹濡，病人的肚子摸起来软软的，脉虚，复厥者，不可下，此为亡血，下之死。所以虚证不可下，虚证的人绝对不可以攻下，为什么?因为有腹濡，如果心下鞕满是实痛要攻下，如果肚子难过，要先检查清楚，有东西在里面才可以攻，没有东西在里面不可以乱攻，如果脉虚，手脚冰冷又很虚弱，病人是里虚的状况，本来还没死，一攻死的更快。  ', NULL, NULL, NULL, NULL, NULL, '363、伤寒，五六日，不结胸，腹濡，脉虚，复厥者，不可下，此为亡血，下之死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476448, '9C95E3AE1D9FEB5FD10113A7C906836B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5594, 324, 904001121, '       如果人在很虚弱的状况之下，胃气恢复的时候，病人下利兼有症状是发热，不是烦躁，发热就是手脚摸到热，摸到热还在利这就不会死，没关系，如果病人汗出不止，汗血同源，汗的来源就是阳的津液，如果下利，表汗又一直在流，整个肠胃都干掉了，这种就是死证，有阴无阳，就是阳脱了，阳脱掉就会有这种现象。用白通汤加猪胆汁和人尿，白通汤可以通阳，大剂的用，靠人尿硬把阴阳相隔打开。', NULL, NULL, NULL, NULL, NULL, '362、伤寒，六七日下利，又发热，其人汗出不止者，死，有阴无阳故也。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476449, 'A6874FE4996B2116F9FE8A7B8AE4816B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5595, 324, 904001120, '       照理说下利是越利越寒，体能都没有了，手脚冰冷了，如果病人发热，代表肠胃功能回来了，利应该会自止，现在发热，下利至甚。厥不止者，这时候下利不止反发热，手脚一直冰冷，没有办法热起来的这都是死证。除了癌证的末期、肝病的末期。还有霍乱痢疾的上吐下泻，好的津液都吐光了，下泻又把肠胃的津液泻掉了，就会有这种现象。  ', NULL, NULL, NULL, NULL, NULL, '361、伤寒，发热，下利至甚，厥不止者，死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618360261476450, 'CBD62E06710E7BB546FF80E81CB040F2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:34:23', 1, '超级管理员', '2024-12-03 08:33:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5596, 324, 904001155, '      如果在打嗝，肚子又胀满，视其前后，知何部不利，利之即愈，看看大小便哪一个不通，通哪一个，前部不利开五苓散，后部不利开承气汤，基本上这种状况都是能治的，如果不能治的话，就是人已经虚掉了，这时候攻下都没有用，如果病人是寒湿很盛的话，又哕，还是用茯苓四逆汤去救逆，如果肚子里面有实堵到，就茯苓四逆汤里面加去实的药，大黄去实，大黄没有所谓的寒热，如果是小便不出来，可以加猪苓、泽泻，但是一定以四逆汤为主证。  \n\n以上讲的是厥阴证。  \n\n        原伤寒论之末篇辨霍乱病脉证并治法，辨阴阳易瘥后劳复脉证，辨痉湿暍脉证，这三脉证有经方家并列入伤寒之末篇，但又是《金匮》之始篇，实介于伤寒与金匮之间的连接篇，个人认为伤寒到最末厥阴篇即可止，这最后三篇可置于《金匮》之首篇，以衔接《伤寒》与《金匮》本源于一书伤寒杂病论。', NULL, NULL, NULL, NULL, NULL, '397、伤寒，哕而腹满，视其前后，知何部不利，利之即愈。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618581241217094, '86D7140FA1E0332DDF1D22D4C26D7FE9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-03 08:33:33', 1, '超级管理员', '2024-12-03 08:33:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5597, 324, 904001154, '        大吐大下后，津液一定伤到了，极虚的时候病人已经很虚了，看病人体外还是有体温，医师误诊，没有注意到里虚，再开了发汗的药，汗一出来，病人更虚，更虚的状况下，肠胃整个的虚寒掉了，这时候喝了水下去就得哕，用茯苓四逆汤，张仲景没出方子，但是讲的就是茯苓四逆汤，因为胃里面有停水，哕就是打嗝，打嗝就是胃气已绝，没有胃气了，胃没有蠕动了，这时候一喝水下去，水停在胃里面，就会造成打嗝，中医讲的胃气绝就是胃寒，西医讲的就是胃没有吸收功能了，这时候水一下去就会打嗝，因为水是寒的冷的，所以是茯苓四逆汤证，四逆汤加茯苓，把水排掉。', NULL, NULL, NULL, NULL, NULL, '396、伤寒，大吐大下之，极虚，以其人外气怫郁，发其汗，复极汗出者，复与之水，因得哕；所以然者，胃中寒冷故也。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618581241217095, 'A8751135051A5E863A0E18B15FB17E7B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-03 08:33:33', 1, '超级管理员', '2024-12-03 08:33:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5598, 324, 904001153, NULL, NULL, NULL, NULL, NULL, NULL, '395、呕而发热者，$f{小柴胡汤}主之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618581241217096, '0EC090546D6A64AF98078D2AE2B2C6A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-03 08:33:33', 1, '超级管理员', '2024-12-03 08:33:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5599, 324, 904001152, '       如果呕酸、呕苦，都是从胃里面来的，干呕就代表胃里面没有东西，为什么呕?因为肝脏肿太大了，肝横逆过来了，所以呕出来的黏液，是肝里面的东西，吴茱萸汤主之，吴茱萸汤是专门治呕的方，实际上吴茱萸汤是入肝脏的，西医的胃下垂就是吴茱萸汤证，这种人大部分都是酒客，酒喝多了，肝受不了了，中医看是肝寒，西医看是胃下垂，所以西医对胃下垂从来是治不好的。  ', NULL, '吴茱萸汤', NULL, NULL, NULL, '394、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618581241217097, 'F2A9BE3551F6C1F12FCD7257449F2E94', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-03 08:33:33', 1, '超级管理员', '2024-12-03 08:33:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5600, 324, 904001151, '       照理说呕吐的病人胃里面虚了，亦即胃里面的津液不够了，所以脉弱，小便复利，小便很多，下焦也是虚寒的，所以中焦、下焦都是虚寒的，身为微热，里面寒湿很盛，体能往外散了，这都是阴太盛，阳不足了，所以四逆汤主之。', NULL, NULL, NULL, NULL, NULL, '393、呕而脉弱，小便复利，身有微热，见厥者，难治，$f{四逆汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618581241217098, '16462945B293B1570522379845537A78', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-03 08:33:33', 1, '超级管理员', '2024-12-03 08:33:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5601, 324, 904001150, '      呕吐的人，有时候吐出来的是脓，从胃里面吐出来像胃痈，或从肺里面吐出来像肺痈、肺里面有脓，所以呕家不可以治呕，要让他先吐，如果病人是干呕、呕酸、呕苦水，这就不是呕家，可以用止呕的药。  ', NULL, NULL, NULL, NULL, NULL, '392、呕家，有痈脓者，不可治呕，脓尽自愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618581241217099, 'D51ADD0F6036545AFE3B77E65D644F9F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-03 08:33:33', 1, '超级管理员', '2024-12-03 08:33:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5602, 324, 904001149, '      如果是心下鞕，代表胀满，是调胃承气汤证，这是实烦，如果是虚烦，就是栀子豉汤，这表示病已经接近好了，常在重病将近痊愈的时候服用。', NULL, '栀子豉汤', NULL, NULL, NULL, '391、下利后，更烦，按之心下濡者，为虚烦也，宜$f{栀子豉汤}。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 618581241217100, '35726ED5A77AAD5429ABB6C51E98CD9D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-03 08:33:33', 1, '超级管理员', '2024-12-03 08:33:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5603, 325, 1001000101, NULL, NULL, NULL, NULL, NULL, NULL, '       论曰：余每览越人入虢之诊，望齐侯之色，未尝不慨然叹其才秀也。怪当今居世之士，曾不留神医药，精究方术，上以疗君亲之疾，下以救贫贱之厄，中以保身长全，以养其生，但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外，而悴其内，皮之不存，毛将安附焉。卒然遭邪风之气，婴非常之疾，患及祸至，而方震栗，降志屈节，钦望巫祝，告穷归天，束手受败，賫百年之寿命，持至贵之重器，委付凡医，恣其所措，咄嗟呜呼！厥身已毙，神明消灭，变为异物，幽潜重泉，徒为啼泣，痛夫！举世昏迷，莫能觉悟，不惜其命，若是轻生，彼何荣势之足云哉！而进不能爱人知人，退不能爱身知己，遇灾值祸，身居厄地，蒙蒙昧昧，憃若游魂。哀乎！趋势之士，驰竞浮华，不固根本，忘躯徇物，危若冰谷，至于是也。余宗族素多，向余二百，建安纪元以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救，乃勤求古训，博采众方，撰用《$m{素问}》、《$m{九卷}》、《$m{八十一难}》、《$m{阴阳大论}》、《$m{胎胪药录}》，并平脉辨证，为《$m{伤寒杂病论}》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。夫天布五行，以运万类，人禀五常，以有五脏，经络府俞，阴阳会通，玄冥幽微，变化难极，自非才高识妙，岂能探其理致哉！上古有$n{神农、黄帝、歧伯、伯高、雷公、少俞、少师、仲文}，中世有$m{长桑、扁鹊，汉有公乘阳庆及仓公}，下此以往，未之闻也。观今之医，不念思求经旨，以演其所知，各承家技，终始顺旧，省疾问病，务在口给。相对须臾，便处汤药，按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，短期未知决诊，九候曾无仿佛，明堂阙庭，尽不见察，所谓窥管而已。夫欲视死别生，实为难矣。\n\n      孔子云：生而知之者上，学则亚之，多闻博识，知之次也。余宿尚方术，请事斯语。\n\n 汉长沙太守南阳张机序', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619747634573381, '8C11F600C9224BC3142835375976BAF3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 15:39:37', 1, '超级管理员', '2024-12-14 14:29:31');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5604, 326, 1001000201, NULL, NULL, NULL, NULL, NULL, NULL, '        余闻吾师$n{张绍祖}先生之言曰：“吾家伤寒一书，相传共有一十三稿，每成一稿，传抄殆遍城邑，兹所存者为第十二稿，余者或为族人所秘，或付劫灰，不外是矣；叔和所得相传为第七次稿，与吾所脏者较，其间阙如固多，编次亦不相类，或为叔和所篡乱，或疑为宋人所增删，聚讼纷如，各执其说；然考晋时尚无刊本，犹是传抄，唐末宋初始易传抄为刊刻，遂称易简，以此言之，则坊间所刊者，不但非汉时之原稿，恐亦非叔和之原稿也。\n\n       ”余聆训之下，始亦疑之，及读至伤寒例一卷，见其于可汗不可汗，可吐不可吐，可下不可下法，尽载其中，于六经已具之条为并不重引，法律谨严，始知坊间所刻之辨可汗不可汗，可吐不可吐，可下不可下，以及发汗 吐下后各卷，盖后人以读书之法，错杂其间，而未计及编书之法固不如是也，不然孔氏之徒，问仁者众，问政者繁，何不各类其类，而惮烦若此耶!吾师讳学正，自言为仲氏四十六世孙，自晋以后迁徙不一，其高祖复初公，自岭南复迁原籍，寄居光州，遂聚族焉。\n       吾师虽承家学，不以医名，亦不轻出此书以三示人，余得之受业者，殆有天焉。\n      余宿好方术，得针灸之学于永川邓师宪章公，后随侍先严游宦岭南，与吾师同寅，朝夕相过从，见余手执宋本伤寒论，笑问曰：“亦嗜此乎？”时余年仅弱冠，答曰：“非敢云嗜，尚未得其要领，正寻绎耳。”师曰：“子既好学，复知针灸，可以读伤寒论矣，吾有世传抄本伤寒杂病论十六卷，向不示人，得人不传，恐成坠绪。”遂历言此书颠末，及吾师家世滔滔不倦。先严促余曰：“速下拜。”于是即席拜之，得师事焉。今罗生哲初为吾邑知名人士，从习针灸历有年所，颇能好余之所好，余亦以所得者尽授之，余不负吾师，罗生亦必不负余，故特序其原起，罗生其志之，罗生其勉之。\n\n       光绪二十年岁次甲午三月桂林左盛德序', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619750650716229, '56016CE42BEEB2D67D1C236C1355F246', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 15:51:53', 2, 'Admin', '2024-12-14 16:12:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5605, 327, 1001000302, NULL, NULL, NULL, NULL, NULL, NULL, '2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。\n\n       师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619773433999429, '80B34002CAF66D98CE09BACA417515E7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:24:36', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5606, 327, 1001000301, NULL, NULL, NULL, NULL, NULL, NULL, '1、问曰：脉何以知气血脏腑之诊也？\n \n    师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。气独胜者，则脉强；血独盛者，则脉滑；气偏衰者，则脉微；血偏衰者，则脉涩；气血和者，则脉缓；气血平者，则脉平；气血乱者，则脉乱；气血脱者，则脉绝；阳迫气血，则脉数；阴阻气血，则脉迟；若感于邪，气血扰动，脉随变化，变化无穷，气血使之；病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619773433999430, '05E8C5B78C0B7732B6B261701A801DF3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:24:36', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5607, 327, 1001000327, NULL, NULL, NULL, NULL, NULL, NULL, '27、师曰：人秉五常，有五脏，五脏发五声，宫、商、角、征、羽是也；五声在人，各具一体；假令人本声角变商声者，为金克木，至秋当死；变宫、征、羽皆病，以本声不可变故也。\n \n       人本声宫变角声者，为本克土，至春当死；变商、征、羽皆病。 \n\n       人本声商变征声者，为火克金，至夏当死；变宫、角、羽皆病。\n\n       人本声征变羽声者，为水克火，至冬当死；变角、宫、商皆病。\n\n       人本声羽变宫声者，为土克水，至长夏当死；变角、商、征皆病。\n\n       以上所言，皆人不病而声先病者，初变可治，变成难瘳；词声之妙，差在毫厘，本不易晓，若病至发声则易知也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585157, '048DCA04B9C762962DDF4FB5472DBBD8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5608, 327, 1001000326, NULL, NULL, NULL, NULL, NULL, NULL, '26、问曰：色有生死，何谓也？\n\n       师曰：假令色黄如蟹腹者，生；如枳实者，死；有气则生，无气则死，余色仿此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585158, '5D787887F62B7F5ACED70A77A6F23B69', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5609, 327, 1001000325, NULL, NULL, NULL, NULL, NULL, NULL, '25、病暴至者，先形于色，不见于脉；病久发者，先见于脉，不形于色；病入于脏，无余证者，见于脉，不形于色；病痼疾者，见于脉，不形于色也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585159, '4B5F492222838ABCAA27F35B3AD3462A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5610, 327, 1001000324, NULL, NULL, NULL, NULL, NULL, NULL, '24、问曰：色有内外，何以别之？师曰：一望而知者，谓之外；在明堂阙庭，推而见之者，谓之内。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585160, 'A90DF66C02D30E3BF9327B50629550A6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5611, 327, 1001000323, NULL, NULL, NULL, NULL, NULL, NULL, '23、明堂阙庭色不见，推之色青紫者，病在中焦有积；推之明于水者，病在上焦有饮；推之黑赤参差者，病在下焦有寒热。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585161, '4DBAA71B5FD83E7D45845ADE05DA62E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5612, 327, 1001000322, NULL, NULL, NULL, NULL, NULL, NULL, '22、阙庭脉色青黑直下睛明，推之不变者，病在肾；推之即至者，病在膀胱。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585162, '0AE341F13B61FC1609F7AF63A1894859', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5613, 327, 1001000321, NULL, NULL, NULL, NULL, NULL, NULL, '21、阙庭脉色青白，推之久不还者，病在肺；推之即至者，病在大肠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585163, '8F18EEFDA46737095E03E54F233848E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
