INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5619, 327, 1001000315, NULL, NULL, NULL, NULL, NULL, NULL, '15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585169, '5C454CA1B402A362F55450498745D03D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5620, 327, 1001000314, NULL, NULL, NULL, NULL, NULL, NULL, '14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585170, '6E2945C2740B218FB9586B64A99EF1E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5621, 327, 1001000313, NULL, NULL, NULL, NULL, NULL, NULL, '13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585171, '09C5248742B4458B57202C20509632B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5622, 327, 1001000312, NULL, NULL, NULL, NULL, NULL, NULL, '12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。\n\n        师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585172, '549F7FFEABD4A9966E4B78CA66073C4A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5623, 327, 1001000311, NULL, NULL, NULL, NULL, NULL, NULL, '11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585173, 'EF857B14FDE34A3AED4E9217EC32E068', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5624, 327, 1001000310, NULL, NULL, NULL, NULL, NULL, NULL, '10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585174, 'EFC6D1416FD930829E894012EE64B3F1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5625, 327, 1001000309, NULL, NULL, NULL, NULL, NULL, NULL, '9、北方肾脉其形何似？\n\n     师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585175, '34D5F9ECA27F5DC307842703A67A5EE8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5626, 327, 1001000308, NULL, NULL, NULL, NULL, NULL, NULL, '8、西方肺脉，其形何似？\n\n      师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585176, 'A1C42FC45BD766D3E7935F05E0684C1A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5627, 327, 1001000307, NULL, NULL, NULL, NULL, NULL, NULL, '7、南方心脉，其形何似？\n \n      师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585177, '337C543FB033534C1E04D64E6940E048', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5628, 327, 1001000306, NULL, NULL, NULL, NULL, NULL, NULL, '6、问曰：东方肝脉，其形何似？\n      师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585178, 'E4883081C301A5236DB3665A2278E319', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5629, 327, 1001000305, NULL, NULL, NULL, NULL, NULL, NULL, '5、问曰：经说，脉有三菽、六菽重者，何谓也？\n\n     师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585179, '54271430241A949B6B7A397DF5D167C2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5630, 327, 1001000304, NULL, NULL, NULL, NULL, NULL, NULL, '4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585180, 'AD493F1A9AB02D6FDFB02373ECB7DBC4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5631, 327, 1001000303, NULL, NULL, NULL, NULL, NULL, NULL, '3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619776122585181, '6B4EDDBC05B3066FBAD2A2BA489C0BD7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-06 17:35:32', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5632, 327, 1001000359, NULL, NULL, NULL, NULL, NULL, NULL, '59、问曰：脉有灾怪，何谓也？师曰：假令人病，脉得太阳，与形证相应，因为作汤。比还送汤如食顷，病人乃大吐，若下利，腹中痛。\n     \n        师曰：我前来不见此证，今乃变异，是名灾怪。又问曰：何缘得此吐利？师曰：或有旧时服药，今乃发作，故名灾怪耳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238917, '42ABD9A3AAFD9F43C48AC23139C4E937', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5633, 327, 1001000358, NULL, NULL, NULL, NULL, NULL, NULL, '58、师曰：病家人来请云，病人发热，烦极。明日师到，病人向壁卧，此热已去也。设令脉不和，处言已愈。设令向壁卧，闻师到，不惊起而盼视，若三言三止，脉之，咽唾者，此诈病也。设令脉自和，处言此病大重，当须服吐下药，针灸数十百处，乃愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238918, '5F043267F94A906B927E325E79F5BB15', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5634, 327, 1001000357, NULL, NULL, NULL, NULL, NULL, NULL, '57、师曰：病家人请云病人苦发热，身体疼，病人自卧，师到，诊其脉，沉而迟者，知其瘥也；何以知之？凡表有病者，脉当浮大，今反沉迟故知愈也；假令病人云腹内卒痛，病人自坐，师到，脉之，浮而大者，知其瘥也；凡里有病者，脉当沉细，今反浮大，故知愈也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238919, 'CD392F46A6B76E52EAFD86BCDEDC1296', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 1, 'admin', '2025-07-30 12:02:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5635, 327, 1001000356, NULL, NULL, NULL, NULL, NULL, NULL, '56、师曰：伏气之病，以意候之，今月之内，欲知伏气。假令旧有伏气，当须脉之。若脉微弱者，当喉中痛似伤，非喉痹也，病人云实咽中痛。虽尔，今复宜下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238920, '6A7BFE87B172000D06532EEB8F3B97AA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 1, 'admin', '2025-07-30 12:01:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5636, 327, 1001000355, NULL, NULL, NULL, NULL, NULL, NULL, '55、病六七日，手足三部脉皆至，大烦而口噤不能言，其人躁扰者，未欲解也。若脉和，其人不烦，目重，睑内际黄者，此欲解也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238921, '16879EE4BC4978E278B680F6E46D80C2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5637, 327, 1001000354, NULL, NULL, NULL, NULL, NULL, NULL, '54、脉浮而迟，面热赤而战惕者，六七日当汗出而解。反发热者差迟。迟为无阳，不能作汗，其身必痒也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238922, '5F2D3F1623304132522FDCE00445D217', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5638, 327, 1001000353, NULL, NULL, NULL, NULL, NULL, NULL, '53、问曰：伤寒三日，脉浮数而微，病人身凉和者，何也？\n\n        师曰：此为欲解也。解以夜半。浮而解者，濈然汗出也；数而解者，必能食也；微而解者，必大汗出也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238923, '55968DE94BE67106BB9C7603FFFA4FD5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5639, 327, 1001000352, NULL, NULL, NULL, NULL, NULL, NULL, '52、问曰：病有不战不汗出而解者，何也？\n\n       答曰：其脉自微，此以曾发汗、若吐、若下、若亡血，以内无津液，此阴阳自和，必自愈，故不战不汗出而解也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238924, '56B754E7D7C7F5CB18C7D49981F0ED4E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5640, 327, 1001000351, NULL, NULL, NULL, NULL, NULL, NULL, '51、问曰：病有不战而汗出解者何也？师曰：脉大而浮数，故不战汗出而解也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238925, '8D233C63FFE8F55AFC285514776D6CBF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5641, 327, 1001000350, NULL, NULL, NULL, NULL, NULL, NULL, '50、问曰：病有战而汗出，因得解者，何也？\n\n       师曰：脉浮而紧，按之反芤，此为本虚，故当战而汗出也。其人本虚，是以发战。以脉浮紧，故当汗出而解也。若脉浮数，按之不芤，此人本不虚；若欲自解，但汗出耳，不发战也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238926, 'CC5B9BB4BF526D1EC161DD8C84A7CC53', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5642, 327, 1001000349, NULL, NULL, NULL, NULL, NULL, NULL, '49、寸口脉浮而大，有热，心下反鞕，属脏者攻之，不令发汗。属腑者不令溲数。溲数则大便鞕，汗多则热甚，脉迟者尚未可攻也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238927, '6EFA144050D5E9C844E0006EB4C94BCA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5643, 327, 1001000348, NULL, NULL, NULL, NULL, NULL, NULL, '48、寸口脉阴阳俱紧，至于吐利，其脉独不解，紧去人安，此为欲解。若脉迟至六七日，不欲食，此为晚发，水停故也，为未解；食自可者，为欲解。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238928, '0C96437F9B963446EE6B90650CD8FE40', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5644, 327, 1001000347, NULL, NULL, NULL, NULL, NULL, NULL, '47、寸口脉阴阳俱紧者，口中气出，唇口干燥，蜷卧足冷，鼻中涕出，舌上胎滑，勿妄治也。到七日以来，其人微发热，手足温者，此为欲解；或到八日以上，反大发热者，此为难治。设使恶寒者，必欲呕也；腹内痛者，必欲利也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238929, '8EDE1F3CD0BB32FDF4439F50DCCE3603', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5645, 327, 1001000346, NULL, NULL, NULL, NULL, NULL, NULL, '46、寸口脉阴阳俱紧者，法当清邪中于上焦，浊邪中于下焦。清邪中于上，名曰洁也；浊邪中于下，名曰浑也，阴中于邪，必内栗也，表气微虚，里气不守，故使邪中于阴也。阳中于邪，必发热、头痛、项强、颈挛、腰痛、胫酸，所谓阳中雾露之气，故曰清邪中上。浊邪中下，阴气为栗，足膝逆冷，便溺妄出，表气微虚，里气微急，三焦相混，内外不通，上焦怫郁，脏气相熏，口烂食断也。中焦不治，胃气上冲，脾气不转，胃中为浊，荣卫不通，血凝不流。若胃气前通者，小便赤黄，与热相搏，因热作使，游于经络，出入脏腑，热气所过，则为痈脓。若阴气前通者，阳气厥微，阴无所使，客气内入，嚏而出之，声嗢咽塞，寒厥相追，为热所拥，血凝自下，状如豚肝，阴阳俱厥，脾气弧弱，五液注下，下焦不阖，清便下重，令便数难，脐筑湫痛，命将难全。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238930, '17CAF4E1F1AD3EA576CA882524D2FB48', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5646, 327, 1001000345, NULL, NULL, NULL, NULL, NULL, NULL, '45、问曰：病有洒淅恶寒而复发热者何也？\n\n       师曰：阴脉不足，阳往从之；阳脉不足，阴往乘之也。何谓阳脉不足？师曰：假令寸口脉微，名曰阳不足，阴气上入阳中，则洒淅恶寒也，何谓阴不足？师曰：假令尺脉弱，名曰阴不足，阳气下陷入阴中，则发热也。阴脉弱者，则血虚。血虚则筋急也。其脉涩者，荣气微也。其脉浮而汗出如流珠者，卫气衰也。荣气微者，加烧针，则血留不行，更发热而躁烦也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238931, 'F323F4525F509BF4EBEEEB7061F60A8B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5647, 327, 1001000344, NULL, NULL, NULL, NULL, NULL, NULL, '44、寸口脉浮而数，浮为风，数为热，风为虚，虚为寒，风虚相搏，则洒淅恶寒也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238932, '765441F236559C6A1B3CF2D43FD589CF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5648, 327, 1001000343, NULL, NULL, NULL, NULL, NULL, NULL, '43、寸口脉浮而紧，浮则为风，紧则为寒。风则伤卫，寒则伤荣。荣卫俱病，骨节烦疼，当发其汗也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238933, 'F634A5686A7D1A3810C2D90E4C1C46CD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5649, 327, 1001000342, NULL, NULL, NULL, NULL, NULL, NULL, '42、寸口脉浮为在表，沉为在里，数为在腑，迟为在脏。假令脉迟，此为在脏也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238934, '97A2618303386851FB6E22FA9D625D19', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5650, 327, 1001000341, NULL, NULL, NULL, NULL, NULL, NULL, '41、寸口脉缓而迟，缓则阳气长，其色鲜，其颜光，其声商，毛发长；迟则阴气盛，骨髓生，血满，肌肉紧薄鲜鞕。阴阳相抱，荣卫俱行，刚柔相得，名曰强也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238935, '9DDD5BA4AA497ABEAA180E51218A4516', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5651, 327, 1001000340, NULL, NULL, NULL, NULL, NULL, NULL, '40、脉浮者在前，其病在表；浮者在后，其病在里；假令濡而上鱼际者，宗气泄也；孤而下尺中者，精不脏也；若乍高乍卑，乍升乍坠，为难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238936, 'A5FC7B178900535B1614184FB2A54A95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5652, 327, 1001000339, NULL, NULL, NULL, NULL, NULL, NULL, '39、问曰：脉病欲知愈未愈者，何以别之？\n     \n      答曰：寸口、关上、尺中三处，大、小、浮、沉、迟、数同等，虽有寒热不解者，此脉阴阳为和平，虽剧当愈。师曰：寸脉下不至关，为阳绝；尺脉上不至关，为阴绝。此皆不治，决死也。若计其余命生死之期，期以月节克之也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238937, '6119E5C22B8EE2272C6B62C513DEDD14', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5653, 327, 1001000338, NULL, NULL, NULL, NULL, NULL, NULL, '38、问曰：凡病欲知何时得，何时愈，何以知之？\n\n       师曰：假令夜半得病者，明日日中愈；日中得病者，夜半愈。何以言之？日中得病，夜半愈者，以阳得阴则解也。夜半得病，明日日中愈者，以阴得阳则解也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238938, '6183442A32FAF25FCA84A3C08AE70C8C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5654, 327, 1001000337, NULL, NULL, NULL, NULL, NULL, NULL, '37、师曰：立夏得洪大脉是其本位。其人病身体苦疼重者，须发其汗。若明日身不疼不重者，不须发汗。若汗濈濈自出者，明日便解矣。何以言之？立夏脉洪大是其时脉，故使然也。四时仿此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238939, 'D9C96DEB02096C8A47CD144C8E95DA66', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5655, 327, 1001000336, NULL, NULL, NULL, NULL, NULL, NULL, '36、问曰：二月得毛浮脉，何以处言至秋当死。\n\n       师曰：二月之时，脉当濡弱，反得毛浮者，故知至秋死。二月肝用事，肝属木，脉应濡弱，反得毛浮者，是肺脉也。肺属金，金来克木，故知至秋死。他皆仿此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238940, 'C82BD1A35245898CAF15DC6B570C5627', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5656, 327, 1001000335, NULL, NULL, NULL, NULL, NULL, NULL, '35、阳脉浮大而濡，阴脉浮大而濡，阴脉与阳脉同等者，名曰缓也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238941, 'E42D59D0011F8ADABEF4109E95D2962B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5657, 327, 1001000334, NULL, NULL, NULL, NULL, NULL, NULL, '34、寸口卫气盛，名曰高；荣气盛，名曰章；高章相搏，名曰纲。卫气弱，名曰惵；荣气弱，名曰卑；惵卑相搏，名曰损。卫气和，名曰缓；荣气和，名曰迟；迟缓相搏，名曰沉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238942, 'C6608F49E888136CF8DA3B9C9444AA9E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5658, 327, 1001000333, NULL, NULL, NULL, NULL, NULL, NULL, '33、师曰：呼吸者，脉之头也。初持脉来疾去迟，此出疾入迟，名曰内虚外实也。初持脉，来迟去疾，此出迟入疾，名曰内实外虚也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238943, 'EE89DC6FA4669E04624A8194A8AB649B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5659, 327, 1001000332, NULL, NULL, NULL, NULL, NULL, NULL, '32、师曰：脉，肥人责浮，瘦人责沉。肥人当沉，今反浮；瘦人当浮，今反沉，故责之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238944, '4FC440F91BC1797DF2586A2F9ACFCE2A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5660, 327, 1001000331, NULL, NULL, NULL, NULL, NULL, NULL, '31、师曰：脉病人不病，名曰行尸，以无王气，卒眩仆，不识人者，短命则死。人病脉不病，名曰内虚，以少谷神，虽困无苦。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238945, '1C5C6E4C3DE60017FF4A5311EDF5E604', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5661, 327, 1001000330, NULL, NULL, NULL, NULL, NULL, NULL, '30、实则谵语，虚则郑声；假令言出声卑者，为气虚；言出声高者，为气实；欲言手按胸中者，胸中满痛；欲言手按腹者，腹中满痛；欲言声不出者，咽中肿痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238946, '737CC9CA47009B6F441DD468E4311D7A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5662, 327, 1001000329, NULL, NULL, NULL, NULL, NULL, NULL, '29、病人长叹声，出高入卑者，病在上焦；出卑入高者，病在下焦；出入急促者，病在中焦有痛处；声唧唧而叹者，身体疼痛；问之不欲语，语先泪下者，必有忧郁；问之不语，泪下不止者，必有隐衷；问之不语，数问之而微笑者，必有隐疾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238947, 'E3A6FCF33FBFE045E2FDF4F6FB68F0BD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5663, 327, 1001000328, NULL, NULL, NULL, NULL, NULL, NULL, '28、师曰：持脉，病人欠者，无病也。脉之，呻者，病也。言迟者，风也。摇头言者，里痛也。行迟者，表强也。坐而伏者，短气也。坐而下一脚者，腰痛也。里实护腹，如怀卵物者，心痛也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 619997388238948, 'BAFCB93BA7A39794C5417EAE800DEF9A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 08:35:52', 2, 'Admin666', '2024-12-23 09:24:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5664, 328, 1001000504, NULL, NULL, NULL, NULL, NULL, NULL, '104、问曰：其处方奈何？\n\n         师曰：相体虚实，察病轻重，采取方法，权衡用之，则无失也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385605, 'B859938FB703E99BFAF6B78AE663C60D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5665, 328, 1001000503, NULL, NULL, NULL, NULL, NULL, NULL, '103、问曰：八脉内伤其脉何似？\n \n        师曰：督脉伤，尺脉大而涩；任脉伤，关脉大而涩；冲脉伤，寸脉短而涩；带脉伤，脉沉迟而结；阳跷伤，脉时大而弦；阴跷伤，脉时细时弦；阳维伤，脉时缓时弦；阴维伤，脉时紧时涩。问曰：其治奈何？师曰：督脉伤，当补髓；任脉伤，当补精；冲脉伤，当补气；带脉伤，当补肾；阳跷伤，则益胆；阴跷伤，则补肝；阴维伤，则调卫；阴维伤，则养荣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385606, '105688A9B612FAF93F6570CB285A2495', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5666, 328, 1001000502, NULL, NULL, NULL, NULL, NULL, NULL, '102、问曰：八脉内伤何以别之？\n\n         师曰：督脉伤，柔柔不欲伸，不能久立，立则隐隐而胀；任脉伤，小便多，其色白浊；冲脉伤，时咳不休，有声无物，劳则；地喘；带脉伤，回身一周冷；阳跷伤，则身左不仁；阴跷伤，则身右不仁；阳维伤，则畏寒甚，皮常湿；阴维伤，则畏热甚，皮常枯。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385607, 'D9B5C6DDC0582A57AC17708461EB3ABB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5667, 328, 1001000501, NULL, NULL, NULL, NULL, NULL, NULL, '101、奇经八脉之病，由各经受邪，久久移传，或劳伤所致，非暴发也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385608, 'DC7E185601979F46FFCFC3CC30487416', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5668, 328, 1001000500, NULL, NULL, NULL, NULL, NULL, NULL, '100、阳维维于阳，阴维维于阴，为气血之别，使不拘于一经也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385609, 'FAC0DADF4067A72E6F1947074600085F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5669, 328, 1001000499, NULL, NULL, NULL, NULL, NULL, NULL, '99、阴维与诸阴交，其为病在脉中，心中痛，手心热，脉当弦而涩，治属血分。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385610, 'E0BF71EE0561CF70D620C37BA7307E73', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5670, 328, 1001000498, NULL, NULL, NULL, NULL, NULL, NULL, '98、阳维与诸阳会，其为病在脉外，发寒热，脉当浮而虚，治属气分。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385611, 'D2E2715DD1631DAB445C3156D8679DA7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5671, 328, 1001000497, NULL, NULL, NULL, NULL, NULL, NULL, '97、阴跷为病，中于侧，气行于内，脉当浮缓，按之微急而弦，治属厥阴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385612, 'E272F1C89161AB274F56128DF18F480A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5672, 328, 1001000496, NULL, NULL, NULL, NULL, NULL, NULL, '96、阳跷为病，中于侧，气行于外，脉当弦急，按之缓，治属少阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704385613, 'E213D497CBE310298D60E5D2E614209C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
