INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5749, 328, 1001000419, NULL, NULL, NULL, NULL, NULL, NULL, '19、阙庭脉色赤而沉细，推之参差不齐者，病在心；赤而横弋，推之愈赤者，病在小肠。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389727, '345F87E226884DD00F687522AF667DBF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5750, 328, 1001000418, NULL, NULL, NULL, NULL, NULL, NULL, '18、阙庭脉色青而沉细，推之不移者，病在肝；青而浮大，推之随转者，病在胆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389728, '27A74591413FCED29F1BA169AE76C779', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5751, 328, 1001000417, NULL, NULL, NULL, NULL, NULL, NULL, '17、色黑者，病在肾与膀胱；假令身色黑，明堂色微青者，生；黄者，死；黄赤者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389729, '4D11A5F92E0A8310E87E64FF6429120C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5752, 328, 1001000416, NULL, NULL, NULL, NULL, NULL, NULL, '16、色白者，病在肺与大肠；假令身色白，明堂色微黑者，生；赤者，死；黄赤者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389730, '3259D2E1E5EAD81B03238C5DD1D35F4C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5753, 328, 1001000415, NULL, NULL, NULL, NULL, NULL, NULL, '15、色黄者，病在脾与胃；假令身色黄，明堂微白者，生；青者，死；黄青者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389731, '5C454CA1B402A362F55450498745D03D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5754, 328, 1001000414, NULL, NULL, NULL, NULL, NULL, NULL, '14、色赤者，病在心与小肠；假令身色赤，明堂微黄者，生；黑者，死；黄黑者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389732, '6E2945C2740B218FB9586B64A99EF1E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5755, 328, 1001000413, NULL, NULL, NULL, NULL, NULL, NULL, '13、色青者，病在肝与胆；假令身色青，明堂色微赤者，生；白者，死；黄白者，半死半生也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389733, '09C5248742B4458B57202C20509632B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5756, 328, 1001000412, NULL, NULL, NULL, NULL, NULL, NULL, '12、问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。\n\n        师曰：夫色合脉，色主形外，脉主应内；其色露脏，亦有内外；察色之妙，明堂阙庭；察色之法，大指推之；察明堂推而下之，察阙庭推而上之；五色应五脏，如肝色青，脾色黄，肺色白，心色赤，肾色黑，显然易晓；色之生死，在思用精，心迷意惑，难与为言。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389734, '549F7FFEABD4A9966E4B78CA66073C4A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5757, 328, 1001000411, NULL, NULL, NULL, NULL, NULL, NULL, '11、师曰：六气所伤，各有法度；舍有专属，病有先后；风中于前，寒中于背；湿伤于下，雾伤于上；雾客皮腠，湿流关节；极寒伤经，极热伤络；风令脉浮，寒令脉紧，又令脉急；暑则浮虚，湿则濡涩；燥短以促，火躁而数；风寒所中，先客太阳；暑气炎热，肺金则伤；湿生长夏，病入脾胃；燥气先伤，大肠合肺；壮火食气，病生于内，心与小肠，先受其害；六气合化，表里相传；脏气偏胜，或移或干；病之变证，难以殚论；能合色脉，可以万全。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389735, 'EF857B14FDE34A3AED4E9217EC32E068', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5758, 328, 1001000410, NULL, NULL, NULL, NULL, NULL, NULL, '10、师曰：人迎脉大，趺阳脉小，其常也；假令人迎趺阳平等为逆；人迎负趺阳为大逆；所以然者，胃气上升动在人迎，胃气下降动在趺阳，上升力强故曰大，下降力弱故曰小，反此为逆，大逆则死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389736, 'EFC6D1416FD930829E894012EE64B3F1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5759, 328, 1001000409, NULL, NULL, NULL, NULL, NULL, NULL, '9、北方肾脉其形何似？\n\n      师曰：肾者水也，其脉沉而石，肾病自得此脉者，愈；若得实大者，则剧；何以知之？实大者，长夏土王，土克北方水，水脏立涸也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389737, '97D9697920B3D42BEDCDBF013E12FF35', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5760, 328, 1001000408, NULL, NULL, NULL, NULL, NULL, NULL, '8、西方肺脉，其形何似？\n\n      师曰：肺者金也，名太阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火也，火克西方金，法当痈肿，为难治也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389738, 'A1C42FC45BD766D3E7935F05E0684C1A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5761, 328, 1001000407, NULL, NULL, NULL, NULL, NULL, NULL, '7、南方心脉，其形何似？\n\n     师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也。脉来头小本大，故曰复，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿。头无汗者可治，有汗者死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389739, '76595950BDA607187A384CE7A096AED9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5762, 328, 1001000406, NULL, NULL, NULL, NULL, NULL, NULL, '6、问曰：东方肝脉，其形何似？\n\n      师曰：肝者木也，名厥阴，其脉微弦濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死，何以知之？以其脉如弦直，此是肝脏伤，故知死也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389740, 'BA126F6509F04BA90A84D66343F30D14', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5763, 328, 1001000405, NULL, NULL, NULL, NULL, NULL, NULL, '5、问曰：经说，脉有三菽、六菽重者，何谓也？\n\n      师曰：脉，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。假令下利，寸口、关上、尺中，悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损至脉来，为难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389741, 'F104CD1BB5AA0407B29423D2B941A1C7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, '超级管理员', '2024-12-07 10:06:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5764, 328, 1001000404, NULL, NULL, NULL, NULL, NULL, NULL, '4、师曰：脉分寸关尺，寸脉分经以候阳，阳者气之统也；尺脉分经以候阴，阴者血之注也；故曰阴阳。关上阴阳交界，应气血升降，分经以候中州之气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389742, 'AD493F1A9AB02D6FDFB02373ECB7DBC4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, 'admin', '2025-02-24 10:22:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5765, 328, 1001000403, NULL, NULL, NULL, NULL, NULL, NULL, '3、师曰：平脉大法，脉分三部。浮部分经，以候皮肤经络之气；沉部分经，以候五脏之气；中部分经，以候六腑之气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389743, '6B4EDDBC05B3066FBAD2A2BA489C0BD7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, 'admin', '2025-02-24 10:22:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5766, 328, 1001000402, NULL, NULL, NULL, NULL, NULL, NULL, '2、问曰：脉有三部，阴阳相乘。荣卫血气，在人体躬。呼吸出入，上下于中，因息游布，津液流通。随时动作，肖象形容，春弦秋浮，冬沉夏洪。察色观脉，大小不同，一时之间，变无经常，尺寸参差，或短或长。上下乖错，或存或亡。病辄改易，进退低昂。心迷意惑，动失纪纲。愿为具陈，令得分明。\n \n        师曰：子之所问，道之根源。脉有三部，尺寸及关。荣卫流行，不失衡铨。肾沉、心洪、肺浮、肝弦，此自经常，不失铢分。出入升降，漏刻周旋，水下二刻，一周循环。当复寸口，虚实见焉。变化相乘，阴阳相干。风则浮虚，寒则牢坚；沉潜水蓄，支饮急弦；动则为痛，数则热烦。设有不应，知变所缘，三部不同，病各异端。太过可怪，不及亦然，邪不空见，中必有奸，审察表里，三焦别焉，知其所舍，消息诊看，料度脏腑，独见若神。为子条记，传与贤人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389744, 'BCBB590C6DB0DC6B49738AA7CA17F92F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, 'admin', '2025-02-24 10:22:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5767, 328, 1001000401, NULL, NULL, NULL, NULL, NULL, NULL, '1、问曰：脉何以知气血脏腑之诊也？\n\n      师曰：脉乃气血先见，气血有盛衰，脏腑有偏胜。\n\n      气血俱盛，脉阴阳俱盛；气血俱衰，脉阴阳俱衰。\n\n      气独胜者，则脉强；血独盛者，则脉滑；\n\n      气偏衰者，则脉微；血偏衰者，则脉涩；\n\n     气血和者，则脉缓；气血平者，则脉平；\n\n     气血乱者，则脉乱；气血脱者，则脉绝；\n\n     阳迫气血，则脉数；阴阻气血，则脉迟；\n\n    若感于邪，气血扰动，脉随变化，变化无穷，气血使之；\n\n    病变百端，本原别之；欲知病源，当凭脉变；欲知病变，先揣其本，本之不齐，在人体躬，相体以诊，病无遁情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620019704389745, '28FDBCB9283A5BD929D7D5A1662A4D17', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:06:40', 1, 'admin', '2025-02-24 10:22:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5768, 329, 1001005007, NULL, NULL, NULL, NULL, NULL, NULL, '7、问曰：其治法奈何？\n\n     师曰：风寒暑湿燥热各随其气，有假者反之，甚者从之，微者逆之，采取方法，慎毋乱也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620026949673029, 'AFE5BC674B9D8A145FDB3C94D2B36064', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:36:09', 1, '超级管理员', '2024-12-13 19:15:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5769, 329, 1001005006, NULL, NULL, NULL, NULL, NULL, NULL, '6、师曰：子知六气，不知五运，未尽其道，今为子言，假如太阳司天，而运当甲己，夫甲己土运也，太阳寒水也，土能克水，太阳不能正其位也；又如厥阴司天，而逢乙庚金运；少阴少阳司天，而逢丙辛水运；太阴司天，而逢丁壬木运；阳明司天，而逢戊癸火运，其例同也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620026949677125, 'F8C146E0CA957B0041EECEAFE235C4D7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:36:09', 1, '超级管理员', '2024-12-13 19:15:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5770, 329, 1001005005, NULL, '腨、胻、', NULL, NULL, NULL, NULL, '5、问曰：其胜复何如？\n\n      师曰：有胜必有复，无胜则无复也；\n\n      厥阴之胜，则病耳鸣，头眩，愦愦欲吐，胃膈如寒，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上及两胁，肠鸣，飧泄，少腹痛，注下赤白，甚则呕吐，膈不通；其复也，则少腹坚满，里急暴痛，厥心痛，汗发，呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。\n\n     少阴之胜，则病心下热，善饥，脐下气动，气游三焦，呕吐，躁烦，腹满而痛，溏泄赤沃；其复也，则燠热内作，烦躁，鼽嚏，少腹绞痛，嗌燥，气动于左上行于右，咳则皮肤痛，暴喑，心痛，郁冒不知人，洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气，骨痿，膈肠不便，外为浮肿，哕噫，痱疹，疮疡，痈疽，痤痔，甚则入肺，咳而鼻渊。\n\n     太阴之胜，则火气内郁，疮疡于中，流散于外，病在胠胁甚则心痛热格，头痛，喉痹，项强，又或湿气内郁，寒迫下焦，少腹满，腰椎痛强，注泄，足下湿，头重，跗肿，足胫肿，饮发于中，跗肿于上；其复也，则体重，中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声，头项痛重，掉瘛尤甚，呕而密默，唾吐清液，甚则入肾，窃泄无度。\n\n       少阳之胜，则病热客于胃，心烦而痛，目赤呕酸，善饥，耳痛，溺赤，善惊谵妄，暴热消烁，少腹痛，下沃赤白；其复也，枯燥，烦热，惊瘛，咳，衄，心热，烦躁，便数，憎风，厥气上行，面如浮埃，目乃瞤瘛，火气内发，上为口糜，呕逆，血溢，血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴饮水浆，色变黄赤，少气肺痿，化而为水，传为跗肿，甚则入肺，咳而血泄。\n\n       阳明之胜，则清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，胸中不便，嗌而咳；其复也，则病生胠胁，气归于左，善太息，甚则心痛痞满，腹胀而泄，呕苦，咳哕烦心，病在膈中，甚则入肝，惊骇筋挛。\n\n       太阳之胜，则病痔疟，发寒，厥人胃，则内生心痛，阴中乃疡，隐曲不利，亘引阴股筋肉拘苛，血脉凝泣，络满血变，或为血泄，皮肤否肿，腹满时减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，则传为濡泄；其复也，则心胃生寒，胸膈不利，心痛痞满，头痛，善悲，时发眩仆，食减，腰椎反痛，屈伸不便，少腹控睪引腰脊上冲心，唾出清水，及为哕噫，甚则入心，善忘，善悲，寒复内余，则腰尻痛，屈伸不利，股胫足膝中痛。\n\n      此六气为病，须谨识之，而弗失也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620026949677126, '2CF0CC07D86F464DC4BABE7347DE2DD5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 10:36:09', 1, '超级管理员', '2024-12-13 19:15:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5788, 329, 1001005001, NULL, NULL, NULL, NULL, NULL, NULL, '1、问曰：六气主客何以别之？师曰：厥阴生少阴，少阴生少阳，少阳生太阴，太阴生阳明，阳明生太阳，太阳复生厥阴，周而复始，久久不变，年复一年，此名主气；厥阴生少阴，少阴生太阴，太阴生少阳，少阳生阳明，阳明生太阳，复生厥阴，周而复始，此名客气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620033729388613, '3FBB2E191488D4E31FEDBC5A5A4A9DC5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 19:03:50', 1, '超级管理员', '2024-12-13 19:15:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5789, 329, 1001005004, NULL, NULL, NULL, NULL, NULL, NULL, '4、问曰：其为病也何如？\n\n     师曰：亦有主客之分也；\n\n    假如厥阴司天，主胜，则胸胁痛，舌难以言；客胜，则耳鸣，掉眩，甚则咳逆。\n\n   少阴司天，主胜，则心热，烦躁，胁痛支满；客胜，则鼽嚏，颈项强，肩背瞀热，头痛，少气，发热，耳聋，目暝，甚则跗肿，血溢，疮，喑，喘咳。\n\n   太阴司天，主胜，则胸腹满，食已而瞀；客胜，则首、面、跗肿，呼吸气喘。\n\n   少阳司天，主胜，则胸满，咳逆，仰息，甚则有血，手热；客胜，则丹疹外发，及为丹熛，疮疡，呕逆，喉痹，头痛，嗌踵，耳聋，血溢，内为瘛疭。\n\n   阳明司天，主胜，则清复内余，咳，衄，嗌塞，心膈中热，咳不止而白血出者死，金居少阳之位，客不胜主也。\n\n   太阳司天，主胜，则喉嗌中鸣；客胜，则胸中不利，出清涕，感寒则咳也。\n\n   厥阴主在泉，主胜，则筋骨徭并，腰腹时痛；客胜，则关节不利，内为痉强，外为不便。\n\n  少阴在泉，主胜，则厥气上行，心痛发热，膈中众痹皆作，发于胠胁，魄汗不藏，四逆而起；客胜，则腰痛，尻、股、膝、髀、腨、胻、足病瞀热以酸，跗肿不能久立，溲便变。\n\n   太阴在泉，主胜，则寒气逆满，食饮不下，甚则为疝；客胜，则足痿下肿，便溲不时，湿客下焦，发而濡泄，及为阴肿，隐曲之疾。\n\n   少阳在泉，主胜，则热反上行，而客于心，心痛发热，格中而呕；客胜，则腰腹痛，而反恶寒，甚则下白溺白。\n\n   阳明在泉，主胜，则腰重，腹痛，少腹生寒，下为鹜溏，寒厥于肠，上冲胸中，甚则喘满，不能久立；客胜，则清气动下，小腹坚满，而数便泄。\n\n   太阳在泉，以水居水位，无所胜也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620034757943365, 'C05264D305757FC5D1FE28961F159324', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 19:07:55', 1, '超级管理员', '2024-12-13 19:15:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5790, 329, 1001005003, NULL, NULL, NULL, NULL, NULL, NULL, '3、问曰：司天在泉奈何？\n\n    师曰：此客气也。假如子午之年，少阴司天，阳明则为在泉，太阳为初气，厥阴为二气，司天为三气，太阴为四气，少阳为五气，在泉为终气；卯酉之年，阳明司天，少阴在泉，则初气太阴，二气少阳，三气阳明，四气太阳，五气厥阴，终气少阴；戌辰之年，太阳司天，太阴在泉；丑未之年，太阴司天，太阳在泉；寅申之年，少阳司天，厥阴在泉；巳亥之年，厥阴司天，少阳在泉；其余各气，以例推之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620034757943366, 'DA599440975059338558150016049136', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 19:07:55', 1, '超级管理员', '2024-12-13 19:15:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5791, 329, 1001005002, NULL, NULL, NULL, NULL, NULL, NULL, '2、问曰：其始终奈何？\n\n      师曰：初气始于大寒，二气始于春分，三气始于小满，四气始于大暑，五气始于秋分，终气始于小雪，仍终于大寒，主客相同，其差各三十度也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620034757943367, '557C512B0044966AAF688DFDC4519E4A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 19:07:55', 1, '超级管理员', '2024-12-13 19:15:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5792, 330, 1001006003, NULL, NULL, NULL, NULL, NULL, NULL, '3、阴阳大论云：春气温和，夏气暑热，秋气清凉，冬气冰冽，此则四时正气之序也。\n\n    冬时严寒，万类深藏，君子周密，则不伤于寒。触冒之者，则名伤寒耳。其伤于四时之气，皆能为病。以伤寒为病者，以其最盛杀厉之气也。中而即病者，名曰伤寒；不即病，寒毒藏于肌肤，至春变为温病，至夏变为暑病。\n   暑病者，热极重于温也。是以辛苦之人，春夏多温热者，皆由冬时触寒所致，非时行之气也。凡时行者，春时应暖而反大寒；夏时应热而反大凉；秋时应凉而反大热；冬时应寒而反大温。此非其时而有其气，是以一岁之中，长幼之病多相似者，此则时行之气也。夫欲候知四时正气为病，及时行疫气之法，皆当按斗历占之。\n    九月霜降节后，宜渐寒，向冬大寒，至正月雨水节后宜解也。所以谓之雨水者，以冰雪解而为雨水故也。\n    至惊蛰二月节后，气渐和暖，向夏大热，至秋便凉。\n    从霜降以后，至春分以前，凡有触冒霜露，体中寒即病者，谓之伤寒也。\n    九月十月寒气尚微，为病则轻；十一月十二月寒冽已严，为病则重；正月二月寒渐将解，为病亦轻。此以冬时不调，适有伤寒之人即为病也。其冬有非节之暖者，名曰冬温。\n    冬温之毒，与伤寒大异，冬温复有先后，更相重沓，亦有轻重，为治不同，证如后章。\n    从立春节后，其中无暴大寒，又不冰雪；而有人壮热为病者，此属春时阳气，发其冬时伏寒，变为温病。\n    从春分以后，至秋分节前，天有暴寒者，皆为时行寒疫也。三月四月或有暴寒，其时阳气尚弱，为寒所折，病热犹轻；五月六月阳气已盛，为寒所折，病热则重；七月八月，阳气已衰，为寒所折，病热亦微。其病与温相似，但治有殊耳。\n\n   十五日得一气，于四时之中，一时有六气，四六名为二十四气。然气候亦有应至仍不至，或有未应至而至者，或有至而太过者，皆成病气也。但天地动静，阴阳鼓击者，各正一气耳。是以彼春之暖，为夏之暑；彼秋之忿，为冬之怒。是故冬至之后，一阳爻升，一阴爻降也。\n    夏至之后，一阳气下，一阴气上也。斯则冬夏二至，阴阳合也；春秋二分，阴阳离也。阴阳交易，人变病焉。此君子春夏养阳，秋冬养阴，顺天地之刚柔也。小人触冒，必婴暴疹。须知毒烈之气，留在何经，必发何病，详而取之。是以春伤于风，夏必飧泄；夏伤于暑，秋必病疟；秋伤于湿，冬必咳嗽；\n   冬伤于寒，春必病温。此必然之道，可不审明之。伤寒之病，逐日浅深，以施方治。\n\n   今世人伤寒，或始不早治，或治不对病，或日数久淹，困乃告医。医人又不依次第而治之，则不中病。皆宜临时消息制方，无不效也。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620044873826373, 'C34825C56B00E69FF351B060190E7593', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 11:49:05', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5793, 330, 1001006002, NULL, NULL, NULL, NULL, NULL, NULL, '2、二十四节气，节有十二，中气有十二，五日为一候，气亦同，合有七十二候，决病生死，此须洞解也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620044873826374, 'B1A9EC05D7C785EED6447D56FE3CD111', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 11:49:05', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5794, 330, 1001006001, NULL, NULL, NULL, NULL, NULL, NULL, '1、\n四时八节二十四节气七十二候决病法：\n立春正月节斗指艮，雨水正月中斗指寅。\n惊蛰二月节斗指甲，春分二月中斗指卯。\n清明三月节斗指乙，谷雨三月中斗指辰。\n立夏四月节斗指巽，小满四月中斗指巳。\n芒种五月节斗指丙，夏至五月中斗指午。\n小暑六月节斗指丁，大暑六月中斗指未。\n立秋七月节斗指坤，处暑七月中斗指申。\n白露八月节斗指庚，秋分八月中斗指酉。\n寒露九月节斗指辛，霜降九月中斗指戌。\n立冬十月节斗指干，小雪十月中斗指亥。\n大雪十一月节斗指壬，冬至十一月中斗指子。\n小寒十二月节斗指癸，大寒十二月中斗指丑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620044873826375, 'B98C54155C1791153C411424AA67A64D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 11:49:05', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5795, 330, 1001006012, NULL, NULL, '白虎汤,大承气汤,小承气汤,调胃承气汤', NULL, NULL, NULL, '12、传阳明，脉大而数，发热，汗出，口渴舌燥，宜$f{白虎汤}，不差与$n{承气汤}--$f{大承气汤}--$f{小承气汤}--$f{调胃承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908037, '6AC7F863A42D057594E6B2D6699FC6DF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5796, 330, 1001006011, NULL, NULL, '麻黄汤', NULL, NULL, NULL, '11、伤寒传经在太阳，脉浮而急数，发热，无汗，烦躁，宜$f{麻黄汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908038, '1CC4389B3D19E2BFCBB7258C56742E5E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5797, 330, 1001006010, NULL, NULL, NULL, NULL, NULL, NULL, '10、尺寸俱弦微者，厥阴受病也，当六七日发。以其脉循阴器、络于肝，故烦满而囊缩。此三经受病，己入于腑者，皆可下而已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908039, '0FF6D37EBE641FAC043A91F573EA892F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5798, 330, 1001006009, NULL, NULL, NULL, NULL, NULL, NULL, '9、尺寸俱沉细者，少阴受病也，当五六日发。以其脉贯肾，络于肺，系舌本，故口燥舌干而渴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908040, 'BC7FE98BC0FF926383635FC8464AC49F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5799, 330, 1001006008, NULL, NULL, NULL, NULL, NULL, NULL, '8、尺寸俱沉濡者，太阴受病也，当四五日发。以其脉布胃中，络于嗌，故腹满而嗌干。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908041, '4E5055C4A02BE25BEE26E43E04E46FA3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5800, 330, 1001006007, NULL, NULL, NULL, NULL, NULL, NULL, '7、尺寸俱弦者，少阳受病也，当三四日发。以其脉循胁络于耳，故胸胁痛而耳聋。此三经受病，未入于腑者，皆可汗而已。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908042, 'FDE0900BD96DE8B094DBEB8339543A37', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5801, 330, 1001006006, NULL, NULL, NULL, NULL, NULL, NULL, '6、尺寸俱长者，阳明受病也，当二三日发。以其脉侠鼻、络于目，故身热、汗出、目疼、鼻干、不得卧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908043, '8FC413BDAD76D8E3F1B97EDBD187823F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5802, 330, 1001006005, NULL, NULL, NULL, NULL, NULL, NULL, '5、凡伤于寒，传经则为病热，热虽甚，不死。若两感于寒而病者，多死。尺寸俱浮者，太阳受病也，当一二日发。以其脉上连风府，故头项痛，腰脊强。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908044, '6379932F13EB91E1E26033BBDD648B9E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5803, 330, 1001006004, NULL, NULL, NULL, NULL, NULL, NULL, '4、又土地温凉，高下不同；物性刚柔，餐［注：桂本餐字为飧，似误］居亦异。是故黄帝兴四方之问，岐伯举四治之能，以训后贤，开其未悟。临病之工，宜须两审也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620047789908045, '118A026B505D82D051D8C1AB656A85A0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 12:00:57', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5804, 330, 1001006065, NULL, NULL, NULL, NULL, NULL, NULL, '65、凡服下汤，得利便止，不必尽剂。此以前是汗吐下三法之大要也。若能于此例之外，更神而明之，斯道其庶几乎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757509, 'FF54FAB00C6EC331E098F66147BD049D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5805, 330, 1001006064, NULL, NULL, NULL, NULL, NULL, NULL, '64、伤寒发热，口中勃勃气出，头痛，目黄，衄不可制，阴阳俱虚，贪水者必呕，恶水者厥。若下之，则咽中生疮；假令手足温者，必下重便脓血。头痛目黄者，下之则目闭。贪水者，下之则脉厥，其声嘤嘤，咽喉塞，汗之则战栗；恶水者，下之则里冷，不嗜食，大便完谷出，汗之则口中伤，舌上白胎，烦躁，脉反数，不大便，六七日后必便血，小便不利也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757510, '4B9CB94F644EC29EF5C39439B8248A5E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5806, 330, 1001006063, NULL, NULL, NULL, NULL, NULL, NULL, '63、伤寒，脉阴阳俱紧，恶寒发热，则脉欲厥。厥者，脉初来大，渐渐小，更来渐大，是其候也。如此者恶寒，甚者，翕翕汗出，喉中痛；若热多者，目赤脉多，睛不慧，医复发之，咽中则伤；若复下之，则两目闭，寒多便清谷，热多便脓血；若熏之，则身发黄；若熨之，则咽燥。若小便利者，可救之；小便难者，危殆也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757511, '9C61EC29BA6CEAB9899CFFE3E8786FD5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5807, 330, 1001006062, NULL, NULL, NULL, NULL, NULL, NULL, '62、脉浮而大，心下反鞕，有热，属脏者，攻之，不令发汗；属腑者，不令溲数。溲数则大便鞕，汗多则越甚，脉迟者，尚未可攻也。。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757512, 'D6E7B9F2097BC183096AD0E3F2D71982', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5808, 330, 1001006061, NULL, NULL, NULL, NULL, NULL, NULL, '61、脉浮而紧，浮则为风，紧则为寒；风则伤卫，寒则伤荣；荣卫俱病，骨节烦疼；当发其汗，而不可下也。。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757513, '24A06F5F62822D24CCA27D15C842015C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5809, 330, 1001006060, NULL, NULL, NULL, NULL, NULL, NULL, '60、脉濡而紧，濡则卫气微，紧则荣中寒。阳微卫中风，发热而恶寒；荣紧胃气冷，微呕心内烦。医谓有大热，解肌而发汗，亡阳虚烦躁，心下苦痞坚。表里俱虚竭，卒起而头眩。客热在皮肤，怅怏不得眠。不知胃气冷，紧寒在关元。技巧无所施，汲水灌其身。客热应时罢，栗栗而振寒。重被而复之，汗出而冒巅。体惕而又振，小便为微难。寒气因水发，清谷不容闲。呕变反肠出，颠倒不得安。手足为微逆，身冷而内烦。迟欲从后救，安可复追还。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757514, 'F8242F72D55D598C0C1E37F5D53CC2FD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5810, 330, 1001006059, NULL, NULL, NULL, NULL, NULL, NULL, '59、脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，虚者不可下也。微弦为咳，咳则吐涎，下之则咳止，而利因不休，利不休则胸中如虫啮，粥入则出，小便不利，两胁拘急，喘息为难，颈背相引，臂则不仁，极寒反汗出，身冷若冰，眼睛不慧，语言不休，而谷气多入，此为除中，口虽欲言，舌不得前。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757515, '57F51B820FB62E27D501ACD10B4DAC74', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5811, 330, 1001006058, NULL, NULL, NULL, NULL, NULL, NULL, '58、诸虚者，不可下之。下之则大渴，求水者易愈，恶水者剧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757516, 'EDE48DDF7137DD3DF6DE0AC120A0368F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5812, 330, 1001006057, NULL, NULL, NULL, NULL, NULL, NULL, '57、诸外实者，不可下之。下之则发微热，若亡脉厥者，当脐握热。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757517, '2DFB25F9CC78E3CEC0BA867C70635F85', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5813, 330, 1001006056, NULL, NULL, NULL, NULL, NULL, NULL, '56、咽中闭寒，不可下之。下之则上轻下重，水浆不下，卧则欲蜷，身急痛，下利日数十行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 620101661757518, '3861B1D3FD0708778B5A8B6C890B89AC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:40:09', 1, '超级管理员', '2024-12-13 21:37:37');
