INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6017, 340, 1001016051, NULL, NULL, '栀子豉汤', NULL, NULL, NULL, '83、伤寒五六日，大下之后，身热不去，心中结痛者，未欲解也，$f{栀子豉汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652815, '12516EEE149FC0319D3F660DA48C2F34', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
