INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6020, 340, 1001016048, NULL, NULL, NULL, NULL, NULL, NULL, '80、发汗后，水药不得入口为逆，若更发汗，必吐下不止。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652818, '2D756CFFD405F2893F2E57A0D44EC856', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6021, 340, 1001016047, NULL, NULL, NULL, NULL, NULL, NULL, '79、发汗后，饮水多，必喘，以水灌之，亦喘。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652819, 'B8D93F91190AB55AD7AE2F0D9F64E589', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6022, 340, 1001016046, NULL, NULL, NULL, NULL, NULL, NULL, '78、未持脉时，病人叉手自冒心，师因试教令咳而不咳者，此必两耳聋无所闻也。所以然者，以重发汗，虚故此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652820, 'BB49F026742F12E96AB0D22CF57D450D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6023, 340, 1001016045, NULL, NULL, NULL, NULL, NULL, NULL, '77、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆。$f{五苓散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652821, '59784F2590A209836BAF5C9CB99A3014', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6024, 340, 1001016044, NULL, NULL, '五苓散,茯苓甘草汤', NULL, NULL, NULL, '76、伤寒汗出而渴，小便不利者，${五苓散}主之。不渴者，$f{茯苓甘草汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652822, '1F24BF6BA7C26F53CCD59810669A4A63', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6025, 340, 1001016043, NULL, NULL, '五苓散', NULL, NULL, NULL, '75、太阳病，发汗已，脉浮弦，烦渴者，$f{五苓散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652823, '72783B1EB9CEFDC9F587ADB9FE3C21FF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6026, 340, 1001016042, NULL, NULL, '五苓散', NULL, NULL, NULL, '74、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水，少少与之，令胃气和则愈。若脉浮，小便不利，微热消渴者，$f{五苓散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652824, '7523155BC909BE138F197C762AAC8FC0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6027, 340, 1001016041, NULL, NULL, '调胃承气汤', NULL, NULL, NULL, '73、发汗后，恶寒者，虚故也；不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652825, 'CF89E2C42C8C457791031C4A5713E0E1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6028, 340, 1001016040, NULL, NULL, '茯苓四逆汤', NULL, NULL, NULL, '72、发汗若下之，病仍不解，烦躁者，$f{茯苓四逆汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652826, '131275D5576144F78EB7DA53221E9B95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6029, 340, 1001016039, NULL, NULL, '芍药甘草附子汤', NULL, NULL, NULL, '71、发汗，病不解，反恶寒者，虚故也，$f{芍药甘草附子汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652827, '93F648C01D2BF1949F2AF62CBFE98D24', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6030, 340, 1001016038, NULL, NULL, '茯苓桂枝白术甘草汤', NULL, NULL, NULL, '70、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 621512097652828, 'FC4D25E23C5736C0079BBE045DB6D15A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:19:14', 1, '超级管理员', '2024-12-21 00:14:38');
