INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6137, 342, 1001018046, NULL, NULL, '白虎加人参汤', NULL, NULL, NULL, '230、阳明病，渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498831, '4DF4AD18CB7602F9C2299E7DDD5094E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6138, 342, 1001018045, NULL, NULL, '栀子豉汤', NULL, NULL, NULL, '229、阳明病，脉浮而大，咽燥口苦，腹满而喘，发热汗出，不恶寒，反恶热，身重；若发汗，则躁，心愦愦反谵语；若加温针，必怵惕，烦躁，不得眠；若下之，则胃中空虚，客气动膈，心中懊憹，舌上苔者，$f{栀子豉汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498832, 'B925A253F96DD0420738A6FA178EDA46', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6139, 342, 1001018044, NULL, NULL, '大承气汤', NULL, NULL, NULL, '228、二阳并病，太阳证罢，但发潮热，手足絷絷汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498833, 'E1879E1286EB7171294BC05B9D688EB2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6140, 342, 1001018043, NULL, NULL, '白虎汤,葛根黄连黄芩甘草汤', NULL, NULL, NULL, '227、三阳合病，腹满，身重，难以转侧，口不仁面垢，若发汗则谵语，遗尿，下之，则手足逆冷，额上出汗，若自汗者，宜$f{白虎汤}。自利者，宜$f{葛根黄连黄芩甘草汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498834, 'EC01EB4608DD70A7A5EA2428DB17A8E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6141, 342, 1001018042, NULL, NULL, NULL, NULL, NULL, NULL, '226、伤寒四五日，脉沉而喘满，沉为在里，而反发其汗，津液越出，大便为难，表虚里实，久则谵语。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498835, 'EF7FF37F79EBB5BB69E35EDC8E98081B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6142, 342, 1001018041, NULL, NULL, '大承气汤', NULL, NULL, NULL, '225、阳明病，汗出，谵语者，以有燥屎在胃中，此为实也，须过经乃可下之；下之若早，语言必乱，以表虚里实故也，下之宜$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498836, '9AD457EF9DB99E12322E5894C3C0131A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6143, 342, 1001018040, NULL, NULL, NULL, NULL, NULL, NULL, '224、阳明病，下血，谵语者，此为热入血室，但头汗出者，刺期门，随其实而泻之，濈然汗出则愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498837, '2D63E54BA135321DF1CD53D8C5CB8D56', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6144, 342, 1001018039, NULL, NULL, '大承气汤', NULL, NULL, NULL, '223、阳明病，谵语，有潮热，反不能食者，胃中必有燥屎五六枚也，若能食者，但鞕尔，宜$f{大承气汤}下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498838, 'E2B2E7F005D713C39EEDFA0CABD8C6EB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6145, 342, 1001018038, NULL, NULL, NULL, NULL, NULL, NULL, '222、阳明病，服$n{承气汤}后，不转失气，明日又不大便，脉反微涩者，里虚也，为难治，不可更与$n{承气汤}也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498839, '9DEDE79F90CC7DE500A5919C475E28FE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6146, 342, 1001018037, NULL, NULL, '小承气汤', NULL, NULL, NULL, '221、阳明病，谵语，发热潮，脉滑而疾者，$f{小承气汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 622605143498840, 'FCF968DBAE95B332DB4121EAB4AEE144', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:51', 1, '超级管理员', '2024-12-16 10:05:17');
