INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6560, 354, 1001002923, NULL, NULL, '橘皮枳实生姜汤,茯苓杏仁甘草汤', NULL, NULL, NULL, '6、胸痹，胸中气塞，或短气者，此胸中有水气也，$f{茯苓杏仁甘草汤}主之；$f{橘皮枳实生姜汤}亦主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623639672291403, 'D60C39284AA97FAFA227A03E6B4243C5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:36:21', 1, '超级管理员', '2024-12-17 15:36:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6561, 354, 1001002922, NULL, NULL, '枳实薤白桂枝厚朴括蒌汤,桂枝人参汤', NULL, NULL, NULL, '5、胸痹，心中痞，留气结在胸，胸满，胁下逆抢心者，枳实薤白桂枝厚朴括蒌汤主之；$f{桂枝人参汤}亦主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623639672291404, 'D2FBED1CBB5531885A15041F5088BB60', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:36:21', 1, '超级管理员', '2024-12-17 15:36:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6562, 354, 1001002921, NULL, NULL, '括蒌薤白半夏汤', NULL, NULL, NULL, '4、胸痹不得卧，心痛彻背者，$f{括蒌薤白半夏汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623639672291405, '9122EECC44C78667C0C8F888DB04195D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:36:21', 1, '超级管理员', '2024-12-17 15:36:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6563, 354, 1001002920, NULL, NULL, '括蒌薤白白酒汤', NULL, NULL, NULL, '3、胸痹，喘、息、咳、唾，胸背痛，寸脉沉迟，关上小紧数者，$f{括蒌薤白白酒汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623639672291406, 'A0E4977CFF01B9A4B389FC0EB5A9C2BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:36:21', 1, '超级管理员', '2024-12-17 15:36:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6564, 354, 1001002919, NULL, NULL, NULL, NULL, NULL, NULL, '2、平人无寒热，胸痹，短气不足以息者，实也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623639672291407, '5B0894E4472CEF75A2F317E57A89D989', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:36:21', 1, '超级管理员', '2024-12-17 15:36:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6565, 354, 1001002918, NULL, NULL, NULL, NULL, NULL, NULL, '1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛；所以然者，责其极虚也，今阳虚，知在上焦，胸痹而痛者，以其脉弦故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623639672291408, 'C211C8FBBED7DC79030A8AF7961736D9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:36:21', 1, '超级管理员', '2024-12-17 15:36:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6566, 355, 1001002966, NULL, NULL, '猪膏发煎', NULL, NULL, NULL, '39、胃气下泄，阴吹而喧，如失气者，此谷道实也，$f{猪膏发煎}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857349, 'B58EFFFBE7287ED32AA5DCDC65F5DF34', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6567, 355, 1001002965, NULL, NULL, '狼牙汤', NULL, NULL, NULL, '38、少阴脉滑而数者，阴中疮也，蚀烂者，$f{狼牙汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857350, 'BED1F4F7FF747C9ECF791D5C761DC5C3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6568, 355, 1001002964, NULL, NULL, '蛇床子散', NULL, NULL, NULL, '37、妇人阴寒，$f{蛇床子散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857351, '2FF1D80E032A6FED894F2E4C849DD905', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6569, 355, 1001002963, NULL, NULL, '肾气丸', NULL, NULL, NULL, '36、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？\n\n          师曰：此名转胞，不得溺也，以胞系了戾，故致此病，但利小便则愈，$f{肾气丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857352, '3D5D1E8CB4AD89B1AD06BC2204D65A5C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6570, 355, 1001002962, NULL, NULL, '当归芍药散,小建中汤', NULL, NULL, NULL, '35、妇人腹中诸病痛者，$f{当归芍药散}主之；$f{小建中汤}亦主之；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857353, 'FE7C1C3631DE29946230E370D30D2C91', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6571, 355, 1001002961, NULL, NULL, '红蓝花酒', NULL, NULL, NULL, '34、妇人六十二种风证，腹中气血如刺痛者，$f{红蓝花酒}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857354, '4DBBDA916B6759DD85E1BE69014E4AE1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6572, 355, 1001002960, NULL, NULL, '矾石丸', NULL, NULL, NULL, '33、妇人经水闭，脏坚癖，下白物不止，此中有干血也，$f{矾石丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857355, '7B8CB00022371BE182A69870078B2095', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6573, 355, 1001002959, NULL, NULL, '抵当汤', NULL, NULL, NULL, '32、妇人时腹痛，经水时行时止，止而复行者，$f{抵当汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857356, 'C607520CF7D5BD521FE3858F8CB55329', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6574, 355, 1001002958, NULL, NULL, '大黄甘遂阿胶汤', NULL, NULL, NULL, '31、妇人少腹满，如敦状，小便微难而不渴，或经后产后者，此为水与血俱结在血室也，$f{大黄甘遂阿胶汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857357, '29BB20892EFD60953DF68D975B61F1DD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6575, 355, 1001002957, NULL, NULL, '胶姜汤', NULL, NULL, NULL, '30、妇人陷经，漏下色黑如块者，$f{胶姜汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857358, '1159CB502A9070BE6EBAA25D282FEF4F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6576, 355, 1001002956, NULL, NULL, '黄芪当归汤,旋覆花汤', NULL, NULL, NULL, '29、妇人半产若漏下者，$f{旋覆花汤}主之；脉虚弱者，$f{黄芪当归汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857359, '238C6DA565D2E4320E7188CBF3887BBC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6577, 355, 1001002955, NULL, NULL, '王瓜根散', NULL, NULL, NULL, '28、经水不利，少腹满痛，或一月再经者，$f{王瓜根散}主之。阴肿者，亦主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857360, '64220EFDA95B243E126E6BC2E635D430', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6578, 355, 1001002954, NULL, NULL, '温经汤', NULL, NULL, NULL, '27、问曰：妇人年五十所，病下血数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？\n\n       师曰：此病属带下，何以知之？曾经半产，瘀血在少腹不去，故唇口干燥也，$f{温经汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857361, '1EF6FB8EED1875CD590531D3E3E000E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6579, 355, 1001002953, NULL, NULL, NULL, NULL, NULL, NULL, '26、妇人之病，因虚积冷结，为诸经水断绝，血结胞门。或绕脐疼痛，状如寒疝；或痛在关元，肌若鱼鳞；或阴中掣痛，少腹恶寒；或引腰脊，或下气街；此皆带下。万病一言，察其寒、热、虚、实、紧、弦、行其针药，各探其源，子当辨记，勿谓不然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857362, '828E66DFC03B2E447673BE85FB4C754F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6580, 355, 1001002952, NULL, NULL, '桔梗甘草茯苓泽泻汤,泻心汤', NULL, NULL, NULL, '25、妇人吐涎沫，医反下之，心下即痞，当先治其吐涎沫，后治其痞，治吐宜$f{桔梗甘草茯苓泽泻汤}；治痞宜$f{泻心汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857363, '6868A906AFDDCAEAD90C2CC992CDE82C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6581, 355, 1001002951, NULL, NULL, '甘草小麦大枣汤', NULL, NULL, NULL, '24、妇人脏燥，悲伤欲哭，数欠伸，象如神灵所作者，$f{甘草小麦大枣汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857364, '7EC43A93D800DB5B0184C493D271402F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6582, 355, 1001002950, NULL, NULL, '半夏厚朴茯苓生姜汤', NULL, NULL, NULL, '23、妇人咽中如有炙脔者，$f{半夏厚朴茯苓生姜汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857365, '05B31CB7F0B15F73F6326C872EC2DE61', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6583, 355, 1001002949, NULL, NULL, '白头翁加甘草阿胶汤', NULL, NULL, NULL, '22、产后下利，脉虚极者，$f{白头翁加甘草阿胶汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857366, '6311FBF3E222378C9EF517460C7E5E75', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6584, 355, 1001002948, NULL, NULL, '竹皮大丸', NULL, NULL, NULL, '21、产后烦乱，呕逆，无外证者，此乳中虚也，$f{竹皮大丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857367, 'FDF70756A2A7443989F0EB42DFA753A0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6585, 355, 1001002947, NULL, NULL, '竹叶汤', NULL, NULL, NULL, '20、产后中风，发热，面赤，头痛，汗出而喘，脉弦数者，$f{竹叶汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857368, '8476AB59CF3C7C191D76F474DC94A04C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6586, 355, 1001002946, NULL, NULL, '小柴胡汤', NULL, NULL, NULL, '19、产后中风，数十日不解，头痛，恶寒，发热，心下满，干呕，续自微汗出，$f{小柴胡汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857369, '2ACC08F611EBE7C59A3AB67322975459', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6587, 355, 1001002945, NULL, NULL, '大承气汤', NULL, NULL, NULL, '18、产后七八日，无太阳证，少腹坚痛，此恶露不尽也；若不大便，烦躁，发热，脉微实者，宜和之；若日晡所烦躁，食则谵语，至夜即愈者，$f{大承气汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857370, '721F60B1823ABC4732C866F4026623B2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6588, 355, 1001002944, NULL, NULL, '枳实芍药散,下瘀血汤', NULL, NULL, NULL, '17、师曰：产后腹痛，法当以$f{枳实芍药散}；假令不愈，必腹中有瘀血着脐下也，$f{下瘀血汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857371, 'CAD2D06EB32BB0C85DAE39F1B9D79325', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6589, 355, 1001002943, NULL, NULL, '枳实芍药散', NULL, NULL, NULL, '16、产后腹痛，烦满不得卧，不可下也，宜$f{枳实芍药散}和之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857372, '3D51251707EA4881157117B13252C748', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6590, 355, 1001002942, NULL, NULL, '当归生姜羊肉汤', NULL, NULL, NULL, '15、产后腹中疞痛，若虚寒不足者，$f{当归生姜羊肉汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857373, 'CA4EB96485500160EAEF453C0DE7935D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6591, 355, 1001002941, NULL, NULL, '大承气汤', NULL, NULL, NULL, '14、郁冒病解，能食，七八日更发热者，此为胃实，$f{大承气汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857374, '00462E3A1C9B92B1C9B7A260C60FE7EF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6592, 355, 1001002940, NULL, NULL, '小柴胡汤', NULL, NULL, NULL, '13、产妇郁冒，其脉微弱，呕不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥则必冒，冒家欲解，必大汗出；以血虚下厥，孤阳上出，故头汗出也。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复；大便坚，呕不能食者，$f{小柴胡汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857375, '73D7037BD8209D8B04F146A8CEF8EB3B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6593, 355, 1001002939, NULL, NULL, NULL, NULL, NULL, NULL, '12、问曰：新产妇人有三病，一者病痉，二者郁冒，三者大便难，何谓也？\n\n         师曰：新产血虚多汗出，喜中风，故令病痉；亡血，复汗，寒多，故令郁冒；亡津液胃燥，故大便难。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857376, 'C8A93148B7F8DF64A7F093FB1C02ED02', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6594, 355, 1001002938, NULL, NULL, '白术散', NULL, NULL, NULL, '10、妊娠，身有寒湿，或腹痛，或心烦，心痛，不能饮食，其胎跃跃动者，宜养之，$f{白术散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857377, 'DCFB9317465976A406226F5AB70214FF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6595, 355, 1001002937, NULL, NULL, '当归散', NULL, NULL, NULL, '9、妇人妊娠，身无他病，宜常服$f{当归散}，则临产不难，产后亦免生他病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857378, '5DBB526B9614A4EA1A877207D213064D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6596, 355, 1001002936, NULL, NULL, '葵子茯苓散', NULL, NULL, NULL, '8、妊娠，有水气，小便不利，洒淅恶寒，起即头眩，$f{葵子茯苓散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857379, '4BAA1EFE2B13BEEC3EECF431EC228E1C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6597, 355, 1001002935, NULL, NULL, '当归贝母苦参丸', NULL, NULL, NULL, '7、妊娠，小便难，饮食如故，$f{当归贝母苦参丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857380, '671392407F6A5E68C56EB89A641CDF08', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6598, 355, 1001002934, NULL, NULL, '干姜人参半夏丸', NULL, NULL, NULL, '6、妊娠，呕吐不止，$f{干姜人参半夏丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857381, '97023F74A0D747DB49EE460D12264C27', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:28', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6599, 355, 1001002933, NULL, NULL, '当归芍药散', NULL, NULL, NULL, '5、妇人怀妊，腹中疞痛，$f{当归芍药散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857382, 'B7F5F7B916198B7B479125DFCF13AE48', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:29', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6600, 355, 1001002932, NULL, NULL, '胶艾汤', NULL, NULL, NULL, '4、师曰：妇人有漏下者；有半产后续下血都不绝者；假令妊娠腹中痛者，此为胞阻，$f{胶艾汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857383, '76698345DAD7ACE94EC758581002D6DE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:29', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6601, 355, 1001002931, NULL, NULL, '附子汤', NULL, NULL, NULL, '3、妇人怀孕六七月，脉弦，发热，其胎愈胀，腹痛，恶寒，少腹如扇，所以然者，子藏开故也，当以$f{附子汤}温之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857384, '0EB8DF8FE89D6B51F2726724C480CA69', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:29', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6602, 355, 1001002930, NULL, NULL, '桂枝茯苓丸', NULL, NULL, NULL, '2、妇人宿有症病，经断未及三月，而得漏下不止，胎动在脐上者，此为症痼害；妊娠六月动者，前三月经水利时胎也；下血者，断后三月衄也；所以血不止者，其症不去故也，当下其症，$f{桂枝茯苓丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623661573857385, '4C269F2C7C07B11CB56628C2775AE16B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:05:29', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6610, 355, 1001002929, NULL, NULL, '桂枝汤', NULL, NULL, NULL, '1、师曰：妇人得平脉，阴脉小弱，其人呕，不能食，无寒热，此为妊娠，$f{桂枝汤}主之；于法六十日当有此证；设有医治逆者，却一月；加吐下者，则绝之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 623664023437381, '15AFB3E5DAB7686E1BEE6B3B1310572F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:15:26', 1, '超级管理员', '2024-12-17 17:16:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6611, 356, 400100101, NULL, NULL, NULL, NULL, NULL, NULL, '      药性之道，具在本草。虽代有哲匠，演其奥义，然去古弥远，寖失其旨。予以绵质，性复疏戆，本不堪尘俗。年方弱冠，直门户衰冷，世累纠缠。以是多见愤激，碍膺之事，十常八九。自兹数婴疾病，於是检讨《图经》，求其本意。积累既久，恍焉有会心处，辄札记之。历三十馀年，遂成此《疏》。学士大夫见而奇之，欲予付诸梓人，予未之许也。予以昔人尝云：“切忌说破，恐塞断后学悟门”，将兹是咎。外孙毛凤苞文学曰：“不然，世间上根人少，中下人多。设使上根人出，自得无师智获，睹此书当不言而喻，默默相契；下根人读之，如盲人谭五色，总不能别；惟中人已上之资，得窥其概，则所得多矣。其为利济，宁有量耶！请亟登梓，以拯夭枉。”予曰：“善”。且曰：“舅祖许可，凤苞愿力任其役。”乃悉检《疏》稿付之。即集予同里门人李枝，通家子云间康元浤，松陵顾澄先二文学，并其舅氏隐沦戈汕辈董督校雠，早夜孜孜，惟恐或后，其用意可谓勤矣！志存及物，有君子之嗜尚焉，良足多也。予年已髦，倘书成而得早行於世，亦足以副海内求明斯道者之企望也。　\n　\n            时天启乙丑暮春海虞遗民缪希雍题于吴江舟次　　\n\n      吴兴晚学姚凝之书　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624728014614597, 'EB40F44AAB8118A822798B5E403834AE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-20 09:24:50', 1, '超级管理员', '2024-12-20 09:27:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6612, 357, 400100201, NULL, NULL, NULL, NULL, NULL, NULL, '       《神农本草经》者，古“三坟”之一也。其成於黄帝之世乎？观其尝药别味，对病主治，施之百世，无可逾越。其为开天大圣，悯生民疾苦，於饮食衣服之外，复设针石药物，用拯夭札，俾得尽其天年。是已原夫药之生也，气禀乎天，味成乎地，性在其间。气为阳，味为阴，五味四气，各归其类，斯亲上、亲下之义也。既述之以本性，又制之以君臣，合之以佐使，以成其攻邪已疾之能。遂使无情之用，同诸有识，自非生而神灵、冥契万物者，其孰能与於斯乎！去古滋远，民性滋漓，心识粗浮，莫能研精殚思，深入玄要，而不察乎即象即理，物物昭然，弭疾延年，功力自著。正以“三坟”之书，言大道也，言其然而不言其所以然。言亦象也。予因据经以疏义，缘义以致用，参互以尽其长，简误以防其失；而复详列病忌药忌；以别其微；条析诸药，应病分门，以究其用；刊定七方十剂，以定其法；阐发五藏苦欲补泻，以畅其神。著论三十馀首，以通古今之变。始悉一经之趣，命之曰《神农本草经疏》。读之者宜因疏以通经，因经以契往，俾炎黄之旨，晦而复明，药物之生，利而罔害，乃余述疏意也。余生也晚，亲年已衰，得于禀者固薄，故少善病。长嗜方伎，僻耽药妙，顾念自昔仙人道士，靡不悉由药道以济群生。加之友生协赞，后先不一。驯届耳顺，良友凋丧，百念灰冷。惟兹一事，尚用婴怀，手所论著，裒然成帙。倘典则可师，幽隐可显，试用于世，有广来学，固所愿也，不敢必也。采真同好，其相证诸？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624728848306245, '7D44DFCCD4BB0DD0A9E3E1A728ADCC72', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-20 09:28:14', 1, '超级管理员', '2024-12-20 09:28:13');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6613, 358, 400100301, NULL, NULL, NULL, NULL, NULL, NULL, '一、《本经》为“三坟”之书，后增入《名医别录》，有朱字、墨字之分，总言药之主治，从未有发其所以然者。兹《疏》直接神圣立言之旨，故总题之曰《神农本草经疏》。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624730599145541, '89AB65D63FA8CB19F0425777310688F4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-20 09:35:21', 1, '超级管理员', '2024-12-21 09:02:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6614, 358, 400100313, NULL, NULL, NULL, NULL, NULL, NULL, '       先生殚一生精力，发千古神圣之奥，以利万世。门人李季虬氏，几经参录，悉以付新安吴康虞氏刻之金陵，未竟而遗焉。流传於知交者，西吴朱氏集而刻之，不及其半，然且序次弗伦，考核未审也。先生以医为司命，一字有讹，遗祸无极。遂命澄先检其存稿若干卷，按部选类，汇得全帙；细复检阅，以为定本。\n\n      凡 “续序例” 二卷，药四百九十味，用识年月，书此凡例云。\n\n      时天启五年岁在乙丑六月十有一日松陵通家子顾澄先谨识。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341061, '8C4C842B33E9AEEB8B27384B22B584CD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6615, 358, 400100312, NULL, NULL, NULL, NULL, NULL, NULL, '一、“续序例” 下卷，倶系病药忌宜。今总列应忌诸药於前，以见必不可轻用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341062, '86F677423214BB2C406AC482E0BDD1E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6616, 358, 400100311, NULL, NULL, NULL, NULL, NULL, NULL, '一、本文顶行立款。其附入之条，有正文者仍从顶行；原系附入者，低字加圈，以别正文。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341063, '4E4829E70F306E5B871E8A6B1C5940D2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6617, 358, 400100310, NULL, NULL, NULL, NULL, NULL, NULL, '一、《证类本草》第三十卷，倶载有名未用之药。今有常用之物，而本经未载；有《拾遗》载之而未详者，兹列为三十卷 “补遗”。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341064, '1ACDD3DB23595E6FB0A7A117FE973361', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6618, 358, 400100309, NULL, NULL, NULL, NULL, NULL, NULL, '一、本文悉遵《证类》善本。但是书流传已久，字画谬讹颇多，兹逐条参订。有一二意义难通者，稍为厘正，如 “伤” 作 “疡”，“动” 作 “痛” 之类。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341065, '4980464DBDEEC8F9D26398FA1CF5BD19', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6619, 358, 400100308, NULL, NULL, NULL, NULL, NULL, NULL, '一、目录次序，悉从《证类本草》，有部分混杂，如木部之藿香，菜部之假苏，今为移正。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341066, '99247604942217FC9FE32BD9791D3F1C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6620, 358, 400100307, NULL, NULL, NULL, NULL, NULL, NULL, '一 “简误” 以防误用之失，故有证同而药不宜同者，每条后详书其害。至於性淳功良，有益无损，一药只堪治一病者，悉不复著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341067, '3DAA32F6AD55300EFC64559725633662', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6621, 358, 400100306, NULL, NULL, NULL, NULL, NULL, NULL, '一、《证类本草》所载诸方，倶录入 “【主治参与】”，有未当於用者，已为删去。其外诸书所录良方甚多，必详纪述，以便采取。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341068, 'DF13ED551036F5EEBE807248DAD12B0C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6622, 358, 400100305, NULL, NULL, NULL, NULL, NULL, NULL, '一、畏忌制使，物性自然，非可以意求者，俱照本经，列之条下。至其制用之宜，古法倶在。兹复采入，俾得遵守。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341069, '094EDB2C711AC6808138C47A61F9F8AF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6623, 358, 400100304, NULL, NULL, NULL, NULL, NULL, NULL, '一、种类随土异形，甚且称名未核。矧近来市肆，饰伪似真。若令误服，遗害非浅。故详辩种类，以正其讹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341070, 'DB61F5C70A405B64CAC69D91D1CC51A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6624, 358, 400100303, NULL, NULL, NULL, NULL, NULL, NULL, '一、药类一千二百馀种，品类浩繁，今简治疗之必不可缺，暨近地所产，得於睹记者，备为具疏。馀非必用之药，及罕识难致者，存而不论。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341071, 'E2EDAEABA64923A2772B028ACECF24A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6625, 358, 400100302, NULL, NULL, NULL, NULL, NULL, NULL, '一、药物治疗，《本经》、《别录》业已备悉。间有未尽者，参之以各名家主治，故小字附列於经文之下，或即于疏内叙述，俾采用易稽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624958512341072, 'AC6E92F5C84498CB97A61358038BD35F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:02:44', 1, '超级管理员', '2024-12-21 09:02:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6626, 359, 400100401, NULL, NULL, NULL, NULL, NULL, NULL, '         予之作是《疏》也，赅括经文，义难概述；求其宗趣，宜有裁节。是以或先经而阐义，或随文而畅旨，或断章以相比，或因源以导流，或从末而会本，或根性以知非。凡兹数者，期在发明经旨，适当於用。然惧偏见多遗，难为准的，必欲使纤悉洞了，小大靡遗。开扩来学，臻乎无惑，尚有望于明哲之助焉。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624964668272710, 'E5ED72F56201BFCFEA8810AF7F8EEAF1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:27:47', 1, '超级管理员', '2024-12-21 09:30:08');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6627, 360, 400100501, NULL, NULL, NULL, NULL, NULL, NULL, '        夫物之生也，必禀乎天。其成也，必资乎地。\n\n       天布令，主发生，$m{寒、热、温、凉}，四时之气行焉，阳也；地凝质，主成物，$n{酸、苦、辛、咸、甘、淡}，五行之味滋焉，阴也。\n\n       故知微寒微温者，春之气也；大温热者，夏之气也；大热者，长夏之气也；凉者，秋之气也；大寒者，冬之气也。\n\n      凡言微寒者，禀春之气以生，春气升而生；言$m{温热}者，盛夏之气以生，夏气散而长；言$m{大热}者，感长夏之气以生，长夏之气软而化；言$m{平}者，感秋之气以生，$m{平}即$m{凉}也，秋气降而收；言$m{大寒}者，感冬之气以生，冬气沉而$m{藏}。此物之气得乎天者也。\n \n      天一生水，地六成之。地二生火，天七成之。天三生木，地八成之。地四生金，天九成之。天五生土，地十成之。\n\n      水曰润下，润下作$n{咸}。火曰炎上，炎上作$n{苦}。 木曰曲直，曲直作$n{酸}。金曰从革，从革作$n{辛}。  土爰稼穑，稼穑作$n{甘}。本乎天者亲上，本乎地者亲下。气味多少，各从其类也。\n\n      凡言$n{酸}者，得木之气；言$n{辛}者，得金之气；言$n{咸}者，得水之气；言$n{苦}者，得火之气；言$n{甘}者，得土之气。\n\n      惟土也，寄旺於四季。生成之数皆五，故其气平，其味甘而淡，其性和而无毒。土德冲和，感而类之，莫或不然。固万物之所出，亦万物之所入乎？此物之味，资乎地者也。　　\n\n      气之毒者必$m{热}，味之毒者必$n{辛}。炎黄言味而不加气性者何也？盖古文尚简，故只言味。物有味，必有气，有气斯有性，自然之道也。气味生成，原本乎是。知其所自，则思过半矣。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624965203685446, 'FC4A9F1B62D0B937ABE06A4305B31BA8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:29:57', 1, 'admin', '2025-01-13 11:35:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6628, 361, 400100601, NULL, NULL, NULL, NULL, NULL, NULL, '         今夫病，譬诸兵焉。料敌出奇者，将之谋也；破军杀贼者，士之力也。\n\n        审度病机者，医之智也；攻邪伐病者，药之能也。非士无以破敌，非药无以攻邪。故良将养士，上医蓄药。然不知士，何以养？不知药，何以蓄？夫士犹有情实可考，才略可试，尚曰难知。\n\n        以孔明之明，一马谡用违其才，卒致败衄，悔不可追，况乎药石无情，才性莫测，既非言论之可考，又非拟议之可及，而欲知其的然不谬，非神圣之智，其孰能与於斯？ 假令尝试漫为，则下咽不返，死生立判，顾不大可惧耶！\n \n      上古之人，病生於$n{六淫者多}，发于$m{七情者寡}。故其主治，尝以一药治一病，或一药治数病。今时则不然：$n{七情弥厚，五欲弥深，精气既亏，六淫易入}。$m{内外胶固，病情殊古}：则$n{须合众药之所长，而又善护其所短，乃能苏凋瘵而起沉疴，其在良医善知药性}，剂量无差，庶得参互旁通，彼此兼济，以尽其才，而无乖刺败坏之弊矣。故作“【主治参与】”，俾后之医师循而求之，共收平定之功，期无夭枉之患，斯作《疏》意也。昔人云：“用医如用兵。”旨哉言乎！旨哉言乎！　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624965914665030, '235214137B27BC18363D45922D992CD4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:32:51', 1, 'admin', '2025-01-13 11:20:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6629, 362, 400100701, NULL, NULL, NULL, NULL, NULL, NULL, '       夫$x{药石}禀$m{天地偏至之气者也}。$n{虽醇和浓懿}，号称$m{上药}，然所禀既$x{偏}，所至必$x{独}。脱也用违其性之宜，则偏重之害，势所必至。\n\n       故凡有益于$x{阳虚者}，必$x{不利乎阴}；有益于$x{阴虚者}，必$x{不利乎阳}。\n\n       能治$x{燥者}，必不宜于$x{湿}；\n\n       能治$x{湿者}，必不宜于$x{燥}。\n\n      能破$x{散者}，不可以$x{治虚}；\n\n      能收$x{敛者}，不可以治实。\n\n      $x{升}，不可以$x{止升}；\n   \n      $x{降}，不可以$x{疗降}。\n\n     $x{寒}有时而不宜于$x{热}，$x{热}有时而不宜于$x{寒}。\n\n     古人$u{半夏}有三禁，谓渴家、汗家、血家。\n\n     仲景呕家忌$x{甘}，酒家亦忌$x{甘}。王好古论$x{肺热}忌$u{人参}之属。\n\n     诸如此类，莫可胜数。苟昧斯旨，吉凶贸焉。人命至重，冥报难逃，医为司命，其可不深思详察也哉！此与“十剂”互证。“十剂”对治，$x{反}则为$m{误}，故作“简误”以防其失。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624966125056069, '86D268095FBD355C914F85B234A71EC2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:33:42', 1, 'admin', '2025-01-11 14:14:29');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6630, 363, 400100809, NULL, NULL, NULL, NULL, NULL, NULL, '$m{复方}　　\n        岐伯曰：奇之不去则偶之，是谓重方。好古曰：奇之不去复以偶，偶之不去复以奇，故曰复。复者，再也，重也。所谓十补一泄，数泄一补也。又伤寒见风脉，伤风得寒脉，为脉证不相应，宜以复方主之。从正曰：复方有三。有二方、三方及数方相合之复方，如桂枝二越婢一汤、五积散之属是也。有本方之外、别加馀药，如调胃承气加连翘、薄荷、黄芩、栀子为凉膈散之属是也。有分两均齐之复方，如胃风汤各等分之属是也。王太仆以偶为复方，今七方有偶又有复，岂非偶乃二方相合，复乃数方相合之谓乎？　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125126, '6DB95C1C48F30914B67A81EBE69893AD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6631, 363, 400100808, NULL, NULL, NULL, NULL, NULL, NULL, '$m{偶方}　　\n        从正曰：偶方有三：有两味相配之偶方，有古之二方相合之偶方，古谓之复方，皆病在下而远者宜之。有药合阴数二、四、六、八、十之偶方，宜汗不宜下。王太仆言汗药不以偶，则气不足以外发；下药不以奇，则药毒攻而致过。意者下本迅利，故单行则力专，专则直下、不旁及而速；汗或难出，故并行则物众而力微乎？乃仲景制方，桂枝汗药，反以三味为奇；大承气下药，反以四味为偶，何也？岂汗下缓急，在力之大小，而不以数之奇偶为重乎？　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125127, '13FB3ED95AE777C721B588D854361552', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6632, 363, 400100807, NULL, NULL, NULL, NULL, NULL, NULL, '$m{奇方}　　\n        王冰曰：单方也。从正曰：奇方有二：有独用一物之奇方，病在下而近者宜之。有药合阳数一、三、五、七、九之奇方，宜下不宜汗。完素曰：假如小承气，奇之小方也；大承气、抵当汤，奇之大方也，所谓因其攻下而为之也。桂枝、麻黄、偶之小方也；葛根、青龙，偶之大方也，所谓因其发散而用之也。故曰：汗不以奇，下不以偶。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125128, '82F43C5F989E429E1BE9B6CED9192453', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6633, 363, 400100806, NULL, NULL, NULL, NULL, NULL, NULL, '$m{急方}　　\n        完素曰：味厚者为阴，味薄者为阴中之阳，故味厚则下泄，味薄则通气；气厚者为阳，气薄者为阳中之阴，故气厚则发热，气薄则发汗是也。好古曰：治主宜缓，缓则治其本也；治客宜急，急则治其标也。表里汗下，皆有所当缓、所当急。从正曰：急方有四：有急病急攻之急方，中风、关格之病是也。有汤散荡涤之急方，下咽易散而行速也。有毒药之急方，毒性能上涌下泄以夺病势也。有气味俱厚之急方，气味俱厚，直趋于下而力不衰也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125129, '3FB265D5615EB31325806868B550C5DB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6634, 363, 400100805, NULL, NULL, NULL, NULL, NULL, NULL, '$m{缓方}　　\n        岐伯曰：补上治上制以缓，补下治下制以急。急则气味厚，缓则气味薄，适其至所，此之谓也。病所远而中道气味之者，食而过之，无越其制度也。王冰曰：假如病在肾而心气不足，服药宜急过之，不以气味饲心，肾药凌心，心复益散矣。馀上下远近例同。完素曰：圣人治上不犯下，治下不犯上，治中上下俱无犯。故曰：诛伐无过，命曰大惑。好古曰：治上必妨下，治表必违里。用黄芩以治肺必妨脾，用苁蓉以治肾必妨心，用干姜以治中必僭上，服附子以补火必涸水。从正曰：缓方有五：有甘以缓之之方，甘草、糖、蜜之属是也，病在胸膈，取其留恋也；有丸以缓之之方，比之汤散，其行迟慢也；有品件众多之缓方，药众则递相拘制，不得各骋其性也；有无毒治病之缓方，无毒则性纯功缓也；有气味俱薄之缓方，气味薄则长于补上治上，比至其下，药力已衰矣。　　\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125130, '4712EC74A92476CA2FFCC19C5DF64532', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6635, 363, 400100804, NULL, NULL, NULL, NULL, NULL, NULL, '$m{小方}　　\n          从正曰：小方有二：有君一、臣二之小方，病无兼证，邪气专一，可一二味治者宜之；有分两少而频服之小方，心肺及在上之病者宜之，徐徐细呷是也。完素曰：肝肾位远，数多则其气缓，不能速达于下，必大剂而数少，取其迅急下走也。心肺位近，数少则其气急下走，不能升发于上，必小剂而数多，取其易散而上行也。王氏所谓肺服九，心服七，脾服五，肝服三，肾服一，乃五脏生成之数也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125131, 'A2E97FE4C5BE682943DB4197EFF486BF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6636, 363, 400100803, NULL, NULL, NULL, NULL, NULL, NULL, '$m{大方}　　\n       岐伯曰：君一、臣三、佐九，制之大也；君一、臣三、佐五，制之中也；君一、臣二，制之小也。又曰：远而奇偶，制大其服；近而偶奇，制小其服。大则数少，小则数多。多则九之，小则二之。完素曰：身表为远，身里为近。大小者，制奇偶之法也。假如小承气汤、调胃承气汤，奇之小方也；大承气汤、抵当汤，奇之大方也，所谓因其攻里而用之也。桂枝、麻黄，偶之小方也；葛根、青龙，偶之大方也，所谓因其发表而用之也。故曰：汗不以奇，下不以偶。张从正曰：大方有二：有君一、臣三、佐九之大方，病有兼证而邪不一，不可以一二味治者宜之；有分两大而顿服之大方，肝肾及下部之病道远者宜之。王太仆以心肺为近，肾肝为远，脾胃为中。刘河间以身表为远，身里为近。以予观之，身半以上其气三，天之分也。身半以下其气三，地之分也。中脘，人之分也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125132, '8C55CF6A9DD66511CF303C7A7BD8E1B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6637, 363, 400100802, NULL, NULL, NULL, NULL, NULL, NULL, '附录：七方　　\n\n       岐伯曰：气有多少，形有盛衰。治有缓急，方有大小。又曰：病有远近，证有中外，治有轻重。近者偶之，远者奇之。汗不以奇，下不以偶。补上治上制以缓，补下治下制以急。近而偶奇，制小其服；远而奇偶，制大其服。大则数小，小则数多。多则九之，少则一之。奇之不去则偶之，偶之不去则反佐以取之。所谓寒热温凉，反从其病也。　　\n\n       王冰曰：脏位有高下，腑气有远近。病证有表里，药用有轻重。单方为奇，复方为偶。心肺为近，肝肾为远，脾胃居中。肠、膀、胞、胆，亦有远近。识见高远，权以合宜。方奇而分两偶，方偶而分两奇。近而偶制，多数服之；远而奇制，少数服之。则肺服九，心服七，脾服五，肝服三，肾服一，为常制也，方与其重也宁轻，与其毒也宁良，与其大也宁小。是以奇方不去，偶方主之；偶方不去，则反佐以同病之气而取之。夫微小之热，折之以寒；微小之冷，消之以热。其大寒热，则必能与异气相格，声不同不相应，气不同不相合。是以反其佐，以同其气，夏令寒热参合，使其始同终异也。　\n　\n       逆者正治，从者反治。反佐，即从治也。谓热在下而上有寒邪拒格，则寒药中入热药为佐。下膈之后，热气既散，寒性随发也。寒在下而上有浮火拒格，则热药中入寒药为佐。下膈之后，寒气既消，热性随发也。此寒因热用，热因寒用之妙也。温冷仿此。　\n　\n      完素曰：流变在乎病，主病在乎方，制方在乎人。方有七：大、小、缓、急、奇、偶、复也。制方之体，本於气味。寒、热、温、凉，四气生於天；酸、苦、辛、咸、甘、淡，六味成於地。是以有形为味，无形为气。气为阳，味为阴。辛甘发散为阳，酸苦涌泄为阴。咸味涌泄为阴，淡味渗泄为阳。或收或散，或缓或急，或燥或润，或软或坚，各随脏腑之证。而施药之品味，乃分七方之制也。故奇、偶、复，三方也，大、小、缓、急，四制之法也。故曰：治有缓急，方有大小。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125133, '8F3CC89C32009F2F5B8AA003680EC9A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6638, 363, 400100801, NULL, NULL, NULL, NULL, NULL, NULL, '         夫方者，法也。法乃所以制物者也。故$x{大}、$x{小}、$x{缓}、$x{急}、$x{奇}、$x{偶}、$x{复}七者，为法制之变且尽也。\n\n       七方不同，同归已疾。其制各异，异以从宜。\n\n       岐伯言之已详，后人演之弥悉，凡制方者必本乎是。\n\n      $y{苟悖其制，则非法矣}。非法则不能所施合辙，而反致$m{乖刺}，恶在其能攻邪已疾耶！　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967342125134, 'EA06C04AD71E3B777C5034F14E4875A7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:38:40', 1, 'admin', '2025-01-11 14:30:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6639, 364, 400100901, NULL, NULL, NULL, NULL, NULL, NULL, '        剂者，从齐从刀，用以齐其不齐，而成其所以齐也。\n\n       夫独用之谓药，合用之谓剂，而其才有长短、大小、良毒之难齐，故用有$x{相益}、$x{相济}、$x{相畏}、$x{相恶}、$x{相忌}、$x{相制}之不同，则剂有$x{宣}、$x{通}、$x{补}、$x{泻}、$x{轻}、$x{重}、$x{滑}、$x{涩}、$x{燥}、$x{湿}十者对治之各异。\n\n       譬夫良相剂量群才，以成治世之功，类良医剂量群药，以成治病之功，其义一也。岐伯论之详矣！凡和剂者必本乎是。苟昧其旨而违其道，即失对治之义，求疾之瘳，其可得乎！　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624967769210950, '7907CFB06A793D4A11F9F1CE11DE02B2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:40:24', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6640, 364, 400100912, NULL, NULL, NULL, NULL, NULL, NULL, '湿剂　　\n            之才曰：湿可去枯，白石英、紫石英之属是也。从正曰：湿者，润湿也。虽与滑类，少有不同。《经》云：辛以润之。辛能走气、能化液故也。盐、硝味虽咸，属真阴之水，诚濡枯之上药也。人有枯涸皴揭之病，非独金化，盖有火以乘之，故非湿剂不能愈。完素曰：津耗为枯，五脏痿弱，荣卫涸涩，必湿剂以润之。好古曰：有减气而枯，有减血而枯。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744581, '6AE5EDAC88D9AAC247A62EA4ED92EBC7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6641, 364, 400100911, NULL, NULL, NULL, NULL, NULL, NULL, '燥剂　　\n         之才曰：燥可去湿，桑白皮、赤小豆之属是也。完素曰：湿气淫胜，肿满脾湿，必燥剂以除之，桑皮之属。湿胜于上，以苦吐之，以淡渗之是也。从正曰：积寒久冷，吐利腥秽，上下所出水液澄彻清冷，此大寒之病，宜姜、附、胡椒辈以燥之。若病湿气，则陈皮、白术、木香、苍术之属除之，亦燥剂也。而黄连、黄檗、栀子、大黄，其味皆苦，苦属火化，皆能燥湿，此《内经》之本旨也，岂独二术之类为燥剂乎？好古曰：湿有在上、在中、在下、在经、在皮、在里。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744582, 'A23E772A2B7C593048EA8113FB83699F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6642, 364, 400100910, NULL, NULL, NULL, NULL, NULL, NULL, '涩剂　　\n         之才曰：涩可去脱，牡蛎、龙骨之属是也。完素曰：滑则气脱，如开肠洞泄，便溺遗失之类，必涩剂以收敛之。从正曰：寝汗不禁，涩以牡蛎、五味、五倍之属。滑泄不已，涩以肉豆蔻、诃黎勒、没食子、亚芙蓉、龙骨之属。凡酸味同乎涩者，收敛之义也。然此种皆宜先攻其本，而后收之可也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744583, '691ACFD48EB467206EE17C01B22993BF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6643, 364, 400100909, NULL, NULL, NULL, NULL, NULL, NULL, '滑剂　　\n         之才曰：滑可去着，冬葵子、榆白皮之属是也。完素曰：涩则气着，必滑剂以利之。滑能养窍，故润利也。从正曰：大便燥结，宜麻仁、郁李之类；小便癃闭，宜葵子、滑石之类。前后不通，两阴俱闭也，名曰三焦约。约者，束也。宜先以滑剂润养其燥，然后攻之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744584, 'D3A8F8D3A5B7B85AB9AC1AA8FEB2BAC9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6644, 364, 400100908, NULL, NULL, NULL, NULL, NULL, NULL, '重剂　　\n           之才曰：重可去怯，磁石、铁粉之属是也。从正曰：重者，镇坠之谓也。怯则气浮，如丧神失守，而惊悸气上。朱砂、水银、沉香、黄丹、寒水石之伦，皆镇重也。久病咳嗽，涎潮于上，形羸不可攻者，以此坠之。《经》曰：重者因而减之，贵其渐也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744585, '5B4512E3ABB2AECB52198D9124536562', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6645, 364, 400100907, NULL, NULL, NULL, NULL, NULL, NULL, '轻剂　　\n         之才曰：轻可去实，麻黄、葛根之属是也。从正曰：风寒之邪，始客皮肤，头痛身热，宜解其表，《内经》所谓轻而扬之也。痈疮疥痤，俱宜解表。汗以泄之，毒以熏之，皆轻剂也。凡熏、洗、蒸、灸、熨、烙、刺、砭、导引、按摩，皆汗法也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744586, '66C1B7CEFF43FED96E0B1E3A77C0948C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6646, 364, 400100906, NULL, NULL, NULL, NULL, NULL, NULL, '泻剂　　\n            之才曰：泄可去闭，葶苈、大黄之属是也。杲曰：葶苈苦寒，气味俱厚，不减大黄，能泄肺中之闭，又泄大肠。大黄走而不守，能泄血闭、肠胃渣秽之物。一泄气闭利小便，一泄血闭利大便。凡与二药同者皆然。从正曰：实则泄之。诸痛为实，痛随利减。芒硝、大黄、牵牛、甘遂、巴豆之属，皆泻剂也。其催生下乳，磨积逐水，破经泄气，凡下行者，皆下法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744587, '0891901E96A56A8DC133C5CE99FBD8B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6647, 364, 400100905, NULL, NULL, NULL, NULL, NULL, NULL, '补剂　　\n         之才曰：补可去弱，人参、羊肉之属是也。杲曰：人参甘温，能补气虚；羊肉甘热，能补血虚。羊肉补形，人参补气。凡气味与二药同者皆是也。从正曰：五脏各有补泻，五味各补其脏，有表虚、里虚、上虚、下虚、阴虚、阳虚、气虚、血虚。《经》曰：精不足者补之以味，形不足者温之以气。五谷、五菜、五果、五肉，皆补养之物也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744588, 'D3192AF3397E38A003868B35CF02F661', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6648, 364, 400100904, NULL, NULL, NULL, NULL, NULL, NULL, '通剂　　\n         之才曰：通可去滞，通草、防己之属是也。完素曰：留而不行，必通以行之。如水病为痰澼之类，以木通、防己之属攻其内，则留者行也。滑石、茯苓、芫花、甘遂、大戟、牵牛之类是也。从正曰：通者，流通也。前后不得溲便，宜木通、海金沙、琥珀、大黄之属通之。痹病郁滞，经隧不利，亦宜通之。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744589, '4CB9971F8D9D6ABFF61B4F76BB17E53E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6649, 364, 400100903, NULL, NULL, NULL, NULL, NULL, NULL, '宣剂　　\n        之才曰：宣可去壅，生姜、橘皮之属是也。杲曰：外感六淫之邪，欲传入里，三阴实而不受，逆于胸中，天分气分窒塞不通，而或哕或呕，所谓壅也。三阴者，脾也。故必破气，药如姜、橘、藿香、半夏之类，泻其壅塞。从正曰：俚人以宣为泻，又以宣为通，不知十剂之中，已有泻矣。仲景曰：春病在头，大法宜吐，是宣剂即涌剂也。经曰：高者因而越之，木郁则达之。宣者，升而上也，以君召臣曰宣是矣。凡风痫、中风、胸中诸实，痰饮寒结，胸中热郁，上而不下，久则喘嗽满胀，水肿之病生焉，非宣剂莫能愈也。吐中有汗，如引涎、追泪、嚏鼻，凡上行者，皆吐法也。完素曰：郁而不散为壅，必宣以散之，如痞满不通之类是矣。攻其里，则宣者上也，泄者下也。涌剂则瓜蒂、栀子之属是矣。发汗解表亦同。好古曰：《经》有五郁，木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之。皆宣也。教曰：宣，扬制曰宣朗，君召臣曰宣唤，臣奉君命，宣布上意，皆宣之意也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744590, '10B59976A22B7FB510195A26BBC75031', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6650, 364, 400100902, NULL, NULL, NULL, NULL, NULL, NULL, '附录：十剂　　\n           刘完素曰：制方之体，欲成七方、十剂之用者，必本于气味也。寒、热、温、凉，四气生于天；酸、苦、辛、咸、甘、淡，六味成于地。是以有形为味，无形为气。气为阳，味为阴。阳气出上窍，阴味出下窍。气化则精生，味化则形长。故地产养形，形不足者，温之以气；天产养精，精不足者，补之以味。辛甘发散为阳，酸苦涌泄为阴；咸味涌泄为阴，淡味渗泄为阳。辛散、酸收、甘缓、苦坚、咸软，各随五脏之病，而制药性之品味。故方有七，剂有十。方不七，不足以尽方之变；剂不十，不足以尽剂之用。方不对证，非方也；剂不蠲疾，非剂也。此乃太古先师，设绳墨而取曲直；叔世方士，乃出规矩以为方圆。夫物各有性，制而用之，变而通之，施于品剂，其功用岂有穷哉！如是有因其性而为用者，有因其用而为使者，有因其所胜而为制者，有气相同则相求者，有气相克则相制者，有气有馀而补不足者，有气相感则以意使者，有质同而性异者，有名异而实同者。故蛇之性上窜而引药，蝉之性外脱而退翳，虻饮血而用以治血，鼠善穿而用以治漏，所谓因其性而为用者如此。弩牙速产，以机发而不括也；杵糠下咽，以杵筑下也，所谓因其用而为使者如此。浮萍不沉水，可以胜湿；独活不摇风，可以治风，所谓因其所胜而为制者如此。麻，木谷而治风；豆，水谷而治水，所谓气相同则相求者如此。牛，土畜，乳可以止渴疾；豕，水畜，心可以镇恍忽，所谓因其气相克则相制也如此。熊肉振羸，兔肝明视，所谓因其气有余补不足也如此。鲤之治水，鹜之利水，所谓因其气相感则以意使者如此。蜜成于蜂，蜜温而蜂寒；油生于麻，麻温而油寒，兹同质而异性者也。靡芜生于芎，蓬蘽并于覆盆，兹名异而实同者也。如斯之类，不可胜举。故天地赋形，不离阴阳，形色自然，皆有法象。毛羽之类，生于阳而属于阴；鳞甲之类，生于阴而属于阳。空青法木，色青而主肝；丹砂法火，色赤而主心；云母法金，色白而主肺；磁石法水，色黑而主肾；黄石脂法土，色黄而主脾。故触类而长之，莫不有自然之理也。欲为医者，上知天文，下知地理，中知人事，三者俱明，然后可以语人之疾病。不然，则如无目夜游，无足登陟，动致颠殒，而欲愈疾者，未之有也。　　\n       徐之才曰：药有宣、通、补、泻、轻、重、滑、涩、燥、湿十种，是药之大体，而《本经》不言，后人未述。凡用药者，审而详之，则靡所遗失矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624968791744591, '01BC4118F1DFD9E2A93D7EA360C8F853', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:44:33', 1, 'admin', '2025-01-11 15:01:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6651, 365, 400101001, NULL, NULL, NULL, NULL, NULL, NULL, '       十剂之后，陶隐居续入寒热二剂。岂知寒有时而不可以治热，热有时而不可以治寒，何者？阴虚内热，当用甘寒滋肾家之阴，是益水以制火也。设用芩、连、栀子苦寒之剂以攻热，则徒败胃气。苦寒损胃而伤血，血愈不足而热愈炽。胃气伤则后天之元气愈无所养，而病转增剧也。阳虚中外俱寒，当以人参、黄耆以益表里之阳气，而少佐桂、附以回阳，则其寒自解，是益火以祛寒也。设专用辛热，如吴茱萸、干姜、麻黄、葫芦巴、荜茇、胡椒之属以散寒，则辛能走散，真气愈虚，其寒愈甚。王安道所谓辛热愈投而沉寒愈滋也。二者非徒无益，而又害之，顾不悖欤！况寒热二剂，摄在补泻，义不重出。今当增入升降二剂。升降者，治法之大机也。《经》曰：高者抑之，即降之义也。下者举之，即升之义也。是以病升者用降剂，病降者用升剂。火空则发，降气则火自下矣，火下是阳交于阴也，此法所宜降者也。劳伤则阳气下陷，入于阴分，东垣所谓阴实阳虚。阳虚则内外皆寒，间有表热类外感者，但不头疼口渴、及热有时而间为异耳，法当升阳益气，用参、耆、炙甘草益元气以除虚寒虚热，佐以升麻、柴胡引阳气上行，则表里之寒热自解，即甘温除大热之谓，此法所宜升者也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624969013674053, '08B0E742AE172B05A9D328E9D648B1AC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:45:28', 1, '超级管理员', '2024-12-21 09:45:27');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6652, 366, 400101101, NULL, NULL, NULL, NULL, NULL, NULL, '       五脏苦欲补泻，乃用药第一义。好古为东垣高足，东垣得之洁古，洁古实宗仲景。仲景远师伊尹，伊尹原本炎黄。圣哲授受，百世一源，靡或少异。不明乎此，不足以言医矣。何则？五脏之内，各有其神。神各有性，性复各殊。故《素问》命十二官之名，厥有旨焉。盖形而上者，神也，有知而无质；形而下者，块然者也，五脏之体也，有质而无知。各各分断者也。肝藏魂，肺藏魄，心藏神，脾藏意与智，肾藏精与志，皆指有知之性而言，即神也。神也者，阴阳不测之谓也。是形而上者，脏之性也。惟其无形，故能主乎有形。故知苦欲者，犹言好恶也。违其性故苦，遂其性故欲。欲者，是本脏之神之所好也，即补也。苦者，是本脏之神之所恶也，即泻也。补泻系乎苦欲，苦欲因乎脏性。不属五行，未落阴阳，其神用之谓与！自“虚则补其母”已下，乃言脏体之虚实，始有补母泻子之法，斯则五行之性也。明乎此，斯可以言药道矣。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624969454137413, '1780AD68BFCB70F7270FF91E29142194', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:47:15', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6653, 367, 400101210, NULL, NULL, NULL, NULL, NULL, NULL, '        肾为作强之官，藏精与志，主五液，属真阴，水脏也。其性本润，故恶涸燥，宜急食辛以润之，知母之属是已。欲坚，急食苦以坚之。盖肾非坚，则无以称作强之职。四气以遇湿热即软，遇寒冷即坚。五味以得咸即软，得苦即坚，故宜急食苦以坚之。黄檗味苦气寒，可以坚肾，故宜急食，以遂其欲坚之性也。以苦补之，是坚即补也，地黄、黄檗之属是已。咸能软坚，软即泻也，泽泻之属是已。虚者，精气夺也。藏精之脏，苦固能坚，然非益精，无以为补，故宜熟地黄、黄檗之属以补之是已。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033542, '8D5AB1ADCA9589E8E3725967FD607D6A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6654, 367, 400101209, NULL, NULL, NULL, NULL, NULL, NULL, '      肾苦燥，急食辛以润之，（知母。）欲坚，急食苦以坚之，（黄檗。）以苦补之，（地黄。）以咸泻之，（泽泻。）虚则熟地黄、黄檗补之。肾本无实，不可泻，钱氏止有补肾地黄丸，无泻肾之药。肺乃肾之母，以五味子补肺。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033543, 'C6640B1D2F1B18CE28534D3B5012B654', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6655, 367, 400101208, NULL, NULL, NULL, NULL, NULL, NULL, '       肺为华盖之脏，相傅之官，藏魄而主气者也。气常则顺，气变则逆，逆则违其性矣，故宜急食苦以泄之，黄芩之属是已。肺主上焦，其政敛肃，故其性喜收，宜急食酸以收之，白芍药之属是已。贼肺者，热也，肺受热邪，急食辛以泻之，桑白皮之属是已，不敛，则气无所管束，是肺失其职也，故宜补之以酸，使遂其收敛之性，以清肃乎上焦，是即补也。五味子之属是已。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033544, '43BDDEC3F04E122BEED78FE34BB42F6D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6656, 367, 400101207, NULL, NULL, NULL, NULL, NULL, NULL, '      肺苦气上逆，急食苦以泄之，（诃子皮，一作黄芩。）欲收，急食酸以收之，（白芍药。）以辛泻之，（桑白皮。）以酸补之，（五味子。）虚则五味子补之，如无他证，钱氏阿胶散补之。脾乃肺之母，以甘草补脾。实则桑白皮泻之，如无他证，以泻白散泻之。肾乃肺之子。以泽泻泻肾。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033545, 'F9573A4851CE7DE68FAC2AEABB54B03B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6657, 367, 400101206, NULL, NULL, NULL, NULL, NULL, NULL, '         脾为仓廪之官，主运动磨物之脏。燥，其性也，宜健而不宜滞。湿，斯滞矣。违其性，故苦而恶之。急食苦以燥之，使复其性之所喜，脾斯健矣。白术之苦温是已。过燥则复欲缓之以甘，甘草之属是已。稼穑之化，故甘先入脾。性欲健运，气旺则行。补之以甘，人参是已。长夏之令，湿热主之。脾气斯困，故当急食苦以泻之，黄连之苦寒是已。虚则宜补，炙甘草之甘以益血，大枣之甘温以益气，乃所以补其不足也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033546, '6AEC66F1D3266D6F38ADA7F3D1D6A9F7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6658, 367, 400101205, NULL, NULL, NULL, NULL, NULL, NULL, '       脾苦湿，急食苦以燥之，（白术。）欲缓，急食甘以缓之，（甘草。）以甘补之，（人参。）以苦泻之，（黄连。）虚以甘草、大枣之类补之，如无他证，钱氏益黄散主之。心乃脾之母，以炒盐补心。实则以枳实泻之，如无他证，以泻黄散泻之。肺乃脾之子，以桑白皮泻肺。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033547, '429E0B7D59AFA975EAAED909DFE588BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6659, 367, 400101204, NULL, NULL, NULL, NULL, NULL, NULL, '          心为形君，神明之性，恶散缓而喜收敛。散缓则违其性，敛则宁静清明，故宜酸以收其缓也。软者，和调之义也。心君本自和调，邪热乘之则躁急，故复须芒硝之咸寒，除其邪热，以软其躁急坚劲之气，使复其平也。以咸补之，泽泻导心气以入肾也。烦劳则虚而生热，故须人参、黄芪、甘草之甘温，以益元气而虚热自退，故谓之泻也。心以下交于肾为补，炒盐之咸以润下，即得心与肾交也。火空则发，盐为水味，得之俾心气下降，是既济之道也，有补之义焉，故软即补也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033548, '40360C24A46AEDE291CABFF714A0AEA4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6660, 367, 400101203, NULL, NULL, NULL, NULL, NULL, NULL, '        心苦缓，急食酸以收之，（五味子。）欲软，急食咸以软之，（芒硝。）以咸补之，（泽泻。）以甘泻之，（人参、黄耆、甘草。）虚以炒盐补之，虚则补其母。木能生火，肝乃心之母。肝，木也，以生姜补肝。如无他证，钱氏安神丸主之。实则甘草泻之。如无他证，钱氏方中重则泻心汤，轻则导赤散。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033549, '1EB163A3622BA198BF2612152B83F119', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6661, 367, 400101202, NULL, NULL, NULL, NULL, NULL, NULL, '         肝为将军之官，言不受制者也，急则有摧折之意焉，故苦而恶之。缓之，是使遂其性也。甘可以缓，甘草之属是已。扶苏条达，木之象也；升发开展，魂之用也。故其性欲散，辛以散之，解其束缚也，是散即补也。辛可以散，川芎之属是已。若其太过，则屈制之，毋使逾分。酸可以收，芍药之属是已。急也，敛也，肝性之所苦也。违其性而苦之，肝斯虚矣。补之以辛，是明以散为补也，细辛、生姜、陈皮之属是已。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033550, 'F0854E39236CF58BAF3C73B179205F6C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6662, 367, 400101201, NULL, NULL, NULL, NULL, NULL, NULL, '        肝苦急，急食甘以缓之，（甘草。）欲散，急食辛以散之，（川芎。）以辛补之，（细辛。）以酸泻之，（芍药。）虚以生姜、陈皮之类补之。《经》曰：虚则补其母，水能生木，肾乃肝之母。肾，水也。苦以补肾，熟地黄、黄檗是矣。如无他证，钱氏地黄丸主之。实则白芍药泻之，如无他证，钱氏泻青丸主之。实则泻其子，心乃肝之子，以甘草泻心。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624970637033551, '4E8852B20CED1776E5063922AE17B0FB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 09:52:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6663, 368, 400101309, NULL, NULL, NULL, NULL, NULL, NULL, '9、病属于虚，宜治以缓。虚者精气夺也。若属沉痼，亦必从缓。治虚无速法，亦无巧法。盖病已沉痼，凡欲施治，宜有次第，故亦无速法。病属于实，宜治以急。实者，邪气胜也。邪不速逐，则为害滋蔓，故治实无迟法，亦无巧法。此病缓急一定之法也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053061, '82D2D8B509B17DEDCEDD665C77FCB320', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6664, 368, 400101308, NULL, NULL, NULL, NULL, NULL, NULL, '8、受邪为本，现证为标；五虚为本，五邪为标。譬夫腹胀由于湿者，其来必速，当利水除湿，则胀自止，是标急于本也，当先治其标。若因脾虚，渐成胀满，夜剧昼静，病属于阴，当补脾阴；夜静昼剧，病属于阳，当益脾气。是病从本生，本急于标也，当先治其本。举一为例，馀可类推矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053062, '90D882B867DCF7FC686AEE105E4C0F7A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6665, 368, 400101307, NULL, NULL, NULL, NULL, NULL, NULL, '7、病在于表，毋攻其里；病在于里，毋虚其表。邪之所在，攻必从之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053063, 'C2AF7FA6F7FCDA820F25774EF302101B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6666, 368, 400101306, NULL, NULL, NULL, NULL, NULL, NULL, '6、病从气分，则治其气：虚者温之，实者调之。病从血分，则治其血：虚则补肝、补脾、补心，实则为热、为瘀，热者清之，瘀者行之。因气病而及血者，先治其气；因血病而及气者，先治其血。因证互异，宜精别之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053064, 'CF9C4FF2F4BFD334C72F8C659F61420A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6667, 368, 400101305, NULL, NULL, NULL, NULL, NULL, NULL, '5、病在于经，则治其经；病流于络，则及其络。经直络横，相维辅也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053065, 'FD6106ADADD70A408849FE7053B69F60', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6668, 368, 400101304, NULL, NULL, NULL, NULL, NULL, NULL, '4、《经》曰：五脏者，藏精气而不泻者也，故曰满而不能实。是有补而无泻者，其常也。脏偶受邪，则泻其邪，邪尽即止。是泻其邪，非泻脏也。脏不受邪，毋轻犯也。世谓肝无补法，知其谬也。六腑者，传导化物糟粕者也，故曰实而不能满。邪客之而为病，乃可攻也。中病乃已，毋尽剂也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053066, '8BB8DCB36EA069302D10D59DB49474B0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6669, 368, 400101303, NULL, NULL, NULL, NULL, NULL, NULL, '3、病之热也，当察其源：火苟实也，苦寒咸寒以折之；若其虚也，甘寒酸寒以摄之。病之寒也，亦察其源：寒从外也，辛热辛温以散之；动于内也，甘温以益之，辛热辛温以佐之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053067, 'E863F2EFA451778CA4497498791ED9FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6670, 368, 400101302, NULL, NULL, NULL, NULL, NULL, NULL, '2、病在于阴，毋犯其阳；病在于阳，毋犯其阴。犯之者，是谓诛伐无过。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053068, '25942A425E716A41677CE32F289B4294', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6671, 368, 400101301, NULL, NULL, NULL, NULL, NULL, NULL, '1、（阴阳、寒热、脏腑、经络、气血、表里、标本先后、虚实缓急）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624981796053069, '0B0EB698D0EABD78F0F17DD5680B9AC6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:37:28', 1, '超级管理员', '2024-12-21 10:37:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6672, 369, 400101402, NULL, NULL, NULL, NULL, NULL, NULL, '2、第准经文，同一苦寒也，黄芩则燥，天冬则润，芦会能消，黄檗能补，黄连止泻，大黄下通，柴胡苦寒而升，龙胆苦寒而降。同一咸也，泽泻则泻，苁容则补，海藻、昆布则消而软坚，马茎、鹿茸则补而生齿。同一酸也，硫黄味酸而热，空青味酸而寒。甘合辛而发散为阳，甘合酸而收敛为阴。人参、黄耆，阳也，甘温以除大热；地黄、五味，阴也，甘酸以敛阴精。聊采数端，引以为例。如斯之类，难可枚举。良由气味互兼，性质各异，参合多少，制用全殊。所以穷五味之变，明药物之能，厥有旨哉！顾其用纷错，其道渊微，可以意知，难以言尽。非由妙悟，则物不从心。固将拯烝民于夭枉，宜寤寐乎兹篇。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624982159904838, 'B66384D2BA9F66F25876CF7617CAD364', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:38:57', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6673, 369, 400101401, NULL, NULL, NULL, NULL, NULL, NULL, '1、药有五味，中涵四气，因气味而成性。合气与味及性而论，其为差别，本自多途。其间厚薄多少，单用互兼，各各不同，良难究竟。是故《经》曰：五味之变，不可胜穷。此方剂之本也。阴阳二象，实为之纲纪焉。咸味本水，苦味本火，酸味本木，甘味本土，辛味本金，此五味之常也。及其变也，有神明之用焉。今姑陈其略以明之：　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624982159904839, 'BF0AC3171444A07E485854D8B85371DC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:38:57', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6674, 370, 400101504, NULL, NULL, NULL, NULL, NULL, NULL, '4、以上皆四时六气所伤致病，并证重舍时，时重舍证，用药主治之大法，万世遵守之常经，圣哲复起，不可改已。所云六气者，即风寒暑湿燥火是也。过则为淫，故曰六淫。淫则为邪，以其为天之气，从外而入，故曰外邪。邪之所中，各有其地：在表治表，在里治里，表里之间，则从和解。病有是证，证有是药，各有司存，不相越也。此古人之定法，今人之轨则也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624982730362950, '75513B14D8DAD44C26BCCA3E089E281C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:41:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6675, 370, 400101503, NULL, NULL, NULL, NULL, NULL, NULL, '3、至于四气所伤。因而致病，则各从所由。是故《经》曰：春伤于风，夏生飧泄。药宜升之、燥之，升麻、柴胡、羌活、防风之属是已。夏伤于暑，秋必痎疟。药宜清暑益气，以除寒热，石膏、知母、干葛、麦门冬、橘皮、参、苓、术之属是已。邪若内陷，必便脓血，药宜祛暑消滞，专保胃气，黄连、滑石、芍药、升麻、莲实、人参、扁豆、甘草之属是已。秋伤于湿，冬生咳嗽。药宜燥湿清热，和表降气保肺，桑白皮、石膏、薄荷、杏仁、甘草、桔梗、苏子、枇杷叶之属是已。冬伤于寒，春必病温。邪初在表，药宜辛寒、苦温、甘寒、苦寒，以解表邪，兼除内热，羌活、石膏、葛根、前胡、知母、竹叶、柴胡、麦门冬、荆芥、甘草之属是已。至夏变为热病，六经传变，药亦同前。散之贵早，治若后时，邪结于里，上则陷胸，中下承气，中病乃已，慎毋尽剂。勿僭勿忒，能事必矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624982730362951, 'E2BF649E57A9F9F3B7D92D5F5F17314A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:41:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6676, 370, 400101502, NULL, NULL, NULL, NULL, NULL, NULL, '2、然而一气之中，初、中、末异；一日之内，寒燠或殊。假令大热之候，人多感暑，忽发冰雹，亦复感寒。由先而感则为暑病，由后而感则为寒病。病暑者投以暑药，病寒者投以寒药。此药之因时制宜，以合乎权，乃变中之常也。此时令不齐之所宜审也。假令阴虚之人，虽当隆冬，阴精亏竭，水既不足，不能制火，则阳无所依，外泄为热，或反汗出，药宜益阴，地黄、五味、鳖甲、枸杞之属是已。设从时令，误用辛温，势必立毙。假令阳虚之人，虽当盛夏，阳气不足，不能外卫其表，表虚不任风寒，洒淅战栗，思得热食，及御重裘，是虽天令之热，亦不足以敌其真阳之虚。病属虚寒，药宜温补，参、耆、桂、附之属是已。设从时令，误用苦寒，亦必立毙。此药之舍时从证者也。假令素病血虚之人，不利苦寒，恐其损胃伤血。一旦中暑，暴注霍乱，须用黄连、滑石以泄之；本不利升，须用葛根以散之。此药之舍证从时者也。从违之际，权其轻重耳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624982730362952, 'CB5691038EC1D2F03325A4872112EB75', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:41:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6677, 370, 400101501, NULL, NULL, NULL, NULL, NULL, NULL, '1、夫四时之气，行乎天地之间。人处气交之中，亦必因之而感者，其常也。春气生而升，夏气长而散，长夏之气化而软，秋气收而敛，冬气藏而沉。人身之气，自然相通。是故生者顺之，长者敷之，化者坚之，收者肃之，藏者固之。此药之顺乎天者也。春温夏热，元气外泄，阴精不足，药宜养阴；秋凉冬寒，阳气潜藏，勿轻开通，药宜养阳。此药之因时制用，补不足以和其气者也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624982730362953, '1CF5460CC9EA61A02B8E6DD8A5518518', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:41:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6682, 373, 400101602, NULL, NULL, NULL, NULL, NULL, NULL, '2、升降者，病机之要最也。升为春气，为风化，为木象。故升有散之之义；降为秋气，为燥化，为金象，故降有敛之之义。饮食劳倦，则阳气下陷，宜升阳益气。泻利不止，宜升阳益胃。郁火内伏，宜升阳散火。滞下不休，宜升阳解毒，开胃除热。因湿洞泄，宜升阳除湿。肝木郁于地中，以致少腹作胀、作痛，宜升阳调气。此病宜升之类也。阴虚则水不足以制火，火空则发而炎上。其为证也，为咳嗽，为多痰，为吐血，为鼻衄，为齿衄，为头痛，为齿痛，为眼痛，为头眩，为晕，为眼花，为恶心，为呕吐，为口苦舌干，为不眠，为寒热，为骨蒸，是为上盛下虚之候。宜用苏子、枇杷叶、麦门冬、白芍药、五味子之属以降气，气降则火自降，而气自归元。而又益之以滋水添精之药，以救其本，则诸证自瘳。此病宜降之类也。设宜降而妄升，当升而反降，将使轻变为重，重必毙矣。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624983610269766, '69E0EEB3CF0FCD7F4599962770169D94', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:44:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6683, 373, 400101601, NULL, NULL, NULL, NULL, NULL, NULL, '1、夫虚实者，诸病之根本也；补泻者，治疗之纲纪也。何谓虚？五脏六腑虚所生病也。何谓实？五脏六腑实所生病也。《经》曰：真气夺则虚，邪气胜则实。虚则补之，实则泻之。此万世之常经也。以补为泻，是补中有泻也；以泻为补，是泻中有补也。譬夫参、耆、炙甘草之退劳倦气虚发热；地黄、黄檗之滋水坚肾，以除阴虚潮热，是补中之泻也。桑根白皮之泻肺火，车前子之利小便除湿，是泻中之补也。举斯为例，馀可类推矣。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624983610269767, '3D10CF2E38F84A54882F990ED216154B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:44:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6684, 374, 400101704, NULL, NULL, NULL, NULL, NULL, NULL, '4、用热远热者，是病本于寒，法应热治，所投热剂，仅使中病，毋令过焉。过则反生热病矣。用寒远寒，义亦同此。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624984105295942, 'A1A6C0393A2119EAC092056BABF18DE5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:46:52', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6685, 374, 400101703, NULL, NULL, NULL, NULL, NULL, NULL, '3、寒因热用，是药本寒也，而反佐之以热。热因寒用，是药本热也，而反佐之以寒，则无拒格之患。故曰：必先其所主，而伏其所因也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624984105295943, '0B4EEB6FC46CB98290B4F131BA6E777F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:46:52', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6686, 374, 400101702, NULL, NULL, NULL, NULL, NULL, NULL, '2、通因通用者，譬夫伤寒挟热下利，或中有燥粪，必用调胃承气汤，下之乃安。滞下不休，得六一散清热除积而愈，皆其义也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624984105295944, 'EB47D0C49DFC17F3A8E046C16EB40221', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:46:52', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6687, 374, 400101701, NULL, NULL, NULL, NULL, NULL, NULL, '1、《经》曰：塞因塞用者，譬夫脾虚中焦作胀，肾虚气不归元，致上焦逆满，用人参之甘以补元气，五味子之酸以收虚气，则脾得补而胀自消，肾得补而气自归元，上焦清泰，而逆满自平矣。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624984105295945, 'A0BFB35FE12A713BE5E953FC641F0CC8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:46:52', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6688, 375, 400101801, NULL, NULL, NULL, NULL, NULL, NULL, '1、夫人在气交之中，其强其弱，卒莫逃乎天地之气明甚。是以上古之人，度百岁乃去，今则七十称古稀矣。身形长大，常过七尺，今则世鲜六尺之躯矣。其寿数精神，既已渐减，则血气脏腑，亦应因之渐薄，乃天地之风气使然，有非人力所能挽回者。又况时丁末造，众生识昏见陋，五欲炽然，难解难遏，斫丧戕贼，日惟不足，于是疾病丛生，虚多实少。临证施治，多事调养，专防克伐，此今日治法之急务也。设使病宜用热，亦当先之以温；病宜用寒，亦当先之以清。纵有积滞宜消，必须先养胃气：纵有邪气宜祛，必须随时逐散，不得过剂，以损伤气血。气血者，人之所赖以生者也。气血一亏，则诸邪辐辏，百病横生。世人之病，十有九虚。医师之药，百无一补。宁知用药之误，则实者虚，虚者死，是死于医药，而非死于疾病也。其慎其难，属诸司命。临证之顷，宜加战兢。勉之哉！毋执己见而轻人命也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624984502259781, 'F4A798F15780DF395927E901C5FB82B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:48:29', 1, '超级管理员', '2024-12-21 10:48:29');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6689, 376, 400101901, NULL, NULL, NULL, NULL, NULL, NULL, '1、《经》曰：邪气盛则实，精气夺则虚。又曰：邪之所凑，其气必虚。凡言虚者，精气夺也；凡言实者，邪气胜也。是故虚则受邪，邪客为实，法先攻邪，邪尽治本。邪犹未尽，勿轻补益。犯之者，是谓实实。精者，阴也；气者，阳也。设被削夺，是五脏六腑之阴精、阳气皆虚也。宜从其类以补之。阴精虚者，补阴精；阳气虚者，益阳气。一切克伐攻击之药，概勿施用。犯之者，是为虚虚。《经》曰：实实虚虚，损不足而益有余，如是者，医杀之耳！戒之哉！　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624984716615750, '4A64E5A7B39B794A244AB6589423FCC4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:49:21', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6690, 377, 400102001, NULL, NULL, NULL, NULL, NULL, NULL, '夫胃气者，即后天元气也，以谷气为本。是故《经》曰：脉有胃气曰生，无胃气曰死。又曰：安谷则昌，绝谷则亡。可见先天之气，纵犹未尽，而他脏不至尽伤。独胃气偶有伤败，以至于绝，则速死矣。谷气者，譬国家之饷道也。饷道一绝，则万众立散；胃气一败，则百药难施。若阴虚，若阳虚，或中风，或中暑，乃至泻利滞下，胎前产后，丁肿痈疽，痘疮痧疹惊疳，靡不以保护胃气、补养脾气为先务，本所当急也。故益阴宜远苦寒，益阳宜防泄气，祛风勿过燥散，消暑毋轻下通，泻利勿加消导。滞下之忌芒硝、巴豆、牵牛，胎前泄泻之忌当归，产后寒热之忌芩、连、栀子，丁肿痈疽未溃之忌当归，痘疹之不可妄下。其他内外诸病，应设药之中，凡与胃气相违者，概勿施用。投药之顷，宜加三思。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624984991821894, 'C3C0EAAF6C58F5E8DC09B7EFCBF7D3F2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:50:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6691, 378, 400102102, NULL, NULL, NULL, NULL, NULL, NULL, '2、夫火者，阳也，气也，与水为对待者也。\n\n      水为阴精，火为阳气，二物匹配，名曰阴阳和平，亦名少火生气，如是则诸病不作矣。\n \n      设不善摄养，以致阴亏水涸，则火偏胜。$m{阴不足，则阳必凑}之，是谓$m{阳盛阴虚}，亦曰壮火食气。是知火即气，气即火也。故仙经谓：药即火，火即药，一而二，二而一者也。\n\n      东垣亦曰：火与元气不两立。亦指此也。譬诸$m{水性本流、本寒}，$m{过极则凝而不流}，为层冰矣。解则复常，非二物也。盖平则为水火既济，当斯时也，火即真阳之气矣。及其偏也，则即阳气而为火也，始与元气不两立，而成乖否之象矣。\n\n     故戴人亦曰：莫治风，莫治燥，治得火时风燥了。言苟能解此，则已达阴阳水火之原，曲畅旁通，何施不可？正指火之变态多端，其为病也非一，了此则馀皆可办。然学者非心领神会，讵足喻于斯乎？　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624985289584710, '75115FEE4894A2EF524B2DDEE370923C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:51:41', 1, 'admin', '2025-01-13 11:13:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6692, 378, 400102101, NULL, NULL, NULL, NULL, NULL, NULL, '1、《经》曰：精气夺则虚。又曰：邪之所凑，其气必虚。虚者，空也，无也。\n \n        譬诸国内空虚，人民离散，则百祸易起，镇抚为难。非委任贤智，安靖休养以生息之，未可保其无事也。\n\n         病之虚者，亦犹是已。医非明哲，孰能镇之以静？久而弗摇，卒成收合散亡，克复故物之功哉！\n\n         是故《经》曰：不能治其虚，安问其余？盖言虚为百病之本，宜其首举以冠诸证也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624985289584711, 'BB6DFB8F39103B5B97C41AA5B8178D3E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:51:41', 1, 'admin', '2025-01-13 11:13:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6693, 379, 400102201, NULL, NULL, NULL, NULL, NULL, NULL, '1、人身之有阴阳也，水一而已，火则二焉。是秉受之始。阳常有余，阴常不足，天地且然，况于人乎？故自少至老，所生疾病，靡不由于真阴不足者，其恒也。若夫真阳不足之病，千百而一二矣。阳者气也，火也，神也：阴者血也，水也，精也。阴阳和平，气血均调，是为平人气象之常候。苟失所养，或纵恣房室，或肆情喜怒，或轻犯阴阳，或嗜好辛热，以致肾水真阴不足，不能匹配阳火，遂使阳气有余。气有余，即是火，故火愈盛而水愈涸，于是发为吐血、咳嗽、吐痰、内热、骨蒸、盗汗，种种阴虚等病。医师不察，不揆其本，凡见前证，不分阴阳，类施温补。参、耆、二术，视同食物；佐以姜、桂，若啖五辛。倘遇惫剧，辄投附子。于是轻者重，重者毙，累累相踵，死而不悟。良可悯也！然使其术得售者，不独医师之罪，亦病家不明，有以致之耳！何则？难成易亏者，阴也。益阴之药，纵医师选用无差，亦必无旦夕之效。助阳之药，能使胃气一时暂壮，饮食加增；或阳道兴举，有似神王。医师藉以要功，病者利其速效，彼此固执，莫辨厥由。故知阴虚真水不足之病，十人而九；阳虚真火不足之病，百不得一。医师之药，补助阳火者，往往概施；滋益阴精者，未尝少见。宜乎服药者之多毙，无药者之反存也。予见世医以此伤人者甚众，兹特著其误，以为世戒。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624985497657414, '0D5EB8BED3CA5D114978E57474B68FA0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:52:32', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6694, 380, 400102301, NULL, NULL, NULL, NULL, NULL, NULL, '1、人身以阴阳两称为平，偏胜则病，此大较也。水不足则火有余，阴既亏则阳独盛。盖阴阳之精，互藏其宅，是阴中有阳，阳中有阴也。故心，火也，而含赤液；肾，水也，而藏白气。赤液为阴，白气为阳。循环往复，昼夜不息，此常度也。苟不知摄养，纵恣情欲，亏损真阴，阳无所附，因而发越上升，此火空则发之义，是周身之气，并于阳也。并于阳则阳盛，故上焦热而咳嗽生痰，迫血上行而为吐衄，为烦躁，为头痛，为不得眠，为胸前骨痛，为口干舌苦，此其候也。阳愈盛则阴愈虚，阴愈虚则为五心烦热，为潮热骨蒸，为遗精，为骨乏无力，为小水短赤，丹田不暖，则饮食不化，为泄泻，为卒僵仆，此其候也。治之之要，当亟降气，当益阴精。气降即阳交于阴，是火下降也。精血生即肾阴复，是水上升也。此既济之象，为坎离交也。坎离交，即是小周天。至此则阴阳二气复得其平矣，病何自而生哉？　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624986025902150, 'DE4337E97631830F0E66374AE8B77D73', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:54:41', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6695, 381, 400102401, NULL, NULL, NULL, NULL, NULL, NULL, '1、《经》曰：形不足，温之以气。人参、羊肉、黄耆、人胞、红铅之属是已。益阳气也，乃可以却沉寒。经曰：精不足，补之以味。人乳、鳖甲、地黄、黄檗、枸杞、牛膝、天门冬之属是已。补阴精也，乃可以除伏热。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624986167001157, '089F519F17D6915154D6EF29C3A75B04', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:55:15', 1, '超级管理员', '2024-12-21 10:55:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6696, 382, 400102504, NULL, NULL, NULL, NULL, NULL, NULL, '4、盖气分之病，不出三端。治之之法，及所主之药，皆不可混滥也。误则使病转剧。世多不察，故表而出之。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624986656993350, 'F80604FBA2C6B9F30B3BE34E3DBBC429', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:57:15', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6697, 382, 400102503, NULL, NULL, NULL, NULL, NULL, NULL, '3、三、破气：破者，损也。实则宜破，如少壮人暴怒气壅之类。然亦可暂不可久。其药如枳实、青皮、枳壳、牵牛之属。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624986656993351, 'AAE467D23BBA3B5A7823FAE481E4751A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:57:15', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6698, 382, 400102502, NULL, NULL, NULL, NULL, NULL, NULL, '2、二、降气、调气：降气者，即下气也。虚则气升，故法宜降。其药之轻者，如紫苏子、橘皮、麦门冬、枇杷叶、芦根汁、甘蔗；其重者，如番降香、郁金、槟榔之属。调者，和也。逆则宜和，和则调也。其药如木香、沉水香、白豆蔻、缩砂蜜、香附、橘皮、乌药之属。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624986656993352, '9276D09CE6F12EB76146FBE810C9C3DC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:57:15', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6699, 382, 400102501, NULL, NULL, NULL, NULL, NULL, NULL, '1、一、补气：气虚宜补之，如人参、黄耆、羊肉、小麦、糯米之属是也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624986656993353, '1A6C56A4A20CCECB7F14588ED6051036', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:57:15', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6700, 383, 400102604, NULL, NULL, NULL, NULL, NULL, NULL, '4、盖血为荣，阴也，有形可见，有色可察，有证可审者也。病既不同，药亦各异。治之之法，要在合宜。倘失其宜，为厉不浅，差剧之门，可不谨乎？　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987077500998, 'B2FA7B2D30DFFB23775C99C6283172E8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:58:58', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6701, 383, 400102603, NULL, NULL, NULL, NULL, NULL, NULL, '3、血瘀宜通之。瘀必发热发黄，作痛作肿，及作结块癖积。法宜辛温、辛热、辛平、辛寒、甘温，以入血通行。佐以咸寒，乃可软坚。其药为当归、红花、桃仁、苏木、桂、五灵脂、蒲黄、姜黄、郁金、京三棱、延胡索、花蕊石、没药、䗪虫、干漆、自然铜、韭汁、童便、牡蛎、芒硝之属。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987077500999, '05731A989E57566198BECC7AD56555F6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:58:58', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6702, 383, 400102602, NULL, NULL, NULL, NULL, NULL, NULL, '2、血热宜清之凉之。热则为痈肿疮疖，为鼻衄，为齿衄，为牙龈肿，为舌上出血，为舌肿，为血崩，为赤淋，为月事先期，为热入血室，为赤游丹，为眼暴赤痛。法宜酸寒、苦寒、咸寒、辛凉，以除实热。其药为童便、牡丹皮、赤芍药、生地黄、黄芩、犀角、地榆、大小蓟、茜草、黄连、山栀、大黄、青黛、天门冬、玄参、荆芥之属。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987077501000, '9DFF7A734EB39B51987BD52EB92BA107', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:58:58', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6703, 383, 400102601, NULL, NULL, NULL, NULL, NULL, NULL, '1、血虚宜补之。虚则发热。内热，法宜甘寒、甘平、酸寒、酸温，以益荣血。其药为熟地黄、白芍药、牛膝、炙甘草、酸枣仁、龙眼肉、鹿角胶、肉苁蓉、甘枸杞子、甘菊花、人乳之属。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987077501001, 'D5B076AD19FAB065EE46E2532D537A79', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 10:58:58', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6704, 384, 400102707, NULL, NULL, NULL, NULL, NULL, NULL, '7、《经》曰：五脏者，藏精气而不泻者也。肝为将军之官，主藏血。吐血者，肝失其职也。养肝则肝气平，而血有所归；伐之则肝不能藏血，血愈不止矣。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987679780934, '1CD9E37B98EDC9BCC342E54E37F79782', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:01:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6705, 384, 400102706, NULL, NULL, NULL, NULL, NULL, NULL, '6、【宜】补肝，不宜伐肝。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987679780935, '2521A4B9B980101FAE7D59603D1D6311', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:01:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6706, 384, 400102705, NULL, NULL, NULL, NULL, NULL, NULL, '5、血不循经络者，气逆上壅也。夫血得热则行，得寒则凝，故降气行血，则血循经络，不求其止而自止矣。止之则血凝，血凝必发热、恶食，及胸胁痛，病日沉痼矣。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987679780936, '3F66A713B521CDCCAFA53F2306F1EC54', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:01:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6707, 384, 400102704, NULL, NULL, NULL, NULL, NULL, NULL, '4、【宜】行血，不宜止血。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987679780937, 'E94ADB8111D767B63C89974B372CB8E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:01:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6708, 384, 400102703, NULL, NULL, NULL, NULL, NULL, NULL, '3、今之疗吐血者，大患有二：一则专用寒凉之味，如芩、连、山栀、青黛、柿饼灰、四物汤、黄檗、知母之类，往往伤脾作泄，以致不救。一则专用人参，肺热还伤肺，咳逆愈甚。亦有用参而愈者，此是气虚喘嗽。气属阳，不由阴虚火炽所致，然亦百不一二也。宜以白芍药、炙甘草制肝；枇杷叶、麦门冬、薄荷、橘红、贝母清肺；薏苡仁、怀山药养脾；韭菜、番降香、真苏子下气；青蒿、鳖甲、银柴胡、牡丹皮、地骨皮补阴清热；酸枣仁、白茯神养心；山茱萸、枸杞子、牛膝补肾。此累试辄验之方。然阴无骤补之法，非多服药不效。病家欲速其功，医者张皇无主。百药杂试，以致殒命，覆辙相寻而不悟，悲夫！　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987679780938, '206F5B89242C611E6AFF70472520ADE9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:01:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6709, 384, 400102702, NULL, NULL, NULL, NULL, NULL, NULL, '2、气有余，即是火。气降则火降，火降则气不上升，血随气行，无溢出上窍之患矣。降火必用寒凉之剂，反伤胃气。胃气伤，则脾不能统血，血愈不能归经矣。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987679780939, '3DB871644DF36E39B1F03A990C124D14', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:01:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6710, 384, 400102701, NULL, NULL, NULL, NULL, NULL, NULL, '1、【宜】降气，不宜降火。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987679780940, '57805E27CFC851DE45470F9BCFF7483E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:01:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6711, 385, 400102801, NULL, NULL, NULL, NULL, NULL, NULL, '1、凡人之生，二五妙合之顷，识神依托是中，即揽父精母血，以为立命之基，遂成左右两肾。肾间动气，即道家所谓先天祖气是也。藏乎两肾之中，以肾属水，故称坎宫。以平人气象言之，此气至子后一阳生，生即渐渐上升，历丑、寅、卯、辰、巳，而六阳已极，则入离宫。午后一阴生，即白气变为赤液，渐渐降下至坎宫，复为白气，昼夜循环，升降不息，此即医家所谓真阳之火，道家所谓君火，即先天祖气，医家谓为相火者是也。方此火之自下而上也，行过中焦，必经脾胃，则能腐熟水谷，蒸糟粕而化精微。脾气散精，上归于肺。通调水道，下输膀胱，气化而出，是谓清升浊降，即既济之象也。苟不慎摄生之道，不明正性之理，则必务快其心，逆于生乐，忧患以伤心，寒热以伤肺，饥饱以伤脾，多怒以伤肝，多欲以伤肾，则真气渐衰，精神日损。驯至子后，一阳不以时生，不能上升腐熟水谷，则糟粕无由而化。寅为三阳之候，阳气微则不能应候而化物，故天黎明而泄。其泄亦溏，俗名鸭溏，是为肾泄，亦名大瘕泄。昔人以四神丸治之，予加人参、莲肉，辄获奇效。盖人参补五脏之阳气故也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624987916378182, '41CB4DF2E1A81F764E1D871A31FE9942', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:02:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6712, 386, 400102901, NULL, NULL, NULL, NULL, NULL, NULL, '1、《经》曰：肾为作强之官，技巧出焉，藏精与志者也。夫志从士从心，志主决定，心主思维。思维则或迁或改，决定则一立不移，此作强之验也。苟志意不遂，则阳气不舒。阳气者，即真火也。譬夫极盛之火，置之密器之中，闭闷其气，使不得发越，则火立死而寒矣。此非真火衰也，乃闷郁之故也。宣其抑郁，通其志意，则阳气立舒，而其痿立起矣。若误谓阳精不足，过投补火之剂，多致痈疽而殁，可不戒哉！　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988249976902, 'A1DD2206D02DF80B06F1918C85E7845E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:03:44', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6713, 387, 400103007, NULL, NULL, NULL, NULL, NULL, NULL, '7、补阳则人参、黄耆、鹿茸、大枣、巴戟天之属。与时消息，则因乎证。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988838809670, 'FAE316E42E4E84E775D0D1EA8358740A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:06:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6714, 387, 400103006, NULL, NULL, NULL, NULL, NULL, NULL, '6、次治本，益阴则天门冬、甘菊花、怀生地、当归身、白芍药、枸杞子、麦门冬、五味子、牛膝、人乳、白胶、黄檗、白蒺藜之属；　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988838809671, '5AC4BBD92E7900747941B22DA3CAD71B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:06:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6715, 387, 400103005, NULL, NULL, NULL, NULL, NULL, NULL, '5、开痰则贝母、白芥子、竹沥、荆沥、栝楼仁、霞天膏。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988838809672, 'F208C9E24E202DD8DFF373F127BBAF84', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:06:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6716, 387, 400103004, NULL, NULL, NULL, NULL, NULL, NULL, '4、顺气则紫苏子、枇杷叶、橘红、郁金；　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988838809673, '0FCF81E730858F3BF215C39BF06A0883', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:06:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6717, 387, 400103003, NULL, NULL, NULL, NULL, NULL, NULL, '3、初清热则天门冬、麦门冬、甘菊花、白芍药、白茯苓、栝楼根、童便；　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988838809674, '3A6FBFD4B44E32187B630D31CEFBFCBF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:06:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6718, 387, 400103002, NULL, NULL, NULL, NULL, NULL, NULL, '2、若夫大江已南之东西两浙、七闽、百粤、两川、滇南、鬼方、荆、扬、梁三州之域，天地之风气既殊，人之所禀亦异。其地绝无刚猛之风，而多湿热之气，质多柔脆，往往多热多痰。真阴既亏，内热弥甚，煎熬津液，凝结为痰，壅塞气道，不得通利。热极生风，亦致猝然僵仆，类中风证。或不省人事，或语言謇涩，或口眼歪斜，或半身不遂。其将发也，外必先显内热之候，或口干舌苦，或大便秘涩，小便短赤，此其验也。刘河间所谓此证全是将息失宜，水不制火。丹溪所谓湿热相火，中痰、中气是也。此即内虚暗风，确系阴阳两虚，而阴虚者为多，与外来风邪迥别。法当清热、顺气、开痰，以救其标，次当治本。阴虚则益血，阳虚则补气，气血两虚则气血兼补，久之自瘳。设若误用治真中风药，如前辛热风燥之剂，则轻变为重，重则必死。祸福反掌，不可不察也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988838809675, '1D9C2EC6EE4CCABF956B79668AECA5EE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:06:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6719, 387, 400103001, NULL, NULL, NULL, NULL, NULL, NULL, '1、凡言中风，有真假内外之别。差之毫厘，谬以千里。何者？西北土地高寒，风气刚烈。真气空虚之人，猝为所中，中脏者死，中腑者成废人，中经络者，可调理而瘳。治之之道，先以解散风邪为急，次则补养气血，此治真中外来风邪之法也。其药以小续命汤，桂枝、麻黄、生熟附子、羌独活、防风、白芷、南星、甘草之属为本。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624988838809676, '73FA6ACB6285FF712775C89DB8174F6A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:06:08', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6720, 388, 400103102, NULL, NULL, NULL, NULL, NULL, NULL, '2、答曰：眠不竟夕而易惺者，心血不足也，故其脉弦而不洪。东垣云：胃虚者多怒，多怒者肝气必不和。《经》曰：怒则气上逆。加以久病多郁，故益易怒，故肝脉亦弦而不长。弦为血少。此非以智慧观察，以慈忍静定之力和之，未可以药石瘳也。肾属水，冬脉沉，故曰：诸浮者，肾不足也。肾主五液，又主二便，肾家有火，则真阴日亏，津液日少，不能荣养于舌络，舌络劲急，故语言不利；火性急速，故小便疾出而不能忍，且有余沥，而大便亦多燥结也。故其脉应沉实而反浮洪，失常候也。肺者，五脏之华盖，位乎上，象天而属金，喜清肃而恶烦热，热则津液干枯，无以下滴而通水道，或煎熬浓稠而成痰矣。肺热则人参反助邪热而伤肺，故往往声重多痰，壅塞气道，而升降不利也。脾为土脏，胃为之腑，乃后天元气之所自出。胃主纳，脾主消，脾阴亏则不能消，胃气弱则不能纳，饮食少则后天元气无自而生，精血坐是日益不足也。《经》曰：损其脾者，调其饮食，节其起居，适其寒温。此至论也。不如是则不足以复脾阴。然其要又在戒暴怒，使肝无不平之气，肝和则不贼脾土矣。命门者，火脏也，乃先天真阳之气之所寄，即道家所谓先天祖气，医家所谓真火是也。其壮也有三：一者元禀过厚，二者保啬精气，不妄施泄，三者志气无所怫郁，则年虽迈而犹壮也。不尔则子后一阳不生，不能上升熏蒸糟粕而化精微，以滋后天之元气，是火不生土，而脾胃因之日弱也。法当降气和肝滋肾，气降是阳交于阴也。肝和则脾胃不被贼邪所干，故能纳而能消也。脾胃无恙，则后天元气日益生长矣。肾足则真阴自生，津液自足，舌络有所荣养，则舌之伸缩自如而言语自利矣。且世无不阴虚而中风者，第须拨去烦恼，一切放下，使心火不炎，则肾亦因之而不燥，此又治之之本也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624989166235718, '5086273A363F4CFED7B979EEC0BD5A0A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:07:28', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6721, 388, 400103101, NULL, NULL, NULL, NULL, NULL, NULL, '1、或问：有患似中风证，眠不竟夕而易惺，心脉弦而不洪，多怒，肝脉弦而不长，语言謇涩不利，多痰声重，小便疾速不能忍，且有余沥，大便燥结，左尺脉浮洪，饮食少，不易消，此何以故？　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624989166235719, 'BEE0F2488654993F03AFD693AD86CDD5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:07:28', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6722, 389, 400103202, NULL, NULL, NULL, NULL, NULL, NULL, '2、世以痰饮混称，药亦混投。殊不知痰之与饮，其由自别，其状亦殊。痰质稠粘，饮惟清水，特其色有异，或青或黄，或绿或黑，或如酸浆，或伏于肠胃，或上支胸胁，刺痛难忍，或流于经络四肢，则关节不利。支饮上攻为心痛，为中脘痛，甚则汗出，为呕吐酸水、苦黄水等，种种各异。或发寒热，不思饮食，及不得眠，皆其候也。此证皆因酒后过饮茶汤，则水浆与肠胃饮食湿热之气，凝而为饮；或因情抱抑郁，饮食停滞，不得以时消散，亦能成饮。总之必由脾胃有湿，或脾胃本虚，又感饮食之湿，则停而不消，此饮之大略也。治宜燥湿利水，行气健脾，乃为得也。其药大都以半夏、茯苓、参、术为君，佐以猪苓、泽泻以渗泄之，白豆蔻、橘皮以开散之，苏梗、旋覆花以通畅之。东垣五饮丸中有人参，其旨概可见矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624989411700806, 'FA03E1CF3AED944B914B7444AF05F6B6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:08:28', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6723, 389, 400103201, NULL, NULL, NULL, NULL, NULL, NULL, '1、夫痰之生也，其由非一；其为治也，药亦不同。由于阴虚火炎，上迫乎肺，肺气热则煎熬津液，凝结为痰，是为阴虚痰火。痰在乎肺而本乎肾，治宜降气清热，益阴滋水。法忌辛温燥热补气等药。由于脾胃寒湿生痰，或兼饮啖过度，好食油面猪脂，以致脾气不利，壅滞为痰，浓厚胶固，甚至流于经络，及皮里膜外，或结为大块，或不思食，或彻夜不眠，或卒尔眩仆，不省人事，或发癫痫，或昔肥今瘦，或叫呼异常，或身重腹胀，不便行走，或泄泻不止，及成瘫痪。种种怪证，皆痰所为。故昔人云：怪病多属痰，暴病多属火。有以夫！此病在脾胃，无关肺肾，治宜燥脾行气，散结软坚。法忌滞泥、苦寒、湿润等药，及诸厚味。由于风寒郁闭，热气在肺，而成痰嗽齁喘，病亦在肺，治宜豁痰除肺热药中，加辛热、辛温，如麻黄、生干姜之属，以散外寒，则药无格拒之患。法忌温补、酸收等药。病因不齐，药亦宜异。利润利燥，及利发散，各有攸当，非可混施也。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624989411700807, '3270D6F28F9B1066092B456033C99264', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:08:28', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6724, 390, 400103302, NULL, NULL, NULL, NULL, NULL, NULL, '2、滞下者，俗呼为痢疾，皆缘暑湿与饮食之积滞胶固而成。其证类多里急后重，数登圊而不便，或发热，或口渴，或恶心，不思食何，莫非暑之标证也。必用六一散、黄连、芍药为主，而后随其所苦，为之增损。伤气分则调气益气；伤血分则行血和血，然未有不先治暑而可获效者矣。治病必求其本，其斯之谓欤？　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624989947719750, 'BAB9755D57DAE3EB585F2E0439484779', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:10:38', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6725, 390, 400103301, NULL, NULL, NULL, NULL, NULL, NULL, '1、风寒暑湿燥火，此天之六淫。其邪自外而入，感之而病，宜随其邪之所在以攻治之。《经》曰：夏伤于暑，秋必痎疟。是疟乃暑邪为病也。虽有山岚瘴气发疟一证，治稍不同，然其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，头疼骨疼，大渴引饮，口苦舌干，呕吐不思食，或烦躁不得眠，必用白虎汤二三剂，随证增损，解表以祛暑邪。而后随经消息，以除其苦可也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624989947719751, '452D7E19D36A99DEDF7783F0C8A5B720', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:10:38', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6726, 391, 400103401, NULL, NULL, NULL, NULL, NULL, NULL, '1、夫喜怒忧思悲恐惊七者，皆发于情者也。情即神识，有知不定，无迹可寻，触境乃发，滞而难通。药石无知，焉能消其妄执？纵通其已滞之气，活其已伤之血，其默默绵绵之意，物而不化者，能保无将来复结之病乎？只宜以识遣识，以理遣情，此即“心病还将心药医”之谓也。如是庶可使滞者通，结者化，情与境离，不为所转，当处寂然，心君泰定，其何七情之为累哉？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624996637380678, '9E8E67E7666731FC6519DFB4A4748507', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:37:52', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6727, 392, 400103506, NULL, NULL, NULL, NULL, NULL, NULL, '6、此之四证，皆须急治。要以自里达表者吉，自表陷里者凶。故药宜解散通利，最忌收涩破气，及诸温补。其关乎死生者最大，故特表而出之，俾世人知所先务也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997215895622, '3FFCD91EE26446E14693CC3C6B4578A7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:40:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6728, 392, 400103505, NULL, NULL, NULL, NULL, NULL, NULL, '5、疟本暑邪，法当解肌。若元气先虚之人，脾胃薄弱，误投破气消食克伐之药，则中气愈虚，邪反内陷，必便脓血。治或失宜，多成腹胀，驯至不救，往往而是。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997215895623, '9BD69F99A0305F75C07CF4552E330450', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:40:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6729, 392, 400103504, NULL, NULL, NULL, NULL, NULL, NULL, '4、若夫疹家，便须速用辛寒、甘寒、苦寒之剂，清凉发散，十不失一。假令病重药轻，或治疗后期，或误投温热，则邪热内攻，烦躁闷乱，不可救药矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997215895624, '7AF68A4B91CB97D9E254C0AF367AA7BD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:40:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6730, 392, 400103503, NULL, NULL, NULL, NULL, NULL, NULL, '3、痘疮之害，多在血热，解于一二日内者十全八九，若迟则热毒内攻，陷入于里。肠胃当之，必致大便作泄，乳食不化，或神昏闷乱，便秘腹胀，则十不救一。除是禀受虚寒，方堪补托，济以温热，可救危急。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997215895625, '4EA4673F16CC5233B51A157CAE56A80D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:40:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6731, 392, 400103502, NULL, NULL, NULL, NULL, NULL, NULL, '2、痈疽皆由荣家实热气逆所结，急宜凉血活血，散结解毒，大剂连进，内外夹攻，务使消散。即势大毒盛，一时不能散尽，亦必十消七八。纵使溃脓，保无大害。若失于救治，使热毒内攻，其膜必坏。膜坏则神人不能救矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997215895626, 'B2C23DA27F6B8D4C8E0FF69339F6110E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:40:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6732, 392, 400103501, NULL, NULL, NULL, NULL, NULL, NULL, '1、伤寒、温疫初发，邪在于表，必头疼身热，病属三阳，即于此时急表散之。冬月即病，宜用辛温、辛热以汗之；春温夏热，宜用辛凉、辛寒、甘寒以汗之。汗后身凉脉静，无所伤犯，病不复作而愈。如投药濡滞，或病重药轻，不散之于表，致邪热内结，病属三阴，须下乃愈。内虚之人，不胜下药，多致危殆。又有少阴咽痛等证，则又不宜于下，或成狐惑，虫蚀肛门，种种难治之条，皆失于不早散故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997215895627, 'C613B88328BE1E40182262E8850BF85D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:40:13', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6733, 393, 400103602, NULL, NULL, NULL, NULL, NULL, NULL, '2、予少检《素问》中载有是说。既长游于四方，见天下医师与学士大夫，在在谈说其义，于时心窃疑之。又见性理所载，元儒草庐吴氏，于天之气运之中，亦备载之。予益自信其为天运气数之法，而非医家治病之书也。后从敝邑见赵少宰家藏宋版仲景《伤寒论》，皆北宋善板，始终详检，并未尝载有是说。六经治法之中，亦并无一字及之。予乃谛信予见之不谬，而断为非治伤寒外感之说。予尝遵仲景法治一切外邪为病，靡不响应。乃信非仲景之言，不可为万世法程。杂学混滥，疑误后人，故特表而出之。俾来学知所决择云。　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997675515974, 'E02DB9E03D321F1DE1EBBF89823744A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:42:05', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6734, 393, 400103601, NULL, NULL, NULL, NULL, NULL, NULL, '1、原夫五运六气之说，其起于汉魏之后乎？何者？张仲景，汉末人也，其书不载也。华元化，三国人也，其书亦不载也。前之则越人无其文，后之则叔和鲜其说。予是以知其为后世所撰，无益于治疗，而有误乎来学，学者宜深辨之。予见今之医师，学无原本，不明所自，侈口而谈，莫不动云五运六气。将以施之治病，譬之指算法之精微，谓事物之实有，岂不误哉！殊不知五运六气者，虚位也。岁有是气至则算，无是气至则不算。既无其气，焉得有其药乎？一言可竟已。其云“必先岁气”者，譬夫此年忽多淫雨，民病多湿，药宜类用二术苦温以燥之，佐以风药，如防风、羌活、升麻、葛根之属，风能胜湿故也。此必先岁气之谓也。其云“无伐天和”者，即春夏禁用麻黄、桂枝，秋冬禁用石膏、知母、芩、连、芍药之谓。即春夏养阴、秋冬养阳之义耳！乃所以遵养天和之道也。昔人谓“不明五运六气，检遍方书何济”者，正指后人愚蒙，不明五运六气之所以，而误于方册所载，依而用之，动辄成过，则虽检遍方书，亦何益哉！　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624997675515975, 'EB9AD1A38F63447A441BCC770506A61F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:42:05', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6735, 394, 400103706, NULL, NULL, NULL, NULL, NULL, NULL, '6、上来所祝五条，皆关切医师才品道术，利济功过。仰愿来学，俯从吾祝，则进乎道而不囿于技矣。讵非生人之至幸，斯道之大光也哉！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624998314508358, '0FD3D73809D372A9D72E95028FFF6BCF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:44:41', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6736, 394, 400103705, NULL, NULL, NULL, NULL, NULL, NULL, '5、医师不患道术不精，而患取金不多。舍其本业，专事旁求。假宠贵人，翼其口吻，以希世重。纵得多金，无拔苦力。于当来世，岂不酬偿？作是思惟，是苦非乐。故当勤求道术，以济物命。纵有功效，任其自酬，勿责厚报。等心施治，勿轻贫贱。如此则德植厥躬，鬼神幽赞矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624998314508359, '0A1DA7C6A8EE6FF0C6EEB30801A7D5CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:44:41', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6737, 394, 400103704, NULL, NULL, NULL, NULL, NULL, NULL, '4、凡作医师，宜先虚怀。灵知空洞，本无一物。苟执我见，便与物对。我见坚固，势必轻人；我是人非，与境角立。一灵空窍，动为所塞，虽日亲至人，终不获益。白首故吾，良可悲已！执而不化，害加于人。清夜深思，宜生愧耻。况人之才识，自非生知，必假问学。问学之益，广博难量。脱不虚怀，何由纳受？不耻无学，而耻下问。师心自圣，于道何益？苟非至愚，能不儆省乎！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624998314508360, 'B2D37895B81C6011ABF4F618C1A2B5BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:44:41', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6738, 394, 400103703, NULL, NULL, NULL, NULL, NULL, NULL, '3、凡为医师，先当识药。药之所产，方隅不同，则精粗顿异，收采不时，则力用全乖。又或市肆饰伪，足以混真。苟非确认形质，精尝气味，鲜有不为其误者。譬诸将不知兵，立功何自？医之于药，亦犹是耳。既识药矣，宜习修事。《雷公炮炙》，固为大法，或有未尽，可以意通。必期躬亲，勿图苟且。譬诸饮食，烹调失度，尚不益人，反能增害，何况药物关乎躯命者耶？可不慎诸！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624998314508361, '7AE995C36E0D0B0BEB6B682FEE57057A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:44:41', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6739, 394, 400103702, NULL, NULL, NULL, NULL, NULL, NULL, '2、凡为医师，当先读书。凡欲读书，当先识字。字者，文之始也。不识字义，宁解文理？文理不通，动成窒碍。虽诗书满目，于神不染，触途成滞，何由省入？譬诸面墙，亦同木偶。望其拯生民之疾苦，顾不难哉？故昔称太医，今曰儒医太医者，读书穷理，本之身心，验之事物，战战兢兢，求中于道。造次之际，罔敢或肆者也。外此则俗工耳，不可以言医矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624998314508362, 'CEC2CC41848669FEE21036AC9C92F4F1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:44:41', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6740, 394, 400103701, NULL, NULL, NULL, NULL, NULL, NULL, '1、凡人疾病，皆由前生不惜众生身命，竭用人财，好杀鸟兽昆虫，好箠楚下贱，甚则枉用毒刑，加诸无罪。种种业因，感此苦报。业作医师，为人司命，见诸苦恼，当兴悲悯。详检方书，精求药道，谛察深思，务期协中。常自思惟，药不对病，病不对机，二旨或乖，则下咽不返。人命至重，冥报难逃。勿为一时衣食，自贻莫忏之罪于千百劫。戒之哉！宜惧不宜喜也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 624998314508363, '90B55D630C707AACEF8E04C1B9A758DA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 11:44:41', NULL, NULL, NULL);
