INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6774, 396, 400103909, NULL, NULL, NULL, NULL, NULL, NULL, '9、上盛下虚：属阳盛阴虚。\n\n【忌】升散、下、助阳、补气、复忌破气、燥热辛温。\n\n      诸药俱见阴虚条下。\n\n【宜】降、益阴、甘寒、酸寒、佐以咸寒、苦寒。\n\n         苏子、枇杷叶、麦门冬、枸杞子、生地、沙参、白芍药、山茱萸、五味子、牛膝、童便、玄参、黄檗、天门冬。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092869, '7B026371AE2EEBB11F30068B68BA7726', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6775, 396, 400103908, NULL, NULL, NULL, NULL, NULL, NULL, '8、阴厥：即寒厥。其证四肢厥逆，身冷，面青蜷卧，手指爪青黯，腹痛，大便溏，或完谷不化，小便自利，不渴，不省人事。\n\n【忌】下、破气、苦寒、咸寒、酸寒。\n\n     食盐、太阴玄精石、童便（已上咸寒）、芍药、醋（已上酸寒）。\n\n     下、破气、苦寒诸药俱见前。\n\n【宜】补气、温中、甘温、辛热。\n\n          人参、干姜、附子、桂、吴茱萸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092870, 'AC4877E03E629B88B49210D5385461BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6776, 396, 400103907, NULL, NULL, NULL, NULL, NULL, NULL, '7、阳厥：即热厥。其证四肢厥逆，身热面赤，唇燥，大渴，口干舌苦，目闭或不闭，小便赤涩短少，大便燥结，不省人事。\n\n【忌】升发、补敛、燥热、辛温。\n\n          诸药俱见前。\n\n【宜】下、清热、甘寒、苦寒、咸寒。\n\n      大黄、芒硝、石膏、黄芩、黄连、山栀、知母、童便。\n如挟虚有痰者，宜麦门冬、竹沥、芦根汁、梨汁、牛黄、童便。\n如妇人热入血室，因而厥者，药中以童便为君，加赤芍药、生地黄、牛膝、牡丹皮、桃仁。甚者大便结燥，加芒硝、大黄下之。通即止，勿尽剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092871, 'E1F0991190E3729799AD0FCD6AB0355C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6777, 396, 400103906, NULL, NULL, NULL, NULL, NULL, NULL, '6、阴实：即里实。外感证属邪热内结者，其证胸腹硬痛，手不可近，大便七八日不行，或挟热下痢。\n\n【忌】辛温发散、补敛。\n\n       诸药俱见前。\n\n【宜】下、苦寒、咸寒、甘辛。\n\n        大黄、厚朴、枳实、滑石、山栀、黄芩、黄连、蓝、茵蔯、陈、芒硝、桃仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092872, '27D1860CA3699D90B8251494E668FB34', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6778, 396, 400103905, NULL, NULL, NULL, NULL, NULL, NULL, '5、阳实：即表邪热盛，其证头痛发热，遍身骨痛，无汗。\n\n【忌】补敛、下、大热。\n\n         黄耆、人参、二术、桂枝、芍药、五味子、米面食、猪羊犬肉、醋（已上补敛）、附子、胡椒、干姜、肉桂、蒜、吴茱萸（已上大热）、下药见前。\n\n【宜】辛寒、发散，天寒略加辛热、辛温佐之。\n\n         石膏、知母、葛根、麦门冬、前胡、柴胡、黄芩、紫苏、薄荷、升麻、防风、葱白、荆芥、羌活、麻黄（冬月可用，春夏忌之）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092873, '0CD07C8211D9A227D76BBC04197C51A9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6779, 396, 400103904, NULL, NULL, NULL, NULL, NULL, NULL, '4、里虚：其证洞泄，或完谷不化，心腹痛，按之即止。或腹胀，或伤寒下后痞满。\n\n【忌】破气、下、苦寒。\n\n         大黄、芒硝、巴豆、玄明粉、牵牛（已上下）、黄芩、黄连、山栀、知母、黄檗、天门冬、茗（已上苦寒）、破气药见前。\n\n【宜】温补、甘、佐以辛热。\n\n           人参、炙甘草、术、大枣、糯米、肉桂、附子（有热者勿用）、干姜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092874, 'F30772507CDCBF74CBC13DB555F25EF4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6780, 396, 400103903, NULL, NULL, NULL, NULL, NULL, NULL, '3、表虚：其证自汗恶风，洒淅寒热，喜就温暖，脉浮无力。\n\n【忌】破气、升发、辛热。\n\n           麻黄、升麻、防风、柴胡、羌活、独活、前胡、干葛、紫苏、薄荷、白芷、生姜、荆芥（已上升发）、吴茱萸、桂枝（表虚而中寒者不忌）、干姜（已上辛热）、破气药见前。\n\n【宜】补敛、益气实表、甘、酸。\n\n        人参、黄耆、白芍药、甘草、桂枝（有热者勿用）、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092875, '8974CCF6AD77040E1C6BDF5266AED104', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6781, 396, 400103902, NULL, NULL, NULL, NULL, NULL, NULL, '2、阴虚：即精血虚。其证为咳嗽多痰，吐血，咯血，嗽血，鼻衄，齿衄，盗汗，自汗，发热，寒热，潮热，骨乏无力，不眠，气急，腰背痛。\n\n【忌】补气，复忌破气、燥热辛温，又忌大寒大苦伤胃，并升提发散、利水。\n\n         人参、黄耆、二术、人胞（已上补气）、南星、半夏、附子、官桂、桂枝、仙茅、鹿茸、干姜、硫黄、阳起石、海狗肾、丁香、胡椒、乌头、火酒、吴茱萸、乌药、生姜（已上燥热辛温）、山栀、黄芩、黄连、大黄、芒硝、玄明粉（已上大寒大苦伤胃）、麻黄、升麻、柴胡、羌活、独活、藁本、川芎、防风（已上升提发散）、破气利水药见前。\n\n【宜】生精补血，兼清虚热、敛摄、酸寒、甘寒、甘平、咸寒，略兼苦寒。\n\n           地黄、柏子仁、人乳、沙苑蒺藜、枸杞子、牛膝、麋角胶、阿胶、沙参、酸枣仁、白芍药、五味子、山茱萸、石斛、麦门冬、薯蓣、牡丹皮、续断、地骨皮、车前子、溺白垽、鳖甲、黄檗、知母、青蒿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092876, 'C4BBB3837E4EA8CD0E04952E6AA0CA6E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6782, 396, 400103901, NULL, NULL, NULL, NULL, NULL, NULL, '1、阳虚：即真气虚。其证恶寒，或发热自汗，汗多亡阳。阳虚不发热，单恶寒者居多。\n\n【忌】破气、降泄、利水、苦寒、又忌辛热发散。\n\n        青皮、枳壳、厚朴、牵牛、槟榔（已上破气）、大黄、石膏、山栀、知母、天门冬、生地黄、栝楼（已上降泄）、泽泻、木通、瞿麦、木桕根皮、汉防己、葶苈、猪苓、滑石、海金沙、商陆（已上利水）、黄芩、黄连、黄檗、玄参、槐花（已上苦寒）、芍药、乌梅、醋（已上酸）、吴茱萸、麻黄、羌活、独活、前胡、防风、荆芥（已上辛热发散）。\n\n【宜】补、甘、温、热。\n\n       人参、黄耆、二术、炙甘草、当归、白胶、淫羊藿、人胞、红铅、补骨脂、巴戟天、桂、附子、仙茅、鹿茸、大蘹香、阳起石、羊肉、雀肉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625083430092877, '76FD4E79635F24FC792C87E2A114667C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-21 17:31:01', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6783, 397, 400104002, NULL, NULL, NULL, NULL, NULL, NULL, '2、心虚（八证）\n【忌】升发、破气、苦寒、辛燥、大热。诸药俱见前。\n【宜】补血、甘温、酸敛、佐以咸寒、镇坠。生地黄、龙眼肉、人参、炙甘草、石斛、酸枣仁、五味子、柏子仁、丹参、茯神、远志、鹿茸、炒盐、丹砂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625689930211398, '1AB31ED3BED1188AEB8CD65D596C450D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 10:38:53', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6784, 397, 400104001, NULL, NULL, NULL, NULL, NULL, NULL, '1、五脏六腑虚实门\n安息香、丹砂、磁石、神水\n五心烦热，属真阴不足。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625689930211399, '16956A70B908ED8D2E5A4EC11E97AFDA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 10:38:53', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6785, 397, 400104089, NULL, NULL, NULL, NULL, NULL, NULL, '89、短气、少气，属气虚。\n【忌】同三焦虚。\n【宜】补气益精、甘温、甘寒、酸温。人参、黄耆、麦门冬、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180165, 'BDF2F10387CC7C55611B2D67351183A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6786, 397, 400104088, NULL, NULL, NULL, NULL, NULL, NULL, '88、腹寒，属中气虚。忌、宜俱同三焦虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180166, '0EA986AB0B0808B60A9C651698BBABB8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6787, 397, 400104087, NULL, NULL, NULL, NULL, NULL, NULL, '87、三焦虚（二证）\n【忌】破气、降、复忌升发、苦寒。诸药俱见前。\n【宜】补中益气，佐以辛温。人参、黄耆、白术、益智子、沉香、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180167, '0CCB3ED86C357CA74AB11D8F39F6BD34', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6788, 397, 400104086, NULL, NULL, NULL, NULL, NULL, NULL, '86、膀胱气。忌、宜俱同疝。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180168, '0CC732D92FA702A72AF3CF39E11E6349', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6789, 397, 400104085, NULL, NULL, NULL, NULL, NULL, NULL, '85、遗尿，属本经气虚，见小肠虚条内。因膀胱虚亦能致遗尿，故复列此。忌、宜俱见小肠虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180169, '1D535160C95EE305F5A94AA0F72A5E37', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6790, 397, 400104084, NULL, NULL, NULL, NULL, NULL, NULL, '84、小便不禁，属气血虚。\n【忌】降下、湿润、燥热。诸药俱见前。\n【宜】同膀胱虚，加：牡蛎、龙骨、鹿茸、桑螵蛸、鸡䏶胵。频数不能少忍，加：麦门冬、五味子、黄檗、山茱萸、天门冬、鳖甲、牛膝、柏子仁、甘枸杞子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180170, 'CB6ECC7E385CF8E81D551911141138E0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6791, 397, 400104083, NULL, NULL, NULL, NULL, NULL, NULL, '83、膀胱虚（三证）\n【忌】破气、燥、利小便。诸药俱见前。\n【宜】补气、酸敛。人参、五味子、山茱萸、益智子、金樱子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180171, 'E61E12E0BE1650815F2E9FD1FABC9AEF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6792, 397, 400104082, NULL, NULL, NULL, NULL, NULL, NULL, '82、脱肛，属气虚，兼有湿热。\n【忌】同大肠虚。\n【宜】补气、升提、除湿热。人参、黄耆、炙甘草、白术、莲肉、白扁豆、升麻、干葛、柴胡、黄檗、防风、黄连、黄芩、樗根白皮、白芍药。外用五倍子傅之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180172, '53CEC790E1C23DA625DA3836234574CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6793, 397, 400104081, NULL, NULL, NULL, NULL, NULL, NULL, '81、肠鸣，属气虚。\n【忌】破气、下、苦寒。诸药俱见前。\n【宜】同大肠虚，加升麻、柴胡以佐之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180173, 'AB2D024AAB2F26A0D8589940D15F76F0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6794, 397, 400104080, NULL, NULL, NULL, NULL, NULL, NULL, '80、虚寒滑泄不禁，属气虚。\n【忌】破气、下、湿润、苦寒。诸药俱见前。\n【宜】补气、升、甘温、酸敛。人参、黄耆、白术、莲肉、升麻、炙甘草、吴茱萸、肉豆蔻、补骨脂、五味子、木瓜、赤石脂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180174, '49FA6EBB04444684606D7A2FB50B01CB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6795, 397, 400104079, NULL, NULL, NULL, NULL, NULL, NULL, '79、虚热便闭不通，属血虚，津液不足。\n【忌】破气、下、燥热、苦温、损津液。郁李仁（损津液）。馀忌药俱见前。\n【宜】生津液、润燥、凉血、益血。五味子、麦门冬、芝麻、麻仁、生蜜、天门冬、肉苁蓉、生地黄、当归、芦荟、炙甘草。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180175, 'AFD545A76617397C3EB079BF97348325', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6796, 397, 400104078, NULL, NULL, NULL, NULL, NULL, NULL, '78、大肠虚（四证）\n【忌】破气、下、燥、热。诸药俱见前。\n【宜】补气、润燥、甘温。人参、黄耆、麦门冬、五味子、白芍药、炙甘草。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180176, '491F02E876CE1E78982FB000839635AA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6797, 397, 400104077, NULL, NULL, NULL, NULL, NULL, NULL, '77、中酒，属胃弱。\n【忌】闭气、升、甘温、燥热、收涩。诸药俱见前。\n【宜】养胃、酸、辛散、淡渗。人参、麦门冬、白扁豆、葛花、五味子、梅酱、橘皮、白豆蔻、黄连、缩砂蜜、白茯苓、泽泻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180177, '41EFF2D8778E2B3ED463A9B6874D54EC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6798, 397, 400104076, NULL, NULL, NULL, NULL, NULL, NULL, '76、反胃，属胃气虚。\n【忌】破气、升、苦寒、甘、燥热。诸药俱见前。\n【宜】补气、降气、和胃、清热、酸敛以制肝。人参、苏子、橘皮、枇杷叶、木瓜、竹茹、麦门冬、芦根汁、石斛、白茯苓、白芍药、梅酱、蔗浆。若因虚寒而得者，加：生姜、术、白豆蔻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180178, '90C7DA67595CB724EA8423D68F9096B7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6799, 397, 400104075, NULL, NULL, NULL, NULL, NULL, NULL, '75、中恶腹中㽲痛，属胃气虚，恶气客之所致。\n【忌】补、酸敛。诸药俱见前。\n【宜】辟恶气、通畅胃气、辛散。龙脑香、檀香、麝香（孕妇忌用）、牛黄、乳香、苏合香、丹砂、雄黄、鬼臼、藿香、橘皮、木香、沉水香、白豆蔻、远志、石菖蒲、干姜、桂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180179, 'B48BB85AB570459A07835F8C48396D16', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6800, 397, 400104074, NULL, NULL, NULL, NULL, NULL, NULL, '74、绞肠痧，属胃气虚，猝中天地邪恶秽污之气，郁于胸腹间，上不得吐，下不得泻，以致肠胃绞痛异常，胸腹骤胀，遍体紫黑，头顶心必有红发，急寻出拔去之，急以三棱鑱针刺委中，挤出热血，可立苏。次用新汲凉水，投入盐两许，恣饮，得吐泻即止。委中穴在两膝下湾横纹中间，两筋之中，刺入一分。\n【忌】温补、敛。诸药俱见前，切忌火酒、生姜、蒜及谷气、米饮、热汤，入口即死。\n【宜】通窍辟恶、辛散、咸寒。龙脑香、苏合香、藿香、檀香、乳香、芒硝、童便。煎药亦宜冷服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180180, '0FCDDB8E4869DE2C3B461B0D6D14918C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6801, 397, 400104073, NULL, NULL, NULL, NULL, NULL, NULL, '73、霍乱转筋，属胃虚，猝中邪恶气及毒气，兼有停滞所致。（转筋与肝经血虚不同。）\n【忌】闭气、滞腻、收敛、温补、大热。诸药俱见前。\n【宜】调气和中、辛散、消导。由于暑，必口渴，或口干、齿燥、口苦、小便短赤：白梅、白扁豆并叶、丝瓜叶、滑石、石膏、甘草、橘皮、香薷、木瓜、石斛、童溺、食盐、泥浆、缩砂蜜、厚朴。由于寒，则小水清白，不渴不热：缩砂蜜、丁香、橘皮、藿香。甚者加：吴茱萸、肉桂。外治用杉木、楠材，煎汤浸洗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180181, '8E2D9DAD08688CA0318C7821F5DAE8A1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6802, 397, 400104072, NULL, NULL, NULL, NULL, NULL, NULL, '72、胃虚呕吐，宜分寒热。忌、宜俱同胃虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180182, '3AB49E7F7B1AE96E8FDE9A7E3F4C7951', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6803, 397, 400104071, NULL, NULL, NULL, NULL, NULL, NULL, '71、胃弱不纳食及不思饮食。\n【忌】同胃虚。\n【宜】同胃虚，仍分寒热治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180183, 'CB21202E4A6BB798276FEEF22B806249', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6804, 397, 400104070, NULL, NULL, NULL, NULL, NULL, NULL, '70、胃虚（七证）\n【忌】下、破气、苦寒、燥热。诸药俱见前。\n【宜】益气、甘平、甘淡、酸。人参、白术、白扁豆、莲肉、石斛、橘皮、白茯苓、木瓜、白芍药。兼寒加：生姜、白豆蔻、缩砂蜜。兼热加：竹茹、枇杷叶、麦门冬、芦根汁、蔗浆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180184, 'B73E4157A55D885F990882E402A3845F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6805, 397, 400104069, NULL, NULL, NULL, NULL, NULL, NULL, '69、病后不得眠，属胆虚。忌、宜俱同胆虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180185, '8916DE8C7535488F0CDCDEFCFB076085', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6806, 397, 400104068, NULL, NULL, NULL, NULL, NULL, NULL, '68、易惊，属胆气虚。\n【忌】破气、升发、燥热。诸药俱见前。\n【宜】补胆气、甘温、辛温、酸平。人参、酸枣仁、甘草、竹叶、当归、白芍药、竹茹、橘皮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180186, '87292CEB9916D13EC5F2E5EF9498655B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6807, 397, 400104067, NULL, NULL, NULL, NULL, NULL, NULL, '67、胆虚（二证）\n【忌】汗、吐、下、苦寒、破气、燥。山栀、瓜蒂、藜芦、盐汤、常山（已上吐）。馀忌药俱见前。\n【宜】甘温、甘平、酸敛，佐以微辛。人参、当归、谷精草、决明子、木贼草、甘草、竹叶、竹茹、白芍药、酸枣仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180187, '07AF4F1F8FCD57D51CCA20DD8E065AF6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6808, 397, 400104066, NULL, NULL, NULL, NULL, NULL, NULL, '66、小肠虚（一证）\n【忌】破气、辛散、燥热。诸药俱见前。\n【宜】补气、甘温、酸温。人参、黄耆、麦门冬、五味子、山茱萸。\n遗尿，属小肠虚，兼肾气虚。\n【忌】同小肠虚。\n【宜】同小肠虚，兼固涩。牡蛎、益智子、龙骨、金樱子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180188, '1EB5C22E9A8378329702B2EC9463B744', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6809, 397, 400104065, NULL, NULL, NULL, NULL, NULL, NULL, '65、畏寒足冷。忌、宜俱同命门虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180189, 'ED1BDE5F6928B5F8C7377877858B92CF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6810, 397, 400104064, NULL, NULL, NULL, NULL, NULL, NULL, '64、肾泄，即五更及黎明泄泻者是也。亦名大瘕泄。属命门真火不足。\n【忌】同命门虚。\n【宜】益气、甘温、酸敛。人参、薯蓣、莲肉、肉豆蔻、砂仁、补骨脂、木香、吴茱萸、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180190, 'AB876415CDDF6C9C42AD9BCD87FDF33F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6811, 397, 400104063, NULL, NULL, NULL, NULL, NULL, NULL, '63、精寒、精薄，属命门火衰，阳气不足。忌、宜俱同阴痿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180191, 'AECDFB1B92F38C4AA2B9570458134FEF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6812, 397, 400104062, NULL, NULL, NULL, NULL, NULL, NULL, '62、阴痿，属命门火衰，下焦虚寒。\n【忌】同命门虚。\n【宜】同命门虚，加：海狗肾、天雄、蛇床子、原蚕蛾、狗阴茎、雀卵、牛膝、白马阴茎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180192, '1385FA8A7D07E5242B91B55F130FFB30', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6813, 397, 400104061, NULL, NULL, NULL, NULL, NULL, NULL, '61、命门虚（四证）\n即元阳真火不足。\n【忌】下泄、破气、发散、辛寒、苦寒、淡渗、燥、补肾水苦寒药。黄檗、知母、生地黄、天门冬（已上补肾水苦寒药）。馀药俱见前。\n【宜】益真阳之气、甘温、咸温、甘热、酸敛。人参、红铅、人胞、鹿茸、白胶、肉苁蓉、菟丝子、枸杞子、覆盆子、五味子、巴戟天、山茱萸、附子、补骨脂、仙茅、阳起石。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180193, 'B295E12C901F4D1D6130AFBD8B23EC3E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6814, 397, 400104060, NULL, NULL, NULL, NULL, NULL, NULL, '60、奔豚，属肾虚，脾家湿邪下传客肾所致。\n【忌】同疝，兼忌燥。诸药俱见前。\n【宜】补气、健脾、辛温、散结。人参、薯蓣、桂、山茱萸、牛膝、蘹香、蛇床子。参用东垣奔豚丸治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180194, 'FA5167D1022A0BF25A6B342FFAC3F911', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6815, 397, 400104059, NULL, NULL, NULL, NULL, NULL, NULL, '59、疝，属肾虚，寒湿邪乘虚客之所致。丹溪谓与肾经绝无相干者，误也。又有先因湿邪为病，后成湿热者，药宜分寒热、先后二途。\n【忌】升、破气、苦寒、湿润。诸药俱见前。\n【宜】补气、通肾气、除湿。又有阴虚有热之人病此，兼宜除热。人参、黄耆、橘核、合欢子、荔枝核、川楝子、牛膝、木瓜、杜仲、萆薢、巴戟天。虚寒而痛，加：桂、蘹香、补骨脂、仙茅。虚热而痛，加：黄檗、车前子。湿盛者，加：术。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180195, 'E03550ACD6F6286FDDEEA9EF6E0FE788', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6816, 397, 400104058, NULL, NULL, NULL, NULL, NULL, NULL, '58、阴窍漏气，属肾气虚不固。肾主纳气，虚则不能纳，故见是证。\n【忌】破气、降、香燥、辛热。苏子、郁金、降香、沉水香、橘皮、通草（已上降）。白豆蔻、木香、香附（已上香燥）。馀忌药俱见前。\n【宜】补真气、酸敛、固涩。人参、五味子、山茱萸、沙苑蒺藜、覆盆子、枸杞子、益智子、远志、龙骨、牡蛎、金樱子、莲须。参用肾虚条内诸药。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180196, '7EC75591E24ABC4599265116798615F6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6817, 397, 400104057, NULL, NULL, NULL, NULL, NULL, NULL, '57、善恐，属肾气虚。肾藏志故也。\n【忌】破气、苦寒。诸药俱见前。\n【宜】补气强志、辛平、甘温、佐以辛香。人参、远志、茯苓、鹿茸、酸枣仁、柏子仁、石斛、沉水香。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180197, '1488056EF546C0AA438F53EEB5E8D264', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6818, 397, 400104056, NULL, NULL, NULL, NULL, NULL, NULL, '56、下消，属肾阴虚，火伏下焦。\n【忌】同肾虚。\n【宜】清热，及峻补真气、润、酸敛。诸药同肾虚，宜以黄檗、五味子、生地黄、天麦门冬、人参为君；石斛、牛膝、知母、人乳、童便为臣；地骨皮、青蒿、侧柏叶为佐。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180198, '7AA09BDCB539493380E50BDEA8169AAF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6819, 397, 400104055, NULL, NULL, NULL, NULL, NULL, NULL, '55、齿浮、真牙摇动，及下龈软或齿衄，属肾虚有热。\n【忌】同肾虚，又忌当归、芎。\n【宜】益阴、凉血、固肾。诸药略同肾虚，应以地黄、黄檗、五味子为君；桑椹、牛膝、沙苑蒺藜、鹿茸、天门冬为臣；龙骨、牡蛎为使。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180199, 'C71EDCBB5128E0BEBC667E10B851ADD0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6820, 397, 400104054, NULL, NULL, NULL, NULL, NULL, NULL, '54、精塞水窍不通，属房欲不竟，或思欲不遂，或惧泄忍精，或老人气不足以送精出窍。\n【忌】破气、下、利小便、燥热。诸药俱见前。\n【宜】行败精，壮实人宜兼泄火。老人宜兼补气血。外治用吮法。牛膝、生地黄、当归、桃仁、红花、车前子、鹿角霜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180200, 'BE345B380879189B5CBA8285F621C17C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6821, 397, 400104053, NULL, NULL, NULL, NULL, NULL, NULL, '53、五淋，属肾虚兼有湿热。\n【忌】同肾虚。\n【宜】同肾虚，加清湿热。茯苓、黄檗、车前子、石斛、萆薢、薏苡仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180201, '00F79A457B669DEEC08E32EEDEA5D92E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6822, 397, 400104052, NULL, NULL, NULL, NULL, NULL, NULL, '52、伤精白浊，属房劳过度，以致精伤流出，似白浊证。\n【忌】利小便、燥、辛热。诸药俱见前。\n【宜】同肾虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180202, '47119AE3E39338932535B8CD049C58D1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6823, 397, 400104051, NULL, NULL, NULL, NULL, NULL, NULL, '51、溺血、血淋，属肾虚有火，热伤血分。\n【忌】同肾虚。\n【宜】同肾虚，加：侧柏叶、阿胶、茅根、韭白、干地黄、戎盐、蒲黄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180203, 'B27DF524EA50E3FA19A8B45FC8F591A8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6824, 397, 400104050, NULL, NULL, NULL, NULL, NULL, NULL, '50、溺有馀沥，属气虚。\n【忌】同肾虚。\n【宜】同肾虚，以五味子、黄檗、人参为君，加菟丝子、覆盆子为臣，益智为佐。如觉平日肺家有热，或咳嗽有火者，忌人参，用沙参。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180204, 'E217A8E23946E1A415172F14A0FA14D7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6825, 397, 400104049, NULL, NULL, NULL, NULL, NULL, NULL, '49、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180205, 'FCF2B6947630A23B8427E766F81601B7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6826, 397, 400104048, NULL, NULL, NULL, NULL, NULL, NULL, '48、小便短涩、热赤频数，属肾虚有火。忌、宜俱同肾虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180206, '5607599427AC4C57D16512841B9714FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6827, 397, 400104047, NULL, NULL, NULL, NULL, NULL, NULL, '47、梦遗泄精，属肾虚有火。\n【忌】同肾虚。\n【宜】滋阴、生津补血、除热、酸敛、佐以涩精。莲花蕊、生甘草、石斛、缩砂蜜、龙骨、覆盆子、鱼胶、莲肉、牡蛎、远志、韭子、桑螵蛸。馀药同肾虚条。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180207, '74C52B0E3291855B62E0372388FA7C12', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6828, 397, 400104046, NULL, NULL, NULL, NULL, NULL, NULL, '46、传尸劳。\n【忌】同肾虚。\n【宜】除热益阴、杀劳虫，兼清镇。诸药同肾虚，加：鬼臼、干漆、漆叶、芦荟、象胆、獭肝、胡黄连。忌、宜俱同肾虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180208, 'FE1FF27784A4C4C0827AB5ACD3ADB30C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6829, 397, 400104045, NULL, NULL, NULL, NULL, NULL, NULL, '45、骨蒸潮热，属精血虚极，以致阳无所附，火空上炎。忌、宜俱同肾虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180209, '2170A46662D7DB37897A201414504165', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6830, 397, 400104044, NULL, NULL, NULL, NULL, NULL, NULL, '44、骨乏无力，属阴精不足，肾主骨故也。忌、宜俱同肾虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180210, 'F0225070A766CF009F2D847D057E3787', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6831, 397, 400104043, NULL, NULL, NULL, NULL, NULL, NULL, '43、肾虚腰痛，属精气虚。\n【忌】破气、燥、热。诸药俱见前。\n【宜】同肾虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180211, '607D339803841EB70202F24A83F5C1E0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 11:49:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6832, 397, 400104042, NULL, NULL, NULL, NULL, NULL, NULL, '42、肾虚（十八证）\n即肾水真阴不足。\n【忌】升、破气、利水、温热、辛燥、补命门相火。仙茅、巴戟天、葫芦巴、人参、补骨脂、鹿茸、人胞（已上补命门相火）。馀忌药俱见前。\n【宜】滋阴、润、生精补血、除热、甘寒、酸寒、苦寒、咸寒。地黄、枸杞子、牛膝、人乳、肉苁蓉、柏子仁、胡麻、沙苑蒺藜、杜仲、续断、天门冬、麦门冬、五味子、山茱萸、薯蓣、牡丹皮、菟丝子、车前子、地骨皮、知母、黄柏、鳖甲、青蒿、童便。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180212, '3DA9C781195D17EAA200C57EA0595B8C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6833, 397, 400104041, NULL, NULL, NULL, NULL, NULL, NULL, '41、息贲，属肺气虚，痰热壅结所致。\n【忌】破气、辛热、补敛。诸药俱见前。\n【宜】降气、清热开痰、佐以散结。橘皮、白豆蔻、白芥子、射干、桔梗、旋覆花、桑白皮。参用东垣息贲丸治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180213, 'E42B5878D2899A189960EC50A5D58FC4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6834, 397, 400104040, NULL, NULL, NULL, NULL, NULL, NULL, '40、龟胸，属肺热有痰。忌、宜俱同齁喘咳嗽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180214, '714EA7D7D7D72C384DC18CED840FA747', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6835, 397, 400104039, NULL, NULL, NULL, NULL, NULL, NULL, '39、肺痿，属肺气虚有热。忌、宜俱同肺虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180215, '1BA7DAE59B5E4A6131486990FC468825', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6836, 397, 400104038, NULL, NULL, NULL, NULL, NULL, NULL, '38、咽喉燥痛，属水涸火炎，肺热之极。此证法所难治。忌、宜俱同咳嗽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180216, '42ADD0A89DC447B9087A55B85D49CD7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6837, 397, 400104037, NULL, NULL, NULL, NULL, NULL, NULL, '37、声哑，属肺热甚。忌、宜俱同咳嗽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180217, 'F62081F66EBDF5A2AF44910139D110AE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6838, 397, 400104036, NULL, NULL, NULL, NULL, NULL, NULL, '36、咳嗽吐血痰，属肺热甚。\n【忌】升、破气，复忌补气、破血、辛燥、温热、收涩。诸药俱见前。\n【宜】降气清热、润肺生津液、凉血益血、甘寒、甘平、咸寒、佐以苦寒。郁金、生地黄、蒲黄、侧柏叶、茅根、剪草、白及、阿胶、童便、知母。馀药肺虚条内参用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180218, '1537E64C32A253398AC7C3F331BD7E46', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6839, 397, 400104035, NULL, NULL, NULL, NULL, NULL, NULL, '35、齁喘，属肺虚有热，因而痰壅。\n【忌】破气、升、发散、收涩。诃子、亚芙蓉、粟壳（已上收涩）。馀忌药俱见前。\n【宜】降气、消痰、辛凉、甘寒、苦平。苏子、枇杷叶、贝母、桑根白皮、栝楼根、竹沥、天门冬、麦门冬、百部、百合、薄荷、马兜铃、款冬花、沙参、前胡、白前、射干。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180219, '5B21B033F708E15258CBFE7C2CF16578', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6840, 397, 400104034, NULL, NULL, NULL, NULL, NULL, NULL, '34、肺虚（七证）\n【忌】补气、升散、辛燥、温热。诸药俱见前。\n【宜】清热、降气、酸敛、润燥。天门冬、麦门冬、苏子、枇杷叶、贝母、沙参、百部、百合、桑白皮、五味子、杏仁、五倍子、蜜、梨、柿。无热者加：人参。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180220, '85F7AEEE4490A7CB7016D6D89DD278CA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6841, 397, 400104033, NULL, NULL, NULL, NULL, NULL, NULL, '33、痞气，属脾气虚及气郁所致。\n【忌】破气、下、湿润、苦寒。诸药俱见前。\n【宜】健脾，兼散结滞、甘温、辛香。人参、白芍药、橘红、缩砂蜜、藿香、吴茱萸、谷糵、麦糵、红曲、香附、木香。参用东垣痞气丸治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180221, '68637CA8B4F8B1F4AB706497F264696E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6842, 397, 400104032, NULL, NULL, NULL, NULL, NULL, NULL, '32、脾虚腹痛，按之则止，属血虚。\n【忌】破气、破血、香燥、苦寒。诸药俱见前。\n【宜】益气补血、甘温、酸平。人参、炙甘草、龙眼肉、大枣、酸枣仁、石斛、麦门冬、白芍药。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180222, '6F84A4310F4C96E18153638BCE2CA095', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6843, 397, 400104031, NULL, NULL, NULL, NULL, NULL, NULL, '31、倦怠嗜卧，属脾气不足。\n【忌】破气、消导、苦寒。诸药俱见前。\n【宜】补气，兼健脾、甘温、辛香。人参、白术、黄耆、茯苓、薯蓣、炙甘草、谷糵、白扁豆、缩砂蜜、橘皮、藿香、白豆蔻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594180223, '778C36D5B856E79429E0619B1D29780A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6844, 397, 400104030, NULL, NULL, NULL, NULL, NULL, NULL, '30、健忘，属气血两虚。\n【忌】升、燥热，复忌苦寒、辛散。诸药俱见前。\n【宜】益脾阴，兼补气，酸敛、甘温、甘寒、辛平以通窍。酸枣仁、白芍药、五味子、人参、炙甘草、黄耆、龙眼肉、柏子仁、麦门冬、丹参、茯苓、茯神、石菖蒲、远志。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184261, '63613687D3D089790F026CF1EE64E607', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6845, 397, 400104029, NULL, NULL, NULL, NULL, NULL, NULL, '29、脾泄，属气虚。\n【忌】破气、下、消导、苦寒。诸药俱见前。\n【宜】温中补气、升清、甘温、甘平，佐以辛香。人参、术、炙甘草、薯蓣、莲肉、白扁豆、茯苓、车前子、白芍药、升麻、柴胡、肉豆蔻、缩砂蜜、橘皮、木香、丁香、藿香、白莱菔。兼有湿及痰，经年不愈，粪色白者，须服九制松脂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184262, '12DCB2791CC4C5920930502C83464F63', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6846, 397, 400104028, NULL, NULL, NULL, NULL, NULL, NULL, '28、噎膈，属气血两虚，由于血液衰少，而非痰气壅逆所成。\n【忌】破气、升，复忌下、消导、燥、苦寒、辛热。诸药俱见前。\n【宜】降、清热润燥，甘温、甘平以益血，略佐辛香以顺气。苏子、橘红、枇杷叶、人参、白芍药、酸枣仁、龙眼肉、人乳、牛乳、蔗浆、梨汁、韭汁、芦根汁、姜汁、白豆蔻仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184263, '8B72CDD5E05B25D16C3995CC060BD891', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6847, 397, 400104027, NULL, NULL, NULL, NULL, NULL, NULL, '27、脾虚中满，属脾气虚，兼脾阴虚。\n【忌】破气、下、消导、利水、甘。饴糖、大枣、蜜、甘草（已上甘）。馀忌药俱见前。\n昼剧夜静，属脾气虚。【宜】补气键脾、甘温、淡渗，佐以辛香。人参、二术、白芍药、桑白皮、茯苓、车前子、橘红、姜皮、藿香、缩砂蜜。无热证者佐以桂。\n夜剧昼静，属脾阴虚。【宜】补脾阴，兼制肝清热、甘平、酸寒、淡渗。酸枣仁、白芍药、石斛、白扁豆、莲肉、橘皮、山药、苏子、五味子、木瓜、桑白皮、车前子、茯苓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184264, '816E9B3A83F57A85684F23A2CCD7BB85', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6848, 397, 400104026, NULL, NULL, NULL, NULL, NULL, NULL, '26、水肿，属脾气虚。\n【忌】破气、下泄、湿润、咸、苦寒。食盐、商陆（已上咸）。馀忌药俱见前。\n【宜】补脾益气、燥湿、利水、辛香、甘温，佐以淡渗。人参、二术、橘皮、薯蓣、木瓜、薏苡仁、桑白皮、茯苓、赤小豆、香薷、乌蠡鱼、车前子、猪苓、泽泻、姜皮、乌芋、缩砂蜜、通草。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184265, 'A684B4BEC20AEE05F6ED8C7E3573B075', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6849, 397, 400104025, NULL, NULL, NULL, NULL, NULL, NULL, '25、停饮，为恣饮汤水，或冷茶、冷酒所致。\n【忌】下、酸敛、湿润、滞腻。诸药俱见前，加忌栝楼根及仁、桃仁、郁李仁。\n【宜】健脾利水、淡渗，兼辛散。人参、白术、半夏、茯苓、橘皮、泽泻、猪苓、木通、桑白皮、旋覆花、紫苏、白豆蔻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184266, '2524223AF1092D303DA6968096A61A6C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6850, 397, 400104024, NULL, NULL, NULL, NULL, NULL, NULL, '24、伤食，必恶食。\n【忌】润湿、苦寒。当归、肉苁蓉、锁阳、天门冬、地黄、知母、玄参、猪脂、茄子、酒、糟、面食（已上湿润）。苦寒诸药见前。\n【宜】健脾消导、甘温、辛香。橘皮、薯蓣、莲肉、白扁豆、白芍药、白茯苓、草果、山查、麦芽、草豆蔻、缩砂蜜、谷糵。如腹痛大便不通，宜下之：枳实、槟榔、厚朴、大黄。元气虚人不可下，宜加：参、术。伤肉食，轻者宜蒜、山查，兼黄连；重者宜矾红、枣肉为丸。服二钱，不可过，终身忌荞麦。伤面食，宜炒莱菔子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184267, 'D1EA061D44AA0653A8CA7A26CD6BB850', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6851, 397, 400104023, NULL, NULL, NULL, NULL, NULL, NULL, '23、饮食不消化，属脾气虚。\n【忌】破气、消导克伐、苦寒、复忌燥。草果、枳实、槟榔、蓬荗、三棱、绿矾（已上消导）。馀忌药见前。\n【宜】益真气、香、甘温、甘辛。同脾虚，加：谷糵、麦糵、肉豆蔻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184268, '52C95F90BE225DFA7906AE07B09D9A1B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6852, 397, 400104022, NULL, NULL, NULL, NULL, NULL, NULL, '22、饮食劳倦、伤脾发热。\n【忌】破气、发散、下、苦寒。诸药俱见前。\n【宜】补中益气、甘温、升、酸。人参、黄耆、术、炙甘草、大枣、柴胡、升麻、石斛、麦门冬、橘红、白芍药、酸枣仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184269, '0ACE84458DEC7D883072216A8F21E2E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6853, 397, 400104021, NULL, NULL, NULL, NULL, NULL, NULL, '21、脾虚（十二证）\n【忌】下、降泄、破气、苦寒。诸药俱见前。\n【宜】甘温，佐以辛香、酸平。人参、大枣、黄耆、薯蓣、炙甘草、莲肉、白茯苓、白扁豆、缩砂蜜、橘红、白豆蔻、藿香、木瓜、白芍药、酸枣仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184270, '76A52C2F2FBAEDBE54D5D4C044F7FCFB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6854, 397, 400104020, NULL, NULL, NULL, NULL, NULL, NULL, '20、肥气，属气血两虚，肝气不和，逆气与瘀血相并而成。\n【忌】破气、下、苦寒。诸药俱见前。\n【宜】和肝散结气，兼行气血凝滞、甘温、甘平。川芎、当归、沉香、干姜、肉桂、橘皮、红花、郁金、延胡索、香附、山查、赤芍药、红曲、砂仁。参用东垣肥气丸治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184271, '07A2D03BD124D6242070B84A33A0972D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6855, 397, 400104019, NULL, NULL, NULL, NULL, NULL, NULL, '19、目黑黯、眩晕，属血虚，兼肾水真阴不足。\n【忌】破气、燥、热、辛温。诸药俱见前。\n【宜】养血补肝、清热、甘寒、甘平、酸寒、苦寒。生地黄、枸杞子、甘菊花、当归、薯蓣、五味子、白蒺藜、甘草、山茱萸、白芍药、天门冬、黄檗。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184272, '05B19445B6ACEC9EEE82103A080FF65A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6856, 397, 400104018, NULL, NULL, NULL, NULL, NULL, NULL, '18、偏头痛，属血虚、肝家有热，不急治，久之必损目。\n【忌】升、燥、热、苦寒。诸药俱见前。\n【宜】养血清虚热、甘寒、酸寒、辛寒。生地黄、天门冬、甘菊花、白芍药、当归、川芎、乌梅、炙甘草、土茯苓、金银藤、黑豆。有实火者可加：黄芩（酒炒）、大黄（酒蒸）、芎、雨前茶、石膏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184273, '3C617CC7E78E61E59A3EC1F7BD1E15CB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6857, 397, 400104017, NULL, NULL, NULL, NULL, NULL, NULL, '17、少腹连阴作痛、按之则止，属足厥阴经血虚。\n【忌】同角弓反张。\n【宜】同角弓反张，加：白胶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184274, '54A8D2287E255ABBD80FC85E6B62ED7E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6858, 397, 400104016, NULL, NULL, NULL, NULL, NULL, NULL, '16、亡血过多，角弓反张，属肝血虚有热。\n【忌】风燥、升、破气、下。诸药俱见前。\n【宜】补血清热、甘寒、甘温、酸寒、咸寒、辛润。当归、生地黄、白芍药、炙甘草、牛膝、麦门冬、牡丹皮、甘菊花、童便。有汗加：人参、黄耆、五味子、酸枣仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184275, 'A8E30E20A41235F7AA7FE39EED2E7590', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6859, 397, 400104015, NULL, NULL, NULL, NULL, NULL, NULL, '15、目翳，属肝热，兼肾水不足。\n【忌】破气、升、燥热、苦寒。诸药俱见前。\n【宜】补肝血、除热、退翳。甘菊花、生地黄、决明子、石决明、沙苑蒺藜、女贞实、青羊胆、羚羊角、犀角、空青、黄连、天龙、伏翼粪、木贼、谷精草、蜜蒙花、人爪、蝉蜕、玛瑙、石蟹、珊瑚、真珠、琥珀、马目毒公、贝子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184276, 'D051D6EF1FFF12A9DB80D1CBBB65FD42', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6860, 397, 400104014, NULL, NULL, NULL, NULL, NULL, NULL, '14、目昏，属肝血虚有热，兼肾水真阴不足。\n【忌】同前目光短。\n【宜】同目光短，加：黄檗、羚羊角。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184277, 'EC56F79221E492052273A3EC81A0A6FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6861, 397, 400104013, NULL, NULL, NULL, NULL, NULL, NULL, '13、目光短，属肝血虚，及肾水真阴不足。\n【忌】破气、升、燥、热。诸药俱见前。\n【宜】补肝兼滋肾、甘温益血、甘寒除热。甘枸杞、生地黄、甘菊花、沙苑蒺藜、谷精草、五味子、决明子、天门冬、麦门冬。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184278, 'E85F60D9083A90B5D4F9D8747CA94C54', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6862, 397, 400104012, NULL, NULL, NULL, NULL, NULL, NULL, '12、转筋，属血虚。\n【忌】下，复忌升、燥热、闭气、苦寒、破气。二术、黄耆、银杏、猪脂、羊肉、面（已上闭气）。馀忌药俱见前。\n【宜】酸、辛、甘平。木瓜、牛膝、当归身、白芍药、石斛、续断、炙甘草、陈皮、缩砂蜜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184279, '7379FAB83C5DF185C289CF3DC3C03458', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6863, 397, 400104011, NULL, NULL, NULL, NULL, NULL, NULL, '11、胸胁痛，属肝血虚，肝气实，因而上逆。\n【忌】敛、补气、破血。诸药俱见前。\n【宜】降气、养血和肝、辛甘、平缓。苏子、郁金、番降香、川通草、当归、生地黄、橘皮、甘草、白芍药、续断、鹿角胶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184280, 'E30C0B03580FADE6AAB0CAC02220E1D1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6864, 397, 400104010, NULL, NULL, NULL, NULL, NULL, NULL, '10、肝虚（十证）\n【忌】收敛、破气、升散、苦寒、下。诸药俱见前。\n【宜】辛散、甘缓。当归、陈皮、生姜、地黄、甘菊、甘草、胡麻、谷精草、决明子、刺蒺藜、羊牛兔肝。因郁而虚者，加：细辛、木香、缩砂蜜、沉木香、川芎、香附。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184281, '0E63E72EA289C1F29CA243BE92F73646', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6865, 397, 400104009, NULL, NULL, NULL, NULL, NULL, NULL, '9、伏梁，属心经气血虚，以致邪留不去。\n【忌】破血、汗、下。三棱、蓬荗、姜黄、虻虫、䗪虫、红蓝花、水蛭、桃仁（已上破血）。汗、下诸药俱见前。\n【宜】活血、凉血、散热通结、辛咸。郁金、五灵脂、乳香、没药、当归、延胡索、赤芍药、远志、菖蒲、茯神、牡蛎。参用东垣伏梁丸治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184282, '52A2CCAC2CCC723414047BE5A30D1005', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6866, 397, 400104008, NULL, NULL, NULL, NULL, NULL, NULL, '8、盗汗，属心血虚。汗者，心之液也。\n【忌】破气、辛散、燥热。诸药俱见前。\n【宜】补敛、清虚热、甘酸、甘平、甘寒、苦寒、咸寒。生地黄、当归、茯神、龙眼肉、黄耆、五味子、白芍药、酸枣仁、黄芩、黄檗、黄连、牡蛎。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184283, 'FAEF925DDDBFEA0F4FC111B188DB7CF5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6867, 397, 400104007, NULL, NULL, NULL, NULL, NULL, NULL, '7、心澹澹动。忌、宜俱同心虚。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184284, '93CFEE2D89D41B8E935AD8E656291208', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6868, 397, 400104006, NULL, NULL, NULL, NULL, NULL, NULL, '6、怔忡，属心血不足。忌、宜俱同心虚。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184285, '06F22C044E5BB069AF65EE5A9416EC40', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6869, 397, 400104005, NULL, NULL, NULL, NULL, NULL, NULL, '5、不得眠，属心血虚有热。\n【忌】升、辛燥、热。诸药俱见前。\n【宜】敛、养阴血、清热。酸枣仁、五味子、龙眼肉、丹参、芍药、人参、石斛、竹叶、生地黄、茯神、远志、黄连、玄参、麦门冬、辰砂六一散、竹茹、木通、生甘草。\n心烦，属心家有热。\n【忌】升、破气、燥热。诸药俱见前。\n【宜】清热、生津液、甘寒、甘平、辛酸。参用不得眠中诸药：竹叶、麦门冬、生甘草、石斛、丹参、龙眼肉、生地黄、玄参、沙参、茯神、远志、知母、酸枣仁。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184286, '788172BA88DA409868762F771FE54857', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6870, 397, 400104004, NULL, NULL, NULL, NULL, NULL, NULL, '4、癫痫，属心气虚有热。\n【忌】补敛、升。诸药俱见前。\n【宜】降、清热、豁痰。诸药见惊邪条，加：贝母、丹参、钓藤钩、郁金、铅丹、神水、白矾。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184287, 'C714E6E6A9E35A21A1F585A722B4042E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6871, 397, 400104003, NULL, NULL, NULL, NULL, NULL, NULL, '3、惊邪，属心气虚。\n【忌】升、破气。诸药俱见前。\n【宜】降、清热、豁痰、平。《经》曰：惊者平之。犀角、丹砂、琥珀、真珠、龙齿、金箔、牛黄、代赭石、羚羊角、麦门冬、石斛、桔梗、胆星、麝香、竹沥、天竺黄、远志、鬼臼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625700594184288, 'D624BA592F28AAAE095C30AD81377D13', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:22:16', 1, 'admin', '2024-12-23 13:47:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6872, 397, 400104142, NULL, NULL, NULL, NULL, NULL, NULL, '142、赤白游风，属血热，热则生风，故善游走，俗名火丹。小儿多患此，大人亦时有之。\n【忌】同三焦实。\n【宜】清热、凉血，兼行血、辛寒、甘寒、苦寒、咸寒。生地黄、黄连、黄檗、生甘草、牡丹皮、蒲黄、红蓝花、连翘、玄参、鼠粘子、牛膝、蓝汁、苎根、童便、赤芍药。宜兼外治，砭出热血，及用漆姑草、慎火草捣烂敷之，即易愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516293, '722B33647FF7A0B12AB8379A88B0B107', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6873, 397, 400104141, NULL, NULL, NULL, NULL, NULL, NULL, '141、头面赤热，属上焦火升。\n【忌】同三焦实。\n【宜】降、清热、甘缓，佐以酸敛。苏子、枇杷叶、天门冬、麦门冬、玄参、薄荷、栝楼根、梨、柿、蔗、童便、白芍药、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516294, '2269BA384FA8D2ED91A7BC9F6032ED81', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6874, 397, 400104140, NULL, NULL, NULL, NULL, NULL, NULL, '140、喉痹，即缠喉风。属少阳相火、少阴君火并炽。《经》曰：一阴一阳结为喉痹。一阴者，少阴君火也。一阳者，少阳相火也。\n【忌】同三焦实。\n【宜】辛散，佐以苦寒、咸寒。急则有针法、吹法、吐法。鼠粘子、山豆根、射干、黄连、黄檗、知母、玄参、童便、苏子、麦门冬、贝母、甘草、生犀角、山慈菇、苦桔梗、续随子。急治用胆矾、朴硝、牛黄为末，和匀吹入喉中。又法：用明矾三钱、巴豆七粒去壳，同矾煅，矾枯，去巴豆，即取矾为细末，吹入喉中，流出热涎即宽。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516295, 'E9F523CDB06712BEB7363E1086B7C59A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6875, 397, 400104139, NULL, NULL, NULL, NULL, NULL, NULL, '139、三焦实（三证）\n【忌】补敛、升、燥热。诸药俱见前。\n【宜】降、清热、调气、甘寒、苦寒、咸寒。苏子、麦门冬、知母、黄檗、玄参、山栀、黄芩、黄连、童便。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516296, 'AF3481E3EB94ECE8EE5A225FBBA284C6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6876, 397, 400104138, NULL, NULL, NULL, NULL, NULL, NULL, '138、膀胱实（一证）\n【忌】燥、热、收涩。诸药俱见前。\n【宜】润、淡渗。知母、黄檗、车前子、木通、瞿麦、滑石、茯苓、猪苓、泽泻。\n癃闭，属膀胱实热。\n【忌】破气、发散、燥、热。如属水液不足，兼忌利小便。诸药俱见前。\n【宜】同膀胱实，佐以升提。升麻、柴胡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516297, 'EE6842BD293A3B5419D211540044DD39', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6877, 397, 400104137, NULL, NULL, NULL, NULL, NULL, NULL, '137、肠痈，属大肠实火。\n【忌】同肠风下血。\n【宜】下、苦寒、解毒。大黄、白药子、白芷、白及、白敛、连翘、忍冬藤、天明精、甘草、黄耆、生地黄、明矾、黄蜡、生蜜（已上三味作丸）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516298, 'D1DEE0ECB5AA4E253E51EB65D18A299A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6878, 397, 400104136, NULL, NULL, NULL, NULL, NULL, NULL, '136、脏毒，属血热。\n【忌】同肠风下血。\n【宜】同肠风下血，加：忍冬、麦门冬、倍加地榆、蒲黄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516299, '41E2D62FD2D7601E2B3D3C1330F33243', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6879, 397, 400104135, NULL, NULL, NULL, NULL, NULL, NULL, '135、肠风下血，属大肠湿热。\n【忌】下、燥、热。诸药俱见前。\n【宜】清热凉血、兼升、甘寒、苦寒。生地黄、槐花、地榆、黄连、黄芩、荆芥、防风、甘草、红曲、白芍药、侧柏叶、白头翁、蒲黄、鸡子、葛谷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516300, '9879B22157B0790B38AB0902ACD0B778', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6880, 397, 400104134, NULL, NULL, NULL, NULL, NULL, NULL, '134、便硬闭。\n【忌】同大肠实。\n【宜】同大肠实，加：芒硝、猪胆、槟榔、郁李仁、石蜜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516301, '1FFFB1B9D9DF8E84316537D89FBC4562', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6881, 397, 400104133, NULL, NULL, NULL, NULL, NULL, NULL, '133、大肠实（四证）\n【忌】补敛、燥、热。诸药俱见前。\n【宜】润下、苦寒、辛寒。生地黄、麻仁、桃仁、黄连、黄芩、槐花、大黄、石膏、知母、枳壳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516302, '45D3FB2CE929EC0613BA08DD90B2B869', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6882, 397, 400104132, NULL, NULL, NULL, NULL, NULL, NULL, '132、吞酸，属胃火。\n【忌】同胃实。\n【宜】同嘈杂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516303, 'F5E1B6AD17CD5C76C33560ABAA611BCA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6883, 397, 400104131, NULL, NULL, NULL, NULL, NULL, NULL, '131、呕吐，属胃火者，必面赤，小便短赤或涩，大便多燥，口苦或干渴。\n【忌】同胃实。\n【宜】同胃实，加：枇杷叶、竹茹、木瓜、芦根、橘皮、通草、白茯苓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516304, 'A42522357B4BBD0D50E8822A5CF34175', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6884, 397, 400104130, NULL, NULL, NULL, NULL, NULL, NULL, '130、口淡，属胃热。忌、宜俱同口臭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516305, '2828759DDFB5473483686ED76D90CC8E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6885, 397, 400104129, NULL, NULL, NULL, NULL, NULL, NULL, '129、嘈杂，属胃火。\n【忌】同口臭。\n【宜】同口臭，略兼消导。山查、麦芽、橘红、神曲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516306, '1BA206FF85B38F8D0215D53933878138', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6886, 397, 400104128, NULL, NULL, NULL, NULL, NULL, NULL, '128、口臭，数欲饮食，属胃火。\n【忌】同胃实。\n【宜】清热降火、苦寒、甘寒、辛寒。黄连、青黛、连翘、麦门冬、石斛、芦根汁、竹叶、石膏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516307, '9DC28D38A192314EEBB96C10CAA9224A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6887, 397, 400104127, NULL, NULL, NULL, NULL, NULL, NULL, '127、谵语发狂、发斑，弃衣而走，登高而歌，属胃家邪热实。\n【忌】同胃实。\n【宜】同胃实。如大便结者，加芒硝，亟下之；发斑者，加鼠粘子、玄参、栝楼根，多用石膏为君。便结亦加大黄下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516308, '6DEEAFDA441BC14810ACC9EEC696755A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6888, 397, 400104126, NULL, NULL, NULL, NULL, NULL, NULL, '126、胃实（六证）\n【忌】升、补敛、辛温、燥、热、湿润。诸药俱见前。\n【宜】下。如邪未结，宜清热发散、苦寒、辛寒、甘寒。大黄、枳实、知母、石膏、葛根、竹叶、大青、小青、青黛、麦冬、甘草。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516309, '3DC726321C0A4EA4838D4389607C9063', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6889, 397, 400104125, NULL, NULL, NULL, NULL, NULL, NULL, '125、鼻渊，属胆移热于脑。\n【忌】辛温、燥、热。诸药俱见前。\n【宜】清热、补脑、甘寒、甘平、佐以辛寒。天门冬、甘菊花、生地黄、沙苑蒺藜、山茱萸、沙参、薄荷、柴胡、辛夷、黄芩、玄参、知母。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516310, '2CE25981274DF5F7B2DFD027BF20AE0F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6890, 397, 400104124, NULL, NULL, NULL, NULL, NULL, NULL, '124、口苦耳聋胁痛，往来寒热。\n【忌】同胆实。\n【宜】用仲景小柴胡汤，随所见兼证加减。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516311, '8B526C4F17747B5F2EF6134E766A633F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6891, 397, 400104123, NULL, NULL, NULL, NULL, NULL, NULL, '123、胆实（二证）\n【忌】汗、吐、下。诸药俱见前。\n【宜】和解、辛寒、甘寒、苦寒、辛温。柴胡、黄芩、半夏、生姜、甘草、橘皮、龙胆草。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516312, 'B0906578986D90BE0DCE8BE1CA0088B0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6892, 397, 400104122, NULL, NULL, NULL, NULL, NULL, NULL, '122、小肠实（一证）\n【忌】敛涩、补气。诸药俱见前。\n【宜】通利、淡渗、苦寒、甘寒、咸寒。车前子、白茯苓、木通、生甘草、黄檗、知母、黄芩、黄连、牛膝、麦门冬、生地黄、童溺。\n小水不利，及赤、或涩痛尿血。忌、宜俱同小肠实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516313, 'B648390B1690AD05A37D7221C8B9CB69', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6893, 397, 400104121, NULL, NULL, NULL, NULL, NULL, NULL, '121、水窍涩痛，属命门实火。\n【忌】同命门实。\n【宜】清热、利窍、甘寒、苦寒、咸寒，佐以淡渗。黄檗、知母、车前子、生地黄、天门冬、生甘草、黄芩、牛膝、麦门冬、童便、茯苓、木通。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516314, 'ABFB1F2573900A51B11FA8B73CE70320', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6894, 397, 400104120, NULL, NULL, NULL, NULL, NULL, NULL, '120、强阳不倒，属命门火实，孤阳无阴所致。此证多不治。\n【忌】同命门实。\n【宜】同命门实，加：五味子、童便、生地黄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516315, 'A406D217B9DFF762DFD6AE60D47F7916', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6895, 397, 400104119, NULL, NULL, NULL, NULL, NULL, NULL, '119、命门实（二证）\n【忌】补气、温、热。诸药俱见前。\n【宜】苦寒、甘寒、咸寒。黄檗、知母、玄参、天门冬、麦门冬、牡丹皮、车前子、木通、泽泻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516316, 'F99676E7FAFAE7DD6DB1816D98B5CFF3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6896, 397, 400104118, NULL, NULL, NULL, NULL, NULL, NULL, '118、肾无实，故无泻法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516317, '94C62E3B78ACDDBB92B43061E23EB8D6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6897, 397, 400104117, NULL, NULL, NULL, NULL, NULL, NULL, '117、上消，属肺家实火，及上焦热。\n【忌】同肺实。\n【宜】降气、清热、补肺、生津、甘寒、苦寒、酸寒、辛寒。苏子、麦门冬、枇杷叶、桑白皮、桔梗、百部、百合、黄芩、天门冬、沙参、黄连、栝楼根、葛根、知母、玄参、石膏、甘草、五味子、白芍药、䈽竹叶、芦根、冬瓜、人乳、天酒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516318, '6A0B401962D9218A4C69C18BB60B940E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6898, 397, 400104116, NULL, NULL, NULL, NULL, NULL, NULL, '116、喉癣，属肺热。\n【忌】同肺热。\n【宜】同肺实，加：鼠粘子、玄参、射干。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516319, 'E8C454D4C42B395F955EA8E16C092592', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6899, 397, 400104115, NULL, NULL, NULL, NULL, NULL, NULL, '115、吐脓血、血痰，咳嗽嗽血，属肺家火实热甚。此正 “邪气胜则实” 之谓。\n【忌】同肺实。\n【宜】清热降气、凉血、豁痰。童便、苏子、枇杷叶、桑白皮、麦门冬、剪草、蒲黄、生地黄、天门冬、百部、桑黄、百合、薏苡仁、甘草、贝母、白芍药、白及、梧梗、款冬花、紫菀。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516320, 'A83FC472D988C380A907A782087AB782', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6900, 397, 400104114, NULL, NULL, NULL, NULL, NULL, NULL, '114、肺胀闷，属肺热。\n【忌】同肺实。\n【宜】同肺实，并参用肺痈诸药。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516321, '6ED2A05339216A3312AE4A41F2FC2AAF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6901, 397, 400104113, NULL, NULL, NULL, NULL, NULL, NULL, '113、肺痈，属肺热极。\n【忌】同肺实。\n【宜】清热、消痰、降火、解毒散结、甘寒、辛寒。桑白皮、桑黄、黄芩、贝母、栝楼根、薏苡仁、蕺菜、虎耳草、鼠粘子、连翘、甘草、败酱草、百年腌芥菜汁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516322, '36E38AD30C52147A79C8AC444A895C51', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6902, 397, 400104112, NULL, NULL, NULL, NULL, NULL, NULL, '112、声重痰稠，属肺热。\n【忌】同肺实。\n【宜】同肺实，加：薄荷、竹沥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516323, '7002067F116E9FC04071D791E24F0932', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6903, 397, 400104111, NULL, NULL, NULL, NULL, NULL, NULL, '111、气壅，属肺热气逆。忌、宜俱同肺实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516324, '6259321D8C85DFF2A25B878EF556094E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6904, 397, 400104110, NULL, NULL, NULL, NULL, NULL, NULL, '110、喘急，属肺有实热，及肺气上逆。\n【忌】同肺实。\n【宜】同肺实，加：桔梗、甘草、栝楼仁、玄参、青黛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516325, '8E02DBAE82C9957A443E1DCD8B8845C9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6905, 397, 400104109, NULL, NULL, NULL, NULL, NULL, NULL, '109、肺实（八证）\n【忌】敛涩、补气、升、燥热、酸、咸。诸药俱见前。\n【宜】降气、润、甘寒、苦寒，佐以辛散。苏子、枇杷叶、桑白皮、天门冬、贝母、栝楼根、杏仁、白前、前胡、知母、车前子、桑黄、石膏、黄芩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516326, '8842DD96874030B20F66DB297B8D1A7B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6906, 397, 400104108, NULL, NULL, NULL, NULL, NULL, NULL, '108、湿热腹痛，按之愈甚。\n【忌】闷气、酸敛、温热、燥。诸药俱见前。\n【宜】利小便，兼升提、苦寒。滑石、车前子、木通、黄连、黄芩、升麻、柴胡、葛根、防风。不愈加熟大黄，即 “土郁则夺之” 之义也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516327, 'B7EB33A1F175E189CDE1945151702C7E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6907, 397, 400104107, NULL, NULL, NULL, NULL, NULL, NULL, '107、中消，属脾家实火。\n【忌】破气、下、温燥、热。诸药俱见前。\n【宜】服诸药同口唇生疮，加人参。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516328, '6D151DF837507BF403FE739836DAAA23', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6908, 397, 400104106, NULL, NULL, NULL, NULL, NULL, NULL, '106、口糜。忌、宜俱同口唇生疮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516329, 'EC50D91688714512AC5EFCD49AD6597E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6909, 397, 400104105, NULL, NULL, NULL, NULL, NULL, NULL, '105、口唇生疮。\n【忌】温燥、热。诸药俱见前。\n【宜】甘寒、酸寒、苦寒、辛寒。麦门冬、生地黄、甘草、白芍药、乌梅、黄连、黄檗、玄参、连翘、栝楼根、干葛、石膏、龙胆草、大青、竹叶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516330, '4677898A8A2DCE22B85E3D24AF383FB6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6910, 397, 400104104, NULL, NULL, NULL, NULL, NULL, NULL, '104、易饥，属脾家邪火。\n【忌】升、辛易、大热、香燥。沉香、麝香、龙脑、缩砂蜜、豆蔻、藿香（已上香燥）。馀忌药俱见前。\n【宜】清火除热、生津液、益脾阴、甘寒、苦寒、酸寒。黄连、青黛、连翘、山栀、石膏、竹叶、麦冬、石斛、白芍药、酸枣仁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516331, '56A2180646A234EECD84E8B343C46436', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6911, 397, 400104103, NULL, NULL, NULL, NULL, NULL, NULL, '103、蛊胀，由于脾家湿热积滞，或内伤瘀血停积而成。\n【忌】补气、甘温、燥热。诸药俱见前。\n【宜】除湿、清热、利小便、消积。木通、防己、车前子、猪苓、泽泻、茯苓、葶苈、乌蠡鱼、桑白皮、山查、红曲、三棱、蓬术。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516332, '6085DB341AE91A90F56CD3B09868991C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6912, 397, 400104102, NULL, NULL, NULL, NULL, NULL, NULL, '102、脾实（六证）\n即湿热邪胜。\n【忌】湿润、收涩、滞腻、热、咸、甘。诸药俱见前。\n【宜】除湿清热、利小便、辛散、风燥、苦寒。术、山栀、猪苓、泽泻、滑石、车前子、茯苓、白豆蔻、防风、干葛、黄连、枳实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516333, '25107DD6767FAA3FAF1C54D35C170E81', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6913, 397, 400104101, NULL, NULL, NULL, NULL, NULL, NULL, '101、目赤肿痛，属血热。\n【忌】同肝实善怒。\n【宜】凉血清热、甘寒、苦寒、酸寒。生地黄、赤芍药、甘草、甘菊、谷精草、蜜蒙花、荆芥、黄檗、大黄、黄连、连翘、玄参、山栀、竹叶、龙胆草、空青、曾青、木通、童便。外治：铜青、芒硝、石胆、蕤核。急者宜以三棱针刺破眼眶肿处，捋出热血，立解。迟则血贯瞳人，目损矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516334, 'DF12E7DB01CCAFD24F2756CEAE5E2C41', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6914, 397, 400104100, NULL, NULL, NULL, NULL, NULL, NULL, '100、发搐，属肝家邪热，热则生风，风主掉眩故也。\n【忌】同善怒。\n【宜】清热、降气、利小便、缓中。生地黄、白芍药、黄连、丹砂、羚羊角、童便、苏子、麦门冬、生甘草、竹叶、甘菊花、白茯苓、木通。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516335, '32CCB85D5DE5FDB92321F8ED39D7078E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6915, 397, 400104099, NULL, NULL, NULL, NULL, NULL, NULL, '99、胁痛呕血，属肝气逆，肝火盛，肝血虚。忌、宜俱同善怒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516336, '75C84B0A6B584FB4A0C877067F324D47', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6916, 397, 400104098, NULL, NULL, NULL, NULL, NULL, NULL, '987、善太息，忽忽不乐。忌、宜俱同善怒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516337, 'B8F9823D8238B53D5BD0FCC62EEFB0E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6917, 397, 400104097, NULL, NULL, NULL, NULL, NULL, NULL, '97、善怒，怒则气上逆，甚则呕血及飧泄。\n【忌】补、升、热、燥、闭气。诸药俱见前。\n【宜】降气、清热、甘寒、酸寒、咸寒，佐以辛散。苏子、郁金、番降香、生甘草、青黛、麦冬、生地黄、赤芍药、橘皮、蒲黄、当归、延胡索、砂仁、香附、童便。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516338, '3F4A4D3EA8EBBA2C6971DE0B5FAC1242', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
