INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6919, 397, 400104095, NULL, NULL, NULL, NULL, NULL, NULL, '95、发狂，属心家有邪热甚。忌、宜俱同心实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516340, 'BBA4C3E718E5EE591D86F5F23B346DD8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6920, 397, 400104094, NULL, NULL, NULL, NULL, NULL, NULL, '94、自笑，属心家有热邪。忌、宜俱同心实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516341, '876DB1A8AB9D5AE01F08D3A922A91DC2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6921, 397, 400104093, NULL, NULL, NULL, NULL, NULL, NULL, '93、烦躁，属心家邪热及心火内炎。烦属心，躁属肾。忌、宜俱同心实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516342, 'AF12535682E34B48B70EB65B1950F6B6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6922, 397, 400104092, NULL, NULL, NULL, NULL, NULL, NULL, '92、舌破，属心火。忌、宜俱同心实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516343, '4154206CD2DA35B43BBD9055E1E94699', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6923, 397, 400104091, NULL, NULL, NULL, NULL, NULL, NULL, '91、谵语，属心家邪热。忌、宜俱同心实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516344, '53BED8A4C5FBA25B72C3710CE6630961', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6924, 397, 400104090, NULL, NULL, NULL, NULL, NULL, NULL, '90、心实（五证）\n即实火实热。\n【忌】补敛、升、热、温燥。诸药俱见前。\n【宜】降火清热，苦寒以折之，辛寒以散之，甘寒以缓之，咸寒以润之。黄连、犀角、石膏、丹砂、牡丹皮、滑石、生甘草、麦门冬、竹叶、童便。大便结燥，加：芒硝、大黄。发狂亦如之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625707342516345, 'CA3A01F891F40501ED2C78626055993F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:49:44', 1, 'admin', '2024-12-23 11:49:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6925, 398, 400104209, NULL, NULL, NULL, NULL, NULL, NULL, '9、伤寒，太阳病、阳明病、少阳病、三阳合病、食、愈后劳复食复女劳复明阳易。冬月即病，宜从仲景冶法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007366, 'BAB0686F230B8E07D59E2817156F5A2E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6926, 398, 400104208, NULL, NULL, NULL, NULL, NULL, NULL, '8、伤寒，冬月即病，宜从仲景法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007367, 'EA08E85C580F5B8AA56EB2CE5BD6A2B6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6927, 398, 400104207, NULL, NULL, NULL, NULL, NULL, NULL, '7、中寒，忌宜同前。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007368, '29528A4A182E5B4B9DB7B055C424989E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6928, 398, 400104206, NULL, NULL, NULL, NULL, NULL, NULL, '6、寒（二证）\n诸病上下所出水液，澄澈清冷，癥瘕㿗疝坚痞，腹满急痛，下利清白，食已不饥，吐利腥秽，屈伸不便，厥逆禁固，皆属于寒。凡中寒，必本于阳虚。\n【忌】破气、苦寒、下、甘寒、辛寒。诸药俱见前。\n【宜】补气、散寒、辛甘、温热，轻者解表，重者温补。桂枝、干姜、麻黄、人参、附子、黄耆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007369, '21839393767B2BC3A49D27F730479A0D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6929, 398, 400104205, NULL, NULL, NULL, NULL, NULL, NULL, '5、伤风热。\n【忌】同感冒风寒。\n【宜】辛寒、甘寒、发散。石膏、知母、甘草、竹叶、麦门冬、前胡、桔梗、薄荷、葛根、桑白皮。久而不愈者属虚。阳虚者加人参、黄耆；阴虚者，加五味子、地黄，倍门冬、白芍药。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007370, '992AB806CFCCE96E7D76B463C73723E8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6930, 398, 400104204, NULL, NULL, NULL, NULL, NULL, NULL, '4、感冒风寒，俗名伤风。其证或头疼身热，轻者则否，鼻必塞，兼流清涕，必恶风寒，或声重，或声哑，甚者痰壅气喘咳嗽。\n【忌】补气、酸敛、闭气。诸药俱见前。\n【宜】发散、辛甘、温。芎、细辛、藁本、防风、甘草、荆芥、白芷、前胡、桑白皮、桔梗、紫苏、薄荷、杏仁、石膏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007371, 'CDBCC15B8BC0547959E27BE8DA604F25', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6931, 398, 400104203, NULL, NULL, NULL, NULL, NULL, NULL, '3、类中风，口眼歪斜，语言謇涩，半身不遂，口噤不言，四肢不举，痰涎壅盛，昏眊不省人事。\n【忌】汗、吐、下，大忌破气、温热、苦寒，及一切治风湿辛燥发散，并开窍走真气、行血诸药，慎勿犯之，犯之则轻必重，重必毙。麝香、苏合香、檀香、龙脑香、安息香（已上开窍走真气）。馀忌药俱见前。\n【宜】滋补，阳虚者补气，阴虚者补血，阴阳两虚则气血双补，兼宜清热、降气、豁痰，及保脾胃。天门冬（脾胃薄弱者勿多用）、麦门冬、荆沥、苏子、栝楼根、贝母、橘红、枇杷叶、甘草、竹沥、童便、霞天膏、梨汁、黄檗。次益血，于前药中加：胡麻仁、石斛、牛膝、生地黄、五味子、甘菊花、枸杞子、何首乌、薯蓣、菟丝子、白芍药、丹参、山茱萸、白蒺藜、酸枣仁、柏子仁、车前子、竹叶、羚羊角、鳖甲、木瓜、青蒿、远志、栝楼仁、沙参、巴戟天、茯苓、茯神。如便闭，加：肉苁蓉、当归，倍麻仁。如兼气虚，加人参、黄耆。有肺热者勿入人参。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007372, 'FED9DD080933E8FB4936930119803F72', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6932, 398, 400104202, NULL, NULL, NULL, NULL, NULL, NULL, '2、真中风，猝僵仆，口噤不言，不省人事。如遗尿，直视，口开，手撒，汗出如珠，属不治证。西北高寒之地有之，东南无。\n【忌】破气、下、吐、苦寒、酸敛。诸药俱见前。\n【宜】辛甘发散、峻补真气。桂枝、附子、甘草、独活、羌活、天麻、麻黄、防风、芎、细辛、藁本、蔓荆实、牛黄、辛夷、牡荆实、白芷、人参、黄耆。有痰加：竹沥、南星、半夏、姜汁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007373, 'C0086AA17FA3094C41100A696E88FE0B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6933, 398, 400104201, NULL, NULL, NULL, NULL, NULL, NULL, '1、风（四证）\n诸暴强直，支痛软戾，里急筋缩，皆属于风。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709726007374, '18758FAF615B876805670A1EF4F4CF8B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 11:59:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6934, 399, 400104301, NULL, NULL, NULL, NULL, NULL, NULL, '     夫伤寒者，大病也。时者，圣人所不能违者也。以关乎死生之大病，而药不从时，顾不殆哉！仲景，医门之圣也。其立法造论，后之明师，如华佗、孙思邈辈，莫不宗之。汉末去古未远，风景犹厚，形多壮伟，气尚敦厖。其药大都为北方感寒即病而设。况南北地殊，厚薄不侔，故其意可师也，其法不可改也。循至今时，千有余年，风气浇矣，人物脆矣。况在荆、扬、交、广、梁、益之地，与北土全别，故其药则有时而可改。非违仲景也，实师其意，变而通之，以从时也。如是则法不终穷矣，故作斯议，条列其方，稍为损益，以从时地。俾后之医师，知所适从，庶几患斯疾者，可免于夭枉尔！　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625709963153478, '6C7DAC19446F1CE1CC55C6ABDB902682', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 12:00:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6935, 400, 400104401, NULL, NULL, NULL, NULL, NULL, NULL, '       凡外感必头疼。其疼也，不间昼夜。探其舌本，必从喉咙内干出于外，多兼烦躁。不烦躁者，即轻证也。不头疼而发热，不发热而头疼，头虽疼而有时暂止，口虽干而舌本不燥，骨虽疼而头不疼，虽渴而不欲引饮，至夜或偶得寐，遇食不好亦不恶，居处虽若尪怯，而神气安静。凡若此者，皆非伤寒也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625710141665350, 'DFCABBEE54A826F9DE597928A6D78685', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 12:01:07', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6936, 401, 400104535, NULL, NULL, NULL, NULL, NULL, NULL, '35、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183366, '339F6897373AC66E50F5C8F67291FD8B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6937, 401, 400104534, NULL, NULL, NULL, NULL, NULL, NULL, '34、伤寒六七日，无大热，其人烦躁者，此以阳去入阴故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183367, 'E411233AE25BA201CBE9B40DBB69FA4F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6938, 401, 400104533, NULL, NULL, NULL, NULL, NULL, NULL, '33、三阳合病，腹满身重，谵语遗尿，白虎汤加百合主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183368, 'CF9B1C66CCABD87B1AF0579259E74287', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6939, 401, 400104532, NULL, NULL, NULL, NULL, NULL, NULL, '32、三阳合病，脉大上关上，但欲睡眠，目合则汗，药用百合（一两），麦门冬（五钱），炙甘草（一钱），知母（二钱），竹叶（五十片），栝楼根（二钱），鳖甲（如法三钱），白芍药（二钱）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183369, '5E77019C0AFD9BF1CD0524DE933706BC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6940, 401, 400104531, NULL, NULL, NULL, NULL, NULL, NULL, '31、阳明少阳并病，必下利，脉滑而数，有宿食也。当承气汤下之。若吐、下、发汗、温针，谵语，柴胡汤证罢，此为坏病。知犯何逆，以法治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183370, '4DC9725FAB49A059D5A6834B7A5933E1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6941, 401, 400104530, NULL, NULL, NULL, NULL, NULL, NULL, '30、凡太阳病不解，传入少阳者，胁下硬满，干呕不能食，往来寒热，未经吐下，脉沉紧者，与小柴胡汤：柴胡（二钱四分），人参（九分），黄芩（九分），甘草（九分），半夏（一钱五分），生姜（九分），大枣（二枚），水煎，温服，日三。加减法：若胸中烦而不呕，去半夏、人参，加栝楼实（一枚）。若心下痞硬，去大枣，加牡蛎（二钱半）。若渴者，去半夏，加人参、栝楼根。若腹中痛者，去黄芩，加芍药（三钱）。若心下悸，小便不利者，去黄芩，加茯苓（二钱）。若不渴，外有微热者，去人参，加桂（一钱，夏勿用）。温覆，取微汗愈。若咳者，去人参、大枣，加五味子（一钱），少佐以干姜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183371, 'BE8E911C1023AF9F681E4023DA1D9BF4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6942, 401, 400104529, NULL, NULL, NULL, NULL, NULL, NULL, '29、伤寒三日，少阳脉小者，欲己也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183372, '87A21A580B873CCFC2BD2A9DD0A7A90D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6943, 401, 400104528, NULL, NULL, NULL, NULL, NULL, NULL, '28、少阳病其证口苦，咽干，目眩，往来寒热，胸胁痛，胸满或痛，耳聋。脉法弦细。头痛发热者，属少阳。少阳不可发汗，发汗则谵语。胃和者，当自愈；不和者，则烦而悸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183373, '04507ED879419C1C2D0F8486E20ACB1D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6944, 401, 400104527, NULL, NULL, NULL, NULL, NULL, NULL, '27、又二阳并病，太阳证罢，潮热，汗出，大便难，谵语者，宜大承气汤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183374, '067BDA48E0D431E792BC891815EA9E71', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6945, 401, 400104526, NULL, NULL, NULL, NULL, NULL, NULL, '26、太阳阳明并病六七日，表证仍在，其人发狂者，以热在下焦，少腹当硬满，小便自利，下其血乃愈，当用桃仁承气汤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183375, '24CD73C62B7E317A3F765D4EADA61282', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6946, 401, 400104525, NULL, NULL, NULL, NULL, NULL, NULL, '25、太阳阳明病协热下利者，宜六一散，以黄连煎汤调服之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183376, 'E13E455BB4CDF2216FEBB59EA2957DFF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6947, 401, 400104524, NULL, NULL, NULL, NULL, NULL, NULL, '24、阳明病发狂，弃衣而走，登高而歌，此阳明实也。以承气汤亟下之。如便不结者，大剂白虎汤灌之。石膏（四两），麦冬（二两），知母（一两五钱），加大青（一两），甘草（七钱）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183377, 'A70091666E676E72F5E5708D272BCA4F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6948, 401, 400104523, NULL, NULL, NULL, NULL, NULL, NULL, '23、阳明实则谵语，虚则郑声。郑声者，重语也。直视、谵语、喘满者死。下利者亦死。发汗多，若重发其汗，谵语脉短者死；脉和者，不死。若吐、若下后不解，不大便五六日，或至十余日，日晡时发潮热，不恶寒，独语如见鬼状。若剧者，发则不识人，循衣妄撮，惕而不安，微喘直视，脉弦者生，涩者死（涩者阳证见阴脉也）。微者但发热谵语者，大承气汤下之。利，勿再服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183378, 'B890DD61E5E31FE313D095AC29363617', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6949, 401, 400104522, NULL, NULL, NULL, NULL, NULL, NULL, '22、阳明病，协热下利者，宜六一散。心下痞者，以黄连栝楼汤调服之。脉浮迟，表热里寒，下利清谷者，四逆汤主之：附子、干姜、甘草。趺阳脉浮而涩，小便数，大便硬，其脾为约，麻子仁丸主之。麻仁（十三两），芍药（四两），枳实（四两），大黄（八两），厚朴（三两），杏仁（六两），蜜丸如梧子大，每用十丸，日三服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183379, '924529294578A846C09B6B6935BA665F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6950, 401, 400104521, NULL, NULL, NULL, NULL, NULL, NULL, '21、阳阳明病脉浮紧，咽燥口苦，腹满而喘，发热汗出，恶热身重。若下之，则胃中空虚，客气动膈，心中懊憹，舌上有胎者，栀子豉汤主之。若渴欲饮水，舌燥者，白虎汤加人参主之，若脉浮，发热口渴，小便不利者，猪苓汤主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183380, 'F7C459EEEB0E2D84AB4DB08A5C435D66', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6951, 401, 400104520, NULL, NULL, NULL, NULL, NULL, NULL, '20、阳明病，下血谵语者，此为热入血室，汗止在头。用荆芥（三钱），葛根（三钱），黄芩（一钱五分），麦冬（五钱），牡丹皮（一钱五分），生蒲黄（二钱），浓煎，以童便对饮之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183381, 'B5D529990ADD2F5CFE6E2D441AC40331', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6952, 401, 400104519, NULL, NULL, NULL, NULL, NULL, NULL, '19、阳明病谵语，发潮热，脉滑而数者，小承气汤主之。服药后腹中转气者，更与一服。若不转气者，勿更与之。若服药后次日不大便，脉反微涩者，里虚也，为难治。勿复议下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183382, 'C71B334300DD7A5D35996DA7B41EBB31', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6953, 401, 400104518, NULL, NULL, NULL, NULL, NULL, NULL, '18、凡阳明病多汗，津液外出，胃中燥，大便必硬，硬则谵语，以小承气汤下之。若一服谵语止者，勿再服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183383, 'CDBE6EFB92B83E52D9091D1260A4247E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6954, 401, 400104517, NULL, NULL, NULL, NULL, NULL, NULL, '17、食谷欲呕，属阳明，非少阳也。胸中烦热者，竹茹汤主之：竹茹（三钱），麦门冬（五钱），枇杷叶（三大片），芦根（三两）。内无热证者，小便利，口不渴，此为阳明虚也。吴茱萸汤主之。吴茱萸（二钱），人参（三钱），生姜（一钱五分），大枣（三枚），水煎，日三服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952183384, '31CD54BF0CA89F4CE64C7043EF7343A1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6955, 401, 400104516, NULL, NULL, NULL, NULL, NULL, NULL, '16、阳明病自汗出，或发汗后，小便利，津液内竭，大便虽硬，不可攻之。须俟其自大便，或用蜜导、胆导法通之。大下后，六七日不大便，烦不解，腹满痛，本有宿食，宜再用承气汤下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187461, 'A876376BACB65E92E4D9FF2B56CFECB6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6956, 401, 400104515, NULL, NULL, NULL, NULL, NULL, NULL, '15、阳明病，发潮热，大便溏，胸满不去者，与小柴胡汤去人参，加栝楼、黄连。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187462, '345FD6AA0F0848288ACD4F085889FB94', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6957, 401, 400104514, NULL, NULL, NULL, NULL, NULL, NULL, '14、阳明病，下之早，外有热，手足温，不结胸，心中懊憹不能食，但头汗出，栀子豉汤主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187463, 'A320FD36B0C645117F690E5C0088F061', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6958, 401, 400104513, NULL, NULL, NULL, NULL, NULL, NULL, '13、阳明病发汗不解，腹满急者，亟下之。伤寒六七日，目中不了了，睛不和，无表证，大便难，宜承气汤下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187464, 'D09CA2E7FEC7D150723C26AFFCE68104', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6959, 401, 400104512, NULL, NULL, NULL, NULL, NULL, NULL, '12、阳明病邪结于里，汗出身重，短气，腹满而喘，潮热，手足濈然汗出者，此大便已硬也。六七日已来，宜下之，用小承气汤。不行，换大承气汤，勿大其剂。若大便不硬者，慎勿轻下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187465, '7302287CD4E3BE681D16CB53A33E67D2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6960, 401, 400104511, NULL, NULL, NULL, NULL, NULL, NULL, '11、阳明病衄血，此缘失于发汗，宜用荆芥（二钱），葛根（三钱），麦门冬（五钱），牡丹皮（一钱五分），蒲黄（二钱），茅根（二两），侧柏叶（二钱），生地黄（三钱），浓煎与之，兼饮童便。阳明病心下硬满者，此邪未入于腹中，慎勿下之。用竹叶石膏汤，加栝楼（一个，捣碎），桔梗（二钱），黄连（一钱）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187466, 'F6FEC4267471CB65B38F6E5862AEE9C1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6961, 401, 400104510, NULL, NULL, NULL, NULL, NULL, NULL, '10、阳明病，头眩，咳而咽痛者，用葛根、甘草、桔梗、麦冬四味浓煎，数数与之。阳明病无汗，小便不利，心中懊憹者，当发黄。急用栀子、麦冬、淡豆豉，大剂浓煎与之。如已见身黄，急加茵陈为君主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187467, '8AC761724022948E5A5E511E529AFE2E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6962, 401, 400104509, NULL, NULL, NULL, NULL, NULL, NULL, '9、阳明病，不能食。若其人本虚，勿轻议下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187468, '997C5368E4CFF1D96A4071DAB33350FF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6963, 401, 400104508, NULL, NULL, NULL, NULL, NULL, NULL, '8、若表证罢后，邪结于里，大便闭，小便短赤，宜用调胃承气汤或小承气汤下之。下后，按其腹中不作痛而和，病即已解。如作痛，是燥粪未尽也。再用前药下之。以腹中和，二便通利为度。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187469, '6F75110BF262427C54896B3C00F8FA76', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6964, 401, 400104507, NULL, NULL, NULL, NULL, NULL, NULL, '7、正阳阳明病\n正阳阳明者，胃家实热是也。其证不大便，自汗，潮热，口渴，咽干，鼻干，呕或干呕，目眴眴不得眠，畏人声、畏木声、畏火，不恶寒反恶热，或先恶寒不久旋发热，甚则谵语狂乱，循衣摸床，脉洪大而长。宜急解其表，用竹叶石膏汤，大剂与之。不呕，无汗，与葛根汤，亦须大剂。若表证已罢，脉缓，小便利，是病解矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187470, '30D7C0C345870012BE2A26CB7F9D9263', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6965, 401, 400104506, NULL, NULL, NULL, NULL, NULL, NULL, '6、太阳病不解，热结膀胱，其人如狂，血自下，下之愈。其外证不解者，不可下，当先解表。表证罢，少腹急结者，乃可下之，桃仁承气汤。无蓄血证，大承气汤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187471, '58996DE31AF08A316F60FD0CB84C4705', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6966, 401, 400104505, NULL, NULL, NULL, NULL, NULL, NULL, '5、如冬月即病太阳证，恶寒、畏风、头疼、遍身骨疼、自汗、不渴，宜用桂枝（八分），芍药（二钱），甘草（一钱），大枣（二枚），生姜（一片）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187472, 'CE4D2A4E61893C9109FA3A70B33FA3CC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6967, 401, 400104504, NULL, NULL, NULL, NULL, NULL, NULL, '4、如自汗烦躁，头疼、遍身骨疼不解者，羌活（一钱），桂枝（七分），石膏（一两二钱），麦冬（六钱），知母（三钱），竹叶（一百二十片），白芍药（二钱），甘草（八分）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187473, '8B01319D14EA827EC93FB76D5C8188A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6968, 401, 400104503, NULL, NULL, NULL, NULL, NULL, NULL, '3、如病人自觉烦躁，喜就清凉，不喜就热，兼口渴，即欲传入阳明也。若外证头疼，遍身骨疼不解，或带口渴、鼻干、目疼、不得卧，即系太阳阳明证。羌活汤中加石膏、知母、麦冬，大剂与之，得汗即解。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187474, 'E013C5784F7B1E5AB68274C4A1D6D0A4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6969, 401, 400104502, NULL, NULL, NULL, NULL, NULL, NULL, '2、其药以羌活汤为主：羌活（三钱）、前胡（二钱）、甘草（八分）、葛根（二钱）、生姜（三片）、枣（二枚）、杏仁（九粒，去皮，研烂）\n水煎服。秋深冬月应用此方，亦可量加紫苏、葱白。如冬月天气严寒，感邪即病，服此方不得汗，本方加麻黄（一钱），生姜（四片），共前（七片），得汗，勿再服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187475, '0E082B9BFF1370420B5F21AF3438967B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6970, 401, 400104501, NULL, NULL, NULL, NULL, NULL, NULL, '1、太阳病其证发热，恶寒恶风，头痛项强，腰脊强，遍身骨痛，脉虽浮洪而不数，多不传经。烦躁脉数急者，是欲传经。宜先发汗以解表邪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625735952187476, '66C9A5433283C51616414D41E1C1FB4F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 13:46:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6971, 402, 400104603, NULL, NULL, NULL, NULL, NULL, NULL, '3、三阴各经见证，悉从仲景《伤寒论》法治之。如少阴咽痛，咽中生疮，声不出，用苦酒汤，到咽即效。故知古人立法，非今人所及也。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625740207001670, 'E1F5CFEFDE9667BA392A647051A88CFC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:03:27', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6972, 402, 400104602, NULL, NULL, NULL, NULL, NULL, NULL, '2、若从无阳邪表证，从不头疼发热，寒邪直中阴经，此必元气素虚之人，或在极北高寒之地，始有是证。法宜温补以接其阳，附子、人参、干姜、官桂，大剂与之。阳回寒退，即以平补之剂调之。勿过用附、桂，以防其毒。　　', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625740207001671, '96CF95C404CB88328482D5E86D4A893C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:03:27', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6973, 402, 400104601, NULL, NULL, NULL, NULL, NULL, NULL, '1、三阴病　其证有二。一者病发于三阳，不时解表，以致邪热传入于里。虽云阴分，病属于热。粪结宜下，腹满不可按宜下，有燥粪协热下利宜下。腹痛下利，宜芍药、黄芩、炙甘草以和之。如便脓血，即加滑石、黄连，佐以升麻、干葛。如邪虽入里，粪犹未结，宜清其热。渴者用白虎汤、竹叶石膏汤；不渴或心下痞者，宜黄连、黄芩、芍药、枳壳、麦冬、栝楼辈以清之。或邪未结于下焦，少腹不坚痛，而误用芒硝以伐真阴，洞泄不己，元气将脱，宜用人参、白术、炙甘草、大枣、干姜、芍药，大剂与之。不止，佐以升提，升麻、葛根、柴胡之类。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625740207001672, 'B216C69AC5C1F7D57F6AC04E4258607C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:03:27', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6974, 403, 400104733, NULL, NULL, NULL, NULL, NULL, NULL, '33、瞤瘈瞀瘈。\n【忌】同火。\n【宜】清热和肝、酸寒、苦寒、辛寒、甘寒。白芍药、生甘草、竹叶、玄参、黄连、黄檗、生地黄、甘菊花、麦门冬、知母、石膏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422726, '0B5FBC3783F418EF1DA1FD70D5B49FDF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6975, 403, 400104732, NULL, NULL, NULL, NULL, NULL, NULL, '32、气逆冲上。\n【忌】同火。\n【宜】降气、酸敛、甘寒、苦寒、咸寒。苏子、枇杷叶、橘红、五味子、番降香、山茱萸、白芍药、麦门冬、石斛、黄檗、牛膝、桑白皮、童溺。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422727, 'F3D4B288E504CD01F63F90D860F53995', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6976, 403, 400104731, NULL, NULL, NULL, NULL, NULL, NULL, '31、禁栗如丧神守。\n【忌】同火。\n【宜】同躁扰狂越。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422728, 'EFB752F26CA92450DD765F55EBB3D411', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6977, 403, 400104730, NULL, NULL, NULL, NULL, NULL, NULL, '30、躁扰狂越，骂詈惊骇。\n【忌】同火。\n【宜】清镇、苦寒、辛寒、咸寒。丹砂、牛黄、黄连、黄芩、山栀、滑石、知母、童便。大便闭者，加大黄下之。不行，加芒硝。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422729, '7FF029D304DAECC0AC76036C919FF149', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6978, 403, 400104729, NULL, NULL, NULL, NULL, NULL, NULL, '29、暴注。\n【忌】同火。\n【宜】利水、苦寒、酸寒。茯苓、黄连、黄芩、白芍药、生甘草、葛根、滑石、木通。虚者加：人参、莲肉、白扁豆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422730, 'B17846056AD8C1D82084C06DADCAA539', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6979, 403, 400104728, NULL, NULL, NULL, NULL, NULL, NULL, '28、暴瘄。\n【忌】同火。\n【宜】降气、发音声、苦、甘寒、辛凉、咸寒。苏子、枇杷叶、贝母、桔梗、百部、竹沥、梨汁、天门冬、麦门冬、甘草、薄荷、玄参、桑白皮、童便。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422731, '66CC7E1FC90E42BD7AFF1C941711CF3B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6980, 403, 400104727, NULL, NULL, NULL, NULL, NULL, NULL, '27、口干舌苦。忌、宜俱同火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422732, '5AFEA2463AC522A6EF71B744DA1B9C1C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6981, 403, 400104726, NULL, NULL, NULL, NULL, NULL, NULL, '26、忽大渴思冰水。\n【忌】同火。\n【宜】润、生津液、辛寒、甘寒、咸寒。石膏、知母、玄参、麦门冬、竹叶、栝楼根、五味子、梨汁、蔗浆、童便、凉水、冰。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422733, 'C860456BE56D6A5D91117174FA9200B7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6982, 403, 400104725, NULL, NULL, NULL, NULL, NULL, NULL, '25、头面赤肿。\n【忌】同火。\n【宜】清热解毒、发散、苦寒、辛寒、甘寒、咸寒。甘菊花、鼠粘子、连翘、荆芥、薄荷、蝉蜕、大黄、玄参、石膏、知母、竹叶、生甘草、童溺。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422734, '7B980E5B44000B91F72CE0BB96863C9B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6983, 403, 400104724, NULL, NULL, NULL, NULL, NULL, NULL, '24、二便忽闭，以利小便为先。\n【忌】同火。\n【宜】降润、苦寒、甘寒、辛寒、利窍。大黄、苏子、生蜜、麻仁、桃仁、石膏、贝母、天门冬、麦门冬、黄芩、山栀、滑石、泽泻、猪苓、车前子、木通、海金沙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422735, '0543CA336AD734B5CCFE4DD59F50FDAC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6984, 403, 400104723, NULL, NULL, NULL, NULL, NULL, NULL, '23、目暴赤肿痛甚，见肝实条内。忌、宜俱同。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422736, '442E5E56375D4B0D8206F26B4B65E534', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6985, 403, 400104722, NULL, NULL, NULL, NULL, NULL, NULL, '22、猝心痛。\n【忌】同火。\n【宜】服山栀、白芍药、延胡索、生甘草、盐汤、苏子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422737, 'AED4BFF9D6700F9CF6AB4D32909AA2B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6986, 403, 400104721, NULL, NULL, NULL, NULL, NULL, NULL, '21、猝眩仆、九窍流血，多不治。\n【忌】同火。\n【宜】服童便、盐汤、竹沥、蓝汁、梨、生犀角汁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422738, '7B28EAF89CD7FB9268012310314D0FD8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6987, 403, 400104720, NULL, NULL, NULL, NULL, NULL, NULL, '20、火，诸热瞀瘈，暴瘖冒昧，躁扰狂越，骂詈惊骇，胕肿疼酸，气逆上冲，禁栗如丧神守，啑呕，疮疡，喉痹，耳鸣及聋，呕涌溢食不下，目昧不明，暴注，瞤瘈，暴病暴死者，皆属于火。\n【忌】补敛、升发、闭气、辛燥、温热。诸药俱见前。\n【宜】降折、下、咸寒、苦寒、辛寒、甘寒。大黄、童便、芒硝、黄芩、黄连、黄檗、连翘、石膏、山栀、玄参、生甘草、知母、天门冬、麦门冬、生地黄、蓝汁。虚者宜甘寒、咸寒以滋水，不宜用苦寒伤胃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422739, 'D726426E60633F13C579550044F05EFB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6988, 403, 400104719, NULL, NULL, NULL, NULL, NULL, NULL, '19、燥火（十三证）\n诸涩枯涸，干劲皴揭，皆属于燥。角弓反张，筋挛急不舒，舌强不能言，二便闭涩，口渴，口干舌苦，皮肤皴揭，毛发脆折，津液不生，血枯胃槁，以致饮食不化，噎膈吐食。\n【忌】升散、破气、下、辛燥、大热、温。诸药俱见前。\n【宜】润、益血、辛、甘寒、酸寒、咸寒，有热证者宜兼清热。麦门冬、当归、地黄、肉苁蓉、酥、人乳、牛乳、蜜、胡桃、甘菊花、麻仁、胡麻、柏子仁、人参、松实、天门冬、五味子、酸枣仁、白芍药、蔗浆、芦根汁、童便、梨汁、韭汁。佐以姜汁。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422740, '98AA98F9546766442DCE824DCCF73DF1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6989, 403, 400104718, NULL, NULL, NULL, NULL, NULL, NULL, '18、脚气，由于湿热。\n【忌】温燥、湿热、补气，复忌破气、升。诸药俱见前。\n【宜】清热、除湿、利小便、甘平、酸寒、苦寒、辛温、淡渗。黄檗、石斛、麦门冬、木瓜、石菖蒲、车前子、茯苓、木通、泽泻、萆薢、防己。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422741, '50FF6F4A6C16525D772A20585C9D79C7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6990, 403, 400104717, NULL, NULL, NULL, NULL, NULL, NULL, '17、湿（一证）\n诸痉强直，积饮痞膈，中满霍乱，吐下体重，胕肿肉如泥，按之不起，皆属于湿。《经》曰：地之湿气，感则害人皮肉筋脉。故其病筋骨疼痛，腰重痛不可转侧，身重，四肢不利。湿在上，病呕吐、头重、胸满；湿在中，病腹胀、中满、泄泻；湿在下，病足胫跗肿，脚气臁疮久不愈。\n【忌】湿润、甘、咸。诸药俱见前。\n【宜】散、渗泄、燥、辛、苦。木瓜、薏苡仁、术、石斛、萆薢、石菖蒲、茯苓。佐以防风、葛根。寒湿加半夏、五加皮，风湿加独活，湿热加黄檗、车前子、木通，甚者加汉防己。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422742, '84A8E87F8C52A7D7B4F27DFA599F8BB5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6991, 403, 400104716, NULL, NULL, NULL, NULL, NULL, NULL, '16、疰夏，由于脾胃薄弱，胃家有湿热，及留饮所致。\n【忌】同前。\n【宜】益气健脾、酸寒、苦寒、淡渗。人参、白术、半夏、橘皮、白茯苓、白扁豆、白芍药、木瓜、泽泻。兼服生脉散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422743, '0585E77EAC7732B5E031328E7B350500', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6992, 403, 400104715, NULL, NULL, NULL, NULL, NULL, NULL, '15、霍乱，见胃虚条内。忌、宜俱同。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422744, '67DF2234EC83B4080EC5ABEBA78243BF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6993, 403, 400104714, NULL, NULL, NULL, NULL, NULL, NULL, '14、太阳病中暍。\n【忌】同暑。\n【宜】人参白虎汤。有肺热火病人，不能服参者，用竹叶石膏汤。脾胃作泻者，水调六一散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422745, '62189AFE4587B1004F5E282745E1DC23', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6994, 403, 400104713, NULL, NULL, NULL, NULL, NULL, NULL, '13、中暑，猝昏晕，急以童便灌入即省。\n\n       忌、宜俱同暑。又方：用丝瓜叶一片，白盐梅肉一枚，并取核中仁，共研如泥，新汲水调灌，立瘥。兼治中暑霍乱有神。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422746, '4D62839776484A2AA42C573B632B5AE7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6995, 403, 400104712, NULL, NULL, NULL, NULL, NULL, NULL, '12、暑（三证）\n诸病喘呕，暴注下迫，霍乱转筋，身热瞀郁，小便浊赤，皆属于暑。\n【忌】破气、升，复忌下、湿润、辛温、辛燥、热、发散、闭气。诸药俱见前。\n【宜】清暑益气、健脾、甘寒、甘温、辛寒、酸寒、苦寒。黄连、香薷、葛根、石膏、知母、甘草、人参、黄芪、白术、白扁豆、神曲、橘皮、白茯苓、木瓜、麦门冬、五味子、白芍药、白梅、乌梅。大约用清暑益气汤、香薷饮、生脉散。凡病暑之人，其气必虚。暑伤气，无气以动，故当补气为本。惟肺热多火者，忌人参、术。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422747, '368690036D10819F80D3E87AB380EE65', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6996, 403, 400104711, NULL, NULL, NULL, NULL, NULL, NULL, '11、时气伤寒（除阴证不可服。）\n        苦参（一两），水、酒各一碗，煎八分。重者水、醋各半服之。一汗而愈。不论伤寒久近，立效。本草云：天行尤良。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422748, 'D68B3E4D6BAC35C3D408F543F9843B56', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6997, 403, 400104710, NULL, NULL, NULL, NULL, NULL, NULL, '10、近代医师鲁莽，既不明伤寒治法，又不识杂证类伤寒，往往妄投汗、下之药，以致虚人元气，变证丛生。元气本虚之人，未有不因之而毙者矣。戒之哉！汗、下之药，焉可尝试也！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422749, 'CDBCD870E2FEC96AA7D670D7B019B35B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6998, 403, 400104709, NULL, NULL, NULL, NULL, NULL, NULL, '9、百合病者，百脉一宗，悉致其病也。其证神思常默然，饮食不美、亦不恶，如寒无寒，如热无热，口苦，小便赤，百合地黄汤主之。汗后者，百合知母汤。下后者，滑石代赭汤。吐后者，百合鸡子汤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422750, '162077A9291E5FF49641E8420DC8C3E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6999, 403, 400104708, NULL, NULL, NULL, NULL, NULL, NULL, '8、伤寒差已后，更发热者，小柴胡汤主之。脉浮者，以汗解之。脉沉实者，以下解之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422751, '108767F70375FDCC277173CD6BB15F27', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7000, 403, 400104707, NULL, NULL, NULL, NULL, NULL, NULL, '7、大病差后，劳复者，枳实栀子汤主之：枳实（三枚）　栀子（十四枚）　豉（一升，绵裹），以清浆水七升，空煮取四升，内枳实、栀子，煮取二升，下豉，更煮五六沸，去滓，温分再服。覆令微似汗。若有宿食者，加大黄如博棋子大五六枚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422752, '21842ACFD9A38A7C13A21D4FB5C3BD46', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7001, 403, 400104706, NULL, NULL, NULL, NULL, NULL, NULL, '6、伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。取妇人中裈近阴处，剪，烧灰，以水和服方寸匕，日三。小便即利，阴头微肿则愈。妇人病，取男子裈裆烧灰。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422753, '40D448EF8B723AAF681D6E1734AFDC08', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7002, 403, 400104705, NULL, NULL, NULL, NULL, NULL, NULL, '5、邪在三阳，法宜速逐，迟则胃烂发斑，或传入于里，则属三阴。邪热炽者，令阴水枯竭，于法不治矣。此治之后时之过也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422754, '7440468E60032B63E0F93378F5308F3E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7003, 403, 400104704, NULL, NULL, NULL, NULL, NULL, NULL, '4、伤寒、温疫，三阳证中，往往多带阳明者，以手阳明经属大肠，与肺为表里，同开窍于鼻，足阳明经属胃，与脾为表里，同开窍于口。凡邪气之入，必从口鼻，故兼阳明证者独多。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422755, '40B49C56ACDAC34960F619EA9E5AA5DF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7004, 403, 400104703, NULL, NULL, NULL, NULL, NULL, NULL, '3、伤寒、温疫，其不可治及难治者，皆属下元虚。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422756, '52C8AE7D68A8D908E976E3BA77B605BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7005, 403, 400104702, NULL, NULL, NULL, NULL, NULL, NULL, '2、至夏变为热病，其表证大约与春温同，但热比于温，则邪气更烈耳。解表用白虎汤、竹叶石膏汤。有太阳证则加羌活，有少阳证则加柴胡、黄芩。如发斑，白虎汤、竹叶石膏汤，加玄参、栀子、桔梗、鼠粘子、连翘、大青、小青、青黛，大剂与之。二证若大便秘，宜按之。其邪已结于内，便硬宜察，邪结中焦，小承气汤、调胃承气汤下之；邪结下焦，少腹坚痛，始用大承气汤下之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422757, '872E82897E524617DCB55441D59034B5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7006, 403, 400104701, NULL, NULL, NULL, NULL, NULL, NULL, '1、冬伤于寒，至春变为温病，大都头疼发热，或渴或不渴。三阳证俱然。亦间有先微寒后即发热者。大抵发热其常也。药用辛温，佐以辛寒，以解表邪。太阳宜羌活汤，阳明宜白虎汤，无汗不呕者，间用葛根汤。少阳往来寒热等证，不可汗、吐、下，宜和解，小柴胡汤。渴者，去半夏，加栝楼根；耳聋，热盛，去人参，加麦冬、知母、栝楼根，渴亦加之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625744468422758, '1E157C6A4DC90773579447972DF4B016', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:20:48', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7007, 404, 400104815, NULL, NULL, NULL, NULL, NULL, NULL, '15、凡劳疟，病人阴不足，或作劳，或房劳，病发于阴，或间日一发，或三日一发。三日一发为病深，须以鳖甲、牛膝、何首乌为君，橘皮为佐。发于夜而便燥者，加当归。脾胃薄弱者勿加，佐以姜皮，热甚勿入。大剂与之，日三乃瘥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900742, '66A255BE720A8B9F0DF8EA82BF939E6D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7008, 404, 400104814, NULL, NULL, NULL, NULL, NULL, NULL, '14、又，暑热湿之邪内伏，百药不效者，用独雄丸立愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900743, 'A0E831809F81673D4C7349386D8FF221', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7009, 404, 400104813, NULL, NULL, NULL, NULL, NULL, NULL, '13、暑邪盛，解散不早，陷入于里，则变为滞下。急投芩、连、芍药、滑石、红曲、甘草，佐以葛根、升麻、柴胡，以表里分消之。脾胃薄弱者，加人参、扁豆、莲肉，大剂与之，以愈为度。滞下若愈，疟亦随止，即不止，其热必轻，仍随经随证以治之，不烦多药而自止也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900744, 'D7A96ECE3CECA43726DFCAC55BB8E5F0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7010, 404, 400104812, NULL, NULL, NULL, NULL, NULL, NULL, '12、疟病多挟风。有风者必用何首乌为君，白术、橘皮为臣，葛根、姜皮、羌活以佐之。不头痛者除羌活。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900745, '39401A5505B1F04701DE0109205A0FC0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7011, 404, 400104811, NULL, NULL, NULL, NULL, NULL, NULL, '11、疟病多挟痰。以故热痰须用贝母为君，自三钱至八钱，竹沥、竹茹、栝楼根、橘红、白茯苓，称是以佐之。甚者可加霞天膏。如寒痰发疟，寒多不渴者，用半夏、白术、橘皮为君，多加生姜皮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900746, 'F92804970E1095D20F8BEF1D36E6D878', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7012, 404, 400104810, NULL, NULL, NULL, NULL, NULL, NULL, '10、足少阴经属肾，其证寒热俱甚，腰痛脊强，口渴，寒从下起，小便短赤。\n【宜】先服人参白虎汤加桂枝，以祛暑邪，后用鳖甲（四五钱），牛膝（两许），热甚者加知母、麦门冬（各四五钱）。寒甚者加桂枝钱许。\n呕则兼加姜皮（三四钱）。如热甚而呕者，去桂枝、姜皮，加竹茹（三钱），人参、橘皮（各三四钱）。用牛膝、桂枝者，肝肾同一治故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900747, 'ECA07D712547A311CC8B5B95F89F75FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7013, 404, 400104809, NULL, NULL, NULL, NULL, NULL, NULL, '9、足太阴经属脾，其证先寒后热，或寒多。若脾疟，必寒从中起，善呕，呕已乃衰，然后发热，热过汗出乃已。热甚者或渴，否则不渴喜火。\n【宜】服桂枝汤、建中汤。\n病人虚者，以人参、姜皮各两许浓煎，露一宿，五更温服。\n有痰者，宜加术、橘皮（各三四钱）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900748, '2DB067DA5D988BC79DD2DDD54ABBDBE0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7014, 404, 400104808, NULL, NULL, NULL, NULL, NULL, NULL, '8、足厥阴经属肝，其证先寒后热，色苍苍然，善太息，甚者状如欲死，或头疼而渴。\n【宜】先服三黄石膏汤加柴胡、鳖甲、橘皮，以祛暑邪。后用当归（两许），橘皮（三四钱），鳖甲（四五钱），牛膝（两许），柴胡（一二钱），浓煎露一宿，发日五更温服。\n如热甚而渴，加栝楼根（三四钱），麦门冬（四五钱），竹叶（一百片），知母（三四钱），鳖甲（五六钱）。\n如脾胃薄弱，或溏泄，去当归，加人参（三五钱）。\n如有肺火，不可服参者，只照本方，多服自愈。\n寒多或寒甚，指爪青黯者，加桂枝、姜皮、人参。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900749, '13B01CE81B6DEF2DFF5057980E49298E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7015, 404, 400104807, NULL, NULL, NULL, NULL, NULL, NULL, '7、以上三阳经疟邪客之者，其证多热多渴，亦易得汗，药宜大剂，急逐暑邪，毋得迟留，则病易愈。继以理脾开胃，大补真气，蔑不瘳矣。邪在三阳，药宜辛寒，如石膏、知母、柴胡；甘寒，如葛根、麦门冬、竹叶、粳米；苦寒，如黄芩之属为君，乃可以散暑邪，除热渴，坠头痛。兼寒甚者，则间用辛温，如姜皮、桂枝以为向导，以伏其邪，则病易退。凡寒甚者，病因于虚。或作劳者，亦因于虚，皆宜甘温。以人参、黄耆、术为君，佐以辛甘，如桂枝、姜皮之属。脾胃虚弱，饮食不消者，则补之以参、术，佐以消导，如白豆蔻、麦芽、砂仁、草豆蔻、枳实、橘皮、山查之属。在阴分者，则以当归、牛膝为君，佐以姜、桂。如热甚而渴者去姜、桂，加知母、麦门冬、竹叶、牛膝、鳖甲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900750, 'F735EE267101D7BBE355B4BC2BC1F94D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7016, 404, 400104806, NULL, NULL, NULL, NULL, NULL, NULL, '6、足少阳经属胆，其证往来寒热，口苦，耳聋，胸胁痛，或呕。宜服小柴胡汤。\n渴者，去半夏，加石膏、麦门冬。\n肺家有热者，去人参，加知母，倍门冬。\n有痰不渴者，本方加贝母（三钱至八钱），术、茯苓（各三钱），姜皮（一钱至三四钱）。\n病人阴虚而有热者，虽呕吐忌用半夏、生姜，误投则损人津液，令人声哑，宜用竹茹、橘皮、麦门冬、白茯苓、乌梅以代之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900751, '7BCC26F6C249FAFC44E4BCE33335445F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7017, 404, 400104805, NULL, NULL, NULL, NULL, NULL, NULL, '5、足阳明经属胃，其证发热头疼，鼻干，渴欲引饮，目眴眴不得眠，甚则烦躁，畏火光、人声、木声。宜服大剂竹叶石膏汤。无汗或汗少不呕者，可加干葛（二三钱）。\n病人虚而作劳者，加人参。\n汗多，加白术。\n痰多，加贝母、橘红，得汗即解。\n寒热俱甚，渴甚，汗多，寒时指爪皆紫黯者，加桂枝（七八分）。\n久而不解属气虚，用人参（两许），姜皮（两许），煎成露一宿，五更温服。下午服理脾健胃药如前方，加减亦如之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900752, 'D6D0CD15447BACCAB583D65D0B70623A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7018, 404, 400104804, NULL, NULL, NULL, NULL, NULL, NULL, '4、《内经》六经疟候汤液\n足太阳经属膀胱，其证令人腰痛，头痛头重，寒从背起，先寒后热，熇熇暍暍然，热止汗出难已，或遍身骨痛，小便短赤：\n羌活（一钱至三四钱），广陈皮（去白二钱五分），黄芩（二钱），前胡（二钱），甘草（炙五分），猪苓（一钱），知母（二钱五分）。\n若口渴者，即兼阳明，宜加石膏、麦门冬，倍知母。渴而汗少，或无汗，并加葛根。\n若涉深秋或入冬，无汗，宜多加姜皮。\n因虚而无汗，或汗少者，加人参（三五钱），麦门冬（四五钱），佐以姜皮（二三钱），露一宿，发日五更温服。\n因虚汗多者，加黄耆（三四钱），桂枝（七八分）。汗止，即去桂枝，不可多服。\n若病人素有热者，勿服桂枝，以芍药、五味子代之。\n若发于阴，并加当归。\n小便短涩或赤者，与六一散二三服。\n有湿者，以猪苓、茯苓代滑石。下午服理脾健胃药：\n橘红（二钱五分），白豆蔻（五分），白茯苓（三钱），山查（三钱），麦芽（炒三钱），藿香（一钱），人参（三钱），白术（二钱），白芍药（三钱），白扁豆（三钱）。\n有肺火者，去人参、白术，加麦门冬（五钱），石斛（三钱），乌梅肉（一枚）。\n停食者必恶食，加山查。伤肉食者加黄连、红曲。伤谷食者加枳实、草果（各七分）。伤面食者加炒莱菔子。食消即已，不可多服，多服则损中气。\n胃家素有湿痰者，其证不渴、寒多，方可用半夏、橘红、二术，大剂与之。呕甚者兼用姜皮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900753, '8C1D743AA9014AB601DF4DDF1C82AFD3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7019, 404, 400104803, NULL, NULL, NULL, NULL, NULL, NULL, '3、误下则邪气陷于内，变为滞下，或腹满肿胀，呕恶不思食。凡属破气、下泄药，切戒勿施！\n【宜】清暑益气，健脾开胃，兼消痰。\n【宜】分脏腑手足六经所见证拖治。\n先清暑：热多者宜服白虎汤加减：硬石膏（自一两至四两），知母（自四钱至二两四钱），竹叶（自一百片至四百片），麦门冬（自八钱至三两二钱），粳米（自一小撮至二大撮）。病人素虚或作劳者，加人参（自三钱至一两）。\n有痰加广橘红（三钱），竹沥（一杯），大渴者，加栝楼根（三钱至六钱）。\n不渴者，用清暑益气汤。\n兼饮食停滞者，加枳实、青皮、草果一二剂，食消即止。勿多服。多服则损中气。其药俱宜黄昏煎，以井水澄冷，须露一宿，五更时温服。盖疟乃暑邪为病，暑得露则散也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900754, '8C589AEA668B85EA1D4581E2174D61BF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7020, 404, 400104802, NULL, NULL, NULL, NULL, NULL, NULL, '2、疟必由于中气虚，破气则伤中气，邪不得解，甚则中满不思食，作泄，恶寒，口干，惟伤食宜消，不同此法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900755, '16C05180519EB3DE2812138776CABFCE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7021, 404, 400104801, NULL, NULL, NULL, NULL, NULL, NULL, '1、疟 \n      《经》曰：夏伤于暑，秋必痎疟。其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，或先寒后热，或先热后寒，或有汗、无汗，或汗少、汗多，或自汗、盗汗，或头疼骨痛，或大渴引饮，口苦舌干，或呕吐不思食，或烦躁不得眠，或大便燥结，或泻利，或连发，或间发，或三日发，或发于阳，或发于阴，要皆中气不足，脾胃虚弱，暑邪乘虚客之而作。虽随经随证投药解散，必先清暑益气，调理脾胃为主。有伤食者兼消导夺食，有风兼散风，有老痰伏饮者兼豁痰逐饮，感瘴疠者兼消瘴疠，汗多者固表，无汗者解表，泄利者升发、兼利小便，便燥者兼益阴润燥。病有阴阳，药分气血，证有缓急，治因先后，人有虚实，法异攻补。久而不解，必属于虚。气虚者补气，血虚者补血，两虚者气血兼补，非大补真气，大健脾胃不得瘳也。\n【忌】破气、下。\n诸药俱见前。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625747983900756, '3F21674115166F3F7C3E071E40BA08AE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 14:35:06', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7022, 405, 400104913, NULL, NULL, NULL, NULL, NULL, NULL, '13、头痛\n挟风寒者：忌补敛。诸药俱见前。\n【宜】辛温、发散。羌活、防风、细辛、荆芥、薄荷、川芎、藁本、升麻、白芷、蔓荆子、生姜、葱白。\n\n挟邪热者：忌同挟风寒。\n【宜】辛寒、苦寒、解散。石膏、薄荷、黄芩（酒炒）、芽茶、黑豆、乌梅、甘菊花、土茯苓。\n\n热极目昏便燥者，加酒蒸大黄。\n挟痰者：忌升、补敛、酸甘、滞腻。诸药俱见前。\n【宜】豁痰降气、辛燥。苏子、橘红、贝母、半夏、前胡、竹沥、术、天麻。\n\n阴虚者：忌辛热发散。诸药俱见前。\n【宜】补血益阴、酸敛、甘寒、酸寒。生地黄、甘菊花、当归、天门冬、麦门冬、枸杞子、黄檗、白芍药、忍冬、五味子、乌梅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235590, 'DEA3F07ABFEDFF2C76E8DFB4639FB761', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7023, 405, 400104915, NULL, NULL, NULL, NULL, NULL, NULL, '15、齿痛\n【忌】升、补敛、燥热、辛温。诸药俱见前。\n【宜】清热凉血、苦寒、辛寒、甘寒、咸寒。麦门冬、生地黄、赤芍药、牡丹皮、竹叶、知母、黄连、黄芩、黄檗、玄参、石膏、薄荷、苏子、甘草、童便。\n上下龈属胃与大肠火，宜石膏、熟大黄、麦门冬、黄芩、黄连、赤芍药、生地黄、生甘草、青黛、细辛、西瓜皮灰、薄荷、枇杷叶、苏子、木通。\n真牙浮动及黑烂，属肾虚有火，已见肾虚条内，忌、宜俱同。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235591, '4B0F1A66DFE250B2EF97AA41BC7DB8BE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7024, 405, 400104914, NULL, NULL, NULL, NULL, NULL, NULL, '14、眉棱骨痛\n忌、宜俱同阴虚头痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235592, '4DC2362EBE25C9DAAD7A1343A6ABBE6F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7025, 405, 400104912, NULL, NULL, NULL, NULL, NULL, NULL, '12、蓄血\n俗名内伤。或积劳，或多怒，或饱后行房，或负重努力，或登高坠下，或奔逐过急，皆致蓄血。其证多发热，其热类外感而不头疼、不作渴。天明少间，至午复剧。有汗，汗多剂颈而还，自汗，无气以息，目光短，不思饮食，不得眠，二便自利，小便或赤，大便或泄。\n【忌】破气，复忌补气、下、苦寒、辛燥。诸药俱见前。\n【宜】行血、辛温，佐以咸寒，瘀血行后宜补血益脾，和肝。桃仁、红蓝花、延胡索、桂（有火之人勿用）、郁金、当归尾、苏方木、乳香、番降香、没药、穿山甲、䗪虫、赤芍药、五灵脂、蒲黄、红曲、麒麟竭、韭汁、童便、桃枭。\n甚者用大黄、花蕊石。瘀行则止，勿过剂。如元气虚，脾胃素弱者，慎勿轻用大黄。如瘀血行后，宜生地黄、川续断、白胶、当归身、麦门冬、牛膝、白芍药、炙甘草、酸枣仁、大枣、龙眼肉、枸杞子、山茱萸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235593, '8E074D3FAD10E93B87812104AC6088FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7026, 405, 400104911, NULL, NULL, NULL, NULL, NULL, NULL, '11、诸血\n吐血、咯血、鼻衄、齿衄、耳衄、舌上出血。\n【忌】升提发散、下、破血、补气、闭气、破气、温热、辛燥，复忌极苦寒伤胃。诸药俱见前。\n【宜】降气、清热、凉血益阴，兼行血、咸寒、酸寒、甘寒。苏子、麦门冬、橘皮、枇杷叶、降香、郁金、天门冬、沙参、牛膝、阿胶、生地黄、枸杞子、五味子、鳖甲、白芍药、犀角汁、牡丹皮、青蒿、剪草、白药子、童便、侧柏叶、小蓟、茅根、棕灰、藕节、当归、蒲黄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235594, 'E50B7E0AC744ED9448988EDF50445C84', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7027, 405, 400104910, NULL, NULL, NULL, NULL, NULL, NULL, '10、哕\n俗呼呃逆。久病沉痼而发者，属真气虚，多不治。\n【忌】破气、升、散。诸药俱见前。\n【宜】补敛、甘温、甘寒。人参、黄耆、炙甘草、麦门冬、五味子、益智子、白芍药、石斛。\n伤寒失下而发者，忌补敛、酸、燥热、滞腻。诸药俱见前。\n大便硬闭宜下，大小承气之类。便不硬闭，按之腹中和软，未经汗吐者，宜辛寒解表，白虎汤之类。\n因气逆冲上而发者，忌升、补。诸药俱见前。\n【宜】降气、甘寒、咸寒。苏子、橘红、枇杷叶、竹茹、芦根汁、麦门冬、童便。\n因痰水停膈而发者，忌升、润、苦寒、甘寒、酸寒。诸药俱见前。\n【宜】降气、开痰、辛散。橘红、苏子、贝母、桑白皮、半夏、旋覆花、生姜、白豆蔻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235595, '3ABC2ECD10B257815F27A9981C057FD9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7028, 405, 400104909, NULL, NULL, NULL, NULL, NULL, NULL, '9、关格\n不得大小便为关，是热在丹田也。吐逆水浆不得下为格，是寒反在胸中也。是阴阳易位，故上下俱病。先投辛香通窍下降之药以治其上，次用下泄苦寒之药以通二便。此急证，法难缓治。纵有里虚，通后再补。\n【忌】升、补敛、闭气、酸。诸药俱见前。\n【宜】降下、辛寒、辛温。沉香、白豆蔻、丁香、苏子、龙脑香、苏合香、橘红、生姜、藿香。\n次用大黄、黄檗、知母、滑石、木通、车前子、牛膝。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235596, '297280F49F9A28ACD55EDAD1E4FAB4DA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7029, 405, 400104908, NULL, NULL, NULL, NULL, NULL, NULL, '8、郁\n【忌】酸敛、滞腻、补气、闭气。诸药俱见前。\n属情抱者宜开发志意，调气散结，和中健脾。远志、贝母、郁金、石菖蒲、香附、苏子、橘红、白豆蔻、木香、苏合香、缩砂蜜、麦门冬。\n属五脏者，木郁达之，宜升、吐。升麻、柴胡、川芎、瓜蒂、人参芦。\n火郁发之，宜散。升麻、葛根、柴胡、防风、羌活。\n土郁夺之，宜下。槟榔、枳实、厚朴、大黄。\n金郁泄之，宜降。橘红、苏子、桑白皮、猪苓、泽泻、茯苓、木通。\n水郁折之，宜利。茯苓、海金沙、猪苓、泽泻、木通、赤小豆、车前子、乌蠡鱼。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235597, 'E83FB38A04FDE39BEE9965645CFCA4DA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7030, 405, 400104907, NULL, NULL, NULL, NULL, NULL, NULL, '7、诸气\n    气有余即是火。\n【忌】升、闭气、酸敛、滞腻。诸药俱见前。\n虚者宜降、补敛、调、温、酸、辛、甘。苏子、枇杷叶、橘红、麦门冬、芦根汁、甘蔗、番降香、沉水香、白豆蔻、郁金、甘草、童便、白芍药、五味子。\n因虚极而气不得行者，加人参。\n实者宜破散、香燥、辛苦、辛寒。枳壳、青皮、槟榔、厚朴、木香、沉香、香附、乌药、降香、藿香、缩砂蜜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235598, 'B18221467D89B11B360B83B1306B7C70', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7031, 405, 400104906, NULL, NULL, NULL, NULL, NULL, NULL, '6、饮\n如涎而薄者，或如涎而稠者，伏于胸中及脾胃间，或吐酸水、苦水、黄水、绿水，或伏而不吐，上支心胸胃脘，作痛不可忍，按之不得下，或发寒热，呕吐不能饮食。\n忌、宜俱同脾虚证内停饮条。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235599, '98DB8A68A3B3CBD8B65ABA6866FD33B9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7032, 405, 400104905, NULL, NULL, NULL, NULL, NULL, NULL, '5、痰\n由于热：忌燥、温热、补敛，升。诸药俱见前。\n【宜】降、润、清热、苦寒、辛寒、佐以咸寒。苏子、橘红、天门冬、枇杷叶、麦门冬、黄芩、桑白皮、薄荷、百部、栝楼根、栝楼仁、桔梗、贝母、蛤粉、竹沥、童便。\n胶固者加霞天膏，并用猫儿刺。\n由于风寒：忌补敛，湿润、酸、咸。诸药俱见前。\n【宜】降气、辛散。橘红、苏子、杏仁、天麻、前胡、半夏、南星、葛根、桑白皮、薄荷、白前、生姜汁。\n由于湿：忌润、咸、酸、滞腻、发湿。诸药俱见前。\n【宜】健脾、燥湿、辛散、佐以淡渗。人参、二术、橘红、半夏、桑白皮、白茯苓、泽泻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235600, '6BBBA43FBDB9F7D21E753FD4A2583CAC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7033, 405, 400104904, NULL, NULL, NULL, NULL, NULL, NULL, '4、五疸\n方书所载五疸，酒、食、大饥后、过饱、女劳失治而成。然其证必由湿热伤脾及饮食停滞。又有瘀血发黄一证，方所不载。分别一误，则药不对证，多致不救。慎之！慎之！\n【忌】破气、闭气、下、咸、滑利、滞腻、润、燥热，有瘀血者兼忌酸寒。诸药俱见前。\n【宜】清热、利水、除湿、养胃气，有停滞者宜消积滞，有瘀血者宜行血。茵陈蒿、黄连、苜蓿（酒疸非此不愈）、栀子、紫草、栝楼根、秦艽、黄芩、滑石、车前子、白鲜皮、仙人对坐草、白茯苓、连钱草（一名蟹靥草，一名九里香，取汁，入姜汁少许，饮之良。）\n虚者，加人参。\n停滞者，加红曲、橘红、谷麦糵、山查。\n瘀血，加琥珀、牡丹皮、红曲、红花、桃仁、延胡索、蒲黄、五灵脂、韭。\n元气壮实者，服前药瘀血不行，可加熟大黄。虚者勿用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235601, '79F0037CCE091263ACA8627A4CAA32EC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7034, 405, 400104903, NULL, NULL, NULL, NULL, NULL, NULL, '3、泻利\n俗称泄泻，因于湿。\n【忌】湿润、破气、下、苦寒、滑利。诸药俱见前。\n【宜】安胃补脾、升、利小便。人参、白茯苓、莲肉、白扁豆、白术、车前子、升麻、橘红、藿香、木瓜、干葛、炙甘草、白莱菔。\n虚寒者，加肉豆蔻、补骨脂、吴茱萸。\n虚热者，去白术，加川黄连，倍芍药、莲肉。\n暑湿为病则小水短赤，或口渴。倍用姜炒黄连为君，佐以干葛、升麻。\n由于感风寒者，二术、吴茱萸、砂仁、陈皮、干姜、紫苏主之。\n若由饮食停滞者，兼消导，山查、麦芽、神曲、陈皮、肉豆蔻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235602, '1033714C42E7F613DD377640AA4EBE50', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7035, 405, 400104902, NULL, NULL, NULL, NULL, NULL, NULL, '2、滞下\n俗呼痢疾。其证腹痛便脓血，或赤或白，或赤白相杂，或下纯血，或下紫黑血块，或如豆汁，或如鱼冻，或如屋漏水，或下纯黄积粪。多里急后重，数登圊而不得便，小便短赤不利，或发热，或口渴，甚则呕恶不思食。此皆暑湿之邪与饮食积滞胶固肠胃而作，必先祛暑渗湿安胃为主。伤气分则调气益气，伤血分则和血补血，挟瘀血则行血。药虽因证而设，要皆以补养胃气为急。故其证以噤口痢为最重，胃气一绝则不可治矣。故曰：安谷则昌，绝谷则亡。俗治多藉口 “迎而夺之” 之说，轻用大黄、朴硝，及误用巴豆、牵牛，以致洞泄肠开而毙。又有妄投诃子、粟壳、亚芙蓉、肉豆蔻收涩之剂，以致便闭腹胀，或湿热上攻，肢节肿胀拘挛，痛不可忍，难以救疗。慎之！慎之！\n【忌】破气、闭气、收涩、燥、温热、咸寒、滑腻。诸药俱见前。\n【宜】清热消积、开胃气、升、利小便。黄连、黄芩、白芍药、红曲、山查、广橘红、升麻、葛根、甘草、滑石、莲肉、白扁豆、乌梅。\n如胃弱，加人参（三四钱），莲子（四十粒），橘红（二钱），升麻（七分）。\n如腹痛，以黄连（四钱），白芍药（三钱），炙甘草（一钱五分），黄檗（一钱），升麻（七分）煎服。\n如里急，同上药加当归（二钱）。\n如后重甚，加槟榔（一钱五分），枳壳（一钱五分），木香汁（七匙）。\n如口渴，去木香，倍滑石。\n如小便赤涩短少，或不利，亦倍之。\n赤多，倍乌梅、山查、红曲。白多，加吴茱萸（七分）。\n恶心欲呕，即噤口痢，多用人参、莲肉、扁豆、白芍药，以绿色升麻（七分）佐之。\n久痢不止，加肉豆蔻（一钱），人参（三钱），砂仁（一钱五分），白茯苓（二钱）。\n凡滞下，非元气壮实、多啖能食之人，慎勿轻用大黄、巴豆、牵牛等下药。\n复有毒痢一证，或痧毒内陷下脓血，各药不效者，加忍冬藤为君，地榆、丹砂、犀角汁饮之。\n凡产后滞下，积滞虽多，腹痛虽极，不可用大黄等药行之，致伤胃气，遂不可救。但用人参、白芍、当归、红曲、升麻、益母草、炙甘草、滑石末足矣。若恶露未净，兼用乳香、没药（各七分五厘），炒砂仁（一钱），久之自愈。血虚可加阿胶（三钱）。\n凡胎前滞下，宜用黄芩、黄连、白芍、炙甘草、橘红、赤曲、枳壳、莲肉，略用升麻。未满七月，勿用滑石。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235603, '76A5671AD6102C328271E8CA629D807F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7036, 405, 400104901, NULL, NULL, NULL, NULL, NULL, NULL, '1、附录：诸疟主治\n热多宜贝母、石膏、麦门冬、橘红、干葛、滑石、竹叶、牛膝、知母、黄芩、柴胡、白茯苓、乌梅、何首乌、牡蛎、鳖甲。\n寒多宜桂枝、姜皮、人参、二术、黄耆、当归、橘红、半夏、草豆蔻、白豆蔻、炙甘草。\n汗多宜人参、白术、黄耆，秋冬加桂枝。\n无汗宜干葛、柴胡、石膏、羌活、姜皮、人参、苍术。\n疟母宜鳖甲、射干、牡蛎、三棱、缩砂蜜、桂、橘皮、青皮、人参。\n凡疟疾多热，久不解者，其人必本阴虚，法当益阴除热，非鳖甲、牛膝不能除也。多寒而久不解者，其人必本阳虚，非人参、白术、黄耆不能除也。\n按：疟有山岚瘴气、停痰留饮而发者，古方类用常山、砒霜等吐之。今人误执其方，见疟辄用，不知二药有大毒，损人真气，犯之多致危殆。慎之！慎之！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625759456235604, 'B593E095453EE3E8BF86D982683CEFD1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:21:47', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7037, 405, 400104916, NULL, NULL, NULL, NULL, NULL, NULL, '16、胃脘痛\n因火者，忌补敛、燥热。诸药俱见前。\n【宜】降、苦寒、甘寒、咸寒、辛寒。苏子、橘红、黄连、山栀、麦门冬、炙甘草、石膏、知母、玄参、童便。\n\n因寒者：忌破气、滞腻、苦寒。诸药俱见前。\n【宜】辛温发散。橘皮、草豆蔻、益智子、丁香、桂、白术、藿香、白豆蔻、缩砂蜜、吴茱萸、厚朴、香附、干姜。\n\n因宿食者：忌升、补敛、苦寒。诸药俱见前。\n【宜】消导，兼降气。山查、橘皮、草果、红曲、枳实、术、槟榔、草豆蔻、青皮、厚朴、谷麦糵、缩砂蜜。\n\n因脾胃虚弱以致食停者：消导药中加入人参。\n因瘀血者：忌补气、酸敛。诸药俱见前。\n【宜】辛温、苦温以行血。桃仁、延胡索、红曲、红花、山查肉、牡丹皮、韭菜、通草、番降香、郁金、肉桂、三棱、童溺、琥珀、菴闾子、牛膝、赤芍药。\n\n因血虚者，按之则痈止：忌破气，复忌补气、燥热、辛温。诸药俱见前。\n【宜】润、补敛、甘寒、甘温。麦门冬、炙甘草、酸枣仁、石斛、白芍药、生地黄、当归。\n\n因虫者：忌补、升、发散、甘。诸药俱见前。\n【宜】杀虫、苦、酸。锡灰、苦楝根、槟榔、鹤虱、雷丸、使君子、芜荑、薏苡仁根、大黄、乌梅。\n\n因恼怒者：虚弱人忌破气，壮实人忌补气，总忌酸敛、升。诸药俱见前。\n【宜】降气、辛温。苏子、枇杷叶、白豆蔻、番降香、缩砂蜜、木香、橘红、延胡索、五灵脂。\n因痰饮者：忌、宜俱见痰饮证下。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625762870751301, 'F9F98923E73703F57F0D77FDCA359F41', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:35:40', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7038, 405, 400104921, NULL, NULL, NULL, NULL, NULL, NULL, '21、鬼疰、尸疰、飞尸、客忤\n此系天地阴邪杀厉之气乘虚中人，或遍身青暗，或忽消瘦声哑，面色青黄不定，或忽惊厥，目直视，手握拳，或遍身骨节疼痛非常。\n【忌】破气，复忌补气、升、澡热、酸敛。诸药俱见前。\n【宜】辟恶气、安神镇心、辛香发散、金石镇坠。牛黄、丹砂、苏合香、天竺黄、琥珀、沉水香、龙脑香、乳香、安息香、檀香、木香、麝香、真珠、雄黄、鬼臼、龙齿、犀角、金银箔、虎骨、代赭石、天灵盖、獭肝、生地黄、菖蒲、远志。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625763206475845, 'BCA8AAFF7514350E8145D9888B46F4C4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:37:02', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7039, 405, 400104920, NULL, NULL, NULL, NULL, NULL, NULL, '20、交肠\n其病大小便易位而出。或因大怒，或因醉饱，遂至脏气乖乱，不循常道。法当宣吐以开提其气，使阑门清利，得司泌别之职，则愈矣。\n【忌】破气、燥、热。诸药俱见前。\n【宜】升清降浊，兼补气、淡渗。升麻、柴胡、苏子、降香、橘红、人参、术、茯苓、泽泻、猪苓、木通、滑石、车前子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625763206475846, 'A6E37F47A8B487437F2777B7823A9919', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:37:02', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7040, 405, 400104919, NULL, NULL, NULL, NULL, NULL, NULL, '19、痿\n属湿热。《经》曰：治痿独取阳明。\n【忌】破气、升、辛热发散。诸药俱见前。\n【宜】大补气血、清热除湿、甘寒、甘温、苦寒、酸寒。人参、黄耆、二术、炙甘草、生地黄、麦门冬、白芍药、木瓜、石斛、薏苡仁、黄檗、茯苓、泽泻、车前子、木通、黄连、黄芩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625763206475847, '8F52AEB3F8F7A5D786A2B2D334DAE019', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:37:02', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7041, 405, 400104918, NULL, NULL, NULL, NULL, NULL, NULL, '18、痹\n拘挛而痛也。因风寒湿三者合而成。风气胜者为行痹，寒气胜者为痛痹，湿气胜者为着痹。\n【忌】下、收敛、酸寒、苦寒、咸寒。诸药俱见前。\n【宜】辛散、行气、燥湿、甘温、淡渗。漆叶、续断、黄耆、甘草、甘菊花、萆薢、防己、白术、防风、羌活、独活、秦艽、牛膝、木瓜、天麻、茯苓、泽泻、菖蒲、车前子、桑寄生、狗脊、蔓荆实、杜仲、白藓皮、石斛、细辛、松节、松叶、葈耳、原蚕沙、威灵仙、海风藤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625763206475848, '4A21BC13D130877C67C88400BABA9556', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:37:02', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7042, 405, 400104917, NULL, NULL, NULL, NULL, NULL, NULL, '17、腹痛\n因于寒：忌苦寒、下利。诸药俱见前。\n【宜】温中、辛散。白术、厚朴、干姜、吴茱萸、桂、炙甘草、木香、缩砂蜜、橘皮。\n\n因于热，火在少腹则绞痛：忌辛热、香燥、补敛。诸药俱见前。\n【宜】甘、苦寒。山栀仁、麦门冬、石斛、白芍药、甘草、桔梗、黄芩、黄连、滑石、木通、戎盐。\n\n诸痛不可按，属实：忌补气、大热。诸药俱见前。\n【宜】破散、疏利、苦寒。枳实、青皮、槟榔、三棱、滑石、蓬莪术、木通、大黄（有积滞宜用，无者勿用）。\n\n诸痛可按，属虚：忌破气、破血、下利、发散。诸药俱见前。\n【宜】补气血、甘温、酸敛。人参、黄耆、二术、生地黄、当归、炙甘草、白芍药、薯蓣、酸枣仁、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625763206475849, 'FF687B381A09F42B5CA68D8DC1836146', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 15:37:02', 1, 'admin', '2024-12-23 15:37:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7043, 406, 400105033, NULL, NULL, NULL, NULL, NULL, NULL, '33、下乳汁。\n漏芦、狗四足、猪四足、麦门冬、人参、栝楼仁、土瓜根、葵子、猪胰、木通。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760710, 'BA6D602A5124518E51526F539C13F53B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7044, 406, 400105032, NULL, NULL, NULL, NULL, NULL, NULL, '32、产后恶心欲呕或吐 由于胃虚。\n【忌】升提发散、湿润、滞腻、苦寒、生冷、燥热。诸药俱见前。\n【宜】降气、补气、安胃、酸寒，佐以辛温。苏子、枇杷叶、竹茹、人参、橘红、麦门冬、白芍药、藿香、石斛、木瓜、白豆蔻、生姜。\n由于寒，倍生姜、白豆蔻、藿香。由于热，倍竹茹，去生姜、白豆蔻、藿香。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760711, 'ECFB0E380168D4B8AD471924F02BE1C7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7045, 406, 400105031, NULL, NULL, NULL, NULL, NULL, NULL, '31、产后腹胀 由于阴血虚、脾阴虚。\n【忌】破气宽中、升提发散、消导、吐、下、甘、苦寒、咸寒、大热、温燥、滞腻。诸药俱见前。\n【宜】益脾阴、补脾、和肝、酸寒、收敛、甘温。白芍药、酸枣仁、人参、茯苓、石斛、橘皮、薯蓣、五味子、木瓜、莲实、车前子、芡实。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760712, 'BF7223E84CEBD05ABDDBF06D01202A86', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7046, 406, 400105030, NULL, NULL, NULL, NULL, NULL, NULL, '30、产后不得眠。\n【忌】同产后大便闭结。\n【宜】补心、降心火、补肝、补脾阴，兼清内热。生地黄、麦门冬、茯神、丹参、沙参、酸枣仁、白芍药、竹叶、远志、莲肉、龙眼肉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760713, '58F85B9DEB045CCBB8F5123B2BD8E093', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7047, 406, 400105029, NULL, NULL, NULL, NULL, NULL, NULL, '29、产后大便闭结 由于血枯内热。\n【忌】补气、行血、辛热、燥、下、升、苦寒。诸药俱见前。\n【宜】益血、凉血、润燥、滋肝肾、生津液。生地黄、熟地黄、天门冬、麦门冬、五味子、蔗浆、牡丹皮、肉苁蓉、当归、麻仁、人乳、蜜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760714, '35570639F2557DA2ED50940E0369F6E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7048, 406, 400105028, NULL, NULL, NULL, NULL, NULL, NULL, '28、产后小便不利或短赤 由于肾水真阴不足。\n【忌】利小便，馀忌同产后发热。诸药俱见前。\n【宜】生津液、益阴、补血、凉血、清热、甘温、甘寒、酸寒。天门冬、麦门冬、生地黄、枸杞子、山茱萸、白芍药、车前子、牛膝、五味子、青蒿子、鳖甲、竹叶。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760715, '048503BA51D8B4548B7A3AE47319E297', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7049, 406, 400105027, NULL, NULL, NULL, NULL, NULL, NULL, '27、产后恶寒 由于气血两虚。\n【忌】同产后发热。\n【宜】补气血、温中、甘温，佐以辛温。人参、黄耆、炙甘草、干地黄、龙眼肉、当归、炮干姜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760716, 'F25EDFCAA6C11222EC094531E6BA7A95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7050, 406, 400105026, NULL, NULL, NULL, NULL, NULL, NULL, '26、产后气喘 由于气血两虚。\n【忌】同产后发热。\n【宜】补气血、润肺、下降。人参、橘红、生地黄、天门冬、麦门冬、苏子、枇杷叶、栝楼仁、栝楼根、童便、五味子、竹茹。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760717, '023F5B7BDFFB4A32909B3FA46FCC808D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7051, 406, 400105025, NULL, NULL, NULL, NULL, NULL, NULL, '25、产后发渴 由于血虚有热。\n【忌】同产后发热。\n【宜】同产后发热，加蔗浆，倍麦门冬、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760718, '11E8AD85F44C4EBF9031131907F0FD47', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7052, 406, 400105024, NULL, NULL, NULL, NULL, NULL, NULL, '24、产后头痛 由于血虚。\n【忌】发散、破血、升提、辛燥、大热。诸药俱见前。\n【宜】益血、凉血、降、甘温、甘寒，佐以酸寒。生地黄、甘菊花、乌梅、麦门冬、苏子、童便、甘草、当归、白芍药、黑豆、五味子、鳖甲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760719, '1C6A315832E9559603064B1420A12621', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7053, 406, 400105023, NULL, NULL, NULL, NULL, NULL, NULL, '23、产后发热或自汗盗汗。\n【忌】苦寒、发散、升提、破气、破血、下、辛燥、大热、寒滑伤脾。诸药俱见前。\n【宜】补血、凉血、补肝、补心、生津液、兼敛摄实表。干地黄、炙甘草、白芍药、五味子、麦门冬、酸枣仁、牡丹皮、童便、青蒿、鳖甲、泽兰、黑豆、黄耆、人参（肺热者禁用）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760720, '52673A2B80380B42CBF5995FD36204A4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7054, 406, 400105022, NULL, NULL, NULL, NULL, NULL, NULL, '22、产后泄泻。\n【忌】消导、滑肠、腻膈、发散、生冷、破气、苦寒。诸药俱见前。\n【宜】温中补气、健脾开胃。人参、甘草、薯蓣、莲肉、扁豆、茯苓、白芍药、橘皮、车前子、肉豆蔻（内热津液不足者少用）、藿香、五味子、补骨脂（内热火炽者勿用）、缩砂蜜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760721, 'F1359D80E4C879C5BED68BA32D62FAE9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7055, 406, 400105021, NULL, NULL, NULL, NULL, NULL, NULL, '21、产后少腹痛按之即止者，属血虚。\n【忌】行血、破气、汗、吐、下、燥、苦寒、大热。诸药俱见前。\n【宜】补血、补脾、和肝。干地黄、白芍药、当归、续断、白胶、阿胶、牛膝、人参、酸枣仁、麦门冬、炙甘草、大枣、薯蓣、橘皮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760722, '0EDD647FABF7605630F2173536991AA7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7056, 406, 400105020, NULL, NULL, NULL, NULL, NULL, NULL, '20、产后少腹痛 按之痛甚有结块，名儿枕痛。\n【忌】酸敛、补气、破气、升、下、汗、燥。诸药俱见前。\n【宜】行血活血散结，兼健脾。延胡索、红蓝花、牡丹皮、苏方木、山查肉、益母草、蓬莪术、蒲黄、白胶、当归、黑豆、生地黄、泽兰、牛膝、五灵脂、缩砂蜜、橘红、童便、桃仁、干姜。\n痛极加乳香、没药（各六七分）。天寒加桂，暑月勿用，肺热有火勿用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760723, '265DC10C58EB4F9B9F2332B1D5F20F1F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7057, 406, 400105019, NULL, NULL, NULL, NULL, NULL, NULL, '19、产后诸病（十四证）\n【忌】破气、升、汗、吐、下、燥、苦寒、大热。诸药俱见前。\n【宜】行血，次宜补血清热，总宜补养肝脾肾、辛温、甘寒、酸寒。苏木、黑豆、鹿角末、红花、乳香、没药、牛膝、炮姜、当归（脾胃弱者勿用）、桃仁（胃弱者禁用，亦不可过用）、桂（天寒无火之人可用）、益母草、泽兰、干地黄、续断、白胶、杜仲、山茱萸、人参、青蒿、麦门冬、白芍药、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760724, 'FD265A645E32EBFF450CF64B629FE49E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7058, 406, 400105018, NULL, NULL, NULL, NULL, NULL, NULL, '18、预防血晕\n腹痛坐草时，即用苏木菊花心者一两，生地黄一两，降香末二钱，水三碗，煎一碗，加童便半碗，儿堕地即饮之，永无恶血冲心之患。房中常打醋、炭，万一血晕亦须此药。更以家宝丹一丸，灌下神效。\n\n凡妇人气弱者，无气力送子出产门，须服人参。此药能兼治横生、倒产，世医不知也。\n\n凡临产交骨不开，惟浓煮柞木枝汤，饮之则自开。柞木俗名一叶一刺，其木枝干直上，每一叶必发一刺。\n\n胞衣不下，用乳香、没药末各七分五厘，麝香一分，芒硝一钱五分，研细。以酒调服，立下。饮热童便以滋药力，更妙。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760725, 'D91F4EBF920C38CD17AA3BF5ACA15CED', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7059, 406, 400105017, NULL, NULL, NULL, NULL, NULL, NULL, '17、难产\n【忌】破气、破血、收敛。诸药俱见前。\n【宜】补气血、滑利、润。人参、柞树枝、鱼胶、冬葵子、千里马、白芷梢、牛膝、桂心、当归、芎、益母草、百草霜、石燕、弓弩、麻油、猪脂、酒、生鸡子、兔头、滑石、麝香。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760726, '8181A8403525E9329AA6E3D50E23778F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7060, 406, 400105016, NULL, NULL, NULL, NULL, NULL, NULL, '16、胎漏\n属气血虚有热。\n忌、宜俱同安胎条。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760727, 'E3B0F0DBF19B1D7A437B5762C527661D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7061, 406, 400105015, NULL, NULL, NULL, NULL, NULL, NULL, '15、安胎\n【忌】破气、破血、升散、辛热、辛燥。诸药俱见前。\n八月以后及胎前滞下者，方可用枳壳，气虚者不用。\n三月以前宜养脾胃，四月以后宜壮腰肾，补血益阴，顺气，总宜清热。茯苓、麦门冬、薯蓣、人参、芍药、白术、橘红、炙甘草、缩砂蜜、艾叶、杜仲、生地黄、益母草、白胶、阿胶、续断、黄芩、枸杞子、青蒿子、桑寄生、鲤鱼、乌雌鸡、葱白。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760728, '3F5C3A0B64B34096357A9CE2FFCE4C64', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7062, 406, 400105014, NULL, NULL, NULL, NULL, NULL, NULL, '14、妊娠恶阻\n【忌】破气、升散、燥热、苦寒、滑肠、腻膈。诸药俱见前。\n【宜】顺气、甘寒、酸寒。苏子、橘红、枇杷叶、白茯苓、麦门冬、芦根、竹茹、木瓜、白芍药、竹叶、人参、缩砂蜜、白梅、乌梅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760729, 'FC30785AE318AE80F0A32506A74B3DF0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7063, 406, 400105013, NULL, NULL, NULL, NULL, NULL, NULL, '13、种子\n内分男、女，气虚、血虚、精寒、血热、火炽、精滑，因证选用。\n【忌】破气、破血、燥、过用辛热。诸药俱见前。\n【宜】调气补血，男子宜固精。桑螵蛸（温，平，治男子精滑）、柏实（甘，温，治男子精滑精寒）、海狗肾（咸，热，治男子精寒）、鱼胶（平，治男子精滑）、阳起石（热，治男子精寒）、覆盆子（甘，温，治男子精滑）、车前子（咸，寒，治男女火炽）、鹿茸（温，咸，治男子精寒）、莲须（甘，温，治男子精滑）、巴戟天（温，治男子精寒）、何首乌（苦，温，益男子气血）、牛膝（苦，平，治男子血虚阴痿）、补骨脂（辛，温，治男子精寒阴弱）、沙苑蒺藜（甘，平，男子固精益血）、白胶（温，平，治男女气血两虚精寒）、肉苁蓉（温，酸，咸，治男女血虚精寒）、黄檗（苦，寒，治男女火炽）、人参（微温，治男女气虚、脾胃薄弱）、麦门冬（甘，寒，男女血热）、五味子（酸，温，治男女精滑精寒）、山茱萸（酸，温，治男女精滑精寒）、天门冬（苦，寒，治男女火炽）、莲肉（甘，平，治男女胃弱精滑）、熟地黄（甘，寒，男女益血生精）、白薇（温平，女）、当归（辛温，女）、白芍药（酸寒，女）、紫石英（温，女）、艾叶（辛温，女）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760730, 'D32E248A2513E3E2B7821052AF84AB29', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7064, 406, 400105012, NULL, NULL, NULL, NULL, NULL, NULL, '12、热血入室\n类伤寒，或经事适来忽住，或届期不行，忽发大热、口渴，或厥，但不头疼为异于伤寒耳。\n【忌】补气、温燥、辛燥、收敛、下泄、大热、升发。诸药俱见前。\n【宜】行血清热、甘寒、咸寒、苦寒。生地黄、牡丹皮、蒲黄、苏木、牛膝、延胡索、麦门冬、犀角、白芍药、黄芩、童溺、荆芥穗。如便闭，加大黄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760731, '5A994DE1ECC5EBAD074421BD6A3DD8FF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7065, 406, 400105011, NULL, NULL, NULL, NULL, NULL, NULL, '11、崩中\n属气血两虚有热。\n【忌】破气、行血、降、温热、辛燥、苦寒。诸药俱见前。\n【宜】补气血，兼清热、甘温、甘寒、酸敛。人参、黄耆、生地黄、熟地黄、地榆、芍药、白胶、阿胶、香附、续断、甘草、麦门冬、山茱萸、杜仲、五味子、白茅根、蒲黄（炒）、桑耳灰、侧柏叶、艾叶、木耳灰。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760732, 'A4BA2F3240668A5D720EE5A14167C793', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7066, 406, 400105010, NULL, NULL, NULL, NULL, NULL, NULL, '10、月事过多\n属心火盛，脾气弱。\n【忌】破气、降、辛温、苦寒。诸药俱见前。\n【宜】凉血、敛摄、酸平、甘寒。麦冬、生地（泻泄禁用）、青蒿、生甘草、牡丹皮、白芍药、酸枣仁、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760733, '06BD8694238260558CCA5F6EC6399EC2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7067, 406, 400105009, NULL, NULL, NULL, NULL, NULL, NULL, '9、经行后期\n为血虚。\n【忌】行血、破气、燥热、苦寒。诸药俱见前。\n【宜】补肝肾、甘温、酸温。熟地黄、薯蓣、人参、菟丝子、山茱萸、杜仲、续断、阿胶、艾、五味子、当归、枸杞子、白胶、牛膝。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760734, '58BA793F6ABB7ECDBE8395A15B5351B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7068, 406, 400105008, NULL, NULL, NULL, NULL, NULL, NULL, '8、经行先期\n为血热。\n【忌】升、补气、辛温、燥热。香附、当归、乌药、艾（已上辛温）。余忌药俱见前。\n【宜】凉血清热、补肝肾，兼降气、甘寒、酸寒、苦寒。生地黄、牡丹皮、白芍药、天门冬、麦门冬、枸杞子、杜仲、青蒿、枇杷叶、苏子、鳖甲、阿胶、黄檗、黄芩、知母。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760735, '20656FCB38667E7D15DACAE08DE33F95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7069, 406, 400105007, NULL, NULL, NULL, NULL, NULL, NULL, '7、血枯经闭\n由于脾胃薄弱，气血不生。\n【忌】破气、破血、燥热、腻膈滑肠、升发、苦寒。诸药俱见前。\n【宜】补脾胃、甘温、甘平。人参、莲肉、酸枣仁、白扁豆、甘草、茯苓、薯蓣、橘红、白芍药、缩砂蜜、菟丝子、牛膝、牡丹皮、白胶、阿胶、芡实、麦门冬。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760736, 'CC66C5FA50686C3CD7639C86965E3B0C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7070, 406, 400105006, NULL, NULL, NULL, NULL, NULL, NULL, '6、标急而元气不甚惫者，先救其标；标急而元气衰剧者，则当本而标之可也。\n【忌】破气、降、温热。诸药俱见前。\n【宜】补敛、清热、辛甘、苦寒，佐以淡渗。生地黄、人参、白芍药、阿胶、山茱萸、黄檗、五味子、麦门冬、白胶、枸杞子、续断、杜仲、牛膝、白茯苓、车前子、泽泻、蛇床子、香附、补骨脂、牡蛎、艾、二术。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760737, '3157BD5EAD7070F9705DEE95F27A832F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7071, 406, 400105005, NULL, NULL, NULL, NULL, NULL, NULL, '5、赤带久不止则血虚，宜胶艾四物汤加便煅牡蛎粉、酸枣仁、麦门冬。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760738, 'CF75B10C8CEC945A6F94A0E203D7B64D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7072, 406, 400105004, NULL, NULL, NULL, NULL, NULL, NULL, '4、赤淋多因于心火、肝火时炽不已，久而阴血渐虚，中气渐损，遂下赤矣。治宜养心为主，兼以和肝缓中，凉血清气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760739, '82C03F994BC4AF2629B67A735642B83E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7073, 406, 400105003, NULL, NULL, NULL, NULL, NULL, NULL, '3、带下如鸡子清者，脾肾极虚也。面色必不华，足胫必浮，腰腿必酸，宜五味子、八味丸。间用开脾养心之剂，如归脾汤之类。阴虚有火，宜八味丸中加五味子、菟丝子、车前子、黄檗。叔和云：崩中日久为白带，漏下多时肾水枯。盖言崩久气血虚脱，而白滑之物下不止耳。此证虽有气血寒热之分，要归总属于虚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760740, '03EC965600CA40D11919668A4AB23101', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7074, 406, 400105002, NULL, NULL, NULL, NULL, NULL, NULL, '2、带下如浓泔而臭秽特甚者，湿热甚也，且多有湿痰下坠者，宜苍术、白术、黄檗、黄芩、车前子为主，佐以升提。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760741, 'F2BD2F5D2BD7ADB309F81940AD025988', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7075, 406, 400105001, NULL, NULL, NULL, NULL, NULL, NULL, '1、赤白带下\n妇人多忧思郁怒，损伤心脾，肝火时发，血走不归经，所以多患赤白带也。白带多是脾虚。盖肝气郁则脾受伤，脾伤则湿土之气下陷，是脾精不守，不能输为荣血，而下白滑之物矣。皆由风木郁于地中使然耳。法当开提肝气，补助脾元。宜以补中益气汤，加酸枣仁、茯苓、山药、黄檗、苍术、麦门冬之类，浓煎，不时饮之。再用六味地黄丸中加牡蛎粉、海螵蛸、杜仲、牛膝，蜜丸，光大如豆。空心饥时吞下五六钱。阳虚火炽加枸杞子、五味子、黄檗。白带多属气虚，补气健脾，治法之要领也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625770171760742, '8D4A33BED80B59FDFE5830E40D23DC8A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:05:23', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7076, 407, 400105116, NULL, NULL, NULL, NULL, NULL, NULL, '16、胎毒\n【忌】补敛、燥热、辛温。诸药俱见前。\n【宜】凉血清热、解毒，兼发散于外。勿从外治，以致热毒内攻。生地黄、玄参、牡丹皮、黄檗、黄连、忍冬藤、甘草、连翘、麦门冬、贝母、犀角、荆芥、鼠粘子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410310, 'F9F272F9A2B05CCDA7796C024F4A2BFA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7077, 407, 400105115, NULL, NULL, NULL, NULL, NULL, NULL, '15、诸虫\n【忌】升，甘。诸药俱见前。\n【宜】杀虫、酸寒、苦寒，佐以辛寒。槟榔、雷丸、使君子、苦楝根、锡灰、鹤虱、芦荟、芍药、乌梅、黄连、黄芩、牵牛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410311, 'EDDCB527A5F0A64627CFBAFE3DE1DE63', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7078, 407, 400105114, NULL, NULL, NULL, NULL, NULL, NULL, '14、疳积\n【忌】破气、酸敛、燥热。诸药俱见前。\n【宜】除疳热，兼消导、苦寒、甘寒，佐以辛寒、辛温。胡黄连、川黄连、肉豆蔻、谷麦糵、神曲、山查、木香、橘皮、白芜荑、使君子、芦会、白术、白芙蓉花、五谷虫、雷丸、青黛、厚朴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410312, 'ABBF604DD97E36C692E5CE876CDA7EFE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7079, 407, 400105113, NULL, NULL, NULL, NULL, NULL, NULL, '13、慢惊\n多因久吐泻、大病后阴阳两虚而成。\n【忌】破气、下、升、苦寒，及治急惊药。诸药俱见前。\n【宜】补脾健胃、和肝益气、甘温、酸平、佐以辛热。人参、黄耆、茯苓、白芍药、甘草、龙眼肉、酸枣仁、石菖蒲、远志、麦门冬、茯神、冬瓜仁、橘红。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410313, 'D2E470FD05F1B63C66850909C6641958', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7080, 407, 400105112, NULL, NULL, NULL, NULL, NULL, NULL, '12、急惊\n【忌】补敛、升、燥热。诸药俱见前。\n【宜】降、清热、镇坠、豁痰、和肝。丹砂、琥珀、牛黄、天竺黄、贝母、竹沥、钓藤钩、僵蚕、茯神、犀角、金箔、胆星、真珠、全蝎、龙脑、麝香、白檀香。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410314, '7D82C003252811094E8386BAF4A08010', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7081, 407, 400105111, NULL, NULL, NULL, NULL, NULL, NULL, '11、泄泻\n总忌破气、下、滑利、滞腻。诸药俱见前。\n因食者：宜和胃消食。橘皮、草果、红曲、谷麦糵、白豆蔻、白术、山查、白茯苓、肉豆蔻、缩砂蜜。\n\n因湿者：宜燥脾、利水。二术、橘皮、木瓜、茯苓、泽泻、车前子、石斛、黄连、薯蓣、猪苓、升麻、葛根。\n\n因暑者：宜前药中加人参、莲肉、白扁豆。\n总之当补脾胃，兼升，兼利小便。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410315, 'C664AA8B53E189FBE2CB7B03128EFC6A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7082, 407, 400105110, NULL, NULL, NULL, NULL, NULL, NULL, '10、呕吐\n因伤乳食者。\n【忌】升、苦寒。诸药俱见前。\n【宜】温中、消导。橘皮、缩砂蜜、枳实、厚朴、谷麦糵、草果、山查、红曲、半夏、人参。\n\n因寒者：忌破气、升、苦寒。诸药俱见前者。\n【宜】辛热、温中。藿香、橘皮、丁香、人参、白术、生姜、半夏、白豆蔻。\n\n因暑者：忌升、破气、温热。诸药俱见前。\n【宜】清暑、补气、安胃，兼利小便。黄连、香薷、人参、木瓜、茯苓、竹茹、石斛、橘皮、甘草、白扁豆、麦门冬、白梅、滑石、木通、泽泻。\n\n有虫者：忌升、甘。诸药俱见前。\n【宜】酸敛，佐以苦寒。白芍药、五味子、木瓜、黄连、楝根、乌梅、槟榔、榧子肉、木香、使君子。\n总之，数呕吐宜安胃，久则宜补气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410316, 'D935C8F71FDF484C8701062A83A17484', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7083, 407, 400105109, NULL, NULL, NULL, NULL, NULL, NULL, '9、痧疹不宜依证施治，惟当治本。本者，手太阴、足阳明二经之邪热也。解其邪热，则诸证自退矣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410317, '7242CF4057CE9B2FC3CE3F5B8FCB9765', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7084, 407, 400105108, NULL, NULL, NULL, NULL, NULL, NULL, '8、痧后生疮不已，余热未尽故也。宜用金银花、荆芥穗、连翘、玄参、甘草、怀生地、鳖虱胡麻、黄连、木通，浓煎饮之良。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410318, '9717A8187639618C11AA2188567959B4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7085, 407, 400105107, NULL, NULL, NULL, NULL, NULL, NULL, '7、痧后元气不复，脾胃薄弱者，宜用白芍药、炙甘草为君，莲肉、山药、白扁豆、麦门冬、青黛、龙眼肉为臣。多服必渐强，慎勿轻用参、术。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410319, '6A790430F97227CF3F748F9990EF5DD5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7086, 407, 400105106, NULL, NULL, NULL, NULL, NULL, NULL, '6、疹后牙疳最危，外用牡黄牛粪尖，煅存性，研极细，加真片脑一分，研匀吹之；内用连翘、干葛、荆芥穗、升麻、玄参、黄连、甘草、生地黄，水煎，加生犀角汁二三十匙调服。缓则不可救药。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410320, '11B8EC7F0BC0F1F51F5669D3ECF8C9F1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7087, 407, 400105105, NULL, NULL, NULL, NULL, NULL, NULL, '5、痧疹乃肺胃邪热所致，初发时必咳嗽，宜清热透毒，不得止嗽。疹后咳嗽，但用贝母、苦梗、甘草、薄荷、栝楼根、玄参、麦门冬，以清余热、消痰壅，则自愈，慎勿用五味子等收敛之剂。多喘，喘者邪热壅于肺故也，慎勿用定喘药，惟应大剂竹叶石膏汤加西河柳两许，玄参、薄荷各二钱。如冬天寒甚，痧毒郁于内，不得透出者，加蜜酒炒麻黄一剂，立止。凡热势甚者，即用白虎汤加西河柳，忌用升麻，服之必喘。多泄泻，慎勿止泻，惟用黄连、干葛、升麻、甘草、则泻自止。疹家不忌泻，泻则阳明之邪热得解，是亦表里分消之义也。疹后泄泻及便脓血，皆由邪热内陷故也，大忌止涩，惟宜升散，仍用升麻、甘草、干葛、黄连、白芍药、白扁豆。便脓血则加滑石末，必自愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410321, 'D465744A01B539EAA2A8E25FBF8A8AB0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7088, 407, 400105104, NULL, NULL, NULL, NULL, NULL, NULL, '4、痧疹者，手太阴肺、足阳明胃二经之火热发而为病者也。小儿居多，大人亦时有之。殆时气瘟疫之类欤？其证类多咳嗽，多嚏，眼中如泪，多泄泻，多痰，多热，多渴，多烦闷，甚则躁乱，咽痛，唇焦神昏，是其候也。治法当以清凉发散为主。药用辛寒、甘寒、苦寒以升发之。惟忌酸敛，最宜辛散。误施温补，祸不旋踵。辛散如荆芥、西河柳、干葛、石膏、鼠粘子、麻黄；清凉如玄参、竹叶、栝楼根、青黛、薄荷；甘寒如麦门冬、生甘草、蔗浆；苦寒如黄芩、黄连、黄檗、贝母、连翘。随证轻重，制剂大小，中病则已，毋太过焉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410322, '73943A4E30919883D9FBCF58E339600E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7089, 407, 400105103, NULL, NULL, NULL, NULL, NULL, NULL, '3、如冬月，佐之以辛散，荆芥、麻黄（去节沫，蜜酒炒，只可用一剂）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410323, '3476697AD2BBDB39C694079241B5EA9A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7090, 407, 400105102, NULL, NULL, NULL, NULL, NULL, NULL, '2、痧疹\n此证多有呕吐者，勿治呕吐，但治痧毒，则呕自止，况呕中便有发散之义。\n【忌】破气、温补、酸敛、燥热、辛温、滞腻。诸药俱见前。\n【宜】清热透肌、辛寒、甘寒、苦寒。石膏、鼠粘子、赤柽木（即西河柳）、知母、甘草、玄参、麦门冬、连翘、薄荷、竹叶、黄连、黄芩、葛根、黄檗、蝉蜕、栝楼根、青黛、蔗浆、贝母。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410324, '5B16F392548088495FA69A2CF71EE975', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7091, 407, 400105101, NULL, NULL, NULL, NULL, NULL, NULL, '1、痘疮\n血热证：忌温补、燥热。天灵盖、鸡冠血、桑蠹、鲮鲤甲、人齿、官桂、附子、丁香、木香、冰片（已上燥热）、馀忌药俱见前。\n【宜】凉血、活血、解毒、甘寒、苦寒。犀角、生地黄、人中黄、紫草、黄连、麦门冬、牡丹皮、白芍药、童溺、连翘、金银花、玄参、贝母、蝉蜕、鼠粘子。\n\n虚寒证：忌汗、吐、下、苦寒、酸寒。诸药俱见前。\n【宜】辛甘发散、补气、温，疮密者佐以解毒。人参、红铅、黄耆、甘草、桂枝、丁香、当归（胃弱大便不闭者禁用）、莲肉、糯米、大枣、龙眼肉、干葛、木香、忍冬藤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625774854410325, '8D36C1377047E5A3817F7741A90898F3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:24:26', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7092, 408, 400105218, NULL, NULL, NULL, NULL, NULL, NULL, '18、漆疮\n【宜】蟹、茱萸皮、鸡子白、杉材、石蟹、漆姑草、韭莱（炒热罨上）、井中苔萍。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394822, 'A6DCDF3E7484300572C3194F87DBAB37', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7093, 408, 400105217, NULL, NULL, NULL, NULL, NULL, NULL, '17、火灼\n【忌】燥热及寒物涂罨。井泥、冰、凉水、芭蕉根、醋（已上寒物涂罨）、馀忌药俱见前。\n【宜】拔散火毒、辛散、润、甘寒、辛寒、苦寒。柴胡、葛根、甘草、升麻、黄连、麦门冬、连翘、栝楼根、石膏、黄檗、鸡子油、柏白皮、生胡麻、食盐、豆酱、黄芩、地榆、山栀。\n外用好酒满浸伤处，温即易之。如遍体被伤，用酒满浸，时时易之即不死。一方用蜜水润之。一方石灰水和生芝麻油敷，治已烂臭甚者，神验。一方用粘米炒黑，为末，将菜汁调敷，神效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394823, 'A0B401FBC82FE0E09401D5972DCF0A09', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7094, 408, 400105216, NULL, NULL, NULL, NULL, NULL, NULL, '16、踒折挫闪\n忌、宜俱同金疮、跌扑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394824, 'EC62E82F0F9E611BCA0A2C88273738E7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7095, 408, 400105215, NULL, NULL, NULL, NULL, NULL, NULL, '15、跌扑损伤\n【忌】同金疮。\n【宜】同金疮。有瘀血停滞者，宜加行血药，如桃仁、红花、苏木、自然铜、䗪虫、千年灰、古文钱之属。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394825, 'F97CD24003E4095B5D1F9C34A244D135', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7096, 408, 400105214, NULL, NULL, NULL, NULL, NULL, NULL, '14、破伤风\n【忌】同金疮。\n【宜】同金疮，佐以祛风药，如白芷、荆芥、防风、柴胡之属。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394826, '156011CBE103612F5CA38EEDBB280678', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7097, 408, 400105213, NULL, NULL, NULL, NULL, NULL, NULL, '13、金疮\n【忌】破气、闭气、升散、酸敛、苦寒、冷利、燥、酸寒。诸药俱见前。\n【【宜】止血、和血、凉血、甘温、甘寒，佐以辛温。地黄、䗪虫、当归、续断、牛膝、甘草、麦门冬、地榆、半夏、茜草、白胶、杜仲、芎、乳香、没药、艾叶、水杨花、钓樟根、黄荆子（炒黑）、王不留行、古钱、自然铜、狗头骨、黄麻皮灰、芦竹箨、韭、大小蓟（内外）、刘寄奴（内外）、花蕊石（内外）、麒麟竭（内外）、古石灰（外）、白蜡（外）、降香（外）、海螵蛸（外）、桑柴灰（外）、人骨灰（外）、紫檀末（外）、三七（外）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394827, '417D5F8A1A57A5D8498FDC2F9081AF60', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7098, 408, 400105212, NULL, NULL, NULL, NULL, NULL, NULL, '12、阴蚀（即下部疮）\n【忌】同乳岩。\n【宜】凉血活血、除热散毒、苦寒、辛寒。青黛、茜草、苦参、鲜地骨皮、黄檗、小蓟、艾叶、马鞭草、木瓜、牛膝、木通、全蝎（外）、蛇床子（外）、橄榄核（外）、蛀竹屑（外）、猪脊髓（外）、青葙子（外）、腻粉（外）、官粉（外）、杏仁（外）、珠末（外）、皂角末（外）、铅丹（外）、象牙末（外）、龙脑香（外）、白僵蚕（外）、粉霜（外）、烟膏（外）、天灵盖（外）、滴乳石（外）、白蜡（外）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394828, 'AC92FA643BD191C98D094B62E47414B4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7099, 408, 400105211, NULL, NULL, NULL, NULL, NULL, NULL, '11、乳岩、乳痈、内外吹\n【忌】补气、升、温补、辛热、燥、酸敛。\n【宜】散结气、和肝、凉血活血，清热解毒。贝母、橘叶、连翘、栝楼根、山慈菇、山豆根、蒲公英、紫花地丁、黄连、甘草、柴胡、白芷、青皮、橘皮、牡鼠粪、王不留行、乳香、没药、漏芦、夏枯草、忍冬藤、栝楼仁、头垢、人爪、鲮鲤甲、半枝莲、茜根。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394829, '1A16CFC481CDEAC4B1ED9D499A104ACD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7100, 408, 400105210, NULL, NULL, NULL, NULL, NULL, NULL, '10、通肠漏\n【忌】破气、下、发散、温燥、辛热。诸药俱见前。\n【宜】凉血、清利湿热、解毒、消漏管、补气血、长肉。槐实、黄连、黄芩、青黛、地榆、白及、忍冬藤、半枝莲、生地黄（已上凉血解毒）、猪悬蹄、黄牛角䚡、刺猬皮、蛀竹屑、明矾、金头蜈蚣（已上消漏管）、黄耆、熟地黄、当归、人参、白芍药、五味子、牛膝、山药、枯矾、黄蜡、白蜡、麻皮灰、铅华、月经布、没食子（已上补气血长肉）、天明精、地骨皮（俱要鲜者）、皮硝、文蛤（已上煎浓汤熏洗）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394830, 'A2D1542A046E2FE71EF3D8B4E4899DF0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7101, 408, 400105209, NULL, NULL, NULL, NULL, NULL, NULL, '9、痔（有内外二证）\n【忌】破气、降、燥热、辛温。诸药俱见前。\n【宜】凉血、活血、除大肠热，兼升。去血过多者宜补血、甘寒、苦寒、酸寒，佐以辛寒。生地黄、五倍子、黄连、黄芩、白芍药、地榆、猬皮、大小蓟、黄檗、侧柏叶、槐实、皂荚灰、熊胆、升麻、鳖甲、红蓝花、龙脑香、茜草、黄耆、赤石脂、猪悬蹄、蛇蜕、榧实、白矾、金银花、青黛、象牙末、蛀竹屑、牛角䚡、白蜡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394831, '44342F385FD32A47CD072C6AACD888DE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7102, 408, 400105208, NULL, NULL, NULL, NULL, NULL, NULL, '8、瘿瘤\n忌、宜俱同瘰疬，兼宜薜荔、半夏、文蛤、南星、通草、生姜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394832, '9B2DAA441C4AA314C64AA6FA97D328AF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7103, 408, 400105207, NULL, NULL, NULL, NULL, NULL, NULL, '7、瘰疬（马刀疮附）\n同属少阳胆经，治法亦同。\n【忌】补气、辛热、酸敛。诸药俱见前。\n【宜】清热散结、和肝凉胆、苦寒、甘寒、咸寒，佐以辛寒。连翘、玄参、忍冬藤、紫背天葵、乳香、麝香、夏枯草、鼠粘子、贝母、天明精、没药、薄荷、肥皂荚、皂角子、何首乌、柴胡、黄芩、甘草、昆布、牡蛎、鳖甲、栝楼根、恶实、漏芦、守宫（煅）、猫头、天荷叶、映山红、海藻、海蛤、苏合油、雄黄、矾石、斑猫、蟾酥、鳖虱胡麻、回燕窝泥。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394833, 'CD3C00CAC4241BF35AC922C5D45BB412', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7104, 408, 400105206, NULL, NULL, NULL, NULL, NULL, NULL, '6、疔疮\n【忌】补敛、温热。诸药俱见前。\n【宜】凉血活血、解毒、祛风、汗、下。生甘草、辟虺雷、茜草、生地草、贝母、紫花地丁、白药子、大黄、金银花、苍耳草、连翘、夏枯草、鼠粘子、矾石（已上内）、半枝莲、牛黄、蟾酥、红药子、白及、白敛（已上内外）、龙脑、铁锈、桑硇、铜青、雄黄（已上外）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394834, '6F55C8148481B984563D784409731887', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7105, 408, 400105205, NULL, NULL, NULL, NULL, NULL, NULL, '5、溃疡\n【忌】闭气、苦寒、破气，又忌躁。诸药俱见前。\n【宜】补气血、甘、酸温，佐以解毒。人参、红铅、胎骨、黄耆、当归、地黄、芍药、甘草、白及、白敛、忍冬藤、甘菊花、贝母、薯蓣、大枣、五味子、麦门冬。\n散毒（外傅）。雄黄、雌黄、粉锡、矾石、龙脑香、松脂、地榆、水银粉、铁锈、白及、白敛、漏芦、檗木、青葙子、楝实、䕡茹、石灰、铁浆、苦参、菖蒲、槲皮、葵根、柳华、五加皮、梓叶、苎根、紫草、马鞭草、艾（灸）。\n\n止痛排脓（外傅）。白及、白敛、大黄、乳香、没药、丹砂、红药子、龙脑、金华、白药子、麦饭石、米醋、蜜。\n\n去瘀肉（外傅）。巴豆膏、轻粉、粉霜、乌梅肉灰。\n\n蚀脓（外傅）。蛀竹屑、䕡茹、雄黄、白芷、大黄、巴豆、地榆、枯矾。\n\n长肉收口（外傅）。仙人杖（烧油）、人参、金华、白蜡、黄蜡、血竭、蛀竹屑、枯矾末、黄芩末、珠末、象牙末、铅丹、红粉霜、胡粉、芝麻油、猪蹄汤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394835, '478070FF47B6BA2E9CBE7931AE872BEA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7106, 408, 400105204, NULL, NULL, NULL, NULL, NULL, NULL, '4、痈疽毒气攻心，发谵语\n【宜】以生绿豆粉、丹砂、乳香，为丸服之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394836, '907C24DEAF8FE13933C0AA31EC6DE3AC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7107, 408, 400105203, NULL, NULL, NULL, NULL, NULL, NULL, '3、肿疡\n忌、宜俱同痈疽。先后发渴，更忌当归。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394837, '2676314C08A3C61BA90017D555B4E52F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7108, 408, 400105202, NULL, NULL, NULL, NULL, NULL, NULL, '2、痈疽先后发渴\n【忌】升、破气、辛温、燥热、吐、下。诸药俱见前。\n【宜】活血、凉血、解毒散结。生地黄、连翘、忍冬藤、白芷、白及、白敛、茜草、紫花地丁、夏枯草、甘菊花、地榆、贝母、鼠粘子、黄檗、栝楼根、乳香、没药、芍药、生绿豆、半枝莲、白药子、红药子、黄蜡、明矾。\n已溃者加人参、黄耆、麦门冬、五味子。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394838, 'A1687370A1F40B23AE5C6C02F8CA73F0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7109, 408, 400105201, NULL, NULL, NULL, NULL, NULL, NULL, '1、疬风\n【忌】破气、酸敛、燥热、下。诸药俱见前。\n【宜】凉血、杀虫、祛风、苦寒，佐以辛寒辛平。豨莶、天门冬、甘菊花、生地黄、青黛、漆叶、苦参、何首乌、鳖虱胡麻仁、白芷、荆芥、天麻、续断、羌、独活、半枝莲、白花蛇、乌梢蛇、皂角刺。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625777960394839, '6D920E10F913F3F20BD540C53757727A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:37:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7110, 409, 400105301, '       味甘，微寒，无毒。主身体五藏百病，养精神，安魂魄，益气明目，通血脉，止烦满消渴，益精神，悦泽人面。杀精魅邪恶鬼，除中恶腹痛，毒气，疥瘘诸疮。久服通神明不老，轻身神仙。能化为汞。作末名真朱。光色如云母，可析者良。（恶磁石，畏碱水。）\n\n       疏：丹砂本禀地二之火气以生，而兼得乎天七之气以成。色赤法火，中含水液。为龙为汞，亦曰阴精。七为阳火之少，故味甘微寒而无毒，盖指生砂而言也。《药性论》云：丹砂为清镇少阴君火之上药，辟除鬼魅百邪之神物。安定神明则精气自固，火不妄炎则金木得平，而魂魄自定，气力自倍。五脏皆安则精华上发，故明目。心主血脉，心火宁谧，则阴分无热而血脉自通，烦满自止，消渴自除矣。杀精魅邪恶鬼，除中恶腹痛者，阳明神物，故能辟除不祥，消散阴恶杀厉之气也。久服通神明不老者，古之真人，飞丹炼石，引纳清和，配以金铅，按之法象，自能合丹道而成变化也。青霞子及太清服炼灵砂法云：能重能轻，能暗能明，能黑能白，能神能灵。一斛人擎，力难举升：万斤遇火，轻速上腾。鬼神寻求，莫知所在。先禀气于甲，受气于丙，出胎见壬，结魄成庚，增光归戊，阴阳升降，各本其原。非虚语矣！\n\n【主治参与】\n        丹砂研飞极细，令状如飞尘，以甘草、生地黄浓煎，调分许，与儿初生时服之，能止胎惊，解胎毒。\n同真珠、琥珀、金箔、牛黄、生犀角、天竺黄、滑石末，治小儿急惊，有神。\n入六一散，治暑气伏于心经，神昏口渴，及泄泻如火热。\n入补心丹，镇心神，定魂魄。\n入乳香托里散，散痈疽热毒，发热疼痛，及毒气攻心发谵语。\n\n【简误】\n       丹砂为八石之主，故列石部之首。体中含汞，汞味本辛，故能杀虫、杀精魅。宜乎《药性论》谓其有大毒。若经伏火，及一切烹炼，则毒等砒、硇，服之必毙。自唐以来，上而人主，下而缙绅，曾饵斯药，鲜克免者。戒之！戒之！', NULL, NULL, NULL, '丹砂', NULL, '1、丹砂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625781558288454, '59432F04ACF78F656F0337D58CFFC3F9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 16:51:43', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7111, 409, 400105304, '       味酸，寒，无毒。主寒热，泄痢，白沃，阴蚀恶疮，目痛，坚骨齿，除固热在骨髓，去鼻中息肉。炼饵服之，轻身不老增年。岐伯云：久服伤人骨，能使铁为铜。生河西山谷，及陇西武都石门。（甘草为之使。恶牡蛎，畏麻黄）\n\n疏：矾石味酸，气寒而无毒。其性燥急，收涩解毒，除热坠浊。盖寒热泄痢，皆湿热所为；妇人白沃，多由虚脱，涩以止脱故也。阴蚀恶疮，亦缘湿火。目痛多由风热，除固热在骨髓，坚齿者，髓为热所劫则空，故骨痿而齿浮。矾性入骨除热，故亦主之。去鼻中息肉者，消毒除热燥湿之功也。\n\n【主治参与】\n矾石即白矾，得巴豆同煅令枯。取矾研末，以鹅翎管吹入喉中，流出热涎立解。喉痹其证，俗呼为缠喉风是也。\n皮肤疥癣，脓窠、坐板、肥疳等疮，皆资其用，各合所宜以施之。\n得硫黄、雄黄、白附子、海金沙、蜜陀僧，擦汗斑殊效。一年者去皮一次，十年者去皮十次。擦后坐卧勿当风，勿行房摇扇。\n制半夏，能散湿痰及食积痰，兼除五饮。\n同芒硝可烧水银成粉，治一切疮中有虫。\n得黄蜡和丸，名蜡矾丸，治一切疮毒有神。凡治痈疽，当服之以护膜，膜苟不破，虽剧必瘥。\n\n陈师古方：中风痰厥，四肢不收，气闭膈塞者，白矾一两，牙皂角五钱，为末。每服一钱，温水调下，吐痰为度。\n\n《简要济众方》：牙齿肿痛，白矾一两烧灰，大露蜂房一两微炙，每二钱水煎，含漱去涎。\n《千金方》：鼻中息肉：用明矾一两，蓖麻仁七粒，盐梅肉五个，麝香一字，捣丸，绵裹塞之，化水自下也。\n夏子益《奇疾方》：发斑怪证：有人眼赤鼻张，大喘，浑身出斑，毛发如铜铁，乃热毒气结于下焦也。白矾、滑石各一两为末。水三碗，煎减半，不住，服尽即安。\n《永类钤方》：烂弦风眼，白矾煅一两，铜青三钱，研末，汤泡澄清，点洗。\n《千金方》：脚气冲心：白矾三两，水一斗五升，煎沸浸洗。\n张仲景《金匮》方：女劳黄疸，日晡发热而反恶寒，膀胱急，少腹满，目尽黄，额上黑，足下热，因作黑疸。其腹胀如水状，大便必黑，时溏，此女劳之病，非水也，自大劳大热交接后入水所致。腹满者难治。用矾石烧，硝石熬黄，等分为散。以大麦粥汁和服方寸匕，日三服。病从大小便去。\n又《金匮》方：妇人白沃，经水不利，子脏坚癖，中有干血，下白物：用矾石三分烧，杏仁一分，研匀，蜜丸枣核大，纳入肠中，日一易之。\n《千金翼》：妇人阴脱作痒，矾石烧研，空心酒服方寸匕，日三。\n\n刘禹锡《传信方》：蛇咬蝎螫：烧刀矛头令赤，置白矾于上，汁出，热滴之，立瘥。此神验之方也。\n\n【简误】\n白矾，《本经》主寒热泄痢，此盖指泄痢久不止，虚脱滑泄，因发寒热。矾性过涩，涩以止脱，故能主之。假令湿热方炽，积滞正多，误用收涩，为害不一。慎之！妇人白沃，多由虚脱。故用收涩以固其标，终非探本之治。目痛不由弩肉及有外障，亦非所宜。除固热在骨髓，仅可资其引导，若谓其独用，反有损也。矾性燥急而能劫水，故不利齿骨。齿者骨之余故也。岐伯云：久服伤人骨。故凡阴虚内热，火炽水涸，发为咽喉痛者，不宜含此。目痛由阴虚血热者，亦不宜用劫水损骨之药，岂可炼服，轻身不老增年？徒虚语耳！\n', NULL, NULL, NULL, '矾石', NULL, '4、矾石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625785487585349, '512A5CA923E049750A7E2D9890539C82', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:07:42', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7112, 409, 400105303, '      味甘，温，无毒。主咳逆上气，明目益精，安五藏，通百节，利九窍，下乳汁，益气，补虚损，疗脚弱疼冷，下焦伤竭，强阴。久服延年益寿，好颜色，不老，令人有子。不炼服之，令人淋。（蛇床为之使。恶牡丹、玄参、紫石英。）\n\n疏：石钟乳禀石之气而生。《本经》谓其味甘，气温，无毒。吴普曰：神农辛。斯言近之。甄权以为有大毒，或是经火之故。应云味甘辛，气大温，其性得火则有大毒，乃为得之。其主咳逆上气者，以气虚则不能归元，发为斯证。乳性温而镇坠，使气得归元则病自愈，故能主之也。通百节、利九窍、下乳汁者，辛温之力也。疗脚弱疼冷者，亦是阳气下行之验也。甄权主寒嗽、通声者，辛以散邪结，温以祛寒气故也。其他种种补益之说，当是前人好事者溢美之辞。夷考其性，恐无是理，未足信也。\n\n【主治参与】\n石钟乳得牛黄、白蜡、象牙末、真珠、乳香、没药、桦皮灰、龟板灰，俱存性细研，枯白矾、蛀竹屑、红铅，治广疮结毒，烂环鼻梁，及阴蚀阳物，有神。\n孙真人《千金翼》钟乳煎：治风虚劳损，腰脚无力，补益强壮。用钟乳粉炼成者三两，以夹绢袋盛之，牛乳一大升，煎减三之一，去袋饮乳，分二服，日一作。不吐不利，虚冷人微溏无所苦。一袋可煮三十度，力尽别作袋。每煎迄，须濯净，令通气。其滓和面，煨鸡子食之，此崔尚书方也。\n\n《宣明方》治一切劳嗽，胸膈痞满，焚香透膈散：用鹅管石、雄黄、佛耳草、款冬花，等分为末。每用一钱，安香炉上焚之，以筒吸烟入喉中，日二次。\n《圣济总录》治肺虚喘急，连绵不息。生钟乳粉光明者五钱，蜡三两和化，饭甑内蒸熟，研丸如梧子大。每水下一丸。\n《外台秘要》治乳汁不通，气少血衰，脉涩不行，故少乳。炼成钟乳粉二钱，浓煎漏芦汤调下，或通草等分为末，米饮服方寸匕，日三服。\n\n【简误】\n石钟乳辛温，若加火炼，有毒无疑。纵治虚寒，尚须审察，况病涉温热者耶？世人病阴虚有热者十之九，阳虚内寒者百之一。是以自唐迄今，因服钟乳而发病者不可胜纪，服之而获效得力者不闻一二。其于事理，可以烛照。经曰：石药之性悍。味斯言也，则其大略可概见已。慎毋轻信方士之言，致蹈前人覆辙。尊生之士，宜安常处，顺以道理，自持修短有命，无惑乎长年之说，庶不为其所误矣。', NULL, NULL, NULL, '石钟乳', NULL, '3、石钟乳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625785487585350, 'CF4077BC1F77EE7F5FE481D19E1E96D4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:07:42', 1, 'admin', '2025-01-15 09:16:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7113, 409, 400105302, '        味甘，平，无毒。主身皮死肌，中风寒热，如在车船上。除邪气，安五藏，益子精。明目，下气，坚肌，续绝补中，疗五劳七伤，虚损少气，止痢。久服轻身延年，悦泽不老，耐寒暑，志高神仙。一名云珠，色多赤；一名云华，五色具；一名云英，色多青；一名云液，色多白；一名云砂，色青黄；一名磷石，色正白。（泽泻为之使，忌羊血，用矾石则柔烂。）\n\n        疏：云母《本经》载其味甘，气平，详其主治，亦应有温。韩保升曰：云母色白而主肺，此石药中温良之品也。以其法金，故主身皮死肌，及中风寒热，如在车船上。甘能缓，温能和，故除邪气。石性镇坠，能使火下，火下则水上，是既济之象也，故安五脏，益子精，明目，久服轻身延年。《别录》主下气，坚肌，续绝补中，疗五劳七伤，虚损少气，久服悦泽不老，耐寒暑，志高神仙，皆此意也。其曰止痢者，久痢则肠胃俱虚，甘温足以回其虚，下坠足以去其积，故亦主之也。\n\n【主治参与】\n云母得铅丹熬成膏，可贴一切痈疽疮毒。和以升丹细末，更著奇效。\n\n《经验方》云：青城山丈人观主康道丰治百病云母粉方：用云母一斤，析开，揉入大瓶内，筑实封固，以十斤顶火煅赤取出，却拌香葱、紫连翘草二件，合捣如泥，后以夹绢袋盛，于大水盆内摇取粉，余滓未尽，再添草药重捣取粉。于木盆一面贮灰，于灰上印一潜坑，铺纸倾粉在内，候干焙之，以面糊丸梧子大。遇有疾者，服之无不效。知成都府辛谏议，曾患大风，众医不愈，道丰进此，服之神验。\n\n《千金方》服食云母法：上白云母二十斤，薄劈，以露水八斗作汤，分半淘净二次。又作二斗汤，纳芒硝十斤，木器中浸二十日，取出绢袋盛，悬屋上，勿见风日，令燥。以鹿皮为囊揉之，从旦至午，筛滓复揉，得好粉二十斤，搅糊，入竹筒内，薄削封口漆固，北垣南下，入地六尺，覆土。春夏四十日，秋冬三十日出之，当成水。若洞洞不消，更埋三十日。此水能治万病，及劳气风疼。每以温水一合和服之，日三服。十日小便当变黄，二十日腹中寒澼消，三十日龋齿更生，四十日不畏风寒，五十日诸病皆愈，颜色日少，长生神仙。\n\n《深师方》：治痰饮头痛，往来寒热。云母粉二两，炼过，常山一两，为末。每服方寸匕，汤服取吐，忌生葱、生菜。\n\n仲景《金匮》方：治牝疟多寒。云母烧二日夜，龙骨、蜀漆烧去腥，等分为末。发前浆水服半钱。\n\n《千金方》治赤白久痢，积年不愈。饮调云母粉方寸匕服，神效。\n又方，治妇人带下，水和云母粉方寸匕，神效。\n\n《积德堂方》治妇人难产，经日不生，云母粉半两，温酒调服，入口即产，不顺者即顺，万不失一。陆氏云：此是何德扬方也。已救三五十人。\n《千金方》治风疹遍身，百计不愈。煅云母粉，清水调服二钱良。又方：治一切恶疮，用云母粉傅之。\n《圣惠方》治火疮败坏。云母粉和生羊髓傅之。\n《事林广记》治金疮出血，云母粉傅之。绝妙。\n《千金翼》治风热汗出，水和云母粉，服三钱，不过再服，立愈。\n\n【简误】\n云母性虽甘平，终属石种，与脏腑气血，实非同类，只宜用以治病取效。若夫益精明目，轻身延年，耐寒暑，志高神仙，皆必不然之论也。始俟世人试过，乃敢信耳。', NULL, NULL, NULL, '云母', NULL, '2、云母', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625785487585351, '555450876DAA1A2AA3D516D6496BDDF9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:07:42', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7114, 409, 400105314, '      味甘，微寒，无毒。主身体五藏百病，养精神，安魂魄，益气明目，通血脉，止烦满消渴，益精神，悦泽人面。杀精魅邪恶鬼，除中恶腹痛，毒气，疥瘘诸疮。久服通神明不老，轻身神仙。能化为汞。作末名真朱。光色如云母，可析者良。（恶磁石，畏碱水。）\n\n      疏：丹砂本禀地二之火气以生，而兼得乎天七之气以成。色赤法火，中含水液。为龙为汞，亦曰阴精。七为阳火之少，故味甘微寒而无毒，盖指生砂而言也。《药性论》云：丹砂为清镇少阴君火之上药，辟除鬼魅百邪之神物。安定神明则精气自固，火不妄炎则金木得平，而魂魄自定，气力自倍。五脏皆安则精华上发，故明目。心主血脉，心火宁谧，则阴分无热而血脉自通，烦满自止，消渴自除矣。杀精魅邪恶鬼，除中恶腹痛者，阳明神物，故能辟除不祥，消散阴恶杀厉之气也。久服通神明不老者，古之真人，飞丹炼石，引纳清和，配以金铅，按之法象，自能合丹道而成变化也。青霞子及太清服炼灵砂法云：能重能轻，能暗能明，能黑能白，能神能灵。一斛人擎，力难举升：万斤遇火，轻速上腾。鬼神寻求，莫知所在。先禀气于甲，受气于丙，出胎见壬，结魄成庚，增光归戊，阴阳升降，各本其原。非虚语矣！\n\n【主治参与】\n        丹砂研飞极细，令状如飞尘，以甘草、生地黄浓煎，调分许，与儿初生时服之，能止胎惊，解胎毒。\n\n同真珠、琥珀、金箔、牛黄、生犀角、天竺黄、滑石末，治小儿急惊，有神。\n\n入六一散，治暑气伏于心经，神昏口渴，及泄泻如火热。\n\n入补心丹，镇心神，定魂魄。\n\n入乳香托里散，散痈疽热毒，发热疼痛，及毒气攻心发谵语。\n\n【简误】\n        丹砂为八石之主，故列石部之首。体中含汞，汞味本辛，故能杀虫、杀精魅。宜乎《药性论》谓其有大毒。若经伏火，及一切烹炼，则毒等砒、硇，服之必毙。自唐以来，上而人主，下而缙绅，曾饵斯药，鲜克免者。戒之！戒之！', NULL, NULL, NULL, '铁锈', NULL, '14、铁锈', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922835525, 'E5224133685B9CD84AE6F01576B698EC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7115, 409, 400105313, '          凉，无毒。治喉痹，蚛牙，口疮，及恶疮疥癣。酿鲫鱼，烧灰和服，疗肠风泻血。（一名皂矾，煅赤醋淬为矾红，又名青矾。）\n\n疏：绿矾气味所禀与白矾同，其酸涌涩收，燥湿解毒，化涎之功，亦与白矾相似而力差缓。本经主喉痹者，酸涌化涎之功也。蚛牙口疮、恶疮疥癣者，燥湿除热解毒之功也。肠风泻血者，消散湿热之后复有收涩之功也。然而诸治之外，又善消积滞，凡腹中坚，肉积，诸药不能化者，以矾红同健脾消食药为丸，投之辄消。\n\n【主治参与】\n          得红曲、山查、肉豆蔻，消肉积。加麦芽、橘皮、草果、槟榔、三棱、蓬荗，消一切肉积，及米面食坚积。脾病黄肿，用绿矾四两，煅成赤珠子，当归四两，酒浸七日焙，百草霜三两，为末，以浸药酒，打糊丸梧子大。每服五丸至七丸，温水下。一月后黄去，立效。\n\n杨真人《济急方》酒黄水肿，黄肿积痛：青矾半斤，醋一大碗，和匀，瓦盆内煅干为度，平胃散、乌药顺气散各半两，为末，醋煮糊丸梧子大，姜汤下二三十丸。\n\n《救急方》食劳黄病，身目俱黄：青矾，锅内安炭煅赤，米醋拌为末，枣肉和丸梧子大。每服二三十丸，食后姜汤下。\n\n《圣惠方》腹中食积：绿矾二两研，米醋一大碗，瓷器煎之，柳条搅成膏，入赤脚乌一两研，丸绿豆大。每空心温酒下五丸。\n\n谈野翁《试验方》走马疳疮：绿矾煅红，以醋拌匀，如此三次，为末，入麝香少许，温浆水漱净，掺之。应加龙脑、雄黄、蓬砂、芒硝。\n\n【简误】\n绿矾、矾红，虽能消肉食坚积，然能令人作泻，胃弱人不能多用，服此者终身忌食荞麦，犯之立毙。', NULL, NULL, NULL, '绿矾', NULL, '13、绿矾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922835526, '8AB4C96ABC0C572B3A84090B3EF5FA10', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7116, 409, 400105312, '       味甘，平，无毒。主金疮折伤内损，止痛，生肌肉。\n\n         疏：无名异禀地中阴水之气以生，本经味甘、气平、无毒，苏颂咸寒。咸能入血，甘能补血，寒能除热，故主金疮折伤内损，及止痛生肌肉也。苏颂：醋摩傅肿毒痈疽者，亦取其活血凉血之功耳。\n\n【主治参与】\n《集验方》打伤肿痛：无名异为末，酒服，赶下四肢，瘀血皆散矣。\n\n《多能鄙事》损伤接骨：无名异、甜瓜子各一两，乳香、没药各一钱，为末。每服五钱，热酒调服，小儿三钱。服毕，以黄米粥涂纸上，掺左顾牡蛎末裹之，竹篦夹住。\n\n谈野翁《试验方》：临杖预服无名异末，临时温酒服三五钱，则杖不甚痛，亦不甚伤。\n\n除折伤肿毒外，无他用，故不著 “简误”。', NULL, NULL, NULL, '无名异', NULL, '12、无名异', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922835527, '45FB09D689207457DD89045F564B0FDC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7117, 409, 400105311, '           味甘、酸、辛，大温，无毒。主养心气，明目益精，疗腹痛泄澼，下痢赤白，小便利，及痈疽疮痔，女子崩中漏下，产难胞衣不出。久服补髓好颜色，益智不饥，轻身延年。（白石脂功用大略相同。石脂有五色，旧经同一条，今用唯赤、白二者，余皆不用。）\n\n          疏：赤石脂禀土金之气，而色赤则象火，故其味甘酸辛，气大温无毒。气薄味厚，降而能收，阳中阴也。入手阳明大肠，兼入手足少阴经。《经》曰：涩可去脱。大小肠下后虚脱，非涩剂无以固之，故主腹痛肠澼，及小便利，女子崩中漏下也。赤者南方之色，离火之象，而甘温则又有入血益血之功，故主养心气，及益精补髓，好颜色也。血足则目自明，心气收摄则得所养而下交于肾，故有如上功能也。痈疽因荣气不从所生，疮痔因肠胃湿热所致，甘温能通畅血脉，下降能涤除湿热，故主之也。其主难产胞衣不出者，以其体重下降，而酸辛能化恶血，恶血化则胞胎无阻滞之患矣。东垣所谓：胞衣不出，涩剂可以下之。此之谓也。不饥轻身延年，乃方士炼饵之法耳。凡泄利肠澼，久则下焦虚脱，无以闭藏。其他固涩之药，性多轻浮，不能达下，惟石脂体重而涩，直入下焦阴分，故为久利泄澼之要药。\n\n【主治参与】\n       《和剂局方》冷痢腹痛，下白冻如鱼脑者，桃花丸主之：赤石脂煅研，干姜炮，等分为末，蒸饼为丸。量大小服，日三服。\n\n仲景方：伤寒下利，便脓血不止，桃花汤主之。赤石脂一斤，一半全用，一半末用，干姜一两，粳米半斤，水七升，煮米熟，去滓。每服七合。纳末方寸匕，日三服，愈乃止。\n\n《千金翼方》：痰饮吐水无时节者，其原因冷饮过度，遂令脾胃气弱，不能消化饮食，饮食入胃，皆变成冷水，反吐不停，赤石脂散主之。赤石脂一斤，捣筛，服方寸匕，酒食自任，稍加至三匕。服尽一斤，则终身不吐痰水，又不下利，补五脏，令人肥健。有人患痰饮，服诸药不效，用此遂愈。病人虚者宜之。\n\n【简误】\n      火热暴注者，不宜用。滞下全是湿热，于法当忌。自非的受寒邪、下利白积者，不宜用。崩中，法当补阴清热，不可全仗收涩。滞下本属湿热积滞，法当祛暑除积，止涩之药定非所宜。慎之！慎之！', NULL, NULL, NULL, '赤石脂', NULL, '11、赤石脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922835528, 'E401D34592798204003FD4FA5A9FDD3D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7118, 409, 400105310, '      味甘、辛，温，无毒。主心腹咳逆邪气，补不足，女子风寒在子宫，绝孕十年无子，疗上气，心腹痛，寒热邪气结气，补心气不足，定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，令人悦泽。久服温中，轻身延年。\n\n      疏：紫石英禀土中之阳气以生，《本经》味甘，气温，无毒。《别录》加辛。雷公言大温。独李当之言大寒者，是昧其性矣。味厚于气，阳中之阴，降也。入手少阴、手厥阴、足厥阴经。少阴主心，属阳而本热，虚则阳气衰而寒邪得以乘之，或为上气咳逆，或为气结寒热心腹痛。此药温能除寒，甘能补中，中气足，心得补，诸证无不瘳矣。惊悸属心虚，魂魄不安亦由心君怯弱，无以镇压诸经。兹得镇坠之力，而心君有以镇摄，即重以去怯之义也。其主女子风寒在子宫，绝孕无子者，盖女子系胎于肾及心包络，皆阴脏也，虚则风寒乘之而不孕，非得温暖之气，则无以祛风寒而资化育之妙。此药填下焦，走肾及心包络，辛温能散风寒邪气，故为女子暖子宫之要药。补中气，益心肝，通血脉，镇坠，虚火使之归元，故又能止消渴，散痈肿，令人悦泽，及久服轻身延年也。凡入丸散，用火煅醋淬七次，研末水飞过，晒干入药。\n\n【主治参与】\n          同白薇、艾叶、白胶、当归、山茱萸、川芎、香附，治女人子宫虚寒，绝孕无子。\n\n张文仲《备急方》虚劳惊悸，补虚止惊，令人能食：紫石英五两，打如豆大，水淘一遍，以水一斗，煮取三升，细细服。\n\n仲景《金匮方》治风热瘈疭及惊痫，风引汤：紫石英、白石英、寒水石、石膏、干姜、大黄、龙齿、牡蛎、甘草、滑石等分，㕮咀，水一升，煎去三分，食后温呷，无不效者。\n\n【简误】\n         紫石英，其性镇而重，其气暖而补，故心神不定，肝血不足，及女子血海虚寒不孕者，诚为要药。然而止可暂用，不宜久服，凡系石类皆然，不独石英一物也。妇人绝孕由于阴虚火旺，不能摄受精气者忌用。', NULL, NULL, NULL, '紫石英', NULL, '10、紫石英', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922835529, 'E449C287EAF3CBDE8E5A09A081301DD2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7119, 409, 400105309, '       味甘、酸，寒、大寒，无毒。主青盲耳聋，明目，利九窍，通血脉，养精神，益肝气，疗目赤痛，去肤翳，止泪出，利水道，下乳汁，通关节，破坚积。久服轻身延年不老，令人不忘，志高神仙。能化铜铁铅锡作金。生益州山谷，及越巂山有铜处。铜精熏则生空青，其腹中空。三月中旬采，亦无时。\n\n       疏：空青感铜之精气而结，其味甘酸，其气大寒，无毒可知已。色青法木，故入肝而主目盲。目者肝之窍，瞳子神光属肾，肝肾虚则内热，怒则火起于肝，故生内外障翳，此目病所由成也。甘寒能除积热，兼之以酸，则火自敛而降矣。热退则障自消，目自明。耳者肾之窍，水涸火炎故耳聋，肾家热解则火息水生而听复聪矣。九窍不利，无非火壅。肝家有火则血热气逆，故血脉不通。凉肝除热则精气自益，阴足火清，则窍自利而血脉自通，精神自长矣。目赤痛，肤翳泪出，皆肝气不足之候，益肝气则诸证自除矣。其曰利水道，下乳汁，通关节，破坚积者，皆以热除则气血和平，阴气自复，五脏清宁则诸证自解。圣药神功，于斯显矣。\n\n【主治参与】\n空青得真珠、贝子、珊瑚、石决明，点目中内外障翳有神。\n\n《千金方》：眼目不明，空青少许，渍露一宿，点。\n\n《圣济总录》：肤翳昏暗，空青二钱，蕤仁去皮一两，片脑三钱，细研，日点。明目去翳障。\n\n上珍之药，一时难构。明目外，无别用，故不著 “简误”。', NULL, NULL, NULL, '空青', NULL, '9、空青', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922839621, 'EE63F93131EFFCFA0AC3C9EB8BC2DCAB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7120, 409, 400105308, '         味甘，寒、大寒，无毒。主身热泄澼，妇子乳难，癃闭，利小便，荡胃中积聚寒热，益精气，通九窍，六府津液，去留结，止渴，令人利中。久服轻身耐饥长年。（石韦为之使，恶曾青。）\n\n        疏：滑石，石中之得冲气者也。故味甘淡，气寒而无毒。入足太阳膀胱经，亦兼入足阳明、手少阴、太阳、阳明经。用质之药也。滑以利诸窍，通壅滞，下垢腻；甘以和胃气，寒以散积热。甘寒滑利以合其用，是为祛暑散热，利水除湿，消积滞，利下窍之要药。《本经》用以主身热泄澼，女子乳难，荡胃中积聚寒热者，解足阳明胃家之热也。利小便癃闭者，通膀胱，利阴窍也。其曰益精气、久服轻身、耐饥长年，此则必无是理矣。《别录》：通九窍津液，去留结，止渴，令人利中者，湿热解，则胃气和而津液自生；下窍通，则诸壅自泄也。丹溪用以燥湿，分水道，实大肠，化食毒，行积滞，逐瘀血，解燥渴，神脾胃，降心火，偏主石淋，皆此意耳。\n\n【主治参与】\n          和甘草为益元散，又名天水散、六一散、太白散：解中暑、伤寒、疫疬，并汗后遗热、劳复诸疾，兼解两感伤寒，百药、酒食、邪热毒，烦满短气，腹胀闷痛，淋閟涩痛，疗身热呕吐泄泻，肠澼下痢赤白，除烦热，胸中积聚寒热，止渴消蓄水。妇人催生下乳，治吹乳，乳痈，牙疮，齿疳。此药大养脾胃之气，通九窍六腑，去留结，通经脉，消水谷，安魂定魄，乃神验之仙药也。\n\n刘河间《伤寒直格》本方：白滑石水飞过六两，粉甘草一两，为末。每服三钱，蜜少许，温水调下。实热则用新汲水调下，解利则葱豉汤下，通乳用猪肉面汤调下，催生用香油浆水调下。凡难产或死胎不下，皆由风热燥涩，结滞紧敛，不能舒缓故也。此药力至，则结滞顿开而瘥矣。如用以治痢，照雷公炮制：用牡丹皮同煮过，加丹砂水飞细末，每两一钱，名辰砂六一散。治心经伏暑，下痢纯血，烦躁口渴，神昏不爽。\n\n《圣惠方》治膈上烦热多渴，利九窍，滑石二两，捣水三大盏，煎二盏，去滓，入粳米煮粥食。\n\n《千金方》治女劳黄疸，日晡发热恶寒，少腹急，大便溏黑，额黑。滑石、石膏等分，研末。大麦汁服方寸匕，日三，小便大利，愈。腹满者难治。\n\n《圣惠方》治乳石发动，烦热烦渴：滑石粉半两，水一盏，绞白汁，顿服。\n\n《广利方》：气壅关格不通，小便淋结，脐下妨闷兼痛：滑石粉水调服一两。\n\n杨氏《产乳》：小便不通。滑石末一升，车前汁和涂脐之四畔，方四寸，干即易之。冬月水和。\n\n《圣惠方》治妇人转脬，因过忍小便而致：滑石末，葱汤服二钱。\n\n《普济方》伏暑水泄，白龙丸：滑石火煅过一两，硫黄四钱，为末，面糊丸绿豆大。每用淡姜汤随大小服。又方：治伏暑或吐，或泻，或疟，小便赤，烦渴。玉液散：用桂府滑石烧四两，藿香一钱，丁香一钱，为末，米汤服二钱。亦治霍乱。\n\n王氏《痘疹方》治痘疮狂乱，循衣摸床，大渴引饮，用益元散一两，加朱砂飞过二钱，冰片三分，麝香一分，用灯心汤调二三钱服。\n\n《普济方》治风毒热疮，遍身出黄水。桂府滑石末傅之，次日愈。先以虎杖、豌豆、甘草等分，煎汤洗后乃搽。\n\n《集简方》治脚指缝烂：滑石一两，石膏煅半两，枯矾少许，研掺之。\n\n夏子益《奇疾方》，载白矾石条内。\n\n【简误】\n        滑石本利窍去湿，消暑除热，逐积下水之药。若病人因阴精不足内热，以致小水短少赤涩或不利；烦渴身热，由于阴虚火炽水涸者，皆禁用。脾肾俱虚者，虽作泄，勿服。', NULL, NULL, NULL, '滑石', NULL, '8、滑石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922839622, 'E62580627FB38DF4BC812C258E8E1ACA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7121, 409, 400105307, '        味辛、甘，性冷，无毒。治心热烦躁，并五藏宿滞癥结，明目，退膈上虚热，消肿毒。此即朴硝炼成者。\n\n        疏：玄明粉，即芒硝投滚汤沸化，夜置冰霜之下，结起在水面上者。用白莱菔切片，煮汁投硝，以结起多次者为上。其色莹白，其味辛咸，沉而降，阴也。入手少阴、足厥阴、阳明经。其治邪热在心烦躁者，《经》曰：热淫于内，治以咸寒，佐之以苦。并主五藏宿滞癥结者，即燥粪、结痰、瘀血、宿食之谓。辛能散结，咸能软坚，兼能润下，苦能下泄，故主之也。目为血热所侵，必赤肿作痛异常，硝物峻利，加以苦辛咸寒之极，故能散热结，逐热血。目病既去，必自明矣。退膈上虚热者，当作实热。邪解心凉，故热退也。消肿毒者，即软坚散结之功也。\n\n【主治参与】\n《集简方》热厥气痛：玄明粉三钱，热童便调下。\n\n《伤寒蕴要》伤寒发狂，玄明粉二钱，朱砂一钱，末之，冷水服。\n\n《圣济总录》鼻血不止：玄明粉二钱，冷水服。\n\n【简误】\n硝者，消也。五金八石，其坚莫比，惟硝能销之。苟非大辛、至咸、极苦、最烈之味，其能消化之乎？消石、朴硝，一经澄炼，便名芒硝、马牙硝、风化硝、甜硝。若经煅过，即名玄明粉。究其功用，无坚不磨，无结不散，无热不荡，无积不推，可谓直往无前，物无留碍之性也。《别录》谓炼饵服之，轻身神仙，失其本矣。故仲景于诸承气汤用之，非邪结下焦、坚实不可按者不用。恐其误伐下焦真阴故也。病不由于邪热深固，闭结难通，断不可轻投。至于血涸津枯，以致大肠燥结，阴虚精乏，以致大热骨蒸；火炎于上，以致头痛目昏，口渴耳聋咽痛，吐血衄血，咳嗽痰壅，虚极类实等证，切戒勿施！庶免虚虚之咎，而无悔不可追之大错也。至如唐玄宗所召道士刘玄真，谓服玄明粉，遂无病长生中所载有益精壮气，助阳补阴，不拘丈夫妇人，幼稚襁褓，不问四时冷热俱治之说，乃是荒唐不经之语。不识本章，何缘载人？岂历代董修儒臣，本不知医，但广异闻，未暇核实而误收之耶？正所谓尽信书，则不如无书也。', NULL, NULL, NULL, '玄明粉', NULL, '7、玄明粉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922839623, 'B95863CD119BE8DE765A64E34E629DC2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7122, 409, 400105306, '        味苦、辛，寒，大寒，无毒。主百病，除寒热邪气，逐六府积聚，结固留癖，胃中食饮热结，破留血闭绝，停痰痞满，推陈致新。能化七十二种石。炼饵服之，轻身神仙。炼之白如银，能寒能热，能滑能涩，能辛能苦，能咸能酸。入地千岁不变。色青白者佳，黄者伤人，赤者杀人。\n\n        疏：朴硝乃初次煎成者，其气味烈于芒硝，主治皆同。总为除邪热，逐六腑积聚，结固留癖，胃中食饮停滞因邪热结，停痰痞满，破留血闭绝之要药。与芒硝功用曾无少别，文具芒硝条下，兹不复疏。\n【主治参与】\n《圣惠方》治时气头痛不止，用朴硝二两，捣罗为散，用生油调涂于顶上。又方：治乳石发动烦闷，及诸风热，用朴硝炼成者半两，细研如粉，每服以蜜水调下一钱匕，日三四服。\n\n《简要济众》治小便不通膀胱热。白花散：朴硝不以多少，研为末，每服二钱匕，温茴香酒调下，无时服。\n\n入紫雪：疗伤寒，温疫，温疟，一切积热烦热，狂呼叫走，瘴疫毒疠，卒死脚气，五尸五注，心腹诸疾，㽲刺切痛，解诸热毒，邪热发黄，蛊毒鬼魅，野道热毒，小儿惊痫百病：黄金一百两，石膏、寒水石、磁石、滑石各三斤，捣碎，水一斛，煮四斗，去滓。入犀角屑、羚羊角屑、青木香、沉香各五两，玄参洗焙、升麻各一斤，炙甘草八两，丁香一两，入前汁中，煮取一斗五升，去滓。入炼朴硝十斤，硝石三十二两，于药汁中微火煎之，用柳木不住搅，至水气欲尽，倾水盆中。待欲凝，入麝香一两二钱半，朱砂末三两，搅匀收之。每服一二钱，凉水服。临时加减，甚者一两。\n\n碧雪：治一切积热，天行时疾，发狂昏愦，或咽喉肿塞，口舌生疮，心中烦躁，或大小便不通，胃火诸病。朴硝、芒硝、马牙硝、石膏水飞、寒水石水飞各一斤，以甘草一斤，煎水五升，入诸药同煎，不住手搅，令消熔得所，入青黛一斤，和匀，倾盆内，经宿结成雪。为末，每含咽，或吹之，或水调服二三钱。欲通利，则热水服一两。\n\n刘禹锡《传信方》治热壅，甘露饮：凉胸膈，驱积滞。芒硝末一大斤，用蜜十二两，和匀，入新竹筒内，半筒已上即止，不得令满。却入炊甑中，令有药处在饭内，其虚处出在上，蒸之。候饭熟，取出，绵滤入磁缽内，竹篦搅匀勿停手，待凝，取入磁盒。每卧时含半匙，渐渐咽之。如要通利，即多服之。\n\n《简便方》治赤眼肿痛：朴硝置豆腐上蒸化，取汁收点。\n\n《外台秘要》治喉痹肿痛：用朴硝一两，细细含咽，立效。或加丹砂一钱。气塞不通，加生甘草二钱半，吹之。\n\n孙真人方：治口舌生疮，用朴硝含之良。\n\n夏之益《奇疾方》：灸疮飞蝶，因艾灸火疮痂退落，疮内鲜肉片子飞如蝶状，腾空飞去，痛不可言，是血肉俱热怪病也。用朴硝、大黄各半两，为末，水调下，微利即愈。\n\n《史记・仓公传》云：菑川王美人，怀子不乳，来召淳于意。意往，饮以莨菪药一撮，以酒饮之，旋乳。意复诊其脉躁，躁者，有余病，即饮以消石一剂，出血豆比五六枚而安。此去蓄血之验也。\n\n《炮炙论》治头痛欲死，用消石末吹鼻中即愈。\n\n《圣惠方》治赤眼肿痛。用消石末，临卧时，以铜箸点黍米大，入目眦，至旦，以盐水洗去之。', NULL, NULL, NULL, '朴硝', NULL, '6、朴硝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922839624, 'D21E649F7395F94EAABA823069C52502', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7123, 409, 400105305, '         味辛、苦，大寒。主五藏积聚，久热胃闭，除邪气，破留血，腹中痰实结搏，通经脉，利大小便及月水，破五淋，推陈致新。生于朴硝。\n\n          疏：芒硝禀天地至阴极寒之气所生，故味苦辛，性大寒。乃太阴之精，以消物为性，故能消五金八石，况乎五脏之积聚，其能比之金石之坚哉？久热即是邪热，伤寒热邪结中焦，或停饮食则胃胀闭，少少投之，可立荡除。除邪气者，寒能除热故也。破留血者，咸能软坚，辛能散结也。邪热盛则经脉闭，热淫于内，治以咸寒，结散热除则经脉自通，二便自利，月水复。此五淋中，惟石淋、膏淋为胶结难解。病由于积热，非得辛苦大寒之药，以推荡消散之，不能除也。推陈致新，总述其体用之功耳。由朴硝再煎而成，故曰生于朴硝。\n\n【主治参与】\n入仲景大承气汤，治伤寒七八日后，邪结下焦，少腹按之坚痛，下之愈。\n\n又治伤寒邪热失汗，蓄血少腹，或先因内伤留血下焦，入桃仁承气汤，下之愈。\n\n《千金方》疗漆疮，用汤渍芒硝令浓，涂之。如干即易之。\n\n《子母秘录》治小儿赤游，行于体上下，至心即死：以芒硝纳汤中，取浓汁以拭丹上。\n\n《百一选方》治疗关格，大小便不通，胀满欲死，两三日则杀人：以芒硝三两，纸裹三四重，炭火烧之，令内一升汤中尽服，当先饮汤一升已，吐出乃服之。\n\n《孙真人食忌》：主眼有翳：取芒硝一大两，置铜器中，急火上炼之，放冷后，以生绢细罗，点眼角中。每夜欲卧时一度点，妙。\n\n姚和众方：治小儿重舌：马牙硝涂于舌上下，三日效。《简要济众方》治小儿鹅口。用马牙硝擦舌上，日五度，效。《梅师方》治火焰丹毒，水调芒硝末涂之。\n\n《信效方》治死胎不下。用芒硝末二钱，童便温服。\n\n《三因方》：治风热喉痹及缠喉风。玉钥匙：用焰硝一两半，白僵蚕一钱，白硼砂半两，脑子一字，研匀，取少许，数数吹之。\n\n《普济方》治重舌、鹅口，用竹沥同焰硝点之。', NULL, NULL, NULL, '芒硝', NULL, '5、芒硝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 625791922839625, '3CAAEDB691FFC13F932E8262BDFF86A6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-23 17:33:53', 1, 'admin', '2024-12-24 08:09:43');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7124, 410, 400105418, '        无毒。主风瘙瘾疹，及恶刺疮、浸淫疮遍身至心者死，并水和傅之。\n\n          疏：胡燕，即玄鸟，春分后至。窠取四方湿土为之，其气味必甘寒，故藏器以之疗诸疮疡。盖诸痛痒疮疡，皆属心火，而甘寒最能解火毒，土性能化一切毒故也。\n\n【主治参与】\n        入回燕膏，贴瘰疬有效。回燕者，朝北燕窠土也。', NULL, NULL, NULL, '胡燕巢内土', NULL, '18、胡燕巢内土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971654, '805296929B6765037535E07FEEDE0B67', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7125, 410, 400105417, '          本经无气味，云主肿毒，醋和为泥傅之。亦主蜘蛛咬，必是甘平无毒之物。甘为土化，故能解诸毒也。', NULL, NULL, NULL, '土蜂巢内土', NULL, '17、土蜂巢内土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971655, 'B9ACF7FCBA3072E0EFC2439BB41E9C12', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7126, 410, 400105416, '        味咸，温，无毒。主除风冷邪气湿痹，益精气，妇人痼冷漏下，心腹积聚冷气，止头疼，解肌。其色青白，龟背者良。\n\n       疏：太阴玄精出于盐卤之地，及至阴之精凝结而成。故其形皆六出，象老阴之数也。本经味咸气温无毒，然详其所主，味应带辛，气应作寒。非辛寒则不能除风冷邪气湿痹，及止头疼、解肌等证。咸能软坚，故主心腹积聚。咸能润下，入肾滋水，故主益精气。本经误认为温，故有妇人痼冷漏下冷气之治，皆非所宜也。\n\n【主治参与】\n《图经本草》正阳丹：治伤寒三日，头疼壮热，四肢不利。太阴玄精石、硝石、硫黄各二两，蓬砂一两，细研，入瓶固济，以火半斤，于瓶子周一寸（火办）之，约近半日，候药青紫色，住火，待冷取出，用腊月雪水拌匀，入罐子中，屋后北阴下阴干。又入地埋二七日，取出研细，面糊丸鸡头实大。先用热水浴后，以艾汤研下一丸。以衣盖，汗出为瘥。\n入来复丹，治缓急诸病，但有胃气，无不获安。\n【简误】\n伤寒阴证不宜服。咸能走血，用以引经入肾则可，多则反泻肾伤血矣。血病无多食咸，戒之。', NULL, NULL, NULL, '太阴玄精', NULL, '16、太阴玄精', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971656, '6C8AC49C8BF45F59834A2C74DBBEBD75', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7127, 410, 400105415, '    味辛，寒，无毒。主辟恶，熨目赤烂。\n\n   疏：玛瑙，玉之属也。观陈藏器云 “砑木不热”，其性寒可知矣。寒而带辛，故能辟恶，及熨目赤烂也。同珊瑚辈为末点目，去障翳尤妙。', NULL, NULL, NULL, '玛瑙', NULL, '15、玛瑙', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971657, 'F9FAAC1D44ED5D90673BF54E9EA3D996', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7128, 410, 400105414, '       味甘，平，无毒。主宿血，去目中翳。鼻衄，末吹鼻中。\n\n        疏：珊瑚得水中阴气以生，味甘气平，性主消散，故能去目中翳，及消宿血、止鼻衄也。\n\n【主治参与】\n      同贝子、真珠、玛瑙、琥珀、石蟹，为极细末，点入目中，去浮翳。', NULL, NULL, NULL, '珊瑚', NULL, '14、珊瑚', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971658, '1BB0D14351033EF4DABCB83A06C47FB5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7129, 410, 400105413, '       味辛、甘，平，无毒。主风热恶疮，疡疽疮痂疥，气在皮肤中，除胸膈中热气，食不下，止烦，去黑子。可以染皂。\n\n        疏：铁落是煅家烧铁赤沸，砧上煅之，如皮甲落下者。本出于铁，不离金象，体重而降。故《素问》有生铁落饮，以疗病狂怒者，云生铁落，下气疾也。又狂怒属肝气暴升，故取金气以制之也。其主气在皮肤中，及除胸膈中热气，食不下，止烦者，皆制木散热之功也。《本经》又主风热恶疮，疡疽疮痂疥者，皆肝心火热所致，辛平能除二经之火热，故主之也。苏恭以之炒热投酒中饮，疗贼风痉。大明治惊邪癫痫，小儿客忤，并煎服之，悉此意耳。\n\n【主治参与】\n         铁秤锤烧红，淬入米泔中百次，乘热熏洗阴癣顽疮，皆有效。别敷杀虫凉血药弥佳。', NULL, NULL, NULL, '铁落', NULL, '13、铁落', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971659, '55CE757FA40A91232A5AEC8E8C2791E8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7130, 410, 400105412, '       味咸、辛，平，有小毒。主久痢，五痔，金疮。面上瘢䵟，面膏药用之。（旧出南闽中银铜冶处，今甚难得，但取煎销银铺炉底用之。）\n\n         疏：蜜陀僧感银铜之气而结，故其味咸辛，气平有小毒。久痢，五痔，大肠湿热积滞也。辛主散结滞，咸主润下除热。大肠清宁，则久痢、五痔自瘳矣。体重，能消磨坚积；味咸，能入血凉血，故又主金疮，及灭面上瘢䵟也。\n\n【主治参与】\n        《圣惠方》鼻皶赤皰：蜜陀僧二两，细研，人乳调，夜涂旦洗。\n\n《活人心鉴》夏月汗癍如疹：用蜜陀僧八钱，雄黄四钱，先以姜片擦热，仍以姜片蘸末擦之，次日即焦。\n\n《寿域方》：骨疽出骨，一名多骨疮，不时出细骨。乃母受胎未及一月，与六亲骨肉交合，感其精气，故有多骨之名。以蜜陀僧末，桐油调匀，摊贴之，即愈。\n\n【简误】\n        蜜陀僧惟治䵟，傅面外，今人无复用以服食者。大都可外傅，不可内服。此药难得真者，销银炉底，乃销铜之气所结，能烂一切物，故益不宜轻用。', NULL, NULL, NULL, '蜜陀僧', NULL, '12、蜜陀僧', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971660, 'C262C9C12E15D15C9C1EEBC9B41ACA65', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7131, 410, 400105411, '           味咸，微温，无毒。主崩中漏下，破子藏中血，癥瘕结气，寒热腹痛，无子，阴痿不起，补不足，疗男子茎头寒，阴下湿痒，去臭汗，消水肿。久服不饥，令人有子。（白色莹明若狼牙者为上，凡用，火煅酒淬七次，研细水飞，日干。）\n\n        疏：阳起石禀纯阳之气以生。《本经》味咸，气微温，无毒。观《图经》所载：齐州阳起山，其山常有暖气，虽盛冬大雪遍境，独此山无少积，盖石气熏蒸也。其为气之温暖，当不甚微矣。味咸而气温，入右肾命门，补助阳气，并除积寒宿血留滞下焦之圣药，故能主崩中漏下，及破子脏中血，癥瘕结气，寒热腹痛，及男子茎头寒，阴痿不起，阴下湿痒，令人有子也。真阳足则五脏之气充溢，邪湿之气外散，故久服不饥，并去臭汗也。《别录》又主消水肿者，盖指真火归元，则能暖下焦，熏蒸糟粕，化精微，助脾土以制水也。\n\n【主治参与】\n          同破故纸、鹿茸、腽肭脐、菟丝子、狗阴茎、肉苁蓉、巴戟天，治命门虚寒，阴痿不起，精寒无嗣。服之能令阳道丰隆，使人有子。总治男子九丑之疾。\n\n【简误】\n       阴虚火旺者，忌之。阳痿属于失志，以致火气闭密，不能发越而然，及崩中漏下由于火盛，而非虚寒者，并不得服。', NULL, NULL, NULL, '阳起石', NULL, '11、阳起石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971661, '33BB26A474C1B52508C066F650B5B382', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7132, 410, 400105410, '        味辛、甘，寒、大寒，无毒。主身热，腹中积聚邪气，皮中如火烧，烦满，水饮之。除时气热盛，五脏伏热，胃中热，烦满，止渴，水肿，小腹痹。久服不饥。一名寒水石，一名白水石。色如云母，可析者良。盐之精也。（石膏亦名寒水石，与此不同。）\n\n       疏：凝水石生于卤地，禀积阴之气而成。《本经》味辛气寒。\n\n      《别录》加甘、大寒无毒。《经》曰：小热之气，凉以和之；大热之气，寒以取之。又曰：热淫于内，治以咸寒。大寒微咸之性，故主身热邪气，皮中如火烧，烦满，及时气热盛，五脏伏热，胃中热也。易饥作渴，亦胃中伏火也。甘寒除阳明之邪热，故能止渴不饥。水肿者，湿热也。小便多不利，以致水气上溢于腹，而成腹痹。辛咸走散之性，故能除热利窍消肿也。疗腹中积聚者，亦取其辛散咸软之功耳。\n\n【主治参与】\n《永类方》男女转脬，不得小便：寒水石二两，滑石一两，葵子一合，为末，水一斗，煮五升，时服一升，即利。\n\n《经验方》：小儿丹毒，皮肤热赤：寒水石半两，白土一分，为末，米醋调涂之。\n\n【简误】\n       凝水石，按本文云 “盐之精”，则与石膏、方解石大相悬绝矣。因石膏有寒水石之名，而王隐君复云寒水石又名方解石，以致混淆难辨。其功能各不相同，用者自宜分别。生卤地，味辛咸，碎之如朴硝者，是凝水石。其气大寒，能除有余邪热。凡阴虚火旺，咳嗽吐血多痰，潮热骨蒸，并脾胃作泄者，不宜服。《经》曰 “诸腹胀大，皆属于热” 者，宜之；“诸湿肿满，属脾土” 者，忌之。大宜详审，慎勿有误。', NULL, NULL, NULL, '凝水石', NULL, '10、凝水石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971662, '9B54BCB3F838A7668F6BC21358F594CE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7133, 410, 400105409, '        味辛、咸，寒，无毒。主周痹，风湿肢节中痛，不可持物，洗洗酸痟。除大热烦满，及耳聋。养肾脏，坚骨气，益精除烦，通关节，消痈肿鼠瘘，颈核喉痛，小儿惊痫。炼水饮之，亦令人有子。一名玄石。（即吸铁石。入药须火烧醋淬，研末水飞，或醋煮三日夜。）\n\n         疏：磁石生于有铁处，得金水之气以生。《本经》：味辛，气寒，无毒。\n\n     《别录》、甄权：咸，有小毒。大明：甘、涩，平。藏器：咸，温。今详其用，应是辛咸微温之药，而甘寒非也。气味俱厚，沉而降，阳中阴也。入足少阴，兼入足厥阴经。其主周痹风湿，肢节中痛，不可持物，洗洗酸者，皆风寒湿三气所致，而风气尤胜也。风淫末疾，发于四肢，故肢节痛不能持物。风湿相搏，久则从火化，而骨节皮肤中洗洗酸也。辛能散风寒，温能通关节，故主之也。咸为水化，能润下软坚。辛能散毒，微温能通行除热，故主大热烦满，及消痈肿鼠瘘。颈核喉痛者，足少阳、少阴虚火上攻所致，咸以入肾，其性镇坠而下吸，则火归元而痛自止也。夫肾为水脏，磁石色黑而法水，故能入肾养肾脏。肾主骨，故能强骨。肾藏精，故能益精。肾开窍于耳，故能疗耳聋。肾主施泄，久秘固而精气盈溢，故能令人有子。小儿惊痫，心气怯，痰热盛也，咸能润下，重可去怯，是以主之。甄权云：补男子肾虚，风虚身强，腰中不利，加而用之。宗奭云：养肾气，填精髓，肾虚耳聋目昏者，皆用之。\n\n【主治参与】\n《直指方》耳卒聋闭：吸铁石半钱，入病耳内，铁砂末入不病耳内，自然通透。\n\n《千金方》阳事不起：磁石五斤，研，清酒渍二七日。每服三合，日三夜一。\n\n倪维德《原机启微集》：眼昏内障，神光宽大渐散，昏如雾露中行，渐睹空花，物成二体，久则光不收及内障。磁朱丸：真磁石火煅醋淬七次二两，朱砂一两，神曲生用三两，为末。更以神曲末一两煮糊，加蜜丸梧子大。每服二十丸，空心饭汤下。\n\n《千金方》金疮血出：磁石末傅之，止痛断血。\n\n诸药石皆有毒，且不宜久服，独磁石性禀冲和，无猛悍之气，更有补肾益精之功，故不著 “简误”。大都渍酒优于丸散，石性体重故尔。', NULL, NULL, NULL, '磁石', NULL, '9、磁石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971663, 'F7EA6E1D8C437A4B3A977EE2F1EDA193', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7134, 410, 400105408, '       味辛，冷，无毒。主通大肠，傅小儿疳并瘰疬，杀疮疥癣虫，及鼻上酒皶，风疮瘙痒。又名汞粉，轻粉，腻粉。（畏磁石、石黄，忌一切血。本出与丹砂故也。土茯苓、黑铅、铁浆，可制其毒。）\n\n      疏：水银粉，升炼水银而成。其味本辛，气冷，无毒。疗体与水银相似，第其性稍轻浮尔。大肠热燥则不通。小儿疳痹因多食甘肥，肠胃结滞所致，辛凉总除肠胃积滞热结，故主之也。其主瘰疬疮疥癣虫，及鼻上酒皶，风疮瘙痒者，皆从外治，无非取其除热杀虫之功耳。\n\n升炼轻粉法：用水银一两，白矾二两，食盐一两，同研不见星，铺于铁器内，以小乌盆覆之，盐泥封固盆口，以炭火打三炷香，取开，则粉升于盆上矣。\n\n【主治参与】\n《活幼口议》：小儿哯乳不止，服此立效。腻粉一钱，盐豉七粒去皮，研匀，丸麻子大。每服三丸，藿香汤下。\n\n《经验方》小儿吃泥，䑋肚：用腻粉一分，砂糖和丸，麻子大。空心米饮下一丸，良久，泄出泥土瘥。\n\n《圣惠方》大小便闭，胀闷欲死，二三日则杀人：腻粉一钱，生麻油一合，相和空心服。\n\n万表《积善堂方》下疳阴蚀疮：轻粉末干掺之，即结靥而愈。\n\n《永类钤方》臁疮不合：葱汁调轻粉傅之。\n\n又秘法升丹灵药方：治痈疽恶疮，杨梅诸疮，拔毒长肉，神验。水银一两，黑铅七钱，朱砂、雄黄各三钱，白矾、火硝各二两半，其法先用铅化开，投水银，凝成饼，入朱砂、雄黄研匀，然后将硝、矾熔化，投前四味末入内，离火急搅令匀，用阳城罐盛之，铁盏盖口上，架铁梁，铁线扎紧，盐泥固济，神仙炉内文武火升炼，盏中时时以水擦之，火渐加，以三分为率。每焚官香一炷，则加一分。如是炼三炷官香为度，候冷，取开，于盏底刮取，研如飞面，甘草汤飞过三次，入龙脑香少许，点广疮上。数数以指蘸药按之。三日自脱，神方也。\n\n【简误】\n         水银粉下膈涎，消积滞，并小儿涎潮瘈疭药多用。然而其性有毒，走而不守，若服之过剂，或不得当，则毒气熏蒸，窜入经络筋骨，莫之能出。痰涎既去，血液随亡，筋失所养，营卫不从，变为筋挛骨痛，或结肿块漏疮，或手足皲裂顽痹等证，遂成痼疾，贻害无穷。盖此物本成于汞，则汞之毒尚存。又得火煅，则火之毒气未出。《本经》言其无毒，误也。凡闭结由于虚，血不能润泽；小儿疳病，脾胃两虚；小儿慢惊，痰涎壅上；杨梅结毒，发于气虚；久病之人，咸不宜服。宗奭有云：病属于惊，尤须审谨。盖惊为心气不足，不可下，下之里虚。惊气入心不可治，其人本虚，便须禁此。慎之至也。', NULL, NULL, NULL, '水银粉', NULL, '8、水银粉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971664, '26E1F702BCD94A50AB120E206D0EDAF6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7135, 410, 400105407, '        味甘，温，无毒。主五藏百病，养神，安魂魄，益气明目，通血脉，止烦满，益精神，杀精魅恶鬼气。久服通神明，不老轻身神仙，令人心灵。一名二气砂。\n\n        疏：灵砂，硫、汞制而成。及水火既济，二气交合，夺造化之功，窃阴阳之妙，可以变化五行，升降气血，为除邪养正，扶危救急之灵丹也。故能主五脏百病，益精神，安魂魄，及益气养神也。其主明目，通血脉，止烦满，杀精魅恶鬼气者，特其余事耳。得阴阳之妙，故能令人心灵。心灵则神明自通，不老轻身神仙所自来矣。又能主上盛下虚，痰涎壅盛，头旋吐逆，霍乱反胃，心腹冷痛诸证，更为镇坠之神丹也。\n\n修治：用水银一两，硫黄六铢，细研，炒作青砂头，后入水火既济炉，抽之如束针纹者，成就也。又按，胡演《丹药秘诀》云：升灵砂法：用新锅安逍遥炉上，蜜揩锅底，文火下烧，入硫黄二两熔化，投水银半斤，以铁匙急搅作青砂头。如有焰起，喷醋解之。待汞不见星，取出细研，盛入水火鼎内，盐泥固济，下以自然火升之。干水十二盏为度。取出束针纹者，成矣。\n\n【主治参与】\n钱氏《小儿方》：霍乱吐逆，不问虚实冷热。二气散，一名青金丹：用水银、硫黄等分，研不见星。每服一字，生姜汤调下。\n\n《直指方》冷气心痛。灵砂三分，五灵脂一分，为末，稀糊丸麻子大。每服二十丸，食前石菖蒲、生姜汤下。\n\n又方，九窍出血，因暴惊而得，其脉虚者，灵砂丹三十粒，人参汤下，三服愈。此证不可认作血得热则妄行而用凉药，误矣！何者？惊则气浮，神魂发越，阳气暴壅故也。得镇坠则神魂复安，而血自循经矣。\n\n《和剂局方》有养正丹，又名交泰丹，用黑铅、朱砂、水银、硫黄炒成，即灵砂意也。其用亦与灵砂略同。\n\n【简误】\n        灵砂虽称水火既济，阴阳配合，然而硫、汞有毒，性亦下坠，止可藉其坠阳交阴，却病于一时，安能资其养神益气，通灵于平日哉？凡胃虚呕吐，伤暑霍乱，肺热生痰，病属于虚，非关骤发者，咸在所忌。', NULL, NULL, NULL, '灵砂', NULL, '7、灵砂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971665, 'C9A250B705A4AE6B6C4F3FFC9E2F55AB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7136, 410, 400105406, '     味辛，平，有毒。主镇精神，坚骨髓，通利五脏，除邪毒气。服之神仙。（寇宗奭曰：不曰金而更屑字者，是已经磨屑可用之义。必须烹炼煅屑为箔，方可入药。苏颂曰：金屑古方不见用，惟作金箔入药甚便，又古方有金石凌、红雪、紫雪辈，皆取金银煮汁。此通用经炼者，假其气尔。生金有毒，能杀人，且难解。有中其毒者，惟鹧鸪肉可解之，性恶锡，畏水银。）\n\n      疏：金屑禀西方刚利之性，善能制木。体重而降，亦能镇心。心气怯则惊邪易入，精神不安，五脏皆为之病。肝经风热则为惊痫失志，魂魄飞扬。肝属木而畏金，与心为子母之脏，故其病同一源，治亦同法。本经主镇惊，通利五脏邪气，及甄权疗小儿惊伤五脏，风痫失志，镇心安魂魄者，亦兼实则泻其子之义也。本经又主坚骨髓者，以肝心平、风热退，则精生血，骨髓自坚矣。服之神仙，乃出之仙经，非医方所述也。\n\n【主治参与】\n       入至宝丹，治中风不语气绝，中恶蛊毒尸疰，难产血晕等证。\n\n入牛黄清心丸，治诸风缓纵不随，语言蹇涩，恍惚怔忡，痰涎壅塞，惊恐怕怖，或喜怒无时，癫狂昏乱。\n\n入紫雪，治内外烦热，口舌生疮，狂呼叫走，瘴疫毒疠卒死，温疟，五尸，五疰，蛊毒，卒黄，小儿惊痫百病。红雪治疗略同。\n\n金箔镇心丸：治小儿风壅痰热，惊悸谵妄，心神不宁。\n\n磨细屑，挑开疔疮头上，没入，能拔疔根。作针，针疔疮，纳药拔疔。\n\n【简误】\n        《太清法》云：金禀中宫阴己之气，性本刚，服之伤肌损骨。予见今之以难求死者，服金一二分，则心腹剜痛，肠胃如裂而毙。其为损伤肌骨，概可见矣。惟作箔入药，可为镇心安神之用。如或止因心气虚，以致神魂不安，并无惊邪外入者，当以补心安神为急，而非金箔所能定矣。', NULL, NULL, NULL, '金屑', NULL, '6、金屑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971666, 'CDE1CD418AB7D9A16768C6564D864A7B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7137, 410, 400105405, '       味辛、甘，微寒、大寒，无毒。主中风寒热，心下逆气，惊喘，口干舌焦不能息，腹中坚痛，除邪鬼，产乳金疮。除时气头痛身热，三焦大热，皮肤热，肠胃中膈气，解肌发汗，止消渴烦逆，腹胀暴气，喘息咽热，亦可作汤浴。（坚白明莹者良。浙人呼为寒水石者真。）\n\n        疏：石膏禀金水之正，得天地至清至寒之气，故其味辛甘，其气大寒而无毒。阴中之阳，可升可降。入足阳明、手太阴、少阳经气分。辛能解肌，甘能缓热，大寒而兼辛甘、则能除大热。故《本经》主中风寒热，热则生风故也。邪火上冲，则心下有逆气及惊喘。阳明之邪热甚，则口干舌焦不能息。邪热结于腹中，则腹中坚痛。邪热不散，则神昏谵语，同乎邪鬼。肌解热散汗出，则诸证自退矣。惟产乳金疮，非其用也。《别录》除时气头痛身热，三焦大热，皮肤热，肠胃中膈气，解肌发汗，止消渴烦逆，腹胀暴气，喘息咽热者，以诸病皆由足阳明胃经邪热炽盛所致，惟喘息咽热，略兼手太阴病。此药能散阳明之邪热，降手太阴之痰热，故悉主之也。甄权亦用以治伤寒头痛如裂，壮热如火。日华子用以治天行热狂，头风旋，揩齿。东垣用以除胃热、肺热，散阳邪，缓脾益气者，邪热去则脾得缓，而元气回也。洁古又谓止阳明经头痛，发热恶寒，日晡潮热，大渴引饮，中暑暍，及牙痛者，无非邪在阳明经所生病也。理阳明则蔑不济矣。足阳明主肌肉，手太阴主皮毛，故又为发斑、发疹之要品。起死回生，功同金液。若用鲜少，则难责其功。世医罔解，兹特表而著之。\n\n【主治参与】\n         仲景白虎汤，专解阳明邪热，其证头疼壮热，口渴烦躁，鼻干，目眴眴不得眠，畏人声、木声，畏火。若劳役人病此，元气先虚者，可加人参，名人参白虎汤。发斑阳毒盛者，白虎汤加竹叶、麦门冬、知母，以石膏为君，自一两至四两，麦门冬亦如之。知母自七钱至二两，竹叶自百片至四百片，粳米自一大撮至四大撮。甚则更加黄连、黄檗、黄芩，名三黄石膏汤，自一剂至四剂。妇人妊娠病此者，亦同。\n\n伤寒汗后烦热不解，竹叶石膏汤主之。\n\n小儿痧疹发热，口渴唇焦，咳嗽多嚏，或多痰，或作泄，竹叶石膏汤加赤柽木枝两许，贝母、栝楼根各二三钱主之。发斑亦同。甚者加三黄。\n\n疟疾头痛，壮热多汗，发渴，亦用竹叶石膏汤二三剂主之。虚者加人参，后随证施治。\n\n中暑用白虎汤，虚者加人参。太阳中蜴，亦用竹叶石膏汤。\n\n胃家实热，或嘈杂，消渴善饥，齿痛，皆须竹叶石膏汤主之。\n\n【简误】\n         石膏本解实热，祛暑气，散邪热，止渴、除烦之要药。温热二病多兼阳明，若头痛，遍身骨痛而不渴、不引饮者，邪在太阳也，未传阳明不当用。七八日来邪已结，里有燥粪，往来寒热，宜下者勿用。暑气兼湿作泄，脾胃弱甚者，勿用。疟邪不在阳明则不渴，亦不宜用。产后寒热由于血虚，或恶露未尽；骨蒸劳热由于阴精不足，而不由于外感。金疮下乳，更非其职。宜详察之，并勿误用。', NULL, NULL, NULL, '石膏', NULL, '5、石膏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971667, '09AE9A39032E499F4CBD2AD02553812F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7138, 410, 400105404, '       味辛，寒，有毒。主疥瘘痂疡，白秃，杀皮肤中虱，堕胎除热。以傅男子阴，阴消无气。杀金银铜锡毒。熔化还复为丹，久服神仙不死。一名汞。（得铅则凝，得硫则结，并枣肉、人唾研则散。别法煅为腻粉、粉霜，得紫河车则伏，得川椒则收。）\n\n         疏：水银从石中迸出为石汞，从丹砂中出者为朱里汞，即丹砂中液也。禀至阴之气而有汞，故其味辛，其气寒而有毒，善能杀虫，其气下走无停歇。故《本经》以之主疥瘘痂疡，白秃，杀皮肤中虱，及堕胎除热也。至阴之精，能消阳气，故不利男子阴也。神仙不死之说，必得铅华相合，乃能收摄真气，凝结为丹。即道家所谓太阳流珠常欲去，人卒得金华，转而相因之旨也。伏炼五金为泥，以其性能杀金银铜锡毒也。熔化还复为丹，亦出仙家烹炼耳。\n\n【主治参与】\n      得矾石、丹砂、芒硝、雄黄、黑铅，入阳城罐内，如法升炼，名红粉霜。能止痛生肌。少加冰片，研匀，擦广疮有效。制法具矾、轻粉。\n\n同大风子、蛇床子、樟脑、轻粉、枯矾、雄黄、胡桃油，治疥癣虫疮。\n\n《肘后方》一切恶疮：水银、黄连、胡粉熬黄各一两，研匀傅之。干则以唾调。\n\n【简误】\n         陈藏器曰：水银入耳，能食人脑至尽，入肉令百节挛缩，倒阴绝阳。人患疮疥，多以水银涂之。性滑重，直入肉，宜谨之。头疮切不可用，恐入经络，必缓筋骨。寇宗奭云：水银入药，虽各有法，极须审谨，有毒故也。历举学士大夫惑于方士之说，服煅炼水银暴卒者，不可胜数。妇人误服，多致绝孕。其为毒害昭昭矣。惟宜外傅，不宜内服。入口为厉，可不戒哉！', NULL, NULL, NULL, '水银', NULL, '4、水银', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971668, '6B19664F49616946466F4BCFBBA0563A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7139, 410, 400105403, '        味咸，温，无毒。主杀鬼蛊邪疰毒气，下部疮，伤寒寒热，吐胸中痰癖，止心腹卒痛，坚肌骨。多食伤肺，喜咳。\n\n        疏：盐禀水气以生。《洪范》：润下作咸。\n \n      《素问》：水生咸。此盐之根源也。《本经》味咸。\n\n      《别录》咸温无毒。察其本具气味，则是咸寒，而非温也。气薄味厚，阴也，降也。入足少阴，亦入手少阴、足阳明、手太阴、阳明经。其主肠胃结热，喘逆胸中病，及伤寒寒热者，皆热邪在阳明也。\n\n     《经》曰：热淫于内，治以咸寒。正此之谓也。五脏苦欲补泻云：心欲软，急食咸以软之，以咸补之。心虚则邪热客之而卒痛，咸寒能除热补心，故主心腹卒痛也。凡湿热在下焦，则为疮；留著经络，则肌骨软。咸寒能除湿热，故主之也。或以为咸能软坚，又何以坚肌骨？不知肌骨软缓，皆湿热所致，《经》曰：热则骨消筋缓。又曰：体重胕肿，肉如泥，皆属于湿。如夏月湿热大盛，则肉食易于溃散，得盐性之咸寒，乃能坚久不腐也。咸味涌泄，所以能吐胸中痰癖，及鬼蛊邪疰毒气，悉皆吐出也。多食作肺喜咳者，肺主清肃，多食则咸味渍入肺窍，故令咳也。\n\n     《日华子》以之助水脏，及霍乱心痛，金疮，明目，止风泪邪气，一切虫伤，疮肿，火灼，通大小肠，疗疝气。诸治悉取其入肾入心，走血软坚，除热润下之功耳。\n\n【主治参与】\n        炒盐三钱，以炒砂仁五钱，为末泡汤，井水澄冷，灌下。治霍乱心腹绞痛，有效。一味炒，作汤，治心经火热作痛。\n\n柳柳州纂《救三死方》治霍乱上不得吐，下不得泻，气绝欲死者，用盐一大匙，熬令黄，童子小便一升，合和温服，少顷吐下，即愈也。\n\n孙真人方：卒中尸遁，服盐汤取吐，效。\n\n甄权《药性论》中恶心痛，盐如鸡子大，青布裹，烧赤，纳酒中，顿服。当吐恶物愈。\n\n唐瑶《经验方》风热牙痛：以槐枝煎浓汤二碗，入盐一斤，煮干炒研，日用揩齿，以水洗目。\n\n《梅师方》：蜈蚣咬人，嚼盐涂之，或盐汤洗之，妙。\n\n《经验方》：蚯蚓咬毒，形如大风，眉鬓皆落，惟浓煎盐汤，浸身数遍即愈。浙西将军张韶病此，每夕蚯蚓鸣于体，一僧用此方而安。蚯蚓畏盐故也。\n\n【简误】\n        《内经》曰：咸走血，血病无多食咸，多食则脉凝泣而色变。凡血病及喘嗽、水肿、消渴，法所大忌。以其或伤肺引痰，或泣血脉，或助水邪，或走精液故也。', NULL, NULL, NULL, '食盐', NULL, '3、食盐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971669, '9B5D92D47C66F59DB90D10C96678B29B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7140, 410, 400105402, '         味酸，温大热，有毒。主妇人阴蚀，疽痔恶血，坚筋骨，除头秃，疗心腹积聚邪气，冷癖在胁，咳逆上气，脚冷疼弱无力，及鼻衄，恶疮，下部疮，止血，杀疥虫。（能干汞，中其毒者，黑铅煎汤解之。或食冷猪血。）\n\n         疏：石硫黄禀火气以生，《本经》味酸，气温，有毒。\n\n       《别录》大热。黄帝、雷公：咸，有毒。气味俱厚，纯阳之物也，入手厥阴经。经曰：寒淫于内，治以温热。冷癖在胁，咳逆上气，寒邪在中也，非温剂无以除之。又曰：硬则气坚，咸以软之。心腹积聚邪气，坚积在中也，非咸剂无以软之。命门火衰，则为脚冷疼弱无力。下焦湿甚，则为阴蚀、疽痔、疮。酸温能补命门不足，大热能除下焦湿气，故主之也。其主头秃、恶疮、疥虫者，悉取其除湿杀虫之功耳。\n\n    《本经》又主坚筋骨，及《别录》疗鼻衄止血者，皆非所宜。夫热甚则骨消筋缓，火载血上则错经妄行，岂有大热之物反能疗是证哉？无是理也！\n\n【主治参与】\n入鸡子，同艾叶煮食，治妇人白带因于虚寒者。\n\n《圣惠方》：诸疮弩肉，如蛇出数寸：硫黄末一两，肉上薄之，即缩。\n\n《急救良方》疥疮有虫：硫黄末，以鸡子煎香油调搽，极效。\n\n【简误】\n       硫黄，古方未有服饵者。《本经》所用，止于治疮蚀，攻积聚，冷气脚弱等，而近世遂为常服。丸散如来复丹、半硫丸、金液丹、黑龙丹，及诸方书所载者，不可缕指，称其功用，亦未能殚述。然而人身之中，阳常有余，阴常不足，病寒者少，病热者多。苟非真病虚寒，胡可服此大热毒药？假令果系虚寒证，法当补气以回阳，亦何须藉此毒石哉！世人徒知其取效良捷，而不知其为害之酷烈也。戒之！戒之！', NULL, NULL, NULL, '石硫磺', NULL, '2、石硫磺', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971670, '90954A86366BF554AD029DFF1B473818', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7141, 410, 400105401, '      味苦甘，平寒大温，有毒。主寒热，鼠瘘，恶疮，疽痔，死肌，疗疥虫疮，目痛，鼻中息肉，及绝筋破骨，百节中大风，积聚癖气，中恶腹痛，鬼疰，杀精物恶鬼邪气，百虫毒。胜五兵，杀诸蛇虺毒，解藜芦毒。悦泽人面。炼食之，轻身神仙。饵食之，皆飞入人脑中，胜鬼神，延年益寿，保中不饥。得铜可作金。\n\n       疏：雄黄禀火金之性，得正阳之气以生。\n     《本经》味苦，平，气寒，有毒。\n    《别录》加甘、大温。甄权言辛，大毒、察其功用，应是辛苦温之药，而甘寒则非也。气味俱厚，升也阳也。入足阳明经。其主杀精物恶鬼邪气，及中恶腹痛鬼疰者，盖以阳明虚则邪恶易侵，阴气胜则精鬼易凭，得阳气之正者，能破幽暗，所以杀一切鬼邪，胜五兵也。寒热、鼠瘘、恶疮、疽痔、死肌，疥虫疮诸证，皆湿热留滞肌肉所致，久则浸淫而生虫。此药苦辛，能燥湿杀虫，故为疮家要药。其主鼻中息肉者，肺气结也；癖气者，大肠积滞也；筋骨断绝者，气血不续也。辛能散结滞，温能通行气血，辛温相合而杀虫，故能搜剔百节中大风积聚也。虺蛇阴物，藜芦阴草，雄黄禀纯阳之气，所以善杀百虫蛇虺毒，及解藜芦毒也。\n\n《别录》复有目痛及悦泽人面之语，悉非正治。炼饵之法，出自仙经。以铜为金，亦黄白术中事耳。\n\n【主治参与】\n\n同红、白药子、白及、白敛、乳香、没药、冰片，傅一切肿毒痈疽。\n\n研细末，入猪胆内，套指头上，治天蛇疔毒发于中指。\n\n同金头蜈蚣、牛角䚡、猪悬蹄、猬皮、象牙末、黄蜡、白矾，治通肠漏。\n\n同漆叶、苦参、刺蒺藜、白芷、荆芥、天麻、鳖虱胡麻、半枝莲、豨莶、百部、天门冬，治大麻风眉毛脱落。\n\n治暑毒疟痢，百法不效，用雄黄研细，水飞九次，竹筒盛，蒸七次，再研，蒸饼和丸梧子大。每服甘草汤下七丸，日三服。其辞云：暑毒在脾，湿气连脚。不泄则痢，不痢则疟。独炼雄黄，蒸饼和药。别作治疗，医家大错，此昔人梦中所得之方，今试之辄效。\n\n《圣惠方》伤寒狐惑，虫食下部，痛痒不止：雄黄半两，烧于瓶中，熏其下部。\n\n《肘后方》五尸疰，病发则变痛无常，昏恍沉重，缠结脏腑，上冲心胁，即身中尸鬼接引为害也：雄黄、大蒜各一两，杵丸弹子大，每热酒服一丸。\n\n夏氏《奇疾方》筋肉虫，有虫如蟹，走于皮下，作声如小儿啼，为筋肉之化：雄黄、雷丸各一两，为末，掺猪肉上炙熟，吃尽自安。\n\n《积德堂方》广东恶疮：雄黄一钱半，杏仁三十粒去皮，轻粉一钱。为末，洗净，以雄猪胆汁调上，二三日即愈。百发百中，天下第一方也。出武定侯府内。入龙脑少许尤良。\n\n【简误】\n       雄黄杀蛇虫咬毒，及傅疥癣、恶疮、疔肿，辟鬼魅邪气，在所必用。然而性热有毒，外用易见其所长，内服难免其无害。凡在服饵，中病乃已，毋尽剂也。', NULL, NULL, NULL, '雄黄', NULL, '1、雄黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626041115971671, 'FC5C7E906C3E811DAC123A4956C3F698', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 10:27:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7142, 411, 400105523, '     平。治翳障，明目，疗风赤眼，盐卤浸用。妇人横逆产，心腹痛，月隔，五淋，以醋淬用。\n\n      疏：古文钱，其金毒火毒悉去，性应平无毒，而寇宗奭云：古钱其铜焦赤有毒。不知本草内赤铜之毒已微，况古钱又多于古穴坑堑中得之，历年既久，毒性必失，甚则有但存形质者。其味辛，气平，平即凉也。目赤翳障，肝经风热也，辛凉能散风热，则翳障赤痛除，目自明矣。妇人生产横逆者，血气壅塞，道路不开也。心腹痛者，亦气血结聚也。月隔者，月事不来，胞脉闭也。五淋者，冲任热壅也。此药能走下焦阴分，散凝滞之气血，开壅塞之道路，则诸证无不除矣。又能主跌扑损伤，其为散凝滞之药无疑。\n\n【主治参与】\n同自然铜、胎骨、䗪虫、血竭、无名异、黄荆子、没药、乳香、狗骨，治跌扑损伤及金刃伤，神效。\n\n《青囊录》跌扑损伤：半两钱五个，火煅醋淬四十九次，甜瓜子五钱，真珠二钱研末。每服一字，好酒调，随上下，食前后。\n\n古方麦斗散：治一切伤损。自然铜煅一两，古文钱煅一两，麝香五分，为末。每服五分，酒下。\n\n【简误】\n       其味辛凉，但能治风热眼。有佐以姜汁点眼者，即从治之意，借其热以拔出火毒也。如肝肾虚而风障生花者，必不宜用。', NULL, NULL, NULL, '古文钱', NULL, '23、古文钱', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954950, '75A4B6E553B68A1C92B7C50CF0D247F7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7143, 411, 400105522, '    冷，无毒。消痰，止惊悸，解酒毒，疗胸膈烦闷，中风痰实，止渴。（一名铅白霜，用铅杂水银十五分之一，合炼作片，置醋瓮中密封，经久成霜。）\n\n      疏：铅霜乃铅假汞气交感，因醋以拔其英华所结。道家谓之神符白雪。其味甘酸，气大寒，无毒。凡中风惊悸，未有不因痰热所生。胸膈烦闷多渴，亦火热炎灼所致。甘寒能除热生津，则痰结消，惊悸平，风自愈也。其主解酒毒者，亦取其除热生津之意耳。并治吐逆，镇惊去怯，黑须发。\n\n【主治参与】\n诸方俱见铅条下。\n\n《简要济众》治室女月露滞涩，心烦恍惚：铅白霜细研为散，每服一钱，地黄汁一合调下。\n\n《十全普救方》治鼻衄：铅白霜为末，取新汲水，调服一字。\n\n【简误】\n       铅霜，附痰去热，定惊痫，止吐逆，皆有奇效。然其性极冷，非久服常用之物，病已即去之。胃弱脾虚肠滑者，不宜用。风寒咳嗽多痰者，并忌之。', NULL, NULL, NULL, '铅霜', NULL, '22、铅霜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954951, '8858D94243D059430E8A9D9CAB9FA30C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7144, 411, 400105521, '      味苦、辛，暖，无毒。消痰止嗽，破癥结，喉痹，及焊金银用。一名鹏砂\n\n       疏：蓬砂出于西南番，采取煎淋而结，亦如硝石、硇砂之类。本经味苦辛，气暖无毒。然详其用，味应有咸，气亦微暖。色白而体轻，能解上焦胸膈肺分之痰热。辛能散，苦能泄，咸能软，故主消痰止嗽、喉痹及破癥结也。寇宗奭云：含化咽津，治喉中肿痛，膈上痰热，初觉便治，不能成喉痹也。兼能去口气，消障翳，除噎膈反胃，积块瘀肉，阴㿉，骨哽，恶疮，折伤，及口齿诸病。\n\n【主治参与】\n同龙脑香、人中白、青黛为末，傅口舌疮效。\n\n《经验方》咽喉肿痛，破棺丹：用蓬砂、白梅等分，捣丸芡子大。每噙化一丸。\n\n《集玄方》：小儿阴㿉肿大不消：鹏砂一分，水研涂之，大效。\n\n《直指方》胬肉瘀突：南鹏砂黄色者一钱，龙脑香少许，研末。灯草蘸点之。\n\n【简误】\n        蓬砂，其性参柔五金，去垢腻，克削为用，消散为能。宜攻有余，难施不足。此暂用之药，非久服之剂。', NULL, NULL, NULL, '蓬砂', NULL, '21、蓬砂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954952, 'AB7973B2DFBD86CF2F97E61BEFEDA56D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7145, 411, 400105520, '      主金疮止血。又疗产妇血晕恶血。出陕、华诸郡。色正黄，形之大小，方圆无定。欲服者当以大火烧之。金疮止血，刮末傅之即合，仍不作脓溃。或名花蕊石。\n\n       疏：花乳石，本经无气味。详其所主，应是酸辛温之药。其功专于止血，能使血化为水。妇人血晕，恶血上薄也。消化恶血，则晕自止矣。以酸敛之气，复能化瘀血，故傅金疮即合，仍不作脓也。\n\n【主治参与】\n        葛可久《十药神书》花乳石散：治五内崩损，喷血出升斗，用此治之。花蕊石煅存性，研如粉，以童子小便一钟，男人酒一半，女人醋一半，令温，食后调服三钱，甚者五钱，能使瘀血化为黄水，后以独参汤补之。按：此石性温，味辛，又加火煅，虚劳吐血多是火炎迫血上行，于药性非宜。除是膈上原有瘀血停凝者，乃可暂用，亦须多服童便。独参汤乃肺热咳嗽所忌，尤不宜于虚劳内热火炎之人。戒之！戒之！', NULL, NULL, NULL, '花乳石', NULL, '20、花乳石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954953, 'C1CD60BA4513DFCC4388BC2C6C64FE25', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7146, 411, 400105519, '         疏：麦饭石出自苏颂《图经》，附于姜石条内。因姜石有疔肿之用，故引及之。其味、气必与姜石相似。但得火煅醋淬之后，复有温暖收敛之功。昔吕子华秘方麦饭石膏，治发背疮神效。取此石碎如棋子，炭火烧赤，投米醋中浸之。良久，又烧又浸，如此十次，研末极细如飞尘；鹿角一具连脑骨者，二三寸截之，炭火烧令烟尽即止。白蔹末与石末等分，鹿角倍之。用三年米醋，入银石器内，煎令鱼目沸，即下前药，不住手搅，熬一二时，稀稠得所，倾出待冷。以鹅翎拂膏于肿上四围赤处，中留肿头泄气。如未脓即内消，已作头即撮小，已溃即排脓。若病久肌肉烂落，见出筋骨者，即涂细布上贴之，干即易，逐日疮口收敛。但中膈不穴者，即无不瘥。已溃者，用时先以猪蹄汤洗去脓血，挹干，然后上药。其疮切忌手触动嫩肉，仍不可以口气吹风，及腋气、月经、孕妇见之，合药时亦忌此等。初时一日一换，十日后二日一换。此药要极细方有效。若不细，涂之即痛也。煅久亦无效，临用方煅，煅过即研若飞尘一二两，可治一痈疽矣。', NULL, NULL, NULL, '麦饭石', NULL, '19、麦饭石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954954, '87CB9F69FC86E99B16A95C90A17214E4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7147, 411, 400105518, '       治食积不消，留滞藏府，宿食癥块久不瘥，及小儿食积羸瘦，妇人积年食癥，攻刺心腹。一名青礞石。\n\n        疏：礞石禀石中刚猛之性，体重而降，能消一切积聚痰结。其味辛咸，气平无毒。辛主散结，咸主软坚，重主坠下，故本经所主诸证，皆出一贯也。今世又以之治小儿惊痰喘急。入滚痰丸治诸痰怪证。\n\n【主治参与】\n        王隐君《养生主论》滚痰丸：通治痰为百病，惟水泻、娠妇不宜服。礞石、焰硝各二两煅过研飞，晒干一两，大黄酒蒸八两，前胡八两，沉香五钱，为末，水丸梧子大。常服一二十丸，欲利大便则服一二百丸，温水下。\n\n【简误】\n        礞石消积滞，坠痰涎，诚为要药。然而攻击太过，性复沉坠，凡积滞癥结、脾胃壮实者可用，虚弱者忌之。小儿惊痰食积，实热初发者可用，虚弱久病者忌之。如王隐君所制滚痰丸，谓百病皆生于痰，不论虚实寒热概用，殊为未妥。不知痰有二因，因于脾胃不能运化，积滞生痰，或多食酒面湿热之物，以致胶固稠粘，咯唾难出者，用之豁痰利窍，除热泄结，应如桴鼓。由于阴虚火炎，煎熬津液，凝结为痰。或发热声哑，痰血杂出者，如误投之，则阴气愈虚，阳火反炽，痰热未退，而脾胃先为之败矣。可见前人立方，不能无敝，是在后人善于简择耳。', NULL, NULL, NULL, '礞石', NULL, '18、礞石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954955, '4178975EDB60EBBD6DC6A9B9677F87B8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7148, 411, 400105517, '      主腹痛，噎，中恶，鼻衄，小儿软疮。\n\n       疏：梁上尘乃是空中烟气结成。本经无气味，应是辛苦之物。辛能散，苦能泄，故主腹痛，噎膈，中恶也。体轻而上腾，故入肺，味辛而清热，故又主鼻衄，及小儿软疮也。一名倒挂尘，一名乌龙尾。\n\n【主治参与】\n          孙氏《集效方》喉痹、乳蛾：乌龙尾、枯矾、猪牙皂荚以盐炒黄，等分为末。或吹或点皆妙。一法：用灯心以盐中苦卤浸过，入鸡子壳中，煅存性，取出研细，加龙脑香一二分，研匀，明矾末五分，同梁上倒挂尘五分，青鱼胆调，点入喉，治喉痹咽痛有效。', NULL, NULL, NULL, '梁上尘', NULL, '17、梁上尘', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954956, 'AD5EEF38838B3CEA02FDC709C5E71B29', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7149, 411, 400105516, '       味辛，平，无毒。疗折伤，散血止痛，破积聚。生邕州山岩中出铜处，于坑中及石间采得，方圆不定，其色青黄如铜，不从矿炼，故号自然铜。（入药火煅醋淬七次，研细水飞过用。）\n\n        疏：自然铜禀土金之气以生，故其味辛，气平，无毒。乃入血行血，续筋接骨之神药也。凡折伤则血瘀而作痛，辛能散瘀滞之血，破积聚之气，则痛止而伤自和也。大明主消瘀血、排脓，续筋骨，治产后血邪，安心止惊悸，以酒磨服者，可谓悉其用矣。寇宗奭云：有人以自然铜饲折翅胡雁，后遂飞去，今人打扑损伤，研细水飞过，同当归、没药各半钱，以酒调服，仍以手摩痛处，即时见效。\n\n【主治参与】\n          同乳香、没药、䗪虫、五铢古钱、麻皮灰、血竭、胎骨作丸，煎当归、地黄、续断、牛膝、牡丹皮、红花浓汤送下，治跌扑损伤，或金刃伤骨断筋，皆效。\n【简误】\n雷公云：石髓铅即自然铜也。凡使勿用方金牙，其方金牙真似石髓铅。若误饵，吐杀人。石髓铅色似干银泥，味微甘也。凡使中病乃已，不可过服，以其有火金之毒，走散太甚。', NULL, NULL, NULL, '自然铜', NULL, '16、自然铜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954957, 'F1A1913CEAFD08BAA2482AE74BF6F0D8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7150, 411, 400105515, '     寒，主解中毒烦闷。\n\n      疏：地浆，弘景云：此掘地作坎，以水沃其中，搅令浊，俄顷取之，以解中诸毒。盖取土为万物之母，诸毒遇土则化故也。山中有毒蕈，人不识，煮食之，无不死。又枫树蕈，食之令人笑不止。惟饮地浆皆瘥，余药不能救也。\n\n【主治参与】\n《圣惠方》热渴烦闷：地浆一盏，饮之。\n\n《千金方》中暑霍乱，不吐不利，胀痛欲死：地浆三五盏，服即愈。大忌米汤。\n\n《金匮》方：中闭口椒毒，吐白沫，身冷欲死者，地浆饮之。\n\n《集玄方》中砒霜毒：地浆调玄明粉服之，立解。', NULL, NULL, NULL, '地浆', NULL, '15、地浆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954958, 'D2266E91422B407680CEA6A0E8EF2300', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7151, 411, 400105514, '      味咸，寒，无毒。主明目，目痛，益气，坚肌骨，去蛊毒心腹痛，溺血，吐血，齿舌出血。一名胡盐，一名青盐。\n\n       疏：戎盐禀水中至阴之气凝结而成，不经煎炼而生于涯埃坂（土责）之阴。其味咸，气寒，无毒。入手足少阴经。《经》曰：热淫于内，制以咸寒。血热则目痛不明，咸寒能入血除热，故主目痛明目也。心腹痛者，心虚而邪热客之也。吐血、齿舌上出血者，火迫血妄行，溢出于上也。咸主润下，俾火气不上炎，则有坎离交之象焉，故能主诸证也。溺血者，小肠热也。心与小肠为表里，心火降则小肠热自除也。《经》曰：热伤气。又曰：肾主骨。热则气散，骨消筋缓，咸能入肾，寒能除热，故主益气坚肌骨也。咸为水化，诸毒得水则解，故又能去毒蛊。日华子云 “助水脏，益精气，除五脏癥结，心腹积聚” 者，取其入肾及软坚除热之功耳。\n\n【主治参与】\n仲景《金匮》方：戎盐汤，治小便不通。用戎盐弹丸大一枚，茯苓半斤，白术二两，水煎服之。\n\n唐氏《经验方》风热牙痛：青盐一斤，槐枝半斤，水四碗，煎汁二碗，煮盐至干，炒研。日用揩齿洗目。\n\n《普济方》风眼烂弦：戎盐水化点之。\n\n“简误” 同食盐。', NULL, NULL, NULL, '戎盐', NULL, '14、戎盐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954959, '57F3091A12085E5F3F4EA9A8E887A1C3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7152, 411, 400105513, '      味苦、甘，寒，无毒。主鬼疰贼风蛊毒，杀精物恶鬼，腹中毒邪气，女子赤沃漏下，带下百病，产难，胎衣不出，堕胎，养血气，除五藏血脉中热，血痹，血瘀，大人小儿惊气入腹，及阴痿不起。（入药煅赤醋淬三次，研，水飞过用。畏天雄、附子。干姜为之使。）\n\n       疏：代赭石禀土中之阴气以生。《本经》味苦气寒，《别录》加甘，无毒。气薄味厚，阴也，降也。入手少阴、足厥阴经。少阴为君主之官，虚则气怯而百邪易入，或鬼疰邪气，或精物恶鬼，或惊气入腹所自来矣。得镇重之性，则心君泰定而幽暗破，邪无从着矣。其主五脏血脉中热，血痹，血瘀，贼风，及女子赤沃漏下，带下百病，皆肝心二经血热所致。甘寒能凉血，故主如上诸证也。甘寒又能解毒，故主蛊毒，腹中毒也。《经》曰：壮火食气，少火生气。火气太盛则阴痿反不能起，苦寒泄有余之火，所以能起阴痿也。重而下坠，故又主产难胞不出及堕胎也。\n\n【主治参与】\n仲景旋覆代赭汤：治伤寒汗吐下后，心下痞硬，噫气不除者。代赭一两，旋覆花三两，人参二两，生姜五两，大枣十二枚，半夏半升，甘草三两，水一斗，煮取六升，去滓再煮，取三升，温服一升，日三。\n\n《直指方》急慢惊风，吊眼撮口，搐搦不定：代赭石火烧醋淬七次，细研水飞，日干。每服一钱或半钱，煎真金汤调下，连进三服。儿脚胫上有赤斑，即是惊气已出，病当安也。无者不治，如慢惊，用冬瓜仁煎汤调，亦妙。\n\n《普济方》妇人血崩：代赭石煅为末，白汤服二钱。\n\n【简误】\n        下部虚寒者不宜用，阳虚阴痿者忌之。', NULL, NULL, NULL, '代赭石,代赭', NULL, '13、代赭石,代赭', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954960, '31781217FF3EC7CDCD1FB740A0549E1D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7153, 411, 400105512, '     至冷。主治汤火烧疮用之。\n\n     疏：井底砂禀地中至阴之气，味甘而大寒者也。故本经主汤火烧伤用。又能疗妊娠热病，取傅心下、脐及丹田，可护胎无失。\n\n   《肘后方》：卧忽不寤，勿以火照，火照之杀人。但痛啮其踵及足拇指甲际，而多唾其面，以井底泥涂其目，令人垂头于井中，呼其姓名便苏。', NULL, NULL, NULL, '井底砂', NULL, '12、井底砂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954961, 'E7EC98C63B0C2BD38A870D0E8D3D93EA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7154, 411, 400105511, '       平，微毒。治妇人血气心痛，合金疮，止血，明目，去肤赤、息肉。生铜皆有青，青则铜之精华。淘洗用。\n\n        疏：铜禀土中阴气以生，青则其英华秀出于外所结。凡铜入地久，或沃以咸、酸之味，乃生青，其义可见矣。本经气平无毒。然观今人用入吐风痰药，应是酸苦涩之味，而气则微寒也。酸入肝而主敛，故能止血合金疮。风热入肝经，则目生肤翳息肉，或赤烂泪出。苦寒能除风热，则所苦去而目自明矣。本经又主妇人血气心痛者，盖苦能泄结，而平则又兼辛散之义也。\n\n【主治参与】\n《经验方》碧林丹：治痰涎潮盛，卒中不语，及一身风瘫。用生绿二两，研细，水化去石，慢火熬干，取辰日、辰时、辰位上修合，再研入麝香一分，糯米粉糊丸弹子大，阴干。卒中者，每丸作二服，薄荷酒研下，吐出青碧涎，泻下恶物，大效。\n\n又方，口鼻疳疮。人中白一钱，铜绿三分，研傅之。\n\n《卫生易简方》烂弦风眼：铜青水调涂碗底，以艾熏干刮下，涂烂处。\n\n【简误】\n      目痛肤翳，不由风热外侵，而因于肝虚血少者，非所宜用。', NULL, NULL, NULL, '铜青', NULL, '11、铜青', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954962, '33E45DEDEB44D5A536B8D90B126B7EB5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7155, 411, 400105510, '     主贼风反折，烧赤铜五斤，内酒二斗中，百遍服。\n\n      疏：赤铜屑，《日华子》云：苦平微毒，亦能接骨理伤，功用与自然铜相等。第其性有毒耳。本经主贼风反折者，风气通于肝，肝属木，金能平之故也。藏器曰：赤铜屑能焊人骨，及六畜有损，细研酒服，直入骨损处。六畜死后，取骨视之，犹有焊痕可验。\n   \n   《朝野佥载》云：定州崔务堕马折足，医者取铜末，和酒服之，遂瘥。及亡后十年改葬，视其胫骨折处，犹有铜束之也。打熟铜不堪用。', NULL, NULL, NULL, '赤铜屑', NULL, '10、赤铜屑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954963, '8E4DD0E1187E4BA6A79DFD6B877963E8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7156, 411, 400105509, '     主下部疮，脱肛\n\n      疏：东壁土先得太阳真火之气，其气温和，其味甘，无毒。脾主四肢而恶湿，下部生疮，湿气侵脾也。得阳气之壮，故能燥湿除疮。脱肛亦大肠湿热所致，甘温而燥，故亦主之。藏器止泄痢霍乱烦闷者，取其土能补脾胃，温能和中也。得太阳初气，能祛暑湿之邪，故又主温疟及猝中暑热，搅土浆与之即解。\n\n【主治参与】\n甄权法：同蚬壳为末，傅豌豆疮。\n\n《肘后方》药毒烦闷欲死者：东壁土调水三升，顿饮之。\n\n《通变要法》解乌头毒，不拘川乌、草乌毒：用多年陈壁土，泡汤服之。\n\n《外台秘要》肛门凸出：东壁土一升，研末，傅肛门头出处，以长皂荚炙熟，互熨之。\n\n气味甘温，性无偏至，故不著“简误”。', NULL, NULL, NULL, '东壁土', NULL, '9、东壁土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954964, 'D9A9C2BBCD5FD3F50C4149F7C6B087B6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7157, 411, 400105508, '        味辛，寒，无毒。主伏尸，毒螫，杀三虫，去鳖瘕，疗恶疮，堕胎，止小便利。（一名铅粉，一名胡粉，一名官粉。）\n\n         疏：粉锡，陶隐居云：即化铅所作胡粉也。其味辛，气寒，无毒。体用与铅相似。性善杀虫，故去伏尸、三虫、鳖瘕。寒能解热毒，故疗恶疮，毒螫。重而下降，故能堕胎。涩而粘腻，故止小便利。甄权主积聚不消，炒焦，止小儿疳痢。藏器主久痢成疳，和鸡子白服，以粪黑为度。皆为其消积杀虫止痢也。\n\n附：李时珍云：胡粉即铅之变黑为白者也。其用虽与铅及黄丹同，内有豆粉、蛤粉杂之。止能入气分，不能入血分，此为稍异。人服食之则大便色黑者，此乃还其本质，所谓“色坏还为铅”也。亦可入膏药，代黄丹用。\n\n【主治参与】\n《肘后方》：劳复、食复欲死者，水调胡粉少许与之。\n\n《子母秘录》：小儿腹胀，或腹皮青色，不速治，须臾死。胡粉，盐熬色变，以摩腹上。\n\n《救急方》：杖疮肿痛：水粉一两，赤石脂生一钱，水银一分，以麻油杵成膏，摊油纸贴之。肉消者填满紧缚。\n\n《备急方》：阴股常湿，胡粉掺之。\n\n邵真人方：黄水脓疮，官粉煅、黄松香各三钱，黄丹一钱，飞矾二钱，为末，香油二两，熬膏傅之。\n\n《备急方》：小儿疳疮，熬胡粉，猪脂和涂。\n\n《集简方》妒精阴疮：铅粉二钱，银杏七个，铜铫内炒至银杏黄，去杏取粉，出火毒，研搽效。\n\n《圣惠方》翻花恶疮：胡粉一两，胭脂一两，为末。盐汤洗净傅之，日五次。\n\n《孙氏集效方》血风臁疮：官粉四两，水调入碗内，以蕲艾烧烟熏干，入乳香少许同研，香油调作隔纸膏，反复贴之。\n\n《千金方》小儿丹毒：唾和胡粉，从外至内傅之。\n\n又方，疮伤水湿：胡粉、炭灰等分，脂和涂孔上，水即出也。\n\n又方：蠼螋尿疮：醋和胡粉涂之。\n\n《直指方》发背恶疮，诸痈肿：好锡粉二两，真麻油三两，慢火熬，以柳枝急搅，至滴水成珠，入白胶末少许，入瓷器水浸二日，油纸摊贴，名神应膏。\n\n【简误】\n       胡粉虽能消疳逐积，杀虫止痢，然其性冷，走而不守。脾胃虚弱者不宜用。娠妇忌之。', NULL, NULL, NULL, '粉锡', NULL, '8、粉锡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954965, '6FB7B6D6DC0ECA30F2DD2BB0F46ADB30', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7158, 411, 400105507, '     味甘，无毒。镇心安神，治伤寒毒气，反胃呕哕。蛇蜴所咬，炙熨之。\n\n      疏：铅禀先天壬癸之气以生，一者数之始，水者物之初，故曰天一生水。中含生气，为万物之先，金丹之母，八石之祖，五金之宝。壬金为清，癸水为浊。清为阳气，浊为阴质。阳气为生，阴质有毒。范以法象，招摄阴阳。烹炼得宜，是成丹药，饵之仙去。生气之初，味固应甘。润下之性，无毒可知。心藏神而法火，宁谧则安，妄炎则病，重而润下，使水火既济而不妄炎，故主镇心安神。伤寒毒气者，即阳证热毒也。先天真水，性含生气，而属至阴，故能解之也。反胃呕哕者，火气上浮，阴阳将离，故气逆升，而发呕哕也。兹得镇坠以下之，则阳火归元而前病自止矣。蛇蜴之毒，无非热气，诸毒得水则解，故亦主之也。五行万物之中，能解一切毒气者，无过先天生气，土中冲气。铅兼有之，故为解诸毒之首药也。\n\n【主治参与】\n黑铅入养正丹，治一切上盛下虚，孤阳发越上浮，烦躁面赤，恍忽惊惕，呕吐反胃等证。用此以镇坠阳气，使火入阴分，则上焦得宁，而后可以随证施治。\n\n入黑锡丹，治一切下元虚冷，阳气垂绝，阴阳将离，及沉寒痼冷诸病。\n\n《圣济录》治小儿惊热，心肺积热，夜卧多惊：铅霜、牛黄各半分，铁粉一分，研匀。每服一字，竹沥调下。\n\n《普济方》惊风痫疾，喉闭牙紧：铅白霜一字，蟾酥少许，为末。乌梅肉蘸药于龈上揩之。仍吹通关药，良久便开。\n\n《圣济录》治消渴烦热：铅白霜、枯白矾等分，为末，蜜丸芡实大，绵裹含化咽汁。又方：铅白霜一两，黄消石一两，为末，每冷水服一钱。\n\n喉痹肿痛：铅白霜、甘草各半两，青黛一两，为末，醋糊丸芡子大。每含咽一丸，立效。\n\n《宣明方》治口疳龈烂，气臭血出，不拘大人小儿：铅白霜、铜绿各二钱，白矾豆许，为末扫之。\n\n《普济方》梳发令黑：铅霜包梳，日日梳之，胜于染者。\n\n【简误】\n          铅性沉重，未经烹炼，癸水之阴质尚存。多服能损伤心脾，盖金石与人身气血异。《悟真篇》云“非类难为巧”是已。凡脾胃虚寒，阳火不足，饮食不化，下部阴湿诸证，法咸忌之。', NULL, NULL, NULL, '铅', NULL, '7、铅', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954966, '3E8F87D0B8180D0219F55EE1C56F1964', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7159, 411, 400105506, '     味辛，微寒。主吐逆胃反，惊痫癫疾，除热下气，止小便利，除毒热，脐挛，金疮溢血，炼化还成九光，久服通神明。（自炒成者佳。市中多杂砂土、矾红，不堪用。）\n\n       疏：铅丹即熬铅所作黄丹，故其味辛，气微寒，性应无毒。铅禀先天壬癸之气，得火成丹，则又有灵通变化之神。其体重而降。胃反吐逆，火气上升也。惊痫癫疾，心气虚怯也。得润下镇重之性，则火不上炎，热气自下，心肾得交，而前证除矣。禀天一所生之气，故能除热毒及金疮溢血也。止小便利者，心与小肠为表里，心神宁敛则小便自有节也。脐挛者，即小儿脐风也。风热入肝则筋自挛急。辛寒镇重，能散风热；金液之性，能平肝木，故主之也。久服通神明者，以其得先天之气，故能镇心安神也。今世又用以解散热毒，长肉去瘀，治恶疮肿毒，及入膏药，为外科必用之物。\n\n【主治参与】\n单用傅疮，能止痛长肉生肌。\n\n入一切膏药，贴恶疮肿毒。\n\n仲景柴胡加龙骨牡蛎汤：治伤寒八九日，下之，胸满烦惊，小便不利，谵语身重者。铅丹、龙骨、柴胡、牡蛎、黄芩、生姜、人参、桂枝、茯苓各一两半，半夏二合半，大黄二两，枣六枚，以水八升，煮取四升，内大黄，更煮一二沸，去渣，温服一升。\n\n《集验方》治吐逆不止。碧霞丹：黄丹四两，米醋半升，煎干，炭火三秤，就铫内煅红，冷定为末，粟米饭丸梧子大。每服七丸，醋汤下。\n\n《刘涓子鬼遗方》小儿瘅疟，壮热不寒：黄丹二钱，蜜水和服，冷者酒服，名鬼哭丹。\n\n《痘疹方》痘疹生翳：黄丹、轻粉等分，为末，吹少许入耳内，左患吹右，右患吹左。\n\n《子母秘录》小儿重舌：黄丹一豆大，安舌下。\n\n《普济方》小儿口疮糜烂：黄丹一钱，生蜜一两，相和蒸黑。每以鸡毛蘸搽，甚效。\n\n《集玄方》：金疮出血不止，以药速合，则内溃伤肉。只以黄丹、滑石等分，为末傅之。\n\n陆氏《积德堂方》血风臁疮：黄丹一两，黄蜡一两，香油五钱，熬膏。先以葱、椒汤洗，贴之。\n\n《集效方》远近臁疮：黄丹水飞炒，黄檗酒浸七日焙，各一两，轻粉半两，研细，以苦茶洗净，轻粉填满，次用黄丹护之，外以檗末摊膏贴之，勿揭动，一七见效。\n\n【简误】\n       吐逆由于胃虚，及因寒发吐者，皆不宜服。', NULL, NULL, NULL, '铅丹', NULL, '6、铅丹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954967, '18E7C0FBACBF7652CF9D3FD9ADC8638B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7160, 411, 400105505, '        味咸、苦、辛，温，有毒。不宜多服。主积聚，破结血，烂胎，止痛，疗咳嗽宿冷，去恶肉，生好肌。柔金银，可为焊药。形如牙硝，光洁者良。（凡用，水飞去尘秽，入瓷器中，重汤煮干。）\n.\n        疏：硇砂乃卤液所结，秉阴毒之气，含阳毒之精。其味极咸、极苦、极辛，气温有毒。甄权：酸咸，有大毒。能消五金八石，腐坏人肠胃。生食之，化人心为血，其毒之猛烈如此，可畏矣！其主积聚结血宿冷者，以咸能入血软坚，辛能散结，温能除冷故也。积聚散则痛自止，气自下。因寒以致顽痰壅结则咳嗽作，故暂用以散之。柔金化石之性，故能烂胎去恶肉也。金石见之即化，其能生好肌乎？此前人之误耳！\n\n【主治参与】\n《普济方》损目生瘀，赤肉弩出不退：杏仁百粒，蒸熟去皮尖研，滤取净汁，入硇砂末一分，水煮化，日点一二次自落。\n\n白飞霞方：鼻中息肉，硇砂点之，即落。此方须入明矾、牛黄、铅粉、象牙末、真珠末，乃佳。\n\n《集效方》面上疣目：硇砂少许，硼砂、铁锈、麝香等分研，搽三次自落，急以甘草汁浸洗。\n\n【简误】\n        按硇砂大热有毒之物，近出于唐世，而方书著古人单服一味，伏火作丸子。亦有兼硫黄、马牙硝辈合饵者，不知方出何时，殊非古法。此物虽能攻积聚凝结，化有形癖块，然多食腐坏人肠胃。观其柔化金铜锡，及庖人煮硬肉，入硇少许即烂，可以类推矣。惟去恶肉，及恶疮息肉，目翳弩肉，是其所长，亦须与真牛黄、龙脑、铅华、象牙末等同用。其内服诸方，虽唐慎微已收附本草末，然服必害人命，悉不敢载。一名狄盐，一名北庭砂，一名气砂，一名透骨将军。中其毒者，生绿豆研汁一二升饮之。畏浆水，忌羊血。', NULL, NULL, NULL, '硇砂', NULL, '5、硇砂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954968, 'B372413F646DE6A3103D77D6AC31C39C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7161, 411, 400105504, '     主蛊毒中恶，血晕吐血，亦涂金疮，生肌止血。\n\n      疏：铛墨，釜月中墨也。本经无气味。然观其所主，大约与伏龙肝相似，而其用则少劣也。凡血见灰、见黑则止，蛊毒恶气得辛温则散，故本经主蛊毒中恶。吐血血晕，以酒或水细研，温服，亦涂金疮，生肌止血也。慎勿入傅面疮药中，其黑入肉如黥，不能去也。血晕宜用米醋研服。', NULL, NULL, NULL, '铛墨', NULL, '4、铛墨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954969, 'F6C7F18AB2E9734F98AF167990512B56', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7162, 411, 400105503, '        味苦、酸，有毒。主诸疟，风痰在胸膈，可作吐药。不可久服，能伤人。飞炼砒黄而成。（畏绿豆，冷水。入药醋煮，杀毒用。）\n\n        疏：砒霜禀火之毒气，复兼煅炼，本经虽云味苦、酸，而其气则大热，性有大毒也。酸苦涌泄，故能吐诸疟，风痰在胸膈间。大热大毒之物，故不可久服，能伤人也。更善落胎，及枯痔杀虫。\n\n【简误】\n         按砒黄既已有毒，见火则毒愈甚。而世人多用砒霜以治疟，不知《内经》云：夏伤于暑，秋必痎疟。法当消暑益气健脾，是为正治，岂宜用此大热大毒之药？如果元气壮实有痰者，服之必大吐。虽暂获安，而所损真气实多矣。初烧霜时，人在上风十余丈外立，下风所近，草木皆死。以之毒鼠，鼠死，猫犬食之亦死。人服至一钱许，则立毙。若得酒及烧酒服，则肠胃腐烂，顷刻杀人。虽绿豆、冷水，亦难解矣。其于钩吻、射罔之毒，殆又甚焉！奈何今人用之治疟，是以必死之药，治必不死之病，岂不误哉！除枯痔杀虫用于外傅之药，此外慎毋服之。切戒！切戒！', NULL, NULL, NULL, '砒霜', NULL, '3、砒霜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954970, '0AAA9628FC2748892E6F4BAED0B9E7FB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7163, 411, 400105502, '     味辛，温。主疽疡疥瘙，热气恶疮，癞疾死肌堕眉，杀痔虫，去黑子息肉，疗髓骨疽。\n\n     疏：石灰烧青石而成，故其味辛，气温。《本经》不言其毒。观其主，皆不入汤，其为毒可知矣。火气未散，性能灼物，故主去黑子、息肉及堕眉也。其主疽疡疥瘙、热气恶疮、癞疾死肌、髓骨疽者，皆风热毒气浸淫于骨肉皮肤之间。辛温能散风热毒气，且能蚀去恶肉而生新肌，故为诸疮肿毒要药也。辛而燥，故又能杀痔虫。古方多用合百草团末，治金疮殊胜者，以其性能坚物，使不腐坏，且血见石灰则止，而百草又能活血凉血故也。\n\n古墓中石灰，名地龙骨。火毒已出，燥烈大减，故主顽疮瘘疮，脓水淋漓，及敛诸疮口尤效。\n\n艌船油灰，名水龙骨。得油性之润，复得水气之阴，故主金疮、跌扑伤损，破皮出血，及诸疮瘘、血风臁疮也。\n\n【主治参与】\n入三仙膏，点一切痈疽肿毒，轻者可消，重者势亦减。\n\n《普济方》疣痣瘤赘：石灰一两，用桑灰淋汁，熬成膏，刺破点之。\n\n又方：去痈疽瘀肉：石灰半斤，麦秆灰半斤，淋汁煎成霜，密封。每以针划破涂之，自腐落。\n\n有毒，不入汤丸，故无 “简误”。\n\n百草霜，乃烟气结成。其味辛，气温，无毒。辛主散，故能消化积滞及下食也。凡血见灰则止，此药性能止血，复能散瘀滞，故主上下诸血，及崩中带下，胎前产后诸病。\n\n【主治参与】\n《笔峰杂兴方》胎动下血，或胎已死：百草霜二钱，棕灰一钱，伏龙肝五钱，为末，每服二钱，白汤入酒及童便调下。\n\n《杜壬方》治横生倒逆，胎前产后虚损，月候不调，崩中带下。百草霜、白芷等分，为末。每服二钱，童子小便、醋各少许调匀，热汤化服，不过二服瘥。\n\n【简误】\n         虽能止血，无益肠胃。救标则可，治本则非，故不宜多服。', NULL, NULL, NULL, '石灰', NULL, '2、石灰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954971, '0BC9BB541CA1253156F830814DB39DA5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2024-12-24 14:10:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7164, 411, 400105501, '        味辛，微温，主妇人崩中、吐血，止咳逆，止血，消痈肿毒气。（此灶中对釜月下黄土，以年久如赤色石中黄者佳，研细水飞用。）\n\n        疏：伏龙肝得火土之气而成。本经味辛，气微温，无毒。甄权言咸。其质本土，味应有甘。以灶有神，故古方多以之治颠狂寐魇，及卒中邪等证。本经主妇人崩中、吐血、止咳逆、止血者，盖以失血过多，中气必损，甘能补中，微温能调和血脉，故主之也。消痈肿毒气者，辛散咸软之功也。日华子主催生下胞及小儿夜啼者，取其土中有神，而性本冲和，复能镇重下坠也。\n【主治参与】\n《千金方》卒中恶气：伏龙肝末一鸡子大，水服取吐。\n\n《救急方》产后血气攻心痛，恶露不下：灶中心土研末，酒服二钱，泻出恶物，立效。\n\n《伤寒类要》妊娠热病；伏龙肝末鸡子许大，水调服之，仍以水和涂脐上方寸，干则再上。\n\n《外台秘要》一切痈肿：伏龙肝以蒜和作泥，贴之，干再易。或鸡子黄和亦可。\n\n【简误】\n       阴虚吐血者不宜用，以其中有火气故也。痈肿毒盛难消者，不得独用。', NULL, NULL, NULL, '伏龙肝,灶心土', NULL, '1、伏龙肝,灶心土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626051000954972, '671E95940B844D810C446C22CD9708FA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 11:08:05', 1, 'admin', '2025-01-17 17:23:51');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7165, 412, 400105616, '     味甘、苦，平、微寒，无毒。主解百毒，杀百精老物殃鬼，辟瘟疫、瘴气、邪气，蛊毒入口皆吐出，中恶腹痛，时气毒疠，头痛寒热，风肿诸毒，喉痛口疮。久服不夭，轻身长年。　　\n\n疏：升麻禀天地清阳之气以生，阳草也。故味甘、苦，平、微寒，无毒。洁古又云：性温，味辛微苦。气味俱薄，浮而升，阳也。为足阳明、太阴引经的药。得葱白、白芷，缓带脉之纵急。亦入手阳明大肠，升阳气于至阴之下。春气生生而上升，升麻正得之，故主解百毒。感清阳之气者，必能破幽暗，故杀百精老物殃鬼，辟瘟疫瘴气邪气，蛊毒入口皆吐出。凡云甘者，其气必和，升则必散。和而散，故主中恶腹痛，时气毒疠，头痛寒热。风肿诸毒，喉痛口疮者，手少阳，足阳明、太阴热极故也。散三经之义，则二证愈矣。末载久服不夭，轻身长年，此岂发散之药所能哉？无是理也。　　\n\n【主治参与】　　\n升麻葛根汤，散足阳明之热邪，发手太阴、阳明之斑疹，及天行豌豆疮，水煎，绵沾拭之。　\n　\n引葱白，散手阳明风邪。引石膏，止阳明经齿痛。或加生地黄、麦门冬、知母、牡丹皮、黄檗、连翘、玄参，弥良。　\n　\n醋炒绿色升麻，君莲肉、人参，治噤口痢有神。　\n　\n同石膏、知母、麦门冬、竹叶，治阳明热极发斑，头疼口渴。　\n　\n佐参、耆，引清阳之气上升行阳道，故补脾胃药中不可阙。\n　　\n入升阳散火汤，治阳气郁遏，及元气不足阳气下陷。\n　　\n同荆芥、防风、黄芩、甘草、白芷，能去皮肤风邪。　\n　\n同葛根、荆芥、菊花、甘草，解肌肉间风热，兼发浮汗。　\n　\n同葛根、连翘、玄参、甘草、生地黄、麦门冬，治牙根浮烂恶臭。　\n　\n为小儿斑疹及天行疮子家圣药。天行疮子即痘也，未见点时可用，见标之后不可用。\n　　\n同郁金服，治蛊毒，不吐则下。　\n　\n同射干，水煎服，治射工溪毒，并以滓涂之。　　\n\n同生地黄、麦门冬、牛膝、蒲黄水煎，治小儿尿血。　\n　\n佐黄连、红曲、滑石、白芍药、莲肉、甘草，为治一切滞下要药。　\n　\n【简误】　　\n       升麻属阳而性升，其功用俱如经说。凡吐血、鼻衄、咳嗽多痰，阴虚火动，肾经不足，及气逆呕吐，惊悸怔忡，癫狂等病，法咸忌之。误用多致危殆。　', NULL, NULL, NULL, '升麻', NULL, '16、升麻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750085, '104F08F404B1A8FA3592AF4E573DFD36', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7166, 412, 400105617, '      味甘、咸，寒，无毒。主气癃，止痛，利水道小便，除湿痹，男子伤中，妇子淋沥，不欲食，养肺，强阴，益精，令人有子，明目，疗赤痛。久服轻身耐老。　　\n叶及根：味甘，寒。主金疮止血，衄鼻瘀血，血瘕下血，小便赤，止烦下气，除小虫。　　\n\n      疏：车前子禀土之冲气，兼天之冬气以生，故味甘寒而无毒。《别录》兼咸，故走水道。其主气癃止痛，通肾气也。小便利则湿去，湿去则痹除。伤中者，必内起烦热，甘寒而润下，则烦热解，故主伤中。女子淋沥不欲食，是脾肾交病也。湿去则脾健而思食，气通则淋沥自止。水利则无胃家湿热之气上熏，而肺得所养矣。男女阴中俱有二窍，一窍通精，一窍通水。命门真阳之火，即系先天之元气，道家谓之君火。后天之精气，亦与之合而系焉。膀胱者，湿热浊阴之水渗出下窍为小便，道家谓之民火是也。二窍不并开，故水窍常开，则小便利而湿热外泄，不致鼓动真阳之火，则精窍常闭而无漏泄。久久则真火宁谧而精用益固，精固则阴强，精盛则生子。肾气固即是水脏足，故明目及疗赤痛。轻身耐老，即强阴益精之验。肝肾膀胱三经之要药也。\n　　\n叶及根，味甘寒。金疮必发热，热则痛极。甘寒能凉血除热，故主金疮。血热则妄行，溢出上窍，故主吐衄，及尿血便赤，止烦下气。　　\n\n《明医杂录》云：根叶治鼻衄，尿血，热痢，捣汁饮之。子主气癃，利水道，疗肝中有风热冲目。若人服固精药久，服此一泄，即有子。　\n　\n【主治参与】　　\n同木通、沉香、橘皮、升麻，治气癃。　　\n\n同二术、宣木瓜、石斛、川萆薢、茯苓、五加皮，治湿痹。　\n　\n独用为末，米饮下二钱匕，治暴泻神效。　　\n\n君白芍药、白茯苓、白扁豆、炙甘草，治水泄。\n　　\n同生地黄、牛膝、天门冬、麦门冬、黄檗、五味子、甘枸杞子、人参、白胶，治尿血及妇人血淋。　\n　\n入五子衍宗丸，为生精种子要药。　　\n\n入金匮肾气丸，则固精益阴。　　\n\n独用炒为末，专治湿胜水泻。　　\n\n同五味子、覆盆子、莲子、莲须、山茱萸肉、没食子、沙苑蒺藜、人参、麦门冬、牛膝、白胶、鱼胶、能强阴固精种子。　　\n\n同生地黄、甘菊花、决明子、玄参、蜜蒙花、连翘、黄连、柴胡、生甘草，治暴赤目痛。　　\n\n【简误】　　\n        车前子性走下窍，虽有强阴益精之功，若遇内伤劳倦，阳气下陷之病，皆不当用。肾气虚脱者，忌与淡渗药同用。　　', NULL, NULL, NULL, '车前子', NULL, '17、车前子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750086, 'BA67CF3ED8067F41B2844C3D281D9339', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7167, 412, 400105618, '    味辛，温，无毒。主邪气，辟毒疫温鬼，强志，主淋露，疗气劣，肌中偏寒。主气不足，消毒，杀鬼精物，温疟，蛊毒，行药之精。久服不梦寤魇寐，轻身致神仙。　　\n\n     疏：青木香，味辛温无毒。是禀夏秋之阳气以生，兼得土之阳精，故无毒。性属纯阳，故主邪气，辟毒疫瘟鬼。阳主清明开发，故强志，及不梦寤魇寐。行药之精，皆阳盛气烈之功也。　　\n【主治参与】　　\n同延胡索，治一切女人血气刺心，痛不可忍。　\n　\n同牵牛、雷丸、槟榔，杀一切虫。\n　　\n佐黄连、芍药，治一切滞下。惟身热作呕逆、口渴者，勿用。\n　　\n同橘皮、砂仁、白豆蔻、紫苏叶，调一切气不通顺，及冷气攻痛作泄，大怒后气逆，胸膈胀满，两胁作痛。　\n　\n【简误】　　\n        详其治疗，与今白木香当是两种。按《图经》谓：生永昌，又云今惟广州舶上有来者。一云出大秦国，一云产昆仑。则所出地土各异，是名同而实异可知已。《药性论》云：当以昆仑来者为胜。此绝不可得。又云：西胡来者劣。今市肆所有，正白木香也。其味辛，其气温，专主诸气不顺。求其能辟毒疫温鬼，杀鬼精物，恐或未然也。肺虚有热者，慎毋犯之。元气虚脱，及阴虚内热，诸病有热，心痛属火者禁用。《伤寒类要》所载，治天行热病，若发赤豆斑，用青木香水煮服者，盖指昆仑来者一种，定非坊间所市广州舶上世所常用之白木香也。　　', NULL, NULL, NULL, '木香', NULL, '18、木香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750087, '8CDE1F78C85A9921763083A5D9B099B9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7168, 412, 400105615, '    味苦、甘，平、微温，无毒。主风寒所击，金疮止痛，贲豚，痫痓。女子疝瘕，疗诸贼风，百节痛风、无久新者。久服轻身耐老。一名羌活。（痓作痉。）　\n　\n     疏：独活禀天地正阳之气以生，故味苦、甘，平。甄权、洁古益之以辛，微温，无毒。气味俱薄，浮而升，阳也。足少阴引经气分之药。　　\n\n羌活性温，辛、苦，气厚于味，浮而升，阳也。手足太阳行经风药，并入足厥阴、少阴经气分。\n　　\n羌活气雄，独活气细。故雄者治足太阳风湿相搏，头痛肢节痛，一身尽痛者，非此不能除，乃却乱反正之主君药也。细者治足少阴伤风头痛，两足湿痹不能行动，非此不能除，而不治太阳之证。名列君部之中，非比柔懦之主。小无不入，大无不通，故能散肌表八风之邪，利周身百节之痛。其主风寒所击，金疮止痛者，金疮为风寒之所袭击，则血气壅而不行，故其痛愈甚。独活之苦甘辛温，能辟风寒，邪散则肌表安和，气血流通，故其痛自止也。贲豚者，肾之积。肾经为风寒乘虚客之，则成贲豚。此药本入足少阴，故治贲豚。痫与痓，皆风邪之所成也，风去则痫痓自愈矣。女子疝瘕者，寒湿乘虚中肾家所致也。苦能燥湿，温能辟寒，辛能发散，寒湿去而肾脏安，故主女子疝瘕，及疗诸贼风，百节痛风无久新也。轻身耐老，定非攻邪发散之药所能，乌可久服哉？《本经》载之误矣！二药本一种，第质有虚实老嫩，气有厚薄之不同耳。　　\n\n【主治参与】　　\n君麻黄、甘草，主冬月即病伤寒，太阳经头疼，发汗解表。　　\n\n君麦门冬、前胡、黄芩，佐以甘草，治春时瘟疫，邪在太阳头痛。　　\n\n入葛根汤，治太阳明头痛，兼遍身骨痛，口渴，烦热不得眠。若渴甚、烦热甚、头痛甚，则加石膏、知母、竹叶各两许。　\n　\n疟发太阳经头痛者，于治疟药中加之，痛止则去之。　　\n\n同白术、苍术、秦艽、生地黄、薏苡仁、木瓜、石斛、黄檗，治下部一切风湿、湿热。　　\n\n同生地黄、赤芍药、生甘草、牡丹皮、石膏等，水煎，治风热上攻牙肿痛。　　\n\n同莱菔子炒香，只取羌活为末，每服二钱，温酒调下，一日一服，二日二服，三日三服，治妊娠浮肿由于风湿。出许学士《本事方》。\n　　\n人睛忽垂至鼻，如黑角色，痛不可忍。或时时大便血出痛，名曰肝胀。羌活一味煎汁，服数盏自愈。出夏子益《奇疾方》。　\n　\n【简误】　　\n        独活、羌活，阳草中之风药也。本为祛风散寒除湿之要品。风能胜湿，以其性燥故也。\n\n     《本经》、《别录》并载主中风及诸风。不知真中风惟西北边塞高寒之地，风气刚猛，虚人当之，往往猝中，或口眼歪斜，或口噤不语，或手足瘫痪，左右不仁，或刚痉柔痉，即角弓反张，此药与诸风药并用可也。若夫江南、吴、楚、越、闽、百粤、鬼方、梁州之域，从无刚劲之风，多有湿热之患。质脆气虚，多热多痰。其患中风，如前等病，外证虽一一相似，而其中实非，何者？此皆刘河间所谓将息失宜，水不制火；丹溪所谓中湿、中痰、中气是也。此则病系气血两虚，虚则内热煎熬津液，结而为痰。热则生风，故致猝倒，亦如真中风状。而求其治疗之方，迥若天渊。外邪之气胜则实，实则泻之，祛风是已；内而真气不足则虚，虚则补之，调气、补血、生津、清热是已。倘误用风药，反致燥竭其津液，血愈不足而病愈沉困，命曰虚虚。攻补既谬，死生遂殊。粗工懵昧，执迷不悟，兹特表而明之。又有血虚头痛，及遍身疼痛骨痛，因而带寒热者，此属内证，误用反致作剧。', NULL, NULL, NULL, '独活,羌活', NULL, '15、独活,羌活', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750088, '0A56C81EBF6940C07915A50D3B1FC35B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7169, 412, 400105614, '     味甘，平、微寒，无毒。主心腹结气，伤中伤饱，胃络脉绝，羸瘦短气，身重目黄，心下支满，虚劳客热，口干燥渴，止呕吐，愈痿蹶，强阴益精，消谷，调中，保神，定肺气，安五藏，令人肥健，美颜色，有子。久服轻身，不老不饥。\n　　\n       疏：麦门冬，在天则禀春阳生生之气，在地则正感清和稼穑之甘。《本经》甘平，平者，冲和而淡也。\n\n《别录》微寒，著春德矣。入足阳明，兼入手少阴、太阴。实阳明之正药。主心腹结气者，邪热之气结于心腹间也。以其清和微寒而平缓，故能散热结而下逆气也。伤中伤饱，以致胃络脉绝者，脾主肌肉，五脏之气皆禀于胃，胃病则脾无所禀，故羸瘦而短气也。身重目黄者，脾胃湿热也。心下支满者，脾虚而湿滞中焦也。虚劳客热，口干燥渴者，因虚劳而热客中焦，故口干而燥渴。阳明之热上冲，则兼呕吐也。痿蹶者，阳明湿热病也。阳明湿热盛，则上熏蒸于肺，而为痿蹶。治痿独取阳明，治本之道也。阴精生于五味，五味先入脾胃。脾胃得所养，则能散精于各脏，而阴精充满，故能强阴益精也。中焦者，脾胃之所治也。脾胃安则中焦治，故能消谷而调中也。保神定肺气，则兼润乎心肺矣。胃气盛则五脏之气皆有所禀而安，脾胃俱实则能食而肥健。脾统血，心主血，五脏之英华皆见于面。血充脏安，则华彩外发而颜色美矣。脾胃强则后天之元气日盛。下气则阳交于阴，交则虚劳愈而内热不生，内热去则阴精日盛，故有子。断谷固著于仙经，却乃已疾之良药，故久服延年轻身，而不老不饥也。　\n　\n【主治参与】　　\n同人参、五味子，为生脉散。能复脉通心。夏月暑伤气，服之良。酒后饮之，解酒毒。肺热者，去人参，加甘枸杞子作饮，治一切虚劳客热。　\n　\n同五味子、枸杞、地黄、牛膝、鳖甲、酸枣仁、天冬，治五劳七伤。胃强者，可加当归。火盛者，可入黄檗、砂仁、甘草，三物俱递减。　\n　\n治阳明疟，大渴引饮烦躁，或呕吐。麦门冬、石膏、知母、竹叶，各数两，病人虚者加人参两许，痰多者加贝母、橘红各两许。　　\n\n《药性论》云：麦门冬止烦渴，主大水，面目肢节浮肿，下水，治肺痿吐脓，宜同天门冬、薏苡仁、黄檗、芍药、茯苓、石斛、桑根白皮、五味子、牛膝，煮饮弥佳。　\n　\n止泄精，宜兼覆盆、蒺藜、黄檗、五味子。　　\n\n同茯苓、车前、黄连、石斛、猪苓、泽泻，疗心腹结气，身重目黄。　　\n\n日华子治五劳七伤，安魂定魄，止渴，肥人时疾，热狂头痛，止嗽。故同石膏、知母、竹叶、粳米，专疗时气头痛，大渴烦躁，及发狂甚者。须各数两浓煎，顿饮乃佳。虚羸人因作劳内伤而发者，可量加人参，名人参白虎汤。有肺热者勿入人参。　　\n\n崔元亮《海上方》：同黄连治消渴。　　\n\n《衍义》治心肺虚热，虚劳客热．入沙参、五味子。　\n　\n同青蒿、鳖甲、牛膝、地黄、芍药、天门冬、枸杞子、五味子、胡黄连、山药、茯苓、山茱萸，蜜丸，治骨蒸劳热。　\n\n【简误】　　\n       麦门冬性寒，虽主脾胃，而虚寒泄泻及痘疮虚寒作泄，产后虚寒泄泻者，咸忌之。　', NULL, NULL, NULL, '麦门冬', NULL, '14、麦门冬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750089, '625E1C00D23A5C4BDB44DEDC59341CCA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7170, 412, 400105610, '     味苦、酸，平，无毒。主寒湿痿痹，四肢拘挛，膝痛不可屈伸，逐血气，伤热火烂，堕胎。疗伤中少气，男子阴消，老人失溺。补中续绝，填骨髓，除脑中痛及腰脊痛，妇人月水不通，血结，益精，利阴气，止发白，久服轻身耐老。（忌牛肉、牛乳。）　　\n\n       疏：牛膝，君、禀地中阳气以生，气则兼乎木火之化也，故其味苦酸平无毒。味厚气薄，走而能补。性善下行，故入肝肾。主寒湿痿痹，四肢拘挛，膝痛不可屈伸者，肝脾肾虚，则寒湿之邪客之而成痹，及病四肢拘挛，膝痛不可屈伸。此药既禀地中阳气所生，又兼木火之化，其性走而下行，其能逐寒湿而除痹也必矣。益补肝则筋舒，下行则理膝，行血则痛止。逐血气，犹云能通气滞血凝也。详药性，气当作痹。伤热火烂，血焦枯之病也。血行而活，痛自止矣。入肝行血，故堕胎。伤中少气，男子阴消，老人失溺者，皆肾不足之候也。脑为髓之海，脑不满则空而痛。腰乃肾之腑，脊通髓于脑，肾虚髓少，则腰脊痛。血虚而热则髪白，虚羸劳顿则伤绝。肝藏血，肾藏精，峻补肝肾，则血足而精满，诸证自瘳矣。血行则月水自通，血结自散。久服轻身耐老，悉如上说，不复具疏。　　\n\n【主治参与】　　\n君术、仙茅、木瓜、石斛、茯苓、石南叶、五加皮、萆薢、生地黄、黄耆、芍药、虎骨、沉香、桂，治诸痹。同甘菊花、石斛、木瓜、何首乌、生地黄、虎骨、沉水香、人参、术、黄耆、天门冬、麦门冬、杜仲、续断、芍药、橘皮、黄檗、桑寄生、白鲜皮，治一切痿痹，四肢拘挛，筋骨疼痛。　　\n\n君当归、地黄，能下死胎。加朴硝，立下胞衣。　　\n\n君木瓜、石斛、萆薢、生地黄、黄檗、五加皮、骨碎补、续断、金银花、白及、芍药、甘草、甘菊根、紫花地丁、茜草、连翘，治鹤膝风。　　\n\n根苗同用二三两浓煎，调鳖甲末三钱，空心服，治疟在阴分久不瘥者，三剂必已。胃虚者加人参两许，橘皮去白五钱。　　\n\n君青蒿、生地黄、麦门冬、甘枸杞子，熬膏，治妇人血虚发热，内热口干舌苦。　　\n\n治小便不利，茎中痛欲死，兼治妇人血结腹坚痛，鲜牛膝三四两，白酒煎浓，服之立愈。　\n　\n金疮作痛，生捣搏之立瘥。　　\n\n【简误】　　\n     误用伤胎，经闭未久、疑似有娠者有勿用。上焦药中勿入。血崩不止者忌之。　　                                                 ', NULL, NULL, NULL, '牛膝', NULL, '10、牛膝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750090, '0808B820D5AD7EE53074D42457B05607', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7171, 412, 400105613, '     味苦，平、微寒，无毒。主心腹，去肠胃中结气，饮食积聚，寒热邪气，推陈致新。除伤寒心下烦热，诸痰热结实，胸中邪逆，五藏间游气，大肠停积水胀，及湿痹拘挛。亦可作浴汤。久服轻身，明目益精。（半夏为之使。）　　\n\n疏：柴胡禀仲春之气以生，兼得地之辛味。春气生而升，故味苦平、微寒而无毒。为少阳经表药。主心腹肠胃中结气，饮食积聚，寒热邪气，推陈致新，除伤寒心下烦热者，足少阳胆也。胆为清净之府，无出无入，不可汗，不可吐，不可下，其经在半表半里，故法从和解，小柴胡汤之属是也。其性升而散，属阳，故能达表散邪也。邪结则心下烦热，邪散则烦热自解。阳气下陷则为饮食积聚，阳升则清气上行。脾胃之气行阳道，则饮食积聚自消散矣。诸痰热结实，胸中邪逆，五脏间游气者，少阳实热之邪所生病也。柴胡苦平而微寒，能除热散结而解表，故能愈以上诸病。大肠停积水胀，及湿痹拘挛者，柴胡为风药，风能胜湿故也。　　\n\n【主治参与】　　\n仲景小柴胡汤中，同人参、半夏、黄芩，治伤寒往来寒热，口苦，耳聋，胸胁痛，无汗。又治少阳经疟，往来寒热。亦治似疟非疟、大便不实，邪不在阳明者。　\n　\n在大柴胡汤，治伤寒表里俱急。　　\n\n伤寒百合证，有柴胡百合汤。　　\n\n东垣治元气劳伤，精神倦怠，用参、耆、白术、炙甘草、当归，佐以柴胡、升麻，引脾胃之气行阳道，名补中益气汤。本方去当归，加茯苓、猪苓、泽泻、干葛、神曲，名清暑益气汤。\n　　\n同四物汤去当归，加泽兰、益母草、青蒿，能治热入血室。　　\n\n同升麻、干葛等，能升阳散火。\n　　\n同生地黄、黄檗、黄连、甘草、甘菊、玄参、连翘、羌活、荆芥穗，治暴赤眼。　　\n\n【简误】　　\n       柴胡性升而发散，病人虚而气升者忌之。呕吐及阴虚火炽炎上者，法所同忌。疟非少阳经者，勿入。治疟必用柴胡，其说误甚！不可久服，亦无益精明目之理。尽信书则不如无书，此之谓也。按今柴胡，俗用有二种，色白黄而大者，为银柴胡，用以治劳热骨蒸；色微黑而细者，用以解表发散。本经并无二种之说，功用亦无分别，但云银州者为最，则知其优于升散，而非除虚热之药明矣。《衍义》所载甚详，故并录之。　\n　\n附：《衍义》曰：柴胡，《本经》并无一字治劳。今人方中鲜有不用者。呜呼！凡此误世甚多。尝原病劳，有一种真藏虚损，复受邪热，邪因虚而致劳。故曰劳者、牢也。当须斟酌用之。\n\n如《经验方》中治劳热青蒿煎之用柴胡，正合宜耳。服之无不效，热去即须急已。若无表热，得此愈甚。虽至死，人亦不悟。目击甚多，可不戒哉！可不慎哉！日华子又谓补五劳七伤。\n\n《药性论》亦谓治劳乏羸瘦。若此等病，苟无实热，医者执而用之，不死何待？注释本草，一字亦不可忽。万世之后，所误无穷耳。', NULL, NULL, NULL, '柴胡,茈胡', NULL, '13、柴胡,茈胡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750091, '31EF97EB3FBFACB22A87B37280A1589E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7172, 412, 400105612, '     味甘，平，无毒。主中风暴热，不能动摇，跌筋结肉，诸不足，心腹结气，虚热，湿毒，腰痛，茎中寒，及目痛眦烂泪出。久服去面黑䵟，好颜色，润泽，轻身不老。　　\n\n      疏：萎蕤禀天地清和之气，而得稼穑之甘，故《本经》甘平无毒，主诸不足。久服好颜色，润泽，轻身不老。\n\n   《别录》又主心腹结气，虚热，腰痛，茎中寒，目痛眦烂泪出。甄权主内补不足，去虚劳客热，头痛不安，加而用之良。日华子谓其除烦闷，止渴，润心肺，补五劳七伤虚损，腰脚疼痛。详味诸家所主，则知其性本醇良，气味和缓，譬诸盛德之人，无往不利，终始一节，故可长资其利，用而不穷。正如斯药之能补益五藏，滋养气血。根本既治，余疾自除。夫血为阴，而主驻颜；气为阳，而主轻身。阴精不足则发虚热，肾气不固则见骨痿及腰脚痛。虚而火炎则头痛不安，目痛眦烂泪出。虚而热壅则烦闷消渴。上盛下虚则茎中寒，甚则五劳七伤，精髓日枯，而成虚损之证矣。以一药而所主多途，为效良伙，非由滋益阴精，增长阳气，其能若是乎？迹其所长，殆亦黄精之类欤？其主中风暴热，不能动摇，跌筋结肉，湿毒等证，皆是女萎之用。以《本经》二物混同一条故耳。或谓即青粘，理或有之。纯而不驳，和而不偏，有益无损，故无“简误”。昔彭城樊阿，少师事华佗，佗授以漆叶青粘散，服之利五藏，去虫，轻身益气，年至五百余岁。青粘，生丰沛彭城及朝歌，一名地节，一名黄芝，主理五藏，益精气。本出于迷人入山，见仙人服之，以告佗，佗以为佳。语阿，阿秘之。人见阿之寿而气力强盛，问之，因醉误说，人服多验。后无复有人识青粘者。或云即黄精之正叶者。又云即萎蕤。　　\n同黄精、桑椹、何首乌，能驻颜。　　', NULL, NULL, NULL, '萎蕤,地节,黄芝', NULL, '12、萎蕤,地节,黄芝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750092, '897DA95FEF716178BC8C97686977F119', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2025-01-14 11:26:39');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7173, 412, 400105611, '     味辛、甘，微温、微寒，无毒。主明目益精，除水气，疗血逆，大热头痛心烦。久服轻身。　　\n茎：主瘾疹痒，可作浴汤。一名益母草。（忌铁。）　\n　\n      疏：茺蔚子禀地中之阳气以生，兼感乎上天春夏之气而成，亦阳草也。味辛甘，微温微寒无毒，入手足厥阴经。为妇人胎产调经之要药。此药补而能行，辛散而兼润者也。目者，肝之窍也。益肝行血，故明目益精。其气纯阳，辛走而不守，故除水气。肝脏有火则血逆，肝凉则降而顺矣。大热头痛心烦，皆血虚而热之候也。清肝散热和血，则头疼心烦俱解。微温微寒说，见人参条内。　\n　\n【主治参与】　　\n午月五日采紫花益母草，捣汁，分贮瓷器内各少许，晒干，剔取，和蜂蜜封固，加人参、琥珀、乳香、没药、血竭、沉香、丹砂、五灵脂，催生及胞衣不下，神效。兼产后血晕，瘀血薄心，恶露不行腹痛，少腹儿枕痛，调经治血闭经阻，经行作痛。　\n　\n单用和童便服，能下死胎，及治热入血室，发热烦躁类伤寒。　\n　\n君四物汤、杜仲、阿胶、真川续断，为丸，安胎止痛。　\n　\n得生地黄、白芍药、麦门冬、枇杷叶、青蒿子、五味子、阿胶，治血热经行先期，及胎漏下血。同生甘菊、苍耳草、金银花、紫花地丁各一握，贝母、鼠粘子、白芷、僵蚕、白及、白剑、生甘草、连翘、生地黄各三钱，熬夏枯草汁，和药同煎浓，顿饮之，消一切疔肿发背及无名肿毒。　　\n\n【简误】　　\n       益母草，辛甘为阳，故性善行走，能行血通经，血崩禁用。瞳子散大禁用。惟热血欲贯瞳人者，与凉血药同用则不忌。　　', NULL, NULL, NULL, '益母草,茺蔚子,充蔚子', NULL, '11、益母草,茺蔚子,充蔚子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750093, 'E0CF3675C855A3F4DB25C193C8C7BC50', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2025-01-14 11:24:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7174, 412, 400105609, '     味辛、甘，平，无毒。主续绝伤，补不足，益气力，肥健。汁去面䵟，养肌，强阴，坚筋骨。主茎中寒，精自出，溺有余沥，口苦燥渴，寒血为积。久服明目，轻身延年。（得酒良，宜丸不宜煮）\n　　\n        疏：菟丝子，君，禀春末夏初之气以生，凝乎地之冲气以成，感秋之气而实。故《本经》言其味辛平，《别录》益之以甘者，正雷公所谓禀中和、凝正阳之气而结者也，其为无毒明矣。五味之中，惟辛通四气，复兼四味，《经》曰：肾苦燥，急食辛以润之，菟丝子之属是也。与辛香燥热之辛，迥乎不同矣。学者不以辞害义可也。为补脾肾肝三经要药。主续绝伤，补不足，益气力，肥健者，三经俱实则绝伤续而不足补矣。脾统血，合肌肉而主四肢。足阳明、太阴之气盛，则力长而肥健。补脾故养肌，益肝肾故强阴、坚筋骨。暖而能补肾中阳气，故主茎中寒，精自出，溺有余沥。口苦燥渴者，脾肾虚而生内热，津液因之不足也，二脏得补则二病自愈。寒血为积者，劳伤则血瘀，阳气乏绝则内寒。血随气行，气弱不能统血以行，久而为积矣。凡劳伤皆脾肾肝三脏主之，肝脾气旺则瘀血自行也。久服明目轻身延年者，目得血而能视，肝开窍于目，瞳子神光属肾，肝肾实则目自明，藏实精满则身自轻，延年可必矣。　　\n\n【主治参与】　　\n君莲实、山药、人参，能实脾、止泄、嗜食。加五味子、肉豆蔻、砂仁，能治肾泄。　　\n\n同五味子、沙苑蒺藜、覆盆子、莲须、山茱萸、巴戟天、车前子、没食子、枸杞子，能益脾肾，固精种子。　\n　\n同甘菊花、沙苑蒺藜、甘枸杞子、熟地黄、羚羊角、谷精草、决明子，能明目。　　\n\n君术、人参、牛膝、胡麻仁，治丈夫腰膝积冷痛，或顽麻无力。　　\n\n单服偏补人卫气，能助人筋脉。　　\n\n王好古云：能补肝脏虚，故去风，专主腰膝。腰膝者，肝肾之所治也。　\n　\n苗：生研涂面斑，神效。　　\n\n【简误】　　\n     肾家多火，强阳不痿者，忌之。大便燥结者，亦忌之。　', NULL, NULL, NULL, '菟丝子', NULL, '9、菟丝子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750094, 'DE6B2708B33D75EAF577DC0146E3D0A6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7175, 412, 400105608, '      味苦、甘，温，无毒。主风寒湿痹，死肌，痉，疸，止汗、除热、消食。主大风在身面，风眩头痛，目泪出，消痰水，逐皮间风水结肿，除心下急满，及霍乱吐下不止，利腰脐间血，益津液，暖胃，消谷嗜食。作煎饵久服，轻身延年不饥。（茅山者为胜，忌蛤、雀、桃、李、菘菜、青鱼）　　\n\n       疏：术禀初夏之气以生，其味苦，其气温，从火化也。正得土之冲气，故《别录》益之以甘，表土德也，故无毒。其气芳烈，其味甘浓，其性纯阳，为除风痹之上药，安脾胃之神品。《本经》主风寒湿痹，死肌痉疸者，正以风寒湿三者合而成痹。痹者，拘挛而痛者是也。《经》曰：地之湿气，感则害人皮肉筋骨。死肌者，湿毒侵肌肉也。痉者，风寒秉虚，客于肝脾肾所致也。疸者，脾胃虚而湿热瘀滞也。如上诸病，莫不由风寒湿而成。术有除此三邪之功，故能祛其所致之疾也。止汗、除热、消食者，湿热盛则自汗，湿邪客则发热。湿去而脾胃燥，燥则食自消，汗自止，热自除也。又主大风在身面者，术气芳烈而悍，纯阳之物也。风为阳邪，发于阳部，故主之也。风眩头痛、目泪出者，阳虚则风客之而眩，痰厥则头痛，风热壅则目泪出也。消痰水，逐皮间风水结肿，除心下急痛，及霍乱吐下不止者，湿客于胃则滞而生痰，客于脾则生水。脾虚湿胜则为水肿，湿客中焦则心下急满，脾胃俱虚则中焦不治，而湿邪客之则为霍乱吐下不止也。利腰脐间血者，血属阴，湿为阴邪，下流客之，使腰脐血滞而不得通利。湿去则诸证无不愈矣。益津液、暖胃、消谷嗜食者，湿去则胃强而津液自生，寒湿散则胃自暖，邪去而脾胃健，则消谷而嗜食矣。煎饵久服，轻身延年不饥者，术为阳药，故善除阴湿，湿去则脾胃之气旺。阳主气，气盛则身轻。脾主四肢，湿去则脾健，健则四肢利，故能涉险负重也。仙经云“气满不思食”，是以延年而不饥也。　　\n\n【主治参与】　　\n术为阳草，气胜黄精。除湿祛寒，疏风辟恶，其功能也。单饵则延年，轻身不饥。兼济则观所从何道。故同人参、茯苓、白芍药、甘草、橘皮、莲肉、缩砂，则健脾开胃，消饮食，为壮脾胃之要剂，调中之正法。\n　　\n同藿香、橘皮、茯苓、人参、木瓜、猪苓、泽泻，缩砂，则治霍乱吐泻转筋。　\n　\n同干葛、防风、茯苓、炙甘草、车前子、猪苓、泽泻，则治湿胜作泄，势若雷奔。　　\n\n同秦艽、萆薢、木瓜、薏苡仁、桑寄生、石斛、黄耆、地黄、石菖蒲、桂枝、甘草、晚蚕砂，则治一切痛痹及关节不利。热者去桂枝、加黄檗。　\n　\n得黄檗、牛膝、木瓜、石斛，能健步潜行。　　\n\n得苦参、牡蛎，治小儿胃家湿热，饮食不生肌肉。　　\n\n君人参、芍药、木瓜、薏苡、茯苓、桑白皮、赤小豆、车前、橘皮，佐以猪苓、泽泻，能治一切水肿。日重则倍人参，夜重则加地黄、芍药，俱与术倍。　\n　\n君枳实、橘皮、砂仁、半夏、人参，则除心腹胀痛，消宿食，开胃，去痰涎，除伤食发寒热及泄泻。　\n　\n同人参、橘红、白茯苓、木瓜、藿香，治反胃吐逆，因于寒则加生姜，因于热则加竹茹、枇杷叶、逆水芦根。　\n　\n君黄耆、生地黄，佐以黄檗，治一切臁疮，湿毒攻注，足胫成疮久不愈，作丸饵良。　　\n\n倍茯苓，修事如《经验方》，能乌须驻颜。　　\n\n同麦门冬、石斛、黄檗、白芍药、木瓜、薏苡仁、五味子，为治痿要药。\n　　\n同生姜、藿香、槟榔，能治山岚瘴气。　　\n\n同四物汤、麦门冬、荆芥、防风、地榆，能治肠风下血。　\n　\n同雄羊肝，治雀盲。　　\n\n同补骨脂、川椒、茴香、青盐、川楝子、黄檗，治疝。　　\n\n同熟地、桑椹，修事采日精月华，干则蜜丸，日三服，可变白。\n　　\n为末，和芝麻研烂，入水搅匀，绞汁滤净，曝干，每三钱，空心酒服，能滋脾肾。\n　　\n【简误】　　\n           术，《本经》无分别，陶弘景有赤白二种。近世乃有苍、白之分，其用较殊。要之俱为阳草，故祛邪之功胜，而益阴之效亏。药性偏长，物无兼力，此天地生物自然之道也。凡病属阴虚血少，精不足，内热骨蒸，口干唇燥，咳嗽吐痰，吐血，鼻衄，齿衄，咽塞，便秘，滞下者，法咸忌之。术燥肾而闭气，肝肾有动气者勿服。刘涓子《痈疽论》云：溃疡忌白术。以其燥肾而闭气，故反生脓作痛也。凡脏皆属阴，世人但知术能健脾，此盖指脾为正邪所干，术能燥湿，湿去则脾健，故曰补也。宁知脾虚而无湿邪者用之，反致燥竭脾家津液，是损脾阴也，何补之足云？此最易误，故特表而出之。', NULL, NULL, NULL, '白术,术', NULL, '8、白术,术', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750095, 'FD204663B8C98B00F59E486A198DD532', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2025-01-14 11:19:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7176, 412, 400105607, '     味甘、苦，寒，无毒。主折跌绝筋，伤中，逐血痹，填骨髓，长肌肉。作汤除寒热积聚，除痹。主男子五劳七伤，女子伤中，胞漏下血，破恶血，溺血，利大小肠，去胃中宿食，饱力断绝，补五藏内伤不足，通血脉，益气力，利耳目。生者尤良。　　\n生地黄　大寒。主妇人崩中血不止，及产后血上薄心闷绝，伤身胎动下血，胎不落，堕坠踠折，瘀血留血，鼻衄吐血，皆捣饮之。久服轻身不老。（采得即用者为生，晒干收者为干，以法制过者为熟。）　　\n\n       疏：干地黄禀仲冬之气以生。黄者，土之正色，兼禀地之和气，故味甘气寒而无毒。《别录》又云苦者，以其兼入心脾也。此乃补肾家之要药，益阴血之上品。《本经》主折跌绝筋伤中，逐血痹者，肝藏血而主筋，补肝则荣血调，荣血调则伤中自去。痹者血分之病，因虚而风寒湿邪客之，故筋拘挛而痛。养血和肝，痹必廖矣。作汤除寒热积聚、除痹者，血和则结散，故诸证自除也。其曰填骨髓，长肌肉，主男子五劳七伤者，地黄为至阴之药，正补肾水真阴而益血，血旺则髓满，阴足则肌肉自长。五劳七伤皆阴虚内热，真阴不足之候。甘寒能除内热而益精髓，故劳伤自除也。女子伤中、胞漏下血者，阴虚则火炽而血热，火能销物，造化自然之道也。凉血益血则胞漏自止矣。下血者，血热也，凉血则下血自愈。荣血滞则为恶血，生地黄能行血，故破恶血。溺血者，肾与小肠热也，益阴凉血则溺血自止，二便自利矣。胃为足阳明，胃家湿热盛则食不消，生地黄能泻脾胃中湿热，湿热去而脾胃安，则宿食自去。饱而努力，则肠胃筋脉有绝伤之患。形属血，故行血益血则诸伤自理矣。五脏咸属阴，阴即精血，补精血则五脏内伤不足自愈矣。通血脉，益气力，利耳目者，皆脏安之验也。又主妇人崩中血不止，及产后血上薄心闷绝，伤身胎动下血，胎不落，堕坠踠折，瘀血留血，衄血吐血，生者捣汁饮之，皆凉血行血之功也。久服轻身不老，则益阴填髓补五脏之能事毕矣。又按日华子云：助心胆气，强筋骨，长志，安魂定魄，除惊悸者，胆为五脏六腑之首，行春升之气，故十一脏皆取决于胆，为中正之官。地黄入手足少阴，亦入足厥阴。心与肝为子母之脏。胆为肝之腑，肝主筋，肾主骨。肾藏精与志，肝藏魂，肺藏魄，心胆二经虚则病惊悸。生地黄为手少阴之要药，能凉心助胆补肝，心凉则热不薄肺，肝肺清宁则魂魄自定，胆气壮则惊自除，肝肾足则筋骨自强，心肾交济则志自长矣。\n　　\n【主治参与】　　\n生地黄同大小蓟各半，俱捣取自然汁，和童便饮，治一切血热妄行，吐血，齿、鼻衄，神效。　　\n\n取汁和面作䬪饦冷淘，治虫心痛。　　\n\n同苎麻根捣汁碗许，加炒砂仁末三钱，治胎动下血。　　\n\n同麦门冬，治产后烦闷。　　\n\n同当归、赤芍药、乳香、没药、肉桂、炒黄荆子末，治一切跌打折伤，瘀血作痛。　　\n\n同金银花、甘草、荆芥穗、玄参、连翘、黄檗、地榆、白芷、木通，治血分湿热生脓疮痛甚者，浓煎恣饮，立差。　　\n\n入琼玉膏，为阴阳两补之要剂。　　\n\n干地黄同沙苑蒺藜、肉苁蓉、鹿茸、山茱萸、五味子，能益男子精。　\n　\n同人参、枸杞、五味子、麦门冬、鹿茸、车前子、覆盆子、菟丝子，多服令人有子。　　\n\n得青蒿子、鳖甲、银柴胡、沙参、天麦二冬、黄檗、甘草、地骨皮、牡丹皮、白芍药、牛膝，能治骨蒸劳热。　　\n\n同人参、远志、麦门冬、酸枣仁、柏子仁、茯神、甘草，治心虚惊悸怔忡健忘。\n　　\n同黄耆、黄连、黄檗、酸枣仁、五味子、白芍药、麦门冬、龙眼肉、牡蛎粉，治盗汗久不止。　\n　\n得麦门冬、五味子、牛膝、枸杞子、车前子、阿胶、天门冬，治溺血。　\n　\n同人参、麦门冬、五味子、牛膝，渍酒，能益气力，逐及奔马。　　\n\n同当归、白芍药、川芎、阿胶、鹿角胶，能益母安胎。　　\n\n同砂仁，治胎动下血腰痛。　　\n\n同青蒿、地骨皮、麦门冬、白芍药、山茱萸、枇杷叶，治妇人月事先期。　　\n\n同生姜，治产后中风。　　\n\n同当归、川芎、蒲黄、黑豆炒、炮姜、泽兰、益母、牛膝、续断、杜仲、鹿角胶，治一切产后血虚发热。\n　　\n得肉桂及乳香、没药、五灵脂，治儿枕痛。夏月去桂。　　\n\n同芍药、当归、川芎、阿胶、蕲艾、香附，治经事不调。　　\n\n同甘菊花、女贞实、枸杞子、白蒺藜，能明目益精。　　\n\n同黄连、连翘、薄荷、甘草、甘菊花、木通，治目暴赤痛。　\n　\n同鹿茸、五味子、人参、人乳粉、白茯苓，能生齿。　　\n\n同何首乌、桑椹、甘菊、鳢肠、蜀椒，能乌须发。　\n　\n【简误】　　\n         生地黄，性大寒，凡产后恶食作泻，虽见发热、恶露作痛，不可误用。误用则泄不止。胃气者，后天元气之本也。胃困则饮食不运，精血不生，虚热何自而退？故并当归忌之。凡见此证，宜多加炮姜、桂心、人参，必自愈。凡阴虚咳嗽，内热骨蒸，或吐血等候，一见脾胃薄弱，大便不实，或天明肾泄，产后泄泻，产后不食，俱禁用生地黄、当归。误则同于前辙。慎之！凡胸膈多痰，气道不利，升降窒塞，药宜通而不宜滞，汤液中禁入地黄。　', NULL, NULL, NULL, '地黄,干地黄', NULL, '7、地黄,干地黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750096, '0B33DE16B3143016E7E734B4ACE0F687', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2025-01-03 15:42:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7177, 412, 400105606, '       味甘，平，无毒。主五藏六腑寒热邪气，坚筋骨，长肌肉，倍力，金疮，尰，解毒，温中下气，烦满短气，伤藏咳嗽，止渴，通经脉，利气血，解百药毒。为九土之精，安和七十二种石，一千二百种草。久服轻身延年。二月、八月除日采根，暴干，十日成。（术、苦参为使，反大戟、芫花、甘遂、海藻，恶远志，忌猪肉，令人阴痿。）　\n　\n        疏：甘草味甘，气平无毒，正禀土中冲和之阳气以生。故《别录》称之为九土之精。可升可降，阴中阳也。主五脏六腑寒热邪气、坚筋骨者，以其得土中冲阳之气。味甘平，性和缓，故能解一切毒气，安脏腑，除邪热也。五脏之寒热邪气既解，则脏气和而真气生，气日以盛，故筋骨坚。长肌肉、倍力者，甘能益脾，脾主肌肉，兼主四肢，脾强则四肢生力，故长肌肉、倍力也。主金疮尰者，甘入血分而能缓中，且伤则热，热而后尰。甘温益血而除热，烦热解，故尰散也。温中下气者，甘味属土，土位乎中，故温中。甘能缓中散结，故下气。烦满短气者，是劳伤内乏，阳气不足，故虚而烦满短气。甘温能益血，除大热，助气，故烦满短气并除也。甘平且和，和能理伤，故治伤脏。肺苦气上逆，嗽乃肺病，甘以缓之，故治咳嗽。血不足则内热，内热则津液衰少而作渴，甘能入脾益血，故止渴。血虚则经脉不通，能益血则经脉自通矣。甘能益血而温气分，故利血气。其解一切金石草木虫鱼禽兽之毒者，凡毒遇土则化，甘草为九土之精，故能解诸毒也。久服轻身延年者，为其益血、安和五脏也。　　\n\n【主治参与】　　\n诸毒遇土则化，甘草为土精，故能化毒，解一切邪气。佐黄耆、防风，能运毒走表，为痘疹气血两虚者，首尾必资之剂。　　\n\n得白芍药则补脾，甲己化土故也。　　\n\n同人参、黄耆、白术、大枣、当归身、麦门冬，加升麻、柴胡，为补中益气药，专理饥饱劳役内伤，阳气下陷发热。\n　　\n同人参、干姜、肉桂，则温中。　　\n\n同麦门冬、苏子、枇杷叶，则下气。　　\n\n同黄连、芍药、升麻、滑石，解热毒滞下。　\n　\n同桔梗、玄参、鼠粘子、栝楼根，清利咽喉虚热。\n　　\n同人参、菖蒲、益智、龙眼肉、远志，治健忘。　\n　\n同麦门冬、石膏、竹叶、知母，除烦闷躁渴头痛，解饥。　\n　\n同紫花地丁、金银花、甘菊、夏枯草、贝母、白及、白芷，消一切疔肿。　　\n\n同川黄连，止小儿胎毒惊痫。　　\n\n同黄连、木通、赤芍药、生地黄，泻心经有余之火。　　\n\n同预知子、贯众，解一切蛊毒。　　\n\n单用水炙百遍，煎熬斤许，治悬痈如神。　\n　\n炙则补伤寒病瘥后血虚。　　\n\n【简误】　　\n       甘能缓中，故中满者忌之。呕家忌甘，酒家亦忌甘。诸湿肿满，及胀满病，咸不宜服。　', NULL, NULL, NULL, '甘草', NULL, '6、甘草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750097, 'EC13E955145A6663E6935765CB356F49', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7178, 412, 400105605, '       味苦、甘，平、大寒，无毒。主诸暴风湿偏痹，强骨髓，杀三虫，去伏尸，保定肺气，去寒热，养肌肤，益气力，利小便，冷而能补。久服轻身益气，延年不饥。（忌鲤鱼）　　\n\n疏：天门冬正禀大寒初之气以生，得地之阴精独厚。味虽微苦甘而带辛，其气大寒，其性无毒。要以甘多者为胜。味厚于气，阴也降也，除肺肾虚热之要药也。其主诸暴风湿偏痹，杀三虫，去伏尸，保定肺气，去寒热者，盖以热则生风，暴则属火。其言湿者，乃湿热之谓。苦以泄湿，寒以除热。热去则风止，湿泄则痹瘳。偏痹者，湿热所致也。强骨髓者，肾为作强之官而主骨，湿热不去，下流客肾，能使人骨痿。肾欲坚，急食苦以坚之，天门冬、黄檗之属是已。且肾者水脏也，平则温而坚，虚则热而软。味苦气寒，正入肾而除热坚软，故强骨也。三虫伏尸，必生于脾肾俱虚、内热气弱之人。若能杀虫，辛能散结，故杀三虫而除伏尸也。肺为华盖之脏，喜清肃而恶烦热，亦畏湿热。平则安和，发声清亮。一受火热，则为贼邪所干，而痰壅咳逆、气喘吐血、寒热声哑之证出焉。热泄则痰散而肝清，肺清则津液流通，气得下降，而诸证自止矣。养肌肤，益气力，利小便者，肺主皮毛，脾气散精，上归于肺，通调水道，下输膀胱。又肺为水之上源，朝百脉而主气，热邪退则肺得所养，故能养肌肤，益气力，利小便也。冷而能补者，热盛则肺肾俱虚，除虚热即补肺肾也。久服轻身益气、延年不饥者，热退则水足，水足则精固，精固则肾气益实。肾为先天真气之源，肾实骨强，延龄可知已。要之道书所录，皆指遗世独立、辟谷服饵之流者设，非谓恒人亦可望此也。　　\n\n【主治参与】　　\n痰之标在脾胃与肺，其本在肾。若非肾家有火，炎上薄肺，煎熬津液而成黏腻，则痰何自而生耶？天门冬味苦气大寒，能清热保肺，下通于肾，故同麦门冬、百部、桑白皮、枇杷叶、玄参、贝母、童便、竹沥，为清肺消痰止嗽必用之药。　　\n\n同地黄、麦门冬、五味子、黄檗、车前子、枸杞、牛膝为丸，补阴除热，滋肾家燥。脾胃弱者加山药、白茯苓、砂仁以佐之。　　\n\n同麦门冬、五味子熬膏，入炼蜜，益肺甚妙。亦治消渴。　　\n\n同甘菊花酿酒，除一切风，能愈大风病。水煮则除风热，兼除烦闷。　　\n\n同生地黄、麦门冬、白芍药、鳖甲、牛膝、杜仲、续断、童便，治吐血。\n　　\n同干膝、百部、鳖甲、青黛、獭肝、象胆，杀三虫而除劳瘵。　　\n\n同薏苡仁、桑黄、白及、紫菀、百部、百合，能除肺痿、吐脓血。　\n　\n同青蒿、鳖甲、麦门冬、银柴胡、牛膝、白芍药、地骨皮、五味子，能治妇人骨蒸。　　\n\n同麻子仁，麦门冬、生地黄、童便，能除大肠热燥。胃强者，略加桃仁。　　\n\n同熟地黄、胡麻仁，和蜜久服，驻颜不饥。　　\n\n【简误】　　\n          天门冬，味苦平、辛，其气大寒。若因阴虚水涸，火起下焦，上炎于肺，发为痰喘者，诚哉要药也。然大寒而苦，不利脾胃阴虚之人。脾胃多弱，又以苦寒损其胃气，以致泄泻恶食，则危殆矣。何者？后天元气，生于胃气。五脏之气，皆因之以为盛衰者也。强则喜食而甘味，弱则恶食而不甘味。阴虚精绝之病，正赖脾胃之气强，能纳能消，以滋精气。若脾胃先困，则是后天生气之源绝矣。丸饵虽佳，总统于食。汤液虽妙，终属于饮。若非胃气无损，焉能纳而消之，以各归其根，奏平定之功哉？必不得已，当以薏苡仁、白茯苓、山药、甘草、白芍药同用。或用麦门冬以代之可也。误用之必泄。　　', NULL, NULL, NULL, '天门冬', NULL, '5、天门冬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750098, 'CAD962AAE5344C6605C7697A38FB1424', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7179, 412, 400105604, '      味甘，微寒、微温，无毒。主补五藏，安精神，定魂魄，止惊悸，除邪气，明目，开心益智，疗肠胃中冷，心腹鼓痛，胸胁逆满，霍乱吐逆，调中，止消渴，通血脉，破坚积，令人不忘。久服轻身延年。（茯苓为之使。）\n\n疏：人参得土中清阳之气，禀春升少阳之令而生，故味甘微寒而无毒，气味均齐，不厚不薄，升多于降。洁古谓其气味俱薄，浮而升，阳中之阳也。又曰阳中微阴，盖亦指其生长真元之气而言欤。神农微寒，《别录》微温，二义相蒙，世鲜解者。盖微寒者，春之寒也；微温者，亦春之温也。神农直指所禀，故曰微寒。\n\n    《别录》兼言功用，故又曰微温。既云微矣，寒不甚寒，则近于温；温不甚温，则近于寒，故知寒温虽别，言微则一也。以言乎天，则得其生生升发之气；以言乎地，则得其清阳至和之精。状类人形，上应瑶光，故能回阳气于垂绝，却虚邪于俄顷，功魁群草，力等丸丹矣。其主治也，则补五脏。盖脏虽有五，以言乎生气之流通则一也，益真气则五脏皆补矣。其曰安精神，定魂魄，止惊悸，开心益智者，以心藏神，肝藏魂，肺藏魄，肾藏精与志，脾藏意与智故也。心肾虚则精神不安矣，肝肺虚则魂魄不定矣。惊悸者，心脾二经之病也。心脾虚则惊悸，心脾之气强则心窍通利，能思而智益深矣。邪气之所以久留而不去者无他，真气虚则不能敌，故留连而不解也。兹得补而真元充实，则邪自不能容。譬诸君子当阳，则小人自退。清阳之气下陷，则耳目不聪明。兼之目得血能视，阳生则阴长，故明目。真气内虚，故肠胃中冷，气旺阳回则不冷矣。心腹鼓痛者，心脾虚故也。二脏得补，其痛自止，所谓按之快然者是也。故经曰：可按者虚也，不可按者实也。不可按者勿用。胸胁逆满者，气不归元也，得补则气实而归元矣，脾胃俱虚则物停滞而邪客之，故霍乱吐逆也。补助脾胃之元气，则二证自除。调中者，脾治中焦。脾得补则中自调矣。消渴者，津液不足之候也，气回则津液生，津液生则渴自止矣。通血脉者，血不自行，气壮则行，故通血脉。破坚积者，真气不足，则不能健行而磨物，日积月累，遂成坚积。譬夫磨管纳物，无力则不转，不转则停积矣。脾主消化，真阳之气回，则脾强而能消，何坚积之不磨哉？令人不忘者，心主记，脾主思，心脾二脏之精气满，则能虑而不忘矣。久服轻身延年者，纯阳则充举，气积则身轻。五脏皆实，延年可知矣。斯皆敦本之论也。\n\n【主治参与】\n人参，补五脏阳气之君药，开胃气之神品。\n\n同大枣、白芍药、龙眼肉、甘草、酸枣仁，补脾阴。\n\n肾气衰阳痿，以之为君，加鹿茸、肉苁蓉、巴戟天、五味子、麦门冬、菟丝子、山茱萸、地黄、枸杞、杜仲、柏子仁，乃扶衰之要剂，兼令人有子。\n\n君藿香、木瓜、橘红，治胃虚弱呕吐反胃。如妊娠呕吐，加竹茹、枇杷叶。\n\n同白术、吴茱萸，治脾泄久不止。\n\n君五味子、吴茱萸、补骨脂、肉豆蔻，治肾泄。\n\n同白芍药、炙甘草，治血虚腹痛鼓痛。\n\n同干姜、白术、炙甘草，治中寒泄泻，下利清谷，甚则加肉桂、附子。\n\n同附子、干姜、肉桂，治寒厥指爪青黯，便清蜷卧。\n\n同附子、五味子，治阳气脱，温肠胃中冷。\n\n君五味子、麦门冬，治肺虚气喘。夏月服之，益气除热止消渴，名生脉散。\n\n加白术，又治中暑伤气倦怠。\n\n同沉水香、白芍药，治真气虚，气不归元，因而胸胁逆满。\n\n同茯苓、远志、益智、枣仁、麦门冬，治精神恍惚，魂魄不定惊悸。\n\n同沉水香、茯神，治心虚邪客作痛。\n\n同鹿角胶、杜仲、续断、当归、地黄、苏木，治负重努力、内伤失血。去苏木，加生地黄，治胎漏不安。\n\n同黄耆、白芍药、五味子，治汗多亡阳。\n\n同苏木、麦门冬，治产后气喘。\n\n在白虎汤，治劳伤元气人患热病，渴甚并头疼。\n\n在败毒散，治气虚人患四时不正伤寒。\n\n在参苏饮，治肺虚人伤风。\n\n同鳖甲、青皮、干漆、䗪虫、肉桂、牡蛎、射干，消疟母。\n\n同甘菊花、当归、地黄、枸杞子、蒺藜、甘草、柴胡，则明目。\n\n同黄连、红曲、白芍药、滑石末、升麻，治滞下腹痛赤色。\n\n同黄连、乌梅、莲肉、升麻、滑石末、肉豆蔻，治滞下久不止。\n\n同白术、木瓜、茯苓、藿香、炙甘草，止虚烦躁。\n\n同牛黄、犀角、天竺黄、钩藤钩、丹砂、雄黄、真珠、茯神、远志，治惊痫。\n\n同地黄、阿胶、麦门冬、山茱萸、五味子、续断、杜仲，治血崩。加牛膝、大蓟、鹿角胶，治血淋。\n\n同橘皮、紫苏、木瓜、白术、竹茹，治恶阻安胎。热多者去术、紫苏，加麦门冬。\n\n同五加皮、白鲜皮、石南叶、石斛、秦艽、木瓜、薏苡仁、萆薢、牛膝、沉香、菖蒲、二术，治痹。\n\n同黄檗、黄耆、白术、五味子、麦门冬、木瓜、白芍药、薏苡仁、茯苓，治痿。\n\n同附子、白术、芍药、甘草、茯苓，治慢惊慢脾风。\n\n同白术、黄耆、芍药，治自汗。\n\n同生姜皮各两许，水煎，露一宿，五更温服，治气虚久疟不止。\n\n同苏木、当归、童便，治产后血晕。\n\n同石菖蒲、莲肉等分水煎，治产后不语。\n\n同乳香、丹砂、鸡子白，姜汁三匙调匀，别用当归两许煎浓，同吞，治横生倒养难产，神效。\n\n同附子、肉桂、麦门冬、五味子，治房劳过度，脱阳欲绝，下部虚冷。\n\n同黄耆、天门冬、五味子、牛膝、枸杞子、菖蒲，治中风不语。\n\n【简误】\n       人参，论其功能之广，俱如《本经》所说，信非虚语。第其性亦有所不宜。世之录其长处，或遗其短；摘其瑕者，并弃其瑜。是以或当用而后时，或非宜而妄设。不蒙其利，徒见其害。二者之误，其失则一。遂使良药不见信于世，粗工互腾其口说，惜哉！岂知人参本补五脏真阳之气者也。若夫虚羸尪怯，劳役饥饱所伤，努力失血，以致阳气短乏，陷入阴分，发热倦怠，四肢无力，或中热伤暑，暑伤气，无气以动；或呕吐泄泻，霍乱转筋，胃弱不能食，脾虚不磨食；或真阳衰少，肾气乏绝，阳道不举，完谷不化，下利清水，中风失音，产后气喘，小儿慢惊，吐泻不止，痘后气虚，溃疡长肉等证，投之靡不立效。惟不利于肺家有热咳嗽，吐痰吐血，衄血齿衄，内热骨蒸，劳瘵阴虚火动之候。盖肺者，华盖之脏也。位乎上，象天属金。喜清肃而恶烦热，真气无亏则宁谧清净，以受生气之熏蒸而朝百脉。苟纵恣情欲，亏损真阴，火空则发，热起于下，炎烁乎上，则肺先受之。火乃肺之贼邪，邪气胜则实，实则肺热郁结为痰，喉痒而发嗽，血热妄行，溢出上窍。王好古所谓 “肺热还伤肺” 是已。又有痧疹初发，身虽热而癍点未形；伤寒始作，形证未定而邪热方炽。若误投之，鲜克免者。斯皆实实之害，非药可解。《经》曰：实实虚虚，损不足而益有余。如是者，医杀之耳。可不戒哉！可不慎哉！', NULL, NULL, NULL, '人参', NULL, '4、人参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750099, '3C07A12B625DBF1FA92C23A2AD3FCBD2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7180, 412, 400105603, '       味苦、甘，平，无毒。主风头眩、肿痛，目欲脱，泪出，皮肤死肌，恶风湿痹，疗腰痛去来陶陶，除胸中烦热，安肠胃，利五脉，调四肢。久服利血气，轻身耐老延年。\n\n        疏：菊花发生于春，长养于夏，秀英于秋，而资味乎土。历三时之气，得天地之精，独禀金精，专制风木，故为祛风之要药。苦可泄热，甘能益血。甘可解毒，平则兼辛，故亦散结。苦入心、小肠，甘入脾胃，平辛走肝胆，兼入肺与大肠。其主风头眩肿痛，目欲脱，泪出，皮肤死肌，恶风湿痹者，诸风掉眩皆属肝木。风药先入肝，肝开窍于目，风为阳邪，势必走上，血虚则热，热则生风，风火相搏故也。腰痛去来陶陶者，乃血虚气滞之候，苦以泄滞结，甘以益血脉，辛平以散虚热也。其除胸中烦热者，心主血，虚则病烦，阴虚则热收于内，故热在胸中。血益则阴生，阴生则烦止，苦辛能泄热，故烦热并解。安肠胃，利五脉，调四肢，利血气者，即除热祛风益血，入心、入脾、入肝之验也。久服轻身耐老延年者，物久则力专，力专则气化，化则变常。其酿酒延龄，和药变白，皆服饵专气之功。故亦为仙经所录矣。生捣最治疔疮，血线疔尤为要药。疔者，风火之毒也，三、六、九、十二月，采叶、茎、花、根四物，并阴干百日，等分捣末，酒调下钱许。又可蜜丸如桐子大，每七丸，日三服，皆酒吞。一年变白，二年齿生，三年返老。仙人王子乔方也。\n\n【主治参与】\n甘菊花祛风要药。风本通肝，肝开窍于目，故为明目之主。同地黄、黄檗、枸杞子、白蒺藜、五味子、山茱萸、当归、羚羊角、羊肝，治肝肾俱虚目痛；加决明子、木贼草、谷精草、柴胡，可以去外翳。\n\n同黄连、玄参、甘草、生地黄、荆芥穗、决明子、连翘、桔梗、柴胡、川芎、羌活、童便，可治风热目痛。\n\n君川芎、细辛、藁本、当归、生熟地黄、天麦门冬、白芍药、甘草、童便，治血虚头痛。亦主头眩晕因痰结而作者。无痰，药不效。\n\n与枸杞子相对，蜜丸久服，则终身无目疾，兼不中风及生疔疽。连根生用为君，加紫花地丁、益母草、金银花、半枝莲、贝母、连翘、生地黄、栝楼根、白芷、白及、苍耳子、夏枯草，可治疔疮。甚者以蟾酥丸发汗。\n\n大便闭者，汗后以玉枢丹下之。如无玉枢丹，以大戟加蚤休、枣肉，丸服三钱，必下矣。忌甘草，犯之则死，为大戟也。\n', NULL, NULL, NULL, '菊花', NULL, '3、菊花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750100, '7BA95B263A92CFC217E7E353ACC48F92', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7181, 412, 400105602, '      味辛，温，无毒。主风寒湿痹，咳逆上气，开心孔，补五藏，通九窍，明耳目，出音声。主耳聋，痈疮，温肠胃，止小便，利四肢湿痹不得屈伸，小儿温疟，身积热不解。可作浴汤。久服轻身，聪明耳目，不忘，不迷惑，延年，益心智，高志不老。（一寸九节者良，露根者不可用。忌饴糖、羊肉。不可犯铁，令人吐逆。）\n\n       疏：菖蒲，君，正禀孟夏六阳之气，而合金之辛味以生者也。其味苦辛，其气大温。阳精芳草，故无毒。阳气开发，外充百骸，辛能四达以散邪结。此通利心脾二经之要药也。盖苦可燥湿，温能辟寒，辛可散结，风寒湿三者合成痹，去此三邪，痹自愈矣。阳气开发，芬芳轻扬，气重于味，辛兼横走，故能下气开心。咳逆者，气逆之候也，下气则咳逆上气可去。五脏之壅遏既彻，则九窍应之而通，故聪明耳目，出音声，主耳聋。辛以散之，故治痈疮。气味辛温，气厚发热，故温肠胃。膀胱虚寒，则小便不禁。肠胃既温，则膀胱与焉，故止小便。脾主四肢，脾湿既祛，则四肢湿痹不得屈伸自利。山岚瘴气，最能使小儿发疟。寒湿之甚，莫过山岚。既散其邪，则病本已拔，疟焉得而不已焉！作浴汤，及久服轻身者，除湿之验也。不迷惑，益心智，高志者，心窍开利也。其曰补五脏、延年者，单指岩棲修炼之士，辟谷服饵之用，以其助发阳气，辟除阴岚。兼可参合养性诸药，如黄精、青黏、地黄、天门冬之属，资其宣导，臻乎太和，故亦为仙经要药。至于世俗之人，五欲炽然，六淫迭至，讵可穷年卒岁，久饵偏燥之物乎？\n\n【主治参与】\n菖蒲同熟地黄、黄檗作丸，治肾虚耳聋。若中年预服，可使老而听聪。\n\n同二术、木瓜、薏仁、石斛、萆薢、黄檗，为除湿强步之要药。兼治下部脓窠湿疮如神。\n\n佐人参、麦门冬、酸枣仁、茯神、远志、生熟地黄，为补心之剂。如心气郁结者，加沉香，能益火以开心。\n\n兼辟蚤虱。\n【简误】\n         雷公云：凡使勿用泥菖、夏菖。其二件相似，如竹根硬鞭，形黑、气秽、味腥，不堪用。凡使采石上生者，根条嫩黄紧硬，节稠，一寸有九节者，是真也。采得后用铜刀刮去黄黑皮硬节一重了，用嫩桑条相拌蒸，出曝干，去桑条剉用。', NULL, NULL, NULL, '菖蒲,石菖蒲', NULL, '2、菖蒲,石菖蒲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750101, '89AC9A29BF572ACAAEF60B9E8FDA9C37', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2025-01-14 16:50:22');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7182, 412, 400105601, '      味甘，平，无毒。主补中益气，除风湿，安五藏。久服轻身延年不饥。黄帝曰：太阳之草，名曰黄精。饵之可以长生。\n\n疏：黄精，君，纯得土之冲气，而禀乎季春之令，故味甘气和，性无毒。其色正黄，味厚气薄，土位乎中，脾治中焦，故补中。脾土为后天生气之源，故益气。中气强，脾胃实，则风湿之邪不能干，故除风湿。五脏之气皆禀胃气以生，胃气者，即后天之气也。斯气盛则五脏皆实，实则安，故安五脏。脏安则气血精三者益盛。气满则不饥，久服轻身延年，著其为效之极功也。虽非治疗之所急，而为养性之上药。故仙经累赞其能服饵驻颜，久而弥胜矣。\n\n【主治参与】\n黄精同漆叶、桑椹、何首乌、茅山术，作丸饵，可以变白。久之杀三虫，能使足温而不寒。\n\n同术久服，可轻身涉险不饥。\n\n同地黄、天门冬酿酒，可去风，益血气。\n\n【简误】\n        雪公云：凡使勿用钩吻，真似黄精，只是叶有毛钩子二个，是别认处。若误服害人。黄精叶似竹叶，以溪水洗净后蒸，从巳至子，竹刀薄切，曝干用。', NULL, NULL, NULL, '黄精', NULL, '1、黄精', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626129393750102, '48E06485FE376470CB110F303D362804', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:27:04', 1, 'admin', '2024-12-24 16:55:48');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7183, 412, 400105632, '       主百病，长生神仙。亦煮花汁酿酒服之。《异类》云：凤刚者，渔阳人也。常采百花水渍，封泥埋之百日，煎为丸。卒死者，纳口中即活。胡刚服药百余岁，入地肺山。《列仙传》云：尧时赤松子服之得仙。\n\n         疏：百草花，当取群草中之芳烈者。大都百花必在春时，春者天地发生万物之气也。花者，华也，因得天地发生之和气，抽其精英而为花，故主百病，长生神仙。亦煮花汁酿酒服。昔有采百花水渍，泥封埋之百日，煎为丸，卒死者纳口中即活，其功固可验矣。\n\n以上三种，一种《唐本馀》，二种陈藏器馀。以下却有旱藕、石蘂、仙人草、会州白药、陈思岌、千里及、铁葛、伏鸡子、陈家白药，龙珠、捶胡根、甜藤、孟娘菜、吉祥草、郎耶菜、茅膏菜、蓼荞等，功效虽多，所产生土地不一，罕识形致，坊间无有。故皆存而不论，以俟后之博物君子。', NULL, NULL, NULL, '百草花', NULL, '32、百草花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770181, '9D9D8C87B2414C641727B844942ED4C5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7184, 412, 400105631, '      味辛，平，无毒。主解诸药毒。岭南及睦、婺间，如中毒草，此药及千金藤并解之。亦主蛊毒、溪毒、恶刺、虎狼虫虺等毒，天行疟瘴寒热，咳嗽痰壅，飞尸，喉闭，疮肿，小儿寒热，丹毒，中恶注忤，痢血等，并煮汁服之。其功用如犀，故名草犀，解毒为最。\n\n        疏：草犀根得地之辛味，感天之寒气以生。本草只言辛平，详治疗功能，专主解诸药毒，亦主蛊毒、溪毒、恶刺、虎狼虫虺等，天行疟瘴寒热，咳嗽痰壅，飞尸，喉闭，疮肿，小儿寒热，丹毒，中恶疰忤，痢血，并煮汁服之。其功用如犀，故名草犀。解毒为最，生衢、婺、江、饶间。苗高二三尺，独茎，根如细辛。研服更良。生水中者名水犀也。', NULL, NULL, NULL, '草犀根', NULL, '31、草犀根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770182, '2566377F5FEDA1187EEAAFB8906318C8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7185, 412, 400105630, '    味甘，平，无毒。解一切毒，止鼻衄，吐血，祛烦躁。苗茎青色，花黄色，叶摘之有汁，捣汁饮，验。\n\n       疏：药王禀天地清和生发之气以生，故其味甘平无毒。甘能解毒，故主解一切毒。平能凉血清热，故止鼻衄、吐血，祛烦躁也。', NULL, NULL, NULL, '药王', NULL, '30、药王', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770183, '7EF8BFBFFBB3B76A001BE03E53864F86', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7186, 412, 400105629, '         味苦，大寒，无毒。主解百毒，消痰，祛大热，疗头痛，辟瘟疫。其状如粗块苍术，节中有眼。\n\n       疏：辟虺雷感天地阴寒之精，其味苦，气大寒，无毒。故主解百毒，消痰，祛大热，疗头痛，辟瘟疫。豫章人专以此和诸草捣汁，治疔疮有神。', NULL, NULL, NULL, '辟虺雷', NULL, '29、辟虺雷', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770184, 'DF45C17E78C299209C52EE329EEA8236', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7187, 412, 400105628, '       味辛、甘，温，平，微寒，无毒。主五藏邪气，女子阴中寒热痛，癥瘕血闭绝子。止咳逆，治脱肛，散淋结，头中风眩，痿蹷，强阴益精。久服轻身，和颜色，令人好容颜。\n\n         疏：卷柏禀石之气，兼感天之阳气以生，故味辛温。《别录》益之以甘平、微寒、无毒。入足厥阴、少阴，血分药也。故主五脏邪气，女子阴中寒热痛，癥瘕血闭绝子。又主痿蹷，强阴益精。久服轻身、和颜色，当是理荣血之要药，行而能补者也。《别录》又谓止咳逆，治脱肛，散淋结，头中风眩，其亦辛能散结，辛能润燥，甘能缓中，甘能益血之谓欤！\n\n【简误】\n     孕妇禁用。', NULL, NULL, NULL, '卷柏', NULL, '28、卷柏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770185, 'FB6FC8D10C32482C309B6AA33048F702', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7188, 412, 400105627, '      味苦，微寒，微温，无毒。主五藏瘀血，腹中水气，胪胀留热，风寒湿痹，身体诸痛。疗心下坚，膈中寒热，周痹，妇人月水不通，消食，明目。久服轻身，延年不老。\n\n        疏：菴䕡子得土之烈气，而微感天之阴气。味厚气薄，故味苦，微寒，微温，无毒。察其功用，必应兼辛。《药性论》加辛是也。何者？苦以泄下，温以开通，使非兼辛，胡能主五藏瘀血及腹中水气、胪胀留热、风寒湿痹、身体诸痛，疗心下坚，膈中寒热，周痹，妇人月水不通，消食明目耶？正以其散中有补，补而能行，故列上经也。\n\n【主治参与】\n同牛膝、茜草、白及，消腹痈，去留血。又主瘀血腹胀，俗呼为单腹胀，四肢不肿者，是其候也。\n\n善辟蛇。蛇着之即烂。\n\n【简误】\n        此行血散结之药。妇人月事不以时至，审察未定者，不可轻用。瘀血病见之不审者，勿试。', NULL, NULL, NULL, '菴䕡子', NULL, '27、菴䕡子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770186, '1319221D49C03CD0306B3D7042DDA8C5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7189, 412, 400105626, '      味辛、甘，微温，无毒。主大风邪气，阴痿不起，强筋骨，安五藏，补中，增志，益气。疗头面游凤，少腹及阴中相引痛，下气，补五劳，益精，利男子。\n\n       疏：巴戟天禀土德真阳之精气，兼得天之阳和，阳主发散，散则横行，是当木之令，而兼金之用也，故其味辛。《别录》益之以甘，而《本经》又曰微温无毒，宜其然也。其主大风邪气，及头面游风者，风为阳邪，势多走上。\n     《经》曰：邪之所凑，其气必虚。巴戟天性能补助元阳而兼散邪，况真元得补，邪安所留？此所以愈大风邪气也。主阴痿不起，强筋骨，安五脏，补中增志益气者，是脾肾二经得所养而诸虚自愈矣。其能疗少腹及阴中引痛，下气，并补五劳，益精，利男子者，五藏之劳，肾为之主。下气则火降，火降则水升，阴阳互宅，精神内守，故主肾气滋长，元阳益盛，诸虚为病者，不求其退而退矣。\n\n【主治参与】\n得黄檗、橘核、荔枝核、牛膝、川萆薢、木瓜、金零子、怀生地黄，治疝气因于肾虚。\n\n得五味子、肉苁蓉、鹿茸、山茱萸、柏子仁、补骨脂、枸杞子，治阴痿。去鹿茸、肉苁蓉、加黄檗、牛膝、麦门冬、生地黄、车前子，治阴虚白浊久不愈。\n\n得鹿角、柏子仁、天门冬、远志、莲须、覆盆、黄檗，治夜梦鬼交泄精。\n\n同甘菊花、石菖蒲、何首乌、刺蒺黎、黑豆、山茱萸、天门冬，治头面上风。\n\n得熟大黄，治饮酒人脚弱。\n\n【简误】\n       巴戟天性温属阳，故凡病相火炽盛，思欲不得，便赤口苦，目昏目痛，烦躁口渴，大便燥闭，法咸忌之。', NULL, NULL, NULL, '巴戟天', NULL, '26、巴戟天', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770187, '67CBCF0562ADB4F81E7FD558F06B9E45', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7190, 412, 400105625, '      味甘，平，无毒。主伤中，除痹，下气，补五藏虚劳羸瘦，强阴益精，补内绝不足，平胃气，长肌肉，逐皮肤邪热痱气，脚膝疼冷痹弱。久服厚肠胃，轻身延年，定志除惊。　　\n\n      疏：石斛禀土中冲阳之气，兼感春之和气以生，故其味甘平而无毒。气薄味厚，阳中阴也。入足阳明、足少阴，亦入手少阴。甘能除热，甘能助脾，苦能益血，平能下气。味厚则能益阴气，故主伤中，下气，补五藏虚劳羸瘦，强阴益精，补内绝不足，平胃气，长肌肉，久服厚肠胃、轻身延年、定志除惊者，以其入胃，入肾，入心、脾，补益四经，则四经所生病，皆得治疗。盖皆益脾、益胃、益肾、益心之功力也。又主除痹，逐肌肤邪热痱气，脚膝疼冷痹弱者，兼能除脾胃二经之湿故也。　　\n\n【主治参与】　　\n同麦门冬、白茯苓、橘皮、甘草，则益胃、强四肢。　\n　\n同麦门冬、五味子、人参、炙甘草、白芍药、枸杞、牛膝、杜仲，则理伤中，补五藏虚劳羸瘦，强阴益精。　　\n\n同枇杷叶、麦门冬、橘皮，则下气。　　\n\n得木瓜、牛膝、桑白皮、石南叶、白鲜皮、黄檗、茯苓、菖蒲，则主诸痹，及逐皮肤邪热痱气，冷痹弱。　\n　\n夏月一味酒蒸，泡汤代茶，顿健足力。　\n　\n【简误】　　\n       【宜】入汤酒，不宜入丸。其味不苦而带甘，其形长而细，中坚实者良。酒洗蒸晒干用，慎毋误用木斛，味大苦，饵之损人。亦不入上焦药。　　', NULL, NULL, NULL, '石斛', NULL, '25、石斛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770188, '221E94B336892AA42184D497F46B92A2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7191, 412, 400105624, '      味辛，温，无毒。主咳逆，头痛，脑动，百节拘挛，风湿痹痛，死肌，温中，下气，破痰，利水道，开胸中，除喉痹，齆鼻，风痫癫疾，下乳结，汗不出，血不行，安五藏，益肝胆，通精气。久服明目，利九窍，轻身长年。　　\n\n疏：细辛禀天地阳升之气以生，故其味辛温而无毒。入手少阴、太阳经风药也。风性升，升则上行，辛则横走，温则发散，故主咳逆，头痛脑动，百节拘挛，风湿痹痛，死肌。盖痹及死肌，皆是感地之湿气，或兼风寒所成。风能除湿，温能散寒，辛能开窍，故疗如上诸风寒湿疾也。《别录》又谓温中下气，破痰开胸中，除喉痹齆鼻，下乳结，汗不出，血不行，益肝胆，通精气，皆升发辛散，开通诸窍之功也。其曰久服明目，利九窍，轻身长年者，必无是理。盖辛散升发之药，其可久服哉？　　\n\n【主治参与】　　\n同石膏，能治阳明火热上攻，以致齿痛。　\n　\n得当归、芍药、芎川、牡丹、藁本、甘草、白薇，通治妇人子宫冷，不受孕。　　\n\n得鲤鱼胆、青羊肝、甘菊花、决明子，疗目痛。　　\n\n得甘草，疗伤寒少阴咽痛。　\n　\n得藁本、芎、白芷、荆芥、防风，治风头痛。\n　　\n得紫苏、防风、甘草、桔梗、杏仁、薄荷、桑白皮，能解利伤风寒鼻塞。　　\n\n【简误】　　\n       细辛，风药也。其性升燥发散，故凡病内热，及火升炎上，上盛下虚，气虚有汗，血虚头痛，阴虚咳嗽，法皆禁用。即入风药，亦不可过五分，以其气味俱厚而性过烈耳。　', NULL, NULL, NULL, '细辛', NULL, '24、细辛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770189, '192226CCD9F2DA9572AD40AB2C079DBE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7192, 412, 400105623, '     味苦、涩，大寒，无毒。主骨间寒热，惊痫邪气，续绝伤，定五藏，杀蛊毒，除胃中伏热，时气温热，热泄下痢，去肠中小虫，益肝胆气，止惊惕。久服益智不忘，轻身耐老。　　\n\n      疏：草龙胆禀天地纯阴之气以生，故其味大苦涩，其性大寒而无毒。足厥阴、足少阴、足阳明三经药。入足少阴，除本经之热。肾主骨，故主骨间寒热。热极生风则发惊搐，重则变为痫病。湿热邪气之在中下二焦者，非此不去，热去则诸证自解。五脏有热则不安，热除则五脏自定。苦涩而寒，故杀蛊毒。大苦大寒，故能涤除胃中所伏实热，及时气温热，热泄下痢，去肠中小虫。热清则肝胆之气亦清，故益肝胆气而止惊惕也。久服益智不忘，轻身耐老，则非其任矣。　　\n\n【主治参与】　　\n草龙胆同白芍药、甘草、茯神、麦门冬、木通，主小儿惊痫入心，壮热骨热，时疾热黄，口疮。　\n　\n同苦参、牛胆，治谷疸。　　\n\n同苦参、蛆虫灰、青黛，治小儿一切疳热狂语及疮疥。　　\n\n治蛔虫攻心如刺，吐清水：龙胆二两去头、剉，水二盏，煎取一盏，去滓。隔宿勿进食，平旦时一顿服之即瘥。　　\n\n同生地黄等分，治湿热伤血分，浸大肠，以致卒下血。多服必效。　　\n\n【简误】　　\n      草龙胆味既大苦，性复大寒，纯阴之药也。虽能除实热，胃虚血少之人不可轻试。凡病脾胃两虚、因而作泄者忌之。凡病虚而有热者勿用。亦勿空腹服，饵之令人溺不禁。以其太苦，则下泄太甚故也。《炮炙论》以铜刀切去须、土头，剉碎，甘草汁中浸一宿，漉出，曝干用。　　', NULL, NULL, NULL, '龙胆 ,龙胆草', NULL, '23、龙胆 ,龙胆草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770190, '8665DC0AE9BA094F67FB192D670EBCC6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2025-01-14 11:50:15');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7193, 412, 400105622, '      味苦，温，无毒。主咳逆，伤中，补不足，除邪气，利九窍，益智慧，耳目聪明，不忘强志，倍力，利丈夫，定心气，止惊悸，益精，去心下膈气，皮肤中热，面目黄。久服轻身不老，好颜色，延年。（茎名小草，主益精，补阴气。止虚损，梦泄。）　　\n\n       疏：远志感天之阳气，得地之芳烈而生，故无毒，亦阳草也。其菖薄之流乎？其味苦温，兼微辛。为手少阴经君药，兼入足太阴经。苦能泄热，温能壮气，辛能散郁，故主咳逆伤中，补不足。养性全神明，故除邪气。阳主发散，故利九窍。心气开通则智慧自益。《经》曰：心为君主之官，神明出焉。天君既定，五官自明，故耳目聪明，不忘强志。阳气盛则力增长。男子属阳，故利丈夫。定心气，止惊悸者，心脏得补而实，故心气定而惊悸止也。心火不妄动，则阳不妄举，精不摇矣，故益精。心下膈气，是心气郁而不舒也。皮肤中热、面目黄者，湿热在上部也。苦以泄之，温以畅之，辛以散之，则二证自去矣。久服轻身不老，好颜色，延年者，心主血，心气足则血色华于面。君主强明则十一官皆得职，故延年不老。阳气日积，故身轻也。人之心肾，昼夜必交，心家气血旺盛，则肾亦因之而实。肾藏精与志，肾实故志强也。　　\n茎名小草，性味略同，功用相近。故亦主益精补阴气，止虚损梦泄。　　\n\n【主治参与】　　\n同茯神、人参、地黄、酸枣仁、丹砂，为镇心定惊要药。　　\n\n同人参、白芍药、酸枣仁、茯神、炙甘草、天竺黄、钓藤钩，治儿心虚易惊。加白檀香，治一切惊及慢惊。　　\n\n同茯神、天竺黄、钓藤钩、丹砂、金箔、真珠、琥珀、胆星、犀角，治小儿急惊。\n　　\n同人参、柏子仁、酸枣仁、麦门冬、五味子、当归身、茯神、茯苓、益智仁、生地黄、甘草、沉香，治心气弱，心血少，馁怯易惊，梦寐多魇，神不守舍，怔忡健忘，失志阳痿。　\n　\n同茯神、人参、白术、龙眼、酸枣仁、木香、炙甘草，能归脾益智。　　\n\n入当归六黄汤，能止阴虚盗汗。　\n　\n加甘草，治妇人血噤失音，小儿客忤。　\n　\n《古今录验》及《范汪方》治胸痹心痛，逆气，膈中饮不下，小草丸：小草、桂心、蜀椒去目、干姜、细辛各三两，附子二分炮去皮脐，共为末，蜜丸如梧子大。先食米汁，下三丸，日三。不知稍增，以知为度。禁猪肉、冷水、生葱菜。　\n　\n远志一味煎酒，治一切痈疽发背。病从七情忧郁恼怒而得者，服之皆愈。　　\n\n陈言《三因方》：用远志酒，治一切痈疽发痛，恶候浸大，有死血阴毒在中则不痛，傅之即痛。有忧怒等气积怒攻则痛不可忍，傅之即不痛。或蕴热在内，热逼人手不可近，傅之即清凉。或气虚冷，溃而不敛，傅之即敛。此本韩大夫宅用以救人方，极验。若七情内郁，不问虚实寒热，治之皆愈。用远志不拘多寡，米泔浸洗，捶去心，为末。每服三钱，温酒一盏调，澄少顷，饮其清，以滓傅患处。　　\n\n【简误】　　\n       心经有实火，为心家实热，应用黄连、生地黄者，禁与参、术等补阳气药同用。　', NULL, NULL, NULL, '远志', NULL, '22、远志', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770191, 'CD1C6DEEEC6AE6902073096E34B0FA48', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7194, 412, 400105620, '     味甘，微寒，无毒。主筋急拘挛，不可屈伸，风湿痹，下气，除筋骨邪气不仁，利肠胃，消水肿，令人能食。久服轻身益气。　\n　\n疏：薏苡仁正得地之燥气，兼禀乎天之秋气以生，故味甘淡，微寒无毒。阳中阴，降也。《经》曰：地之湿气，感则害人皮肉筋脉。又曰：风寒湿三者合而成痹。此药性燥，能除湿，味甘能入脾朴脾，兼淡能渗泄，故主筋急拘挛不可屈伸，及风湿痹。除筋骨邪气不仁，利肠胃，消水肿，令人能食，久服轻身。总之湿邪去则脾胃安，脾胃安则中焦治，中焦治则能荣养乎四肢，而通利乎血脉也。甘以益脾，燥以除湿，脾实则肿消，脾强则能食，湿去则身轻。如是则已上诸疾，不求其愈而自愈矣。\n　　\n【主治参与】　　\n同木瓜、石斛、萆薢、黄檗、生地黄、麦门冬，治痿厥。　　\n\n同五加皮、牛膝、石斛、生地黄、甘草，主筋拘急。加二术，菖蒲、甘菊花，可治痹。佐以附子，能治胸痹偏缓。　\n　\n独用数两，淘净煮浓汤，顿饮，可治肺经因湿火所伤吐脓血，一切肺痿、肺疽、咳嗽、涕唾上气。《经》曰：治痿独取阳明。阳明者，胃与大肠也。二经湿热盛则成痿，熏蒸于肺则发肺痈，及吐血咳嗽、涕唾秽浊。盖肺与大肠为表里，腑热必传于五脏，大肠与胃家之湿热散则痿自愈，吐脓血咳嗽亦并止矣。　\n　\n【简误】　　\n        薏苡乃除湿燥脾胃之药。凡病人大便燥，小水短少，因寒转筋，脾虚无湿者忌之。妊娠禁用。　　', NULL, NULL, NULL, '薏苡仁', NULL, '20、薏苡仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770192, '9988F9E7F424DEE33DC22FE484EE0277', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7195, 412, 400105621, '     味甘、咸，寒，无毒。主风寒湿痹，乳难，消水，养五藏，益气力，肥健，补虚损五劳，除五藏痞满，起阴气，止泄精，消渴，淋沥，逐膀胱三焦停水。久服耳目聪明，不饥延年轻身，面生光，能行水上。扁鹊云：多服，病人眼。　　\n\n       疏：泽泻禀地之燥气，天之冬气以生，故味甘寒。《别录》益之以咸。肾与膀胱为表里。咸能入肾，甘能入脾，寒能去热，盖淡渗利窍之药也。其曰主风寒湿痹，乳难，消水，养五脏，皆以利水燥湿则脾得所养，脾得所养则五脏皆得所养。益气力，肥健者，皆水利则湿去，湿去则脾强之功效也。又云主腹痞满淋沥，逐膀胱三焦停水，其能利水祛湿，益无疑矣。泄精者，湿热下流，客肾与膀胱，是民火扇君火也，故精摇而泄。病在脾胃，湿热尽则泄精自止矣。止消渴者，单指湿热侵脾，脾为邪所干则不能致津液也。总之，其性利水除湿，则因湿热所生之病，靡不除矣。　　\n\n【主治参与】　　\n水肿昼剧夜平者，阳水也。泽泻同猪苓、白茯苓、人参、白术、白芍药、赤小豆、桑白皮、橘皮治之，多服必愈。夜剧昼平者，阴水也，同车前子、赤茯苓、生地黄、白芍药、赤小豆、桑根白皮、木瓜、石斛、薏苡仁治之，多服必愈。　　\n\n入五苓散、四苓散，治一切湿热。　\n　\n入六味地黄丸，除阴虚病有湿热者。　　\n\n同人参、白术、半夏、茯苓、橘皮、紫苏、猪苓，为治饮之要药。一切停饮停水无不效。　\n　\n仲景治心下支饮，泽泻五两，术二两，水二升，煎取半升，分温再服。　　\n\n《素问》身热解堕，汗出如浴，恶风少气，名曰酒风。服之以泽泻、术各十分，麋衔五分，合以二指撮，食后服之。　　\n\n饮证，病甚欲眩者，用泽泻五两，炒术二两，水三升，煮浓服必效。　　\n\n仲景治水搐渴烦，小便不利，或吐或泻，五苓散主之。　　\n\n【简误】　　\n       泽泻，《本经》及《药性论》、日华子皆曰补虚损五劳，久服耳目聪明，不饥延年，及仙经断谷，肾虚精自出，补女人血海，令人有子等条，则悖谬之谈，文不属理，非神农氏之言明矣。扁鹊云：多服病人眼，乃为确论也。泽泻善逐水病，人无湿无饮而阴虚，及肾气乏绝，阳衰精自流出，肾气不固，精滑目痛，虚寒作泄等候，法咸禁用。误犯令人虚极。　　', NULL, NULL, NULL, '泽泻', NULL, '21、泽泻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770193, 'DCA5C49CE2367170EDA557DEF1BC3942', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2024-12-24 16:55:47');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7196, 412, 400105619, '     味甘，温、平，无毒。主伤中，补虚羸，除寒热邪气，补中，益气力，长肌肉。主头面游风，头风眼眩，下气，止腰痛，补虚劳羸瘦，充五藏，降烦热，强阴。久服耳目聪明，轻身不饥延年。　　\n\n      疏：薯蓣得土之冲气，兼禀春之和气以生，故味甘，温平无毒。观其生捣傅痈疮，能消热肿，是微寒之验也。甘能补脾，脾统血而主肌肉；甘温能益血，脾治中焦，故主伤中，补虚羸，补中，益气力，长肌肉，充五藏，除烦热，强阴也。其主寒热邪气，及头面游风，头风眼眩，下气，止腰痛者，正以其甘能除大热，甘能益阴气，甘能缓中，甘温平能补肝肾。《药性论》云：薯蓣，臣，能补五劳七伤，去冷是也。盖寒热邪气者，阴不足则内热，内虚则外邪客之。热则生风，缓则下气，下气则阳交于阴。五劳既去，五脏既充，则久服耳目聪明、轻身延年之效自著矣。\n　　\n【主治参与】　　\n同地黄、枸杞、牛膝、甘菊花、白蒺藜、五味子，则补肝肾，益阴气，治一切虚羸，强阴，长肌，增力，明目。同莲肉、白扁豆、人参、白芍药、茯苓、炙甘草、橘皮，则补脾健胃止泄泻。加木瓜、藿香，安吐逆。　　\n\n同羊肉、肉苁蓉作羹，可扶衰补虚羸。　\n　\n【简误】　　\n      藷藇、薯蓣，确系两种。譬诸米谷，其种有粇、糯、秈、黍、稷之不同是也。入药必以冀州所产者为胜。总之南方不迨北地。《图经》并载入四明，则误矣。不宜与面同食。　', NULL, NULL, NULL, '山药,薯蓣', NULL, '19、山药,薯蓣', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626136455770194, 'F45369508FF143CF9B647992EA136C2B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 16:55:48', 1, 'admin', '2025-01-14 11:40:51');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7197, 413, 400105706, '        味甘，微温，无毒。主痈疽、久败疮，排脓止痛，大风癞疾，五痔鼠瘘，补虚，小儿百病，妇人子藏风邪气，逐五藏间恶血，补丈夫虚损，五劳羸瘦，止渴，腹痛，泄痢，益气，利阴气。生白水者冷补。其茎叶疗渴及筋挛，痈肿疽疮。\n\n疏：黄耆禀天之阳气、地之冲气以生。故味甘、微温而无毒。气厚于味，可升可降，阳也。入手阳明、太阴经。甘乃土之正味，故能解毒。阳能达表，故能运毒走表。甘能益血，脾主肌肉，故主久败疮，排脓止痛。风为阳邪，凡贼风虚邪之中人也，则病疠风。《经》曰：邪之所凑，其气必虚。性能实表，则能逐邪驱风，故主大风癞疾，五痔鼠瘘，补虚，兼主小儿天行痘疮之在阳分，表虚气不足者，小儿胎毒生疮疖。《别录》又主妇人子藏风邪气，逐五脏恶血者，血不自行，随气而行，参合血药则能之矣。补丈夫虚损，五劳羸瘦者，通指因劳阳气乏绝所生病也。甘温益元气，甘温除大热，故通主之。气旺则津液生，故止渴。血虚则腹痛，中焦不治亦腹痛。脾胃之气不足，则邪客之而泄痢，补中气则诸证自除矣。益气利阴气者，阳生阴长也。\n\n【主治参与】\n黄耆在补中益气汤，甘温能除大热，为治劳倦发热之要剂。\n\n同生熟地黄、黄檗、黄芩、黄连、当归，加酸枣仁炒熟研，为治阴虚盗汗之正法。\n\n本方去三黄，加人参、五味子、酸枣仁，治表虚自汗。同桂枝、白芍药、防风、炙甘草，能实表，治表虚畏风，伤风自汗。\n\n与茅山术、生地黄等分，牛膝、黄檗减半，作丸，治积年湿毒臁疮，百药不效。\n\n《外台秘要》主甲疽疮肿烂，生脚指甲边，赤肉出。黄耆二两，䕡茹三两，苦酒渍一宿，猪脂五合，微火上煎取三合，绞去滓，以封疮上，日三度易，其肉即消。\n\n同白芷、白及、甘草、金银花、皂角刺，排脓止痛。\n\n同人参、甘草，治天行痘疮，阳虚无热证。\n\n【简误】\n      黄耆功能实表，有表邪者勿用。能助气，气实者勿用。能内塞补不足，胸膈气闭闷，肠胃有积滞者勿用。能补阳，阳盛阴虚者忌之。上焦热甚，下焦虚寒者忌之。病人多怒，肝气不和者勿服。痘疮血分热盛者禁用。', NULL, NULL, NULL, '黄芪,黄耆', NULL, '6、黄芪,黄耆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626145179439174, 'B7E78A7D02519B3194B507F0CA476887', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 17:31:18', 1, 'admin', '2025-01-14 14:30:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7198, 413, 400105705, '        味苦、辛，温，微寒，无毒。主恶血，破癥结积聚，喉痹，乳难，身体风痒，头痛，咳逆伤肺、肺痿，止烦下气，小儿头疮，痈肿阴㿉，可作摩粉。其叶：主风痒，可煮以浴。久服长肌肉，明目，轻身。\n\n         疏：蒺藜有两种，一种同州沙苑白蒺藜，一种秦州刺蒺藜。白者感马精所生，刺者感地中阳气所生。《本经》苦温，《别录》加辛及微寒，并无毒。夫苦能泄，温能宣，辛主散，主润。故刺蒺藜主恶血，破癥结积聚，喉痹，乳难，身体风痒，头痛，咳逆，小儿头疮，痈肿，阴㿉。叶主风痒，可煮以浴。辛入肝，肝主风也。\n\n《药性论》云：白蒺藜味甘，微腥。甘中必有辛，辛能润，故主咳逆伤肺肺痿，止烦下气，久服长肌肉，明目，轻身，以其入肾益精故也。专饵长年，效可责矣。单行杂疗，主治良多，本草诸方咸堪选用。形如羊肾圆而细，色如绿豆，嚼之作绿豆腥气，为末煮之，则香同新茶者真。\n\n【主治参与】\n刺蒺藜同何首乌、豨莶叶、胡麻、地黄、木瓜、荆芥穗、天门冬、黄檗，治遍身风痒。\n\n同州白蒺藜得莲须、山茱萸、五味子、莲肉、覆盆子、鱼胶、龙骨、白胶，能固精益肾，令人有子，兼主小便遗沥。\n\n得甘菊花、甘枸杞子、决明子、女贞实、槐角子，能明目。\n\n《外台秘要》：单服，能复明三十年目疾。\n\n【简误】\n      同州蒺藜性能固精，命门火炽，阳道数举，交媾精不得出者，勿服。', NULL, NULL, NULL, '蒺藜子,刺疾藜', NULL, '5、蒺藜子,刺疾藜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626145179439175, 'AF89E5E51647F5CDBB0FAF6874E3B9B2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 17:31:18', 1, 'admin', '2025-01-15 09:42:56');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7199, 413, 400105704, '      味苦，温、微寒，无毒。主风热，死肌，痈伤，（伤宜作疡）。口干舌焦，痈肿不消，喉舌肿不通，水浆不下，大惊入腹，除邪气，养肾，主腰髋痛，坚筋骨，利关节。久服轻身，明目，润泽好颜色，不老延年。\n\n疏：络石禀少阳之令，兼得地之阴气。其味苦，其气温，微寒而无毒，入足阳明、手足少阴、足厥阴、少阳经。故主风热，死肌，痈伤，口干舌焦，痈肿不消，喉舌肿，水浆不下，皆苦温通气血。血属阴，阴寒入血而除热之效也。又能除邪气，养肾，主腰髋痛，坚筋骨，利关节，疗蛇毒心闷，刀斧伤，捣封立瘥，皆凉血除热之功也。\n\n《本经》久服轻身明目，润泽好颜色，不老延年。陈藏器以为能变白，亦指益阴凉血而言也。生石上者良。\n\n【主治参与】\n络石捣汁，入诸解毒药，治发背痈疽，神验。\n\n《外台秘要》治喉痹，喘息不通，须臾欲绝：以络石二两，水一升，煎取一大盏，去滓。细细吃，须臾即通。\n\n【简误】\n     阴脏人，畏寒易泄者，勿服。\n\n木莲，薜荔也。附木而生，得木气，故名木莲，俗呼鬼馒头。夤缘树木墙壁，三五十年渐大，枝叶繁茂，叶长二三寸，厚若石韦，生子似莲房，打破有白汁，停久如漆。六七月实内空而红，则满腹细子，大如稗子，一子一须，其味微涩，其壳虚轻。一年一熟，子亦入药。颂曰：薜荔、络石极相类，茎叶粗大如藤状，木莲更大于络石，四时不凋，盖禀天地阴寒之气而生者也。故其味酸寒，辛平无毒。用其叶研烂绞汁，和蜜饮数升，并傅痈上，能消背痈，下利即愈。考木莲无经文者，为其与络石相类也。俱以杜仲、牡丹为之使。恶铁落，畏贝母、菖蒲。', NULL, NULL, NULL, '络石,木莲附', NULL, '4、络石,木莲附', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626145179439176, 'FBFE4EC043D62CBAD2A38B35F83DEAAF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 17:31:18', 1, 'admin', '2025-01-15 09:27:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7200, 413, 400105701, '    味苦，寒，无毒。主解诸毒，杀蛊蚑，疰鬼，螫毒。久服头不白，轻身。\n其叶汁：杀百药毒，解狼毒、射罔毒。\n\n     疏：蓝实禀天地至阴之精，故其味苦寒而无毒。其用主解诸毒，杀蛊蚑、疰鬼、螫毒，久服头不白。头白者，血热也，蓝能凉血而解热，故令发不白也。热去而血得所养，故身轻。其叶汁解百药毒，解狼毒、射罔毒。\n\n   《药性论》云：蓝实味甘，能填骨髓，益心力。汁止心烦躁。由此观之，苦寒而兼甘可知矣。\n\n    日华子又云：治天行热狂，疔疮，游风，热毒，肿毒，风疹，除烦止渴，杀疳，解毒药、毒箭，金疮血闷，排脓，小儿热疳，小儿丹热，最为要药。其功用之广，俱如本草所载。蓼蓝最堪入药。甘蓝，若人食，去热黄。\n\n【主治参与】\n蓝汁入麝香、雄黄，治蜘蛛咬，有神。\n\n干蓝为末，同犬肉空腹食之，主长肉，内塞。\n\n【简误】\n       虚寒人及久泄畏寒，腹中觉冷者，勿服。', NULL, NULL, NULL, '蓝实', NULL, '1、蓝实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626145179439177, '771F1CECCF4F8AF0DFC538263D7F0751', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 17:31:18', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7201, 413, 400105702, '     味辛，温，无毒。主中风入脑头痛，寒痹，筋挛缓急，金疮，妇人血闭无子，除脑中冷动，（动宜作痛）。面上游风去来，目泪出，多涕唾，忽忽如醉，诸寒冷气，心腹坚痛，中恶，卒急肿痛，胁风痛，温中内寒。\n\n疏：芎䓖禀天之温气，地之辛味，辛甘发散为阳，是则气味俱阳而无毒，阳主上升，辛温主散，入足厥阴经，血中气药。扁鹊言酸，以其入肝也。故主中风入脑头痛，寒痹，筋挛缓急，金疮，妇人血闭无子。《别录》除脑中冷动，面上游风去来，目泪出，多涕唾，忽忽如醉，诸寒冷气，心腹坚痛，中恶，卒急肿痛，胁风痛，温中内寒。已上诸病，皆病在血分，正以其性走窜而绝无阴凝粘滞之性，故入血药上行而不可多用耳。\n\n【主治参与】\n同地黄、当归、芍药，为四物汤。通主入血分补益。\n\n同荆芥、白芷、当归、地黄、芍药、术、甘草，治破伤风。冬月加桂枝。\n\n同当归、地黄、干漆、延胡索、五灵脂、芍药、牡蛎粉、京三棱，治血瘕。\n\n同白芷、茜根、黄耆、金银花、生地黄，能排脓消瘀血。\n\n同甘菊花、当归、地黄、天门冬、白芍药、炙甘草，专主血虚头痛。火盛者加童便服。\n\n同当归尾、桂心、牛膝，治子死腹中。\n\n同续断、怀熟地、白胶、杜仲、山茱萸、五味子、人参、黄耆、酸枣仁，治血崩久不止。\n\n【简误】\n        芎䓖性阳、味辛。凡病人上盛下虚，虚火炎上，呕吐，咳嗽，自汗，易汗，盗汗，咽干口燥，发热作渴烦燥，法并忌之。', NULL, NULL, NULL, '芎䓖,川芎', NULL, '2、芎䓖,川芎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626145179439178, '4F7D23EC274F9420AF9E9774780F369C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 17:31:18', 1, 'admin', '2025-01-14 12:01:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7202, 413, 400105703, '         味苦，寒，无毒。主热气，目痛眦伤泪出，明目，肠澼，腹痛下痢，妇人阴中肿痛，五藏冷热，久下泄澼脓血，止消渴、大惊，除水，利骨，调胃厚肠，益胆，疗口疮。久服令人不忘。\n\n         疏：黄连禀天地清寒之气以生，故气味苦寒而无毒。味厚于气，味苦而厚，阴也，宜其下泄。欲使上行须加引导。入手少阴、阳明，足少阳、厥阴，足阳明、太阴。为病酒之仙药，滞下之神草。六经所至，各有殊功。其主热气，目痛眦伤泪出，明目，大惊，益胆者，凉心清肝胆也。肠澼，腹痛下痢，《别录》兼主泄澼。泄者，泻利也；澼者，大肠下血也，俗呼为脏毒。除水利骨，厚肠胃，疗口疮者，涤除肠、胃、脾三家之湿热也。久服令人不忘者，心家无火则清，清则明，故不忘。禅家习定，多饮苦茗，亦此义尔。\n\n【主治参与】\n同赤柽木叶，入三黄石膏汤，治痧疹已透而烦躁不止，有神。\n\n入当归六黄汤，加枣仁、龙眼，治盗汗，有神。\n\n同地黄、甘菊、荆芥穗、甘草梢、芎、柴胡、蝉蜕、木通，治风热上攻、目赤痛。\n\n黄连末一两，同雄羊肝一具，生捣匀，众手丸如梧子。每服以滚浆水吞廿一丸。诸眼目疾，及障翳青盲皆主之。禁食猪肉，虽油汁亦勿入口，作六剂必效矣。\n\n同当归、甘菊花，人乳浸蒸，入明矾、铜绿各少许，洗目甚效。\n\n同芍药、莲子、扁豆、升麻、甘草、滑石、红曲，治一切滞下脓血。\n\n同槐花、枳壳、乳香、没药，治滞下纯血腹痛，煮服神效。\n\n同五谷虫、芦荟、白芜荑、青黛、白槿花、白芙蓉花，治小儿一切疳热，如神。\n\n同赤小豆为细末，傅痔疮妙。\n\n同干葛、甘草、升麻、芍药，治痧疹后泄泻。\n\n同五味子、麦门冬、干葛，治酒病酒伤，如神。\n\n同五味子、甘草，煮浓汁漱口，治口糜口疮良。\n\n同麦门冬、五味子，治卒消渴，小便多，良。\n\n同人参、莲子，治虚人患滞下，及老人、产妇滞下不止。\n\n【简误】\n        黄连味大苦，气大寒，群草中清肃之物。其处上经，譬犹皋陶之在虞廷，明刑执法，以禁民邪，是其职也。稷契夔龙之事，则非其任矣。故祛邪散热，荡涤肠胃，肃清神明，是其性之所长；而于补益精血，温养元气，则其功泊如也。凡病人血少气虚，脾胃薄弱，心血不足，以致惊悸不眠，而无烦热躁渴，及产后不眠，血虚发热，泄泻腹痛，小儿痘疮，阳虚作泄，行浆后泄泻，老人脾胃虚寒作泻，阴虚人天明溏泄，病名肾泄，真阴不足，内热烦躁诸证，法咸忌之。犯之使人危殆，大忌猪肉。', NULL, NULL, NULL, '黄连', NULL, '3、黄连', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626145179439179, 'EB81FA2ACBB07806F6E707C1AE2D1062', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 17:31:18', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7203, 413, 400105707, '       味甘、酸、咸，微温，无毒。主五劳七伤，补中，除茎中寒热痛，养五藏，强阴，益精气，多子，妇人癥瘕，除膀胱邪气，腰痛，止痢。久服轻身。\n\n        疏：肉苁蓉得地之阴气、天之阳气以生，故味甘酸咸，微温无毒。入肾，入心包络、命门。滋肾补精血之要药。气本微温，相传以为热者，误也。甘为土化，酸为木化，咸为水化。甘能除热补中，酸能入肝，咸能滋肾。肾肝为阴，阴气滋长，则五脏之劳热自退，阴茎中寒热痛自愈。肾肝足则精血日盛，精血盛则多子。妇人癥瘕，病在血分，血盛则行，行则癥瘕自消矣。膀胱虚则邪客之，得补则邪气自散，腰痛自止。久服则肥健而轻身，益肾肝，补精血之效也。若曰治痢，岂滑以导滞之意乎？此亦必不能之说也。软而肥厚，大如臂者良。\n\n【主治参与】\n肉苁蓉得白胶、杜仲、地黄、当归、麦门冬，主妇人不孕。\n\n同人参、鹿茸、牡狗阴茎、白胶、杜仲、补骨脂，主男子阳痿，老人阳衰，一切肾虚腰痛，兼令人有子。\n\n同地黄、枸杞、牛膝、鳖甲、天门冬、麦门冬、当归、白胶、杜仲、青蒿、五味子、黄檗、山茱萸，治五劳七伤，茎中寒热痛，妇人癥瘕。\n\n独用数两，浸去咸味，并去鳞甲及中心膜，淡白酒煮烂，顿食，治老人便燥闭结，有神。\n\n【简误】\n        泄泻禁用。肾中有热，强阳易兴而精不固者，忌之。', NULL, NULL, NULL, '肉苁蓉', NULL, '7、肉苁蓉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626145937358917, '063A9E3446E4B3B4B121D796CA3BBE13', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-24 17:34:23', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7204, 413, 400105727, '       味甘，温，无毒。主风血冷气宿疾，温中去风。草似松叶，上有脂，山人服之。\n\n       疏：长松生太行西北五台诸山，得天地温和之气而生，故性味甘温而无毒。主风血冷气宿疾，温中去风。出陈藏器。治大风恶疾，眉发堕落，百骸腐溃：每一两，入甘草少许，水煎服，旬日即愈。又解诸虫毒。当是祛风之仙药也。', NULL, NULL, NULL, '长松', NULL, '27、长松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291653, 'AE686BFBB9BEF1B401ACCFDCB56C91B9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7205, 413, 400105726, '      味苦、甘，平，无毒。主金疮止血，逐痛出刺，除风痹内寒，止心烦，鼻衄，痈疽，恶疮，瘘乳，妇人难产。久服轻身，耐老增寿。\n\n       疏：王不留行禀土金火之气，故味苦甘平。平者辛也，其气应温而无毒。苦能泄，辛能散，甘入血，温能行，故主金疮止血，逐痛出刺，除风痹内寒，痈疽，恶疮，瘘乳，妇人难产，入血活血之要药也。若夫心烦，鼻衄，应是血分热病，非同凉血药用，未见其可也。入足厥阴经。\n\n【主治参与】\n同漏芦、贝母、鲮鲤甲、青皮、没药、山茨菇、山豆根、栝楼根，治乳岩，乳痈。\n\n同鲮鲤甲、白芷、通草、猪蹄汁，煮服下乳。\n\n为末，和蟾酥，治疔疮，酒服取汗。\n\n《千金方》有王不留行汤，治痈疽，妬乳，月蚀，白秃，及面上疮，去虫止痛：王不留行、东南桃枝、东行吴茱萸根皮各五两，蛇床子一升，牡荆子、苦竹叶、刺蒺藜子各三升，大麻子一升，以水二斗半，煮水一斗，频频洗之。\n\n【简误】\n       孕妇勿服。', NULL, NULL, NULL, '王不留行', NULL, '26、王不留行', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291654, '34DF71C29611D25A37AA2D3601F50BBA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7206, 413, 400105725, '    味苦，微寒，无毒。主血积，惊气，除寒热，补中，益肺气，疗胸痹，心腹痛，结热邪气头痛，皮间邪热，安五藏，补中。久服利人。\n\n     疏：沙参禀天地清和之气。《本经》味苦，微寒，无毒。王好古谓甘而微苦。苦者，味之阴也；寒者，气之阴也；甘乃土之冲气所化，合斯三者，故补五脏之阴。故主血积，惊气，除寒热，补中益肺气。\n\n   《别录》又疗胸痹，心腹结热，邪气头痛，皮间邪热者，苦能泄热，寒能除热，甘能缓急，益血补中，故疗诸因热所生病，而其功用驯致安五脏补中，久服利人也。入手太阴经。\n\n【主治参与】\n同天门冬、麦门冬、百部、五味子、桑白皮，治肺痿，肺热。\n\n同贝母、枇杷叶、栝楼、甘草、桑白皮、百部、天门冬、款冬花，治久嗽。\n\n葛洪治卒得诸疝，少腹及阴中相引痛如绞，自汗出欲死，捣细末，酒服方寸匕，立差。\n\n【简误】\n       脏腑无实热，肺虚寒客之作嗽者，勿服。', NULL, NULL, NULL, '沙参', NULL, '25、沙参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291655, '161F88D205572F3B16E7B40176A0706E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7207, 413, 400105724, '     味苦，平，微寒，无毒。主风湿寒热邪气，热结黄疸，通身发黄，小便不利，除头热，去伏瘕。久服轻身，益气，耐老，面白悦，长年。\n\n      疏：茵蔯蒿感天地苦寒之味，而兼得春之生气以生者也。其味苦平，微寒无毒，故主风湿寒热邪气，热结黄疸，通身发黄，小便不利，及头热，皆湿热在阳明、太阴所生病也。苦寒能燥湿除热，湿热去则诸证自退矣。去伏瘕，及久服轻身，益气耐老，面白悦，长年，未有修事者。\n\n     日华子云：石茵蔯味苦，凉无毒。即山茵蔯也。入足阳明、太阴，足太阳三经。除湿散热结之要药也。\n\n【主治参与】\n茵蔯性苦寒，能除一切湿热。五疸虽各有其因，然同为湿热所成。故得黄连、干葛、黄檗、苜蓿、五味子，治酒疸如神。\n\n得二术、茯苓、泽泻、车前子、木通、橘皮、神曲、红曲、麦门冬，治谷疸。\n\n同生地黄、仙人对坐草、石斛、木瓜、牛膝、黄檗，治疸因酒色而得，病名女劳疸。\n\n治谷疸，寒热不食，食即头眩，心胸不安。茵蔯六两，栀子十四枚，大黄二两，以水一斗，先煮茵蔯，减六升，内二味，煮取三升，去滓。分温三服，小便当利，尿如皂角汁状，色正赤，一宿腹减，黄从小便去也。\n\n    又茵蔯五苓散，总治诸疸。\n\n【简误】\n       蓄血发黄者，禁用。', NULL, NULL, NULL, '茵陈蒿,茵陈', NULL, '24、茵陈蒿,茵陈', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291656, '0B95CDBE706C20AAC09E50C4AB4EC841', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2025-01-14 15:16:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7208, 413, 400105723, '    味苦、酸，平，无毒。主大热，火疮，身热烦，邪恶气，诸蛊毒，痂疕，寒热风痹，诸不足。\n\n花：主女人漏下赤白。轻身明目，久服通神不老。\n\n     疏：景天即慎火草也。味苦平，\n\n  《别录》酸，无毒。今详其功用，当是大寒纯阴之草也。性能凉血解毒，故主大热，火疮，身热烦，邪恶气，诸蛊毒，痂疕，寒热风痹，诸不足。热解则毒散血凉，血凉则阴生故也。\n花：功用具如经说，第大苦寒之药，而云轻身明目，通神不老，未可尝试也。\n\n【主治参与】\n治毒虺蛇伤，取汁饮，并敷伤处，立效。\n\n治一切赤游风、各种火丹之神药也。故知其性大寒、其味大苦耳。\n\n【简误】\n       一切病得之寒湿，恶寒喜热者，勿服。', NULL, NULL, NULL, '景天', NULL, '23、景天', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291657, '2C396373FEDAD658D383CC24B7D2675B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7209, 413, 400105722, '    味苦、寒、无毒。主膀胱热，利小便，补中益精气，去皮肤中热气，散恶疮疝瘕，强阴，久服耳目聪明，轻身耐老，使人润泽。\n\n    疏曰：地肤子，即俗呼落帚也。得地之阴气，故味苦、寒而无毒。其主膀胱热，利小便，补中益精气。\n\n《别录》去皮肤中热气，散恶疮疝瘕，强阴，久服耳目聪明，轻身耐老，使人润泽者，寒能除热，热散则阴强。其性带涩，涩能秘精。精秘则日盛。阴强精盛，故能疗上来诸疾也。', NULL, NULL, NULL, '地肤子,落帚', NULL, '22、地肤子,落帚', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291658, '4F62394329C9D8D4F68F00B26E67BE5E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7210, 413, 400105721, '      味苦、辛、甘，平，无毒。主妇人阴中肿痛，男子阴痿湿痒，除痹气，利关节，癫痫，恶疮，温中下气，令妇人子藏热，男子阴强。久服轻身，好颜色，令人有子。\n\n      疏：蛇床子味苦平，《别录》辛甘无毒。今详其气味，当必兼温燥，阳也，故主妇人阴中肿痛，男子阴痿湿痒，除痹气，利关节，恶疮。\n\n   《别录》温中下气，令妇人子藏热，男子阴强。久服轻身，令人有子。盖以苦能除湿，温能散寒，辛能润肾，甘能益脾，故能除妇人男子一切虚寒湿所生病。寒湿既除，则病去身轻。性能益阳，故能已疾，而又有补益也。\n\n雷公云：凡使须用浓蓝汁，并百部自然汁，二味同浸三伏时，漉出日干，却用生地汁拌蒸，从午至亥，日干用。此药只令阳气盛数，号曰鬼考也。\n\n【主治参与】\n蛇床子同巴戟天、远志、牛膝、何首乌、阳起石，治男子阴痿湿痒。\n\n同巴戟天、牛膝、杜仲、续断、地黄、黄檗、白胶，治妇人阴中肿痛。\n\n同黄檗、山茱萸肉、五味子、茯苓、车前子、香附、川续断、补骨脂，治一切带下。赤者加白胶、阿胶。\n\n【简误】\n       蛇床子性温燥，肾家有火，及下部有热者，勿服。', NULL, NULL, NULL, '蛇床子', NULL, '21、蛇床子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291659, 'CE26FF25359D7CDD2AA0FA76E851C9AD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7211, 413, 400105720, '     味甘，温，无毒。主寒热，身肿。久服轻身，长年益寿。\n\n      疏：忍冬，即金银花。藤一名鹭鹚藤。感土之冲气，禀天之春气，故味甘、微寒而无毒。主寒热身肿，久服轻身、长年益寿者，甘能益血，甘能和中，微寒即生气也。气味如斯，所主宜矣。\n\n【主治参与】\n同甘菊花、紫花地丁、夏枯草、白及、白剑、贝母、连翘、鼠粘子，治一切肿毒。加辟虺雷治一切疔疮。\n\n君地榆、芍药、黄连、甘草、升麻，治一切血痢。\n\n单味熬膏，小儿服之可稀痘。\n\n《肘后方》：忍冬藤熬膏，治飞尸、伏尸、遁尸、沉尸、风尸、尸疰。', NULL, NULL, NULL, '金银花,忍冬', NULL, '20、金银花,忍冬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291660, '8C136E76ACA3121BB23B4813E2AD36D8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7212, 413, 400105719, '      味辛，平，无毒。主利水道，杀蛊毒，辟不祥，除胸中痰癖。久服益气，轻身不老，通神明。\n\n      疏：兰草禀天地清芬之气以生，故其味辛气平无毒。入手太阴、足阳明经。肺主气，肺气郁结则上窍闭，而下窍不通。胃主纳水谷，胃气郁滞，是水谷不以时化，而为痰癖。蛊毒、不祥之气，亦胃中受病。辛平能散结滞，芬芳能除秽恶，则上来诸证自瘳。大都开胃除恶，清肺消痰，散郁结之圣药也。久服等语，亦言其效之极功。\n\n【主治参与】\n同藿香、枇杷叶、石斛、竹茹、橘红，开胃气之神品。\n\n加入沉水香、郁金、白豆蔻、真苏子、芦根汁，下气开郁，治噎膈之将成者。\n\n同栝楼根、麦冬、黄连、竹叶、芦根汁，治消渴。', NULL, NULL, NULL, '兰草', NULL, '19、兰草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291661, '3E092DD4223FD65611EB8CE11D9D55E5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7213, 413, 400105718, '      味甘、温，无毒。主益气，去面皯黑色，媚好。其根味辛，主腹中寒热邪气，利小便，久服不饥轻身。\n\n      疏曰：旋花，《唐本》注云：旋菖花是也。然详其气味甘温无毒，功能有主益气去面皯黑色，媚好，根味辛，主腹中寒热邪气，利小便，久服不饥轻身之辞，则似非今之金沸草矣。《别录》根主续筋。\n\n     陈藏器云：旋花本功外，取筋食之不饥，绞汁服之，主丹毒，根亦主续筋。\n\n   《蜀本图经》云：旋菖花根也。蔓生，叶似薯蓣而多狭长，花红白色，根无毛节，蒸煮堪啖，味甘美，根名筋根。\n\n     今所在川泽皆有，应与下品$m{旋复花}$w{殊别}。识之者甚稀。', NULL, NULL, NULL, '旋花', NULL, '18、旋花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291662, 'F6B2FA26911BCC487884478536812EF8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7214, 413, 400105717, '      味酸，温，无毒。主益气，咳逆上气，劳伤羸瘦，补不足，强阴，益男子精，养五藏，除热，生阴中肌。（苁蓉为之使，恶萎蕤，胜乌头）\n\n       疏：五味子得地之阴，而兼乎天之阳气，故《本经》味酸，气温，味兼五而无毒。王好古云：味酸，微苦咸。阴中微阳。入足少阴、手太阴血分，足少阴气分。主益气者，肺主诸气，酸能收，正入肺补肺，故益气也。其主咳逆上气者，气虚则上壅而不归元，酸以收之，摄气归元则咳逆上气自除矣。劳伤羸瘦，补不足，强阴，益男子精。《别录》养五脏，除热，生阴中肌者，五味子专补肾，兼补五脏。肾藏精，精盛则阴强，收摄则真气归元而丹田暖，腐熟水谷，蒸糟粕而化精微，则精自生，精生则阴长，故主如上诸疾也。《药性论》云：五味子，君，能治中下气，止呕逆，补诸虚劳，令人体悦泽，除热气，病人虚而有气兼嗽者，加而用之。日华子云：暖水脏，下气，贲㹠冷气，消水肿，反胃，心腹气胀，止渴，除烦热，解酒毒，壮筋骨，皆其极功也。\n\n【主治参与】\n同人参、麦门冬，名生脉散，能复脉通心。\n\n入八味丸，代附子，能润肾强阴。\n\n同吴茱萸、山茱萸、肉豆蔻、补骨脂、人参，治肾泄良。\n\n同怀干地黄、甘枸杞子、车前子、覆盆子、肉苁蓉、白胶、麦门冬、人参、杜仲、白蒺藜、黄檗，主令人有子。\n\n同天麦二冬、百部、阿胶、薄荷叶，主肺虚久嗽。\n\n君干葛、白扁豆，解酒毒良。\n\n【简误】\n        痧疹初发，及一切停饮，肝家有动气，肺家有实热，应用黄芩泻热者，皆禁用。', NULL, NULL, NULL, '五味子', NULL, '17、五味子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291663, 'E13F0586B53D7FDA6817BBC4A11937F1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7215, 413, 400105716, '       味苦，寒，无毒。主寒湿风痹，黄疸，补中，止血，内崩下血，膀胱不足，踒跌，蛊毒。久服益精气，轻身。\n\n       疏：茜根禀土与水之气，而兼得天令少阳之气以生。\n\n      《本经》味苦寒。甄权云甘。洁古微酸，咸温无毒。盖尽之矣。入足厥阴、手足少阴，行血凉血之要药也。非苦不足以泄热，非甘不足以和血，非咸不足以入血软坚，非温少阳之气不足以通行。故主痹及疸。疸有五，此其为治，盖指蓄血发黄，而不专于湿热者也。痹者血病，行血软坚则痹自愈。甘能益血而补中，病去血和，补中可知已。苦寒能下泄热气，故止内崩及下血，除热故益膀胱。踒跌则血瘀，血行则踒跌自安。凉无病之血，行已伤之血，故治蛊毒。\n\n《药性论》味甘，主六极伤心肺，吐血泻血。\n\n日华子：味酸，止鼻洪，带下，产后血晕，乳结，月经不止，肠风痔瘘，排脓，治疮疖，泄清尿血，扑损瘀血，皆取其凉血行血，苦寒泄热之功耳。\n\n【主治参与】\n同地黄、麦门冬、当归身、阿胶、茅根、童便，主吐血，衄血，诸血热妄行溢出上窍。\n\n同牛膝、地黄、黄耆、地榆、芍药、荆芥穗，治肠风下血。\n\n佐地榆，治横痃鱼口，有神。\n\n同䗪虫、乳香、没药、桂心、牛膝、地黄，主踒跌。\n\n【简误】\n       病人虽见血证，若加泄泻，饮食不进者，勿服。', NULL, NULL, NULL, '茜根', NULL, '16、茜根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291664, '39BA5A8959633A48AD301401E1D92653', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7216, 413, 400105715, '      味苦，微寒，无毒。主心腹邪气，肠鸣幽幽如走水，寒热积聚，破癥除瘕，止烦满，益气养血，去心腹痼疾结气，腰脊强，脚痹，除风邪留热。久服利人。（畏咸水，反藜芦。）\n\n       疏：丹参，《本经》味苦，微寒。陶云：性热无毒。观其主心腹邪气，肠鸣幽幽如走水，寒热积聚，破癥除瘕，则似非寒药。止烦满，益气，及《别录》养血，去心腹痼疾结气，腰脊强，脚痹，除风邪留热，久服利人，又决非热药。当是味苦平微温。入手足少阴、足厥阴经。心虚则邪气客之，为烦满结气，久则成痼疾。肝虚则热甚风生。肝家气血凝滞，则为癥瘕。寒热积聚，肾虚而寒湿邪客之，则腰脊强，脚痹。入三经而除所苦，则上来诸证自除。苦能泄，温能散，故又主肠鸣幽幽如走水。久服利人，益气养血之验也。北方产者胜，俗名逐马。\n\n【主治参与】\n入天王补心丹则补心。\n\n同牛膝、地黄、黄耆、黄檗，则健步。\n\n同当归、牛膝、细辛，则下死胎。\n\n同鳖甲、牡蛎、牡丹皮、青蒿、延胡索、牛膝、干膝、水赤蓼子，主寒热积聚，破癥除瘕，心腹痼疾结气。\n\n同麦门冬、沙参、五味子、甘草、青蒿、栝楼，止烦满。\n\n同人参、麦门冬、酸枣仁、地黄，益气养血。\n\n同牛膝、萆薢、木瓜、狶莶、杜仲、续断，主腰脊强，脚痹，除风邪留热。\n\n《圣惠方》：独用一两为末，热酒每服二钱，主寒疝，少腹及阴阳引痛，自汗出欲死。\n\n《千金方》治堕胎下血，亦独用丹参十二两，酒五升，煮取三升，温服，日三。\n\n萧炳云：酒浸服之，治风软脚，可逐奔马，故名奔马草。曾用有效。\n\n《梅师方》治中热油及火烧，除外痛，用丹参八两细剉，以水微调，取羊脂二斤，煎，三上三下，以傅疮上。\n\n【简误】\n      妊娠无故，勿服。', NULL, NULL, NULL, '丹参', NULL, '15、丹参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291665, '134BC29C580B74052B461C5EC8B49441', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7217, 413, 400105714, '       味咸、苦、甘，平，微寒，无毒。主青盲，目淫肤，赤白膜，眼赤痛泪出，疗唇口青。多服益精光，轻身。\n\n       疏：决明子得水土阴精之气，而兼禀乎清阳者也。故其味咸平。《别录》益以苦甘、微寒而无毒。咸得水气，甘得土气，苦可泄热，平合胃气，寒能益阴泄热，足厥阴肝家正药也。亦入胆肾。肝开窍于目，瞳子神光属肾，故主青盲，目淫肤、赤白膜，眼赤痛泪出。《别录》兼疗唇口青，《本经》久服益精光，轻身者，益阴泄热，大补肝肾之气所致也。亦可作枕，治头风，明目。\n\n【主治参与】\n得沙苑蒺藜、甘菊花、枸杞子、生地黄、女贞实、槐实、谷精草，补肝明目益精，除肝脏热之要药。\n\n得生地黄、甘菊花、荆芥、黄连、甘草、玄参、连翘、木通，治暴赤风眼泪痛。\n\n疗目疾外无他用，故无 “简误”。', NULL, NULL, NULL, '决明子', NULL, '14、决明子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291666, '3A90755AD16FFF7A2DE78E17EA962DE1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7218, 413, 400105713, '        味甘，寒，无毒。主瘀血，血瘕欲死，下血，止血，利小便，除小虫，去痹，除胸中结热，止烦渴，逐水，大吐下。久服轻身耐老。（垣衣为之使。）\n\n       疏：天名精禀天地清阳之气，故味甘辛，气寒而无毒。阴入血，甘亦入血，辛能散结，寒能除热，故主瘀血，血瘕欲死，下血，止血。小便不利，由于内热，除热则小便自利也。小虫者，湿热所生也，辛寒能散湿祛热，则小虫自除也。除痹者，去湿之功也。除胸中结实，止烦渴，祛热散结益阴之功也。逐水者，湿热散，则水自消也。\n\n      《唐本》注云：即鹿活草也。\n\n    《别录》一名天蔓精。南人呼为地菘。非鹤虱，亦非狶莶，乃荔枝草也。为消痔疮之圣药。味甘辛，故有姜称。其主破血，生肌，利小便，杀三虫，除诸毒肿，疔疮瘘痔，金疮内射，身痒瘾疹不止者，揩之立已，凉血除热散结之力也。\n\n【简误】\n        脾胃寒薄，性不喜食冷，易泄，无渴者，勿服。', NULL, NULL, NULL, '天名精', NULL, '13、天名精', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291667, 'EF4B7E1EACCBB958BA86CDC8093333CF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7219, 413, 400105712, '       味酸，温、微寒，无毒。主痈疽恶疮，结肉跌筋，败疮热气，阴蚀不瘳，利关节。久服轻身益气。\n\n根：止泄痢腹痛，五藏客热，除邪逆气，疽癞诸恶疮，金疮伤挞，生肉复肌。\n\n        疏：营实华于春而实于夏，味酸得木之化。其气芬芳，宜其有温之义。《别录》微寒，以其得春之气也，故无毒。其主恶疮，结肉跌筋，败疮热气，阴蚀不瘳，利关节。《别录》止泄痢腹痛，五脏客热，除邪逆气，疽癞诸恶疮，金疮伤挞，生肉复肌。岂非酸能收敛，温能通畅，微寒能除热，而兼主乎发生之用也？俗名蔷薇，白花野者良。\n\n【主治参与】\n葛洪：治金疮发热，用蔷薇根灰一方寸匕，日三。\n\n《外台秘要》治鲠：蔷薇根末，水服方寸匕，日三。\n\n又方：治少小睡中遗尿不自觉：以蔷薇根剉，以酒饮之。\n\n《肘后方》：治口疮，以根煮浓汁，温含，冷易，神验。\n\n用之颇稀，不著 “简误”。', NULL, NULL, NULL, '营实', NULL, '12、营实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291668, 'FB8515866F33AAAC94EF5DBA456D11A2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:34', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7220, 413, 400105711, '        味苦、咸，寒，大寒，无毒。主皮肤热，恶疮疽痔，湿痹，下乳汁，止遗溺，热气疮痒如麻豆，可作浴汤。久服轻身益气，耳目聪明，不老延年。\n\n        疏：漏芦得地味之苦咸，禀天气之大寒，故无毒。苦能下泄，咸能软坚，寒能除热。入足阳明、少阳、太阳，手太阴、阳明。寒而通利之药也，故主皮肤热，恶疮疽痔，湿痹，下乳汁。《别录》又主止遗溺，热气疮痒如麻豆，可作浴汤。又《本经》久服轻身益气，耳目聪明，不老延年者，盖亦通指热散病除，则脏腑自安，精神自倍，而臻乎寿考也。\n\n【主治参与】\n漏芦同贝母、连翘、甘草、金银花、橘叶、鼠粪、白芷、山豆根、山茨菇、夏枯草，治乳岩、乳痈。\n\n同连翘、生甘菊、紫花地丁、贝母、金银花、甘草、夏枯草，治发背，瘰疬，排脓止痛。\n\n同黄耆、人参，排脓长肉。加狗蹄、猪蹄汁，能下乳。\n\n【简误】\n        妊娠禁用。疮疡阴证，平塌不起发者，真气虚也，法当内塞。漏芦苦寒，非所宜设。', NULL, NULL, NULL, '漏芦', NULL, '11、漏芦', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291669, '52D4DA2F6344FF74DE96AD50156D8662', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:35', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7221, 413, 400105710, '      味苦、辛，微温，无毒。主伤寒，补不足，金疮痈伤，折跌，续筋骨，妇人乳难，崩中漏血，金疮血内漏，止痛生肌肉，及踠伤恶血，腰痛，关节缓急。久服益气力。（地黄为之使）\n\n      疏：续断得土金之气，而兼禀乎天之阳气以生。《本经》味苦微温，《别录》益之以辛。曾得蜀中者，尝之，其味带甘，应云味苦甘辛，微温无毒。使非味甘，焉能主伤中、补不足？非辛焉能主金疮痈伤，折跌，续筋骨，妇人乳难？辛能润，苦温能散，甘能益血。故《别录》又主崩中漏血，金疮血内漏，止痛生肌肉，及踠伤恶血、腰痛，关节缓急。《本经》久服益气力，伤去血生之效也。入足厥阴、少阴，为治胎产，续绝伤，补不足，疗金疮，理腰肾之要药。茎方，叶似苎，相对生。\n\n【主治参与】\n欲行血理伤，当以当归、牛膝、肉桂、延胡索同用。\n\n欲止血，补不足，疗崩中，则与白胶、阿胶、地黄、麦门冬、杜仲、五味子、山茱萸、人参、枸杞子、黄耆同用。\n\n欲安胎，则与凉血、补血、顺气药同用。\n\n欲疗金疮，则与金疮药同用。\n\n【简误】\n        禁与苦寒药同用以治血病，及与大辛热药用于胎前。雷公云：草茆根，真似续断，误服之，令人筋软。\n', NULL, NULL, NULL, '续断', NULL, '10、续断', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291670, '7339F129C9C03448CC5F0D2F898E5923', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:35', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7222, 413, 400105709, '       味甘，平，无毒。主心腹、膀胱寒热，利小便，止血，消瘀血。久服轻身，益气力，延年神仙。\n\n        疏：蒲黄得地之阴气，兼得金之辛味。其言甘平者，是兼辛而言也，非辛则何以能散邪？又禀天之阳气，故曰微寒而无毒也。如是则甘能和血，辛能散结，微寒能除热。入手少阴、太阳、太阴，足阳明、厥阴。故主心腹、膀胱寒热，利小便，止血，消瘀血。久服轻身、益气力者，是血热、瘀血、伤损之病去，而身轻力长也。欲止血，熟用；欲消血，生用。产泰州。\n\n【主治参与】\n得炒黑干姜、炒黑豆、泽兰、当归、川芎、牛膝、生地黄，治产后诸血病。\n\n同车前子、牛膝、生地黄、麦门冬，治溺血。\n\n同阿胶、白胶、人参、麦门冬、赤茯苓、车前子、杜仲、川续断，治血崩、血淋。\n\n生纳舌下，数数易之，消重舌。\n\n治一切跌扑伤损，瘀血停滞腹中，生蒲黄煮浓，和童便饮之良。\n\n能破血，故治癥结，五劳七伤，停积瘀血，胸前痛，即发吐衄，悉和凉血行血药主之。\n\n【简误】\n        一切劳伤发热，阴虚内热，无瘀血者禁用。', NULL, NULL, NULL, '蒲黄', NULL, '9、蒲黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291671, '202BA1C17E229E9E6C055C48B44430C7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:35', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7223, 413, 400105708, '      味甘、辛，温，无毒。主大风，头眩痛，恶风风邪，目盲无所见，风行周身，骨节疼痹，烦满，胁痛，胁风，头面去来，四肢挛急，字乳金疮内痉。久服轻身。\n叶：主中风热汗出。\n\n        疏：防风禀天地之阳气以生，故味甘温。《别录》兼辛而无毒。气厚味薄，升也，阳也。入手阳明，足少阴、厥阴。风药也，治风通用，升发而能散，故主大风，头眩痛，恶风风邪，周身骨节疼痹，胁痛胁风，头面去来，四肢挛急，字乳金疮因伤于风内痉。其云主目无所见者，因中风邪，故不见也。烦满者，亦风邪客于胸中，故烦满也。风寒湿三者，合而成痹。祛风燥湿，故主痹也。发散之药，焉可久服？其曰轻身，亦湿去耳。《别录》云：叉头者，令人发狂，叉尾者，发痼疾。子似胡荽而大，调食用之香，而疗风更优也。\n\n【主治参与】\n防风同黄耆、芍药，则能实表止汗。\n\n同荆芥穗、白芷、生地黄、地榆、黄耆，治破伤风，有神。\n\n同甘草、桔梗、紫苏、桑根白皮、杏仁、细辛，解利伤风。去紫苏，换薄荷，加石膏，兼除风热。\n\n用麻黄易紫苏，治风寒郁于腠理，皮肤致密无汗。\n\n入羌活汤，兼除太阳经伤风寒头痛。\n\n亦入治风痹药用。若入治大风厉风药中，须加杀虫药、活血药乃可，不宜纯用风药也。\n\n【简误】\n          南方中风、产后血虚发痉，俗名角弓反张。诸病血虚痉急、头痛不因于风寒、溏泄不因于寒湿、二便秘涩、小儿脾虚发搐、慢惊、慢脾风、气升作呕、火升发嗽、阴虚盗汗、阳虚自汗等病，法所同忌。犯之者增剧。', NULL, NULL, NULL, '防风', NULL, '8、防风', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626377492291672, 'C5135BBF12A739AA85B87BE6A1C53E14', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 09:16:35', 1, 'admin', '2024-12-25 09:16:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7224, 414, 400105808, '      味苦，温、微温，无毒。主中风伤寒头痛，温疟，发表出汗，去邪热气，止咳逆上气，除寒热，破癥坚积聚，五藏邪气缓急，风胁痛，字乳馀疾，止好唾，通腠理，疏伤寒头疼，解肌，泄邪恶气，消赤黑斑毒。不可多服，令人虚。\n\n      疏：麻黄禀天地清阳刚烈之气，故《本经》味苦，其气温而无毒。详其主治，应是大辛之药。\n\n     《药性论》加甘，亦应有之。气味俱薄，轻清而浮，阳也，升也。手太阴之药，入足太阳经，兼走手少阴、阳明。轻可去实，故疗伤寒，为解肌第一。专主中风伤寒头痛，温疟，发表出汗，去邪热气者，盖以风寒湿之外邪，客于阳分皮毛之间，则腠理闭拒，荣卫气血不能行，故谓之实。此药轻清成象，故能去其壅实，使邪从表散也。咳逆上气者，风寒郁于手太阴也。寒热者，邪在表也。五脏邪气缓急者，五缓六急也。风胁痛者，风邪客于胁下也。斯皆卫实之病也。卫中风寒之邪既散，则上来诸证自除矣。其曰消赤黑斑毒者，若在春夏，非所宜也。破癥坚积聚，亦非发表所能。洁古云：去荣中寒邪，泄卫中风热，乃确论也。多服令人虚，走散真元之气故也。\n\n【主治参与】\n仲景治伤寒，有麻黄汤，大、小青龙汤。治肺病上气，有射干麻黄汤，厚朴麻黄汤。\n\n同石膏、杏仁、桑白皮、甘草，治寒邪郁于肺经，以致喘满咳嗽。\n\n仲景治少阴病发热脉沉，有麻黄附子细辛汤及麻黄附子甘草汤。\n\n同桂可治风痹冷痛。\n\n蜜炒麻黄，治冬月疮疱为风寒所郁，以致倒靥喘闷，一服立解。\n\n【简误】\n       麻黄轻扬发散，故专治风寒之邪在表，为入肺的要药。然其味大辛，气大热，性轻扬善散，亦阳草也，故发表最速。若夫表虚自汗，阴虚盗汗，肺虚有热，多痰咳嗽，以致鼻塞；疮疱热甚不因寒邪所郁而自倒靥；虚人伤风，气虚发喘，阴虚火炎，以致眩晕头痛；南方中风瘫痪，及平日阳虚，腠理不密之人，皆禁用。汗多亡阳，能损人寿，戒之！戒之！自春深夏月，以至初秋，法所同禁。', NULL, NULL, NULL, '麻黄', NULL, '8、麻黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265670, '2C6EA4397453D2A31C998B2BDD2A86DB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7225, 414, 400105807, '        味甘、辛，温、大温，无毒。主咳逆上气，温疟寒热洗洗在皮肤中，妇人漏下绝子，诸恶疮疡，金疮，煮饮之。温中止痛，除客血，内塞，中风痓（作痉），汗不出，湿痹，中恶客气，虚冷，补五藏，生肌肉。（恶䕡茹、面。畏菖蒲、海藻、牡蒙。）\n\n         疏：当归禀土之甘味，天之温气。《别录》兼辛，大温，无毒。甘以缓之，辛以散之润之，温以通之畅之。入手少阴，足厥阴，亦入足太阴。活血补血之要药，故主咳逆上气也。温疟寒热洗洗在皮肤中者，邪在厥阴也，行血则厥阴之邪自解，故寒热洗洗随愈也。妇人以血为主，漏下绝子，血枯故也。诸恶疮疡，其已溃者温补内塞，则补血而生肌肉也。金疮以活血补血为要，破伤风亦然，并煮饮之。内虚则中寒，甘温益血，故能温中。血凝则痛，活血故痛自止。血溢出膜外，或在肠胃，曰客血。得温得辛则客血自散也。内塞者，甘温益血之效也。中风痉，痉即角弓反张也。汗不出者，风邪乘虚客血分也。得辛温则血行而和，故痉自柔而汗自出也。痹者，血分为邪所客，故拘挛而痛也。风寒湿三者合而成痹，血行则邪不能客，故痹自除也。中恶者，内虚，故猝中于邪也。客气者，外来之寒气也，温中则寒气自散矣。虚冷者，内虚血不荣于肉分，故冷也。补五脏、生肌肉者，脏皆属阴，阴者血也，阴气足则荣血旺而肌肉长也。患人虚冷，加而用之。\n\n【主治参与】\n同川芎、芍药、地黄，名四物汤，主妇人血分百病。加炒黑干姜、炒黑豆、泽兰、牛膝、益母草、蒲黄，治妇人产后百病。\n\n同桂枝、术、菊花、牛膝，主痹。\n\n同牛膝、鳖甲、橘皮、生姜，治疟在阴分久不止。\n\n同酸枣仁、远志、人参、茯神，治心血虚不得眠。\n\n同黄耆、生熟地黄、黄芩、黄连、黄檗，治盗汗。\n\n同荆芥、白芷、芎、地黄，治破伤风。\n\n同续断、牛膝、杜仲、地黄、鹿角屑、桂，治一切折伤踠跌，挫闪作疼。\n\n同川芎、人参，治难产及倒生。\n\n同益母草、红蓝花、蒲黄、牛膝，治产后血上薄心。\n\n同白胶、地黄、芍药、续断、杜仲，治妇人血闭无子。\n\n同地榆、金银花、滑石、红曲，治滞下纯血，里急后重。\n\n【简误】\n       当归性辛温，虽能活血补血，终是行走之性，故致滑肠。又其气与胃气不相宜，故肠胃薄弱，泄泻溏薄，及一切脾胃病，恶食不思食，及食不消，并禁用之。即在产后胎前，亦不得入。', NULL, NULL, NULL, '当归', NULL, '7、当归', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265671, '194F830BF6621FD652DC4D5CE100F451', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7226, 414, 400105806, '     味苦，寒，无毒。主心腹结气，癥瘕积聚，黄疸，溺有余沥，逐水除痈肿。补中，明目止泪，养肝胆气，安五藏，定志，益精，利九窍，除伏热肠澼，止渴醒酒，小便黄赤，疗恶疮下部䘌，平胃气，令人嗜食，轻身。（玄参为之使，恶贝母、漏芦、菟丝子，反藜芦）\n\n      疏：苦参禀天地阴寒之气而生，其味正苦，其气寒而沉，纯阴无毒。足少阴肾经君药也。苦以燥脾胃之湿，兼泄气分之热，寒以除血分之热。热则生风，风湿合则生虫，故主心腹结气，癥瘕积聚，黄疸，溺有余沥，逐水，除痈肿，明目止泪，利九窍，除伏热，肠澼，止渴醒酒，小便黄赤，疗恶疮，下部䘌疮。胃家湿热盛，则口淡不思食，食亦不生肌肉。湿热散则胃气平和而令人嗜食矣。其曰补中养肝胆气、安五脏、定志、益精、轻身者，通指热散湿除，则脏腑气血安和而致然也。味既至苦，性复阴寒，善能杀虫，故《药性论》治热毒风，皮肌烦躁生疮，赤癞眉脱，主除大热嗜睡。\n\n【主治参与】\n腊月米醋渍，入瓮中封固。主一切天行热病，头疼口渴身热，甚者发狂：饮碗许，得吐则愈。汗亦如之。\n\n同胡麻、刺蒺藜、荆芥穗、甘菊花、狶莶、白芷、当归、川芎、地黄、天门冬、何首乌、牛膝、漆叶、秦艽、龙胆草，治大麻风。\n\n同牡蛎粉、白术、青黛，治童子胃热，羸瘦疳蛔。\n\n同龙胆草为末，牛胆和丸梧子大，生大麦汤服五丸，日三。治谷疸，食劳头旋，心怫郁不安，而发黄疸，由失饥大食，胃气湿热冲熏所致。\n\n《集验方》治热毒足肿疼欲脱，酒煮苦参以渍之。\n\n【简误】\n       苦参虽能泄血中之热，除湿热生虫为疠，然以其味大苦，气大寒，久服能损肾气。肝肾虚而无大热者，勿服。', NULL, NULL, NULL, '苦参', NULL, '6、苦参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265672, 'CD1F6C49D012C327C20D6EA750E57012', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7227, 414, 400105805, '       味苦，寒，无毒。主消渴身热，烦满大热，补虚安中，续绝伤，除肠胃中痼热，八疸身面黄，唇干口燥，短气，通月水，止小便利。\n\n实名黄瓜，主胸痹，悦泽人面。\n\n茎叶：疗中热伤暑。\n\n枸杞子为之使，恶干姜，畏牛膝，干漆，反乌头。\n\n      疏：栝楼根禀天地清寒之气，故味苦气寒而无毒。能止消渴身热，烦满大热。热散则气复，故又主补虚安中。凉血则血和，故主续绝伤，并除肠胃中痼热。苦寒能除热，故主八疸身面黄，唇干口燥，短气。血凉则不瘀，故通月水。膀胱热解则小便不频，故能止小便利。黄瓜主胸痹及伤寒结胸，悦泽人面。栝楼仁主消痰。茎叶疗中热伤暑者，皆以其清寒散热故也。\n\n【主治参与】\n根同贝母、竹沥、竹茹、荆沥、天门冬，清痰。\n\n同金银花、连翘、贝母、白及、甘草，消一切肿毒。\n\n实同黄连、枳实，为小陷胸汤。治伤寒虚结胸。\n\n【简误】\n        脾胃虚寒作泄者，勿服。', NULL, NULL, NULL, '栝蒌根,栝楼根', NULL, '5、栝蒌根,栝楼根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265673, '79D3791C035BF171B15A3A434F65492C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7228, 414, 400105804, '      味甘，平，无毒。主消渴，身大热，呕吐，诸痹，起阴气，解诸毒，疗伤寒中风头痛，解肌发表，出汗开腠理，疗金疮止痛，胁风痛。\n生根汁：大寒，疗消渴，伤寒壮热。\n\n葛谷：主下痢，十岁以上。\n\n叶：主金疮，止血。\n\n花：主消酒。\n\n一名鸡荠根，一名鹿霍。（杀野葛、巴豆、百药毒。）\n\n        疏：葛根禀天地清阳发生之气，其味甘平，其性升而无毒。入足阳明胃经，解散阳明温病热邪之要药也。故主消渴，身大热，热壅胸膈作呕吐。发散而升，风药之性也，故主诸痹。生气升腾，故起阴气。甘者，土之冲气，春令少阳，应兼微寒，故解诸毒及《别录》疗伤寒中风头痛，解肌发表，出汗开腠理。甘能和血而除热，故又主疗金疮止痛，及胁风痛也。\n\n【主治参与】\n葛根汤，治阳明胃经温病，邪热头疼，发渴烦闷，鼻干不得眠。如渴甚、呕甚，则加石膏、麦门冬、知母、竹叶。\n\n葛根升麻汤，治斑疹初发，点粒未形。\n\n同一切补肾益精药作丸饵，则起阴，令人有子。\n\n同升麻，入升阳散火、升阳除湿、升阳益胃、清暑益气、补中益气等汤用。\n\n【简误】\n       伤寒头痛，兼项强腰脊痛，及遍身骨疼者，足太阳也。邪犹未入阳明，故无渴证，不宜服。五劳七伤，上盛下虚之人，暑月虽有脾胃病，不宜服。', NULL, NULL, NULL, '葛根,鸡荠根，鹿霍', NULL, '4、葛根,鸡荠根,鹿霍', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265674, '4500425F7DEF61070AE4CBED940200CD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7229, 414, 400105803, '         味苦、甘，温。叶：味苦、辛，微寒，有小毒。主风寒头痛，风湿周痹，四肢拘挛痛，恶肉死肌，膝痛，溪毒。久服益气，耳目聪明，强志轻身。\n\n        疏：葈耳，苍耳也。得土之冲气，兼禀天之春气，故味甘温，而《别录》益之以苦，当是无毒。叶味苦辛，微寒有小毒。苦以燥湿，甘以和血，温则通畅。春气发生而升，故主风寒头痛、风湿周痹、四肢拘挛，恶肉死肌、膝痛、溪毒也。祛风疗湿之药。《食疗》、《圣惠》、《千金》、《外台秘要》诸方，咸堪选用，亦无 “简误”。', NULL, NULL, NULL, '葈耳实,苍耳,苍耳子', NULL, '3、葈耳实,苍耳,苍耳子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265675, 'BF690BF31A0FA11405DB6DC4BCE0A392', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7230, 414, 400105802, '      味辛，微温。主伤寒头痛鼻塞，咳逆上气，止呕吐。久服去臭气，通神明。\n\n疏：生姜所禀与干姜性气无殊。第消痰止呕，出汗散风，祛寒止泄，疏肝导滞，则功优于干者。\n\n“主治”、“简误”，并与前同。', NULL, NULL, NULL, '生姜', NULL, '2、生姜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265676, '59F8A02779C4E40E938126AC4FCA6BCA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7231, 414, 400105801, '      味辛，温、大热，无毒。主胸满，咳逆上气，温中止血，出汗，逐风湿痹，肠澼下痢，寒冷腹痛，中恶霍乱胀满，风邪诸毒，皮肤间结气，止唾血。生者尤良。\n\n疏：干姜禀天地之阳气，故味辛而气温，虽热而无毒。辛可散邪理结，温可除寒通气，故主胸满咳逆上气，温中出汗，逐风湿痹，下痢因于寒冷，止腹痛。其言止血者，盖血虚则发热，热则血妄行，干姜炒黑，能引诸补血药入阴分，血得补则阴生而热退，血不妄行矣。治肠澼亦其义也。生姜能通神明，辟恶气，故主中恶霍乱胀满，风邪诸毒，皮肤间结气。惟唾血定非寒证，《别录》载之误矣！\n\n【主治参与】\n干姜生用，同橘皮、乌药、白豆蔻，除胸满咳逆上气。\n\n同紫苏、桂枝，能温中出汗。加术则能逐风湿痹。\n\n同术、茯苓、人参、甘草、治下利寒冷腹痛。\n\n炒黑，同生地黄、白芍药、当归、牛膝，治产后恶露不尽，血虚发热。\n\n同地黄、地榆、芍药、麦门冬、人参、黄耆、甘草、升麻，治肠澼下血。\n\n同藿香、缩砂、橘皮、紫苏、木香，治中恶。去木香，加木瓜，则治霍乱胀满。加桂枝，并治风邪诸毒，皮肤间结气。\n\n同橘皮、人参，止胃虚呕逆。\n\n同橘皮、术、贝母、茯苓，治痰疟久不愈。\n\n同人参、术、桂枝、橘皮，治寒疟。\n\n同人参、术、甘草，治虚寒泄泻，中寒作泄。\n\n【简误】\n      干姜大辛，辛能散气走血。久服损阴伤目。阴虚内热，阴虚咳嗽吐血，表虚有热汗出，自汗盗汗，脏毒下血，因热呕恶，火热腹痛，法并忌之。', NULL, NULL, NULL, '干姜', NULL, '1、干姜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626418042265677, '9EAE3CD416389E8FF6141C687D89F70C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 12:01:34', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7232, 414, 400105831, '      味苦，大寒，无毒。主疗时气头痛，大热口疮。\n\n        疏：大青禀至阴之气，故味苦，气大寒、无毒。甄权云：大青臣，味甘，能去大热，治温疫寒热。盖大寒兼苦，其能解散邪热明矣。《经》曰：大热之气，寒以取之，此之谓也。时行热毒头痛，大热口疮，为胃家实热之证，此药乃对病之良药也。\n\n【主治参与】\n《千金方》小儿口疮：大青十八铢，黄连十二铢，水三升，煮一升。日二服，以瘥为度。\n\n《肘后方》热病下利困笃者，大青汤。大青四两，甘草、赤石脂各三两，豉八合，水一斗，煮三升，分三服，不过二剂瘥。\n\n《保幼大全》方：小儿卒然肚皮青黑，乃血气失养，风寒乘之，危恶之候也。大青为末，纳口中，以酒送下。\n\n【简误】\n        大青乃阴寒之物，止用以祛除天行热病，而不可施之虚寒脾弱之人。\n', NULL, NULL, NULL, '大青', NULL, '31、大青', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042949, '0FC2220972A14794C025D95053D0A30A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7233, 414, 400105830, '       味苦、咸，平、大寒，无毒。主暴中风，身热支满，忽忽不知人，狂惑邪气，寒热酸疼，温疟洗洗，发作有时。疗伤中淋露，下水气，利阴气，益精。久服利人。\n\n       疏：白薇全禀天地之阴气以生，《本经》味苦咸平。\n\n   《别录》益之以大寒，无毒可知已。暴中风、身热支满者，阴虚火旺则内热，热则生风，火气烦灼，故令支满。火旺内热，则痰随火涌，故令神昏忽忽不知人也。狂惑邪气，寒热酸疼，皆热邪所致也。阴气不足，则阳独盛而为热，心肾俱虚，则热收于内而为寒，此寒热之所以交作。寒热作则荣气不能内荣，是以肢体酸疼也。先热而后寒者名曰温疟。疟必因暑而发，阴气不足则能冬不能夏，至夏而为暑邪所伤，秋必发为温疟。故知温疟之成，未有不由阴精不守而得者。若夫阴精内守，则暑不能侵，疟何自而作耶？上来诸证，皆由热淫于内之所发。\n\n  《经》曰：热淫于内，治以咸寒。此药味苦咸而气大寒，宜其悉主之也。\n\n《别录》疗伤中淋露者，女子荣气不足则血热，血热故伤中，淋露之候显矣。除热益阴，则血自凉，荣气调和，而前证自瘳也。水气亦必因于湿热，能除热则水道通利而下矣。终之以益精者，究其益阴除热功用之全耳。\n\n【主治参与】\n妇人调经种子方中，往往用之。不孕缘于血少血热，其源必起于真阴不足。真阴不足则阳胜而内热，内热则荣血日枯，是以不孕也。益阴除热则血自生旺，故令有孕也。其方以白薇为君，佐以地黄、白芍药、当归、苁蓉、白胶、黄檗、杜仲、山茱萸、天麦门冬、丹参，蜜丸，久服可使易孕。\n\n凡温疟、瘴疟，久而不解者，必属阴虚，除疟邪药中，多加白薇主之则易瘳。\n\n凡治似中风证，除热药中，亦宜加而用之良。\n\n天行热病得愈，或愈后阴虚内热，及余热未除者，随证随经应投药中宜加之。\n\n【简误】\n       白薇苦咸大寒之药，凡伤寒及天行热病，或汗多亡阳，或内虚不思食，食亦不消，或下后内虚，腹中觉冷，或因下过甚，泄泻不止，皆不可服。', NULL, NULL, NULL, '白薇', NULL, '30、白薇', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042950, 'EF8FFDA6D25E44E63201BB26676344DB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7234, 414, 400105829, '        味苦、甘，平，无毒。主腰背痛，强骨节，风寒湿周痹，恶疮不瘳，热气伤中，恚怒，阴痿，失溺，关节老血，老人五缓。（薏苡为之使。畏葵根、大黄、柴胡、前胡。）\n\n         疏：萆薢得火土之气，而兼禀乎天之阳气，故味苦甘平无毒。阳中之阴，降也。入足阳明、少阴、厥阴。为祛风除湿，补益下元之要药，故主腰背痛，强骨节，风寒湿周痹。恶疮不瘳，热气伤中，恚怒，阴痿，失溺，关节老血，老人五缓，正以苦能燥湿，甘入脾而益血，故悉主之。甄权又主冷风（疒帬）痹，腰脚瘫缓不遂，手足惊掣，男子腰痛久冷，肾间有湿，膀胱宿水。日华子主头旋痫疾，补水脏，坚筋骨，益精明目，中风失音。海藏主肝虚。李氏治白浊，茎中痛，痔漏坏疮。已上诸证，无非阳明湿热，流入下焦，客于肝肾所致。此药祛阳明之湿热，以固下焦，故能去浊分清，而疗下元虚冷，湿邪为病也。\n\n【主治参与】\n得牛膝、木瓜、薏苡仁、黄檗、骨碎补、续断、杜仲、石斛、生地黄、狗脊，治腰脊痛，强骨节。加术、菖蒲、茯苓，治周痹。\n\n同黄芪、生地黄、金银花、皂角刺、皂荚子、牛膝、木瓜、石斛、薏苡仁、海风藤、白僵蚕、胡麻，治恶疮久不瘳。\n\n同莲子、茯苓、车前子、木通、泽泻、牛膝、黄檗、甘草，可分清除湿。\n\n《杨氏家藏方》治真元不足，下焦虚寒，小便频数，白浊如膏，有萆薢分清饮。\n\n又杨子建《万金护命方》云：凡人小便频数，不计度数，便时茎中痛不可忍者，此疾必先大腑不通，水液只就小肠，大腑愈加干竭，甚则浑身热，心躁，如此即重证也。此疾本因贪酒色，积有热毒，腐物瘀血之类，乘虚流入于小肠，故便时作痛也。不饮酒者，必平生过食辛热荤腻之物，又因色伤而然。此乃小便频数而痛，与淋证涩而痛者不同也。宜用萆薢一两，水浸少时，以盐半两同炒，去盐为末。每服二三钱，水一盏，煎八分，和滓服之。使水道转入大肠，仍以葱汤频洗谷道，令气得通，则小便数及痛自减也。\n\n【简误】\n      萆薢本除风湿，若下部无湿，阴虚火炽，以致溺有余沥，茎中痛，此真阴不足之候也。无湿、肾虚腰痛，并不宜服。\n菝葜、土茯苓，与萆薢形虽不同，而主治不甚相远。李氏疑为一物数种，理或然也。总之皆善除湿、祛风、消水，去浊分清，固下焦元气，故能兴阳道而主诸痹，及恶疮不瘳也。“主治” 及 “简误” 并同前。忌茗，醋。', NULL, NULL, NULL, '萆薢', NULL, '29、萆薢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042951, '4351B6E4C493EC5538FF954EB1991A9F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7235, 414, 400105828, '       味辛、苦，温、微温、微寒，无毒。主妇人疝瘕，阴中寒肿痛，腹中急，除风头痛，长肌肤，悦颜色，辟雾露，润泽，疗风邪亸曳，金疮。可作沐药，面脂。\n\n       实：主风流四肢。（恶䕡茹）\n\n      疏：藁本感天之阳气，兼得地之辛味，故味辛气温。\n\n      《别录》兼苦，从火化也。无毒。入足太阳经。温能通，苦能泄，大辛则善散，气厚则上升，阳也。妇人疝瘕，阴中寒肿痛，腹中急，皆太阳经寒湿邪为病也。风头痛者，风中于太阳经也。此药正入本经，故悉主之。凡痈疮皆血热壅滞，毒气浸淫于肌肉，以致溃烂不收。辛散苦泄，则毒散滞消，肌肉自长矣。悦颜色者，即去风作面脂之义也。辟雾露，疗风邪者，辛温芬芳，开发升散之力也。亸曳、金疮，及甄权治一百六十种恶风鬼疰，流入腰痛冷，能化小便，通血，作沐药面脂。日华子去皮肤疵皯，酒齄粉刺。元素主太阳经头痛，颠顶痛，及大寒犯脑，痛连齿颊。东垣主头面身体皮肤风湿。皆风邪湿气干犯太阳经所致也。好古主督脉为病，脊强而厥者，督脉并足太阳经夹脊而上故也。\n\n【主治参与】\n用羌活、细辛、川芎、葱白，治寒邪郁于足太阳经，头痛、颠顶痛，非此不能除。\n\n与木香同用，治雾露、疗清邪中于上焦。\n\n与白芷同作面脂。\n\n治小儿疥癣，煎汤浴之，并以浣衣。\n\n治风，又治湿，各从其类也。\n\n【简误】\n       温病头疼，发热口渴，或骨疼，及伤寒发于春夏，阳证头疼，产后血虚火炎头痛，皆不宜服。', NULL, NULL, NULL, '藁本', NULL, '28、藁本', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042952, 'A59D6FA1159900B8CE71A366B0E5A063', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7236, 414, 400105827, '      味苦、辛，寒、微寒，无毒。主心腹积聚，寒热邪气，通九窍，利大小便，疗肠胃大热，唾血衄血，肠中聚血，痈肿诸疮，止渴益精。（畏辛夷。甄权：主散瘀血，妇人血闭不通。好古：主狂疟，鼽血，血利。苏恭：主金疮。）\n\n      疏：紫参禀地之阴气，兼得天之寒气，故味苦辛，气寒而无毒。气味俱厚，阴也，降也。入足厥阴，亦入足太阳、阳明。专入血分，为除热散结逐血之要药。故主心腹积聚，寒热邪气，通九窍，利大小便，略同紫草也。苦以燥湿泄热，辛以散结，寒以除邪气，故疗肠胃大热，唾血衄血，肠中聚血。亦主痈肿诸疮者，荣气热则留瘀而成痈肿，血凉而活，则自散也。能散瘀血，故主妇人血闭不通。疟有血蓄则狂。阳明热则鼽血。湿热在肠胃，则血瘀滞而成血痢。除热活血，故亦主金疮。\n\n【主治参与】\n仲景《金匮玉函经》：滞下纯血，紫参汤主之。\n\n《圣惠方》治吐血不止：用紫参、阿胶、甘草等分，为末，乌梅汤或糯米汤服一二钱。\n\n【简误】\n         妇人血枯经闭禁用。男子劳伤吐血，阳气虚乏，脾胃弱者禁用。', NULL, NULL, NULL, '紫参', NULL, '27、紫参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042953, '0E370A2EE33AD96F705D11EB5E9BCDCE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7237, 414, 400105826, '      味苦、咸、寒，无毒。主头风，黄疸，咳逆，淋沥，女子阴中肿痛，湿痹死肌，不可屈伸起止行步，疗四肢不安，时行腹中大热饮水，欲走大呼，小儿惊痫，妇人产后余痛。（恶螵蛸、桔梗、茯苓、萆薢）\n\n         疏：白鲜皮禀天地清燥阴寒之气，其味苦寒。\n\n       《别录》兼咸无毒。降多于升，阴也。入足太阴、阳明，兼入手太阳。苦能泄热，寒能除热，故主头风有火证。性寒而燥，能除湿热，故主五疸。咳逆者，实火上冲也。得寒而散，则咳逆止矣。淋沥及女子阴中肿痛，亦皆下部湿热乘虚客肾与膀胱所致也。湿痹死肌，不可屈伸起止行步者，地之湿气，感则害人皮肉筋脉也。脾主四肢，恶湿而喜燥，今为湿邪所干，故四肢不安也。时行腹中大热，因而饮水、大呼欲走者，邪热盛也。小儿惊痫，亦热则生风之候也。散湿除热，蔑不济矣。妇人产后余痛，应是血虚而热，非所宜也。\n\n【主治参与】\n          得牛膝、石斛、薏苡仁、黄檗、苍术，疗足弱顽痹。去下部湿热，多加金银花，佐以汉防己，治下部一切湿疮。\n\n【简误】\n      下部虚寒之人，虽有湿证勿用。', NULL, NULL, NULL, '白鲜皮', NULL, '26、白鲜皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042954, 'AEA878F251A70E8F5C91672F1580E57C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7238, 414, 400105825, '      味苦，微寒，无毒。主疗痰满，胸胁中痞，心腹结气，风头痛，去痰实，下气。治伤寒寒热，推陈致新，明目益精。（半夏为之使。恶皂荚。畏藜芦。）\n\n      疏：前胡得土金之气，而感秋冬之令，故味苦微寒无毒。入手太阴、少阳。阳中之阴，降也。应有甘、辛、平、寒而能降，所以下气，故除痰满，胸胁中痞，心腹结气，痰厥头风痛，去痰下气，治伤寒寒热，推陈致新，能去实热及时气内外俱热。单煮服之，亦治一切气，破痰结，及邪热骨节烦闷，气喘咳嗽，兼散风邪也。\n\n【主治参与】\n同白前、杏仁、桑白皮、甘草、桔梗，能豁风热痰壅，喘嗽下气。\n\n入青礞石滚痰丸中，代黄芩，治一切实痰有殊功，其用黄芩者误也。\n\n同羌活、干葛、柴胡、黄芩、栝楼根，治时疫寒热。\n\n【简误】\n      前胡苦辛微寒之药也，能散有余之邪热实痰，而不可施诸气虚血少之病。故凡阴虚火炽，煎熬真阴，凝结为痰而发咳嗽；真气虚而气不归元，以致胸胁逆满；头痛不因于痰而因于阴血虚；内热心烦，外现寒热而非外感者，法并禁用。明目益精，厥理亦谬。', NULL, NULL, NULL, '前胡', NULL, '25、前胡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042955, '38F452BFF972588D3305B21ACB0AA2F0', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7239, 414, 400105824, '      味苦，寒，无毒。主心腹邪气，五疸，补中益气，利九窍，通水道，疗腹肿胀满痛。以合膏，疗小儿疮及面皶。\n\n      疏：紫草禀天地阴寒清和之气，故味苦气寒而无毒。入足少阴、厥阴。为凉血之圣药，故主心腹邪热之气。五疸者，湿热在脾胃所成，去湿除热利窍，其疸自愈。邪热在内，能损中气，邪热散即能补中益气矣。苦寒性滑，故利九窍而通利水道也。腹肿胀满痛者，湿热瘀滞于脾胃，则中焦受邪而为是病，湿热解而从小便出，则前证自除也。合膏药，疗小儿痘疮及面皶，皆凉血之效也。\n\n【主治参与】\n         同红花子、生地黄、甘草、贝母、牡丹皮，浓煎，加生犀角汁，量儿大小，以四十九匙至半盏为度，治痘疮深红色，或紫、或黑陷干枯，便闭，神效。若在一朝及二朝内，稍有元气，虽危可生。痘疔痘毒咸治之。惟痘毒须加黄耆、金银花、鼠粘子。痘疮夹斑疹者，加硬石膏、麦冬、知母、竹叶。一二剂即去之。\n\n【简误】\n      紫草苦寒而能通利九窍，痘疮家气虚脾胃弱，泄泻不思食，小便清利者，俱禁用。', NULL, NULL, NULL, '紫草', NULL, '24、紫草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042956, 'CD8624B363D405D81B9FC6949557BDB4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7240, 414, 400105823, '    味苦、辛，温，无毒。主咳逆上气，胸中寒热结气，去蛊毒，痿蹷，安五藏，疗咳唾脓血，止喘悸，五劳体虚，补不足，小儿惊痫。（款冬为之使。恶瞿麦、雷丸、远志。畏茵蔯蒿。）\n\n     疏：紫菀感春夏之气化，而兼得地中之金性，故味苦温。《别录》兼辛、无毒。入手太阴，兼入足阳明。苦以泄之，辛以散之，温以行之，辛先入肺，肺主诸气，故主咳逆上气，胸中寒热结气。去蛊毒，亦辛之力也。痿蹷者，阳明之湿热熏蒸于肺，则肺热而津液不能下滴，伤其气化，以困水之上源，故为痿蹷也。肺为五脏之华盖，而主诸气，肺安则能朝百脉，散精布液于各脏，故云安五脏也。疗咳逆吐脓血，止喘悸者，散肺家之邪也。能安五脏，故治五劳及体虚不足。小儿惊痫，亦虚而有热故也，热散则惊痫自止矣。得蜜蒸焙良。\n\n【主治参与】\n《古今传信方》治久嗽：紫菀、款冬花各一两，百部半两，为末作散。每服三钱，生姜三片，乌梅一枚，同煎汤下，食后、临卧各一服。\n\n入噙化丸，治阴虚咳嗽。\n\n《千金方》治妇人卒不得小便：紫菀末，以井花水服三撮，便通。小便血，服五撮便止。\n\n《斗门方》治缠喉风喉闭，饮食不通欲死者，返魂草根一茎，洗净，纳入喉中，取恶涎出即瘥，神效。更以马牙硝津咽之，即绝。根一名紫菀，南人呼为夜牵牛。\n\n《全幼心鉴》治小儿咳嗽声不出者：紫菀末、杏仁泥等分，入蜜同研，丸芡实大，每服一丸，五味子汤化下。\n\n【简误】\n      观其能开喉痹，取恶涎，则辛散之功烈矣。而其性温，肺病咳逆喘嗽，皆阴虚肺热证也，不宜专用及多用，即用亦须与天门冬、百部、麦冬、桑白皮苦寒之药参用，则无害。', NULL, NULL, NULL, '紫菀', NULL, '23、紫菀', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042957, 'B43E24E6A7F65CC6C3CBE87157E22B50', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7241, 414, 400105822, '       味甘，寒，无毒。主劳伤虚羸，补中益气，除瘀血血闭寒热，利小便，下五淋，除客热在肠胃，止渴，坚筋，妇人崩中。久服利人。\n\n       疏：茅根正禀土之冲气，而兼感乎春阳生生之气以生，故其味甘、气寒而无毒。入手少阴，足太阴、阳明。劳伤虚羸必内热，甘能补脾，甘则虽寒而不犯胃，甘寒能除内热，故主劳伤虚羸。益脾所以补中，除热所以益气，甘能益血。血热则瘀，瘀则闭，闭则寒热作矣。寒凉血，甘益血，热去则血和，和则瘀消而闭通，通则寒热自止也。小便不利，由于内热也，热解则便自利。淋者血分虚热所致也，凉血益血则淋自愈，而肠胃之客热自解，津液生而渴亦止矣。肝藏血而主筋，补血凉肝则筋坚矣。血热则崩，凉血和血，崩自愈矣。血热则妄行，溢出上窍为吐，为咯，为鼻衄、齿衄，凉血和血则诸证自除。益脾补中利小便，故亦治水肿、黄疸，而兼理伤寒哕逆也。\n\n【主治参与】\n同麦冬、生地、枸杞子，治劳伤内热。\n\n同生地、麦冬、苏子、枇杷叶、白芍药、甘草、蒲黄、童便，治诸血。\n\n同牛膝、生地黄、童便，治血热经枯而闭。\n\n同竹茹、麦冬、石膏、人参，治伤寒胃热哕逆。\n\n同芍药、赤小豆、赤白茯苓、车前子、薏苡仁、木瓜、石斛、木通，治水肿。\n\n同枇杷叶、竹茹、麦门冬，治火炎内热，反胃上气。\n\n同生地、天麦门冬、车前子、牛膝、白茯苓、黄檗、五味子、枸杞子、童便，治溺血。\n\n【简误】\n      因寒发哕，中寒呕吐，湿痰停饮发热，并不得服。', NULL, NULL, NULL, '茅根', NULL, '22、茅根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042958, 'A004984E37C268309C123ED200F37AE5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7242, 414, 400105821, '     味苦、甘，平、微温，无毒。主腰背强，机关缓急，周痹，寒湿膝痛，颇利老人，疗失溺不节制，男子脚弱腰痛，风邪淋露，少气，目暗，坚脊，利俯仰，女子伤中，关节重。（萆薢为之使，恶败酱。）\n\n      疏：狗脊禀地中冲阳之气，而兼感乎天之阳气，故其味苦，其气平。\n\n    《别录》云甘、微温、无毒，兼火化也。苦能燥湿，甘能益血，温能养气，是补而能走之药也。入足少阴。肾主骨，骨者肾之余也。肾虚则腰背强，机关有缓急之病，滋肾益气血，则腰背不强，机关无缓急之患矣。周痹寒湿膝痛者，肾气不足，而为风寒湿之邪所中也。兹得补则邪散痹除而膝亦利矣。老人肾气衰乏，肝血亦虚，则筋骨不健，补肾入骨，故利老人也。失溺不节，肾气虚脱故也。\n\n   《经》曰：腰者肾之府，动摇不能，肾将惫矣。此腰痛亦指肾虚而为湿邪所乘者言也。气血不足，则风邪乘虚客之也，淋露者，肾气与带脉冲任俱虚所致也。少气者，阳虚也。目得血而能视，水旺则瞳子精明。肝肾俱虚故目暗。女子伤中，关节重者，血虚有湿也。除湿益肾，则诸病自瘳，脊坚，俯仰利矣。\n\n【主治参与】\n得鹿茸、白敛、艾、茯苓、蛇床子，治室女冲、任、带脉三经虚寒，下白带。\n\n得牛膝、菟丝子、地黄、山茱萸、白胶、杜仲，固精强骨，壮腰肾。\n\n得沉香、牛膝、石斛、木瓜、五加皮、白鲜皮、菊花、漆叶、蒺藜子，能通利关节，除五缓六急。\n\n【简误】\n       肾虚有热，小水不利，或短涩赤黄，口苦舌干，皆忌之。', NULL, NULL, NULL, '狗脊', NULL, '21、狗脊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042959, '39427A14932CD2423072749E2C22E1C4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7243, 414, 400105820, '      味苦，平，大寒，无毒。主诸热，黄疸，肠澼泄痢，逐水，下血闭，恶疮疽蚀，火疡，疗痰热，胃中热，小腹绞痛，消谷，利小肠，女子血闭，淋露下血，小儿腹痛。\n其子主肠澼脓血。（山茱萸、龙骨为之使。恶葱实。畏丹砂、牡丹、藜芦。）\n\n      疏：黄芩禀天地清寒之气，而兼金之性，故味苦平无毒。《别录》益之以大寒。味厚气薄，阴中微阳，可升可降，阴也。入手太阴、少阴、太阳、阳明，亦入足少阳。其性清肃，所以除邪；味苦所以燥湿；阴寒所以胜热，故主诸热。诸热者，邪热与湿热也。黄疸、肠澼泄痢，皆湿热胜之病也。折其本则诸病自瘳矣。苦寒能除湿热，所以小肠利而水自逐，源清则流洁也。血闭者，实热在血分，即热入血室，令人经闭不通，湿热解则荣气清而经自行也。恶疮疽蚀者，血热则留结而为痈肿溃烂也。火疡者，火气伤血也，凉血除热则自愈也。\n\n    《别录》消痰热者，热在胸中则生痰，火在少腹则绞痛，小儿内热则腹痛，胃中湿热去，则胃安而消谷也。淋露下血，是热在阴分也。其治往来寒热者，邪在少阳也。五淋者，湿热胜所致也。苦寒清肃之气胜，则邪气自解，是伐其本也。\n\n【主治参与】\n入仲景小柴胡汤，治伤寒寒热，邪在少阳。亦治少阳疟，往来寒热。伤寒心下痞满，泻心汤凡四方，皆用黄芩，以其主诸热、利小肠故也。又太阳病下之，利不止，喘而汗出者，有葛根黄芩黄连汤。又太阴少阳合病下利，黄芩汤。成无己言：黄芩苦而入心，泄痞热，是黄芩能入手少阴、阳明，手足太阴、少阳六经明矣。盖以苦入心，寒胜热，泄心火，去脾湿，则胃火不熏蒸于肺，乃所以救肺也。\n\n同芍药、黄连、炙甘草、车前子、防风、升麻，治湿热作泄腹痛。\n\n同芍药、黄连、炙甘草、滑石、升麻，治滞下腹痛。\n\n洁古：风热有痰，眉眶作痛，酒浸黄芩，同白芷、天麻等分为末，每服二钱，茶调下。\n\n同芍药、麦门冬、白术，能安胎清热。\n\n一切火丹，为细末，鸡子清调傅。又治驴马负重伤破，洗净傅之，主生肌肉。\n\n【简误】\n      黄芩为苦寒清肃之药，功在除热邪，而非补益之品。当与黄连并列。虽能清湿、利热、消痰，然苦寒能损胃气而伤脾阴，脾肺虚热者忌之。故凡中寒作泄，中寒腹痛，肝肾虚而少腹痛，血虚腹痛，脾虚泄泻，肾虚溏泻，脾虚水肿，血枯经闭，气虚小水不利，肺受寒邪喘咳，及血虚胎不安，阴虚淋露，法并禁用。', NULL, NULL, NULL, '黄芩', NULL, '20、黄芩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042960, '1C81B5B3DE9EC68F9BABA7F8201D7995', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7244, 414, 400105819, '      味辛，寒，无毒。主阴痿绝阳，茎中痛，利小便，益气力，强志，坚筋骨，消瘰疬、赤痈，下部有疮，洗出虫。丈夫久服，令人无子。（薯蓣为之使）\n\n      疏：淫羊藿本得金土之气，而上感天之阳气，故其味辛甘，其气温而无毒。\n\n   《本经》言寒者，误也。入手厥阴，为补命门之要药，亦入足少阴、厥阴。可升可降，阳也。辛以润肾，甘温益阳气，故主阴痿绝阳，益气力，强志。茎中痛者，肝肾虚也，补益二经，痛自止矣。膀胱者，州都之官，津液藏焉，气化则能出矣。辛以润其燥，甘温益阳气，以助其化，故利小便也。肝主筋，肾主骨，益肾肝则筋骨自坚矣。辛能散结，甘能缓中，温能通气行血，故主瘰疬赤痈，及下部有疮，洗出虫。丈夫久服令人无子者，因阳旺则阳道数举，频御女而精耗伤，故无子也。一名仙灵脾。柳文作毘。毘者，人脐也。脐为命蒂，故主入命门。修事如雷公法。\n\n【主治参与】\n淫羊藿，阳草也。甘温益阳气，辛则走而能补，宜与白蒺藜、甘枸杞、肉苁蓉、五味子、牛膝、山茱萸同用，为补阳之妙剂。\n\n渍醇酒饮，益丈夫，兴阳道，理腰膝冷，亦治偏风不遂。大约每藿一斤，渍酒十斤，如常法，勿令过醉。修事时忌鸡犬妇人见。\n\n与五味子等分为末，炼蜜丸如梧子大，每三十丸姜茶汤下，治三焦咳嗽，腹满不饮食，气不顺。\n\n《圣济总录》：治目昏生翳，用仙灵脾、生王瓜即小栝楼红色者，等分为末。每服一钱，茶下，日三服。\n\n《百一选方》治病后青盲目，日近者可治，仙灵脾一两，淡豆豉一百粒，水一碗半，煎一碗，顿服即愈。\n\n《普济方》治小儿雀盲：仙灵脾、晚蚕蛾各半两，炙甘草、射干各二钱半，为末，羊肝一枚切开，掺药末二钱，扎定，以黑豆一合，米泔一盏，同煮熟。分二次食，以汁送之。\n\n痘疹入目，用仙灵脾、葳灵仙等分为末，每服五分，米汤下。\n\n【简误】\n        虚阳易举，梦遗不止，便赤口干，强阳不痿，并忌之。', NULL, NULL, NULL, '淫羊藿,仙灵脾', NULL, '19、淫羊藿,仙灵脾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042961, '29085F62C2F0DE10AB2EEB0A41678310', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7245, 414, 400105818, '       味辛，温，无毒。主女人漏下赤白，血闭，阴肿，寒热，头风侵目泪出，长肌肤润泽，可作面脂。疗风邪，久渴（宜作泻），呕吐，两胁满，风痛、头眩、目痒。可作膏药、面脂，润颜色。\n\n         疏：白芷得地之金气，兼感天之阳气，故味辛气温，无毒。其气香烈，亦芳草也。入手足阳明，足太阴。走气分，亦走血分，升多于降，阳也。性善祛风，能蚀脓，故主妇人漏下赤白。辛以散之，温以和之，香气入脾，故主血闭阴肿，寒热，头风侵目泪出。辛香散结而入血止痛，故长肌肤。芬芳而辛，故能润泽。辛香温散，得金气，故疗风邪久泻，风能胜湿也。香入脾，所以止呕吐。疗两胁风痛，头眩目痒，祛风之效也。兼可作膏药、面脂，润颜色，乃祛风散结之余事耳。\n\n【主治参与】\n同芍药、黄耆、当归、地黄、续断、杜仲、益母草、香附、白胶，主漏下赤白。加牛膝，主血闭阴肿寒热。\n\n同甘菊、细辛、藁本、决明子、蒺藜子、荆芥穗、辛夷，治头风侵目泪出。\n\n同黄耆、甘草、地黄、麦冬、五味子，能长肉。\n\n同黄耆、甘草、茜草、皂角刺、金银花、夏枯草、地黄、赤芍药，排脓止痛消痈肿。\n\n同升麻、柴胡、干葛、羌活，治湿泄。\n\n同羌独活、防风、荆芥、蒺藜、胡麻仁、甘菊花、何首乌，治风邪。\n\n同贝母、漏芦、连翘、金银花、夏枯草、蒲公英、紫花地丁、橘皮，消乳痈结核。\n\n《衍义》蚀脓方：白芷一两，单叶红蜀葵根二两，白芍药、白矾烧枯各半两，别研，余俱为细末，黄蜡丸如梧子大。空腹及饭前米饮下十丸或十五丸。俟脓尽，仍别以他药补之。\n\n同雄黄烧，可以辟蛇。\n\n同白芍药治痘疮作痒，及皮肤搔痒。\n\n【简误】\n      白芷性升而温，呕吐因于火者，禁用。漏下赤白，阴虚火炽血热所致者，勿用。痈疽已溃，宜渐减去。', NULL, NULL, NULL, '白芷', NULL, '18、白芷', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042962, '5FF743F33BF5A53B942ADE6481643F68', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7246, 414, 400105817, '      味辛、苦，平，微寒，无毒。主伤寒烦热，淋沥邪气，疝瘕，喉痹，乳难，金疮风痉，疗腹中结实，心下满，洗洗恶风寒。目眩，项直，咳嗽上气，止烦热渴，出汗，安五藏，利骨髓。（厚朴、白薇为之使。畏秦艽。反乌头。）\n\n       疏：贝母在地则得土金之气，在天则禀清肃之令，故味辛平。《别录》兼苦、微寒、无毒。入手太阴、少阴。阴中微阳，可升可降，阴也。色白象金而主肺，肺有热，因而生痰，或为热邪所干，喘嗽烦闷，必此主之。其主伤寒烦热者，辛寒兼苦，能解除烦热故也。淋沥者，小肠有热也。心与小肠为表里，清心家之烦热，则小肠之热亦解矣。邪气者，邪热也。辛以散结，苦以泄邪，寒以折热，故主邪气也。\n\n    《经》曰：一阴一阳结为喉痹。一阴者，少阴君火也；一阳者，少阳相火也。解少阴少阳之热，除胸中烦热，则喉痹自愈矣。乳难者，足厥阴、足阳明之气结滞而不通，辛能散结气，通其结滞则乳难自瘳。热解则血凉，血凉则不痛，故主金疮。热则生风，故主风痉。\n\n   《别录》又疗腹中结实，心下满，洗洗恶风寒者，肺主皮毛也。目眩者，热上攻也。项直即风痉也。咳嗽上气，气上逆也。烦热渴，邪不解，汗不出者，邪热盛也。其性专能散结除热，则上来诸证皆自愈矣。病去则五脏自安，骨髓自利也。\n\n【主治参与】\n同知母、前胡、葛根、麦冬、甘草，治阳明斑疹初发，壮热，喘嗽有痰，不得眠，即《本经》所谓伤寒烦热邪气。\n\n君橘皮、前胡、石膏、知母、麦门冬、竹沥，治痰疟。\n\n同知母、天麦门冬、桑白皮、枇杷叶、百部、桔梗、甘草，治肺热咳嗽及胸中烦热。\n\n同生甘菊、紫花地丁、金银花、白及、白敛、鼠粘子、甘草、夏枯草，治一切热毒，消一切痈疽。\n\n同鼠粘子、玄参、栝楼根、白僵蚕、甘草、桔梗，治风痉。\n\n同郁金、橘叶、连翘、栝楼根、鼠粘子、夏枯草、山茨菇、山豆根、玄参，消一切结核、乳岩、瘰疬。\n\n同百部、百合、薏苡仁、麦冬、苏子、郁金、童便、竹沥、鱼腥草，治肺热吐脓血。\n\n同番降香、郁金、橘红、远志、苏梗、苏子、香附、白豆蔻，开郁痰。加抚芎、神曲，并解一切气郁。\n\n【简误】\n       寒湿痰及食积痰火作嗽，湿痰在胃，恶心欲吐，痰饮作寒热，脾胃湿痰作眩晕，及痰厥头痛，中恶呕吐，胃寒作泄，法应以辛温燥热之药，如南星、半夏、天麻、苍白术、茯苓之类治之者，并禁用。', NULL, NULL, NULL, '贝母', NULL, '17、贝母', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042963, '57E539385EC1FE879170E23CA8EF45CA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7247, 414, 400105816, '       味苦，寒。无毒。主消渴热中，除邪气，肢体浮肿，下水，补不足，益气。疗伤寒，久疟烦热，胁下邪气，膈中恶，及风汗、内疸。多服令人泄。\n\n疏：知母禀天地至阴之气，故味苦气寒而无毒。\n \n     《药性论》兼平，日华子兼甘，皆应有之。入手太阴、足少阴经。苦寒能除烦热，至阴能入骨，故主消渴，热中，除邪气。脾肾俱虚，则湿热客之，而成肢体浮肿，肺为水之上源，肾属水，清热滋肺金，益水脏，则水自下矣。补不足者，清热以滋金水之阴，故补不足。热散阴生，故益气。苦寒至阴之性，烦热得之即解，故疗伤寒，久疟烦热，及胁下邪气。凡言邪者，皆热也。膈中恶，即邪恶之气中于膈中也。风汗者，热则生风，而汗自出也。内疸者，即女劳色疸也。热火既散，阴气即生，故主上来诸证也。多服令人泄者，阴寒之物，其味复苦，多则必伤脾胃生发之气，故作泄也。\n\n【主治参与】\n入白虎汤，解伤寒阳明证。口渴，头疼烦热，鼻干不得眠，加竹叶、麦门冬，名竹叶石膏汤。治阳明经前证，大渴引饮，头疼欲破，因作劳而得者，加人参，名人参白虎汤。汗后烦热不解亦用之。\n\n同麦门冬、石膏、贝母、橘红、鳖甲、青蒿、牛膝，治久疟烦热而渴。\n\n同贝母、天门冬、麦门冬、沙参、甘草、桑白皮、枇杷叶、五味子、百部，治阴虚咳嗽。\n\n同黄檗、车前子、木通、天门冬、生甘草，治强阳不痿。\n\n【简误】\n         阳痿，及易举易痿，泄泻脾弱，饮食不消化，胃虚不思食，肾虚溏泄等证，法并禁用。', NULL, NULL, NULL, '知母', NULL, '16、知母', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042964, '312643DC2C40668AF750737CCA96EDF4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7248, 414, 400105815, '        味甘，平，无毒。主邪气腹胀心痛，利大小便，补中益气，除浮肿胪胀，痞满寒热，通身疼痛，及乳难喉痹，止涕泪。\n\n         疏：百合得土金之气，而兼天之清和，故味甘平，亦应微寒无毒。入手太阳、阳明，亦入手少阴。故主邪气腹胀，所谓邪气者，即邪热也。邪热在腹故腹胀，清其邪热则胀消矣。解利心家之邪热，则心痛自瘳。肾主二便，肾与大肠二经有热邪，则不通利，清二经之邪热，则大小便自利。甘能补中，热清则气生，故补中益气。清热利小便，故除浮肿胪胀，痞满寒热，通身疼痛。乳难，足阳明热也。喉痹者，手少阳三焦，手少阴心家热也。涕泪，肺肝热也。清阳明、三焦、心部之热，则上来诸病自除。\n\n【主治参与】\n仲景治伤寒病百合证，有柴胡百合汤。\n\n同知母、贝母、天门冬、麦门冬、百部、桑根白皮、薏苡仁、枇杷叶，治肺热咳嗽及吐脓血。\n\n同麦门冬、白芍药、甘草、通脱木，利大小便。\n\n同知母、柴胡、竹叶，治寒热邪气，通身疼痛。\n\n同白芍药、炙甘草、麦门冬、五味子，补中益气。\n\n同白芍药、白茯苓、车前子、桑根白皮，治浮肿。\n\n【简误】\n      中寒者勿服。', NULL, NULL, NULL, '百合', NULL, '15、百合', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042965, '554C746F811EB64C055B97D85244F228', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7249, 414, 400105814, '       味苦、辛，平，微温，无毒。主寒热邪气，寒湿风痹肢节痛，下水利小便。疗风，无问新久，通身挛急。\n\n        疏：秦艽感秋金之气，故味苦平，《别录》兼辛、微温而无毒。洁古：气微温，味苦辛，亦可云微寒。阴中微阳，可升可降，降多于升。入手足阳明经。苦能泄，辛能散，微温能通利。故主寒热邪气，寒湿风痹肢节痛，下水利小便。性能祛风除湿，故《别录》疗风无问久新，及通身挛急。能燥湿散热结，故日华子治骨蒸及疳热。\n\n       甄权：治酒疸，解酒毒。元素除阳明风湿，及手足不遂，肠风泻血，养血荣筋。好古泄热益胆气。咸以其除湿散结、清肠胃之功也。\n\n       雷公云：左文列为秦，即治病；右文列为艽，即发脚气。先以布拭上黄肉毛令尽，用还元汤浸一宿，晒干用。\n\n【主治参与】\n秦艽同干葛、山茵蔯、五味子、黄连、白扁豆、木通、苜蓿，治酒疸。\n\n《圣惠方》治小便难，腹满，不急治之，杀人。用秦艽一两，去苗细剉，以水一大盏，煎取七分，去滓。每于食前分为三服。\n\n同薏苡仁、木瓜、五加皮、黄檗、苍术、牛膝，治下部湿热作疼，或生湿疮。\n\n孙真人治黄疸，皮肤眼睛如金色，小便赤，取秦艽五两，牛乳三升，煮取一升，去滓，纳芒硝一两，分作三服。\n\n《正元广利方》疗黄疸，心烦，烦热口干，皮肉皆黄。以秦艽三两，牛乳一大升，同煮，取七合，去滓，分温再服，差。此方出许仁则。\n\n崔元亮《集验方》：凡发背疑似者，须便服秦艽牛膝煎，当即快利三五行，即差。\n\n【简误】\n       下部虚寒人及小便不禁者，勿服。', NULL, NULL, NULL, '秦艽', NULL, '14、秦艽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042966, '2FF30269D8A58477C8370BABC601D29F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7250, 414, 400105813, '     味苦、咸、微寒，无毒。主腹中寒热积聚，女子产乳余疾，补肾气，令人明目。主暴中风伤寒，身热支满，狂邪忽忽不知人，温疟洒洒，血瘕，下寒血，除胸中气，下水，止烦渴，散颈下核，痈肿，心腹痛，坚癥、定五脏。久服补虚明目，强阴益精。（忌犯铜器。甄权：杀瘤瘘、瘰疬。时珍：解斑毒，利咽喉。）\n\n      疏：玄参正禀北方水气，而兼得春阳之和，故味苦而微寒无毒。\n\n    《别录》兼咸，以其入肾也。为足少阴经君药。黑乃水色，苦能下气，寒能除热，咸能润下软坚，故主腹中寒热积聚，女子产乳余疾。补肾气，令人明目者，益阴除热，故补肾而明目也。热则生风，故主暴中风，及疗伤寒至春变温病，身热支满，狂邪忽忽不知人。主温疟洒洒者，邪热在表也。胸中气亦邪热也。止烦渴，散颈下核痈肿者，解热软坚之效也。心腹痛亦热也。坚癥者，内热血瘀而干也。益阴除热，故定五脏，久服补虚强阴益精也。散结气而能软坚，故主瘰疬也。散结凉血降火，故解斑毒、利咽喉也。“下寒血” 三字疑有误。\n\n【主治参与】\n同升麻、甘草等分，水煎，治发斑咽痛，出《活人书》。\n\n同鼠粘子半生半炒，各两许，为末，新汲水服。治急喉痹风。\n\n同地黄、甘菊花、蒺藜、枸杞子、柴胡，能明目。\n\n同贝母、连翘、甘草、栝楼根、薄荷、夏枯草，治瘰疬。\n\n同知母、麦门冬、竹叶，治伤寒阳毒，汗下后，热毒不散，心下懊憹，烦不得眠，心神颠倒欲绝。\n\n同黄连、大黄等分，蜜丸如梧子，每三四十丸，白汤下，治三焦积热。\n\n《经验方》治劳香：玄参一斤，甘松六两，为末，炼蜜一斤和匀，入瓶中封闭，地中埋窨十日，取出，更用灰末六两，炼蜜六两，同和入瓶，更窨五日，取出烧之，常令闻香，其疾自愈。\n\n【简误】\n        血少目昏，停饮寒热支满，血虚腹痛，脾虚泄泻。并不宜服。', NULL, NULL, NULL, '玄参', NULL, '13、玄参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042967, 'B92DC26387F5F342C04B00DBE4B067BB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7251, 414, 400105812, '       味苦、辛，寒，无毒。主关格诸癃结，小便不通，出刺，决痈肿，明目去翳，破胎堕子，下闭血，养肾气，逐膀胱邪逆，止霍乱，长毛发。\n\n       疏：瞿麦禀阴寒之气而生，故味苦寒。《别录》兼辛无毒。苦辛能破血，阴寒而降，能通利下窍而行小便，故主关格诸癃结小便不通，因于小肠热甚者。寒能散热，辛能散结，故决痈肿。除湿热，故明目去翳。辛寒破血，故破胎堕子而下闭血也。去肾家湿热，故云养肾气。逐膀胱邪逆者，亦泄湿热故也。湿热客中焦，则清浊不分而为霍乱，通利湿热则霍乱自解矣。\n用蕊壳，不用茎叶。入药先须以堇竹沥浸一伏时，漉出晒干。\n\n【主治参与】\n入八正散，利小肠实热结闭。\n\n《千金方》立效散：治下焦结热，小便淋闭，或有血出，或大小便出血。瞿麦穗一两，炙甘草七钱五分，山栀仁炒半两，为末，每服七钱，连须葱白七个，灯心五十茎，生姜五片，水二盏，煎至七分，时时温服。\n\n【简误】\n        瞿麦苦寒兼辛，性猛利，善下逐。凡肾气虚，小肠无大热者，忌之。胎前产后，一切虚人患小水不利，法并禁用。水肿、蛊胀脾虚者不得施。', NULL, NULL, NULL, '瞿麦', NULL, '12、瞿麦', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042968, 'DAFD9DC6735225C0197144275C0A51C9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7252, 414, 400105811, '       味苦、酸，平，微寒，有小毒。主邪气腹痛，除血痹，破坚积，寒热疝瘕。止痛，利小便，益气通顺血脉，缓中散恶血，逐贼血，去水气，利膀胱大小肠。消痈肿，时行寒热，中恶腹痛，腰痛。\n\n    （甄权：主妇人血闭不通。日华子：主女人一切病，胎前产后诸疾。治风补劳，退热除烦，益气，目赤，肠风泻血。元素：主泻肝，安脾肺，收胃气，止泻利，固腠理，和血脉，收阴气，敛逆气。好古：主理中气，治脾虚中满，心下痞，胁下痛，喜噫。肺急胀逆喘咳。太阳鼽衄。目涩，肝血不足。阳维病苦寒热。带脉病苦腹痛满，腰溶溶如坐水中。时珍：止下利腹痛后重。）\n\n        疏：芍药禀天地之阴，而兼得甲木之气。\n\n      《本经》味苦平无毒。\n\n     《别录》加酸、微寒。气薄味厚，升而微降，阳中阴也。又可升可降，阴也，降也。为手足太阴引经药，入肝脾血分。\n\n    《图经》载有二种：金芍药，色白；木芍药，色赤。赤者利小便散血，白者止痛下气。赤行血，白补血。白补而赤泻，白收而赤散。酸以收之，甘以缓之，甘酸相合用，补阴血通气而除肺燥。\n\n     故《本经》主邪气腹痛，除血痹，破坚积，寒热疝瘕，通顺血脉，散恶血，逐贼血，消痈肿，妇人血闭不通，目赤，肠风泻血，赤所治也。缓中，去水气，利膀胱大小肠，中恶腹痛，腰痛，女人一切病，胎前产后诸病，治风补劳，退热除烦，益气，泻肝安脾肺，收胃气，止泻利，固腠理，和血脉，收阴气，敛逆气，理中气，治脾虚中满，心下痞，胁下痛，善噫，肺急胀逆喘咳，太阳鼽衄，目涩肝血不足，阳维病苦寒热，带脉病苦腹痛满，腰溶溶如坐水中，止下利腹痛后重，白所治也。\n\n      详味《图经》，以金木分赤白，厥有深旨。芍药味酸，寒得木化，金色白，故白者兼金气者也。专入脾经血分，能泻肝家火邪。故其所主收而补。制肝补脾，陡健脾经，脾主中焦，以其正补脾经，故能缓中。土虚则水泛滥，脾实则水气自去，故去水气。土坚则水清，故利膀胱大小肠。中焦不治则恶气乘虚而客之，为腹痛，补脾则中自和而邪不能留，腹痛自止矣。脾虚则湿气下流客肾，故腰痛，得补则脾气运而上行，故腰痛自愈。女人以血为主。脾统血，故治女人一切病。胎前产后，无非血分所关，酸寒能凉血补血，故主胎产诸病。土实则金气肃而木气自敛，故治风除热。益血，故能补劳退热，除烦，统后天之元气。得补则旺，故益气。酸寒能泻肝，肝平则脾不为贼邪所干，脾健则母能令子实，故安脾肺。胃气属土，土虚则缓而散，木化作酸，故收胃气。脾虚则中气下陷而成泻利，东垣以中焦用白芍药，则脾中升阳，又使肝胆之邪不敢犯，则泻利自止矣。肺主皮毛腠理，脾主肌肉，而为肺之母，母能令子实，故固腠理。脾统血，脾和则血脉自和。酸敛入阴，故收阴气，敛逆气，理中气。脾虚则中满，实则满自消。治中则心下不痞，泻肝则胁下不痛。善噫者，脾病也，脾健则不噫。肝脾之火上炎，则肺急胀逆喘咳，酸寒收敛以泻肝补脾，则肺自宁，急胀逆喘咳之证自除。凉血补血则太阳鼽衄自愈。脾虚则目涩，得补则涩除。肝家无火则肝血自足。阳维病苦寒热，及带脉病苦腹痛满，腰溶溶如坐水中，皆血虚阴不足之候也。肝脾和，阴血旺，则前证自瘳矣。\n\n木芍药色赤，赤者主破散，主通利，专入肝家血分，故主邪气腹痛。其主除血痹、破坚积者，血瘀则发寒热，行血则寒热自止。血痹疝瘕，皆血凝滞而成，破凝滞之血，则痹和而疝瘕自消。凉肝故通顺血脉。肝主血，入肝行血，故散恶血，逐贼血。荣气不和则逆于肉里，结为痈肿，行血凉血则痈肿自消。妇人经行属足厥阴肝经，入肝行血，故主经闭。肝开窍于目，目赤者，肝热也，酸寒能凉肝，故治目赤。肠风下血者，湿热伤血也，血凉则肠风自止矣。\n\n【主治参与】\n白芍药酒炒为君，佐以炙甘草，为健脾最胜之剂，能治血虚腹痛。\n\n同黄连、滑石、甘草、升麻、人参、莲肉、扁豆、红曲、干葛，为治滞下之神药。\n\n同人参、白术、茯苓、炙甘草、肉豆蔻、橘皮、车前子，治脾虚泄泻。\n\n酒炒白芍药二两，炙甘草二钱，莲子去心五十粒，水煎。治痘疮有热作泄，热甚加酒炒黄连一钱。\n\n同荆芥、防风、生地黄、黄耆、炙甘草，治肠风下血。\n\n同当归、地黄、牛膝、炒黑干姜、续断、麦门冬、五味子，治产后血虚发热。\n\n君白芷、炙甘草，治痘疮血虚发痒。\n\n同黄耆、防风，治表虚伤风自汗。\n\n赤芍药同藿香、橘皮、木瓜、甘草，治中恶腹痛。\n\n同芎、红花、生地黄、当归、白芷、荆芥，治破伤风发热疼痛。\n\n同牛膝、当归、地黄、延胡索、山查、泽兰、红蓝花、五灵脂，治初产恶露不下腹痛，冬月加肉佳。\n\n同金银花、白芷、鲮鲤甲、紫花地丁、夏枯草、茜草、生甘菊，消一切痈肿。\n\n同香附、当归、地黄、延胡索、青皮，治经阻腹痛。加五灵脂、蒲黄，能散恶血，逐败血。\n\n【简误】\n       白芍药酸寒，凡中寒腹痛，中寒作泄，腹中冷痛，肠胃中觉冷等证忌之。赤芍药破血，故凡一切血虚病及泄泻，产后恶露已行，少腹痛已止，痈疽已溃，并不宜服。', NULL, NULL, NULL, '芍药', NULL, '11、芍药', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042969, 'C8840A8C5DD9730781122BE9C0866D91', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7253, 414, 400105809, '     味辛、甘，平，无毒。主去恶虫，除脾胃寒热，通利九窍血脉关节，令人不忘。疗脾疸常欲眠，心烦，哕出音声，疗耳聋，散痈肿诸结不消，及金疮恶疮，鼠瘘，踒折，齆鼻息肉，堕胎，去三虫。\n\n       疏：通草者，即木通也。禀清秋之气，兼得土之甘淡，故其味辛平。\n\n        《别录》加甘、无毒。又云：微寒，味甘而淡，气平味薄，降也，阳中阴也。入足少阴、太阳，亦入手少阴、太阳。能助西方秋气下降，故利小便，专泻气滞。肺受热邪，津液气化之源绝，则寒水断流；膀胱受湿热癃闭，则约束小便不通，宜此治之。其证胸中烦热，口燥舌干，咽干，大渴引饮，小便淋沥，或闭塞不通，胫酸脚热，并宜此主之。\n     \n      《本经》主除脾胃寒热者，以其通气利湿热也。其曰通利九窍血脉关节，以其味淡渗而气芬芳也。令人不忘者，心主记，心家之热去，则心清而不忘矣。湿热生虫，故又主恶虫。疗脾疸常欲眠，心烦哕者，脾家湿热壅盛则成疸，心脾之热不清，则昏昏欲眠而心烦哕。音声出于肺，肺家之湿热去，则肺金之气清而音声出矣。治耳聋者，泄肾家之湿火也。散痈肿诸结不消，及金疮恶疮，鼠瘘，踒折，齆鼻息肉，堕胎。\n\n       又《药性论》治五淋，利小便，开关格，下水，排脓止痛，及治人多睡，水肿浮大。陈士良主理湿热、小便数急疼，少腹虚满。日华子主妇人血闭，月候不匀，乳结下乳者，皆通窍之所致也。\n\n【主治参与】\n同茯苓、泽泻、灯心、车前子、猪苓，治膀胱湿热癃闭，如疏中所引东垣所说。\n\n入导赤散者，以其能泻丙丁之火，则肺不受邪，能通水道，水源既清，则津液自化，而诸经之湿与热得由小便泻去故也。\n\n同牛膝、生地黄、天麦门冬、五味子、黄檗、甘草，治尿血。\n\n同牛膝、生地黄、延胡索，治妇人经闭及月事不调。\n\n【简误】\n        木通性通利，凡精滑、不梦自遗，及阳虚气弱，内无湿热者，禁用。妊娠忌之。', NULL, NULL, NULL, '通草,木通', NULL, '9、通草,木通', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042970, '8F7137C3A37CF463C734BAEE217B2A24', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7254, 414, 400105810, '       即今之通草也。禀土之清气，兼得天之阳气，故味甘淡，气寒无毒。东垣：甘平。阳中阴，降也。阳中之阴必下降，故主利阴窍，治五淋，除水肿癃闭，泻肺，解诸毒虫痛，明目退热，下乳催生。以其色白体轻，气寒味淡，故入手太阴经，引热下降，以利小便。故又入足阳明胃经，通气上达，而下乳汁。及除寒热不通之气，以其气寒而降也。\n\n【主治参与】\n        佐番降香、红曲、鲮鲤甲、山查、没药，治上部内伤。 \n【简误】\n虚脱人禁用。孕妇忌服。', NULL, NULL, NULL, '通脱木', NULL, '10、通脱木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626480658042971, '83CF9C63907B3F4C7ADDE8218DAB9A40', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 16:16:21', 1, 'admin', '2025-01-15 17:33:03');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7255, 415, 400105912, '     味辛，平，无毒。主杀诸小虫，去臭气，破癥积，下恶气，除邪鬼蛊毒。\n\n       疏：阿魏禀火金之气，而兼得乎天之阳气，故其味辛平温而无毒。气味俱厚，阳也。入足太阴、阳明经。其气臭烈殊常，故善杀诸虫，专辟恶气。辛则走而不守，温则通而能行，故能消积利诸窍，除秽恶、邪鬼蛊毒也。苏恭曰：体性极臭而能止臭，亦奇物也。\n\n【主治参与】\n同人参、橘红、京三棱、蓬莪术、砂仁，治一切肉食坚积。入膏药，同麝香、硫黄、苏合油，贴一切痞块。\n\n同安息香、百部、青黛、丹砂，治尸疰恶气。\n\n【简误】\n      阿魏之气臭烈，人之血气闻香则顺，闻臭则逆，故凡脾胃虚弱之人，虽有痞块坚积，不可轻用。当先补养胃气，胃气强则坚积可渐磨而消矣。故古人治大积大聚，消其大半而止，正此谓也。', NULL, NULL, NULL, '阿魏', NULL, '12、阿魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373062, 'D580FB061BB031895A667657E8477431', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7256, 415, 400105911, '        味辛，平，无毒。主诸风湿痹，四肢拘挛，小儿风痫惊气，利腰膝，强筋力。久服益气轻身。\n\n        疏：天麻得土之辛味，兼感天之阳气以生，故其味辛气平无毒。大明云 “暖”。浮而升，阳也。入足厥阴经。厥阴为风木之脏，诸风湿痹，四肢拘挛，小儿风痫惊气，皆肝脏为邪气所客致病。天麻入肝，味辛气暖，能逐风湿外邪，则肝气平和，前证自瘳矣。肝主筋，位居于下，故能利腰膝，强筋力也。风湿缠注则身重气乏，能除风湿则身自轻，气自益也。凡头风眩晕，与夫痰热上壅，以致头痛及眩，或四肢湿痹麻木，小儿风痫惊悸等证，所必须之药。\n\n【主治参与】\n同术、半夏、黄芩、前胡、橘皮、茯苓，治痰厥头痛。\n\n同术、橘皮、茯苓、车前，治饮在心下作支满。同南星、前胡、橘皮、白前，消一切风痰。\n\n【简误】\n        风药多燥，风能胜湿故也。凡病人觉津液衰少，口干舌燥，咽干作痛，大便闭涩，病火炎头晕、血虚头痛，及南方似中风，皆禁用之。', NULL, NULL, NULL, '天麻', NULL, '11、天麻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373063, '14668358956FF2D29B019FA435C2F736', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7257, 415, 400105910, '      味辛、苦，平、温，无毒。主风寒温疟，热气诸痫，除邪，利大小便，疗水肿风肿，去膀胱热，伤寒寒热邪气，中风手脚挛急，止泄，散痈肿恶结，诸（疒呙）疥癣虫疮，通腠理，利九窍。\n\n        疏：防己得土中阳气，而兼感乎秋之燥气以生，故味辛苦，平温无毒。洁古谓其大苦辛寒为得之。然性燥而不淳，善走下行，长于除湿，以辛能走散，兼之气悍，故主风寒温疟，热气诸痫，除邪气。除湿下行，故利大小便。此《本经》所载也。\n\n       《别录》疗水肿风肿，去膀胱热，通腠理，利九窍，止泄者，皆除湿之功也。其曰伤寒寒热邪气，中风手脚挛急，则寒，非燥药可除，不宜轻试。又曰：散痈肿恶结，诸（疒呙）疥癣虫疮，非在下部者，亦不宜用。治湿风口眼㖞斜，手足拘痛，真由中风湿而病者，方可用之。留痰非由脾胃中湿热而得者，亦不宜服。肺气喘嗽，不因风寒湿所郁、腠理壅滞者勿用。惟治下焦湿热，肿、泄、脚气，行十二经湿为可任耳。生汉中，内有淡黑纹晕如车辐解者，良。凡修事，以车前草根相对，蒸半日，晒干。杀雄黄毒。恶细辛。畏萆薢、女菀、卤咸。伏硝石。殷孽为之使。\n\n【主治参与】\n凡用防己，于下部湿热药中，亦必以二术、茯苓、黄檗、甘草、萆薢、木瓜、石斛、薏苡仁等补益之药为主，而使防己为使，乃无瞑眩之患。陶曰：防己是疗风水要药。洁古曰：去下焦湿肿及痛，并泄膀胱火邪，必用汉防己、龙胆草为君，黄檗、知母、甘草佐之。防己乃足太阳本经药也。\n\n《本草・十剂》云：通可去滞，通草、防己之属是也。夫防己大苦寒，能泻血中湿热，通其滞塞，亦能泻大便，补阴泻阳，助秋冬、泻春夏之药也。比之于人，则险而健者也。幸灾乐祸，能首为乱阶，然善用之，亦可敌凶突险。此瞑眩之药也，故圣人存而不废。大抵闻其臭则可恶，下咽则令人身心烦乱，饮食减少。至于十二经有湿，壅塞不通，及下注脚气，暨膀胱积热，非此药不可，真行经之仙药，无可代之者。若夫饮食劳倦，阴虚生内热，元气谷食已亏，以防己泄大便，则重亡其血，此不可用一也。如人大渴引饮，是热在上焦肺经气分，宜渗泄，而防己乃下焦血分药，此不可用二也。外伤风寒，邪传肺经，气分湿热，而致小便黄赤，乃至不通，此上焦气病，禁用血药，此不可用三也。大抵上焦湿热者，皆不可用。下焦湿热流入十二经，致二阴不通者，然后审而用之。\n\n张仲景方治皮水胕肿，按之没指，不恶风，水气在皮肤中，四肢聂聂动者，防己茯苓汤主之。防己、黄耆、桂枝各三两，茯苓六两，甘草三两，水一升，煎半升，日二服。\n\n又方：治风水恶风，汗出身重，脉浮，防己黄芪汤主之。防己一两，黄耆二两二钱半，白术七钱半，炙甘草半两，剉散，每服五钱，生姜四片，枣一枚，水一盏半，煎八分。温服，良久再服。腹痛加芍药。又治风湿相抟，关节沉痛，微肿恶风。方同上。\n\n【简误】\n       防己固为去下焦血分湿热之要药，然其性悍，其气猛，能走窜决防，大苦大寒，能伤胃气。凡胃虚、阴虚、自汗、盗汗、口苦、舌干，肾虚小水不利，及胎前产后血虚，虽有下焦湿热，慎毋用之。犯之为害非细。', NULL, NULL, NULL, '防己', NULL, '10、防己', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373064, '5F3A2E554129093B7B946FDD82DA8E25', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7258, 415, 400105909, '       味咸，寒，无毒。主十二种水肿，瘿瘤聚结气，瘘疮。\n\n        疏：昆布得水气以生，故味咸气寒而性无毒。咸能软坚，其性润下，寒能除热散结，故主十二种水肿，瘿瘤聚结气，瘘疮，东垣云：瘿坚如石者，非此不除，正咸能软坚之功也。详其气味、性能、治疗，与海藻大略相同。故同一 “简误” 也。\n\n【主治参与】\n《外台秘要》项下卒肿，其囊渐大欲成瘿者：昆布、海藻等分，为末，蜜丸杏核大。时时含咽汁。\n\n《圣惠方》瘿气结核，㿔㿔肿硬：以昆布一两，洗去咸，晒干为散。每以一钱绵裹，好醋浸过，含之咽汁，味尽再易之。项下五瘿同此。\n\n《广济方》治膀胱结气，急宜下气：用昆布一斤，白米泔浸一宿，洗去咸味，以水一斛，煮熟劈细，入葱白一握，寸断之，更煮极烂，乃下盐，酢，掺姜、橘、椒末，调和食之。仍食粱米、粳米饭，极能下气。', NULL, NULL, NULL, '昆布', NULL, '9、昆布', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373065, '59F1B46BC173C44E0D5C1832CAE7A44B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7259, 415, 400105908, '      味苦、甘，微温，无毒。主乳妇内衄，中风余疾，大腹水肿，身面四肢浮肿，骨节中水，金疮，痈肿疮脓，产后金疮内塞。（防己为之使。根名地笋。）\n\n      疏：泽兰感土泽之气，故味苦甘而入血。兼得乎春气，故微温而无毒。桐君兼酸，故入足厥阴、太阴经。苦能泄热，甘能和血，酸能入肝，温通荣血，故又主痈肿疮脓，及妇人吹乳、乳结，止衄血，并中风余疾。佐以益脾土之药，而用防己为之使，则主大腹水肿，身面四肢浮肿，骨节中水气。日华子云：泽兰通九窍，利关脉，养血气，破宿血，消癥瘕，产前产后百病。通小肠，长肉生肌，消扑损瘀血，治鼻洪吐血，头风目痛，妇人劳瘦，丈夫面黄。\n\n     又《药性论》云：泽兰，使，味苦辛，主产后腹痛，频产血气衰冷、成劳瘦羸。又治通身面目大肿。主妇人血沥腰痛。总其泄热和血，行而带补之能也。\n\n【主治参与】\n泽兰，妇人方中最为急用。古人治妇人，泽兰丸甚多。\n\n泽兰得炒黑豆、炮干姜、当归、芎、干地黄、牛膝、益母草、赤芍药、蒲黄、五灵脂，治产后恶露不尽，少腹作痛，俗名儿枕痛。寒月加桂。多火及内热虚劳人，去桂加童便。去五灵脂，加人参、鳖甲、香附、麦门冬，治产后诸虚百病。肺热者去人参。\n\n雷公云：凡使须要别识雌雄，其形不同。大泽兰茎叶皆圆，眼青黄，能生血调气，养荣气，与小泽兰迥别。采得后看叶上斑、根须尖。此药能破血通久积。凡修事大小泽兰，须细剉之，用绢袋盛悬于屋南畔角上，令干用。\n\n《子母秘录》：治小儿蓐疮，嚼泽兰心封上。\n\n泽兰气味和平，除妇人产后，他用甚稀，故无 “简误”。', NULL, NULL, NULL, '泽兰', NULL, '8、泽兰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373066, 'A83495880837143CDA7996562BF14E06', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7260, 415, 400105907, '       味苦、咸，寒，无毒。主瘿瘤气，颈下核，破散结气痈肿，癥瘕坚气，腹中上下鸣，下十二水肿，疗皮间积聚，暴㿉，瘤气热结、利小便。\n    \n      疏：海藻全禀海中阴气以生，故味苦咸、寒而无毒。气味俱厚、纯阴，沉也。苦能泄结，寒能除血热，咸能软坚润下，故《本经》主瘿瘤气，颈下核，破散结气痈肿，癥瘕坚气，及腹中上下鸣，下十二水肿，疗皮间积聚，暴㿉，瘤气结热，利小便。洁古专消瘿瘤、马刀、瘰疬诸疮，坚而不溃者。《经》云：咸能软坚。荣气不从，外为浮肿，随各引经治之，肿无不消。反甘草。一云有小毒。\n\n【主治参与】\n危氏《得效方》治蛇盘瘰疬，头项交接者：海藻莱，以荞麦面炒过，白僵蚕等分，为末，以白梅泡汤，和丸梧子大。每服六十丸，米饮下，必泄出毒气。宜加连翘。\n\n《范汪方》海藻酒：治瘿气及项下瘰疬。用海藻一斤，绢袋盛之，以清酒二斤浸之，春夏二日，秋冬三日，每服两合，日三，酒尽再作。其滓曝干为末，每服方寸匕，日三服。不过两剂即瘥。\n\n雷公云：凡使须用生乌豆，并紫背天葵，同蒸一伏时，曝干用。宜以淡白酒先洗净为佳。\n【简误】\n        脾家有湿者勿服。', NULL, NULL, NULL, '海藻', NULL, '7、海藻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373067, '80F4D7455026B6B0D3046D1B9B3E7A42', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7261, 415, 400105906, '        味甘，温。主养精保血。大蓟主女子赤白沃，安胎，止吐血鼻衄。令人肥健。\n\n       疏：大蓟根禀土之冲气，兼得天之阳气，故味甘气温而无毒。日华子：凉，当是微寒。陶云有毒，误也。女子赤白沃，血热所致也。胎因热则不安。血热妄行，溢出上窍则吐衄。大蓟根最能凉血，血热解则诸证自愈矣。其性凉而能行，行而带补。补血凉血则荣气和，荣气和故令肥健也。\n\n【主治参与】\n大蓟叶得地榆、茜草、牛膝、金银花，治肠痈、腹痈、少腹痈。生捣绞汁，入前四味浓汁，和童便饮，良。\n\n得炒蒲黄、棕皮灰，调汁半升，治崩中下血立瘥。\n\n又治瘀血作晕，跌扑损伤作痛，俱生取汁，入酒并童便服。\n\n又治恶疮疥癣，同盐捣罯之。\n\n《药性论》云：大蓟亦可单用，味苦平，止崩中下血。生取根捣绞汁半升许，立瘥。\n\n日华子云：大蓟叶，凉，治肠痈，腹藏瘀血，血晕，扑损，可生研，酒并小便任服。恶疮疥癣，盐研罨傅。又名刺蓟，山牛旁。\n\n小蓟根苗，气味甘温，微寒，无毒。其所禀与大蓟皆同，得土中冲阳之气，而兼得乎春气者也。故主养精保血。精属阴，气血之所生也。甘温益血而除大热，故能养精而保血也。\n\n陈藏器云：破宿血，生新血，暴下血，血崩出血，呕血等，绞取汁，作煎，和沙糖，合金疮，及蜘蛛蛇蝎毒，服之亦佳。\n\n日华子云：小蓟根，凉，无毒，治热毒风，并胸膈烦闷，开胃下食，退热，补虚损。苗：去烦热，生研汁服。小蓟力微，只可退热，不似大蓟能补养下气。\n\n《食疗》云：小蓟根主养气，取生根叶捣取自然汁，服一盏亦佳。又取叶煮食之，除风热。根：主崩中，又女子月候伤过，捣汁半升服之。金疮血不止，挼叶封之。夏月热烦闷不止，捣叶取汁半升服，立瘥。\n\n《圣惠方》：治心热吐血口干，用刺蓟叶及捣绞取汁，每服一小盏，顿服。\n\n又方：乳石发动，壅热心闷吐血：以生刺蓟捣取汁，每服三合，入蜜少许，搅匀服之。\n\n《外台秘要》治鼻塞不通：小蓟一把，水二升，煮取一升，去滓分服。\n\n《梅师方》治卒吐血及泻鲜血：取小蓟叶捣汁，温服。\n\n《简要济众》治九窍出血：以刺蓟一握，绞取汁，以酒半盏，调和顿服。如无鲜汁，只捣干者为末，冷水调三钱。\n\n又方：治小儿浸淫疮，痛不可忍，发寒热：刺蓟末，新水调傅疮上，干即易之。\n\n【简误】\n       大、小蓟性下行，以其能下气，故主崩衄多效。惟不利胃弱泄泻，及血虚极，脾胃弱，不思饮食之证。', NULL, NULL, NULL, '大蓟,小蓟', NULL, '6、大蓟,小蓟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373068, '0B423C5811112F4ADCC6545FE7A1A560', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7262, 415, 400105905, '        味苦、甘、酸，微寒，无毒。主妇人乳痓痛，七伤，带下病，五漏，止痛，除恶肉，止汗，疗金疮，止脓血，诸瘘恶疮，热疮，消酒，除消渴，补绝伤，产后内塞，可作金疮膏。（得发良。恶麦门冬）\n\n         疏：地榆禀地中阴气，而兼得乎天之微阳，故味苦甘酸，气则微寒而无毒。气薄味厚，沉而降，阴也。入足厥阴、少阴，手足阳明经。妇人乳痓痛者，厥阴肝经有热，以致血分热壅所致也。七情伤于带脉，故带下也。五漏者，阳明大肠湿热伤血病也。血热则肿而作痛。恶肉者，亦血热极则瘀，故肿而成恶肉也。伤则出血，血出必发热而作痛，金疮是也。脓血不止，皆血热所致。诸瘘恶疮，莫不由血热所生。苦寒能凉血泄热，热散则血活肿消，故并主如上诸疾也。性行而带补，味兼甘酸，故补绝伤及产后内塞也。消酒，除渴，明目，止纯血痢、疳痢极效。治肠风者，皆善祛湿热之功也。沉寒入下焦，故多主下部湿热诸病。\n\n【主治参与】\n地榆得金银花等分，佐以芍药、甘草、枳壳、黄连、乌梅，治血痢。如热在心经，下利纯鲜血，则加生犀角汁十五匙，神验。\n\n绵地榆四两为君，加金银花两许，鲮鲤甲三片土炒，研细，水酒煎浓，空心温热服。治横痃鱼口，有神。虽甚，四服无不消者。若已成脓，更加盐水炒黄耆五钱，白芷二钱，主速溃易合。\n\n去鲮鲤甲，并加牛膝、木瓜、僵蚕、黄檗，治下疳阴蚀极效。\n\n《圣惠方》治妇人漏下赤白不止，令人黄瘦：地榆三两，米醋一斤，煮十余沸，去滓。食前稍热服一合。\n\n崔元亮《海上方》治赤痢骨立者：地榆一斤，水三升，煎一升半，去滓，再煎如稠饧，绞滤，空腹时服三合，日再服。\n\n《活法机要》治久病肠风，痛痒不止：地榆五钱，苍术一两，水二钟，煎一钟，空心服，一日一服。\n\n《肘后方》治下血不止二十年者：地榆、鼠尾草各二两，水二升，煮一升，顿服。若不断，以水渍屋尘饮一小杯投之。\n\n《宣明方》治结阴下血，腹痛不已。地榆四两，炙甘草三两，每服五钱，水一盏，入缩砂七枚，煎半盏，分二服。\n\n《肘后方》治小儿疳痢：地榆煮汁，熬如饴糖，与服便已。\n\n《千金方》治大指肿痛，地榆煮汁渍之，半日愈。\n\n【简误】\n       地榆性寒而下行。凡脾胃虚寒作泄，白痢久而胃弱，胎产虚寒泄泻，血崩脾虚作泄，法并禁服。', NULL, NULL, NULL, '地榆', NULL, '5、地榆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373069, '9A4BA9AEA026FFF3BAFABB6AA4868BA9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7263, 415, 400105904, '      味苦，寒，无毒。主消渴内疸，瘀血月闭，寒热酸疼，益气愈聋，疗诸邪气热结，鼠瘘，散痈肿留血，妇人带下不通，下乳汁，止小便数不禁，逐四肢骨节中水，疗马骨刺人疮。（一名土瓜。）\n\n       疏：王瓜禀土中清肃阴寒之气，故味苦气寒而无毒。其能除湿热热毒，大约与栝楼性同，故其主治内疸消渴，邪气热结，鼠瘘，痈肿等证，皆与栝楼相似，而此则入血分诸病为多耳。\n“简误”“主治”，与栝楼亦略相当，不复赘。', NULL, NULL, NULL, '王瓜', NULL, '4、王瓜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373070, '530670848897349117BF8DFFCE6B8705', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7264, 415, 400105903, '      味辛、酸，寒，无毒。主暴热身痒，下水气，胜酒，长须发，主消渴，下气。以沐浴，生毛发。久服轻身。一名水花。\n\n     疏：水萍专得水气之清阴，故味辛气寒，《别录》兼酸无毒。盖其体轻浮，其性清燥，能祛湿热之药也。热气郁于皮肤则作痒，味辛而气清寒，故能散皮肤之湿热也。寒能除热，燥能除湿，故下水气。酒性湿热，而萍之质不沉于水，其气味辛寒，轻清而散，故能胜酒。血热则须发焦枯而易堕，凉血则荣气清而须发自长矣。\n\n《别录》主消渴者，以湿热之邪去，则津液自生而渴自止也。其曰下气，以沐浴、生毛发者，亦以寒能除热、凉血之验也。热邪不干，荣气清旺则能获轻身矣。\n\n【主治参与】\n苏颂曰：治恶疾疠疮遍身者，浓煮汁，浴半日，多效。\n\n《圣惠方》：少年面皰，挼浮萍盦之，亦可饮汁少许。\n\n《千金翼方》治小便不利，膀胱水气流滞：浮萍日干为末，服方寸匕，日二服，良。\n\n《子母秘录》风热丹毒：浮萍捣汁傅之令遍。去风丹：采浮萍诗曰：“天生灵草无根干，不在山间不在岸，始因飞絮逐东风，泛梗青青飘水面。神仙一味去沉疴，采时须在七月半。选甚瘫风与大风，些小微风都不算。豆淋酒化服三丸，铁扑头上也出汗”。其法以紫背浮萍晒干，为细末，炼蜜丸弹子大。每服一丸，以豆淋酒化下，治瘫痪，三十六种风，有验。\n\n【简误】\n       表气虚而自汗者，勿用。', NULL, NULL, NULL, '浮萍,水萍,水花', NULL, '3、水花,水萍,浮萍', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373071, 'DF47ED67CF303CE85D5951A9941288C4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2025-01-16 10:52:11');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7265, 415, 400105902, '   味辛，平。主明目，补中，除风伤。\n\n    疏：恶实至秋而成，得天地清凉之气。本经言辛平，藏器兼苦。升多于降，阳也。入手太阴、足阳明经。为散风、除热、解毒之要药。辛能散结，苦能泄热，热结散则脏气清明，故明目而补中。风之所伤，卫气必壅，壅则发热，辛凉解散则表气和，风无所留矣，故除风伤。藏器主风毒肿，诸瘘。元素主润肺散结气，利咽膈，去皮肤风，通十二经者，悉此意耳。故用以治瘾疹、痘疮，尤获奇验。\n\n【主治参与】\n同赤柽木，为疹家要药。\n\n同浮萍等分为末，治风热瘾疹，薄荷汤下，每服二钱，日进二服。\n\n同紫草、犀角、生地黄，治天行痘疮，血热干枯不得出，有神。\n\n《痘疹要诀》治咽喉痘疮：牛旁子二钱，桔梗一钱五分，粉草节七分，水煎服。\n\n《和剂局方》治痘疮出不快，时壮热狂躁，咽膈壅塞，大便秘涩，小儿咽肿不利：牛旁子炒一钱二分，荆芥穗二分，甘草四分，水煎，温服。已出亦可服。名必胜散。若大便利者勿用。\n\n《延年方》治风龋牙疼，单用一味煎汤，含漱吐去。\n\n《袖珍方》治便痈肿痛。用牛旁子二钱，炒研，入蜜一匙，朴消一匙，空心温酒服。\n\n刘禹锡《传信方》疗暴中风：用紧细牛旁子根，取时避风，以竹刀或荆刀刮去土，用生布拭了，捣绞取汁一大升，和蜜四大合，温分二服，得汗出，便瘥。\n\n【简误】\n        恶实性冷而滑利，痘疮家惟宜于血热便闭之证。若气虚色白，大便自利或泄泻者，慎勿服之。痧疹不忌泄泻，故用之无妨。痈疽已溃，非便闭不宜服。', NULL, NULL, NULL, '恶实', NULL, '2、恶实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373072, '76ACE2570DF0660F174479FF5D6DB587', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7266, 415, 400105901, '         味苦，微温，无毒。主灸百病。可作煎，止下痢，吐血，下部䘌疮，妇人漏血。利阴气，生肌肉，辟风寒，使人有子。作煎勿令见风。（弘景：捣汁止伤血，杀蛔虫。苏恭：止衄血，下血，脓血痢，主崩血，金疮，安胎。苦酒作煎治癣。大明：治妇人带下，霍乱转筋。\n\n        疏：艾叶禀天地之阳气以生，故味苦微温，熟则大热。可升可降，其气芳烈，纯阳之草也，故无毒。入足太阴、厥阴、少阴三经。烧则热气内注，通筋入骨，故灸百病。性能通窍，辟恶杀鬼精，故止鬼击吐血。芳烈之气必燥，故主下部䘌疮。其治妇人漏血，利阴气，生肌肉者，皆以之导引凉血补血药为用者也。使人有子，盖指气血两虚之人，风寒乘虚入子宫不孕者设也。辟风寒，其性辛温也。捣汁服止伤血者，生寒而兼辛散也。杀蛔虫者，辛而苦也。主衄血者，伤寒邪热，郁而不汗则发衄也。风邪入大肠则下血，湿热伤脾胃则下痢脓血。煮则上升，故亦止崩漏也。理金疮，血热则行也。胎为风寒之气所犯则不安，风寒散则胎自安也。苦酒作煎治癣甚良者，杀虫之功也。治妇人带下，温中除湿而升也。止霍乱转筋者，因寒而得也。为治白带之要药，调经之妙品，故妇人方多须之。\n\n【主治参与】\n艾叶能灸百病，陈久者良。\n\n入红铅蒸脐，补阳虚，温脾胃。治妇人月事不调，血少无热证者，同香附醋浸，入四物汤加阿胶、枳壳，神效。\n\n《金匮要略》：妇人有漏下者，有半产后下血不绝者，有妊娠下血者，并以胶艾汤主之。阿胶二两，艾叶三两，芎、甘草各二两，当归、地黄各三两，芍药四两，水五升，清酒五升，煮取三升，内胶令消尽。每温酒一升，日三服。\n\n妊娠、产后、血虚人作痢下血，用胶艾汤：蕲艾、阿胶、白芍药、人参、橘皮、甘草。胎前加黄芩，产后入当归。\n\n烧烟入管中，熏狐惑虫䘌良。\n\n非时不正之气伤人，发为头痛壮热，因于寒者，用干艾叶三升，水一斗，煮取一升，顿服，取汗，出《肘后方》。\n\n《妇人良方》治妊娠风寒卒中，不省人事，状如中风：用熟艾三两，米醋和炒极热，以绢包熨脐下，良久即解。\n\n蛔虫咬或心痛如刺，口吐清水：白熟艾一升，水三升，煮取一升服，吐虫出。\n\n或取生艾捣汁，五更先食香脯一片，乃饮一升，当下虫出。鹅掌风，用蕲艾五两，水四五碗，煮五六滚，入大口瓶，覆以麻布二层，熏掌心，如冷，顿热再熏，如神。\n\n发背初起，急灸疮头。不痛灸至痛，痛灸至不痛，夺命神方也。纵溃，毒气外泄，不致内攻矣。若未溃，疮头用湿纸贴上，看先干处是也，即于此灸。\n\n臁疮年久，口冷不合者，用艾烟熏之。\n\n【简误】\n         艾性纯阳，善辟风寒湿气及非时邪气。然性气芳烈而燥热，凡妇人胎动不安，由于热而不由于寒，妊娠下利脓血由于暑湿，肠胃热甚而非单湿为病，崩中由于血虚内热，经事先期由于血热，吐血不由于鬼击中恶，霍乱转筋不由于寒邪，而由于脾胃虚弱停滞，或伤暑所致，不孕由于血虚而不由于风寒入子宫，法并忌之。', NULL, NULL, NULL, '艾叶', NULL, '1、艾叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626498204373073, 'D1632A1EA7B758CD230864654DDE86C1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-25 17:27:45', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7267, 415, 400105914, '     微温（《蜀本》云微寒）。主咳嗽上气。\n\n      疏：百部根正得天地阴寒之气。故《蜀本》云微寒。日华子言苦。本经言微温者，误也。苦而下泄，故善降肺气。升则喘嗽，故善冶咳嗽上气。能散肺热，故《药性论》主润益肺。其性长于杀虫，传尸骨蒸劳，往往有虫，故亦主之。疳热有虫，及蛔虫、寸白虫、蛲虫，皆能杀之。又烧熏树木蛀虫，触烟即死。亦杀蝇蠓。日华子论之详矣。陶云：杀虱，浓煎，洗牛马虱即去。陈藏器云：火炙酒浸，空腹饮，去虫蚕咬，兼疥癣疮。\n\n【主治参与】\n同桑根白皮、天麦二冬、贝母、枇杷叶、五味子、紫菀，治一切虚嗽，但不能治食积嗽。\n\n《千金方》：单用一味熬膏，入蜜，不时取服，可疗三十年嗽。\n\n《杨氏经验方》治遍身黄肿：取鲜百部根，洗捣罨脐上，以糯米饭半升，拌酒半合，揉和，盖在药上，用帛包住。过一二日后，口内作酒气，则水从小便出，肿自消矣。\n\n《圣济总录》百虫入耳：百部炒、研细末，生油调傅耳门上。\n\n【简误】\n         百部味苦，脾虚胃弱人，宜兼保脾安胃药同用，庶不伤胃气。', NULL, NULL, NULL, '百部根', NULL, '14、百部根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626799507566661, 'A065F7E613EA1B5D4FB877FA6185D51E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 13:53:46', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7268, 415, 400105913, '     大温。主暴冷，胃中冷逆，霍乱腹痛。\n\n       疏：高良姜禀地二之气以生，本经大温，藏器辛温，元素辛热。纯阳，浮也。入足阳明、太阴经。二经为客寒所犯，则逆冷、霍乱、腹痛诸病生焉。辛温暖脾胃而逐寒邪，则胃中冷逆自除，霍乱腹痛自愈矣。甄权治腹内久冷气痛，去风冷痹弱。大明：主转筋泻痢，反胃，解酒毒，消宿食。苏颂治恶心呕清水。皆取其暖胃温中，散寒祛冷之功也。\n\n【主治参与】\n《外台秘要》霍乱吐利：高良姜炙令香，每用五两，以酒一升，煮三四沸，顿服。亦治腹痛中恶。\n\n《普济方》霍乱呕甚不止：用高良姜生剉二钱，大枣一枚，水煎冷服，立定。\n\n《永类钤方》心脾冷痛：用高良姜三钱，五灵脂六钱，为末。每服三钱，醋汤调下。\n\n【简误】\n      高良姜辛温大热，惟治客寒犯胃，胃冷呕逆，及伤生冷饮食，致成霍乱吐泻之要药。如胃火作呕，伤暑霍乱，火热注泻，心虚作痛，法咸忌之。', NULL, NULL, NULL, '高良姜', NULL, '13、高良姜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626799507566662, '83A946EBFA1E8BC8DFCB77B4A943EEC5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 13:53:46', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7269, 415, 400105943, '    味辛、苦，温，无毒。主贼风伤寒，发汗，恶气，心腹胀满，霍乱，宿食不消，下气。煮汁服，亦堪生食。饮汁发汗，大解劳烦。（菜部移入。）\n\n      疏：薄荷感杪春初夏之气，而得乎火金之味，金胜火劣，故辛多于苦而无毒。洁古：辛凉，浮而升，阳也。入手太阴、少阴经。辛合肺，肺主皮毛。苦合心而从火化，主血脉，主热，皆阳脏也。贼风伤寒，其邪在表，故发汗则解。风药性升，又兼辛温，故能散邪辟恶。辛香通窍，故治腹胀满霍乱。《食疗》以为能去心家热，故为小儿惊风，风热家引经要药。辛香走散以通关节，故逐贼风。发汗者，风从汗解也。本非脾胃家药，安能主宿食不消？上升之性，亦难主下气。劳乏属虚，非散可解。三疗俱非，明者当自别之。\n\n【主治参与】\n风热上壅，斯为要药。\n\n入噙化丸，以为之君，主阴虚肺热咳，嗽甚良，加生干姜，并治伤风寒咳嗽。\n\n佐漆叶、苦参、何首乌、胡麻仁、荆芥穗、生地黄、蒺藜子、石菖蒲、苍术，治大麻风。去苍术，加赤茎豨莶，治紫云风。\n\n同贝母、荆芥穗、玄参、斑猫，佐肥皂，能治瘰疬。\n\n《外台秘要》治水入耳中，捣汁滴入，立验。\n\n孙真人用以辟邪毒，除劳气，令人口气香洁。\n\n煎汤洗漆疮。\n\n日华子用以治中风失音吐痰。\n\n苏颂主伤风，头脑风，通关节，及小儿风涎，为要药。\n\n东垣用以清头目，除风热。故可疗风瘙瘾疹，及涂蜂螫。\n\n《简便单方》清上化痰，利咽膈，治风热上壅：以薄荷叶为末，炼蜜丸芡实大，每噙一丸。\n\n《医学集成》治舌胎语蹇。薄荷自然汁，和白蜜、姜汁少许，擦之。\n\n《明目经验方》治眼弦赤烂：薄荷以生姜汁浸一宿，晒干为末，每用一钱，沸汤泡洗。\n\n《济生方》治瘰疬结核，或破、未破：以新薄荷二斤取汁，皂荚一挺，水浸去皮，捣取汁，同于银石器内熬膏，入连翘末半两，连白青皮、陈皮、黑牵牛半生半炒，各一两，皂荚仁一两半，同捣和丸梧子大。每服三十丸，煎连翘汤下。\n\n张杲《医说》疗火毒生疮，因灸火，火气入内，两股生疮，汁水淋漓者：用薄荷煎汁，频涂立愈。\n\n【简误】\n       病人新瘥勿服，以其发汗虚表气也。咳嗽若因肺虚，寒客之而无热证者勿服，以其当补而愈也。阴虚人发热勿服，以出汗则愈竭其津液也。脚气类伤寒勿服，以其病在下而属脾故也。血虚头痛，非同诸补血药不可用。小儿身热，由于伤食者不可用。小儿身热，因于疳积者不可用。小儿痘疮，诊得气虚者，虽身热初起，亦不可用。', NULL, NULL, NULL, '薄荷', NULL, '44、薄荷', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673469509, '57D3F0B43B8433BEC25A499E8B9CF446', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7270, 415, 400105942, '    味辛，微温。主霍乱腹痛吐下，散水肿。（菜部移入。）\n\n      疏：香薷，丹溪谓其有金与水，然亦感夏秋之气以生者，故其味辛，其气微温而无毒。可升可降，阳也。入足阳明、太阴，手少阴经。辛散温通，故能解寒郁之暑气、霍乱腹痛。吐下转筋，多由暑月过食生冷，外邪与内伤相并而作。辛温通气，则能和中解表，故主之也。散水肿者，除湿利水之功也。孟诜谓其去热风，卒转筋者，煮汁顿服半斤即止。为末，水调服，止鼻衄。日华子谓其下气，除烦热，疗呕逆冷气。汪颖谓其夏月煮饮代茶，可无热病。调中温胃。含汁嗽口，去臭气。\n\n【主治参与】\n香薷饮，有十味者，有六味者，有加黄连者。虽同为祛暑之药，然脾、胃、肾俱虚之人，当以十味者为准。除有肺热咳嗽病者，去人参、白术、黄耆。\n\n治水肿以之为君，当同人参、术、木瓜、茯苓、橘皮、白芍药、车前子，良。\n\n《和剂局方》香薷饮：治一切伤暑，或暑月卧湿当风，或生冷不节，真邪相干，便致吐利，或发热头痛体痛，或心腹痛，或转筋，或干呕，或四肢逆冷，或烦闷欲死：并用香薷一斤，厚朴姜制，扁豆微炒各半斤，剉散，每用五钱，水二盏，煎一盏，水中沉冷，连进二服，立效。《活人书》去扁豆，入黄连四两，姜汁同炒黄色。\n\n《外台秘要》治水病，洪肿气胀，食不消：干香薷五十斤，剉入釜中，以水淹过三寸，煮使气尽，去滓澄之，微火煎至可丸，丸如梧子大。一服五丸，日三服，渐加之，以小便利则愈。宜有术同煎。\n\n《外台秘要》薷术丸：治暴水，风水，气水，通身皆肿，服至小便利为效：用香薷叶一斤，熬成膏，加白术末七两，和丸梧子大。每服十丸，米饮下，日五夜一服。\n\n《肘后方》治心烦，胁痛连胸欲死者：香薷捣汁二升服。\n\n《圣济总录》治鼻衄不止：香薷研末，水服一二钱。\n\n《肘后方》治舌上出血，如钻孔者：香薷煎汁，服一升，日三进。\n\n《千金方》治口臭：香薷一把，煎汁含之。\n\n《食医心镜》主心烦，去热：取煎汤，作羹煮粥，及生食亦得。\n\n《子母秘录》治小儿白秃发不生，汁出惨痛：浓煮陈香薷汁，入猪脂少许，和胡粉傅之。\n\n《衍义》云：治霍乱不可缺，用之无不效。\n\n雷公云：凡采得，去根留叶，细剉曝干，勿令犯火。服至十两，一生不得食白山桃也。\n\n【简误】\n         香薷性温，不宜热饮，故治乘凉饮冷，寒与暑气相搏激，是阳气为阴邪所遏，以致头疼发热恶寒，烦躁口渴，或吐，或泻，或霍乱者，宜用此药以发越阳气，散水和脾则愈。若夫饮食不节，劳役斫丧之人，伤暑热而病大热大渴，汗泄如雨，烦躁喘促，或泻或吐者，乃劳倦内伤之证，宜从东垣人参白虎汤、清暑益气汤、桂苓甘露饮之类，以泻火益元可也。然中热不吐泻者，宜人参白虎汤；吐泻者，宜清暑益气汤、桂苓甘露饮。设用香薷，是重虚其表而又济之以温，则误矣。盖香薷乃夏月解表之药，表无所感，而中热为病，何假于此哉？误则损人表气。戒之！戒之！', NULL, NULL, NULL, '香薷', NULL, '42、香薷', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673469510, '892FA785988674F0BA4894F7F4014484', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7271, 415, 400105941, '     味辛，温。主下气，除寒中。其子尤良。（忌与鲤鱼同食，生毒疮。自菜部移入。）\n\n       疏：苏，紫苏也。得天阳和之气，故温。兼地之金味，故辛。辛则善散，温能通气，故主下气，除寒中也。子尤良者，以其善降气也。入手少阴、太阴，足阳明经。孟诜谓其除寒热，治一切冷气。日华子谓其补中益气，治心腹胀满，止霍乱转筋，开胃下食，止脚气，通大小肠。苏颂谓其通心经，益脾胃，煮饮尤胜，与橘皮相宜。时珍谓其解肌发表、散风寒，行气宽中，消痰利肺，和血，温中，止痛，定喘，定胎，解鱼蟹毒。\n\n子：味辛，温，无毒。主下气，除寒，温中。甄权用以治上气咳逆，冷气，及腰脚中湿气，风结气。研汁煮粥常食，令人肥白身香。日华子谓其能止霍乱，呕吐反胃，消五膈，消痰止嗽，润心肺。寇宗奭用以治肺气喘急。皆辛温能散结而兼润下之力也。\n\n【主治参与】\n苏，阳草也，解肌散寒，苏表辟恶之要药。\n\n入参苏饮，治表虚人伤风久不愈。\n\n入苏沉九宝汤，解利伤风寒咳嗽。\n\n《肘后方》治感寒上气：苏叶三两，橘皮四两，酒四升，煮一升半，分再服。\n\n又方，治霍乱胀满，未得吐下：生苏捣汁饮之佳，干苏煮饮亦妙。\n\n《金匮要略》疗食蟹中毒：紫苏煮汁，饮二升。\n\n《普济方》治咳逆上气：苏茎叶二钱，人参一钱，水一钟，煎数沸服。\n\n《济生方》顺气利肠：紫苏子、麻仁等分，研烂，水滤取汁，同米煮粥食之。\n\n《圣惠方》治风顺气，利肠宽中：用苏子一升，微炒，杵，以生绢袋盛，于三斗清酒中浸三宿，少炒食之。\n\n《药性论》治一切冷气：苏子、良姜、橘皮，等分，蜜丸梧子大。每服十丸，空心酒下。又用治风湿脚气。\n\n《简便方》治上气咳逆：紫苏子，入水研，滤汁，同粳米煮粥食。\n\n【简误】\n        苏叶，其气芬芳，其味辛，其性温，纯阳之草也。故善发散，解肌出汗。病属阴虚，因发寒热，或恶寒及头痛者，慎毋投之，以病宜敛宜补故也。火升作呕者，亦不宜服，惟可用子。', NULL, NULL, NULL, '紫苏,苏,苏叶', NULL, '41、紫苏,苏,苏叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473605, '92438F13AFAA46750C3692905150276D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7272, 415, 400105940, '    味辛，温，无毒。主寒热鼠瘘，瘰疬生疮，破结聚气，下瘀血，除湿痹。（自菜部移入。）\n\n     疏：假苏，荆芥也。得春气，善走散，故其气温，其味辛，其性无毒。升也，阳也。春气升，风性亦升，故能上行头目。肝主风木，故能通肝气，行血分。能入血分之风药也，故能发汗。其主寒热者，寒热必由邪盛而作，散邪解肌出汗，则寒热自愈。鼠瘘由热结于足少阳、阳明二经，火热郁结而成。瘰疬为病，亦属二经故也。生疮者，血热有湿也，凉血燥湿，疮自脱矣。破结聚气者，辛温解散之力也。下瘀血，入血分，辛以散之，温以行之之功用也。痹者，风寒湿三邪之所致也。祛风燥湿散寒，则湿痹除矣。\n\n【主治参与】\n得白颈蚯蚓，同捣取汁，解阳明经热病汗出，立已。得童子小便调服，立苏血晕。\n\n《千金方》治头项风强：八月后取荆芥穗作枕及铺床下，立春日去之。\n\n又方，治风热牙疼：用荆芥根、乌桕根、葱根，等分煎汤，频含漱之。\n\n《经验方》治一切偏风口眼㖞斜：用青荆芥一斤，青薄荷一斤，同捣汁，于磁器中熬成膏，留三分之一，将二分日干为末，以膏和丸如梧子大。每三十丸白汤下，早暮各一服，忌动风物。\n又方，治中风口噤：荆芥穗为末，酒服二钱，立愈，名荆芥散。贾似道云：此方出《曾公谈录》，前后用之甚验。其子名顺者，病已革，服之立定，真再生丹也。\n\n华佗愈风散，治妇人产后中风口噤，手足瘈疭如角弓；或产后血晕不省人事，四肢强直；或心眼倒筑，吐泻欲死：用荆芥穗微焙，为末，每服三钱，豆淋酒调服，或童便服之。口噤则挑齿灌之，龈噤则灌入鼻中，其效如神。大抵产后虚甚则汗出而腠理疏，易于中风也。\n\n戴原礼：独行散，治产后迷闷，因怒发热而得者。用荆芥穗，以新瓦半炒半生，为末，童便服一二钱；若角弓反张，以豆淋酒下，或剉散童便煎服，极妙。盖荆芥乃产后要药，而角弓反张乃妇人急候，得此证者十存一二而已。\n\n《图经本草》治产后血晕，筑心眼倒，风缩欲死者：取荆芥末二钱匕，童便调匀热服，立愈。口噤者灌鼻中皆效。近世名医用之，无不如神也。\n\n《保命集》治产后血眩晕风虚，精神昏冒：荆芥穗一两三钱，桃仁去皮尖五钱，为末，水服三钱。若喘加杏仁去皮尖炒，甘草炙，各三钱。\n\n《妇人良方》治产后鼻衄：荆芥穗末，童便服二钱，海上方也。\n\n《简便方》治大便下血：用荆芥二两，槐花一两，同炒紫为末，每三钱，清茶送下。\n\n《活法机要》治瘰疬溃烂，牵至胸前、两腋，块如茄子大，或牵至两肩上，四五年不能疗者，皆治之，其效如神。晋陵朱守仁传云：其项不能回顾，用此数日减可。如疮烂破者，用荆芥根下一段剪碎，煎沸待温洗，良久，看烂破处紫黑，以针一刺去血，再洗三四次愈。用樟脑、雄黄，等分为末，麻油调扫上，出水。次日再洗再扫，以愈为度。\n\n《普济方》治一切疥疮：荆芥末，以地黄自然汁熬膏，和丸如梧子大。每服三十五丸，茶酒任下。\n\n《龙木论》治一切眼疾，血劳风气头痛，头旋目眩：用荆芥穗末，每酒服三钱。\n\n《普济方》治癃闭不通，小便急痛，无问久新。\n\n荆芥、大黄为末，等分，每温水服三钱。小便不通，大黄减半；大便不通，荆芥减半。名倒换散。\n\n【简误】\n       荆芥，风药之辛温者也。主升，主散，不能降，亦不能收。病人表虚有汗者忌之。血虚寒热，而不因于风湿风寒者勿用。阴虚火炎面赤，因而头痛者，慎勿误入。', NULL, NULL, NULL, '荆芥,假苏', NULL, '40、荆芥,假苏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473606, '75ADB6EE8AAA68EF8D51F77EC71D0CF8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7273, 415, 400105939, '    微温。疗风水毒肿，去恶气，疗霍乱心痛。（自木部移入。）\n\n    疏：藿香禀清和芬烈之气，故其味辛，其气微温、无毒。洁古：辛甘，又曰甘苦。气厚味薄，浮而升，阳也。东垣：可升可降，阳也。入手足太阴，亦入足阳明经。风水毒肿，病在于脾，恶气内侵，亦由脾虚邪入，霍乱心腹痛，皆中焦不治之证。脾主中焦，香气先入脾，理脾开胃，正气通畅，则前证自除矣。苏颂以为脾胃吐逆为要药。洁古谓其助胃气，开胃口，进饮食。海藏谓其温中快气。肺虚有寒，及寒郁热壅于上焦，饮酒口臭，煎汤饮之。皆辛温入肺入脾，清上治中之功也。\n\n【主治参与】\n得缩砂蜜、炒盐，治霍乱。\n\n得人参、橘皮、木瓜、茯苓、缩砂蜜，治吐泻转筋霍乱。\n\n得木香、沉水香、乳香、缩砂蜜，则辟恶气，治中恶心腹㽲痛。\n\n入顺气乌药散则补肺。入黄耆四君子汤则补脾。入桂苓甘露饮，治中暑吐泻。\n\n得木香、丁香、紫苏叶、人参、生姜，治暴中寒邪，吐逆不止。\n\n《经效济世方》升降诸气：藿香一两，香附炒五两，为末，每以白汤点服一钱。\n\n《百一选方》治霍乱吐泻垂死者，服之回生。用藿香叶、陈皮各半两，水煎，温服。\n\n《禹师经验方》治暑月吐泻：滑石二两，藿香二钱五分，丁香五分，为末。每服二钱，淅米泔调服。\n\n【简误】\n       藿香虽能止呕、治呃逆，若病因阴虚火旺，胃弱欲呕，及胃热作呕，中焦火盛热极，温病热病，阳明胃家邪实，作呕作胀，法并禁用。', NULL, NULL, NULL, '藿香', NULL, '39、藿香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473607, '0993A6B33D795B814732349EA90CE6C7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7274, 415, 400105938, '    味辛，温，无毒。主温中，心腹痛，呕吐，去口臭气。（《开宝》：主下气，止霍乱，一切冷气，消酒毒。东垣：调中补胃，健脾消食，去客寒心与胃痛。自果部移入。）\n\n     疏：豆蔻得地二之火气而有金，复兼感乎夏末秋初之令以生。故《别录》谓其味辛，气温，而性无毒。海藏又云：大辛热，阳也，浮也。入足太阴、阳明经。盖辛能破滞，香能入脾，温热能祛寒燥湿，故主温中，及寒客中焦心腹痛，中寒呕吐也。脾开窍于口，脾家有积滞则瘀而为热，故发口臭，醒脾导滞则口气不臭矣。辛散温行，故下气。寒客中焦，饮良不消，气因闭滞则霍乱，又散一切冷气，消酒毒者，亦燥湿、破滞、行气、健脾、开胃之功也。产闽之建宁者，气芳烈，类白豆蔻，善散冷气，疗胃脘痛，理中焦。产滇、贵、南粤者，气猛而浊，俗呼草果者是也。善破瘴疠，消谷食，及一切宿食停滞作胀闷及痛。\n\n【主治参与】\n入人参养胃汤，能消一切宿食，开拓中焦滞气。\n\n《药性论》云：草豆蔻单用，能主一切冷气。\n\n《千金方》治心腹胀满短气：用草豆蔻一两，去皮为末，以木瓜、生姜汤调服半钱。\n\n《圣济总录》治霍乱烦渴：草豆蔻、黄连各一钱半，乌豆五十粒，生姜三片，水煎服。\n\n《济生方》治气虚瘅疟，热少寒多，或单寒不热，或虚热不寒：用草果仁、熟附子等分，水一盏，姜七片，枣一枚，煎半盏服，名果附汤。\n\n《医方大成》亦用治脾寒疟，大便泄而小便多，不能食者。\n\n《百一选方》治脾肾不足，虚寒泄泻：草果仁一两，以舶上茴香一两炒香，去茴不用；吴茱萸一两，汤泡七次，同破故纸一两炒香，去故纸不用；胡卢巴一两，同山茱萸一两炒香，去茱萸不用。三味为末，酒糊丸，每六七十丸，盐汤下。\n\n《肘后方》香口辟臭：草豆蔻、细辛为末，含之。\n\n《直指方》治脾痛胀满：草果仁二个，酒煎服之。\n\n【简误】\n       豆蔻性温热，味大辛，本是祛寒破滞，消食除瘴之药。凡疟不由于瘴气，心痛胃脘痛由于火而不由于寒，湿热瘀滞、暑气外侵而成滞下赤白、里急后重、及泄泻暴注、口渴，湿热侵脾因作胀满，或小水不利，咸属暑气湿热，皆不当用，犯之增剧。', NULL, NULL, NULL, '豆蔻', NULL, '38、豆蔻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473608, 'F62B094EFAA1F0EC6AF612A838CB808B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7275, 415, 400105937, '    凉，无毒。治恶疮、疥癣、风瘙。根名白药。（叶如茗而细。）\n\n     疏：剪草禀天地清寒至阴之气以生，故藏器云味苦，其气寒凉，性应无毒。主诸恶疮、疥癣、风瘙、瘘蚀者，以诸痛痒疮疡，皆属心火。苦寒能降火而凉血清热，故主之也。湿热生虫，苦能杀虫，寒能除热，故有虫，浸酒服。\n\n【主治参与】\n洁古专以主上部血，而与牡丹皮、天门冬、麦门冬同用。\n\n许学士《本事方》云：剪草治痨瘵吐血肺损，及血妄行，名神传膏。其法每用一斤，洗净，晒为末，入生蜜二斤，和为膏，以器盛之，不得犯铁器，九蒸九曝，日一蒸曝。病人五更起，面东坐，不得语言，以匙抄药如粥服之。每服四两，服已，良久，以稀粟米饮压之。药只冷服，米饮亦勿太热，或吐或下皆不妨。如久病肺损咯血，只二服，愈。寻常咳嗽血妄行，每服一匙可也。有一贵妇病瘵，得此方，九日药成。前一夕，病者梦人戒令翌日勿乱服药。次日将服之，为屋上土坠器中，不可服。再合既成，又将服之，为婢覆器，又不得服。又再合未就，而夫人卒矣。此药之异如此。若小小血妄行，一啜而愈矣。此药妙绝若此，而世失传，惜哉！\n\n《中藏经》：治风虫牙痛。剪草、细辛、藁本等分，煎水热漱，少顷自止。\n\n《和剂局方》有滑肌散，治风邪客于肌中，浑身瘙痒，致生疮疥，及脾肺风毒，攻冲生疮，干湿日久不瘥：用剪草七两，不见火，轻粉一钱，为末掺之，干者麻油调搽。\n\n【简误】\n        剪草，大苦大寒之药，虽治血热妄行神效，若脾肾俱虚，胃口薄弱，见食欲呕，及不思食、泄泻者，勿遽投之，法当先理脾胃，俟能进食而后施治乃可。', NULL, NULL, NULL, '剪草', NULL, '37、剪草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473609, 'A292598F44CC813554E39D20C7041E72', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7276, 415, 400105936, '    味辛，大温，无毒。主积冷气，止吐逆反胃，消谷下气。（入药去皮焙用）\n\n     疏：白豆蔻感秋燥之令，而得乎地之火金，故其味辛，其气大温，其性无毒。好古大辛热，味薄气厚，轻清而升，阳也，浮也。入手太阴，亦入足阳明经。味大辛也，气大温也，宜其主积冷气，及伤冷吐逆，因寒反胃也。暖能消物，故又主消谷。温能通行，故主下气。东垣用以散肺中滞气，宽膈进食，去白睛翳膜，散滞之功也。\n\n【主治参与】\n得人参、生姜、橘皮、藿香，治胃虚反胃，及因寒呕吐，殊验。\n\n得半夏、橘红、生姜、白术、茯苓，治寒痰停胃作呕吐似反胃。\n\n得橘皮、白术、白蒺藜、决明子、甘菊花、蜜蒙花、木贼草、谷精草，理脾虚，白睛生障翳。\n\n得藿香、橘皮、木香，理上焦滞气。加乌药、香附、紫苏，治妇人一切气逆不和。\n\n佐参、术、姜、橘，治秋深疟发，寒多热少，呕吐胃弱，饮食不进，良。\n\n同扁豆、五味子、橘红、木瓜，能解酒毒，及中酒呕吐恶心。\n\n张文仲《备急方》治胃冷恶心，食已即欲吐：用白豆蔻三枚，捣细，好酒一盏温服，并饮数服，佳。\n\n《肘后方》治人忽恶心，多嚼白豆蔻子最佳。\n\n《危氏得效方》治小儿吐乳胃寒者：白豆蔻、缩砂蜜各十四个，生炙甘草各二钱，为末，常掺小儿口中。\n\n《济生方》治脾虚反胃：白豆蔻、缩砂蜜各二两，丁香一两，陈廪米一升，黄土炒焦，去土细研，姜汁和丸，每二三钱，姜汤下，名太仓丸。\n\n【简误】\n         白豆蔻辛温，其治在因寒呕吐反胃，其不因于寒及阳虚者，皆不得入。故凡火升作呕，因热腹痛，法咸忌之。', NULL, NULL, NULL, '白豆蔻', NULL, '36、白豆蔻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473610, 'DFEF124AC20537F1D825C22AF94289D7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7277, 415, 400105935, '       味甘，温，无毒。主小儿五疳，小便白浊，杀虫，疗泻痢。俗传始因潘州郭使君疗小儿多是独用此物，后医家因号为使君子。\n\n       疏：使君子得土之冲气，而兼感乎季春之令以生，故其味甘，其气温，其性无毒。甘入脾，故入足太阴、阳明。为补脾健胃之要药。小儿五疳、便浊、泻利、及腹虫，莫不皆由脾虚胃弱，因而乳食停滞，湿热瘀塞而成。脾健胃开，则乳饮自消，湿热自散，水道自利，而前证俱除矣。不苦不辛，而能杀疳蛔，此所以为小儿上药也。\n\n【主治参与】\n得芦荟、芜荑、滑石、麦芽、厚朴、橘皮，治一切疳疾，神效。\n\n又方，治小儿脾疳：使君子、芦荟等分，为末，米饮每服一钱。\n\n《全幼心鉴》治小儿蛔痛，口流涎沫：使君子为末，五更米饮调服一钱。\n\n《简便方》治小儿虚肿，头面阴囊俱浮：使君子肉一两，蜜五钱，炙尽为末，每食后米汤服一钱。\n\n《普济方》治头（疒查）面疮，使君子仁，以香油少许浸三五枚，临卧时细嚼，香油送下，久久自愈。\n\n《集简方》治虫牙疼痛，使君子煎汤频漱。\n\n【简误】\n       小儿泄痢有赤积，是暑气所伤，禁与肉豆蔻、诃子等涩药同用。亦忌食热物及饮热茶，犯之即泄。', NULL, NULL, NULL, '使君子', NULL, '35、使君子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473611, '7A8D8C031DAD9D7A5D65F425CCEDBD6F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7278, 415, 400105934, '     味甘、酸，平，无毒。主血痢，针灸疮发，洪血不可止者，傅之立已。汁涂发眉，生速而繁。\n\n      疏：鳢肠正禀北方坎水之气，故其汁玄黑，其味甘酸平而无毒，纯阴之草也。入肾，入肝，亦入胃与大小肠。善凉血，须发白者，血热也；齿不固者，肾虚有热也。凉血益血，则须发变白而齿亦因之而固矣。故古今变白之草，当以兹为胜。本经主血痢及针灸疮发，洪血不可止者，傅之立已。涂眉髪生速而繁。萧炳又谓能止血，排脓，通小肠，傅一切疮。膏点鼻中添脑者，盖以血痢由于血分为湿热所伤，针变疮发，洪血不止，亦缘病人素有血热，及如艾火，则益炽矣，血凉则不出。荣血热壅则生脓，凉血则自散。小肠属丙火，有热则不通。荣血热解，则一切疮自愈。脑为髓之海，热则消，火能消物故也。鼻窍通气于脑，故以膏点鼻中，使脑中热散，无邪剥蚀，则脑自益之矣。数者，何非凉血之功也。\n\n【主治参与】\n孙真人《千金月令》方有金陵煎，能益髭须，变白为黑：金陵草一秤，六月后收，拣青嫩无泥土者，不用洗，抹净，摘去黄叶，烂捣，新布绞取汁，以纱绢滤过，入通油器钵盛之，日中煎五日。又取生姜一斤绞汁，白蜜一斤合和，日中煎，以柳木勿停手搅，待如稀饧，药乃成矣。每早及午后各服一匙，以温酒一盏化下。如欲作丸，日中再煎，令可丸，每服三十丸，及时多合为佳。\n\n《摄生众妙》用方：取旱莲草根一斤，用无灰酒洗净，青盐四两，淹三宿，同汁入油锅中炒存性，研末。日用擦牙，连津咽之，能乌须固齿。又方：旱莲一两半，麻枯饼三两，升麻、青盐各三两半，诃子连核二十个，皂角三挺，晚蚕沙二两炒，为末，薄醋面糊丸弹子大，晒干，入泥瓶中火煅，令烟出存性，取出研末，日用揩牙。\n\n又方：取汁滴鼻中，治偏正头痛。\n\n同蓝叶各一握，油一斤，入浸，蜜封四十九日，每卧时以铁匙点一切眼疾，翳膜遮障，凉脑，再摩顶上四十九遍，久久甚佳，亦治头痛，能生发。\n\n同车前草等分，杵取汁，每空心服三杯，治小便溺血。\n\n独用瓦上焙研，每米饮下二钱，治肠风脏毒，下血不止。\n\n独用捣汁，冲极热酒饮，治痔漏疮发，外即以滓傅患处，重者不过三服。\n\n同盐少许，揉擦掌心，治风牙疼痛。\n\n【简误】\n       鳢肠性冷阴寒之质，虽善凉血，不益脾胃。病人虽有血热，一见脾胃虚败，饮食难消，及易溏薄作泄者，勿轻与服。孙真人方用姜汁和剂，盖防其冷而不利于肠胃故也。不用姜汁、椒红相兼修事服之者，必腹痛作泄。宜详审之。', NULL, NULL, NULL, '鳢肠', NULL, '34、鳢肠', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473612, '6FE2A24498FB0D1EE2D3A348B8D69727', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7279, 415, 400105933, '     味苦，平，无毒。主久痢成疳，伤寒咳嗽，温疟骨热，理腰肾，去阴汗，小儿惊痫寒热，不下食，霍乱，下痢。（《唐本》云：大寒，主骨蒸劳热，补肝胆明目，治冷热泄痢，益颜色，厚肠胃，治妇人胎蒸虚惊，治三消五痔，大人五心烦热。恶菊花、玄参、白鲜皮，解巴豆毒。服之忌猪肉，令人漏精。折之尘出如烟者真。肉似鸜鹆眼者良。）\n\n      疏：胡黄连得天地清肃阴寒之气，故其味至苦，其气大寒，性则无毒。善除湿热，故主久痢成疳，及冷热泄痢，厚肠胃。伤寒咳嗽者，邪热在手太阴、足阳明也。温疟骨蒸者，热在骨间也。理腰肾，去阴汗者，肾虚湿热下流客之，使热伏肾间也。小儿惊痫寒热，不下食者，热则生风，故发惊痫，热在胃口，故不下食也。心主五色，脾胃主肌肉，二经湿热去，则颜色自佳也。三消五痔，大人五心烦热者，无非湿热在肠胃，及火在五脏间也。大寒至苦极清之性，能清热自肠胃以次于骨，一切湿热、邪热、阴分伏热所生诸病，莫不消除。\n\n【主治参与】\n苏颂《图经》治伤寒劳复，身热，大小便赤如血色者：胡黄连一两，山栀仁二两，入蜜半两，拌和，炒令微焦，二味捣罗为末，用猪胆汁和丸梧子大，每服用生姜二片，乌梅一枚，童便三合，浸半日，去滓，食后暖童便令温，下十丸，临卧再服，甚效。\n\n《全幼心鉴》治小儿疳热，肚胀潮热，髪焦，不可用大黄、黄芩伤胃之药，恐生别证：以胡黄连五钱，五灵脂一两，为末，雄猪胆汁和丸绿豆大。米饮服一二十丸。\n\n钱乙《小儿方诀》治脾热疳疾：用胡黄连、川黄连各半两，朱砂二钱半，为末，入猪胆内扎定，以杖子钓悬于砂锅内，浆水煮一炊久，取出研烂，入芦荟、麝香各一分，饭和丸麻子大。每服五七丸至一二十丸，米饭下。\n\n又方：治小儿黄疸：胡黄连、川黄连各一两，末，用黄瓜一个，去瓤留盖，入药在内，合定，面裹煨熟，去面，捣丸绿豆大。量大小温水下。\n\n【简误】\n       胡黄连气味苦寒之至，设使阴血太虚，真精耗竭，而胃气脾阴俱弱者，虽见如上诸证，亦勿轻投。即欲用之，亦须与健脾安胃等药同用，乃可无弊。慎之！', NULL, NULL, NULL, '胡黄连', NULL, '33、胡黄连', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473613, '0708EBB65FD94EDABCF6190010A27FD1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7280, 415, 400105932, '      味甘，微寒，无毒。主除胸中热，充皮毛。久服令人益气，长须眉。\n\n       疏：莎草根禀天地温燥之气，而兼得乎土金之味，故其味甘，应有苦辛微寒，亦应微温无毒。入足厥阴气分，亦入手太阴经。气厚于味，阳中之阴，降也。血中之气药也。能行十二经八脉气分。得童子小便、苦酒渍过，良。芎为之使。辛主散，苦温主降泄。肝主怒而苦急，肺苦气上逆而主皮毛。怒则气上逆，逆则胸中热。降则肝气平而胸中热除，肺得安而皮毛自充，须眉自长矣。其云久服益气者，是亦调气之功也。苏颂又谓：治心腹中客热，膀胱间连胁下气妨，常日忧愁不乐，心忪少气。东垣治一切气，霍乱吐泻，腹痛，肾气膀胱冷气。世医专用以治妇人崩漏带下，月经不调者，皆降气调气、散结理滞之所致也。盖血不自行，随气而行，气逆而郁则血亦凝涩，气顺则血亦从之而和畅，此女人崩漏带下，月事不调之病，所以咸须之耳。然须辅之以益血凉血之药，气虚者兼入补气药，乃可奏功也。海藏云：本草不言治崩漏，而方中用治崩漏，是能益气而止血也。又能逐去瘀血，是推陈也。凡气郁血滞，必用之药。童便浸透炒黑，能止血，治崩漏。\n\n【主治参与】\n香附一斤，童子小便浸透，砂器中炒，炒时不住手洒童便，火勿过猛，炒三昼夜为度，川木耳四两，纸包裹，以新瓦两片夹定，绳缚泥固，火煅存性，觉烟起良久，急去火，取置冷地，候冷取出。同香附研极细如面。每五七分，淡醋汤调，空心服。此治血崩秘方，累试有验。\n\n交感丹：凡人中年，精耗神衰。盖由心血少，火不下降；肾气惫，水不上升，致心肾隔绝，荣卫不和。上则多惊，中则塞痞，饮食不下，下则虚冷遗精。愚医徒知峻补下田，非惟不能生水滋阴，而反见衰悴。但服此方半年，屏去一切暖药，绝嗜欲，然后习秘固溯流之术，其效不可殚述：香附子一斤，新水浸一宿，炒黄，同茯神四两为末，蜜丸弹子大。每早细嚼一丸，以降气汤下。降气汤用香附半两，茯神二两，炙甘草一两半，为末，点沸汤服前药。\n\n《和剂局方》升降诸气，并一切气病，痞胀、喘、哕、噫酸、烦闷，虚痛走注。常服开胃，消痰，散壅，思食。早行，山行，尤宜服之，去邪辟瘴：香附子炒四百两，沉香十八两，缩砂仁四十八两，炙甘草一百二十两，为末。每服一钱，盐汤点服。\n\n又方：香附一片，砂仁八两，炙甘草四两，为末，盐汤服。治一切气疾，心腹胀满，噎塞，噫气，吞酸，痰逆呕恶，及宿酒不解。\n\n又方：香附二十两，乌药十两，甘草炒一两，为末。盐汤服二钱。能调中快气，治心腹刺痛。\n\n《集简方》：香附二两，蕲艾五钱，以醋汤同煮熟，去艾，炒为末，醋糊丸。白汤服二钱。治心气痛，腹痛，少腹痛，血气痛不可忍。\n\n《仁存方》：香附、皂荚水浸，半夏各一两，白矾末半两，姜汁面糊丸。姜汤下一二钱。治停痰宿饮，风气上攻，胸膈不利。\n\n同南星等分为末，姜汁糊丸。治老少痃癖，往来疼痛。\n\n《集简方》：香附末二钱，以海藻一钱，煎酒，空心调下。并食海藻，治㿗疝胀痛及小肠气。\n\n《妇人良方》：香附炒一两，荔枝核烧存性半两，为末，每二钱米饮调下，治血气刺痛。\n\n《瑞竹堂方》四制香附丸：香附一斤，分作四分。用酒、醋、盐水、童便，各浸，春三、夏一、秋五、冬七日，淘净晒捣，微焙为末，醋糊丸梧子大，每酒下七十丸。治女人经候不调兼诸病。瘦人加泽兰、赤茯苓末二两，气虚加四君子料，血虚加四物料。\n\n《济生方》：香附四两，茯苓、甘草炙各一两，橘红二两，为末。沸汤下二钱。治妇人气盛血衰，变生诸证，头晕、腹满皆宜。\n\n独用炒为末，极热，酒服二钱，主愈下血血崩，或五色漏带。并宜常服滋血调气，乃妇人之仙药也。\n\n同赤芍药为末，加盐一捻，煎服。治赤白带下及崩漏不止。\n\n君缩砂仁、炙甘草，能临产顺胎，九月、十月服此，永无惊恐。独用为末，童便调下二钱，治气郁吐血。\n\n君川芎，治气郁头痛。\n\n独用为末，莱菔子煎汤，早夜各服二钱，治耳卒聋闭。\n\n【简误】\n        香附香燥，苦温带辛，凡月事先期者，血热也，法当凉血，禁用此药。误犯则愈先期矣。', NULL, NULL, NULL, '莎草根', NULL, '32、莎草根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473614, 'FD07F2DFC6834D259D424425189F162D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7281, 415, 400105931, '     味辛，温，无毒。主金疮生肌。\n\n      疏：白药子禀天地清寒之气，而兼金水之性，故味辛。经云气温，日华子云冷。当是辛寒之药无疑。故无毒而能解毒。金疮出血过多必发热，热则作痛，不得生肌矣，凉血清热则其痛自止，肌自生也。又《药性论》亦可单用，味苦，能治喉中热塞，噎痹不通，胸中隘塞，咽中常痛，肿胀。日华子云：性冷，消痰，止嗽，治渴，并吐血喉闭，消肿毒。又云：剪草，根名白药。详味二条所主，皆解热散结之功，则其为寒明矣。入肺，入胃，不言可知。\n\n【主治参与】\n施州人取白药子并野猪尾二味，洗净去粗皮，焙干，等分为末，酒调服二钱许，疗心气痛，解热毒，甚效。\n\n又诸疮痈肿不散者，取生根烂捣傅贴，干则易之，无生者用细末，水调涂之亦可。\n\n崔元亮《海上方》治一切天行热病，取白药研如面二钱，浆水一大盏，空腹顿服之，使仰卧一食顷，候心头闷乱，或恶心，腹内如车鸣㽲刺痛，良久，当有吐利数行，勿怪。欲服药时，先令煮浆水粥，于井中悬着待冷。若吐利过度，即吃冷粥一碗止之，不吃即困人。\n\n《经验方》治妊娠伤寒，护胎：以白药子为细末，鸡子清调摊于棉纸上，可如碗大，自脐贴至脐下胎存生处，干即以湿水润之。\n\n《衍义》又为治马肺热药，有效。\n\n《圣惠方》治风热上壅，咽喉不利：白药三两，黑牵牛五钱，同炒香，去牵牛，一半为末，防风末三两和匀，每一钱，水调服。\n\n又方治吐血不止：白药煅存性，糯米饮服三钱。\n\n又方，治咽喉肿痛：白药末一两，龙脑香二分五厘，生蜜和丸芡实大。每含咽一丸。\n\n又方，名铁罩散，治胎热不安：用白药子一两，白芷五钱，为末。每服二钱，紫苏汤下。心烦热，入白砂糖少许。\n\n《经验良方》治衄血不止：红枣肉、白药各煅存性，等分为末，糯米饮调服二钱许。\n\n【简误】\n        苦寒辛散之物，凡病虽有血热吐衄等证，若脾胃素弱、易于作泄者，勿服。', NULL, NULL, NULL, '白药', NULL, '31、白药', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473615, 'B56FEACE627592CC6FE510DBB46BFD57', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7282, 415, 400105930, '        味甘，微温（蜀本云微寒），无毒。主胸胁逆气，咳嗽上气。\n\n       疏：白前感秋之气而得土之冲味，故味甘辛，气微温。苏恭又谓微寒。性无毒，阳中之阴，降也。入手太阴肺家之要药。甘能缓，辛能散，温能下。以其长于下气，故主胸胁逆气，咳嗽上气。二病皆气升气逆，痰随气壅所致。气降则痰自降，能降气则病本立拔矣。微温，微寒，见人参条下。\n\n【主治参与】\n         寇宗奭曰：白前能保定肺气，治嗽多用，以温药相佐使尤佳。\n\n仲景《金匮要略》治嗽而脉浮，用泽漆汤中有白前。苗似细辛而大，根色白，亦似白薇，又似牛膝，脆而易折，不若白薇之可弯而不折也。苦者非是。\n\n《外台》方治久嗽吐血，用白前、桔梗、桑根白皮各三两，甘草炙一两，水六升，煮一升，分三服。忌猪肉、菘菜。\n\n《深师方》治久咳上气，体肿短气，昼夜倚壁不得卧，常作水鸡声者，白前汤主之：白前二两，紫菀、半夏各三两，大戟七合，以水一斗，渍一宿，煮取三升，分作数十服。第进一服，勿相继，以须药力之行。\n\n【简误】\n        白前辛温，走散下气之药，性无补益。凡咳逆上气，咳嗽气逆，由于气虚气不归元，而不由于肺气因邪客壅实者，禁用。\n《深师方》中所主久咳上气，体肿短气胀满，当是有停饮、水湿、湿痰之病，乃可用之。病不由于此者，不得轻施。', NULL, NULL, NULL, '白前', NULL, '30、白前', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473616, '1A3E5E0A7D49F7A23052ADFAB2663531', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7283, 415, 400105929, '      味苦，辛，温，无毒。主心腹痛，中恶疰忤鬼气，霍乱冷气，吐酸水，解毒，食饮不消，酒磨服之。又疗妇人血气，丈夫奔豚。\n\n        疏：蓬莪术感夏末秋初之气，而得土金之味，故其味苦辛，其气温而无毒。阳中阴，降也。入足厥阴肝经气分，能破气中之血。入气药发诸香。主积聚诸气，为最要之药。与京三棱同用之，良。心腹痛者，非血气不得调和，即是邪客中焦所致。中恶疰忤鬼气，皆由气不调和，脏腑壅滞，阴阳乖隔，则疫疠、疰忤、鬼气得以凭之。荗气香烈，能调气通窍，窍利则邪无所容而散矣。解毒之义亦同乎是。其主霍乱，冷气，吐酸水，乃饮食不消，皆行气之功也，故多用酒磨。又疗妇人血气结积，丈夫奔豚，入肝破血行气故也，多用醋磨。郁金入心亦入肝，专主血分，亦散肝郁。荗与三棱专能行气破积，姜黄行气破血，入脾为多。\n\n【主治参与】\n得人参、橘皮、缩砂蜜、京三棱、肉豆蔻、青皮、麦蘗、谷蘗、木香，消一切饮食停滞积聚，及小儿癥癖，甚良。\n\n杨子建《护命方》治一切冷气抢心切痛，发即欲死，久患心腹痛时发者：蓬莪术醋煮二两，木香煨一两，为末，淡醋汤下半钱。\n\n《普济方》治妇人血气游走作痛及腰痛，荗同干漆等分，为末，酒服二钱。腰痛，核桃酒下。\n\n《保幼大全》治小儿盘肠内钓痛。以荗半两，用阿魏一钱，化水浸周时，焙研。紫苏汤下一字。\n\n《十全普救方》治小儿气痛：以荗炮熟为末，热酒服一钱。\n\n《保幼大全》治初生吐乳不止：用荗少许，盐二厘，乳一合，煎二五沸，入牛黄二厘，服之甚效。\n\n《危氏得效方》治浑身燎泡，每个出水，有靥一片，如指甲大，其泡复生，抽尽肌肉，即不可治：用荗同三棱，各五钱，为末，分三服，酒调连进，愈。\n\n【简误】\n        蓬莪术行气破血散结，是其功能之所长。若夫妇人、小儿气血两虚，脾胃素弱，而无积滞者用之，反能损真气，使食愈不消而脾胃益弱。即有血气凝结，饮食积滞。亦当与健脾开胃，补益元气药同用，乃无损耳。', NULL, NULL, NULL, '蓬莪术', NULL, '29、蓬莪术', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473617, '76F46D296159ACCE61D80FB541672471', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7284, 415, 400105928, '      味辛，温，无毒。主虚劳冷泻，宿食不消，赤白泄痢，腹中虚痛，下气。\n\n      疏：缩砂蜜禀天地阳和之气以生，故其味辛，其气温，其性无毒。入足太阴、阳明、少阴、厥阴，亦入手太阴、阳明、厥阴。可升可降，降多于升，阳也。辛能散，又能润，温能和畅通达。虚劳冷泻，脾肾不足也。宿食不消，脾胃俱虚也。赤白滞下，胃与大肠因虚而湿热与积滞客之所成也。辛以润肾，故使气下行，兼温则脾肾之气皆和，和则冷泻自止，宿食自消，赤白滞下自愈。气下则气得归元，故腹中虚痛自已也。甄权用以止冷气痛，止休息痢，消化水谷，温暖肝肾。陈藏器用以主上气奔豚，鬼疰邪气。鬼疰必由于脾肾两虚、阴阳乏绝故也。日华子用以主一切气，转筋霍乱。转筋霍乱必由脾胃为邪所干，胃气壅滞闭塞而成。杨氏用以止痛安胎。气结则作痛，气逆则胎不安。洁古用以治脾胃气结滞不散，皆下气散结，温中和胃，入脾、入肾、入肝、入命门、入大肠之故耳。\n\n【主治参与】\n缩砂蜜，气味辛温而芬芳，香气入脾，辛能润肾，故为开脾胃之要药，和中气之正品。若兼肾虚气不归元，非此为向导不济，殆胜桂、附热毒之害多矣。好古谓得人参、益智则入脾，得黄檗、茯苓则入肾，得赤白石脂则入大小肠也。\n\n得人参、橘皮、藿香、白茯苓、白芍药、炙甘草，治泄泻兼呕吐，及不思食。\n\n得藿香、橘皮、木瓜，治霍乱转筋，腹痛吐泻。\n\n独用两许，炒为末，入食盐三钱，滚汤一碗，泡汤冷服，治干霍乱，累效。\n\n《药性论》治冷滑下痢不禁，虚羸：以缩砂仁为末，以羊子肝薄切糁之，瓦上焙干，为末，入干姜末等分，饭丸梧子大。每四十丸，白汤下，日二服。\n\n《直指方》治遍身肿满，阴亦肿者：用缩砂仁、土狗一个，等分研，和老酒服之。\n\n《简便方》治痰气膈胀：用砂仁捣碎，以萝卜汁浸透，焙干为末。每服二钱，食远沸汤服。\n\n《简便方》治上气咳逆：用砂仁洗净炒研，生姜连皮，等分捣烂，热酒食远泡服。\n\n《温隐居方》治子痫昏冒：用砂仁和皮炒黑，热酒调下二钱，不饮者米饮下。此方安胎止痛，其效不可尽述。\n\n孙尚药方：治妊娠胎动，偶因所触，或跌堕伤损，致胎不安，痛不可忍者：用砂仁熨斗炒热，去皮用仁，捣碎。每服二钱，热酒调下。须臾觉腹中胎动极热，即胎已安矣。神效。\n\n《妇人良方》治妇人血崩：用砂仁于新瓦上焙，研末，米饮服三钱。\n\n《直指方》治牙齿疼痛，缩砂仁常嚼之良。\n\n《事林广记》治一切食毒，用砂仁末，水服二钱。\n\n【简误】\n       缩砂蜜，气味辛温，阳药也。凡腹痛属火，泄泻得之暑热，胎动由于血热，咽痛由于火炎，小儿脱肛由于气虚，肿满由于湿热，上气咳逆由于火冲迫肺，而不由于寒气所伤，皆须详察简别，难以概用。误则有损无益，勿易视也。本非肺经药，今亦有用之于咳逆者，通指寒邪郁肺，气不得舒，以致咳逆之证。若咳嗽多缘肺热，此药即不应用矣。', NULL, NULL, NULL, '缩砂蜜', NULL, '28、缩砂蜜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473618, '95C06385CB1359A6560773CC538F1F92', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7285, 415, 400105927, '       味辛，大温，无毒。主五劳七伤，风虚冷，骨髓伤败，肾冷精流，及妇人血气，堕胎。一名破故纸。（忌羊肉、诸血。得胡桃良）\n\n      疏：补骨脂禀火土之气，而兼得乎天令之阳，故其味辛，其气大温，性则无毒。阳中微阴，降多升少。入手厥阴心包络、命门、足太阴脾经。能暖水脏，阴中生阳，壮火益土之要药也。其主五劳七伤，盖缘劳伤之病，多起于脾肾两虚，以其能暖水脏，补火以生土，则肾中真阳之气得补而上升，则能腐熟水谷，蒸糟粕而化精微。脾气散精，上归于肺，以荣养乎五脏，故主五脏之劳，七情之伤所生病。风虚冷者，因阳气衰败，则风冷乘虚而客之，以致骨髓伤败，肾冷精流。肾主骨而藏精，髓乃精之本，真阳之气不固，即有证见矣。固其本而阳气生，则前证自除。男子以精为主，妇人以血为主。妇人血气者，亦犹男子阳衰肾冷而为血脱气陷之病，同乎男子之肾冷精流也。大温而辛，火能消物，故能堕胎。\n\n【主治参与】\n《三因方》治精气不固：用破故纸、青盐，等分，同炒为末。每服二钱，米饮下。\n\n《普济方》治小便无度，肾气虚寒：用破故纸十两酒蒸，茴香十两盐炒，为末，酒糊丸梧子大。每服百丸，盐、酒下。或以末糁猪肾，煨食之。\n\n《婴童百问》治小儿遗尿，膀胱冷也，夜属阴，故小便不禁：用破故纸炒为末，每夜热汤服五分。\n\n《和剂方》补骨脂丸，治下元虚败，脚手沉重，夜多盗汗，纵欲所致。此药壮筋骨，益元气。补骨脂四两炒香，菟丝子四两酒蒸，胡桃肉一两去皮，沉香研细一钱半，炼蜜丸如梧子大。每服二三十丸，空心盐汤、温酒任下。自夏至起，冬至止，日一服。此乃唐宣宗时，张寿太尉知广州，得方于南番人。有诗云：三年时节向边隅，人信方知药力殊。夺得春光来在手，青娥休笑白髭须。\n\n《经验方》治虚劳，男子女人五劳七伤，下元虚冷，一切风病，四肢疼痛，驻颜壮气，乌髭须：用补骨脂一斤，酒浸一宿，晒干，却用乌油麻一升和炒，令麻子声绝，簸去，只用补骨脂，为末，醋煮面糊丸如梧子大。每服二三十丸，空心温酒、盐汤任下。\n\n又方：治肾虚腰痛。用破故纸一两，炒为末，温酒服三钱，神效。或加木香一钱。\n\n《和剂局方》青娥丸，治肾气虚弱，风冷乘之。或血气相抟，腰痛如折，俯仰不利，或因劳役伤肾，或湿痹伤腰，或堕跌损伤，或风寒客抟，或气滞不散，皆令腰痛，或腰间如物重坠：用破故纸酒浸炒一斤，杜仲去皮切片姜汁炒一斤，胡桃肉去皮二十个，为末，以蒜捣膏一两，和丸梧子大。每空心温酒服二十丸，妇人淡醋汤下。常服壮筋骨，活血脉，乌髭须，益颜色。\n\n夏子益《奇疾方》治玉茎不痿，精滑无歇，时时如针刺，捏之则脆，此名肾漏：用破故纸、韭子各一两，为末。每用三钱，水二盏，煎六分服，日三次，愈则止。\n\n二神丸，治脾肾虚泻：用破故纸炒半斤，肉豆蔻生用四两，为末，肥枣研膏，和丸梧子大。每服五七十丸，空心米饮下。\n\n《本事方》加木香二两，名三神丸。\n\n《直指方》治打坠腰痛，瘀血凝滞。用破故纸炒，茴香炒，辣桂，等分为末。每热酒服二钱。\n\n唐・郑相国自叙云：予为南海节度，年七十五。粤地卑湿，伤于内外，众疾俱作，阳气衰绝，服乳石补药，百端不应。元和七年，有诃陵国舶主李摩诃，知予病状，遂传此方并药。予初疑而未服。摩诃稽首固请，遂服之。经七八日而觉应验。自尔常服，其功神效。十年二月，罢郡归京，录方传之：用破故纸十两，净去皮，洗过，曝干，酒浸蒸，再曝，捣筛令细；胡桃瓤二十两，汤浸去皮，细研如泥。更以好蜜和，令如饴糖，瓷器盛之。旦日以暖酒二合，调药十匙服之，便以饭压。如不饮酒人，以暖熟水调之。饵久则延年益气，悦心明目，补添筋骨。但禁芸薹、羊肉，余无所忌。此物本自外番随海舶而来，非中华所有。番人呼为补骨脂，语讹传为破故纸也。王绍颜《续传信方》载其事颇详，故录之。\n\n按白飞霞《方外奇方》云：破故纸属火，收敛神明，能使心包之火与命门之火相通。故元阳坚固，骨髓充实，涩以治脱也。胡桃属木，润燥养血，血属阴，恶燥，故油以润之。佐破故纸，\n\n有木火相生之妙。故语云：破故纸无胡桃，犹水母之无虾也。\n\n【简误】\n       补骨脂，阳药也。凡病阴虚火动，阳道妄举，梦遗，尿血，小便短涩，及目赤，口苦，舌干，大便燥结，内热作渴，火升目赤，易饥嘈杂，湿热成痿，以致骨乏无力者，皆不宜服。', NULL, NULL, NULL, '破故纸,补骨脂', NULL, '27、破故纸,补骨脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473619, 'C18021272F6E896ACB8FB3A8035C673E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7286, 415, 400105926, '       味辛，温，无毒。主鬼气，温中，治积冷心腹胀痛，霍乱中恶，冷疰，呕沫冷气，消食止泄，小儿乳霍。糯米粉裹煨，去粉，擂碎。忌铜铁器。\n\n       疏：肉豆蔻禀火土金之气，故味辛气温而无毒。入足太阴、阳明经，亦入手阳明大肠。辛味能散能消，温气能和中通畅。其气芬芳，香气先入脾，脾主消化，温和而辛香，故开胃，胃喜暖故也。故为理脾开胃，消宿食，止泄泻之要药。香能辟恶除不祥，又中气不虚，则邪恶之气不能入，故主鬼气及温中。脾主中焦，胃为后天生气之本，脾胃之阳气旺，则积冷心腹胀满，霍乱、中恶、冷疰，呕沫冷气、食不消、泄不止、小儿乳霍，诸证自除矣。\n\n【主治参与】\n君人参、补骨脂、吴茱萸、五味子、砂仁，为治肾泄及冷泄之圣药。\n\n得缩砂蜜、橘皮、人参、红曲、山查肉、藿香、麦芽，为开胃进饮食，消宿食，止泻之上剂。\n\n独用修事为末，以枣肉和丸，或为末，缩砂汤下，名公子登筵散。言服之即可赴席，其开胃进食消导之功烈矣。\n\n《百一选方》治久泻不止：用肉豆蔻一两，木香二钱五分，为末，枣肉和丸。米饮下四五十丸。又方：肉豆蔻煨一两，熟附子七钱，为末，糊丸。米饮服四五十丸。\n\n《瑞竹堂方》治老人虚泻：肉豆蔻三钱煨研，乳香一两，为末。\n\n《全幼心鉴》治小儿泄泻：用肉豆蔻五钱，乳香二钱半，生姜五片，同炒黑色，去姜研为膏，收入密器，旋丸绿豆大。每量大小，米饮下。\n\n《圣惠方》治冷痢腹痛不能食者：肉豆蔻一两，去皮，醋和面裹煨，捣末。每服一钱，粥饮调下。\n\n【简误】\n       大肠素有火热，及中暑热泄暴注，肠风下血，胃火齿痛，及湿热积滞方盛，滞下初起，皆不宜服。', NULL, NULL, NULL, '肉豆蔻', NULL, '26、肉豆蔻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473620, 'BF83523BBBA324C8C5479F6835A6C896', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7287, 415, 400105925, '      味辛，温，无毒。主破血，产后诸病因血所为者，妇人月经不调，腹中结块，崩中淋露，产后血晕。暴血冲上，因损下血。或酒摩及煮服。\n\n       疏：延胡索禀初夏之气，而兼得乎金之辛味，故味辛气温而无毒。入足厥阴，亦入手少阴经。温则和畅，和畅则气行。辛则能润而走散，走散则血活。血活气行，故能主破血，及产后诸病因血所为者。妇人月经之所以不调者，无他，气血不和，因而凝滞，则不能以时至而多后期之证也。腹中结块，产后血晕，暴血冲上，因损下血等证，皆须气血和而后愈，故悉主之也。崩中淋露，利守不利走，此则非与补气血同用，未见其可。\n\n【主治参与】\n君当归、生地黄、牛膝、益母草、童便，则主产后血晕，有神。\n\n得四物汤、白胶、牛膝、香附，则主妇人经阻少腹作痛，或结块。\n\n《活人书》治小便尿血。用延胡索一两，朴硝七钱半，为末。每服四钱，水煎服。非蓄血瘀滞者，不可用。\n\n《胜金方》治膜外气疼及气块。延胡索不限多少，为末，猪胰一具，切作块子，炙熟，蘸末频食之。\n\n《圣惠方》治热厥心痛，或发或止，久不愈，身热足寒者：用延胡索去皮，金铃子肉等分，为末。每温酒，或白滚汤下二钱。\n\n《济生方》治妇女血气腹中刺痛，经候不调。用延胡索去皮醋炒，当归酒浸炒，各一两，橘红二两为末，酒煮，米糊丸梧子大。每服一百丸，空心艾醋汤下。\n\n《圣惠方》治产后诸病，凡产后秽污不尽腹满，及产后血晕心头硬，或寒热不禁，或心闷手足烦热，气力欲绝诸病。并用延胡索炒研，酒服二钱。\n\n《直指方》治疝气危急：用延胡索盐水炒，全蝎去毒生用，等分为末，空心盐酒下。又方：治冷气腰痛。用延胡索、当归、桂心，等分为末，温酒服三四钱，随量频进，以止为度。\n\n《圣惠方》治坠落车马，筋骨痛不止。延胡索末，豆淋酒一服二钱，日二服。\n\n【简误】\n       此药性温味辛，能走而不能守。故经事先期，及一切血热为病，凡崩中淋露，皆应补气血，凉血清热则愈。一切辛走之药，法所应禁。', NULL, NULL, NULL, '延胡索', NULL, '25、延胡索', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473621, '5BE139D6768196BBA1F400DC4DEF6CA7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7288, 415, 400105924, '      味苦，寒，无毒。主热风烦闷，胸膈间热气，明目镇心，小儿癫痫惊风，疗五疳，杀三虫，及痔病疮瘘，解巴豆毒。俗呼为象胆，盖以其味苦如胆故也。生波斯国。似黑锡。\n\n        疏：芦荟禀天地阴寒之气，故其味苦，其气寒，其性无毒。寒能除热，苦能泄热燥湿，苦能杀虫，至苦至寒，故为除热杀虫之要药。其主热风烦闷，胸胁间热气，明目，镇心，小儿癫痫惊风，疗五疳，杀三虫者，热则生风，热能使人烦闷，热除则风热烦闷及胸膈间热气自解。凉肝故明目，除烦故镇心。小儿癫痫惊风，热所化也，五疳同为内热脾胃停滞之证，三虫生于肠胃湿热，痔病疮瘘亦皆湿热下客肠脏，致血凝滞之所生，故悉主之。能解巴豆毒，亦除热之力也。详其功用，是足厥阴、足太阴二经药，亦可兼入手少阴经。\n\n【主治参与】\n同厚朴、橘红、甘草、青黛、芜荑、百草霜、旋复花，为末，以砂仁汤吞，治小儿诸疳。一岁一分，甚效。\n\n《卫生易简方》治脾疳，与使君子等分，为末。每服一二钱，米饮调下。\n\n李珣用以主小儿诸疳热。\n\n甄权单用杀疳蛔，及吹鼻杀脑疳，除鼻痒。\n\n苏颂研末傅䘌齿，甚效。治湿癣出黄水，有神。\n\n治大便不通。真芦荟研细七钱，朱砂研如飞面五钱，滴好酒和丸。每服三钱，酒吞。朝服暮通，暮服朝通。须天晴时修合为妙。\n\n【简误】\n        其味至苦，其性大寒，主消不主补。凡儿脾胃虚寒作泻及不思食者，禁用。', NULL, NULL, NULL, '芦荟', NULL, '24、芦荟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473622, '5A8429BC3C9D59770FF893A32AAC0A71', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7289, 415, 400105923, '     味辛、苦，寒，无毒。主血积，下气，生肌，止血，破恶血，血淋，尿血，金疮。\n\n      疏：郁金禀天令清凉之气，而兼得土中金火之味，故其味辛苦，其气寒而无毒。洁古论气味俱薄，阴也，降也，入酒亦能升。入手少阴、足厥阴，能通足阳明经。辛能散，苦能泄，故善降逆气。入心、肝、胃三经，故治血积。气降而和，则血凝者散，故主生肌止血。其破恶血，治血淋尿血，主金疮者，调气行血之功也。单用亦治女人宿血气心痛，冷气结聚。温醋磨服之。入心凉血，故洁古用以凉心。入足阳明，故治阳毒入胃，下血频痛。其性轻扬，能开郁滞，故为调逆气，行瘀血之要药。\n\n【主治参与】\n郁金同韭菜、番降香、当归、生地黄、童便，能治怒气伤肝吐血。又治鼻衄、唾血，喉中血腥气，及经脉逆行。有痰，方加竹沥。\n\n郁金七两，同明矾三两，为细末，薄米糊为丸，梧子大。每服五十丸，白汤下。昔人曾治妇人癫狂，十年不愈，初服此药，心胸间有物脱去，即神气洒然，再服而苏。此惊忧痰血，总聚心窍所致。此药入心去恶血，明矾化顽痰故也。\n\n庞安常《伤寒论》云：痘疹始有白泡，忽搐入腹，渐作紫黑色，无脓，日夜叫乱者：郁金一枚，甘草二钱半，水半碗煮干，去甘草，切片，微火烘燥为末，入真片脑半钱。每用一钱，以生猪尾血五七滴，新汲水调下，不过二服，甚者毒气从手足心出如痈状乃瘥。此乃五死一生之候也。\n\n又《范石湖文集》云：岭南有采生之害，其术于饮食中行厌胜法，致鱼肉能反生于人腹中，而人已死，则阴役其家。初得觉胸腹痛，次日刺人，十日则生在腹中也。凡胸膈痛，即用升麻或胆矾吐之。若膈下痛，急以米汤调郁金末二钱服，即泻出恶物。或合升麻、郁金服之。不吐则下。李巽岩侍郎为雷州推官，鞠狱得此方，活人甚多。\n\n【简误】\n         郁金本入血分之气药，其治已上诸血证者，正谓血之上行，皆属于内热火炎。此药能降气，气降即是火降，而其性又入血分，故能降下火气，则血不妄行。丹溪不达此理，乃谓其上行治血则误矣。凡病属真阴虚极，阴分火炎，薄血妄行，溢出上窍，而非气分拂逆，肝气不平，以致伤肝吐血者，不宜用也。即用之亦无效。', NULL, NULL, NULL, '郁金', NULL, '23、郁金', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473623, '945F4A3F9FFBEA6C315BC00022D7541D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7290, 415, 400105922, '       味咸、寒，无毒。主解诸药毒，小儿诸热，惊痫，发热，天行头痛寒热，并水研服之。亦摩傅热疮，恶肿，金疮下血，蛇犬等毒。染淀，亦堪傅热毒恶肿，蛇虺螯毒。\n\n        疏：青黛，外国蓝靛之英华也。禀水土阴寒之气以生，故味咸寒而无毒。甄权谓其甘平，以其得土气之厚也。故可解诸药毒，及小儿诸热，惊痫发热，天行头痛寒热，并水研服之。亦磨傅热疮恶肿，金疮下血，蛇犬等毒。波斯国来及太原产者胜。如不可得，即用染瓮上沫之紫碧色者，亦可。\n\n【主治参与】\n得芜荑、使君子肉、胡黄连、芦会，杀虫除热，及小儿一切疳积病。\n\n《医学正传》治心口热痛，姜汁调一钱服之。\n\n《圣惠方》治内热吐血，青黛二钱，新汲水下。\n\n《中藏经》治肺热咯血：用青黛一两，杏仁以牡蛎粉炒过一两，研匀，黄蜡化和，作三十饼子，方名青饼子。每服一饼，以干柿半个夹定，湿纸裹，煨香嚼食，粥饮送下，日三服。\n\n《生生编》治小儿夜啼，青黛水研服之。\n\n《宫气方》治小儿疳痢歌云：孩儿杂病变成疳，不问强羸女与男。烦热毛焦鼻口燥，皮肤枯槁四肢瘫。腹中时时更下痢，青黄赤白一般般。眼涩面黄鼻孔赤，谷道开张不可看。此方便是青黛散，孩儿百病服之安。\n\n《活人书》治伤寒赤斑，青黛二钱，水研服。\n\n【简误】\n        青黛既禀阴寒之气而生，解毒除热，固其所长，古方多有用之于诸血证者。使非血分实热，而病生于阴虚内热，阳无所附，火气因空上炎，发为吐衄咯唾等证，用之非宜。血得寒则凝，凝则寒热交作，胸膈或痛，愈增其病矣。医师宜详辨之。', NULL, NULL, NULL, '青黛', NULL, '22、青黛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473624, '1C33F6C5C38E05084E89F2F3EC83A09D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7291, 415, 400105921, '      味甘辛，温，无毒。主虚劳。叶食之，功同于子。\n\n       疏曰：萝摩子禀阳和之气以生，故其味甘辛，其气温而无毒。甘能益血，辛能润燥。辛甘属阳，故主虚劳，补益精气，强阴道。叶煮食之，功同于子，此 “唐本先附” 之说也。陈藏器又云：捣子傅金疮，生肌止血。捣叶傅肿毒，皆甘和辛润且散之遗意也。即婆婆针线包也。一名羊婆奶。\n\n【主治参与】\n《千金方》补益虚损，极益房劳，用萝摩四两、枸杞根庆、五味子、柏子仁、酸枣仁、干地黄各三两，为末，每服方寸匕，酒下，日三服。\n\n与枸杞子等分为末，酒调服亦佳。\n\n《袖珍方》治损伤出血，痛不可忍，用婆婆针线包擂水服，以渣罨疮口，立效。\n\n【简误】\n       阳道数兴、不得痿者，勿服。', NULL, NULL, NULL, '萝摩子,羊婆奶', NULL, '21、萝摩子,羊婆奶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473625, 'DE9296A5076E459D20686C10D3B18B1F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7292, 415, 400105920, '    味辛、苦，大寒，无毒。主心腹结积，疰忤，下气破血，除风热，消痈肿。功力烈于郁金。\n\n     疏：姜黄得火气多，金气少，故其味苦胜辛劣，辛香燥烈，性不应寒，宜其无毒。阳中阴也，降也。入足太阴，亦入足厥阴经。苦能泄热，辛能散结，故主心腹结积之属血分者，兼能治气，故又云下气。总其辛苦之力，破血，除风热，消痈肿，其能事也。日华子谓其能治癥瘕血块，又通月经，及扑损瘀血。苏颂谓其祛邪辟恶，治气胀及产后败血攻心。方书用以同肉桂、枳壳治右胁痛、臂痛、有效。戴元礼云：能入手臂治痛何？莫非下气破血，辛走苦泄之功欤？察其气味治疗，乃介乎京三棱、郁金之药也。\n\n【主治参与】\n得当归、生地黄、牛膝、延胡索、肉桂，治一切积血，在腹中作痛。\n\n《经验方》治中寒心痛难忍：姜黄一两，桂三两，为末。醋汤服一钱。\n\n《产宝》方治产后血痛有块：用姜黄、桂心等分，为末。酒服方寸匕，血下尽即愈。\n\n【简误】\n       凡病人因血虚臂痛，血虚腹痛，而非瘀血凝滞，气逆上壅作胀者，切勿误用。误则愈伤血分，令病转剧。慎之！慎之！', NULL, NULL, NULL, '姜黄', NULL, '20、姜黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473626, '388EFD0F1ED88B7CA6575FDF18351B96', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7293, 415, 400105919, '        味苦，平，无毒。主老癖癥瘕结块。俗传昔人患癥瘕死，遗言令开腹取之。得病块，坚硬如石，文理有五色。人谓异物，窃取削成刀柄。后因以刀刈三棱，柄消成水，乃知此可疗癥癖也。黄色体重，状若鲫鱼而小者良。\n\n疏：京三棱禀火土之气，故本经味苦平。洁古兼甘。亦应兼辛兼甘，故无毒。入足厥阴，亦入足太阴。从血药则治血，从气药则治气。老癖癥瘕，积聚结块，未有不由血瘀、气结、食停所致，苦能泄而辛能散，甘能和而入脾，血属阴而有形，此所以能治一切凝结停滞有形之坚积也。又主产后恶血血结，通月水，堕胎，止痛利气者，亦散血行气之功用也。洁古用以治心膈痛，饮食不消。海藏用以通肝经积血，皆与作者之意合也。\n\n【主治参与】\n用蓬莪术、青皮、香附、延胡索、肉桂、牡蛎、鳖甲、人参，则消一切坚癥老癖之积聚。\n\n同青皮、红蓝花、当归、川芎、生地黄、芍药、桂心、牛膝、延胡索、五灵脂，则治产后一切恶血停滞留结，及月水凝蓄不通，少腹作痛不可按。\n\n同橘皮、青皮、缩砂蜜、红曲、山查、麦芽、人参、肉豆蔻、黄连，则消一切食积并气壅塞不利。\n\n《子母秘录》治小儿气癖：三棱煮汁作羹粥，与奶母食，日亦以枣许与儿食。小儿百日及十岁已下，痫热痃癖皆理之。合人参弥良。\n\n【简误】\n       京三棱，洁古谓其辛苦甘，无毒。阴中之阳，能泻真气，真气虚者勿用。此见谛之言也。故凡用以消导，必资人参、芍药、地黄之力，而后可以无弊。观东垣五积方皆有人参，意可知已。何者？盖积聚癥癖，必由元气不足，不能运化流行致之。欲其消也，必藉脾胃气旺，方能渐渐消磨开散，以收平复之功。如只一味，专用克削，则脾胃之气愈弱，后天之气益亏，将见故者不去，新者复至矣。戒之哉！', NULL, NULL, NULL, '京三棱', NULL, '19、京三棱', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473627, 'F71A05795078A5C5CC850ECE08FB31DF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7294, 415, 400105918, '      味辛、苦，寒、微寒，无毒。主寒热，中风瘈疭，痉，惊痫邪气，除癥坚瘀血留舍肠胃，安五藏，疗痈疮，除时气头痛客热。五劳劳气，头腰痛，风噤癫疾。\n\n      疏：牡丹皮禀季春之气，而兼得乎木之性。阴中微阳，其味苦而微辛，其气寒而无毒，其色赤而象火，故入手少阴、厥阴，足厥阴，亦入足少阴经。辛以散结聚，苦寒除血热，入血分凉血热之要药也。寒热者，阴虚血热之候也。中风瘈疭，痉，惊痫，皆因阴虚内热，荣血不足之故。热去则血凉，凉则新血生，阴气复。阴气复则火不炎，而无热生风之证矣，故悉主之。痈疮者，热壅血瘀而成也。凉血行血，故疗痈疮。辛能行血，苦能泄热，故能除血分邪气，及癥坚瘀血留舍肠胃。脏属阴而藏精，喜清而恶热，热除则五脏自安矣。\n\n     《别录》并主时气头痛，客热，五劳劳气、头腰痛者，泄热凉血之功也，甄权又主经脉不通，血沥腰痛，此皆血因热而桔之候也。血中伏火，非此不除，故治骨蒸无汗，及小儿天行痘疮血热。东垣谓心虚肠胃积热，心火炽甚，心气不足者，以牡丹皮为君，亦此意也。忌胡荽。赤花者利，白花者补。\n\n【主治参与】\n神不足者手少阴，志不足者足少阴。故仲景肾气丸，用之治神志之不足。究竟牡丹皮乃入心经正药，心主血，凉血则心不热而阴气得宁。用之肾经药中者，阴阳之精，互藏其宅，神志水火藏于心肾，即身中坎离也。交则阴阳和而百病不生，不交则阴阳否而精神离矣。欲求弗夭，其可得乎？\n\n入清胃散，治阳明胃经，血热齿痛。\n\n洁古曰：叶为阳，发生也；花为阴，成实也。丹者赤色，火也，故能泻阴胞中之火。四物汤加之，治妇人骨蒸。又曰：牡丹皮入手厥阴、足少阴，故治无汗之骨蒸，然须与青蒿子、天麦门冬、沙参、地黄、五味子、牛膝、枸杞之属同用，始得其力。\n\n【简误】\n        牡丹皮，本入血凉血之药，然能行血。凡妇人血崩，乃经行过期不净，并忌与行血药同用。', NULL, NULL, NULL, '牡丹皮,牡丹, 丹皮', NULL, '18、牡丹, 牡丹皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473628, 'C2A74659BE5677D3B02BAC78692100F5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2025-01-16 10:59:58');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7295, 415, 400105917, '      味辛，温，无毒。主产后血晕口噤，腹内恶血不尽绞痛，胎死腹中，并酒煮服。亦主蛊毒下血。堪作燕脂。其苗生捣碎，傅游肿。其子吞数颗，主天行疮子不出。其燕脂，主小儿聤耳，滴耳中。\n\n      疏：红蓝花禀土与火之气，洁古、海藏皆兼甘苦温。阴中之阳，故入心。海藏以为肝经血分药也。入酒良，乃行血之要药。其主产后血晕口噤者，缘恶血不下，逆上冲心，故神昏而晕及口噤。入心、入肝，使恶血下行，则晕与口噤自止。腹内绞痛，由于恶血不尽，胎死腹中，非行血活血则不下。瘀行则血活，故能止绞痛，下死胎也。凡蛊药之毒必伤血分，此药能行血，血活则解可毒。子主天行疮子者，痘疮因血分有毒，血行则毒散，故主之也。小儿聤耳亦血凝也，血散则耳肿自消矣。\n\n【主治参与】\n热病胎死腹中，新汲水浓煮红蓝花汁，和童便热饮之，立瘥。胞衣不下，产后血晕，并同此法，无不立效。\n\n同延胡索、当归、生地黄、牛膝、赤芍药、益母草、川芎，或丸，或煎，治经阻少腹作痛及结块，良。\n\n其子：主天行痘疮血热有功，宜同生犀角、紫草、生地黄用。\n\n燕脂：其汁所造也。痘疮初发时，以之抹眼眶及眼角，可免疮子入眼。\n\n同薄荷、金丝荷叶汁，入矾末少许，滴入耳中，治聤耳。\n\n同冰片、真珠细末，治痘毒及痘疔，剔破，令人吮出恶血，抹入疮眼中良。\n\n【简误】\n       红蓝花本行血药也，血晕解，留滞行，即止。过用能使血行不止而毙，世人所不知者。', NULL, NULL, NULL, '红蓝花', NULL, '17、红蓝花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473629, 'CA4E8802FCC83099D268BAFB36315979', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7296, 415, 400105916, '       味辛、甘，温，无毒。主咳逆上气，善喘，喉痹，诸惊痫，寒热邪气，消渴，喘息呼吸。\n\n        疏：款冬花得天地阴寒之气，而兼禀乎金水之性，故凌冰雪而独秀。其味辛、甘，温而无毒，阴中含阳，降也。辛能散而能润，甘能缓而能和，温则通行不滞，善能降下。咳逆上气，善喘，喉痹，诸惊痫，寒热邪气，消渴，喘息呼吸，一皆气升火炎之病也。气降则火自降，气降则阳交于阴。水火既济，既济则火不上炎，气不逆升，肺不受邪，得清肃之常道，而诸证自退矣。杏仁为之使，得紫菀良。\n\n【主治参与】\n款冬花虽畏贝母，然得贝母、桑根白皮、紫菀、枇杷叶、栝楼根、百部、天麦门冬、杏仁，治喘逆及咳嗽反良，物有相制故也。如半夏畏生姜，得之则制其毒而愈能奏效也。\n\n得麻黄、杏仁、桑根白皮、甘草，治风寒郁实热于上焦肺分作喘，其效甚速。\n\n一味烧烟吸之，治喘嗽。具如《本草》注中所载。\n\n《济生方》痰嗽带血：款冬花、百合蒸焙，等分为末，蜜丸龙眼大。每卧时嚼一丸，薄荷汤下。\n\n款冬花，古今方用之为治嗽要药，以其辛温，散而能降，于肺无迕，无分寒热虚实，皆可施用，故无 “简误”。', NULL, NULL, NULL, '款冬花', NULL, '16、款冬花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473630, '160C191DF869976FB988EB11619015DF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7297, 415, 400105915, '      味辛，平，无毒。主诸瘘，霍乱，及蛇伤。\n\n       疏：蘹香得土金之冲气，而兼禀乎天之阳，故其味辛平，亦应兼甘无毒。辛香发散，甘平和胃。入足太阴、阳明、太阳、少阴经，故主霍乱。香气先入脾，脾主肌肉，故主诸瘘。脾主四肢，故主脚气。通肾气，膀胱为肾之腑，故主膀胱肾间冷气，及治疝气。胃和则热解，热解则口臭自除。\n\n【主治参与】\n蘹香酒炒，得川楝子、荔枝核、橘核、肉桂、苍术、木瓜、牛膝，治寒湿成疝。\n\n得炒砂仁、食盐，则主中恶腹痛，霍乱腹痛吐逆。\n\n古方：恶毒痈肿，或连阴髀间疼痛急挛，牵入少腹不可忍，一宿则杀人者，用蘹香苗叶捣取汁一升，服之，日三四进，用其滓以贴肿上。冬间根亦可用。此外国方，永嘉已来用之，起死神效。\n\n【简误】\n        蘹香辛温，胃肾多火，阳道数举，得热则呕者，勿服。', NULL, NULL, NULL, '蘹香子', NULL, '15、蘹香子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626830673473631, '9A7AD51740C96BF88BD9FEF167C02604', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 16:00:34', 1, 'admin', '2024-12-26 16:00:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7298, 416, 400106016, '       味辛，温，有大毒。主贼风在皮肤中淫淫痛，温疟，恶毒，诸痹，邪气鬼疰，蛊毒。\n\n         疏：羊踯躅，毒药也。然性能祛风寒湿，故可以治恶痹。痹者，风寒湿所成也。然非元气未虚，脾胃尚实之人，不可用。凡用此等毒药，亦须杂以安胃和气血药同用。\n【简误】\n踯躅性发散，气血虚人忌之。不可近眼。', NULL, NULL, NULL, '羊踯躅', NULL, '16、羊踯躅', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784198, '7999854366067FD58D1D413E5F7A3F91', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7299, 416, 400106015, '       味苦，微寒，有毒。主腹中邪热气，诸毒，杀三虫，去寸白，破癥瘕，除头风，止金疮。花：疗恶疮，令人泄。（赤小豆为之使。）\n\n        疏：贯众味苦，而又微寒，止应云有小毒。以其苦寒，故主腹中邪热气诸毒。三虫皆由湿热所生，苦寒除湿热，则三虫自死矣。苦以泄之，亦兼有散之之义，故破癥瘕。苦寒能除风热，故止头风。金疮出血后必发热，泄热散结，则金疮自止。\n\n【主治参与】\n         贯众一味为细末，水调一钱匕，治鼻衄有效。疫气发时，以此药置水中，令人饮此水，则不传染。\n【简误】\n         病人虚寒无实热者，禁用。', NULL, NULL, NULL, '贯众', NULL, '15、贯众', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784199, 'C6CB3F8CB25FC76E98936B09B80949CE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7300, 416, 400106014, '        味苦、甘，寒、大寒，有小毒。主蛊毒，十二水，肿满急痛，积聚，中风，皮肤疼痛，吐逆，颈腋痈肿，头痛，发汗，利大小肠。（反甘草。畏菖蒲、芦草、鼠粪。）\n\n         疏：大戟禀天地阴毒之气以生，故味苦寒而有小毒。甄权、洁古兼辛。\n\n      《别录》兼甘。应是辛多，非辛则无毒矣。苦寒故善下走而入肾肝，辛则横走无所不到矣，洁古又谓泻肺损真气。其主下蛊毒者，以蛊毒必热，必辛，辛则散，走脏腑，故假其辛寒以搜其辛热，是以毒攻毒也。苦寒下泄，故能逐诸有余之水湿热，及留饮在中下二焦，则为腹满急痛，或成积聚。苦辛甘寒，故散颈腋痈肿，利大小便，泻毒药，通月水。阴草，苦辛有毒，故又堕胎也。天行黄病，非元气实者勿用。\n\n       《经》曰：邪之所凑，其气必虚。中风之人，其虚必矣。《本经》末又谓其主中风，皮肤疼痛，吐逆者，非也！焉有虚病而可施苦寒有毒下泄之药哉？是重虚其虚也。\n\n【主治参与】\n大戟入玉枢丹、紫金锭，则解蛊毒，热毒痈疽疔肿，及蛇虫诸毒，内服外傅，取利为度。\n\n百祥丸：治痘疮变黑，干陷不发，寒而大便闭结者，用大戟一两，枣三枚，水一碗，同煮曝干，去大戟，以枣肉焙丸。从三分服至五分，以利为度。\n\n《三因方》控涎丹，治痰涎留在胸膈上下，变为诸病，或颈项、胸背、腰胁、手足、胯髀，隐痛不可忍，筋骨牵引，钓痛走易，及皮肤麻痹，似乎瘫痪，不可误作风气风毒及疮疽施治。又治头痛不可举，或睡中流涎，或咳唾喘息，或痰迷心窍，并宜此药，数服，痰涎自失，诸疾寻愈。紫大戟、白甘遂、白芥子微炒，各一两，为末，姜汁打面糊丸梧子大。每服七丸，或二十丸，以津液咽下。若取利，则服五六十丸。\n\n《千金方》中风发热。大戟、苦参各四两，白酢浆一斗，煮熟洗之，寒乃止。\n\n《生生方》：牙齿摇痛，大戟咬于痛处，良。\n\n【简误】\n       大戟阴寒，善走而下泄，洁古谓其损真气。故凡水肿不由于受湿停水，而由于脾虚，土坚则水清，土虚则水泛滥，实脾则能制水，此必然之数也。今不补脾，而复用疏泄追逐之药，是重虚其虚也。宜详辨而深戒之。惟留饮伏饮，停滞中焦，及元气壮实人患水湿，乃可一暂施耳。', NULL, NULL, NULL, '大戟', NULL, '14、大戟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784200, '86A0EBB365FFC8B4B36E9317AEBB622E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7301, 416, 400106013, '      味苦、辛，平、微寒，无毒。主痈肿恶疮败疽，伤阴死肌，胃中邪气，贼风鬼击，痱缓不收，除白癣疥虫。（紫石英为之使。恶理石。畏李核、杏仁。反乌头。）\n\n       疏：白及，《本经》味苦平。《别录》加辛、微寒。李当之大寒。日华子加甘。东垣亦微寒，谓其性涩。阳中之阴，收也。辛为金味，收为金气，其为得季秋之气，而兼金水之性者哉，宜乎入肺理伤有奇效矣。苦能泄热，辛能散结，痈疽皆由荣气不从，逆于肉里所生，败疽、伤阴死肌、皆热壅血瘀所致，故悉主之也。胃中邪气者，即邪热也。贼风鬼击，痱缓不收，皆血分有热，湿热伤阴之所生也。入血分以泄热，散结逐腐，则诸证靡不瘳矣。\n\n【主治参与】\n白及性涩，破散中有收敛，盖去腐逐瘀以生新之药也。得白敛、红药子，加脑、麝、乳、没，治一切痈疽肿毒，止痛散结排脓，有神。\n\n一味为细末，米饮调三钱服，治损肺吐血有奇效。\n\n《经验方》治鼻衄不止，津调白及末，涂山根上，仍以水服一钱，立止。\n\n《袖珍方》治疔疮肿毒：白及末半钱，以水澄之，去水，摊于厚纸上贴之。\n\n《永类钤方》治打跌骨折：酒调白及末二钱服，其功不减于自然铜、古铢钱也。\n\n《济急方》治手足皲裂：白及末水调塞之，勿犯水。\n\n真人方：治汤火伤灼，白及末，油调傅之。\n\n【简误】\n       痈疽已溃，不宜同苦寒药服。', NULL, NULL, NULL, '白及', NULL, '13、白及', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784201, 'D28BE043E8EF27C5C8C04AB894CF2382', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7302, 416, 400106012, '      味苦、甘，平、微寒，无毒。主痈肿疽疮，散结气，止痛除热，目中赤，小儿惊痫，温疟，女子阴中肿痛，下赤白，杀火毒。（反乌头。）\n\n       疏：白敛得金气，故味苦平，平应作辛。\n\n      《别录》兼甘。其气微寒无毒。苦则泄，辛则散，甘则缓，寒则除热，故主痈肿疽疮，散结止痛。盖以痈疽皆由荣气不从，逆于肉里所致。女子阴中肿痛，亦由血分有热之故。火毒伤肌肉，即血分有热，目中赤，赤血热为病。散结凉血除热，则上来诸苦蔑不济矣。其治小儿惊痫，温疟，及妇人下赤白，则虽云惊痫属风热，温疟由于暑，赤白淋属湿热，或可通用。然病各有因，药各有主，以类推之，恐非其任矣。尚俟后哲详之。总之，为疔肿痈疽家要药，乃确论也。\n\n【主治参与】\n白敛得白及、红药子，加朱砂、雄黄、乳、没、脑、麝，为傅痈疽、止痛散毒之上药。\n\n《肘后方》治发背初起，水调白敛末傅之。\n\n《圣惠方》治疔疮初起，同上。\n\n陶隐居治一切痈肿：白敛、赤小豆、茜草，为末，鸡子白调涂之。\n\n又方：白敛二分，藜芦一分，为末。酒和贴之，日三上。\n\n《御药院方》治面鼻酒皶，白敛、白石脂、杏仁各半两，为末。鸡子调涂，日一洗。\n\n《肘后方》治面生粉刺：白敛二分，杏仁半分，鸡屎白一分，为末，蜜和杂水拭面。\n\n谈野翁治冻耳成疮：白敛、黄檗，等分为末，生油调搽。\n\n《外台》方治汤火灼烂：白敛末傅之。\n\n《圣惠方》治铁刺诸哽，及竹木哽在咽中：白敛、半夏泡，等分为末，酒服半钱，日二服。又治刺在肉中，方同上。\n\n《千金方》治风痹筋急，肿痛，屈转异常处：白敛二分，熟附子一分，为末。每酒服半刀圭，日二服。以身中热行为候，十日便觉。忌猪肉、冷水。《瑞竹堂方》治诸疮不敛口：白敛、赤敛、黄檗各三钱，炒研，轻粉一钱，用葱白浆水洗净，傅之。\n\n【简误】\n        痈疽已溃不宜服。', NULL, NULL, NULL, '白敛', NULL, '12、白敛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784202, '4F99E7AA3EC2C994569218B87243F03F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7303, 416, 400106011, '      味苦、甘，寒、大寒，有毒。主大腹，疝瘕腹痛，面目浮肿，留饮宿食，破癥坚积聚，利水谷道，下五水，散膀胱留热，皮中痞，热气肿满。（瓜蒂为之使。恶远志。反甘草。）\n\n      疏：甘遂禀天地阴寒之气以生，故其味苦，其气寒而有毒，亦阴草也。水属阴，各从其类，故善逐水。其主大腹者，即世所谓水蛊也。又主疝瘕腹满，面目浮肿，及留饮，利水道、谷道，下五水，散膀胱留热，皮中痞气肿满者，谓诸病皆从水湿所生，水去饮消湿除，是拔其本也。洁古谓其味苦性寒。苦性泄，寒胜热，直达水气所结之处，乃泄水之圣药。水结胸中非此不能除，故仲景大陷胸汤用之。但有毒不可轻用，其性之恶可概见已。其根皮赤，肉白，作连珠、实重者良。\n\n【主治参与】\n入陷胸汤，治伤寒水结胸，有神。\n\n《圣济总录》治膜外水气：甘遂末、大麦面各半两，水和作饼，烧熟食之，取利。\n\n《肘后方》治身面洪肿：甘遂末二钱，以雄猪腰子一枚，分作七片，入末在内，湿纸包煨令熟。每日服一片，至四五服，当觉腹鸣小便利，是其效也。\n\n张仲景《金匮玉函方》治心下留饮坚满，脉伏，其人欲自利反快，甘遂半夏汤：用甘遂大者三枚，半夏十二枚，以水一升，煮半升，入芍药五枚，水二升，煮半升，去滓。以蜜半升，同煎至八合，顿服之。\n\n《笔峰杂兴方》治小便转脬：甘遂末一钱，猪苓汤调下，立通。\n\n秘方治体气：甘遂末一钱，同猪肉煮食。于野地中掘一坑，令患人至彼处，向上风站立，以甘草末唾调入脐内，须臾腹中作响，取利下黑汁，亟从上风奔回，可绝。不绝再作一服，仍前用之。\n\n【简误】\n       甘遂性阴毒，虽善下水除湿，然能耗损真气，亏竭津液。元气虚人，除伤寒水结胸不得不用外，其余水肿臌胀，类多脾阴不足，土虚不能制水，以致水气泛滥。即刘河间云：诸湿肿满属脾土。法应补脾实土，兼利小便。不此之图而反用甘遂下之，是重虚其虚也。水既暂去，复肿必死矣。必察病属湿热，有饮有水而元气尚壮之人，乃可一施耳。不然祸不旋踵矣。戒之！戒之！慎之！慎之！\n', NULL, NULL, NULL, '甘遂', NULL, '11、甘遂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784203, '708A8249549F1B6BA9FE5D80318CAA88', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7304, 416, 400106010, '       味苦、辛，寒、微寒，有毒。主伤寒寒热，热发温疟鬼毒，胸中痰结吐逆，疗鬼蛊往来，水胀，洒洒恶寒，鼠瘘。（畏玉札。忌菘菜。）\n\n        疏：常山禀天地阴寒之气以生，故其味苦寒。\n\n     《别录》、桐君益之以辛，宜其有毒也。苦泄辛散，故善逐饮。阴寒祛热。故善破瘴疠。入口即吐，其性暴悍又可知已。\n\n     《本经》主伤寒寒热，宜作主山岚瘴气，寒热发为温疟，鬼毒，胸中痰结。古方治疟多用，盖以岭南、西粤、鬼方，咸多山岚瘴疠之气，所感邪气，充于荣卫皮肤之间，欲去皮肤毛孔中瘴气根本，非常山不可。以其性能祛逐老痰积饮，善散山岚瘴疠之邪故也。\n\n【主治参与】\n治山岚瘴气作疟，百药不效，秘方：常山四两，砂仁四两，槟榔二两，米醋浸，入瓷器中二宿，取出，各炒燥为末，鸡子清和丸如绿豆大。五更，新汲水向东吞三五钱，一服可止。九月以后，宜以酒吞。\n\n刘长春《经验方》治瘴疟寒热，用常山一寸，草果一枚，热酒一盏，浸一宿，五更向东饮之，盖卧，酒醒即愈。\n\n《肘后方》治三十年老疟，及积年久疟：常山、黄连各一两，酒三升，渍一宿，以瓦釜煮取一升半。发日早服五合，发时再服。热当吐，冷当利，无不瘥者。\n\n【简误】\n       常山，阴毒之草也，其性暴悍，虽能破瘴疠，逐积饮，然善损真气。故疟非由于瘴气，及老痰积饮所致者，勿用。《经》曰：夏伤于暑，秋必痎疟。又曰：邪之所凑，其气必虚。暑邪乘虚客于五脏六腑十二经，疟亦因之而发。《内经》载之详矣。王好古分条立方，殊得仲景遗意，此皆疟之对病正药也。并不得妄用常山，虚人真气，变为危证。戒之！戒之！清暑养胃，健脾消痰，乃治疟之正法。稍久则当分气血施补助，靡不愈者，又安所事常山乎？', NULL, NULL, NULL, '常山', NULL, '10、常山', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784204, '2B3FE6FFB63EBC0C4D01AFBC70EA3509', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7305, 416, 400106009, '     味苦，平、微温，有毒。主咳逆上气，喉痹咽痛、不得消息，散结气，腹中邪逆，食饮大热，疗老血在心脾间，咳唾，言语气臭，散胸中热气。久服令人虚。\n\n      疏：射干禀金气而兼火，火金相搏则辛而有毒，故《本经》谓其味苦平有毒，平亦辛也。\n\n   《别录》微温。保升：微寒。二说一义，并无异云。洁古云：味苦。阳中阴也。入手少阳、少阴、厥阴经。苦能下泄，故善降。兼辛，故善散，故主咳逆上气，喉痹咽痛不得消息，散结气，胸中邪逆。既降且散，益以微寒，故主食饮大热。\n\n  《别录》又主老血在心脾间，咳唾言语气臭，散胸中热气。\n\n    甄权：主疰气，消瘀血，主女人月闭。\n\n    日华子主消痰，破癥结，胸膈满，腹胀气喘，痃癖。\n\n    寇宗奭：主脉气喉痹为佳。\n    \n    洁古：主胃中痈疮。皆此意也。\n\n    丹溪：主行太阴、厥阴之积痰，使结核自消甚捷。又治足厥阴湿气下流，因疲劳而发为便毒。悉取其泄热散结之力耳。故古方治喉痹咽痛为要药。\n\n【主治参与】\n仲景《金匮》方治咳逆上气，喉中作水鸡声，射干麻黄汤。\n\n入鳖甲煎丸，治疟母。\n\n《袖珍方》治咽喉肿痛。用生射干、猪脂各四两，合煎令焦，去滓，每噙枣许，即瘥。\n\n《医方大成》治喉痹不通：用扁竹新根，擂汁咽之，大肠动即解。或醋研汁，噙，引涎出亦妙。\n\n《便民方》亦治喉痹不通：用紫蝴蝶根一钱，黄芩、生甘草、桔梗各五分，为末，水调顿服，立愈。名夺命散。\n\n《永类钤方》治乳痈初肿：用扁竹根如僵蚕者，同萱草根为末，蜜调敷之，神效。\n\n孙真人《千金方》治喉痹，有乌翣膏。\n\n【简误】\n       射干虽能降手少阳、厥阴相火，泄热散结，消肿痛，然无益阴之性。故《别录》云：久服令人虚。凡脾胃薄弱，脏寒气血虚人，病无实热者，禁用。', NULL, NULL, NULL, '射干', NULL, '9、射干', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784205, '8DCF6DE1C6190F777749A723D72843D5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7306, 416, 400106008, '      味辛、苦，寒、微寒，有毒。主蛊毒，咳逆，泄痢肠澼，头疡疥瘙恶疮，杀诸虫毒，去死肌，疗哕逆，喉痹不通，鼻中息肉，马刀烂疮。不入汤。\n\n      疏：藜芦禀火金之气以生，故其味辛气寒，《别录》苦微寒，有毒。入手太阴，足阳明经。\n\n   《本经》主蛊毒咳逆，及《别录》疗哕逆，喉痹不通者，皆取其宣壅导滞之力。苦为涌剂，故能使邪气痰热，胸膈部分之病悉皆吐之也。辛能散结，故主鼻中息肉。苦能泄热杀虫，故主泄痢肠澼。头疡疥瘙，杀诸虫毒也。疮疡皆湿热所生，湿热不去则肌肉溃烂，苦寒能泻湿热，则马刀恶疮，烂疮死肌皆愈也。味至苦，入口即吐，故不入汤。\n\n【主治参与】\n《经验方》诸风痰饮：藜芦十分，郁金一分，为末。每以一字，温浆水一盏和服，探吐。\n\n《简要济众方》中风不省，牙关紧急者：藜芦一两去苗，浓煎，防风汤洗，焙干，切片，炒为末。每服半钱，小儿减半，温水调灌，吐出风涎，效。\n\n《圣惠方》诸风头痛：以藜芦一茎，日干研末，入麝香少许，吹鼻。《保命集》久疟痰多不食，欲吐不吐：藜芦末半钱，温浆水调下，探吐。\n\n【简误】\n          藜芦辛苦有大毒，服一匕则令人胸中烦闷，吐逆不止。凡胸中有痰饮，或中蛊毒恶气者，只可借其上涌宣吐之力，获效一时。设病非关是者，切勿沾唇，徒令人闷乱，吐逆不止，亏损津液也。', NULL, NULL, NULL, '藜芦', NULL, '8、藜芦', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784206, '444E3C393986F0D2999E794B69533426', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7307, 416, 400106007, '        味咸、甘，温、微温、冷利，有小毒。主结气胁下满，惊悸，除水，去五藏间寒热，补中下气。消胸上痰结，唾如胶漆，心胁痰水，膀胱留饮，风气湿痹，皮间死肌，目中眵䁾，利大肠，通血脉，益色泽。一名金沸草。五月采花，日干。\n\n      疏：旋覆花，《别录》、甄权、日华子、寇宗奭，皆无毒。宗奭又加苦辛。而曰冷利，其禀冬之气而生者乎？故其味首系之以咸，润下作咸，咸能软坚。\n\n   《别录》加甘，甘能缓中，微温，温能通行，故主结气胁下满。心脾伏饮则病惊悸，饮消则复常矣。除水去五脏间寒热，及消胸上痰结，唾如胶漆，心胁痰水，膀胱留饮，风气湿痹，皮间死肌，目中眵䁾，利大肠者，皆软坚、冷利、润下、消痰饮、除水之功也。其曰补中下气者，以甘能缓中，咸能润下故也。通血脉，益色泽者，盖指饮消则脾健，健则能运行，脾裹血、又统血故也。\n\n【主治参与】\n仲景治伤寒汗下后，心下痞坚，噫气不除，有七物旋覆代赭汤。成无己曰：硬则气坚，旋覆之咸以软痞坚也。\n\n《金匮要略》治半产漏下，虚寒相搏，其脉弦芤，旋覆花汤：用旋覆花三两，葱十四茎，新绛少许，水三升，煮一升，顿服。\n\n胡洽治痰饮在两胁，胀满，有旋覆花丸。\n\n《总微论》治小儿眉癣，自眉毛眼睫，因癣退不生：用野油花即旋覆花，赤箭即天麻苗，防风，等分为末，洗净。以油调涂之。\n\n【简误】\n        丹溪谓为走散之药，病人涉虚者，不宜多服。冷利，大肠虚寒人禁用。', NULL, NULL, NULL, '旋覆花,旋复花', NULL, '7、旋覆花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784207, 'AEEC349D2A9432EA3120F88015249DB6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', 1, 'admin', '2025-01-16 15:31:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7308, 416, 400106006, '      味苦，寒，无毒。主疥瘙痂痒恶疮，杀虱，留热在骨节间，明目。一名青蒿。\n\n       疏：草蒿，青蒿也。禀天地芬烈之气以生，故其味苦，其气寒而芬芳，其性无毒。疥瘙痂痒恶疮，皆由于血热所致。留热在骨节间者，是热伏于阴分也。肝胃无热则目明。苦能泄热，苦能杀虫，寒能退热，热去则血分平和，阴气日长，前证自除，故悉主之也。诸苦寒药多与胃气不宜，惟青蒿之气芬芳可人，香气先入脾，故独宜于血虚有热之人，以其不犯胃气故尔。是以蓐劳虚热，非此不除矣。\n\n【主治参与】\n青蒿得鳖甲、地黄、牛膝、枸杞、麦门冬、五味子，除一切产后虚热，寒热淹延不解。亦治一切虚劳寒热，阴虚五心烦热，肾水真阴不足，以致骨蒸劳热，此为要药。\n\n陶隐居谓其生挼傅金疮，大止血，生肉，止疼痛，以帛裹之。\n\n陈藏器谓其主鬼气尸疰伏留，妇人血气腹内满，及冷热久痢。秋冬用子，春夏用苗。\n\n日华子谓其能补中益气，轻身补劳，驻颜色，长毛发，发黑不老，心痛热黄，生捣汁服。\n\n《百一方》治蜂螫人，嚼青蒿傅疮上，即瘥。\n\n《斗门方》治男妇劳瘦，用青蒿细剉，水三升，童便五升，同煎，取一升半，去滓，入器中煎成膏，丸如梧子大。每空心及临卧，温酒吞二十丸。\n\n《灵苑方》治虚劳寒热，肢体倦疼，不拘男妇：八九月青蒿成实时采之，去枝梗，以童便浸三日，晒干为末。每服二钱，乌梅一个，煎汤服。\n\n崔元亮《海上方》治骨蒸鬼气：用童便五大斗，澄清，青蒿五斗，八九月采，带子者最好，细剉相和，纳大釜中，以猛火煎取三大斗，去滓，溉釜令净，再以微火煎可二大斗，入猪胆一枚，同煎一大斗半，去火待冷，以磁器盛之。每欲服时，取甘草二三两，炙熟为末，以煎和捣千杵为丸。空腹粥饮下二十丸，渐增至三十丸止。\n\n《十便良方》治骨蒸烦热：用青蒿一握，猪胆汁一枚，杏仁四十个去皮尖炒，以童溺一大盏，煎五分，空心温服。\n\n《圣济总录》治虚劳盗汗，烦热口干：用青蒿一斤，取汁熬膏，入沙参末，麦冬末各一两，同熬至可丸，丸如梧子大，每食后米饮服二十丸，名青蒿煎。\n\n《肘后方》治疟疾寒热：用青蒿一握，水二升，捣汁服之。\n\n《仁存方》治温疟痰盛，但热不寒：用青蒿二两，童便浸焙，黄丹半两，为末。每服二钱，白汤调下。\n\n《卫生易简方》治鼻衄：青蒿捣汁服之，并塞鼻中，极验。\n\n《永类钤方》治酒痔便血：青蒿用叶不用茎，用茎不用叶，为末。血从粪前冷水调，粪后温酒调服。\n\n《济急方》治牙齿肿痛：青蒿一握，煎漱之。\n\n《圣惠方》治耳中出脓：青蒿为末，绵裹纳耳中。\n\n【简误】\n         产后气虚，内寒作泻，及饮食停滞泄泻者，勿用。凡产后脾胃薄弱，忌与当归、地黄同用。', NULL, NULL, NULL, '青蒿,草蒿', NULL, '6、青蒿,草蒿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784208, 'DB3296576CD2E4A666FB3A27EE308382', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7309, 416, 400106005, '      味辛、苦，微温，有小毒。主胸胁痛如刀刺，腹满肠鸣幽幽，惊恐悸气，利五藏肠胃，补血气，除寒热风痹，温中消谷，疗喉咽痛，下蛊毒。\n\n      疏：桔梗，《本经》味辛，气微温。\n\n    《别录》加苦，云有小毒。神农、医和、岐伯、雷公，咸曰无毒，而复加甘。观其所主诸病，应是辛苦甘平，微温无毒。入手太阴、少阴，兼入足阳明胃经。味厚气轻，阴中之阳，升也。伤寒邪结胸胁，则痛如刀刺。邪在中焦，则腹满及肠鸣幽幽，辛散升发，苦泄甘和，则邪解而气和，诸证自退矣。其主惊恐悸气者，心脾气血不足则现此证，诸补心药中藉其升上之力，以为舟楫胜载之用，此佐使之职也。\n\n     《别录》利五脏肠胃，补气血者，盖指邪解则脏腑肠胃自和，和则血气自生也。除寒热风痹，温中，疗喉咽痛，下蛊毒者，皆散邪解毒通利之功也。消谷者，以其升载阳气，使居中焦而不下陷，则脾中阳气长浮而谷食自消矣。甄权用以治下痢及去肺热气促者，升散热邪之故也。日华子用以除邪辟瘟，肺痈排脓。洁古用以利窍除肺部风热，清利头目咽嗌，胸膈滞气及痛，除鼻塞者，入肺开发和解之功也。好古以其色白，故为肺部引经，与甘草同行，为舟楫之剂，诸药有此一味，不能下沉也。\n\n【主治参与】\n朱肱《活人书》治胸中痞满不痛，用桔梗、枳壳，取其通肺利膈下气也。\n\n张仲景《伤寒论》治伤寒寒实结胸，用桔梗、贝母、巴豆，取其温中散邪，消谷破积也。又治肺痈唾脓，用桔梗、甘草，取其苦辛清肺，甘温泻火，又能排脓血，补内漏也。其治少阴证二三日咽痛，亦用桔梗、甘草，取其苦辛散邪，甘平除热，合而用之，能调寒热也。后人易名甘桔汤，通治咽喉、口舌诸病。\n\n《南阳活人书》治伤寒腹胀，阴阳不和者，桔梗半夏汤主之：桔梗、半夏、陈皮各三钱，姜五片，煎服。\n\n《简要济众方》治痰嗽喘急：桔梗一两半，为末，用童子小便半升，煎四合，去滓温服。\n\n仲景《金匮玉函方》治肺痈咳嗽，胸满振寒，脉数，咽干不渴，时出浊唾腥臭，久久吐脓如粳米粥者：桔梗一两，甘草二两，水三升，煮一升，分温再服，朝暮吐脓血则瘥。\n\n《千金方》治喉痹毒气：桔梗二两，水三升，煮一升，顿服。\n\n仲景《伤寒论》少阴证二三日，咽痛者，可与甘草汤；不瘥者，与甘桔汤主之：桔梗一两，甘草二两，水三升，煮一升，分服。又可治口舌生疮。\n\n《永类钤方》治齿䘌肿痛：桔梗、薏苡仁等分，为末服。\n\n《经验方》治骨槽风，牙龈肿痛者：桔梗为末，枣瓤和丸皂子大。绵裹咬之，仍以荆芥汤漱之。\n\n《卫生易简方》治牙疳臭烂，桔梗、茴香等分，烧研傅之。\n\n《普济方》治鼻衄：桔梗为末，水服方寸匕，日四服。一方加生犀角屑。\n\n《古今录验方》治中蛊下血如鸡肝，昼夜出血石余，四脏皆损，惟心未毁，或鼻破将死者：苦梗为末，以酒服方寸匕，日三服。不能下药，以物拗口灌之。心中当烦，须臾自定，七日止。\n\n当食猪肝肺以补之。一方加犀角等分。\n\n《圣惠方》治妊娠中恶，心腹疼痛：桔梗一两，生姜三片，煎温服。\n\n张文仲《备急方》治小儿客忤死，不能言：桔梗烧研三钱，米汤服之，仍吞麝香豆许。\n\n【简误】\n        桔梗之性属阳而升，凡病气逆上升，不得下降，及邪在下焦者勿用。凡攻补下焦药中勿入。\n        雷公云：凡使勿用木梗，真似桔梗，只是咬之腥涩不堪为异。', NULL, NULL, NULL, '桔梗', NULL, '5、桔梗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784209, 'F76D1242FE0786C45C682579C71FF42C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7310, 416, 400106004, '        味辛、苦，寒、大寒，无毒。主癥瘕积聚结气，饮食寒热，破坚逐邪，通利水道，下膀胱水，伏留热气，皮间邪水上出，面目浮肿，身暴中风热痱痒，利小腹。久服令人虚。得酒良。\n\n        疏：葶苈禀阴金之气以生，故其味辛苦，大寒无毒。气薄味厚，阳中阴也。为手太阴经正药，故仲景泻肺汤用之。亦入手阳明，足太阴经。肺属金，主皮毛，膀胱属水，藏精液，肺气壅塞则膀胱与焉，譬之上窍闭则下窍不通，下窍不通则水湿泛溢，为喘满，为肿胀，为积聚，种种之病生矣。辛能散，苦能泄，大寒沉阴能下行逐水，故能疗《本经》所主诸病。“十剂” 云：泄可去闭，葶苈之属是矣。至苦极寒，有泻无补，暂用尚能损真，久服宁不令人虚也？\n\n【主治参与】\n《金匮》方：肺痈喘急不得卧，葶苈大枣泻肺汤主之。葶苈炒黄捣末，蜜丸弹子大。每用大枣二十枚，水三升，煎取二升，入葶苈一丸，更煎取一升，顿服。亦主支饮不得息。\n\n《外台秘要》通身肿满：苦葶苈炒四两，为末，枣肉和丸梧子大，每服十五丸，桑白皮汤下，日三。大效。\n\n《千金方》腹胀积聚：葶苈子一升，熬，以酒五升浸七日，日服三合。\n\n《箧中方》痰饮咳嗽，含奇丸：用葶苈子一两，纸衬炒令黑，知母、贝母各一两，枣肉半两，砂糖一两半，和丸弹子大。每以新绵裹一丸，含之咽津，甚者不过三丸。\n\n【简误】\n        葶苈，泻肺利小便，治肿满之要药。然味大寒，走而不守，不利于脾胃虚弱，及真阴不足之人。凡肿满由于脾虚不能制水，水气泛溢；小便不通由于膀胱虚，无气以化者，法所咸忌。犯之则轻病重、重必危，慎之！近世甜、苦二种，据《本经》云辛苦，则甜者非矣！总之，疗体皆以行水泄闭为用，多服久服，咸不宜耳。', NULL, NULL, NULL, '葶苈子', NULL, '4、葶苈', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784210, '701EFF4566AF3BBB79F6E9C5E7B96C69', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', 1, 'admin', '2025-01-16 15:24:56');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7311, 416, 400106003, '       味苦，寒，大寒，无毒。主下瘀血，血闭寒热，破癥瘕积聚，留饮宿食，荡涤肠胃，推陈致新，通利水谷，调中化食，安和五藏，平胃下气，除痰实，肠间结热，心腹胀满，女子寒血闭胀，小腹痛，诸老血留结。（黄芩为之使。无所畏。）\n\n      疏：大黄禀地之阴气独厚，得乎天之寒气亦深，故其味至苦，其气大寒而无毒。入足阳明、太阴、厥阴，并入手阳明经。气味俱厚。味厚则发泄，故其性猛利，善下泄，推陈致新，无所阻碍。所至荡平，有戡定祸乱之功，故号将军。味厚则入阴分，血者，阴也，故主下瘀血，血闭寒热，癥瘕积聚，留饮宿食，荡涤肠胃，通利水谷。其曰调中化食，安和五藏者，概指脏腑积滞既去，则实邪散而中自调，脏自和也。\n\n      《别录》又云：平胃下气，除痰实，肠间结热，心腹胀满，女子寒热，女子因寒血凝闭而作胀，少腹痛因于血闭，及诸老血留结，皆由通利开导之力所致也。总之，此药乃除实热燥结，下有形积滞之要品。随经随证以为佐使，则奏功殊疾矣。\n\n【主治参与】\n大黄君枳实、厚朴，为小承气汤，治伤寒热病，邪结中焦。\n\n治伤寒病发于阴而反下之，心下满而不痛，按之濡，此为痞也，大黄黄连泻心汤主之：大黄二两，黄连一两，以麻沸汤二升渍之，须臾绞汁，分作二次温服。\n\n洁古用以泻诸实热不通，及泻心下痞满由于实。皆本仲景法也。亦治滞下赤白初起。壮实之人可用枳壳、槟榔、当归、甘草、滑石，作丸投之，是迎而夺之之法也。然不可过剂，过剂则伤胃气。\n\n同碱及白敛、炒陈小粉、没药、乳香、醋、蜜，调傅作痈肿围药。凡实热湿痰为病，以锦纹大黄酒蒸八两，入前胡八两，橘红四两，外另以青礞石二两，同焰硝二两，入砂罐固济，煅红研末二两。上各取末，以水发为丸梧子大。每常服一二十丸，小病五六十丸，缓病七八十丸，急病一百二十丸，温水吞下，即卧勿动，候药逐上焦痰滞，次日先下糯粕，次下痰涎，未下再服。惟妊娠、水泄忌之。此真方滚痰丸也。治一切因痰发为怪证。若入霞天膏为丸，更妙。\n\n仲景《金匮玉函方》云：凡人食已即吐，此胸中有火也。大黄一两，甘草炙二钱五分，水一碗，煮半升，温服。\n\n西大黄拌蜜及竹沥，九蒸九晒，粉糊为丸如麻子大，薄荷汤吞三钱，治中上二焦有热痰，因发偏头风，诸药不效，目将损者有殊功。又治中焦脾胃湿热下流客肾，以致饱后夜卧即梦遗，临卧以升麻、陈皮汤吞三四钱，湿热去即止。\n\n【简误】\n        《经》曰：实则泻之。大黄气味大苦大寒，性禀直逐，长于下通，故为泻伤寒、温病、热病实热，热结中下二焦，二便不通，及湿热胶痰滞于中下二焦之要药。祛邪止暴，有拨乱反正之殊功。第具峻利之性，猛烈之气，长驱直捣，一往不返。如武王伐纣，前徒倒戈，血流漂杵，虽应天顺人，救民水火，然亦不免于未尽善之议矣。故凡血闭由于血枯，而不由于热积；寒热由于阴虚，而不由于瘀血；癥瘕由于脾虚胃弱，而不由于积滞停留；便闭由于血少肠燥，而不由于热结不通；心腹胀满由于脾虚中气不运，而不由于饮食停滞；女子少腹痛由于厥阴血虚，而不由于经阻老血瘀结；滞下初起即属胃虚，当以补养胃气，清消湿热为本，而不可以妄加推荡；疟病伤于暑气，而不由于山岚湿热；吐衄血由于阴虚火起于下，炎铄乎上，血热妄行，溢出上窍，而不由于血分实热；腰脚风气由于下元先虚，湿热下流，因兹致病，而不专由于风湿外侵；骨蒸积热本于阴精不足，而非实热所致；偏坠由于肾虚，湿邪乘虚客之而成，而不由于湿热实邪所犯；乳痈肿毒由于肝家气逆郁抑不舒，以致荣气不从，逆于肉里，乃生痈肿，而不本于膏粱之变，足生大疔，血分积热所发，法咸忌之。以其损伤胃气故也。故伤寒家，调胃承气汤中用甘草以和之，正谓是也。轻发误投，多致危殆，戒之！戒之！', NULL, NULL, NULL, '大黄', NULL, '3、大黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784211, '3D37F56C9980D7156884B1191405EE85', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7312, 416, 400106002, '         味辛，平，生微寒，熟温，有毒。主伤寒寒热，心下坚，下气，咽喉肿痛，头眩，胸胀咳逆，肠鸣，止汗，消心腹胸膈痰热满结，咳嗽上气，心下急痛坚痞，时气呕逆，消痈肿，堕胎，疗痿黄，悦泽面目。生令人吐，熟令人下。用之汤洗，令滑尽。（射干为之使。恶皂荚。畏雄黄、生姜、干姜、秦皮、鳖甲。反乌头。忌羊血、海藻、饴糖。）　　\n\n        疏：半夏得土金之气，兼得乎天之燥气，故其味辛平苦温，火金相搏，则辛而有毒。洁古谓味辛苦，性温，气味俱薄，沉而降。好古谓其辛厚苦轻，阳中阴也。入足太阴、阳明、少阳，亦入手少阴经。柴胡为之使。辛温善散，故主伤寒邪在表里之间，往来寒热。苦善下泄。邪在胸中则心下坚，胸胀咳逆。邪在上焦则头眩。邪在少阴则咽喉肿痛。\n\n     《别录》亦谓其消心腹胸膈痰热满结，咳逆上气，心下急痛坚痞，时气呕逆，亦皆邪在上焦胸中之所致，故悉主之也。中焦者，足太阴之所治也。有湿有热，清浊不分则肠鸣，湿热胜则自汗，入足太阴，故并主之。辛能散结，故消痈肿。脾家湿热，则面色痿黄。实脾分水燥湿，则前证俱除，面目因而滑泽矣。辛温有毒，故堕胎也。　\n　\n【主治参与】　　\n张仲景《伤寒论》小结胸痛，正在心下，按之则痛，脉浮而滑者，小陷胸汤主之：半夏半升，黄连一两，栝楼实大者一个，水六升。先煮栝楼至三升，去滓，内二味，煮取二升，分三服。　　\n又治少阴咽痛生疮，不能言语，声不出者，苦酒汤主之：半夏七枚打碎，鸡子一枚，头开一窍，去黄，纳苦酒令小满，入半夏在内，以环子坐于炭火上，煎三沸，去滓，置杯中，时时咽之，极验。未瘥更作。　\n　\n《金匮要略》治支饮作呕，呕家本渴，不渴者，心下有支饮也。或似喘不喘，似呕不呕，似哕不哕，心下愦愦，并宜小半夏汤。用半夏泡七次，一升，生姜半升，水七升，煮一升五合，分温服。　　\n\n又治呕、哕、眩、悸，谷不得下。小半夏加茯苓汤：半夏一升，生姜半斤，茯苓三两切，以水七升，煎一升半，分温服之。\n　　\n又，心下悸忪，半夏麻黄丸。半夏、麻黄等分，为末，蜜丸小豆大。每服三十丸，日三。　\n　\n又，呕吐反胃，大半夏汤：半夏三升，人参三两，白蜜一升，水一斗二升，和，扬之一百二十遍，煮取三升半，温服一升，日再服。亦治膈间支饮。　　\n\n又，张仲景方，治黄疸喘满，小便自利，不可除热者：用半夏半斤，生姜半斤，水七升，煮一升五合，分温再服。有一人气结而死，心下暖，以此少许入口，其人遂活。　\n\n洁古《活法机要》方：风痰头晕，呕逆目眩，面青黄色，脉弦者，水煮金花丸：用生半夏、生天南星、寒水石煅，各一两，天麻半两，雄黄二钱，小麦面三两，为末，水和成饼，水煮浮起，漉出，捣丸梧子大。每服五十丸，姜汤下，极效。亦治风痰咳嗽，二便不通，风痰头痛。　　\n\n又治风痰喘逆，兀兀欲吐，眩晕欲倒：半夏一两，雄黄三钱，为末，姜汁浸，蒸饼丸梧子大。每服三十丸，姜汤下。已吐者加槟榔。　\n　\n又治湿痰咳嗽，面黄体重嗜卧，兼食不消，脉缓者，白术丸：用半夏、南星各一两，白术一两半，为末，薄糊丸梧子大。每服五十丸，姜汤下。　\n　\n又治气痰咳嗽，面白气促，洒淅恶寒，愁忧不乐，脉涩者，玉粉丸：用半夏、南星各一两，官桂半两，为末，糊丸梧子大。每服五十丸，姜汤下。　\n　\n《和剂局方》治停痰留饮，胸膈满闷，气短恶心，饮食不下，或吐痰水。茯苓半夏汤：用半夏泡五两，茯苓三两，每服四钱，姜七片，水一钟半，煎七分，甚捷径。　\n　\n又搜风化痰，安神定志，利头目，辰砂化痰丸：用半夏曲三两，天南星炮一两，辰砂、枯矾各半两，为末，姜汁打糊丸梧子大。每服三十丸，食后姜汤下。　\n　\n又治风痰喘急，千缗汤：用半夏汤洗七个，甘草炙、皂荚炒各寸许，姜三片，水一盏，煎七分，温服。　　\n\n又治停痰冷饮呕逆。橘皮半夏汤：用半夏水煮熟，陈橘皮各半两，每服四钱，生姜七片，水二盏，煎一盏，温服。　　\n\n又治胃寒哕逆，停痰留饮，藿香半夏汤：用半夏汤泡炒黄二两，藿香一两，丁香皮半两，每服四钱，水一盏，姜七片，煎服。　　\n\n又治伏暑引饮，脾胃不和，消暑丸：用半夏醋煮一斤，茯苓半斤，生甘草半斤，为末，姜汁面糊丸梧子大。每服五十丸，热汤下。\n　　\n又治中焦痰涎，利咽，清头目，进饮食：半夏泡七次四两，枯矾一两，为末，姜汁打糊，或煮枣肉，和丸梧子大。每姜汤下十五丸。寒痰加丁香五钱，热痰加寒水石煅四两，名玉液丸。\n　　\n《御药院方》治膈壅风痰：半夏半斤，酸浆浸一宿，温汤洗五十遍，去恶气，日干，为末，浆水搜作饼，日干，再研为末。每五两入生龙脑一钱，以浆水浓脚和丸鸡头子大。纱袋盛，避风处阴干。每服一丸，好茶或薄荷汤嚼下。　\n　\n叶氏方：治风痰、湿痰，青壶丸：半夏一斤，天南星八两，各汤泡晒干，为末，姜汁和作饼，焙干，入神曲半两，白术末四两，枳实末二两，姜汁面糊丸梧子大。每服五十丸，姜汤下。　　\n一作三仙丸，能化痰利气。　\n　\n《斗门方》消痰开胃，去胸膈壅滞：用半夏洗泡焙干为末，自然姜汁和作饼，湿纸裹，煨香，以熟水二盏，同饼二钱，入盐五分，煎一盏，服之，大压痰毒及酒食伤，极验。　\n　\n《机要》又治结痰不出，语音不清，年久者亦宜。玉粉丸：半夏半两，桂心一字，草乌半字，为末，姜汁浸蒸饼丸芡实大。每服一丸，夜卧含咽。　　\n\n《活幼口议》治小儿痰吐，或风壅所致，或咳嗽发热，饮食即呕：半夏泡七次半两，丁香一钱，以半夏末水和包丁香，用面重包，煨熟，去面为末，生姜自然汁和丸麻子大。每服二三十丸，陈皮汤下。\n　　\n《肘后方》治冒寒霍乱腹胀：用半夏、桂枝等分为末，水服方寸匕。　　\n\n又治产后晕绝：半夏末，冷水和丸大豆大，纳鼻中即愈。此扁鹊法也。　\n　\n《永类钤方》打扑瘀痕：水调半夏末涂，一宿即没。　　\n\n魏元君方：卒死不寤，用半夏末搐鼻中，即活。\n　　\n《子母秘录》治五绝急病：一曰自缢，二曰墙压，三曰溺水，四曰魇魅，五曰产乳。并以半夏末，纳大豆一丸入鼻中，心温者，一日可活也。　　\n\n刘长春《经验方》治吹奶肿痛。半夏一个煨研，酒服，立验。一方：以末随左右㗜鼻效。　　\n\n钱相公《箧中方》：治蝎虿螫人，用半夏末，水调涂之，立止。　\n　\n【简误】　　\n        半夏辛温性燥而有毒，虽能祛湿分水实脾，开寒湿痰，气郁结痰，而其所大忌者，乃在阴虚血少，津液不足诸病。故古人立三禁，谓血家、渴家、汗家也。故凡一切吐血、衄血、咯血、齿衄、舌上出血、金疮、产后失血过多、尿血、便血，肾水真阴不足发渴、中暑发渴，阳虚自汗、阴虚盗汗、内热烦躁出汗诸证，皆所当禁者也。然三禁之外，应忌者尚多，兹更详列于后：凡咳嗽由于阴虚火空，上炎烁肺，喉痒，因而发嗽，内热煎熬津液，凝结为痰所致，而不由于寒湿，病本乎肺而不本乎脾；呕吐由于火冲胃热，而不由于寒湿痰壅；饮食不化由于脾阴不足，而不由于因湿脾慢；呕、哕、眩、悸，谷不得下，由于胃气虚弱，见食厌恶，而不由于寒湿邪所干。霍乱腹胀由于脾虚邪热客中焦，而不由于寒湿饮食停滞。咽痛由于阴虚，肾水不足则水涸而阳无所附，故火空上炎而发咽痛，而不由于伤寒少阴病邪热不解。气喘由于气虚，而不由于风寒所郁。头痛由于血虚，而不由于痰厥。小儿吐痰由于伤热，而不由于脾胃。不寐由于心经血少，而不由于病后胆虚。自汗由于表虚腠理不固，而不由于湿热内客自胜。如上诸证，法所同禁。其所最易误而难明者，世医类以其能去痰，凡见痰嗽莫不先投之，殊不知咳嗽吐痰，寒热骨蒸，类皆阴虚肺热，津液不足之候，误服此药，愈损津液，则肺家愈燥，阴气愈虚，脓痰愈结，必致声哑而死。若合参、术，祸不旋踵。盖以其本脾胃家药，而非肺肾药也。寒湿痰饮作嗽，属胃病者固宜，然亦百之一二。其阴虚火炽，煎熬真阴，津液化为结痰，以致喉痒发咳者，往往而是。故凡痰中带血，口喝咽干，阴虚咳嗽者，大忌之。又有似中风痰壅失音，偏枯拘挛，及二便闭涩，血虚腹痛，于法并忌。犯之过多，则非药可救。吉凶贸理，悔不可追，责在司命，谨诸！戒诸！　　', NULL, NULL, NULL, '半夏', NULL, '2、半夏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784212, 'CEB23296FEF2846DB17A4370028A4C7E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7313, 416, 400106001, '      味辛、甘，温、大热，有大毒。主风寒咳逆邪气，温中，金疮，破癥坚积聚血瘕，寒湿踒躄，拘挛膝痛，脚疼冷弱，不能行步，腰脊风寒，心腹冷痛，霍乱转筋，下痢赤白，坚肌骨，强阴，又堕胎。为百药长。冬月采为附子，春采为乌头。（忌豉汁。得蜀椒、食盐可引之下行。地胆为之使。恶蜈蚣。畏防风、黑豆、甘草、黄耆、人参、童便、犀角。）\n\n      疏：附子全禀地中火土燥烈之气，而兼得乎天之热气，故其气味皆大辛大热，微兼甘苦，而有大毒。气厚味薄，阳中之阴，降多升少，浮中沉无所不至。入手厥阴，命门，手少阳三焦，兼入足少阴、太阴经。其性走而不守，得甘草则性缓，得肉桂则补命门。\n\n      《本经》主风寒咳逆邪气，寒湿踒躄，拘挛膝痛，脚疼冷弱，不能行步，以此诸病，皆由风寒湿三邪客之所致也。邪客上焦则咳逆，邪客下焦则成踒躄、拘挛膝痛，脚疼冷弱，不能行步。此药性大热而善走，故亦善除风寒湿三邪。三邪祛则诸证自瘳矣。癥坚积聚血瘕，皆血分虚寒，凝而不行所成。血得热则行，故能疗之。其主金疮，亦谓金疮为风寒所郁击，血瘀不活之证，而非血流不止之金疮也。\n\n      《别录》又主腰脊风寒，脚气冷弱，心腹冷痛，及脾虚寒客中焦为霍乱，客下焦肝肾之分为转筋。偕诸补气药则温中，补血药则强阴坚肌骨。火能消物，气性热极，入血善行，故善堕胎。为百药长，引参、术、黄耆、茯苓，则温暖脾胃，除脾湿，祛肾寒，补下焦阳虚。佐之以桂，则除脏腑沉寒，三焦厥逆，湿淫腹痛，胃寒蛔动，气虚经闭，补阳虚，散虚壅。亦可入足太阳、少阴，故治督脉为病，脊强而厥。督脉夹脊而上，并足太阳膀胱经。膀胱者，肾之府，故主之也。天雄、乌头、侧子，本是同生。第其形质有异，老嫩或殊，大热大毒，则未始有别也。\n\n【主治参与】\n附子得生干姜、桂枝，主伤寒直中阴经，温中散寒，而能出汗。\n\n佐人参，兼肉桂、五味子，则补命门相火不足，回阳有神。\n\n得人参、肉桂，治元气虚人，暴寒之气入腹，腹痛作泄，完谷不化，小水不禁。佐白术为除寒湿之圣药。\n\n得黄耆、人参、炙甘草、白芍药、橘皮、五味子，主痈疽溃后去脓血过多，以致饮食不进，恶心欲呕，饮食不化，不生肌肉。亦主久漏冷疮。\n\n得人参、白芍药、炙甘草、砂仁、橘皮，主小儿慢惊。加莲肉、白扁豆，则治吐泻不止。\n\n得术、桂、牛膝、木瓜、橘皮，主寒疝痛极，立止。\n\n得术、木瓜、石斛、萆薢、薏苡仁、橘皮、茯苓，治风湿麻痹肿痛，脚气之无热证者，辄验。\n\n得人参、橘皮、主久病呕哕反胃，虚而无热者良。\n\n《经》曰：肾苦燥，急食辛以润之。附子同肉桂之辛，入八味丸以润肾燥。阳虚无热证者宜之。\n\n【简误】\n       附子既禀地二之火气，兼得乎天之热气以生，是阴阳凑合，无非火热为性，气味皆然，毒可知已。论其性质之所能，乃是退阴寒，益阳火，兼除寒湿之要药，引补气血药入命门，益相火之上剂。若非阴寒寒湿，阳虚气弱之病，而误用之于阴虚内热、血液衰少，伤寒温病、热病阳厥等证，靡不立毙。谨列其害如下。医师司命，宜详玩而深鉴之，亦生人之大幸也。\n伤寒阳厥，其外证虽与阴厥相类，而其内实不相侔，何者？阳厥之病，若系伤寒温疫，其先必发热头疼口渴，其后虽头不疼而表热已除，然必面赤颧红，二便不利，小水必赤，或短少，是其候也，此当下之病也。产后血虚，角弓反张，病名曰痉。痉者，劲也。是去血过多，阴气暴虚，阴虚生内热，热则生风，故外兼现乎风证，其实乃阴血不足，无以荣养于筋所致，足厥阴肝家大虚之候。此宜益阴补血清热则愈也。故凡病人一见内热口干，咽干口渴，渴欲引饮，咳嗽多痰，烦躁，五心烦热，骨蒸劳热恶寒，阴虚内热外寒，虚火上攻齿痛，脾阴不足，以致饮食无味，小便黄赤短涩及不利，大便不通或燥结，腹内觉热闷，喜饮冷浆及鲜果，畏火及日光，兼畏人声木声。虚阳易兴，梦泄不止。产后发热，产后血行不止，及恶疮臭秽，小产，憎寒壮热，中暑厥晕，阴虚头晕，中暑暴泄，利下如火，赤白滞下。小儿中暑，伤食作泄，小便短赤，口渴思饮。血虚腹痛，按之即止。火炎欲呕，外类反胃，而恶热焦烦，得寒暂止。中热腹中绞痛，中暑霍乱吐泻，或干霍乱；或久疟寒热并盛；或赤白浊，赤白淋，尿血，便血，血崩，吐衄，齿衄，舌上出血；目昏，神短，耳鸣，盗汗，汗血，多汗恶热；老人精绝阳痿，少年纵欲伤情，以致阴精不守，精滑，脑漏；妇人血枯无子，血枯经闭；肾虚小便余沥，血虚大便燥结，阴虚口苦舌干，心经有热，梦寐纷纭；下部湿热，行履重滞，湿热痿痹，湿热作泄，湿热脚气；小儿急惊内热，痘疮干焦黑陷，痘疮火闭不出，痘疮皮薄娇红，痘疮因热咬牙，痘疮挟热下利，痘疮余毒生痈；中风僵仆不语，中风口眼歪斜，中风语言蹇涩，中风半身不遂，中风痰多神昏；一切痈疽未溃，金疮失血发痉；血虚头痛，偏头风痛，上来内、外、男、妇、小儿共七十余症，病属阴虚及诸火热，无关阳弱，亦非阴寒，法所均忌。倘误犯之，轻变为重，重者必死，枉害人命，此药居多。临证施治，宜谨审之。世徒见其投之阳虚之候，肺肾本无热证者，服之有起死之殊功，而不知其用之阴虚如上诸病，亦复下咽莫救。故特深著其害，以表其非尝试轻用之药也。业医君子，可不慎诸？', NULL, NULL, NULL, '附子', NULL, '1、附子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 626852612784213, '9D0403C0EAAD3004DA127AA640395FC2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-26 17:29:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7314, 417, 400106104, '      味甘、辛，平，有小毒。主水癥，水研二十枚服之，吐恶沫，加至三十枚，三日一服，瘥则止。又主风虚寒热，身体疮痒浮肿，尸疰恶气，榨取油涂之。\n\n       叶：主脚气风肿不仁，捣蒸傅之。\n\n      疏：蓖麻得土金之气，故其味甘辛，而其气则平，性有小毒。其力长于收吸，故能拔病气出外。其性善收，故能追脓取毒，能出有形之滞物。又能通利关窍，故主水癥。又主风虚寒热，身体疮痒浮肿，尸疰恶气，榨取油涂之。研涂手足心，催生。寇氏主瘰疬。李氏主偏风半身不遂，口眼㖞斜，头风脚气毒肿，丹瘤火伤，针刺入肉，女人胞衣不下，及子肠挺出，皆从外治，不经内服，良有见也。子无刺者良，子有刺者毒。\n\n雷公云：凡使勿用黑天赤利子，缘在地蒌上，是颗两头尖，有毒。其蓖麻子，节节有黄黑斑。凡使以盐汤煮半日，去皮取子研用。\n\n时珍云：取蓖麻油法，用蓖麻仁五升，捣烂，以水一斗，煮之，沫浮于汤面，即撇起，待沫尽乃止，去水。以沫煎至点灯不炸，滴水不散为度。\n\n李氏曰：凡服蓖麻子者，一生不得食豆，犯之必胀死。其油能伏丹砂、轻粉。\n\n【主治参与】\n        蓖麻子去壳，同紫背天葵等分，清水入砂器中煮半日，空腹时与病人嚼下，自十五枚至廿一枚，瘰疬久久自消。\n\n李氏云：一人病偏风，手足不举。用此油同羊脂、麝香、鲮鲤甲等药，煎作摩膏，日摩数次，一月余渐复。兼服搜风养血化痰之剂，三月而愈。又一人病手臂一块肿痛，亦用蓖麻捣膏贴之，一夜而愈。又一人病气郁偏头痛，用此同乳香、食盐捣熁太阳穴，一夜痛止。又一妇产后子肠不收，捣仁贴其丹田，一夜而上。此药外用累奏奇功，但内服不可轻率耳。或言捣膏以箸点于鹅马六畜舌根下，即不能食。或点肛内，即下血死，其毒可知矣。\n\n又方，治口眼㖞斜：蓖麻子仁捣膏，左贴右，右贴左，即正。\n\n又《妇人良方》亦治前证，用蓖麻子仁七七粒，研作饼，右㖞安在左手心，左㖞安在右手心，却以铜盂盛热水，坐药上，冷即换，五六次即正也。\n\n治风气头痛不可忍者：乳香、蓖麻仁等分，捣饼，随左右贴太阳穴，解发出气，甚验。\n\n又方：蓖麻仁半两，枣肉十五枚，捣涂纸上，卷筒插入鼻中，下清水涕，头痛即止。\n\n《圣济录》治鼻塞不通：用蓖麻仁三十粒，大枣去皮一枚，捣匀，绵裹塞之。一日一易，三十日闻香臭也。\n\n《摘玄方》治舌上出血：用蓖麻子油纸撚，烧烟熏鼻中自止。\n\n《经验良方》治舌胀塞口：用蓖麻子仁四十粒，去壳研油涂纸上，作撚烧烟熏之。未退再熏，以愈为度。有人舌肿出口外，一村人用此法而愈。\n\n治急喉痹，牙关紧急不通，用此即破：以蓖麻子仁研烂，纸卷作筒，烧烟熏吸即通。或只取油作撚尤妙。名圣烟筒。\n\n崔元亮《海上集验方》治催生下胞：用蓖麻子七粒，去壳研膏，涂脚心。若胎及衣下，便速洗去，不尔则子肠出，即以此膏涂顶，肠自入也。\n\n《肘后方》产难：取蓖麻子十四枚，每手各把七枚，须臾立下也。\n\n《摘玄》治子宫脱下：用蓖麻仁、枯矾等分为末，安纸上托入。仍以蓖麻仁十四枚，研膏涂顶心即入。\n\n又治盘肠生产，涂顶方同上。\n\n《肘后方》治一切肿毒，痛不可忍：用蓖麻子捣傅，即止也。\n\n【简误】\n       蓖麻子能吸气，又能通窍，体质多油，而又有毒。脾胃薄弱，大肠不固之人，慎勿轻用服饵。', NULL, NULL, NULL, '蓖麻子', NULL, '4、蓖麻子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627077189537862, 'D108A25BAB5F2F0A961EB077AEBDB13D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 08:43:39', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7315, 417, 400106103, '      味苦，寒，有毒。主下气，疗脚满水肿，除风毒，利小便。\n\n       疏：牵牛子《本经》不载，乃名医续注《本草》，谓为苦寒有毒。东垣以为感南方热火之化所生，应是辛热有毒之药。其主下气者，乃损削真气之谓。疗脚满水肿，除风毒，利小便，皆相似语，况前病多属脾胃气虚，此是泻药，今反用之，为害滋大。\n\n【主治参与】\n黑牵牛得白木香、槟榔、使君子，能追虫取积。\n\n《普济方》治气筑奔冲不可忍。牛郎丸：用黑牵牛半两，槟榔二钱半，为末。每服一钱，紫苏汤下。追虫取积亦可用。\n\n《摘玄方》治面上风刺：黑牵牛酒浸三宿，为末，先以姜汁擦面，后用药涂之。\n\n《圣惠方》治面上粉刺，㿔子如米粉：黑牵牛末，兑入面粉药中，日日洗之。\n\n【简误】\n        牵牛子，辛热有毒之药。性又迅急，其所主治，多是脾胃与肺家湿热之病，理应属虚，何资泻药？况诸证应用药物，寻检《本经》所载，良药不乏，何至舍其万全，而就不可必、不可保之毒物哉？宜东垣之谆复其辞，以戒后人之勿轻用也。兹并附录其论，以诏后世云。\n附录 东垣云：牵牛，非《神农》药也。名医续注云：味苦寒，能除湿气，利小便，治下注脚气。此说气味主治俱误矣！何也？凡用牵牛，少则动大便，多则泄下如水，乃泻气之药。其味辛辣，久嚼猛烈雄壮，所谓苦寒安在哉？夫湿者，水之别称，有形者也。若肺先受湿，湿气不得施化，致大小便不通，则宜暂用之。盖牵牛感南方热火之化所生，火能平金而泄肺，湿去则气得周流。所谓五脏有邪，更相平也。今不问有湿无湿，但伤食或有热证，俱用牵牛克伐之药，岂不误哉？况牵牛止能泄气中之湿热，不能除血中之湿热。湿从下受之，下焦主血，血中之湿，宜苦寒之味，反以辛药泄之，伤人元气。且牵牛辛烈，比之诸辛药，泄气尤甚，其伤人必矣。《经》云：辛泄气，辛走气，辛泄肺，肺病者无多食辛。况饮食失节，劳役所伤，是胃气不行，心火乘之。肠胃受火邪，名曰热中。脾胃主血，当血中泄火。以黄芩之苦寒泄火，当归身之辛温和血，生地黄之苦寒凉血益血，少加红花之辛温以泄血络，桃仁之辛温除燥润肠。仍不可专用，须于补中益气，泄阴火之药内加而用之。何则？上焦元气已自虚弱，若反用牵牛大辛热气味俱阳之药，以泄水、泄元气，利其小便，竭其津液，是谓重虚。重则必死，轻则夭人。故张文懿云：牵牛不可耽嗜，脱人元气。见人有酒食病痞者，多服牵牛丸散，取快一时。药过仍痞，随服随效，效后复痞。以致久服脱人元气，犹不知悔也。张仲景治七种湿热，小便不利，无一药犯牵牛者。仲景岂不知牵牛能泄湿利小便乎？为湿病之根在下焦，是血分中气病。不可用辛辣之药，泄上焦太阴之气，是血病泻气，使气血俱损也。《经》云：毋实实，毋虚虚，毋绝人长命，此之谓也。用者戒之！\n牵牛自宋以后，北人常用取快。及刘守真、张子和出，又倡为通用下药。李明之目击其事，故著此说，极力辟之。牵牛治水气在肺，喘满肿张，下焦郁遏，腰背胀重，及大肠风秘、气秘，卓有殊功。但病在血分，及脾胃虚弱而痞满者，则不可取快一时，及常服暗伤元气也。', NULL, NULL, NULL, '牵牛子', NULL, '3、牵牛子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627077189537863, '4F8561BDCC35DF1A0B7F5A0191A63B47', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 08:43:39', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7316, 417, 400106102, '       味苦，温，无毒。主诸风，宣通五藏，去腹内冷滞，心膈痰水，久积癥瘕，痃癖气块，膀胱宿脓恶水，腰膝冷疼，及疗折伤。一名能消。久服之，无温疫疟。忌茗。\n\n        疏：威灵仙感春夏之气，故其味苦，其气温，其性无毒，升也，阳也。入足太阳经。春为风木之化，故主诸风，而为风药之宣导善走者也。腹内冷滞，多由于寒湿。心膈痰水，乃饮停于上中二焦也。风能胜湿，湿病喜燥，故主之也。膀胱宿脓恶水，靡不由湿所成。腰膝冷疼，亦缘湿流下部，侵筋致之。祛风除湿，病随去矣。其曰久积癥瘕，痃癖气块及折伤，则病干血分者多，气分者少，而又未必皆由于湿，施之恐亦无当，取节焉可也。\n\n【主治参与】\n《简便方》治脚气入腹，胀闷喘急：用末二钱，酒下，痛减一分，则药亦减一分。\n\n《千金方》治腰脚诸痛：用末，空心温酒服一钱，逐日以微利为度。\n\n《集验方》治肾脏风壅，腰膝沉重：用威灵仙末，蜜丸梧子大。温酒吞八十丸。平明微利恶物如青脓胶，即是风毒积滞。如未利，再服百丸，取下后，食粥补之一月。仍常服温补药。孙兆方名放杖丸。\n\n《卫生易简方》治破伤风：威灵仙半两，独蒜一个，香油一钱，同捣烂，热酒冲服。汗出即愈。又方，治停痰宿饮，喘咳呕逆，全不入食：威灵仙焙，半夏姜汁浸焙，为末，用皂角水熬膏，丸绿豆大。每服七丸至十丸，姜汤下，日三服，一月验，忌茶、面。\n\n又方，治诸骨鲠：威灵仙一两二钱，缩砂蜜一两，沙糖一盏，水二钟，煎一钟。温服。\n\n李楼《怪证方》治飞丝缠阴，肿痛欲断，以威灵仙捣汁，浸洗，效。\n\n【简误】\n        风药性升而燥，走而不守。凡病非风湿，及阳盛火升，血虚有热，表虚有汗，痎疟口渴身热者，并忌用之。', NULL, NULL, NULL, '能消,威灵仙', NULL, '2、能消,威灵仙', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627077189537864, '579606277F5549C82D8BF415C3E492BB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 08:43:39', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7317, 417, 400106101, '   味苦、涩，微温，无毒。主瘰疬，消痈肿，疗头面风疮，五痔。主心痛，益血气，黑髭鬓，悦颜色，久服长筋骨，益精髓，延年不老。亦治妇人产后及带下诸疾。（茯苓为之使。与白莱菔相恶，犯之令人髭发早白。）\n\n       疏：何首乌，本文味苦涩微温，《传》言味甘气温，其禀春深生气无疑。春为木化，入通于肝，外合于风，升也，阳也。入足厥阴，兼入足少阴经，故为益血祛风之上药。雌雄二种，遇夜则交，有阴阳交合之象，故能令人有子。肝主血，肾主精，益二经则精血盛。发者，血之余也，故乌髭鬓。其主瘰疬者，肝胆气郁结则内热，荣气壅逆，发为是病。十一脏皆取决于胆，与肝为表里，为少阳之经，不可出入。气血俱少，乃风木反主。行胆气，益肝血，则瘰疬自消矣。调荣气则痈肿消。治风先治血，血活则风散，故疗头面风疮。肠澼为痔，痔者湿热下流，伤血分而无所施泄，则逼近肛门肉分，迸出成形为种种矣，风能胜湿，湿热解则痔将自平。心血虚则内热，热则心摇摇而作痛，益血则热解而痛除。益血气，黑髭鬓，悦颜色，久服长筋骨，益精气，延年不老者，皆补肝肾、益精血之极功也。亦治妇人产后及带下诸疾者，妇人以血为主，月事通后，厥阴主之，带下本于血虚而兼湿热，行湿益血，靡不除矣。\n\n【主治参与】\n君甘菊花、枸杞子、地黄、牛膝、天门冬、赤白茯苓、桑椹、南烛子，则益精血，乌须发，驻颜延年。\n\n得牛膝、鳖甲、橘红、青皮，治疟邪在阴分，久而不解。如表气已虚，脾胃已弱，则加人参三五钱。肺热者去人参，换入当归如其数。\n\n得刺蒺藜、甘菊花、天门冬、胡麻仁、漆叶、白芷、荆芥穗、苦参、地黄、百部，治头面诸风及大麻风。\n\n得金银花、地榆、犀角、草石蚕、山豆根、黄连、芍药、干葛、升麻、甘草、滑石，治毒痢下纯血，诸药不效，有神。《经验方》治骨软风，腰膝疼，行履不得，遍身瘙痒：何首乌大而有花纹者，同牛膝，剉，各一斤，以好酒一升，浸一宿，曝干，于木臼内捣末，蜜丸。每日空心食前酒吞三五十丸。兼可治风痰，久疟不愈。\n\n《斗门方》治瘰疬，或破或不破，下至胸前者，皆治之。用何首乌根洗净，日日生嚼，并取叶捣涂之，数服即止。其药久服延年黑发，用之神效。\n\n《何首乌传》：何首乌味甘气温，性则无毒。茯苓为之使。治五痔，腰膝之病，冷气心痛，积年劳瘦，痰癖，风虚败劣，长筋力，益精髓，壮气，驻颜黑发，延年，妇人恶血痿黄，产后诸疾，赤白带下，毒气入腹，久痢不止，其功不可具述。一名野苗，二名交藤，三名夜合，四名地精，五名首乌。本出虔州，江南诸道皆有之。苗叶有光泽者，又如桃李叶，雄者苗色黄白，雌者黄赤，根远不过三尺。春秋可采，日干，去皮为末，酒下最良。有疾即用茯苓煎汤为使。常杵末，新瓷器盛用，偶日服之。忌猪肉、血，无鳞鱼，触药无力。其根形大如拳，连珠。其有形如鸟兽山岳之状者，珍也。掘得去皮生吃，得味甘甜，可休粮，赞曰：神妙胜道，著在仙书。雌雄相交，夜合昼疏。服之去谷，日居月诸。返老还少，变安病躯。有缘者遇，最尔自如。明州刺史李远传录云：何首乌，所出顺州南河县，及韶州、潮州、恩州、贺州、广州四会县、潘州者为上；邕州、桂州、康州、春州、高州、勒州、循州晋兴县出者次之，真仙草也。五十年者如拳大，号山奴，服之一年，髭鬓青黑。一百年者如碗大，号山哥，服之一年，颜色红悦。一百五十年者如盆大，号山伯，服之一年，齿落更生。二百年如斗栲栳大，号山翁，服之一年，颜如童子，行及奔马。三百年者如三斗栲栳大，号山精，纯阳之体，久服之成地仙也。\n\n《衍义》曰：何首乌，兼黑髭鬓。与萝卜相恶，令人髭鬓早白，治肠风热多用。\n\n【简误】\n        何首乌为益血之药，忌与天雄、乌头、附子、仙茅、姜、桂等诸燥热药同用。修事以苦竹刀切片，米泔浸，经宿曝干，蒸用，勿令犯铁。', NULL, NULL, NULL, '何首乌', NULL, '1、何首乌', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627077189537865, '780EA90A68DB7A436E19A1436CE11697', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 08:43:39', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7318, 417, 400106135, '     气辛烈。主漆疮，挼研傅之，热更易。亦主溪毒疮。\n\n       疏：漆姑草，藏器云：气辛烈。然观其多生石间及階墀阴处，必是辛苦寒之药。辛能散，苦能泄，故主漆疮、溪毒疮，及大人小儿丹毒。总之，其气味辛凉，治一切血热为病之要药也。', NULL, NULL, NULL, '漆姑草', NULL, '35、漆姑草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466245, '6B2C1A8E9BA17401639ECFCD266E2ED8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7319, 417, 400106134, '       生高山石上，根如箸，上有毛，节如蚕，叶似卷柏。山人取浸酒，除风破血，主溪毒，煮食之。\n\n       疏：按草石蚕，本经无气味。予见明州好事者，以水渍羊肚石种之，盘生石上俨类蚕形。得水石之气，性必清寒，故能解毒。予少时见一老医，治毒痢下血久不愈，方中有之。后予按其法试用，良验。\n\n【主治参与】\n         草石蚕，同川黄连、白芍药，各酒浸炒，肉豆蔻，糯粉裹煨，莲肉、白扁豆俱炒，橘皮、炙甘草、升麻、山查，和为末，蜜汤调服，治久痢不止，往往获效。当是凉血、破瘀血、消积滞之功也。\n\n无别用，故不著 “简误”。', NULL, NULL, NULL, '草石蚕', NULL, '34、草石蚕', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466246, '8BAD06F77D478053557E2D26152B2FB8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7320, 417, 400106133, '     味甘，温，无毒。主风血，去诸冷，益老起阳，浸酒服之。生姑藏巴西，根苗并似黄精，根鹿好食。（俗呼鹿跑草，又名延寿果。）\n\n      疏：鹿药得土中阳和之气以生，故其味甘，其气温，其性无毒。甘能益血，甘能入脾，甘温益阳气，故能主风血，去诸冷，而益老起阳也。当与黄精、萎蕤、枸杞之类同科。气味和平，性本无毒，补益之外，无别治疗，故不著 “主治”、“简误”。', NULL, NULL, NULL, '鹿药,鹿跑草,延寿果', NULL, '33、鹿药\n   \n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466247, 'C854E0237756A59A515D2130102AEB24', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7321, 417, 400106132, '      味甘，平，温，无毒。疗产后恶血，通月水血结，堕胎，破积聚癥瘕，止痛利气，一名鸡爪三棱。\n\n     疏：草三棱，即鸡爪三棱，与京三棱其实一类。但以所产之地与形质不同为别耳。破散克削之性，一同乎京三棱，故 “参互”、“简误” 亦同，兹不复赘。', NULL, NULL, NULL, '鸡爪三棱,草三棱根', NULL, '32、草三棱根\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466248, '97287A3F2015B5C8CF3326604C56C90A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2025-01-17 14:28:13');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7322, 417, 400106131, '     主通利小肠。得栀子、马牙硝、蓬砂，共疗伤寒热狂。\n\n     疏：海金沙味甘淡，气寒，性无毒。甘寒淡渗之药，故主通利小肠。得牙硝、栀子，皆咸寒苦寒之极，又得蓬砂之辛，所以能治伤寒热狂大热，当利小便，此釜底抽薪之义也。淡能利窍，故治热淋、血淋、膏淋等病，乃手太阳小肠经药也。\n\n【主治参与】\n《夷坚志》治热淋急痛：海金沙草，日中曝之，令小干，纸衬，以杖击之，有细沙落纸上，旋收之，且曝且击，以沙尽为度，研细，煎生甘草汤，调服二钱。\n\n《图经本草》治小便不通，脐下满闷：海金沙一两，腊南茶半两，捣碎。每服三钱，生姜、甘草煎汤下，日二服。《仁存方》治膏淋如油：海金沙、滑石各一两，甘草梢二钱半，为末。每服二钱，麦门冬煎汤服，日二次。\n\n《普济方》治血淋痛涩，但利水道，则清浊自分：海金沙末，新汲水或沙糖水服一钱。《兰室秘藏》治脾湿肿满，腹胀如鼓，喘不得卧，海金沙散：用海金沙三钱，白术四两，甘草半两，牵牛子一两半，为末。每服一钱，煎倒流水调下，得利为妙。元气虚人禁服此方。\n\n【简误】\n        海金沙，性淡渗而无补益，小便不利，及诸淋由于肾水真阴不足者，勿服。', NULL, NULL, NULL, '海金沙', NULL, '31、海金沙', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466249, '201D7273801A7303DA4B74CB65EBD384', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7323, 417, 400106130, '    主蛇毒，捣傅之；绞汁服，止蛇毒入内心闷。煮渍捋脚，消气肿。\n\n     疏：水蓼感金水之气而兼有土，故味辛性冷而无毒。阴中微阳。冷而辛，所以能解蛇毒入内心闷，及水煮渍捋脚，消气肿也。\n\n【主治参与】\n《集验方》治脚痛成疮：先剉水蓼煮汤，令温热得所，频频淋洗，疮干自安。\n\n《衍义》治瘰疬：水红子不拘多少，微炒一半，生用一半，同为末，好酒调二钱，日三服，食后、夜卧各一服，破者亦治。', NULL, NULL, NULL, '水蓼', NULL, '30、水蓼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466250, 'DA494FA748C841B74C6883C7B5427AC6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7324, 417, 400106129, '    味辛，平，无毒。主恶疮，马疥。一名马疕。\n\n     疏：马勃感土金之气而生，故味辛气平而无毒。宜其主恶疮马疥，及止冻疮也。《衍义》曰：去膜，以蜜揉拌，少以水调呷，治喉痹痛，则辛散之功也。\n\n【主治参与】\n《经验良方》治走马喉痹：马屁勃，即灰菰、焰硝各一两，为末。每吹一字，吐涎血，即愈。\n\n《普济方》治久嗽不止：马勃为末，蜜丸梧子大。每服二十丸，白汤下即愈。\n\n斑疮入眼：马屁勃、蛇皮各五钱，皂角子十四个，为末，入罐内盐泥固济，煅存性，研。每温酒服一钱。此阎孝忠《集效方》也。\n\n因无别用，故不著 “简误”。', NULL, NULL, NULL, '马勃', NULL, '29、马勃', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466251, '8DBC24AF3670087EC50B345440FBD7A2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7325, 417, 400106128, '    味甘，寒，无毒。根及苗主五淋，生煮服之，败席煮服更良。（入药宜用生草。）\n\n     疏：灯心草，气味甘寒，则无毒可知。入心、小肠药也。其质轻通，其性寒，味甘淡，故能通利小肠，热气下行从小便出。小肠为心之腑，故亦除心经热也。\n\n【主治参与】\n灯心草以碱卤浸透，入鸡子壳中封固，煅存性，研细，加梁上倒挂尘，及青鱼胆、明矾、铜青，点咽喉生乳蛾，有神效。\n\n《经验方》治小儿夜啼，用灯心烧灰，涂乳上与吃。\n\n《胜金方》治破伤，多用灯心草烂嚼，和唾贴之，用帛裹，血立止。\n\n又方，治小虫蚁入耳挑不出者，以灯心浸油钓出虫。\n\n【简误】\n性专通利，虚脱人不宜用。', NULL, NULL, NULL, '灯心草', NULL, '28、灯心草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466252, '6BC6FE6A59F980F3B9D7F58B6F2C55F0', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7326, 417, 400106127, '     根有小毒。主痈肿疮瘘，瘰疬结核等。醋磨傅之。亦剥人面皮，除皯䵴。\n\n      疏：山慈菇，味辛气寒，善散热消结，故主痈肿疮瘘，瘰疬结核等。昔人用醋磨傅，今人亦入服药中。产处州遂昌县，实非金灯花与鹿蹄草，叶似车前。\n\n【主治参与】\n入玉枢丹、紫金锭、大内观音救苦锭，磨傅并服，消一切疔肿痈疽，解一切蛇虫毒，有神。方中有大戟，用此不得服甘草，误则杀人。\n\n亦入乳岩、乳毒方用，相宜。\n\n因无别用，故不著 “简误”。', NULL, NULL, NULL, '山慈菇', NULL, '27、山慈菇', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466253, '64C96FE9A95C84823D803015AED90339', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7327, 417, 400106126, '      味苦、辛，寒，无毒。主寒热，瘰疬，鼠瘘，头疮，破癥，散瘿结气，脚肿湿痹，轻身。（土瓜为之使。）\n\n       疏：夏枯草得金水之气，故其味苦辛，而性寒无毒。为治瘰疬、鼠瘘之要药。入足厥阴、少阳经。丹溪谓其补厥阴肝家之血，又辛能散结，苦寒能下泄除热，故治一切寒热，及消瘰疬鼠瘘，破癥散瘿结气。头疮皆由于热，脚肿湿痹，无非湿热所成，热消结散湿去，则三证自除而身亦轻矣。\n\n【主治参与】\n夏枯草得连翘、忍冬藤、贝母、玄参、薄荷、栝楼根、紫背天葵、蓖麻子仁、甘草，治一切瘰疬有效。\n\n得蒲公英，治一切乳痈、乳岩，方具蒲公草条下。\n\n单取数两，水煮浓汁，入生甘菊、紫花地丁、忍冬藤、连翘、白及、白敛、甘草、生地黄、白芷、半枝莲，消一切痈疽肿毒，止痛有神。此复方也。\n\n《简要济众方》治肝虚目睛疼，冷泪不止，血脉痛，羞明怕日：夏枯草半两，香附子一两，为末，每服一钱，茶调下。\n\n《衍义》云：古方用以烧灰，合洁面药。初生嫩时作菜食之，须浸洗淘去苦水。\n\n此草无毒，除治瘰疬鼠瘘，以散瘿结气，消痈肿乳毒之外，无别用，故不著 “简误”。\n', NULL, NULL, NULL, '夏枯草', NULL, '26、夏枯草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466254, 'E2286F943C28556C36FD27007CC3ACB7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7328, 417, 400106125, '     味辛，温，无毒。主疗喉痹，齿风痛，及诸疮疥。饲马，主虫颡毛焦等病。\n\n      疏：谷精草得金气，故味辛，所言气温者，应曰微温，故其性无毒。入足厥阴经，又入足阳明经，补肝气之要药也。辛能散结，微温能通气。喉痹者，手少阴心火与足少阳相火相扇、上壅而成。散二经之火，则气通而无所结滞矣。齿风痛者，阳明胃家风火热盛上冲之所致也。热则生风，风火相搏，故发齿风痛也。诸疮疥之生，皆由于血热。诸痛痒疮疡，皆属心火。药宜辛散，故悉主之。其用以饲马，主虫颡毛焦等病者，以马性多热，又为风热所伤，故主之也。以其入肝，补益肝气，故为治目散翳之上药，而《本经》不载，是谓厥文。\n\n【主治参与】\n谷精草，得决明子、木贼草、甘菊花、密蒙花、生地黄，专除目病障翳。\n\n《集验方》治偏正头痛：用谷精草一两，为末，以白面粉调摊油纸上，贴痛处，干换。\n\n《圣惠方》治鼻衄不止，谷精草为末，熟面汤服二钱。\n\n《明目方》治目中翳膜：谷精草、防风等分，为末。米饮服之，甚验。\n\n邵真人《济急方》治痘后目翳，隐涩泪出，久而不退，用谷精草为末，以肺或猪肝片蘸食。一方加蛤粉等分，同入猪肝内煮熟，日食之。\n\n《卫生家宝方》治小儿雀盲，至晚或不见物，用羯羊肝一具，不用水洗，竹刀剖开，入谷精草一撮，瓦罐煮熟，日食之，屡效。忌铁器。如不肯食，炙熟，捣作丸，绿豆大。每服三十丸，茶下。\n\n《保幼大全》治小儿中暑吐泻，烦渴：谷精草烧存性，用器覆之，放冷，为末。每冷米饮服半钱。\n\n此药味淡，性无毒，喉痹、齿痛、目翳之外，无他用，故不著 “简误”。', NULL, NULL, NULL, '谷精草', NULL, '25、谷精草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466255, '9CC5B75AEDF94128899B97CC4A0DAFB3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7329, 417, 400106124, '     味甘，平，无毒。主妇人乳痈肿，水煮汁饮之，又封之，立消。\n\n       疏：蒲公英得水之冲气，故其味甘平，其性无毒，当是入肝、入胃，解热凉血之要药。乳痈属肝经，妇人经行后，肝经主事，故主妇人乳痈肿，乳毒，并宜生啖之良。\n【主治参与】\n\n      蒲公草，得夏枯草、贝母、连翘、白芷、栝楼根、橘叶、甘草、头垢、特鼠粪、山豆根、山慈菇，治一切乳痈毒肿痛，及治乳岩为上药。\n\n    《图经》治恶刺，及孤尿刺，摘取根茎白汁涂之，惟多涂立差。此方出孙思邈《千金方》。其序云：余以贞观五年七月十五日夜，以左手中指背触着庭木，至晓遂患痛不可忍。经十日，痛日深，疮日高大，色如熟小豆色。尝闻长者之论有此方，遂依治之，手下即愈，痛亦除，疮亦即瘥，未十日而平复如故。杨炎《南行方》亦著其效云。\n\n《梅师方》治产后不自乳儿，蓄积乳汁结作痈：取蒲公草捣傅肿上，日三四度，易之。\n\n此草单治乳痈及肿毒，性既甘平无毒，又乏他用，故无 “简误”。', NULL, NULL, NULL, '蒲公草,蒲公英', NULL, '24、蒲公草,蒲公英', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466256, '7AC2D45FDD6E7E049E9AB4C578C0BA84', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7330, 417, 400106123, '     味甘，微苦，无毒。主目疾，退翳膜，又消积块，益肝胆，明目，疗肠风止痢，及妇人月水不断。得牛角䚡、麝香，治休息痢历久不差。得禹余粮、当归、芎，疗崩中赤白。得槐鹅、桑耳，肠风下血服之，效。又与槐子、枳实相宜，主痔疾出血。\n\n     疏：木贼草感春升之气，故应味甘微苦，而性则无毒。入足厥阴、少阳二经血分。故首主目疾，及退翳膜，益肝胆而明目也。又疗肠风止痢，及妇人月水不断，则消之中又有止之义矣。其主积块，疗肠风止痢，及妇人月水不断，崩中赤白，痔疾出血者，皆入血益肝胆之功，肝藏血故也。\n\n【主治参与】\n木贼得谷精草、决明子、白蒺藜、蝉蜕、生地黄、甘菊花、蜜蒙花，治目疾久不愈，消翳障有奇功。\n\n得槐角子、桑耳煅存性、地榆、茜草根，治肠痔下血，多效。\n\n《广利方》治泻血不止：木贼十二分，切，以水二升，煎取八合，去滓。空心温分二服，如人行五里再服。\n\n《衍义》云：治小肠膀胱气，木贼细剉，微焙，捣为末。沸汤点二钱，食前服，必效。\n\n【简误】\n         目疾由于怒气，及暑热伤血，暴赤肿痛者，非其所任。', NULL, NULL, NULL, '木贼', NULL, '23、木贼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466257, '47A7630313427E76ACEA9FCC3B2F8202', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7331, 417, 400106122, '      味苦，寒。无毒。杀虫疗蛊，治诸毒。传云取二枚缀衣领上，遇蛊毒物则闻其有声，当便知之。有皮壳，其实如皂荚子，去皮研服之，有效。\n\n      疏：预知子感阴寒之气以生，故其味苦，其气寒，其性无毒。凡蛊毒多辛热之物所造，故宜苦寒以泄其热毒，热毒既解，则蛊不灵矣。凡虫皆湿热所生，虫得苦则伏，故杀虫之药多苦多寒也。此草中之有灵性者，故其命名如此。又名仙诏子、圣知子、圣先子。蜀人贵重，云亦难得。采无时。其根味苦，性极冷，其效愈于子，山民目为圣无忧。冬月采，阴干，石臼内捣末，筛细。凡中蛊毒，则水煎三钱匕，温服立已。日华子又云：盍合子，温，治一切风，补五劳七伤，其功不可备述。并治痃癖气块，天行温疾，消宿食，止烦闷、利小便，催生，解毒药，中恶，失音，发落，傅一切蛇虫蚕咬。\n\n【主治参与】\n《和剂局方》预知子丸，治心气不足，精神恍惚，言语错妄，忪悸烦郁，忧愁惨慽，善怒多恐，健忘少睡，夜多异梦，寤即惊魇，或发狂眩，暴不知人，并宜服此：预知子去皮，白茯苓、枸杞子、石草蒲、茯神、柏实、人参、地骨皮、远志、山药、黄精、丹砂等分，为末，炼蜜丸芡实大。每嚼一丸，人参汤下。\n\n《圣惠方》治耳卒聋：八月取石榴，开一孔，留盖，入米醋满中，盖定，面裹煻火中煨熟，取出，入仙诏子、黑李子末，取水滴耳中，脑痛勿惊。如此二夜，又点一耳。\n\n【简误】\n       预知子苦寒能利，凡病人脾虚作泄泻者，勿服。', NULL, NULL, NULL, '预知子,仙诏子,圣知子,圣先子,盍合子', NULL, '22、预知子,仙诏子,圣知子,圣先子,盍合子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466258, '9B7A03FEAE4C7F2FC6C5FF6EEEA480EF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7332, 417, 400106121, '    味苦，平，无毒。主蛊毒，女子腰腹痛，不乐，肠痈，瘰疬，疡气。\n\n       疏：鹿藿禀地中之阴气以生，故其味苦、气平、无毒。入足阳明、太阴、厥阴经。解毒凉血之药也。惟其解毒，故主蛊毒。惟其凉血，故主肠痈，瘰疬，疡气。女人以血为主，血虚有热则腰腹痛、不乐。得苦凉之气，则热退而血得所养，故主女人腰腹痛不乐也。方药不复用，人亦罕识。故不著 “参互” 及 “简误”。', NULL, NULL, NULL, '鹿藿', NULL, '21、鹿藿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466259, '5C984B35DFC107005B30E79F6C66D69F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7333, 417, 400106120, '       主心痛，血痹，面上百病。行药势。\n        \n         疏：白附子感阳气而生，故其味应辛微甘，气大温有小毒，性燥而升，风药中之阳草也。东垣谓其纯阳，引药势上行，是已其主心痛血痹者，风寒之邪触心，以致痰壅心经则作痛，寒湿邪伤血分，则成血痹。风能胜湿，辛湿散寒，故主之也。风性升腾，辛温善散，故能主面上百病而行药势也。日华子用以治中风失音，一切冷风气，面皯瘢疵。李珣用以治诸风冷气，足弱无力，疥癣风疮，阴下湿痒，头面斑痕，入面脂用。丹溪用以治风痰，皆祛风燥湿散结之功也。\n\n【主治参与】\n白附子得南星、半夏，能豁风痰暴壅而有寒邪者，为要药。\n\n同胆星、全蝎、白僵蚕、钓藤、天竺黄、白檀香、牛黄，能治小儿急惊。\n\n《济生方》治痰厥头痛：同天麻、半夏、南星等分，生姜汁浸，蒸饼丸绿豆大，每服四十丸，食后姜汤下。\n\n《简便方》治赤白汗斑：白附子、硫黄等分，为末，姜汁调稀，茄蒂蘸擦，日数次。\n\n《卫生易简方》治面上皯（黑曾），白附子为末，卧时浆水洗面，以白蜜和涂纸上，贴之。久久自落。\n\n【简误】\n      白附子，燥药也。似中风证，虽痰壅禁用。小儿慢惊不宜服。', NULL, NULL, NULL, '白附子', NULL, '20、白附子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466260, '3F5C19961965DD66830429DAD025DD20', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7334, 417, 400106119, '    味甘，寒，无毒。主解诸药毒，止痛，消疮肿毒，人及马急黄，发热咳嗽，杀小虫。生剑南山谷，蔓如豆。\n\n     疏：山豆根得土之冲气，而兼感冬寒之令以生，故其味甘苦，其气寒，其性无毒。甘所以和毒，寒所以除热。凡毒必热、必辛，得清寒之味，甘苦之味，则诸毒自解。譬大人盛德，与物无竞，即阴毒忮害，遇之不起矣。故为解毒清热之上药。凡痛必因于热，毒解热散则痛自止，疮肿自消。人马急黄乃血热极所发，故必发热，热气上熏则发咳嗽。诸虫亦湿热所化，故悉主之，而多获奇效也。\n\n【主治参与】\n山豆根，入散乳毒药中，能消乳岩。\n\n《备急方》解中蛊毒，密取山豆根，水研服少许。未定再服。已禁声音者，亦愈。\n\n又方，治五般急黄：山豆根末，水服二钱。若带蛊气，以酒下。\n\n又方，治赤白滞下：山豆根末，蜜丸梧子大，每服二十丸，空腹白汤下，三服当自止。\n\n又方，治头风热痛：山豆根末，油调，涂两太阳。\n\n又方，治牙龈肿痛：山豆根一片，含于痛所。\n\n《永类方》治喉痈：山豆根磨醋噙之，追涎即愈。势重不能言者，频以鸡翎扫入喉中，即引涎出，立能言语。\n\n《经验方》治麸豆诸疮，烦热甚者：水研山豆根汁，服少许。\n\n《备急方》治疥癣：山豆根末，腊猪脂调涂。\n\n杨清叟《外科》治喉风急证，牙关紧闭，水谷不入：山豆根、白药子等分，水煎噙之，咽下二三口即愈。\n\n【简误】\n病人虚寒者勿服。', NULL, NULL, NULL, '山豆根', NULL, '19、山豆根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466261, '789DBADB28E5CAF24BB71947FD08EB5E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7335, 417, 400106118, '    味辛，温，有毒。主妇人血结月闭，癥瘕痃癖，瘀血，蛊毒鬼疰，心腹痛，冷气胀满，利大小肠，除痰饮积聚，下恶滞物。\n\n     茎中白汁：剥人面皮，去䵟黯。苗如大戟。一名拒冬，一名千金子。\n\n      疏：续随子味辛气温，而其性有毒，实攻击克伐之药也。长于解蛊毒鬼疰，以致腹痛胀满，攻积聚，下恶滞物，及散痰饮。至于妇人月闭，癥瘕痃癖，瘀血，大小肠不利诸病，则各有成病之由，当求其本而治，不宜概施。盖此药之为用，乃以毒攻毒之功也。\n\n【主治参与】\n《圣济录》治小便不通，脐腹胀痛不可忍：用续随子一两，铅丹半两，同少蜜捣作团，瓶盛埋阴处，腊月至春末取出，研，蜜丸梧子大，每服二三十丸，木通汤下。\n\n又方，治涎积癥块：续随子三十枚，腻粉二钱，青黛炒一钱，研匀，糯米饭丸芡子大。每服一丸，打碎，以大枣一枚烧熟去皮核，同嚼，冷茶送下。半夜后，取下积聚恶物为效。\n\n崔元亮《海上方》治蛇咬肿闷欲死：用重台六分，续随仁七粒，捣筛为散。酒服方寸匕，兼唾和少许涂咬处，立效。\n\n《普济方》治黑子疣赘：续随子于熟时涂之，自落。\n\n【简误】\n         病人元气虚，脾胃弱，大便不固着，禁用。', NULL, NULL, NULL, '千金子,拒冬,续随子', NULL, '18、千金子,拒冬,续随子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466262, '50E2E4CFE890275E4B0A70F09CB9FDF6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7336, 417, 400106117, '        味苦，平，无毒。主寒热，鼠瘘瘰疬，痈肿恶疮，瘿瘤结热，蛊毒，去白虫。\n\n         疏：连翘感清凉之气，得金水之性。《本经》虽云味苦平无毒，平应作辛，乃为得之。洁古谓其性凉，味苦。气味俱薄，轻清而浮，升也，阳也。海藏以为阴中阳也。入手足少阳，手阳明经，亦入手少阴心经。其主寒热、鼠瘘瘰疬、瘿瘤结热者，以上来诸证，皆从足少阳胆经气郁有热而成。此药正清胆经之热，其轻扬芬芳之气，又足以解足少阳之郁气，清其热，散其郁，靡不瘳矣。痈肿恶疮，无非荣气壅遏，卫气郁滞而成。清凉以除瘀热，芬芳轻扬以散郁结，则荣卫通和而疮肿消矣。蛊毒非热非辛则不成，热解则蛊自消。湿热盛则生虫，清其热而苦能泄，虫得苦即伏，故去白虫。甄权用以通利五淋，小便不通，除心家客热。日华子用以通小肠，排脓治疮疖，止痛通月经，东垣用以散诸经血结气聚，消肿。丹溪用以泻心火，除脾胃湿热，及治中部血证以为使。海藏用以治气秘火炎之耳聋，一皆清热散结、下气燥湿之功也。\n\n【主治参与】\n得贝母、白芷、甘草、金银花、玄参、薄荷、夏枯草、白及，能消瘰疬。加牡鼠粪、人爪、山豆根、蒲公英，消乳痈、乳岩。\n\n《简便方》治瘰疬结核：连翘、脂麻等分，为末，时时食之。\n\n洁古治项边马刀，属少阳经，连翘二斤，瞿麦一斤，大黄三两，甘草半两。每用一两，煎，食后热服。十余日后，灸临泣穴二七壮，六十日决效。\n\n《集验方》治痔疮肿痛：连翘煎汤熏洗后，以刀上飞过绿矾，入麝香贴之。\n\n【简误】\n      连翘清而无补之药也。痈疽已溃勿服。火热由于虚者勿服。脾胃薄弱，易于作泄者勿服。', NULL, NULL, NULL, '连翘', NULL, '17、连翘', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466263, 'A1B457DABCD1DD8254A2AB251778B05F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7337, 417, 400106116, '       味苦，温，无毒。主破血，止血，补折伤。\n\n        疏：骨碎补得金气，兼得石气。石者水之母也。味苦气温，亦应有辛。好生阴处，故得阴气为多，宜其入足少阴，而主骨、开耳、入血行伤也。开元命名，其义可思矣。甄权用以主骨中毒气，风血疼痛，五劳六极，手足不收，上热下冷。雷公用以治耳鸣。戴元礼用以治痢风，足痿软。皆入肾强骨之验也。\n\n【主治参与】\n骨碎补，得青盐、槐角，炒研，细擦牙，能固齿。\n\n《灵苑方》治虚气攻牙，齿痛血出，或时痒痛：骨碎补二两，铜刀细剉，瓦锅慢火炒黑为末。如常揩齿，良久吐之，咽下亦可。刘松石云：此方不独治牙痛，极能坚骨固牙，益精髓，去骨中毒气疼痛。牙动将落者，数擦立住，再不复动，经用有神。\n\n《圣济总录》治风虫牙痛：骨碎补、乳香等分为末，糊丸，塞孔中。名金针丸。\n\n苏氏《图经》治耳鸣、耳闭，骨碎补削作细条，火炮，乘热塞之。\n\n又方，病后发落：胡孙姜、野蔷薇嫩枝，煎汁，刷之。\n\n《仁存方》治肠风失血：胡孙姜烧存性五钱，或酒，或米饮服。\n\n时珍云：骨碎补，足少阴药也。故能入骨治牙，及久泄痢。昔魏刺史子久泄，诸医不效，垂殆。用此药末，入猪肾中煨熟，与食，顿佳。盖肾主大小便，久泄属肾虚，不可专责脾胃也。雷公用治耳鸣，耳亦肾之窍也。戴元礼治痢后下虚，不善调养，或远行，或房劳，或外感，致两足痿软，或痛，或痹，遂成痢风。宜用独活寄生汤吞虎骨四斤，丸，仍以骨碎补三分之一，同研取汁，酒和服之。外用杜牛膝、杉木节、萆薢、白芷、南星煎汤，频频熏洗。此亦从肾虚骨痿而治也。\n\n雷公云：凡采得，铜刀刮去黄赤毛，细切，蜜拌蒸曝用。\n\n【简误】\n      不宜与风燥药同用。', NULL, NULL, NULL, '骨碎补', NULL, '16、骨碎补', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466264, 'A7813F2E0031DACA7318AB908C345614', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7338, 417, 400106115, '      味苦，温，无毒。主破血下胀。多服令人痢。\n\n       疏：刘寄奴草，其味苦，其气温，揉之有香气，故应兼辛。苦能降下，辛温通行，血得热则行，故能主破血下胀。然善走之性，又在血分，故多服则令人痢矣。昔人谓为金疮要药，又治产后余疾，下血止痛者，正以其行血迅速故也。\n\n【主治参与】\n《集简方》治大小便血：刘寄奴为末，茶调空心服二钱，即止。《千金方》治折伤，瘀血在腹内者：刘寄奴、骨碎补、延胡索各一两，水二升，煎七合，入酒及童子小便各一合，顿温服。\n\n《本事方》治汤火灼伤：刘寄奴捣末，先以糯米浆鸡翎扫上，后乃掺末。并不痛，亦无痕，大验。此方凡汤火伤，先以盐末掺之，护肉不坏，后乃掺药为妙。\n\n《圣惠方》治风入疮口，肿痛：刘寄奴为末，掺之即止。\n\n【简误】\n       刘寄奴草，通行走散之性，专入血分，病人气血虚，脾胃弱，易作泄者，勿服。', NULL, NULL, NULL, '刘寄奴草', NULL, '15、刘寄奴草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466265, '960F13162253672E0526B4058BBEAC3D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7339, 417, 400106114, '       味辛，温，有毒。主心腹冷气不能食，腰脚风冷挛痹不能行，丈夫虚劳，老人失溺、无子，益阳道。久服通神强记，助筋骨，益肌肤，长精神，明目。\n\n        疏：仙茅禀火金之气，然必是火胜金微。虽云辛温，其实辛热有毒之药也。气味俱厚，可升可降，阴中阳也。入手足厥阴经。命门真阳之火，即先天祖气。天非此火不能生物，人非此火不能有生。故真火一衰，则虚劳无子，阳道痿弱，老人失溺，风冷外侵，为腰脚不利，挛痹不能行，并不能生土，以致脾虚腹冷不能食。此药味辛气热，正入命门补火之不足，则诸证自除，筋骨自利，皮脉自益也。命门之系，上通于心，相火得补，则君火益自振摄，故久服能通神强记也。长精神、明目者，言真阳足，阴翳消，肝肾俱补之极功耳。\n\n【主治参与】\n《圣济总录》仙茅丸：壮筋骨，益精神，明目，黑髭须。仙茅二斤，糯米泔浸五日，去赤水，夏月浸三日，铜刀刮剉，阴干，取一斤。枸杞子一斤，车前子十二两，白茯苓去皮茴香炒、柏子仁去壳各八两，生地黄焙、熟地黄焙各四两，为末，酒煮糊丸如梧子大。每服五十丸，食前温酒下，日二服。\n\n【简误】\n       凡味之毒者必辛，气之毒者必热。仙茅味辛，气大热，其为毒可知矣。虽能补命门，益阳道，助筋骨，除风痹，然而病因不同，寒热迥别，施之一误，祸如反掌。况世之人火旺致病者，十居八九。火衰成疾者，百无二三。辛温大热之药，其可常御乎？凡一概阴虚发热，咳嗽，吐血，衄血，齿血，溺血，血淋，遗精，白浊，梦与鬼交，肾虚腰痛，脚膝无力，虚火上炎，口干咽痛，失志阳痿，水涸精竭，不能孕育，老人孤阳无阴，遗溺失精，血虚不能养筋，以致偏枯痿痹，胃家邪热不能杀谷，胃家虚火，嘈杂易饥，三消五疸，阴虚内热，外寒阳厥，火极似水等证，法并禁用。', NULL, NULL, NULL, '仙茅', NULL, '14、仙茅', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466266, '9A14216BEAABFAEBAEAF0B6E13409576', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7340, 417, 400106113, '     味苦，寒，无毒。主肺热咳嗽，痰结喘促，血痔瘘疮。\n\n      疏：马兜铃感冬气而生，故味苦气寒而无毒。亦应有辛，兼金气也。入手太阴经。苦善下泄，辛则善散，寒能除热，其性轻扬，厥状类肺，故能入肺除热，而使气下降。咳嗽者，气升之病也，气降热除，嗽自平矣。痰结喘促，亦肺热病也，宜并主之。血痔瘘疮，无非血热，况痔病属大肠，大肠与肺为表里，清脏热则腑热亦清矣，故亦主之。甄权用以治肺气上急，坐息不得，咳逆连连不止。洁古用以清肺气，补肺，去肺中湿热者，皆除热降气散结之力也。\n\n独行根：一名青木香。治鬼疰积聚，诸毒热肿，蛇毒：水磨为泥，封之，日三四易，立瘥。水煮一二两，取汁服，吐蛊毒。又，捣末水调，涂丁肿，大效。\n\n【主治参与】\n马兜铃，得桑根白皮、百部、天门冬、桔梗、苏子、枇杷叶、贝母、紫菀，能治一切喘嗽。\n\n《圣惠方》治五种蛊毒：马兜铃根三两，为末，分为三贴，以水一盏，煎五分，去滓顿服，当吐蛊出。未快再服，以快为度。\n\n又方，草蛊术在西凉之西及岭南，人中此毒，入咽刺痛欲死者，用马兜铃苗一两，为末，以温水调下一钱匕，即消化蛊出，神效。\n\n《外台秘要》解蛇蛊毒，饮食中得之，咽中如有物，咽不下，吐不出，心下热闷。马兜铃一两，煎服，即吐出。又服麝香一钱匕，即吐蛊毒尽。\n\n《简要济众》治肺气喘嗽：马兜铃二两酥炒，甘草一两水炙，为末。每服一钱，水煎温呷。或以药末含，咽津亦得。\n\n雷公云：凡采得实，去叶及蔓，用生绢袋盛于东屋角畔，悬令干，劈作片，取向里子，去革膜，取净子，焙用。\n\n【简误】\n         肺虚寒作咳嗽，或寒痰作喘者，勿服。', NULL, NULL, NULL, '马兜铃', NULL, '13、马兜铃', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466267, '91D1B492CD55A5AE36BFF65BC6E966DF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7341, 417, 400106112, '       味辛，温、微温，有毒。主杀蛊毒，鬼疰精物，辟恶气不祥，逐邪，解百毒。疗咳嗽喉结，风邪烦惑，失魂妄见，去目中浮翳，杀大毒。不入汤。\n\n        疏：鬼臼得地之金气，而性复阴沉，是以辛温有毒，乃阴草中之散结辟邪者也。故能入阴分以辟不祥，及诸蛊毒，鬼疰精物，尸疰传尸，烦惑，失魂妄见。然此诸病何？莫非阴邪尸鬼之所为。凡物以类相从，故惟阴草之异品，乃能治乎阴鬼之贼害也。其去目中肤翳，及咳嗽喉结风邪，则辛散之功耳。其药有二种，味甘者胜，苦者稍劣。\n\n【主治参与】\n鬼臼得丹砂、雄黄、云母、生犀角、丹参、远志、射干、百部、菖蒲、天门冬，能治一切怪惑不祥，及诸尸疰、传尸，阴邪为祟诸异证。\n\n《妇人良方》治子死腹中，胞破不生：用鬼臼不拘多少，黄者去毛，为细末，不用筛箩，只撚之如粉为度。每服一钱，无灰酒一盏，同煎八分，通口服，立生如神。名一字散。\n\n《千金方》治射工中人，寒热发疮：鬼臼叶一把，苦酒渍捣取汁，服一升，日二次。\n\n三十六黄方：治黑黄急病，其证面黑黄，身如土色，不妨食，脉沉，若青脉入口者死。宜烙口中黑脉，百会、玉泉、章门、心俞。用生鬼臼捣汁一小盏服。干者为末，水服。\n\n【简误】\n       凡病属阳，阳盛热极，有似鬼魅为祟，及烦惑失魂妄见者，不可用。', NULL, NULL, NULL, '鬼臼', NULL, '12、鬼臼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466268, 'B14540F43C409DF1CC226463FAE54207', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7342, 417, 400106111, '        味甘，寒，无毒。主消渴，客热，止小便利。（逆水者良，苏恭：疗反胃呕逆，不下食，胃中热，伤食内热。甄权：解大热，开胃，治噎哕不止。大明：主时疾烦闷，泻利人渴，孕妇心热。）\n\n         疏：芦根禀土之冲气，而有水之阴气，故味甘气寒而无毒。消渴者，中焦有热，则脾胃干燥，津液不生而然也。甘能益胃和中，寒能除热降火，热解胃和，则津液流通而渴止矣。客热者，邪热也，甘寒除邪热，则客热自解。肺为水之上源，脾气散精，上归于肺，始能通调水道，下输膀胱。肾为水脏而主二便，三家有热，则小便频数，甚至不能少忍，火性急速故也。肺肾脾三家之热解，则小便复其常道矣。火升胃热，则反胃呕逆，不下食，及噎哕不止，伤寒时疾，热甚则烦闷，下多亡阴，故泻利人多渴。孕妇血不足则心热。甘寒除热安胃，也能下气，故悉主之也。\n\n     笋：亦能除热，利小便，解河鲀鱼蟹毒。\n\n【主治参与】\n逆水芦根，得竹茹、枇杷叶、麦门冬、乌梅、木瓜，能止因热呕吐。\n\n得竹茹、麦门冬、大青、青黛，能除伤寒热病，烦闷呕吐。《药性论》云：芦根能解大热，开胃，治噎哕不止，皆由甘寒除热之力也。\n\n《外台秘要》治骨蒸肺痿不能食者，苏游芦根饮主之：芦根、麦门冬、地骨皮、生姜各十两，橘皮、茯苓各五两，水二斗，煮八升，去滓，分五服，取汗乃瘥。\n\n《肘后方》治劳复、食复欲死，并以芦根煮浓汁饮。\n\n又方，治呕哕不止、厥逆者：芦根三斤切，水煮浓汁，频饮二升，必效。若以童子小便煮服，不过三升愈。\n\n《金匮玉函方》治五噎吐逆，心膈气滞，烦闷不下食：芦根五两剉，以水三大盏，煎取二盏，温服。\n\n《千金方》治反胃上气。芦根、茅根各二两，水四升，煮二升，分服。\n\n《太平圣惠方》治霍乱烦闷：芦根三两，麦门冬一两，煎服。\n\n《梅师方》治食狗肉中毒，心下坚，或腹胀口干，忽发热妄语，芦根煮汁服。又《圣惠方》治中马肉毒，《千金方》治鯸鮧鱼毒，并食蟹中毒。方俱同。\n\n【简误】\n       因寒霍乱作胀，因寒呕吐，勿服。', NULL, NULL, NULL, '芦根', NULL, '11、芦根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466269, '70BB0C59EE48E6CE27F0083615343FEA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7343, 417, 400106110, '      大寒。主痈肿结热。\n\n       疏：甘蕉禀地中至阴之气以生，其味应甘，气大寒，性无毒。入足阳明经。膏粱之变，发为痈肿。甘寒解阳明之结热，则痈肿自除。苏恭捣傅痈肿，去热毒。捣汁服，治产后血胀闷。大明治天行热狂、烦闷消渴，患痈毒，并金石发动，燥热口干，并绞汁服之。又治头风游风等证，皆取其甘寒凉血除热之功也。\n\n【主治参与】\n《肘后方》发背欲死，芭蕉根捣烂傅之。\n\n《子母秘录》小儿赤游，行于上下，至心即死，捣芭蕉汁，煎涂之。\n\n《圣惠方》血淋涩痛：芭蕉根、旱莲草各等分，水煎服，日二。\n\n【简误】\n       蕉性大寒，痈肿阴证，不焮肿，不发热者，忌之。天行病非阳明热甚者，忌之。产后血胀闷，当以行血补血为主，蕉虽味甘，然性大寒，尤非所宜。', NULL, NULL, NULL, '甘蕉根', NULL, '10、甘蕉根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466270, '772DAF42CCDB5F7923DB618450ECDECA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7344, 417, 400106109, '      味苦，温，无毒。主温疟，狂昜（音羊）寒热，癥瘕积聚，瘿气，逐血止痛，疗金疮、鼻衄。\n\n      疏：白头翁，《本经》味苦温无毒。吴绶益以辛寒。详其所主，似为得之。东垣谓其气厚味薄。既能入血主血，应云气味俱厚。可升可降，阴中阳也。入手足阳明经血分。暑伏足阳明经，则发温疟；伏手阳明经，则病毒痢、滞下纯血。狂昜，鼻衄者，血热也。寒热者，血瘀也。癥瘕积聚，瘿气，靡不由血凝而成。积滞停留则腹痛。金疮，血凉则痛自止。苦能下泄，辛能解散，寒能除热凉血，具诸功能，故悉主之。殆散热、凉血、行瘀之要药欤！前人所谓肾欲坚，急食苦以坚之。痢则下焦虚，故以纯苦之剂坚之。男子阴疝偏坠，小儿头秃腥膻，鼻衄，无此不效。毒痢有此获功，热毒下痢紫血鲜血者，宜之。\n\n【主治参与】\n仲景《金匮玉函方》白头翁汤，治热痢下重：用白头翁二两，黄连、黄檗、秦皮各三两，水七升，煎二升，每服一升。不愈更服。妇人产后痢，虚极者，加甘草、阿胶各二两。\n\n《圣惠方》治下痢咽肿，春夏病此，宜用白头翁、黄连各一两，木香半两，水五升，煎一升半，分三服。\n\n《外台秘要》治阴㿗偏肿，用根生捣傅肿处。一宿当作疮。廿日愈。\n\n《卫生方》治外痔肿痛，用白头翁草，一名野丈人，以根捣涂之，逐血止痛。\n\n《肘后方》治小儿秃疮，白头翁根捣傅，一宿作疮，半月愈。\n\n【简误】\n       白头翁苦寒，滞下胃虚不思食，及下利完谷不化，泄泻由于虚寒寒湿，而不由于湿毒者，忌之。', NULL, NULL, NULL, '白头翁', NULL, '9、白头翁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466271, '5C244D1768222E195C810A426293CEAC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7345, 417, 400106108, '    寒，主小儿赤丹。其渍苎汁，疗渴。\n\n     疏：苎根得土之冲气，而兼阴寒，故味甘气寒而无毒。《别录》专主小儿赤丹，为其寒能凉血也。渍苎汁疗渴者，除热之功也。日华子用以治心膈热，漏胎下血，胎前产后心烦，天行热疾，大渴发狂，及服金石药人心热，罯毒箭、蛇虫咬，皆以其性寒，能解热凉血故也。\n\n【主治参与】\n同生地黄汁，能凉血安胎。\n\n《圣惠方》治小便血淋：苎根煎汤频服，大妙。亦治诸淋。\n\n《斗门方》治五种淋疾：苎根两茎，打碎，以水一碗半，煎半碗，顿服即通。\n\n《梅师方》治妊娠胎动，忽下黄汁如胶，或如小豆汁，腹痛不可忍者：苎根去黑皮切二升，以银一斤，水九升，煎四升。每服入酒半升或一升，分作二服。《圣惠方》同。\n\n《濒湖集简方》治肛门肿痛：生苎根捣烂，坐之良。\n\n《圣惠方》治脱肛不收：苎根捣烂，煎汤熏洗之。\n\n《外台秘要》治五色丹毒：苎根煮浓汁，日三浴之。\n\n【简误】\n        病人胃弱泄泻者，勿服。诸病不由血热者，亦不宜用。', NULL, NULL, NULL, '苎根', NULL, '8、苎根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466272, '8ECC2F49AA53BFF29A974A213B83055B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7346, 417, 400106107, '     主下部䘌疮。\n\n      疏：马鞭草，《图经》谓之龙牙。《别录》味苦，气寒无毒。保升、日华子咸谓辛凉，应有之也。本是凉血破血之药。下部䘌疮者，血热之极，兼之湿热，故血污浊而成疮，且有虫也。血凉热解，污浊者破而行之，靡不瘥矣。陈藏器谓其破血杀虫，亦此意耳。\n\n【主治参与】\n《集验方》治男子阴肿大如升，核痛，人所不能治者，马鞭草捣涂之。\n\n《太平圣惠方》治白癞风：用马鞭草为末，每服一钱，食前荆芥、薄荷汤下，日三服。忌铁。\n\n董炳《集验方》治人疥，马疥：马鞭草捣自然汁半盏，饮尽，十日内愈，神效。\n\n《医方摘要》治赤白下痢：龙牙草五钱，陈茶一撮，煎服，神效。陈嘉谟《本草蒙筌》治杨梅恶疮：马鞭草煎汤，先熏后洗，气到便爽，痛肿随减。\n\n【简误】\n        病人虽有湿热、血热证，脾阴虚而胃气弱者勿服。', NULL, NULL, NULL, '马鞭草', NULL, '7、马鞭草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466273, '7BB15333826C0254FF538A500DEF3F34', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7347, 417, 400106106, '      味苦，寒，有小毒。主热䘌烦满不能食，生捣汁服三四合，多则令人吐。\n\n       疏：豨莶，阳草也。感少阳生发之气以生，故其味苦寒，不应有毒。乃入血分祛风除湿，兼活血之要药也。湿热盛则生䘌。湿则烦满不能食。春生之药，本合风化，风能胜湿，苦寒除热，故主之也。《经》曰：地之湿气，感则害人皮肉筋脉。故苏颂治肝肾风气，四肢麻痹，骨间疼痛，腰膝无力，及行大肠气。成讷用以疗中风。张詠用以轻身驻颜。效已著于曩代，功复见于今时。妙在走而不泄，香可开脾，邪去身安，功力斯倍矣。\n\n【主治参与】\n豨莶，如法修事：一斤，入漆叶四两，亦以蜜酒润过，九蒸九晒，蜜和，丸如梧子大。每五钱，空心饥时白汤吞，日三服。治紫云风、烂麻风，有神。\n\n江陵府节度使成讷进豨莶丸方表略云：臣有弟訢，年三十一，中风伏枕五年，百医不差。有道人钟针者，因睹此患曰：可饵豨莶丸，必愈。其药多生沃壤，高三尺许，节叶相对。其叶当夏五月已来收。每去地五寸剪刈，以温水洗去泥土，摘其叶及枝头。凡九蒸九曝，不必太燥，但取蒸足数为度。仍熬捣为末，炼蜜丸如梧子，空心温酒或米饮下二三十丸。服至二千丸，所患愈加，不得忧虑，是药攻之力。服至四千丸必得复故，五千丸当复丁壮。臣依法修合，令訢服之，果如其言。钟针又言：此药与本草所述功效相异。盖出处盛在江东，彼土人呼猪莶，缘此药如猪莶气，故以为名。但经蒸曝，莶气自泯。每当服后，须吃饭三五匙压之。五月五日采者佳。奉敕宣付医院详录。\n\n知益州张咏进豨莶丸表略云：此草金棱银线，素（应是赤字）茎紫荄，对节而生。蜀号火杴。茎叶颇同苍耳。谁知至贱之中，乃有殊常之效。臣自吃至百服，眼目清明，积至千服，髭须乌黑，筋力轻健，效验多端。臣本州有都押衙罗守一，曾因中风坠马，失音不语。臣与十服，其病立瘥。又和尚智严，年七十，忽患偏风，口眼㖞斜，时时吐涎。臣与十服，亦便得瘥。今合一百剂，差职员史元奏进。\n\n【简误】\n凡病人患四肢麻痹，骨间疼，腰膝无力，由于脾肾两虚，阴血不足，不因风湿所中而得者，不宜服之。予少年时晤金坛令公刘蓉川，论及此药。刘太夫人平居常服，在金坛令隶卒取此草，太夫人见之辄曰非是。乃知张益公表中所云金棱、银线、素茎、紫荄，与吴地所产者有异。物随土变，固其性也。', NULL, NULL, NULL, '豨莶', NULL, '6、豨莶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466274, '106350647B6755F4412F8C20DA65F810', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7348, 417, 400106105, '      味苦、辛，有毒。主中风，除痰，麻痹，下气，破坚积，消痈肿，利胸膈，散血堕胎。（畏附子、干姜、生姜。）\n\n        疏：南星得火金之气，故其味苦辛。火金相搏，故性烈而有毒。阴中之阳，可升可降，入手太阴经。为风寒郁于肺家，以致风痰壅盛之要药也。炎上作苦，苦则善燥，从革作辛，辛则善散，温则开通，故主麻痹，下气，破坚积，消痈肿，利胸膈，散血堕胎。\n\n【主治参与】\n南星得牛胆则燥气减，得火炮则毒性缓。\n\n得姜、桂、附，主破伤风、口噤身强。\n\n得牛胆、皂角、川乌、茯神、牛黄、天竺黄、丹砂，治惊痫。加天麻，治一切风痰壅盛。\n\n同半夏捣细末，入降真香末，傅金疮折伤瘀血。\n\n同桂枝、干姜、甘草、细辛，治西北边人真中风，风痰猝壅僵仆。\n\n【简误】\n       南星味既辛苦，气复大温而燥烈，正与半夏之性同，而毒则过之，故亦善堕胎也。半夏治湿痰多，南星主风痰多，是其异矣。二药大都相类，故其所忌亦同。非西北人真中风者，勿用。详载半夏条下，兹不重出。', NULL, NULL, NULL, '南星,天南星', NULL, '5、南星,天南星', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627098796466275, 'C77251FE743E09C1BF19A4A0812EBF51', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 10:11:34', 1, 'admin', '2024-12-27 10:11:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7349, 418, 400106211, '        味辛，温，无毒，有毒。主绝伤，补中，续筋骨，填髓脑，安五藏，五缓六急，风寒湿痹，疗咳嗽，消瘀血，痞结腰痛，女子疝瘕，利小肠，去蛔虫。\n\n        疏：干漆禀火金之气以生，故其味辛气温，火金相搏则未免有毒，《别录》言之为当矣。甄权加咸，宗奭加苦。气味俱厚，通行肠胃，入肝行血之药也。凡风寒湿邪之中人，留而不去则肠胃郁而生虫，久则五脏六腑皆受病，或为瘫痪，或为拘挛，所自来矣。此药能杀虫消散，逐肠胃一切有形之积滞，肠胃既清，则五脏自安，痿缓痹急自调矣。又损伤一证，专从血论，盖血者，有形者也。形质受病，惟辛温散结而兼咸味者，可入血分而消之，瘀血清则绝伤自和，筋骨自续，则髓脑自足矣。其主痞结腰痛，女子疝瘕者，亦指下焦血分受寒血凝所致。利小肠者，取其通行经脉之功耳。至于疗咳嗽，虽非正治，然亦有瘀血停积，发为骨蒸劳瘵以致咳嗽者，得其清散瘀血之力，则骨蒸退而咳嗽亦除也。误中漆毒者，多食蟹及甘豆汤解之。\n\n【主治参与】\n同䗪虫、桃仁、当归、红花、苏木、牡丹皮、五灵脂、延胡索、牛膝，治腹中瘀血作痛。或产后感寒，恶露未尽，结成痞块作痛者，加入干姜、泽兰。\n\n同楝根、鹤虱、槟榔、锡灰、薏苡根、乌梅、龙胆草，能杀肠胃一切诸虫。\n\n同牛膝、牡丹皮、续断、赤芍药、桃仁、乳香、没药、红花、延胡索、鳖甲，治女子月闭因于瘀血。脐腹作痛畏寒，及不发热，不口渴者，可加桂。\n\n同豨莶叶、生地黄、半枝莲、胡麻、荆芥、何首乌、天门冬、苦参，可疗紫云风。\n\n入仲景大黄䗪虫丸中，治五劳虚极羸瘦，腹满不能饮食，内有干血，肌肤甲错。\n\n【简误】\n干漆，味辛有毒，瘀血得之即化成水，其消散之功可知。凡经闭由于血虚，而非有瘀血结块阻塞者，切勿轻饵。\n\n漆叶：味辛，无毒。《图经》曰：彭城樊阿，少师事华佗，佗授以漆叶青粘散，云：服之去三虫，利五脏，轻身益气，使人头不白。', NULL, NULL, NULL, '干漆', NULL, '11、干漆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967430, '7E02691706FCDA770060C7BBB13C1507', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:20', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7350, 418, 400106210, '      味甘，寒，无毒。主阴痿，水肿，益气，充肌肤，明目。久服不饥，不老轻身。\n\n      疏：楮实禀土气以生，故其味甘气寒无毒。气薄味厚，阴也，降也。入足太阴经。其主水肿，益气，充肌肤者，脾为土脏而主肌肉，脾虚则肌肉不充，土虚则水湿泛滥。甘为土化，能入脾坚土，则水肿消，肌肉充，气自益矣。明目者，目得血而能视，脾旺自能生血也。阴痿者，精气竭也。脾实则能生精而灌注于肾，故阴自强也。补脾益气，则五脏皆实，不饥，不老轻身，是其验矣。\n\n【主治参与】\n《活法机要》治水气蛊胀，楮实子丸，以洁净府：用楮实一斗，水三斗，熬成膏，茯苓三两，白丁香一两半，为末，以膏和丸梧子大。从少至多，至小便清利，用减为度。后服治中汤养之。忌甘苦峻补，及发动之物。\n\n刘禹锡《传信方》治女子月经不绝，来无时者。取案纸三十张烧灰，以清酒半升，和调服之，顿定。蓐中血晕服之立验。已毙者，去板齿灌之，经一日亦活。\n\n《圣惠方》治癣湿痒：用楮叶捣烂傅上。\n\n《外台秘要》治天行病后，两胁胀满，脐下如水肿，以榖枝汁，随意服，愈。\n\n《肘后方》治鼻衄，小劳辄出：楮叶取汁，饮三升，良。\n\n《子母秘录》治小儿下痢赤白，作渴，得水又呕逆者：楮叶炙香，以饮浆半升浸至水绿，去叶。以木瓜一个切，内汁中，煮二三沸，去木瓜，细细饮之。\n\n《圣惠方》治通身水肿：楮枝叶，煎如饧。空腹服一匕，日三服。\n\n《直指方》肝热生翳：楮实研细，食后蜜汤服一钱，日再服。\n\n《外台秘要》治金疮出血：榖子捣，傅之。\n\n【简误】\n    楮实虽能消水补脾，然气亦微寒，脾胃虚寒者不宜用。', NULL, NULL, NULL, '楮实', NULL, '10、楮实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967431, 'A463D6A7595A02934BDA65CCEB4F834B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:20', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7351, 418, 400106209, '        味苦，寒，无毒。主五藏肠胃中结热，黄疸，肠痔，止泄痢，女子漏下赤白，阴伤蚀疮，疗惊气在皮间，肌肤热赤起，目热赤痛，口疮。久服通神。\n\n         疏：黄檗禀至阴之气而得清寒之性者也，其味苦，其气寒，其性无毒，故应主五脏肠胃中结热。盖阴不足则热始结于肠胃。黄疸虽由湿热，然必发于真阴不足之人。肠澼痔漏，亦皆湿热伤血所致。泄痢者，滞下也，亦湿热干犯肠胃之病。女子漏下赤白，阴伤蚀疮，皆湿热乘阴虚流客下部而成。肤热赤起，目热赤痛，口疮，皆阴虚血热所生病也。以至阴之气，补至阴之不足，虚则补之，以类相从，故阴回热解湿燥而诸证自除矣。乃足少阴肾经之要药，专治阴虚生内热诸证，功烈甚伟，非常药可比也。洁古用以泻膀胱相火，补肾水不足，坚肾壮骨髓，疗下焦虚，诸痿瘫痪，利下窍除热。东垣用以泻伏火，救肾水，治冲脉气逆，不渴而小便不通，诸疮痛不可忍。丹溪谓：得知母滋阴降火，得苍术除湿清热，为治痿要药。得细辛泻膀胱火，治口舌生疮。\n\n【主治参与】\n黄檗，为足少阴肾经药，然以柴胡引之则入胆。以黄连、葛根、升麻引之则入肠胃及太阴脾经，治湿热滞下。\n\n佐牛膝、枸杞、地黄、五味子、鳖甲、青蒿，则益阴除热。\n\n佐甘菊、枸杞、地黄、蒺藜、女贞实，则益精明目。\n\n得猪胆汁、水银粉，则主诸热疮有虫，久不合口。\n\n得铅丹，则生肌止痛。\n\n得木瓜、茯苓、二术、石斛、地黄，则除湿健步。\n\n佐白芍药、甘草，则主火热腹痛。\n\n《外台秘要》治口中及舌上生疮，剉黄檗含之。\n\n《千金方》治小儿重舌，以黄檗，苦竹沥浸，点舌上。\n\n《肘后方》治咽喉卒肿，食饮不通。黄檗捣末，苦酒和敷肿上，佳。又方，治伤寒时气温病，毒攻手足，肿痛欲断，亦治毒攻阴肿：细剉黄檗五斤，以水三斗煮渍之。《伤寒类要》同。\n\n葛氏方：治食自死六畜肉中毒。黄檗末服方寸匕，未解再服之。\n\n《经验方》治呕血：黄檗蜜涂炙干，杵为末，用麦冬汤调下二钱匕，立瘥。\n\n《梅师方》治痈疽发背，或发乳房，初起微赤，不急治之即杀人：捣黄檗末，和鸡子白涂之。\n\n《简要济众方》治吐血热极：黄檗二两，蜜炙捣末。每服二钱，温糯米饮调下。\n\n《十全博救方》治小儿热泻：黄檗削皮焙为末，用薄米饮丸如粟大。每服十丸，米饮下。\n\n《深师方》治伤寒热病口疮：黄檗削去粗皮，蜜渍一宿，唯欲令厚，含其汁，良久吐，更含。若胸中热有疮时，饮三五合尤佳。\n\n《衍义》云：檗木，今用皮以蜜炙，与青黛各一分，同为末，入生龙脑一字，研匀。治心脾热，舌颊生疮，当掺疮上，有涎即吐。又张仲景檗皮汤，无不验。《伤寒论》中已著。\n\n《妇人良方》治妊娠下痢白色，昼夜三五十行：根黄厚者蜜炒令焦，为末，大蒜煨熟，去皮捣烂如泥，和丸梧子大。每空心米饮下三五十丸，日三服。神妙不可述。\n\n《洁古家珍》治赤白浊淫，及梦泄精滑，真珠粉丸：黄檗炒、真蛤粉各一斤，为末，炼蜜丸绿豆大。每服一百丸，空心温酒下。黄檗苦而降火，蛤粉咸而补肾也。又方：加知母炒，牡蛎煅，山药炒，等分为末，糊丸梧子大。每服八十丸，盐汤下。\n\n许学士《本事方》治积热梦遗，心忪恍惚，膈中有热，宜清心丸主之：黄檗末一两，片脑一钱，炼蜜丸梧子大。每服十五丸，麦冬汤下，此大智禅师方也。\n\n《三因方》治口疳臭烂，绿云散：黄檗五钱，铜绿二钱，为末掺之，漱去涎。\n\n《圣惠方》治鼻疳有虫。黄檗二两，冷水浸一宿，绞汁温服。《普济方》治鬈毛毒疮生头中，初生如蒲桃，痛甚：黄檗一两，乳香二钱半，为末，槐花煎水，调作饼，贴于疮上。\n\n《子母秘录》治小儿脐疮不合者：黄檗末涂之。\n\n又方，治臁疮、热疮：黄檗末一两，轻粉三钱，猪胆汁调搽之。或只用蜜炙黄檗末一味。\n\n张杲《医说》治火毒生疮：凡人冬月向火，火气入内，两股生疮，其汁淋漓，用黄檗末掺之，立愈。一妇生此，人无识者，用此而愈。\n\n《宣明方》敛疮生肌：黄檗末，面糊调涂，效。\n\n【简误】\n         黄檗固能除热益阴，然阴阳两虚之人，病兼脾胃薄弱，饮食少进，及食不消，或兼泄泻，或恶冷物，及好热食，肾虚天明作泄，上热下寒，小便不禁，少腹冷痛，子宫寒，血虚不孕，阳虚发热，瘀血停滞，产后血虚发热，金疮发热，痈疽溃后发热，伤食发热，阴虚小水不利，痘后脾虚，小水不利，血虚不得眠，血虚烦躁，脾阴不足作泄等证，法咸忌之。', NULL, NULL, NULL, '黄柏,黄檗,檗木', NULL, '9、黄柏,黄檗,檗木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967432, '90A54712FC32023A2BCECFCF4DF2D311', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:20', 1, 'admin', '2025-01-14 15:57:02');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7352, 418, 400106208, '        味酸，平，无毒。主心腹寒热，邪结气聚，四肢酸疼湿痹，烦心不得眠，脐上下痛，血转久泄，虚汗烦渴，补中益肝气，坚筋骨，助阴气，能令人肥健。久服安五藏，轻身延年。\n\n        疏：酸枣仁得木之气而兼土化，故其实酸平，仁则兼甘，气味匀齐，其性无毒，为阳中之阴。入足少阳，手少阴，足厥阴、太阴之经。专补肝胆，亦复醒脾，从其类也。熟则芳香，香气入脾，故能归脾。能补胆气，故可温胆。母子之气相通，故亦主虚烦，烦心不得眠。其主心腹寒热，邪结气聚，及四肢酸疼湿痹者，皆脾虚受邪之病，脾主四肢故也。胆为诸脏之首，十一脏皆取决于胆，五脏之精气皆禀于脾。故久服之，功能安五脏，轻身延年也。\n\n     《别录》主烦心不得眠，脐上下痛，血转久泄，虚汗烦渴。补中益肝气，坚筋骨，助阴气，能令人肥健者，缘诸证悉由肝胆脾三脏虚而发。胆主升，肝藏血，脾统血，三脏得补，久而气增，气增则满足，故主如上功能也。\n\n【主治参与】\n君茯神、远志、麦门冬、石斛、五味子、龙眼、人参，能止惊悸，并一切胆虚易惊。\n\n入温胆汤，治病后胆虚不眠。\n\n入归脾汤，治脾家气血虚，自汗，不眠，惊悸，不嗜食。\n\n《太平圣惠方》治骨蒸，不眠心烦：用酸枣仁一两炒研，水二盏，研绞取汁，煮粥熟，下地黄汁一合再煮匀食。\n\n凡服固表药而汗不止者，用枣仁一两炒研，同地黄、白芍药、麦冬、五味子、龙眼肉、竹叶煎服，多服取效，汗乃心液故尔。\n\n《简便方》治睡中汗出，即盗汗，用酸枣仁、白茯苓、人参等分，为末。每服一钱，米饮下。\n\n《外台秘要》疗刺入肉中，枣仁核烧存性，为细末，水服之立出。\n\n【简误】\n       凡肝、胆、脾三经，有实邪热者勿用。以其收敛故也。', NULL, NULL, NULL, '酸枣仁', NULL, '8、酸枣仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967433, '3100E5E33BDD9DF762A2A515CEB4CCF0', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7353, 418, 400106207, '      味甘，平，无毒。主安五藏，定魂魄，杀精魅邪鬼，消瘀血，通五淋。　　\n\n       疏：琥珀感土木之气而兼火化，故其味甘平，无毒而色赤。阳中微阴，降也。入手少阴、太阳，亦入足厥阴经。专入血分。五脏有所感触则不安，能杀精魅邪鬼，则五脏自安，而魂魄自定。心主血，肝藏血。入心入肝，故能消瘀血也。\n\n     《药性论》云：琥珀君，治百邪，产后血瘀作痛。日华子云：疗蛊毒，壮心，明目磨翳，止心痛癫邪，破结癥。正以其阳明之物，又消瘀血，故主上来诸病也。若作傅药，能止血生肌，愈金疮。宋高祖时，宁州贡琥珀枕，碎以赐军士傅金疮，其一证也。出罽宾国。初如桃胶，凝乃成焉。\n\n     《海药》云：是海松木中津液，初如桃胶，后乃凝结，性温，主止血，生肌，镇心，明目，破癥瘕气块，产后血晕闷绝，儿枕痛等，并宜饵此。以拾草通明而坚轻、色赤者良。\n　　\n【主治参与】　　\n得没药、乳香、延胡索、干漆、鳖甲，为散，治产后血晕有神。佐以人参、益母草、泽兰、生地、牛膝、当归、苏木，作汤，送前药，则治儿枕痛，恶露下不尽，腹痛，少腹痛，寒热等证，极效。　\n　\n和大黄、鳖甲作散子，酒下方寸匕，下妇人腹内恶血。　　\n\n同鳖甲、京三棱各一两，没药、延胡索各半两，大黄六铢，熬捣为散，空心酒服三钱。治妇人癥瘕气块，及产后血晕闷绝，儿枕痛甚。虚极者，减大黄。　　\n\n同丹砂、滑石、竹叶、麦冬、木通，治心家有热，小肠受之，因之小水不利，立效。　　\n\n同人爪、珍珠、玛瑙、珊瑚，除目翳赤障。　　\n\n得丹砂、犀角、羚羊角、天竺黄、远志、茯神，镇惊主诸痫。　\n　\n《直指方》治小儿胎惊：琥珀、防风各一钱，丹砂半钱，为末，猪乳调一字，入口中，最妙。\n　　\n又方，治小儿胎痫：琥珀、丹砂各少许，全蝎一枚，为末。麦门冬汤调一字服。　\n　\n《圣惠方》治小儿转胞：真琥珀一两，为末。用水四升，葱白十茎，煮汁三升，入琥珀末二钱，温服，砂石诸淋，三服皆效。　\n　\n《普济方》小便淋沥：琥珀为末二钱，麝香少许，白汤服之，或萱草煎汤服。老人虚人，以人参汤下。亦可蜜丸，以赤茯苓汤下。\n　　\n《外台秘要》治从高坠下，有瘀血在内：刮琥珀屑，酒服方寸匕。或入蒲黄二三匙，日服四五次。　　\n\n《鬼遗方》治金疮闷绝不识人：琥珀研粉，童子小便调一钱，三服瘥。\n　　\n【简误】　　\n         此药毕竟是消磨渗利之性，不利虚人。大都从辛温药则行血破血，从淡渗药则利窍行水，从金石镇坠药则镇心安神。凡阴虚内热，火炎水涸，小便因少而不利者，勿服琥珀以强利之，利之则愈损其阴。', NULL, NULL, NULL, '琥珀', NULL, '7、琥珀', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967434, '49816C872298A8E9175ECC0D607B2AA1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7354, 418, 400106206, '        味甘，平，无毒。主胸胁逆气，忧恚惊邪恐悸，心下结痛，寒热，烦满，咳逆，口焦舌干，利小便，止消渴，好睡，大腹，淋沥，膈中痰水，水肿淋结，开胸腑，调藏气，伐肾邪，长阴益气力，保神守中。久服安魂养神，不饥延年。其有抱根者，名茯神。　　\n\n       茯神，平，主辟不祥。疗风眩风虚，五劳，口干，止惊悸，多恚怒善忘，开心益智，安魂魄，养精神。　　\n\n       疏：茯苓生于古松之下，感土木之气而成质，故其味甘平，性则无毒。入手足少阴，手太阳，足太阴、阳明经，阳中之阴也。胸胁逆气，邪在手少阴也。忧恚惊邪，皆心气不足也。恐悸者，肾志不足也。心下结痛、寒热烦满咳逆、口焦舌干，亦手少阴受邪也。甘能补中，淡而利窍，补中则心脾实，利窍则邪热解，心脾实则忧恚惊邪自止，邪热解则心下结痛，寒热烦满咳逆，口焦舌干自除。中焦受湿热则口发渴，湿在脾，脾气弱则好睡。大腹者，脾土虚不能利水，故腹胀大也。淋沥者，脾受湿邪则水道不利也。膈中痰水，水肿，皆缘脾虚所致。中焦者，脾土之所治也，中焦不治，故见斯病。利水实脾，则其证自退矣。开胸腑，调脏气，伐肾邪者何？莫非利水除湿、解热散结之功也。长阴益气力，保神守中，久服安魂养神，不饥延年者，补心脾，伐肾邪，除湿利窍之极功也。白者入气分，赤者入血分，补心益脾，白优于赤；通利小肠，专除湿热，赤亦胜白。　　\n\n《药性论》云：茯苓臣，忌米醋，能开胃止呕逆，善安心神，主肺痿痰壅，治小儿惊痫，疗心腹胀满，妇人热淋，赤者破结气。日华子云：茯苓补五劳七伤，安胎，暖腰膝，开心益智，止健忘。　　\n\n    茯神，抱木心而生，以此别于茯苓。《别录》谓茯神平。总之，其气味与性，应是茯苓一体。茯苓入脾肾之用多，茯神入心之用多。故主辟不祥，疗风眩风虚，五劳，口干，止惊悸，多恚怒善忘，开心益智，安魂魄，养精神。\n  《药性论》又云：茯神君，味甘无毒。主惊痫，安神定志，补劳乏，主心下急痛坚满，人虚而小肠不利，加而用之。　　\n     其心名黄松节，治偏风口面㖞斜，毒风筋挛不语，心神惊掣，虚而健忘，其所主与茯苓大同小异耳。　\n　\n【主治参与】　　\n白茯苓得炼蜜、胡麻仁，饵之可以辟谷，延年不饥。　　\n\n入五苓散，利水除湿。暑气胜则去桂。\n　　\n得人参、白术、橘皮、山药、扁豆、芍药、甘草，为补脾胃之上药。　\n　\n得二术、泽泻、车前、白芍药、橘皮、木瓜、猪苓，为消水肿之要剂。　\n　\n入六味地黄丸，能伐肾邪。　　\n\n入补心丹，则补心安魂养神。　\n　\n《百一选方》朱雀丸：治心神不定，恍惚健忘，不乐，火不下降，水不上升，时复振跳。常服消阴、养火、全心气：茯神二两去皮，沉香半两，为末，炼蜜丸小豆大。每服三十丸，食后人参汤下。　\n　\n《证治要诀》治血虚心汗，别处无汗，独心孔有汗，思虑多则汗亦多，宜养心血：以艾汤调茯苓末，服一钱。　　\n\n《直指方》治心虚梦泄，或白浊：白茯苓末二钱，米汤调下，日二服，东坡方也。　\n　\n威喜丸：治丈夫元阳虚惫，精气不固，小便下浊，余沥常流，梦寐多惊，频频遗泄。妇人白淫、白带并治之。白茯苓去皮四两，作匮，以猪苓四钱半入内，煮二十余沸，取出日干，去猪苓，为末，化黄蜡搜和，丸弹子大。每嚼一丸，空心津下，以小便清为度。忌米醋。　　\n\n《三因方》治小便淋浊，由心肾气虚，神志不守，或梦遗白浊：赤白茯苓等分为末，新汲水飞去沫，控干，以地黄汁同捣，酒熬作膏，和丸弹子大，空心盐汤嚼下一丸。　　\n\n《禹讲师方》治妊娠水肿，小便不利恶寒：赤茯苓去皮，葵子各半两，为末。每服二钱，新汲水下。　　\n\n《普济方》治卒然耳聋：黄蜡不拘多少，和茯苓末细嚼，茶汤下。　　\n\n夏子益《奇疾方》治血余怪证，十指节断坏，惟有筋连，无节肉虫出如灯心，长数寸，遍身绿毛卷，名曰血余：以茯苓、胡黄连煎汤，饮之愈。　　\n\n《普济方》治水肿尿涩：茯苓皮，椒目等分，煎汤，日饮取效。　　\n\n【简误】　　\n       病人肾虚，小水自利，或不禁，或虚寒精清滑，皆不得服。', NULL, NULL, NULL, '茯苓', NULL, '6、茯苓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967435, '6A81EF2AB93B31C245DD24885162BEEF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7355, 418, 400106205, '      味甘，平，无毒。主惊悸，安五藏，益气，除风湿痹，疗恍忽虚损吸吸，历节腰中重痛，益血止汗。久服令人润泽美色。耳目聪明，不饥不老，轻身延年。　　\n\n叶：味苦，微温，无毒。主吐血，衄血，痢血，崩中赤白，轻身益气。令人耐寒暑，去湿痹，生肌。四时各依方向采，阴干。　　\n\n柏白皮：主火灼烂疮，长毛发。　　\n\n        疏：柏感秋令得金气，其质坚而气极芬芳，故其实味甘平无毒。甄权加辛，亦应有之。入足厥阴、少阴，亦入手少阴经。其主惊悸者，心藏神，肾藏精与志，心肾两虚则病惊悸。入心故养神，入肾故定志，神志得所养而宁定，则其证自除矣。芬芳则脾胃所喜，润泽则肝肾所宜，故能安五脏，五脏皆安则气自益矣。心主五色，耳为肾窍，目为肝窍，加以久服气专，其力自倍，岂不令人润泽美色，耳目聪明，不饥不老，轻身延年哉？惟除风湿痹之功，非润药所能，当是叶之能事耳。\n\n       《别录》疗恍忽，即惊悸之渐也。虚损吸吸，精气微也，历节腰中重痛，肝肾不足也。汗乃心液，心主血，益阴血则诸证悉瘥矣。　\n　\n 叶：味苦而微温，义应并于微寒，故得主诸血，崩中赤白。若夫轻身益气，令人耐寒暑，则略同于柏实之性矣。惟生肌去湿痹，乃其独擅之长也。　\n　\n柏白皮：主火灼烂疮，长毛发者，凉血之功也。　　\n\n【主治参与】　　\n雷斅云：柏叶，有花柏叶、丛柏叶，及有子圆叶。其有子圆叶成片，如大片云母，叶皆侧叶，上有微赤毛者，宜入药用。柏实，凡使先以酒浸一宿，至明漉出晒干，用黄精自然汁于日中煎之，缓火煮成煎为度。每煎柏子仁三两，用酒五两浸。服柏实法：九月连房取实，曝收去壳，研末。每服二钱，温酒下，一日三服，渴即饮水，令人悦泽。一方加松子仁等分，以松脂和丸。一方加菊花等分，蜜丸服。寇宗奭：治老人虚闭。柏子仁、松子仁、大麻仁等分，同研，熔蜜蜡丸梧子大。以少黄丹汤，食前服二三十丸，日二服。　\n　\n《普济方》治小儿躽啼惊痫，腹满，大便青苔色：用柏子仁末，温水调服一钱。\n　　\n陆氏《积德堂方》治黄水湿疮：真柏油二两，熬稠搽之，如神。　　\n\n叶，甄权用以治冷风历节疼痛，止尿血。　　\n\n日华子用以炙罯冻疮，烧取汁，涂头黑润鬓发。　　\n\n苏颂用以傅汤火伤，止痛灭瘢，服之疗蛊痢，作汤常服，杀五脏虫，益人。　\n　\n丹溪云：柏属阴与金，善守，故采其叶，随月建方，取其多得月令之气，此补阴之要药，其性多燥，久得之大益脾土，以滋其肺。　　\n\n神仙服饵方：五月五日采五方侧柏叶三斤，远志去心二斤，白茯苓一斤，为末，炼蜜和丸梧子大。每以仙灵脾酒下三十丸，日再服。并无所忌。　\n　\n《杨氏家藏方》治中风不省人事。得病之日，便进此药，可使风退气和，不成废人。柏叶一握去枝，葱白一握连根研如泥，无灰酒一升，煎一二十沸，温服，如不饮酒，分作四五服，方进他药。　　\n\n《圣惠方》治忧恚吐血，烦满少气，胁中疼痛：柏叶为散，米饮调服二方寸匕。　\n　\n《普济方》治衄血不止：柏叶、榴花，研末吹之。\n　　\n《百一选方》治大肠下血：随四时方向采柏叶，烧研，每米饮服二钱。王涣之舒州病此，陈宜父大夫传方，二服愈。　\n　\n又方：以柏叶一斤，捣令极匀，加蜜丸如梧子大。每五钱，白汤空心吞，治肠风效。　\n　\n《普济方》治酒毒下血，或下痢：嫩柏叶九蒸九晒二两，陈槐花炒焦一两，为末，蜜丸梧子大。每空心温酒下四十丸。\n　　\n《本草图经》治蛊痢下黑血茶脚色，或脓血如靛色：柏叶焙干为末，黄连和煎为汁，服之。　\n　\n《经验方》治小儿洞痢：柏叶煮汁，代茶饮之。　　\n\n《本草图经》治汤火灼烧。柏叶生捣，涂之，系定二三日，止痛灭瘢。　　\n\n姚僧坦《集验方》治鼠瘘核痛末成脓：以柏叶捣涂，熬盐熨之，气下即消。　\n　\n《圣惠方》治大风厉疾，眉发不生：侧柏叶九蒸九晒，为末，炼蜜丸梧子大。每服五丸至十丸，日三夜一，服百日即生。　　\n\n《圣惠方》治头发黄赤：生侧柏叶末一升，猪膏一升，和丸弹子大。每以布裹一丸，纳泔汁中化开，沐之，一月色黑而润矣。　\n　\n【简误】　　\n         柏子仁，体性多油，肠滑作泻者勿服。膈间多痰者勿服。阳道数举，肾家有热，暑湿作泻，法咸忌之。已油者勿用入药。　　', NULL, NULL, NULL, '柏实，柏子仁', NULL, '5、柏实，柏子仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967436, 'AA262DA0408F18A9CFA66494E65AFC1E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2025-01-14 15:53:59');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7356, 418, 400106204, '       味苦，寒。根：大寒。子：微寒，无毒。主五内邪气，热中消渴，周痹风湿，下胸胁气，客热头痛，补内伤大劳嘘吸，坚筋骨，强阴，利大小肠。久服坚筋骨，轻身不老，耐寒暑。\n\n        疏：枸杞感天令春寒之气，兼得乎地之冲气，故其味苦甘，其气寒而其性无毒。苗叶苦甘，性升且凉，故主清上焦心肺客热。根名地骨，味甘淡，性沉而大寒，故主下焦肝肾虚热，为三焦气分之药。\n       \n        《经》曰：热淫于内，泻以甘寒者是已。子味甘平，其气微寒，润而滋补，兼能退热，而专于补肾润肺，生津益气，为肝肾真阴不足，劳乏内热补益之要药。《本经》主五内邪气，热中消渴，周痹。\n\n         《别录》主风湿，下胸胁气，客热头痛，当指叶与地骨皮而言，以其寒能除热故也。至于补内伤大劳嘘吸，坚筋骨强阴，利大小肠；又久服坚筋骨，轻身不老，耐寒暑者，方是子之功用，而非根叶所能办矣。老人阴虚者，十之七八，故服食家为益精明目之上品。昔人多谓其能生津益气，除阴虚内热、明目者，盖热退则阴生，阴生则精血自长，肝开窍于目，黑水神光属肾，二脏之阴气增益，则目自明矣。\n\n【主治参与】\n甘枸杞子，得地黄、五味子、麦门冬、地骨皮、青蒿、鳖甲、牛膝，为除虚劳内热，或发寒热之要药。加天门冬、百部、枇杷叶，兼可治肺热咳嗽之因阴虚者。\n\n《千金方》枸杞煎：治虚劳，退虚热，轻身益气，令一切痈疽永不发。用枸杞三十斤，春夏用茎叶，秋冬用根实，以水一石，煮取五斗，以滓再煎取三斗，澄清去滓，再煎取二斗，入锅煎如饧，收之。每早酒服一合。《经验方》金髓煎：枸杞子，逐日摘红熟者，不拘多少，以无灰酒浸之，蜡纸封固，勿令泄气。两月足，取入砂盆中擂烂，滤取汁，同浸酒入银锅内，慢火熬之，不住手搅，恐粘滞不匀。候成膏如饧，净瓶密收。每早温酒服二大匙，夜卧再服。百日身轻气壮，积年不辍，可以羽化也。\n\n《经验方》枸杞酒：变白，耐老，轻身。用枸杞子二升，十月壬癸日，面东采之，以好酒二升，磁瓶内浸三七日。乃添生地黄汁三升，搅匀密封，至立春前三十日开瓶。每空心暖饮一杯，至立春后髭发却黑。勿食芜菁、葱、蒜。\n\n《瑞竹堂方》四神丸：治肾经虚损，眼目昏花，或云翳遮睛。甘枸杞子一斤，好酒浸透，分作四分：一分同蜀椒一两炒，一分同小茴香一两炒，一分同芝麻一两炒，一分同川楝肉一两炒，拣取枸杞，加熟地黄、白术、白茯苓各一两，为末，炼蜜丸，日服。\n\n《龙木论》疗肝虚下泪：枸杞子二斤，绢袋盛，浸一斗酒中，密封三七日，饮之。\n\n《肘后方》疗目赤生翳：枸杞捣汁，日点三四次，神验。\n\n《圣惠方》治面（黑曾）皯皰，枸杞子十斤，生地三斤，为末。每服方寸匕，温酒下，日三服。久则如童颜。\n\n《摄生方》疗注夏虚病：枸杞子、五味子，研细滚水泡，代茶饮，效。\n\n《千金方》治虚劳客热：枸杞根为末，白汤调服。有痼疾人慎之。\n\n又方，治虚劳苦渴，骨节烦热，或寒：用枸杞根白皮切五升，麦冬三升，小麦二升，水二斗，煮至麦熟，去滓。每服一升，口渴即饮。\n\n又方，治肾虚腰痛：枸杞根、杜仲、萆薢各一斤，好酒三斗渍之。罂中密封，锅中煮一日，饮之任意。\n\n《简便方》疗小便出血：鲜地骨皮，洗捣自然汁，无汁则以水煎汁。每服一盏，入酒少许，食前温服。\n\n《千金方》治带下，脉数：枸杞根一斤，生地黄五斤，酒一斗，煮五升，日日饮之。\n\n《兰室秘藏》治口舌糜烂，因膀胱移热于小肠，则上为口糜，心胃壅热，水谷不下：地骨皮、柴胡各三钱，水煎服之。\n\n《卫生宝鉴》疗下疳：先以浆水洗之，后搽地骨皮末。生肌止痛。\n\n《永类方》疗妇人阴肿，或生疮：枸杞根煎水，频洗。\n\n唐慎微《本草》疗痈疽恶疮，脓血不止：地骨皮洗净，刮去粗皮，取细白瓤，以粗皮同骨煎汤洗，令脓血尽。以细瓤贴之，立效。\n\n《千金方》治瘭疽出汗，此证手足肩背累累如赤豆。用枸杞根、葵根叶，煮汁煎如饧，随意服之。\n\n《闺阁事宜》治足趾鸡眼作疮作痛：地骨皮同红花研细，傅之，次日即愈。\n\n《肘后方》治火赫毒疮，此患急防毒气入心腹：枸杞捣汁，服之立瘥。\n\n《十便良方》治目涩有翳：枸杞叶、车前叶挼汁，以桑叶裹，悬阴地一夜，取汁点之，不过三五度。\n\n【简误】\n        枸杞虽为益阴除热之上药，若病脾胃薄弱，时时泄泻者勿入。须先治其脾胃，俟泄泻已止，乃可用之。即用尚须同山药、莲肉、车前、茯苓相兼，则无润肠之患矣。', NULL, NULL, NULL, '枸杞', NULL, '4、枸杞', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967437, 'E530BA2681A4A381C244375A301DC362', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7357, 418, 400106203, '     味苦、酸、咸，寒，无毒。主五内邪气热，止涎唾，补绝伤，五痔，火疮，妇人乳瘕，子藏急痛。以七月七日取之，捣取汁，铜器盛之，日煎令可作丸，大如鼠屎，纳窍中，三易乃愈。又堕胎。久服明目益气，头不白，延年。\n\n枝：主洗疮，及阴囊下湿痒。\n\n皮：主烂疮。\n\n根：主喉痹寒热。\n\n花：苦平无毒。主五痔，心痛，眼赤，杀腹藏虫及热，治皮肤风，并肠风泻血，赤白痢，并炒服。\n\n叶：平无毒，煎汤治小儿惊痫壮热，疥癣，及疔肿。\n\n       疏：槐实感天地阴寒之气，而兼木与水之化，故其味苦气寒而无毒。《别录》益以酸咸，宜矣。入手足阳明，兼入足厥阴经。其主五内邪气热者，乃热邪实也。涎唾多者，脾胃有热也。伤绝之病，其血必热。五痔由于大肠火热。火疮乃血为火伤。妇人乳瘕，肝家气结血热所成。子藏急痛，由于血热燥火。槐为苦寒纯阴之药，为凉血要品，故能除一切热，散一切结，清一切火。如上诸病莫不由斯三者而成，故悉主之。久服明目益气，头不白，延年者，血分无热，则目自明矣。热能伤气，除火热则气自益矣。凉血则发不白，热去则阴精不损，故引年也。其花味以苦胜，故除手足阳明、足厥阴诸热证尤长耳。\n\n【主治参与】\n《外台秘要》疗蛔虫心痛：取槐树上木耳烧灰，末如枣许，正发和水服。若不止，饮热水一升，蛔虫出。\n\n《千金方》疗胎赤眼：取槐枝如马鞭大，长二尺，作二段，齐头，麻油一匙置铜钵内，晨使童子一人，以其木研之，至瞑乃止，令仰卧以涂两眼眦，日三度瘥。\n\n古方：以子入冬月牛胆中渍之，阴干百日，每日吞一粒。久服明目通神，白发还黑。有痔及下血者，尤宜服之。\n\n《千金方》治九种心痛：当太岁上取新生槐枝一握，去两头，水三大升，煎取一升，顿服。\n\n《千金翼》治蠼螋疮：槐白皮醋浸半日，洗之。及诸恶疮。\n\n《肘后方》疗肠痔，大便常下血：槐树上木耳，取末，饮方寸匕，日三服。\n\n《经验方》治野鸡痔：用槐柳枝煎汤洗痔上，便以艾灸之，七壮。\n\n又方，治下血：槐花、荆芥穗等分，为末。酒调下一钱匕。\n\n《梅师方》治痔有虫作痒，或下脓血：多取槐白皮，浓煎汁，安盆内，先熏后洗，良久，欲大便当有虫出，不过三度即愈。仍以其皮为末，绵裹内下部。\n\n孟诜《必效方》疗阴疮湿痒：槐树北面不见日枝，煎水洗三五遍，冷再暖之。\n\n《太清草木方》云：槐者，虚星之精。以十月上巳日采子服之，去百病，长生通神。又《梁书》言：庚肩吾常服槐实，年七十余，发鬓皆黑，目看细字，亦其验也。\n\n《外台秘要》疗内外痔：用槐角子一斗，捣汁晒稠，取地胆为末，同捣丸梧子大。每服十丸，兼作挺子内下部。或以苦参末代地胆亦可。\n\n《圣济总录》治目热昏暗：槐子、黄连各二两，为末，蜜丸梧子大。每浆水下二十丸，日二服。\n\n杨梅毒疮乃阳明积热所生。《集简方》用槐花四两略炒，入酒二盏，煎十余沸，热服。胃虚寒者勿服。\n\n《医方摘要》疗疔疮肿毒，一切痈疽，不问已成未成，但焮痛者，皆用槐花微炒，核桃仁二两，无灰酒一钟，煎十余沸，热服。未成者二三服，已成者一二服见效。\n\n《摘玄方》治白带：槐花炒、牡蛎煅等分，为末，酒服三钱。\n\n《圣惠方》治风热牙痛，槐枝烧热烙之。\n\n《普济方》疗破伤风：用避阴槐枝上皮，旋刻一片，安伤处，用艾灸皮上百壮。不痛灸至痛，痛者灸至不痛，用火摩之。\n\n《生生方》治阴囊下湿痒：槐白皮炒，煎水日洗。\n\n【简误】\n         槐性苦寒而属纯阴，病人虚寒，脾胃作泄，及阴虚血热而非实热者，外证似同，内因实异，即不宜服。', NULL, NULL, NULL, '槐实', NULL, '3、槐实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967438, '8703CE16ED58B958548365B1061B05B3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7358, 418, 400106202, '     味苦、甘，温，无毒。主疽恶疮，头疡白秃，疥瘙风气，安五藏，除热，胃中伏热，咽干消渴，及风痹死肌。炼之令白。其赤者主恶痹。久服轻身，不老延年。\n\n      疏：松脂感天之阳气而得乎地之火土之化者也。故其味苦而兼甘，其气则温，其性无毒。得阳气兼火土，则其性燥，燥则除湿散风寒。苦而燥则能杀虫。甘能除热，胃中伏热散则咽干消渴自止。痹者，风寒湿合而为病也。地之湿气，感则害人皮肉筋脉，此死肌之所由来也。湿热之邪散则血不瘀败，荣气通调而无壅滞，故主疽恶疮。荣和热散，则头疡白秃、疥瘙风气俱愈矣。热消则荣血和，风湿去则卫气安，脾胃健，五脏无病。可知湿去则身轻可必。久服不老延年，固可想见。\n\n松实：味甘，气温，性和而无毒。《本经》言苦者，误也。以其属阳，故亦主风痹寒气。其主虚羸少年，补不足者，精不足补之以味，甘能益血是已。形不足温之以气，温能和气是已。服饵延年轻身不饥，惟此足以当之。然亦久服乃可责效耳。\n\n松叶：味苦，温而不甘。宜其主风湿疮，生毛发也。安五脏，守中，不饥，延年。其旨具松脂条内。服之可治恶疾，即癞病。炙罯冻疮风疮佳。\n\n松节：味苦，气温，性燥。故能主百节久风，风虚脚痹疼痛。\n\n【主治参与】\n陶弘景以松节酿酒，主脚弱骨节风。\n\n丹溪以松节炒焦用，以治筋骨间病，能燥血中之湿。\n\n《外台秘要》治历节风痛，四肢如解脱：松节二十斤，酒五斗，浸三七日，每服一合，日五六服。\n\n《集简方》治阴毒腹痛：油松木七块，炒焦，冲酒二钟，热服。\n\n《谈野翁方》跌扑损伤，松节煎酒服。\n\n【简误】\n       松脂、松叶，其性甚燥，味又苦温，病人血虚有火，及病不关风寒湿所伤而成者，咸不宜服。', NULL, NULL, NULL, '松脂', NULL, '2、松脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967439, '826E9FD3A101E17B1F110ED0E04A04AD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7359, 418, 400106201, '      味辛、甘，大热，有小毒。主温中，利肝肺气，心腹寒热冷疾，霍乱转筋，头痛，腰痛，出汗，止烦，止唾，咳嗽，鼻齆。能堕胎，坚骨节，通血脉，理疏不足，宣导百药，无所畏。久服神仙不老。（元素：补下焦不足。治沉寒痼冷之病。渗泄，止渴，去荣卫中风寒，表虚自汗。春夏为禁药，秋冬下部腹痛非此不能止。好古：补命门不足，益火消阴。日华子：桂心治一切风气，补五劳七伤，通九窍，利关节，益精明目，暖腰膝，破痃癖癥瘕，消瘀血，治风痹骨节挛缩，续筋骨，生肌肉。甄权：主九种心痛，腹内冷气痛不可忍，咳逆结气壅痹，脚痹不仁，止下利，杀三虫，治鼻中息肉，破血，通利月闭，胞衣不下。）\n\n            疏：桂禀天地之阳，而兼得乎土金之气，故其味甘辛，其气大热，亦有小毒。木之纯阳者也。洁古谓其气热，味大辛，纯阳。东垣谓其辛热有毒。浮也，气之薄者，桂枝也。气之厚者，肉桂也。气薄则发泄，故桂枝上行而发表。气厚则发热，故肉桂下行而补肾。此天地亲上亲下之道也。桂枝入足太阳经；桂心入手少阴、厥阴经血分；桂肉入足少阴、厥阴经血分。夫五味，辛、甘发散为阳；四气，热亦属阳。气味纯阳，故能散风寒。自内充外，故能实表。辛以散之，热以行之，甘以和之，故能入血行血，润肾燥。其主利肝肺气，头痛出汗，止烦止唾，咳嗽，鼻齆，理疏不足，表虚自汗，风痹骨节挛痛者，桂枝之所治也。以其病皆得之表虚不任风寒，寒邪客之所致，故悉主之，以其能实表祛邪也。其主心腹寒热冷疾，霍乱转筋，腰痛堕胎，温中，坚筋骨，通血脉，宣导百药，无所畏。又补下焦不足，治沉寒痼冷，渗泄，止渴，去荣卫中风寒，秋冬下部腹痛因于寒，补命门，益火消阴者，肉桂之所治也。气薄轻扬，上浮达表，故桂枝治邪客表分之为病。味厚，甘辛大热而下行走里，故肉桂、桂心，治命门真火不足，阳虚寒动于中，及一切里虚阴寒，寒邪客里之为病。盖以肉桂、桂心，甘辛而大热，所以益阳。甘入血分，辛能横走，热则通行，合斯三者，故善行血。命门者，心包络也，道家所谓两肾中间一点明。又曰：先天祖气是也。先天真阳之气，即医家所谓命门相火，乃真火也。天非此火不能生物，人非此火不能有生。若无此真阳之火，则无以蒸糟粕而化精微，脾胃之气立尽而亡矣。心腹寒热，寒邪在里也。冷疾，霍乱转筋者，脾与肝同受寒邪也。行二脏之气则前证自止矣。腰者，肾之府，动摇不能，肾将惫矣！补命门之真阳，则腰痛自除。血热则行，故堕胎也。益阳则温中。筋者肝之余也，骨者，肾之余也。入肝入肾，故坚筋骨也。通血脉，宣导百药，无所畏者，热则通行，辛则善散也。阳长则阴消，气之自然者也，能益阳则消阴必矣。寒邪触心则心痛，阳虚气不归元，因而为寒所中，则腹内冷气痛不可忍。咳逆者亦气不归元所致也。结气壅痹，脚痹不仁者，皆寒湿邪客下焦，荣卫不和之所生也。血凝滞而不行，则月经不通，血瘀不走，则胞衣不下。九窍不通，关节不利者，荣卫不调，血分之病也。消瘀血，破痃癖癥瘕，疏导肝气，通行瘀血之力也。补五劳七伤者，盖指阳气虚羸下陷，无实热之候也。其曰久服神仙不老，甄权又谓杀三虫、治鼻中息肉，大明又谓益精明目，皆非其性之所宜也。何者？独阳偏热之质，行血破血乃其能事，阴精不长则阳无所附，安所从得神仙不老哉？味既带甘，焉能杀虫？鼻中息肉，由于肺有积热，瞳子神光属肾，肉桂辛而大热，其不利于肺热、肾阴不足亦明矣！益精明目，徒虚语耳。尽信书则不如无书，斯之谓也。\n\n【主治参与】\n得芍药、炙甘草、饴糖、黄耆则建中，兼止荣弱自汗。\n\n得石膏、知母、人参、竹叶、麦门冬，治阳明疟，渴欲引饮，汗多，寒热俱甚。\n\n得白芷、当归、川芎、黄耆、生地黄、赤芍药、白僵蚕，治金疮为风寒所击，俗名破伤风。\n\n得朴硝、当归，下死胎。\n\n得蒲黄、黑豆、泽兰、益母草、红花、牛膝、生地黄、当归，治产后少腹儿枕作痛。甚则加乳香、没药各七分。\n\n得吴茱萸、干姜、附子，治元气虚人，中寒腹痛不可忍，虚极则加人参。\n\n佐参、耆、五味、当归、麦冬，疗疮疡溃后热毒已尽。内塞长肉良。\n\n入桂苓甘露饮，治中暑霍乱吐泻，殊验。\n\n得姜黄、郁金，治怒气伤肝胁痛。\n\n得当归、牛膝，治冬月难产，产门交骨不开。\n\n得当归、牛膝、生地黄、乳香、没药、桃仁，治跌扑损伤，瘀血凝滞腹中作痛，或恼怒劳伤以致蓄血发寒热，热极令人不得眠。腹不痛，大便不秘，亦不甚渴，脉不洪数，不思食，食亦无味，热至天明，得汗暂止，少顷复热，小便赤，此其候也。和童子小便服之立除。\n\n【简误】\n        桂辛甘，其气大热，独热偏阳，表里俱达，和荣气，散表邪，出汗，实腠理，则桂枝为长，故仲景专用以治冬月伤风寒即病，邪在表者，寇宗奭、成无己论之详矣，一览可尽，因附之于后。肉桂、桂心实一物也，只去皮耳。此则走里行血，除寒破血，平肝，入右肾命门，补相火不足，其功能也。然大忌于血崩，血淋，尿血，阴虚吐血，咯血，鼻衄，齿衄，汗血，小便因热不利，大便因热燥结，肺热咳嗽，产后去血过多，及产后血虚发热，小产后血虚寒热，阴虚五心烦热，似中风口眼歪斜、失音不语、语言蹇涩、手足偏枯，中暑昏晕，中热腹痛，妇人阴虚少腹痛，一切温病，热病，头疼口渴，阳证发斑发狂，小儿痧疹，腹疼作泻，痘疮血热干枯黑陷，妇人血热经行先期，妇人阴虚内热经闭，妇人阴虚寒热往来、口苦舌干，妇人血热经行作痛，男妇阴虚，内热外寒，中暑泻利，暴注如火热，一切滞下纯血由于心经伏热，肠风下血，脏毒便血，阳厥似阴，梦遗精滑，虚阳数举，脱阴、目盲等三十余证，法并忌之。误投则祸不旋踵！谨察病因，用舍在断。行其所明，无行所疑。其难其慎，毋尝试也！\n\n      附：寇宗奭曰：桂，辛甘大热。《素问》云：辛甘发散为阳。故汉张仲景桂枝汤治伤寒表虚，皆须此药，正合辛甘发散之意。本草三种之桂，不用菌桂、牡桂者，此二种性止于温，不可以治风寒之病也。然《本经》止言桂，仲景又言桂枝者，取枝上皮也。好古曰：或问本草言桂能止烦出汗，而张仲景治伤寒有 “当发汗” 凡数处，皆用桂枝汤。又云：无汗不得用桂枝。汗家不得重发汗，若用桂枝是重发其汗。汗多者用桂枝甘草汤，此又用桂枝闭汗也。一药二用，与本草之义相通否乎？曰：本草言桂辛甘大热，能宣导百药，通血脉，止烦出汗，是调其血而汗自出也。仲景云：太阳中风，阴弱者汗自出。卫实荣虚，故发热汗出。又云：太阳病发热汗出者，此为荣弱卫强。阴虚阳必凑之，故皆用桂枝发其汗。此乃调其荣气，则卫气自和，风邪无所容，遂自汗而解。非桂枝能开腠理，发出其汗也。汗多用桂枝者，以之调和荣卫，则邪从汗出而汗自止，非桂枝能闭汗孔也。昧者不知出汗、闭汗之意，遇伤寒无汗者，也用桂枝，误之甚矣！桂枝汤下发汗，“发” 字当认作 “出” 字，汗自然出，非若麻黄能开腠理，发出其汗也。其治虚汗，亦当逆察其意可也。成无己曰：桂枝本为解肌者，太阳中风，腠理致密，荣卫邪实，津液禁固，其脉浮紧，发热汗不出者，不可与此必也。皮肤疏泄自汗，脉浮缓，风邪干于卫气者，乃可投之。发散以辛甘为主，桂枝辛热，故以为君，而以芍药为臣，甘草为佐者，风淫所胜，平以辛苦，以甘缓之，以酸收之也。以姜、枣为使者，辛甘能发散，而又用其行脾胃之津液而和荣卫，不专于发散也。故麻黄汤不用姜、枣，专于发汗，不待行其津液也。', NULL, NULL, NULL, '桂枝,桂', NULL, '1、桂枝,桂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627125773967440, '2844DDBC8E5D8E2150F56BD9E2F28108', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 12:01:21', 1, 'admin', '2025-01-03 16:57:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7360, 418, 400106229, '        味甘，温，无毒。主一切风血。理腰脚，轻身，变白不老。浸酒服之。（生温、括、睦、婺山中，树如木天蓼，老人服之，一月放杖，故以为名。）\n\n         疏：放杖木得土气以生，故味甘气温无毒。甘入脾而养血，温散风而通行，故主一切风血、腰脚为病。变白易老，亦皆血虚不能荣养筋骨，及润毛发所致，甘能补血，血足则发自不白，身轻不老有自来矣。', NULL, NULL, NULL, '放杖木', NULL, '29、放杖木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067333, '9EA6726E8722464E9AB5731EE8FA4CC8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7361, 418, 400106228, '      味酸、涩，平、温，无毒。疗脾泄下痢，止小便利，涩精气。久服令人耐寒轻身。\n\n      疏：金樱子得阳气而兼木化，故其味酸涩，气平温无毒。气薄味厚，阴中阳也。入足太阳，手阳明，兼入足少阴经。十剂云：涩可去脱。脾虚滑泄不禁，非涩剂无以固之。膀胱虚寒则小便不禁，肾与膀胱为表里，肾虚则精滑，时从小便出。此药气温味酸涩，入三经而收敛虚脱之气，故能主诸证也。精固则精气日生，而阳气充，骨髓满，故耐寒轻身也。\n\n【主治参与】\n和芡实粉为丸，名水陆丹，益气补真。\n\n孙真人《食忌》金樱子煎：霜后用竹夹子摘取，入木臼中杵去刺，劈去核。以水洗过捣烂，入大锅水煎，不得绝火，减半滤过，仍煎似稀饧。每服一匙，暖酒调服。活血驻颜，其功不可备述。\n【简误】\n泄泻由于火热暴注者，不宜用。小便不禁，及精气滑脱，因于阴虚火炽而得者，不宜用。', NULL, NULL, NULL, '金樱子', NULL, '28、金樱子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067334, '25172BF2D37C3643D54F395E33306E34', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7362, 418, 400106227, '        味甘，温，无毒。主辟恶，杀鬼精物，温疟、蛊毒、痫痓（痓作痉）。去三虫，除邪，令人无梦魇。久服通神明，轻身长年。\n\n       疏：苏合香，聚诸香之气而成，故其味甘气温无毒。凡香气皆能辟邪恶，况合众香之气而成一物者乎？其走窍逐邪，通神明，杀精鬼，除魇梦、温疟、蛊毒，宜然矣。亦能开郁。', NULL, NULL, NULL, '苏合香', NULL, '27、苏合香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067335, '3A3FE77A1ED8B043EBEB5FCBEE1A4BE4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7363, 418, 400106226, '    李珣云：味辛，温，无毒。烧之辟天行时气，宅舍怪异。小儿带之，辟邪恶气。\n\n     疏：降真香，香中之清烈者也，故能辟一切恶气不祥。入药以番舶来者，色较红，香气甜而不辣，用之入药殊胜，色深紫者不良。上部伤，瘀血停积胸膈骨，按之痛，或并胁肋痛，此吐血候也，急以此药刮末，入药煎服之良。治内伤，或怒气伤肝吐血，用此以代郁金，神效。\n\n    《名医录》云：周崈被海寇刃伤，血出不止，筋骨如断，用花蕊石散不效。军士李高用紫金散掩之，血止痛定，明日结痂如铁，遂愈，且无瘢痕。叩其方，则用紫藤香，瓷瓦刮下研末尔。云即降真之最佳者，曾救万人。', NULL, NULL, NULL, '降真香', NULL, '26、降真香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067336, '428365E9AD145CFB9437E9FE289DF123', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7364, 418, 400106225, '       微温。疗风水毒肿。去恶气，疗风瘾疹痒毒。\n\n        疏：乳香得木气而兼火化。本经微温，大明辛热微毒，元素苦辛。气厚味薄，阳也。入足太阴，手少阴，兼入足厥阴经。风水毒肿，邪干心脾，恶气内侵，亦由二经虚而邪易犯。瘾疹痒毒，总因心脾为风湿热邪所干致之。脾主肌肉，而痛痒疮疡皆属心火。此药正入二经，辛香能散一切留结，则诸证自瘳矣。日华子云：煎膏止痛长肉。陈藏器云：治妇人血气，疗诸疮令内消。则今人用以治内伤诸痛，及肿毒，内服外敷之药，有自来矣。\n\n【主治参与】\n同紫花地丁、白及、白敛、金银花、夏枯草、白芷、连翘、贝母、甘菊、甘草、穿山甲、没药，治一切痈疽疔肿。\n\n同续断、牛膝、当归、红曲、牡丹皮、没药、地黄、川芎，治内伤胸胁作痛。\n\n同没药、牛膝、泽兰、黑豆、蒲黄、五灵脂、延胡素、牡丹皮、山查，治产后儿枕作痛。\n\n入一切膏药，能消毒止痛。\n\n《灵苑方》治甲疽弩肉，脓血疼痛不愈：用乳香为末，胆矾烧研，等分傅之，内消即愈。\n\n《山居四要》治玉茎作肿：乳香、葱白等分，捣敷。\n\n《简要济众方》难产催生：用明乳香为末，取母猪血和丸梧子大。每服五丸，酒下。\n\n【简误】\n       痈疽已溃不宜服。诸疮脓多时未宜遽用。', NULL, NULL, NULL, '乳香', NULL, '25、乳香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067337, '996A7F639349E635C37C2D6022CD7F65', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7365, 418, 400106224, '      本经无正文。弘景云：白檀，消热肿。藏器；主心腹霍乱，中恶鬼气，杀虫。日华子云：檀香，热，无毒。治心痛，霍乱，肾气腹痛，浓煎服。水磨傅外肾，并腰肾痛处。详其所主诸证，亦是芬芳开发，辟恶散结除冷之药也。今人多供燃爇。非上乘沉水者不入药。', NULL, NULL, NULL, '檀香', NULL, '24、檀香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067338, '81802C842F6DF6C8A69AA11944B08B72', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7366, 418, 400106223, '      微温。疗风水毒肿，去恶气。\n\n        疏：沉香禀阳气以生，兼得雨露之精气而结，故其气芬芳，其味辛而无毒。气厚味薄，可升可降，阳也。入足阳明、太阴、少阴，兼入手少阴、足厥阴经。本经疗风水毒肿者，即风毒水肿也。风为阳邪，郁于经络，遇火相煽，则发出诸毒，沉香得雨露之精气，故能解风火之毒。水肿者，脾湿也，脾恶湿而喜燥，辛香入脾而燥湿，则水肿自消。凡邪恶气之中人必从口鼻而入，口鼻为阳明之窍，阳明虚则恶气易入。得芬芳清阳之气则恶气除而脾胃安矣。\n\n附录：李珣：味苦温，无毒。主心腹痛霍乱，中恶邪鬼疰，清人神，并宜酒煮服之。诸疮肿宜入膏用。日华子：味辛热，无毒，主调中，补五脏，益精壮阳，暖腰膝，去邪气，止转筋吐泻冷气，破痃癖，冷风麻痹，骨节不任，风湿皮肤痒，心腹痛，气痢。元素：补右肾命门相火。\n\n【主治参与】\n同人参、菖蒲、远志、茯神、酸枣仁、生地黄、麦门冬，治思虑伤心，心气郁结不舒者。得木香、藿香、砂仁，治中恶腹中㽲痛，辟一切恶气。\n\n同苏子、橘红、枇杷叶、白豆蔻、人参、麦门冬，治胸中气结，或气逆不快。\n\n《医垒元戎》治胞转不通，非小肠、膀胱、厥阴受病，乃强忍房事，或过忍小便所致，当治其气则愈，非利药可通也。沉香、木香各二钱，为末，白汤空腹服之，以通为度。\n\n【简误】\n沉香治冷气、逆气、气郁、气结，殊为要药。然而中气虚，气不归元者忌之。心经有实邪者忌之。非命门真火衰者，不宜入下焦药用。', NULL, NULL, NULL, '沉香', NULL, '23、沉香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067339, '062CCDA76F86E7E27A5F5300EC943995', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7367, 418, 400106222, '      味辛，温，无毒。主温脾胃，止霍乱拥胀，风毒诸肿，齿疳䘌。能发诸香。\n\n       疏：丁香禀纯阳之气以生，故其味辛气温性无毒。气厚味薄，升也，阳也。入足太阴、足阳明经。其主温脾胃，止霍乱拥胀者，盖脾胃为仓廪之官，饮食生冷伤于脾胃，留而不去则为壅塞胀满，上涌下泄则为挥霍撩乱，辛温暖脾胃而行滞气，则霍乱止而拥胀消矣。齿疳䘌者，亦阳明湿热上攻也，散阳明之邪则疳䘌自除。疗风毒诸肿者，辛温散结，而香气又能走窍除秽浊也。\n\n【主治参与】\n同白豆蔻、藿香、陈皮、厚朴、砂仁，治霍乱因于寒。加生姜、半夏，治吐呕因于寒冷伤胃，或寒月饱食受寒腹痛甚。同砂仁、厚朴、干姜、橘皮、草果、苍术、木香、麦糵，治小儿伤生冷腹痛。\n\n刘氏《小儿方》治小儿虚寒吐泻：丁香、橘皮等分，姜汁糊丸绿豆大。米汤化下。\n\n《全幼心鉴》治小儿脾胃虚寒，呕吐不止：丁香、半夏末各一钱，姜汁浸一夜，晒干为末，姜汁打面为丸黍米大。量大小，用姜汤下。\n\n《和剂局方》治妇人产难：母丁香、乳香、麝香三件，用十分之三，各为末，腊月兔脑和杵为丸，如芡实大。每服一丸，酒下。\n\n《梅师方》治乳头破裂：丁香末，傅之。\n\n《证治要诀》食蟹致伤：丁香末，姜汤服五分，入陈氏异功散，治痘疮虚寒之极，又值冬月寒气薄之发不出者。\n\n【简误】\n       丁香气味辛温，一切有火热证者忌之。非属虚寒，概勿施用。', NULL, NULL, NULL, '丁香', NULL, '22、丁香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067340, '0435D31F088E290A7590BA1E20C1306F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7368, 418, 400106221, '      味甘，温、微寒，无毒。主心腹邪结气，明目，目赤痛，伤泪出，目肿眦烂，齆鼻，破心下结痰痞气。久服轻身，耐老不饥。\n\n       疏：蕤核得土气以生。神农：味甘，气温。《别录》加微寒无毒，气薄味厚，阳中之阴也。入足厥阴经。厥阴为风木之脏，开窍于目。风热乘肝则肝血虚而目为之病，或为赤痛肿伤，或为泪出眦烂，此药温能散风，寒能除热，甘能补血，肝气和而目疾悉瘳矣。其主心腹邪结气者，即邪热气也。热则生痰，痰碍中焦，气为之痞，甘寒除热，温主通行，热邪去而痰自不生，痰结解而气自通畅矣。鼻齆者，热在上焦心肺之分也。甘寒总能除上下之热，故亦主之。非养性益精之药，而云轻身益气不饥者，未必然也。\n\n【主治参与】\n《和剂局方》春雪膏：治肝虚风热上攻，眼目昏暗，痒痛隐涩，赤肿羞明，迎风有泪，多见黑花：用蕤核去皮压去油二两，脑子二钱半，研匀，生蜜六钱和收，点眼。\n\n《集效方》百点膏：治一切风热眼，蕤仁去油三钱，甘草、防风各六钱，黄连五钱，以三味煎取浓汁，次下蕤仁膏，日点。\n\n【简误】\n        目病非关风热，而因于肝肾两虚者，不宜用。凡修事，汤浸去皮尖，劈作两片，用芒硝、木通、通草同煎，一伏时取出，研膏入药。', NULL, NULL, NULL, '蕤核', NULL, '21、蕤核', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067341, '636ED01CD98AF301C61866097723FE4E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7369, 418, 400106220, '       本经附出女贞条下，不载气味所主。然观陈藏器云：其皮堪浸酒，补腰膝令健，枝叶烧灰淋汁，或煎膏，涂白癜风，亦可作稠煎傅之。应是苦寒无毒，气味俱阴，入肝入肾之药也。惟其入肝，故主白癜风，盖肝为风木之位，藏血之脏，血虚则发热，热甚则生风，苦寒能凉血清热，故主之也。其补腰膝令健者，腰为肾之府，肾虚则湿热乘之而腰膝不利；又肾为作强之官，虚则热而软，故其性欲坚，急食苦以坚之。此药味苦入肾，正遂其欲坚之性耳。肾气既实则湿热自除，而腰膝自健矣。\n\n【主治参与】\n秘方：取其叶煮饮，治痰火甚验。盖痰火未有不因阴虚火炎，上烁乎肺，煎熬津液而成。此药直入足少阴经补养阴气，则痰火自消，如釜底抽薪之意也。兼能散风毒恶疮。昔有老妓患杨梅结毒三十年者，有道人教以单服此药，疮愈而颜色转少，皆假其清热凉血之功耳。一名枢木。黑子者名极木，又名猫儿刺。用作罗经入地不差。\n\n【简误】\n        脾胃虚寒作泄，及火衰阴痿者，忌之。', NULL, NULL, NULL, '枸骨，枢木', NULL, '20、枸骨，枢木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067342, 'B9545EC1213704D3E85743B9CE43197E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7370, 418, 400106219, '      味苦、甘，平，无毒。主补中，安五藏，养精神，除百疾。久服肥健，轻身不老。\n\n      疏：女贞实禀天地至阴之气，故其木凌冬不凋。神农：味苦气平。《别录》加甘无毒。观今人用以为变白多效者，应是甘寒凉血益血之药。气薄味厚，阴中之阴，降也。入足少阴经。夫足少阴为藏精之脏，人身之根本。虚则五脏虽无病而亦不安，百疾丛生矣。《经》曰：精不足者，补之以味。盖肾本寒，因虚则热而软，此药气味俱阴，正入肾除热补精之要品。肾得补则五脏自安，精神自足，百疾去而身肥健矣。其主补中者，以其味甘，甘为土化，故能补中也。所主如上功能，则轻身不老盖有自矣。此药有变白明目之功，累试辄验，而经文不载，为阙略也。叶长子黑色者为女贞。叶微圆子红色者为冬青。亦能治风虚，补益肌肤。\n\n【主治参与】\n同地黄、何首乌、人参、麦门冬、旱莲草、南烛子、牛膝、枸杞子、山药、没食子、桑椹子、黄檗、椒红、莲须，为变白要药。\n\n同甘菊花、生地黄、蒺藜、枸杞子，能明目。\n\n《简便方》治虚损百病，久服须白再黑，返老还童：用女贞实十月上巳日收，阴干，用时以酒浸一日，蒸透晒干一斤四两，旱莲草五月收，阴干，十两为末，桑椹子四月收，阴干十两为末，炼蜜丸如梧子大。每服七八十丸，淡盐汤下。若四月收桑椹，捣汁和药，七月收旱莲捣汁和药，即减蜜之半矣。\n\n《济急仙方》治风热赤眼：冬青子不拘多少，捣汁重汤熬膏，净瓶收固，每用点眼。\n\n《普济方》治一切眼疾：冬青叶研烂，入朴硝贴之。海上方也。\n\n【简误】\n       气味俱阴，变白家当杂保脾胃药，乃椒红温暖之类同施。否则恐有腹痛作泄之患。', NULL, NULL, NULL, '女贞实,女贞,女贞子', NULL, '19、女贞实,女贞,女贞子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067343, '469C3FA61CA91CD1BA9D4323F454F9D8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2025-01-14 16:14:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7371, 418, 400106218, '     味辛、苦，平，无毒。主瘾疹风痒，浮肿，齿痛。一名白胶香。（附：李时珍治一切痈疽，疮疥，金疮，吐血，咯血，活血生肌，止痛解毒，烧过揩牙，永无牙疾。）\n\n      疏：枫香脂属金有火，故其味辛苦，气平无毒。气薄味厚，阳中之阴也。入足厥阴，为活血凉血之药。凡热则生风，又血热则壅而发瘾疹。风为木化，风火相搏则为浮肿。苦平能凉血热，兼辛又能散风，故主血热生风之证。风火既散，则肌肉和而浮肿自消。齿痛亦因风热上攻，风势既散则痛亦止矣。\n\n【主治参与】\n《袖珍方》治便痈脓血：白胶香一两为末，入麝香、轻粉少许，掺之。\n\n《直指方》诸疮不合。白胶香、轻粉各二钱，猪脂和涂。\n\n《儒门事亲》一切恶疮，水沉金丝膏：用白胶香、沥青各一两，以麻油、黄蜡各二钱，同熔化，入冷水中扯千遍，摊贴之。\n\n《危氏得效方》年久牙疼：枫香脂为末，以香炉内灰和匀，每旦揩擦。\n\n枫香，近世为外科要药，除外科无别用，故不著 “简误”。', NULL, NULL, NULL, '白胶香,枫香脂', NULL, '18、白胶香,枫香脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067344, '5B49D7310615C8EA4DF4DCE1B95F4592', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7372, 418, 400106217, '       味辛、甘，平，无毒。主腰脊痛，补中益精气，坚筋骨，强志，除阴下痒湿，小便余沥，脚中酸痛不欲践地，久服轻身耐老。\n\n        疏：杜仲禀阳气之微，得金气之厚，故其味辛，气平无毒。《别录》加甘温。甄权言苦暖。应是辛甘胜而苦次之，温暖多而平为劣也。气薄味厚，阳中阴也。入足少阴，兼入足厥阴经。按《本经》所主腰脊痛，益精气，坚筋骨，脚中酸痛不欲践地者，盖腰为肾之府，《经》曰：动摇不能，肾将惫矣。又肾藏精而主骨，肝藏血而主筋，二经虚则腰脊痛而精气乏，筋骨软而脚不能践地也。五脏苦欲补泻云：肾苦燥，急食辛以润之，肝苦急，急食甘以缓之。杜仲辛甘俱足，正能解肝肾之所苦，而补其不足者也。强志者，肾藏志，益肾故也。除阴下痒湿，小便余沥者，祛肾家之湿热也。益肾补肝，则精血自足，故久服能轻身耐老。其主补中者，肝肾在下，脏中之阴也，阴足则中亦补矣。\n\n【主治参与】\n同牛膝、枸杞子、续断、白胶、地黄、五味子、菟丝子、黄檗、山药，治肾虚腰痛，及下部软弱无力。\n\n崔元亮《海上方》治肾虚腰痛：用杜仲去皮酥炙黄，一斤分作十剂，每夜取一剂，以水一升浸至五更，煎三分减一，取汁去滓，以羊肾三四枚切片放下，再煎三五沸，如作羹法，和以椒盐，空腹顿服。\n\n《得效方》治风冷伤肾，腰背虚痛：杜仲一斤切炒，酒二升，渍十日，日服三合。\n\n《肘后方》治病后虚汗，及目中流泪：杜仲、牡蛎等分，为末。卧时水服五匕，不止更服。\n\n《简便方》治频惯堕胎，或三四月即堕者：于两月前，以杜仲八两，糯米煎汤浸透炒，去丝，续断二两，酒浸焙干为末，以山药五六两为末作糊，丸梧子大。每服五十丸，空心米饮下。\n青娥丸。（见补骨脂条下。）\n\n【简误】\n      肾虚火炽者不宜用，即用当与黄檗、知母同入。', NULL, NULL, NULL, '杜仲', NULL, '17、杜仲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067345, '84489368A04EF4CCBC73F5D788F78C67', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7373, 418, 400106216, '      味苦、甘、平，无毒。主腰痛，小儿背强，痈肿，安胎，充肌肤，坚发齿，长须眉，主金疮，去痹，女子崩中，内伤不足，产后余疾，下乳汁。\n\n其实：主明目，轻身通神。\n\n       疏：桑寄生感桑之精气而生，其味苦甘，其气平和，不寒不热，固应无毒。详其主治，一本于桑，抽其精英，故功用比桑尤胜。腰痛及小儿背强，皆血不足之候。痈肿多由于荣气热。肌肤不充由于血虚。齿者骨之余也，发者血之余也，益血则发华，肾气足则齿坚而须眉长，血盛则胎自安。女子崩中及内伤不足，皆血虚内热之故。产后余疾，皆由血分，乳汁不下，亦由血虚。金疮则全伤于血。上来种种疾病，莫不悉由血虚有热所发，此药性能益血，故并主之也。兼能祛湿，故亦疗痹。\n\n实：味甘平，亦益血之药，故主治如经所云也。\n\n【主治参与】\n同枸杞子、地黄、胡麻、川续断、何首乌、当归、牛膝，治血虚手臂骨节疼痛。\n\n入独活寄生汤，疗一切风湿痹。\n\n《圣惠方》疗胎动腹痛：桑寄生一两五钱，阿胶炒五钱，艾叶五钱，水一盏半，煎一盏，去滓温服。或去艾叶，以其热也。\n', NULL, NULL, NULL, '桑寄生,桑上寄生', NULL, '16、桑寄生,桑上寄生', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067346, '20D9B9FA7E752716D867E1506D1AC46A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2025-01-14 16:09:58');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7374, 418, 400106215, '       味辛，温，无毒。主五藏身体寒热，风头脑痛，面䵟，温中解肌，利九窍，通鼻塞涕出，治肌肿引齿痛，眩冒，身兀兀如在车船上者。生须发，去白虫。久服下气，轻身明目，增年耐老。可作膏药。用之去心及外毛，毛射入肺令人咳。\n\n         疏：辛夷禀春阳之气以生，故其味辛气温，性无毒。气清而香，味薄而散，浮而升，阳也。入手太阴，足阳明经。其主五脏身体寒热，风头脑痛，面䵟，解肌，通鼻塞涕出，面肿引齿痛者，皆二经受风邪所致，足阳明主肌肉，手太阴主皮毛，风邪之中人，必自皮毛肌肉以达于五脏而变为寒热。又鼻为肺之窍，头为诸阳之首，三阳之脉会于头面，风客阳分则为头痛，面䵟，鼻塞涕出，面肿引齿痛。辛温能解肌散表，芳香能上窜头目，逐阳分之风邪，则诸证自愈矣。眩冒及身兀兀如在车船之上者，风主摇动之象故也。风邪散，中气温，则九窍通矣。大风之中人，则毛发脱落，风湿之浸淫则肠胃生虫，散风行湿则须发生而虫自去矣。久服下气，轻身明目，增年耐老，悉非风药所能。虽出自《神农本经》，然而易世相传，得无谬讹，存而不论可也。\n\n【主治参与】\n   同甘菊花、苍耳子、薄荷、细辛、甘草、羌活、藁本、防风、川芎，治风寒入脑头痛，或鼻塞流涕，或鼻渊涕下不止腥臭。\n\n【简误】\n辛香走窜之性，气虚人不宜服。虽偶感风寒，鼻窍不通，亦不得用。头脑痛属血虚火炽者，不宜用。齿痛属胃火者，不宜用。\n', NULL, NULL, NULL, '辛夷', NULL, '15、辛夷', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067347, '89A5E7581705A325596BAEF771CD1D72', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7375, 418, 400106214, '       味苦、辛，微寒、平、温，无毒。主筋骨间寒热，湿痹拘挛，明目坚齿，利九窍，去白虫、长虫，主风头痛，脑鸣，目泪出，益气。久服轻身耐老，令人光泽脂致。\n\n        疏：蔓荆实禀阳气以生，兼得金化而成。神农：味苦微寒，无毒。《别录》加辛平温。察其功用应是苦温辛散之性，而寒则甚少也。气清味薄，浮而升，阳也。入足太阳，足厥阴，兼入足阳明经。其主筋骨间寒热，湿痹拘挛，风头痛，脑鸣目泪出者，盖以六淫之邪，风则伤筋，寒则伤骨，而为寒热，甚则或成湿痹，或为拘挛。又足太阳之脉，夹脊循项而络于脑，目为厥阴开窍之位，邪伤二经，则头痛脑鸣目泪出，此药味辛气温，入二脏而散风寒湿之邪，则诸证悉除矣。邪去则九窍自通。痹散则光泽脂致。其主坚齿者，齿虽属肾而床属阳明，阳明客风热则上攻牙齿，为动摇肿痛，散阳明之风热，则齿自坚矣。去白虫、长虫者，假其苦辛之味耳。益气轻身耐老，必非风药所能也。\n\n【主治参与】\n同甘菊花、荆芥、酒炒黄芩、乌梅、芽茶、白蒺藜、川芎、羌活、黑豆、土茯苓，治偏头风痛，目将损者。\n\n【简误】\n        头目痛不因风邪，而由于血虚有火者忌之。元素云：胃虚人不可服，恐生痰疾。', NULL, NULL, NULL, '蔓荆实', NULL, '14、蔓荆实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067348, 'EE52A133A4BF6B13F012CCC8E3D9B6B9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7376, 418, 400106213, '     味苦，温，无毒。主除骨间寒热，通利胃气，止咳逆下气。（得术、柏实、青葙，共疗头风。防风为之使。）\n\n      疏：牡荆实感仲夏之气以生，故其味苦气温无毒。可升可降，阳也。入足阳明、厥阴经。其主骨间寒热，通利胃气，止咳逆下气者，盖足阳明为十二经脉之长，厥阴为风木之位，外邪伤于二经，则寒热留连于筋骨，而胃气壅滞，苦温能通行散邪，则胃气利而寒热自除。咳逆亦邪气壅胃所致，邪散气下则咳逆自止矣。\n\n【主治参与】\n《外台秘要》头风痛：取荆沥不拘多少服，日日服之。\n\n朱震亨治心痛及妇人白带：用牡荆实炒焦，为末，饮服。入折伤药，能散瘀血，和筋骨。\n\n【简误】\n      病非干外邪者，一概不宜用。', NULL, NULL, NULL, '牡荆实', NULL, '13、牡荆实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067349, '7247F49C14649539D88080DA2EB3B5CA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7377, 418, 400106212, '      味辛，温，微寒，无毒。主心腹疝气腹痛，益气疗躄，小儿不能行，疽疮阴蚀，男子阴痿囊下湿，小便余沥，女人阴痒，及腰脊痛，两脚疼痹风弱，五缓虚羸，补中益精，坚筋骨，强志意。久服轻身耐老。\n\n        疏：五加皮在天得少阳之气，为五车星之精，在地得火金之味，故其味辛，其气温，而其性无毒。\n\n      《别录》加苦，微寒。气味俱厚，沉而阴也。入足少阴、足厥阴经。观《本经》所主诸证，皆因风寒湿邪伤于二经之故，而湿气尤为最也。其治疝气腹痛，疗躄，小儿不能行，阴蚀疽疮，男子阴痿囊下湿，小便余沥，女人阴痒，脊痛两脚疼痹风弱者何？莫非二经受风寒湿邪所致，《经》云：伤于湿者，下先受之。又云：地之湿气，感则害人皮肉筋脉。肝肾居下而主筋骨，故风寒湿之邪多自二经先受。此药辛能散风，温能除寒，苦能燥湿，二脏得其气而诸证悉瘳矣。又湿气浸淫则五脏筋脉缓纵，湿气留中则虚羸气乏，湿邪既去则中焦治而筋骨自坚，气日益而中自补也。其主益精强志者，肾藏精与志也。轻身者，除风湿之效也。耐老者，补肝肾之功也。昔人云：宁得一把五加，不用金银满车。宁得一斤地榆，安用明月宝珠。又昔鲁定公母，单服五加酒，以致不死。又东华真人煮石法，用玉豉、金盐。玉鼓，地榆也。金盐，五加也。世为仙经所颂。其能轻身耐老，又可知矣。\n\n【主治参与】\n得牛膝、木瓜、黄檗、麦门冬、生地黄、薏苡仁、石斛、虎胫骨、山药，治湿热痿痹，腰以下不能行动。\n\n同续断、杜仲、牛膝、山茱萸、巴戟天、破故纸，治肾虚寒湿客之作腰痛。\n\n同二术、萆薢、石菖蒲、薏苡仁、白蒺藜、甘菊花、防风、羌活、独活、白鲜皮，石斛，治风寒湿成痹。\n\n同石菖蒲、连翘、苍术、黄檗、黄耆、薏苡仁、金银花、鳖虱胡麻、木瓜、土茯苓，治下部湿疮久不愈。兼治脓窠疮如神。\n\n同黄檗末、菖蒲末、蛇床子，俱为细末，傅囊湿神效。如欲作汤沐，加荆芥、苦参、防风。\n\n一味酿酒饮之，治风痹四肢拘挛。\n\n《全幼心鉴》治小儿三岁不能行，用此便走：五加皮五钱，牛膝、木瓜各二钱半，为末。每服五分，米饮入酒二三滴，调服。\n\n【简误】\n       下部无风寒湿邪而有火者，不宜用。肝肾虚而有火者，亦忌之。', NULL, NULL, NULL, '五加皮', NULL, '12、五加皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627173885067350, '3F04D8416B391C17BC4994B4961485F6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 15:17:06', 1, 'admin', '2024-12-27 15:17:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7378, 419, 400106335, '     味苦，平、微寒，无毒。主青盲，浮翳赤涩多眵泪，消目中赤脉，小儿麸豆，及疳气攻眼。\n\n      疏：蜜蒙花禀土气以生，其蕊萌于冬而开于春，故气平微寒，味甘而无毒，为厥阴肝家正药。观本经所主，无非肝虚有热所致。盖肝开窍于目，目得血而能视，肝血虚则为青盲、肤翳，肝热甚则为赤肿眵泪赤脉，及小儿豆疮余毒，疳气攻眼。此药甘以补血，寒以除热，肝血足而诸证无不愈矣。好古谓其润肝燥，守真以之治畏日羞明，诚谓此也。形与芫花相似。但芫花狭小而蜜蒙花差大为异，用者宜详辨之。\n\n【主治参与】\n同空青、木贼、生地黄、蝉蜕、白蒺藜、谷精草、决明子、羚羊角，治青盲翳障。\n\n同甘菊花、枸杞子、生地黄、白蒺藜、谷精草，治肝肾虚，目不能远视。\n\n同黄连、赤芍药、防风、荆芥穗、黄檗、甘菊花、甘草、龙胆草，治风热湿热眼赤痛。同胡黄连、白芜荑、使君子、蝉蜕、木贼、芦会，治小儿疳积，眼目不明。\n\n疗眼疾外无他用，故不著 “简误”。', NULL, NULL, NULL, '蜜蒙花', NULL, '35、蜜蒙花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457030, '64C5A8EDBEBDE38FEAB3CFE2FC0B664E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7379, 419, 400106334, '     味苦，寒，无毒。主小儿惊风天吊，镇心，明目，去诸风热，疗金疮，止血，滋养五藏。\n\n      疏：天竺黄，竹之津气结成。其气味功用，与竹沥大同小异。第竹黄气微寒而性亦稍缓，故为小儿家要药。入手少阴经。小儿惊风天吊，诸风热者，亦犹大人热极生风之候也。此药能除热养心，豁痰利窍，心家热清而惊自平，主君安而五脏咸得滋养，故诸证悉除也。明目疗金疮者，总取其甘寒凉血清热之功耳。\n\n【主治参与】\n同牛黄、犀角、丹砂、茯神、琥珀、酸枣仁、远志、钓藤钩，治小儿惊痫癫疾。有痰者加牛胆南星、贝母、竹沥。属虚者去南星，加人参。\n\n钱乙方：小儿惊热：天竺黄二钱，雄黄、牵牛末各一钱，研匀，面糊丸粟米大，每服三五丸，薄荷汤下。\n\n除小儿惊痫痰热外，无别用，故不著 “简误”。', NULL, NULL, NULL, '天竺黄', NULL, '34、天竺黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457031, 'D886E04BB6195341DA9892617631F6D3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7380, 419, 400106333, '      味苦、酸，平，无毒。疗齿宣疳䘌，肺藏风毒流溢皮肤，作风湿癣疮，瘙痒脓水，五痔下血不止，小儿面鼻疳疮。\n\n       疏：五倍子得木气而兼金水之性，其味苦酸涩，气平无毒。气薄味厚，敛也，阴也。入手太阴、足阳明经。本经主齿宣疳䘌，风湿癣疮，及小儿面鼻疳疮者，皆从外治，取其苦能杀虫，酸平能敛浮热，性燥能主风湿疮痒脓水。五痔下血者，大肠积热也，大肠与肺为表里，肺得敛肃则大肠亦自清宁也。藏器：疗肠虚泄利。日华子：主生津液，消酒毒。时珍谓其敛肺降火，化痰饮，止咳嗽，消渴，盗汗，敛溃疮，金疮，收脱肛，子肠坠下者，悉假其入肺清金，收敛固脱之功耳。\n\n【主治参与】\n同地骨皮、小蓟、皮硝、甘草、苦参、葱头，煎汤洗杨梅结毒。\n\n《集灵方》自汗、盗汗：用五倍子研末，津调填脐中，缚定，一夜即止。\n\n化痰生津，噙化丸：用五倍子安大钵头内，用煮糯米粥汤浸，盖好安静处，七日后常看，待发芽黄金色，又出黑毛，然后将箸试之，若透内无硬，即收入细瓦钵中。擂如酱，连钵日中晒至上皮干了。又擂匀，又晒，晒至可丸，方丸弹子大，晒干收用。其味甘酸，能化一切胶痰。\n\n又方，脾泄久利：五倍子炒半斤，除仓米炒一升，丁香、细辛、木香各三钱，川椒五钱，为末，每服一钱，蜜汤下，日二服。忌生冷鱼肉。\n\n《和剂局方》玉锁丹：治肾经虚损，心气不足，思虑太过，真阳不固，溺有余沥，小便白浊如膏，梦中频遗，盗汗虚烦，食减乏力。此方性温不热，极有神效。五倍子一斤，白茯苓四两，龙骨二两，为末，水糊丸梧子大。每服七十丸，食前盐汤送下，日三服。\n\n《百一选方》脏毒下血：五倍子不拘多少为末，大鲫鱼一枚，去肠胃鳞鳃，填药令满，入瓶内煅存性，为末。每服一钱，温酒下。\n\n《直指方》大肠痔疾：五倍子煎汤熏洗，或烧烟熏之，自然收缩。\n\n《三因方》脱肛不收：用五倍子末三钱，入白矾少许，水一碗，煎汤洗之，立效。\n\n《妇人良方》产后肠脱：五倍子末掺之。\n\n《博济方》风毒攻眼，肿痒涩痛不可忍者，或上下睑赤烂，或浮翳瘀肉侵睛。神效驱风散：五倍子一两，蔓荆子一两半，为末，每用二钱，水二盏。铜石器内煎汁，去滓，乘热洗。大能明目去涩。\n\n杨子建《护命方》牙龈肿痛：五倍子两许，瓦焙，研末，以半钱傅痛处，片时唾去涎。内服去风热药。\n\n《端效方》白口恶疮，状如木耳。不拘大人小儿，并用五倍子、青黛等分为末，以筒吹之。\n\n《儒门事亲》赴筵散：治口舌生疮。五倍子、蜜陀僧等分，为末。将水漱过，干贴之。《院方》加晚蚕蛾\n\n《杏林摘要》鱼口疮毒，初起未成脓者，用五倍子炒黄研，入百草霜等分，以腊醋调涂患处，一日一夜即消。\n\n《拔萃方》一切金疮：五倍子、降真香等分，炒，研末。傅之，皮肉自痊。\n\n【简误】\n       五倍子，性燥急而专收敛，咳嗽由于风寒外触者忌之。泻痢非肠虚脱者忌之。咳嗽由于肺火实甚者忌之。若误服之，反致壅塞喘满，以其酸敛太骤，火气无从泄越故耳。', NULL, NULL, NULL, '五倍子', NULL, '33、五倍子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457032, 'CA74FF712535794A5B3B46FE62F30AE3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7381, 419, 400106332, '     味甘，平，无毒。主安五藏，利心志，令人欢乐无忧，久服轻身，明目，得所欲。\n\n      疏：合欢禀土气以生，故味甘气平无毒。入手少阴、足太阴经。土为万物之母，主养五脏，心为君主之官，本自调和。脾虚则五脏不安，心气躁急则遇事拂郁多忧。甘主益脾，脾实则五脏自安；甘可以缓，心气舒缓则神明自畅而欢乐无忧，神明畅达则觉照圆通，所欲咸遂矣。嵇叔夜《养生论》云：合欢蠲忿，正此之谓欤。其主轻身明目，及大明主消痈疽，续筋骨者，皆取其能补心脾，生血脉之功耳。\n\n【主治参与】\n与白蜡同入膏，能长肌肉，续筋骨，甚捷。\n\n《独行方》肺痈唾浊，心胸甲错：取夜合皮一掌大，水三升，煎取一半，分二服。\n\n《百一选方》扑损折骨：夜合树皮，去粗皮，炒黑色四两。芥菜子炒一两，为末。每服二钱，温酒卧时服，以滓外傅，接骨神妙。\n\n子，合橘核、木瓜、牛膝，能治疝。湿热者为黄檗，寒湿者加茴香子。\n\n气味和平，与病无忤，故不著 “简误”。', NULL, NULL, NULL, '合欢', NULL, '32、合欢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457033, 'D1162237A9FDA0A8DD6F1B21257FAD2B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7382, 419, 400106331, '    微温，无毒。主冷热气攻心腹，大肠壅毒，痰膈醋心。并以姜、盐同煎，入疏气药良。\n\n      疏：大腹皮，即槟榔皮也。其气味所主，与槟榔大略相同。第槟榔性烈，破气最捷，腹皮性缓，下气稍迟。入足阳明、太阴经。二经虚则寒热不调，逆气攻走，或痰滞中焦，结成膈证，或湿热郁积，酸味醋心。辛温暖胃，豁痰通行下气，则诸证除矣。大肠壅毒，以其辛散破气而走阳明。故亦主之也。\n\n【主治参与】\n    同白术、茯苓、车前子、木瓜、桑白皮、五加皮、猪苓、泽泻、薏苡仁、蠡鱼，治水肿有效，虚者加人参。\n\n【简误】\n鸩鸟多集槟榔树上，凡用槟榔皮，宜先洗去黑水，复以酒洗，后以大豆汁再洗过，晒干，入灰火煨用。性与槟榔相似，病涉虚弱者，概勿使用。', NULL, NULL, NULL, '大腹,大腹皮', NULL, '31、大腹,大腹皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457034, '0A9EBD9F841FAA6B3C9B5F39DBE9B9C5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', 1, 'admin', '2025-01-14 16:00:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7383, 419, 400106330, '       味苦，平，无毒。主霍乱，中恶，赤白久痢。除疽䘌疥癣，牙齿虫痛，并煮服及含之。水浸洗目除浮赤。\n\n        疏：海桐皮禀木中之阴气以生，本经味苦气平无毒。然详其用，味应带辛。气薄味厚，阴中阳也。入足太阴、阳明经。二经虚则外邪易入，为霍乱中恶，辛以散之。湿热内侵为疳䘌，久痢，苦以泄之。又脾胃主肌肉，湿热浸淫则生虫而为疥癣，苦能杀虫，平即微寒，湿热去而疥癣除矣。其主漱齿洗目者，亦取其寒杀虫，辛平散风热之意耳。李珣以之治腰脚不遂，血脉顽痹，腿膝疼痛之证，其为辛苦之剂无疑矣。\n\n【主治参与】\n         《续传信方》治腰膝痛不可忍：用海桐皮二两，牛膝、芎穷、羌活、地骨皮、五加皮各一两，甘草半两，薏苡仁二两，生地黄十两，浸洗焙干剉细，以绵包裹，入无灰酒二斗浸之，冬二七日，夏一七日，空心饮一盏，每日早、午、晚各饮一盏，长令醺醺。合时不得添减，禁毒食。此药治因风湿、湿热流注下焦腰膝为病，若因阴虚血少火炽而得者勿服。同真川槿皮、轻粉、蛇床子、山大黄，为末，傅癣疮。\n\n【简误】\n腰痛，非风湿者不宜用。', NULL, NULL, NULL, '海桐皮', NULL, '30、海桐皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457035, '3B90843533744B9B279CD9D750AAEC1B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7384, 419, 400106329, '   味咸，平（一云冷），无毒。主哕气呕逆，辟痁，小儿吐乳，大人吐食，并水煮服。小儿惊痫及夜啼，安身伴睡良。又主痔病，烧为末，服方寸匕。\n\n    疏：仙人杖，此笋之将成竹时立死者。得笋之气已过，禀竹之性未全。故味咸气平无毒。其功用在竹茹、竹黄之间。所主哕气呕逆，小儿吐乳，辟痁，大人吐食，痔疮者，竹茹之用也。疗小儿惊痫，及夜啼者，竹黄之用也。虽其形已痿，而其性尚存，故能疗诸证也。又秘方：用此蘸麻油于空室中燃之，取滴下油涂痈疽已溃，长肉如神。\n他用甚稀，故无 “主治”、“简误”。', NULL, NULL, NULL, '仙人杖', NULL, '29、仙人杖', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457036, '9E3C781E20FAD19222489F1D9EC9A1D2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7385, 419, 400106328, '     味辛、苦，平，无毒。主心腹恶气，鬼疰。\n\n      疏：安息香禀火金之气而有水，故味辛苦，气平而芳香，性无毒。气厚味薄，阳也。入手少阴经。少阴主藏神，神昏则邪恶鬼气易侵，芳香通神明而辟诸邪，故能主鬼疰恶气也。\n\n【主治参与】\n同鬼臼、犀角、牛黄、丹砂、乳香、苏合香、龙齿、雄黄、麝香，治鬼疰尸疰，杀痨虫，寐魇暴亡，及大人小儿卒中邪恶气。\n\n《奇效良方》小儿惊邪：安息香一豆许，烧之自除。\n\n【简误】\n      病非关邪恶气侵犯者，不宜服。', NULL, NULL, NULL, '安息香', NULL, '28、安息香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457037, 'FB22127A2D39337814838B2384E36DC8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7386, 419, 400106327, '       味苦，平，无毒。主破血止痛，疗金疮，杖疮，诸恶疮，痔漏，卒下血，目中翳晕痛肤赤。\n\n       疏：没药禀金水之气以生，故味苦平无毒。然平应作辛，气应微寒。气薄味厚，阴也，降也。入足厥阴经。凡恶疮痔漏，皆因血热瘀滞而成。外受金刃及杖伤作疮，亦皆血肉受病，血肉伤则瘀而发热作痛。此药苦能泄，辛能散，寒能除热。水属阴，血亦属阴，以类相从，故能入血分散瘀血，治血热诸疮，及卒然下血证也。肝开窍于目，目得血而能视，肝经血热则目为赤痛浮翳，散肝经之血热则目病除矣。\n\n【主治参与】\n同延胡索、乳香、干漆、鳖甲、琥珀为末，治产后血晕，有神效。\n\n加人参、泽兰、生地、益母草、苏木，作汤送前药。治儿枕痛，及恶露未净，腹痛寒热等证，立效。\n\n同乳香、白及、白敛、紫花地丁、半枝莲、夏枯草、忍冬藤、连翘、甘菊、贝母，治一切痈疽疔肿。\n\n同乳香、当归、牡丹皮、牛膝、续断、川芎、番降香、穿山甲，治内伤胸胁骨痛。\n\n入一切膏药，能消毒止痛长肉。\n\n《御药院方》筋骨损伤：米粉四两炒黄，入没药、乳香末各半两，酒调成膏，摊贴之。\n\n《奇效良方》金刃所伤未透膜者：乳香、没药各一钱，以童子小便半盏，酒半盏，温化服之。\n\n《图经本草》妇人腹痛内伤㽲刺：没药末一钱，酒服便止。又治妇人血晕，方同。\n\n《妇人良方》产后恶血：没药、血竭末各一钱，童便、温酒各半盏，煎沸服，良。\n\n《危氏得效方》女人异疾，月事退出，皆作禽兽之形，欲来伤人：先将绵塞阴户，乃顿服没药末一两，白汤调下，即愈。\n\n【简误】\n        孕妇不宜服。凡骨节痛，与夫胸腹胁肋痛，非瘀血停留，而因于血虚者不宜用。产后恶露去多，腹中虚痛者不宜用。痈疽已溃不宜用。目赤浮翳，非血热甚者不宜用。大概其功长于通滞血，血滞则气亦壅，气血壅滞则经络满急，经络满急故发肿作痛，打扑踠跌亦伤经络血分，血气不行故壅滞作肿痛也。没药善通壅滞之血，血行则气亦行，气血流通则肿痛自止矣。故为诸疮痈，及金疮、杖疮、跌扑伤损、腹中血结作痛之要药，而不主诸虚也。', NULL, NULL, NULL, '没药', NULL, '27、没药', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457038, '1E6BBD34DDC46107C627FD669B46D85A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7387, 419, 400106326, '       味辛，温，无毒。主中恶心腹痛，蛊毒疰忤鬼气，宿食不消，天行疫瘴，膀胱肾间冷气攻冲背膂，妇人血气，小儿腹中诸虫。\n\n        疏：乌药禀地之二气以生，故味辛气温无毒。然尝其味，亦带微苦，气亦微香。气厚于味，阳也。入足阳明、少阴经。其主中恶心腹痛，疰忤鬼气，天行疫瘴者，皆足阳明受病。阳明开窍于口鼻。凡邪恶鬼忤，与夫疫瘴之气侵人，悉从口鼻而入。此药辛温暖胃，辟恶散邪，故能主诸证也。胃暖则宿食自消，辛散则蛊毒亦解。又肾与膀胱为表里，虚则寒客之而冷气攻冲背膂，辛温能散寒邪，其性又善下走，则冷气攻冲自止也。性温走泄，故复能散妇人血凝气滞，微苦而辛，故又能疗小儿腹中诸虫也。\n\n【主治参与】\n同沉香、木香、白豆蔻、香附、橘皮、槟榔，治妇人气实，暴气壅胀。\n\n《济生方》治七情郁结，上气喘急：用四磨汤降中兼升，泻中带补。其方以人参、乌药、沉香、槟榔，各磨浓汁七分，煎，细细咽之。\n\n《和剂局方》乌沉汤，治一切气，一切冷，补五脏，调中壮阳，暖腰膝，去邪气，冷风麻痹，膀胱、肾间冷气攻冲背膂，俯仰不利，风水毒肿，吐泻转筋，癥癖刺痛，中恶心腹痛，鬼气疰忤，天行疫瘴，妇人血气痛：用天台乌药一百两，沉香五十两，人参三两，炙甘草四两，为末。每服半钱，姜盐汤空心点服。\n\n【简误】\n         乌药辛温散气，病属气虚者忌之。世人多以香附同用，治女人一切气病，不知气有虚有实，有寒有热。冷气暴气用之固宜，气虚气热用之能无贻害耶？以故妇人月事先期，小便短赤，及咳嗽内热，口渴口干舌苦，不得眠，一切阴虚内热之病，皆不宜服。', NULL, NULL, NULL, '乌药', NULL, '26、乌药', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457039, 'E3956E4EDE49A956CFCEF80309F05FA8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7388, 419, 400106325, '      味甘、苦，平，无毒。主痎疟，解毒蛊疰不祥，利水道。久服轻身耐老。\n\n       疏：猪苓禀戊土之阳气，得风木之阴气，《本经》谓其味甘，应兼淡苦，其气平而无毒。气味俱薄，降也，阳中阴也。入足太阳、足少阴经。其主痎疟者，疟必由暑，暑必兼湿，淡以利窍，引暑湿之气从小便出，所以分消之也。淡渗之性，故利水道。湿胜则身重，湿去则身轻。利窍之药，必能走泄精气，其曰久服耐老，必无是理矣。解蛊毒疰不祥，义将安出？亦未可尽信也。\n\n【主治参与】\n入五苓散，为除湿之要药。\n\n佐白芍药、白茯苓、人参、橘皮、术、泽泻，治水肿之属阳分者。\n\n佐白芍药、生地黄、桑寄生、桑根白皮、茯苓、泽泻、琥珀、石斛、薏苡仁、肉桂，治水肿之属阴分者，均为要药。其功长于利水，故善除湿。\n\n【简误】\n       寇宗奭曰：猪苓利水之功多，久服必损肾气，昏人目。洁古曰：淡渗太燥，能亡津液，无湿证勿服。皆确论也。有湿尚宜暂用，久服断乎不可。', NULL, NULL, NULL, '猪苓', NULL, '25、猪苓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457040, '4B4788B68D71B0E63535022E98D10867', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7389, 419, 400106324, '     味咸、苦，大寒，无毒。主大毒热，心腹烦满，水和服之取吐。又主牛马急黄黑汗，水研三二两灌之，立瘥。\n\n      疏：胡桐泪禀地中至阴之气，而兼水化，故味咸苦，气大寒，无毒。气味俱厚，阴中之阴也。入足阳明经。《经》曰：热淫于内，治以咸寒。又曰：在高者，因而越之。苦以涌吐，寒以胜热，故主大毒热，心腹烦满，取吐而效也。牛马性热而又犯热病，所以急黄黑汗也，咸寒能除大热，故亦主之。日华子以之治风虫牙齿痛。李珣谓其能治骨槽风，齿䘌。元素言瘰疬非此不能除。皆资其苦能杀虫，咸能入骨软坚，大寒能除极热之用耳。\n\n【主治参与】\n《圣惠方》牙疼出血：胡桐泪半两，研，入麝香少许，夜夜贴之。\n\n又方，牙疳宣露，脓血臭气者：胡桐泪一两，枸杞根一升。每用五钱，煎水热漱。\n\n《圣济总录》牙齿蠹黑，乃肾虚也。胡桐泪一两，丹砂半两，麝香一分，为末掺之。\n\n除口齿药外，他用甚稀，故不著 “简误”。', NULL, NULL, NULL, '胡桐泪', NULL, '24、胡桐泪', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457041, '43D3ABBC0A2BCED695C3E50555474E2C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7390, 419, 400106323, '      味酸，微寒，无毒。主妇人产乳余疾，崩中，癥瘕，血闭寒热羸瘦，养胎。\n\n      疏：紫葳，即凌霄花也。禀春气以生，故其味酸，气微寒，无毒。花开于夏而色赤，味应带苦，入肝行血之峻药。故主妇人产乳余疾，及崩中，癥瘕，血闭寒热羸瘦诸证。至于养胎，决非其性所宜，用者慎之！\n\n【主治参与】\n同当归、红花、川芎、牛膝、地黄、延胡索、桃仁、苏方木、五灵脂，治壮实妇人经闭。\n\n《普济方》婴儿百日内无故口青不饮乳：同凌霄花、大蓝叶、芒硝、大黄，等分为末，以羊髓和丸梧子大。每研一丸，乳送下，便能吃乳。热者可服，寒者忌之。\n\n【简误】\n        紫葳长于破血消瘀。凡妇人血气虚者，一概勿施。胎前断不宜用。', NULL, NULL, NULL, '紫葳', NULL, '23、紫葳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457042, 'FCE1A35907332CE06717AA96C7721AD9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7391, 419, 400106322, '        味酸，平、微温，无毒。主心下邪气寒热，温中，逐寒湿痹，去三虫，肠胃风邪寒热，疝瘕，头风风气去来，鼻塞，目黄，耳聋，面皰，温中下气，出汗，强阴益精，安五藏，通九窍，止小便利。久服轻身，明目，强力长年。\n\n        疏：山茱萸感天地春生之气，兼得木之酸味，神农气平。《别录》微温。总言其得春气之正耳。岐伯、甄权加辛。然尝其味，必是酸多辛少。入足厥阴、足少阴经。阳中之阴，降也。其治心下邪气寒热，肠胃风邪寒热，头风风气去来，鼻塞，面皰者，皆肝肾二经所主，二经虚热，故见前证。肝为风木之位，《经》曰：诸风掉眩，属肝木。此药温能通行，辛能走散，酸能入肝而敛虚热，风邪消散则心下肠胃寒热自除，头目亦清利，而鼻塞、面皰悉愈也。逐寒湿痹者，《经》曰：邪之所凑，其气必虚。总藉其辛温散结，行而能补也。至于三虫。亦肠胃湿热所生，湿去则虫自除。能温中则气自下，汗自出矣。凡四时之令，春气暖而生，秋气凉而杀，万物之性，喜温而恶寒，人身精气亦赖温暖而后充足。况肝肾在下，居至阴之位，非得温暖之气则孤阴无以生。此药正入二经，气温而主补，味酸而主敛，故精气益而阴强也。精益则五脏自安，九窍自利。又肾与膀胱为表里，膀胱虚寒，则小便不禁；耳为肾之外窍，肾虚则耳聋。肝开窍于目，肝虚则邪热客之而目黄。二经受寒邪则为疝瘕，二脏得补则诸证无不瘳矣。轻身强力长年者，益精安五脏之验也。\n\n【主治参与】\n同菟丝子、肉苁蓉、巴戟天、鹿茸、牛膝、白胶、车前子、枸杞子、生地黄、沙苑蒺藜、麦门冬，能添精固髓，暖腰膝，益阳道，令人有子。\n\n同人参、五味子、牡蛎、益智子，治老人小便淋沥及遗尿。\n\n同人乳、沙苑蒺藜、熟地黄、人参、麦门冬、牛膝、甘菊花，治脑骨痛。脑为髓之海，髓足则脑痛自除。\n\n同石菖蒲、甘菊花、地黄、黄檗、五味子，治肾虚耳聋。\n\n同杜仲、牛膝、地黄、白胶、山药，治肾虚腰痛。\n\n入六味地黄丸，为肾虚而有湿热者所须。\n\n【简误】\n      命门火炽，强阳不痿者忌之。膀胱热结，小便不利者，法当清利，此药味酸主敛，不宜用。阴虚血热不宜用，即用当与黄檗同加。', NULL, NULL, NULL, '山茱萸', NULL, '22、山茱萸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457043, 'E7DCC52B19643A26B81772EDC4E74D67', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7392, 419, 400106321, '      茗味甘，苦，微寒，无毒。主瘘疮，利小便，去痰热渴，令人少睡。\n\n      苦（木荼）：主下气消食。\n\n      疏：茗禀土中之清气，兼得春初生发之意，本经味甘，气微寒，无毒。藏器言苦。然亦有不苦者。气薄味厚，阴中微阳，降也。入手太阴、少阴经。太阴为清肃之脏，喜凉而恶热，热则生痰而津液竭，故作渴也。瘘疮者，大肠积热也。小便不利者，小肠热结也。甘寒入心肺而除热则津液生，痰热解，脏气既清，腑病不求其止而止矣。令人少睡者，盖心藏神，神昏则多睡，清心经之热，则神常自惺寂，故不寐也。下气消食者，苦能下泄，故气下火降而兼涤除肠胃，则食自消矣。\n\n【主治参与】\n同黄连、酸枣仁生用、通草、莲实，治多睡好眠。\n\n同当归、川芎、乌梅、黑豆、生地黄、土茯苓、甘菊花，治头痛因于血虚有火者。\n\n《直指方》热毒下痢：蜡茶为末，蜜水煎服，白痢以姜汁同水煎服。两三服即愈。\n\n【简误】\n       凡茶之种类极多，方宜大异，要皆以味甘不涩，气芬如兰，摘于夏前者为良。夫茶禀天地至清之气，生于山谷硗瘠砂土之中，不受纤芥秽滓，专感云露之气以为滋培，故能涤肠胃一切垢腻，宁非木中清贵之品哉！昔人多以其苦寒不利脾胃，及多食发黄消瘦之说，此皆语其粗恶苦涩，品质最下者言之耳。昔雅州蒙山出一种茶，服四两即为地仙，岂有味甘气芬者，饮之反致疾耶？但苦涩野气，叶痿茎枯，非道地所产者，服之不利心脾，故不宜饮。酒后不宜用，能成饮证。', NULL, NULL, NULL, '茗苦苦，木荼', NULL, '21、茗苦苦，木荼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457044, '7DDBD698068878AA88060BB0AB697487', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7393, 419, 400106320, '       味苦，温、大温，无毒。主中风伤寒，头痛寒热惊悸，气血痹，死肌，去三虫，温中益气，消痰下气，疗霍乱，及腹痛胀满，胃中冷逆，胸中呕不止，泄痢，淋露，除惊，去留热，心烦满，厚肠胃。\n\n        疏：厚朴禀地二之气以生，兼得乎春阳之气而成，故其味苦，其气温。甄权苦辛大热。应是辛热苦温之药。辛热太过，则其性宜有毒，以其得阳气之正，故无毒耳。气味俱厚，阳中之阴，降也。入足太阴、手足阳明经。其主中风伤寒，头痛寒热，气血痹，死肌者，盖以风寒外邪伤于阳分，则为寒热头痛。风寒湿入腠理，则气血凝涩而成痹，甚则肌肉不仁。此药辛能散结，苦能燥湿，温热能祛风寒，故悉主之也。\n\n     《别录》又主温中，消痰，下气，疗霍乱及腹痛胀满，胃中冷逆，胸中呕不止，泄痢，心烦满者何？莫非肠胃气逆壅滞，及痰饮留结，饮食生冷所致。得引下泄开通，温热暖胃，则诸证不求其止而止矣。至于淋露，虽属下焦为病，然多因胃家湿热下流，三虫亦肠胃湿热所生，苦能燥湿杀虫，故亦主之也。\n\n     《本经》又主惊悸，及《别录》除惊去留热者，皆非其所宜。惊悸属心虚，于脾胃绝无相干。气味大温之药，又岂能去留热哉？至益气，厚肠胃，盖亦指邪气去，正气自益之谓，积滞消，肠胃自厚之意耳。非消散之外，复有补益之功也。用者详之。\n\n【主治参与】\n同陈皮、枳壳、麦蘖、草果、山查、砂仁、矾红，治伤食腹胀。\n\n同橘皮、黄连、甘草、苍白术、葛根，治湿热作泻。\n\n同槟榔、木香、黄连、滑石、橘皮、甘草、白芍药，治滞下初起。\n\n同白术、人参、白芍药、茯苓，消腹胀。\n\n佐生姜、橘皮、藿香、砂仁、半夏，止胃寒呕吐。\n\n同三棱、蓬荗、槟榔、人参、青皮，治积年冷癖坚块。\n\n同苍术、橘皮、甘草，为平胃散，治胸中敦厚之气，使饮食倍增。\n\n《圣惠方》治痰壅呕逆，心胸满闷，不下饮食：用厚朴一两，姜汁炙黄为末。米饮调下二钱匕。\n\n张仲景《金匮》方治腹胀脉数，厚朴三物汤：用厚朴半斤，枳实五枚，以水一斗二升，煎取五升，入大黄四两，再煎取三升，温服一升。转动更服，不动勿服。\n\n又，七物厚朴汤，治腹痛胀满：用厚朴半斤，甘草、大黄各三两，枣十枚，枳实五枚，桂二两，生姜五两，以水一斗，煎取四升，温服八合，日三。呕者加半夏五合。\n\n【简误】\n        厚朴气味辛温，性复大热，其功长于泄结散满，温暖脾胃。一切饮食停积，气壅暴胀，与夫冷气逆气，积年冷气入腹，肠鸣虚吼，痰饮吐沫，胃冷呕逆，腹痛泄泻，及脾胃壮实之人偶感风寒，气实人误服参耆致成喘胀，诚为要药。然而性专消导，散而不收，略无补益之功。故凡呕吐不因寒痰冷积，而由于胃虚火气炎上；腹痛因于血虚脾阴不足，而非停滞所致；泄泻因于火热暴注，而非积寒伤冷；腹满因于中气不足，气不归元，而非气实壅滞；中风由于阴虚火炎，猝致僵仆，而非西北真中寒邪；伤寒发热头疼而无痞塞胀满之候；小儿吐泻乳食，将成为慢惊；大人气虚血槁见发膈证；老人脾虚不能运化，偶有停积；娠妇恶阻，水谷不入；娠妇胎升眩晕，娠妇伤食停冷，娠妇腹痛泻痢，娠妇伤寒伤风，产后血虚腹痛，产后中满作喘，产后泄泻反胃，以上诸证，法所咸忌。若误投之，轻病变重，重病必危。世人不究其原，一概滥用，虽或一时未见其害，而清纯冲和之气，默为之耗矣。可不慎哉！\n', NULL, NULL, NULL, '厚朴', NULL, '20、厚朴', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457045, '8B490A89EFEFCACC80CD23827927A274', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7394, 419, 400106319, '      味苦、酸，寒、微寒，无毒。主大风在皮肤中，如麻豆苦痒，除寒热结，止痢，长肌肉，利五藏，益气轻身，除胸胁痰癖，逐停水，破结实，消胀满，心下急痞痛，逆气胁风痛，安胃气，止溏泄，明目。\n\n       疏：枳实感天地苦寒之气以生，故其味苦，气寒无毒。\n   \n     《别录》、雷公加酸，甄权加辛。察其功用，必是苦为最，而酸辛次之。气味俱厚，阴也。入足阳明太阴经。细详神农主治，与本药气味大不相侔，究其所因，必是枳壳所主。盖二物古文原同一条，后人分出时误入耳。其《别录》所主除胸胁痰癖，逐停水，破结实，消胀满，心下急痞痛，逆气胁风痛，安胃气，止泄泻者，是其本分内事，皆足阳明、太阴受病。二经气滞则不能运化精微，而痰癖、停水、结实、胀满所自来矣。胃之上口名曰贲门，贲门与心相连，胃气壅则心下亦自急痞痛，邪塞中焦，则升降不舒而气上逆。肝木郁于地下，则不能条达而胁痛，得其破散冲走之力，则诸证悉除。所以仲景下伤寒腹胀实结者，有承气汤。胸中痞痛者，有陷胸汤。洁古疗心下痞满者，有枳术丸。壅滞既去，则胃气自安，而溏泄亦止矣。末云明目者，《经》曰：目得血而能视。气旺乃能生血，损气破散之性岂能明目哉？无是理也！\n\n【主治参与】\n同三棱、蓬荗、青皮、槟榔，为消磨坚积之剂，然须能食、脾胃健者宜之。\n\n同白术、橘皮、厚朴、甘草、砂仁为枳术丸，治心下痞满因于食。\n\n入陷胸汤，治伤寒寒热结胸。\n\n入大小承气汤，治伤寒热邪入里，结实胀满，痛不可当，数日不更衣者。\n\n【简误】\n        此药性专消导，破气损真。观朱震亨云：泻痰有冲墙倒壁之力，其为勇悍之气可知。凡中气虚弱，劳倦伤脾，以为痞满者，当用补中益气汤，补其不足则痞自除，此法所当忌也。胀满非实邪结于中下焦，手不可按，七八日不更衣者，必不可用。挟热下痢，亦非燥粪留结者，必不可用。伤食停积，多因脾胃虚，不能运化所致，慎勿轻饵。如元气壮实有积滞者，不得已用一二剂，病已即去之。即洁古所制枳术丸，亦为脾胃有积滞者设，积滞去则脾胃自健。故谓之益脾胃之药，非消导之外，复有补益之功也。时医不识病之虚实，药之补泻，往往概施，损人真气，为厉不浅。设误投之，虽多服参耆补剂，亦难挽其刻削之害也。世人多蹈其弊，故特表以为戒。', NULL, NULL, NULL, '枳实', NULL, '19、枳实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457046, '48C8B70D5A69A6E81B5ADDF1F23F4241', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7395, 419, 400106318, '      味苦、酸，微寒，无毒。主风痒麻痹，通利关节，劳气咳嗽，背膊闷倦，散留结，胸膈痰滞，逐水消胀满，大肠风，安胃止风痛。\n\n       疏：枳壳气味所主，与枳实大略相同，但枳实形小，其气全，其性烈，故善下达，如少年猛悍之将，勇往直前，而一无回顾者也。枳壳形大。其气散，其性缓，故其行稍迟，是以能入胸膈肺胃之分，及入大肠也。其主风痒麻痹，通利关节，止风痛者，盖肺主皮毛，胃主肌肉，风寒湿入于二经，则皮肤瘙痒，或作痛，或麻木。此药有苦泄辛散之功，兼能引诸风药入于二脏，故为治风所需。风邪既散，则关节自然通利矣。其疗劳气咳嗽，背膊闷倦者，盖亦指风寒郁于上焦，则肺气滞而为闷倦咳嗽。\n\n      《经》曰：肺苦气上逆，急食苦以泄之。枳壳味苦能泄至高之气，故主之也。又肺与大肠为表里，风邪入肺则并入大肠，风热相搏而为肠风下血，苦寒下泄之气，则血热清而风自除矣。其主散留结、胸膈痰滞，逐水消胀满，安胃，诸证悉与枳实相同，第其气稍缓耳。\n\n【主治参与】\n同苏子、橘皮、桔梗、木香、白豆蔻、香附，治上焦壅气胀满因于寒。\n\n同黄连、槐花、干葛、防风、荆芥、芍药、黄芩、当归、生地黄、地榆、侧柏叶，治肠风下血初起者，神效。\n\n同荆芥、苦参、防风、苍耳草、败蒲，煎汤沐浴，治风疹作痒。\n\n同槟榔、芍药、黄连、升麻、葛根、甘草、红曲、滑石，治滞下里急后重。\n\n得人参、麦冬，治气虚大便不快。\n\n同肉桂，治右胁痛。\n\n【简误】\n        枳壳泄肺，能损至高之气，肺气虚弱者忌之。脾胃虚，中气不运，而痰壅喘急者忌之。咳嗽不因于风寒入肺气壅者，服之反能作剧。咳嗽阴虚火炎者，服之立致危殆。一概胎前产后，咸不宜服。今世多用以治妇人胎气不安，或至八九月为易产之剂，动辄资用。殊不知妇人怀孕，全赖气血以养胎，气血充足则胎自易产。且娠妇至八九月，精神困倦，四肢软弱，饮食减少，动息喘促何？莫非虚弱之证，而更用此耗散之药耶？正《经》所谓损不足而虚其虚，岂不大谬哉！古方有瘦胎饮者，为湖阳公主而设，以彼奉养太过，其气必实，故用此以耗其有余之气，则胎易产。今人不知古人立方之意，一概滥施。误甚！误甚！', NULL, NULL, NULL, '枳壳', NULL, '18、枳壳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457047, '5854D8256502C49A04396244E8A06DFC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7396, 419, 400106317, '       味辛，平，无毒。主五内邪气，散皮肤骨节中淫淫温行毒，去三虫，化食，逐寸白，散肠中嗢嗢喘息。\n        \n        疏：芜荑禀金气而生于春阳之令，本经味辛，气平无毒。甄权加苦，李珣加温。详其功用应是苦辛温平之药。非辛温则不能散五脏皮肤骨节中邪毒气，非苦平则不能去三虫，化食，逐寸白，疗肠中嗢嗢喘息。然察其所主，虽能除风淫邪气之为害，而其功则长于走肠胃，杀诸虫，消食积也。故小儿疳泻冷痢为必资之药。\n\n【主治参与】\n同肉豆蔻、胡黄连、芦荟、使君子、青黛、五谷虫、雷丸、槟榔、橘皮，治小儿疳热泻痢，及腹大羸瘦面黄，好吃泥土。\n\n《本事方》制杀诸虫：生芜荑、生槟榔各四两，为末，蒸饼丸如梧子。每服二十丸，白汤下。\n\n钱氏《小儿直诀》疳热有虫瘦悴，久服充肥：用芜荑一两，黄连一两，为末，猪胆汁七枚，和入碗内，饭下蒸之，一日蒸一次，九蒸，乃入麝香半钱，汤浸蒸饼，和丸绿豆大。每服五七丸，至二十丸，米饮下。\n\n《危氏得效方》虫牙作痛：以芜荑仁，安蛀孔中及缝中，甚效。\n\n入药用大者，小者即榆荚，不堪入药。除疳证杀虫外，他用甚稀，故不著 “简误”。', NULL, NULL, NULL, '芜荑', NULL, '17、芜荑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457048, '469AB7EDC6DB071D961169AE4F7E0397', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7397, 419, 400106316, '     味辛、甘，微寒，一云温平，无毒。主心腹邪气，风湿积聚，耳聋，明目，去目赤浮翳。\n\n      疏：龙脑香禀火金之气以生。本经味辛苦，气微寒无毒。其香为百药之冠。凡香气之甚者，其性必温热。李珣言温，元素言热，是矣！气芳烈，味大辛，阳中之阳，升也，散也。性善走窜开窍，无往不达。芳香之气，能辟一切邪恶，辛热之性，能散一切风湿。故主心腹邪气及风湿积聚也。耳聋者，窍闭也，开窍则耳自聪。目赤浮翳者，火热甚也，辛温主散，能引火热之气自外而出，则目自明，赤痛浮翳自去，此从治之法也。\n\n    《别录》又主妇人难产者，取其善走、开通关窍之力耳。\n\n【主治参与】\n同乳香、没药、雄黄、红药子、乌鸡骨、白及、白敛、桑、卤碱、牛黄，傅一切疔肿痈疽，神效。\n\n《圣济总录》目生浮翳：龙脑为末，日点三五度。\n\n《御药院方》头目风热上攻：用龙脑末半两，南蓬砂末一两，频㗜两鼻。\n\n濒湖《集简方》风热喉痹：灯心一钱、黄檗五分，并烧存性，白矾七分煅过，片脑三分，为末。每以一二分吹患处。此陆一峰家传绝妙方也。\n\n又方：鼻中鼻肉垂下者，用片脑点之自入。\n\n《夷坚志》伤寒舌出过寸者：梅花片脑半分，为末掺之，随手而愈。\n\n又方：中风牙噤，无门下药者，开关散揩之。五月五日午时，用龙脑、天南星，等分为末，每以一字揩齿二三十遍，其口自开。\n\n《经验方》痘疮狂躁，心烦气喘，妄语，或见鬼神，疮色赤未透者：用龙脑一钱，细研，旋以猪心血丸芡子大。每服一丸，紫草汤下。少时心神便定，得睡发疮。\n\n《总微论》用獖猪第二番血清半杯，紫草汁半杯，和匀，入龙脑一分，温服。良久下瘀血一二行，疮即红活。此治痘疮黑黡恶候，医所不治者，百发百中。\n\n【简误】\n       宗奭云：此物大通利关膈热塞，大人小儿风涎闭塞，及暴得惊热，甚为济用，然非常服之词药。震亨云：龙脑属火，世知其寒而通利，未达其热而轻浮飞越。喜其香而贵重，动辄与麝同为桂、附之助。然人之阳易动，阴易亏，不可不思。杲曰：龙脑入骨，风病在骨髓者，宜用之为引经。若风在血脉肌肉，辄用脑、麝，反引风入骨髓，如油入面，莫之能出也。观三公之言，则龙脑之为害可知。凡中风，非外来之风邪，乃因气血虚而病者忌之。小儿吐泻后成惊者，为慢脾风，切不可服。急惊属实热可用，慢惊属虚寒不可用。眼目昏暗，属肝肾虚者不宜入点药，设误点之，必致昏暗难疗。', NULL, NULL, NULL, '龙脑香', NULL, '16、龙脑香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457049, 'D95A29AD899E9B0573115DE58AD9C846', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7398, 419, 400106315, '      味甘、咸、平，有小毒。主五藏邪气，带下，止痛，破积血，金疮生肉。（旧与紫铆同条，今分出。）\n\n        疏：麒麟竭禀土气而兼水化，故味甘咸，气平无毒。《丹房鉴源》云：禀于荧惑之气，生于汤石之阴，其色赤象火而味咸，则得阴气也。气薄味厚，阴也，降也。入足厥阴，手少阴经。甘主补，咸主消，散瘀血，生新血之要药。故主破积血，金疮止痛生肉。主五脏邪气者，即邪热气也。带下者，湿热伤血分所致也。甘咸能凉血除热，故悉主之。苏恭：主心腹卒痛；李珣以之治伤折打损，一切疼痛，血气搅刺，内伤血聚者，诚为此耳。（此药产外国，极难得真者，理伤折有夺命之功。）\n\n【主治参与】\n同乳香、没药、自然铜、麻皮灰、狗头骨煅存性、䗪虫、黄荆子、骨碎补，治一切打扑损伤。\n\n同发灰、乳香、没药、片脑、轻粉、象牙末、红粉霜，为细末，掺一切金疮及肿毒，生肌止痛。\n\n《广利方》金疮出血，麒麟竭末，傅之立愈。\n\n《医林集要》产后血冲，心胸喘满，命在须臾：用血竭、没药各一钱，研，童便和酒调服。\n\n《究原方》收敛疮口：血竭末一字，龙脑少许，大枣烧灰半钱，同研。津调涂之。\n\n《摘玄方》胸中血块：血竭、没药各一两，滑石、牡丹皮各一两，同煮过，为末，醋糊丸梧子大，空心服之。\n\n《医林集要》嵌甲疼痛，血竭末傅之。\n\n【简误】\n       凡使，勿用海母血，真相似，只是味咸并腥气。麒麟竭味微咸甘，似栀子气也。又云：嚼之不烂，如蜡者为上。凡血病无瘀积者，不必用。日华子云：此药性急，不可多使，却引脓。用时勿与众药同研，化作飞尘也。', NULL, NULL, NULL, '麒麟竭', NULL, '15、麒麟竭', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457050, 'EC73014561B1676E70C2753E21150D8F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7399, 419, 400106314, '    味苦，寒、大寒，无毒。主五内邪气，胃中热气，面赤酒皰皶鼻，白癞赤癞，疮疡。疮目热赤痛，胸心大小肠大热，心中烦闷。\n\n     疏：栀子感天之清气，得地之苦味，故其性无毒。气薄而味厚，气浮而味沉，阳中阴也。入手太阴、手少阴、足阳明经。少阴为君主之官，邪热客之，则五脏皆失所主。清少阴之热，则五内邪气自去，胃中热气亦除。面赤酒皰皶鼻者，肺热之候也。肺主清肃，酒热客之，即见是证，于开窍之所延及于面也。肺得苦寒之气则酒热自除，而面鼻赤色皆退矣。其主赤白癞疮疡者，即诸痛痒疮疡，皆属心火之谓。疗目赤热痛，及胸心大小肠大热，心中烦闷者，总除心肺二经之火热也。此药味苦气寒，泻一切有余之火，故能主如上诸证。\n\n【主治参与】\n仲景治伤寒汗吐下后，虚烦不得眠，及心中懊憹者，有栀子豉汤：用栀子十四枚，香豉四合，水煎服。\n\n入茵陈大黄汤，治伤寒湿热发黄，腹胀：栀子十四枚，茵陈六两，大黄三两，水一斗，先煮茵陈，减六升，内二味，煮取三升。分三服，小便当利，尿如皂角汁状，正赤，一宿腹减，黄从小便出也。\n\n同甘草、黄檗，为栀子檗皮汤，亦治发黄身热。\n\n同厚朴、枳实，为栀子厚朴汤。治伤寒下后心烦，腹满卧起不安者，得吐即愈。\n\n同鼠矢作汤，治大病后劳复，小便不利者，小便利即愈。以上皆仲景法。\n\n同连翘、麦门冬、竹叶、灯心草、生甘草、黄连，能泻心经有余之火。加赤茯苓、木通、滑石、泽泻，泻小肠火。\n\n同桑黄或桑白皮、黄芩、甘草、桔梗、五味子、干葛，治酒热伤肺，发出鼻皶。\n\n同茵陈蒿、滑石、车前子、秦艽、黄连、连前草、苜蓿，治酒热发黄。\n\n《梅师方》治热病后劳复，及因交接后发动，欲死不能语者：栀子三十枚，水三升，煎一升服，令微汗。\n\n《救急方》治汤烫火伤：栀子末，和鸡子清浓涂之。\n\n丹溪方：治胃脘火痛，山栀七枚炒，水一盏，煎七分，入生姜汁饮之，立止。\n\n【简误】\n      栀子禀至苦大寒之气，苦寒损胃而伤血。凡脾胃虚弱者忌之，血虚发热者忌之。性能泻有余之火，心肺无邪热者不宜用。小便不通，由于膀胱虚，无气以化，而非热结小肠者，不宜用。疮疡因气血虚不能收敛，则为久冷败疮，非温暖补益之剂则不愈。此所谓既溃之后，一毫寒药不可用是也。世人又以治诸血证，不知血得热则行，得寒则凝，瘀血凝结于中，则反致寒热，或发热劳嗽，饮食减少，为难疗之病。凡治吐血，法当以顺气为先，盖血随气而行，气降则火降，火降则血自归经，不求其止而止矣。此治疗之要法，不可违也。', NULL, NULL, NULL, '栀子', NULL, '14、栀子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457051, 'AD70841EDD28DE19C08AAA0D05699604', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7400, 419, 400106313, '      味辛，温，无毒。主消谷，逐水，除痰癖，杀三虫，伏尸，疗寸白。\n\n       疏：槟榔得天之阳气，地之金味，故味辛气温无毒。大明言涩，元素言苦，以其感盛夏之火气耳。气薄味厚，阳中微阴，降也。入手、足阳明经。夫足阳明为水谷之海，手阳明为传道之官，二经相为贯输，以运化精微者也。二经病则水谷不能以时消化，羁留而成痰癖，或湿热停久则变生诸虫。此药辛能散结破滞，苦能下泄杀虫，故主如上诸证也。甄权：宣利五脏六腑壅滞，破胸中气，下水肿，治心痛积聚。\n\n       日华子：下一切气，通失节，利九窍，健脾调中，破癥结。李珣：主贲豚气，五膈气，风冷气，脚气，宿食不消。皆取其辛温走散，破气坠积，能下肠胃有形之物耳。\n\n【主治参与】\n同草果、枳实、橘皮，治食疟。加三棱、蓬荗、矾红、红曲、山查、麦糵，消一切坚硬肉食，及诸米面、生冷、食积成块作痛。\n\n同黄连、扁豆、莲肉、橘红、白芍药、红曲、乌梅、葛根、枳壳，治滞下后重。\n\n同雷丸、使君子、白芜荑、芦荟、肉豆蔻、胡黄连，治小儿疳蛔。\n\n同楝根、鹤虱、锡灰、薏苡根、贯众、乌梅，治一切寸白虫。\n\n同苍术、草果、青皮、甘草，治山岚瘴气发疟。\n\n《直指方》心脾作痛：鸡心槟榔、高良姜各一钱半，陈米百粒，同以水煎，服之。\n\n《广利方》脚气冲心，闷乱不识人：用白槟榔十二分，为末，分二服，空心暖小便调下，日二服。\n\n《十便良方》虫痔里急：槟榔为末，每日空心以白汤调二钱。\n\n《千金方》寸白虫病：槟榔二七枚，为末。先以水二升半煮槟榔片，取一升，空心调末方寸匕服之，经日虫尽出。未尽再服，以尽为度。\n\n【简误】\n        槟榔性能坠诸气，至于下极，病属气虚者忌之。脾胃虚，虽有积滞者不宜用。下利，非后重者不宜用。心腹痛，无留结及非虫攻咬者不宜用。凡病属阴阳两虚，中气不足，而非肠胃壅滞，宿食胀满者，悉在所忌。', NULL, NULL, NULL, '槟榔', NULL, '13、槟榔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457052, 'C21681751E6507F3E76DDC4CA45BAED0', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7401, 419, 400106312, '      味辛，温、大热，有小毒。主温中，下气，止痛，咳逆寒热，除湿血痹，逐风邪，开腠理，去痰冷，腹内绞痛，诸冷实不消，中恶心腹痛，逆气，利五藏。\n\n     疏：吴茱萸禀火气以生，故其味辛气温，有小毒。甄权：辛苦大热。气味俱厚，阳也。入足阳明、太阴，兼入足少阴、厥阴经。凡脾胃之气，喜温而恶寒，寒则中气不能运化，或为冷实不消，或为腹内绞痛，或寒痰停积，以致气逆发咳，五脏不利。辛温暖脾胃而散寒邪，则中自温，气自下，而诸证悉除。其主除湿血痹，逐风邪者，盖以风寒湿之邪多从脾胃而入，脾胃主肌肉，为邪所侵，则腠理闭密而寒热诸痹所从来矣。辛温走散开发，故能使风寒湿之邪从腠理而出，中恶腹痛，亦邪恶之气干犯脾胃所致，入脾散邪则腹痛自止矣。\n\n【主治参与】\n仲景吴茱萸汤：治少阴病，吐利，手足逆冷，烦躁欲死者，吴茱萸一斤，人参二两，生姜六两，大枣十二枚劈，四味以水七升，煮二升，去滓温服七合，日三服。厥阴干呕吐涎沫、头痛者，同此方。\n又，当归四逆加吴茱萸汤，治厥阴证，手足厥冷，脉细欲绝，其人内有久寒者：当归三两，芍药三两，炙甘草二两，通草二两，桂枝三两，细辛三两，生姜半斤，吴茱萸二升，大枣二十五枚，以水六升，清酒六升，同煮取五升，去滓，分五服。\n\n《食疗》治冬月感寒：吴茱萸五钱，煎汤，服之取汗。\n\n《圣惠方》治阴毒伤寒，四肢逆冷：用吴茱萸一升，酒拌湿，绢袋二个包，蒸极热，更互熨足心。候气透，痛亦即止，累有效。\n\n《肘后方》治寒疝往来：吴茱萸一两，生姜半两，清酒一升煎，分温服。\n\n《圣惠方》治食已吞酸，胃虚冷者：吴茱萸汤泡七次，焙，干姜等分，为末，汤服一钱。\n\n孙氏《仁存方》治多年脾泄，老人多此，谓之水土同化：吴茱萸三钱泡，入水煎汁，入盐少许，通口服。盖茱萸能暖膀胱，水道既清，大肠自固，他药虽热，不能分解清浊也。\n\n《和剂局方》戊己丸：治脾胃受湿，下痢赤白，腹痛，米谷不化：吴茱萸、黄连、白芍药各一两，同炒为末，蒸饼丸梧子大。每服二三十丸，米饮下。\n\n【简误】\n       阳厥似阴，手足虽逆冷，而口多渴，喜饮水，大小便秘结，小便或通亦赤涩短少，此火极似水，守真所谓禁慄如丧神守，皆属于火之谓耳。此与桂、附、干姜之类同忌。呕吐吞酸，属胃火者不宜用，咳逆上气，非风寒外邪及冷痰宿水所致，不宜用。腹痛属血虚有火者，不宜用。赤白下痢，病名滞下，因暑邪入于肠胃，而非酒食生冷，停滞积垢者，不宜用。小肠疝气，非骤感寒邪，及初发一二次者，不宜用。霍乱转筋，由于脾胃虚弱冒暑所致，而非寒湿生冷干犯肠胃者，不宜用。一切阴虚之证，及五脏六腑有热无寒之人，法所咸忌。', NULL, NULL, NULL, '吴茱萸', NULL, '12、吴茱萸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457053, '4B5DBAE904EB689990033072F93AB5AD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7402, 419, 400106311, '    味甘，大寒，无毒。疗暴中风痹，胸中大热，止烦闷，消渴，劳复。\n\n     疏：竹沥，竹之津液也。经云大寒，亦言其本性耳。得火之后，寒气应减，性滑流利，走窍逐痰，故为中风家要药。凡中风之证，莫不由于阴虚火旺，煎熬津液，结而为痰，壅塞气道，不得升降，热极生风，以致猝然僵仆，或偏痹不仁。此药能遍走经络，搜剔一切痰结，兼之甘寒能益阴而除热，痰热既祛则气道通利，经脉流转，外证自除矣。其主胸中大热，止烦闷者，取其甘寒清热益阴之功耳。观古人以竹沥治中风，则知中风未有不因阴虚痰热所致。不然，如果外来风邪，安得复用此甘寒滑利之药治之哉？\n\n【主治参与】\n同贝母、栝楼仁、霞天膏、白芥子、苏子、橘红、郁金、童便、麦门冬，治似中风口眼㖞斜，语言蹇涩，或半身不遂等证。\n\n《千金方》治中风口噤：竹沥加姜汁，日日饮之。\n\n《梅师方》治产后中风口噤，身直面青，手足反张：以竹沥饮一二升，即苏。\n\n《外台秘要》治破伤中风：凡闪脱折骨诸疮，慎不可当风用扇，中风则发痉口噤项急，杀人。亟饮竹沥二三升。忌饮食及酒。\n\n《千金方》小儿伤寒：淡竹沥、葛根汁各六合，细细与服。\n\n《至宝方》小儿狂语，夜后便发，竹沥夜服二合。\n\n《产宝方》妇人胎动，妊娠因夫所动，困绝：以竹沥饮一升，立愈。\n\n《梅师方》孕妇子烦：茯苓二两，竹沥一升，水四升，煎二升，分三服。《千金方》时气烦躁，五六日不解。青竹沥半盏，煎热，数数饮之。覆取微汗。\n\n李绛《兵部手集》咳嗽肺痿，大人小儿咳逆短气，胸中吸吸，咳出涕唾，嗽出臭脓：用淡竹沥一合，服之日三五次，以愈为度。\n\n【简误】\n        寒痰，湿痰，及饮食生痰，不宜用。', NULL, NULL, NULL, '淡竹沥', NULL, '11、淡竹沥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457054, '6C1FC2F10C39152ED52218A5FBCD1D5D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7403, 419, 400106310, '       味甘，微寒，无毒。主呕啘，温气寒热，吐血，崩中。\n\n        疏：竹茹虽与竹叶同本，然竹茹得土气多，故味带甘，气微寒无毒。入足阳明经。《经》曰：诸呕吐酸水，皆属于热。阳明有热则为呕啘，温气寒热，亦邪客阳明所致，甘寒解阳明之热则邪气退而呕啘止矣。甘寒又能凉血清热，故主吐血崩中，及女劳复也。\n\n【主治参与】\n同木瓜、橘皮、麦门冬、枇杷叶、人参、芦根汁、石斛，治胃虚有热，呕啘不止。\n\n《活人书》治伤寒愈后交接，妇劳复，头痛身热，耳鸣口渴，腰骨痛，男子卵肿股痛：竹皮一升，水三升，煮五沸，服汁。\n\n又方，治妇人大病初愈，有所动劳，致热气冲胸，手足搐搦拘急，如中风状：淡竹青茹半斤，栝楼二两，水二升，煎一升，分二服。\n\n【简误】\n       胃寒呕吐，及感寒挟食作吐，忌用。', NULL, NULL, NULL, '淡竹茹', NULL, '10、淡竹茹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457055, 'AF6BC24F352B36331B7BF5AA954B53D9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7404, 419, 400106309, '    味辛，平、大寒，无毒。主胸中痰热，咳逆上气。\n     \n      疏：竹叶禀阴气以生，《本经》味辛平，气大寒无毒。甄权言甘寒。气薄味厚，阴中微阳，降也。入足阳明，手少阴经。阳明客热则胸中生痰，痰热壅滞则咳逆上气，辛寒能解阳明之热结，则痰自消，气自下，而咳逆止矣。仲景治伤寒发热大渴，有竹叶石膏汤，无非假其辛寒散阳明之邪热也。\n\n【主治参与】\n煎汤调酸枣仁炒熟末五钱，临卧服，治心虚不得眠。\n\n同麦门冬、酸枣仁、远志、丹参、茯神、丹砂、犀角，治心经蕴热，虚烦不眠。入白虎汤治伤寒烦热，大渴引饮。\n\n《肘后方》治时行发黄：竹叶五升，小麦七升，石膏三两，水一斗半，煮取七升，细服，尽剂愈。', NULL, NULL, NULL, '竹叶', NULL, '9、竹叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457056, 'F7314026F6C72772804719F73CE333EC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7405, 419, 400106308, '      气味与白皮同。其除肺热之功，殆又过之。山家老桑树多生，湖桑少见。同天门冬、百部、山栀、枇杷叶，治赤鼻有神。', NULL, NULL, NULL, '桑黄', NULL, '8、桑黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457057, '41CF5E4CCD054A17F855F83B8DCF464D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7406, 419, 400106307, '      味苦，平，性不冷不热。主遍体风痒干燥，火气脚气风气，四肢拘挛，上气眼晕，肺气咳嗽，消食，利小便。疗痈疽后渴，嫩条细捣一升，熬香煎饮。亦无禁忌。久服，终身不患偏风。\n《圣惠方》治紫白癜风。桑枝十斤，益母草三斤，水五斗，慢煮至五升，去滓，再煎成膏，每卧时温酒调服半合，以愈为度。', NULL, NULL, NULL, '桑枝', NULL, '7、桑枝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457058, 'B176F67E49CAFE896DFD2003BF707D95', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7407, 419, 400106306, '      即灰汁，以桑皮绵纸衬淘箩底，用滚水淋下，瓷器盛之，重汤煮干，别名木硵。能钻筋透骨，为傅痈疽，拔疔，引诸散毒药攻毒之要品。得丹砂、雄黄、乳香、没药、牛黄、龙脑香、红白药子、白及、白敛，傅一切肿毒，止痛追毒有奇效。得铁锈、蟾酥，可拔疔。', NULL, NULL, NULL, '桑霜，木硵', NULL, '6、桑霜，木硵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457059, 'FFB4902F4DAF39EFBFCFBD315BA2AF47', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7408, 419, 400106305, '      味辛，寒，有小毒。淋取汁，与冬灰等分，同灭痣疵黑子，蚀恶肉。煮赤小豆食，大下水胀。傅金疮，止血生肌。', NULL, NULL, NULL, '桑柴灰', NULL, '5、桑柴灰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457060, '98E4B17F9807830A6E99EF9778496A98', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7409, 419, 400106304, '       味甘，寒，无毒。单食，止消渴。陈藏器：利五藏、关节，通血气，久服不饥，安魂镇神，令人聪明，变白不老。多收曝干，为末，蜜丸，日服。时珍；捣汁饮，解中酒毒。酿酒服，利水气消肿。（一名文武实。）\n\n      疏：桑椹者，桑之精华所结也。其味甘，其气寒，其色初丹后紫，味厚于气。合而论之，甘寒益血而除热，其为凉血补血益阴之药无疑矣。消渴由于内热津液不足，生津故止渴。五脏皆属阴，益阴故利五脏。阴不足则关节之血气不通，血生津满，阴气长盛，则不饥而血气自通矣。热退阴生则肝心无火，故魂安而神自清宁，神清则聪明内发，阴复则变白不老。甘寒除热，故解中酒毒。性寒而下行利水，故利水气而消肿。皆自然之道也。\n\n【主治参与】\n寇宗奭曰：《本经》言桑甚详，独遗乌椹。然桑之精英，尽在于此，采摘微研，以布滤汁，石器熬成稀膏，量多少入蜜熬稠，贮瓷器中，每抄一二钱，食后、夜卧以沸汤点服。治服金石药发热口渴，生精神，及小肠热甚。\n\n仙方：日干为末，蜜和丸，酒服亦良。\n\n《四时月令》云：四月宜饮桑椹酒，能理百种风热。其法用桑椹汁三斗，重汤煮至一斗半，入白蜜二合，酥油一两，生姜汁一合，煮令得所，瓶收。每服一合，和酒饮之。亦可以汁熬烧酒藏之，经年味愈佳。\n\n《普济方》治水肿胀满，水不下则满溢，水下则虚竭还胀，十无一活，宜用桑椹酒治之：桑白皮切，以水二斗，煮汁一斗，入桑椹再煮，取五升，以糯米饭五升，酿酒饮。\n\n《保命集》治瘰疬结核，文武膏：用文武实，即桑椹子二斗，黑熟者，以布取汁，银石器熬成膏，每白汤调服一匙，日三服。\n\n《千金方》治小儿赤秃：桑椹子取汁，频服。《圣济录》治小儿白秃：黑椹，入罂中，曝三七日，化为水，洗之三七日，神效。\n\n《集简方》治阴证腹痛：桑椹绢包风干，过伏天，为细末。每服三钱，热酒下，取汗。\n\n【简误】\n       甘寒带滑，故润而下行，脾胃虚寒作泄者，勿服。', NULL, NULL, NULL, '桑椹', NULL, '4、桑椹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457061, 'B2A75869BC644D997F89415B7C480EA1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7410, 419, 400106303, '     味甘，有毒。黑者，主女子漏下赤白沃，血病癥瘕积聚，阴痛，阴阳寒热，无子，疗月水不调。其黄熟陈白者，止久泄，益气，不饥。其金色者，治癖饮，积聚，腹痛，金疮。桑耳煅存性，研细，香附、童便炒黑，研细，每用桑耳灰二分，香附三分，淡醋汤空心调服。治血崩奇效，过于他木耳。', NULL, NULL, NULL, '桑耳', NULL, '3、桑耳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457062, '6A3177C7CCF832C6E345AFC34DEDF172', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7411, 419, 400106302, '     主除寒热出汗。汁解蜈蚣毒。\n\n      疏：叶《本经》无气味。详其主治，应是味甘气寒性无毒。甘所以益血，寒所以凉血，甘寒相合，故下气而益阴，是以能主阴虚寒热，及因内热出汗。其性兼燥，故又能除脚气水肿，利大小肠。原禀金气，故又能除风。经霜则兼得天地之清肃，故又能明目而止渴。发者，血之余也。益血故又能长发，凉血故又止吐血。合痈口，罨穿掌，疗汤火，皆清凉补血之功也。\n\n【主治参与】\n四月采桑叶，酒拌，九蒸九曝，为末，胡麻或黑芝麻去壳，九蒸九曝，另磨如泥，各等分，炼蜜和为丸。每五六钱，空心饥时白汤下。能益气血，祛风。仙家饵之，为引年止饥之要药。\n\n《普济方》治青盲洗法：昔武胜军宋仲孚，患此二十年，用此法二年，目明如故。摘青桑叶晒干，逐月按日就地上烧存性，每以一合于瓷器内煎，减二分，倾出澄清，温热洗目，至百度，屡试有验。正月初八，二月初八，三月初六，四月初四，五月初六，六月初二，七月初七，八月二十九，九月十二，十月十三，十一月初二，十二月三十。\n\n《集简方》治风眼下泪：腊月不落桑叶，煎汤，日日温洗。或入芒硝。\n\n《千金方》治头发不长：用桑叶、麻叶，煮泔水，沐之七日，可长数尺。\n\n《圣济总录》治吐血不止：晚桑叶焙干研，凉茶服三钱，只一服止，后用补肝肺药。《直指方》治痈口不敛。经霜黄桑叶，为末傅之。\n\n《通玄论》治穿掌肿毒：新桑叶研烂，罨之即愈。\n\n《医学正传》治汤火伤疮。经霜桑叶烧存性，为末，油和敷之，三日愈。', NULL, NULL, NULL, '桑叶', NULL, '2、桑叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457063, 'F1E81E0427DF256A196F90C9B8AA65B3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7412, 419, 400106301, '       味甘，寒，无毒。主伤中，五劳六极，羸瘦，崩中脉绝，补虚益气，去肺中水气，唾血热渴，水肿腹满胪胀，利水道，去寸白，可以缝金疮。出土上者杀人。\n\n      疏：桑根白皮得土金之气，故味甘气寒而无毒。东垣、海藏俱云兼辛。然甘厚辛薄，降多升少，阳中阴也。入手太阴经。甘以固元气而补不足，辛以泻肺邪之有余，故能止嗽也。凡肺中有水气及肺火有余者宜之。伤中者，中气伤也。五劳者，五脏劳伤也。六极者，六腑之中气极也。羸瘦者，肌肉脱也。崩者中，血脱也。脉绝者，气血两虚之至，故脉不来也。之数者，皆由阴不足则阳有余，阳有余则火盛而内热，火与元气不两立，火能消物，造化自然也。惟甘也，可以补元气；惟寒也，可以除内热。热除矣，元气生矣，则上来诸证自瘳。故《本经》终之以补虚益气焉。《别录》去肺中水气者，即十剂中云：燥可去湿，桑白皮之属是已。吐血热渴者，热伤肺，火炎迫血妄行，溢出上窍，而兼发热作渴也。其主水肿腹满胪胀者，即利水道，除湿补虚之功也。湿热盛则寸白生，消除湿热则虫自不能留也。缝金疮者，甘寒补益，宜于伤损也。\n\n【主治参与】\n得天麦二冬、款冬花、百部、薄荷、甘草、沙参、贝母、枇杷叶、五味子，为治嗽要药。\n\n得芍药、薏苡仁、木瓜、茯苓、橘皮、赤小豆，为治水肿之神剂。\n\n《经验方》治咳嗽吐血甚者：鲜桑根白皮一斤，米泔浸三宿，刮去黄皮，剉细，入糯米四两，焙干为末。每服一钱，米饮下。\n\n《肘后方》治消渴尿多：入地三尺桑根，剥取白皮，炙黄黑，剉，以水煮浓汁，随意饮之。亦可少入米，勿用盐。\n\n《肘后方》治产后下血：炙桑白皮，煮水饮之。\n\n《经验方》治坠马拗损：桑根白皮五斤，为末，以水五升煎膏，敷之便止。以后亦无宿血，终不发动。\n\n《子母秘方》治小儿重舌：桑根白皮煮汁，涂乳上饮之。\n\n《圣惠方》治小儿流涎，脾热也，胸膈有痰：新桑根白皮捣自然汁饮之，甚效。煎饮亦良。《圣惠方》治小儿天吊惊痫：取家桑东行根，研汁服。\n\n《千金方》治石痈坚硬不作脓者：桑白皮，阴干为末，烊胶和酒调傅，以软为度。\n\n苏颂：取皮中白汁，主治小儿口疮白漫，拭净，涂之便愈。又涂金刃所伤（火参）痛，须臾血止，仍以白皮裹之，甚良。\n\n时珍：取汁涂蛇、蜈蚣、蜘蛛伤，有验。\n\n取枝烧沥，治大风疮疥，生眉发。\n\n《子母秘录》治小儿鹅口：桑皮汁，和胡粉涂之。\n\n《圣惠方》治小儿唇肿：桑木汁，涂之即愈。\n\n《摘玄方》治破伤中风：桑沥、好酒，对和温服，以醉为度。醒服消风散。\n\n【简误】\n肺虚无火，因寒袭之而发咳嗽者，勿服。', NULL, NULL, NULL, '桑白皮,桑根白皮', NULL, '1、桑根白皮,桑白皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627197436457064, '4E62058653D24AFAEFD8874C25AFCB8C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 16:52:56', 1, 'admin', '2025-01-16 11:07:31');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7413, 420, 400106409, '     味苦，平，无毒。主诸恶肿疮瘘，喉痹，蛇犬咬毒。研水服之，亦含亦涂。\n\n      疏：黄药根得土中至阴之气以生，故其色黄味苦，气平无毒。平即兼凉，日华子加凉是矣。气薄味厚，降多升少，阴也。入手少阴、足厥阴经。诸恶肿疮瘘，皆营气不从，逆于肉里所致。盖营主血，肝、心又主血、藏血之脏，二经得苦凉之气，则血热解，营气和，标证不求其止而止矣。《经》曰：一阴一阳结为喉痹。一阴者，少阴君火也；一阳者，少阳相火也。解少阴之热，相火自不妄动，而喉痹瘳矣。蛇犬咬毒，亦血分受热毒所伤故也。苦寒能凉血，得土气之厚者又能解百毒也。日华子以之疗马病。盖马性多热，亦取其苦寒除热之义耳。\n\n【主治参与】\n同忍冬藤、夏枯草、白及、白敛、紫花地丁、甘菊、茜草、连翘、牛蒡子、白芷、贝母、白药子之属，治一切疔肿痈疽。本经并载赤药，俗名红药子。予尝得一方，以之为君，每四两加白及、白敛各一两，乳香、没药各五钱，丹砂、雄黄各三钱，麝香、龙脑香各一钱，为细末。量疮大小，蜜调敷疮四围，中留大孔，以绵纸护之，时时以米醋润之。其痛即减，亦复易溃易收。治一切发背、痈疽俱神效。阴毒尤要。如无赤药子，以黄药子代之。\n\n孙思邈《千金月令》方：疗忽生瘿疾，以万州黄药子半斤，须紧重者为上。如轻虚，即是他州者，力慢，须用加倍。取无灰酒一斗，投药入中，固济瓶口。以糠火烧一伏时，待酒冷乃开。时时饮一杯，不令绝酒气。经三五日后，常把镜自照，觉消即停饮，不尔便令人项细也。\n\n《圣惠方》治吐血不止：黄药子一两，水煎服。\n\n《简要济众方》治鼻衄不止：黄药子为末，每服二钱，煎薄胶汤下。良久，以新水调面一匙头服之。\n\n禹讲师《经验方》产后血晕，恶物冲心，四肢冰冷，唇青，腹胀，昏迷：红药子一两，头红花二钱，水二盏，妇人油钗二只，同煎一盏服。大小便俱利，血自下也。\n\n【简误】\n痈疽已溃不宜服。痈疽发时，不焮肿，不渴，色淡，脾胃作泄者，此为阴证，当以内补为急，解毒次之，药子之类宜少服，只可外敷。', NULL, NULL, NULL, '黄药根', NULL, '9、黄药根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029254, '7619814724FB9D65BD2BDF24A454CB27', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7414, 420, 400106408, '      味苦，温，无毒。主赤白痢，肠滑，生肌肉。\n\n       疏：无食子禀春生之气，兼得西北金水之性，故味苦气温无毒。金主敛肃，大肠属金，以类相从，故主赤白痢，肠滑。春为发生之令，温能和脾胃，养腠理，故主生肌肉。水为润下，色黑而象肾，故李珣以之益血生精，和气安神，乌髭发，治阴痿诸证也。得温暖之气，复兼收敛之性，故为固涩精气之要药。（雷公云：凡使勿犯铜铁，并被火惊者，用颗小无栨米者妙，用浆水于砂盆中研令尽，焙干再研，如乌犀色入药。）\n\n【主治参与】\n同莲须、女贞子、枸杞子、地黄、南烛子、何首乌、黄精、旱莲草、术、人参，为乌须发之胜药。\n\n同覆盆子、牡蛎、枸杞子、五味子、车前子、地黄、莲须、龙骨、鹿茸、沙苑蒺藜、鱼膘胶、砂仁、黄檗，能补益精气，治一切梦遗泄精。\n\n仲景方：治阴汗，用无食子烧灰，先以汤浴了，布裹灰扑之，甚良。\n\n《宫气方》小儿久痢：没食子二个，熬黄研末，作馄饨食之。\n\n《圣济总录》牙齿疼痛：绵裹无食子末一钱，咬之，涎出吐去。\n\n《圣惠方》大小口疮：没食子炮三分，甘草一分，研末，掺之。月内小儿，生者少许，置乳上吮之，入口即啼，不过三次。\n\n《奇效方》足趾肉刺：无食子三枚，肥皂荚一挺，烧存性，为末，醋和傅之，立效。\n\n【简误】\n      赤白痢，由于湿热郁于肠胃，兼积滞多者，不宜用。', NULL, NULL, NULL, '无食子', NULL, '8、无食子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029255, '6436054EE186C8408162ECE5E2F014D7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7415, 420, 400106407, '     味酸，平，无毒。主大腹水肿，面目四肢浮肿，利小便水道。\n\n      疏：郁李仁得木气而兼金化，《本经》味酸，气平无毒。元素言辛苦。性润而降下，阴也。入足太阴，手阳明、太阳经。其主大腹水肿，面目四肢浮肿者。《经》曰：诸湿肿满，皆属脾土。又曰：诸腹胀大，皆属于热。脾虚而湿热客之，则小肠不利，水气泛溢于面目四肢，辛苦能润热结，降下善导癃闭，小便利则水气悉从之而出矣。甄权主肠中结气，关格不通。日华子云：泄五脏膀胱结痛，宣腰胯冷脓，消宿食下气。元素云：破血润燥。李杲云：专治大肠气滞，燥涩不通。均得之矣。\n\n【主治参与】\n同当归、地黄、麻仁、麦门冬、桃仁、生蜜、肉苁蓉，治大便燥结不通，甚者加大黄。\n\n《杨氏产乳》肿满气急不得卧，用郁李仁一大合，捣，和面作饼吃。入口即大便通，泄气便愈。\n\n【简误】\n       郁李仁，性专降下，善导大肠燥结，利周身水气。然而下后多令人津液亏损，燥结愈甚，乃治标救急之药。津液不足者，慎勿轻用。', NULL, NULL, NULL, '郁李仁', NULL, '7、郁李仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029256, 'F7669C9653DD225DDE86057FABB85904', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7416, 420, 400106406, '     味苦，有毒。主洗疮疥，风疽。皮：主疳䘌。樗木根、叶尤良。（雷公云：凡使椿根，不近西头者为上。采出拌生葱蒸半日，剉细，以袋盛，挂屋南阴干用。）\n\n      疏：椿禀地中之阴气以生，本经味苦有毒。甄权言微热。震亨言凉而燥。然考其用，必是微寒苦燥之药。入手足阳明经。本经主疳䘌及洗疥疮风疽，藏器去口鼻疳虫疥䘌者，因肠胃有湿热，故现是证。苦凉而燥，所以外治皆得也。\n\n藏器又主杀蛔虫，蛊毒，下血，及赤白久痢。日华子主肠风泻血。萧炳云：得地榆主疳痢。孟诜云：止女子血崩，及产后血不止，赤带。皆取其苦能燥湿，寒能除热，涩能收敛之功耳。采得去粗皮，蜜炙用。（樗功用相同。）\n\n【主治参与】\n《仁存方》下血经年：樗根白皮三钱，水一盏，煎七分，入酒半盏服。\n\n《外台秘要》小儿疳痢困重者：用樗根白皮捣粉，以水和枣作大馄饨子，日晒少时，又捣，如此三遍，以水煮熟，空腹吞七枚，重者不过七服愈。\n\n《子母秘录》小儿疳疾：椿根白皮，日干二两为末，以粟米淘净研浓汁，和丸梧子大。十岁儿三四丸，米饮下。量大小加减，仍以一丸纳竹筒中，吹入鼻内，三度良。\n\n《经验方》下利清血，腹中刺痛：椿根白皮，洗刮晒研，醋糊丸梧子大。空心米饮下三四十丸。\n\n《妇人良方》产后肠脱，不能收拾者：樗根取皮焙干一握，水五升，连根葱五茎，汉椒一撮，同煎至三升，去渣，倾盆内。乘热熏洗，冷则再热，一服可作五次用。洗后睡少时。忌盐、酢、酱、面、发风毒物，及用心劳力等事。\n\n丹溪方：女人白带：椿根白皮、滑石等分，为末，粥丸梧子大。空腹白汤下一百丸。\n\n寇宗奭云：洛阳一女子，年四十六七，耽饮无度，多食鱼蟹，蓄毒在脏，日夜二三十泻，大便与脓血杂下，大肠连肛门痛不堪忍。医以止血痢药不效，又以肠风药则益甚，盖肠风则有血无脓。如此半年，气血渐弱，食减肌瘦，服热药则腹愈痛，血愈下；服冷药则注泄食减；服温平药则病不知。如此期年，垂命待尽。或人教服人参散，一服知，二服减，三服脓血皆定，遂常服之而愈。其方治大肠风虚，饮酒过度，挟热下痢脓血痛甚，多日不瘥。用樗根白皮一两，人参一两，为末。每服二钱，空心米饮调服。忌油腻、湿面、青菜、果子、甜物、鸡、猪、鱼、羊、蒜、薤等。\n\n【简误】\n       脾胃虚寒者不可用。崩带属肾家真阴虚者，亦忌之，以其徒燥故也。凡滞下积气未尽者，亦不宜遽用。不入汤煎。', NULL, NULL, NULL, '椿木叶', NULL, '6、椿木叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029257, '3FB748A592E407EE2929A2B80BF64648', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7417, 420, 400106405, '     味苦，寒，有小毒。主温疾、伤寒大热烦狂，杀三虫，疥疡，利小便水道。\n\n     根：微寒，疗蛔虫，利大肠。（即金铃子。）\n\n    疏：楝实禀天之阴气，得地之苦味，故其味苦气寒，极苦而寒，故其性有小毒。气薄味厚，阴也，降也。入足阳明、手足太阴经。《经》曰：冬伤于寒，春必病温。其主温疾、伤寒大热烦狂者，总因寒邪郁久，至春变为温病，邪在阳明也。苦寒能散阳明之邪热，则诸证自除。膀胱为州都之官，小肠为受盛之官，二经热结，则小便不利。此药味苦气寒，走二经而导热结，则水道利矣。湿热郁积则内生诸虫，湿热浸淫则外为疥疡，得大寒极苦之物，则湿热散，故能疗诸虫及疥疡也。\n根：气味相同，故亦主杀虫，利大肠耳。\n\n【主治参与】\n同牛膝、木瓜、橘核、荔枝核、杜仲、巴戟天、乌秾树子、蘹香，治肾虚疝气。\n\n《澹寮方》楝实丸：治㿗疝肿痛，或钓肾偏坠，痛不可忍，用川楝子肉五两，分作五分，一分用破故纸二钱炒黄；一分用小茴香三钱，食盐半钱同炒；一分用班蝥七枚，去头足同炒；一分用莱菔子一钱同炒；\n\n一分用牵牛子三钱同炒。炒完，拣去食盐、莱菔子、牵牛、班蝥，只留故纸、茴香，同研为末，以酒打麵糊丸梧子大。每服五十丸，空心酒下。\n\n根，同白芜荑、槟榔、鹤虱、黄连、牵牛、雷丸、使君子、锡灰、乌梅、芦会，杀肠胃一切虫。\n\n《集简方》治小儿蛔虫：楝根皮，同鸡卵煮熟，空心服之。次日虫下。\n\n【简误】\n 脾胃虚寒者不宜用。', NULL, NULL, NULL, '楝实,金铃子,川楝子,苦楝子', NULL, '5、楝实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029258, '5303454C9C9A129EE229D89C9E455619', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2025-01-17 14:13:59');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7418, 420, 400106404, '   味苦，温，无毒。主冷气心腹胀满，下食。\n\n     疏：诃黎勒，其味苦涩，其气温而无毒。苦所以泄，涩所以收，温所以通。惟敛故能主冷气心腹胀满，惟温故能下食。甄权用以止水道，萧炳用以止肠澼久泄，苏颂用以疗肠风泻血，带下，朱震亨用以实大肠。无非苦涩收敛治标之功也。\n\n【主治参与】\n得人参，治肺虚受寒喘嗽。\n\n得橘皮、砂仁，主冷气入内，心腹胀满，及因寒食不下。\n\n得益智，止气虚寒小水不禁。\n\n佐樗根白皮，止肠澼泻血。\n\n佐白术、莲实，止久泄因于虚寒。\n\n同蛇床子、五味子、山茱萸、杜仲、续断，止虚寒带下。\n\n同人参、肉豆蔻，则实大肠。\n\n【简误】\n       诃子性温而味涩，涩主敛，不主散。故咳嗽因于肺有实热，泄泻因于湿热所致，气喘因于火逆冲上，带下因于虚热，而不因于虚寒，及肠澼初发，湿热正盛，小便不禁，因于肾家虚火，法并忌之。至于滞下必本湿热，喘嗽实由肺火，用之立致杀人，不可不深戒也！东垣谓苦重泻气，酸轻不能补肺，故嗽药中不用，亦此意耳。', NULL, NULL, NULL, '诃黎勒', NULL, '4、诃黎勒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029259, '2FB237A37155D6ACCB245E9304B80A7F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7419, 420, 400106403, '      味辛、咸，温，有小毒。主风痹死肌，邪气风头泪出，利九窍，杀精物，疗腹胀满，消谷，除咳嗽，囊结，妇人胞不落，明目益精。可为沐药。\n\n      疏：皂荚禀木气而兼火金之性，故味辛微咸，气温有小毒。气味俱厚，浮而散，阳也。入足厥阴，手太阴、阳明经。厥阴为风木之脏，其主风痹死肌，头风泪出者，皆厥阴风木为病。得金气之厚者，能胜木，禀辛散之性者，能利窍。木气平，关窍利，则风邪散，诸证除也。关窍既利则神明自通，精物邪气安得不去哉？又厥阴之脉，循阴器而络于肝，厥阴客寒为囊结，辛温散厥阴之寒，则囊结解矣。肺受风寒所迫为咳嗽，入肺散邪则咳嗽止矣。咸能软坚，温主通行，辛能开窍横走，故又主腹胀满，消谷及妇人胞不落也。宣壅导滞之性，而云益精明目，无是理矣！\n\n子：气味与皂荚同。炒，舂去赤皮，以水浸软，煮熟，糖渍食之，疏导五脏风热壅滞，及治大肠虚秘，瘰疬，恶疮肿毒。\n\n刺：功用与荚同。第其锐利，能直达疮所，为痈疽、妒乳、疔肿未溃之神药。苏颂以米醋熬嫩刺，作煎涂癣疮，有奇效。又治疠风恶疮，胎衣不下，杀虫。凡痈疽已溃，不宜服，孕妇亦忌之。\n\n【主治参与】\n同真珠、象牙末、牛黄、冰片、白僵蚕、滴乳石、土茯苓，治蛀疳神效。\n\n孙用和稀涎散：治中风昏昏如醉，形体不收，或倒或不倒，或口角流涎，斯须不治，便成大病。此证风涎潮于上，胸痹不通，急宜吐之。用大皂荚，肥实不蛀者四挺，去黑皮，白矾明者一两，为末。每用半钱，重者三字，温水调灌。不大呕吐，只是微微稀冷涎，或出一升、二升，当待醒，醒乃用药调治，不可便大吐之，恐过剂伤人。累效不能尽述。《圣惠方》胸中痰结：皂荚三十挺，去皮切，水五升，浸一夜，挼取汁，慢熬至可丸，如梧子大。每食后，盐浆水下十丸。\n\n又，钓痰膏：用半夏醋煮过，以皂角膏和匀，入明矾少许，以柿饼捣膏，丸如弹子大，噙之。\n\n《千金方》二便关格：皂荚烧研，粥饮下三钱，立通。《宣明方》铁脚丸同。\n\n《千金方》齆鼻不通，皂角末吹之。\n\n《十全方》风虫牙痛：猪牙皂角、食盐等分，为末，日揩之。\n\n《袖珍方》便毒肿痛：猪牙皂角七片，煨黄去皮弦，出火毒，为末，空心温酒服五钱。妇人妒乳同。\n\n《直指方》便毒痈疽：皂角一条，醋熬膏，傅之，屡效。\n\n《儒门事亲》便痈初起：皂角子七枚，研末水服，效。\n\n阮氏《经验方》年久瘰疬：用不蛀皂角子一百粒，米醋一升，蓬砂二钱，同煮干，炒令酥。看疬子多少，如一个服一粒，十个服十粒，细嚼米汤下。酒浸煮服亦可。一云：虚人不可用蓬砂。\n\n同蝉蜕、白僵蚕、杏仁、芭蕉根、白毛藤、土茯苓、独核肥皂仁、白鲜皮、连翘、薏苡仁、萆薢、汉防己，治下疳广疮，神效。\n\n同连翘、白芷、甘菊、紫花地丁、白及、金银花、甘草、鼠粘子、茜草、地榆，治下部痈疽肿毒。\n\n《神仙传》崔言患大风恶疾，双目昏盲，眉发自落，鼻梁崩倒，势不可救，遇异人传方：用皂角刺三斤，烧灰，蒸一时久，日干为末。食后浓煎大黄汤调一匕，饮之。一旬眉发再生，肌润目明。\n\n【简误】\n     皂荚利九窍，疏导肠胃壅滞，洗垢腻，豁痰涎，散风邪。暴病气实者，用之殊效。第似中风证，由于阴虚火炎，煎熬津液，结而为痰，热极生风，以致猝然仆蹶。世人多以稀涎散吐之，损其不足，竭其津液，津液愈耗则经络无以荣养，为拘挛偏废之证矣。法所最忌也。孕妇忌服。', NULL, NULL, NULL, '皂荚', NULL, '3、皂荚', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029260, 'F7BF127A509E1472451C33EBB13D8F3A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7420, 420, 400106402, '      味辛，温、大热，有毒。主邪气咳逆，温中，逐骨节皮肤死肌，寒湿痹痛，下气，除六腑寒冷，伤寒，温疟，大风汗不出，心腹留饮宿食，肠澼下痢，泄精，女子字乳余疾，散风邪，瘕结水肿，黄疸，鬼疰蛊毒，杀虫、鱼毒。久服头不白，轻身增年。开腠理，通血脉，坚齿发，调关节，耐寒暑。可作膏药。多食令人乏气。口闭者杀人。\n\n      疏：蜀椒禀火金之气，得南方之阳，受西方之阴。《本经》味辛气温。\n \n   《别录》大热有毒。气味俱厚，阳也。入手足太阴，兼入手厥阴经。其主邪气咳逆，皮肤死肌，寒湿痹痛，心腹留饮宿食，肠澼下痢，黄疸，水肿者，皆脾肺二经受病。肺出气，主皮毛。脾运化，主肌肉。肺虚则外邪客之，为咳逆上气。脾虚则不能运化水谷，为留饮宿食，肠澼下痢，水肿，黄疸。二经俱受风寒湿邪，则为痛痹，或成死肌，或致伤寒温疟。辛温能发汗，开腠理，则外邪从皮肤而出。辛温能暖肠胃，散结滞，则六腑之寒冷除，肠胃得温则中焦治，而留饮、宿食、肠澼下痢、水肿、黄疸，诸证悉愈矣。其主女子字乳余疾者，亦指风寒外侵，生冷内停而言。泄精、瘕结，由下焦虚寒所致。此药能入右肾命门，补相火元阳，则精自固而结瘕消矣。疗鬼疰蛊毒，杀虫、鱼毒者，以其得阳气之正，能破一切幽暗阴毒之物也。外邪散则关节调，内病除则血脉通。佐补阴凉血之药，则头不白，齿发坚，耐寒暑，轻身增年所自来矣。\n\n【主治参与】\n同女贞子、牛膝、地黄、何首乌、旱莲草、枸杞子、没食子、桑椹子、黄檗、人参、南烛子，能乌须黑发，悦色驻颜。\n\n空心单服，能收轻粉、水银毒。\n\n椒红丸：治元脏伤惫，目暗耳聋。服此百日，觉身轻少睡，足有力，是其效也。服及三年，心智爽悟，目明倍常，面色红悦，髭发光黑。用蜀椒去目及闭口者，炒出汗，曝干，捣取红一斤，以生地黄捣自然汁，入砂器中煎至一升，候稀稠得所，和椒末丸梧子大。每空心暖酒下三十丸。合药时勿令妇人、鸡犬见。\n\n孙真人方：心腹冷痛，以布裹椒安痛处，用熨斗熨令椒出汗，即止。\n\n《普济方》飧泄不化，及久利：小椒一两炒，苍术二两土炒，研末，醋糊丸梧子大。每五十丸，米饮下。\n\n《经验方》囊疮痛痒：红椒七粒，葱头七个，煎水洗之。\n\n《大全良方》寒湿脚气：川椒二三升，疏布囊盛之，日以踏脚。\n\n入仲景乌梅丸，治蛔厥。\n\n宗奭方：治盗汗，将椒目微炒，研细，用半钱，以生猪上唇煎汤一合，睡时调服，无不效。\n\n甄权方：治肾虚耳中如风水鸣，或如钟罄之声，卒暴聋者，用椒目、巴豆、菖蒲，同研细，以松脂、黄蜡溶和为挺，纳耳中抽之。一日一易，神验。\n\n《千金方》水气肿满：椒目炒捣细，每酒服方寸匕。\n\n【简误】\n       椒禀纯阳之气，乃除寒湿，散风邪，温脾胃，暖命门之圣药。然而肺胃素有火热，或咳嗽生痰，或嘈杂醋心、呕吐酸水，或大肠积热下血，咸不宜用。凡泄泻由于火热暴注，而非积寒虚冷者忌之。阳痿脚弱，由于精血耗竭而非命门火衰虚寒所致者，不宜入下焦药用。咳逆非风寒外邪壅塞用，不宜用。字乳余疾，由于本气自病者，不宜用。水肿、黄疸，因于脾虚而无风湿邪气者，不宜用。一切阴虚阳盛，火热上冲，头目肿痛，齿浮，口疮，衄血，耳聋，咽痛，舌赤，消渴，肺痿咳嗽，咯血吐血等证，法所咸忌。', NULL, NULL, NULL, '蜀椒', NULL, '2、蜀椒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029261, '2C40EDD71378729ACD7064047063449F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7421, 420, 400106401, '      味辛，温，生温，熟寒，有大毒。主伤寒、温疟寒热，破癥瘕结聚坚积，留饮痰癖，大腹水胀，荡涤五藏六府，开通闭塞，利水谷道，去恶肉，除鬼毒蛊疰邪物，杀虫鱼，疗女子月闭，烂胎，金疮脓血，不利丈夫阴，杀斑猫毒。可炼饵之，益血脉，令人色好，变化与鬼神通。\n\n      疏：巴豆生于盛夏六阳之令，而成于秋金之月，故味辛气温，得火烈刚猛之气，故其性有大毒。\n \n   《别录》言生温、熟寒，恐熟亦不甚寒。气薄味厚，降也，阳中阴也。入手足阳明经。其主破癥瘕结聚坚积，留饮痰癖，大腹水肿，鬼毒蛊疰邪物，女人月闭者，皆肠胃所治之位，中有实邪留滞，致生诸病。故肠胃有病，则五脏六腑闭塞不通，此药禀火性之急速，兼辛温之走散，入肠胃而能荡涤一切有形积滞之物，则闭塞开，水谷道利，月事通，而鬼毒蛊疰邪物悉为之驱逐矣。温疟者，亦暑湿之气入于肠胃也。肠胃既清，则温疟自止。火能灼物，故主烂胎及去恶肉。性热有大毒，则必有损于阴，故不利丈夫阴。\n\n   《本经》又主伤寒寒热，及《别录》炼铒之法，悉非所宜。岂有辛热大毒之物，而能治伤寒寒热，及益血脉，好颜色之理哉？\n\n【主治参与】\n同白矾枯过，去巴豆，单用矾研细，吹入喉中，流出热毒涎，喉即宽，治急喉痹如神。\n\n一味炒，烟尽存性，研膏，治痈疽溃后腐肉不落，傅上即拔毒去瘀生新。\n\n《外台秘要》飞尸鬼击中恶，心痛腹胀，大便不通。走马汤：用巴豆二枚，去皮心熬黄，杏仁二枚，以绵包椎碎，热汤一合，捻取白汁，服之，当下而愈。量老少用之。\n\n《琐碎录》天丝入咽：凡露地饮食，有飞丝入上，食之令人咽喉生疮。急以白矾、巴豆烧灰，吹入即愈。\n\n《经验方》耳卒聋闭：巴豆一粒，绵裹，针刺孔通气，塞之取效。\n\n《普济方》一切恶疮有虫者：巴豆三十粒，麻油煎黑，去豆，以油调硫黄、轻粉末，频涂取效。\n\n仲景三物白汤：治伤寒懊憹满闷，身无热者，为寒结胸，用桔梗三分，巴豆一分去皮心熬黑，贝母三分，二味为末，内巴豆臼中杵之，以白汤和服。强人半钱，弱者减之。病在膈上必吐，在膈下必利，不利进热粥一杯，利过不止，进冷粥一杯。\n\n【简误】\n       元素曰：巴豆乃斩关夺门之将，不可轻用。世以之治酒病膈气，以其辛热能开通肠胃郁结耳。第郁结虽开，而血液随亡，真阴亏损。从正曰：伤寒、风温、小儿痘疮、妇人产后，用之下膈，不死亦危。奈何庸人畏大黄而不畏巴豆，以其性热而剂小耳。岂知蜡匮之，犹能下后使人津液枯竭，胸热口燥，耗却天真，留毒不去，他病转生。观二公之言，则巴豆之为害昭昭矣。然而更有未尽者，巴豆禀火烈之气，沾人肌肉无有不灼烂者。试以少许轻擦完好之肤，须臾即发出一泡，况肠胃柔脆之质，下咽则徐徐而走，且无论下后耗损真阴，而腑脏被其熏灼，能免无溃烂之患耶？凡一概汤散丸剂，切勿轻投，即不得已急证，欲借其开通道路之力，亦须炒熟，压令油极净，入分许即止，不得多用。', NULL, NULL, NULL, '巴豆', NULL, '1、巴豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627206520029262, '9CF2E08F4EC92646AD558E616D45980B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-27 17:29:54', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7422, 420, 400106429, '        平，无毒。止肠风泻血。又止痢后热渴。作饮服之，令人得睡。入药妙用。\n\n       疏：木槿，本经气平无毒。详其主治，应是味苦气寒，清热滑利之药。肠风泻血，湿热留中也。痢后作渴，余热在经，津液不足也。夜卧少睡，心经蕴热，虚烦不宁也。苦寒能除诸热，滑利能导积滞，故主如上等证。今人用治癣疮，多取川中所产，肉厚而色红者弥良。\n花：功用相同，作汤代茶，兼能治风。\n\n【主治参与】\n《扶寿方》牛皮癣：川槿皮一两，大风子肉十五个，半夏五钱剉，河水、井水各一碗，浸六七宿，入轻粉一钱，秃笔扫涂，覆以青衣，数日有臭涎出妙。忌澡浴。\n\n《简便方》癣疮有虫：川槿皮煎，入肥皂，浸水频频擦之。或以槿皮浸汁，磨雄黄尤妙。', NULL, NULL, NULL, '木槿', NULL, '29、木槿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929925, '836439F2DABD917286F5577C29A92484', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7423, 420, 400106428, '      平，无毒。止鼻洪，吐血，破癥，治崩中，带下，肠风，赤白痢。入药烧灰用，不可绝过。\n\n       疏：棕榈皮禀微阳之气以生，故其味苦涩，气平无毒。本经主诸病，皆烧灰用者。凡血得热则行，得黑灰则止，故主鼻洪，吐血。苦能泻热，涩可去脱，故主崩中，带下，及肠风，赤白痢也。止血固脱之性，而能消瘀血，故能破癥也。凡失血过多，内无瘀滞者用之切当。与乱发灰同入更良。如暴得吐血，瘀滞方动，暴得崩中，恶露未竭，湿热下痢，初发肠风，带下方炽，悉不宜遽用，即用亦无效。入药须年久败者良。', NULL, NULL, NULL, '棕榈皮', NULL, '28、棕榈皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929926, '3FD1D00AB4B05C9BC8CE7727F7B708BA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7424, 420, 400106427, '      味苦，平，无毒。治黄疸病。皮烧末，服方寸匕。\n\n      疏：柞木，即凿子木，处处山中有之。叶小而有细齿，光滑而韧。其木及叶丫皆有针刺，经冬不凋，五月开碎白花，不结子，木心里皆白色。本经味苦气平无毒。然其性又善下达。主黄疸病者，盖黄疸因湿热郁于肠胃而发，此药苦能燥湿，微寒能除热，兼得下走利窍之性，则湿热皆从小便出而黄自退矣。今世又以为治难产、催生之要药，亦取其下达利窍之性耳。同鱼膘、人参、千里马、百草霜、牛膝、白芷、当归、益母草，为催生圣药。\n无别用，故不著 “参互” 及 “简误”。', NULL, NULL, NULL, '柞木皮', NULL, '27、柞木皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929927, 'E5E400DE9B2F944B9DC4AE0AA1B353AB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7425, 420, 400106426, '     味苦，平，无毒。主久痢赤白，捣和水绞取汁，服一升，日二，大效。\n\n      疏：水杨叶嫩枝，生于涯溪之旁，得水土之阴气偏多，故味苦气平无毒。久痢赤白，肠胃湿热也。得苦凉之气，则湿热散，痢自止。今人又用以治痈肿痘疮，多效。魏直《博爱心鉴》云：痘疮数日陷顶，浆滞不行，或风寒所阻者，宜用水杨枝叶，无叶用枝五斤，流水一大釜，煎汤温浴之，如冷添汤。良久，照见累起有晕丝者，浆行也。如不满，再浴之，力弱者，只洗头面手足。如屡浴不起者，气血败矣，不可再浴。始出及痒塌者，皆不可浴。痘不行浆，乃气滞血涩，腠理闭密，或风寒外阻而然。浴令暖气透达和畅，郁蒸气血通彻，每随暖气而发，行浆贯满，功非浅也。若内服助气血药，藉此升之，其效更速。直见一妪，在村中用此有验。叩得其方，行之百发百中。慎勿易之，诚有燮理之妙也。', NULL, NULL, NULL, '水杨叶嫩枝', NULL, '26、水杨叶嫩枝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929928, '99FBF251E94A2251714EF446E9609406', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7426, 420, 400106425, '     无毒。主剥驴马血入肉毒。取以火炙熨之，亦可煮汁浸之。\n\n        疏：赤柽木禀春阳之气以生，故其色青而叶稍带微赤，凌冬不凋。其味甘咸，其气温而无毒。浮而升，阳也。入足阳明，手太阴、少阴经。观本经载其能解驴马血入肉发毒者，盖以驴马性热，故多毒，生时汗气沾人即能为病，所以剥时热血入肉亦能致毒。此药味甘咸，甘得土气，咸得水气，故能入血解血分之毒也。近世又以治痧疹热毒不能出，用为发散之神药。经曰：少阴所至为疡疹。正刘守真所谓 “诸痛痒疮疡，皆属心火” 之旨也。盖热毒炽于肺胃，则发斑疹于肌肉间，以肺主皮毛，胃主肌肉也。此药正入肺胃心三经。三经毒解则邪透肌肤而内热自消。此皆开发升散，甘咸微温之功用也。\n\n【主治参与】\n同石膏、知母、薄荷、荆芥、玄参、牛旁子、麦门冬、竹叶、连翘、黄芩、甘草之属，治癍疹发不出，或虽发不透。如热甚毒炽，舌生芒刺，大渴，谵语，癍色紫黑者，加入三黄石膏汤内，大效。\n\n单用及兼各药，并主痧疹首尾诸证。\n\n治一切风，不问远近，用赤柽木叶半斤，切，荆芥半斤，水五升，煮二升，澄清，入白蜜五合，竹沥五合，新瓶盛之，油纸封，入重汤煮一伏时，每服一小盏，日三服。\n\n酒多致病，长寿仙人柳，晒干为末，每服一钱，温酒下。\n\n气味甘温，性复无毒，除痧疹外，他用甚稀，故不著 “简误”。\n', NULL, NULL, NULL, '赤柽木', NULL, '25、赤柽木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929929, '6240249608169BEA78D20EF46EEA0A09', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7427, 420, 400106424, '      微寒，无毒。主小儿寒热，十二惊痫。\n\n      疏：钓藤禀春气以生，本经气微寒，无毒。保升言苦，甄权言甘平。应是甘苦俱不甚，气味悉和平者也。为手少阴、足厥阴经要药。少阴主火，厥阴主风，风火相搏，则为寒热惊痫。此药气味甘寒，直走二经，则风静火息而肝心宁，寒热惊痫自除矣。甄权主小儿惊啼，瘈疭热壅，客忤胎风者，亦此意耳。\n\n【主治参与】\n得远志、茯神、琥珀、枣仁、丹砂、牛黄、天竺黄、犀角屑、生地黄、龙齿、麦门冬、金箔，治小儿惊痫瘈疭。有痰加竹沥、南星、橘红。\n\n《圣济录》小儿惊热：钓藤一两，消石半两，炙甘草二钱五分，为散。每服半钱，温水服，日三服。\n\n《圣惠方》卒得痫疾：钓藤、炙甘草各二钱，水五合，煎二合。每服枣许，日五、夜三。\n\n除小儿惊痫外，无他用，故不著 “简误”。', NULL, NULL, NULL, '钓藤', NULL, '24、钓藤', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929930, 'D62383E9E7E14CC5C1301282718E510E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7428, 420, 400106423, '     味甘，温，无毒。主折伤，消结肿恶疮，生肌，止腰痛，除粉刺䵟（黑曾），妇人乳痈，肛门肿痛。\n\n     疏：木鳖子禀火土之气，感长夏暑热之令以生，故其味甘，气温无毒。味厚于气，可升可降，阳也。为散血热、除痈毒之要药。夫结肿恶疮，粉刺䵟（黑曾），肛门肿痛，妇人乳痈等证，皆血热所致。折伤则血亦瘀而发热。甘温能通行经络，则血热散，血热散则诸证无不瘳矣。其止腰痛者，盖指湿热客于下部所致，而非肾虚为病之比也。用者详之。\n\n【主治参与】\n       孙用和《秘宝方》肛门痔痛：用木鳖仁三枚，砂盆擂如泥，入百沸汤一碗，乘温先熏后洗，日用三次，仍涂少许。\n\n     《圣惠方》耳卒热肿：木鳖子仁一两，赤小豆、大黄各半两，为末，每以少许生油调涂之。\n\n【简误】\n木鳖子味虽甘，而气则大温。本经虽云无毒，然亦未免有毒。但宜外用，勿轻内服。刘绩《霏雪录》云：木鳖子有毒，不可食。昔蓟门有人生二子，恣食成痞，其父得一方，以木鳖子煮猪肉食之。其幼子当夜死，长子明日死。其为毒虽未如此之厉，然亦必非纯粹之物也。\n番木鳖：形小于木鳖，而色白，味苦，气寒，性无毒。主伤寒热病，咽喉痹痛，消痞块，并含之咽汁。《医方摘要》治喉痹作痛，用番木鳖、青木香、山豆根等分，为末，吹之。\n【简误】\n番木鳖，性大寒，味至苦，凡病人气血虚弱，脾胃不实者，慎勿用之。', NULL, NULL, NULL, '木鳖子', NULL, '23、木鳖子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929931, '209C4A6A396A650DACA30CF90D7AEC4F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7429, 420, 400106422, '     味苦，平，无毒，主诸黄疸。浓煮汁饮之，良。\n\n       疏：桦木皮生于西北阴寒之地，故其味苦气平无毒。气味俱薄。降多升少，阴也。入足阳明经。五疸皆湿热郁于阳明所致，苦平能除湿热，故主诸疸也。藏器以之治伤寒，时行热毒疮。宗奭以之治肺风毒，皆取其苦凉能散风邪热毒之义耳。\n\n【主治参与】\n《灵苑方》乳痈初发，肿痛结硬欲破，一服即瘥。以北来真桦皮，烧存性研，无灰酒服方寸匕，即卧，觉即瘥也。\n\n唐瑶《经验方》乳痈腐烂：靴内年久桦皮烧灰，酒服一钱，日一服。\n\n《和剂局方》肺风毒疮，遍身疮疥如疠，及瘾疹瘙痒，面上风刺，妇人粉刺，并用桦皮散主之：桦皮烧灰四两，枳壳去穰烧四两，荆芥穗二两，炙甘草一两，各为末，杏仁水煮过，去皮尖二两，研如泥，研匀。每服二钱，食后温酒调下，疮疥甚者日三服。\n\n【简误】\n      脾胃弱，易于作泄者忌之。', NULL, NULL, NULL, '桦木皮', NULL, '22、桦木皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929932, '5548D8A98DFF4D3CECB6AD243A618053', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7430, 420, 400106421, '     味甘、苦，平，无毒。主折伤，续筋骨，除风痒龋齿。可作浴汤。\n\n      疏：接骨木禀土气以生，故其味甘苦，气平无毒。甘能入脾养血，故主折伤，续筋骨。苦凉能除风湿浮热，故主风痒龋齿也。《千金方》打伤瘀血，及产妇恶血，一切血不行，或行不止，并煮汁服。\n\n【主治参与】\n       《易简方》治折伤筋骨：接骨木半两，乳香半钱，芍药、当归、川芎、自然铜各一两，为末。化黄蜡四两，投药搅匀，众手丸如芡实大。若止损伤，酒化一丸，若碎折筋骨，先用此敷贴，乃服。\n无别用，故不著 “简误”。', NULL, NULL, NULL, '接骨木', NULL, '21、接骨木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929933, 'CB9BF50CEE705C37F833C207249A5DCF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7431, 420, 400106420, '     微温，无毒。主疗漆疮。\n\n     疏：杉极得阳气而兼金化，本经气微温，无毒。日华子加辛。气味芬芳，可升可降，阳也。入足阳明经。本经主疗漆疮，及苏恭疗脚气肿满者，皆从外治，取其芬芳能解漆气之秽恶，辛温能散湿毒之冲逆也。苏恭又云：服之治心腹胀痛，去恶气。日华子云：治霍乱上气。无非假其下气散邪，辛温开发之功耳。\n\n木皮：主金疮血出，及汤火伤灼，取老树皮烧存性，研傅之。或入鸡子清调傅，一二日愈，香油亦可。\n\n【主治参与】\n同橘皮、木瓜、香薷、砂仁、白扁豆、石斛，治暑月霍乱转筋。\n\n柳柳州纂《救三死方》云：元和十年二月得脚气，夜半痞绝，胁有块，大如石，且死，困不知人三日，家人号哭。荥阳郑洵美传杉木汤，服半食顷，大下三行，气通块散。方用杉木节一大升，橘叶切一大升，无叶则以皮代之，槟榔七枚，童子小便三大升，共煮一大升半，分为两服。若一服得快，即停后服。此乃死病，会有教者，乃得不死。恐人不幸病此，故传之。\n\n危氏《得效方》小儿阴肿赤痛，日夜啼叫，数日退皮，愈而复作：用老杉木烧灰，入腻粉，清油调傅，效。\n\n《救急方》臁疮黑烂多年。老杉木节烧灰，麻油调，隔箬叶摊贴系定，数易即愈。\n\n除转筋、脚气外，他用甚稀，故不著 “简误”。', NULL, NULL, NULL, '杉材', NULL, '20、杉材', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929934, 'ABC72130F38AB436601939ACE866DC1E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7432, 420, 400106419, '    味苦，微温，有毒。主暴水，癥结积聚。\n\n      疏：乌桕木根皮，禀火金之气以生，本经味苦气微温。日华子言凉。然详其用，应是辛苦温之药，而其性则有毒也。与巴豆、牵牛大略相似。性沉而降，阳中阴也。入手足阳明经。其主暴水、癥结积聚者，皆二经为病，苦能泄，辛能散，温能通行肠胃，则诸证无不除矣。\n\n【主治参与】\n《肘后方》二便关格，二三日则杀人：乌桕东南根白皮，干为末，热水服二钱。\n\n【简误】\n       水肿多属脾虚不能制水，以致水气泛滥，法当补脾实土为急，此药必不可轻用。如果元气壮实者，亦须暂施一二剂，病已即去之。', NULL, NULL, NULL, '乌桕木根皮', NULL, '19、乌桕木根皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929935, '59C9725CE304CF4B0EBAC97CAD7FD21E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7433, 420, 400106418, '     味咸，微寒。主恶毒风毒。\n\n       疏：紫真檀禀水气以生，故其味咸，气微寒，性应无毒。气味俱厚，阳中阴也。入足厥阴经。其主恶毒、风毒者，凡毒必因热而发，热甚则生风，而荣血受伤，毒乃生焉。此药咸能入血，寒能除热，则毒自消矣。弘景以之傅金疮，止血、止痛者，亦取此意耳。宜与番降真香同为极细末，傅金疮良。', NULL, NULL, NULL, '紫真檀', NULL, '18、紫真檀', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929936, 'BE02239D357B81424E3397FC32656161', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7434, 420, 400106417, '       味苦，平，无毒。主破宿血，下五淋。浓煮服之。\n\n        疏：紫荆木皮，内禀天地清寒之性，外感南方初阳之气，故其味苦，气平。花、木色皆紫，藏器言寒无毒。入足厥阴经血分。寒胜热，苦泄结，紫入荣，故能活血破血，消肿毒，下五淋也。花、梗：气味、功用并同。\n\n【主治参与】\n《仙传外科》发背初生，一切痈疽皆治：单用紫荆皮为末，酒调箍住，自然撮小不开。内服柞木饮子，乃救贫良剂也。并可内服。\n\n杨清叟《仙传方》冲和膏：治一切痈疽、发背、流注，诸肿毒。用紫荆皮三两炒，独活炒三两，赤芍药炒二两，生白术一两，木蜡炒一两，为末。用葱汤调热敷。血得热则行，葱能散气也。疮不甚热者酒调之，痛甚者加乳香。\n\n除痈毒外，他用甚稀，故无 “简误”。', NULL, NULL, NULL, '紫荆木', NULL, '17、紫荆木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929937, '6BFBE0A3B1EFC00C82A03EB042F86FD8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7435, 420, 400106416, '     味辛，温，无毒。主遗精虚漏，小便余沥，益气安神，补不足，安三焦，调诸气。夜多小便者，取二十四枚，碎，入盐同煎服，有奇验。\n\n      疏：益智子仁，得火土金之气，故其味辛，其气温，其性无毒。入足太阴、足少阴经。惟辛故所以散结，惟温故所以通行。其气芳香，故主入脾。其禀火土与金，故燥而收敛。以其敛摄，故治遗精虚漏，及小便余沥。此皆肾气不固之证也。肾主纳气，虚则不能纳矣。又主五液，涎乃脾之所统，脾肾气虚，二脏失职，是肾不能纳，脾不能摄，故主气逆上浮，涎秽泛滥而上溢也。敛摄脾肾之气，则逆气归元，涎秽下行。宜东垣用以治客寒犯胃，和中益气，及人多唾。王好古谓益智本脾家药，主君相二火。故用以益脾胃，理元气，补肾虚滑沥。刘河间又谓益智辛热，能开发郁结，使气宣通。皆以其香可入脾开郁，辛能散结，复能润下，于开通结滞之中，复有收敛之义故也。\n\n【主治参与】\n益智在集香丸则入肺，在四君子汤则入脾，在大凤髓丹则入肾。当于补药中兼用，不宜多服。\n\n佐人参、茯苓、半夏、橘皮、车前子，则摄涎秽立效。\n\n同藿香、苏子、橘皮、枇杷叶、木瓜，止逆气上壅。\n\n同五味子、山茱萸、炒盐、人参，治小便频数淋沥。\n\n同人参、干姜、橘皮、藿香，治因寒犯胃作呕吐。\n\n【简误】\n         益智乃脾肾二经之药，其用专在脾，所以亦能入肾者，辛以润之之故也。然其气芳香，性本温热，证属燥热，病人有火者，皆当忌之。故凡呕吐由于热，而不因于寒；气逆由于怒，而不由于虚；小便余沥由于水涸精亏内热，而不由于肾气虚寒；泄泻由于湿火暴注，而不由于气虚肠滑，法并忌之。', NULL, NULL, NULL, '益智子', NULL, '16、益智子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929938, '73C2967C990EDC54D9D0ADC2F7561D81', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7436, 420, 400106415, '      味辛、苦，平，有毒。主养肾气，内伤阴衰，利筋骨皮毛，疗脚弱，五藏邪气，除热。女子不可久服，令思男。\n\n       疏：石南得火金之气，故其味辛、苦，气平有毒。然观其用，当是金胜火微，其性应云有小毒。可升可降，阴中阳也。入足厥阴，足少阴经。少阴属水，得金气之厚者能生水，故主养肾气。又肾为阴中之阴，肝为阴中之阳，二经俱在下而主筋骨。二经得所养，则内伤阴衰自起，筋骨皮毛自利，而脚弱自健也。湿热之邪留滞五脏，则筋骨、皮毛、气血，皆为之病矣。邪热散，则诸病自瘳。女子久服思男者，以其补肾气，助阳火耳。\n\n【主治参与】\n同巴戟天、肉苁蓉、锁阳、鹿茸、枸杞子、山茱萸，治肾经虚寒，精滑精冷。\n\n同白蒺藜、桑叶、何首乌、淫羊藿、巴戟天、五加皮、菟丝子、威灵仙、虎骨，治肝肾为风寒湿所乘，以致痹弱不能行动。\n\n【简误】\n肾虚而阳道数举者，不宜用。脚弱由于肝肾虚，而不由于风寒湿客下部者，不宜用。\n', NULL, NULL, NULL, '石南', NULL, '15、石南', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929939, '747A6A2A02326904B72F7ABF26BEF227', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7437, 420, 400106414, '      味苦，微温，无毒。主下痢，厚肠胃，肥健人。其壳为散，及煮汁服，亦主痢。并堪染用。\n\n       疏：橡实感天地微阳之气，兼得秋时收敛之性，故其味苦，气微温，性无毒，气薄味厚，阳中阴也。入手足阳明，足太阴、少阴经。夫脾胃为五脏根本，一身之最要，喜温暖而恶寒湿，寒湿则违其性，故宜急食苦以燥之。此药味苦能除其所恶，气温能遂其所喜，故主厚肠胃，肥健人也。得收敛之性，故又主下痢，及日华子涩肠止泻诸治，兼能涩精。煮食复能止饥御歉岁。\n壳：气味与实相同，而涩则过于实。故亦主下痢。并堪染皂也。\n\n【主治参与】\n《圣惠方》水谷下痢，日夜百余行者：橡实二两，楮叶炙一两，为末。每服一钱，食前乌梅汤调下。\n\n《直指方》下痢脱肛：橡斗子，烧存性，研末，猪脂和傅。\n\n【简误】\n      湿热作痢者不宜用。', NULL, NULL, NULL, '橡实', NULL, '14、橡实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929940, '88E3E2C23661A117C43B0A34C19B7CE8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7438, 420, 400106413, '      味苦，平，无毒。止泄，除睡，强筋，益气。久服轻身，长年，令人不饥，变白去老。取茎叶捣碎渍汁，浸粳米，九浸九蒸九曝，米粒紧小，正黑如瑿珠。袋盛之，可适远方。日进一合，不饥，益颜色，坚筋骨能行。取汁炊饭，名乌饭。亦名乌草，亦名牛筋，言食之健如牛筋也。\n\n       疏：南烛禀春生之气以生，本经言其味苦气平，性无毒。然尝其味，亦多带微涩。其气平者，平即凉也。入心脾肾三经之药。十剂云：涩可去脱。非其味带涩，则不能止泄；非其气本凉，则不能变白。发者，血之余也；颜色者，血之华也。血热则鬓发早白，而颜枯槁，脾弱则困倦嗜卧而气力不长，肾虚则筋骨软弱而行步不前。入心凉血，入脾益气，入肾添精，其云轻身长年，令人不饥者，非虚语矣。凡变白之药，多是气味苦寒，有妨脾胃，惟南烛气味和平，兼能益脾，为修真家所须。\n子：味甘、酸。其功效尤胜枝叶。真变白、驻颜、轻身却老之良药也。牧童食之，辄止饥渴，亦一验矣。\n\n【主治参与】\n       孙思邈《千金月令》方：南烛煎：益髭发及容颜，兼补暖。三月三日采叶并蕊子，入大净瓶中，以童子小便浸满瓶，固济其口。置闲处，经一周年取开。每用一匙，温酒调服，极有效验。同旱莲草、没食子、地黄、桑堪、枸杞、山茱萸、何首乌、白蒺藜，为乌须发之圣药。\n\n气味和平，性复无毒，除变白外，无他用，故不著 “简误”。', NULL, NULL, NULL, '南烛枝叶', NULL, '13、南烛枝叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929941, '982FE92A6831127AADF518BB001C15E2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7439, 420, 400106412, '    味辛，大温，无毒，主下气，温中，去痰，去脏腑中风冷。\n\n     疏：胡椒禀天地纯阳之气以生，故其味辛、气大温。性虽无毒，然辛温太甚，过服未免有害。气味俱厚，阳中之阳也。入手足阳明经。其主下气，温中，去痰，除脏腑中风冷者，总因肠胃为寒冷所乘，以致脏腑不调，痰气逆上，辛温暖肠胃而散风冷，则痰气降，脏腑和，诸证悉瘳矣。\n\n【主治参与】\n《食疗》治心腹冷痛：胡椒三七枚，清酒吞之。\n\n《卫生易简方》夏月冷泻及霍乱：用胡椒碾细，饭丸梧子大，每米饮下四十丸。\n\n【简误】\n        胡椒，辛温大热纯阳之药也。凡胃冷呕逆，宿食不消，或霍乱气逆，心腹冷痛，或大肠虚寒，完谷不化，或寒痰冷积，四体如冰，兼杀一切鱼、肉、鳖、蕈等毒，诚为要品。然而血分有热，与夫阴虚发热咳嗽，吐血，咽干口渴，热气暴冲目昏，口臭，齿浮，鼻衄，肠风脏毒，痔漏泄澼等证，切勿轻饵。误服之，能令诸病即时作剧。慎之！慎之！', NULL, NULL, NULL, '胡椒', NULL, '12、胡椒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929942, '88AFBFED93577625DEB220C7531E3939', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7440, 420, 400106411, '      味甘、咸，平，无毒。主破血。产后血胀闷欲死者，水煮、苦酒煮五两，取浓汁服之效。\n \n       疏：苏方木禀水土之气以生，故其味甘咸，气平无毒。好古加辛。降多于升，阳中阴也。入足厥阴，兼入手少阴，足阳明经。凡积血，与夫产后血胀闷欲死，无非心肝二经为病。此药咸主入血，辛能走散，败浊瘀积之血行，则二经清宁，而诸证自愈。日华子主妇人血气心腹痛，月候不调，及蓐劳，排脓止痛，消痈肿，扑损瘀血，女人失音血噤。《海药》主虚劳，血癖，气壅滞，产后恶露不净，心腹搅痛，及经络不通。悉取其入血行血，辛咸消散，亦兼有软坚润下之功，故能祛一切凝滞留结之血，妇人产后，尤为所须耳。\n\n【主治参与】\n同泽兰、川芎、麦门冬、生地黄、蒲黄、人参、童便、益母草、牛膝、黑豆、荆芥穗，治产后血晕，有神。\n\n同山查、延胡索、牡丹皮、泽兰、当归、五灵脂、赤芍药、红花，治产后儿枕作痛。加入乳香、没药，治产后血癖不消，因寒而得者，加炒黑干姜，桂各少许。\n\n同延胡索、牡丹皮、牛膝、当归、地黄、芍药、续断，治妇人月候不调。煎浓汁，加入乳香、没药、血竭、自然铜、䗪虫、麻皮灰、黄荆子等末，量病轻重，调服四五钱，治跌扑损伤如神。\n\n胡氏方：产后气喘，面黑欲死，乃血入肺也，用苏木二两，水二碗，煮一碗，入人参末五钱服。随时加减，神效不可言。名参苏饮。\n\n【简误】\n产后恶露已尽，由血虚腹痛者，不宜用。', NULL, NULL, NULL, '苏方木', NULL, '11、苏方木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929943, '2C60503679CFEC25BF9936B16E295DC8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7441, 420, 400106410, '      味苦、咸，寒、微寒，有小毒。主杀三虫，逐毒气，胃气热。利丈夫，不利女子。作摩膏，除小儿百病，逐邪气恶风汗出，除皮中热，结积蛊毒，白虫寸白自出不止。久服令人阴痿。\n\n      疏：雷丸禀竹之余气，兼得地中阴水之气以生。《本经》味苦气寒。\n   \n     《别录》加咸，有小毒。黄帝、岐伯、桐君、扁鹊云甘。详其所主，应是苦咸为胜。气薄味厚，阴也，降也。入手足阳明经。其主杀三虫，白虫寸白自出者，肠胃湿热甚也。逐毒气，胃中热，邪气恶风汗出，皮中热，结积者，肠胃邪热盛也。苦寒能除二经湿热邪气，则上来诸证自除。作摩膏治小儿百病者，以小儿好食甘肥，肠胃类多湿热虫积，苦能杀虫除湿，咸寒能清热消积，故主之也。凡蛊毒必热，必辛苦寒能除辛热，故又主解蛊毒也。利丈夫，不利女子者，盖以男子属阳，得阴而生，故喜阴寒之味。女子属阴，得阳而长，故不利阴寒之物也。《别录》又云：久服令人阴痿，正见其过于苦寒，偏至之气能令阳道痿也。\n\n【主治参与】\n同芜荑、使君子、芦会、五谷虫、胡黄连、青黛，治小儿疳蛔，有神。\n\n同槟榔、鹤虱、楝根、贯众、牵牛、锡灰、薏苡根，杀肠胃一切虫。\n\n《经验方》下寸白虫：雷丸水浸去皮，切焙为末。五更初，食炙肉少许，以稀粥饮服一钱匕。须上半月服，虫乃下。\n\n除杀虫外，他用甚稀，故不著 “简误”。惟赤色者能杀人，用时细择去之。\n', NULL, NULL, NULL, '雷丸', NULL, '10、雷丸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627443975929944, '287AA92D722AC01F5D72091F6E5A3966', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 09:36:06', 1, 'admin', '2024-12-28 09:36:06');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7442, 421, 400106513, '      主疟。烧为灰，饮下之。\n\n       疏：脐者，命蒂也。当心肾之中，为真元归宿之处。胎在母腹，脐连于胞，喘息呼吸滋养之妙，从此而通。胎出母腹，脐带剪断，则一点真元之气，从此而归入命门丹田。故脐为命蒂，而脐带亦真气会聚之所也。本经以之治疟者，应是久疟虚寒之甚，借其气以补不足也。今世以小儿脱下脐带，烧灰与服，可解胎中一切毒，及免惊风痘患，亦取裨补真元耳。\n\n【主治参与】\n《全幼心鉴》脐汁不干：绵裹落下脐带，烧研一钱，入当归头末一钱，麝香一字，掺之。\n\n《保幼大全》预解胎毒：脐带烧灰，以乳汁调服。或入辰砂少许，可免痘患。\n\n无毒而主疗甚稀，不著“简误”。', NULL, NULL, NULL, '初生脐带', NULL, '13、初生脐带', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259910, 'B9977D0FAF67CFABDE1E82801D56B1D2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7443, 421, 400106512, '      主血气羸瘦，妇人劳损，面䵟皮黑，腹内诸病渐瘦瘁者，以五味和之，如䭔（饣甲）法与食之，勿令知。一名紫河车。\n\n       疏：夫人有生之初，揽父精母血以成胚胎，外即有衣一层裹之，即胞也。至十月降生时，随儿后出。其味甘咸，气温无毒。血气羸瘦，妇人劳损，面䵟皮黑，腹内诸病渐瘦瘁者，皆荣血不足，精气亏损也。此药得精血之气而结，能从其类以补之，是以主诸证也。今世以之治男女一切虚损劳极，为益血补精气之用。\n\n【主治参与】\n同人参、黄耆、鹿茸、白胶、当归、补骨脂、五味子、巴戟天，治真阳虚极，畏寒足冷。\n\n吴球大造丸：治虚劳骨蒸，女人无子，及多生女，月水不调，小产难产。服之必主有子。危疾将绝者，一二服可更活一二日，其补气血之功力可见也。久服耳目聪明，须发乌黑，延年益寿，有夺造化之功，故名大造丸。用紫河车一具，男用女胎，女用男胎，初生者，米泔洗净，淡酒蒸熟，捣晒研末。败龟板、童便浸三日，酥炙黄二两，黄檗、杜仲各一两半，牛膝一两二钱；生地黄二两半入砂仁六钱，白茯苓二两，绢袋盛入瓦罐酒煮七次，去茯苓、砂仁不用，杵地黄为膏听用，天门冬、麦门冬、人参各一两二钱净，夏月加五味子七钱，俱忌铁器，为细末，地黄膏加酒、米糊，丸小豆大。每服八九十丸，空心盐汤下。女人去龟板，加当归二两。男子遗精，女人漏下，并加牡蛎粉一两，去人参。\n\n【简误】\n人胞乃补阴阳两虚之药，以其形质亦得男妇坎离之气而成，如阴阳两虚者，服之有返本还元之功，诚为要药也。然而阴虚精涸，水不制火，发为咳嗽、吐血、骨蒸、盗汗等证，此属阳盛阴虚，法当壮水之主以制阳光，不宜服此并补之剂，以耗将竭之阴也。胃火齿痛，法亦忌之。\n\n胞衣水　味辛，无毒。主小儿丹毒，诸热毒发寒热不歇，狂言妄语，头上无辜发竖，虚痞等证。天行热病，饮之立效。此即胞衣埋地下久远化为水者，得地中之阴气，其气必寒，辛寒而走足阳明经，故主如上诸证也。南人以甘草、升麻和人胞，瓶盛埋之，三五年后掘出，取为药也。\n', NULL, NULL, NULL, '人胞', NULL, '12、人胞', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259911, '06C3601F5C21FD61C67ACEB6B8BE5AB5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7444, 421, 400106511, '      味咸，平，无毒。主传尸尸疰，鬼气伏连，久瘴劳疟，寒热无时者。烧令黑，细研，白饮和服，亦合丸散用。\n\n      疏：天灵盖，乃死人脑盖骨也。不用他骨，而用此者，以人生时，脑为诸阳之会，而此骨则一身众骨之主也。其主传尸尸疰，鬼气伏连者，取其同类之气，引出邪魅，则其魂魄飞越，不复附人，故得瘥也。久瘴劳疟，寒热无时者，亦邪恶之气侵人也。辟恶散邪是其能事，故亦主之。\n\n【主治参与】\n同鬼臼、干漆、象胆、獭肝、丹砂、胡黄连，入滋阴药内治传尸劳。\n\n同牛黄、象牙末、蛀竹屑、血竭、乳香、没药、黄蜡、明矾、真珠，作丸。治杨梅结毒。\n\n《痘疮经验方》：痘疮陷伏，灰平不长，此系虚寒证。用天灵盖烧研，酒服三分。\n\n附：化尸场上人骨，取为细末，傅金疮，止血长肉，及恶疮不收敛。并能治打扑折伤，人受杖时服之，不痛，不肿，不烂。\n\n【简误】\n       天灵盖治劳瘵者，以其有尸鬼劳虫为害，取其逐散邪也。今人虚损劳怯，皆系色欲过度，损伤真阴，实无鬼气淹伏，何得用此幽暗不祥之物治之哉？其痘疮虚寒陷伏，或为邪气所触发不出者，不过借其阳气所结之余，逐散其邪以发出耳，非正治也。若血热烦躁，疮干紫黑者，用之必致危殆不救。慎之！慎之！', NULL, NULL, NULL, '天灵盖', NULL, '11、天灵盖', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259912, 'FD3A778CE4F1E0F12C8729AA1A1767B8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7445, 421, 400106510, '      取细末，置目中去翳障。\n\n       疏：爪者，筋之余，肝胆之外候也。《经》曰：多食辛，则筋急而爪枯。以辛能散真气而走筋也。本经独用怀妊妇人者，盖妇人气血充实，乃能受孕，取其有生长力紧之意也。其味甘咸，气平无毒。目中翳障，肝经血虚也。爪甲乃肝之余气所生，而性又带散，故点目能去翳障也。寇宗奭：以众人甲，刮取细末㗜鼻内，治鼻衄立愈。兼能催生，利小便，止尿血，散乳痈等用。\n\n【主治参与】\n        《圣惠方》胞衣不下，取本妇手足爪甲，烧灰，酒服。又方，一切目疾：以木贼草擦取爪甲末，同丹砂等分，研匀，以露水搜丸芥子大。每以一粒，点入目内。或用乳汁和亦得。并治飞丝入目。', NULL, NULL, NULL, '怀妊妇人爪甲', NULL, '10、怀妊妇人爪甲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259913, '47892DEED899D56B437BE2D9A0997B56', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7446, 421, 400106509, '        解箭毒，并女劳复亦善。\n\n        妇人裈裆，主阴易病。当阴上割取，烧末服方寸匕。童女裈益佳。若女患阳易，即须男子裈也。阴易病者，人患时行，病起后交合，阴阳便即相著，甚于本病。其候小便赤涩，寒热甚，头痛，腰痛，耳鸣，眼花，服此便通利。\n\n        疏：裈裆居下体，得阴气胜，取其以类相从、气相感，能导邪热，故主阴阳易病也。\n\n【主治参与】\n          仲景方：阴阳易病，身体重，少气，腹里急，或引阴中拘急，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。取中裈近阴处，烧灰，水服方寸匕，日三服，小便即利，阴头微肿则愈。男用女，女用男。\n\n《千金方》胞衣不下，以本妇裈，覆井上即下。', NULL, NULL, NULL, '浣裈汁', NULL, '9、浣裈汁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259914, '054BA09DF12EAEF6B9E8D75A865D9AE3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', 1, 'admin', '2025-01-15 09:34:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7447, 421, 400106508, '       解箭毒，并女劳复。\n\n        陈藏器云：经衣：主金疮血涌出，炙热熨之。又烧灰傅虎狼伤疮，及箭镞毒入腹。\n\n       疏：《经》云：女子二七天癸至，任脉通，太冲脉盛，月事以时下。谓之天癸者，乃天一所生之水也。上应太阴，下应海潮，月有盈亏，潮有朝汐，故月事一月一行，与之相符也。其味咸，咸为水化，凡毒得水则解，故能解箭毒也。女劳复者，热病新瘥后交感而得。其证发热烦躁，少腹阴囊牵引而痛，以前病余热未除，阴精复损，故有是证。月水乃阴中有阳之物，能补阴除热，故主之也。金疮及虎狼伤疮，皆血分受伤为病，以类相从，乃所以补其不足也。童女首经，名红铅，能回垂绝之阳气，第一时难得耳。如女子自受胎时，算至十四岁足，即于是日是时经至者，此为正鼎，其经为上药。用法招摄，于经将至时，真气先到，采入身中，名得大药，可以接命。即《首楞经》所载精仙是也。绝非入炉交感，亦非情想得通，故亦成仙道耳。\n\n【主治参与】\n扁鹊方：丈夫热病后，交接复发，忽卵缩入腹，腹痛欲死。烧女人月经赤衣为末，热水服方寸匕，即定。并治女劳色疸。\n\n《千金方》男子阴疮，因不忌月事行房，阴物溃烂：用室女血衲，瓦上烧存性，研末，麻油调傅。\n\n《博物志》：交广夷人，以焦铜和毒药于箭镞上，中人即沸烂，须臾骨坏而死。但服月水、屎汁解之。\n\n【简误】\n         月水虽能治病，然秽污不洁之物，故女子入月时，人宜远之。其升丹煎膏治药，及小儿出痘，切须避忌。如犯之，则药不灵，痘变坏也。红铅，其性质乃阳气凝结而成，火盛人不宜单服，须多服人乳，并入童溺乃佳。', NULL, NULL, NULL, '妇人月水', NULL, '8、妇人月水', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259915, '62BC4D2FE24AD8268BFADCD3CA736DCD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7448, 421, 400106507, '     疗鼻衄，汤火灼疮。\n \n     疏：溺白垽，即人中白，乃人溺之积气结成。其味咸，气凉，无毒，能泻肝、肾、三焦、膀胱有余之火。本经疗鼻衄。及大明治传尸劳热，肺痿，心膈热，吐血，羸瘦，渴疾者，以其能入诸经泻去火邪也。凉能除热，故又治汤火灼疮。今人以之治口舌生疮，疳䘌等证，多效，是其除热降火之验也。\n\n【主治参与】\n同冰片、硼砂、青黛、黄檗、牙硝、白矾，治口舌生疮，及小儿走马牙疳口臭。\n\n《经验方》鼻衄不止：人中白焙干，入麝香少许，温酒调服，立效。\n\n又方，小儿口疳：人中白煅，黄檗蜜炙焦，为末，等分，入冰片少许，以青布拭净，掺之，累效。\n', NULL, NULL, NULL, '溺白垽', NULL, '7、溺白垽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259916, '0844EADF1AAB4389FD558F8FE1388ECA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7449, 421, 400106506, '     疗寒热头疼温气。童男者尤良。\n\n     疏：人溺，乃津液之浊者，渗入膀胱而出。其味咸，气寒无毒，为除劳热骨蒸，咳嗽吐血，及妇人产后血晕闷绝之圣药。晋・褚澄《劳极论》云：降火甚速，降血甚神，饮溲溺百不一死，服凉药百不一生。言其功力之优胜也。《经》云：饮入于胃，游溢精气，上输于脾，脾气散精，上归于肺，通调水道，下输膀胱。故人服小便入胃，亦随脾之气上归于肺，下通水道而入膀胱，乃循其旧路也。故能治肺病引火下行。凡人精气，清者为血，浊者为气，浊之清者为津液，清之浊者为小便，与血同类也。故其味咸而走血，咸寒能伏虚热，使火不上炎而血不妄溢，是以能疗诸血证也。苏恭：主久嗽上气，失声。及日华子止劳渴，润心肺，疗血闷热狂，扑损瘀血在内晕绝，止吐血，鼻衄，皮肤皴裂，难产，胞衣不下诸证，悉由此故。本经主寒热头疼温气者，咸寒能除邪热故耳。法当热饮，热则于中尚有真气在，其行自速，冷则惟存咸味、寒性矣。\n\n【主治参与】\n同枇杷叶、天门冬、麦门冬、苏子、桑白皮、沙参、五味子、生地黄、款冬花、百部，治阴虚咳嗽声哑，喉间血腥气。\n\n同苏木、番降香、续断、牛膝、牡丹皮、蒲黄，治内伤吐血，或瘀血停留作痛。\n\n同泽兰、荆芥、白芷、续断、延胡索、牛膝、苏木、黑豆，治产后血晕，虚者加人参。\n\n凡产后温饮一杯，可免血晕，至三日后止之。\n\n中暍昏倒，以热小便灌下即活。\n\n《圣济总录》头痛至极：童便一盏，豉心半合，同煎至五分，温服。\n\n孟诜《必效方》骨蒸发热：童便五升，煎取一升，以蜜三匙和之。每服二碗，半日更服。此后常服自己小便，轻者二十日，重者五十日瘥。\n\n《圣惠方》绞肠痧痛：童便乘热服之，即瘥。\n\n仲景方：中暑昏闷，夏月在途中热死，急移阴处，就掬道上热土，拥脐上作窝，令人溺满，暖气透脐即苏。乃服地浆、蒜水等药。\n\n《千金方》金疮出血不止，饮人尿五升。\n\n《外科发挥》折伤跌扑，童便入少酒饮之，推陈致新，其功甚大。\n\n《千金方》火烧闷绝，不省人事者，新尿顿服二三升良。\n\n《通变要法》人咬手指，瓶盛热尿浸一宿，即愈。\n\n《普济方》赤眼肿痛。自己小便乘热抹洗，即闭目少顷。此以咸寒内有真气，故能退去邪热也。\n\n【简误】\n        人溺滋阴降火，除骨蒸，解劳乏，治诸吐衄，咯血唾血，其效甚速。《褚澄遗书》云：人喉有窍则咳血杀人。喉不停物，毫发芥蒂必咳，血既渗入，愈渗则愈咳，愈咳愈渗，惟饮溲溺则百不一死。若服寒凉则百不一生。其为肺肾有火者必须之物。第其性稍寒，惟不利于脾胃虚寒，或溏泄，及阳虚无火食不消者，咸在所忌。今世人类用秋石，此乃水澄火炼，真元之气尽失，其功不逮童便多矣。况难多服，久服则咸能走血，使血凝泣为病。', NULL, NULL, NULL, '人溺', NULL, '6、人溺', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259917, '0AAB3ED46A3FE354E9670D40ADA6EB7B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7450, 421, 400106505, '     寒。主疗时行大热狂走，解诸毒。宜用绝干者，捣末，沸汤沃服之。\n\n      疏：人之五谷入胃，津液上升为气血，糟粕下降而成粪。其本原以化过，但存极苦大寒之气味耳。入足阳明经。《经》曰：阳明实热，则登高而歌，弃衣而走。苦寒能除阳明之热，故疗时行大热狂走也。凡毒必热必辛，苦寒能除辛热，故又主解诸毒也。苏恭云：新者封疔肿，一日根烂。盖疔肿乃风火之毒气结成，得大寒极苦之气，则风火散，根自烂也。今世人又以之治痘疮血热，紫黑倒靥者，殊效。\n粪清：腊月截淡竹，去青皮，塞口，纳粪坑中，积年得汁，甚黑而苦。主天行热狂，热疾，中恶，蕈毒，恶疮，瘟病垂死者，皆瘥，一名黄龙汤，俗名金汁。\n\n人中黄：即多年厕坑中，砖上所凝结黄垽是也。药性治疗大约与人屎同，解胃家热毒有效。\n\n【主治参与】\n《斗门方》热病发狂，奔走似癫，如见鬼神，久不得汗，及不知人事者：以人中黄入大罐内，以泥固济，煅半日，去火毒，研末。新汲水服三钱。未退再服。\n\n寇宗奭《衍义》大热狂渴：干陈人屎，为末，于阴地净黄土中作五六寸小坑，将末三两匙于坑中，以新汲水调匀，良久澄清，细细与饮，即解。\n\n《儒门事亲》四灵无价散：治痘疮黑陷，腹胀危笃者，此为劫剂。用人粪、猫粪、猪犬粪等分，腊月初旬收埋高燥黄土窖内，至春取出，砂罐盛之，盐泥固济，炭火煅，令烟尽为度。取出为末，入麝香少许，研匀，瓷器密封收之，一岁一字，二岁半钱，三岁一钱，蜜水调下，须臾疮起。\n\n《千金方》疔肿初起：刮破，以热屎傅之，干即易。\n\n又方，五色丹毒：黄龙汤饮二合，并涂之良。\n\n陶弘景：解药箭毒，交广夷人用焦铜为箭镞，更以毒药物汁渍之，射人才伤皮便死。惟饮粪汁即解。\n\n【简误】\n       伤寒、温疫，非阳明实热者不宜用。痘疮，非火热郁滞，因而紫黑干陷倒靥者，不宜用，以其苦寒之极耳。', NULL, NULL, NULL, '人屎', NULL, '5、人屎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259918, '16A9652D939D3A2DDC42BA40517C2C1C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7451, 421, 400106504, '    平。除劳，治疟，蛊毒气。入药烧用。\n\n     疏：牙齿者，肾之标，骨之余也。《经》云：男子三八肾气平，而真牙生；五八肾气衰，而齿槁。以肾主骨故也。其味甘咸，气热有小毒。其主除劳治疟者，盖劳乃劳极精气乏绝，肾家亏损所致也。齿牙为肾气所生，以类相从，适还其本，故主之也。疟亦因劳而发，非夏伤暑、秋为疟之比，故亦主之。味甘而咸，所以能解蛊毒气也。今世又以之治痘疮倒靥、乳痈未溃，为必须之药。\n\n【主治参与】\n钱氏《小儿方》痘疹倒靥：人牙烧存性，入麝香少许，温酒服半钱。\n\n闻人规《痘疹论》人牙散：治痘疮方出，为风寒外袭，或变黑，或青紫，此倒靥也。宜温肌发散，使热气复行而斑自出。用人牙不拘多少，瓦罐固济，煅过，出火毒，研末。出不快而黑陷者，獖猪血调下一钱；因误服凉药，血涩倒陷者，入麝香，温酒服之，其效如神。\n\n《肘后方》乳痈未溃：人牙齿烧研，酥调敷之。\n\n《直指方》阴疽不发，头凹沉黯，不疼无热，内服补散不起，用人牙烧过，穿山甲炙，各一分，为末。分作二服，用当归、麻黄煎汤下。外以姜汁和面傅之。\n\n【简误】\n          近世用人牙治痘疮陷伏，称为神品。然一概用之，贻害不浅。夫齿者，肾之标，骨之余也。痘疮则毒自肾出，方长之际，外为风寒秽气所冒，腠理闭塞，血涩不行，毒不能出，或变黑倒靥，宜用此以酒、麝达之，窜入肾经，发出毒气，使热令复行，而疮自红活，盖劫剂也。若伏毒在心，昏冒不省人事，及气虚色白痒塌，不能作脓，热沸紫泡之证，止宜解毒补虚。苟误用此，则郁闷声哑，反成不治之证，可不慎哉！其除劳治疟，本经虽言之，今世亦稀用。', NULL, NULL, NULL, '人牙齿', NULL, '4、人牙齿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259919, 'EB1CD26E74C6772F96B1F03FE8770A7E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7452, 421, 400106503, '     主淋闭不通。（梳上者，名百齿霜。）\n \n      疏：头垢，头上垢腻也。其性滑润而下走，故本经主淋闭不通，及弘景疗噎疾。其味苦温，能走阳明，故又主劳复，及妇人吹乳也。\n\n【主治参与】\n同白芷、贝母、半夏为丸，酒下。治妇人吹乳。\n\n同山茨菰、橘叶、鼠粪、人爪、蒲公英、柴胡、山豆根、白芷、连翘、贝母、夏枯草、忍冬藤，治乳岩、乳痈，神效。\n\n《类要方》天行热病后劳复：含头垢枣核大一枚，良。\n\n《外台秘要》预防劳复：伤寒初愈，欲令不劳复者，头垢烧研，水丸梧子大，饮服一丸。\n\n《卫生宝鉴》妇人吹乳：百齿霜，以无根水丸梧子大，每服三丸。\n\n数条之外无别用，故不著 “简误”。', NULL, NULL, NULL, '头垢', NULL, '3、头垢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259920, 'A3F31EB19AE0E43A8DF91C146B474ABC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7453, 421, 400106502, '     主补五藏，令人肥白悦泽。（《唐本》注：疗目赤痛多泪，解独肝牛肉毒，合豉浓汁饮之，神效。）\n\n      疏：人乳乃阴血所化，生于脾胃，摄于冲任，未受孕则下为月水，既受孕则留而养胎，已产则赤变为白，上为乳汁。此造化玄微之妙，人身转运之神也。其味甘，气平无毒。入心、入肾、入脾、润肺，益寿延年之圣药也。气血之液，故能补五脏，五脏得补，则气血充实而体自肥白悦泽也。《经》曰：目得血而能视。乳为血化，故能疗目赤痛多泪，甘能解毒，故又主解独肝牛肉毒也。\n\n【主治参与】\n《摄生众妙方》接命丹：治男妇气血衰弱，痰火上升，虚损之证；又治中风瘫痪，手足疼痛，不能动履等证。用人乳二杯，香甜白者为佳，以好梨汁一杯，和匀，银石器内顿滚。每日五更一服，能消痰补虚，生血延寿。此以人补人之妙法也。《圣惠方》眼热赤肿：人乳半合，古文钱十文，铜器中磨令变色，稀稠成煎，瓶收，日点数次。或以乳浸黄连，蒸热洗之。\n\n《万氏家抄方》一切虚损劳证，太乙神应丸：人乳一碗，磁器煮干焙燥，牛乳一碗，同前制，杜仲三两，破故纸二两半，白鲜皮、白茯苓、牛膝、当归各二两，黍米金丹一个晒干，即初生儿口中血珠，共为末，蜜丸桐子大。每服一丸，夜间噙化。\n\n【简误】\n       乳属阴，其性凉而滋润，血虚有热，燥渴枯涸者宜之。若脏气虚寒，滑泄不禁，及胃弱不思食，脾虚不磨食，并不宜服。', NULL, NULL, NULL, '人乳汁', NULL, '2、人乳汁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259921, '2061BB02A2C881DFE6AFC80FFAC1FABA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7454, 421, 400106501, '     味苦，温、小寒，无毒。主五癃关格不通，利小便水道，疗小儿痫，大人痉。仍自还神化。合鸡子黄煎之，消为水，疗小儿惊热。（雷斅云：是男子二十已来无疾患，颜色红白，于顶心剪下者。入丸药膏中用，先以苦参水浸一宿，漉出，入瓶子以火煅赤，放冷研用。）\n\n      疏：发者，血之余也。《经》曰：男子八岁，肾气盛，齿更发长。是发因人之血气以为生长荣枯也。故血盛之人则发润而黑，血枯之人则发燥而黄。《本经》用发髲之意，为是故尔。其味苦气温。《别录》小寒，无毒。入手足少阴经。大人痉，小儿惊痫，皆心肝二经血虚而有热也。发为血之余，故能入心、入肝益血。微寒而苦又能泄热，所以疗小儿惊痫及大人痉也。心与小肠为表里，肾与膀胱为表里，心肾有热则二腑亦受病。此药能入心除热，入肾益阴，则水道利，五癃关格俱通矣。是以古人治惊，多用茯苓、琥珀、竹叶之类，取其分利心经之热自小肠出也。日华子主止血闷血晕，金疮伤风，及煎膏长肉消瘀血者，悉取其入心走肝，益血除热之功耳。自还神化之事，未见别方，大抵以火煅之，复化而凝成血质，此即自还神化之谓。是因血而生，复还为血，非神化而何？\n\n       乱发：微温。主咳逆，五淋，大小便不通，小儿惊痫，止血。鼻衄，烧之吹内立已。\n\n       疏：乱发即常人头上堕下者。其气味所主，与发髲相似，第其力稍不及耳。以发髲一时难得，故《别录》重出此条，以便临时取用。疗体实不甚相远也。\n\n【主治参与】\n《和剂局方》肠风黑散：治肠风泻血，用乱发一两半，荆芥二两，槐花、槐角各一两，以上共煅为末。枳壳、甘草各一两半，为末，和前末匀。每服二钱，水一盏，煎七分，空心服，温酒调下亦得。\n\n刘禹锡《传信方》孩子热疮：乱发一团如梨子大，鸡子黄十个煮熟，同于铫子内熬至甚干，始有液出，旋置盏中，液尽为度。用敷疮上，外即以苦参粉掺之，神效。\n\n又方，小儿断脐，即用清油调发灰傅之，不可伤水。脐湿不干，亦傅之效。\n\n《千金方》小儿惊啼：乱油发烧研，乳汁或酒服少许，良。\n\n《圣惠方》鼻血不止：血发烧灰，吹之。\n\n又方，诸窍出血：头发、败棕、陈莲蓬，并烧灰，等分。每服三钱，童便、温酒调下。\n\n《妇人良方》女人漏血：乱发洗净，烧研，空心温酒服一钱。\n\n入诸膏药内，能消毒止痛，长肉生肌。\n\n《肘后方》女劳黄疸，膏发煎：用猪膏半斤，乱发鸡子大三团，和煎，发消药成矣。分再服，病从小便中出也。\n\n【简误】\n           发灰，走血分而带散。其主诸血证，亦是血见灰则止，取其治标之义居多。若欲全仗其补益，未必能也。经熬煅成末后，气味不佳，胃弱者勿服。入外科药殊有神效。', NULL, NULL, NULL, '发髲', NULL, '1、发髲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627454084259922, '77B74035B79E326854EA3014B44C8C02', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 10:17:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7455, 422, 400106611, '     微寒。补五脏，利大肠，主口疮。\n\n      疏；酥乃牛乳所出，乳之精华也。其味甘，气微寒无毒。性滑泽。五脏皆属阴，酥乃阴血之精华，故能补五脏。血枯火盛，大肠燥结，乃口舌生疮，甘寒除热补血，故主利大肠、口疮也。\n\n     按：酥酪醍醐，总成于牛乳，但有精粗之别耳。其性大抵皆滋润滑泽，宜于血热枯燥之人。其功不甚相远，故二物不复载。\n\n【主治参与】\n       凡一切药，用酥炙者，取其润燥兼能益精髓，补血脉，又有渗入骨肉，使骨易糜之功。《外台秘要》；一切肺病咳嗽，脓血不止。用好酥五十斤，炼三遍，当出醍醐。每服一合，日三服，以瘥为度，神效。\n\n【简误】\n性能利窍，骤食之使人遗精。', NULL, NULL, NULL, '酥', NULL, '11、酥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881094, '2D43B5837EDBA831516F4AAB6CE66094', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7456, 422, 400106610, '      味甘，微寒，无毒，主润五脏，利大小便，益十二经脉。\n\n      疏：牛乳，乃牛之血液所化，其味甘，其气微寒，无毒，甘寒。能养血脉，滋润五脏，故主补虚羸止渴。及乳腐所主皆同也。日华子主养心肺，解热毒，润皮肤者，亦此意耳。\n\n      肝：味苦、甘，气和平，食之能补肝，治雀盲。\n\n【主治参与】\n同人乳、羊乳、梨汁、芦根汁、蔗浆，熬膏，治反胃噎膈，大便燥结。宜时时饮之，兼能止消渴。\n\n夏子益《奇疾方》肉人怪病：人顶生疮，五色如樱桃状，破则自顶分裂，连皮剥脱至足，名曰肉人。常饮牛乳自消。\n\n【简误】\n        患冷气人忌之，与酸物相反，令人腹中癥结。脾胃作泄者，亦不得服。', NULL, NULL, NULL, '乳腐', NULL, '10、乳腐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881095, '9A9152D09E996EA44EC04E6EB2EF1C09', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7457, 422, 400106609, '     微寒。补虚羸，止渴。\n\n      酥   微寒。补五脏，利大肠，主口疮。\n\n     疏：酥乃牛乳所出，乳之精华也。其味甘，气微寒无毒，性滑泽。五脏皆属阴，酥乃阴血之精华，故能补五脏。血枯火盛，大肠燥结，乃口舌生疮，甘寒除热补血，故主利大肠、口疮也。\n\n按：酥酪醍醐，总成于牛乳，但有精粗之别耳。其性大抵皆滋润滑泽，宜于血热枯燥之人。其功不甚相远，故二物不复载。\n\n【主治参与】\n       凡一切药用酥炙者，取其润燥兼能益精髓，补血脉，又有渗入骨肉，使骨易糜之功。\n\n《外台秘要》一切肺病咳嗽，脓血不止。用好酥五十斤，炼三遍，当出醍醐。每服一合，日三服，以瘥为度，神效。\n\n【简误】\n    性能利窍，骤食之使人遗精。', NULL, NULL, NULL, '牛乳', NULL, '9、牛乳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881096, '2009A9DAD0D68B1DEF43F9336F82032A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7458, 422, 400106608, '      味甘，平、微温，无毒。主心腹内崩，劳极洒洒如疟状，腰腹痛，四肢酸疼，女子下血，安胎，丈夫小腹痛，虚劳羸瘦，阴气不足，脚酸不能久立，养肝气。久服轻身益气。一名傅致胶。（得火良，薯蓣为之使。畏大黄。凡用以蛤粉炒，或酒化成膏亦得。）\n\n       疏：阿胶，旧云煮牛皮作之。藏器与苏颂皆云是乌驴皮，其说为的。其功专在于水。按阿井在山东兖州府东阿县，乃济水之伏者所注，其水清而重，其色正绿，其性趋下而纯阴，与众水大别。\n\n   《本经》味甘气平。《别录》微温无毒。元素云：性平味淡。气味俱薄。可升可降，阳中阴也。入手太阴，足少阴、厥阴经。其主女子下血，腹内崩，劳极洒洒如疟状，腰腹痛，四肢酸疼，胎不安，及丈夫少腹痛，虚劳羸瘦，阴气不足，脚酸不能久立等证。皆由于精血虚，肝肾不足，法当补肝益血。\n\n     《经》曰：精不足者，补之以味。味者，阴也。补精以阴，求其属也。此药得水气之阴，具补阴之味，俾入二经而得所养，故能疗如上诸证也。血虚则肝无以养，益阴补血，故能养肝气。入肺肾补不足，故又能益气，以肺主气，肾纳气也。气血两足，所以能轻身也。今世以之疗吐血、衄血、血淋、尿血、肠风下血、血痢、女子血气痛、血枯、崩中、带下、胎前产后诸疾，及虚劳咳嗽。肺痿，肺痈脓血杂出等证神效者，皆取其入肺入肾，益阴滋水，补血清热之功也。\n\n【主治参与】\n同天、麦门冬、栝楼根、白药子、五味子、桑白皮、剪草、生地黄、枸杞子、百部、苏子、白芍药，治肺肾俱虚，咳嗽吐血。\n\n同杜仲、枸杞子、白芍药、山药、麦门冬、地黄、黄耆、人参、青蒿、续断、黄檗，治妇人崩中漏血。\n\n同白芍药、炙甘草、麦冬、地黄、白胶、当归、枸杞子、杜仲、续断，治妇人胎痛，或胎漏下血。\n\n《直指方》老人虚秘：阿胶炒二钱，葱白三根，水煎化，入蜜二匙，温服。\n\n仲景方：黄连阿胶汤，治少阴病，得之二三日以上，心中烦，不得卧者。用阿胶三两，黄连四两，黄芩一两，芍药二两，鸡子黄二枚，以水五升，先煮三物，取二升，去滓，内胶烊尽，小冷，内鸡子黄，搅令相得。温服七合，日三。《和剂局方》治肠胃气虚，冷热不调，下痢赤白，里急后重腹痛，小便不利，用阿胶二两炒，黄连三两，茯苓二两，为末，捣丸梧子大。每服五十丸，米汤下，日三。\n\n《千金翼》吐血不止：阿胶炒二两，蒲黄六合，生地黄三两，水五升，煮三升，分服。兼治衄血。\n\n《梅师方》妊娠下血不止：阿胶三两炙为末，酒一升煎化，服即愈。\n\n《产宝方》胶艾汤：妊娠胎动，阿胶、艾叶各二两，葱白一升，水四升，煮一升，分服。\n\n【简误】\n      此药多伪造，皆杂以牛马皮、旧革鞍靴之类，其气浊秽，不堪入药。当以光如瑿漆，色带油绿者为真。真者折之即断，亦不作臭气，夏月亦不甚湿软。如入调经丸药中，宜入醋，重汤顿化和药。其气味虽和平，然性粘腻，胃弱作呕吐者，勿服。脾虚食不消者，亦忌之。', NULL, NULL, NULL, '阿胶,傅致胶', NULL, '8、阿胶,傅致胶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881097, 'A5A0C5C02BA055EF74930019DFA6F9BA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7459, 422, 400106607, '      味甘，平、温，无毒。主伤中，劳绝，腰痛，羸瘦，补中益气，妇人血闭无子，止痛安胎。疗吐血下血，崩中不止，四肢酸疼，多汗淋露，折跌伤损。久服轻身延年。一名鹿角胶。（得火良，畏大黄。）\n\n       疏：白胶是熬鹿角而成，故其味甘，气平。《别录》温，无毒。气薄味厚，降多升少，阳中之阴也。入足厥阴、少阴，手少阴、厥阴经。经曰：劳则喘且汗出，内外皆越，中气耗矣。故凡作劳之人，中气伤绝，四肢作痛多汗，或吐血下血，皆肝心受病。此药味甘气温，入二经而能补益中气，则绝伤和，四肢利，血自止，汗自敛也。折跌伤损，则血瘀而成病，甘温入血通行，又兼补益，故折跌伤损自愈。妇人血闭无子，乃崩中淋露，胎痛不安，腰痛羸瘦者，皆血虚肝肾不足之候。温肝补肾益血，则诸证自退而胎自得所养也。血气生，真阳足，故久服能轻身延年耳。更治尿血，溺精，疮疡肿毒及漏下赤白。妇人久服，能令有子。\n\n【主治参与】\n同牛膝、牡丹皮、麦门冬、地黄、真苏子、郁金、白芍药、当归、童便、续断，治劳伤吐血。\n\n同山茱萸、枸杞子、鹿茸、地黄、麦冬、杜仲、补骨脂、怀山药、车前子、五味子、巴戟天、莲须，治肾虚阳痿，精寒无子。加入当归、紫石英，治妇人血闭，子宫冷，服之受孕。\n\n《外台秘要》虚劳尿精及尿血：白胶二两炙，酒二升，顿和温服。\n\n《肘后方》妊娠卒下血：以酒煮胶二两，消尽顿服。\n\n【简误】\n         鹿乃仙兽，纯阳之物也。其治劳伤羸瘦，益肾添精，暖腰膝，养血脉，强筋骨，助阳道之圣药也。然而肾虚有火者，不宜用，以其偏于补阳也。上焦有痰热，及胃家有火者，不宜用。以其性热复腻滞难化也。凡吐血下血，系阴虚火炽者，概不得服。', NULL, NULL, NULL, '白胶,鹿角胶', NULL, '7、白胶,鹿角胶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881098, 'EDDEE02E384CD8D9713F1BD2C62B11AD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7460, 422, 400106606, '       主明目，及治疳，治疮肿。以水化涂之。治口臭，以绵裹少许贴牙根，平旦漱去，数度即瘥。\n\n        疏：象胆，苦寒之物也。入肝脾二经，肝热则目不明。脾家郁热则成疳积，或口臭。苦寒除二经之热，故能主诸证。苦寒凉血解毒，故又能主疮肿也。今世治疳证、痨瘵、传尸多用之，总取其苦寒能杀疳虫痨虫，兼除脏腑一切热结也。\n\n【主治参与】\n同獭肝、芦会、干漆、胡黄连、青黛、鬼臼、丹砂，入滋肾药内，治传尸痨瘵。\n\n《圣济总录》内障目翳：用象胆半两，鲤鱼胆七枚，熊胆一分，牛胆半两，麝香一分，石决明一两，为末，糊丸绿豆大。每茶下十丸，日二。\n\n象皮：其性最易收敛，人以钩刺插入皮中，拔出半日，其疮即合，故入膏散，为长肉合金疮之要药。\n\n【简误】\n       象胆苦寒之极，不利脾胃。凡疳证脾弱者，目', NULL, NULL, NULL, '象胆', NULL, '6、象胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881099, 'FA74E909CD00F2C3D3DAD35A0B07A774', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7461, 422, 400106605, '      无毒。主诸铁及杂物入肉，刮取屑，细研，和水傅疮上，立出。\n\n      疏：象牙，本经无气味。日华子云平，《海药》云寒。应是甘寒无毒之物。象性勇猛，而牙善蜕，故能出一切皮肉间有形滞物，如经所言也。又能治邪魅惊悸风痫，及恶疮拔毒，长肉生肌，去漏管等用。\n\n【主治参与】\n同明矾、黄蜡、牛角䚡、铅花、金头蜈蚣、猬皮、猪悬蹄，治通肠漏，能去漏管。\n\n防杨梅结毒，载牛黄条内。\n\n王氏《痘疹方》痘疹不收：象牙屑，铜铫炒黄红色，为末。每服七八分，白汤下。\n\n又方，针箭入肉。象牙末，水和傅之，即出也。\n\n日华子：治小便不通，象牙生煎服之。小便过多，烧灰饮下。', NULL, NULL, NULL, '象牙', NULL, '5、象牙', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881100, 'EF3EE71A538FFADFD876EFF6B8457DB7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7462, 422, 400106604, '       味甘，微寒、微温，无毒。主风痹不仁筋急，五藏腹中积聚，寒热羸瘦，头疡白秃，面皯皰，食饮吐呕。久服强志，不饥，轻身长年。\n\n       疏：《诗》云：惟熊惟罴，男子之祥。取其为阳兽而强力壮毅也。\n\n     《本经》味甘，气微寒。《别录》微温无毒。其主风痹不仁筋急者，盖风为阳邪，熊为阳兽，其气温，能通行经络，其性润，能滋养肝脾，故主之也。滑泽而通行，故主五脏腹中积聚，及食饮吐呕。甘寒而强力，故能主寒热羸瘦，轻身。性润而疏风，故能主头疡白秃，面皯皰也。久服强志，不饥长年，甚言其补虚壮筋骨之功耳。\n\n熊掌，乃八珍之一，食之可御风寒，益气力。肉与脂同功。河间云：熊肉振羸。是因其气有余，以补不足者也。\n\n熊胆   味苦，寒，无毒。疗时气热盛变为黄疸，暑月久痢，疳䘌，心痛疰忤。（《药性论》：小儿五疳，杀虫治恶疮。）\n\n疏：熊胆气味与象胆同。其所主亦相似。时气热盛变为黄疸，热邪在足太阴也。久痢，疳䘌，湿热在手阳明也。心痛疰忤，热邪在手少阴也。入三经而除热邪，故能疗诸证也。极苦而寒，故又能杀虫，治恶疮，点痔。\n\n【主治参与】\n《齐东野语》赤目障翳：熊胆丸以胆少许化开，入片脑一二厘，研匀，点上绝妙。\n\n《圣惠方》小儿鼻蚀：熊胆半分，汤化抹之。\n\n《外台秘要》十年痔疮。熊胆涂之，神效。一切方不及也。或加入片脑少许，以猪胆汁和涂，亦妙。\n\n《保幼大全》诸疳羸瘦：熊胆、使君子末，等分研匀，瓷器蒸溶，蒸饼丸麻子大。每米饮下二十丸。\n\n【简误】\n        凡胆，皆极苦寒而能走肝胆二经，泻有余之热，盖以类相从也。小儿疳积，多致目内生翳障者，以肝脾二脏邪热壅滞，则二脏之气血日虚，闭塞日甚故也。用此泻肝胆脾家之热，则内邪清而外障去矣。如不因疳证而目生翳障，及痘后蒙闭者，多因肝肾两虚，宜滋阴养血清热为急，诸胆皆不得用。有痼疾者，不可食熊肉，令终身不愈。\n', NULL, NULL, NULL, '熊脂', NULL, '4、熊脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881101, 'F75267DF754E858062192E0C4BB9B866', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7463, 422, 400106603, '     味苦，平，有小毒。主惊痫寒热，热盛狂痉，除邪逐鬼。疗小儿百病，诸痫热口不开，大人狂癫，又堕胎。久服轻身增年，令人不忘。（人参为之使。恶常山。畏牛膝、干漆。）\n\n      疏：牛为土畜，其性甘平，惟食百草，其精华凝结为黄，犹人身之有内丹也。故能解百毒而消痰热，散心火而疗惊痫，为世神物，诸药莫及也。凡牛生黄，则夜视其身有光，皮毛润泽，眼如血色，盖得气之精而形质变化自有异也。或云牛病乃生黄者，非也。\n     \n     《本经》味苦气平。《别录》有小毒。吴普云无毒。然必无毒者为是。入足厥阴、少阳，手少阴经。其主小儿惊痫，寒热热盛口不能开，及大人癫狂痫痉者，皆肝心二经邪热胶痰为病。心热则火自生焰，肝热则木自生风，风火相搏，故发如上等证。此药味苦气凉，入二经而能除热消痰，则风火息，神魂清，诸证自瘳矣。鬼邪侵着，因心虚所致。小儿百病多属胎热，入心养神，除热解毒，故悉主之也。性善通窍，故能堕胎。善除热益心，故能令人不忘。非久服多服之药。其云轻身延年者，盖指病去则身自轻安，而得尽其天年也。\n\n【主治参与】\n同犀角、琥珀、天竺黄、钩藤钩、茯神、真珠、金箔、麝香、丹砂，治小儿惊痫百病。\n\n入外科内服药，能解疔肿痈疽毒。并可入傅药，止痛散毒如神。\n\n同犀角、生地黄、牡丹皮、竹叶、麦门冬，治小儿五色丹毒。\n\n同钟乳石、真珠、猪牙皂角、象牙末、白僵蚕、红铅、片脑、明矾、没药、蛀竹屑、天灵盖，为丸。土茯苓汤下，治结毒有神。\n\n姚和众方：小儿初生三日，去惊邪，辟恶气：以牛黄一豆许，以蜜少许，研匀，绵蘸令儿吮之，一日令尽。\n\n《外台秘要》小儿七日口噤：牛黄为末，以淡竹沥化一字，灌之。更以猪乳滴之。\n\n钱氏《小儿方》初生胎热，或身体黄者，以真牛黄一豆大，入蜜调膏，乳汁化开，时时滴儿口中。兼治腹痛夜啼。\n\n《总微录》小儿热惊，或惊痫嚼舌，迷闷仰目：牛黄一杏仁大，竹沥、姜汁各一合，和匀与服。\n\n又方，小儿积热毛焦，睡语、欲发惊者：牛黄六分，朱砂五钱，同研。以犀角磨汁，调服一钱。\n\n王氏《痘疹方》痘疮黑陷：牛黄二粒，朱砂一分，研末。蜜浸胭脂，取汁调搽，并可内服。\n\n【简误】\n         牛黄，治小儿百病之圣药。盖小儿禀纯阳之气，其病皆胎毒痰热所生，肝心二经所发。此药能化痰除热，清心养肝，有起死回生之力。惟伤乳作泻、脾胃虚寒者，不当用。', NULL, NULL, NULL, '牛黄', NULL, '3、牛黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881102, '27E5AC061E95010A76289C4D50503689', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7464, 422, 400106602, '       味辛，温，无毒。主辟恶气，杀鬼精物，温疟，蛊毒，痫痉，去三虫，疗诸凶邪鬼气，中恶心腹暴痛，胀急痞满，风毒，妇人难产，堕胎，去面䵴（音孕），目中肤翳。久服除邪，不梦寤魇寐，通神仙。（忌大蒜。）\n\n      疏：陶弘景云：麝常食柏叶，又啖蛇。予以为其香必非因啖蛇而结。\n\n      苏颂乃云：夏月食蛇多，至寒则香满，入春脐内急痛，自以爪剔出。\n    \n      陶云：五月得香，往往有蛇皮骨，岂有食蛇逾一年，而皮骨尚不化者乎？不知麝乃山兽，好食香木芳草，如柏叶之类，故其气聚于脐，而结成是香。或遇蛇亦啖，但不结香耳。如必啖蛇多而后有香，则此药必大毒难近之物，安得味辛气温无毒耶？\n\n      甄权言苦辛，其香芳烈，为通关利窍之上药。凡邪气着人，淹伏不起，则关窍闭塞，辛香走窜，自内达外，则毫毛骨节俱开，邪从此而出。故主辟恶气，杀鬼精物凶邪，蛊毒，温疟，中恶心腹暴痛，胀急痞满，风毒诸证，其主痫痉者，借其气以达于病所也。苦辛能杀虫，故主去三虫。辛温主散，故能去面䵴，及目中肤翳。性能开窍，故主难产堕胎也。走窜之性，而云久服除邪，不梦寤魇寐，通神仙者，凡香皆能辟除恶气而通神明，故有是功能也。\n\n         日华子云：纳子宫，暖水脏，止冷带疾。\n\n        《药性论》主小儿惊痫客杵，蚀一切痈疽脓水。今人又以治中风、中气、中恶、痰厥猝仆。兼入膏药、傅药，皆取其通窍开经络、透肌骨之功耳。\n\n【主治参与】\n同犀角、牛黄、琥珀、龙齿、远志、丹砂、铅丹、金箔、菖蒲、真珠、茯神、天竺黄，治心气虚怯，惊邪癫痫，或梦寐纷纭，鬼交鬼疰，及小儿急惊，大人中恶等证。\n\n同白及、白敛、红白药子、雄黄、乌鸡骨煅、乳香、没药、冰片，为末。傅一切痈疽疔肿，有神。\n\n《济生方》中风不省：麝香二钱，研末，入清油二两，和匀，灌之即苏。\n\n又方，食诸果成积伤脾，作胀气急，用麝香一钱，生桂末一两，饭和丸，绿豆大。大人十五丸，小儿七丸，白汤下。盖果得麝即落，木得桂即枯故也。\n\n夏子益《奇疾方》口内肉球，根如线，五寸余，如钗股，吐出乃能食物，捻之则痛彻心者：麝香一钱，研，水服之，日三，自消。\n\n《续千金方》催生易产：麝香一钱，水研服。\n\n《经验方》鼠咬成疮：麝香封之，妙。并治蚕咬成疮。\n\n【简误】\n      麝香走窜飞扬，内透骨窍脏腑，外彻皮肉及筋。其性能射，故善穿透开散。东垣云：凡风病在骨髓者，用之使风邪得出。若在肌肉，用之反引风入骨。丹溪云：五脏之风，不可用麝香以泻卫气。二公之言，诚得其旨矣。凡似中风，小儿慢脾风，与夫阴阳虚竭，发热，吐血，盗汗，自汗，气虚眩晕，气虚痰热，血虚痿弱，血虚目翳，心虚惊悸，肝虚痫痉，产后血晕，胎前气厥，诸证之属于虚者，法当补益，概勿施用。即如不得已欲借其开通关窍于一时，亦宜少少用之，勿令过剂，苏省开通之后，不可复用矣。孕妇不宜佩带。劳怯人亦忌之。李廷飞云：不可近鼻，有白虫入脑，患癞。久带其香透关，令人成异疾。', NULL, NULL, NULL, '麝香', NULL, '2、麝香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881103, 'FC3206794FE61DF765463A41EE15618D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7465, 422, 400106601, '      味甘，平、微寒，无毒。主心腹鬼疰，精物老魅，咳逆，泄痢脓血，女子漏下，癥瘕坚结，小儿热气惊痫。疗心腹烦满，四肢枯痿，汗出，夜卧自惊，恚怒伏气在心下，不得喘息，肠痈内疽，阴蚀，止汗，缩小便，溺血，养精神，定魂魄，安五藏。\n\n      白龙骨：疗梦寐泄精，小便泄精。\n\n      齿：主小儿、大人惊痫，癫疾狂走，心下结气，不能喘息，诸痉，杀精物，小儿五惊十二痫，身热不可近，大人骨间寒热。又杀蛊毒。（得牛黄、人参良。畏石膏。忌鱼及铁。）\n\n      疏：龙禀阳气以生，而伏于阴，为东方之神，乃阴中之阳，鳞虫之长，神灵之物也。故其骨味甘平，气微寒，无毒。内应乎肝，入足厥阴、少阳、少阴，兼入手少阴、阳明经。神也者，两精相合，阴阳不测之谓也。神则灵，灵则能辟邪恶、蛊毒、魇魅之气，及心腹鬼疰、精物老魅，遇之则散也。咳逆者，阳虚而气不归元也。气得敛摄而归元，则咳逆自止。其性涩以止脱，故能止泄痢脓血，因于大肠虚而久不得止，及女子漏下也。小儿心肝二脏虚则发热，热则发惊痫，惊气入腹则心腹烦满，敛摄二经之神气而平之，以清其热则热气散，而惊痫及心腹烦满皆自除也。肝气贼脾，脾主四肢，故四肢痿枯。肝宁则热退，而脾亦获安，故主之也。汗者，心之液也。心气不收，则汗出。肝心肾三经虚，则神魂不安而自惊，收敛三经之神气，则神魂自安。气得归元，升降利而喘息自平，汗自止也。肝主怒，肝气独盛，则善恚怒。魂返乎肝，则恚怒自除。小肠为心之腑，膀胱为肾之腑，二经之气虚脱，则小便多而不禁。脏气敛则腑亦随之，故能缩小便，及止梦寐泄精，小便泄精，兼主溺血也。其主养精神，定魂魄，安五脏者，乃收摄神魂，闭涩精气之极功也。又主癥瘕坚结，肠痈，内疽，阴蚀者，以其能引所治之药，粘着于所患之处也。\n\n       按：龙骨入心、肾、肠、胃。龙齿单入肝、心。故骨兼有止泻涩精之用，齿惟镇惊安魂魄而已。凡用龙骨，先煎香草汤洗二度，捣粉，绢袋盛之。用燕子一只，去肠肚，安袋于内，悬井上面，一宿取出，研粉。入补肾药中，其效如神。又法：酒浸一宿，焙干，研粉，水飞三度用。如急用，以酒煮焙干。或云：凡入药须水飞过，晒干。每斤用黑豆一斗，煮一伏时，晒干用。否则着人肠胃，晚年作热也。\n\n【主治参与】\n仲景方：同牡蛎，入柴胡、桂枝各汤内，取其收敛浮越之正气，固脱而镇惊。\n\n同远志等分为末，炼蜜丸如梧子大，朱砂为衣。每服三十丸，莲心汤下，治劳心梦遗。\n\n《梅师方》睡即泄精：白龙骨四分，韭子五合，为散。空心酒服方寸匕。\n\n又方泄泻不止：白龙骨、白石脂等分，为末，水丸梧子大。紫苏、木瓜汤下，量大人小儿用。亦治久痢休息。\n\n姚和众方：久痢脱肛，白龙骨粉，扑之。\n\n龙齿同荆芥、泽兰、牡丹皮、苏木、人参、牛膝、红花、蒲黄、当归、童便，治产后恶血扑心，妄语癫狂，如伤害发狂者。切不可认作伤寒治，误则杀人。\n\n同牛黄、犀角、钩藤钩、丹砂、生地黄、茯神、琥珀、金箔、竹沥、天竺黄、苏合香，治大人小儿惊痫癫疾。\n\n【简误】\n         龙骨味涩而主收敛。凡泄痢肠澼，及女子漏下崩中、溺血等证，皆血热积滞为患，法当通利疏泄，不可便用止涩之剂，恐积滞瘀血在内，反能为害也，惟久病虚脱者，不在所忌。', NULL, NULL, NULL, '龙骨', NULL, '1、龙骨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627467114881104, 'AA2FDDA9304DEA57C4DA4519C938DCD6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:10:16', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7466, 423, 400106724, '    平，无毒，主头眩痛，癫疾。\n     脑：主涂冻疮。\n     肝：主目暗。\n     肉：味辛，平，无毒。主补中益气。\n\n     疏：兔，属金，得太阴之精，故其性喜望月。兔至秋深时可食者，金气全也。其肉味辛气平无毒。然详其用，味应有甘，气应作凉。《经》曰：里不足者，以甘补之。又曰：热伤气。味甘而气凉，所以能补中益气也。肝为风木之位，太过则摇动撼物。兔属金而头骨在上，尤得气之全，故能平木邪，疗头眩痛、癫疾也。肝开窍于目，兔目不瞬而了然，其肝气足也，故能主目暗。河间云：兔肝明目。因其气有余以补不足也。\n\n    脑：为髓之至精，性温而滑润，故主涂冻疮皲裂，及世人用为催生利胎之圣药也。\n     血：味咸，寒。能凉血活血，解胎中热毒。亦能催生易产。\n     屎：一名明月砂。明目，治目中翳膜，劳瘵，五疳，痔瘘，杀虫，解毒。\n\n【主治参与】\n《博济方》催生散：用腊月兔脑摊纸上，夹匀，阴干，剪作符子，于面上书 “生” 字一个，候产母痛极时，用钗股夹定，灯上烧灰，煎丁香酒调下。\n\n《和剂局方》催生丹：麝香、乳香、母丁香为末，腊月兔脑和丸如芡实大，阴干，密封。每一丸温水下，即时产下。随男女左右手中握药丸，是验。\n\n刘氏《保寿堂方》兔血丸：小儿服之，终身不出痘疮，即出亦稀少。腊月八日，取生兔一只，刺血和荞麦面，少加丹砂、雄黄四五分，候干，丸绿豆大。初生小儿以乳汁化下二三丸。遍身发出红点，是其微验也。但儿长成，常以兔肉啖之尤妙。蔺氏《经验方》痘后目翳：直往山中东西地上，不许回顾，录兔屎二七粒，以雌雄槟榔各一个，同磨，不落地，井水调服。百无一失，其效如神。\n\n【简误】\n       妊娠不宜食兔肉，令子缺唇，且能致产不顺。性寒属阴，阳虚无热者不宜服。多服则损元气，痿阳事。不宜合白鸡、獭肉、姜、橘、芥同食。八月至十月可食，余月伤人神气。', NULL, NULL, NULL, '兔头骨', NULL, '24、兔头骨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225158, '89590EDB97E3E8D63E6361484F570EC2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7467, 423, 400106723, '      主除邪恶气，杀鬼疰毒，止惊悸，主恶疮鼠瘘。头骨尤良。\n\n        疏：虎，西方之兽，山兽之君。属金而性最有力。语云：风从虎者，风，木也；虎，金也。木受金制，焉得不从！故虎啸而风生，自然之道也。所以能治风病挛急，屈伸不便，走疰骨节风毒，惊痫癫疾等证。其性虽死而胫犹矻立不仆，故胫骨治脚膝无力，及手足诸风多效，取以类相从，借其气有余以补不足也。本经无气味。《药性论》云味辛，微热无毒。禀勇猛之气，其味更辛散而通行，故主辟邪恶气，杀鬼疰毒，止惊悸也。恶疮鼠瘘，亦风邪浸淫所致，消散风邪，则恶疮鼠瘘自除矣。\n\n【主治参与】\n同牛膝、木瓜、地黄、山药、山茱萸、黄檗、枸杞子、麦门冬、五味子，治腰脚无力，筋骨疼痛，或痿弱不能步履。同萆薢、独活、防己、苍术、牛膝、何首乌、薏苡仁、木瓜、刺蒺藜，治风寒湿邪着于经络，以致偏痹不仁。同当归、白芍药、炙甘草、续断、牛膝、白胶、麦门冬、地黄，治遍身骨节痛。\n\n《永类钤方》健忘惊悸，预知散：用虎骨酥炙、白龙骨、远志等分为末。每服三钱，生姜汤下，日三。久则令人聪慧。\n\n李绛《兵部手集》虎骨治臂胫疼痛，不计深浅皆效。用虎胫骨二两，酥炙碎，羚羊角屑一两，芍药二两切，以无灰酒浸之，养至七日，秋冬倍之。每日空腹饮一杯。若要速服，即入磁银器中，以火暖养二三日，即可服也。\n\n《圣济总录》历节痛风：虎胫骨炙三两，没药七钱，为末，每服二钱，温酒下，日三。\n\n《小品方》恶犬咬伤，虎骨刮末，水服，并傅之。\n\n【简误】\n        凡血不足以养，以致筋骨疼痛者，宜少用。', NULL, NULL, NULL, '虎骨', NULL, '23、虎骨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225159, '68D91A93EDCCB9ACFBD6867776D7212B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7468, 423, 400106722, '    味苦、酸、咸，寒、微寒，无毒。主百毒蛊疰，邪鬼瘴气，杀钩吻、鸩羽、蛇毒，除邪，不迷惑魇寐，疗伤寒温疫，头痛寒热，诸毒气。久服轻身骏健。（升麻、松脂为之使。恶乌头。忌盐。凡欲作末，先锯屑置入怀中一宿，捣之应手成粉。）\n\n     疏：犀，亦神兽也。故其角之精者名通天，夜视有光，能开水辟邪，禽兽见之皆惊骇辟易。\n\n    《本经》味苦，气寒无毒。《别录》酸咸微寒。李珣大寒。味厚于气，可升可降，阳中之阴也。入足阳明，兼入手少阴经。阳明为水谷之海，无物不受，又口鼻为上下阳明之窍，邪气多从口鼻而入。凡蛊毒鬼瘴，与夫风火邪热气之侵人也，必先入于是经。犀角为阳明经正药，其性神灵而寒，故能除邪鬼，省魇寐。其味苦寒，能散邪热，解诸毒，故主百毒蛊疰，瘴气，杀钩吻、鸩羽、蛇毒，及伤寒温疫头痛寒热等证也。邪热去则心经清明，人自不迷惑，胃亦遂安，而五脏皆得所养，故能令人骏健，及久服轻身也。\n\n      《药性论》主镇心神，解大热，散风毒，治发背痈疽疮肿，疗时疾热如火，烦毒入心，狂言妄语。日华子治心烦，止惊，镇肝，明目。《海药》主风毒攻心，冒燥热闷，小儿麸豆，风热惊痫。孟诜主中恶心痛，中饮食药毒，心风烦闷，中风失音。及今人用治吐血，衄血，下血，伤寒蓄血发狂谵语，发黄，发斑，痘疮稠密，热极黑陷等证，神效。皆取其入胃、入心，散邪清热，凉血解毒之功耳。\n\n【主治参与】\n同鬼臼、麝香、龙齿、茯神、苏合香、沉水香、天灵盖、丹砂、雄黄，能辟鬼疰邪气。\n\n同丹砂、琥珀、金箔、天竺黄、牛黄、钩藤钩、羚羊角、真珠、麝香，治大人小儿风热惊痫。\n\n磨汁，同生地黄、红花子、麦门冬、紫草、白芍药、鼠粘子，治痘疮血热，初见点红艳，壮热口渴，烦躁狂语，多服可保无虞。\n\n磨汁，同郁金、童便、生地黄、麦门冬、炙甘草、白芍药、紫苏子、剪草、丹参、白药子，治吐血，衄血。\n\n犀角地黄汤：治伤寒蓄血发黄，或热盛吐血。\n\n入紫雪丸，治大人小儿颠狂，温疫，盅毒，邪魅，一切烦热为病。\n\n入抱龙丸，治小儿恍惚惊悸，痰涎壅塞。\n\n入至宝丹，治中风不语，中恶气绝，一切神魂恍惚，癫狂扰乱等证。\n\n《圣济总录》吐血不止似鹅鸭肝：用生犀角、桔梗各一两，为末。每酒服二钱。\n\n《广利方》治小儿惊痫不知人，嚼舌仰目者，犀角磨浓汁，服之立效。\n\n钱氏《小儿方》痘疮稠密：生犀角，于涩器中新汲水磨浓汁，冷饮之。\n\n《千金方》瘭疽毒疮，喜着十指，状如代指，根深至肌，能坏筋骨，毒气入脏杀人。宜烧铁烙之，或炙百壮，日饮犀角汁瘥。\n\n《圣惠方》下痢鲜血：犀角、地榆、金银花各一两，升麻五钱，为末，炼蜜丸弹子大。每服一丸，水一升，煎五合，去滓温服。此热毒伏于心经故也。宜加丹砂、滑石末，以金银藤花熬汁煎药，更效。\n\n【简误】\n痘疮，气虚无大热者不宜用。伤寒阴证发躁，因阴寒在内，逼其浮阳失守之火，聚于胸中，上冲咽嗌，故面赤、手温、烦呕、喜饮凉物、食下良久复吐出。惟脉沉细，足冷，虽渴而饮水不多，且复吐出，为异于阳证耳，不宜误用犀角凉剂。妊妇勿多服，能消胎气。', NULL, NULL, NULL, '犀角', NULL, '22、犀角', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225160, '510F7B71169F4CCA01816648C214F408', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7469, 423, 400106721, '     味咸、苦，寒、微寒，无毒。主明目，益气，起阴，去恶血注下，辟蛊毒恶鬼不祥，安心气，常不魇寐。疗伤寒时气寒热，热在肌肤，温风注毒伏在骨间，除邪气惊梦，狂越僻谬，及食噎不通。久服强筋骨，轻身，起阴益气，利丈夫。\n\n      疏：羊，火畜也。而羚羊则属木。《本经》味咸气寒，《别录》苦微寒，无毒。气薄味厚，阳中之阴，降也。入手太阴、少阴，足厥阴经。少阴为君主之官，虚则神明不守，外邪易侵，或蛊毒恶鬼不祥，或邪气魇寐，惊梦狂越僻谬。羚羊性灵能通神灵，逐邪气，心得所养而诸证除矣。其主伤寒时气寒热，热在肌肤，温风注毒伏在骨间者，皆厥阴为病。厥阴为风木之位，风热外邪伤于是经，故见诸证。入肝散邪，则诸证自除。\n\n     《经》曰：壮火食气。又曰：热则骨消筋缓。火热太甚，则阴反不能起，而筋骨软，咸寒入下焦，除邪热则阴自起，气自益，筋骨强，身自轻也。肝热则目不明。肝藏血，热伤血则恶血注下。肝在志为怒，病则烦满气逆，噎塞不通。苦寒能凉血热，下降能平逆气，肝气和而诸证无不瘳矣。\n\n【主治参与】\n同犀角、丹砂、牛黄、琥珀、天竺黄、金箔、茯神、远志、钩藤钩、竹沥，治惊邪靥寐，及癫痫狂乱等疾。\n\n同枸杞子、甘菊花、决明子、谷精草、生地黄、五味子、黄檗、蜜蒙花、木贼草、女贞实，治肝肾虚而有热，以致目昏生翳。\n\n《外台秘要》噎塞不通：羚羊角为细末，饮服方寸匕。\n\n《千金方》产后烦闷汗出，不识人：羚羊角烧末，东流水服方寸匕，未愈再服。\n\n【简误】\n       凡肝心二经，虚而有热者宜之，虚而无热者不宜用。凡用有神羊角，甚长，有二十四节挂痕甚明，内有天生木胎。此角有神，力抵千牛。入药不可单用，须要不拆元对，绳缚，铁剉剉细末，尽处须重重密裹，恐力散也。避风捣筛极细，更研万匝如飞尘后入药，免刮人肠。', NULL, NULL, NULL, '羚羊角', NULL, '21、羚羊角', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225161, '414121655153254722893092717FFB79', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7470, 423, 400106720, '      味咸、酸，温。主安五藏，补绝伤，轻身，益气。\n\n       疏：犬，火畜也。其味咸酸，气温无毒。乃脾胃家肉也。五脏皆赖脾胃以养，脾胃得补，故主安五脏，五脏安而身自轻，气血益，绝伤自补矣。\n   \n       日华子主补胃气，壮阳道，暖腰膝，益气力。孟诜主补五劳七伤，益阳事，补血脉，厚肠胃，实下焦，填骨髓者，皆取其温暖脾胃之功，则气血生长，腰肾受庇，阳道壮健而下焦暖也。\n\n【主治参与】\n《乾坤秘韫》戊戌丸：治男子妇人一应诸虚不足，大补元气。用黄童子狗一只，去皮毛肚肠同外肾，于砂锅内，以酒、酢八分，水二升，入地骨皮一斤，前胡、黄耆、肉苁蓉各半斤，同煮一日。去药，再煮一夜，去骨，再煮肉如泥，擂细。入当归末四两，莲肉、苍术末各一斤，山药、菟丝子末各十两，甘草末八两，和杵千下，丸梧子大。每空心酒下六七十丸。\n\n危氏方：痔漏有虫，用熟犬肉蘸蓝汁，空心食，七日效。\n\n【简误】\n        气壮多火，阴虚之人不宜食。凡犬肉不可炙食，令人消渴。妊妇食之，令子无声。热病后食之杀人。道家以犬为地厌，忌食。', NULL, NULL, NULL, '犬肉,狗肉', NULL, '20、犬肉,狗肉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225162, '9B9DF539DA979B5522AE1D4DD83CC9BE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7471, 423, 400106719, '     味咸，无毒。主癫疾发作。\n\n     疏：癫疾属手少阴，少阴主血，藏神，血虚而神自不宁，故发是证。此物入心补血，以类相从，故主癫疾发作也。\n\n【简误】\n         犬性热，以其禀火土之气，故助阳，阳胜则发热、动火、生痰、发渴。凡病人阴虚内热，多痰多火者，慎勿食之。天行病后，尤为大忌。治痢亦非所宜。', NULL, NULL, NULL, '白狗血', NULL, '19、白狗血', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225163, '66DE31B96448736E89D8D73DB20B59D3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7472, 423, 400106718, '       主金疮止血。（烧灰，用黄狗者良。余骨烧灰，生肌，敷马疮，及疗诸疮瘘，妒乳，痈肿。）\n\n        疏：狗头骨，本经无气味。察其功用，应是甘咸温之物。咸能入血，甘能补血，温能和血，故主金疮止血也。\n\n【主治参与】\n同血竭、乳香、没药、蚺蛇胆、䗪虫、天灵盖、自然铜，治跌扑损伤有神。临杖时服之护心止痛，杖后服之生肌长肉。\n\n《千金方》治小儿久痢：狗头骨烧灰，白汤服。非久痢虚寒者勿用。\n\n《和剂局方》狗头骨丸：治久痢脐腹㽲痛，所下杂色，昼夜不止；或其人久虚，所下肠垢，谓之恶痢，并能治之。赤石脂、干姜各半两，肉豆蔻煨、附子炮去皮各一两，狗头骨灰一两，为末，醋和丸如桐子大。每服六七十丸，空心米饮下。非阴脏人，及阳虚极者不宜用。\n\n《圣惠方》赤白带下不止者，狗头骨烧存性，为末。每酒服一钱，日三。\n\n《经验方》产后血不定，奔四肢，以狗头骨灰，酒服二钱，甚效。\n\n《卫生易简方》打损接骨，狗头骨灰，热醋调涂伤处，暖卧。\n\n《寿域方》恶疮不愈：狗头骨灰、黄丹等分，敷之。\n\n同白敛等分，为末，生白酒调服五钱，治少腹痈，有神。', NULL, NULL, NULL, '黄头骨', NULL, '18、黄头骨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225164, '71E2073F82C6F5677C6E279F97FD48F8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7473, 423, 400106717, '     味咸，平，无毒。主伤中，阴痿不起，令强热大，生子。除女子带下十二疾。一名狗精，六月上伏取，阴干百日。\n\n      疏：狗阴茎，气味与马阴茎同，其所主亦相似。性专补右肾命门真火，故能令阳道丰隆，精暖盈溢，使人生子也。女子带下十二疾，皆冲任虚寒所致。咸温入下焦，补暖二脉，故亦主之也。\n\n【主治参与】\n         同菟丝子、覆盆子、鱼胶、车前子、巴戟天、肉苁蓉、鹿茸、沙苑蒺藜、山茱萸，能益阳暖精，使人有子。\n\n【简误】\n       阳事易举者忌之。内热多火者勿服。', NULL, NULL, NULL, '狗阴茎,狗精', NULL, '17、狗阴茎,狗精', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225165, '9B712B44B339EB169C248F30B0CC0633', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7474, 423, 400106716, '     主女人中风血虚闷，产后血晕，闷欲绝者。生饮一升即活。\n     \n      疏：血为水化，故其味应咸，气平无毒。女人以血为主，血热则生风，血虚则闷绝，咸平能补血凉血，故主女人血虚中风，及产后血闷欲绝也。性能解丹石毒，如丹砂、水银、汞粉、生银、硇砂、砒霜、硫黄、钟乳、礜石、阳起石等类。凡觉毒发，刺饮一升，即解。凡服地黄、何首乌诸补药者，须忌之。', NULL, NULL, NULL, '羊血', NULL, '16、羊血', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225166, '648DBE97869CD8053DF0064700BDA0C8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7475, 423, 400106715, '     性冷。疗肝风虚热，目赤暗无所见。生食子肝七枚，神效。或切薄片，水浸傅之。\n\n     疏：羊肝补肝，以类相从。肝开窍于目，肝热则目赤痛，失明。补肝除热，所以能明目，及治诸目疾也。\n\n【主治参与】\n      《医镜》翳膜羞明有泪，肝经有热也，用青羊子肝一具，竹刀切，和黄连四两，为丸梧子大。食远茶清下七十丸，日三服。忌铁器、猪肉、冷水。', NULL, NULL, NULL, '羊肝', NULL, '15、羊肝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225167, '5AD86D4FBFA7AD20407B7AF15301C83E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7476, 423, 400106714, '      味甘，大热，无毒。主缓中，字乳余疾，及头脑大风汗出，虚劳寒冷，补中益气，安心止惊。（反半夏、菖蒲。）\n\n       疏：羊得火土之气以生，故其味甘气大热无毒。\n \n    《素问》言苦，亦以其性热属火耳。李杲云：补可去弱，人参、羊肉之属是已。羊肉有形，凡形气痿弱，虚羸不足者宜之。其主字乳余疾者，盖产后大虚，血气暴损，得甘热之物补助阳气，则阴血自长，余疾自除矣。中气虚则心不安，或惊惕；阳气弱则头脑大风汗出。补中则中自缓，故能安心止惊；益气则阳自足，故能疗头脑大风汗出，及虚劳寒冷也。\n\n【主治参与】\n《金匮要略》羊肉汤：治寒劳虚羸，及产后心腹疝痛，用肥羊肉一斤，水一斗，煮汁八升，入当归五两，黄耆八两，生姜六两，煮取二升，分四服。\n\n又方，产后虚羸腹痛，冷气不调，及脑中风汗自出：白羊肉一斤，治如常，调和食之。\n\n《饮膳正要》壮胃健脾：羊肉三斤切，粱米二升同煮，下五味作粥食。\n\n《千金方》损伤青肿，用新羊肉贴之。\n\n【简误】\n         羊肉，味甘，大热。脾胃虚寒，羸瘦气乏者宜之。然天行热病后，温疟、热痢后食之，必致发热难疗。妊妇食之，令子多热。与夫痈肿疮疡，消渴，吐血，嘈杂易饥等证，咸不宜服。又铜器煮食之，男子损阳，女子暴下。物性之异如此，不可不知也。', NULL, NULL, NULL, '羊肉', NULL, '14、羊肉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225168, '2ED18271E26917EED39C9F329945F0B3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7477, 423, 400106713, '     补肾气，益精髓。\n\n     疏：羊肾，补肾气者，以其类相从，借其气以补其不足也。肾得补则精髓自益矣。\n\n【主治参与】\n        羊肾一对，去脂切，肉苁蓉一两，酒浸一夕，去皮膜，和作羹，加五味食，治劳伤阳虚无力。', NULL, NULL, NULL, '羊肾', NULL, '13、羊肾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225169, 'F358312DEFFF1D6314FA384315D69A5F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7478, 423, 400106712, '     味咸、苦，温、微寒，无毒。主青盲，明目，杀疥虫，止寒泄，辟恶鬼虎狼，止惊悸，疗百节中结气，风头痛，及蛊毒吐血，妇人产后余痛。久服安心，益气，轻身。取之时勿中湿，湿即有毒。\n\n      疏：羊角，乃肺肝心三经药也。而入肝为正。《本经》咸温。《别录》苦微寒。甄权：大寒。察其功用，应是苦寒居多。非苦寒则不能主青盲，惊悸，杀疥虫，及风头痛，蛊毒吐血也。盖青盲，肝热也；惊悸，心热也；疥虫，湿热也；风头痛，火热上升也；蛊毒吐血，热毒伤血也。苦寒总除诸热，故能疗如上等证也。惊悸平则心自安。热伤气，热除则气自益。其主百节中结气，与妇人产后余痛，亦指血热气壅者而言。《本经》又主止寒泄，及辟恶鬼虎狼，未解其义，俟博物者详之。\n\n【主治参与】\n《子母秘录》产后寒热，心闷胀极，百病：羖羊角烧末，酒服方寸匕。\n\n《普济方》治小儿痫疾，方同上。', NULL, NULL, NULL, '羖羊角', NULL, '12、羖羊角', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225170, 'F2D3E994F4A7D41FC391623C3BB2E88A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7479, 423, 400106711, '      味甘，平，无毒。主安中，益气，养脾胃。\n\n      疏：牛，土畜也。黄，中央正色也。经云：中央色黄，入通于脾。故为益脾胃之药。脾胃得所养则中自安，气自益矣。丹溪朱氏有倒仓法，非为其有吐下之力也。特饮之既满，或上涌下泄尔。此盖借其补以为泻，故积聚去而肠胃得所养，亦奇法也。但病非关肠胃者，不宜服。凡牛病死，及黑身、白头、独肝者，皆不宜服。合猪肉及黍米酒食，并生寸白虫。合韭、薤食，令人热病。合生姜食，损齿。又云：牛乃稼穑之资，不可多杀及食。若以之疗病，则药物甚多。以之供馔核，则肥甘不少。似可无此一物也。好生君子，其念及而力戒之，当有冥福耳。', NULL, NULL, NULL, '牛肉', NULL, '11、牛肉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225171, '3E3EEF29CD2FAD8F09087C04A1165AE2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7480, 423, 400106710, '    味苦，大寒无毒。除心腹热，渴利、口焦燥，益目精。可丸药。\n\n     疏：胆，牛食百草，其精华萃于胆，其味苦，其气大寒无毒。《经》云：寒以胜热，苦以泄结。故主心腹热，及渴利、口焦燥也。肝开窍于目，肝热则目睛不明，入肝泄热故益目精也。近世以南星末酿入阴干，治惊风有奇功者，取其苦寒制南星之燥，俾善于豁痰除热耳。\n\n【简误】\n       脾胃虚寒者忌之。目病非风热者，不宜用。', NULL, NULL, NULL, '牛胆', NULL, '10、牛胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225172, 'F45E07AA4EA1A03D633511A754A4C756', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7481, 423, 400106709, '     下闭血，瘀血疼痛，女人带下，燔之。味苦，无毒。\n\n      疏：牛角䚡，乃角中嫩骨也。为筋之粹，骨之余。入足厥阴、少阴血分之药。兼入手阳明经。苦能泄，温能通行，故主妇人带下，及闭血瘀血疼痛也。\n\n【主治参与】\n同猪悬蹄、猬皮、金头蜈蚣、蛀竹屑、明矾、白蜡，去漏管。\n\n《近效方》大便下血：黄牛角䚡一具煅末，煮豉汤服二钱，日三。\n\n《塞上方》鼠瘘痔疾：牛角䚡烧灰，酒服方寸匕。', NULL, NULL, NULL, '牛角䚡', NULL, '9、牛角䚡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225173, 'DEC5C5748938638BB6E6C33BDA1F11FE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7482, 423, 400106708, '     甘，温。补中，强五藏，益气力。生者疗口僻，割薄之。\n\n     疏：鹿，所食多芳草，其性质芳洁，气味醇和，故其肉味甘，气温无毒，与他肉不同也。性能益脾胃，通血脉，故主补中，强五脏，益气力也。生者疗中风口僻，亦取其有通血脉之功，血脉通则口僻自正也。', NULL, NULL, NULL, '鹿肉', NULL, '8、鹿肉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225174, 'E618FD4EDA6AB0C9190BCC7368611561', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7483, 423, 400106707, '     平。主补肾气。\n\n      疏：鹿性淫，一牡常御百牝，肾气有余故也。故服之能壮阳道，补肾家不足。', NULL, NULL, NULL, '鹿肾', NULL, '7、鹿肾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225175, 'C8C54F276DEBA05C7EE778B9FC0F74B4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7484, 423, 400106706, '     味甘，温。主丈夫女子伤中绝脉，筋急痛，咳逆。以酒和服之良。\n\n     疏：髓者，精血之纯懿，内充以实骨者也。鹿禀纯阳，故其髓味甘，气温，性能补血而润燥，所以主一切血脉不和，如伤中脉绝，筋急痛及咳逆也。日华子：同蜜煮服壮阳道，令人有子。同地黄汁煎膏服，填骨髓，壮筋骨。治呕吐者亦此意也。', NULL, NULL, NULL, '鹿髓', NULL, '6、鹿髓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225176, 'E1E2018078D3AF0992B96AF8763A8B1A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7485, 423, 400106705, '      味咸，无毒。主恶疮痈肿，逐邪恶气，留血在阴中，除小腹血急痛，腰脊痛，折伤恶血，益气。（杜仲为之使。）\n\n       疏：鹿，山兽，属阳。夏至解角者，阴生阳退之象也。麋，泽兽，属阴。冬至解角者，阳生阴退之象也。是以麋茸补阴，鹿茸补阳。角亦如之。凡角初生软嫩者为茸，禀壮健之性，故能峻补肾家真阳之气。熬成白胶，则气味甘缓，能通周身之血脉。生角则味咸，气温，惟散热、行血、消肿、辟恶气而已。咸能入血软坚，温能通行散邪，故主恶疮痈肿，逐邪恶气，及留血在阴中，少腹血急痛，折伤恶血等证也。肝肾虚则为腰脊痛，咸温入肾补肝，故主腰脊痛。气属阳，补阳故又能益气也。日华子云：水磨服，治脱精，尿血，夜梦鬼交。醋磨汁，涂疮疡痈肿热毒。火炙热，熨小儿重舌，鹅口疮。孟诜云：蜜炙研末酒服，轻身，强骨髓，补阳道绝伤。又治妇人梦与鬼交者，酒服一撮，即出鬼精。烧灰治女子胞中余血不尽欲死者，悉取其入血行血，散热消肿，补阳辟邪之意也。\n\n【主治参与】\n《济生方》骨虚劳极，面肿垢黑，脊痛不能久立，血气衰惫，发落齿槁，甚则喜唾：用鹿角屑二两，牛膝一两半，为末，炼蜜丸梧子大。每服五十丸，空心盐汤下。\n\n《肘后方》肾虚腰痛如锥刺，不能动摇：鹿角屑三两，炒黄研末。空心温酒服方寸匕，日三。\n\n《子母秘录》产后腹痛，瘀血不尽者，鹿角烧研，豉汁服方寸匕，日三。并治产后血晕。\n\n《千金方》蹉跌损伤，血瘀骨痛：鹿角末，酒服方寸匕。\n\n濒湖方：痈疖肿痛毒：鹿角尖，磨浓汁涂之。\n\n【简误】\n      无瘀血停留者不得服。阳盛阴虚者忌之。胃火齿痛亦不宜服。', NULL, NULL, NULL, '鹿角', NULL, '5、鹿角', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225177, '3F9117EDD316334F633C2203371281E5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7486, 423, 400106704, '      味甘、酸，温、微温，无毒。主漏下恶血，寒热惊痫，益气，强志，生齿，不老。疗虚劳洒洒如疟，羸瘦，四肢酸疼，腰脊痛，小便利，泄精，溺血，破留血在腹，散石淋，痈肿，骨中热，疽痒。（痒应作疡。凡用取形如分岐马鞍，茸端如玛瑙红玉，破之肌如朽木者最良。先以酥薄涂匀，于烈炎中燎去毛，再炙。）\n\n       疏：鹿茸禀纯阳之质，含生发之气，故其味甘气温。《别录》言酸微温。气薄味厚，阴中之阳也。入手厥阴、少阴，足少阴、厥阴经。妇人冲任脉虚则为漏下恶血，或瘀血在腹，或为石淋；男子肝肾不足则为寒热惊痫，或虚劳洒洒如疟，或羸瘦，四肢酸疼，腰脊痛，或小便数利，泄精溺血。此药走命门、心包络，及肾肝之阴分，补下元真阳，故能主如上诸证，及益气、强志、生齿、不老也。痈肿疽疡，皆荣气不从所致。甘温能通血脉，和腠理，故亦主之。日华子主补男子腰肾虚冷，脚膝无力，夜梦鬼交，精溢自出；女人崩中漏血，赤白带下。炙末，空心酒服方寸匕。\n\n【主治参与】\n同牛膝、杜仲、地黄、山茱萸、补骨脂、巴戟天、山药、肉苁蓉、菟丝子，治肾虚腰痛，及阴痿不起。\n\n《澹寮方》斑龙丸：治诸虚，用鹿茸酥炙，鹿角胶炒成珠，鹿角霜、阳起石煅红醋淬，肉苁蓉酒浸，酸枣仁、柏子仁、黄耆各一两，地黄九蒸八钱，朱砂半钱，各为末，酒糊丸梧子大。每空心酒下五十丸。昔西蜀市中有一道人货之，一名茸珠丹。每醉高歌曰：“尾闾不禁沧海竭，九转灵丹都漫说。唯有斑龙顶上珠，能补玉堂关下穴”。朝野遍传之，即此方也。\n\n《普济方》鹿茸酒：治阳事虚痿，小便频数，面色无光，用嫩鹿茸一两，去毛切片，山药末一两，绢袋裹，置酒瓮中，七日后开瓮，日饮三杯。将茸焙干作丸服。\n\n《本事方》阴虚腰痛，不能反侧：鹿茸、菟丝子各一两，茴香半两，为末，以羊肾二对，和酒煮烂，捣和泥，和丸梧子大，阴干。每服三五十丸。酒下，日三服。\n\n《济生方》室女白带，因冲任虚寒者：鹿茸酒蒸焙二两，金毛狗脊、白敛各一两，为末，用艾煎醋，打米糊丸梧子大。每酒下五十丸，日二服。\n\n“简误” 同白胶。', NULL, NULL, NULL, '鹿茸', NULL, '4、鹿茸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225178, 'BB5164A328F0714F4B59F6882F00CDBE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7487, 423, 400106703, '     味辛，微寒。主消渴，破癥坚积聚，男子伏梁积疝，妇人瘕疾。铜器盛饮之。\n\n      疏：白马溺，昔有人与其奴皆患心腹痛病。奴死剖之，得一白鳖，赤眼，仍活。以诸药纳口中，终不死。有人乘白马观之，马尿堕鳖而鳖缩。遂以灌之，即化成水。其人乃服之，疾亦愈。观其气味，不应有如是之功。乃知物性畏忌，各有所制，如刀柄之刈三棱而化为水，正以遇其所制之物故也。本经云气微寒。然详其用，必是微温，味应带咸，辛咸温俱足，所以能疗经所言诸证。\n\n【主治参与】\n《千金方》食髪成瘕，咽中如有虫上下者，白马尿饮之，佳。\n\n《鲍氏方》利骨取牙：白马尿浸茄秆三日，炒，为末，点牙即落。\n\n【简误】\n       无积聚癥瘕者，不得服。胸中虚痞误作伏梁，服之有损。', NULL, NULL, NULL, '白马溺', NULL, '3、白马溺', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225179, 'CF3579C4773F1B3689F39A3C0EA35DD5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7488, 423, 400106702, '   微温。主妇人崩中，止渴，及吐、下血，鼻衄，金疮止血。\n\n    疏：白马通，本经虽云微温，然必是苦而凉者。惟其苦凉所以能疗诸血热证，止渴。及孟诜主阴阳易、垂死者，绞汁服也。', NULL, NULL, NULL, '马通', NULL, '2、马通', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225180, '81FAEA2A6410A845836327CF05859A03', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7489, 423, 400106701, '     味咸、甘，平，无毒。主伤中，脉绝，阴不起，强志益气，长肌肉肥健，生子，小儿惊痫。阴干百日用。\n\n       疏：马，火畜也。其阴茎又纯阳之物也。故能主男子阴痿，坚强，房中药多用之。《本经》味咸气平，《别录》甘无毒。察其功用，气平应作温。非甘温则不主伤中脉绝，以甘能补血脉，温能通经络故耳。阳衰则阴不起而生长之道绝，咸温走下焦，补助真阳则阴自起，精自暖，故能令人有子也。气属阳，阳得补故能益气。肾藏志，肾气足故能强志。甘温补血脉而助真气，故又能长肌肉肥健也。《别录》又主小儿惊痫者，似非其所长，应是误入耳。凡收当取银色无病白马，春月游牝时，力势正强者。生取阴干百日，用时以铜刀切片，将生羊血拌蒸半日，去血，晒干，剉用。\n\n【主治参与】\n       得肉苁蓉、巴戟天、山茱萸、菟丝子、真阳起石、人参、鹿茸、狗阴茎，作丸。治真阴虚脱，阴痿不起，下元冷惫等证。\n\n【简误】\n       马阴茎，乃纯阳之物也。凡阴虚火盛者，不得服。人但喜其温暖，滋助阳道，少年多欲者，房中术用之，仗其力势，恣欲无节，以致损竭真阴，多成劳瘵，不可不戒也。', NULL, NULL, NULL, '白马茎', NULL, '1、白马茎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627478315225181, '7315C50948DEB9D56889658EBDE853D2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 11:55:50', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7490, 424, 400106811, '      味咸，无毒。主鬼气尸疰，梦与鬼交，鬼魅狐魅，心腹痛，中恶邪气，宿血结块，痃癖羸瘦。（一名海狗肾。雷云：此物多伪者，真者有一对，则两重薄皮裹丸核，其皮上有肉黄毛，三茎共一穴，湿润常如新。或置睡犬旁，其犬忽惊跳若狂者，真也。与水乌龙似，以此别之。凡用酒浸一宿，纸裹炙香，剉或酒煎熟合药。）\n\n      疏：腽肭，海兽也。得水中之阳气，故其味咸无毒。《药性论》大热，李珣甘香美、大温。其味与獭肝相似，第其气倍热耳。所主鬼气尸疰，梦与鬼交，鬼魅狐魅，心腹痛，中恶邪气者，盖因真阳虚则神明不振，幽暗易侵，故诸邪恶缠疰为病。此药专补阳气则阴邪自辟，所以能疗如上等证也。咸能入血软坚，温热能通行消散，故又主宿血结块，及痃癖羸瘦也。近世房术中多用之，以其咸温入肾补虚，暖腰膝，固精气，壮阳道也。\n\n【主治参与】\n同阳起石、肉苁蓉、巴戟天、菟丝子、山茱萸、鹿茸，能壮阳道，益精。\n\n《和剂局方》有腽肭脐丸，治诸虚劳损，鬼疰邪恶，梦与鬼交，精气乏绝等证。\n\n【简误】\n    腽肭脐，性热助阳，为肾气衰竭，精寒痿弱之要药。然而阴虚火炽，强阳不倒，或阳事易举，及骨蒸劳嗽等候，咸在所忌。', NULL, NULL, NULL, '腽肭脐,海狗肾', NULL, '11、腽肭脐,海狗肾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711430, '40ECCC53CBB8A7653FD5E49E2ED27306', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7491, 424, 400106810, '       味甘，有毒。主鬼疰蛊毒，却鱼鲠，止久嗽，烧服之。\n\n        疏：獭，水中之兽也。本经味甘有毒。《药性论》咸，微热无毒。详其功用，应是咸胜甘劣，微温小毒之物。入肝、入肾之药也。《经》曰：邪之所凑，其气必虚。虚损劳极，则五脏之神俱不安，鬼邪相挟而为病。久嗽者，亦劳极所致，水不胜火，火气上炎，肺为贼邪所干也。咸味润下，俾火气下降，则肺自清。总之，此药能益阴气，补虚损，保劳极，故主如上诸证也。甘咸善于解毒，故又主蛊毒。獭性嗜鱼，故能却鱼鲠也。大抵其功长于治传尸劳，及鬼疰邪恶有效。故张仲景治冷劳有獭肝丸；崔氏治九十种蛊疰传尸，骨蒸伏连殗殜，诸鬼毒疠疾，有獭肝丸，皆妙。\n\n【主治参与】\n同芦荟、牛漆、象胆、青黛、胡黄连、啄木鸟头、狐脾、虎胃、丹砂、天灵盖，治传尸劳，能杀劳虫。\n\n孟诜：尸疰，一门悉患者。獭肝一具，烧，水服方寸匕，日再。\n\n葛洪：尸疰鬼疰，乃是五尸之一，又挟诸鬼邪为害，其病变动，乃有三十六种至九十种。大略使人寒热，沉沉默默，不知病之所苦，而无处不恶。积月累年，淹滞至死。死后传人，乃至灭门。觉有此候，惟以獭肝散服之有效。法如上。\n\n除传尸劳证外无他用，故不著 “简误”。', NULL, NULL, NULL, '獭肝', NULL, '10、獭肝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711431, '781321FAC18528F176F14BC513BA14B2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7492, 424, 400106809, '        甘，无毒。主痹，止血，益气力。\n\n        疏：麋属阴，好游泽畔。其角冬至解者，阳长则阴消之义也。为补左肾真阴不足，虚损劳乏，筋骨腰膝酸痛，一切血液衰少为病。故主止血，益气力，及除痹也。痹虽风寒湿合而成疾，然外邪易入者，由气血先虚，经络因之壅滞，血脉不通故也。麋角入血益阴，荣养经络，故主之也。\n\n茸：功用相同，而补阴之力更胜。\n\n【主治参与】\n《千金方》麋角丸：补心神，安五脏，填骨髓，理腰脚，能久立，聪明耳目，发白更黑，返老还少。麋角取当年新角连脑顶者，不论具数，去尖一大寸截断，于净盆中水浸，每夜换易。软即将出，削去皱皮，以镑镑取白处，至心即止。以清米泔浸两宿，取出曝干。以无灰酒于大瓷器中浸两宿，其药及酒俱入净釜中，初用武火煎一食顷，后以文火微煎如蟹眼，柳木不住手搅，时时添酒，以成膏为度。煎时皆须平旦下手，不得经宿。仍看屑如稀胶，即以牛乳五升，酥一升，以次渐下后项药。另以麋角炙令黄，为末：槟榔、通草、秦艽、肉苁蓉、人参、菟丝子、甘草各一两，为末。将胶再煎一食顷，似稀粥即止火。投诸药末，和匀，约稠粘堪作丸，倾出，众手一时丸梧子大。空腹酒下三十丸，日加一丸，至五十丸为度。日二服，至一百日。忌房事。经一月，腹内诸疾自相驱逐，有微利勿怪。服至二百日，面皱光泽。一年，齿落更生，强记身轻。二年，令人肥饱少食，不老神仙。合时须在净室，勿令阴人、鸡、犬、教子等见。\n\n杨氏《家藏方》二至丸：补虚损，生精血，去风湿，壮筋骨。用鹿角镑细，以真酥一两，无灰酒一升，慢火炒干，取四两；麋角镑细，以真酥二两，米醋一升，慢火炒干，取四两；苍耳子酒浸一宿，焙，半斤；山药、白茯苓、黄耆蜜炙，各四两，当归五两，肉苁蓉酒浸焙，远志、人参、沉香，各二两，五味子一两，通为末，酒煮糯米糊丸梧子大。每服五十丸，温酒、盐汤任下，日二服。\n\n【简误】\n        阳气衰少，虚羸畏寒者勿用。肉多食，令人弱房。', NULL, NULL, NULL, '麋角', NULL, '9、麋角', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711432, '8E9A35741DB34E758987BA11DA3C7940', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7493, 424, 400106808, '      一名肾脂，生两肾中间，似脂非脂，似肉非肉，乃人物之命门、三焦发原处也。陈藏器主肺痿咳嗽，和枣肉浸酒服。亦能主痃癖羸瘦。苏颂主肺气干胀喘急，润五脏，去皴皰䵟（黑曾）等证。盖是甘寒滑泽之物，甘寒则津液生，滑泽则垢腻去，故主如上诸证也。男子多食损阳，薄大肠。其能专在去垢腻，可用以浣垢衣，俗名猪胰子。\n\n【简误】\n       按猪为食味中常用之物，脏腑肠胃咸无弃焉。然其一身除肚、膏外，余皆有毒发病，人习之而不察也。壮实者，或暂食无害；有疾者，不可不知其忌，故列其害于后。\n\n肉：多食令人虚肥，生痰热。热病后食之复发。不宜与姜同食，食则发大风病。\n\n头肉：有病者食之，生风发疾。\n\n脑：食之损男子阳道，临房不能行事，酒后尤不可食。\n\n血：能败血损阳，服地黄、何首乌诸补药者，尤忌之。多食耗心气，不可合吴茱萸食。\n\n肝：饵药人不可食。合鱼鲙食生痈疽。合鲤鱼肠、子食，伤人神。《延寿书》云：猪临宰，惊气入心，绝气归肝，俱不可多食，必伤人。\n\n脾：孙思邈云：凡六畜脾，人一生莫食之。\n\n肺：不可与白花菜合食，令人气滞发霍乱。八月和饴食，至冬发疽。\n\n肾：久食令人伤肾少子。冬月不可食，损人真气，兼发虚壅。\n\n胰：男子多食损阳。\n\n肠：多食动冷气。\n\n鼻、唇：多食动风。\n\n舌：多食损心。', NULL, NULL, NULL, '猪胰子', NULL, '8、猪胰子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711433, '97757B8E01637747AE0D2706979E3A35', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7494, 424, 400106807, '    主煎诸膏药，解斑猫、芫青毒。\n\n    疏：肪膏即脂油也。味甘寒，性滑泽。能凉血解毒润燥，故主煎诸膏药，及解斑猫、芫青毒也。又能利肠胃，通大小便，能散风热，疗恶疮。\n\n【主治参与】\n《肘后方》膏发煎：治女劳黄疸，见发髲条，兼能治五疸。\n\n万氏方：肺热暴瘖。猪脂油一斤炼过，入白蜜一斤再炼少顷，滤净冷定。不时挑服一匙，即愈。', NULL, NULL, NULL, '猪脂油,肪膏', NULL, '7、猪脂油,肪膏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711434, 'BBB81B7236AD45E27E04A2514D296BC7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7495, 424, 400106806, '   主补中益气，止渴利。\n\n    疏：猪肚属土，故其味必甘，气微温，无毒。乃猪一身无害之物，为补脾胃之要品。脾胃得补则中气益、利自止矣。日华子主补虚损，苏颂主骨蒸劳热，血脉不行，皆取其补益脾胃则精血自生，虚劳自愈，根本固而五脏皆安也。\n\n【主治参与】\n《普济方》水泻不止，用猪肚一枚煮烂，入平胃散捣丸服效。\n\n仲景方：猪肚黄连丸，治消渴：用雄猪肚一枚，入黄连末五两，栝楼根、白粱米各四两，知母三两，麦门冬二两，缝定蒸熟，捣丸梧子大。每服三十丸，米饮下。\n\n《千金方》温养胎气，胎至九月消息，用猪肚一枚，如常着五味煮食至尽。\n\n又，猪肚丸：黄连一味为细末，量肚大小实之，煮令极烂，捣匀为丸梧子大。治脏毒下血。\n\n又方，治腹胀大，用乌芋去皮，入雄肚，线缝，砂器煮糜，食之，勿入盐。', NULL, NULL, NULL, '猪肚', NULL, '6、猪肚', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711435, '5959D73D3CC02B1734ECFCF97A1FD57C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7496, 424, 400106805, '      仲景治足少阴下利，咽痛，胸满心烦者，有猪肤汤。用猪肤一斤，水一斗，煮五升，取汁，入白蜜一升，白粉五合，熬香，分服。成无己注云：猪，水畜也。其气先入肾，解少阴客热。加白蜜以润燥除烦，白粉以益气断利也。', NULL, NULL, NULL, '猪肤', NULL, '5、猪肤', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711436, '08955753936261559646FA0C909EE192', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7497, 424, 400106804, '    主伤寒热渴。\n\n     疏：胆，味苦气寒，《经》曰：热淫于内，寒以胜之，苦以泄之。故主伤寒热渴也。\n\n【主治参与】\n仲景胆导法：以猪胆汁和醋少许，灌谷道中，通大便神效。入猪牙皂角细末二分，搅匀更速。盖酸苦益阴，润燥而泻便也。\n\n又治少阴下利不止，厥逆无脉，干呕烦者，以白通汤加猪胆汁主之。使其气相从，无拒格之患。此寒因热用，热因寒用之义也。葱白四茎，干姜一两，生附子一枚，水三升，煮一升，入人尿五合，猪胆汁一合，分服。\n\n入雄黄末三四分，蜈蚣末二发，套指缚紧，治天蛇毒，有效。\n\n《梅师方》热病䘌蚀上下：用猪胆汁一枚，醋一合，煎沸服，虫立死。\n\n《外台秘要》汤火伤疮，猪胆调黄檗末，涂之。', NULL, NULL, NULL, '猪胆', NULL, '4、猪胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711437, 'B665D28152A27E53DF3B6A69A36AC465', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7498, 424, 400106803, '    冷。和理肾气，通利膀胱。\n\n     疏：猪肾味咸，气冷，能泻肾气，肾虚寒者不宜食。本经主理肾气，乃借其同气以引导之耳。不言补而言理，其意有在矣。肾与膀胱为表里，故复能利膀胱也。今人误认以为补肾，恣意食之，大为差谬。不睹日华子云 “久食令人无子”，孟诜云 “久食令人伤肾”，其非补肾之物明矣。', NULL, NULL, NULL, '猪肾', NULL, '3、猪肾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711438, 'B22899C9F5CED324961CB2A8FE09630E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7499, 424, 400106802, '     小寒。主伤挞诸败疮，下乳汁。\n     \n       疏：乳属阳明，阳明脉弱则乳汁不通，能益阳明经气血，故能下乳。伤挞败疮，必血热作痛，气寒而味甘咸，故凉血止痛也。又，煮汤为洗溃疡之要药。\n\n【主治参与】\n《广济方》妇人乳无汁者，以猪蹄四枚，水二斗，煮一斗，去蹄，入土瓜根、通草、漏芦各三两，再煮六升，去滓，内葱白、豉，作粥或羹食之，身体微热有少汗出佳，未通再作。\n\n《梅师方》痈疽发背，乳发初起：母猪蹄一只，通草六分，绵裹煮羹食之。《外科精要》洗痈疽，有猪蹄汤。', NULL, NULL, NULL, '猪四足', NULL, '2、猪四足', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711439, '13DFB8226809C1973A19E2B93CCD2878', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7500, 424, 400106801, '     主五痔，伏热在肠，肠痈内蚀。\n\n      疏：猪，水畜也。在辰属亥，在卦属坎。其肉气味虽寒，然而多食令人暴肥，性能作湿生痰，易惹风热，殊无利益耳。其悬蹄，乃蹄甲之悬起不着地者。《本经》无气味，然为咸寒无毒之物，入手足阳明经药也。湿热下注则为五痔内蚀，热壅血滞则为肠痈，咸寒能除肠胃之热，故主之也。\n\n【主治参与】\n得牛角䚡、槐角子、蝟皮、象牙末、金头蜈蚣、蛀竹屑、明矾、地榆、青黛、白蜡，治通肠漏，令漏管自出。\n\n钱氏《小儿方》痘后目翳，半年已上者，一月取效。用猪悬蹄三两，瓦瓶固济煅，蝉蜕一两，羚羊角三钱，为末。每岁一字，三岁已上三钱，温水服，日三。', NULL, NULL, NULL, '猪悬蹄', NULL, '1、猪悬蹄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627515181711440, 'B5EB47311FA2228B56FDB6DC2FCBE9E9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 14:25:51', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7501, 425, 400106911, '     味咸，平，无毒。肉主辟诸药毒，及人马久患疥。又云：暖，无毒。调精益气，治恶疮疥，并风瘙，白癜，疬疡风。\n\n      疏：白鸽禀水金之气，故其味咸，气平，无毒，肾藏精，肾纳气，肺主皮毛，咸入肾，故能调精益气，平则兼辛入肺，故能主恶疮疥，及白癜疬疡风。凡毒药之性多热，鸽得金水之气，故又能辟诸药毒也。\n\n其屎名左盘龙，亦能主人马疥疮。\n\n【主治参与】\n《食医心镜》治消渴，饮水不知足，用白花鸽，切作小片，以土苏煎，含之咽汁。\n\n《潜江方》预辟痘毒，用白鸽卵一对，入竹筒封，置厕中，半月取出，以卵白和辰砂三钱，丸绿豆大。每服三十丸，豆子饮送下，毒从大小便出也。\n\n《保命集》破伤中风病传入里，用左盘龙、白僵蚕各炒半钱，雄黄一钱，为末，蒸饼丸梧子大。每服十五丸，温酒下，取效。\n\n《圣惠方》头痒生疮：白鸽屎五合，醋煮三沸，杵，傅之，日三上。\n\n又方，头疮白秃：鸽粪研末，先以醋米泔洗净，傅之。\n\n【简误】\n      鸽，本经虽云调精益气，其用只长于去风解毒，然而未必益人。故孟诜云：食多减药力。今世劳怯人多畜养，及煮食之，殊未当也。', NULL, NULL, NULL, '白鸽', NULL, '11、白鸽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612876870, '37F674E75A71E2EF559A9A8D82F15D7D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7502, 425, 400106910, '    味辛，寒，无毒。主面痈肿，皮肤洗洗时痛，腹中血气，破寒热积聚，除惊悸，去面䵟。（一名夜明沙。）\n\n     疏：天鼠夜出，喜食蚊蚋，故其屎中淘出细沙，皆未化蚊蚋眼也。所以今人主明目，治目盲障翳，取其气类相从也。其味辛寒，乃入足厥阴经药。《本经》所主诸证，总属是经所发，取其辛能散内外结滞，寒能除血热气壅故也。然主疗虽多，性有专属。明目之外，余皆可略。\n\n【主治参与】\n《圣惠方》青盲障翳：夜明沙一两，柏叶炙一两，为末，牛胆汁和丸梧子大。每夜卧时，竹叶汤下二十丸。\n\n又方，五疟不止：夜明沙末，每冷茶服一钱，立效。并治胎前疟。\n\n除目疾外，他用甚稀，故不立 “简误”。', NULL, NULL, NULL, '天鼠屎,夜明沙', NULL, '10、天鼠屎,夜明沙', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612876871, 'EC309D405A8C332DDA7E934A45DADB34', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7503, 425, 400106909, '       疗目痛，决痈疖，女子带下，溺不利，除疝瘕。（一名白丁香，一头尖是雄，两头圆者雌。凡用研细，甘草水浸一宿，焙干用。）\n\n      疏：雀屎，本经无气味。察其所主，应是辛苦温之物，性善消散，故外用疗目痛，决痈疖，内服治带下，溺不利，疝瘕也。苏恭以首生男子乳，研雀屎成泥，点目中弩肉，赤脉贯瞳子者，即消，神效。盖取其辛散拔出火毒之义也。\n\n【主治参与】\n《子母秘录》小儿中风，口噤乳不下：雀屎丸如麻子大，服二丸即愈。\n\n《梅师方》诸痈疖已成脓，不肯决，惧针者，涂雀屎疮头，即易决。\n\n《普济方》喉痹乳蛾：白丁香二十个，以沙糖和作三丸。每以一丸，绵裹含咽，即时遂愈。甚者不过二丸，极有奇效。\n\n【简误】\n        雀肉及卵，阴虚火盛者忌之。不可合李食。妊娠食雀肉饮酒，令子多淫。凡服术人忌之。雀屎疗目痛，非风热外邪者不宜用。女子带下溺不利，属肾虚有火者，并忌之。古方同天雄服，此药性极热，有大毒，非阴脏及真阳虚惫者，慎勿轻饵。', NULL, NULL, NULL, '雄雀屎', NULL, '9、雄雀屎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612876872, 'D1751346F0FD474ECC0306328DE41C59', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7504, 425, 400106908, '     味酸，温，无毒。主下气。男子阴痿不起，强之令热，多精有子。\n\n       疏：雀属阳，其气温，味酸，其性淫，故能入下焦阴分，能补暖两肾。夫人身两肾，左为肾，右为命门；左属水，为阴；右属火，为阳。天非此火不能生物，人非此火不能有生。又云：阳生则阴长。可见命门真阳之气，乃人身生化之本也。故命门衰败则阴痿，精寒，绝化育之道。\n\n       雀卵性温补，暖命门之阳气，则阴自热而强，精自足而有子也。温主通行，性又走下，故主下气也。弘景云：术家和天雄服之，令茎大不衰。孟诜云：和天雄、菟丝子末为丸，空心酒下五丸，治男子阴痿，女子带下，便溺不利，除疝瘕。以其有温暖命门之功也。肉味甘温，功用不及卵。', NULL, NULL, NULL, '雀卵', NULL, '8、雀卵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880965, 'A1BBEE4D8C7F0C7D6EAA421436AA06B5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7505, 425, 400106907, '       微寒。主泄利，小便利，遗溺，除热止烦。\n\n        疏：此即肫内黄皮，一名鸡内金是也。肫是鸡之脾，乃消化水谷之所。其气通达大肠、膀胱。二经有热则泄痢遗溺，得微寒之气则热除而泄痢遗溺自愈矣。烦因热而生，热去故烦自止也。今世又以之治诸疳疮多效。\n\n【主治参与】\n《医林集要》小便淋沥，痛不可忍：鸡肫内黄皮五钱，阴干烧存性，作一服，白汤下，立愈。\n\n《子母秘录》鹅口白疮：鸡肫内黄皮，为末，乳服半钱，并可傅之。\n\n《经验方》走马牙疳：鸡肫内黄皮，不落水者五枚，焙存性，枯矾一钱，研细，搽。并治阴头疳蚀。', NULL, NULL, NULL, '鸡内金,肶胵里黄皮', NULL, '7、鸡内金,肶胵里黄皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880966, '605E97A07196597E9EBF1E7BB83C9653', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7506, 425, 400106906, '   主除热火疮，痫痉。\n\n    卵白：微寒，疗目热赤痛，除心下复热，止烦满咳逆，小儿下泄，妇人产难，胞衣不出。醯渍之一宿，疗黄疸，破大烦热。\n\n   疏：鸡子禀生化最初之气，如混沌未分之形。故卵白象天，其气清，其性微寒。卵黄象地，其气浊，其性微温。卵则兼清浊而为体。其味甘，气平无毒。凡痫痉皆火热为病，鸡子之甘，能缓火之标，平即兼凉，能除热，故主痫痉及火疮，并治伤寒少阴咽痛，神效。\n\n【主治参与】\n《医方集成》年深哮喘：鸡子略敲损，浸尿缸中三四日，煮食，能去风痰。\n\n又方，用头生鸡卵七枚，童便浸七日，取出煮熟，每日食一枚，永不出痘。\n\n仲景苦酒汤：治少阴病，咽中伤生疮，痛不能语言，声不出者，用半夏十四枚碎，鸡子一枚去黄，内入半夏、苦酒令满，置刀环中，安火上，令三沸，去滓，少少含咽之。不瘥更作。此方有神效。\n\n《普济方》咽塞生疮，干呕头痛，食不下。法同上，无半夏。\n\n《经验秘方》汤火烧灼：鸡子清和酒调洗，勤洗止痛生肌。\n\n《普济方》涂面驻颜：鸡子一枚，开孔，去黄留白，入金华胭脂，及桑硇少许，纸封，与鸡抱之，俟别卵抱出，以涂面。洗之不落，半年尚红也。\n\n仲景方：治少阴病，得之二三日以上，心中烦，不得卧者，用黄连、黄芩、芍药、阿胶、鸡子黄，先煎三物成，去滓，胶烊尽小冷，鸡子黄搅匀，温服。\n\n刘禹锡《传信方》乱发鸡子膏：治孩子热疮效，见发髲条下。\n\n抱出卵壳：研末，磨障翳。取其蜕脱之义也。苏颂又主伤寒劳复。熬令黄黑，为末，热汤和一合服，取汗出即愈，炒，研细，傅下疳亦妙。卵中白皮，主久咳气结，得麻黄、紫菀和服之立止。', NULL, NULL, NULL, '鸡子', NULL, '6、鸡子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880967, '56BD5E17171166139D7DA21B62B5207D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7507, 425, 400106905, '    微寒。主消渴，伤寒寒热，破石淋，及转筋，利小便，止遗溺，灭瘢痕。（雄鸡屎乃有白，腊月收之。白鸡乌骨者更良。《素问》作鸡矢。）\n\n      疏：鸡屎白微寒，乃肠胃所出之物，故复能走肠胃治病。《素问》云：心腹满，旦食不能暮食，名为鼓胀。治之以鸡矢醴，一剂知，二剂已。\n \n      王太仆注云：《本草》鸡矢，并不治蛊胀，但能利小便。盖蛊胀皆生于湿热，湿热胀满则小便不利，鸡屎能通利下泄，则湿热从小便而出，蛊胀自愈。故曰治湿不利小便，非其治也。本经主石淋，利小便，止遗溺者，正此意耳。转筋者，血热也。伤寒寒热及消渴者，热在阳明也。瘢痕者，血热壅滞肌肉也。寒能总除诸热，故主之也。日华子炒服，治中风失音痰迷。陈藏器和黑豆炒酒浸服，治贼风风痹。盖风为阳邪，因热而生，鸡屎寒能除热，鸡本与风木之气相通，取其治本从类之义也。\n\n【主治参与】\n《普济方》鸡矢醴：治臌胀，旦食不能暮食，用腊月干鸡矢白半斤，袋盛，以酒醅一斗，渍七日，温服三杯，日三。或为末服二钱亦得。\n\n《积善堂经验方》治一切肚腹四肢肿胀，不拘鼓胀、气胀、湿胀、水胀等，用干鸡矢一升，炒黄，以酒醅三碗，煮一碗，滤汁饮之。少顷腹中气大转动利下，即自脚下皮皱消也。未尽，隔日再作。', NULL, NULL, NULL, '鸡矢白,屎白,鸡屎白', NULL, '5、屎白,鸡屎白,鸡矢白', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880968, 'E267BEE6C3D2DA4F597FCFEB8FE4EBFC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', 1, 'admin', '2025-01-17 17:08:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7508, 425, 400106904, '     主起阴气。\n     疏：肝，本经主起阴气，性温可知。味甘微苦，入足厥阴、少阴经。今人用以治少儿疳积，眼目不明者，取其导引入肝，气类相感之用也。\n【主治参与】\n同芜荑、使君子、胡黄连、青黛、五谷虫、谷精草、芦荟，治小儿疳热，目生障翳。\n\n《千金方》阴痿不起，用雄鸡肝三具，菟丝子一升，为末，雀卵和丸小豆大。每五六十丸，酒下，日二服。\n', NULL, NULL, NULL, '鸡肝', NULL, '4、鸡肝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880969, 'AC8716CB6FC1FED3613ABA247A1E119C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7509, 425, 400106903, '     主乳难。用三年老雄者，取其阳气充溢也。凡风中血脉则口角僻㖞，冠血咸而走血，透肌肉，故以之治中风口㖞不正，涂颊上效。丹雄鸡为阳禽，冠血乃诸阳之所聚，故能治中恶客忤邪气。高武《痘疹正宗》云：鸡冠血和酒服，发痘最佳，鸡属巽，属风，顶血至清至高故也。\n\n【主治参与】\n《皆效方》对口毒疮：热鸡冠血，频涂之，取散。\n\n《青囊杂纂》中蜈蚣毒，舌胀出口是也。雄鸡冠血，浸舌，并咽之。\n\n《胜金方》诸虫入耳，鸡冠血滴入即出。\n\n【简误】\n       痘疮须分寒热。鸡血性温，天行疮子虚寒者得之，固可资其起发；倘因血热而干枯焦黑者，误用之能更转剧。世人类用鸡血、桑蠹虫发痘，而不分寒热，误也。', NULL, NULL, NULL, '鸡冠血', NULL, '3、鸡冠血', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880970, 'D737B5B00A13D233D74222AE42370F59', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7510, 425, 400106902, '    味甘，平，无毒，主补虚劳羸弱，消渴，中恶鬼击心腹痛，益产妇，治女人崩中带下，一切虚损诸疾。\n\n     疏：乌骨鸡，得水木之精气，其性属阴，能走肝肾血分，补血益阴，则虚劳羸弱可除。阴回热去，则津液自生，渴自止矣。阴平阳秘，表里固密，邪恶之气不得入，心腹和而痛自止，鬼亦不能犯矣。益阴则冲、任、带三脉俱旺，故能除崩中带下，一切虚损诸疾也。古方乌骨鸡丸，治妇人百病者，以其有补虚、益阴、入血分之功也。\n\n【主治参与】\n古方乌骨鸡丸：治妇人产后蓐劳，及阴虚等证。方中半夏、人参，乃立方者之误，宜去之。\n\n用骨一具煅存性，同红药子、白及、白敛、冰片、雄黄、朱砂、乳香、没药，醋、蜜调傅一切痈疽肿毒，神效。\n\n治中恶心腹痛欲死，但杀白乌骨鸡，乘热薄心即瘥。如鬼击卒死，用其热血涂心下亦妙。', NULL, NULL, NULL, '乌骨鸡', NULL, '2、乌骨鸡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880971, '835CF16B718DD5422B0456DC776AF3C2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7511, 425, 400106901, '     疏：按鸡为阳禽，属木而外应乎风，故在卦为巽，其色虽有丹、白、黄、乌，其种复有乌骨之异，总之性热，补阳起阴，兼有风火之义。惟乌骨者，别是一种，独得水木之精，故主阴虚发热、蓐劳、崩中等证也。\n【简误】\n        鸡，性热动风。凡热病初愈，痈疽未溃，素有风病人，咸忌之。弘景云：小儿五岁以下，食鸡生蛔虫。鸡肉不可合葫、芥、李食，不可合犬肝、犬肾，并令人泄痢。同兔食成痢。同鱼汁食成心瘕。同鲤鱼食成痈疖。同獭肉食成遁尸。同生葱食成虫痔。同糯米食生蛔虫。年久老鸡，脑有大毒，食之能发疔，中其毒发疔者，以玉枢丹丸可解。', NULL, NULL, NULL, '诸鸡', NULL, '1、诸鸡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627523612880972, 'E86A285D4B7C1764620FF6A3A6A70975', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:00:09', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7512, 426, 400107015, '     主产妇腹痛，烧灰酒服，亦治血气。杂诸药用之。\n\n      疏：鱼鳞得水中之阳气，而鲤鱼鳞则又禀阴极生阳之数，性能入血散滞。入血者，阴之用也；散滞者，阳之用也。故主妇人产后腹痛，及血气不和等证。\n\n【主治参与】\n《和剂局方》乌金散：治产后血迷血晕，败血不止，淋沥不断，脐腹疼痛，及崩中下血过多不止。鲤鱼鳞烧、血竭、百草霜、乱发灰、松墨煅酢淬、延胡索、当归、赤芍药，等分为末。每二钱，温酒下。\n\n《外台秘要》：《古今录》疗鱼鲠骨横喉中，六七日不出，取鲤鱼鳞皮烧作屑，以水服之即出。未出再服。\n\n【简误】\n        六阴已极，阳气初生，故能发热动风，风热病者不宜食。天行病后下痢，及有宿癥者，俱不可食。不宜合犬肉、葵菜食。服天门冬、朱砂人不可食。凡炙鲤鱼，不可使烟入目，损目光，三日内必验也。前《和剂局方》乌金散方内有肉桂、当归、延胡索、赤芍药，皆行血之药，而其所主病内，开载崩中下血过多不止，用之则大误矣。慎之！慎之！', NULL, NULL, NULL, '鲤鱼鳞', NULL, '15、鲤鱼鳞', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176198, 'F70B635DE438263D6CE934A9A189872B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7513, 426, 400107014, '      味甘，主咳逆上气，黄疸，止渴。生者主水肿脚满，下气。\n\n      疏：鲤鱼禀阴极之气，故其鳞三十六。阴极则阳复，故《素问》言鱼热中。其气味虽甘平，然多食能令人发风热也。甘可以缓，故主咳逆上气止渴。阴中有阳，能从其类以导之，故能利小便，使黄疸、水肿、脚气俱消也。河间云：鲤之治水，因其气以相感者是矣。\n\n【主治参与】\n《外台秘要》治水肿，用大鲤一尾，赤小豆一升，水二斗，煮可二升余，滤去滓，顿服尽，当下利，利尽即瘥。并治妊娠水肿有神效。', NULL, NULL, NULL, '鲤鱼肉', NULL, '14、鲤鱼肉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176199, '9AA809C2D9D8D1F2CBA5C503F3EC683D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7514, 426, 400107013, '    味苦，寒，无毒。主目热赤痛，青盲，明目。久服强悍益志气。\n\n     疏：凡胆皆苦寒走厥阴，故鲤鱼胆亦主明目，及目热赤痛、青盲也。肝为将军之官，肾为作强之官，二经有热，则虚怯志气衰。苦寒除二经之热，故久服强悍益志气也。', NULL, NULL, NULL, '鲤鱼胆', NULL, '13、鲤鱼胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176200, 'EFCCD0D150121BC5C953C822F8A4424D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7515, 426, 400107012, '    味甘，大温，无毒。主补中益血，疗沈唇。\n\n     疏：鱓鱼得土中之阳气以生，故其味甘、气大温。甘温俱足，所以能补中益血；甘温能通经脉，疗风邪，故又主沈唇，及今人用之以治口眼㖞斜也。\n\n【主治参与】\n与黄耆同食，能益气力。治火丹赤肿，生鱓血涂之效。\n\n【简误】\n性热而补，凡病属虚热者不宜食。时行病后食之多复。过食动风气，兼令人霍乱。', NULL, NULL, NULL, '鱓鱼', NULL, '12、鱓鱼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176201, '322D125EB1C370FDD2C92904543C7672', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7516, 426, 400107011, '     合莼作羹，主胃弱不下食。作鲙，主久赤白痢。烧灰，涂诸疮，或取猪脂煎用。又主肠痈。\n\n       疏：鲫鱼禀土气以生，故其味甘，其气温，无毒。是以能入胃，治胃弱不下食；入大肠治赤白久痢，肠痈。脾胃主肌肉，甘温能益脾生肌，故主诸疮久不瘥也。藏器主虚羸，大明主温中下气，孟诜云调中益五脏，表其益脾和胃之功也。\n\n【主治参与】\n《百一选方》肠风下血，用活鲫鱼一大尾，去肠留鳞，入五倍子末填满，泥固，煅存性，为末。酒服一钱。一方入白矾末二钱，外以棕包，更以纸裹煨存性，研末。每二钱，米饮下。\n\n《经验方》膈气吐食，用大鲫鱼去肠留鳞，切大蒜片填满腹，纸包十重，泥固，晒半干，炭火煨熟，单取肉用，和平胃散一两，杵丸梧子大，密藏。每服三十丸，米饮下。\n\n【简误】\n       鲫鱼调胃实肠，与病无碍。诸鱼之中，惟此可常食。但不宜与沙糖同食，生疳虫。同芥菜食，成肿疾。同猪肝、鸡肉、雉肉、鹿肉食，生痈疽。同麦门冬食，害人。', NULL, NULL, NULL, '鲫鱼', NULL, '11、鲫鱼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176202, '763CD9C5390D684FB82E011181B6B171', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7517, 426, 400107010, '      味甘，寒，无毒。主湿痹，面目浮肿，下大水，疗五痔。有疮者不可食，令人瘢白。\n\n        疏：蠡鱼禀北方玄水之精，得中央阴土之气，故其色黑、味甘，气寒无毒。乃益脾除水之要药也。土虚则水泛滥，土坚则水自清。凡治浮肿之药，或专于利水，或专于补脾，其性各自为用，惟蠡鱼色黑象水，能从其类以导横流之势；味甘土化，能补其不足以遂敦阜之性。补泻兼施，故主下大水及湿痹，面目浮肿，有神效也。五痔因湿热所生，水去则湿气自除。今世俗小儿痘后咸食之。然而早食多食，能令皮肤瘢痕皆黑。本草独云：有疮者食之，令人瘢白，非也。孟诜主下大小便，壅塞气，作鲙与脚气、风气人食，良。苏颂主妊娠有水气，并取其除湿下水益脾之功也。\n\n【主治参与】\n同白术、茯苓、橘皮、姜皮，煮食，下水肿大效。\n\n与蒜作鲙食，能去湿下水。\n\n《食医心镜》治十种水气垂死：蠡鱼一斤重者，煮汁和冬瓜、葱白作羹食。\n\n《灵苑方》喉痹将死者，以蠡鱼胆点入少许即瘥。病深者水调灌之。诸鱼胆皆苦。惟此胆甘可食为异耳。\n\n【简误】\n蠡鱼其功专于去湿下水，他用无所长，且多食能发痼疾，不可不知也。', NULL, NULL, NULL, '蠡鱼', NULL, '10、蠡鱼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176203, '6848871F48E54A94CF7828A506D65C3D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7518, 426, 400107009, '     味咸，平，无毒。主恶疮蚀，五痔，咳逆胸痹，腰痛胁急，鼠瘘，大孔出血，崩中漏下。\n\n      疏：文蛤即花蛤，大小背上有斑纹。得阴水之气，故其味咸气平无毒。经曰：硬则气坚，咸以软之。文蛤之咸，能消散上下结气，故主咳逆胸痹，腰痛胁急也。恶疮蚀，五痔，鼠瘘，大孔出血，崩中漏下，皆血热为病，咸平入血除热，故主之也。更能止烦渴，化痰，利小便。\n\n【主治参与】\n仲景方：伤寒在阳，当以汗解，反以冷水噀之或灌之，其热被劫不得去，更益烦热，皮上粟起，欲饮水，反不渴者，文蛤散主之。文蛤五两，为末。每服方寸匕，沸汤下，甚效。\n\n《千金翼》疳蚀口鼻，数日欲尽：文蛤烧灰，以蜡、猪脂和涂之。\n\n【简误】\n       病属邪热痰结者宜之。气虚有寒者，不得用。', NULL, NULL, NULL, '文蛤', NULL, '9、文蛤', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176204, '6EC70F6CAD1AFA6D3F05FA55E9DE2F0E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7519, 426, 400107008, '    味咸，平，无毒。主目障翳痛，青盲。久服益精轻身。（凡用以面裹煨熟，磨去粗皮，捣细如飞面，方堪入药。一名千里光。得龙骨疗泄精。畏旋覆花。）\n\n    疏：石决明得水中之阴气以生，故其味咸，气应寒无毒。乃足厥阴经药也。足厥阴开窍于目，目得血而能视，血虚有热，则青盲赤痛障翳生焉。咸寒入血除热，所以能主诸目疾也。咸寒又能入肾补阴，故久服益精轻身也。研细水飞，主点外障翳。\n\n【主治参与】\n得甘菊花、生地黄、木贼草、谷精草、羚羊角、人爪、蝉蜕、空青、蜜蒙花、决明子、夜明砂，治青盲障翳。\n\n《明目集验方》羞明怕日：用千里光、甘菊花、甘草各二钱，水煎冷服。\n\n《鸿飞集》痘后目翳：用石决明火煅研，谷精草各等分，为细末，以猪肝蘸食。\n\n目疾外，他用甚稀，故无 “简误”。', NULL, '石决明', NULL, '石决明', NULL, '8、石决明', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176205, '34A1CD9A24BEEB519200FAD9E6796259', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7520, 426, 400107007, '    味咸、甘，平，无毒。主伤中，疝瘕，阴痿，益精生子。女子血闭腰痛，通五淋，利小便水道，又疗男子虚损，五藏气微，梦寐失精遗溺。久服益气养神。二月三月采蒸之，当火炙，不尔令人泄。\n\n     疏：桑螵蛸，桑树上螳螂子也。禀秋金之阴气，兼得桑木之津液。《本经》味咸气平，《别录》甘无毒。气薄味厚，阴也。入足少阴、太阳经。人以肾为根本，男子肾经虚损，则五脏气微，或阴痿，梦寐失精遗溺。咸味属水，内合于肾，肾得之而阴气生长，故能愈诸疾及益精生子也。肾与膀胱为表里，肾得所养则膀胱自固，气化则能出，故利水道通五淋也。女子属阴，肝肾用事，疝瘕血闭腰痛，皆二经为病。咸能益阴入血软坚，是以主之。甘能补中，故主伤中益气。肾足则水自上升，克与心交，故能养神也。\n\n【主治参与】\n《外台秘要》虚劳盗汗，遗精白浊：桑螵蛸炙，白龙骨等分，为细末。每服二钱，空心盐汤下。\n\n寇宗奭方：桑螵蛸散：治男子房劳，小便日数十次，如稠米泔，心神恍惚，瘦瘁食减。其药安神魂，定心志，治健忘，补心气，止小便数。用桑螵蛸、远志、龙骨、菖蒲、人参、茯神、当归、龟甲各如法制，\n\n各一两，为末。卧时人参汤调下二钱。\n\n《千金翼》妇人遗尿：桑螵蛸酒炒为末，白汤服二钱。兼治胎前产后遗尿不禁。\n\n【简误】\n       桑螵蛸气味虽咸平，走肾利水道，然得秋时收敛之气，凡失精遗溺，火气太盛者，宜少少用之。', NULL, NULL, NULL, '桑螵蛸,桑蜱蛸', NULL, '7、桑螵蛸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176206, '26F4FC0E7FE97AB7FD6C50653A151A97', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', 1, 'admin', '2025-01-15 16:13:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7521, 426, 400107006, '      寒，无毒。主解岭南百药毒。（一名玳瑁。）\n\n      疏：瑇瑁，龟类也。得水中至阴之气，故气寒无毒，而解一切热毒。其性最灵，凡遇饮食有毒，则必自摇动，然须用生者乃灵，死者则不能矣。岭南人善以诸毒药造成蛊，人中之则昏愦闷乱，九窍流血则死。惟用活瑇瑁，刺其血饮，或生者磨浓汁服之可解。日华子主破癥结，消痈肿，止惊痫。陈士良主心风，解烦热，行气血，利大小肠。以其性禀纯阴，气味至寒，故治如是等病也。又能解痘毒，神效。\n\n【主治参与】\n杨氏《产乳方》：解一切蛊毒：生玳瑁磨浓汁，服一盏即消。\n\n《灵苑方》预解痘毒，遇时行痘疹，服此未发内消，已发稀少：用生玳瑁、生犀角，各磨浓汁一合，和匀温服半合，日三，最良。\n\n闻人规《痘疮论》：痘疹黑陷，乃心热血凝也。法同上，加入猪心血少许，紫草汁五匙，和匀温服。\n\n《鸿飞集》：迎风目泪，乃肝肾虚热也，用生玳瑁、羚羊角各一两，石燕一双，为末，每一钱，薄荷汤下，日二服。\n\n【简误】\n痘疮虚寒不起发者，不宜服。', NULL, NULL, NULL, '瑇瑁,玳瑁', NULL, '6、瑇瑁,玳瑁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176207, '19751972797DF0279C9EA65B4C4DD0C3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7522, 426, 400107005, '    寒，无毒。主手足皮肤逆胪，镇心，绵裹塞耳主聋，傅面令人润泽好颜色。粉点目中主肤翳障膜。\n\n     疏：珠禀太阴之精气而结，故中秋无月则蚌无胎。其体光明，其性坚硬，大小无定，要以新完未经锁缀者为上。味甘，微咸，气寒，无毒。入手少阴，足厥阴经。心虚有热，则神气浮越；肝虚有热，则目生浮翳障膜。除二经之热，故能镇心去目中障翳也。耳聋本属肾虚有热，所以主之。逆胪者，胪胀也。胸腹胀满气逆，以及于手足皮肤皆肿也。《经》云：诸湿肿满，属脾土。又云：诸腹胀大，皆属于热。此因脾虚有热，兼有积滞所致。真珠味甘，亦能益脾气，寒能除热，体坚能磨积消滞，故主手足皮肤逆胪也。古人未发斯义，所以方书叙论不详，亦为阙略也。珠藏于泽，则川自媚，况涂面，宁不令人润泽好颜色乎？凡小儿惊热风痫，为必须之药。\n\n【主治参与】\n同丹砂、牛黄、犀角、天竺黄、茯神、远志、钩藤钩、琥珀、金箔，治小儿惊痫风热，大人失志癫狂等证。\n\n同炉甘石、龙脑香、白硼砂、空青、人爪，点目能去翳障。\n\n同钟乳石、象牙末、牛黄、冰片、白僵蚕、红铅、天灵盖、蛀竹屑、桦皮灰、没药、明矾，治广疮结毒，及阴蚀疮有奇效。\n\n同人中白、黄檗、青黛、硼砂，和冰片少许，治口疳。加入鸡内金、腻粉治下疳。\n\n《格古论》灰尘迷目，用大珠挹之则消。\n\n《千金方》妇人难产，或胞衣不下：真珠末一两，酒服，立出。\n\n《圣惠方》肝虚目暗：真珠末一两，白蜜二合，鲤鱼胆二枚，和合，铜器煎至减半，新绵滤过，瓶盛，频点取瘥。\n\n痘疮发疔毒方，见谷部豌豆下。\n\n【简误】\n真珠，体最坚硬，研如飞面，方堪服食，不细能伤人脏腑。病不由火热者勿用。', NULL, NULL, NULL, '真珠', NULL, '5、真珠', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176208, '7454D1C33500E9FFA6EF26BE9ED96216', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7523, 426, 400107004, '     味咸、甘，平，有毒。主漏下赤白，破癥瘕，痎疟，五痔，阴蚀，湿痹四肢重弱，小儿囟不合，头疮难燥，女子阴疮，惊恚气，心腹痛，不可久立，骨中寒热，伤寒劳复，或肌体寒热欲死，以作汤良。久服轻身不饥，益气资智，亦使人能食。勿令中湿，中湿即有毒。\n\n      疏：介虫三百六十，而龟为之长。禀金水之气。故味咸而甘，气平。其性神灵能变化，凡入药，勿令中湿，中湿则遂其变化之性而成癥瘕于腹中，故言有毒也。气味俱阴，入足少阴经。方家多入补心药用，以心藏神，而龟性有神，借其气以相通，且得水火既济之义，实非补心之正药也。其主骨中寒热，及伤寒劳复，肌体寒热欲死，痎疟者，皆阴虚而邪热为病。\n\n    《经》曰：伤于湿者，下先受之。湿痹四肢重弱，亦肾阴虚而邪气易犯。肾主骨，肾虚则小儿囟门不合。肾为五脏阴中之阴，阴虚则火热偏至，而为惊恚气、心腹痛。此药补肾家之真阴，则火气自降而寒热邪气俱除矣。益阴除热软坚，故主漏下赤白，癥瘕，五痔，阴蚀阴疮，及小儿头疮也。经曰：邪热不杀谷。热去故令人能食，能食则脾胃得所养而能思，思作睿，故资智。久服益气轻身不饥者，除热益阴之功也。\n\n【主治参与】\n丹溪方：补阴丸：用龟下甲酒炙，熟地黄蒸晒，各六两，黄檗、知母各四两，为末，以猪脊髓和丸梧子大。每百丸，空心温酒下。\n\n《摘玄方》治产三五日不下，垂死，及短小女子交骨不开者，用干龟壳一个酥炙，头发一握烧灰，川芎、当归各一两，为末和匀，每服七钱，水煎服。如人行五里许，再一服。生胎、死胎俱下。\n\n【简误】\n      按：龟、鳖二甲，《本经》所主大略相似。今人有喜用鳖甲，恶用龟甲者；有喜用龟甲，恶用鳖甲者，皆一偏之见也。二者咸至阴之物，鳖甲走肝益肾以除热，龟甲通心入肾以滋阴。第鳖甲无毒可多用，龟甲非千年自死者，则有毒。故方书所用曰败龟板者，取其长年则得阴气多，故有益阴之功用耳。若今新剖之甲，断乎有毒，不宜频使用者，不可不详辨也。妊妇不宜用。病人虚而无热者不宜用。凡入药，须研极细，不尔，留滞肠胃能变癥瘕也。', NULL, NULL, NULL, '龟甲', NULL, '4、龟甲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176209, '6349F1E6E7DBB4D39769A748F1B96331', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7524, 426, 400107003, '     味咸，平、微寒，无毒。主伤寒寒热，温疟洒洒，惊恚怒气，除拘缓鼠瘘，女子带下赤白，除留热在关节，荣卫虚热去来不定，烦满，止汗，心痛气结，止渴，除老血，涩大小肠，止大小便，疗泄精，喉痹，咳嗽，心胁下痞热。久服强骨节，杀邪鬼，延年。（贝母为之使。得甘草、牛膝、远志、蛇床子良。恶麻黄、细辛、吴茱萸。）\n\n         疏：牡蛎得海气结成，故其味咸平，气微寒无毒。气薄味厚，阴也，降也。入足少阴、厥阴、少阳经。其主伤寒寒热，温疟洒洒，惊恚怒气，留热在关节，去来不定，烦满气结心痛，心胁下痞热等证，皆肝胆二经为病。二经冬受寒邪，则为伤寒寒热。夏伤于暑，则为温疟洒洒。邪伏不出，则热在关节，去来不定。二经邪郁不散，则心胁下痞热。邪热甚，则惊恚怒气，烦满气结心痛。此药味咸气寒，入二经而除寒热邪气，则荣卫通，拘缓和，而诸证无不瘳矣。少阴有热，则女子为带下赤白，男子为泄精，解少阴之热而能敛涩精气，故主之也。咸属水，属阴而润下，善除一切火热为病，故又能止汗止渴，及鼠瘘、喉痹、咳嗽也。老血者，宿血也，咸走血而软坚，所以主之。其性收敛，故能涩大小肠，止大小便利也。肾主骨，入肾益精，则骨节自强。邪本因虚而入，肝肾足则鬼邪自去。人以肾为根本，根本固，则年自延矣。更能止心脾气痛，消疝瘕积块，瘿瘤结核，胁下坚满等证，皆寒能除热，咸能软坚之功也。\n\n【主治参与】\n同生地黄、黄耆、龙眼、五味子、酸枣仁、麦门冬、白芍药、茯神、黄檗、当归，治心肾虚，盗汗。\n\n同黄檗、五味子、地黄、山茱萸、枸杞子、车前子、沙苑蒺藜、连须、杜仲，治梦遗泄精。加牛膝则兼治赤白浊。\n\n同地黄、黄檗、阿胶、木耳、炒黑香附、白芍药、地榆、麦门冬、续断、青蒿、鳖甲、蒲黄，止妇人崩中下血，及赤白带下。\n\n仲景方：同龙骨入柴胡、桂枝各汤内，取其收敛浮越之阳气，固脱而镇惊，更能除胸胁中痞硬。\n\n藏器方：同麻黄根、蛇床子为粉，去阴汗。\n\n《本事方》虚劳盗汗：牡蛎粉、麻黄根、黄耆，等分为末。每服二钱，水煎服。\n\n仲景《金匮玉函方》伤寒传成百合病，如寒无寒，如热无热，欲卧不卧，欲行不行，欲食不食，口苦，小便赤色，得药则吐，变成渴疾，久不瘥者用牡蛎煅二两，栝楼根二两，为细末。每服方寸匕，用米饮调下，日三服。\n\n《古今灵验方》水病囊肿：牡蛎粉二两，干姜炮一两，研细，冷水调稠扫上。须臾囊热如火，干则再上。小便利即愈。一方用葱汁、白面同调。小儿不用干姜。\n\n《经验方》男女瘰疬，用牡蛎粉四两，玄参末三两，甘草一两，面糊丸梧子大。每三十丸，酒下，日三服。服尽除根，不拘已破未破，皆效。\n\n《普济方》月水不止：牡蛎煅，研细，米醋搜成团，再煅，研末，以米醋调艾叶末熬膏，丸梧子大。每用醋汤下四五十丸。\n\n【简误】\n       凡病虚而多热者宜用。虚而有寒者忌之。肾虚无火，精寒自出者非宜。', NULL, NULL, NULL, '牡蛎', NULL, '3、牡蛎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176210, '43F11D43EE72E5E8D1E85C136257DA03', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7525, 426, 400107002, '    味甘，微温，无毒。主下痢脓血，补中，续绝伤、金疮，益气，不饥耐老。\n\n     白蜡：疗久泄澼、后重、见白脓，补绝伤，利小儿。久服轻身不饥。\n\n     疏：蜡，石蜜之凝结于底者也。蜜性缓，质柔，故主润脏腑经络；蜡性涩，质坚，故能疗久痢，泄澼后重，下脓血也。甘能益血补中，温能通行经脉，故主续绝伤及金疮也。中得补则气自益，故久服能不饥轻身耐老也。男子女人，大小内外皆可施。而《别录》独云利小儿者，非也。\n\n【主治参与】\n得象牙末等，能去漏管长肉，见象牙条下。\n\n得腻粉、真珠末、黄檗末、龙脑香、铅丹、蛀竹屑、葱白、猪脊髓，治阴蚀恶疮。\n\n同孩儿茶、铅丹、胡粉、水龙骨粉、霜龙骨、黄檗、猪胆汁、炙猪脂作膏，治内外臁疮久不愈。\n\n《金匮》方：调气饮：治赤白痢，少腹痛不可忍，后重，或面青手足俱变者，用黄蜡三钱，阿胶三钱同溶化，入黄连末五钱，搅匀，分三次热服，神效。\n\n《千金方》胶蜡汤：治热痢，及妇人产后下痢。用蜡二棋子大，阿胶二钱，当归二钱半，黄连三钱，黄檗一钱，陈廪米半升，水三升，煮至一升，去米入药，煎至一钟，温服神效。\n\n【简误】\n       火热暴痢不宜用。', NULL, NULL, NULL, '蜜蜡', NULL, '2、蜜蜡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176211, '83D67066C29A33740B64DE48FCDB917F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7526, 426, 400107001, '      味甘，平，无毒，微温。主心腹邪气，诸惊痫痓（痓作痉）。安五藏诸不足，益气补中，止痛解毒，除众病，和百药，养脾气，除心烦，食饮不下，止肠澼，肌中疼痛，口疮，明耳目。久服强志轻身，不饥不老，延年神仙。\n\n       疏：石蜜，蜂采百花酿成。故《本经》味甘，气平。《别录》微温无毒。得草木群英之精华，合露气以酿成。故其气清和，其味纯甘。施之精神、气血、虚实、寒热、阴阳、内外诸病，罔不相宜。《经》曰：里不足者，以甘补之。甘为土化，土为万物之母。石蜜具天地间至甘之味，故能安五藏诸不足，及益气补中除众病也。心经有热，则为诸惊痫痉，得甘缓之气则心火降，烦热除，诸惊痫痉平矣。诸痛痒疮疡，皆属心火，故又能止肌中疼痛及口疮也。甘主解毒，故能和百药。甘主入脾，故能养脾气。脾气得所养，而饮食自下，肠澼止矣。五脏足，气血充，则耳目聪明，不饥不老，轻身强志，延年神仙所自来矣。\n\n【主治参与】\n同芦根汁、梨汁、人乳、牛羊乳、童便，治噎膈，大便燥结，用此润之。有痰加竹沥。\n\n炼熟和诸丸药及膏子，主润五脏，益血脉，调脾胃，通三焦，涂火灼疮能缓痛。\n\n仲景方：蜜导煎：治阳明病自汗，小便反利，大便鞕者，用蜜二合，铜器中微火熬之，候凝如饴状至可丸，乘热捻作挺，令头锐大如指，长寸半许，候冷，纳谷道中，少顷即通也。一法：加皂角细末二分，搅匀，尤速。\n\n《产书》：产后口渴，用熟蜜不计多少，熟水调服即止。\n\n《全幼心鉴》：痘疹作痒难忌，抓成疮及痂，欲落不落，百花膏主之。用上等石蜜，不拘多少，汤和，时时以翎刷之，效。\n\n《肘后方》：天行虏疮，头面及身须臾周匝，状如火疮，皆戴白浆，随决随生。不即疗，数日必死，瘥后疮瘢黯色，一岁方灭。此恶毒之气深入也。用蜜入升麻煎过，数数拭之。\n\n【简误】\n   石蜜虽称补五脏，益脾胃，然而生者性寒滑，能作泄。大肠气虚完谷不化者，不宜用。呕家、酒家，不宜用。中满蛊胀不宜用。湿热脚气不宜用。生者有小毒，尤不宜食。青赤酸者，食之令人心烦。不可与生葱同食，害人。若与莴苣同食，令人利下。食蜜饱后，不可食鲊，令人暴亡。', NULL, NULL, NULL, '石蜜', NULL, '1、石蜜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627536704176212, '758D1D16A4D396345967DB27E1B377B4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 15:53:25', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7527, 427, 400107117, '      平。补五脏，益筋骨，和肠胃，治水气，多食宜人。\n\n       疏：鲈鱼，秋月方美，其得水中之清气者乎？味甘淡，气平，虽有小毒，不至发病，乃与脾胃相宜之物也。肾主骨，肝主筋，滋味属阴，总归于脏。益二脏之阴气，故能益筋骨。脾胃有病，则五脏无所滋养而积渐流于虚弱。脾弱则水气泛滥，益脾胃则诸证自除矣。\n', NULL, NULL, NULL, '鲈鱼', NULL, '17、鲈鱼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142534, 'AB53F1F3FE9C45FF22047BE59F40527A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7528, 427, 400107116, '     味甘，无毒。头中有石如棋子。主下石淋，磨石服之，亦为灰末服。和莼菜作羹，开胃益气。候干食之名为鲞。炙食之，主消瓜成水，亦主卒腹胀，食不消，暴下痢。\n\n      疏：石首鱼得海中水土之气，故其味甘气平无毒。胃属土，甘为土化，故能开胃。胃气开则饮食增，五脏皆得所养而气自益矣。干鲞其性疏利，故能入肠胃宽中、消食止痢。头中石坚重下走，故主下石淋也。凡泄痢腹痛，与夫肠胃诸疾，最忌油腻鱼腥，惟白鲞不忌。盖鲞饮咸水而性平不热，且无脂腻，不惟少热中之患，更有消食理脾实肠胃之功也。', NULL, NULL, NULL, '石首鱼', NULL, '16、石首鱼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142535, '2AC74B2E8EDE196BD6B7EF9029D1FCEA', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7529, 427, 400107115, '     主目暗，滴汁目中，并涂恶疮。\n\n       疏：青鱼胆，色青象木，木气通于肝，肝开窍于目，故能治目暗。味苦气寒，能凉血热，故又主涂恶疮也。\n\n【主治参与】\n龚氏《易简方》治赤目障翳，用黄连熬膏，入大青鱼胆汁和就，再入片脑少许，瓶收密封。每日点之，甚妙。\n\n《龙木论》：一切障翳，鱼胆丸：用青鱼胆、鲤鱼胆、羊胆、牛胆，各半两，熊胆二钱，龙脑香少许，石决明一两，为末，蜜丸梧子大。每空心茶下十丸。\n\n《万氏家抄》乳蛾喉痹：用胆矾盛青鱼胆中，阴干。每用少许，吹喉取吐。\n\n【简误】\n目病非风热盛，而由于血虚昏暗者，不宜用。服术人，不可食青鱼肉。', NULL, NULL, NULL, '青鱼胆', NULL, '15、青鱼胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142536, '46322AA193D0194302792E93C798EC1A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7530, 427, 400107114, '     味咸，寒，有毒。主心腹寒热洗洗，血积癥瘕，破坚，下血闭，生子，大良。一名地鳖。\n\n     疏：䗪虫生于下湿土壤之中，故其味咸，气寒。得幽暗之气，故其性有小毒。以刀断之，中有白汁如浆，凑接即连，复能行走，故今人以之治跌扑损伤，续筋骨有奇效。乃足厥阴经药也。夫血者，身中之真阴也。灌溉百骸，周流经络者也。血若凝滞则经络不通，阴阳之用互乖，而寒热洗洗生焉。咸寒能入血软坚，故主心腹血积，癥瘕血闭诸证。血和而荣卫通畅，寒热自除，经脉调匀，月事时至，而令妇人生子也。又治疟母为必用之药。\n\n【主治参与】\n同自然铜、血竭、乳香、没药、五铢钱、黄荆子、麻皮灰、狗头骨，治跌扑损伤神效。\n\n仲景方：大黄䗪虫丸：治产妇腹痛有干血，用䗪虫二十枚去足，桃仁二十枚，大黄二两，为末，炼蜜杵和，分为四丸，每以一丸，酒一升，煮取二合，温服，当下血也。\n\n仲景鳖甲煎丸：治久疟成癖。\n\n董炳《集验方》治跌扑闪挫：用土鳖阴干一个，临时旋研，入乳香、没药、自然铜、龙骨各等分，麝香少许，为末。每服三分，入土鳖末，以酒调下。须先整定骨乃服，否则接挫也。又可代杖。\n\n【简误】\n    无瘀血停留者，不宜用。', NULL, NULL, NULL, '䗪虫,地鳖', NULL, '14、䗪虫,地鳖', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142537, 'A238B8893E83691DC001CF7ED5B0493F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7531, 427, 400107113, '     味苦，微寒，有毒。主逐瘀血，破下血积，坚痞癥瘕，寒热，通利血脉及九窍，女子月水不通，积聚，除贼血在胸腹五脏者，及喉痹结塞。（一名虻虫。）\n\n      疏：蜚虻，其用大略与䗪虫相似，而此则苦胜，苦能泄结；性善啮牛马诸畜血，味应有咸，咸能走血。完素云：虻饮血而用以治血。故主积聚癥瘕，一切血结为病，如经所言也。苦寒又能泄三焦火邪，迫血上壅，闭塞咽喉，故主喉痹结塞也。今人以其有毒，多不用。然仲景抵当汤、丸，大黄䗪虫丸中咸入之，以其散脏腑宿血结积有神效也。凡毒药之治病，如刑罚之治盗贼，不如是则不足以祛邪反正。《书》曰：若药不瞑眩，厥疾不瘳。正此谓也。其与病相乖不宜用者，详著简误中。\n\n【主治参与】\n入大黄䗪虫丸，治虚劳羸瘦，内有干血，肌肤甲错，两目黯黑。\n\n入抵当汤，治太阳病，身黄，脉沉结，小腹硬，小便自利，其人如狂者。\n\n《备急方》扑坠瘀血：虻虫二十枚，牡丹皮一两，为末。酒服方寸匕，血化为水也。\n\n【简误】\n        伤寒发黄，脉沉结，少腹硬，如小便不利者，为无血证，非蓄血也，不宜用。瘀血未审的者，不宜用。女子月水不通，由于脾胃薄弱，肝血枯竭，而非血结闭塞者，不宜用。孕妇腹中有癥瘕积聚不宜用。凡病气血虚甚，形质瘦损者忌之。', NULL, NULL, NULL, '蜚虻,虻虫', NULL, '13、蜚虻,虻虫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142538, 'E435EC46686A1B5E56B9512C67F0C649', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', 1, 'admin', '2025-01-16 14:26:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7532, 427, 400107112, '     味咸，寒，无毒。主贼风㖞僻，轶筋，及脱肛，惊痫挛缩。\n      蜗牛：味咸，寒。主贼风㖞僻，踠跌，大肠下脱肛，筋急及惊痫。（蛞蝓、蜗牛，《本经》分二条，今按其气味相同，主疗无别，惟形质稍异，故并为一。蜗牛负壳，蛞蝓无壳耳。）\n\n     疏：蛞蝓、蜗牛，禀阴湿之气而生，故味咸气寒无毒。经曰：清静则肉腠闭拒，虽大风苛毒，弗能害也。如阴血亏竭，阳气躁扰，则腠理不密，贼风乘虚而入。风主摇动，中于经络故㖞僻挛缩，轶筋、筋急所自来矣。又风为阳邪，筋脉得之皆燥急，咸寒能益阴润燥软坚，则筋脉舒缓，经络通达而诸证除矣。惊痫者，风热也。脱肛者，大肠热也。踠跌者，血脉伤必发热也。咸寒总除诸热，所以主之。蜈蚣性畏二物，不敢过其所行之路，触其身即死。故人取以治蜈蚣毒。\n\n【主治参与】\n《圣惠方》治大肠因热脱肛，用蜗牛一两烧灰，猪脂和傅，立缩。\n\n《济生方》痔疮肿痛：用蜗牛一杖，入麝香少许，以碗盛，次日取水涂之。丹溪方：用蜗牛浸油涂之，或烧灰傅亦可。\n\n《集验方》发背初起：活蜗牛二百个，以新汲水一盏，瓶内封一宿，取涎水，入真蛤粉，旋调扫傅疮上。日十余度。\n\n《大全良方》痔热肿痛，用大蛞蝓一个，研泥，入片脑一字，燕脂坯子半钱，同傅之。\n\n【简误】\n       其气大寒，非有风热者不宜用。小儿薄弱多泄者不宜用。', NULL, NULL, NULL, '蛞蝓,蜗牛', NULL, '12、蛞蝓,蜗牛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142539, '94930C0F0E1EF7B3681E3BBC9765A7B9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7533, 427, 400107111, '     味甘，有毒，主五痔疮瘘，杀诸虫。\n\n      疏：鳗鲡鱼禀土中之阴气，故其味甘，其气寒。其形类蛇，常与水蛇同穴，故其性有小毒。甘寒而善能杀虫，故骨蒸劳瘵，及五痔疮瘘人，常食之有大益也。烧烟辟蚊，熏屋舍竹木断蛀虫，置骨于衣箱子断蠹。其杀诸虫之验可证矣。腹下有黑斑，背上有白点者，毒甚不可食。重三四斤，及水行昂头者，不可食。妊娠食之，令胎有疾。脾胃薄弱易泄者，勿食。', NULL, NULL, NULL, '鳗鲡鱼', NULL, '11、鳗鲡鱼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142540, '5FFE7052CD170AF1227BC86DDA9F1151', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7534, 427, 400107110, '     味咸、辛，平，无毒。主小儿惊痫夜啼，去三虫，灭黑䵟，令人面色好，男子阴疡（作疮）病，女子崩中赤白，产后余痛，灭诸疮瘢痕。\n\n      疏：蚕属阳，而僵者又兼金木之化。《本经》味咸，《别录》辛平无毒。然详其用，应是辛胜咸劣，气微温之药也。气味俱薄，浮而升，阳也。入足厥阴，手太阴、少阳经。厥阴为风木之位，主藏血。小儿惊痫夜啼，女子崩中赤白，风热乘肝脏也。产后余痛，风寒入血分也。辛能祛散风寒，温能通行血脉，故主如上诸证也。肺主皮毛，而风邪客之，则面色不光润。辛温入肺，去皮肤诸风，故能灭黑䵟，及诸疮瘢痕，令人面色好也。男子阴疡，风湿浸淫也。辛平能散风热，兼能燥湿，是以主之。三虫亦湿热所化，故又能去三虫也。《药性论》治口噤发汗，日华子主中风失音，一切风疰，小儿客忤，男子阴痒痛，女子带下。苏颂治风喉痹欲绝。元素主皮肤诸风如虫行，皆取其性属阳，风热为阳邪，能入皮肤经络，发散诸邪热气也。\n\n【主治参与】\n同丹砂、牛黄、胆星、全蝎、麝香、钩藤钩、犀角、金箔、天竺黄、蝉蜕，治小儿急惊客忤。\n\n《仁存方》开关散：治急喉风痹，用白僵蚕炒，白矾半生半烧，等分为末。每以一钱，用竹沥加姜汁调灌，得吐顽痰，立效。小儿加薄荷。一方用白梅和丸，绵裹含之。\n\n《圣惠方》小儿撮口噤风，面黄赤，气喘，啼声不出，由胎气挟热，流毒心脾，故令舌强唇青，撮口发噤。用白僵蚕二杖，去嘴略炒，为末。蜜调傅唇中，甚效。\n\n《普济方》治大人头风，及小儿惊风，并用大蒜七个，先烧红地，以蒜逐个于地上磨成膏。却以僵蚕一两，去头足，安蒜上，碗覆一夜，勿令泄气，只取僵蚕研水。每用㗜鼻，口内含水，有效。\n\n又方，治腹内龟病，诗云：人间龟病不堪言，肚里生成硬似砖。自死僵蚕白马溺，不过时刻软如绵。\n\n《药性论》灭诸疮瘢痕：白僵蚕衣、鱼鹰屎白等分，傅之。\n\n《圣惠方》瘾疹风疮疼痛：白僵蚕焙研，酒服一钱，立瘥。\n\n《小儿宫气方》小儿口疮通白者，白僵蚕炒为末，蜜和傅之，效。兼治内疳蚀疮。\n\n【简误】\n      僵蚕性辛温，辛能散，其功长于祛风化痰，散有余之邪。凡中风口噤，小儿惊痫夜啼，由于心虚神魂不宁，血虚经络劲急所致，而无外邪为病者，忌之。女子崩中，产后余痛，非风寒客入者，亦不宜用。今世治小儿惊风，不问虚实，一概混施，误甚！误甚！', NULL, NULL, NULL, '白僵蚕', NULL, '10、白僵蚕', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142541, '4894A81F98A36E762CD311F51E9EAEAD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7535, 427, 400107109, '   主血风病，益妇人。一名马明退。（近世医家多用初出蚕子壳在纸上者。东方诸医用老蚕眠起所蜕皮。功用虽相近，当以蜕皮为正，用之微炒。）\n\n    疏：蚕退如蝉蜕、蛇蜕之类，各因其本质以为用。蚕退得蚕气之余，故能治血风病。血热则生风，妇人以血为主，故尤益妇人也。近世以之疗痘疹，去目中翳障，其义犹蝉蜕也。\n\n【主治参与】\n《集验方》走马牙疳：用蚕退纸灰，入麝香少许，贴之。并治口疮。\n\n又方，治缠喉风：蚕蜕纸烧存性，蜜丸芡实大，含化咽津。蚕已出蛾，取退煅存性为末，服之能排脓、穿毒疮口。\n\n【简误】\n妇人血虚无风湿者，不宜用。', NULL, NULL, NULL, '蚕退,马明退', NULL, '9、蚕退,马明退', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142542, 'C2F376DF1EB5A617DEA1963170289BD9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7536, 427, 400107108, '     瘫缓筋骨不随，由于血虚不能荣养经络，而无风湿外邪侵犯者，不宜服。', NULL, NULL, NULL, '蚕沙,蚕屎', NULL, '8、蚕沙,蚕屎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142543, '3424D146B3F8098993E73CBCE5273B21', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7537, 427, 400107107, '   雄者有小毒。主益精气，强阴道，交接不倦，亦止精。\n\n    疏：原蚕蛾，乃是晚蚕第一番出者，其子再复出者为二蚕。此二蚕之种，其蛾性最淫，出茧便媾。味咸气温热，故能强阴益精，令交接不倦也。日华子主壮阳事，止泄精，尿血，暖水脏。盖取其性淫助阳，咸温入肾之功耳。\n\n【主治参与】\n《千金方》丈夫阴痿不起：未连蚕蛾二升，去头翅足，炒为末，蜜丸梧子大。每夜服一丸，可御十女，以菖蒲酒止之。\n\n《圣济总录》玉枕生疮，生枕骨上，如痈，破后如箸头，用原蚕蛾炒、石韦等分，为末，干贴，瘥。\n\n【简误】\n少年阴痿，由于失志者，不宜用。阴虚有火者，咸忌之。', NULL, NULL, NULL, '原蚕蛾', NULL, '7、原蚕蛾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142544, 'C466954A11ED36F2EE6E1FE87C76A61B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7538, 427, 400107106, '      味咸，微温，无毒。主女子漏下赤白，经汁血闭，阴蚀肿痛，寒热癥瘕，无子，惊气入腹，腹痛环脐，阴中寒肿。令人有子。又止疮多脓汁不燥。（一名海螵蛸，一名乌鲗骨，一名墨鱼。）\n\n       疏：乌贼鱼骨禀水中之阳气以生，故其味咸，气微温无毒。入足厥阴、少阴经。厥阴为藏血之脏，女人以血为主，虚则漏下赤白，或经汁血闭，寒热癥瘕；少阴为藏精之脏，主隐曲之地，虚而有湿，则阴蚀肿痛。虚而寒客之，则阴中寒肿。男子肾虚则精竭无子，女子肝伤则血枯无孕。咸温入肝肾，通血脉而祛寒湿，则诸证除，精血足，令人有子也。其主惊气入腹，腹痛环脐者，盖肝属木，主惊，惊入胆则荣气不和，故腹痛环脐也。入肝胆舒荣气，故亦主之。温能燥湿，故又主疮多脓汁也。按《素问》云：有病胸胁支满者，妨于食，病至则先闻腥臊臭，出清液，先唾血，四肢清，目眩，时时前后血，病名曰血枯。得之年少时，有所大脱血，或醉入房中，气竭肝伤，故月事衰少不来。治之以四乌鲗骨一藘茹，为末，丸以雀卵，大如小豆。每服五丸，饮以鲍鱼汁，所以利肠中及伤肝也。观此则其入厥阴血分，为女人崩漏下血的要药可知矣。\n\n【主治参与】\n《圣惠方》赤白目翳：用乌鲗骨一两，去皮为末，入片脑少许点之。\n\n《澹寮方》底耳出脓：海螵蛸半钱，麝香一字，为末。以绵杖绞净，吹入。\n\n《圣惠方》小儿脐疮出血及脓：海螵蛸、干胭脂，为末，油调搽之。\n\n《圣济总录》骨鲠在喉：乌贼鱼骨、橘红焙，等分为末，寒食面和饧丸芡子大。每一丸含化。\n\n《简便单方》舌肿出血不止：乌贼骨、蒲黄各等分，炒为末，涂之。\n\n【简误】\n其气味咸温，血病多热者勿用', NULL, NULL, NULL, '海螵蛸,乌贼鱼骨,乌鲗骨,墨鱼,乌贼骨', NULL, '6、海螵蛸,乌贼鱼骨,乌鲗骨,墨鱼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142545, '0346E50BB1F0785474B67CD09EE7F1D9', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', 1, 'admin', '2025-01-16 14:18:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7539, 427, 400107105, '       味咸、甘，寒，无毒。主小儿痫，女人生子不出。灰服之，主久痢。（一名枯蝉，一名金牛儿。凡用洗去泥，并去翅足。浆水煮，晒干用。）\n\n       疏：蝉禀水土之余气，化而成形，其飞鸣又得风露之清气，故能入肝祛风散热，如《药性论》主小儿壮热惊痫是矣。其主妇人生子不下者，取其蜕脱之义。治久痢者，以其有甘寒之功也。其鸣清响，能发音声。其性善蜕，能脱翳障。其体轻浮，能发疮疹。其味甘寒，能除风热。故陈藏器主哑病。寇宗奭主目昏障翳，小儿疮疹出不快。及今人治头风眩晕，皮肤风热，痘疹作痒，疔肿毒疮，大人失音，小儿噤风天吊，惊哭夜啼等证，皆以其有如上诸功能也。\n\n【主治参与】\n同羚羊角、蜜蒙花、白蒺藜、草决明、木贼草、谷精草、甘菊花、夜明沙、生地黄、黄连、女贞实，治目盲障翳。\n\n同丹砂、茯神、真珠、牛黄、僵蚕、天竺黄、钩藤钩、犀角、琥珀、全蝎，治小儿风热急惊痫病。\n\n同犀角、生地黄、紫草、麦门冬、连翘、金银花，治痘疮血热，出不快。\n\n同石膏、鼠粘子、赤柽木、薄荷、玄参、甘草、葛根、栝楼根、麦门冬，治大人小儿痧疹。\n\n《普济方》治小儿夜啼不止，状若鬼祟，以蝉蜕下半截为末，每一字，钩藤汤调下，或入辰砂少许亦可。并治天吊惊啼。\n\n《全幼心鉴》痘疮作痒：蝉蜕三七枚，炙甘草各一钱，水煎服。\n\n钱氏方：痘后目翳，蝉蜕为末，每一钱，羊肝煎汤下，日二服。\n\n《和剂局方》蝉花散：治肝经蕴热，风毒之气内搏上攻，眼目赤肿，翳膜疼痛昏涩，内外障翳，咸治之。用蝉蜕、谷精草、刺蒺藜、甘菊花、防风、草决明、蜜蒙花、甘草、羌活、黄芩、蔓荆子、川芎、木贼草、荆芥，等分为末。每二钱，茶清调，食后临卧各一服。\n\n【简误】\n痘疹虚寒证不得服。', NULL, NULL, NULL, '蝉蜕,枯蝉,金牛儿', NULL, '5、蝉蜕,枯蝉,金牛儿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142546, '1BD05AB7B1E437C08BF09F62A16B853F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7540, 427, 400107104, '    味咸，寒，有毒。主胸中邪气热结痛，㖞僻面肿。败漆烧之，致鼠。解结散血，愈漆疮，养筋，益气。\n    爪：主破胞堕胎。\n\n    疏：蟹禀水气以生，故其味咸气寒。《本经》虽云有毒，然今人多食之卒无害。其有害者，大抵形质怪异，如后文所载诸种，始有大毒耳。外骨内肉，阴包阳也。入足阳明，足厥阴经。《经》曰：热淫于内，治以咸寒。故主胸中邪气热结痛也。㖞僻者，厥阴风热也。面肿者，阳明热壅也。解二经之热，则筋得养而气自益，㖞僻、面肿俱除矣。咸走血而软坚，故能解结散血。漆得蟹则化为水，烧之可集鼠于庭，此物性之相感相制，莫能究其义也。愈漆疮者，以其能解漆毒故也。\n\n爪性迅利，故能破胞堕胎也。\n\n【主治参与】\n日华子：产后肚痛，血不下者，以酒食之。筋骨折伤者，生捣炒罯之。\n\n陈藏器：续断绝筋骨，去壳同黄，捣烂微炒，纳入疮中，筋即连也。\n\n寇宗奭：小儿解颅不合，以蟹螯同白及末捣涂，以合为度。\n\n唐瑶《经验方》骨节离脱：生蟹捣烂，以热酒倾入，连饮数碗，其渣涂。半日内，骨肉谷谷有声即好。\n\n董炳《验方》：中鱓鱼毒，食蟹即解。\n\n胡洽方：治孕妇僵仆，胎上抢心，有蟹爪汤。\n\n《千金方》神造汤：治子死腹中，或双胎一死一生，服之令死者出，生者安，神验。用蟹爪一升，甘草二尺，东流水一斗，以苇薪煮至二升，滤去滓，入真阿胶三两，令烊，顿服，或分二服。若人困不能服者，灌入即活。\n\n【简误】\n      蟹性冷，能散血热为病，故跌扑损伤，血热瘀滞者宜之。若血因寒凝结，与夫脾胃寒滑腹痛，喜热恶寒之人，咸不宜食。有独螯、独目、两目相向、六足、四足、腹下有毛、腹中有骨头、背有星点、足斑目赤者，并有毒，不可食，能害人。被其毒者，冬瓜汁、紫苏、蒜、豉、芦根汁，皆可解之。不可与柿及荆芥食，发霍乱动风，木香汁可解。', NULL, NULL, NULL, '蟹', NULL, '4、蟹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142547, '1912F560F312823A02A2A649CD50B7DB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7541, 427, 400107103, '    味咸，平，无毒。主心腹癥瘕，坚积寒热，去痞，息肉，阴蚀，痔，恶肉，疗温疟，血瘕腰痛，小儿胁下坚。\n     肉：味甘。主伤中，益气补不足。（恶矾石。）\n\n    疏：鳖甲全禀天地至阴之气，故其味咸平无毒。润下作咸，象水明矣。本乎地者亲下，益阴何疑？甲主消散者，以其味兼乎平，平亦辛也。咸能软坚，辛能走散，故《本经》主癥瘕坚积寒热，去痞疾、息肉、阴蚀、痔核、恶肉。\n\n    《别录》疗温疟者，以疟必暑邪为病，类多阴虚水衰之人，乃为暑所深中，邪入阴分，故出并于阳而热甚，入并于阴而寒甚，元气虚羸则邪陷而中焦不治，甚则结为疟母。甲能益阴除热而消散，故为治疟之要药，亦是退劳热在骨，及阴虚往来寒热之上品。血瘕腰痛，小儿胁下坚，皆阴分血病，宜其悉主之矣。劳复、女劳复为必须之药。劳瘦骨蒸，非此不除。产后阴脱，资之尤急。\n\n【主治参与】\n仲景鳖甲煎丸，治疟母之要药。\n\n得牛膝、当归，佐以橘皮、何首乌、知母、麦门冬治久疟。\n\n同知母、石膏、麦门冬、贝母、竹叶，治温疟热甚、渴甚，无肺热病者加人参。若疟发热甚、渴甚，又寒甚汗多，发时指甲黯，状若欲死，并加桂枝，有神。去桂枝，治瘅疟良。\n\n得青蒿、麦门冬、五味子、地黄、枸杞、牛膝，治骨蒸劳热。甚则加银柴胡、地骨皮、胡黄连。\n\n肉：主伤中，益气补不足，腹中结热，妇人漏下，阴虚羸瘦，性冷，补一切阴虚人，宜常食之。\n\n【简误】\n鳖甲，妊娠禁用。凡阴虚胃弱，阴虚泄泻，产后泄泻，产后饮食不消，不思食，及呕恶等证，咸忌之。', NULL, NULL, NULL, '鳖甲', NULL, '3、鳖甲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214142548, '02FC386D2CC20C108FBCE58309D7079C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7542, 427, 400107102, '   味苦、咸，平，有毒。主惊痫瘈疭，寒热邪气，癫疾，鬼精盅毒，肠痔。火熬之良。又疗蜂毒、毒肿。\n\n   疏：蜂性有毒，螫人则痛极，以其得火气之甚也。故蜂房味苦，气平，性亦有毒。《别录》言咸，当作辛咸。辛散苦泄，咸可软坚，故主惊痫瘈疭，寒热邪气，癫疾，鬼精蛊毒，肠痔等证也。疗蜂毒、毒肿者，取其气类相从，以毒攻毒之义也。苏恭以乱发、蛇皮，三物合烧灰，酒服方寸匕，治恶疽附骨痈，根在脏腑，历节肿，出疔肿恶脉诸毒。大明煎水漱齿，止风虫疼痛，洗乳痈，蜂疔恶疮。皆取其攻毒散邪杀虫之功耳。\n\n【主治参与】\n《子母秘录》脐风湿疮久不瘥者，蜂房烧末，傅之效。\n\n《袖珍方》风虫牙痛：蜂房一枚，盐实孔内，烧过研末，擦之，盐汤漱去。一方同细辛煎，水漱之。\n\n又方，喉痹肿痛：露蜂房灰、白僵蚕等分，为末，吹入喉内，或用乳香汤服半钱。\n\n《济众方》女人妒乳、乳痈，汁不出，内结成肿，名妒乳：用蜂房烧灰研末，每服二钱，水一盏，煎六分，去滓温服。\n\n《经验方》治漏痔，蜂房烧存性，研细掺之。干则菜油调傅。\n\n【简误】\n蜂房主惊痫瘈疭，及诸痈疽恶毒，正取其攻散邪恶，以毒攻毒之意。若病属气血虚，无外邪者，与夫痈疽溃后元气乏竭者，皆不宜服。', NULL, NULL, NULL, '露蜂房，蜂房', NULL, '2、露蜂房，蜂房', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214146629, '572A9571BD076F1D634ABD9B53E3F5C7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7543, 427, 400107101, '    味苦，平，无毒。主五痔，阴蚀，下血赤白、五色血汁不止，阴肿痛引腰背，酒煮杀之。又疗腹痛疝积，亦烧为灰酒服之。（得酒良。畏桔梗、麦门冬。）\n\n     疏：猬，鼠类，属水。其皮毛戟刺如针，属金。故味苦平，平即兼辛。大肠属金，以类相从，故能治大肠湿热、血热为病，及五痔，阴蚀，下血赤白，五色血汁不止也。阴肿痛引腰背，腹痛疝积，皆下焦湿热邪气留结所致，辛以散之，苦以泄之，故主之也。\n\n肉：味甘平。能开胃气，止反胃，亦主痔瘘肠风。\n\n【主治参与】\n同象牙末等，治通肠漏，见象牙条下。\n\n《衍义》五痔下血：用猬皮、穿山甲等分，烧存性，入肉豆蔻一半，空心米饮下一钱，妙。\n\n《杨氏家藏方》肠风下血：猬皮一枚，木贼草半两，炒黑为末。每二钱，热酒调下。\n\n【简误】\n    凡食其肉，当去骨，误食令人瘦劣，诸节渐小也。', NULL, NULL, NULL, '猬皮', NULL, '1、猬皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 627557214146630, '29A8DF267FC9B27B3F0ABD435E7922E1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-28 17:16:53', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7544, 428, 400107218, '       微寒。主五邪惊啼悲伤。烧之作灰，以酒或水和方寸匕，疗蚁瘘。\n\n        疏：鲮鲤甲，穿山穴居，其性善走。味辛平，气微寒有毒。入足厥阴，兼入手足阳明经。邪魅着人，则惊啼悲伤不已，辛主散，则邪魅去，惊啼悲伤止矣。喜食蚁，又能入大肠，故疗蚁瘘。蚁瘘者，即世人所云漏也。性走能行瘀血，通经络，故又有消痈毒，排脓血，下乳，和伤，发痘等用。\n\n【主治参与】\n鲮鲤甲，俗名穿山甲。土炒，同乳香、没药、番降香、红曲、山查、川通草、童便，治上部内伤，胸膈间疼痛。\n\n同当归、白芷、金银花、连翘、紫花地丁、夏枯草、牛旁子、乳香、没药、甘草、贝母、皂角刺，治痈肿未溃，资为引导。\n\n佐地榆，治便毒。\n\n《直指方》：治鼠痔成疮肿痛，用穿山甲尾尖处一两，煅存性，鳖甲酥炙一两，麝香半钱，为末。每服一钱，空心茶下。\n\n又方，乳汁不通，涌泉散：用穿山甲炮研末，酒服方寸匕，日二服，外以油梳梳乳，即通。\n\n又方，便毒便痈：穿山甲半两，猪苓二钱，并以醋炙研末，酒服二钱。得紫草、生犀角、生地黄，治痘疮毒盛，不得起发，色带干红枯燥者有功。\n\n【简误】\n      痈疽已溃，不宜服。痘疮元气不足不能起发者，不宜服。', NULL, NULL, NULL, '鲮鲤甲', NULL, '18、鲮鲤甲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791878, '53A2955699D9BD6F5969886C731A8675', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7545, 428, 400107217, '     味甘、辛，有毒。疗诸风瘾疹，及中风半身不遂，口眼㖞斜语涩，手足抽掣。形紧小者良。\n\n      疏：蝎禀火金之气以生，本经味甘辛有毒。然察其用，应是辛多甘少，气温。入足厥阴经。诸风掉眩，属肝木，风客是经，非辛温走散之性，则不能祛风逐邪，兼引诸风药入达病所也。故大人真中风，小儿急惊风，皆须用之。\n\n【主治参与】\n《全幼心鉴》：小儿脐风，宣风散：治小儿初生断脐后伤风，唇青口撮，出白沫，不乳，用全蝎二十一个，无灰酒涂炙为末，入麝香少许。每用金、银煎汤，调半字服之。\n\n《经验方》大人风涎：用蝎一个，头尾全者，以薄荷四叶裹定，火上炙焦，同研为末。作一服，白汤下。小儿惊风分四服，如前服。得胡桃同煅，共研，黄耆、金银花汤下，治横痃不收口。\n\n【简误】\n       蝎，风药也。似中风，及小儿慢脾风病属于虚，法咸忌之。', NULL, NULL, NULL, '蝎', NULL, '17、蝎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791879, '7987AB36D9D80D48DCC2C11A03865DD2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7546, 428, 400107216, '      味甘，温，无毒。主疗心腹冷气，小儿五疳，辟疫，治肠风，通利气脉，女子月闭。出北地，此是寒号虫粪也。\n      \n       疏：寒号虫，畏寒喜暖，故其粪亦温，味甘而无毒。气味俱厚，阴中之阴，降也。入足厥阴、手少阴经。性专行血，故主女子血闭。味甘而温，故疗心腹冷气，及通利气脉也。其主小儿五疳者，以其亦能消化水谷。治肠风者，取其行肠胃之瘀滞也。凡心胸血气刺痛，妇人产后少腹儿枕块诸痛，及痰挟血成窠囊，血凝齿痛诸证，所必须之药。\n\n【主治参与】\n同泽兰、牛膝、益母草、延胡索、牡丹皮、红花、赤芍药、山查、生地黄，治产后恶露不净，腹中作疼。加桃仁其效更速，勿过剂。同番降香、红曲、川通草、红花、延胡索、韭菜、童便，治胃脘瘀血作痛。\n同木香、乌药，治周身血气刺痛。\n\n《和剂局方》失笑散：治男女老少心痛，腹痛，少腹痛，并少腹疝气，诸药不效者，能行能止；妇人妊娠心痛，及产后心痛，少腹痛，血气痛尤妙。用五灵脂、蒲黄等分，研末。先以醋二杯调末，熬成膏，入水一盏，煎至七分，连药热服。未止再服。一方以酒代醋，一方以醋糊丸，童便酒服。\n\n《杨氏产乳方》紫金丸：治产后恶露不快，腰痛，少腹如刺，时作寒热头痛，不思饮食；又治久有瘀血，月水不调，黄瘦不食；亦疗心痛，功与失笑同。以五灵脂，水淘净炒末一两，以好米醋调稀，慢火熬膏，入真蒲黄末，和丸龙眼大。每服一丸，以水与童便各半盏，煎至七八分，温服，少顷再服，恶露即下。血块经闭者，酒磨服之。\n\n《图经》：产后血晕不知人事，用五灵脂二两，半生半炒，为末。每服一钱，白水调下。如口噤者，斡开灌之，入喉即愈。\n\n丹溪方：产后腹痛，五灵脂、香附、桃仁，等分研末，醋糊丸。服一百丸，白术、牛膝、陈皮汤下。\n\n《事林广记》卒暴心痛：五灵脂炒一钱半，干姜炮三分，为末。热酒服，立愈。\n\n《产宝方》胎衣不下，恶血冲心：用五灵脂半生半炒，研末。每服二钱，温酒下。\n\n《百一选方》：痰血凝结，紫芝丸：用五灵脂水飞，半夏汤泡，等分为末，姜汁浸，蒸饼丸梧子大。每米饮下二十丸。\n\n夏子益《奇疾方》：血溃怪病，凡人眼中白珠浑黑，视物殊常，毛发坚直如铁条，能饮食而不语，如醉，名曰血溃。以五灵脂为末，汤服二钱即愈。\n\n【简误】\n      五灵脂，其功长于破血行血，故凡瘀血停滞作痛，产后血晕，恶血冲心，少腹儿枕痛，留血经闭，瘀血心胃间作痛，血滞经脉，气不得行，攻刺疼痛等证，在所必用。然而血虚腹痛，血虚经闭，产妇去血过多发晕，心虚有火作痛，病属血虚无瘀滞者，皆所当忌。', NULL, NULL, NULL, '五灵脂', NULL, '16、五灵脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791880, '32787D9F02E4B303CEBEDD91A18C352F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7547, 428, 400107215, '      味咸，寒，有毒，主小儿惊痫瘈疭，腹胀寒热，大人癫疾狂昜（音羊），手足端寒，支满，贲豚。\n\n       疏：蜣螂禀阴湿之气以生，故其味咸气寒有毒。入足厥阴、手足阳明经。小儿惊痫瘈疭，腹胀寒热，大人癫疾狂昜，皆肝、胃、大肠三经风热壅盛所致。咸寒除三经之邪热，则诸证自瘳。《别录》主手足端寒、支满者，以脾胃主四肢而治中焦。脾气结滞，则血液不能通行灌溉于手足。胃家热壅及大肠结实，则中焦不治而气逆支满。行三经之壅滞，则所苦减除矣。咸能软坚入肾，故又主奔豚也。古今方书以之治一切痔瘘，及疔肿疽疮，出箭镞之用。\n\n【主治参与】\n《本事方》推车散：治大小便经月不通欲死者，用推车客七个，男用头，女用身；蝼蛄七个，男用身，女用头，新瓦焙，研末。用虎目树南向皮煎汁调服，只一服，立通。\n\n一方，大肠脱肛：蜣螂烧存性，为末，入冰片研匀，掺上托之即入。\n\n唐氏方：肠漏出水，用蜣螂一枚，阴干，入冰片少许，为细末。纸捻蘸末入孔内，渐渐生肉，药自退出，即愈。\n\n刘涓子方：附骨疽疮：蜣螂七枚，同大麦捣傅。\n\n《广利方》：无名恶疮，忽得不识者，用蜣螂杵汁涂之。\n\n刘禹锡纂 “柳州救三死方” 云：元和十一年得疔疮，凡十四日益笃，善药傅之莫救。长庆贾方伯教用蜣螂心，一夕百苦皆已。明年正月，食羊肉又大作，再用如神验。其用蜣螂心，在腹下度取之，其肉稍白是也。贴疮半日许，再易，血尽根出即愈。蜣螂畏羊肉，故食之即发。其法盖出葛洪《时后方》。\n\n杨氏《家藏方》：箭镞入骨不可移者，用巴豆微炒，同蜣螂捣涂，斯须痛定，必微痒，忍之。待极痒不可忍，乃撼动拔之立出。凡诸疮皆可疗也。\n\n捣为丸，塞下部，引痔虫出尽，永差。\n\n【简误】\n蜣螂有毒，外用易臻厥功。内服非虚人所宜。非不得已，勿轻试。', NULL, NULL, NULL, '蜣螂', NULL, '15、蜣螂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791881, 'CA44EBBAEA44762F070EF21B2026615A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7548, 428, 400107214, '      味甘、咸，温，有毒。主中风，湿痹不仁，筋脉拘急，口面㖞斜，半身不遂，骨节疼痛，大风疥癞，及暴风瘙痒，脚弱不能久立。一名褰鼻蛇。白花者良。（出蕲州，龙头虎口，黑质白花，目开如生，尾有爪甲，真蕲产也。）\n\n         疏：白花蛇，生于土穴阴霾之处，禀幽暗毒厉之气，故其味虽甘咸，性则有大毒也。《经》曰：风者，百病之长，善行而数变。蛇性走窜，亦善行而无处不到，故能引诸风药至病所，自腑脏而达皮毛也。凡疠风、疥癣、㖞僻、拘急、偏痹不仁、因风所生之证，无不借其力以获瘥。本经著其功能，信非虚矣。\n\n【主治参与】\n同苦参、何首乌、威灵仙、鳖虱胡麻、天门冬、百部、豨莶、漆叶、刺蒺藜，治疠风，并遍身顽痹、疥癣。\n\n《医垒元戎》驱风膏：治风瘫疠风，遍身疥癣，用白花蛇肉四两，酒润炙干，天麻七钱半，薄荷、荆芥各二钱半，为末，好酒二升，蜜四合，石器熬成膏。每服一盏，温汤服，日三服，急于暖处出汗，十日效。\n\n《瑞竹堂经验方》白花蛇酒：治诸风疠癣，用白花蛇一条，酒润，去皮骨取肉，绢袋盛之，蒸糯米一斗，安曲于缸底，置蛇于曲上，以饭安蛇上，用物密盖三七日，取酒，以蛇晒干为末，每服三五分，温酒下，仍以浊酒并糟作饼食之，尤佳。\n\n洁古白花蛇散治大风病：白花蛇、乌梢蛇，各取净肉二钱酒炙，雄黄二钱，大黄五钱，为末。每服二钱，白汤下，三日一服。\n\n乌蛇：即乌梢蛇，气味所主，经白花蛇同，第性善无毒耳。修事亦同，不复载。（色黑如漆，尾细有剑脊者良。）\n\n【简误】\n白花蛇，性走窜有毒，疠风、疥癣、顽痹等证，诚为要药。然而中风口面㖞斜，半身不遂，定缘阴虚血少、内热而发，与得之风湿者殊异，非所宜也，医师宜辨之。头尾并骨俱有大毒，须尽去之。\n', NULL, NULL, NULL, '白花蛇,褰鼻蛇', NULL, '14、白花蛇,褰鼻蛇', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791882, '50DD4DF0512B5D5D8EC225B4E4708E2D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', 1, 'admin', '2025-01-03 17:25:59');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7549, 428, 400107213, '      大寒。主目热赤痛，止渴。\n\n      疏：田螺，产于水田中，禀水土之阴气，故其汁大寒，味应甘，性无毒。陶隐居以真珠、黄连末纳入，良久取汁点目痛，神效。以其寒能除热也。解一切有余之热，故能止渴及醒酒。\n\n【主治参与】\n丹溪方：治噤口痢疾，用活大田螺二枚，捣烂，入麝香三分，作饼，烘热贴脐间。半日热气下行，即思食矣。甚效。\n\n又方治小便不通，腹胀如鼓：用田螺一枚，盐半匕，生捣，傅脐下一寸三分，即通。\n\n《经验方》大肠脱肛坠下三五寸者，用大田螺二三枚，将净水养去泥，用鸡爪黄连研细末，入厣内，待化成水，以浓茶洗净肛门，将鸡翎蘸水刷之，以软帛托上，自然不再发也。\n\n《乾坤生意》痔漏疼痛，用田螺一个，入龙脑一分在内，取水搽之效。\n\n【简误】\n目病非关风热者，不宜用。', NULL, NULL, NULL, '田螺,田中螺汁', NULL, '13、田螺,田中螺汁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791883, '90451CCAB03045B35F872306F1A57319', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7550, 428, 400107212, '       味辛，寒，有毒。主寒热，鬼疰蛊毒，鼠瘘，疥癣，恶疮疽，蚀死肌，破石癃血积，伤人肌，堕胎。（马刀为之使。畏巴豆、丹参、空青、甘草。）\n\n       疏：斑猫禀火金相合之气，故其味辛气寒。扁鹊云：有大毒。近人肌肉则溃烂，毒可知矣。入手阳明、手太阳经。性能伤肌肉，蚀死肌，故主鼠瘘、疽疮、疥癣。辛寒能走散下泄，故主破石癃血积，及堕胎也。至于鬼疰蛊毒，必非极辛大毒之药所能疗，此《本经》之误。甄权主瘰疬，通利水道。以其能追逐肠胃垢腻，复能破结走下窍也。\n\n【主治参与】\n治瘰疬，用肥皂二斤，去核，每服皂一荚，入斑猫四枚，线缚蒸，取出，去斑猫并肥皂皮筋，得净肉十两，入贝母二两，栝楼根、玄参、甘草、薄荷叶各一两五钱，共为末，以肥皂捣如泥，为丸梧子大。每服一钱，白汤吞。服后腹疼，勿虑，此药力追毒之故。\n\n治癫犬咬方：用斑猫七个，去头足并翅，酒洗，和湿糯米铜勺内炒，米熟为度，随将二物研成细末，加六一散三两，分作七服，每清晨一服，白汤调下。本人头顶心必有红发二三根，要不时寻觅拔去。\n《经验方》内消瘰疬，不拘大人小儿：用斑猫一两，去头足翅，以粟米一升同炒，米焦去米，入薄荷四两，为末，乌鸡子清丸如绿豆大。空心腊茶下三丸，加至五丸，却每日减一丸，减至一丸后，复日增一丸，以消为度。\n\n【简误】\n        斑猫，性有大毒，能溃烂人肌肉。惟瘰疬、癫犬咬，或可如法暂施。此物若煅之存性，犹能啮人肠胃，发泡溃烂致死。即前二证，亦不若用米同炒，取气而勿用质为稳。余证必不可饵。切戒！切戒！', NULL, NULL, NULL, '斑蟊,斑猫', NULL, '12、斑猫,斑蟊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791884, '2B581C3DFDBBEA9A68EC697CA690D392', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', 1, 'admin', '2025-01-17 14:41:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7551, 428, 400107211, '      味咸、苦，平、微寒，有毒。主逐恶血，瘀血月闭，破血瘕积聚无子，利水道，又堕胎。（俗名马蟥。）\n\n       疏：水蛭生于溪涧阴湿之处，其味咸苦，气平有大毒。其用与虻虫相似。故仲景方中往往与之并施。咸入血走血，苦泄结，咸苦并行，故治妇人恶血，瘀血月闭，血瘕积聚因而无子者。血蓄膀胱则水道不通，血散而膀胱得气化之职，水道不求其利而自利矣。堕胎者，以其有毒善破血也。\n\n【主治参与】\n入抵当汤，治伤寒蓄血下焦，因而发狂。\n\n入大黄䗪虫丸，兼治虚劳骨蒸咳嗽，内有干血，皮肤甲错。\n\n入鳖甲煎丸，消疟母。以上皆仲景方。\n\n《古今录验方》坠跌打击内伤，神效。水蛭一两，烧令烟出，为末，入麝香一两，每酒服一钱，当下蓄血。未止再服，其效如神。\n\n【简误】\n       水蛭、虻虫，皆破逐瘀血，血瘀发病之恶药。而水蛭入腹，煅之若尚存性，尚能变为水蛭，啮人肠脏，非细故也。破瘀消血之药尽多，正足选用，奚必用此难制之物？戒之可也。如犯之，以黄泥作丸吞之，必入泥而出。', NULL, NULL, NULL, '水蛭,马蟥', NULL, '11、水蛭,马蟥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791885, 'BBC2DA6CAE13F9B90649E93410633691', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7552, 428, 400107210, '      味咸，平，有小毒，主久肺劳传尸，杀鬼物邪气，疗咳嗽，下淋沥，通水道。生岭南山谷，及城墙或大树间。身长四五寸，尾与身等，形如大守宫，一雌一雄，常自呼其名曰蛤蚧。最护惜其尾，或见人欲取之，多自啮断其尾，人即不取之。凡采之者，须存其尾，则用之力全故也。\n\n       疏：蛤蚧得金水之气，故其味咸气平，有小毒。入手太阴，足少阴经。其主久肺劳传尸、鬼物邪气、咳嗽、淋沥者，皆肺肾为病，劳极则肺肾虚则生热，故外邪易侵，内证兼发也。蛤蚧属阴，能补水之上源，则肺肾皆得所养而劳热咳嗽自除，邪物鬼气自去矣。肺朝百脉，通调水道，下输膀胱，肺气清，故淋沥水道自通也。又顾玠《海槎录》云：广西横州甚多蛤蚧，牝牡上下，相呼累日，情洽乃交，两相抱负，自堕于地。人往捕之亦不知觉，以手分劈，虽死不开。乃用熟槁草细缠，蒸过曝干，售之，炼为房中之药甚效。寻常捕者，不论雌雄，但可为杂药用。\n\n【主治参与】\n寇氏《衍义》：治久嗽不愈，肺积虚热成痈，咳出脓血，晓夕不止，喉中气塞，胸膈噎痛，用蛤蚧、阿胶、鹿角胶、犀角、羚羊角，各二钱半，用河水三升，银石器内文火熬至半升，滤汁。时时仰卧细呷，日一服。\n\n【简误】\n咳嗽由风寒外邪者，不宜用。雷公曰：其毒在眼，须去眼及甲上、尾上、腹上肉毛，以酒浸透，隔两重纸缓焙令干，以瓷器盛，悬屋东角上一夜，用之力可十倍。勿伤尾。', NULL, NULL, NULL, '蛤蚧', NULL, '10、蛤蚧', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791886, '2091AAEDC8C3D06E1BF4BB496507C31C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7553, 428, 400107209, '      味辛，温，有毒。主鬼疰蛊毒，噉诸蛇虫鱼毒，杀鬼物老精，温疟，去三虫，疗心腹寒热结聚，堕胎，去恶血。赤头足者良。（一名蝍蛆，一名天龙。）\n\n       疏：蜈蚣禀火金之气以生，故其味辛，气温有毒。乃属阳之毒虫，足厥阴经药也。善能制蛇，见大蛇便缘上啖其脑。《淮南子》云：腾蛇游雾，而殆于蝍蛆。正指此也。故《本经》主噉诸蛇虫鱼毒，及去三虫蛊毒也。性复走窜辟邪，所以能疗鬼疰温疟，杀鬼物老精。辛主散结，温主通行，故又治心腹寒热结聚，堕胎去恶血也。今世又以之治小儿惊痫风搐，脐风口噤，与夫瘰疬、便毒、痔漏等证皆用之。\n\n【主治参与】\n金头蜈蚣，得牛角䚡、象牙末、猪悬蹄、刺猬皮、蛀竹屑，能去通肠漏管。\n\n《直指方》：瘭疮，一名蛇瘴。蛮烟瘴雨之乡多毒蛇气，人有不伏水土风气而感触之者，数月以还，必发蛇瘴。惟赤足蜈蚣最能伏蛇，为上药，白芷次之。\n\n《圣济总录》云：岭南外蛇瘴，一名琐喉瘴，项大肿痛连喉。用赤足蜈蚣一二节，研细，水下即愈。\n\n《奇效良方》：天蛇头疮，生手指头上：用蜈蚣一条，烧烟熏，一二次即愈。或为末，猪胆汁调涂之。\n\n《济生秘览》便毒初起：蜈蚣一条，瓦上焙存性，为末，酒调服。\n\n《图经》治初失小儿口噤不开，不能乳者，用赤足蜈蚣去足炙，研末，以猪乳二合，调半钱，分三四服，温灌之，效。\n\n【简误】\n         蜈蚣性有毒，善走窜，小儿慢惊风，口噤不言；大人温疟，非烟岚瘴气所发；心腹积聚，非虫结蛇瘕；便毒成脓将溃，咸在所忌。性畏蛞蝓，不敢过其所行之路。能啮人痛甚，以蛞蝓捣涂之，痛立止。蜈蚣能制龙蛇而反畏蛞蝓、蜘蛛，即《庄子》所谓物畏其天，《阴符经》所谓禽之制在气也。凡使勿用千足虫，真相似，但蜈蚣腰中一段无脚，所以能掬而弹远为异。又云：头上有白肉面并嘴尖可别。若误用并把着，腥臭气入顶，能杀人也。', NULL, NULL, NULL, '蜈蚣,蝍蛆,天龙', NULL, '9、蜈蚣,蝍蛆,天龙', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791887, 'FD0A080EA9E6706CFEC2B84D995CAA30', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7554, 428, 400107208, '     味咸，寒、大寒，无毒。主蛇瘕，去三虫，伏尸鬼疰，蛊毒，杀长虫。仍自化作水，疗伤寒伏热狂谬，大腹黄疸。一名土龙。（畏葱、盐。）\n\n      疏：蚯蚓得土中阴水之气，故其味咸寒，无毒大寒。能祛热邪，除大热，故主伏尸鬼疰，乃疗伤寒伏热狂谬。咸主下走，利小便，故治大腹黄疸。诸虫瘕，咸属湿热所成，得咸寒之气，则瘕自消，虫自去，而蛊毒之热亦解矣。昔一道人，治热病发狂，用白颈蚯蚓十数条，同荆芥穗捣汁，与饮之，得臭汗而解。其为治伤寒伏热狂谬之明验也。\n\n【主治参与】\n《肘后方》伤寒热结六七日，狂乱见鬼欲走：以大白颈蚯蚓半斤，去泥，用人溺煮汁饮。或生绞汁亦可。\n\n《斗门方》小便不通，因湿而得者：用蚯蚓捣烂，浸水，滤取浓汁半碗，服立通。\n\n《胜金方》耳卒聋闭：蚯蚓入盐，安葱管内，化水点之，立效。\n\n《保命集》瘰疬溃烂流串者，用荆芥根下段煎汤，温洗良久，看疮破紫黑处，以针刺去血，再洗三四次，用韭菜地上蚯蚓一把，五更时收取，炭火上烧红为末。每一匙入乳香、没药、轻粉各半钱，穿山甲九片，炙为末，麻油调傅之，神效。\n\n【简误】\n蚯蚓，气大寒，能除有余邪热，故伤寒非阳明实热狂躁者，不宜用。温病无壮热，及脾胃素弱者，不宜用。黄疸缘大劳腹胀，属脾肾虚。尸疰因阴虚成劳瘵者，咸在所忌。性复有小毒，被其毒者，以盐水解之。', NULL, NULL, NULL, '白颈蚯蚓', NULL, '8、白颈蚯蚓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791888, '5673E9762C5B201B495256B11883E430', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7555, 428, 400107207, '      味咸、甘，平，无毒。主小儿百二十种惊痫、瘈疭、癫疾、寒热、肠痔、虫毒、蛇痫弄舌摇头。大人五邪，言语僻越，恶疮，呕咳，明目。火熬之良。\n\n       疏：蛇蜕，蛇之余性犹存，不以气味为用者。故蛇之性上窜而主风；蜕之用，入肝而辟恶，其性一也。小儿惊痫、瘈疭、癫疾、寒热，蛇痫弄舌摇头，大人五邪，言语僻越，皆肝经为病，邪恶侵犯也。蛇蜕走窜，能引诸药入肝散邪，故主如上等证。善能杀虫，故主肠痔、虫毒、恶疮。邪去木平，故止呕咳，明目。今人亦用以催生、去翳膜者，取其善脱之义也。\n\n【主治参与】\n《肘后方》治小儿头面疮：蛇蜕烧灰，腊猪脂和傅之，并治小儿月蚀。周密《齐东野语》云：小儿痘后障翳，蛇蜕一条，净洗，焙，天花粉五钱，为末。以羊肝破开，夹药缚定，米泔水煮食。屡试辄效，真奇方也。《济生秘览》治横生、逆生，须臾不救，用蛇蜕一具，蝉蜕十四个，发一握，并烧存性，分二服，酒下。仍以小针刺儿足心，擦盐少许，即顺。并能下胞衣。\n\n《产乳方》妇人吹乳：蛇皮一尺七寸，烧末酒服。\n\n《千金方》诸漏有脓：蛇蜕灰，傅之即虫出。\n\n《直指方》鱼脐疮出水，四畔浮浆：用蛇蜕烧存性，鸡子清和傅。\n\n《医方摘要》耳忽大痛，如有虫在内奔走，或血水流出，或干痛不可忍者，蛇蜕皮烧存性，研细，鹅翎吹入，立愈。\n\n【简误】\n小儿惊痫癫疾，非外邪客忤，而由于肝心虚者，不效。', NULL, NULL, NULL, '蛇蜕', NULL, '7、蛇蜕', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791889, 'D66F17420182F8B1E2A6D4B223751474', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7556, 428, 400107206, '     味甘、苦，寒，有小毒。主心腹䘌痛，下部䘌疮，目肿痛。\n\n      疏：蚺蛇禀火土之气，其胆为甲乙风木之化，故其味苦中有甘，气寒有小毒。气薄味厚，阴也。降也。入手少阴，足厥阴、阳明经。心腹䘌痛者，虫在内攻啮也。下部䘌疮者，虫在外侵蚀也。湿热则生虫，苦寒能燥湿杀虫，故内外施之皆得也。肝开窍于目，肝热则目肿痛，入肝泄热，则肿痛除矣。今人受杖时，用此噙化，可得不死。其功能护心止痛，使恶血不上薄心，有神力也。\n\n【主治参与】\n\n同血竭、乳香、没药、狗头骨灰、䗪虫、天灵盖、象牙末、麻皮灰、丹砂，作丸。临杖服一丸，护心止痛，多杖无害。\n\n《圣惠方》：小儿急疳疮，水调蚺蛇胆傅之。\n\n《医方摘要》痔疮肿痛：蚺蛇胆研，香油调涂，立效。\n\n真胆绝难得，狭长，通黑，皮膜极薄，舐之甜苦，剔取粟许，着净水中，浮游水上，回旋行走者为真。其径沉者，非也。勿多着，亦沉散也。今世惟为受杖人所需，余甚稀使，故不著“简误”。', NULL, NULL, NULL, '蚺蛇胆', NULL, '6、蚺蛇胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791890, '97C712709E7C95D995F0C669EC3612BE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7557, 428, 400107205, '     温。主心腹冷气，腰脊冷风，利五脏，健胃，令人能食。又云温中消食，起阳，益血色。\n\n       壳：烧过，以米醋三度淬后，埋令坏，醋膏丸。治一切血气，冷气，癥癖。\n\n       疏：蚶得水中之阳气，故其味甘，气湿，性亦无毒。《经》曰：里不足者，以甘补之。又曰：形不足者，温之以气。甘温能益气而补中，则五脏安，胃气健，心腹腰脊风冷俱瘳矣。胃健则食自消，脏暖则阳自起，气充则血自华也。\n\n      壳味咸，走血而软坚，故能治血气冷气癥癖。丹溪用以消血块，化痰积，以此也。今世糟其肉侑酒之物，罕有入药者。壳惟消癥癖之外，无他用。故并不著“主治”及“简误”。', NULL, NULL, NULL, '蚶', NULL, '5、蚶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791891, '903CF36C0134426B14F70E4F445DC049', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7558, 428, 400107201, '       味辛，寒，有毒，主邪气，破癥坚血，痈肿阴疮。服之不患热病。疗阴蚀，疽疠恶疮，猘犬伤疮，能合玉石。一名蟾蜍。\n\n       疏：虾蟆、蟾蜍，本是二物。经云：一名蟾蜍者，盖古人通称蟾为虾蟆耳。经文虽名虾蟆，其用实则蟾蜍也。今世所用者皆蟾蜍，而非虾蟆，其功益可见矣。禀土金之精气，上应月魄，性亦灵异，其味辛气寒，毒在眉棱皮汁中。其主痈肿阴疮，阴蚀，疽疠恶疮，猘犬伤疮者，皆热毒气伤肌肉也。辛寒能散热解毒，其性急速，以毒攻毒则毒易解，毒解则肌肉和，诸证去矣。凡瘟疫邪气，得汗则解。其味大辛，性善发汗，辛主散毒，寒主除热，故能使邪气散而不留，邪去则胃气安而热病退矣。破癥坚血者，亦以其辛寒能散血热壅滞也。陶隐居云：其肪涂玉，则刻之如蜡，故云能合玉石。近世治小儿疳疾多用，以其走阳明而能消积滞也。\n\n【主治参与】\n《全婴方》五疳保童丸：治五疳八痢，面黄肌瘦，好食泥土，不思乳食，用大干蟾蜍一枚，烧存性，皂角去皮弦一钱，烧存性，蛤粉水飞三钱，麝香一分，糊丸粟米大。空心米饮下三四十丸，日二服。\n\n郑氏小儿方：走马牙疳，侵蚀口鼻：干蚵蚾，黄泥裹固，煅过，黄连，各二钱半，青黛一钱，入麝香少许，和研傅之。\n\n《锦囊秘览》附骨坏疮久不瘥，脓汁不已，或骨从疮孔中出：用大虾蟆一个，乱发一鸡子大，猪油四两，入二物煎枯去滓，待凝如膏。先以桑根皮、乌头煎汤洗，拭干，煅龙骨末糁四边，以前膏贴之。\n\n《医林集要》发背肿毒初起势重者，以活蟾一个，破开，连肛乘热合疮上。不久必臭不可闻，再易，三四次即愈。\n\n《袖珍方》治疯犬伤，即用蟾蜍后足捣烂，水调服之。先于顶心拔去血发三两根，则小便内见沫也。', NULL, NULL, NULL, '蟾蜍,虾蟆', NULL, '1、蟾蜍,虾蟆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791892, '20247B502E322D1D0D39293DC51CBBA7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7559, 428, 400107204, '    冷，无毒。润五藏，止消渴，开胃，解酒毒，主老癖能为寒热者，及妇人血块。煮食之。\n    \n      疏：蛤蜊禀水中之阴气以生，其味咸，气冷无毒。入足阳明经。五脏皆属阴，得水气之阴者，其性滋润而助津液，故能润五脏，止消渴，开胃也。咸能入血软坚，故主妇人血块，及老癖为寒热也。煮食更能醒酒。\n\n蛤粉：丹溪云：味咸，寒，无毒。主热痰、湿痰、老痰、顽痰、疝气、白浊、带下。同香附末，姜汁调服，主心痛。\n\n疏：此即蛤壳煅成粉者，其味咸，气寒无毒，为诸痰证的要药。盖痰未有不由火气上炎，煎熬津液而成。咸能软坚润下，得之则火自降，痰结自消矣。疝气、白浊、带下，皆肾经为病也。肾属水，咸为水化，气类相从，故能入肾以除其所苦也。心痛者，心虚而热邪客之也。“五脏苦欲补泻”云：心欲软，急食咸以软之。此之谓也。更有消浮肿，利小便，散瘿核肿毒，妇人血块，汤火伤疮等服。\n\n【主治参与】\n《普济方》气虚水肿：用大蒜十个，捣如泥，入蛤粉丸梧子大。每食前白汤下二十丸，服尽，小便下数桶而愈。\n\n洁古方：治白浊遗精，真珠粉丸：用蛤粉煅一斤，黄檗蜜炙一斤，为末，水跌为丸梧子大。每服一百丸，空心温酒下，日二次。盖蛤粉味咸，而能补肾阴，黄檗苦而降心火、坚肾故也。\n\n【简误】\n       肉气味虽冷，乃与丹石人相反，食之令腹结痛。壳粉善消痰积血块，然脾胃虚寒者，宜少用，或加益脾胃药同用为宜。', NULL, NULL, NULL, '蛤蜊', NULL, '3、蛤蜊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791893, '656ADE14D466D7F39F472D56B765BD0F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7560, 428, 400107203, '      微寒，无毒。主小儿痫疾，大腹，时行劳复。（两头尖者是牡鼠屎。）\n\n        疏：牡鼠粪，本经诸家不言味，但云微寒无毒。然详其所自，应是苦咸之物。盖鼠属水，而凡粪必苦者也。入足阳明，足厥阴经。其主小儿痫疾，大腹，及时行劳复者，皆热邪在阳明也。苦寒能除是经之热，所以主之。古方治男子阴易腹痛，妇人吹乳乳痈，皆取其除热软坚泄结，走肝入胃之功耳。\n\n【主治参与】\n同白芷、山慈菇、山豆根、连翘、金银花、蒲公草、夏枯草、贝母、橘叶、栝楼根、紫花地丁、牛旁子，治乳痈、乳岩，有效。\n\n《外台秘要》伤寒劳复：用雄鼠屎二十枚，豉五合，水二升，煮一升，顿服。《活人书》加栀子、葱白。\n\n南阳《活人书》：男子阴易，及劳复。豭鼠屎汤：用豭鼠屎两头尖者，十四枚，韭白根一大把，水二盏，煎一盏，温服得粘汗为效。未汗再服。\n\n《集要方》妇人吹奶：鼠屎七粒，红枣七枚去核包屎，烧存性，入麝香少许，温酒调服。并治乳痈初起。\n\n《普济方》大小便秘：雄鼠屎末，傅脐中，立效。\n\n除伤寒劳复阴易及乳痈、乳岩外，他用甚稀，故不著“简误”。', NULL, NULL, NULL, '牡鼠粪', NULL, '3、牡鼠粪', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791894, '0823215AB34707EFEFC995E4A481DA2F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7561, 428, 400107202, '     甄权云：端午日，取眉脂，以朱砂、麝香为丸，如麻子大，治小儿疳瘦，每日一丸。如脑疳，以乳汁调，滴鼻中。日华子云：眉酥治蚛牙。和牛酥摩傅腰眼并阴囊，治腰肾冷，并助阳气。苏颂云：主蚛牙，及小儿疳瘦。观诸家所主，但言其有消积杀虫，温暖通行之功。然其味辛甘，气温，善能发散一切风火抑郁、大热痈肿之候，为拔疔散毒之神药。第性有毒，不宜多用。入发汗散毒药中服者，尤不可多。\n\n【主治参与】\n同铁锈、桑硇、麝香、牛黄、冰片，用金针针入疔根，抹入前药，其疔根即烂出。\n\n治疔丸：同朱砂、冰片、牛黄、明矾、白僵蚕、麝香、黄蜡，溶化作丸，麻子大。用葱头、白酒吞下取汗，不过二三小丸。\n\n《青囊杂纂》拨取疔黄：蟾酥，以面丸梧子大。每用一丸，安舌下，即黄出也。\n\n危氏方：拔取疔毒：蟾酥，以白面、黄丹搜作剂，每丸麦粒大。挑破纳入，仍以水澄膏贴之。\n\n《保命集》一切疮毒：蟾酥一钱，白面二钱，朱砂少许，井水调成小锭子如麦大。每用一锭，葱汤服，汗出即愈。如疮势紧急，用三四锭。\n\n《万氏家抄》：凡痈疽发背，无名肿毒初起者，急取蟾酥三五分，广胶一块，米醋一二碗，入铫内火化开，用笔蘸，乘热令人不住手周围润之。以散为度。\n\n【简误】\n        蟾虽有毒，与病无害。其眉酥有大毒，不宜多服。诸家咸云，治小儿疳瘦，恐非正治，不宜漫尝也。即用亦煅过者。予亲见一人，因齿痛，以蟾酥纳牙根，误吞入，头目俱胀大而毙。即陶注云：其皮汁甚有毒，犬啮之，口皆肿之验也。惟疔肿服之者，取其以毒攻毒之义。然其剂亦甚小，不能为害耳。外治殊有神效，若欲内服，勿过三厘。慎毋单使，必与牛黄、明矾、乳香、没药之类同用乃可。如疮已溃，欲其生肌长肉之际，得之作痛异常，不可不知也。', NULL, NULL, NULL, '蟾酥', NULL, '2、蟾酥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628169100791895, '4543985C91138662E1FFCFA80ED28AFC', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 10:46:39', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7562, 429, 400107328, '     味甘，无毒。主五痔，去三虫，蛊毒，鬼疰。（木部移入。）\n\n      疏：榧实禀土气以生。本经味甘无毒。然尝其味多带微涩，详其用应是有苦，气应微寒。气薄味厚，阴也，降也。入手太阴、阳明经。五痔、三虫皆大肠湿热所致，苦寒能泻湿热，则肠清宁，而二证愈矣。其主蛊毒鬼疰者，以其甘能解毒，而苦寒能涤除肠胃邪恶气耳。\n\n【主治参与】\n孟诜《食疗》：治寸白虫，日食榧子七颗，满七日，虫皆化为水也。\n\n《简便方》：好食茶叶，面黄者，每日食榧子七枚，以愈为度。', NULL, NULL, NULL, '榧实', NULL, '28、榧实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019526, 'E5B51C5473C8DD34EDCC53C91285B62B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7563, 429, 400107327, '     味酸，冷，无毒。汁服主水痢，沐头及洗身上疮痒。（自木部移入。即今山查，一名棠梂。）\n\n     疏：山查禀木气而生。本经云：味酸气冷，然观其能消食积，行瘀血，则其气非冷矣。入足阳明、太阴经。二经有积滞，则成下痢。产后恶露不尽，蓄于太阴经部分，则为儿枕痛。山查能入脾胃，消积滞，散宿血，故主水痢及产妇腹中块痛也。大抵其功长于化饮食，健脾胃，行结气，消瘀血，故小儿，产妇宜多食之。本经误认为冷，故有洗疮痒之用。\n\n【主治参与】\n同矾红、黄连、红曲，消肉积。\n\n同红曲、麦芽、橘皮、白术、肉豆蔻、厚朴、砂仁，能消食健脾。\n\n同牛膝、生地黄、当归、续断、益母草、泽兰、牡丹皮、蒲黄、芍药，治产后儿枕作痛。\n\n《卫生易简方》偏坠疝气：山查肉、茴香炒各一两，为末，糊丸梧子大。每服一百丸，空心白汤下。\n\n【简误】\n       山查性能克化饮食，若胃家无食积，及脾虚不能运化，不思食者，多食之反致克伐脾胃生气。如脾虚兼有积滞者，当与补药同施，亦不宜过用也。《物类相感志》云：煮老鸡硬肉，入山查数颗即易烂。其消食克伐之力彰矣。', NULL, NULL, NULL, '赤爪木实', NULL, '27、赤爪木实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019527, '5910F136F4D74E5A8915E7980155BF5C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7564, 429, 400107326, '       味甘，平，无毒。主五藏邪气，安志厌食，除虫去毒。久服强魂，聪明，轻身不老，通神明。（自木部移入。）\n\n       疏：龙眼禀稼穑之化，故其味甘，气平，无毒。入足太阴、手少阴经。少阴为君主之官，藏神而主血，甘能益血补心，则君主强，神明通，五脏邪气俱除矣。甘味补脾，脾得补则食自寡而饫。心得补则火下降而坎离交，故能安志。肝藏魄，主纳血，心家血满，则肝有所受而魂强。甘能解毒，故主去毒。久服聪明耳目，轻身不老，总之补益心脾之验也。至于除虫，非其所能，略之可也。\n\n【主治参与】\n同生地黄、天麦门冬、丹参、柏子仁、远志、莲实、五味子、茯神、人参，能补心保神，益气强志。\n\n严用和《济生方》归脾汤：治思虑过度，劳伤心脾，健忘怔忡，虚烦不眠，自汗惊悸，用龙眼肉、酸枣仁、炒黄耆、炙白术、焙茯神各一两，木香半两，炙甘草二钱半，㕮咀，每服五钱，姜三片，枣一枚，水二钟，煎一钟，温服。', NULL, NULL, NULL, '龙眼', NULL, '26、龙眼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019528, '4E5D55BCFBA1D4DE87E98C3AC0DE409C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7565, 429, 400107325, '      味甘，小温，无毒。主骨节风，头眩，去死肌，发白，散水气，润五藏，不饥。生新罗。\n\n      疏：海松子气味香美，甘温。甘温助阳气而通经，则骨节中风水气，及因风头眩、死肌自除矣。气温属阳，味甘补血，血气充足，则五脏自润，发白，不饥所由来矣。仙方服食，多饵此物，故能延年轻身不老也。', NULL, NULL, NULL, '海松子', NULL, '25、海松子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019529, '1DCC575B639A4CF5B6033F77AA9E9DC6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7566, 429, 400107324, '       味甘，平，无毒。食之令人肥健，润肌，黑发。取瓤烧令黑末，断烟，和松脂研傅瘰疬疮。又和胡粉为泥，拔白须发，以内孔中，其毛皆黑。多食利小便，能脱人眉，动风故也。去五痔。外青皮染髭。\n\n        疏：胡桃禀火土之气以生。本经虽云甘平，然其气多热而性润，益血脉，补命门之药也。血不充，则消瘦、肌肤不泽、及须发易白，益血故令人肥健，润肌，黑须发也。多食利小便者，以其能入肾固精，令水窍常通也。傅瘰疬者，甘热能解毒散结。去五痔，取其润肠除湿之功也。能脱人眉者，热极则生风，风甚则万物摇落之象也。青皮性涩，故能染髭。\n\n【主治参与】\n一味勿去黄皮，空腹食之，最能固精。\n\n同补骨脂、蒺藜、莲须、鹿茸、麦门冬、巴戟天、覆盆子、山茱萸、五味子、鱼胶，益命门，种子，最效。\n\n入青娥丸，能黑须发，补右肾，方见补骨脂条。\n\n《御药院方》胡桃丸：益血补髓，强筋壮骨，延年明目，悦心润肌，能除百病。用胡桃肉四两捣膏，入补骨脂、杜仲、萆薢末各四两，杵匀，丸梧子大。每空心温酒、盐汤任下五十丸。\n\n《普济方》产后气喘：胡桃肉、人参各二钱，水一盏，煎七分，顿服。\n\n李楼方：误吞铜钱，多食胡桃，自化出也。\n\n《圣惠方》揩齿乌须：胡桃仁烧过、贝母等分，为散，日日用之。\n\n《圣济总录》血崩不止：胡桃肉十五枚，烧存性，研作一服，空心温酒调下，神效。\n\n子和《儒门事亲》便毒初起。用胡桃七个，烧研，酒服，不过三服效。\n\n杨试《经验方》，鱼口便毒：端五日午时，取树上青胡桃，筐内阴干，临时全烧为末，酒服。少行一二次，有脓自大便出，无脓即消，二三服平。上二方，应加全蝎、穿山甲尤妙。\n\n《图经本草》压扑损伤：胡桃肉捣，和温酒顿服，便瘥。\n\n【简误】\n       胡桃，前人多言其有害不可食。孙思邈云：多食动痰饮，令人恶心吐水。苏颂云：性热不可多食。马志云：多食动风，脱人眉。同酒食，多令人咯血。汪颖曰：多食生痰动肾火。然而近世医方用治痰气喘嗽，和伤，补命门，润血脉、大肠，及疠风诸病，而酒家往往以之佐酒，则多食吐水、咯血、脱眉、动火之说，亦未尽然也。但性本热，惟虚寒者宜之。如肺家有痰热，命门火炽，阴虚吐衄等证，皆不得施。', NULL, NULL, NULL, '胡桃', NULL, '24、胡桃', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019530, '87D69FBB8D476D3BE0A05A75989A33E7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7567, 429, 400107323, '       味酸、甘，温，无毒。主消酒，疗鯸鲐毒。\n\n        疏：橄榄，本经味酸、甘。今尝之先涩而后甘。得土中的阳气，气温无毒，肺胃家果也。能生津液，酒后嚼之不渴，故主消酒。甘能解毒，故疗鯸鲐毒也。马志云：鯸鲐即河豚也。人误食此鱼肝及子，必迷闷至死，惟橄榄汁煮服之，必解。其木作楫，拨着鱼皆浮出，故知物有相畏如此，不特味甘解毒之义也。\n\n【主治参与】\n食诸鱼被鲠，用橄榄嚼汁咽之。无橄榄时，即觅核研末，急流水调服，亦效。\n\n手抓碎成疮，用橄榄磨浓汁涂之，能灭瘢痕。\n\n《直指方》肠风下血：橄榄烧存性，研末。每服二钱，陈米饮调下。\n\n《乾坤生意》耳足冻疮：橄榄核烧研，油调涂之。', NULL, NULL, NULL, '橄榄', NULL, '23、橄榄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019531, '8ACD68B3DD8A0C6F895BB83D24675476', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7568, 429, 400107322, '      味甘、微酸，寒。多食令人寒中。金疮、乳妇尤不可食。\n\n       疏：梨成于秋，花实皆白，其得西方之阴气者乎！味甘微酸，气寒无毒。入手太阴，兼入足阳明经。\n\n    《别录》著梨，止言其害，不叙其功。陶隐居言梨不入药。盖古人论病，多主于风寒外邪，以温热为补，药多桂、附。凡冷利之物，辍而不用也。不知时运迭降，禀受递殊。今时之人，火病、热病、痰病，往往皆是。梨能润肺消痰，降火除热，故苏恭主热嗽，止渴，贴汤火伤，治客热，中风不语，伤寒寒热，解丹石热气，惊邪，利大小便。大明主贼风，心烦，气喘，热狂。孟诜主胸中痞塞热结等，诚不可阙者也。本经言多食令人寒中者，以其过于冷利也。乳妇、金疮不可食者，以血得寒则凝而成瘀为病也。凡人有痛处，脉数无力，或发渴，此痈疽将成之候，惟昼夜食梨，可转重为轻。膏粱之家，厚味酽酒，纵恣无节，必多痰火卒中。痈疽之病，数食梨，可变危为安。功难尽述。\n\n【主治参与】\n梨汁，同霞天膏、竹沥、童便，治中风痰热。\n\n同人乳、蔗浆、芦根汁、童便、竹沥，治血液衰少，渐成噎膈。\n\n《普济方》消渴饮水：用香水梨，或鹅梨、雪梨皆可，取汁以蜜和熬成膏，瓶收。不时白汤调服一二匙。\n\n崔元亮《海上方》：卒得咳嗽，用上好梨去核，捣汁一碗，入椒四十粒，煎一沸，去滓，纳黑饧一大两，消讫，细细含咽，立定。\n\n《食疗本草》暗风失音：捣梨汁一盏饮之，日再服。\n\n《圣惠方》小儿风热，昏懵躁闷，不能食：用消梨三枚切破，以水二升，煮取汁一升，入粳米一合，煮粥食之。\n\n治小儿内热，痰壅喉间吐不出，或因惊热生痰，或因风热生痰：取梨汁时时与之，加牛黄分许，神效。\n\n《图经》：赤目胬肉，日夜痛者，取好梨一颗捣绞汁，以黄连切片一钱浸汁内，取汁，仰卧点之。\n\n《圣济总录》反胃转食，药物不下：用大雪梨一个，以丁香十五粒，刺入梨内，湿纸包四五重，煨熟，去丁香，食之。\n\n【简误】\n         肺寒咳嗽，脾家泄泻，腹痛冷积，寒痰痰饮，妇人产后，小儿痘后，胃冷呕吐，及西北真中风证，法咸忌之。', NULL, NULL, NULL, '梨', NULL, '22、梨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019532, '0C2550C1B2DA1FDBDEFCC4AEA79ADAB5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7569, 429, 400107321, '       味甘、苦，温，冷利，有毒。主咳逆上气雷鸣，喉痹，下气，产乳金疮，寒心，贲豚，惊痫，心下烦热，风气去来，时行头痛，解肌，消心下急，杀狗毒。\n\n       疏：杏核仁禀春温之气，而兼火土之化以生。故《本经》味甘，气温。《别录》加苦，有毒。其言冷利者，以其性润利下行之故，非真冷也。气薄味厚，阴中微阳，降也。入手太阴经。太阴为清肃之脏，邪客之则咳逆上气。火炎乘金，则为喉痹。杏仁润利而下行，苦温而散滞，则咳逆上气、喉痹俱除矣。其主心下烦热者，邪热客于心肺之分也。风气去来，时行头痛者，肺主皮毛，风邪自外而入也。温能解肌，苦能泄热，故仲景麻黄汤中用之，亦取其有发散之功也。主产乳、金疮者，亦指为风寒所乘者言之。消心下急者，以其润利而下气也。心寒贲豚者，心虚而肾邪凌之也。惊痫者，痰热盛也。雷鸣者，大肠不和也。总之取其下气消痰，温散甘和，苦泄润利之功也。\n\n【主治参与】\n同桑根白皮、前胡、薄荷、桔梗、苏子、贝母、甘草、五味子、橘红、紫菀，治风寒入肺，咳嗽生痰。\n\n入麻黄汤，治太阳病无汗，恶寒，喘急。\n\n《千金方》咳逆上气：以杏仁三升去皮尖，炒黄研膏，入蜜一合，杵熟。每食前含之，咽汁。\n\n《梅师方》食狗肉不消，心下坚胀，口干，发热妄语：杏仁一升去皮尖，水三升，煎减半，取汁分三服，效。\n\n【简误】\n       杏仁性温，散肺经风寒滞气殊效。第阴虚咳嗽，肺家有虚热，热痰者忌之。风寒外邪，非壅逆肺分，喘急息促者，不得用。产乳、金疮无风寒击袭者，不得用。惊痫，喉痹，亦非必须之药。用者详之。双仁者能杀人。《本经》言有毒，盖指此耳。', NULL, NULL, NULL, '杏仁,杏核仁', NULL, '21、杏仁,杏核仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019533, '40D6A3A7ADA236BD80EE5F4E5A0D887C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7570, 429, 400107320, '      味苦微温。主杀百鬼精物，疗中恶腹痛，杀精魅五毒不祥。一名桃奴。\n\n       疏：桃枭是桃实着树经冬不落者，正月采之。桃为五木之精，仙木也，最能辟邪。今道家禁咒镇魇之术，犹有用桃木者。《本经》以桃枭主杀诸精鬼不祥，亦此意耳。况着于树上最久，得气尤全，苦温之性，又能通滞散邪者乎？治血之功，与桃仁同。\n\n【主治参与】\n桃枭煅存性，同棕皮灰、蒲黄、朱砂、京墨，为末，临卧以童便调服三钱，小便解，色渐淡为度。治内伤吐血神效。\n\n同番降香、辰砂，治鬼击吐血。\n\n《圣惠方》伏梁结气在心下不散：桃奴三两为末，空心温酒下，每服二钱。', NULL, NULL, NULL, '桃枭,桃奴', NULL, '20、桃枭,桃奴', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019534, '5834D951B0400035C840F44A4189FC16', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7571, 429, 400107319, '       味苦、甘，平，无毒。主瘀血血闭瘕，邪气，杀小虫，止咳逆上气，消心下坚，除卒暴击血，破癥瘕，通月水，止痛。\n\n        疏：桃核仁禀地二之气，兼得天五之气以生，故其味苦重、甘微，气平无毒。思邈言辛，孟诜言温，皆有之矣。气薄味厚，阳中之阴，降也。入手、足厥阴经。夫血者，阴也，有形者也。周流乎一身者也。一有凝滞，则为癥瘕，瘀血血闭，或妇人月水不通，或击扑伤损积血，及心下宿血坚痛，皆从足厥阴受病，以其为藏血之脏也。苦能泄滞，辛能散结，甘温通行而缓肝，故主如上等证也。心下宿血去则气自下，咳逆自止。桃为五木之精，能镇辟不祥，故主邪气。味苦而辛，故又能杀小虫也。\n\n【主治参与】\n仲景桃仁承气汤：治伤寒湿热在内，小便利而大便黑，为蓄血，用桃仁五十粒，桂枝二两，大黄四两，芒硝二两，甘草一两，以水七升，煮取二升半，去滓，内芒硝，更上火微沸，空心温服五合，日三，当微利。\n\n入抵当汤，治太阳病六七日，表证仍在，脉微而沉，反不结胸，其人如狂者，以热结在下焦，少腹当硬满，小便自利，下血乃愈。用桃仁二十粒，水蛭三十个熬，虻虫三十个去翅足熬，大黄三两酒浸，以水五升，煮取三升，温服一升，不下再服。\n\n同当归、芍药、泽兰、延胡索、苏木、五灵脂、红花、牛膝、生地黄、益母草，治产后瘀血，结块作痛，并治壮盛妇人经闭不通。\n\n同当归、麻仁、地黄、麦门冬、芍药、黄芩、肉苁蓉、甘草，治大肠血燥，便结不通。\n\n同番降香、川通草、山查、穿山甲、乳香、没药、红花、续断、当归，治上部内伤，瘀血作痛。\n\n《圣济总录》大便不快，里急后重：用桃仁三两去皮，以吴茱萸二两，食盐一两，同炒熟，去二物，每嚼桃仁五七粒，效。兼可预辟瘴疠。\n\n《删繁方》：妇人难产，数日不出。桃仁一个劈开，用朱砂书一片 “可” 字，一片 “出” 字，吞之即生。\n\n《肘后方》妇人阴痒：桃仁杵烂，绵裹塞之。杏仁亦可用。\n\n【简误】\n      桃仁性善破血，凡血结、血秘、血燥、瘀血、留血、蓄血、血痛、血瘕等证，用之立通。第散而不收，泻而无补，过用之及用之不得其当，能使血下不止。损伤真阴，为害非细。故凡经闭不通由于血枯，而不由于瘀滞；产后腹痛由于血虚，而不由于留血结块；大便不通由于津液不足，而不由于血燥闭结，法并忌之。', NULL, NULL, NULL, '桃仁,桃核仁', NULL, '19、桃仁,桃核仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019535, '056C1F01287C4C91AA1D1F1AF562C3EF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7572, 429, 400107318, '      味甘，寒，无毒。功用与石蜜同，而冷利过之。\n       \n       疏：沙糖，蔗汁之清而煎炼至紫黑色者。本经虽云与石蜜同功，然而不逮石蜜多矣。既经煎炼之久，则未免有湿热之气，故多食损齿生虫，发疳胀满，令人心痛等害。与鲫鱼同食成疳虫，与葵同食生流澼，与笋同食不消成癥，身重不能行。今医家用作汤，下小儿丸散，殊为未当。', NULL, NULL, NULL, '沙糖', NULL, '18、沙糖', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019536, '2F2377BBE05878D9A5DE366E03981C74', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7573, 429, 400107317, '      味甘，平，无毒。主下气，和中，助脾气，利大肠。\n\n       疏：甘蔗禀地中之冲气，故味甘气平无毒。日华子云：冷。气薄味厚，阳中之阴，降也。入手足太阴、足阳明经。甘为稼穑之化，其味先入脾，故能助脾气。脾主中州，故主和中。甘寒除热润燥，故主下气，利大肠也。大明为其消痰止渴，除心胸烦热，解酒毒。今人用以治噎膈反胃呕吐，大便燥结。皆取其除热生津润燥之功耳。\n\n【主治参与】\n蔗浆一味单服，能润大便，下燥结。\n\n同芦根汁、梨汁、藕汁、人乳、童便、竹沥，和匀。时时饮之，治胃脘干枯，噎食呕吐。\n\n《梅师方》反胃吐食：蔗浆七升，姜汁半升，和匀，日日细呷。\n\n【简误】\n甘蔗，世人皆以其性热，不敢多食，不知乃是甘寒之物，能泻火热，润枯燥。唐王摩诘 “樱桃诗” 云：饱食不须愁内热，大官还有蔗浆寒。可为证矣。惟胃寒呕吐，中满滑泄者，忌之。', NULL, NULL, NULL, '甘蔗', NULL, '17、甘蔗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019537, '85C6C05DC4CF062CBA18C7E2E24BF18B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7574, 429, 400107316, '     味甘，寒，无毒。主心腹热胀，口干渴，性冷利。\n\n      疏：石蜜乃煎甘蔗汁曝之，凝如石，而体甚轻，今之白沙糖也。其味甘，其气寒，其用在脾，故主心腹热胀。甘寒能除热生津液，故止口干渴，及咳嗽生痰也。多食亦能害脾，以其味太甘耳。', NULL, NULL, NULL, '石蜜', NULL, '16、石蜜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019538, '6C042852CFE95F1CEA03B9F7B5E2DB49', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', 1, 'admin', '2025-01-14 16:43:13');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7575, 429, 400107315, '      味甘，平，无毒。止渴，益人颜色。\n\n       疏：荔枝子，南方果也。感天之阳气，得地之甘味。本经虽云平，而其气实温也。鲜时味极甘美，多津液，故能止渴。甘温益血，助荣卫，故能益人颜色也。多食令人发热，或衄血、齿痛者，以其生于炎方，熟于夏月，故善助火发热耳。\n\n入药甚稀，无 “主治”、“简误”。\n\n 核：味甘，温。主心痛，小肠气痛，㿗疝，妇人血气刺痛。以一枚煨存性，研末，酒调服。盖其气温而通行，入肝者，散滞气，辟寒邪，所以能疗如上诸证也。\n\n【主治参与】\n荔枝核同牛膝、补骨脂、延胡索、合欢子、茴香、木瓜、杜仲、橘核、萆薢，治疝气。虚热者加黄檗，虚寒加桂。\n\n孙氏方：治疝气㿗肿，荔枝核炒黑色，大茴香炒，等分为末。每服一钱，温酒下。\n\n又方，肾肿如斗：荔枝核、青橘皮、茴香等分，各炒研。酒服二钱，日三。\n\n除疝气外无他用，故不著 “简误”。', NULL, NULL, NULL, '荔枝子', NULL, '15、荔枝子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019539, '1BF34635D9878CA4EFE6D786E9874BA2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7576, 429, 400107314, '    味苦，平，无毒。主卒啘不止，下气。\n\n     疏：枇杷叶禀天地清寒之气，四时不凋，其味苦，气平，平即凉也，无毒。入手太阴、足阳明经。气薄味厚，阳中之阴，降也。《经》曰：诸逆冲上，皆属于火。火气上炎，则为卒啘不止。啘者，哕也，其声浊恶而长。经曰：树枯者叶落，病深者声哕。病者见此，是为危证。枇杷叶性凉，善下气，气下则火不上升，而胃自安，故卒啘止也。其治呕吐不止，妇人产后口干，男子消渴，肺热咳嗽，喘息气急，脚气上冲，皆取其下气之功。气下则火降痰顺，而呕者不呕，渴者不渴，咳者不咳，冲逆者不冲逆矣。又治妇人发热咳嗽，经事先期，佐补阴清热之药，服之可使经期正而受孕。\n\n【主治参与】\n同生地黄、麦门冬、白芍药、炙甘草、枸杞子、桑根白皮、童便、茅根、天门冬、苏子、五味子、栝楼根，治阴虚咳嗽吐血。\n\n入噙化丸，治肺热咳嗽：同竹茹、木瓜、芦根汁、石斛、麦门冬、人参、白茯苓，治胃热呕吐。加童便、人乳、竹沥、苏子、白芍药、蔗浆，治噎膈反胃。\n\n同白芍药、生地黄、青蒿子、五味子、黄檗、阿胶、枸杞子、杜仲、牡丹皮、鳖甲作丸，治妇人经行先期，发热无孕。\n\n同人参、白芍药、茯苓、竹茹、橘红、苏子、麦门冬、木瓜，治妊娠恶阻。\n\n同栝楼根、天门冬、枸杞子、五味子、石斛、白芍药、黄连、甘草、芦根汁、童便、竹叶，治消渴。\n\n庞安常方：温病发哕，因饮水多者，枇杷叶去毛炙香，茅根各半斤，水四升，煎二升，稍稍饮之。\n\n《圣惠方》衄血不止：枇杷叶去毛，焙研末，茶服一二钱，日二服。\n\n【简误】\n       胃寒呕吐，及肺感风寒咳嗽者，法并忌之。', NULL, NULL, NULL, '枇杷叶', NULL, '14、枇杷叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019540, '550717B706B217AD4BAB885B3F29D9EE', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7577, 429, 400107313, '      味苦、甘，微寒，无毒。主消渴痹热，温中益气。一名荸脐。\n\n       疏：乌芋，禀土金之气以生。本经味苦、甘，气微寒，无毒。然详其用，味应有辛，辛能散，苦能泄，故主痹热。甘寒能除热而生津，故主消渴。热去则气自益，气益则中自温，自然之道也。孟诜主下丹石，消黄疸，除胸中实热气。汪机主疗五种膈气，消宿食，治误吞铜物，及今人治腹胀下血等证，皆取其辛寒消散除热之功也。\n\n【主治参与】\n乌芋去皮，填入雄猪肚肉，线缝，砂器煮糜食之，勿入盐，治腹满胀大。\n\n善毁铜，铜器中煮之即烊。\n\n误吞铜物，以乌芋合胡桃食一二斤许，即消。\n\n一味晒干，为末服，能辟蛊毒。\n\n《神秘方》大便下血：荸脐捣汁大半钟，入酒少许，温服，三日见效。\n\n【简误】\n孟诜云：乌芋性冷，先有冷气人不可食。多食令人患脚气。又孕妇忌之。', NULL, NULL, NULL, '乌芋', NULL, '13、乌芋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019541, '6E3A1191F488DF74AE622EF458C14FDF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7578, 429, 400107312, '   味甘，寒，无毒。主通鼻耳气，肠澼不足。\n\n    疏：柿禀地中之阴气以生，故味甘，气寒，无毒。入手、足太阴经。鼻者，肺之窍也。耳者，肾之窍也。金水二脏最忌火热，二脏有火上炎，则外窍闭而不通。得甘寒之气，俾火热下行，窍自清利矣。肺与大肠为表里，湿热伤血分，则为肠澼不足。甘能益血，寒能除热，脏气清而腑病亦除也。\n\n干柿：寒气稍减，能厚肠胃，补不足，润肺止渴，功同于前。\n\n柿霜：清心肺间热，生津止渴，化痰宁嗽，治喉舌口疮。总之其功长于清肃上焦火邪，兼能益脾开胃，故三者所主虽不同，而其源皆归于一义也。\n\n【主治参与】\n        柿霜得桑根白皮、百部、天麦门冬、沙参、贝母、苏子、枇杷叶、橘红、栝楼根，作丸噙化，治肺经有火，咳嗽生痰。\n\n【简误】\n柿性寒，肺经无火，因客风寒作嗽者，忌之。冷痢滑泄，肠胃虚脱者，忌之。脾家素有寒积，及感寒腹痛、感寒呕吐者，皆不得服。不宜与蟹同食，令人腹痛作泻。', NULL, NULL, NULL, '柿', NULL, '12、柿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019542, 'BD209DC9F0A1E3815EEF44BABCCB259B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7579, 429, 400107311, '       味酸，温，无毒，主湿痹脚气，霍乱大吐下，转筋不止。\n\n        疏：木瓜实得春生之气，禀曲直之化，故其味酸，气温性无毒。气薄味厚，降多于升，阳中阴也。入足太阴、阳明，兼入足厥阴。其主湿痹脚气者，以脾主四肢，又主肌肉，性恶湿而喜燥，湿侵肌肉，则为湿痹，伤足络则成脚气。木瓜温能通肌肉之滞，酸能敛濡满之湿，则脚气、湿痹自除也。霍乱大吐下，转筋不止者，脾胃病也。夏月暑湿饮食之邪伤于脾胃，则挥霍撩乱，上吐下泻，甚则肝木乘脾而筋为之转也。酸温能和脾胃，固虚脱，兼之入肝而养筋，所以能疗肝脾所生之病也。藏器治脚气冲心，强筋骨，下冷气，止呕逆。大明主吐泻，水肿，心腹痛。好古治腹胀善噫，心下烦痞。无非取其去湿和胃，滋脾益肺，利筋骨，调荣卫，通行收敛，有并行不悖之功也。\n\n【主治参与】\n得白扁豆、藿香、白茯苓、橘皮、白梅、人参、白术、甘草、砂仁、香薷，治伤暑霍乱，吐泻不止。加入石斛、鸡舌香，治转筋。\n\n同当归、石斛、牛膝、续断、芍药、橘皮，治血虚转筋。\n\n同薏苡仁、术、茯苓、五加皮、石斛、萆薢、黄檗，治湿热脚气。\n\n同人参、白茯苓、麦门冬、藿香、白豆蔻、竹茹、枇杷叶，治胃虚呕吐。\n\n一味末之，白汤吞三钱，日五服，治杨梅结毒有效。\n\n入六和汤，治暑月霍乱。\n\n《圣惠方》治霍乱转筋：木瓜一两，酒一升，煎服。不饮酒者，煎汤服。仍煎汤浸青布裹其足。\n\n《御药院方》四蒸木瓜丸：治肝肾脾三经气虚，为风寒暑湿相搏，流注经络。凡遇时令不和，七情怫郁，必致发动，或肿满，或顽痹，憎寒壮热，呕吐自汗，霍乱吐利，用宣州大木瓜四个，切盖剜空听用。一个入黄耆、续断末各半两于内，一个入苍术、橘皮末各半两于内，一个入乌药、黄松节末各半两于内，黄松节即茯神心中木也，一个入威灵仙、苦葶苈末各半两于内。以原盖盖好拴定，用酒浸透，入甑内蒸熟，晒干，再浸蒸，如此三度，捣末，以榆皮末水和，糊丸如梧子大。每服五十丸，温酒、盐汤任下。\n\n《医林集要》翻花痔疮：木瓜为末，以鱓鱼身上涎，调贴之，以纸护住。\n\n【简误】\n      下部腰膝无力，由于精血虚，真阴不足者，不宜用。伤食，脾胃未虚，积滞多者，不宜用。入药忌犯铁器。', NULL, NULL, NULL, '木瓜实', NULL, '11、木瓜实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019543, 'D48389C9DBFE247B5F85EF93B2F8C128', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7580, 429, 400107310, '      味酸，平，无毒。主下气，除热烦满，安心，肢体痛，偏枯不仁，死肌，去青黑痣，恶疾，止下痢，好唾口干。\n\n       疏：梅实，即今之乌梅也。梅得木气之全，故其味最酸，所谓曲直作酸是也。《经》曰：热伤气。邪客于胸中，则气上逆而烦满，心为之不安。乌梅味酸，能敛浮热，能吸气归元，故主下气，除热烦满，及安心也。下痢者，大肠虚脱也。好唾口干者，虚火上炎，津液不足也。酸能敛虚火，化津液，固肠脱，所以主之也。其主肢体痛，偏枯不仁者，盖因湿气侵于经络，则筋脉弛纵，或疼痛不仁。肝主筋，酸入肝而养筋，肝得所养，则骨正筋柔，机关通利，而前证除矣。其主去死肌、青黑痣、恶肉者、白梅之功也。白梅味咸，咸能软坚故也。又能消痰，醒睡，止霍乱，解酒毒。弘景云：生梅、乌梅、白梅功用大约相似，第乌梅较良，资用更多。\n\n【主治参与】\n乌梅同川黄连、白芍药、滑石、甘草、莲肉、白扁豆、葛根、升麻、红曲、橘红作丸，治滞下如神。\n\n一味作汤，代茶饮，治火炎头痛。\n\n仲景乌梅丸：治蛔厥，蛔上入膈，故烦，须臾复止，得食而呕，又烦者，蛔闻食即出故耳。用乌梅三百个，细辛、附子、人参、桔梗、黄檗各六两，当归、蜀椒各四两，黄连一斤，干姜十两，捣乌梅肉和丸桐子大。先食饮服十丸，日三服。\n\n《刘涓子鬼遗方》蚀恶疮努肉：用乌梅肉烧为灰，傅上，恶肉立尽。\n\n《圣惠方》赤痢腹痛：乌梅肉、黄连各四两，炼蜜丸梧子大。每米饮下二十丸，日三服。\n\n《图经本草》治劳疟，用乌梅十四枚，豆豉二合，甘草三寸，生姜一块，以童便二升，煎去一半，温服即止。\n\n治暑气霍乱：白梅一个，和仁捣碎，入丝瓜叶一叶，或扁豆叶，再捣烂，用新汲水调，灌下即解。\n\n【简误】\n      《素问》云：味过于酸，肝气以津。又云：酸走筋，筋病无多食酸。以肝主筋，性喜升发，酸味敛束，是违其性之所喜也。梅实过酸，不宜多食。齿痛及病当发散者，咸忌之。', NULL, NULL, NULL, '梅实', NULL, '10、梅实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019544, 'E51DBF9DC3D79A83928C77281830AD15', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7581, 429, 400107309, '     味甘，平、寒，无毒。主补中养神，益气力，除百疾。久服轻身耐老，不饥延年。\n\n     疏：藕实得天地清芳之气，禀土中冲和之味，故味甘气平。《别录》寒，无毒。入足太阴、阳明，兼入手少阴经。土为万物之母，后天之元气藉此以生化者也。母气既和则血气生，神得所养而疾病无由来 \n矣。藕实正禀稼穑之化，乃脾家之果，故主补中养神，益气力，除百疾，及久服轻身耐老，不饥延年也。孟诜主五脏不足伤中，益十二经脉血气。大明主止渴去热，安心，止痢，治腰痛及泄精。多食令人喜，皆资其补益心脾之功也。\n\n【主治参与】\n得川黄连、白芍药、白扁豆、干葛、升麻、红曲、橘红、甘草、滑石、乌梅为丸，治滞下如神。\n\n下痢饮食不入，俗名噤口痢。此证大危，用鲜莲肉一两，黄连五钱，人参五钱，水煎浓。细细与呷，服完思食便瘥。同菟丝子、五味子、山茱萸、山药、车前子、肉豆蔻、砂仁、橘红、芡实、人参、补骨脂、巴戟天，治脾肾俱虚，五更溏泻。有肺热者去人参、肉豆蔻。\n\n孟诜《食疗》服食不饥：石莲肉蒸熟去心，为末，炼蜜丸梧子大。日服三十丸。此仙家方也。\n\n《普济方》白浊遗精：石莲肉、龙骨、益智仁等分，为末。每服二钱，空心米饮下。\n\n《直指方》心虚赤浊：莲子六一汤：用石莲肉六两，炙甘草一两，为末。每服一钱，灯心汤下。\n\n《丹溪心法》久痢噤口：石莲肉炒为末，每服二钱，陈仓米汤调下，便觉思食，甚妙。\n\n君山药、白茯苓、白术、人参、莲肉、薏苡仁、白扁豆，为补脾胃要药。\n\n一味捣末，熬金樱子煎，和丸。服之补下元益人，谓之水陆丹。\n\n《经验方》鸡头粥法：用鸡头实三合，煮熟去壳，粳米一合煮粥，日日空心食。能益精气，强志意，利耳目。\n\n《永类钤方》四精丸：治思虑色欲过度，损伤精气，小便数，遗精。用秋石、白茯苓、芡实、莲肉各二两，为末，蒸枣和丸梧子大。每服三十丸，空心盐汤送下。\n\n【简误】\n芡实生食味涩，动风冷气，小儿不宜多食，以其难消化也。', NULL, NULL, NULL, '芡实,鸡头实', NULL, '9、芡实,鸡头实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019545, '9FEE580D25E31573484F1DAC019C04C1', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7582, 429, 400107308, '     味甘，平，无毒。主益气轻身，令发不白。\n\n     疏：覆盆子得木气而生，本经味甘，气平，无毒；甄权微热，宗奭酸甘，深得其义。入足少阴经。其主益气者，言益精气也。肾藏精，肾纳气，精气充足则身自轻，发不白也。苏恭：立补虚续绝，强阴健阳，悦泽肌肤，安和脏腑。甄权：主男子肾精虚竭，阴痿。女子食之有子。大明：主安五脏，益颜色，养精神，长发，强志。皆取其益肾添精，甘酸收敛之义耳。\n\n【主治参与】\n同黄檗、沙苑蒺藜、莲须、五味子、砂仁、鱼胶、山茱萸，治梦遗泄精。\n\n同车前子、五味子、菟丝子、蒺藜子，为五子衍宗丸。治男子精气亏乏，中年无子。\n\n加入巴戟天、腽肭脐、补骨脂、鹿茸、白胶、山茱萸、肉苁蓉，治阳虚阴痿，临房不举，或精寒精薄。\n\n【简误】\n强阳不倒者忌之。', NULL, NULL, NULL, '覆盆子', NULL, '8、覆盆子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019546, '18ECC85B3DA471480EA923087C1E51DF', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7583, 429, 400107307, '     味甘，平，无毒。主心腹邪气，安中养脾，助十二经，平胃气，通九窍，补少气、少津液、身中不足，大惊，四肢重，和百药，补中益气强力，除烦闷，疗心下悬，肠澼。久服轻身延年，不饥神仙。\n\n      疏：大枣纯得土之冲气，兼感天之微阳以生。《本经》味甘，气平，无毒。东垣、孟诜言温。气味俱厚，阳也。入足太阴、阳明经。《经》曰：里不足者，以甘补之。又曰：形不足者，温之以气。甘能补中，温能益气，甘温能补脾胃而生津液，则十二经脉自通，九窍利，四肢和也。正气足则神自安，故主心腹邪气，及大惊。中得缓则烦闷除，故疗心下悬急，及少气。脾得补则气力强，肠胃清，故主身中不足及肠澼。甘能解毒，故主和百药。脾胃足，气血充，后天生气借此而盈溢，故久服轻身长年，不饥神仙也。然亦指辟谷修炼者言之，非恒人所能耳。\n\n【主治参与】\n大枣甘温，能和阴阳，调荣卫，生津液。凡邪在荣卫者，辛甘以解之，故仲景桂枝汤，用姜、枣以和荣卫，助脾胃，生津液，令出汗也。\n\n仲景治伤寒水饮胁痛，咳而干呕者，有十枣汤，取其益土而胜水也。\n\n又方，发汗后，小便利，其人脐下悸，欲作奔豚者，茯苓桂枝甘草大枣汤主之。茯苓能伐肾邪，桂枝泄奔豚，甘草、大枣之甘，滋助脾土，以平肾气。\n\n许叔微《本事方》治妇人脏躁，悲伤欲哭，象若神凭，数欠者，大枣汤：大枣十枚，小麦一升，甘草二两，每服一两，水煎服之。\n\n【简误】\n         枣虽能补脾胃、益气，然而味过于甘，中满者忌之。小儿疳病不宜食，齿痛及患痰热者不宜食。生者尤不利人，多食致寒热。', NULL, NULL, NULL, '大枣', NULL, '7、大枣', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019547, 'CFCD991342797AF57E36B18FED722081', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7584, 429, 400107306, '       古今方书不载，能散阳明、厥阴经滞气。妇人妒乳、内外吹、乳岩、乳痈用之皆效。以诸证皆二经所生之病也。', NULL, NULL, NULL, '橘叶', NULL, '6、橘叶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019548, 'CD9D7464B24DF9F6680D4B3DD3844855', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7585, 429, 400107305, '     主腰痛，膀胱气，肾冷。炒去壳，酒服良。\n      按：橘核出日华子，其味苦温而下气，所以能入肾与膀胱，除因寒所生之病也。疝气方中多用。', NULL, NULL, NULL, '橘核', NULL, '5、橘核', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019549, 'BAD7C8147453FD67EC792AF30E84F76B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7586, 429, 400107304, '    主气滞，下食，破积结及膈气。\n\n     疏：青皮古方无用者，至宋时医家始用之。其色青，其味极苦而辛，其气温而无毒。气味俱厚，沉而降，阴也。入足厥阴、少阳。苦泄、辛散，性复刻削，所以主气滞，下食，破结积及膈气也。元素：破坚癖，散滞气，治左胁肝经积气。亦此意耳。\n\n【主治参与】\n青皮同人参、鳖甲，能消疟母。\n\n同枳壳、肉桂、川芎，治左胁痛。\n\n同人参、白术、三棱、蓬茂、阿魏、矾红、山查、红曲、木香，消痃癖气块，及一切肉食坚积。\n\n【简误】\n       青皮性最酷烈，削坚破滞是其所长。然误服之，立损人真气，为害不浅。凡欲使用，必与人参、术、芍药等补脾药同用，庶免遗患，必不可单行也。肝脾气虚者，概勿施用。', NULL, NULL, NULL, '青皮,青橘', NULL, '4、青皮,青橘', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019550, '0A2A1740EDCEA67A1820E88F9C8FD885', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7587, 429, 400107303, '       味辛，温，无毒。主胸中瘕热逆气，利水谷，下气止呕咳，除膀胱留热停水，五淋，利小便，主脾不能消谷，气冲胸中，吐逆霍乱，止泄，去寸白。久服去臭，下气通神，轻身长年。（按：橘、柚实两种，《本经》作一条，盖传误也。今改正。）\n\n        疏：橘皮，花开于夏，实成于秋，得火气少，金气多，故味辛苦，气温无毒。味薄气厚，降多升少，阳中之阴也。入手足太阴、足阳明经。其主胸中瘕热逆气，气冲胸中呕咳者，以肺主气，气常则顺，气变则逆，逆则热聚于胸中而成瘕。瘕者，假也。如痞满郁闷之类也。辛能散，苦能泄，温能通行，则逆气下，呕咳止，胸中瘕热消矣。脾为运动磨物之脏，气滞则不能消化水谷，为吐逆霍乱，泄泻等证，苦温能燥脾家的湿，使滞气运行，诸证自瘳矣。肺为水之上源，源竭则下流不利，热结膀胱。肺得所养而津液贯输，气化运动，故膀胱留热停水，五淋皆通也。去臭及寸白者，辛能散邪，苦能杀虫也。通神轻身长年者，利脾肺之极功也。\n\n【主治参与】\n橘皮留白，补脾胃和中；去白，消痰理肺气。同白术则补脾，同甘草则补肺，同补气药则益气，同泄气药则破气，同消痰药则能去痰，同消食药则能化食，各从其类以为用也。\n\n同人参、何首乌、桂枝、当归、姜皮，治三日疟寒多。\n\n得白豆蔻、生姜、藿香、半夏，治胃家有寒痰，或偶感寒气，伤冷食，呕吐不止。\n\n同人参、白术、白茯苓、甘草、山药、白豆蔻、藿香、麦芽、山查、白扁豆，治脾胃虚，饮食不化，或不欲食，食亦无味。\n\n同苏子、贝母、枇杷叶、麦门冬、桑根白皮、沙参、栝楼根、五味子、百部，治上气咳嗽，能消痰下气。\n\n同枳壳、乌药、木香、草豆蔻、槟榔，治气实人暴气壅胀。\n\n同苍术、厚朴、甘草，为平胃散，治胸中胀满。\n\n入二陈汤，治脾胃湿痰及寒痰痰饮。\n\n仲景方：橘皮汤：治男女伤寒，并一切杂病呕哕，手足逆冷者，用橘皮四两，生姜一两，水二升，煎一升，徐徐呷之即止。\n\n《百一选方》霍乱吐泻，但有一点胃气存者，服之即生：广陈皮去白五钱，真藿香五钱，水二盏，煎一盏，时时温服。\n\n《食疗》治脚气冲心，或心下结硬，腹中虚冷：陈皮一斤和杏仁五两去皮尖熬，少许蜜捣和，丸如梧桐子大，每日食前米饮下三十丸。\n\n《普济方》大肠闭塞：陈皮连白，酒煮焙干，研末。每服二钱，米饮下。\n\n《适用方》脾寒诸疟，不拘老少孕妇，只两服便止：真橘皮去白切，生姜自然汁浸过一指，银石器内重汤煮干，焙，研末，每服三钱，用隔年青州枣十个，去核，水一盏，煎半盏，发前服，以枣下之。\n张氏方：妇人乳痈，未成者即散，已成者即溃，痛极者不痛，神验不可言。用真橘皮汤浸去白，晒干，面炒微黄，为末。每服二钱，麝香调酒下，初发一服见效。\n\n【简误】\n         橘皮味辛气温，能耗散真气，中气虚，气不归元者，忌与耗气药同用。胃虚有火呕吐，不宜与温热香燥药同用。阴虚咳嗽生痰，不宜与半夏、南星等同用。疟非寒甚者，亦勿施。', NULL, NULL, NULL, '陈皮,橘皮', NULL, '3、陈皮,橘皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019551, 'CF744128169978547DF3609C623E2849', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7588, 429, 400107302, '     《唐本》注：主热渴，散血生肌。久服令人心欢。《药性论》云：藕汁，味甘，能消瘀血不散。藕节，捣汁主吐血不止，或口鼻出血。孟诜云：生食之，主霍乱后虚渴烦闷不能食。其产后忌生冷物，惟藕不同生冷，为能破血故也。蒸食甚补五脏，实下焦。陈藏器云：消食止泄，除烦，解酒毒，及病后热渴。日华子云：止霍乱，开胃消食，除烦止闷，口干渴疾，止怒，令人喜，破产后血闷，捣罯金疮并伤折，止暴痛。\n\n       疏：藕禀土气以生，其味甘，生寒熟温。入心、脾、胃三经。生者甘寒，能凉血止血，除热清胃，故主消散瘀血，吐血，口鼻出血，产后血闷，罯金疮伤折，及止热渴，霍乱烦闷，解酒等功。熟者甘温，能健脾开胃，益血补心，故主补五脏，实下焦，消食止泄，生肌，及久服令人心欢止怒也。本生于污泥之中，而体至洁白，味甚甘脆，孔窍玲珑，丝纶内隐，疗血止渴，补益心脾，真水果中之嘉品也。又能解蟹毒。\n\n       莲蕊须，一名佛座须，味甘涩，气温。本经不收，而古方固真补益方中，往往用之。详其主治，乃是足少阴经药，也能通手少阴经。能清心入肾，固精气，乌须发，止吐血，疗滑泄。同黄檗、砂仁、沙苑蒺藜、鱼胶、五味子、覆盆子、生甘草、牡蛎，作丸。治梦遗精滑，最良。\n', NULL, NULL, NULL, '藕', NULL, '2、藕', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019552, '3F30499785B02C567DCCD3CA466E128B', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7589, 429, 400107301, '    味甘，平、寒，无毒。主补中养神，益气力，除百疾。久服轻身耐老，不饥延年。\n\n     疏：藕实得天地清芳之气，禀土中冲和之味，故味甘气平。《别录》寒，无毒。入足太阴、阳明，兼入手少阴经。土为万物之母，后天之元气藉此以生化者也。母气既和则血气生，神得所养而疾病无由来矣。藕实正禀稼穑之化，乃脾家之果，故主补中养神，益气力，除百疾，及久服轻身耐老，不饥延年也。孟诜主五脏不足伤中，益十二经脉血气。大明主止渴去热，安心，止痢，治腰痛及泄精。多食令人喜，皆资其补益心脾之功也。\n\n【主治参与】\n得川黄连、白芍药、白扁豆、干葛、升麻、红曲、橘红、甘草、滑石、乌梅为丸，治滞下如神。\n\n下痢饮食不入，俗名噤口痢。此证大危，用鲜莲肉一两，黄连五钱，人参五钱，水煎浓。细细与呷，服完思食便瘥。同菟丝子、五味子、山茱萸、山药、车前子、肉豆蔻、砂仁、橘红、芡实、人参、补骨脂、巴戟天，治脾肾俱虚，五更溏泻。有肺热者去人参、肉豆蔻。\n\n孟诜《食疗》服食不饥：石莲肉蒸熟去心，为末，炼蜜丸梧子大。日服三十丸。此仙家方也。\n\n《普济方》白浊遗精：石莲肉、龙骨、益智仁等分，为末。每服二钱，空心米饮下。\n\n《直指方》心虚赤浊：莲子六一汤：用石莲肉六两，炙甘草一两，为末。每服一钱，灯心汤下。\n\n《丹溪心法》久痢噤口：石莲肉炒为末，每服二钱，陈仓米汤调下，便觉思食，甚妙。\n\n【简误】\n        藕实，脾家果也。甘平无毒，于诸疾并无相迕。第生者食之过多，微动冷气胀人。石莲子乃九月经霜后采，坚黑如石者，破房得之，堕水入泥者良。今肆中一种石莲子，状如榧子，其味大苦，产广中，出树上，木实也，不宜入药。', NULL, NULL, NULL, '莲子,藕实', NULL, '1、莲子,藕实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628187664019553, '04AD02D01E06F8DF17AA7192031D253F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 12:02:11', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7590, 430, 400107404, '      味甘，微温。主补虚乏，止渴，去血。\n\n      疏：饴糖用麦蘖或谷蘖同诸米渍熬炼而成，故其味甘气温无毒。入足太阴，亦入手太阴经。甘入脾，而米麦皆养脾胃之物，故主补虚乏，仲景建中汤用之是也。肺胃有火，则发渴。火上炎迫血妄行，则吐血。甘能缓火之标，则火下降而渴自止，血自去也。思邈又谓其有消痰，润肺，止嗽，治咽痛、吐血等功。\n\n【主治参与】\n入建中汤，治脾虚腹痛。\n\n《简便方》误吞稻芒：白饧频食，效。\n\n《千金方》：服药过剂，闷乱者，饴糖食之。\n\n【简误】\n       饴糖成于湿热，少用虽能补脾润肺，然而过用之则动火生痰。凡中满吐逆，酒病牙疳，咸忌之。肾病尤不可服。', NULL, NULL, NULL, ' 饴糖', NULL, '4、 饴糖', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628215132844102, '41D40F96EF5F46CBB38219A0D9B454B4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 13:53:57', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7591, 430, 400107403, '     微寒。利大肠，胞衣不落。生者摩疮肿，生秃发。（此即乌脂麻油也。功用与白麻油相同，而力更胜。入药当以乌者为佳。）\n\n      疏：麻油，甘寒而滑利，故主胞衣不下，及利大肠。生者气更寒，能解毒凉血，故摩疮肿，生秃发也。藏器主天行热閟，肠内热结。服一合，取利为度。孟诜主瘖痖，杀五黄，下三焦热毒气，通大小肠，治蛔心痛，傅一切恶疮疥癣，杀一切虫。日华子：煎膏，生肌长肉止痛，消痈肿，补皮裂。皆取其甘寒滑利，除湿润燥，凉血解毒之功也。\n\n【主治参与】\n入血余一味熬膏，铅丹收好，能傅一切疮毒，排脓止痛。\n\n诸熬膏，必用真胡麻油，以其凉血解毒也。惟湿气膏不用。岭南解蛊法：以清油多饮，取吐效。\n\n《卫生易简方》：解河豚毒，一时仓卒无药，以清麻油多灌，取吐出毒物，即效。亦能解砒毒。\n\n《胎产须知》：妇人难产，因血枯涩者，用清油半两，好蜜一两，同煎数十沸，温服，胎滑即下。他药无益，以此助血为效。\n\n《直指方》：痈疽发背初起，即服此，使毒气不内攻。以麻油一斤，银石器内煎二十余沸，和醇醋二碗，分五次，一日服尽。\n\n《百一选方》肿毒初起：麻油煎葱黑色，趁热通手旋涂，自消。\n\n又方，丹石毒发，发热者不得食热物，不得用火，但着厚衣暖卧，取清油一匙含咽。\n\n刘禹锡《传信方》：蚰蜒入耳，用麻油煎作饼，枕卧，须臾自出。\n\n【简误】\n       麻油生者过寒，多食发冷疾，及脾胃虚寒作泻者，不宜食。熬熟治饮食甚美，但须逐日熬用，不可过宿，若经宿则火性反复，能助热动气也。', NULL, NULL, NULL, '胡麻油', NULL, '3、胡麻油', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628215132844103, '84CDC6367665622724DA4ECBCC2C3E3A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 13:53:57', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7592, 430, 400107402, '        味甘，平，无毒。主补中益气，中风汗出，逐水，利小便，破积血，复血脉，乳妇产后余疾，长发，可为沐药。久服肥健，不老神仙。\n\n         疏：麻子，即大麻仁，禀土气以生。《本经》味甘平无毒。然其性最滑利，甘能补中，中得补则气自益。甘能益血，血脉复则积血破，乳妇产后余疾皆除矣。风并于卫，则卫实而荣虚。荣者，血也，阴也。《经》曰：阴弱者，汗自出。麻仁益血补阴，使荣卫调和，风邪去而汗自止也。逐水利小便者，滑利下行，引水气从小便而出也。好古云：入手、足阳明，足太阴经。阳明病汗多，及胃热便难，三者皆燥也，用之以通润。《经》曰：脾欲缓，急食甘以缓之。麻仁之甘以缓脾润燥，故仲景脾约丸用之。\n\n【主治参与】\n《食医心镜》麻子仁粥：治风水腹大，腰脐重痛，不可转动，用冬麻子半升，研碎，水滤取汁，入粳米二合，煮稀粥，下葱、椒、盐豉，空心食。\n\n仲景方：麻子仁丸：治脾约，大便秘而小便数。麻子仁二升，芍药半斤，厚朴一尺，大黄、枳实各一斤，杏仁一升，熬研，炼蜜丸梧子大。每以浆水下十丸，日三服。不知再加。\n\n《本事方》产后秘塞，许学士云：产后汗多则大便必秘，难于用药，惟麻子粥最稳。不惟产后可服，凡老人诸虚风秘，皆妙。用大麻子仁、紫苏子各二合，洗净研细，再以水研，滤取汁一盏，分二次煮粥啜之。\n\n夏子益《奇疾方》：截肠怪病，大肠头出寸余，痛苦，干则自落，又出，名为截肠病，若肠尽则不治。但初觉截时，用器盛脂麻油坐浸之，饮大麻子汁数升，即愈也。\n\n【简误】\n陈士良云：多食损血脉，滑精气，痿阳事。妇人多食即发带疾，以其滑利下行，走而不守也。', NULL, NULL, NULL, '麻子仁,麻子,大麻仁', NULL, '2、麻子仁,麻子,大麻仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628215132844104, 'A4EB9A465A00753BD38BE12FEBCA8C0D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 13:53:57', 1, 'admin', '2025-01-15 16:32:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7593, 430, 400107401, '     味甘，平，无毒。主伤中虚羸，补五内，益气力，长肌肉，填髓脑，坚筋骨。疗金疮止痛，及伤寒、温疟大吐后，虚热羸困。久服轻身不老，明耳目，耐饥渴，延年。一名巨胜。\n\n      疏：胡麻禀天地之冲气，得稼穑之甘味，故味甘气平无毒。入足太阴，兼入足厥阴、少阴。气味和平，不寒不热，益脾胃，补肝肾之佳谷也。弘景云：八谷之中，惟此为良。仙家作饭饵之，断谷长生。故主伤中虚羸，补五内，益气力，长肌肉，坚筋骨，填髓脑，及伤寒、温疟大吐后，虚热羸困。久服明耳目，耐饥渴，轻身不老延年也。金刃伤血则瘀而作痛，甘平益血润燥，故疗金疮止痛也。日华子：主补中益气，润养五脏，补肺气，止心惊，利大小肠，逐风湿气，游风，头风，劳气，产后羸困。李廷飞云：风病人久服，则步履端正，语言不蹇。陈士良：生嚼涂小儿头疮，煎汤浴恶疮，及妇人阴疮。皆取其甘平益血脉，补虚羸，入肝脾肾之功耳。刘河间曰：麻，木谷而治风。又云：治风先治血，血活则风去。胡麻入肝益血，故风药中不可阙也。\n\n【主治参与】\n得何首乌、茅山苍术、白茯苓、菖蒲、桑叶、牛膝、当归、续断、地黄、桑上寄生，治风湿痹。\n\n同甘菊花、天门冬、黄檗、生地黄、何首乌、柏子仁、桑叶、牛膝、枸杞子、麦门冬作丸，治似中风口眼㖞斜，半身不遂。久服不辍，有神验。\n\n一味九蒸九曝，加茅山苍术，乳蒸晒三次，作丸。能健脾燥湿，益气延年。\n\n抱朴子服食胡麻法：用上党胡麻三斗，淘净蒸令气透，日干，以水淘去沫再蒸，如此九度。去壳，炒香为末，白蜜或枣膏丸弹子大。每温酒化下一丸，日三服。忌毒鱼、狗肉、生莱菔至百日。能除一切痼疾，一年病色光泽不饥，二年白发还黑，三年齿落更生，久服常生不老矣。\n\n《外台秘要》解下胎毒：小儿初生，嚼生脂麻，绵包，与儿咂之，其毒自下。\n\n《简便方》小儿瘰疬：脂麻、连翘等分，为末。频频食之。\n\n《经验方》蜘蛛及一切虫咬伤，油麻研烂傅之。\n\n《三因方》：谷贼尸咽，喉中痛痒，此因误吞谷芒，戟刺痒痛也。用脂麻炒研，白汤调下。\n\n甘平无毒，补益为用，仙家服食所须。故不著 “简误”。', NULL, NULL, NULL, '胡麻', NULL, '1、胡麻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628215132848197, 'E15A70E493D49C4999AAA864BDEC0C14', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 13:53:57', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7594, 431, 400107511, '   味甘，寒，无毒。主丹毒，烦热，风疹，药石发动。热气奔豚，生研绞汁服。亦煮食，消肿下气，压热解石。用之勿去皮，令人小壅。\n\n    疏：绿豆禀土中之阴气，故其味甘气寒无毒。入足阳明经。夫丹石之药，气悍而性热，多服则火动，上升为烦热，甚则口鼻出血，狂闷躁扰。甘寒能除热下气解毒，故主服丹石药人毒发烦热也。阳明客热，则发出风疹，以胃主肌肉，热极生风故也。解阳明之热，则风疹自除。胀满者，湿热侵于脾胃也。热气奔豚者，湿热客于肾经也。除湿则肿消，压热则气下，益脾胃而肾邪亦自平也。孙思邈：主寒热热中，止泄痢，卒澼，利小便胀满。日华子：主厚肠胃。作枕，明目，治头风头痛，益气，除热毒风。孟诜：主去浮风，益气力，治消渴，和五脏，安精神。可常食之，功效不可备述。\n\n【主治参与】\n扁鹊三豆饮：治天行痘疮，预服此饮，疏解热毒，纵出亦少。用绿豆、赤小豆、黑豆各一升，甘草节二两，以水八升，煮极熟。任意吞豆饮汁，七日乃止。\n\n《医学正传》：痘后痈毒初起，以三豆膏治之，神效。绿豆、赤小豆、黑大豆等分，为末。醋调时时扫涂，即消。\n\n《全幼心鉴》小儿丹肿：绿豆五钱，大黄二钱，为末，用生薄荷汁入蜜调涂。中砒毒者，研汁饮之。\n\n【简误】\n     脾胃虚寒滑泄者，忌之。', NULL, NULL, NULL, '绿豆', NULL, '11、绿豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491462, '62105E5EFD24DE4DB46EB35317900972', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7595, 431, 400107510, '   味苦，寒，无毒。主伤寒头痛寒热，瘴气恶毒，烦躁满闷，虚劳喘吸，两脚疼冷。\n\n     疏：豉，诸豆皆可为之，惟黑豆者入药。有盐、淡二种，惟江右淡者治病。经云：味苦，寒，无毒。然详其用，气应微温。盖黑豆性本寒，得蒸晒之，气必温。非苦温则不能发汗开腠理，治伤寒头痛寒热，及瘴气恶毒也。苦以涌吐，故能治烦躁满闷。以热郁胸中，非宣剂无以除之。如伤寒短气烦躁，胸中懊憹，饥不欲食，虚烦不得眠者，用栀子豉汤吐之是也。又能下气调中，辟寒，故主虚劳喘吸，及两脚冷疼。\n\n【主治参与】\n《肘后方》云：伤寒有数种，庸人卒不能分别者，今取一药兼疗之。凡初觉头痛身热，脉洪，一二日，以葱豉汤治之。用葱白一虎口，豉一升，绵裹，水三升，煮一升。顿服取汗。\n\n仲景栀子豉汤：治伤寒汗下后虚烦，用栀子十四枚，香豉四合绵裹，以水四升，先煮栀子得二升半，内豉，煮取一升半，去滓。分二服，温进一服，得吐，止后服。\n\n又枳实栀子豉汤：治大病瘥后劳复，用枳实三枚，栀子十四枚，豉一升，以清浆水七升，空煮取四升，纳枳实、栀子，取二升，下豉更煮五六沸，去滓。分温再服，令微似汗。伤寒之邪自外入，劳复之邪自内发，发汗、吐下，当随宜施治也。治伤寒食早成食复，前汤中加大黄如博棋子大五枚。\n\n《梅师方》辟除温疫：豉和白术，浸酒，常服之。\n\n甄权方：伤寒暴痢腹痛者，豉一升，薤白一握切，以水三升，先煮薤，内豉更煮。汤色黑，去豉，分二服，不瘥更服。亦治血痢。\n\n孟诜：治久患盗汗，以豉一升，熬令香，清酒三升渍，满三日取汁，冷暖任服，不瘥更作，二剂即止。\n\n《简要济众方》：伤寒后余毒攻手足，及身体虚肿，用豉五合微炒，以酒一升半，同煎五七沸，任性饮之。\n\n《千金方》：蠼螋尿疮，杵豉傅之良。\n\n《卫生易简方》中牛马毒：豉汁和人乳，频服之，效。\n\n《千金方》中酒成病：豉、葱白各半升，水二升，煮一升，顿服。\n\n又方：服药过剂闷乱者，豉汁饮之。\n\n《肘后方》肿从脚起：豉汁饮之，以滓傅之。\n\n弘景云：春夏之气不和，以豉蒸炒，酒渍，服之至佳。\n\n【简误】\n       凡伤寒传入阴经，与夫直中三阴者，皆不宜用。热结胸中烦闷不安者，此欲成结胸，法当下，不宜复用汗吐之药，并宜忌之。', NULL, NULL, NULL, '豉', NULL, '10、豉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491463, 'CECB2FA45808BD61A65F1E4355602831', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7596, 431, 400107509, '    味甘，微温。主和中下气。\n\n     叶：主霍乱吐下不止。\n\n     疏：扁豆禀土中冲和之气，其味甘，气香，性温、平，无毒。入足太阴、阳明经气分，通利三焦，升清降浊，故专治中宫之病，和中下气，消暑除湿而解毒也。孟诜：主霍乱吐利不止，及呕逆，久食头不白。日华子云：补五脏。苏颂：主女子带下，解酒毒、河豚鱼毒。寇宗奭：主霍乱转筋。皆取其益脾开胃，和中气，除湿热之功耳。\n\n叶：气味相同，故主霍乱。\n\n花有紫、白二色，豆有黑、白二种。入药惟紫花、豆白者良。豆黑色及紫色者，名鹊豆，不入药，亦不益人。\n\n【主治参与】\n白扁豆，同山药、白茯苓、人参、莲肉、薏苡仁、芡实，为补脾胃之上药。中焦有湿者加白术。\n\n同黄连、干葛、白芍药、升麻、红曲、滑石、乌梅、橘红、甘草、莲肉，治滞下如神。\n\n同麦门冬、五味子、黄连、干葛，能解酒毒。\n\n同木瓜、石斛、橘皮、藿香、茯苓、缩砂、香薷，治霍乱吐泻转筋。\n\n入十味香需饮，能消暑气，健脾。\n\n《奇效良方》血崩不止：白扁豆花，焙干为末。每服二钱，空心炒米煮饮，入盐少许，调下，即效。\n\n治霍乱秘法：用白扁豆叶一叶，同白梅一枚，并仁研烂。新汲水调服，神效。\n\n苏恭：治吐利后转筋。用白扁豆叶一把，捣，入醋少许，绞汁服，立瘥。\n\n【简误】\n       弘景云：患寒热者不可食。盖指伤寒寒热，外邪方炽，不可用此补益之物耳。如脾胃虚，及伤食劳倦发寒热者，不忌。', NULL, NULL, NULL, '扁豆', NULL, '9、扁豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491464, '8E8383FB88E54402FF8DB6F107E0652A', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7597, 431, 400107508, '     味甘，大暖。疗藏腑中风气，调中下气，开胃，消宿食，主霍乱，心膈气，痰逆，除烦，破癥结，补虚，去冷气，除肠胃中塞，不下食，令人有颜色。六月作者良。\n\n      神曲：使，无毒。能化水谷宿食，癥气。健脾暖胃。\n\n      疏：古人用曲，即造酒之曲。其气味甘温，性专消导，行脾胃滞气，散脏腑风冷，故主疗如诸家所言也。\n\n     神曲，乃后人专造以供药用，力倍于酒曲。盖取诸神聚会之日造之，又取各药物以象六神之用，故得神名。陈久者良。入药炒令香用。六畜食米多。胀欲死者，煮曲汁灌之立消。\n\n    造神曲法：用五月五日，或六月六日，以白面百斤，青蒿自然汁三升，赤小豆末、杏仁泥各三升，苍耳自然汁、野蓼自然汁各三升，以配白虎、青龙、朱雀、玄武、勾陈、腾蛇六神，用汁和面、豆、杏仁作饼，麻叶或楮叶包罯，如造酱黄法，待生黄衣，晒干收之。\n\n【主治参与】\n神曲，开胃健脾，消食止泄，同山查、麦蘖、谷蘖、缩砂、陈皮、草果、藿香、白术、干葛、莲肉等用，效。\n\n《百一选方》疗痞满暑泄，曲术丸：用神曲炒，苍术泔制炒，等分为末，糊丸梧子大。每米饮下五十丸。\n\n《和剂局方》：健胃思食，治脾胃俱虚，不能消化水谷，胸膈痞闷，腹胁膨胀，连年累月，食减嗜卧，口无味。神曲六两，麦蘖炒三两，干姜炮四两，乌梅肉焙四两，为末，蜜丸梧子大。每米饮下五十丸，日三服。\n\n《摘玄方》食积心痛：陈神曲一块烧红，淬酒二大碗，服之。\n\n【简误】\n      脾阴虚，胃火盛者，不宜用。能落胎，孕妇宜少食。', NULL, NULL, NULL, '神曲,曲', NULL, '8、曲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491465, '50C0A37A7E820CAD3F213A078F141605', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', 1, 'admin', '2025-01-17 17:22:33');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7598, 431, 400107507, '      味咸，温、微寒，无毒。主消渴，除热，益气，调中。又云：令人多热，为五谷长。（蜜为之使。）\n\n       疏：大麦功用与小麦相似，而其性更平凉滑腻，故人以之佐粳米同食，或歉岁全食之，而益气补中，实五脏，厚肠胃之功，不亚于粳米矣。陈士良云：补虚劣，壮血脉，化谷食，止泄泻，不动风气，久食令人肥白，滑肌肤。为面无燥热，胜于小麦。苏恭云：平胃止渴，消食疗胀满。其为效可知。本经末云：令人多热。与上文及诸说相背，必是误入也。\n\n麦蘖\n苏颂云：化宿食，破冷气，止心腹胀满。日华子：温中，下气，开胃，止霍乱，除烦，消痰，破癥结。\n\n      疏：麦蘖，以水渍大麦而成。其味咸，气温，无毒。功用与米蘖相同，而此消化之力更紧。咸能软坚，温主通行。其发生之气，又能助胃气上升，行阳道而主健运。故主开胃补脾，消化水谷，及一切结积，冷气，胀满，如上所言等证也。好古曰：麦芽、神曲二药，胃气虚人宜服之，以代戊己腐熟水谷。豆蔻、缩砂、乌梅、木瓜、芍药、五味子为之使。\n\n【主治参与】\n麦蘖同山查、红曲、橘皮、草果、砂仁、厚朴、苍术，消食积。\n\n快膈进食：麦芽四两，神曲二两，白术、橘皮各一两，为末，蒸饼丸梧子大。每人参汤下三五十丸。\n\n李绛《兵部手集》：产后腹胀不通转，气急，坐卧不安，以麦蘖一合，为末。和酒服，良久通转，神验。\n\n《妇人经验方》：产后青肿，乃血水渍也。干漆、大麦蘖等分，为末。新瓦中铺漆一层，孽一层，重重令满，盐泥固济，煅赤，研末。热酒调服二钱，产后诸疾并宜。\n\n丹溪方：产后回乳：产妇无子食乳，乳不消，令人发热恶寒，用大麦蘖二两炒，为末。每服五钱，白汤下，甚良。\n\n【简误】\n     麦蘖能消导米面、诸果食积。无积滞，脾胃虚者，不宜用。久服消肾气，堕胎。', NULL, NULL, NULL, '大麦', NULL, '7、大麦', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491466, 'D536503236905DC0742C1F6C1124C037', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7599, 431, 400107506, '       味甘，微寒，无毒。主除热，止燥渴咽干，利小便，养肝气，止漏血、唾血。以作曲，温。消谷，止痢。以作面，温。不能消热止烦。\n\n       疏：小麦禀四时中和之气，故其味甘，气微寒，无毒。入手少阴经。少阴有热，则燥渴咽干，解少阴之热，则燥渴咽干自止。心与小肠为表里，脏气清，腑病亦自除，故利小便。肝、心为子母之脏，子能令母实，故主养肝气。甘寒走二经而能益血凉血，故止漏血、唾血也。\n\n曲：性温，所以能消谷，止痢。\n\n面：性热，故不能消热止烦。北方霜雪多，地气厚，热性减，凡入药以北来者为胜。\n\n浮麦：即水淘浮起者，能止自汗、盗汗，亦以北方者良。古方有用寒食面者，寒食日，以纸袋盛面，悬风处，数十年亦不坏。取其热性去而无毒也。\n\n【主治参与】\n《奉亲书》老人五淋，身热腹满：小麦一升，通草二两，水三升，煮一升。饮之，良。\n\n《生生编》走气作痛：用小麦麸拌，酽醋炒热，袋盛熨之。\n\n面作蒸饼和药，取其易消也。\n\n【简误】\n      小麦寒气全在皮，故面去皮则热，热则壅滞动气，发渴助湿，令人体浮，皆其害也。凡大人脾胃有湿热，及小儿食积疳胀，皆不宜服。然北人以之代饭，常御而不为患者，此其地势高燥，无湿热熏蒸之毒，故面性亦温平，能厚肠胃，强气力，补虚助五脏，其功不减于稻粟耳。东南卑湿，春多雨水，其湿热之气郁于内，故食之过多，每能发病也。夏月疟、痢人，尤不宜食。', NULL, NULL, NULL, '小麦', NULL, '6、小麦', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491467, 'BA412C895F87568D0BAB232550C65106', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7600, 431, 400107505, '     味苦，无毒。主寒中，下气，除热。\n\n    疏：蘖米，即稻蘖也。味甘，气温，无毒。具生化之性，故为消食健脾，开胃和中之要药。脾胃和则中自温，气自下，热自除也。\n【主治参与】\n《澹寮方》启脾进食，谷神丸：用谷蘖四两，为末，入姜汁、盐少许，和作饼，焙干，入炙甘草、砂仁、白术麸炒各一两，为末。白汤点服，或丸服。', NULL, NULL, NULL, '蘖米,稻蘖', NULL, '5、蘖米,稻蘖', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491468, '4E33C3531BE3E71048EFDC4B991BBB7D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7601, 431, 400107504, '     味甘、苦，平，无毒。主益气，止烦，止泄。\n\n      疏：粳米，即人所常食米，感天地冲和之气，同造化生育之功，为五谷之长，人相赖以为命者也。《经》曰：安谷则昌，绝谷则亡。仲景曰：人受气于水谷以养神，水谷尽而神去。自上古圣人树艺，至今不可一日无此也。禀土德之正，其味甘而淡，其性平而无毒。虽专主脾胃，而五脏生气，血脉、精髓，因之以充溢周身；筋骨、肌肉、皮肤，因之而强健。本经益气，止烦、止泄，特其余事耳。\n\n【主治参与】\n入白虎汤，治作劳人伤寒发热，虚羸少气，气逆上冲欲吐。少阴病下痢脓血，或腹满下如鱼脑者，桃花汤主之。粳米一升，赤石脂一斤，一半全，一半末，干姜一两，以水七升，煮米令熟，去滓。温服七合，内赤石脂末方寸匕，日三服。若一服愈，余勿服。以上仲景法。\n\n《普济方》：小儿初生无皮，色赤，但有红筋，乃受胎未足也。用早白米粉扑之，肌肤自生。\n\n《千金方》：嗜食生米成瘕，用白米五合，鸡屎一升，同炒焦，为末，水一升，顿服。少时吐出瘕，如研米汁，或白沫淡水，乃愈也。', NULL, NULL, NULL, '粳米', NULL, '4、粳米', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491469, '3501A630908BC85413C18EB0DDF53369', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7602, 431, 400107503, '      味苦、甘、辛，大热，有毒。主行药势，杀百邪恶毒气。\n\n      疏：酒，品类极多，醇醨不一，惟米造者入药用。经云：酒者，热谷之液，其气悍。弘景云：大寒凝海，惟酒不冰。明其性热，独冠群物。制药多用之，以藉其势。人饮多则体弊神昏，是其有毒故也。《博物志》云：昔三人冒雾晨行，一人饮酒，一人饱食，一人空服。空腹者死，饱食者病，饮酒者健。此酒势辟邪恶毒气之效，胜于他物也。藏器主通血脉，厚肠胃，润皮肤，消忧发怒，宣言畅意。无非取其横行经络，走散皮肤，开发宣通之功耳。\n\n【主治参与】\n诸药可造酒者：五加皮、女贞实、仙灵脾、薏苡仁、天门冬、麦门冬、地黄、菖蒲、枸杞子、人参、何首乌、甘菊花、黄精、桑椹、术、蜜、仙茅、松节、柏叶、竹叶、胡麻、磁石、蚕沙、乌白蛇、鹿茸、羊羔、腽肭脐、黑豆之类。各视其所生之病，择其所主之药，入曲、米，如常酿酒法，酿成饮。或袋盛入酒内，浸数日，饮之。\n\n《肘后方》：鬼击诸病，卒然着人，如刀刺状，胸胁腹内切痛，不可抑按，或吐血、鼻血、下血。以醇酒吹两鼻内，良。\n\n又方，马气入疮，或马汗、马毛入疮，皆致肿痛烦热，入腹则杀人。多饮醇酒，至醉即愈。\n\n《千金方》三十年耳聋：酒三升，渍牡荆子一升，七日去滓，任性饮之。\n\n《梅师方》产后血闷。清酒一升，和生地黄汁煎服。\n\n【简误】\n       王好古曰：酒能引诸经不止，与附子相同。味之辛者能散，苦者能下，甘者能居中而缓，用为导引，可以通行一身之表，至极高之分。古人惟以麦造曲酿黍，已为辛热有毒。今之醖者，加以乌头、巴豆、桂、姜之类大毒大热之药，以增其气味。岂不伤冲和，损精神，涸荣卫，竭天癸，而夭夫人寿耶？朱震亨云：《本草》止言酒热而有毒，不言湿中发热，近于相火。醉后振寒战慓可见矣。又性喜升，气必随之。痰郁于上，溺涩于下，恣饮寒凉，其热内郁于肺与大肠。其始也病浅，或呕吐，或疮疥，或鼻皶，或泄利，或心脾痛，尚可散而去之。其久也病深，或消渴，或内疽，或肺痈，或鼓胀，或喉哑，或哮喘，或劳瘵，或痔漏，为状不一，非具眼未易处也。扁鹊云：过饮腐肠烂胃，溃髓蒸筋，生痰动火，亡精耗血，伤神损寿。孟诜云：软筋骨，动气痢，醉卧当风则成癜风，醉浴冷水成痈痹。陈士良云：凡服丹砂、钟乳诸石药，并不可长用酒下，能引石药气入四肢，滞血化为痈疽。藏器云：凡饮酒，忌甜物。同牛肉食，令人生虫。合乳饮，令人气结。诸如此类，不可胜载。今人有喜以火逼极热，恣饮为快。不知酒性既热，又以火济火，鲜有不为害者。曾见一人好饮火酒，不几年患一恶证，吐脓血瘀肉而毙。盖肺为火热腐烂也。酒能合欢解忧，御寒祛疾，自上古至今，循习为常用之物。然而如上等害，不可不晓。惟在樽节度量，寒温适宜，不至沉湎荒乱，斯得酒中之趣者。古人终日饮，不及乱，用此道耳。震亨又云：醇酒冷饮有三益，予谓三益未必。然而伤肺生痰，动火损胃之害，可差免矣。', NULL, NULL, NULL, '酒', NULL, '3、酒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491470, 'B0A904EA4078F0C1E1EF6F2273169E51', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7603, 431, 400107502, '       味甘、酸，平，无毒。主下水，排痈肿脓血，寒热，热中，消渴，止泄，利小便，吐逆，卒澼，下胀满。\n\n        疏：赤小豆，禀秋燥之气以生。本经味甘酸，气平，无毒。然详其用，味应有辛，非辛平则不能排痈肿脓血，及疗寒热，热中，消渴也。凡水肿胀满，泄泻，皆湿气伤脾所致，小豆健脾燥湿，故主下水肿胀满，止泄，利小便也。十剂云：燥可去湿。赤小豆之属是矣。吐逆者，气逆上升也。卒澼者，大肠湿热也。甘酸敛逆气，辛平散湿热，故亦主之。\n\n【主治参与】\n陈藏器《本草》：赤小豆和桑根白皮煮食，去湿气痹肿。\n\n孟诜《食疗》：和鲤鱼煮食，甚治脚气。\n\n《金匮要略》：伤寒狐惑病，脉数，无热微烦，默默但欲卧，汗出。初得之三四日，目赤如鸠眼；七八日，目四眦黄黑。若能食者，脓已成也。赤豆当归散主之：赤小豆三升，浸令芽出，当归三两，为末。浆水服方寸匕，日三服。\n\n甄权《药性》热毒痈肿：赤小豆为末，鸡子白调涂。\n\n苏颂《图经》治脚气：以袋盛此豆，置足下，朝夕辗转践踏之，遂愈。\n\n【简误】\n陶弘景云：小豆逐津液，利小便，久服令人枯燥。凡水肿胀满，总属脾虚，当杂补脾胃药中用之。病已即去，勿过剂也。其治消渴，亦借其能逐胃中热，从小便利去。若用之过多，则津液竭而渴愈甚，不可不戒也。', NULL, NULL, NULL, '赤小豆', NULL, '2、赤小豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491471, '9F94D33A0CA3F989738572AEF6C2DF56', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7604, 431, 400107501, '       味甘，平，涂痈肿。煮汁饮，杀鬼毒，止痛。逐水胀，除胃中热痹，伤中淋露，下瘀血，散五藏结积内寒。杀乌头毒。久服令人身重。炒为屑，味甘，主胃中热，去肿除痹，消谷，止腹胀。（恶五参、龙胆。得前胡、杏仁、牡蛎良。）\n\n       疏：生大豆，苏颂云：有黑白二种，黑者入药，白者不用。其紧小者为雄，入药尤佳。禀土气以生，而色黑则象水，故味甘气平无毒。平即兼凉，为肾家之谷也。甘平能活血解毒，祛风散热，故主涂痈肿，止痛，杀鬼毒，乌头毒，除胃中热痹，伤中淋露，下瘀血，散五脏结积内寒，消谷也。色黑属水，同气相求，故能逐水肿腹胀。仙方修治末服之，可以辟谷度饥。然初服时似乎身重，一年以后便觉轻健也。陈藏器：炒令黑，烟未断，及热投酒中饮之，治风痹瘫缓，口噤，产后诸风，及风痉，阴毒腹痛。食罢生吞半两，去心胸烦热，热风。孟诜主中风脚弱，产后诸疾。同甘草煮汤饮，去一切热毒气，及风毒脚气。同桑柴灰煮食，下水鼓腹胀。捣涂一切肿毒。日华子：主调中气，通关脉，制金石药毒，解牛马瘟病。皆取其活血散风，除热解毒，下气利水之功耳。\n\n【主治参与】\n同泽兰、益母草、苏木、人参、牛膝、荆芥、生地黄、童便、蒲黄，治产后血晕闷绝。\n\n同蔓荆子、土茯苓、金银花、甘菊花、玄参、川芎、天麻、芽茶、荆芥、乌梅，治偏头风痛，有神。\n\n古方紫汤：破血去风，除气散热，产后两日，尤宜服之。用黑豆五升，清酒一斗，将豆炒令烟绝，投酒中，待酒紫赤色，去豆。量性饮之，神验。中风口噤，加鸡屎白二升和炒，投之。\n\n《广利方》脚气冲心，烦闷不识人：以大豆一升，水三升，浓煮汁服。未定，再服。\n\n扁鹊方：三豆饮子：能稀痘，见绿豆条内。\n\n大豆壳同蜜蒙花、谷精草、黄连、木贼草、决明子、甘菊花、金银花、生地黄、羚羊角、羊肝，治小儿痘后目翳。\n\n【简误】\n        生大豆，歧伯云：生温，熟寒。藏器云：生平，炒食极热，煮食极寒。观《本经》及孟诜云：生捣涂肿毒，则生者非温矣。经又云：炒为屑，主胃中热，则炒者又非极热矣。应是生平、炒温、煮寒无疑。忌猪肉，小儿以炒豆、猪肉同食，必壅气致死，十有八九。十岁以上，则无害也。服萆麻子者，忌炒豆，犯之胀满致死。服厚朴者亦忌之，最能动气故也。', NULL, NULL, NULL, '生大豆', NULL, '1、生大豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628220914491472, '2DD24ED310753440BAAEDE34507061FB', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 14:17:29', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7605, 432, 400107603, '    味咸、酸，冷利。主除热，止烦满，杀百药、热汤及火毒。\n\n     疏：按酱之品不一，惟豆酱陈久者入药。其味咸酸冷利，故主除热，止烦满，及汤火伤毒也。能杀一切鱼肉菜蔬蕈毒。本经云：杀百药毒者，误也。圣人不得其酱不食。朱子云：食肉用酱，各有所宜。玩一宜字，则不宜者必有伤害于人，非特悦口而已。如食蟹用橙酱，或姜酱，煮鱼用茱萸酱，取其能杀毒之义耳。又有榆仁酱，味辛美，杀诸虫，利大小便，心腹恶气。芜荑酱主疗相同。茱萸酱作法不用面、豆、盐，只以河水，量茱萸多少，稍稍加石灰掺入拌匀，瓮藏。杀一切鱼腥毒。用时洗去石灰，擂烂，烹水入之良。\n', NULL, NULL, NULL, '酱', NULL, '3、酱', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628257421762630, 'FFA971DEF81D76B941FFD998FFA8711F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 16:46:02', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7606, 432, 400107602, '   味苦。主温中，令人多热，大便坚。\n\n    疏：稻米，即今之糯米也。禀土中之阳气，其味应甘，气应温无毒。造酒必用之者，以其性近于热也。为补脾胃，益肺气之谷。脾胃得补，则中自温，大便亦坚实。温能养气，气充则身自多热。大抵脾肺虚寒者宜之，为其能益气温中也。故又有止泄利，缩小便，收自汗，发痘疮等用。\n\n【主治参与】\n《松篁经验方》久泄食减：以糯米一升，水浸一宿，沥干，炒熟磨筛，入怀山药一两，每日清晨用半盏，入白砂糖二匙，胡椒末少许，以滚汤调食。大有滋补。久服更能令人精暖有子。\n\n《医方大成》癫犬咬伤：糯米一合，斑猫七枚，同炒熬黄去之；再入七枚，再炒黄去之；又入七枚，待米出烟，去猫，为末。水调服之，小便利下，佳。亦可油调外傅。\n\n又方，虚劳不足：糯米入猪肚内，蒸熟，日食。\n\n【简误】\n糯米，孟诜云：发风动气，久食令人多睡。藏器云：久食令人身软；妊娠杂肉食之，令子不利。萧炳云：拥诸经络气，使四肢不收，发风昏昏。陈士良云：久食发心悸，及痈疽疮疖中痛，合酒食之醉难醒。然愚意观之，其为害未必如此之甚。盖天生五谷以食人，皆禀土中冲和之气，可常御而无害者。第糯米气温，性粘滞，惟不利于上焦有痰热，及脾病不能转运，小儿难于克化者，余皆无害。诸家之言，不可尽信也。', NULL, NULL, NULL, '稻米', NULL, '2、稻米', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628257421762631, '562474429209CC08B92AD638F059DB8D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 16:46:02', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7607, 432, 400107601, '    味酸，温，无毒。主消痈肿，散水气，杀邪毒。（一名苦酒。）\n\n     疏：醋惟米造者入药，得温热之气，故从木化，其味酸，气温，无毒。酸入肝，肝主血，血逆热壅则生痈肿。酸能敛壅热，温能行逆血，故主消痈肿。其治产后血晕，癥块血积，亦此意耳。散水气者，水性泛滥，得收敛而宁谧也。杀邪毒者，酸苦涌泻，能吐出一切邪气毒物也。日华子主下气除烦，妇人心痛血气，并产后，及伤损金疮出血迷闷，杀一切鱼肉菜毒。取其酸收，而又有散瘀解毒之功也。故外科傅药中多资用。\n\n【主治参与】\n仲景方：少阴病，脉微细，但欲寐，咽中伤，生疮，不能言语，声不出者，苦酒汤主之。用半夏十四枚，鸡子一枚去黄，以苦酒、半夏着鸡子壳中，置刀环中，安火上，令三沸，去滓，少少含咽之。不瘥，更用三剂。\n\n仲景《金匮》方：黄耆芍药苦酒汤，治黄汗，汗出沾衣，正黄如药汁。因汗出时入水中浴，水从汗孔入得之。用黄耆五两，芍药三两，桂枝三两，以苦酒一斗，水七升，相和，煮取三升，温服一升。当心烦，服至六七日乃解。\n\n《衍义》云：产妇房中，常以火炭沃醋气为佳，酸气能敛血，使下也。\n\n孟诜《食疗》：青木香，以醋磨汁服，止卒心痛。\n\n浸黄檗，含之，治口疮。\n\n《千金方》身体卒肿：醋和蚯蚓屎傅之。\n\n又方，舌肿不消：以酢和釜底墨，厚傅舌之上下，脱则更傅，须臾即消。\n\n又方汤火伤灼，即以酸酢淋洗，并以酢泥涂之良，亦无瘢痕。喉痹咽痛，以酽醋探吐之。\n\n【简误】\n《经》曰：酸走筋，筋病毋多食酸。凡筋挛、偏痹、手足屈伸不便，皆忌之。又曰：味过于酸，肝气以津，脾气乃绝。多食酸则肉皱而唇揭，言能助肝贼脾。凡脾病者，亦不宜过食。', NULL, NULL, NULL, '苦酒,醋', NULL, '1、苦酒,醋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628257421762632, '0AA44A35AD92775AD6C19FC0E49E045C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 16:46:02', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7608, 433, 400107708, '     味苦，平，无毒。主安中利人，可久食。\n\n     疏：苜蓿，草也，嫩时可食，处处田野中有之，陕陇人亦有种者。本经云苦平无毒。主安中利人。可久食。然性颇凉，多食动冷气，不益人。根苦寒，主热病烦满，目黄赤，小便黄，酒疸。捣汁一升服，令人吐利，即愈。其性苦寒，大能泄湿热故耳。以其叶煎汁多服，专治酒疸大效。\n', NULL, NULL, NULL, '苜蓿', NULL, '8、苜蓿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134918, '8E7592CB6DEB79E169503C0C69A2F011', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7609, 433, 400107707, '     味苦，寒，无毒。主五藏邪气，厌（伏也）谷胃痹，肠澼，渴热中疾，恶疮。久服安心益气，聪察少卧，轻身耐老，耐饥寒，高气不老。\n\n     疏：苦菜与苦苣、苦荬一物，而形稍异，功用则相同也。禀天地之阴气，故其味苦气寒，无毒。入心、脾、胃三经。其主五脏邪气者，邪热客于心也。胃痹、渴热中疾者，热在胃也。肠澼者，热在大肠也。恶疮者，热瘀伤血肉也。苦寒总除诸热，故主之也。热去则神自清，故久服安心益气，聪察少卧也。轻身耐老，耐饥寒，高气不老者，总言其热退阴生，安心益气之极功也。\n\n【主治参与】\n寇宗奭《衍义》：治疔疮，以苦苣捣汁傅之，殊验。青苗叶阴干，以备冬月需用，为末，水调傅之。\n\n唐瑶《经验方》对口恶疮：野苦苣，擂汁一钟，入姜汁一匙，和酒服，以渣傅，一二次即愈。\n\n《肘后方》中沙虱毒：沙虱在水中，人澡浴则着人身，钻入皮里。初得皮上正赤，如小豆、黍、粟，摩之痛如刺，三日后发寒热，发疮毒，若入骨杀人，岭南多此。即以茅叶刮去，以苦菜汁涂之，佳。\n\n【简误】\n脾胃虚寒者忌之', NULL, NULL, NULL, '苦菜,苦苣,苦荬', NULL, '7、苦菜,苦苣,苦荬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134919, '2200B21F0C735C10A8E27C586DBC2905', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7610, 433, 400107706, '     根味辛、甘，温，无毒。散服及炮煮服食，大下气，消谷，去痰癖。肥健人。生捣汁服，主消渴，试大有验。\n\n     疏：莱菔根禀土金之气以生。本经味辛甘，气温无毒。孟诜云：性冷。大明云：平。详其功用，应是生者味辛性冷，熟者味甘温平。故本经下气，消谷，去痰癖，肥健人，及温中补不足，宽胸膈，利大小便，化痰消导者，煮熟之用也。止消渴，制面毒，行风气，去邪热气，治肺痿吐血，肺热痰嗽，下痢者，生食之用也。大抵入手足太阴、手足阳明经。故所主皆脾、肺、肠、胃之病。\n\n      子：味辛过于根。生研汁服，吐风痰。同醋研，消肿毒。炒熟，下气定喘，消食除胀，止气痛。以其性辛甚，故升降之功亦烈于根也。朱震亨云：莱菔子治痰，有推墙倒壁之功。是矣！\n\n【主治参与】\n《医学集成》（鼻勾）喘痰促，遇厚味即发者：用蔔子淘净，蒸熟晒研，姜汁浸，蒸饼丸绿豆大。每服三十丸，以口津咽下，日三服。治年远脾泄，百药不效。单煮白莱菔，终日啖之不辍，必瘥。\n\n【简误】\n莱菔根叶皆可食，生熟皆宜，乃蔬中之至贱，而能止渴充饥者。歉岁，农人种之最有利益。但性专下气，复能耗血，故多食则髭发早白。服地黄、何首乌者，不可食。\n子，消痰下气更速，凡虚弱人忌之。', NULL, NULL, NULL, '莱菔', NULL, '6、莱菔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134920, 'DE927B9FF729CD12F5D057DE96468386', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7611, 433, 400107705, '     味辛，温，无毒。归鼻。主除肾邪气，利九窍，明耳目，安中。久食温中。\n\n     疏：芥所禀与白芥同。今人以醋、椒同芥心作辣齑食之，则脑额酸楚，泪涕俱出，即归鼻利窍，明耳目之验也。辛温能利气消痰，开胃辟寒，故主安中，及久食温中也。其主除肾邪气者，辛能润肾，温能暖水脏故也。\n\n子：功用与白芥子相同，力稍不逮。\n\n【主治参与】\n     治肺痈，用百年芥菜卤，久窨地中者，饮数匙立效。其义以芥菜辛温，得盐水久窨之气，变为辛寒。辛寒能散痰热，芥菜主通肺气，所以治肺痈，真良法也。\n\n【简误】\n   与白芥子同。其主利九窍，明耳目者，盖言辛散走窜，豁痰引涎，暂用一时，使邪去而正自复，非谓其真能利窍明耳目也。用者详之。', NULL, NULL, NULL, '芥', NULL, '5、芥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134921, '0DB22E18CEC014A24EE26E2C5024120C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7612, 433, 400107704, '     味辛，温，无毒。主冷气。色白，甚辛美。\n\n      子：主射工，及疰气，上气，发汗，胸膈痰冷，面黄。\n\n      疏：芥禀火金之气以生，而白芥则又得金气之胜，故味辛气温无毒。辛温入肺而发散，故有温中除冷，发汗辟邪，豁痰利气之功。朱震亨云：痰在胁下及皮里膜外，非白芥子莫能达。古方控涎丹用之，正此义尔。\n\n【主治参与】\n       韩懋《医通》云：凡老人，苦于痰气喘嗽，胸满懒食，不可妄投燥利之药，反耗真气。因有人求治其亲，遂制三子养亲汤治之，随试随效。用白芥子、紫苏子、白莱菔子，各微炒研破，看所主为君，每剂不过三四钱，用绢袋盛，入汤煮饮之。勿煎大过，则味苦辣。若大便素实者，入蜜一匙。冬月加姜一片。\n\n苏恭：主疰气发无常处，及射工毒，以芥子丸服之。或捣末醋和涂之，随手有验。\n\n【简误】\n       白芥子，味极辛，气温，能搜剔内外痰结，及胸膈寒痰，冷涎壅塞者殊效。然而肺经有热，与夫阴火虚炎，咳嗽生痰者，法在所忌。其茎叶煮食，动风动气，有疮疡痔疾便血者，咸忌之。', NULL, NULL, NULL, '白芥', NULL, '4、白芥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134922, '990935EABB2DA6BA1B6D2F5C41F6E1AD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7613, 433, 400107703, '      味甘，微寒。主除小腹水胀，利小便，止渴。\n\n      疏：白冬瓜内禀阴土之气，外受霜露之侵，故其味甘，气微寒，而性冷利，无毒。水属阴，瓜性亦属阴，气类相从，故能利小便，除小腹水胀也。甘寒解胃中之热，故又能止渴也。弘景：止消渴烦闷，解毒，孟诜：益气耐老，除心胸满，去头面热。大明：消热毒痈肿，切片摩疿子。苏颂：利大小肠，压丹石毒。皆得其旨者也。\n\n【主治参与】\n孟诜《食疗》积热消渴：白冬瓜去皮，每食后嚼二三两，五七度良。\n\n《古今录验》：产后痢渴，久病津液枯竭，四肢浮肿，口舌干燥，用冬瓜一枚，黄土泥厚五寸煨熟，绞汁饮良。亦治伤寒痢渴。\n\n《杨氏家藏方》：十种水气浮肿喘满，用大冬瓜一枚，切盖去瓤，以赤小豆填满，盖合签定，以纸筋泥固济，日干。用糯糠两大箩，入瓜在内，煨至火尽，取出切片，同赤豆焙干为末，水糊丸梧子大。每服七十丸，煎冬瓜子汤下，日三服，小便利为度。\n\n冬瓜仁，味甘寒，能开胃醒脾。同橘红、石斛、竹茹、枇杷叶、白芍药、芦根汁、人参、白茯苓，治胃虚呕吐。\n\n同人参、茯神、竹沥、白茯苓、黄耆、甘草、白芍药、酸枣仁，治小儿慢脾风。\n\n【简误】\n       冬瓜性冷利，凡脏腑有热者宜之。若虚寒肾冷，久病滑泄者，不得食。未经霜者，不宜多食。九月后食之乃佳。', NULL, NULL, NULL, '白冬瓜', NULL, '3、白冬瓜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134923, '1B7D7D6823251CEFECB05C1B0D4475C0', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7614, 433, 400107702, '      味苦，寒，有毒。主大水，身面四肢浮肿，下水杀蛊毒，咳逆上气，及食诸果，病在胸腹中，皆吐下之。去鼻中息肉。疗黄疸。\n\n      疏：瓜蒂感时令之火热，禀地中之伏阴，故其味苦，气寒有小毒。气薄味厚，浮而升，阴多于阳，酸苦涌泄为阴故也。入手太阴、足阳明、足太阴经。其主大水，身面四肢浮肿，黄疸者，皆脾胃虚，水气湿热乘虚而客之也。苦以涌泄，使水湿之气外散，故能主之。\n\n    《经》曰：在高者，因而越之。病在胸膈，则气不得归元而为咳逆上气，吐出胸中之邪，则气自顺，咳逆止矣。杀蛊毒者，亦取吐出之义。去鼻中息肉者，以其苦寒能除肺家之热也。日华子：治脑寒热齆，眼昏吐痰。好古：得麝香、细辛，治鼻不闻香臭，及吐风热痰涎，风眩头痛，癫痫，喉痹，头面有湿气，伤寒客水胸中，伤食胀满，下部无脉等证，皆借其宣发涌泄，引涎追泪之功耳。\n\n【主治参与】\n仲景《伤寒论》：病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞硬，气上冲咽喉，不得息者，此胸中有寒也。当吐之，宜瓜蒂散。用瓜蒂、赤小豆，等分为散，取一钱，以香豉一合，用热汤七合，煮作稀糜，去滓，取汁和散顿服之。不吐，少少加，得快吐乃止。\n\n湿家病身上疼痛，发热面黄而喘，头痛鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故鼻塞，内药鼻中则愈，瓜蒂散主之。\n\n太阳中暍，身热疼重，而脉微弱，此因夏月伤冷水，水行皮中所致。宜吐之，瓜蒂散。\n\n病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下利日十余行，其脉反微，寸口脉微滑，此可吐之，吐之则利自止。\n\n宿食在上脘者，当吐之。\n\n病人手足厥冷，脉乍结，以客气在胸中，心下满而烦，欲食不能食者，当吐之。\n\n懊憹烦躁不得眠，未经汗下者，谓之实烦，当吐之。已上悉用瓜蒂散。皆仲景法。\n\n东垣曰：《难经》云上部有脉，下部无脉，其人当吐，不吐者死。此饮食内伤，填塞胸中，食伤太阴，则风木生发之气伏于下，宜瓜蒂散吐之。《内经》所谓木郁达之也。吐去上焦有形之物，则木得舒畅，天地交而万物通矣。诸亡血家，不可与瓜蒂散。\n\n寇氏《衍义》：风涎暴作，气塞倒仆，用瓜蒂末二钱，腻粉一钱匕，以水半合调灌，良久涎自出。不出，含沙糖一块，下咽即涎出也。\n\n《千金翼》热病发黄：瓜蒂为末，以大豆许吹鼻中，取出黄水乃愈。\n\n孟诜《食疗》阴黄黄疸：取瓜蒂、丁香、赤小豆各七枚，为末。吹豆许鼻中，少时黄水流出，隔一日用，瘥乃止。并治身面浮肿。\n\n《活人书》湿家头痛：瓜蒂末一字，㗜入鼻中，口含冷水，取出黄水愈。\n\n《圣惠方》鼻中息肉：瓜蒂末，白矾末，各半钱，锦裹塞之。或以猪脂和挺子塞之，日一换。\n\n【简误】\n        瓜蒂极苦而性上涌，能损胃伤血，耗气损神，凡胸中无寒，胃家无食，皮中无水，头面无湿，及胃虚气弱，诸亡血，诸产后，似中风倒仆，心虚有热，癫痫，女劳、谷疸，元气尪羸，脾虚浮肿，切勿误用。误用则为害非细，伤生不浅。戒之！慎之！', NULL, NULL, NULL, '瓜蒂', NULL, '2、瓜蒂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134924, 'B27633976AA178497A317178FDE84CA5', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7615, 433, 400107701, '    味辛，温（一云微寒），微毒。消谷，治五藏，补不足，利大小肠，通小腹气，拔四肢热，止头痛。疗沙疹、豌豆疮不出，作酒喷之，立出，通心窍。\n\n    疏：胡荽禀金气多，火气少，故味辛香，气温微毒。入足太阴、阳明经。辛香走窜而入脾，故主消谷，利大小肠，通少腹气。脾胃为邪热所干，则头痛四肢热。辛温发散二经之邪，则头痛四肢热自拔。沙疹、痘疮出不快者，外为风寒所侵，或秽气所触也。辛温祛风寒，香窜辟秽气，则腠理通畅而沙疹痘疮皆出矣。通心窍，治五脏补不足者，总言其辛香内通心脾，外达肠胃，除一切不正之气，则真气安和，斯有补益之道耳。\n\n子：亦能发痘疹，杀鱼腥。\n\n【主治参与】\n《经验后方》疹痘出不快：同胡荽二两切，以酒二大盏，煎沸沃之，以物盖定，勿令泄气。候冷去滓，微微含喷，从项背至足令遍，勿噀头面。\n\n《子母秘录》肛门脱出：胡荽一升切，烧烟熏之，即入。\n\n《外台秘要》牙齿疼痛：胡荽子五升，水五升，煮取一升，含嗽。\n\n【简误】\n      胡荽，辛香发散，气虚人不宜食。疹痘出不快，非风寒外侵及秽恶之气触犯者，不宜用。孟诜云：多食损人精神。华佗云：胡臭、口臭、䘌齿、脚气，皆不可食，令病加甚。陈藏器云：久食令人多忘，发腋臭。根发痼疾。凡服一切补药，及药中有白术牡丹者，咸忌之。', NULL, NULL, NULL, '胡荽', NULL, '1、胡荽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628261021134925, '9C5358A77D397D87944A17E41B1ABE80', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:00:40', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7616, 434, 400107802, '     味辛、微酸，温，无毒。归心，安五藏，除胃中热，利病人，可久食。\n\n      疏：韭禀春初之气而生，而兼得金水木之性，故其味辛，微酸，气温而无毒。生则辛而行血，熟则甘而补中、益肝、散滞、导瘀，是其性也。以其微酸，故入肝而主血分。辛温能散结，凡血之凝滞者，皆能行之，是血中行气药也。心主血，专理血分，故曰归心。五脏之结滞去，则气血条畅而自安矣。胃中热，乃胃中有瘀滞而发热也，瘀血行，热自除矣。病人之气抑郁者多，凡人气血，惟利通和，韭性行而能补，故可久食。\n\n     韭子：味辛，甘，温，无毒。主梦中泄精，溺血。盖韭乃入足厥阴、少阴经。肾主闭藏，肝主疏泄。《素问》云：足厥阴病则遗尿。思想无穷，入房太甚，发为筋痿，及为白淫。韭子入厥阴而甘温，补肝及命门之不足，故主泄精溺血。\n\n【主治参与】\n有一贫叟，病噎膈，食入即吐，胸中刺痛。或令取韭汁，入盐、梅、卤汁少许，细呷，得入渐加，忽吐稠涎数升而愈。此亦仲景治胸痹痛用薤白，皆取辛温能散胃脘痰饮恶血之义也。\n\n一人腊月饮酒三杯，自后食必屈曲，下膈硬涩微痛，右脉甚涩，关脉沉。此污血在胃脘之口，气因郁而成痰，隘塞食道也。以韭汁半盏，细细冷呷，尽半斤而愈。\n\n《食疗本草》：胸痹急痛如锥刺，不得俯仰，自汗出，或彻背上，不治或至死。取生韭及根五斤，洗捣汁，服之瘥。\n\n《金匮要略》风忤邪恶：韭根一把，乌梅十四个，吴茱萸炒半升，水一斗，煮之，仍以病人栉内入，煮三沸。栉浮者生，沉者死。煮至三升，分三服。\n\n《千金方》：刺伤中水肿痛，煮韭热搨之。\n\n【简误】\n韭性辛温通利，虽曰补益，然多食能令人神昏，最为养性所忌。胃气虚而有热者勿服。韭黄未出于土者勿服，食之滞气，以其气尚抑郁未申故也。花食之亦动风。', NULL, NULL, NULL, '韭', NULL, '2、韭', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628264597422150, '688E00DCBDFF17C97B679D0F5E0C16F3', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:15:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7617, 434, 400107801, '       辛，平。可作汤，主伤寒寒热，出汗，中风面目肿，伤寒骨肉痛，喉痹不通，安胎，归目，除肝邪气，安中利五藏，益目睛，杀百药毒。\n\n      葱实：味辛，温，无毒。主明目，补中不足。\n\n      葱根：主伤寒头痛。\n\n      葱汁：平，温。主溺血，解藜芦毒。（弘景云：葱有寒热，白冷青热。伤寒汤中不用青也。）\n\n     疏：葱禀天之阳气，得地之金味，中空象肺，其味辛平，平即凉也，而性无毒。气厚味薄，升也，阳也。入手太阴、足厥阴、足阳明经。辛能发散，能解肌，能通上下阳气，故外来怫郁诸证，悉皆主之。伤寒寒热，邪气并也。中风面目肿，风热郁也。伤寒骨肉痛，邪始中也。喉痹不通，君相二火上乘于肺也。辛凉发散，得汗则火自散，而喉痹通也。肝开窍于目。散肝中邪热，故云归目、除肝邪气。邪气散则正气通，血自和调，而有安胎、安中、利五脏之功矣。其曰益目睛、杀百药毒者，则是辛润利窍而兼解散通气之力也。\n\n【主治参与】\n《活人书》治伤寒头痛如破：连须葱白半斤，生姜二两，水煎温服。\n\n《济生秘览》：时疾头痛发热者，以连根葱白二十根，和米煮粥，入醋少许，热食取汗即解。数种伤寒一二日，初起不能分别者，亦用之取汗。\n\n风湿身痛：用生葱捣烂，入香油数点，水煎，调川芎、郁金末一钱服，取吐。\n\n《杨氏产乳》：六月孕动，困笃难救者，葱白一大握，水三升，煎一升，去滓顿服。\n\n《深师方》：胎动下血，病痛抢心，用葱白煮浓汁饮之，未死即安，已死即出。未效再服。一方加川芎。\n\n阴毒腹痛厥逆，唇青，卵缩，六脉欲绝者，用葱一束，去根及青，留白二寸，烘热，安脐上，以熨斗火熨之。葱坏则易，良久热气透入，手足温，有汗即瘥。乃服四逆汤。若熨而手足不温，不可治。\n\n华佗救卒病方：脱阳危证，凡人大吐大泄之后，四肢厥冷，不省人事，或与女子交后少腹坚痛，外肾搐缩，冷汗出，厥逆，须臾不救。先以葱白炒热熨脐，后以葱白三七茎，捣烂，用酒煮灌之，阳气即回。加人参为要。\n\n《本事方》小便闭胀，不治杀人：葱白三斤，剉、炒，帕盛二个，更互熨小腹，气透即通。\n\n刘禹锡《传信方》打扑损见血，取葱新折者，煻火煨热，剥皮，其间有涕，便将罨损处，仍多煨，续续易热者，立愈。\n\n张氏《经验方》：金疮折伤出血，用葱白连叶煨热，或锅烙炒热，捣烂傅之，冷即再易，神验。\n\n【简误】\n病人表虚易汗者，勿食。病已得汗，勿再进。', NULL, NULL, NULL, '葱白', NULL, '1、葱白', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628264597422151, 'F2855282644D8B31FD6649B7B40B4254', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:15:14', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7618, 435, 400107904, '       味辛，微温。主蠼螋溺疮。多食令人气喘。（俗呼鱼腥草。）\n\n        疏：蕺，生于下湿之地，得阴中之阳，故其味辛，气温。入手太阴经。能治痰热蕴肺，发为肺痈吐脓血之要药。辛温主散，故能治蠼螋溺疮。肺主气，辛温能散气，故多食令人气喘。肺与大肠为表里，大肠湿热盛则为痔疮。得辛温之气，则大肠清宁，故又为痔疮必须之药。\n\n【主治参与】\n单用捣汁，入年久芥菜卤饮之，治肺痈有神。\n\n《救急方》：痔疮肿痛。鱼腥草一握，煎汤熏洗，仍以滓傅，即愈。\n\n【简误】\n蕺，只能消肺痈，治痔疮，余非所长。况多食令人气喘，发虚弱，损阳气，发脚气等害。慎之！慎之！', NULL, NULL, NULL, '鱼腥草,蕺', NULL, '4、鱼腥草,蕺', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628266279395398, 'A4CC4B0113281640260ED3398A4381AD', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:22:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7619, 435, 400107903, '     味甘，寒。久冷人不可多食，损人动气，发疮及痼疾。\n\n      根及枯茎叶：主冻脚疮，可煮作汤渍之，良。\n\n      疏：茄，内禀地中一阴之气，外受南方热火之阳，故其花实皆紫。本经虽云甘寒，必是湿中有火，使非湿热，则不能动气，发疮及痼疾也。湿胜则久冷人多食有损，热胜故能主冻脚疮也。孟诜云：主寒热五脏劳。大明：治温疾，传尸劳气。皆非正治，惟肿毒家用之为当耳。\n\n【主治参与】\n《灵苑方》肠风下血：经霜茄，连蒂烧存性，为末。每日空心温酒服二钱匕。\n\n丹溪方：治乳头裂，用茄子老黄者，烧灰傅之。\n\n鲜茄蒂、鲜何首乌，等分煮饮，治对口疮有神。\n\n茄秆烧灰淋汁，和入桑硇、碱等药，诸痈肿疔疮有效。\n\n【简误】\n茄，观本经所说，止是损人，并无利益，后人虽有处治之法，然终与本经相失。凡有痼疾及虚冷人，切不可食。近世为茹菜中常用之物，尊生者当慎之。', NULL, NULL, NULL, '茄子', NULL, '3、茄子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628266279395399, 'DFB959151301B4A6BC714964AD470073', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:22:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7620, 435, 400107902, '      主目盲白翳，利大小便，去寒热，杀诸虫，止渴，破癥结，痈疮。服之长年不白。和梳垢封疔疮。又烧为灰，和多年醋滓，先灸疔肿，以封之，即根出。生捣绞汁服，当下恶物，去白虫。煎为膏，涂白秃。又主三十六种风结疮，以一釜煮，澄清，内腊三两，重煎成膏，涂疮上，亦服之。\n\n       疏：马齿苋禀天之阴寒，兼得地中之金气以生。故叶节间有水银，以其得金气多也。味应辛苦，气寒无毒。《经》云：荣气不从，逆于肉里，乃生痈肿。《原病式》云：诸痛痒疮疡，皆属心火。辛寒能凉血散热，故主癥结，痈疮疔肿，白秃，及三十六种风结疮。捣敷则肿散疔根拔，绞汁服则恶物当下，内外施之皆得也。辛寒通利，故寒热去，大小便利也。苦能杀虫，寒能除热，故主杀诸虫，去寸白，止渴。辛寒能散肺家之热，故主目盲白翳也。长年不白，总言其凉血、益血，病去身轻之功耳。方士多采取用，以其亦有代砂结汞之能也。\n\n【主治参与】\n崔元亮：治赤白带下，不问老幼孕妇悉可服。取马齿苋，捣绞汁三大合，和鸡子白一枚，微温顿服之。不过再作则愈。\n\n又方：疗多年恶疮，百方不瘥，或痛焮走不已者。并烂捣马齿苋敷上，不过三两遍，即愈。\n\n《广利方》小儿火丹热如火，绕脐即损人：马齿苋捣涂之。\n\n崔元亮方：疔疮肿毒，马齿苋二分，石灰三分，为末，鸡子白和傅之。\n\n【简误】\n马齿苋辛寒滑利，凡脾胃虚寒、肠滑作泄者，勿用煎饵。方中不得与鳖甲同入，令化作小鳖伤人也。', NULL, NULL, NULL, '马齿苋', NULL, '2、马齿苋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628266279395400, 'ECF421CC27946879AE0249BC24090668', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:22:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7621, 435, 400107901, '     味辛，温，有毒。主散痈肿，䘌疮，除风邪，杀毒气。独子者亦佳。归五脏，久食伤人，损目明。\n\n      疏：葫，大蒜也。禀火金之气以生。故其味辛气温。辛温太甚，故其性有毒，熏臭异常，不宜多食。入足阳明、太阴、厥阴经。辛温能辟恶散邪，故主除风邪，杀毒气，及外治散痈肿䘌疮也。辛温走窜，无处不到，故主归五脏。脾胃之气最喜芳香，熏臭损神耗气，故久食则伤人。肝开窍于目，目得血而能视，辛温太过，则血耗而目损矣。总之其功长于通达走窍，去寒湿，辟邪恶，散痈肿，化积聚，暖脾胃，行诸气。故苏恭主下气消谷，化肉。藏器主风湿，破冷气，烂痃癖，伏邪恶，宣通温补。日华子主健脾胃，治肾气，止霍乱转筋腹痛，除邪祟，解温疫等用也。\n\n【主治参与】\n《外台秘要》：关格胀满，大小便不通，独头蒜烧熟，去皮绵裹，纳下部，气立通。\n\n又方：治金疮中风，角弓反张。取蒜一大升，破去心，无灰酒四升，煮令极烂，并滓服一大升，须臾得汗则瘥。\n\n《简要济众》治鼻血不止，服药不应，用蒜一枚，去皮，细研如泥，摊一饼子如钱大，厚一豆许。左鼻血出，贴左脚心；右鼻血出，贴右脚心。两鼻俱出，皆贴之，立瘥。血止，急以温水洗脚心。\n\n《外科精要》背疮灸法：凡觉背上肿硬疼痛，以湿纸贴寻疮头。用大蒜十颗，淡豆豉半合，乳香一钱，细研匀，随疮头大小，用竹片作圈圈定，填药于内，二分厚，著艾灸之。痛灸至痒，痒灸至痛，以百壮为率，效。\n《永类钤方》干湿霍乱转筋：用大蒜捣涂足心，立愈。\n\n《普济方》寒疟冷痢：端午日以独头蒜十个，黄丹二钱，捣丸梧子大。每服九丸，长流水下，妙。\n\n《衍义》暴下血病：用葫五七枚，去皮研膏，入豆豉，捣丸梧子大。每米饮下五六十丸，无不愈者。\n\n华佗行道，见车载一人，病咽塞食不下，呻吟。佗视曰：饼店家蒜齑、大酢三升，饮之当自痊。果吐大蛇一枚而愈。\n\n【简误】\n蒜性温，属火，气味臭烈。凡肺胃有热，肝肾有火，气虚血弱之人，切勿沾唇。虽有暖脾胃、祛寒湿之功，亦宜暂用，切勿过施。过则生痰动火，伤神散气，损目耗血。切戒！切戒！', NULL, NULL, NULL, '蒜,葫', NULL, '1、蒜,葫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628266279395401, '9AA23C76DABD9A1015E6E18FFC8C3509', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-30 17:22:04', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7622, 436, 400108033, '      味甘，温，无毒。\n主消食，活血，健脾，燥胃。\n治赤白痢下水谷。\n\n疏：红曲，以白粳米杂曲母蒸罨为之，亦奇术也。\n人之水谷入于胃，受中焦湿热熏蒸，精气变化而赤为血。\n红曲以白米饭受湿热郁蒸而变为红，皆造化自然之微妙也。\n故红曲治脾胃荣血之功，有同气相求之理。\n消食健脾胃，与神曲相同。\n而活血和伤，惟红曲为能，故治血痢，尤为要药。\n\n【主治参与】\n得番降香、通草、鲮鲤甲、没药，治上部内伤，胸膈作痛。\n\n或怒伤吐血，和童便服，有神效。\n\n同黄连、白扁豆、莲肉、黄芩、白芍药、升麻、干葛、乌梅、甘草、滑石、橘红，治滞下有神。\n\n同续断、番降香、延胡索、当归、通草、红花、牛膝、没药、乳香。\n\n治内伤血瘀作痛。\n\n同泽兰、牛膝、地黄、续断、蒲黄、赤芍药，治产后恶露不尽，腹中痛。\n\n《丹溪心法》湿热泄痢，青六丸：用六一散加炒红曲五钱，为末，蒸饼和丸梧子大。\n\n每六七十丸白汤下，日三服。\n\n《摘玄方》心腹作痛：赤曲、香附、乳香，等分为末，酒服。\n\n【简误】\n性能消导，无积滞者勿用。\n又善破血，无瘀血者禁使。\n', NULL, NULL, NULL, '红曲', NULL, '33、红曲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549510, '79802D15DCFA012547AD8E684B16398C', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7623, 436, 400108032, '      味甘，微温。\n主温中下气，止呃逆。\n昔有人病后患呃逆不止，声闻邻家。\n或令取刀豆子烧存性，为末。\n白汤调服二钱即止。\n此即下气归元之验也。', NULL, NULL, NULL, '刀豆子', NULL, '32、刀豆子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549511, 'A205D9D7EED4DB1291911D7357F22494', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', 1, 'admin', '2025-01-15 09:14:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7624, 436, 400108031, '      味甘、咸，平，无毒。\n补肾健胃，与诸疾无禁，可常食之。\n昔卢廉夫教人补肾气，每日空心煮豇豆，入盐少许食之，甚效。', NULL, NULL, NULL, '豇豆', NULL, '31、豇豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549512, '841725603441719AFE681C3A1CA780B8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', 1, 'admin', '2025-01-15 09:13:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7625, 436, 400108030, '     味甘，微辛，无毒。\n能厚肠胃，和脏腑。\n万表《积善堂方》言：一女子误吞针入腹，诸医不能治，一人教令煮蚕豆同韭菜食之，针自大便同出。\n今人有误吞金银物者，用之皆有效。\n实救急之良方也。', NULL, NULL, NULL, '蚕豆', NULL, '30、蚕豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549513, '4A700FBCF6E502B98D7F63CB750CD1B7', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7626, 436, 400108029, '     即今之小豌豆也。\n一名胡豆。\n陈藏器云：煮食治消渴。\n孙思邈治寒热热中，吐逆，泄澼，及胀满利小便。\n应是甘平无毒，入脾胃，清利除热之物也。\n又能治痈肿痘毒。\n牛都御史秘传四圣丹，治小儿痘中有疔，或紫黑而大，或黑坏而臭，或中有紫线，此证十死八九，惟此方点之最妙。\n用豌豆四十九粒烧存性，头发灰三分，真珠十四粒研为末，以油胭脂同杵成膏，先以簪挑疔破，咂去恶血，以少许点之，即时变红活色。\n《千金》、《外台》洗面澡头方：盛用毕豆面，取其白腻去䵟（黑曾），令人光泽也。', NULL, NULL, NULL, '豌豆,胡豆', NULL, '29、豌豆,胡豆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549514, 'D980426A95833E2E494F1A9A276A46C6', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', 1, 'admin', '2025-01-15 09:13:32');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7627, 436, 400108028, '       甘，凉，无毒。\n主解诸热，益气，解酒食诸毒。\n治发背痈疮肿，及汤火伤灼。\n\n     疏：绿豆粉，所禀气味与绿豆同。\n故能解诸热，及酒食毒，汤火伤灼也。\n发背痈疽疮肿，皆热毒所致，甘寒解阳明之热，则毒气不至犯胃而呕恶，肠胃清凉而诸肿散矣。\n热伤气，除热故能益气也。\n\n【主治参与】\n李嗣立《外科精要》护心散，又名内托散、乳香万全散：凡有疽疾，一日至十三日内，宜连进十余服，方免变证，使毒气出外。\n\n服之稍迟，毒气内攻，渐生呕吐，或鼻生疮菌，不食即危矣。\n\n四五日亦宜间服之。\n\n用真绿豆粉一两，乳香半两，灯心同研和匀，以生甘草煎浓汤，调下一钱，时时呷之。\n\n若毒气冲心有呕逆之证，大宜服此。\n\n盖绿豆压热下气，消肿解毒，乳香消诸痈肿毒。\n\n服至一两，则香彻疮孔中，真圣药也。\n\n一方有丹砂二钱半。\n\n《卫生易简》解砒石毒：绿豆、寒水石等分，以蓝汁调服三五钱。\n\n又方，夏月痱疮：绿豆粉二两，滑石一两，和匀扑之。\n\n一方加蛤粉。\n《生生编》杖疮疼痛：绿豆粉炒研，以鸡子白和涂之，妙。\n\n《澹寮方》打扑伤损：用绿豆粉炒紫色，新汲水调傅，以杉木皮缚定，其效如神。\n\n绿豆皮：能解热毒，退目翳。\n\n《直指方》通神散：治斑痘后目生翳，用绿豆皮、甘菊花、谷精草等分，为末。\n\n每服一钱，以干柿饼一枚，粟米泔一盏，同煮干。\n\n食柿，日三服。\n浅者五七日见效，远者半月见效。\n\n【简误】\n绿豆粉性凉，脾胃虚寒易泄者，勿多食。', NULL, NULL, NULL, '绿豆粉', NULL, '28、绿豆粉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549515, 'B80CC1BB9F35FD5CF76E634231571A62', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7628, 436, 400108027, '    罂粟花之津液也。\n\n     罂粟结青苞时，午后以大针刺其外面青皮，勿损里面硬皮，或三五处，次早津出，以竹刀刮取，入磁器，阴干用之。\n\n其气味与粟壳相同，而此则止痢之功尤胜。\n\n故小儿痘疮行浆时，泄泻不止，用五厘至一分，未有不愈，他药莫逮也。\n', NULL, NULL, NULL, '阿芙蓉', NULL, '27、阿芙蓉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549516, 'C6D65F4B0BF3BB859CBD30931EEBEC42', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7629, 436, 400108026, '      味甘，平，无毒。\n主丹石发动不下食。\n和竹沥煮作粥，食之极美。\n\n疏：罂粟，其花至有千叶者，红、白、紫、黑色，有数种。\n\n一罂内子凡数千万粒，细如葶苈子而色白。\n\n本经味甘，平，无毒。\n\n苏颂性寒。\n\n甘寒除热解毒，下气和中，故主丹石发动不下食，及《图经》行风气，逐邪热，止反胃，去胸中痰滞也。', NULL, NULL, NULL, '罂子粟', NULL, '26、罂子粟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549517, 'AE1712CBC91E614BBA34832B5CC79D2F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7630, 436, 400108025, '      味酸、涩，微温，无毒。\n\n古方治嗽，及泻痢、脱肛、遗精，多用之，今人亦效尤辄用，殊为未妥。\n\n不知咳嗽惟肺虚无火，或邪尽嗽不止者，用此敛其虚耗之气。\n\n若肺家火热盛，与夫风寒外邪未散者，误用则咳愈增而难治。\n\n泻痢脱肛由于下久滑脱，肠虚不禁；遗精由于虚寒滑泄者，借用酸涩收敛之气以固虚脱。\n\n如肠胃积滞尚多，湿热方炽，命门火盛，湿热下流为遗精者，误用之则邪气无从而泄，或腹痛不可当，或攻入手足骨节肿痛不能动，或遍身发肿，或呕吐不下食，或头面俱肿，或精窍闭塞，水道不通，变证百出而淹延不起矣。\n可不慎哉！', NULL, NULL, NULL, '粟壳', NULL, '25、粟壳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549518, 'FD3002C1EC4BFFFC86BC01AD39175B1D', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7631, 436, 400108024, '     即鳖虱胡麻，出兖州威胜军，今陕州亦种之。\n其味甘，气温，无毒。\n足厥阴经血分药也。\n厥阴藏血，为风木之脏。\n凡大风疮癣，总厥阴血热所致。\n甘温益血而通行，则血自活，风自散，疠疾疥癞疮癣俱除矣。\n\n【主治参与】\n得漆叶、苦参、荆芥、天门冬、生地黄、青黛、百部、白花蛇、何首乌、半枝莲、豨莶叶、刺蒺藜、甘菊花，治大麻风。\n\n同金银花、连翘、萆薢、土茯苓、何首乌、苍术、木瓜、薏苡仁、生地黄、黄檗，治湿热太甚，遍身脓窠疮。\n', NULL, NULL, NULL, '亚麻', NULL, '24、亚麻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549519, 'F58CFAF4E0ACF9EE62A0805057281166', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', 1, 'admin', '2025-01-15 09:13:01');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7632, 436, 400108023, '        此鱼最能发湿，惟胆能治鱼骨鲠，及竹木刺误吞入喉不出，或吞入腹，腹中作痛隐隐，皆效。\n状如鲈鱼者是。', NULL, NULL, NULL, '鳜鱼胆', NULL, '23、鳜鱼胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549520, '4E92930F32667DF7CFF7DE8956485239', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7633, 436, 400108022, '    本经无文。\n      《纲目》载其主虚冷劳，及脾弱肾虚不能摄精，白浊，除湿热，健腰脚，固牙齿，去䵟（黑曾），治误吞铜铁金银等证。\n按《名医录》云：昔汉上张成忠女，年七八岁，误吞金馈子一只，胸膈痛不可忍，忧惶无措。\n一银匠炒末药三钱，米饮服之，次早大便取下。\n叩求其方，乃羊胫灰一物。\n盖羊胫骨灰可以磨镜，羊头骨灰可以消铁，故能治如是之证。\n谈野翁亦有此方。\n乃秘妙神效之法也。\n\n【主治参与】\n《食鉴》：擦牙固齿。\n\n羊胫骨灰一两，升麻一两，黄连五钱，为末，入青盐和匀，日用。\n\n《圣惠方》：咽喉骨鲠。\n\n羊胫骨灰，米饮下一钱。', NULL, NULL, NULL, '羊胫骨', NULL, '22、羊胫骨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549521, '225BCFF0DFF6DBE778D80B0A685BFB37', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7634, 436, 400108021, '       味甘，热，无毒。\n主阳虚阴痿精寒。\n此物出广之宜州嵠峒，及南丹州。\n土人号为插翅。\n其性淫毒，山中有此物，凡牝兽皆避去。\n獭无偶则抱木而枯。\n徭女春时成群入山，以采物为事。\n獭闻妇人气，必跃来抱之，刺骨而入，牢不可脱，因扼杀之。\n负归取其阴，一枚值金一两。\n若得抱木死者，尤奇贵。\n峒獠甚珍重之，私货出界者，罪至死。\n本地亦不常有，多伪者。\n试之之法，但令妇女摩手极热，取置掌心，以气呵之，跃然而动者为真', NULL, NULL, NULL, '山獭阴茎', NULL, '21、山獭阴茎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549522, '74CC804C86E16529997DE56F647F2149', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7635, 436, 400108020, '     狗宝，如牛之有黄也。\n第狗性热，其宝定是苦温之物。\n世人用治噎证，以其苦能下泄，温能通行耳。\n又能主痈疽疔肿，同蟾酥、脑、麝、雄黄、乳香、没药等用。\n\n【简误】\n狗宝性热，善消噎病。\n由于痰及虚寒而得者，犹可暂用取效。\n若因血液衰少以致噎膈者，法所当忌。\n世医不谙药理，不察病本，一概妄投，致病增剧。\n戒之！戒之！\n又，凡有脾胃虚弱，羸瘦不振之病，尤不宜用。', NULL, NULL, NULL, '狗宝', NULL, '20、狗宝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549523, '4D76118362217779BC47D0729CFD401F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', 1, 'admin', '2025-01-15 09:12:36');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7636, 436, 400108019, '       味甘，温，无毒。\n主中风偏废，口眼歪斜，痰涎壅塞，五藏六腑留痰、宿饮、癖块，手足皮肤中痰核。\n其法用肥嫩雄黄牛肉三四十斤，洗极净，水煮成糜，滤去滓，再熬成膏用。\n\n      疏：胃属土，为水谷之海，无物不受。\n胃病则水谷不能以时运化，羁留而为痰饮。\n壅塞经络，则为积痰、老痰、结痰等证。\n阴虚内热生痰，则为偏废、口眼歪斜。\n留滞肠胃，则为宿饮、癖块。\n随气上涌，则为喘急迷闷。\n流注肌肉，则为结核。\n王隐君论人之诸疾，悉由于痰。\n然而痰之所生，总由于脾胃虚，不能运化所致。\n惟用霞天膏以治诸痰证者，盖牛，土畜也。\n黄，土色也。\n肉者，胃之味也。\n熬而为液，虽有形而无浊质也。\n以脾胃所主之物，治脾胃所生之病，故能由肠胃而渗透肌肤毛窍，搜剔一切留结也。\n阴虚内热之人，往往多痰，此则由于水涸火炽，煎熬津液，凝结为痰。\n胶固难散者，亦须以此和竹沥、贝母、橘红、苏子、栝楼根、枸骨叶之类消之。\n或以橘皮、白茯苓、苏子、白豆蔻仁、半夏、苍术为麯，治脾胃积痰。\n或以橘皮、贝母、苏子、栝楼根及仁、蓬砂为麯，治积热痰结。', NULL, NULL, NULL, '霞天膏', NULL, '19、霞天膏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549524, '2DD1109B8EFF62496DD6091B0D582B34', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7637, 436, 400108018, '   味甘，平，无毒。\n\n主诸吐血，下血，血淋，妊妇胎动下血，风湿走注疼痛，打扑伤损，汤火灼疮，一切痈疽肿毒，活血止痛。\n（即牛皮胶。）\n\n按《本经》白胶，一名鹿角胶，煮鹿角作之。\n\n阿胶，一名傅致胶，煮牛皮或驴皮作之。\n\n其说甚明。\n黄明胶，即今水胶，乃牛皮所作，其色黄明，非白胶也，亦非阿井水所作。\n\n甄权以黄明为鹿角白胶，唐慎微又采黄明诸方附于白胶后，并误矣。\n\n其气味与阿胶同，故其所主亦与阿胶相似。\n\n以非阿井水及驴皮同造，故不能疏利下行。\n\n以其性味皆平补，亦宜于血虚有热者。\n\n若鹿角胶，则性味温补，非虚热者所宜，不可不详辨也。\n\n【主治参与】\n蔺氏方：跌扑损伤：真牛皮胶一两，干冬瓜皮一两，剉，同炒存性，研末。\n\n每服五钱，热酒一钟调服。\n\n仍饮酒二三盏，暖卧微汗痛止。\n\n《本事方》诸般痈肿：黄明胶一两，水半升化开，入黄丹一两，煮匀，以鹅翎扫上疮口。\n\n如未成者，涂其四围自消。\n\n阮氏《经验方》：背疽初起，用黄明牛皮胶四两，入酒重汤顿化，随意饮尽。\n\n不能饮者，滚白汤饮之。\n\n服此，毒不内攻。\n\n一方加穿山甲四片，炒成末，其妙无比。', NULL, NULL, NULL, '黄明胶', NULL, '18、黄明胶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549525, 'E2068A4F75D353F731588BFFC130F7A4', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7638, 436, 400108017, '     主下元虚冷。\n日令童男女，以时隔衣进气脐中，及两腰肾间，甚良。\n凡人身体骨节痹痛，令人更互呵熨，久久经络通透。\n盖气属阳，为一身之健运，即真火也。\n天非此火不能生物，人非此火不能有生。\n故老人、虚人，与二七以前少阴同寝，藉其熏蒸，最为有益，下元虚冷，火气衰也。\n得外入之少火，乃所以补其不足。\n骨节疼痹，血泣不行也。\n血不自行，随气而行，故能使骨节通畅也。\n近时术士，令童女以气进入鼻窍、脐中、精门，以通三田，谓之接补。\n此亦小法，不得其道者，反以致疾。', NULL, NULL, NULL, '人气', NULL, '17、人气', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549526, '14330CE28A8C0DD315BE172F7CFB157F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', 1, 'admin', '2025-01-15 09:12:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7639, 436, 400108016, '      年久枯竹中蠹屑也。\n竹之余气尚存，其气味必甘平无毒。\n甘能解毒，平则兼散，故可用为蚀脓长肉之药也。\n\n【主治参与】\n同象牙末、真珠、白矾等药，能消漏管。方见象牙条下。\n\n朱氏《集验方》：耳出臭脓，用蛀竹屑、胭脂胚子等分，麝香少许，为末，吹之。\n\n《普济方》：耳脓作痛，因水入耳中者，蛀竹屑一钱、腻粉一钱、麝香五分，为末。\n\n以绵杖绞净，送药入耳，以绵塞定。\n\n有恶物，放令流出，甚者三度必愈。\n\n又方湿毒臁疮：蛀竹屑、黄檗末等分，先以葱椒茶汤洗净，搽之。\n\n日一次，效。\n《外台秘要》汤火灼疮：蛀竹屑末，傅之愈。', NULL, NULL, NULL, '蛀竹屑', NULL, '16、蛀竹屑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549527, 'C4F4E170F02FC76DEF5B281749CF9F5E', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7640, 436, 400108015, '      得纯阳之气，其味辛，其气热。\n初时以水煎成，后得火则焰炽不息，其禀龙火之性者乎？\n气亦香窜，能通利关窍，逐中恶邪气，复能去湿杀虫。\n凡一切疥癣风瘙，湿毒疮疡等证，皆所须用。', NULL, NULL, NULL, '樟脑', NULL, '15、樟脑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549528, 'DE88E3B07EF626A51924403C90B03E46', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7641, 436, 400108014, '       禀火金之气以生，故其味辛苦，气热，有毒，辛能散风，苦能杀虫燥湿，温热能通行经络。\n世人用以治大风疠疾，乃风癣疥癞诸疮，悉此意耳。\n然性热而燥，伤血损阴，不宜多服。\n用之外治，其功不可备述也。', NULL, NULL, NULL, '大风子', NULL, '14、大风子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549529, '82ED2B6E6E3FDE87CC47E482D5723856', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7642, 436, 400108013, '       生于盛夏六阳之令，而成于秋金之月。\n得火金之气，故其味辛，气温有毒。\n凡肠胃有垢腻，秽恶之气郁于中，则外生瘰疬恶疮肿毒。\n泄于外，则为肠风下痢脓血。\n此药专能荡涤垢腻，宣通秽积，肠胃洁净，则诸证自除也。\n\n【主治参与】\n秘方：治瘰疬，用肥皂去核，入斑猫在内，扎紧蒸，去斑猫，加入贝母、天花粉、玄参、甘草、牛旁子、连翘，为丸。\n\n每服一钱，白汤下，服后腹疼勿虑，此药力追毒之故。\n\n独核仁，同猪胰子、金银花、皂角刺、芭蕉根、雪里红、五加皮、土茯苓、皂荚子、白僵蚕、木瓜、蝉蜕、白鲜皮，治霉疮。\n\n久虚者，加人参、黄耆、薏苡仁，兼治结毒。\n\n《普济方》肠风下血：独子肥皂烧存性一片，为末，糊丸。\n\n米饮下。\n又方，治腊梨头疮：用独核肥皂，去核，填入沙糖，入巴豆二枚，扎定，盐泥固煅存性，再入槟榔、轻粉六七分，研匀，香油调搽。\n\n先以汤洗净，拭干乃搽。\n\n一宿见效。\n\n除疮毒外，无他用，故不著 “简误”。', NULL, NULL, NULL, '肥皂荚', NULL, '13、肥皂荚', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549530, '0E90FE0B551E0F69A88837F2C145AC07', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7643, 436, 400108012, '    得地中之阳气，复感秋金之气以成。\n其味辛，其气热，其性有毒。\n入肝、入肾，祛风湿、寒湿之药也。\n惟其辛，故能散风邪；惟其热，故能除寒湿。\n凡下部有风寒湿邪者宜之。\n然而性热有毒，肝肾虚者不宜用。\n一切阴虚火炽，痿弱下体无力者，咸忌之。', NULL, NULL, NULL, '木绵子', NULL, '12、木绵子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549531, '1634A5B2A7390FC44A926CCF3B905716', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7644, 436, 400108011, '      得一阳之气以生，故其花开于冬末春初之时。\n其味甘而微辛，气平而微寒，色赤而入血分，故主吐血，衄血，肠风下血。\n并为末，入童溺及酒调服。\n', NULL, NULL, NULL, '山茶花', NULL, '11、山茶花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549532, '796DCEE8A174196E12D3592C195B63ED', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7645, 436, 400108010, '      禀夏末秋初之气，故其味辛。\n辛属金化，故能清肺，其气平，平即凉也，故能凉血散热解毒，兼治一切痈疽肿毒恶疮，排脓止痛，小儿疳积。\n\n【主治参与】\n《简便方》痈疽肿毒：重阳前取芙蓉叶，研末，端午前取苍耳烧存性，研末，等分，蜜水调涂四周。\n\n其毒自不走散。名铁井栏。\n\n他用甚稀，故不著 “简误”。', NULL, NULL, NULL, '木芙蓉', NULL, '10、木芙蓉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549533, '0866019300A59A93B58477FED4D0DAC0', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7646, 436, 400108009, '     味甘，寒，无毒。\n主明目，定心，去小儿热烦，止渴。\n方诸，大蚌也。\n向月取之，得二三合，水亦如朝露，又名明水。\n得至阴之精华，故能明目定心，及止渴除烦热也。\n又为丹灶家所须。', NULL, NULL, NULL, '方诸水', NULL, '9、方诸水', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549534, 'C8AE868DD60616EB9FEACCDF4637CA40', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7647, 436, 400108008, '      味甘，温，无毒。\n主止血，消肿毒，生肌，明目去翳退赤，收湿除烂。\n同龙脑，点治目中一切病。\n\n疏：炉甘石，受金气而结。\n味应甘辛，气温无毒，其性带涩。\n《经》曰：荣气不从，逆于肉里，乃生痈肿。\n甘温能通畅血脉，则肿痛散，血自止，肌肉生也。\n又目得血而能视，风热上壅则目为赤烂浮翳。\n甘入脾而益血，辛温能散风热，性涩则能粘物，故同除翳药点目翳，及治目中一切病也。\n\n【主治参与】\n一切目疾：真炉甘石半斤，用黄连四两，剉碎，入银石器内，水二碗，煮二伏时，去黄连，以甘石为末，入龙脑香二钱半，研匀，罐收。\n\n每点少许，频用取效。\n\n邵真人方：下疳阴疮，炉甘石煅，醋淬七次，一两，孩儿茶三钱，为末，麻油调敷，立效。\n', NULL, NULL, NULL, '炉甘石', NULL, '8、炉甘石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549535, '85AE1521DDFA09A0CC13BE4AC5B65907', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7648, 436, 400108007, '      乃硫黄同汞升炼而成。\n其性燥烈，过服能使人龈烂筋挛。\n其味辛气温，有毒。\n亦能破积滞，散结，疗癣疥恶疮，杀虫。\n不宜服食。\n今人多以黄丹、矾红杂之，不堪用。\n\n【主治参与】\n李楼《怪症方》火焰丹毒：银朱调鸡子清涂之。\n\n《多能鄙事》汤火灼伤：银朱研细，菜油调敷。\n\n《应急良方》：日久顽疮不收者。银朱一钱、地龙骨（即年久石灰）五分、松香五钱，为末，香油一两，化摊纸上贴之。\n\n兼能治湿毒臁疮。', NULL, NULL, NULL, '银朱', NULL, '7、银朱', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549536, 'DD3650F06A492119513769FE3A755F44', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7649, 436, 400108006, '      味辛、苦、涩，气温，微毒。\n性能除垢腻，磨积块，过服能损人。\n同石灰、桑硇，透肌肉，溃痈瘰疬，去瘀肉，点痣靥疣赘。\n今人用以浣衣。\n（出山东济宁、大同诸处。彼入采蒿蓼之属，开窖浸水，漉起晒干，烧灰，以原水淋汁，每百斤入粉面一二斤，则凝定如石，连汁货之。）\n\n【简误】\n      碱乃软坚消积之物，食之使人泄泻。\n以其阴湿之性，润下软坚透肉，故于肠胃非宜。\n作泄胃薄者忌之。', NULL, NULL, NULL, '石碱', NULL, '6、石碱', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549537, '64709E0805322452CE49E4324174B4B8', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7650, 436, 400108005, '      味辛，苦，气微温。\n辛能散风，苦能燥湿杀虫。\n故主头疮，白秃，疥疮，风癣痒痛流水。\n取焇牛皮灶岸烟膏为末，麻油调涂，或入轻粉少许。\n（此即熏焇牛皮灶上黑土也。）', NULL, NULL, NULL, '烟胶', NULL, '5、烟胶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549538, '7090404F162708CA312670AF48A7D068', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7651, 436, 400108004, '     味苦、涩，平，无毒。\n主清上膈热，化痰生津，涂金疮，一切诸疮，生肌定痛，止血收湿。\n一名孩儿茶。\n（出南番爪哇暹罗诸国。今云南、老挝、暮云场地方造之。云是细茶末，入竹筒中，坚塞两头，埋乌泥沟中，日久取出，捣汁熬制而成。其块小而润泽者为上，大而焦枯者次之。）\n\n         疏：乌爹泥本是茶末，又得土中之阴气，其味苦涩，气应作寒，性无毒。\n其主清上膈热，化痰生津者，茶之用也。\n得地中之阴气，能凉血清热，故主金疮止血，及一切诸疮，生肌定痛也。\n苦能燥，涩能敛，故又主收湿气。\n\n【主治参与】\n《积德堂方》牙疳口疮：孩儿茶、硼砂等分，为末搽之。\n\n《纂奇方》下疳阴疮：孩儿茶一钱，真珠一分，片脑半分，为末傅之。\n\n董炳方：脱肛气热。孩儿茶二分，熊胆五分，片脑一分，为末，人乳调搽肛上，热汁自下而肛收也。亦治痔疮。\n\n今人多用外治，内服甚少，故不著 “简误”。', NULL, NULL, NULL, '乌爹泥', NULL, '4、乌爹泥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549539, '8D433F0301E1E03E51C78B80C8E30977', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7652, 436, 400108003, '    大寒，无毒。\n治发背，诸恶疮。\n阴干为末，新水调傅，其痛立止。\n《圣济总录》治疔肿：粪下土、蝉蜕、全蝎等分，捣作钱大饼，香油煎滚，温服。\n以滓傅疮四围，疔自出也。\n今人以热粪盛核桃壳内，覆疔肿上，云疔根即烂出，即此意也。', NULL, NULL, NULL, '粪坑底泥', NULL, '3、粪坑底泥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549540, 'D4E9A47D5B27A496519B466419AA8C6F', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', 1, 'admin', '2025-01-15 09:11:17');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7653, 436, 400108002, '      即蚯蚓屎也。\n味甘，气寒，无毒。\n赤白久热痢，取一升炒，烟尽，沃汁半升，滤净饮之。\n盖久痢乃湿热甚于肠胃，得甘寒之气，则湿热自除矣。\n日华子主小儿阴囊忽虚热肿痛，以生甘草汁入轻粉末调涂之。\n以盐研，傅疮去热毒，及蛇犬伤。\n苏恭主傅狂犬伤，出犬毛者，神效。\n皆取甘寒除热解毒之力耳。\n【主治参与】\n《外台秘要》：一切丹毒，水和蚯蚓泥傅之。\n\n丹溪方：时行腮肿，柏叶汁调蚯蚓泥涂之。\n\n《摘玄方》燕窝生疮：韭地蛐蟮屎，米汁水和，煅过，入百草霜，等分研末，香油调涂之。\n\n又方：治下部杨梅结毒，韭地上蚯蚓泥、硫黄，等分研匀，用泥封固，作团煨过，取出研细，生桐油调搽。\n\n【简误】\n虚寒滑利，不宜用。', NULL, NULL, NULL, '蚯蚓泥', NULL, '2、蚯蚓泥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549541, '7373CF8F7AB69B28598A024F2579C2E2', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7654, 436, 400108001, '     味甘，平，无毒。\n\n       主泄痢冷热赤白，腹中热毒绞结痛，下血。\n取入地干土，以水煮三五沸，绞去滓，暖服一二升。\n又解诸药毒，中肉毒，合口椒毒，野菌毒。\n（张司空云：三尺以上曰粪，三尺以下曰土。凡用当去上恶物，勿令入客水。）\n\n        疏：土为万物之母，黄乃中央正色，在人脏腑则脾胃应之。\n故万物非土不生，人身五脏六腑非脾胃无以养。\n是以黄土入药，治泄痢冷热赤白，脾中热毒绞结痛者，取其补助戊己之功也。\n味甘而气和，故能安和脾胃，止下血，及解百毒，如经所言也。\n\n【主治参与】\n《小儿秘诀》：乌沙惊风，遍身都黑者，急推向下，将黄土一碗，捣末，入酢一钟，炒热包定，熨之，引下至足，刺破为妙。\n\n气味和平，与物无迕。故不著 “简误”。', NULL, NULL, NULL, '黄土', NULL, '1、黄土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 628517375549542, '6FFD76AC6718BA27784B516E9841FF23', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2024-12-31 10:23:47', NULL, NULL, NULL);
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7655, 317, 902000416, '\n【本经原文】味甘平，主黄疸泄利肠癖脓血，阴蚀下血，赤白邪气痈肿疽痔，恶疮头疡疥掻，久服补骨髓益气肥健不饥，轻身延年，五石脂各随五色补五脏。   计然曰赤石脂出河东赤色者善，列仙传曰赤须子好食石脂。 \n\n【产地】生南山之阳山谷中。产山西山东河南，他省亦多。 \n\n【性味】性味酸辛，性大温无毒。 \n\n【主治】为固肠收敛要药，主治赤白久痢，赤白带下，厚肠胃，除水湿，收脱肛。 \n\n【甄权】补五脏虚气。 \n\n【括要】固肠胃，有收敛之能，下胞衣，无推荡之峻。 \n\n【灵胎】功能治温，分补五脏。 \n\n【用量】普通二钱至三四钱。 \n\n【禁忌】凡火热暴注者不宜用，滞下全是湿热，于法当利，自非的受寒邪，下利白积者不宜用，崩中法当补阴清热，带下本属湿热积滞，法当去湿除积，止涩非宜。 \n\n【容川】赤石脂粘涩又味甘，能填补止泻利，土之质也，能燥湿。 \n\n【倪注】此药常与禹余粮合用，因同属涩剂，多用于温中止血痢不止。 \n\n【药征】主治水毒下利，故兼治便脓血。 \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。用醋淬可以增强收敛之功。  \n', NULL, NULL, '1', '赤石脂,黄石脂,白石脂,黑石脂,青石脂', NULL, '16、赤石脂,黄石脂,白石脂,黑石脂,青石脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633223730069573, '634E657EB1BD3971A46544CC2FE22D20', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-13 17:33:59', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7656, 317, 902000415, '\n【本经原文】味甘温，主心腹咳逆邪气，补不足，女子风寒在子宫绝孕，十年无子，久服轻身延年。 \n\n【产地】产深山中。 \n\n【性味】味甘辛，性温无毒。 \n\n【主治】主镇怯润枯，养心益肝，治女子风寒在子宫不孕。 \n\n【别录】疗上气心腹痛，寒热邪气结心，补心气不足，定惊悸安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，令人悦泽。 \n\n【甄权】养肺气，治惊痫，蚀脓。 \n\n【灵胎】补血降气。 \n\n【用量】普通煎用二至三钱，火炙过后用量宜少。 \n\n【禁忌】凡绝孕由阴虚火旺，不能摄受精气者忌用。 \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。', NULL, NULL, '1', '紫石英', NULL, '15、紫石英', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633223730135109, '5AD1EA84E176F8D59306309ABB7E5742', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-13 17:33:59', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7657, 317, 902000414, '\n【本经原文】味甘微温，主消渴，阴萎不足咳逆，膈间久寒益气除风湿痹，久服轻身延年。形如紫石英，选白泽长者二三寸。  \n\n【产地】产深山中。  \n\n【性味】味甘微温无毒。  \n\n【主治】肺大肠枯燥，疗肺痿肺痈消渴。  \n\n【甄权】治肺痈吐脓，咳逆上气，黄疸。  \n\n【用量】普通煎用二至三钱，火炙过用。 \n\n【禁忌】不可久服，寇氏曰紫白二石英攻疾可暂煮汁，未闻久服之益，仲景只为咀嚼不为细 末，岂无意焉。  \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。  ', NULL, NULL, '1', '白石英', NULL, '14、白石英', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633223730135110, '68A482BED02607C88F0A0E052C027503', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-13 17:33:59', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7658, 317, 902000413, '\n【本经原文】味甘平，主治咳逆上气，症瘕血闭，漏下除邪气，久服耐寒暑不饥，轻身飞行千里神仙。生泰山上，石如甲，甲中有白，白中有黄如鸡子黄色，又名太乙余粮，与禹余粮同，唯质较佳者。  \n\n【抱朴子金丹篇】灵丹经用丹砂雄黄雌黄石硫磺曾青矾石戎盐太一余粮，亦用六一泥及神室祭蘸合之三十六日成。  ', NULL, NULL, '1', '太一余粮,太乙余粮', NULL, '13、太一余粮,太乙余粮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633223730135111, '43DAC8A7906F45AD30D1FD300DAE83C7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-13 17:33:59', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7659, 317, 902000412, '\n【本经原文】味甘寒，主咳逆寒热烦满，痢赤白，血闭，症瘕大热，炼饵服之不饥轻身延年。\n\n【产地】生太山山谷 产于山岛或是池泽，乃石中黄粉。  \n\n【性味】味甘寒，无毒。 \n\n【主治】禹余粮为固补下焦要药，主治滑泄下血，血闭血虚，四肢虚而不仁，崩露赤白。  \n\n【别录】疗小腹痛结烦疼。  \n\n【甄权】主崩中。 \n\n【大明】治邪气及骨节疼，四肢不仁，痔露等疾，久服耐寒暑。  \n\n【灵胎】除热燥湿，止利消瘀。  \n\n【用量】入煎剂钱半至三钱，水飞用五分至一钱。  \n\n【禁忌】重可去怯，故为镇纳固补之剂，下焦有实热者忌，虚者良。  \n\n【倪注】此药多使用于下脓血利不止，常与赤石脂同用。 \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。  \n\n【容川】是石谷中之土质，又具涩性，故以填涩胃肠，甘而微咸，甘能补正以止利，咸能入肾以涩精。  ', NULL, NULL, '1', '禹余粮', NULL, '12、禹余粮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633223730135112, 'E5D2C899D70C2F0127A601A1255EF2D0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-13 17:33:59', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7660, 317, 902000421, '\n【本经原文】味甘微寒，主补五脏，安精神，定魂魄，止惊悸，除邪气，明目开心益智，久服轻身延年。采根，竹刀刮，曝干，无令见风。人形皆具者能做儿啼。  \n\n【产地】生上党山谷。我国吉林辽宁产者最良，山西长子县云南姚安县安徽舒城县亦有出产，高丽产出丰。\n\n【性味】味甘微苦性微寒无毒。 \n\n【主治】人参为大补元气要药，功能治一切衰弱痨瘵，通行周身补五脏之气，泻五脏之火，效益多但功缓，红色曰高丽参，性温而力较峻。  \n\n【甄权】主五劳七伤，虚损痿弱，止呕哕，补五脏六腑，保中守神。消胸中痰，治肺痿及痫 疾，冷气上逆，伤寒不下食，凡虚而多梦者可用。  \n\n【元素】治肺胃阳气不足，肺气虚促短气少气，补中缓中。泻心肺脾胃中火邪，止渴生津液。\n\n【容川】人参多用于病后元气伤者、用人参佐他药来调理，病人邪去正脱者，用人参佐他药调理之，现今人参多人工栽植，药力不如野参，我们可用黄耆甘草代人参，方剂中多以党参代人参。  \n\n因生于阴湿之地，禀水阴润泽之气，故味苦甘而有汁液，发为三枒五叶，阳数也，因生于阴而出阳，故于甘苦味中而有一番生阳之气。人身之元气，由肾水之中而上达于肺，此亦生于阴而出阳，与人参同一理，因此人参大能化气，气化而上，出于口鼻，即为津液，所以人参能生津也。人参生于北方、有阴中之阳药称，有化气补津之功。  \n\n【炮制】用湿布包裹，焖润用火烤，再晾干或烘干即可。 \n\n【药征】主治心下痞坚，痞鞭支结，旁治不食呕吐喜唾心痛腹痛烦悸等。  \n\n【灵胎】升提元气，兼补五脏，有崇正去邪之功，然非虚者勿服。\n\n【用量】普通五分至三钱，大剂一两。  \n\n【禁忌】肺家有热诸症及阴虚火动之候与痘疹之初发，身虽热而斑点未形，与伤寒始作，形症未定而邪热炽均忌，反藜芦。  ', NULL, NULL, '1', '人参  ', NULL, '21、人参  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633479149895749, '1E8A9C2E0EFDB88C78B26FE74DA08E91', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 10:53:18', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7661, 317, 902000420, '\n【本经原文】味苦平，主风，头眩肿痛，目欲脱泪出，皮肤死肌，恶风湿痹，久服利气血，轻身耐老延年，生川野及田野。今之菊花。  \n\n【产地】处处有之，种类很多，黄白二种入药，味苦，家庭玩赏之菊不入药，今杭州出产多，号称杭菊。  \n\n【性味】味苦甘平无毒。  \n\n【甄权】治头目风热，风眩倒地，脑骨疼痛，身上一切游风令消散，利血脉，调四肢。  \n\n【大明】作枕明目，叶亦明目，生熟都可食。  \n\n【元素】养目血，去翳膜。 \n\n【容川】菊叶为治疮之要药，因其性散，能去肌肉中之风邪也。  \n\n【灵胎】平肝熄风。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】味苦辣者，陈久者，不堪用，其甘者亦名甘菊，可饮可食亦入药。  \n\n【吴克潜】近世用为平肝良药，头痛目疼多因肝经风热上乘所致，菊花入肝，兼行周身，血脉不利而死肌，得菊花之利血脉皆效，特长于解毒，外科方剂用之治疔毒发背者，沈金鳌曰菊花并茎叶打汁饮，外涂内服皆可。时医用之因防邪热过久而酝酿化毒；平淡多奇功。  \n\n【附加菊叶】菊叶解毒之功胜于花，以鲜者良，捣汁敷一切肿毒，亦可内服。\n\n【炮制】拣去杂质及梗叶，拍去灰尘即得。  ', NULL, NULL, '1', '菊花,鞠华,杭菊', NULL, '20、菊花,鞠华,杭菊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633479149895750, '0C140350A32A7ACC60D5D1AD563D6000', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 10:53:18', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7662, 317, 902000419, '\n【本经原文】味辛温，主风寒湿痹，咳逆上气，开心孔补五脏，通九窍，明耳目，出声音，主耳聋痈疽，温肠胃，止小便利，久服轻身不忘不迷惑延年，生池泽。  \n\n吕氏春秋云冬至后五旬七日昌始生，昌者百草之先，于是始耕，又名兰荪。即今之菖蒲 也。  \n\n【产地】我国四川，今处处有之，多生水滨，可供盆栽，西洋及日本亦俱产之，根入药，一寸九节者良。  \n\n【性味】味辛性温无毒。  \n\n 【主治】菖蒲为宣窍泄热，健胃行滞要药，主开心孔通九窍，明耳目出声音，治咳嗽上逆，霍乱转筋，健脾胃杀诸虫，疗噤口痢。 \n\n【别录】四肢湿痹不得曲伸，小儿温疟，身积热不解，可作浴汤。  \n\n【甄权】治耳鸣，头风泪下，鬼气，杀虫，恶疮疥掻。  \n\n【大明】除风下气，丈夫水脏女人血海冷败，多忘，除烦闷，止心腹痛，霍乱转筋及耳痛者，作末炒，趁热裹。  \n\n【好古】心积伏梁。  \n\n【时珍】解巴豆大戟毒。  \n\n【灵胎】下逆开窍。 \n\n【用量】普通生用二三钱，干用五分至一钱半。  \n\n【禁忌】忌饴糖羊肉铁器。  \n\n【吴克潜】菖蒲南人多常用置食水中，或加矾少许，解一切毒，周颠仙曰常食菖蒲饮水，永无腹痛之疾，沈金鳌曰治禁口痢，屡用屡效，道藏经曰能治一切风，手足顽痹瘫痪不遂。正传曰九节菖蒲去毛捣末，入黑猪心一个，批开煮服，之癫痫风疾，著名方剂有$x{菖蒲丸}（$u{石菖蒲}、$u{人参}、$u{丹参}、$u{天冬}、$u{麦冬}、$u{赤石脂}）。治小儿心气不足，不能言语。又醋糊丸棉裹置耳中，治耳内卒痛，聋闭不闻，有$x{菖蒲益智丸}（$u{菖蒲}、$u{远志}、$u{人参}、$u{桔梗}、$u{牛膝}、$u{附子}、$u{茯苓}、$u{桂心})。治健忘恍惚，破积聚止痛，安心定神聪明耳目均效。  \n\n【倪注】常用于鼻塞不通，脑部受损。内服外用皆宜。  \n\n【炮制】拣去杂质，刷去灰尘，洗净晒干，去灰尘即得。  ', NULL, NULL, '1', '菖蒲,石菖蒲,兰荪', NULL, '19、菖蒲,石菖蒲,兰荪', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633479149895751, '21FD309567A5F8AD475FF128576BC166', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 10:53:18', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7663, 317, 902000418, '\n【本经原文】味甘平，主目痛明目，折跌痈肿，金创不疗，破积聚解毒气，利精神，久服轻身不老。神农雷公小寒无毒，治丈夫内绝令人有子。去寒热风痹，及丈夫茎中百病益精。  \n\n【别录】吐风痰，癫痫，平肝。\n\n 【灵胎】养肝明目。  ', NULL, NULL, '1', '扁青', NULL, '18、扁青', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633479149895752, '387F3B2BD1E994642FE496C7AF9035F8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 10:53:18', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7664, 317, 902000417, '\n【本经原文】味甘平，主明目利九窍，耳聋心下邪气令人吐，杀诸毒三虫。久服通神明，轻 身延年不老。  ', NULL, NULL, '1', '白青', NULL, '17、白青', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633479149895753, 'B65B847D3ED3F18AD0ED03C188E5910F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 10:53:18', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7665, 317, 902000446, '\n【本经原文】味辛温，主杀鬼精物蛊毒恶气，久服益气力长阴肥健轻身增年。今之天麻。  \n\n【产地】产四川及各地山野林中之阴地，苗名赤箭，根即天麻。  \n\n【性味】味辛性平无毒。 \n\n【主治】天麻为祛风镇痉要药，功能治诸风头痛头眩，风湿痹，小儿精痫拘挛。  \n\n【甄权】治冷气麻痹瘫缓不随，语多恍惚，善惊失志。 \n\n【大明】助阳气，补五劳七伤，鬼疥（病），通血脉，开窍。  \n\n【禁忌】风药多燥，风能胜湿故也。凡病人觉津液少，口干舌燥，咽干痛，大便涩，及火炎头晕，血虚头痛，似中风症皆忌。  \n\n 【东垣曰】肝虚不足者，天麻川芎以补之。罗天益曰眼黑头眩，风虚内作，非天麻不能治，因此天麻有养血之功。汪昂云风药中必兼养血药，以制其燥，养血药须兼收风药，宣其滞也。古云治风先治血，血行风自灭。举凡能宣血之滞，故能发痘疹。  ', NULL, NULL, '1', '天麻,赤箭', NULL, '46、天麻,赤箭', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786373, 'C2572A73BDC6AB270AAB8AAA064B7FBC', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7666, 317, 902000445, '\n【本经原文】味甘平，主五脏邪气风寒湿痹，补中益气，长毛发令黑，疗心悬少食常饥，久服轻身耳目聪明不老。  \n\n【产地】到处皆有，以水生蒌蒿最好，辛香而美。  ', NULL, NULL, '1', '白蒿', NULL, '45、白蒿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786374, '4ADBC550432F42408347322D40CA6D0B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7667, 317, 902000444, '\n【本经原文】味甘寒，主寒热八疽消渴补中益气，久服轻身延年。 \n\n【产地】生川泽，为野生蔓草，全草可用。 \n\n【性味】根苗叶味甘，性寒。 \n\n【效用】白英为解热药，治风疹，丹毒，黄疸及热疟。有补益之效。\n\n【弘景】叶做羹饮，可疗劳。 \n\n【藏器】烦热，风疹，丹毒，瘴疟寒热，小儿结热，煮汁饮之。', NULL, NULL, '1', '白英 ', NULL, '44、白英 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786375, '69DBA13AE65383DF575E6CDD92AEAFF8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7668, 317, 902000443, '\n【本经原文】味辛微温主大风邪气，阴痿不起，强筋骨安五脏，补中增智益气。\n\n【产地】产四川者最佳，多山林内，叶经冬不枯，根似联珠，入药。  \n\n【性味】味辛甘，性微温，无毒。 \n\n【主治】巴戟天为补气益精要药，功能祛风除湿，强筋骨，壮元阳，治遗精。  \n\n【别录】疗头面游风，小腹及阴中相引痛，补五劳，益精，利男子。  \n\n【甄权】男子夜梦鬼交泄精，强阴，下气，治风癞。  \n\n【日华】治一切风，疗水胀。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡相火炽，思欲不得，便赤口苦，目昏目痛，烦燥口渴，大便燥结者均忌，恶雷丸丹参，得覆盆子良。此药治肾亏最佳，故遗精滑精者宜，阳痿者良，有虚火者禁忌。  \n\n【容川】色紫而根实，能温肝，足厥阴主风，属阴中之阳，药气温者即阴中之阳，故入肝。  ', NULL, NULL, '1', '巴戟天', NULL, '43、巴戟天', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786376, 'E8D992B172E58F2628CEBE4CFBB8156B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7669, 317, 902000442, '\n【本经原文】味甘平主伤中除痹下气，补五脏虚劳羸瘦，强阴，久服厚肠胃轻身延年。  \n\n【产地】产我国四川湖南湖北安徽等地，多自生于山谷湿润之石上，日人用以栽种，出产丰，  \n\n【性味】味甘性平无毒。 \n\n【主治】石斛为除热益阴要药，主养脾胃，益心肾，补虚劳，退虚热，治自汗盗汗，小便余沥，脚痛痹弱。  \n\n 【别录】补内绝不足，平胃气，长肌肤肉，逐皮肤邪热，疿气脚湿，疼冷痹弱，定志除惊。\n\n【甄权】益气除热，男女腰脚软弱，健阳，逐皮肌风痹，骨中久疼，补肾益力。 \n\n【日华】壮筋骨，暖水脏，益智清气。 \n\n【灵胎】养胃生津，补虚除痹。 \n\n【用量】普通一钱至三钱。  \n\n【禁忌】多服能寒胃，至大便溏薄，入姜一二片为辅，则无此弊，清肺补脾也，恶凝水石巴豆，畏雷丸僵蚕。  \n\n【附录】 鲜石斛—石斛茎之鲜者，以铁皮鲜石斛为最良，治胃中大热，津液干竭，凉肺生精，胜于石斛。 钗石斛—石斛之状似金钗者，较之寻常石斛凉性多而黏性少，滋阴降火，于小儿胃热尤宜。川石斛—石斛之产于四川者，其茎紧小，清热之功较着。', NULL, NULL, '1', '石斛', NULL, '42、石斛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786377, '845EC8A585820CAA8868659E0DE15D36', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7670, 317, 902000441, '\n【本经原文】味辛温，主咳逆头痛，脑动，百节拘挛，风湿痹痛，死肌，久服明目利九窍， 轻身长年。岐伯曰无毒。色白者善。  \n\n【产地】生华阴山谷。产我国陕西及关外，今北地多有之，为多年生草本，叶下开花，状似杜衡，唯苗叶经冬则凋，根外淡褐而内白色，气味辛烈。  \n\n【性味】味辛性温无毒。  \n\n【主治】细辛为风痛要药，功能深入散风袪寒，主治咳逆上气，风湿，痹痛，头痛，齿痛，泄热破痰，开窍行水。  \n\n【别录】温中下气，破痰，利水道，开胸中滞积，除喉痹，鼻塞不闻香臭，风痫癫疾，下乳 结，汗不出，血不行，安五脏，益肝胆，通精气。  \n\n【甄权】添胆气，治咳嗽，去皮风湿痒。风眼泪下，除齿痛，血闭，妇人血沥腰痛。  \n\n【弘景】含之去口臭。  \n\n【好古】治督脉为病，脊强而厥。  \n\n【吴克潜】曰细辛主治诸痛，但用不可过剂。宗奭曰治头面风不可缺此。元素曰以独活为使治少阴头痛如神。张子和曰治头痛，太阳经则羌活，少阴则细辛，阳明则白芷，厥阴则川芎 吴萸，少阳则柴胡。成无己曰胆气不足，细辛补之。著名方剂有伤寒论之麻黄附子细辛汤，小青龙汤等。  \n\n【容川】细辛形细色黑，故入少阴经，味大辛，能温散少阴之风寒，而少阴为寒水之脏，寒则水气上泛，细辛散少阴之寒，能达水中之阳，故能逐水饮。  \n\n【药征】主治宿饮停水也，故治水气在心下而咳满，或上逆，或胁痛。  \n\n【灵胎】疏风散邪，驱逐寒气。  \n\n【用量】普通三分至一钱。  \n\n【禁忌】升燥发散性烈，凡内热及火升炎上，上盛下虚，气虚有汗，血虚头痛，阴虚咳嗽，均忌。  ', NULL, NULL, '1', '细辛', NULL, '41、细辛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786378, 'AB37DB047A08C8F2C04FA82E6E403CEE', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7671, 317, 902000440, '\n【本经原文】味苦涩，主骨间寒热，惊痫邪气，续绝伤，定五脏，杀蛊毒，久服益智不忘，轻身耐老。  \n\n【产地】山野自生之宿根草，其叶经霜雪不凋，根茎黑暗褐色入药。  \n\n【性味】味甘涩，性大寒，无毒。  \n\n【主治】龙胆草为涤邪火除湿热要药，功能健胃清热，治痢杀虫，主治肝火胆火胃火，下焦湿热。  \n\n【别录】除胃中伏热，时气温热，热泄下痢，去肠中小虫，益肝胆气，止惊惕。  \n\n【甄权】治小儿壮热骨蒸，惊痫入心，时疾热黄，痈肿口干。  \n\n【大明】客忤疳气，热狂，明目止渴治疥疮。  \n\n【元素】去目中黄及睛赤肿胀，瘀肉高起，痛不可忍。  \n\n【东垣】退肝经邪热，除下焦湿热之肿，泻膀胱之火。  \n\n【容川】味苦而坚涩，兼水火之性，故能泻肝胆之火。且龙胆草根多而深细，故泻火并兼降利，能清热以利少阳三焦与胆之火。  \n\n【倪注】去中焦肝胆脾胃之湿热。  \n\n【灵胎】泻肝胆火。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】胃虚血少，脾胃两虚作泻，病虚有热均忌。 龙胆草大苦大寒，所治多湿热之病，洁古曰下行之功与防己同，酒浸则能上行外行，柴胡为主龙胆为使，治目疾必用之药。因性大寒故不可久服，恐伤胃气。  \n\n【炮制】拣去杂质，洗凈泥砂，捞出，沥干，稍闷，除去残茎，切 0.5-1  厘米，晒干或烘焙， 去灰即得。  ', NULL, NULL, '1', '龙胆', NULL, '40、龙胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786379, '08DE15D2A21D5F13262E0462B6EBBF85', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7672, 317, 902000439, '\n【本经原文】苦温，主咳逆伤中补不足，除邪气，利九窍，益智慧，耳目聪明不忘，强志倍力，久服轻身不老。 \n\n【产地】产陕西河南，为山野自生之常绿草，其根入药。 \n\n【性味】味甘苦性温无毒。 \n\n【主治】远志为强心益智要药，功能治神虚怔忡，痰涎咳逆。 \n\n【别录】利丈夫，定心气，止惊悸益精，去心下隔气，皮肤中热，面目黄。 \n\n【之才】杀天雄附子乌头毒，煎汁饮之。 \n\n【甄权】治健忘，安魂魄，令人不迷，坚壮阳道。 \n\n【好古】肾积奔豚。 \n\n【灵胎】补心通窍，益智除邪。 \n\n【用量】普通八分至二三钱。 \n\n【禁忌】凡心经有实火为心家实热应用黄连生地者，禁与参术等助阳气药物同用，畏珍珠藜芦得茯苓良。  \n\n【容川】其性与桂枝同，但桂枝四达，远志则系根体细瘦，故主入心经，以散心中之滞血。味苦亦入心，兼有辛温之性，故能补心火。  ', NULL, NULL, '1', '远志', NULL, '39、远志', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786380, '602212DB9A39E8624FABAB94DA295BC3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7673, 317, 902000438, '\n【本经原文】味甘寒，主风寒湿痹，乳难消水，养五脏，益气力，肥健，久服耳目聪明，不饥延年，轻身，面生光，能行水上。其叶如车前草，味亦相似。 \n\n【产地】生汝南池泽。产我国福建陕西河南山东等地，生于水泽池沼，根作圆球形，色黄，入药。 \n\n【性味】味甘咸，性寒无毒。 \n\n【主治】泽泻为渗湿利尿要药，主风寒湿痹，逐膀胱三焦停水，通淋沥，止遗泄，利小便，消肿胀。 \n\n【别录】补虚损，五脏痞满，起阴气，止泄精，消渴，淋沥，逐膀胱三焦停水。 \n\n【甄权】主肾虚精自出，治五淋，宣通水道。 \n\n【大明】主头眩耳虚鸣，筋骨挛缩，通小肠，止尿血，主难产，补女人血海，令人有子。 \n\n【元素】入肾经，去旧水，养新水，利小便，消肿胀，渗泄止渴。 \n\n【东垣】去肤中留垢，心下水痞。 \n\n【药征】主治小便不利冒眩也，旁治渴。 \n\n【灵胎】消水利肿。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡病人无湿无饮而阴虚，及肾气乏绝，阳衰精自流出，肾气不固，精滑目痛，虚寒作泄等候，均忌。\n\n 古方常以配合补剂用，因欲补必兼泻邪，邪去则补药得力，宗奭曰多服昏人眼，以行去其水也，凡服泽泻散，未有尿不多者，尿既多肾气焉得实。海藏曰泻伏水去留垢，故明目，小便利，肾气虚，故昏目，是可知泽泻之能明目，在能渗湿，若已中病而用之过量，则诛伐无过，使肾气虚而昏目，药本在治病救偏，过量则害，百药皆然，岂独泽泻而已。著名方剂有疏凿饮（泽泻商陆赤小豆羌活大腹皮椒目木通秦艽茯苓槟榔生姜）治水气通身浮肿。烦燥喘渴，小便不利。泽泻汤（泽泻五两白术二两）治心下有支饮其人苦冒眩者。五苓散（茯苓 猪苓白术泽泻肉桂）治水分有热，小便不利，烦渴或水饮内停，脐下悸者。 生于根下，则化气上行，引肾阳以达上。 \n\n【炮制】拣去杂质，大小分开，浸泡四小时，热天加少量明矾，冬天不用。捞出，沥干除水，  \n\n用盐水喷洒，晒干，火烤使色现微黄色，取出，冷却即得。  ', NULL, NULL, '1', '泽泻', NULL, '38、泽泻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786381, '48DFC6C8FB9344E4EF52C45C27EE9230', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7674, 317, 902000437, '\n【本经原文】味甘微寒，主筋急拘挛不可屈伸，风湿痹，下气，久服轻身益气，其根下三虫，一名解蠡。 \n\n【产地】产我国直隶陕西及安南等地，他处亦多有种植，仁白，咬之觉粘者良。 \n\n【性味】味甘淡，性微寒，无毒。 \n\n【主治】薏苡仁为除湿行水，健胃补肺要药，主除筋骨邪气，拘痹不仁，利肠胃，消水肿， 祛风湿，治脚气。 \n\n【别录】除筋骨中邪气不仁，利肠胃，消水肿，令人能食。  \n\n 【藏器】炊饭做面食，主不饥，温气，煮饮止消渴，杀蛔虫。 \n\n【甄权】治肺痿，肺气积脓血，咳嗽涕唾上气，煎服破毒肿。 \n\n【孟铣】祛干湿脚气大验。 \n\n【药征】主治浮肿也。 \n\n【灵胎】养胃舒筋，除湿泄热。 \n\n【用量】普通三钱至六钱。 \n\n【禁忌】大便燥结，因寒转筋，及孕妇忌。 汪讱庵曰，泻水所以益土，故健脾益土，所以生金，故补肺清热，扶土所以抑肝木，故 治风热拘挛。\n\n【宗奭曰】本经言薏苡仁主筋急拘挛，但拘挛有两等，素问注中大筋受热，则缩而短，故挛不伸，此是因热而拘挛也，故可以用薏苡仁，若素问言因寒则筋急者，此盖受寒 使人筋急，不可以用薏苡仁，寒热使人筋挛，若但受热不曾受寒，亦使人筋缓，受湿则又引长无力，此药力极缓和，凡用须加倍，即见效。又经疏谓孕妇忌服，不识何故，或未必然也。又日医记载其能治疣，颇功效。 生于茎上，化气下行，故能引肺阳达下。 \n\n【炮制】取去壳之仁，清水洗净晒干，拣去杂质即可。  \n\n【容川】此药生于水中，味极淡，不补又不涩，专于渗利。凡味淡气薄皆能降而渗利，其属阳之阴，不行在上之窍，而行在下之清窍，故能利小便。  \n\n【附录】苡仁根──主下三焦，能堕胎，治黄疸，卒心腹烦满，胸胁痛。  ', NULL, NULL, '1', '薏苡仁', NULL, '37、薏苡仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786382, '10BB109DE7718AD7DA735C4FD946BD31', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7675, 317, 902000436, '\n【本经原文】味甘温，主伤中，补虚羸，除寒热邪气，补中，益气力，长肌肉，久服耳目聪  \n\n明，轻身不饥，延年。又名薯豫。又名山药。今名淮山。 \n\n【产地】产河南及浙江等地，他处亦多有之，为山野自生之宿根蔓草，根入药。 \n\n【性味】味甘性温平，无毒。 \n\n【主治】署豫为补虚扶弱要药，主益肺脾，清虚热，治虚羸，长肌肉，补心益肾，疗健忘遗精，生捣敷痈疮，消肿硬。 \n\n【别录】主头面游风，头风眼眩，下气，止腰痛，治虚劳羸瘦，充五脏，除烦热。 \n\n【甄权】补五劳七伤，去冷风，镇心神，安魂魄，补心气不足，开达心孔多记事。 \n\n【大明】强筋骨，主泄精健忘。 \n\n【丹溪】生捣贴肿硬毒能消散。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】恶甘遂，不宜与面同食。 \n\n【容川】味甘有液，得土之湿气，功能补脾阴即补脾之水以补湿，因其色白，得土中之金气，故有益肺之功，带酸之性故兼入肝肺。  ', NULL, NULL, '1', '山药,薯豫,淮山,怀山', NULL, '36、山药,薯豫,淮山,怀山', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786383, 'F06A20B61DC3504D9A1F6A386ABD1C23', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7676, 317, 902000435, '\n【本经原文】味辛。主邪气，辟毒疫温鬼，强志，主淋露，久服不梦寤魇寐。 \n\n【产地】我国云南贵州两广皆出产，其根外面灰黄，内部灰白，有香气入药。 \n\n【性味】味辛苦，性温无毒。 \n\n【主治】木香为开胃调气要药，功能行三焦之气，宣扬肠胃之滞，主治心腹诸痛呕吐泄泻，消痞积，辟邪气。  \n\n 【别录】消毒，杀鬼、精物、温疟、蛊毒，气劣气不足，肌中偏寒，引药之精。 \n\n【大明】治心腹一切气，膀胱冷痛，呕逆反胃，霍乱泄泻，痢疾，健脾，消食安胎。 \n\n【甄权】九种心痛，积年冷气，痃症块，胀痛，壅气上冲，烦闷羸劣，女人血气刺心，痛不可忍，末酒服之。  \n\n 【元素】散滞气，调诸气，和胃气，泄肺气。 \n\n【丹溪】行肝经气，煨熟实大肠。 \n\n【好古】治冲脉为病，逆气里急，主浮，渗小便秘。 \n\n【灵胎】辟邪逐疫。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】肺虚有热，元气虚脱，及阴虚内热，诸病有热，心痛属火，均忌。 \n\n【吴克潜】曰木香调气定痛，功力甚佳，治中下二焦气结滞而不运，宜槟榔为使，故治痢疾腹痛，有木香槟榔丸之设也。 \n\n【宗奭】曰此专决泄胸腹间滞塞冷气。他则次之，得橘皮蔻仁生姜相佐，效尤速。 \n\n【弘景】曰木香疗毒肿消恶气有验，今唯制蛀虫丸中用之，至于木香配合之成方颇多，著者有木香丸（香附黄柏胡黄连木香），治腹痛食伤，气郁作痛，诸虫痛，盖佐以苦寒之药，则不仅治冷痛也。香连丸（木香黄连）治痢疾为调和之剂，木香丸（木香附子卤砂）治寒疝绕脐作痛，结鞭不消，木香饼（生地木香作饼），热熨贴之，治结肿成核，消乳中结核酸痛等，均有灵效。  \n\n【容川】木香之理气，以其香气归脾，而味兼微辛，气浮味沉，得木气之温，力能疏土，茎是五枝五节，合于脾之数。其气浮味沉，能理上中下三焦。  ', NULL, NULL, '1', '木香', NULL, '35、木香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786384, '10F8976B9C448BE5A8B7F956687753B8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7677, 317, 902000434, '\n【本经原文】味甘寒，无毒，主气癃，止痛，利水道小便，除湿痹，久服轻身耐老。因喜在牛迹中生，故又名当道也。 \n\n【产地】产泽野及路旁，处处有之，自地下生叶，从叶中抽茎，长数寸，多子。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】车前子为行水泄热要药，主利小便，通淋沥，清肺肝风热，渗膀胱湿热，强阴益精明目。 \n\n【别录】男子伤中，女子淋沥不欲食，养肺，强阴益精，令人有子，明目疗赤痛。 \n\n【甄权】去风毒，肝中风热，毒风冲眼，赤痛障翳，脑痛泪出，压丹石毒，去心胸烦热。 \n\n【灵胎】专利小便。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】内伤劳倦，阳气下陷者忌，肾气虚脱者忌与淡渗药同用。 \n\n【吴克潜】曰车前子能利水道而不走真气，与茯苓同功，治暑湿暴下，则泌别清浊，使小便利而泄泻自止，治五淋则渗泄湿热，使从小便下而淋自止，且以通为补，车前尤能强肾益精，如五子衍宗丸等。  \n\n【附录】车前叶──凉血除热，止吐衄，消症瘕，与车前子同功。  ', NULL, NULL, '1', '车前子', NULL, '34、车前子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786385, '65CE96E11BCD8154B3637E59701828B7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7678, 317, 902000433, '\n【本经原文】味苦平，主风寒所击，金疮止痛，贲豚，痫痓，女子疝瘕，久服轻身耐老。此药有风花不动，无风独摇。  \n\n【产地】产我国四川陕西甘肃，或云产西羌者名羌活，或云即系一种，独活根老而气细，羌活根嫩而气雄。  \n\n【性味】味辛苦，性温，无毒。 \n\n【主治】独活为风痛要药，主治头痛身痛脚痛，机关不利，风湿诸痹。  \n\n【别录】疗诸贼风，百节痛风，无问久新。  \n\n 【甄权】治诸中风湿冷，奔喘气逆，皮肤苦痒，手足挛痛，劳损风毒齿痛。  \n\n【好古】去肾间风邪，搜肝风，泻肝气，治项强，腰脊痛。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡血虚发痉，血虚头痛，及遍身疼痛，骨痛，因而带寒热者，均属内症，均忌，误用必反剧。  \n\n【容川】色黑，故兼入少阴经，以达太阳，能散背脊之风寒，同$u{天麻}与$u{白头翁}皆有风不动，无风而动。但味太辛，气太温，能散风寒，其力胜于天麻，兼能燥湿，但不如天麻之刚柔得中也。  ', NULL, NULL, '1', '独活', NULL, '33、独活', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178786386, '72E156BD118ABDB837377EFCC2714EA9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7679, 317, 902000432, '\n【本经原文】味甘平，主心腹结气，伤中伤饱，胃络脉绝羸瘦短气，久服轻身不老，不饥。生川谷及堤阪。 陶弘景云：实如青珠，根似穬麦，故谓麦门冬。 \n\n【产地】生函谷川谷。生山谷肥地，我国陕西及江浙一带，多有之。叶绿，四季不凋，根黄白色，入药。\n\n【性味】味甘性寒，无毒。 \n\n【主治】麦冬为润肺清火要药，主治肺中伏火，痰多，心腹结气，肺弱胃弱，津少口渴，止咳嗽，疗肺病吐脓血。 \n\n【别录】疗身重目黄，心下支满，虚劳客热，口干燥渴，止呕吐，愈痿躄，强阴益精，消谷 调中，保神定肺气，定五脏，令人肥健，美颜色，有子。 \n\n【藏器】去心热，止烦热寒热体劳，下痰饮，合车前地黄丸服去湿痹。 \n\n【甄权】治热毒大小，面目肢节浮肿，下水主泄积。 \n\n【元素】治肺中伏火，补心气不足，主血妄行，及经水枯，乳汁不下。 \n\n【灵胎】补土生金，寒咳勿用。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】麦冬性寒，虽主脾胃而虚寒泄泻及痘疮虚寒作泻，产后虚寒作泻均忌，入补药，酒浸良。秉水阴，能滋肺以清气分。 \n\n【炮制】拣去杂质，洗净晒干即得。  ', NULL, NULL, '1', '麦门冬', NULL, '32、麦门冬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790469, '60588D4E11034F4B54D247599BE91DA1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7680, 317, 902000431, '\n【本经原文】味苦平，主心腹，去肠胃中结气，饮食积聚，寒热邪气，推陈致新，久服轻身明目益精。现名柴胡。  \n\n【产地】生弘农川谷。出关东陕西各地，今各处亦有产，分南北两种，性味相同，产银州者曰银柴胡，性味稍异。  \n\n【性味】味苦性平无毒。  \n\n【主治】柴胡为发表清热要药，功能散三焦肝胆诸经之热邪，主治寒热疟疾，口苦耳聋，头痛眩晕。  \n\n【别录】除伤寒心下烦热，诸痰热结实，胸中邪气，五脏间游气，大肠停积水胀，及湿痹拘急，亦可做浴汤。  \n\n【甄权】治热劳骨蒸烦疼，热气，肩背疼痛，劳乏羸瘦，下气消食，宣畅气血，主时疾内外 热不解，单煮服食良。  \n\n【备要】伤寒邪热，痰热结实，虚劳肌热，十二经疮疽血凝气聚，功同连翘。  \n\n【容川】柴胡一茎直上，花清香，故能升散郁结。专治胸前逆满，太阳经气陷于胸中，不得外达，以致胸满，唯柴胡能透达，其色青，生于春而采于夏，得木火之气，从中土以达木火之气，使不侮肺也，故功能透胸前之结，仲景用柴胡以治少阳，少阳为水中之阳，发于三焦，以行腠理，寄居胆中，以化水谷，故必三焦之膜网通畅，肝胆之木火清和，则水中之阳乃由内达外，柴胡茎中虚松，有白丝通气，象人之三焦膜网，少阳木火，郁于腠理，而不达者，则作寒热，柴胡能达之，阳气得发散，且味清苦，良柴胡须用一茎直上，茎色青，叶生四面，细如竹叶，开小黄花者，乃为真柴胡，此为仲景所用。四川梓潼产柴胡最佳，价极廉。今多不知用，因药典有软柴胡，银柴胡，红柴胡等，皆以假乱真，柴胡入肝经。附银柴胡：柴胡之产于陕西银州者，色黄白而大，味甘性微寒，凡热在骨髓者，非此不除，为清热凉血之品，优于发散而推陈致新，治虚劳者酌用之。  \n\n【药征】主治胸胁苦满也，旁治往来寒热也，腹中痛，胁下痞鞭。\n\n【灵胎】其性轻扬，能逐半表半里之邪。  \n\n【用量】普通八分至一钱，大剂三四钱。 \n\n【禁忌】凡虚人气升呕吐，及阴虚火热炎上，法同所忌。 汪昂曰凡胁痛，多属肝旺，宜小柴胡汤。加青皮川芎白芍，左胁痛宜治活血行气，右胁痛宜 消食行痰，因胁痛须开郁，故加柴胡则皆宜也。  ', NULL, NULL, '1', '柴胡,茈胡', NULL, '31、柴胡,茈胡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790470, '932FA96E7413CB200A23A1AE2547C9A7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7681, 317, 902000430, '\n【本经原文】味辛寒，主疝瘕，肠泄，膀胱热结，溺不下，咳逆，温疟，癫痫，惊邪狂走，久服坚骨髓，益气轻身。又名梨盖。  \n\n【性味】防葵味辛苦，性寒。 \n\n【效用】根为解热利尿，镇静药，治膀胱宿水，膀胱热结，癃闭，癫狂痫症。  \n\n【甄权】主痃癖气块，膀胱宿水，血气瘤大如盆者，悉能消散。  ', NULL, NULL, '1', '防葵 ,梨盖', NULL, '30、防葵 ,梨盖', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790471, '7D110423760C99866D3E41A43C38207D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7682, 317, 902000429, '\n【本经原文】味甘平，主中风暴热不能动摇，跌筋结肉，诸不足，久服去面黑皯，好颜色，润泽，轻身不老。又名萎蕤。现名玉竹。 郭璞云药草也，叶似竹，大者如箭竿有节叶狭而长，表白里青根大如指长一二尺，可啖。 \n\n【产地】生于山麓阴地之多年生草，各地皆有，以产南部地方者为上，其地下茎粗大有三棱，节作紫黑色。  \n\n【性味】味甘性平无毒。  \n\n【主治】萎蕤为治风热风湿入肌作痛要药，功能祛风清热，除湿止痛，主邪热头痛，及腰痛身痛，补劳伤。  \n\n【别录】心腹中结气，虚热湿毒肿痛，茎中寒，及目痛眦烂泪出。 \n\n【甄权】时疾寒热，内补不足，去虚劳客热，头痛不安加而用之良。  \n\n【弘景】服诸石人不调和者，煮汁饮之。  \n\n【容川】风能胜湿，风伤血则筋燥，玉竹可以润燥。  \n\n【用量】普通二钱至四钱，大剂二三两。  \n\n【禁忌】畏咸卤。  ', NULL, NULL, '1', '玉竹,女萎', NULL, '29、玉竹,女萎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790472, 'C33D98EFC94E11E0FA8E10473B796593', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7683, 317, 902000428, '\n【本经原文】味辛微温，主明目益精，除水气，久服轻身，茎主瘾疹痒，可做浴汤，一名益母。 \n\n【产地】多生于原野及近水处，叶为深裂式，茎做方形，名益母草，即茺蔚子。 \n\n【性味】味辛苦性微寒，无毒。 \n\n【主治】此药为去瘀生新，通调月经，及产后要药，根茎功用相同。 \n\n【别录】疗血逆，大热头痛心烦。 \n\n【吴瑞】舂仁生食补中益气，通血脉，填精髓，止渴，润肝。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】血崩及瞳子散大均忌，唯热血欲贯瞳仁者，可与凉药同用。 \n\n【吴克潜】曰近医多用于行血止血，如胎动下血，经行不止，小便混有鲜血，可熬膏用。 \n\n【附录】益母草性味通茺蔚子，主瘾疹，可做浴汤，捣汁服用主浮肿下水，消恶毒疔肿，乳痈丹游等毒可敷之，又服汁主治胎死腹中及产后血胀闷，滴汁入耳治耳聤。  ', NULL, NULL, '1', '益母草,充蔚子,益母', NULL, '28、益母草,充蔚子,益母', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790473, 'DD5069F8DF1C2DAC4767949A09C195B8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7684, 317, 902000427, '\n【本经原文】味苦酸，主寒湿痿痹，四肢拘急，膝痛不可屈伸，逐血气伤热火烂，堕胎，久服轻身耐老。 \n\n【产地】产我国河南一带，四川亦有出产，为山野自生之多年生草本，根入药。 \n\n【性味】味苦酸性平无毒。 \n\n【主治】牛膝为寒湿痹痿，骨节疼痛要药，走血能补，益肝肾强筋骨，痛淋浊，引诸药下行，治膝痛，能堕胎。 【别录】疗伤中少气，男子阴消，老人失溺，补中续绝，益精，利阴气，填骨髓，止白发，除脑中痛，及腰脊痛，妇人月水不调血结。 \n\n【甄权】治阴痿，补肾助十二经脉，逐恶血。 \n\n【大明】治腰膝软怯弱，破症结，排脓止痛，产后心腹痛，并血晕，落死胎。 \n\n【灵胎】舒筋行血，降气堕胎。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】牛膝误用必伤胎，经闭未久，疑似有妊者忌用，上焦药中勿用，梦遗失精，脾虚下陷，血崩不止亦忌。忌牛肉牛乳。 \n\n【附录】杜牛膝──性专走下，毫无补益，散恶血破症瘕，止痛，治淋药中宜用。 \n\n【容川】牛膝性降，因根深味苦，故能引水火下行。因根坚实，形不空，无升达之孔道，味既苦泻，故下行双足。其节如膝，能利膝胫，以其形似也。  ', NULL, NULL, '1', '牛膝', NULL, '27、牛膝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790474, '10DC8E8D6913C45160A3D97ED8F107FF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7685, 317, 902000426, '\n【本经原文】味辛平，主续绝伤，补不足，益气力肥健，汁去面皯，久服明目，轻身延年。  \n\n【产地】产朝鲜川泽及田野，我国亦有之，夏生苗，初如细丝，得地种植物而缠绕之，自绝其根，即借他物之养料以生长，子入药。  \n\n【性味】味辛甘，性平无毒。  \n\n【主治】菟丝子为补肾益精要药，主绝续伤，补不足，坚筋骨，强阴分，治茎中寒，精自出，溺有余沥，腰痛膝冷。  \n\n【甄权】治男女虚冷，添精益髓，去腰疼膝冷，消渴热中，久服去面皯，悦颜色。  \n\n【大明】补五劳七伤，治鬼交泄精，尿血，润心肺。  \n\n【灵胎】补益肝脾，接续筋骨。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肾家多火，阳强不痿，及大便燥急者，均忌，得酒良。\n\n【倪注】现在已经是属于被管制中药，因为植物保护法。  ', NULL, NULL, '1', '菟丝子', NULL, '26、菟丝子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790475, '98C24C2343EB80AEEE5D55CEC80986FF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7686, 317, 902000425, '\n【本经原文】味苦，主风寒湿痹，死肌痉疸止汗，除热消食，作煎饵，久服轻身延年，不饥。一名山精，神药经云：必欲长生服山精。  \n\n【产地】生郑山山谷。产河南浙江安徽及各地，为山间多年野生草，根细者如指，大者如拳，外微褐，肉白入药。  \n\n【性味】味甘性温无毒。 \n\n【主治】白术为健脾胃要药，功能利水去湿，和中调气，外科用托疡疮。  \n\n【别录】大风在身面，风眩头痛，眼泪出，消痰水，逐皮间风水结肿，除心下急满，霍乱吐 下不止，利腰脐间血，益津液，暖胃消谷嗜食。  \n\n【甄权】治心腹胀满，腹中冷痛，胃虚下利，多年气痢，除寒热止呕逆。  \n\n【大明】反胃利小便，主五劳七伤，补腰膝长肌肉，治妇人症瘕。  \n\n【好古】理胃益脾，补肝风虚，主舌本强，食即呕，胃脘痛，心下急痛，心下水痞，冲脉为病，气逆里急脐腹痛。  \n\n【容川】内含甘润之油质，可以滋脾之阴，外发辛香之温性，故可以畅达脾之阳，尤以浙产之油质最厚，可补脾之膏油，油不粘水，故能利水，其气香味甘而苦温，能升发，故补脾温土，使脾土之气上达，和肝气以伸脾气，为补脾之正药。  \n\n【药征】主利水也，故能治小便自利，不利，旁治身烦疼，痰饮失精，眩冒下利喜唾。  \n\n【灵胎】白术补脾补气，苍术燥湿发汗。  \n\n【用量】普通半至三钱，大剂二三两。  \n\n【禁忌】凡病属阴虚血少，精不足，内热骨蒸，口干唇燥，咳嗽吐痰，吐血鼻血，齿血，咽塞，便秘，滞下均忌，溃疡用之反生脓作痛，忌与蛤雀桃李菘菜青鱼同食。  ', NULL, NULL, '1', '白术,山精', NULL, '25、白术,山精', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790476, '44CF0CDC9567EBBC2B456E61EFD22AA6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7687, 317, 902000424, '\n【本经原文】味甘寒，主折跌绝筋，伤中逐血痹，填骨髓长肌肉，作汤除寒热积聚，除痹，生者尤良，久服轻身不老，一名地髓。 鲜生地根绞汁晒干曰干生地，大者今称大生地，细者称细生地。 \n\n【产地】生咸阳川泽。产陕西河南者良，生川泽黄土之地。根入药，根须之鲜者即鲜生地。  \n\n【性味】味甘性寒无毒。  \n\n【别录】主男子五劳七伤，女子伤中胞露下血，破恶血溺血，利大小肠，去胃中宿食，饱力断绝，补五脏内伤不足，通血脉益气力，利耳目。 \n\n【大明】助心胆气，强筋骨，长志安魂定魄，治惊悸劳力，心肺损吐血，鼻血，妇人崩中血 晕。  \n\n【元素】凉血生血，补肾水真阴，除皮肤燥，去诸湿热。  \n\n【好古】主心病掌中热痛，脾气痿蹶，嗜卧，足下热而痛。  \n\n【容川】产中州，得土深水厚之性，内含润泽之湿也。原色为黄，制后为黑，故人知地黄之能滋肾阴，不知地黄实滋脾阴，内经云脾为阴中之至阴，地黄以湿归脾，脾阴足，则肝肾自受其灌溉。其不辛温，故能益水液，滋血之源，而不能变化、以成血色。以水配火，不使壮火食气，如此气纳矣。  \n\n【药征】主治血症及水病也。 \n\n【灵胎】熟地补血，生地凉血。 \n\n【用量】普通二钱至四钱，大剂二三两。  \n\n【禁忌】凡病人脾胃弱，大便泄，产后不食或泻，及胸膈多痰，气道不利者均忌，忌铜铁及茶，得清酒麦冬良。  \n\n【吴克潜】曰现市面用药有三种，鲜生地干地黄熟地黄，一物各有其用，鲜生地多用于肺胃实热，口燥烦渴，舌苔光绛色。干地黄多用于滋养阴血，血虚内热之症。熟地黄则用于补阴 生精，扶养亏弱之虚。是故元素曰生地凉血，血热者须用。熟地微温，血衰者须用。  \n\n【王硕】曰男子多阴虚宜熟地，女子多血热宜生地。  ', NULL, NULL, '1', '地黄', NULL, '24、地黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790477, '779C05072F7FFE5AE517B9D2FCF9DF0D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7688, 317, 902000423, '\n【本经原文】味甘平，主五脏六腑寒热邪气，坚筋骨长肌肉倍力，金创肿解毒，久服轻身延年，生河西沙山及上郡。 郭璞云：今甘草蔓延生，叶似荷青黄，茎赤黄有节，节有枝。  \n\n【产地】生河西川谷。我国四川陕西出产，江苏福建亦有，日本种植颇多，茎高二三尺。  \n\n【性味】味甘性平无毒。 \n\n【主治】甘草为调合周身气血要药，功能解百毒，补脏腑，泻诸火，在上去痰止咳，在中调和脾胃，在下清热利溲，入和剂则补益，入汗剂则解肌，入凉剂则泻热，入润剂则生津，入峻剂则缓正气，制药之暴性，效益甚多，为诸药之君。  \n\n【别录】温中下气，烦满短气，伤脏咳嗽，止渴。通经脉，利气血，解百药毒，为九土之精，安和七十二种石，一千二百种草。  \n\n【甄权】主腹中冷痛，治惊痫除腹胀满，补益五脏，肾气内伤，令人不痿，主妇人血沥腰痛，凡虚而多热者加用之。  \n\n【大明】安魂定魄，补五劳七伤，一切虚损，惊悸烦闷健忘，通九窍利百脉，益精养气壮筋 骨。  \n\n【好古】吐肺痿之脓血，消五发之疮疽。  \n\n【仲醇】凡解毒必入甘草。  \n\n【吴克潜】曰九土即九州岛岛土气之精华，故能解诸毒如神，古时有炼石为丹服之者多中药石之毒，服甘草而解，故曰安和七十二种石。  \n\n【容川】味甘正入脾。守而不走，补中气，和诸药，根深四五尺，与黄耆同，但黄耆中空，属气分，是得土中之水气，甘草中实，纯得土气之厚，故深长且实，能补脾阴，益胃之阳。炙用是取其益胃，使胃气上升，如炙甘草汤。生用取其气平，如芍药甘草汤。  \n\n【倪注】仲景经方中使用甘草多处，即知道仲师之重视甘草，而现今却被西洋人购去制造成许多药品或是食物，再回销我国，实在是感叹国家之愚昧竟至于斯，我辈当以复兴中医药为职志，将中药制剂卖到国外，既造福人类又可以赚取外汇，岂非一举两得。甘草缓中，故遇排腹积水时忌用，因其能守，故不利于排水。  \n\n【药征】主治急迫，治里急急痛，旁治厥冷烦躁冲逆之症。  \n\n【灵胎】生用泻火，解毒炙用，和中益气。  \n\n【用量】普通生者五分至钱半，炙者三分至一钱，大剂一两左右。 \n\n【禁忌】凡中满人呕家酒家，诸湿肿满及胀满均忌，反$u{大戟}、$u{甘遂}、$u{芫花}、$u{海藻}，恶$u{远志}忌猪肉。  ', NULL, NULL, '1', '甘草', NULL, '23、甘草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790478, 'D33F141EA611353FBE34E5BB763B671E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 16:44:28');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7689, 317, 902000422, '\n【本经原文】味苦平，主诸暴风湿偏痹，强肾髓，杀三虫去伏尸，久服轻身益气延年。  \n\n【产地】处处有之，近以浙东产者为多，或生于暖地海滨或种植各地，藤蔓大，根似麦门冬而色白。  \n\n【主治】为清虚热润燥痰要药，主肺气咳逆，风湿偏痹益肌肤，保肺气治消渴、疗咳血。\n\n【别录】保定肺气去寒热养肌肤，利小便，冷而能补。  \n\n【甄权】肺气咳逆，喘息促急，肺痿生痈吐脓，除热气通肾，止消渴去热，中风，治湿疥，宜久服煮食之，令人肌体滑泽白净，除身上一切恶气不洁之疾。  \n\n【大明】镇心润五脏，补五劳七伤吐血，治咳嗽消痰，去风热烦闷。  \n\n【好古】主心病嗌干，心痛渴欲饮，痿躄嗜卧，足下热而痛。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】胃虚无热及泻者均忌，忌鲤鱼。  \n\n【吴克潜】曰天冬麦冬性相近，故一般方剂二药并用。仲醇曰痰之标在脾胃肺，其本在肾，若非肾家有火，炎上薄肺，煎熬津而成黏腻，则痰何自成。天冬味苦气寒，能清热保肺，下通于肾，故为消痰止咳必用要药，观此则天冬治痰乃治本元不足虚火所生之痰，而与外感咳 嗽，痰饮咳嗽，虚寒痰嗽，风火痰喘等均不相同，著名方剂如天门冬散治小儿心胸烦闷，体热咳嗽。三才封髓丹治虚火上炎，梦遗失精，滋阴养血，降心火益肾水。三才丸治气血俱虚，虚劳咳嗽。天王补心丹治心血不足，津液枯涸，健忘怔忡。 秉水阴，能滋肺以清气分。  \n\n【炮制】拣去杂质，洗净晒干即得。  ', NULL, NULL, '1', '天门冬 ,天冬 ', NULL, '22、天门冬 ,天冬 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633496178790479, '29120C97AF2D9D67F284DAF2CA31FF70', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 12:02:35', 1, 'admin', '2025-01-15 09:05:35');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7690, 317, 902000453, '\n【本经原文】味辛温，主中风入脑，头痛寒痹，筋挛缓急，金疮，妇人血闭无子。一名川芎。  \n\n【产地】产四川陜西及江南各地，为多年生草本，或自生或栽种，根为块状结节，味辛烈，入药。  \n\n【性味】味辛性温无毒。  \n\n【主治】川芎为顺气行血要药，功能行气开郁，入肝理血，上行头目，下行血海，主治头痛及妇女一切气郁血郁，心腹痛，腰脚软，破宿血，养新血，补肝散风。  \n\n【别录】除脑中冷痛，面上游风去来，目泪多涕唾，忽忽如醉，诸寒冷气，心腹坚痛，中恶 卒急肿痛，胁风痛。  \n\n【甄权】脚膝软弱，半身不遂，胞衣不下。  \n\n【大明】一切风一切气，一切劳损，一切血，补五劳，壮筋骨，调众脉，破症结宿血，养新血，吐血，鼻血，溺血，脑瘫，发背，瘰疬瘿赘痔瘘疮疥，长肉排脓，消瘀痰血。  \n\n【好古】搜肝风，补肝血，润肝燥，益肝虚。  \n\n【容川】川芎之味更辛苦于当归，得木火之性尤烈，苦而兼辛，有生血之功，质不柔润，性专走窜，故专主行心肝之血。苦者火之味也，苦而兼辛，则性温而有生血之功，苦而不辛，则性凉而专主泻血，温者阴中之阳，是风木本气，故入肝经，根又主上升故能至于巅顶，以散风寒，气滞血瘀，寒热身疼，女子经闭不通，当行血中之气。  \n\n【用量】普通三分至钱半。 \n\n【禁忌】其性疏散，不宜久服，反能损肝，畏黄连，伏雌黄。', NULL, NULL, '1', '芎䓖,川芎', NULL, '53、芎䓖,川芎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633530974302277, '24C92EF0C33B3DD97B5E85CAD184F648', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 14:24:10', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7691, 317, 902000452, '\n【本经原文】味苦寒，主解毒，杀蛊蚑，注鬼，螫毒，久服头不白轻身。又今俗名青黛。\n\n【产地】从属于大青科名蓝草者之蓝叶制出，体轻质细，药用最良，今多见于园艺。 \n\n【性味】味咸性寒无毒。  \n\n【主治】蓝实（青黛）为解散热毒要药，主散五脏郁火，治时疾热狂与大青同功，并敷热疮虫咬，头生黄水疮，治小儿丹毒。  \n\n【甄权】填骨髓，明耳目，利五脏，调六腑，通关节，治经络中结气，使人健少睡，益心力。  \n\n【苏颂】疗肿毒。  \n\n【时珍】主解班蝥，芫青，朱砂，橒鸡，砒石毒。  \n\n【备要】外敷治痈疽蛇犬毒。  \n\n【用量】普通三分至钱半。 \n\n【禁忌】凡血证非血分实热，而由阴虚内热，阳无所附，火气因空上炎，发为唾咯吐血诸证，切不可用青黛等，盖血得寒则凝，则寒热交作，胸膈或痛，愈增其病。  \n\n【附录】 蓝汁—蓝叶之汁，主一切毒，百毒药，天行热狂，游风热毒肿毒，吐衄血，金疮血闷，烦渴，女人产后血晕。 蓝淀—蓝汁中合有石灰者，主解诸毒，敷热疮，小儿秃疮热肿。其止血拔毒杀虫之功，更胜于蓝。  ', NULL, NULL, NULL, '蓝实', NULL, '52、蓝实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633530974306373, 'A0D819056F67D240930D6C9AD27FFAA5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 14:24:10', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7692, 317, 902000451, '\n【本经原文】味辛温，主五脏邪气，女子阴中寒热，痛，症瘕，血闭，绝子，久服轻身和颜色。一名万岁。 \n\n【产地】产陜西山东等地，多附生深山石壁，叶细似柏，生于地上者曰地柏，茎高数吋。 \n\n【性味】味辛性平无毒。 \n\n【主治】卷柏生用平，主破血通经，炙用性温，治肠风脱肛。 \n\n【别录】止咳逆，治脱肛，散淋结，头中风眩，痿躄，强阴益精。 \n\n【甄权】通月经，治ㄕ疰（由病死之人传染的病）鬼疰，腹痛百邪，鬼魅啼泣。 \n\n【大明】镇心，除面皯，头风，暖水脏，生用破血，炙用止血。  \n\n 【用量】普通一钱至三钱。 \n\n【禁忌】多用于止血药中，其他方剂罕用。', NULL, NULL, NULL, '卷柏', NULL, '51、卷柏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633530974306374, '8848ACD3CE4216C725AF426DF67595C9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 14:24:10', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7693, 317, 902000450, '\n      赤芝—味苦平，主胸中结，益心气，补中，增慧智，不忘，久服轻身不老，延年神仙。一名丹芝。生霍山。\n\n     黑芝—味咸平，主癃，利水道，益肾气，通九窍，聪察，久服轻身不老，延年神仙。一名元芝。生恒山。  \n\n     青芝—味酸平，主明目补肝气，安精魂，仁恕，久服轻身不老，延年神仙。一名龙芝。生太白。 \n\n     白芝—味辛平，主咳逆上气，益肺气，通利口鼻，强志意，勇悍，安魂，久服轻身不老，延年神仙。一名玉芝。生华山。\n\n     黄芝—味甘平，主心腹五邪，益脾气，安神，忠信和乐，久服轻身不老，延年神仙。一名金 芝。生嵩山。 \n\n     紫芝—味甘温，主耳聋，利关节，保神，益精气，坚筋骨，好颜色，久服轻身不老，延年神仙。一名木芝。生高夏地上，色紫形如桑。 六芝皆无毒，六月八月采。  ', NULL, NULL, NULL, '赤芝,黑芝,青芝,白芝,黄芝,紫芝', NULL, '50、赤芝,黑芝,青芝,白芝,黄芝,紫芝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633530974306375, 'CC2F50E417C2ADB25FF7BF1340FA4F57', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 14:24:10', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7694, 317, 902000448, '\n【本经原文】味辛微温，主明目目痛泪出，除痹痛，补五脏益精光，久服轻身不老。 ', NULL, NULL, '1', '析蓂子', NULL, '48、析蓂子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633530974306376, '2297B5B1EF533F2D4409F40CFB7EF7B3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 14:24:10', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7695, 317, 902000449, '\n【本经原文】味苦平主益气充肌，明目聪慧先知，久服不饥不老轻身。  \n\n【灵胎】此因其物之所能，以益人之能也，昔圣人幽赞于神明而生耆，此草中之神物也，服之则补人之心神，自能聪慧前知，食肉者鄙，不益信夫。能益智通灵。  ', NULL, NULL, '1', '蓍实', NULL, '49、蓍实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633530974306377, 'D5004F9B85F03F6AA185B1ED5727E9D4', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 14:24:10', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7696, 317, 902000447, '\n【本经原文】味苦微寒，主五脏瘀血，腹中水气，胪张留热，风寒湿痹，身体诸痛，久服轻身延年不老。 \n\n【产地】处处有之，状似蒿艾，其茎可以盖覆奄闾，故名。 \n\n【性味】味苦性微寒，无毒。 \n\n【主治】奄闾主五脏瘀血，风寒湿痹，身体诸痛，明目益气消食。 \n\n【别录】疗心下坚，隔中寒热，周痹，妇人月水不通。 \n\n【甄权】益气，主男子阴痿不起，治心腹胀满。 \n\n【大明】腰脚重痛，膀胱痛，及骨节烦痛，不下食。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】用之治扑打损伤效，罕有用于调理者。  ', NULL, NULL, '1', '奄闾子', NULL, '47、奄闾子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633530974306378, '9B8FE6FDF1E69BF4E2D22724A64CBD98', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 14:24:10', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7697, 317, 902000496, '\n【本经原文】味苦寒，主五内邪气，热中消渴，周痹，久服坚筋骨，轻身不老。\n\n【产地】处处有之，其子名枸杞，根皮名地骨皮，均入药。  \n\n【性味】味甘苦，性平，无毒。  \n\n【主治】枸杞子为滋肾养肝要药，生精润肺要药，主五内邪热，周痹风湿，坚筋骨，补精气，治虚劳，明目。  \n\n【别录】下胸胁气，客热头痛，补内伤大劳嘘吸，强阴，利大小肠。  \n\n【甄权】补精气，诸不足，易颜色，变白，明目安神。\n\n【孟铣】坚筋骨，耐老，除风去虚劳，补精气。  \n\n【好古】主心病嗌干，心痛，渴而引饮，肾病消中。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡有外邪实热，脾虚有湿及肠滑者忌。', NULL, NULL, '1', '枸杞', NULL, '96、枸杞', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909957, 'C8D6729235B7D0D28BDF730D570C7C05', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7698, 317, 902000495, '\n【本经原文】味苦寒，主五内邪气热，止涎唾，补绝伤，五痔，火创，妇人乳瘕，子藏急痛。\n\n【产地】槐树处处有之，其花与实均入药。  \n\n【性味】味苦性平，无毒。  \n\n【主治】槐花为凉血要药，主五痔肠风，解毒杀虫，凉大肠，润肝燥，治吐衄，崩中，痢疾，漏下。  \n\n【大明】主五痔，心痛，眼赤，杀腹脏虫，及皮肤风热，肠风泻血，赤白痢，并炒研服。  \n\n【灵胎】清湿火疗疮痔。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】病人虚寒作泄及阴虚血热而非实热者均忌。  \n\n【附录】槐角子即槐实，味苦性寒，无毒，主一切热，散一切结，清一切火，治五痔瘘疮（熬膏丸入谷道，日三易），邪热，妇人乳瘕，子脏急痛，补绝伤，疗火疮，阴疮湿痒，大热难产，能明目补脑，除头脑心胸间热，风眩欲倒，心头吐涎如车船上晕者。  ', NULL, NULL, '1', '槐实', NULL, '95、槐实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909958, '1065598CF590099D5EF7C7887BB5AFA6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7699, 317, 902000494, '\n【本经原文】味苦温，主疽恶创，头伤白秃，疥搔风气，安五脏，除热，久服轻身不老延年。  \n\n【产地】产于松树之脂，处处有之。 \n\n【性味】松脂味苦甘，性温。松子味甘，性微温。松花味甘，性温。松节味苦，性温。  \n\n【主治】松脂为袪风寒湿，止痛，生肌，杀虫药；治痈疽恶疮，风痹，死肌，疥癣，蛀齿。松子为祛风，滋润强壮药；治骨节风痹，气虚头眩，肺燥咳嗽，及老人虚闭。松花为驱风，镇静药；治头眩脑肿。松节为驱风，止痛药；治历节风痛，风痹，脚弱。  \n\n【别录】松脂除胃中伏热，咽干消渴，风痹死肌，炼之令白，其赤者主恶痹。  \n\n【甄权】松脂治骨节风，头眩，去死肌，变白，散水气，润五脏。  \n\n【大明】松脂除邪下气，润心肺，治耳聋。  \n\n【弘景】松节酿酒，主脚弱骨节风。  \n\n【灵胎】除湿火敷疮疡。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】燥热症者忌。  \n\n【附方】 肿毒疮疖——翠玉膏：松脂八两，铜绿二两，麻油二两，雄猪胆汁三个，先溶松脂，乃下油胆，倾入水中扯拔，每用摊贴，不须再换。 历节风痛——松节酒：松节二十斤，酒五斗，浸二十一天，每服一杯，日五六服。（外台） 头旋脑肿——三月取松花连苔如鼠尾者，切一升，以绢袋浸三升酒中，五日后，空心暖饮五杯。（普济）  \n\n肺燥咳嗽——风髓膏：松子仁一两，胡桃仁二两，蜜半两，和研膏，每服二钱。（外台）  ', NULL, NULL, NULL, '松脂', NULL, '94、松脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909959, 'F22551E811AA92B1180B95A57830D91E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7700, 317, 902000493, '\n【本经原文】味辛温，主百病，养精神和颜色，为诸药先聘通使。久服轻身不老，面生光华媚好，常如童子。又名肉桂。  \n\n【产地】产安南及我国云南两广等地，木高大，皮入药。  \n\n【性味】味辛甘，性大热，有小毒。  \n\n【主治】肉桂为温补要药，主扶火助阳，温中逐寒，能引火归元，治上热下寒，破沉寒痼冷，疗霍乱转筋，心腹诸痛，疝瘕奔豚。  \n\n【好古】补命门不足，能益火消阴。  \n\n【元素】补下焦不足，治沉寒痼冷之病，去荣卫中风寒，表虚自汗，春夏为禁药，秋冬下部腹痛。非此不能止。  \n\n【汪昂】木得桂而枯，又能抑肝风而扶脾土，脾虚恶食、湿盛泄泻，补劳通经。  \n\n【灵胎】补助阳气，驱逐阴邪。  \n\n【用量】普通三分至一钱。  \n\n【禁忌】忌生葱石脂及火炙，凡阴虚内热。液少口干者慎用，食木实或瓜类中毒，及闭口蜀 椒中毒，俱用肉桂煎汁饮之可解。 肉桂——一般生用冲服之，力更大。 禀地二之火，入血分，但仲景取其化气，非是化血。肉桂导心火下交于水，须有附子来  \n\n【炮制】拣去杂质，刮去粗皮，刷去灰尘即得。肉桂大辛大温，虽得金味，实为木火之性，故主入心肝血分，能助血之化源，桂皮尤能上行。张仲景之复脉汤，用桂枝。取其入心助火，以化血也。  \n\n【容川】肉桂比枝味更厚，气更凝聚。乃木之极致，大辛则大温，能益心火，为以木生火之专药，其实是温肝之品。肝为心之母，虚则补其母也，心肝皆司血分，故肉桂又为温血之要 药，仲景用肾气丸，是接引心肝之火使之下归于肾。  \n\n【倪注】一般桂枝多用于动脉有循环问题，能行阳达表。  \n\n【附录】桂心主补阳活血，治一切风气，补五劳七伤，通九窍利关节，益精明目，暖腰膝，破痃癖症瘕，消瘀血治风痹骨节挛缩，续筋骨，生肌肉。  \n\n【日华】主九种心痛，腹内冷气痛不可忍，咳逆结气雍塞，脚痹不仁，止下利，杀三虫，治  \n鼻中息肉，破血通利月闭，胎衣不下。  \n\n【甄权】主引血化汗化脓，内托痈疽痘疮，治噎膈满腹。  ', NULL, NULL, NULL, '菌桂,小桂', NULL, '93、菌桂,小桂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909960, 'C868AAD22CB2562D136A25524204B548', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7701, 317, 902000492, '\n【本经原文】味辛温，主上气咳逆。结气喉痹吐吸，利关节，补中益气，久服通神轻身不老。一名肉桂，一名桂枝，一名桂心。 桂之供药有两种，一曰菌桂，又称小桂，其皮为肉桂，或称筒桂：一曰牡桂，又称大桂，或单称桂，其皮为官桂，其枝为桂枝。  \n\n【产地】产安南及我国云南两广等地。  \n\n【性味】味辛甘，性温无毒。 \n\n【主治】桂枝为发表解肌要药。主温经通脉，表虚中风，治手足痛风，伤寒头痛，无汗能发，有汗能止，行肺气，散寒邪，调和营卫，横通肢节。  \n\n【别录】心痛胁痛胁风，温经通脉，止烦出汗。  \n\n【甄权】去冷风疼痛。  \n\n【丹溪】横行手臂治痛风。 \n\n【元素】去伤风头痛，开肌理，解表发汗，去皮肤风湿。  \n\n【容川】色赤味辛，入心肝助火，但桂枝实因苓泽之利水，方能入水以化气，可以导心火以下交于水，故多用之以降冲逆之气，加入补血药中，因而能温通血脉，桂枝能散四肢，质较坚实，故桂枝能兼走筋骨。味辛又得土之气，故能散血脉肌肉中之风寒。  \n\n【药征】主治冲逆也，旁治奔豚头痛，发热恶风，汗出身痛。  \n\n【用量】普通三分至钱半。  \n\n【禁忌】凡阴虚火炎，温病大热，喉症血症均忌。  \n\n【倪注】桂枝为古今皆用之要药，治疗甚广，与麻黄柴胡荆芥防风生姜葱白等同用，治风寒束表，与桑枝附子牛膝威灵仙茯苓防己等同用，治关节疼痛。与白芥子厚朴杏仁半夏等同用，治上气咳逆。与白芍同用解肌和中，与葛根同用发汗退热，伤寒论中使用最多的就是桂枝了。  \n\n【炮制】拣去杂质。刮去粗皮，刷去灰尘即得。  ', NULL, NULL, '1', '桂枝,桂,大桂,牡桂', NULL, '92、桂枝,桂,大桂,牡桂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909961, 'DDFE74BEE62AFE7FF3EF8999B5A8A4B5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7702, 317, 902000491, '\n【本经原文】味苦平，主久咳上气，伤中虚羸，女子阴蚀漏下，赤白沃。\n\n【产地】今人已不识此物，至为可惜。  ', NULL, NULL, NULL, '淮木', NULL, '91、淮木', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909962, 'DBEDB459812D89915450AC2B18AC7D3E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7703, 317, 902000490, '\n【本经原文】味苦，主胸胁下痛邪气腹间寒热，阴痹，久服轻身益气耐老。因方药无人用，今无人识者。 ', NULL, NULL, NULL, '屈草', NULL, '90、屈草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909963, 'C9B2FFE780DE19498792044ECD76E33D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7704, 317, 902000489, '\n【本经原文】味苦微温，主风寒湿痹，身重四肢疼酸。寒邪历节痛。  \n\n【产地】生蓝田，今俗亦绝耳。', NULL, NULL, NULL, '别羁', NULL, '89、别羁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909964, '447CFA7830241274826F80FCF69A80E3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7705, 317, 902000488, '\n【本经原文】味甘温，主大风邪气，湿痹寒痛。久服轻身益寿耐老，一名冬葵子。  \n\n【产地】处处有之。 \n\n【性味】冬葵子及叶，根味皆甘，性滑。  \n\n【甄权】冬葵苗煮汁服利小肠，治时行黄病，干叶为末及烧灰服治金疮出血。  \n\n【思邈】此脾之菜也，宜脾，利胃气，滑大肠。\n\n【用量】一钱至三钱，大剂一两。  \n\n【附方】 肉锥怪疾——手足忽长倒生肉刺，痛不可忍，但食冬葵叶即可。 消中尿多——尿崩，日夜尿七八升。冬葵根浓煎。每日平旦服二升。 妊妇下血——葵子水煎服，日三。 妊妇水肿——小便不利，身重，恶寒，起即头眩。冬葵子，茯苓等分为末，饮服方寸匕，日三，小便利即愈。 胎死腹中，葵子为末，酒服方寸匕，口噤不开者，灌之即生  ', NULL, NULL, NULL, '姑活,冬葵子', NULL, '88、姑活,冬葵子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909965, '0DBC6DD9BFBFB382FA0D83DA04929131', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7706, 317, 902000487, '\n【本经原文】味甘寒，主五藏邪气，风寒湿痹，益气，补脑髓。坚筋骨。久服耳目聪明，不饥不老增寿，乃巨胜之苗也。今称胡麻，此植物叶名青蘘，种子名胡麻。 \n\n【产地】处处有之，昔从胡来，故曰胡麻，今名脂麻有黑白黄三种，其大者曰巨胜子，入药。\n\n【性味】青蘘性味如上，胡麻味甘性平无毒。 \n\n【主治】胡麻主长肌肉，补虚羸，滋润五脏，利大小肠，其油亦作解毒用。 \n\n【别录】胡麻坚筋骨，明耳目，耐饥渴。疗金疮止痛，及伤寒温疟，大吐后虚热羸困。 \n\n【日华】补中养气，润养五脏，补肺气，止心惊，利太小肠，耐寒暑，逐风湿气，游风头风，治劳气，产后羸困，催生落胞，细研涂发令长，白蜜蒸饵治百病。 \n\n【廷飞】炒食不食，风病人久食，则步履端正，语言不蹇。 \n\n【苏颂】生嚼涂小儿头疮，煎汤浴恶疮，妇女阴疮大效。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】多用为服食，少以入药，如入药，大便溏泄者忌之。 \n\n【附录】麻油主利大肠，产妇胞衣不下。  \n\n 【别录】天行热闷，膈内热结，服一合，取利为度。 \n\n【藏器】下三焦热毒气，通大小肠，治蚘心痛，敷一切恶疮疥癣，杀一切虫，取一合和鸡子二个，芒硝一两，搅服，少时即泻下热毒。 \n\n【孟铣】士良曰外科熬膏多用之，以其能凉血解毒，止毒生肌也，虞鍑曰生用消疮毒，熟用利肠胃。  \n\n **胡麻**：胡麻历史上被称为胡麻，这个名称体现了它的外来属性，“胡”字前缀在中国古代常用以指代西方或外来的事物。\n\n **芝麻**：芝麻古代同样被称作胡麻，但后来为了避讳“胡”字，改名为芝麻。这个名字也与其作为油料作物的特性有关。', NULL, NULL, '1', '胡麻,青蘘', NULL, '87、胡麻,青蘘', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909966, '23C69EAB5FD7A73BDBC56D543C6BC401', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7707, 317, 902000486, '\n【本经原文】味甘辛，主解百毒，杀百老物殃鬼，辟温疾障邪气毒蛊，入口皆吐出，中恶腹痛，时气毒疠，头痛，寒热，风肿诸毒，喉痛口疮，久服不夭。  \n\n 【产地】产益州山谷中，今四川陕西淮南溪涧阴地皆有之，根紫黑色、体轻，入药。 \n\n【性味】味甘苦，性平无毒。 \n\n【主治】升麻为升阳散毒要药，功能升清气，散浊邪，治斑疹疮毒，时气寒热，阳明胃经风邪。 \n\n【甄权】小儿惊痫，热拥不通，疗痈，豌豆疮，水煎绵沾拭疮上。 \n\n【大明】安魂定魄，鬼附啼泣，疳疮游风肿毒。 \n\n【元素】治阳明头痛，补脾胃，去皮肤风邪，解肌肉间风热，疗肺痿咳唾脓血，能发浮汗。\n\n【好古】牙根浮烂恶臭，太阳鼻衄，为疮家圣药。 \n\n【用量】普通八分至一钱半。 \n\n【禁忌】凡吐衄多痰，阴虚火动，气逆呕吐，惊悸怔忡癫狂等病，均忌。误用多致危。  \n\n 【容川】升麻味甘，能升脾胃之气，其能升之理则因根中有孔道，引水气上达于苗，故性主升，然无四散之性，因为是根之性，升麻根大于苗，故根之得气也厚，故专取其根。  ', NULL, NULL, '1', '升麻', NULL, '86、升麻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909967, '2A96C58C2362E804F4888CC4ECCB37B8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7708, 317, 902000485, '\n【本经原文】味苦平，主金创止血，逐痛出剌，除风痹内寒，久服轻身耐老。 \n\n【产地】处处有之，为一年生草本植物，因其性走而不守，虽有王命，不能留行，故名之。\n\n【性味】味苦性平，无毒 \n\n【主治】王不留行为行血要药，走血分通血脉，行月经，下乳汁，催生定痛，治金疮。 \n\n【别录】主金疮，止血逐痛，出刺。除风痹，内塞，止心烦，鼻衄，痈疽恶疮瘘乳，妇人难产。 \n\n【甄权】治风毒，通血脉。 \n\n【元素】下乳汁。  \n\n【日华】游风风疹，妇人经血不匀，发背。\n\n【用量】普通一钱至二钱。  \n\n【禁忌】走而不守，血症慎用，孕妇忌之。 民间方治妇人乳少，因气郁者：王不留行，穿山甲，炒龙骨，瞿麦穗，麦门冬等分为末，每服一钱，热酒调之，后食猪蹄汤。此名涌泉汤。 ', NULL, NULL, NULL, '王不留行', NULL, '85、王不留行', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909968, 'CA0F907C7564CBDB0334EFFF662CFABC', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7709, 317, 902000484, '\n【本经原文】味辛温，主泄利，肠澼，杀虫蛊毒，去邪恶结气，止痛除热，主见鬼精物，多食令人狂走，久服轻身通神明。  \n\n【产地】处处有之。  \n\n【性味】味辛微苦，性温。  \n\n【主治】云实为止泻，截疟，杀虫要药。  \n\n【苏颂】治疟多用。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】寒利者禁忌。', NULL, NULL, NULL, '云实', NULL, '84、云实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909969, '695FCB30C5429C8746DA4245B691C959', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7710, 317, 902000483, '\n【本经原文】味苦平，主风湿痹历节痛，惊痫吐舌，悸气贼风，鼠瘘痈肿。今名鹿衔草。  \n\n【产地】产我国陕西河南，叶似茺蔚。 \n\n【性味】味苦性平无毒。 \n\n【主治】鹿衔草主治风湿痹，逐水。益筋节，疗痿躄，婴儿先天不足。\n\n 【别录】暴症，逐水。疗痿躄。 \n\n【藏器】妇人服之，绝产无子。 \n\n【用量】普通一二钱。 \n\n【禁忌】待孕之妇忌服，绝产。  ', NULL, NULL, NULL, '鹿衔草,薇衔', NULL, '83、鹿衔草,薇衔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909970, '2F81DF11CC27861AEFDBCF10B761C16C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7711, 317, 902000482, '\n【本经原文】味苦微寒，主心腹邪气，小便不利，淋闭，风湿，鬼注，恶毒，久服补虚羸， 轻身，耳目聪明，延年。一名龙须草。  \n\n【产地】生长泽地，产山西河南一带，茎以九节多珠者良。  \n\n【性味】味苦性微寒，无毒。 \n\n【主治】龙须草为泻心经之热，通利小肠膀胱要药，主治小便不通，小便带血；茎中热痛及淋闭。 \n\n【别录】补内虚不足痞满，身无润泽。出汗。除茎中热痛，疗疣虫肿不消食。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】小便不通不因于热者勿用。  ', NULL, NULL, NULL, '石龙刍,龙须草', NULL, '82、石龙刍,龙须草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909971, 'B414BC259B5E5F75A413EAAAB272D7D3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7712, 317, 902000481, '\n【本经原文】味辛温，主鬼物百精蛊毒，疫疾邪恶气，温疟，久服强悍轻身。 \n\n【产地】生山东陕西甘肃，如细辛微粗而长，徐长卿乃人名，尝以此药治邪病，人遂以名之。\n\n【性味】味辛性温无毒。  \n\n 【主治】徐长卿主辟邪恶，近时用者不多，功与鬼督邮相近。 \n\n【别录】鬼疰精物邪恶气，杀百虫蛊毒老魅注易，立走啼哭。悲伤恍惚。  \n\n 【用量】普通八分至钱半。 \n\n【禁忌】治鬼之药多有毒。用之宜慎。  ', NULL, NULL, '1', '徐长卿', NULL, '81、徐长卿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909972, '564B179A1D27671FAA439C14FD503104', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7713, 317, 902000480, '\n【本经原文】味苦平，主蛇虺蜂藌猘狗蔡肉蛊毒。  ', NULL, NULL, NULL, '白兔藿', NULL, '80、白兔藿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909973, '792945D56A5D81547542FEE0F89061CC', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7714, 317, 902000479, '\n【本经原文】味苦微寒，主血积，惊气，除寒热，补中益肺气，久服利人。  \n\n【产地】产北方沙地，故又号北沙参，叶椭圆有锯齿，根粗大，似参而质松，产南方者为南沙参，体虚力逊。  \n\n【性味】味甘苦，性微寒，无毒。  \n\n【主治】沙参为清补肺气要药，功能清肺中之热，祛肺中之痰。补肺中之气，治久咳，退邪 热，安神，南沙参力减。  \n\n【别录】疗胸痹，心腹结热，邪气头痛，皮间邪热，安五脏，久服利人，又云主头肿痛，益气长肌肉。  \n\n【甄权】去皮肌浮风，疝气下坠。治常欲眠。养肝气，宣五脏风气。 \n\n【大明】补虚止惊烦，益心肺：并一切恶疮疥癣及身痒，排脓消肿毒。  \n\n【灵胎】补中益气。  \n\n【元素】肺寒者用人参，肺热者用沙参，故举凡属肺家有虚热。嗽痰咳血，潮热似痨症，用之甚佳，如属风寒初客肺，浊痰未成，此时宜解表为先。  ', NULL, NULL, '1', '沙参', NULL, '79、沙参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909974, '710A1CE8FC766391D5C9C3B22314BD31', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7715, 317, 902000478, '\n【本经原文】味辛微温，主胸胁下逆气，温中风，入脑户，头肿痛，多涕泪出，久服益精明目，轻身。一名杜衡。  \n\n【产地】山中阴地之多年生草，叶做心脏形，似细辛，惟经冬不凋，与细辛异，根入药。  \n\n【性味】味辛，性温，无毒。 \n\n【主治】杜衡主治发热头痛，能催吐，近世用者不多。  \n\n【甄权】止气奔喘促，消痰饮，破留血，项间瘿瘤之疾。  \n\n【括要】下气杀虫，利小便，发汗通经，将根末吹入鼻中，能做轻嚏。  \n\n【用量】普通五分至一钱。 \n\n【禁忌】使人呕恶，不宜多用。  ', NULL, NULL, NULL, '杜若,杜衡', NULL, '78、杜若,杜衡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909975, 'F7F3798E357F3E30E02A7CB70385CA12', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7716, 317, 902000477, '\n【本经原文】味苦平，主风湿寒热，邪气热结黄疸，久服轻身，益气耐老，面白悦。今名茵陈蒿。  \n\n【产地】生于山野或河岸沙石之多年生草，其叶状似青蒿而背白，茎叶枯，则由陈茎再生，故名茵陈。  \n\n【性味】味苦性平微寒，无毒。  \n\n【主治】茵陈蒿为黄疸要药，功能除湿利尿，主治脾胃湿热，天行时热，周身发黄，以此为君。  \n\n【别录】治通身发黄，小便不利，除头热，去伏瘕。  \n\n【藏器】通关节，去滞热，伤寒用之。  \n\n【大明】石茵陈治天行时疾热狂，头痛头旋，风眼疼痛，瘴疟，女人症瘕，并闪损乏绝。  \n\n【药征】主治发黄也。  ', NULL, NULL, '1', '茵陈蒿', NULL, '77、茵陈蒿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909976, '605545DD8BB76BADDD762A56661311DD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7717, 317, 902000476, '\n【本经原文】味苦平，主大热，火创身热烦邪恶气华，主女人漏下赤白，轻身明目。  \n\n【产地】多自生于高山上，庭中盆景俱可栽种，叶入药。 \n\n【性味】味苦甘，性寒。无毒。 \n\n【主治】景天主治肿疡蜂螫，能吸脓拔毒。消毒止血药，火疮，丹毒，风疹、狂热赤眼，脑 膜炎头痛。 \n\n【括要】治虫毒蜂螫，傅肿伤，吸脓拔毒。 \n\n【甄权】风疹恶疮，小儿丹毒及发热。 \n\n【弘景】疗金疮止血。煎水浴小儿，去烦热惊风。 \n\n【用量】普通一钱，外用无定量。 \n\n【禁忌】为外用药，少内服。  ', NULL, NULL, '1', '景天', NULL, '76、景天', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909977, '38EF5D85A676BF86496D88D5BA4EF3CB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7718, 317, 902000475, '\n【本经原文】味苦寒，主膀胱热，利小便，补中益精气，久服耳聪目明，轻身耐老。 \n\n【产地】生田野间，处处有之，子落则老茎可以为少帚，故又名落帚。 \n\n【性味】味苦性寒。无毒。 \n\n【主治】地肤子为利小便要药，主膀胱热，通利五淋，强阴益精，治下焦虚而有热良。 \n\n【别录】主皮肤中热气，使人润泽，散恶疮疝瘕，强阴。 \n\n【甄权】治阴卵颓疾；去风热，可做汤沐浴，与阳起石同服，主丈夫阴痿不起，补气益力。\n\n【日华】治客热丹肿。 \n\n【用量】普通一钱至二三钱。 \n\n【禁忌】老人小便短而频数，是膀胱气化不足，小肠火偏弱也，法当补小肠火；如乌药艾叶，不可独用地肤子。  \n\n【附录】地肤子煎——煎水洗目，去热暗雀盲涩痛，煎水服利小便诸淋，解恶疮。', NULL, NULL, '1', '地肤子', NULL, '75、地肤子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909978, 'A1E29F4AFF17224B0F64F260D710E66C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7719, 317, 902000474, '\n【本经原文】味苦平，主妇人阴中肿痛，男子阴痿湿痒，除痹气，利关节，癫痫，恶创，久服轻身。  \n\n【产地】产于海滨或下湿地。我国江北及关外皆有之。  \n\n【性味】味辛苦，性温无毒。 \n\n【主治】蛇床子为疏风去湿强阳益阴要药，主治下焦留湿，男子阳痿湿痒，女人阴肿痛痒。恶疮湿癣。外用煎汤浴良。 \n\n【别录】温中下气，令妇人子脏热。男子阴强，久服令人有子。 \n\n【甄权】治男子女人虚湿痹，毒风屌痛。去男子腰痛，浴男子阴，去风冷，大益阳事。 \n\n【大明】暖丈夫阳气，女人阴气，治腰胯酸疼，四肢顽痹，缩小便，去阴汗，湿癣，齿痛，赤白带下。小儿惊痫，扑损瘀血，煎汤浴大风身痒。  \n\n 【灵胎】专治下体湿毒之病。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肾家有火，下部有热。及阳易举者，虽有湿，宜酙酌用之。恶丹皮，巴豆，贝母，伏硫磺。  ', NULL, NULL, '1', '蛇床子', NULL, '74、蛇床子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909979, '5B1BA79F23944BF18ADD65E8DC32A3D0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7720, 317, 902000473, '\n【本经原文】味辛平，主利水道，杀蛊毒，辟不祥，久服益气，轻身不老通神明。  \n\n【性味】味辛性平无毒。 \n\n【主治】兰草为消炎除恶荡涤肠胃要药，功能推陈致新，生津止渴，治消渴，辟秽毒。  \n\n【别录】除胸中痰癖。 \n\n【东垣】其气清香，生津止渴，润肌肉，治消渴、胆痹。 \n\n【元素】辛平能散肺气郁结，芬芳能去胃气郁滞。 \n\n【汪机】兰草走气分，故能利水道除痰癖，杀蛊辟恶而为消渴良药。与泽兰同走血分，能消水肿，除痈毒，除症破瘀，为妇人要药。  \n\n【好古】消痈肿。调月经，煎水解中牛马毒。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】无。 我国药物同名甚多。因兰草又名省头草。今药房所谓佩兰，其名亦省头草，解释为籣草为较老草，佩兰为较嫩草，同为一株。  ', NULL, NULL, '1', '兰草 ', NULL, '73、兰草 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909980, '95B6953634E8D3848795EB9A782F45A0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7721, 317, 902000472, '\n【本经原文】味甘温，主益气，去面皯黑，色媚好，其根味辛，主腹中寒热邪气，利小便，久服不饥轻身。今名旋覆花。  \n\n【产地】为野生多年蔓草，处处有，花及根供药用。\n\n【性味】旋花之花，根，茎，叶俱甘滑微苦，性温。  \n\n【主治】旋花为固精强壮药并可合金疮，补劳损。  \n\n【别录】续筋骨，合金疮。 太乙金锁丹：功于秘精益髓，龙骨，覆盆子各五两，莲花蕊四两，栀子花三两，芡实米100 粒，共为末，另以金樱子200 枚，去皮臼杵捣烂，水七升煮浓汁一升，加药粉杵为丸梧子大，每空心盐酒服下30 丸，服至百日，极效。  \n\n【用量】普通五分至一二钱。  \n\n【禁忌】无。 \n\n【容川】旋覆花味微咸，花黄色，滴露而生，得金之气多，得水之气少，故润肺而利金降痰。  ', NULL, NULL, '1', '旋覆花,旋华 ', NULL, '72、旋覆花,旋华 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909981, 'DC6D30A7A7CB8C8E01ED35746A0FE15B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7722, 317, 902000471, '\n【本经原文】味酸温，主益气，咳逆上气，劳伤羸酸，补不足，强阴，益男子精。  \n\n【产地】生齐山山谷。产高丽及我国山东陕西一带，江浙间亦有，有南五味北五味黑五味诸种，就中以北五味最良，子赤黑色，含有滋润，入药。 \n\n【性味】味酸（皮甘肉酸核辛苦，都具咸味，五味俱备）性温无毒。 \n\n【主治】五味子为肺虚咳逆上气要药，主敛肺滋肾，祛痰止咳，生津止渴，敛汗退热，治劳伤，补不足。 \n\n【别录】养五脏，除热，生阴中肌。 \n\n【甄权】治中下气，止呕逆，补虚劳，令人体悦泽。 \n\n【大明】明目，暖水脏，壮筋骨，治风，消食，反胃，霍乱转筋，痃癖，奔豚冷气，消水肿，心腹气胀，止渴除烦热，解酒毒。 \n\n【好古】治喘咳逆，壮水镇阳。 \n\n【容川】五味子酸敛肝木，得金收之性，使木气不上逆，则水火二者皆不上冲于肺，其味酸而质润，囊大而中空，有肺中空虚之象，又生于叶间，其性轻浮，故专攻敛肺生津。这是药能敛肝故能敛肺也。性极沉。 \n\n【药征】主治咳而冒者也。 \n\n【灵胎】敛肺补肾。 \n\n【用量】普通五分至一钱。大剂倍用。  \n\n【禁忌】咳初起脉数，有实火，及肝家有动气，肺气有实热痧疹初发，及一切停饮，均忌。五味子本兼滋补及收敛之长，故祛痰止咳治肺气虚而似实者，效倍之。东垣曰酸以收逆气，肺寒气逆宜与干姜同治之，又五味收肺气，乃火热必用之药，故治咳嗽，有痰加半夏，喘加阿胶。丹溪曰五味大能收肺气，宜其有补肾之功，收肺气即是除热，补肾即是暖水脏，故乃火热嗽必用之药，黄昏嗽乃火气浮入肺中，不宜用凉药，宜五味子敛而降之。  ', NULL, NULL, NULL, '五味子', NULL, '71、五味子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909982, 'A3AA93C550FC23278A010309B2001F2C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7723, 317, 902000470, '\n【本经原文】味苦平，主骨节热，胫重酸疼，久服令人身轻。 \n\n【产地】陶弘景曰处处有之，极似苦芙，叶多缺刻，叶下茎多有皮起。 \n\n【性味】飞廉根及花味苦，性平。 \n\n【主治】飞廉花根为去风湿止痛活血药，能下乳汁及杀虫。\n\n 【别录】头眩顶重，皮间邪气，如蜂螫针剌，鱼子细起，热疮，痈疽，痔，湿痹，止风邪咳嗽，下乳汁，可煮、可干用。\n\n 【苏敬】主留血，疗疳蚀，杀虫。 \n\n【萧炳】小儿疳痢，为散水服，大效。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】里有寒，又兼下痢者禁用。  ', NULL, NULL, '1', '飞廉', NULL, '70、飞廉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909983, '4BCD121BBBE118466D7D450DF64750A3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7724, 317, 902000469, '\n【本经原文】味苦寒，主寒湿，风痹，黄疸，补中，现名茜草。 \n\n【产地】生山谷中，为多年生蔓草，亦可种植根形如圆柱，色红褐入药。 \n\n【性味】味酸咸，性寒无毒。 \n\n【主治】茜草为凉血通经要药，主吐血下血，月经不通，月经不止，治骨节风痛，折跌损伤，凉无病之血，行已伤之血。 \n\n【别录】止血内崩，下血，膀胱不足，踒跌，蛊毒，久服益精气，可以染绛，又苗根主痹及热中，伤跌折。 \n\n【甄权】治六极伤，心肺吐血，泻血。 \n\n【大明】止鼻洪尿血，产后血运，月经不止，带下，扑损瘀血，泄精，痔瘘疮节，排脓，酒 煎服。 \n\n【用量】普通一钱至二钱。  \n\n【禁忌】病人虽见血证，若加泄泻，饮食不进者忌。 茜草一名血见愁，其理血之效可知，俗方用治女子经水不通。以一两煎酒服之。仲醇曰治疸，此治因蓄血而发黄的疸，不专于湿热者也。 黑发方：茜根一斤，生地三斤，加水熬成膏，每日酒服半匙，一月发尽黑。  \n\n【容川】色赤味苦，根长，故下行之力必重，专能降泄行血。 ', NULL, NULL, NULL, '茜根 ', NULL, '69、茜根 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909984, 'E59791AB267D38DEC31F125BFDD037F0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7725, 317, 902000468, '\n【本经原文】味苦微寒，主心腹邪气，肠鸣幽幽如走水，寒热积聚，破症除瘕，止烦满益气。  \n\n【产地】产陕西一带，今各处俱有之，叶对生，作心脏形，根紫赤色，入药。  \n\n【性味】味苦性微寒，无毒。 \n\n【主治】丹参为通经要药，功能活血调经，治心腹邪气，寒热积聚，宿血恶露。  \n\n【别录】养血，去心腹痛疾，结气，腰脊强，脚痹，除风邪留热。  \n\n【大明】养神定志，通利关脉，治冷热劳，骨结疼痛。四肢不遂，头痛赤眼，热温狂闷，破 宿血，生新血，安生胎，落死胎，止崩带，调月经，血邪心烦，恶疮疥癣瘿赘，一切肿毒。  \n\n【纲目】活血通心包络，治疝痛。  \n\n【灵胎】养血消瘀。  \n\n【用量】普通二钱至三四钱，大剂一两。  \n\n【禁忌】孕妇无故忌，畏咸水，反藜芦。 丹参为女子调经良药，故有一味丹参功兼四物之称，产后养血去瘀，能入心养血，故天王补心丹中用此味治劳心过度，神志不宁，烦热健忘，怔忡。又言丹参入心又曰赤参。  ', NULL, NULL, '1', '丹参', NULL, '68、丹参', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909985, '46B3E5DB0D9B0A395DF0E26EB7D5F0C4', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7726, 317, 902000467, '\n【本经原文】味咸平，主青盲目淫，肤赤白膜，眼赤痛泪出，久服益精光。 \n\n【产地】山野自生之草本植物，产陕西山西一带，今处处可移植，与草决明为截然二种。\n\n【性味】味甘苦咸，性平。 \n\n【主治】决明子为泻肝明目要药，能补肝虚泻肝经风热，主头风头痛，治一切眼病。  \n【别录】疗唇口青。  \n\n【甄权】治肝热，风泪赤眼，每旦取一匙洗净，空心吞之，百日后夜见物光。 \n\n【日华】助肝气益精，以水调末涂肿毒，治太阳穴头痛，又贴胸心止鼻洪，作枕头治头风明目。  \n\n【灵胎】明目益精。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】恶麻仁，疗目疾外，其他用者鲜，惟外治可以疗蛇伤虫刺。  ', NULL, NULL, '1', '决明子', NULL, '67、决明子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909986, 'D3F6E1B03056E46BAD8493B456D23AC8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7727, 317, 902000466, '\n【本经原文】味甘寒，主瘀血，血瘕欲死，下血止血，利小便，久服轻身耐老。 \n\n【产地】产平原川泽，处处有之，纲目属湿草类。 \n\n【性味】味甘苦性平无毒。 \n\n【主治】天名精主治瘀血症瘕，诸毒疔肿，破血生肌杀虫，内外皆可用。 \n\n【别录】除小虫去痹，除胸中结热，止烦渴，逐水，大吐下。 \n\n【唐本】破血生肌，止鼻衄，杀三虫，除诸毒肿疔疮瘘痔金疮内射，身痒瘾疹不止者，皆之立已。 【注】血瘕，留着肠胃之外及少腹间，下有积气，坚牢如石，女子多因经行未尽，饮食过度，血留经络而得之，治法不一。 \n\n【用量】普通一二钱。 \n\n【禁忌】时珍曰有小毒，生汁吐人。  ', NULL, NULL, '1', '天名精', NULL, '66、天名精', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909987, 'B2E8EFCE325A23B670657899609ECF80', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7728, 317, 902000465, '\n【本经原文】味酸温，主痈疽恶创，结肉跌筋，败创热气，阴蚀不瘳，利关节。 \n\n【产地】处处有之，亦名蔷薇，茎多刺，花红色，亦有白色黄色者，子即营实，入药。  \n\n【性味】味酸，性温，无毒。  \n\n【主治】营实主痈疽，下停水。 \n\n【效用】营实为清热解毒要药，治痈疽恶疮，热毒阴蚀，蔷薇根能清热生肌，缩尿。  \n\n【别录】蔷薇根主泄痢腹痛、五脏客热，除邪逆气，疽癞诸恶疮，金疮伤打，生肉复肌。  \n\n【括要】口舌縻烂，蔷薇根煮汁温含，口疮日久，延及胸前生疮，三年以上不愈者，用此效，杨梅疮筋骨毒痛，取根皮煮汁多饮效，下疳用黄花蔷薇叶焙研洗之敷之良。  \n\n【用量】普通一二钱。 \n\n【禁忌】用以配大黄，行水之效甚著，普通方药罕用之。 ', NULL, NULL, '1', '营实', NULL, '65、营实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909988, 'BD073894A04274F55443EC75BFFD691B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7729, 317, 902000464, '\n【本经原文】味苦咸寒，主皮肤热，恶创，疽痔，湿痹，下乳汁，久服轻身益气，耳聪目明，不老延年。  \n\n【产地】生于向阳之地之草木植物，秋后则草枯而变黑，异乎他草，根苗皆入药。 \n\n【性味】味苦咸，性寒，无毒。 \n\n【主治】漏芦为泄热解毒要药，主治恶疮热毒，湿痹，扑损，能排脓止血，通经脉。 \n\n【别录】止遗漏，热气疮痒如麻豆，可作浴汤。 \n\n【大明】通小肠，泄精尿血，肠风，赤眼，小儿壮热，扑损续筋骨，乳痈瘰疠金疮，止血排脓，补血长肉，通经脉。 【括要】下乳汁，消热毒，排脓止血生肌杀虫，能预解时行痘疹毒，取其寒胜热，又入阳明故也，无则以山栀取代之。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】妊娠禁用，疮疡阴证平塌不起发者，真气虚也，法当内塞，漏芦苦寒，非所宜投。  ', NULL, NULL, '1', '漏芦', NULL, '64、漏芦', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909989, '340856813F8EB6742BB9D67B8A4FF8CD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7730, 317, 902000463, '\n【本经原文】味苦微温，主伤寒，补不足，金疮痈伤，折跌续筋骨，妇人乳难，久服益气力。\n\n【产地】产我国山西陕西四川一带，为原野自生多年生草，其根细长，作赤黄色，入药。 \n\n【性味】味苦，性微温，无毒。 \n\n【主治】续断为补益筋骨要药，主伤中，腰脊痛，折跌续筋骨，疮痈止痛生肌，破瘀生新，补肝肾，安胎气，并治产后诸病。 \n\n【别录】妇人崩中漏血。金疮血内漏，止痛生肌肉，及腕伤恶血腹痛，关节缓急。 \n\n【甄权】去诸温毒，通宣血脉。助气补五劳七伤，破症结瘀血，消肿毒，肠风痔瘘乳痈瘰疬，妇人产后一切病，胎漏，子宫冷，面黄虚肿，缩小便，止泄精尿血。 \n\n【容川】此物多筋，故治绝伤，因其筋象骨节，故主接筋骨；去骨节间之风寒。 \n\n【灵胎】补益劳伤，强续筋骨。 \n\n【用量】普通二钱至三四钱。 \n\n【禁忌】禁与苦寒药治血病，及大辛热药用于胎前，又气味颇劣，颇不宜于胃，恶雷丸。 此药多用于金疮折跌，现多用于妇女胎产良药，因其补益筋骨，破瘀生新。  \n\n【仲醇】欲行血理伤，当与当归牛膝肉桂延胡索同用，欲止血疗崩中补不足，则与白胶阿胶地黄麦冬杜仲人参山茱萸杞子黄耆五味同用，欲安胎则与凉血补血顺气药同用，欲疗金疮，则与金疮药同用。  ', NULL, NULL, '1', '续断', NULL, '63、续断', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909990, 'D39C2446AC231DF2195A13FD0CB121CD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7731, 317, 902000462, '\n【本经原文】味甘平，主五脏心下邪气，口中烂臭，坚齿明目聪耳，久服轻身耐老。\n\n 【产地】香蒲为生于池沼之宿根草，处处有之。 \n\n【性味】味甘，性平。 时医多用蒲黄，鲜少用香蒲。', NULL, NULL, NULL, '香蒲', NULL, '62、香蒲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909991, '514E0E7F150B31C11B852254394A1DBA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7732, 317, 902000461, '\n【本经原文】味甘平，主心腹膀胱寒热，利小便，止血消瘀血，久服轻身，益气力延年神仙。\n\n【产地】香蒲为生于池沼之宿根草，处处有之，蒲黄乃蒲花之花粉，入药。 \n\n【性味】味甘辛，性平，无毒。 \n\n【主治】蒲黄为凉血活血散结除热要药，生用消瘀通经，疗扑打损伤，炒黑用止血止崩，止带止遗。 \n\n【甄权】治痢血鼻衄，吐血，尿血，泻血，利水道，通经络，止女子崩中。 \n\n【大明】妇人带下，月侯不匀，血气心腹痛，妊妇下血，坠眙，血运，血症，儿枕气痛，颠扑血闷，排脓，疮疖，游风肿毒，下乳汁，止泄精。 \n\n【用量】普通七分至二钱。 \n\n【禁忌】一切劳伤发热，阴虚内热，无瘀血者忌。 蒲黄配合五灵脂，治产后腹痛，产后血晕，不省人事，亦治妇人痛经，单用炒黑，止一切血均效。  \n', NULL, NULL, '1', '蒲黄', NULL, '61、蒲黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909992, '5E10834AD18A3DAD5A0B7BCBC87B5A7E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7733, 317, 902000460, '\n【本经原文】味甘温无毒，主大风头眩痛，恶风，风邪，目盲无所见，风行周身，骨节疼痹烦满，久服轻身。\n\n【产地】产蒙古及山西河南等地，根黄白色，入药。 \n\n【性味】味甘辛，性温，无毒。 \n\n【主治】防风为伤风头痛要药，功能散表发汗，主诸般风，周身痛，搜肝泻肺，散风胜湿。\n\n【别录】烦满胁痛，风头面去来，四肢挛急，字乳，金疮内痉。 \n\n【大明】治三十六般风，男子一切劳劣，补中益神，风赤眼，止冷泪，及瘫痪，通利五脏关脉，五劳七伤，羸损盗汗，心烦体重，能安神定志匀气脉。 \n\n【元素】治上焦风邪，泻肺实，散头目中滞气，经络中留湿，主上部见血。 \n\n【吴克潜】防风善表散，故用以解毒，如砒毒，乌头毒。芫花毒，野菌毒，诸毒药，又防风本制黄耆，黄耆得防风而功最大，治风邪久留不去，表虚自汗不止。 徐之才曰得葱白行周身，得泽泻橐本疗风，得归芍阳起石禹余粮治妇人子脏风，元素曰治风 去湿之仙药也。 \n\n【容川】防风辛而味甘入肌，气香而温，故入脾。散肌肉之风寒。  \n\n【灵胎】专治风邪。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】似中风，产后血虚发痉，诸病血虚痉急，头痛不因风寒，溏泻不因寒湿，二便秘涩，小儿慢惊，阴虚盗汗，阳虚自汗，均忌。  ', NULL, NULL, '1', '防风', NULL, '60、防风', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909993, 'AE9E173847F10D08B40FA92CA16E36D1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7734, 317, 902000459, '\n【本经原文】味甘微温，主五劳七伤，补中，除茎中寒热痛，养五脏，强阴益精气多子，妇人症瘕，久服轻身。一名肉苁蓉。 \n\n【产地】生于各处高山，为一种寄生植物，茎富肉质，叶细如鳞。 \n\n【性味】味甘酸咸，性温无毒。 \n\n【主治】肉苁蓉为益髓壮阳要药，功能治精血不足，阳痿不举，女子绝产阴痛，润枯燥，滑大肠。 \n\n【别录】除膀胱邪气，腰痛止痢。 \n\n【甄权】益髓悦颜色，大补壮阳，治女子血崩。 \n\n【大明】男子绝阳不兴，女人绝阴不产，润五脏，长肌肉，暖腰膝，男子泄精血，遗沥，女子带下阴痛。 \n\n【容川】象人之阴，味咸入肾，温润而强阴，能助肾中之阳，益命门之火也。 \n\n【灵胎】补精益气，养血润肠。 \n\n【用量】普通二钱至四钱。 \n\n【禁忌】凡泄泻，肾中有热，强阳易兴而精不固者均忌，忌犯铁器。 \n\n【泡制】洗净，大小分开，浸泡4 - 8 小时，捞出，润透，切6 毫米纵片，用清水漂4 - 6 小时，捞出，晒干或烘干即得。 \n\n【酒制】取肉苁蓉片，加白酒调匀，置密闭容器内，隔水蒸至酒被吸尽，停火稍闷，取出晒 干即得。一般酒制后，较能温肾助阳。', NULL, NULL, '1', '肉苁蓉,肉松容', NULL, '59、肉苁蓉,肉松容', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909994, 'E685F70BF36A1B6E914EB49A3B313251', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7735, 317, 902000458, '\n【本经原文】味甘微温，主痈疽久败疮，排脓止痛，大风癞疾，五痔鼠瘘，补虚，小儿百病。  \n\n【产地】我国山西陕西均有出产，山西绵上者佳，茎卧地成蔓状，叶为羽状复叶，根肥大，短而理横，味苦者不堪入药。 \n\n【性味】味甘性微温无毒。 \n\n【主治】黄耆为补气要药，功能助肺气，实皮毛，升清气，泻火气，补虚损五劳，痘疮不起，外症治痈疽，托毒止痛。 \n\n【别录】女人子脏冷，逐五脏间恶血，补丈夫虚损五劳羸瘦，止渴，腹痛泄痢，益气，利阴气。 \n\n【甄权】主虚喘，肾衰耳聋，疗寒热，治发背，内补。 \n\n【日华】助气，壮筋骨，长肌肉补血，破症癖瘰疬瘿赘，肠风血崩带下，赤白痢，产前后一切病，月侯不匀。痰嗽，头风，热毒，赤目。 \n\n【元素】治虚劳自汗，补肺气，泻肺火心火，实皮毛，益胃气，去肌热，及诸经之痛。 \n\n【好古】太阴疟疾，阳维为病苦寒热，督脉为病逆气里急。 \n\n【容川】禀北方水中之阳气以生，以北耆最佳，人身之阳气皆从肾与膀胱之气海出发，上循三焦油膜，以达于肺，而为呼吸，分布于皮毛，则为卫气，北耆之体极松，内行水道之孔更大，故知其气盛，黄耆之根长数尺，深入土中，吸收土下之水以上其苗叶，气即水也，故其气盛而能补气，色黄如三焦油膜，故为三焦之良药，能拓里达表，行三焦之水气，又皮色黑，是水火之色也，色黄味甘，乃土之色味也，得味厚故能补，黄耆入土最深，得土之气最厚，故又大补脾，所以黄耆归脾经，又能通利三焦也。与升麻不同，升麻味不厚，故能升不能补。\n\n【药征】主治肌表之水，故能治黄汗盗汗皮水，又旁治身体肿或不仁者。 \n\n【灵胎】内补脾胃，外托疮毒。 \n\n【用量】普通生者钱半至三钱，炙者八分至三钱，大剂一二两。 \n\n【禁忌】黄耆功能实表，有表邪者忌，又能塞补不足，胸膈气闭闷，肠胃有积滞者忌，又能补阳，阳盛阴虚者忌，上焦热甚，下焦虚寒，及病人多怒肝气不和，并痘疮血分热者均忌。\n\n【倪注】一般言黄耆专于补气，凡气虚之症皆可用，又治自汗，补中气之不足，外科及痘科多以之托里透脓，肾亏溺血亦治之。 \n\n【附录】黄耆皮——性味功用同黄耆，善走表逐水湿，治虚浮及脚肿。 \n\n【炮制】拣去杂质，刮去粗皮，洗净捞出，沥干水分，切片晒干，再筛去灰即得。炙黄耆，用蜂蜜与水置锅中炒至干，取出冷却，即是。  ', NULL, NULL, '1', '黄芪', NULL, '58、黄芪', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909995, 'A57E2EB5BE4B8188FFCEC78176126FA0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7736, 317, 902000457, '\n【本经原文】味苦温，主恶血，破症结积聚，喉痹乳难，久服长肌肉，明目轻身。又名刺疾藜。  \n\n【产地】到处皆有。  \n\n【性味】味苦性温。  \n\n【别录】主身体风痿，头痛，咳逆伤肺，肺痿，止烦下气，小儿头疮，痈肿阴溃，可做磨粉。  \n\n【大明】主身益精，疗水脏冷，小便多，止遗沥泄精，溺血肿痛。\n\n【毅民】白疾藜治睛球凹陷，及睛生障翳，视物模糊。  \n\n【容川】利湿，此以金行水也。  \n\n【时方】腰脊引痛——捣末为蜜丸，胡豆大，酒服二丸日三。年久失明——阴干捣散，食后水服方寸匕。（外台）  \n', NULL, NULL, NULL, '蒺藜子,刺疾藜', NULL, '57、蒺藜子,刺疾藜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909996, 'E2CA916330948AB04464B22DFB7B9FF2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7737, 317, 902000456, '\n【本经原文】味苦温，主风热死肌痈伤，口干舌焦，痈肿不消，喉舌肿，水浆不下，久服轻身明目，润泽好颜色，不老延年。 又名耐冬，云花，为野生常绿藤本，茎有气根，藉以攀缘于他物上。此药以石上生者为最佳，故又名石龙藤。  \n\n【产地】产山谷阴湿之地，为自生常绿之草，茎入药。  \n\n【性味】味苦性微寒，无毒。 \n\n【主治】络石主利筋骨关节，治风热痈肿，能凉血退热，舒筋活络。 \n\n【别录】大惊入腹除邪气，养肾主腰髋痛，坚筋利关节，久服明目润泽。  ', NULL, NULL, NULL, '络石', NULL, '56、络石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909997, 'ADD3937B886E37EEF2F8F1DC64AFE7C4', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7738, 317, 902000455, '\n【本经原文】味苦寒，主热气，目痛，眦伤，泣出，明目，肠澼，腹痛，下利，妇人阴中肿痛，久服令人不忘。  \n\n【产地】生巫阳川谷。产四川者良，雅州者尤可贵，云南及他省亦有之，为山野多年生草本，日本产者劣，然多流入我国。根色黄，故名。  \n\n【性味】味苦性寒无毒。 \n\n【主治】黄连为清火除湿健胃要药，功能治湿滞，解热毒，益肝胆，厚肠胃，主治肠澼下痢，天行热疾，胎毒疳疾，效益甚多。  \n\n【别录】五脏冷热，久下泄澼脓血，止消渴，大惊，调胃厚肠益胆，疗口疮。  \n\n【大明】治五劳七伤益气，止心腹痛，惊悸烦燥，润心肺，长肉止血，天行热疾，止盗汗，并疮疥，猪肚蒸为丸，治小儿疳气，安疣杀虫。  \n\n【好古】心病逆而盛，心积伏梁。  \n\n【容川】黄连之味正苦，入心经以泻火。清火之药，是水交于火也，故能止血，凡药得苦味者，其中必含水性，故能降火，此为水火互根之理。其质枯而不泽，其纯于苦味而无气，故守而不走，为去暑之要药。  \n\n【倪注】按此药专治热与利湿，凡出现热症皆可用，但是须要辨明是属于何种热，例如虚热，则须在去热药中增加补虚的药物，像黄连阿胶汤；如是实热，则须在去热的药中加去实的药物，像三黄泻心汤之类，学者按此推之，即可善用黄连。黄连大寒，得水之性，故去热。与阿胶鸡子黄为填离清坎之药，故治心内之热。  \n\n【药征】主治心中烦悸也，旁治心下痞，吐下腹中痛。  \n\n【灵胎】除热燥湿，明目止利。  \n\n【用量】普通三分至一钱。 \n\n【禁忌】血少气虚，致惊悸烦燥，小儿痘疮阳虚作泄，行浆后泄泻，老人脾胃虚寒泻，真阴不足内热均忌。  ', NULL, NULL, '1', '黄连', NULL, '55、黄连', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909998, 'A437A37B7C1A697485F6603729CB6AA7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7739, 317, 902000454, '\n【本经原文】味辛性温，主咳逆定惊气辟邪恶，除蛊毒鬼注，去三虫，久服通神。即川芎之 苗也。  \n\n【别录】身中老风，头中久风，风眩。  \n\n【苏颂】作饮止泄泻。  \n\n【时珍】蘼芜花入面脂用。', NULL, NULL, NULL, '蘼芜,川芎之苗', NULL, '54、蘼芜,川芎之苗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633551935909999, 'FA1913AE36F6C056708E7AC4285D8A13', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 15:49:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7740, 317, 902000522, '【本经原文】味甘平，主风头，除蛊毒，补虚羸伤中，久服令人光泽好颜色不老，大黄蜂子主心腹胀满痛，轻身益气，土蜂子主痈肿。 \n\n【产地】产我国南方诸省岩岭间，今江浙之间多自养蜂，出蜜佳，国外产者亦佳。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】$n{蜂蜜}为润脏腑要药，主益气补中，滋养脾胃，调和营卫，治五脏不足，肠胃燥结，肌肉疼痛，除心烦，疗肠澼，作榳入谷道，导便秘。\n\n               $n{蜂蜡}为止血，安胎，补益药，治孕妇胎 动下血有殊效，又为硬膏基础剂。\n\n              ${蜜蜂子}为补虚，解毒药，治麻风病及肠寄生虫结聚腹痛，滇越等地常以油炸佐膳。 \n\n【别录】蜂蜜益气补中，止痛解毒，除众病，和百药，久服强志轻身。 \n\n【藏器】蜂蜜治牙齿疳虫，唇口疮，目肤赤障，杀虫。 \n\n【孟铣】蜂蜜治心腹血气刺痛，及白痢，同生地黄汁各一匙服，即下。 \n\n【本经】蜂蜡主下利脓血，补中，续绝伤金疮，益气。 \n\n【甄权】蜂蜡主孕妇胎动，下血不绝欲死，以鸡子大煎三五沸。投美酒半升立愈，又主白发镊去，消蜡点孔中即生黑发。 \n\n【本经】蜜蜂子治头风，除蛊毒，补虚羸伤中，久服令人光泽。 \n\n【别录】蜜蜂子治心腹痛，面目黄，大人小儿腹中五虫从口吐出者。 \n\n【藏器】蜜蜂子主丹毒风疹，腹中留热，利大小便涩，去浮血，下乳汁，妇人带下病。 \n\n【用量】可做食品，无定量。 \n\n【禁忌】无。  \n\n【附方】 阴头生疮——以蜜煎甘草涂之。 肛门生疮——白蜜一斤、猪胆汁一枚相和，微火煎令可丸，作挺长约三寸，大如手指，涂油纳肛门内，卧令后重，须臾通泻。 热油灼痛——以白蜜涂之。 肝虚雀目——黄蜡溶汁，入蛤粉相合所得，冷却，每以二钱夹入猪肝内煮之，乘热食肝  \n饮汁，日二，以平安为度。  \n\n大风疠疾——须眉已无，皮肉已烂成疮者：蜜蜂子，胡蜂子，黄蜂子并炒各一分，白花蛇，乌梢蛇并酒浸去皮骨炙干，全蝎，僵蚕并炒，各一两，地龙炒半两，蝎虎（守宫），赤足蜈蚣各15 条，丹砂一两，雄黄 一分（醋炒），龙脑半钱，共为细末，每服一钱匕，蜜汤调下，月三五服。（圣济）。', NULL, NULL, NULL, '蜂蜜,蜂子,蜂蜡  ', NULL, '122、蜂子，蜂蜜，蜂蜡 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882940997, '34C2340A845D0DE1ACE125D128D34B2E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7741, 317, 902000521, '【本经原文】味甘平，主心腹邪气，诸惊痫痓，安五藏，诸不足，益气补中，止痛解毒除众病，和百药，久服强志轻身，不饥不老。  \n\n【性味】味甘，性寒，无毒。 \n\n【主治】石蜜主和中益脾，润心肺解酒毒，治目中热膜，燥热咳嗽，心腹胀热，口干渴。  \n\n【唐本】主心腹热胀，口干渴。 \n\n【孟铣】治目中热膜明目，和枣肉巨藤末为丸含之，润肺气，五脏生津。  \n\n【灵胎】养胃和中。 \n\n【用量】普通做食品，入药无定量。  \n\n【禁忌】无。  \n\n【吴克潜】曰糖之赤者为赤沙糖，白者为白沙糖，凝结成块者为冰糖，入药用冰糖最良，膏 泛丸多用之。时珍曰蔗糖甘寒，能泻大热，素问甘温除大热意也，煎炼成糖则甘温而助湿热，所谓积温成热也，又白糖霜主润心肺，和中消痰，解酒生津，大约功专润泽，赤沙糖主心腹热胀，润心肺大小肠热，解酒毒，又为和血去积之药。  ', NULL, NULL, NULL, '石蜜', NULL, '121、石蜜  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882940998, '41E396223C6D5FCCE38C5CDCA2194D3C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7742, 317, 902000520, '\n【本经原文】味甘平，主风挛拘急，偏枯气不通利，久服益气不饥，轻身耐老。即野鸭。  \n\n【产地】野鸭之脂。 \n\n【性味】味甘平无毒。 \n\n【主治】四肢拘急，半身不遂等偏风。 \n\n【用量】无一定剂量，可做食用。 \n\n【禁忌】勿与犬肉猪肉牛肉等并煮，主腹泻。', NULL, NULL, NULL, '雁肪,野鸭', NULL, '120、雁肪,野鸭', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882940999, 'B019C38807C61BF1691595120E8543E7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7743, 317, 902000519, '\n【本经原文】味甘微温，主女人崩中漏下，赤白沃，补虚温中，止血通神，杀毒辟不祥头，主杀鬼，东门上者尤良。肪主耳聋，肠主遗溺，肶胵裹黄皮，主泄利，尿白主消渴，伤寒寒热，黑雌鸡主风寒湿痹，五缓六急，安胎，翮羽主下血闭，鸡子主除热火疮痫痉，可作虎魄 神物。鸡白蠹肥脂。即鸡一种。  \n\n【产地】处处有之。  \n\n【灵胎】疏肝养窜，鸡金消积。 \n\n【白雄鸡】味酸甘性微温无毒。主调中除邪，下气疗狂，安五脏利小便。  \n\n【乌雄鸡】味甘性微温无毒，主补中止痛，除心腹恶气，治风湿麻痹，诸虚羸，安胎，疗折伤。  \n\n【黑雄鸡】味甘酸性温平，无毒，主风寒湿痹五缓六急，破恶血，补新血，安胎，治产后虚羸，除邪辟恶痈疽排脓，酒浸饮，令人肥白。  \n\n【黄雄鸡】味甘酸咸．性平无毒，主伤中消渴，小便数而不禁，肠澼泄痢，补盖五脏绝伤，添髓生精，助阳气，疗五劳，益气力，去冷气，消水癖，治产后虚羸，煮汁煎药服佳。  \n\n【乌骨鸡】味甘性平无毒，主补虚劳羸弱．治消渴，益产妇，治女人崩带，一切虚损诸病，大人小儿噤口痢，并煮食饮汁，验鸡舌黑者良。  \n\n【用量】普通为服食之品，入药无定量。  \n\n【禁忌】鸡肉不可合葫蒜葱芥子食，不可合犬肉食，不可合獭肉兔肉鱼汁食，多食动风发疾，小儿五岁以下不宜食，忌与糯米同食。  \n\n【鸡内金】味甘性平无毒，主化积，治反胃，疗泄痢尿血下血，崩中带下，小儿食疟疳积，大人淋沥，消导酒积，外敷治一切口疮，牙疳腿疮，谷道生疮。  \n\n【鸡屎白】味苦性微寒无毒，主行水消积，治鼓胀，疗转筋入腹，破石淋二便，下气破血，治伤寒，寒热中风，贼风风痹，白虎风，贴风痛头痛，止遗溺，灭瘢痕，小儿客忤惊啼，解 金银毒，酒服疗乳妒乳痈乳头破裂，外敷秃疮耳疮瘰疬。  \n\n救急方——古人急救吊死或勒死之人时，将活雄鸡一只，腹部切开，趁热直接放置到死人的脖子位置，病患保持平躺姿势，可以救助于危急之时。  \n', NULL, NULL, NULL, '丹雄鸡', NULL, '119、丹雄鸡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941000, '4028438E406F192E784D0D941B36E40D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7744, 317, 902000518, '\n【本经原文】味甘平，主心腹内崩，劳极洒洒如疟状，腰腹痛，四肢酸疼，女子下血安胎，久服轻身益气。  \n\n【产地】原产山东东阿县，用阿井之水将牛皮或驴皮煎熬而成，今者阿井之水久湮，处处皆有出产，多以驴皮熬胶入药。  \n\n【性味】味甘，性平，无毒。  \n\n【主治】阿胶为养阴清热要药，主清补肺脏，滋益肝肾和血液，坚筋骨，治风痛．虚劳喘嗽吐血，妇人血枯经闭，崩中带下。  \n\n【别录】丈夫小腹痛，虚劳羸瘦，阴气不足，脚酸不能久立，养肝气。  \n\n【药性】坚筋骨，益气，止痢。  \n\n【药征】主治诸血症，故兼治心烦不得眠者。 \n\n【容川】阿胶以水济火，是以坎填离，此阴汁得心火化为赤，即为血，益阴气，使阳不动、保持厥阴之本体，阿胶得阿井伏流之水性，故能伏水中之阳。 \n\n【灵胎】养肝滋血，补脾安胎。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】气味虽平和然其性黏腻，胃弱作呕吐，脾虚食不消者均忌。  ', NULL, NULL, NULL, '阿胶', NULL, '118、阿胶', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941001, 'C72BCAA36BCADA120B93BF64F2E3C529', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7745, 317, 902000517, '\n【本经原文】味甘平，主伤中劳绝，腰痛羸瘦，补中益气，妇人血闭无子．止痛安胎，久服轻身延年，一名鹿角胶。  \n\n【产地】鹿之角茸。产我国东北西北地区。  \n\n【性味】味甘，性平，无毒。  \n\n【主治】主补中益气，长肌增髓，止痛安胎．黑须发。强筋骨，壮腰膝，生精血，治伤中，虚损，劳嗽，吐血，尿血，下血，多汗淋露，腰痛羸瘦，四肢作痛，崩中带下，疗疮疡，肿毒。  \n\n【别录】疗虚劳洒洒如疟，羸瘦，四肢酸疼，腰脊痛，小便数利，泄精溺血，破瘀血在腹，散石淋，痈肿，骨中热疽痒，安胎下气，杀鬼精物，久服耐老，不可近丈夫阴令痿。  \n\n【日华】补男子腰肾虚冷，脚膝无力，夜梦鬼交，精溢自出，女人崩中漏血，赤白带下，炙末空心服方寸匕，壮筋骨。  \n\n【灵胎】补督脉，强肾气。  \n\n【用量】普通七分至钱半。  \n\n【禁忌】壮年慎用，阴虚火旺者忌。麻勃为使畏大黄，不可嗅，有虫恐入鼻内，药不能治，男子阴茎近入，易于痿弱。  \n\n鹿茸——味甘咸性温无毒．鹿茸为大补真阳要药，主养血益阳，强筋健骨，生精充髓，治男子虚劳，老人精衰，腰膝无力，滑精眩晕，妇人崩漏带下。  \n\n鹿角——味咸性温无毒，主益气补阳，强骨髓，续绝伤，治腰脊痛，心腹痛少腹血急痛，脱精尿血，夜梦鬼交、疗女子胞中余血不尽欲死，恶疮痈疽，煮成粉名鹿角霜，治脾胃虚寒，呕逆食少便溏。  \n\n【吴克潜】曰鹿茸为纯阳之物，性温而燥，专补元阳，凡男子虚怯老人阳亏允为合宜，若吐血尿血等症，由于阴虚火旺下焦有热者居多，误用鹿茸必致反剧，故鹿茸治血症乃治阳衰气虚而不摄血者。治痈疽亦为阴症而火衰者，研习者须知。  ', NULL, NULL, NULL, '白胶 ', NULL, '117、白胶 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941002, '5DB91BFFC593DA3D729649258B0CA732', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7746, 317, 902000516, '\n【本经原文】味甘微寒，主风痹不仁，筋急，五藏腹中积聚，寒热羸瘦，头疡白秃，面皯， 久服强志，不饥轻身。  \n\n【产地】熊身上之脂肪。今已经不用。', NULL, NULL, NULL, '熊脂', NULL, '116、熊脂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941003, '48EB4946F0E2FEF0915ACDE82EC62602', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7747, 317, 902000515, '\n【本经原文】味苦平，主惊痫寒热，热盛狂痓，除邪逐鬼。 \n\n【产地】牛黄生于病牛胆中，状如鸡子黄，多出陕西甘肃等地。 \n\n【性味】味苦，性平，有小毒。 \n\n【主治】牛黄为泻热定惊，利痰清心要药，主惊痫，寒热中恶，口噤，小儿惊邪，痘疮发狂，治痰迷，痉急，斑痧疮毒，益肝胆，定魂魄。 \n\n【别录】疗小儿百病，诸痫热，口不开，大人狂癫，又堕胎，久服令人不忘。 \n\n【甄权】安魂定魄，辟鬼邪，卒中恶，小儿夜啼。 \n\n【日华】主中风失音，口噤，惊悸，天行时疾，健忘虚乏。 \n\n【思邈】益肝胆，定精神，除热，止惊痢，辟恶气，除百病。 \n\n【灵胎】化痰定痫，泄热除邪。 \n\n【用量】普通五分至一钱。  \n\n【禁忌】恶龙骨龙胆（钱乙方中不忌）地黄常山蜚蠊，畏牛膝干漆，风热未深者忌用。', NULL, NULL, NULL, '牛黄', NULL, '115、牛黄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941004, 'EFE8C304A5CF304F404869986FDF5108', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7748, 317, 902000514, '\n【本经原文】味辛温，主辟恶气．杀鬼精物，温疟，虫毒，痫痓，去三虫，久服除邪，不梦寤魇寐。  \n\n【产地】产我国青海西藏陕西甘肃四川等地，似鹿而小，牡麝之脐部有囊，分泌奇香之质，曰麝脐香，结成颗粒者曰当门子。  \n\n【性味】味辛，性温，无毒。  \n\n【主治】麝脐香为开关通窍要药，主内透骨髓，外彻皮毛，走窜开通。治中恶，痞满，风毒，风痰，暴痛卒闭，疗痰厥惊痫，鼻塞耳聋目翳。  \n\n【别录】疗诸凶邪鬼气，中恶，心腹暴痛，胀急，痞满，风毒，去面黡，目中肤翳，妇人难产，堕胎。  \n\n【日华】治蛇蚕咬，沙蛊溪瘴毒，辟蛊气，杀脏腑虫，治疟疾，吐风痰，疗一切虚损恶病，纳子宫，暖水脏，止冷带下。  \n\n【弘景】佩服及置枕间辟恶梦，及ㄕ疰鬼气，又疗蛇毒。  \n\n【药性】热水研服一粒，治小儿惊痫客忤，镇心安神，止小便利，又能蚀一切痈疮脓水。  \n\n【好古】疗鼻窒不闻香臭。 \n\n【孟铣】除百病，治一切恶气，及惊怖恍惚。  \n\n【灵胎】除邪辟秽，开窍杀虫。  \n\n【用量】普通数厘至分许。  \n\n【禁忌】凡病之属于虚者，当补益，概勿施用。劳怯及孕妇均不宜佩带，忌蒜及近鼻嗅之。  \n\n【吴克潜】中医之用麝香乃因其有开窍之功，一般毛孔闭塞者麻黄以通之，腠理闭塞者葛根以通之，荣卫闭塞者桂枝以通之，风塞者独活羌活以通之，血塞者延胡郁金以通之，肺气塞 者桔梗前胡以通之，心气塞者菖蒲远志以通之，胃气塞者藿香川朴以通之，肝气塞者香附川芎以通之。但是此类用法可以一脏一腑一经为治，并非闭塞之重者。当诸邪深入，或内病暴作，内则经络全被遏阻之势，外则诸窍亦有闭塞之象，是故心神失其主，神志为蒙，此时势非麝香通之不可，著名方剂有麝香天麻丸（麝香天麻防风川芎天南星菊花，治风痰气厥，头痛目眩、四肢倦怠，睡卧不宁），麝昏蟾酥丸（麝香蟾酥轻粉乳香砒石雄黄巴豆寒水石治痈疽发背．疔疮内毒），及至宝丹紫雪丹苏合丸牛黄清心丸等。  ', NULL, NULL, NULL, '麝香', NULL, '114、麝香', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941005, '256FBBF4D61A14B34D3CC11646374550', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7749, 317, 902000513, '\n【本经原文】味甘平，主心腹鬼注，精物老魅，咳逆泄利脓血，女子漏下，症瘕坚结，小儿热气惊痫。齿，主小儿大人惊痫癫疾狂走，心下结气，不能喘息，诸痉，杀精物，久服轻身，通神明延年。  \n\n【产地】多产于我国山西四川等处山岩中，为一种化石。  \n\n【性味】味甘，性平，无毒。  \n\n【主治】龙骨为固敛正气，镇纳浮阳要药，主安心神辟惊烦，治泄痢脓血，崩带遗精，镇喘逆，敛虚汗，收疮口，疗脱肛。  \n\n【别录】心腹烦满，恚怒，气伏在心下不得喘息，肠痈内疽，阴蚀，四肢痿枯，夜卧自惊汗出，止汗，缩小便，溺血，养精神，定魂魄，安五脏。白龙骨主多寐泄精，小便泄精。  \n\n【甄权】逐邪气，安心神，止夜梦鬼交，虚而多梦纷纭，止冷痢，下脓血，女子崩中带下。  \n\n【日华】怀孕漏胎，止肠风下血，鼻洪吐血，止泻痢渴疾，健脾，涩肠胃。  \n\n【药征】主治脐下动也，旁治烦惊失精。  \n\n【灵胎】敛气涩血，定志安神。  \n\n【用量】普通二钱至三四钱。  \n\n【禁忌】收摄太过，若非久痢虚脱者，切勿妄投，火盛失精者误用，多致溺赤涩痛，得人参牛黄良，畏石膏川椒，忌鱼及铁器。 龙骨今所用者皆石质也，过去有人误解为龙之骨化石，实则为化石之一种，质细而性纯，如 同禹余粮亦为石之一种，故二者功能相近，常与牡蛎合用。系土中石类，潜藏于土中，是天  \n水之阳，以归地下，故能潜纳肾气．收敛心神．因其潜纳之性也。  \n\n【炮制】拣去杂质，刷去泥沙即得，煅龙骨即置铁锅中，煅透，即得。', NULL, NULL, NULL, '龙骨', NULL, '113、龙骨', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941006, 'C34F5CE8C50A329BD0141494E6C5A926', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7750, 317, 902000512, '\n【本经原文】味苦温，主五癃关格不通，利小便水道。疗小儿痫，大人痓，仍自还神化。 \n\n【产地】乃人身头上之发也，处处有之。 \n\n【性味】味苦，性温，无毒。 \n\n【主治】发髲主益阴泄热，治小便不利，五癃关格，小儿惊痫，血闷血晕，去瘀血，止好血。\n\n【别录】合鸡子黄煎之消积水，疗小儿惊热百病。 \n\n【大明】止血闷血运金疮伤风血痢，入药烧存性用，煎膏长肉，消瘀血。 \n\n【苏敬】乱发烧灰，疗转胞小便不通，赤白痢，痈肿疔肿骨疽。 \n\n【丹溪】乱发消瘀血，止舌血，补阴甚捷。 \n\n【用量】普通三五分。 \n\n【禁忌】发灰气味不佳，胃弱者勿服。  ', NULL, NULL, NULL, '发髲 ', NULL, '112、发髲 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941007, 'DDC5D38827059779B1429FBBBE36F5F6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7751, 317, 902000511, '\n【本经原文】味辛温，主胸中瘕热逆气，利水谷，久服去臭，下气通神。又名橘皮。今之陈皮。 \n\n【产地】产我国广东，即广橘皮，以晒干陈久为良，故名陈皮。 \n\n【性味】味苦辛，性温，无毒。 \n\n【主治】陈皮为宣通疏利要药，主行气健胃，去湿化痰，能发散清热，消积水气。 \n\n【别录】下气止呕咳，治气冲胸中，吐逆霍乱，疗脾不能消谷，止泄，除膀胱留热停水，起淋，利小便，去寸白虫。 【甄权】清痰涎，治上气咳嗽．开胃主气痢，破症瘕痃癖。  \n【药征】主治呃逆也，旁治胸痹停痰。\n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡中气虚，气不归元者，忌与耗气药同用，胃虚有火呕吐，忌与温热香燥药同用，阴虚咳嗽生痰，忌与半夏南星等同用，疟非寒甚者忌。  \n\n成无己曰陈皮和百药，脾为气母，肺为气籥，凡补药涩药必用陈皮以利气，凡用陈皮取 其发散皮肤也，故陈皮之用在于行气，气行则领导百药，有痰者因气行而化，有湿者亦因气行而消，其它因食积及饮食之毒亦无不因气行而消解，气虚不能归元，则仅存之气不可再行而耗之，故忌。  \n\n【容川】陈皮亦木实也，能治胃，兼治脾，但兼辛香，又能上达于肺。枳壳不辛香，故不走肺，厚朴辛，而气太沉，故不走肺。因肺通于大肠，故厚朴可泄肺气。其气不轻不重，故可降上焦与中焦之气。 ', NULL, NULL, NULL, '陈皮,橘柚', NULL, '111、陈皮,橘柚', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941008, '95D9DB2DB2C52A88F1ABFFA6543EB598', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7752, 317, 902000510, '\n【本经原文】味甘温，主心腹邪气，明目，目赤痛，伤泪出，久服轻身，益气不饥。 \n\n【产地】产我国陝西河南等地，核仁入药。 \n\n【性味】味甘，性温，无毒。 \n\n【主治】蕤核主心腹邪热结气，治目赤痛伤泪出，翳膜，眦烂，生用疗多睡，熟用治不眠。\n\n【别录】破心下结痰痞气，齆鼻。 \n\n【甄权】治鼻衄。 \n\n【吴普】强志，明耳目。 \n\n【藏器】生治足睡，熟治不眠。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】能补肝虚，今人多用治眼疾，然非火风暴眼所宜用也。', NULL, NULL, NULL, '蕤核', NULL, '110、蕤核', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941009, '49119E474E034CF7A3DD2F7F0A52E407', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7753, 317, 902000509, '\n【本经原文】味苦寒，主身大热在皮肤中，去面热，赤疱酒皻，恶风瘨疾，阴下痒湿，明耳目。  \n\n【产地】处处有之，庭院可种植。  \n\n【性味】木兰皮味苦，性寒。 \n\n【主治】木兰皮为解热，行血，祛湿药。治面疱，酒糟鼻，水肿，酒疸，重舌，及阴下湿痒。\n\n【别录】疗中风伤寒，及痈疽，水肿，去臭气。  \n\n 【用量】普通一钱至三钱。  \n\n【禁忌】体寒之人禁。  \n\n【附方】 面上疱——木兰皮一斤，细切酒渍百日晒干，栀子一斤，共为末，每服方寸匕，日三。（肘后）。 酒疸发斑——赤黑黄色，心下懊痛，足胫肿满，小便黄，由大醉当风，入水所致：木兰皮一两，黄花二两，为末，酒服方寸匕，日三。（肘后）。  ', NULL, NULL, NULL, '木兰', NULL, '109、木兰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941010, '159240FB80A63E0747F94C5C9F14781D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7754, 317, 902000508, '\n【本经原文】味苦平，主补中安五脏，养精神，除百疾，久服肥健，轻身不老。又名女贞子。 \n \n【产地】处处有之，生川谷中，叶隆冬不凋，实入药。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】女贞子为除热益精要药，主补中安五脏，养精神，健腰膝，治白发。\n\n【用量】普通一至三钱。 \n\n【禁忌】气味俱阴，老人当入保脾胃药及椒红温暖之剂，不然恐腹痛作泻。 ', NULL, NULL, NULL, '女贞实,女贞子', NULL, '108、女贞实,女贞子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941011, '0BA7E20EC4D3C75AD5EC507AEFC6931D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7755, 317, 902000507, '\n【本经原文】味辛平，主腰脊痛，补中益精气，坚筋骨强志，除阴下痒湿，小便余沥、久服轻身耐老。 \n\n【产地】产我国陕西四川等地，树皮中有银丝如棉，故亦名锦杜仲，入药。 \n\n【性味】味辛甘，性温，无毒。 \n\n【主治】杜仲为健筋骨补腰肾要药，主腰膝酸痛，体虚强直，治胎漏胎堕，精气亏弱。 \n\n【别录】脚中酸痛，不欲践地。 \n\n【甄权】肾冷膂腰痛，人虚而身强直，风也，腰不利加重。 \n\n【大明】治肾劳腰脊挛。 \n\n【东垣】能使筋骨相着。 \n\n【好古】润肝燥，补肝经风虚。 \n\n【汪机】治胎漏胎堕。 \n\n【容川】杜仲柔韧，象人之筋膜，能伸能缩，极其坚韧，包紫黑，味纯厚，故入肝肾，以强人筋骨。 \n\n【用量】普通二钱至三四钱，大剂二三两。 \n\n【禁忌】恶元参蛇蜕，肾虚火炽者忌，当知母黄柏同用。 常用于胎前能安，胎后能补。  ', NULL, NULL, '1', '杜仲', NULL, '107、杜仲', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941012, 'B1DF05A434171DEB219193A13FEB462B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7756, 317, 902000506, '\n【本经原文】味苦平，主腰痛，小儿背强，痈肿，安胎充肌肤，坚发齿，长须眉，其实明目轻身通神。  \n\n【产地】产我国广西．或云处处有之，但寄生杂树者多，寄生桑树者少。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】桑上寄生为补肝肾坚筋骨要药，主腰痛背强，益血脉，安胎孕，治女子内伤不足，怀孕胎漏，产后余疾。 \n\n【别录】去女子崩中内伤不足，产后余疾，下乳汁，主金疮，去痹。 \n\n【容川】此药味酸枝繁，具木之性，生于桑树之上，桑者，木中之金也，寄生附之，故独得金木之间气，且根不粘土，纯感风气而生，故为清散风木之要药。此药附木而生，象胆附肝，味酸苦，得木火之味，能清肝胆之火，治风热，筋脉结等症，胆通三焦之网膜，外连于筋，寄生如藤附木，象人之筋，故治之。  \n\n【灵胎】驱风养血安胎。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】忌见火。  ', NULL, NULL, NULL, '桑寄生,桑上寄生', NULL, '106、桑寄生,桑上寄生', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941013, '25C4F7F191BB34633D1D9B57BB0E9413', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7757, 317, 902000505, '\n【本经原文】味辛温，主五脏身体，寒风头脑，面皯，久服下气，轻身明目，增年耐老。 \n\n【产地】处处有之，庭园可以种植，树高大，苞入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】辛夷为升阳治上要药，主头脑各病，鼻渊鼻塞，行胃气，宣肺气。 \n\n【别录】温中解肌，利九窍，通鼻塞涕出，治面肿，引齿痛，眩冒身几几如在车船之上者，生须发，去白虫。 \n\n【大明】通关脉，治头痛，憎寒体噤，搔痒，入面脂生光泽。 \n\n【灵胎】疏肝散风。 \n\n【用量】普通一二钱。 \n\n【禁忌】凡气虚人忌，偶感风寒鼻塞亦忌，头脑痛属血虚火炽亦忌，齿痛属胃火者亦忌，恶赤石脂，畏菖蒲黄连蒲黄石膏。  \n此药性升，故主头面各疾，可引诸药上升至头面，经曰脑渗为涕，王冰曰胆液不澄，则为浊涕，如泉不已，故名鼻渊。 \n\n【容川】辛夷花在树梢，其性极升，而味辛散，故能散脑鼻之间风寒。 \n\n【炮制】拣去杂质及柄，去灰即得。  ', NULL, NULL, NULL, '辛夷', NULL, '105、辛夷', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941014, '3CB8E9C47FB88B5E7E6CDD32AEC22E03', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7758, 317, 902000504, '\n【本经原文】味苦微寒，主筋骨间寒热痹，拘挛明目，坚齿利九窍，去白虫，久服轻身耐老。\n\n【产地】产我国河南甘肃江浙等地，子入药。 \n\n【性味】味苦辛，性微寒，无毒。 \n\n【主治】蔓荆子为搜风凉血要药，主利九窍，散风邪，明目坚齿，治风头痛脑鸣，湿痹拘挛。\n\n【别录】风头痛脑鸣，目泪出，益气，令人光泽，脂致。 \n\n【甄权】治贼风，长髭发。 \n\n【大明】利关节，治痫疾，赤目。 \n\n【元素】太阳头痛头沉昏闷，除昏闷，散风邪，凉诸经血，止目精内痛。 \n\n【好古】搜肝风。  \n\n【用量】普通八分至二钱。 \n\n【禁忌】头目痛不因风邪而由血虚有火者忌，胃虚人不可服，恐生痰疾。\n\n【容川】蔓荆子气烈，味辛而气发散，而质轻，故主散头目之风。  ', NULL, NULL, '1', '蔓荆实', NULL, '104、蔓荆实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941015, '2FB3CE65829F5505532D331034D92E7F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7759, 317, 902000503, '\n【本经原文】味辛温，主心腹疝气腹痛，益气疗躄，小儿不能行，疽创阴蚀。 \n\n【产地】产我国陕西江浙湖南等地，五叶者良，根皮入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】五加皮为祛风湿壮筋骨要药，主疼痹风弱，五缓虚羸，小儿行迟，疝气腹痛，治瘀留皮肌，阴痒囊湿。 \n\n【别录】男子阴痿囊下湿，小便余沥，女人阴痒及腰脊痛，两脚疼痹风弱，五缓虚羸，补中益精，坚筋骨，强志意。 \n\n【甄权】破逐恶风，四肢不遂，贼风伤人，软脚兼腰，主多年瘀血在皮肌，治痹湿内不足。\n\n【大明】明目下气，治中风骨节挛急。 \n\n【苏颂】酿酒饮治风痹，四肢挛急。 \n\n【雷斅】作末浸酒饮，治目僻眼瘫。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】下部无寒湿邪而有火，及肝肾虚而有火，均忌。 ', NULL, NULL, NULL, '五加皮', NULL, '103、五加皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941016, '4CFC84291C764823A889150A5A30914B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7760, 317, 902000502, '\n【本经原文】味辛温，无毒，主绝伤补中，续筋骨，填髓脑安五脏，五缓六急，风寒湿痹，生漆去长虫，久服轻身耐老。 \n\n【产地】产我国四川安徽等地，为漆树之脂，自然干者入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】干漆主破瘀血，续筋骨，治风寒湿痹，积滞，疝瘕，心痛，闭经。 \n\n【别录】干漆疗咳嗽，消瘀血痞结腰痛，女子疝瘕，利小肠，去疣虫。 \n\n【甄权】杀三虫，主女人经脉不通。 \n\n【大明】治传尸劳，除风。 \n\n【元素】削年深坚结之积滞，破日久凝结之瘀血。 \n\n【灵胎】养筋骨，祛风湿。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】畏川椒紫苏鸡卵及蟹，忌油脂，然大伤营血卫气，若胃虚大疮及无瘀血者均忌用，', NULL, NULL, NULL, '干漆', NULL, '102、干漆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941017, 'D75F2CAB8D9B737AA757216B22E4D80D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7761, 317, 902000501, '\n【本经原文】味苦寒，主五脏肠胃中结热，黄疸，肠痔，止泄利，女下漏下，赤白阴阳蚀疮。今名黄柏。 \n\n【产地】生汉中山谷。产我国四川，故亦称川柏，他处亦有之，日本输入者劣，树皮入药。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】黄柏为除热杀虫，坚肾益阴要药，主结热，黄疸，诸痿，瘫痪，治诸疮痛，泄痢，下血，泻膀胱相火，疗淋浊白带，肠胃结热。 \n\n【别录】疗惊气在皮间肌肤赤起，目热赤口疮。 \n\n【甄权】男子阴痿及传茎上疮，治下血如鸡鸭肝片。 \n\n【藏器】热疮疱起，虫疮，血痢，止消渴，杀蛀虫。 \n\n【元素】泻膀胱相火，补肾水不足，坚肾壮骨髓，疗下焦虚，诸痿瘫痪，利下窍，除热。 \n\n【大明】安心除劳治骨蒸，洗肝目多泪，口干心热，杀疳虫，治疣心痛，鼻衄，肠风下血，后急热肿痛。 \n\n【东垣】泻伏火救肾水，治冲脉气逆，不渴而小便不通，诸疮痛不可忍。 \n\n【丹溪】得知母降阴火，得苍术除湿清热，为治痿要药，得细辛泻膀胱火，治口舌生疮。 \n\n【灵胎】清热燥湿。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】恶干漆，伏硫磺，阴阳两虚，脾胃薄弱者均忌。  ', NULL, NULL, '1', '黄柏', NULL, '101、黄柏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941018, 'D4A25F7D807DA38C0DC01DF46298922F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7762, 317, 902000500, '\n【本经原文】味酸平，主心腹寒热，邪结气聚，四肢酸疼，湿痹，久服安五脏，轻身延年。\n\n【产地】产我国山西河南等地，多生山野间，或作棘实，，乃棘树之实也，实之大者名酸枣仁，入药。 \n\n【性味】味酸，性平，无毒。 \n\n【主治】酸枣仁为宁心敛汗要药，主心腹寒热，邪结气聚，烦心不眠，虚汗烦渴，治四肢酸痛湿痹，益肝养筋。  \n\n【别录】烦心不得眠，脐上下痛，血转久泄，虚汗烦渴，补中益肝气，坚筋骨，助阴气。\n\n【甄权】筋骨风，炒仁研汤服。 \n\n【药征】主治胸膈烦躁，不能眠也。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡肝胆心脾有实邪热者，禁用，以收敛故也。  ', NULL, NULL, NULL, '酸枣仁,酸枣', NULL, '100、酸枣仁,酸枣', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941019, '917377D4F76B0FA145CD1B8D10AF5503', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7763, 317, 902000499, '\n【本草原文】味甘平，主大小便不通，利水道，除邪气，久服轻身不饥。今名榆白皮。  \n\n【产地】榆树处处有之，树之白皮入药。 \n\n【性味】味甘性平，滑利，无毒。 \n\n【主治】榆白皮为泄滞去着，利水消肿要药，主大小便不通，利五淋，渗湿热，治肠胃邪热，水肿，痈肿，外敷疗癣湿，头疮。 \n\n【别录】疗肠胃邪热气，消肿，治小儿头疮痂疕。 \n\n【甄权】滑胎，利五淋，治喘疗不眠。 \n\n【大明】通经脉，捣涎傅癣疮。 \n\n【孟铣】生皮捣和三年醋泡封，暴患赤肿，女人妒乳肿，日六七易效。 \n\n【用量】普通二三钱。  \n\n【禁忌】此能利窍渗湿热，去有形之积，气盛而壅者宜之，若胃寒而虚者，久服恐泄真气。  ', NULL, NULL, NULL, '榆皮,榆白皮', NULL, '99、榆皮,榆白皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941020, 'D46CAB49D2EA8A7D344DCE40853706A2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7764, 317, 902000498, '\n【本经原文】味甘平，主胸胁逆气，忧恚惊邪恐悸，心下结痛，寒热烦满，咳逆，口焦舌干，利小便，久服安魂养神，不饥延年。  \n\n【产地】生太山山谷。产我国云南及各省山中大松树下，年久而巨大者良，有白色者，有微赤者，皆入药。\n\n【性味】味甘性平无毒。  \n\n【主治】茯苓为利水行痰，通补兼长要药，主胸胁逆气，忧恚惊恐，治烦满咳逆，水肿淋沥，能除湿益燥，开胃平呕，除虚热，安心神。  \n\n【别录】止消渴好睡。大腹淋沥，膈中痰水，水肿淋结，开胸腑，调脏气，伐肾邪，长阴益气力，保神气。  \n\n【甄权】开胃止呕逆，善安心神，主肺痿痰壅，心腹胀满，小儿惊痫，女人热淋。\n\n 【大明】补五劳七伤，开心益志，止健忘，暖腰膝，安胎。  \n\n【元素】止渴利小便，除湿益燥，和中益气，利腰脐间血。 \n\n【东垣】逐水暖脾，生津导气，平火止泄，除虚热，开肌理。  \n\n【好古】泻膀胱，益脾胃，治肾积奔豚。 \n\n【药征】主治悸及肉瞬筋惕也。旁治小便不利，头眩烦躁。  \n\n【灵胎】补脾生津，化痰利水。 \n\n【用量】普通钱半至四钱，大剂二三两。  \n\n【禁忌】恶白敛，畏地榆雄黄秦艽鳖甲，忌米醋及酸物，凡病人肾虚，小水自利或不禁，或虚寒，精清精滑均忌，入补药，宜乳蒸晒干用。  \n\n【吴克潜】茯苓能行气而和缓，利水而不伤正，故通补皆宜，古今方中用者很多，著名方剂有茯苓半夏汤（茯苓，白术，半夏，神曲，大麦芽，陈皮，天麻，治胃气虚弱，身重有痰， 恶心欲吐）。茯苓四逆汤（茯苓，人参，甘草，干姜，生附子，治伤寒太阳证厥而心下悸，汗下后烦燥者）。四苓散（茯苓，猪苓，泽泻，陈皮，一方有白术无陈皮，治湿热霍乱，胸闷胀痛，溺涩烦渴）。茯苓甘草汤（茯苓，甘草桂枝生姜，治伤寒太阳证汗出不渴，或厥而 心下悸，或咳而遗溺，或小便不利）。茯苓厚朴汤（治伤寒伤风，夹痰呕逆。及吐泻后喉涎牵响，脾胃气虚，饮食减少）。茯苓桂枝甘草大枣汤（治太阳证发汗后，脐下悸，欲做奔豚）。茯苓杏仁甘草汤（治水邪射肺，阻其出气，治胸痹短气）。茯苓补心汤（茯苓，桂枝，炙甘 草，紫英石，人参，麦冬，大枣，赤小豆，治心气不足，悲愁恚怒，烦热，面黄衄血，喉痛 舌强，妇人气血两虚）等。  \n\n【附录】 赤茯苓：性质功用与白茯苓同，尤能利窍行水，破结气，泻心小肠膀胱湿热，凡外感证多用之。  \n\n茯苓皮：主利水道，开肌理，治水肿肤胀，行水而不耗气，胜于大腹皮。  \n\n【容川】茯苓得木之气，又能疏土，故能化气行水。  ', NULL, NULL, NULL, '茯苓', NULL, '98、茯苓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941021, '7DE1748598D553EB9F7C0301D67FF269', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7765, 317, 902000497, '\n【本经原文】味甘平，主惊悸，安五脏，益气除湿痹，久服令人悦泽美色，耳目聪明，不饥不老，轻身延年。今名柏子仁。  \n\n【产地】处处有之，山野最宜种植，树高大可做木材，叶侧生者入药，名侧柏叶，实名柏子仁，亦入药。  \n\n【性味】味甘性平无毒。 \n\n【主治】柏子仁为滋润要药，主养心气，润肾燥，除风湿，治痹痛，疗恍惚虚损，养肝舒脾。  \n\n【别录】疗恍惚虚损，吸吸历节，腰中重痛，益血止汗。 \n\n【甄权】治头风腰肾中冷，膀胱冷，浓宿水，兴阳道，去百邪鬼魅，小儿惊痫。  \n\n【好古】润肝。 \n\n【灵胎】养心气，润肌肤。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肠滑做泻，膈间多痰，阳道数举，肾家有热，暑湿做泻者均忌。  \n\n【吴克潜】曰柏子仁不寒不燥，味甘而补，辛而能润，既养心肾，兼益脾肾，凡补脾药多燥，唯此独润而气味清香，故脾约宜之，燥脾药中，加用最良，著名方剂有柏子养心丸（柏子仁，枸杞子，麦冬，当归，石菖蒲，伏神，元参，熟地，甘草），治劳欲过度，心血亏损，精神恍惚，怔忡惊悸，及健忘遗精等症。柏子仁汤（柏子仁，人参，茯苓，陈皮，甘草，麝香少 许），治肠胃中津液枯少，脉虚微无力，大便艰涩者。柏子仁散（柏子仁，远志，人参，桑寄生，防风，琥珀，当归，生地，甘草）治产后败血挟邪攻心，乱语狂言，乍见鬼神等症。柏子仁丸（柏子仁，干地黄，茯苓，枳壳，覆盆子，北五味，附子，石斛，鹿茸，酸枣仁，桂心，沉香，黄耆）治妇人臂痛，筋脉挛急，遇寒则剧者。  ', NULL, NULL, NULL, '柏实', NULL, '97、柏实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633570882941022, '53AE4DA545067881511DACCA7DB955CA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-14 17:06:34', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7766, 317, 902000542, '\n【本经原文】味苦寒，主五脏邪气，厌谷胃痹，久服安心益气，聪察少卧，轻身耐老。\n\n【产地】处处有之，凌冬不死，诗云谁谓荼苦，即此物也。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】苦菜主明目，除热，治痈疮，黄疸，调经脉，去邪气。 \n\n【别录】肠澼，渴热中疾，恶疮，久服耐饥寒。 \n\n【嘉佑】调十二经脉，霍乱后胃气烦逆，久服强力，虽冷甚益人。 \n\n【臓器】捣汁饮除面目皮及舌下黄，其白汁涂疔肿拔根，滴痈上利溃。 \n\n【纲目】主明目诸痢血淋痔瘘。 \n\n【用量】普通二至三钱。 \n\n【禁忌】脾胃虚寒人不可食，不可共蜜食。', NULL, NULL, NULL, '苦菜', NULL, '142、苦菜  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349674053, '039BA62E1BD79B5AE89575959E4AEF97', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7767, 317, 902000541, '\n【本经原文】味甘平，主令人悦泽好颜色，益气不饥，久服轻身耐老。 \n\n【产地】热带地区处处有之。今名冬瓜。其子为白瓜子。 \n\n【性味】甘寒。 \n\n【主治】泻寒热，甘益脾，利二便，消水肿，止消渴，散热毒痈肿。子能补肝明目。现药物中所用之瓜子，皆冬瓜子也。', NULL, NULL, NULL, '白瓜子,冬瓜子', NULL, '141、白瓜子  ,冬瓜子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678149, '851D8E01E71CFBCA7BECA35F39BEF4E7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7768, 317, 902000540, '\n【本经原文】味苦寒，主大水。身面四肢浮肿，下水杀虫毒，咳逆上气及食诸果，病在胸腹 中，皆吐下之。即甜瓜之蒂也。 \n\n【产地】生嵩高平泽。处处有之，取甜瓜之苦蒂入药。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】上焦之实症，以吐取之，浊痰壅塞，全身水肿等实症。 \n\n【倪注】主治因上焦不通造成之全身性水肿，专治膈上之疾，中风浊痰不出，无法吞咽。仲景方之瓜蒂散。 \n\n【药征】主治胸中有毒，欲吐而不吐也。 \n\n【用量】普通一钱至二钱。 \n\n【禁忌】凡虚弱之人禁忌之。吐后不止，可服半夏解之。', NULL, NULL, NULL, '瓜蒂', NULL, '140、瓜蒂  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678150, '28239AB4B4F1B3BCEE78A301A2689F9E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7769, 317, 902000539, '\n【本经原文】味甘寒，主青盲明目，除邪，利大小便，去寒，久服益气力，不饥，轻身。  ', NULL, NULL, NULL, '苋实', NULL, '139、苋实  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678151, '261466D473D00C2D5819575538D8D901', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7770, 317, 902000537, '\n【本经原文】味辛平，主五劳七伤，利五脏，下血寒气，多食令人见鬼狂走，久服通神明轻身。今名麻勃(花粉)，火麻仁（果仁）。 \n\n【产地】生太山川谷。大麻处处有之，种者尤多，生圆形坚果，中含扁平之仁，即为麻子仁，入药，其花粉即麻勃。 \n\n【性味】麻仁味甘，性平。麻勃味辛，性温。 \n\n【主治】麻仁为滑润，行血，除风，强壮药，治大便燥，乳汁少，热淋经闭。麻勃为除风，通经，健脑药。 \n\n【别录】麻仁治中风汗出，逐水气，利小便，破积血，复血脉，乳妇产后余疾，沐发长润。\n\n【开宝】主补虚劳，润五脏，疏风气，治大肠风热结涩，利大小便。 \n\n【孟铣】取汁煮粥去五脏风，润肺，治关节不通，发落，产后余疾。 \n\n【士良】主润五脏，利大肠风热燥结及热淋。 \n\n【日华】补虚劳，逐一切风气；长肌肉，益毛发，通乳汁，止消渴，催生难产。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】大便溏者禁忌麻仁，患疔肿者忌麻勃，见之致死，用胡麻针砂烛尽为末，醋合敷之，可解。 麻勃药性——主一百二十种恶风，黑色遍身苦痒，逐诸风恶血，治女人经侯不通。  \n\n【附方】 产后秘塞——老人虚秘，麻仁，紫苏子等分，淘净研细，再以水研滤取汁，煮粥饮之。\n\n（本事） 月经不通——二三月或半年者，麻仁，桃仁等分，研匀，老酒浸一宿后，日饮一升．（普济） 发落不生——麻仁研汁煮粥频食之。（圣济总录） 大风癞疾——大麻浸酒，研取白汁，滤去渣，纳瓶中，煮数沸，每饮一杯。（圣惠） 健忘——麻勃一升，人参二两，为末，蒸令气遍，每卧服一刀圭。（范汪）  \n\n【容川】麻仁油滑，而无辛烈之性，故但能润降，不能速下。', NULL, NULL, NULL, '麻子仁,火麻仁,麻蕡', NULL, '137、麻蕡  ,麻子仁,火麻仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678152, '3DF293DEDBA72EE6BCB8CFBC602F27CB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7771, 317, 902000538, '\n【本经原文】味甘寒，主五脏六腑，寒热羸瘦。五癃，利小便，久服坚骨，长肌肉，轻身延年。 \n\n【产地】处处有之，苗叶做菜茹，味甘美为百菜主。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】冬葵子为润燥滑肠利窍要药，主通行荣卫，行津液，利二便，下乳滑胎，治癃闭，水肿。 \n\n【别录】疗妇人乳内闭肿痛。 \n\n【孟铣】出痈疽头。 \n\n【弘景】下丹石毒。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】葵菜心有毒伤人不宜食，葵性滑利不益人，病后食之令人失明。 葵菜——功同葵子，孕妇食之，胎滑易生，散脓血，治带下，疗手足长倒生肉刺痛不可  \n忍者奇效。 菜根——功同葵子，小儿吞钱不出，煮汁饮之妙，治疮疽恶毒。  ', NULL, NULL, NULL, '冬葵子', NULL, '138、冬葵子  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678153, 'F9E0C3C7B74AC0E565B234C756404532', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7772, 317, 902000536, '\n【本经原文】味甘平，主伤中虚羸，补五内，益气力，长肌肉，填髓脑，久服轻身不老。 \n\n【产地】处处有之，昔从胡来故曰胡麻，今名脂麻，有黑白黄三种，其大者曰巨胜子。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】胡麻主长肌肉，补虚羸，滋润五脏，利大小便，其油亦作解毒用。 \n\n【别录】坚筋骨，明耳目，耐饥渴，疗金疮止痛，及伤寒温疟，大吐后虚热羸困。 \n\n【日华】补中养气，润养五脏，补肺气，止心惊，利大小肠，耐寒暑，逐风湿气，游风头风，治劳气，产后羸困，催生落胞，细研涂发令长，白蜜蒸饵止百病。 \n\n【廷飞】炒食不生风病，风人久食则步履端正，语言不蹇。 \n\n【苏颂】生嚼涂小儿头疮，煎汤浴恶疮；妇人阴疮大效。 \n\n【用量】普通一钱至三钱。  \n\n【禁忌】多用为服食，少以入药，便溏者禁之。 \n\n【容川】麻油因其油质，故主滑利，但性不热，故行缓，无辛，故气不走窜，故下大便也缓。', NULL, NULL, NULL, '胡麻', NULL, '136、胡麻  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678154, 'B24AA98ED7A6A8E2E3F078D965CF4B2A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7773, 317, 902000535, '\n【本经原文】味甘平，主湿痹，腰脊膝痛，补中，除暴疾，益精气强志，令耳目聪明，久服  \n\n【产地】处处有之，产水泽中，俗名鸡头米。 \n\n【性味】味甘淡，性平，无毒。 \n\n【主治】芡实为固本益精要药，主泄泻遗精，带下白浊，治湿痹腰脊膝痛。 \n\n【日华】开胃助气。 \n\n【容川】微甘而涩，能收湿气，故健脾。 \n\n【灵胎】补脾益胃。 \n\n【用量】普通二至三钱。 \n\n【禁忌】生食动冷气，小儿不宜多食，以难化也，故食芡必细嚼，使华液流通，转相灌输，其功胜于乳汁。  ', NULL, NULL, NULL, '芡实,鸡头实', NULL, '135、鸡头实,鸡头米,芡实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678155, '1656DEEDC6C8A762A3C70BB6A7D98234', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7774, 317, 902000534, '\n【本经原文】味酸平，安五脏，益精气长阴，令坚强志，倍力有子，久服轻身不老．今名覆盆子。  \n\n【产地】处处有之，多生于山野向阳之林木中。 \n\n【性味】味甘酸，性微温，无毒。 \n\n【主治】覆盆子为补涩要药，主益肾脏，缩小便，起阳事，固精液，治遗尿遗精。\n\n【藏器】食之令人好颜色，榨汁涂发不白。 \n\n【甄权】主男子肾精虚竭阴痿，能令坚长，女子食之有子。 \n\n【宗奭】益肾脏，缩小便，取汁同少蜜煎为稀膏，点服治肺气虚寒。 \n\n【括要】补虚续绝，强阴健阳，悦泽肌肤，安和五脏，温中益力，疗劳损风。 \n\n【用量】普通一钱至二至三钱。 \n\n【禁忌】小便短涩者不宜。（今之前列腺肿大或是癌症均不宜。）  ', NULL, NULL, NULL, '覆盆子,蓬蘽', NULL, '134、蓬蘽,覆盆子', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678156, 'C6026F8D6C6AF67931375CB3E6012BD2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7775, 317, 902000533, '\n【本经原文】味甘平，主筋骨湿痹：益气倍力，强志，令人肥健耐饥，忍风寒，久服轻身，不老延年，可作酒。  \n\n【产地】处处有之，多种植园区山地之间，美法诸国盛产之。  \n\n【性味】味甘涩，性平，无毒。 \n\n【主治】蒲萄主补身益气养血，治筋骨湿痹，作酒用良。  \n\n【别录】逐水，利小便。  \n\n【甄权】除肠间水，调中治淋。  \n\n【苏颂】时气痘疮不出，食之或研酒饮之效。 \n\n【灵胎】补益筋骨，滋养肌肉。 \n\n【用量】普通做食品，入药无定量。 \n\n【禁忌】多食令人卒烦闷眼暗，东南商人食之多病热，西北人食之无恙。', NULL, NULL, NULL, '蒲萄', NULL, '133、蒲萄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678157, 'DBBB87AF297EC6FA4AC2065271A347F6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7776, 317, 902000531, '\n【本经原文】味甘平，主补中养神，益气力，除百疾，久服轻身耐老，不饥延年。即莲子也。\n\n【产地】处处有之，产湖泽池塘，家园多种植，花名荷花，亦名莲花，根茎曰藕，叶梗曰荷叶,荷梗，均入药。  \n\n【性味】味甘涩，性平，无毒。  \n\n【主治】莲子为健脾，养胃，清心，固精，资益气血，主补中倍力，除烦养神，治白浊梦遗，女子崩带，疗久痢，脾虚泄泻。  \n\n【孟铣】主五脏不足，伤中，益十二经脉血气。 \n\n【大明】止渴去热，安心止痢。治腰痛及泄精，多食令人欢喜。  \n\n【苏颂】捣碎和米作粥饭食轻身益气，令人强健。  \n\n【嘉谟】安靖上下君相火邪。  \n\n【灵胎】滋血脉，养脾胃。  \n\n【用量】普通三至四钱。  \n\n【禁忌】莲子甘平无毒，于诸疾并无所忤，第生者食之过多，微动冷气胀人，熟者食之过多，涩大便，莲藕忌犯铁。  ', NULL, NULL, NULL, '莲子,藕实,藕实茎', NULL, '131、藕实,莲子,藕实茎  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349678158, 'CFA8F5918E51AB0E70C375A786476228', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7777, 317, 902000532, '\n【本经原文】味甘平，主心腹邪气，安中养脾，助十二经，平胃气，通九窍，补少气少津液，身中不足，大惊，四肢重，和百药，久服轻身长年。  \n\n【产地】生河东平泽。产我国山东山西河北等省，他处亦有，生枣晒干，即名大枣。  \n\n【性味】味甘，性平，无毒。 \n\n【主治】大枣为补中益气，和解百药要药，主养脾平胃，调荣卫，生津液，润心肺，治虚损。  \n\n【别录】补中益气，坚志强力，除烦闷，疗心下悬。除肠癖。（痢疾的古名)  \n\n【孟铣】小儿患秋痢，与蛀枣食之良。 \n\n【大明】润心肺，止嗽，补五脏，洽虚损，除肠胃癖气。 \n\n【之才】杀乌头附子天雄毒。 \n\n【药征】主治挛急引强急也，旁治咳嗽奔豚烦躁，身疼胁痛，腹中痛。  \n\n【灵胎】补脾和中。  \n\n【用量】普通二至三钱。  \n\n【禁忌】生枣多食，令人热渴膨胀、动脏腑，损脾元，助湿热，忌与葱鱼同食，大枣多食，壅气助湿，凡中满者，小儿疳病者，齿痛及患痰热者，均忌。  \n\n【吴克潜】古方中多用大枣，因欲调和营卫，使气血流通津液输布，百药都须其协助，因此方中多用姜枣甘草等，经云：里不足者，以甘补之，形不足者温之以气，大枣甘温，专补脾胃，令津液自生，使十二经脉皆通畅，今医以温脾健胃时多选用红枣，滋阴养胃则用黑枣，而红枣即大枣，黑枣生于南方，黏液多而温性少，又名南枣，著名方剂有大枣汤（大枣十五枚，附子一枚，甘草一尺，黄耆四两，生姜二两，麻黄五两)治历节疼痛甚良。  \n\n【容川】大枣禀火之赤色，亦入心以养血，肉黄，得火生土之性，故纯于补脾胃。  ', NULL, NULL, NULL, '大枣', NULL, '132、大枣  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682245, 'E740FE8B0A55951780938F4366007CE7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7778, 317, 902000530, '\n【本经原文】味苦寒，主目热，赤痛，青盲，明目，久服强悍，益志气．功同青鱼胆。  \n\n【产地】即鲤鱼体内之胆。 \n\n【性味】味苦寒，无毒。 \n\n【主治】主各类目疾，能明目。 \n\n【甄权】鲤鱼胆点眼治赤肿翳痛。 \n\n【肘后】鲤鱼胆点雀目燥痛即明。 \n\n【容川】以类入肝胆，味苦又生水中，正得水性．为治肝胆火之正药，故治喉目。  \n\n【附方】 赤眼肿痛——鲤鱼胆五枚，黄连末半两，和匀，入蜂蜜少许，瓶盛，安饭上蒸熟，每日点目眦，日五七次。 阴痿——鲤鱼胆，雄鸡肝各一枚，为末，雀卵和丸小豆大，每吞一丸。  ', NULL, NULL, NULL, '鲤鱼胆', NULL, '130、鲤鱼胆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682246, '74B68407CFE9818052826ACD450A7854', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7779, 317, 902000529, '【本经原文】味甘寒，主湿痹，面目浮肿，下大水。 因过去诸多论述，各自意见不同，故今已无人能识，编者认为应是指鲤鱼，因为排列在下一位的药就是鲤鱼胆。 本草衍义亦认为是鲤鱼。  \n\n【产地】江南一带最多，以黑鲤鱼入药为最佳。  \n\n【性味】鲤肉甘味，性平。 \n\n【主治】黑鲤鱼有排水，利尿，消肿之效，治咳逆，黄疸，水肿，脚气肿痛，妊妇水肿。\n\n【别录】鲤鱼煮食治咳逆上气，黄疸，止渴，治水肿脚满，下气。 \n\n【日华】鲤鱼治妊娠身肿，及胎气不安。 \n\n【藏器】鲤鱼作脍温补，去冷气痃癖气块，横关伏梁，结在心腹。  \n\n【用量】为食物，无定量。  \n\n【禁忌】无。  \n\n【附方】 水肿——大鲤鱼一尾，赤小豆一升，同煮食肉饮汁，一顿尽服，当下利，尽即愈 妊妇水肿——如上方。 水肿满胀——鲤鱼一尾，破开不见水及盐，以生白矾末五钱入腹内，火纸包裹，外以黄土泥涂之，煨熟，一日食尽，屡验。  ', NULL, NULL, NULL, '蠡鱼', NULL, '129、蠡鱼  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682247, 'AE875F3AE53B8609B4F653338C2AE63B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7780, 317, 902000528, ' 【本经原文】主恶疮，蚀五痔。  \n\n【产地】产东海之滨，壳表有文彩者佳。  \n\n【性味】味咸，性平，无毒。 \n\n【主治】主咳逆胸痹，腰痛胁急，女人崩中漏下，止烦渴，利小便，化痰软坚，敷治口鼻中蚀疳，恶疮五痔。 \n\n【用量】普通一至二钱，外用无定量。 \n\n【禁忌】畏甘遂芫花，虽善消痰积血块，然脾胃虚寒者宜少用。  ', NULL, NULL, NULL, '文蛤 ', NULL, '128、文蛤 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682248, '4BD9E29FD06B3CB5F2AB45ACCD7716CD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7781, 317, 902000527, '\n【本经原文】味苦平，主咳逆上气、喘息烦满，胸痛寒热。  \n\n【产地】产海滨，为蛤类之壳，经海水漂集海边泥沙中者，细小如棋子，光润莹净。  \n\n【性味】味苦咸．性平，无毒。  \n\n【主治】海蛤粉为软坚润下要药，主老痰，热痰，痰气喘咳，消瘿核，散肿毒，止呕逆，利小便，治妇人血病。  \n\n【丹溪】主热痰湿痰老痰顽痰，疝气，白浊带下，香附末姜汁调服，主心痛。  \n\n【用量】普通一至二钱。 \n\n【禁忌】畏甘遂芫花，虽善消痰积血块，然脾胃虚寒者宜少用。  ', NULL, NULL, NULL, '海蛤 ', NULL, '127、海蛤  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682249, 'A3EB2D2E0978FF15A468C077F9D63E2B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7782, 317, 902000526, '【本经原文】味咸平，主伤中，疝瘕阴痿，益精生子，女子血闭，腰痛，通五淋，利小便水道。今名桑螵蛸。  \n\n【产地】处处有之，乃螳螂所作房，着生于桑枝上者，入药。  \n\n【性味】味咸甘，性平，无毒。 \n\n【主治】桑蜱蛸为固肾益精要药，主遗尿，滑精，治白浊疝瘕，肾衰阴痿，通五淋，疗便浊。  \n\n【别录】疗男子虚损，四脏气微，梦寐失精，遗溺，久服益气养神。  \n\n【甄权】炮熟空心食之，止小便利。  \n\n【吴克潜】桑螵蛸为小儿梦中遗尿要药，得覆盆子菟丝子益智仁补骨脂等甚效，合龙骨疗滑精，著名方剂有桑螵蛸散（盐灸桑螵蛸远志肉龙骨盐炙菖蒲人参茯神醋炙龟板当归）治男子因女劳，小便日数十次，如稠米泔色，心神恍惚，有实效。  \n\n【灵胎】养血逐瘀，补肾利水。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡膀胱有热，小便短数者忌之。  ', NULL, NULL, NULL, '桑螵蛸,桑螵蛸', NULL, '126、桑蜱蛸  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682250, '8DC8B0BB5142A4972A8F82A53A54D99F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7783, 317, 902000525, '【本经原文】味咸平，主漏下赤白，破症瘕疟痎，五痔阴蚀，湿痹四肢重弱，小儿囟不合。久服轻身不饥。  \n\n【产地】处处有之，生池泽及海水中，其甲即龟甲，肉亦入药。  \n\n【性味】味甘咸，性平，无毒。  \n\n【主治】龟板为益阴滋血要药，主补心肾，益大肠，去瘀血，续筋骨，治久疟，劳复，血痹，湿痹，症瘕，产难，久痢久泻。  \n\n【别录】惊恚气，心腹痛不可久立，骨中寒热，伤寒劳复；或肌体寒热欲死，以作汤良，久服益气资智，烧灰治小儿头疮难燥，女子阴疮。  \n\n【甄权】烧灰治脱肛。  \n【弘景】壳主久嗽，断疟。  \n\n【肃炳】壳炙末酒服，主风脚弱。  \n\n【日华】治血麻痹。 \n\n【丹溪】下甲补阴，主阴血不足，去瘀血，止血痢，续筋骨，治劳倦四肢无力。  \n\n【容川】龟之性伏，其精在板，能通任脉，任为离中之阴，以下交于督，合为既济之象，故龟板益阴滋心肾。与鹿茸是对子。以水配火，不使壮火食气，如此气纳矣。  \n\n【用量】普通二至四钱。 \n\n【禁忌】妊娠及病人虚而无热者，均忌，凡使用时须研极细，否则留滞肠胃，能变症瘕，鳖甲亦然，合猪肉菰米瓜笕食损人。  \n\n常见方剂有大补阴丸，黄柏知母熟地败龟板治阴亏火旺，肺痿咳血，呃逆烦热易饥，骨蒸盗汗，足膝疼热虚劳等症，能降阴火，益肾水，龟鹿二仙膏，败龟板鹿角枸杞人参，主大 补精髓，益气养神，治视物不清，加味芎归汤，治横生倒产，交骨不开。用以催生良。  \n\n【龟肉】味甘酸，性温，无毒。主筋骨疼痛，年久寒嗽，泻血血痢，酿酒治大风缓急，四肢 拘挛，瘫缓不收，煮食治疗身肿痿折。 ', NULL, NULL, NULL, '龟甲', NULL, '125、龟甲  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682251, '37112C15BC6259EF2B88192B3AD210AC', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7784, 317, 902000524, '【本经原文】味咸平，主伤寒寒热温疟，洒洒惊恚，怒气除拘，缓鼠瘘，女子带下赤白，久服强骨节 , 杀邪气延年。  \n\n【产地】生东海池泽。产浅海泥沙中，右壳小而薄，左壳大而凸，常连缀重叠，附于岩石。  \n\n【性味】味咸，性平，微寒，无毒。  \n\n【主治】牡蛎为软坚利水，敛汗固肠要药，主益肝肾，除老血，治伤寒，留热在骨间，化痰破积，去胁下坚满。涩大小肠。清热安神。  \n\n【别录】除留热在关节，营卫虚热去来不定，烦满心痛气结，止汗止渴，除老血，疗泄精，涩大小肠，止大小便，治喉痹，咳嗽，心胁下痞热。  \n\n【藏器】粉身止大人小儿盗汗，同麻黄根蛇床子，干姜为粉去阴汗。  \n\n【孟铣】治女子崩中，止痛，除风热风疟，鬼交精出。  \n\n【李珣】男子虚劳，补肾安神，去烦热，小儿惊痫。  \n\n【好古】去胁下坚满，瘰疬，一切疮。  \n\n【药征】主治胸腹之动也，旁治惊狂烦躁。牡蛎黄连龙骨同治烦躁，而各有所主也，心口黄连所主，脐下龙骨所主也，而部位不定，胸腹烦躁者，牡蛎所主也。  \n\n【用量】普通三四钱。 \n\n【禁忌】恶麻黄细辛吴萸伏磠砂，凡病虚而有寒者忌，肾虚无火，寒精自出者亦忌。  \n\n', NULL, NULL, NULL, '牡蛎', NULL, '124、牡蛎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682252, '57EB1C7739A33C1CF3B0C726E88F90FD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7785, 317, 902000523, '【本经原文】味甘微温，主下利脓血，补中益气续绝伤，治金创，益气不饥耐老，今用之甚稀。  \n\n【性味】味淡甘，性温。  \n\n【主治】止血，安胎，补益要药，治孕妇胎动下血有殊效，又为硬膏基础剂。  \n\n【甄权】蜜蜡主孕妇胎动，下血不绝欲死，以鸡子大煎三五沸，投美酒半升服立瘥。又主白发镊去，消腊点孔中，即生黑者。  ', NULL, NULL, NULL, '蜜蜡', NULL, '123、蜜蜡 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633919349682253, '97F19BBC737C92E904EFF42FE2FF5E25', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:44:28', 1, 'admin', '2025-01-15 22:19:16');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7786, 437, 902000601, '\n【本经原文】味苦平寒、主寒热鼠瘘，恶创疽痔死肌，杀精恶物鬼邪气，百虫毒，胜五兵，炼食之，轻身神仙。  \n\n【产地】产我国西部，南省亦有。  \n\n【性味】味辛苦，性温，有毒。  \n\n【主治】雄黄为蚀疮杀虫要药，主辟邪气，疗诸疮，解毒，为外科要剂，亦可内服。  \n\n【别录】疗疥虫疮，鼻中息肉，及绝筋破骨，百节中大风，积聚癖气，中恶腹痛，鬼疰，诸蛇毒，解藜芦毒。  \n\n【大明】风邪癫痫岚瘴，一切虫兽伤。  \n\n【好古】搜肝气，泻肝风，消涎积。  \n\n【用量】普通内服数分，外用无定量。  \n\n【禁忌】雄黄性热有毒，外用易见长，内服难免害，凡服之中病即止，无过剂也，能柔五金干汞，转硫磺，伏粉霜（以轻粉升成之霜。）与雌黄同，或云雄黄变铁，雌黄变锡。  \n\n【吴克潜】按雄黄于疮痬螫外科，最为急用，以其性能杀虫解毒也，吴俗于五月五日饮雄黄酒，并洒之室角以驱五毒，但须要知道雄黄虽有腐蚀之力，能蚀恶肉以杀虫治疮，但过用终不免侵蚀好肉，故不可多服，外科亦须审慎使用，著名方剂有安虫丸（干漆雄黄巴豆霜），治吐沫水后腹中必虫痛。雄黄解毒丸（巴豆雄黄玉金）治急喉痹咽喉不通，胸膈气促，金锁 匙（朴消雄黄大黄）治一切风热，咽喉闭塞为末，吹入喉中。 ', NULL, NULL, NULL, '雄黄', NULL, '143、雄黄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633920418689094, NULL, NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:48:49', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7787, 437, 902000618, '\n【本经原文】味苦寒，主消渴身热，烦满大热，补虚安中，续绝伤。今名天花粉。  \n\n【产地】生弘农川谷。产我国陕西者良，他处亦有之，为山野自生之蔓草，根名天花粉，实名瓜篓实，皮名瓜篓皮，中含仁甚多，名瓜篓仁，俱入药。  \n\n【性味】味甘，性寒，无毒。  \n\n【主治】瓜篓实为润肺降气要药，主袪痰止嗽，涤胸中垢腻，润心肺及胃，治吐血，天花粉主消渴，烦满大热，通乳消肿。  \n\n【别录】主胸痹，悦泽人面。  \n\n【纲目】润肺燥降火，治咳嗽，涤痰结，利咽喉，止消渴，利大肠，消痈肿疮毒。  \n\n【大明】子炒用补虚劳，口干，润心肺，治吐血，肠风泻血，赤白痢。  \n\n【吴克潜】瓜篓根实，皆能润肺治痰，此其同也，其中仁以清胸中痰火，润肠涤秽之功为主，其根治时热大渴，痈疮肿毒。皮能润肠消炎并行。一般治痰剂有宣有下有消有攻有润，而瓜篓实为润也，润剂之别是瓜篓清而润，苏子温而润，莱服子消而润，麦冬补而润，牛蒡杏仁 散而润，补以治痰则有五味子之收敛，除湿健脾以治痰则有半夏之温而燥。  \n\n【倪注】按伤寒杂病论之用根为生津要药，滋润太阳经之燥与胃经之燥，实为去心包积痰之要药。  \n\n【容川】花粉清热，入气分，色白味苦而有液，故泻热之功轻，入胃生津之力重。瓜篓实能治膈间之结气，因篓之膜似人胸之膈膜，又似人腹之象，又治大腹之气，因子有油而气烈，包有瓠而味苦，捣烂合用，能解膈膜之痰火  \n\n【药征】主治胸痹也，旁治痰饮。治消渴。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】脾胃虚寒作泄者忌，恶干姜畏牛膝，反乌头，忌铁。  ', NULL, NULL, NULL, '栝蒌,瓜篓根,天花粉', NULL, '160、瓜篓根 ,天花粉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632325, 'F30D9FB76CDDC892489E775A265CC02A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7788, 437, 902000617, '\n【本经原文】味甘平，主消渴，身大热，呕吐，诸痹，起阴气，解诸毒。【葛谷】主下利，治下痢十岁已上。一名鸡齐根。\n\n【产地】生汶山川谷。处处有之，江浙尤多，花名葛花，子名葛谷，根制粉名葛粉，捣汁名葛汁，均入药。\n\n【性味】味甘，性平，无毒。 \n\n【主治】葛根为发汗解肌升阳散火要药，主消渴大热，伤寒中风，治头痛，泄泻，开胃气，解酒毒。 \n\n【别录】疗伤寒中风头痛，解肌发表出汗，开腠理，疗金疮，止胁风痛。 \n\n【甄权】治天行上气呕逆，开胃下食，解酒毒。 \n\n【大明】治胸膈烦热发狂，止血痢，通小便，排脓破血，傅蛇虫毒，毒箭伤。 \n\n【之材】杀野葛巴豆百药毒。 \n\n【藏器】生者堕胎，蒸食消酒毒，可断谷不饥，作粉尤妙。 \n\n【开宝】作粉止渴，利大小便，解酒去烦热，压丹石，傅小儿热疮，捣汁饮治小儿热痞。 \n\n【苏敬】猘狗伤捣汁饮，并末傅之。 \n\n【容川】葛根其根深，能以地中水气，上达于苗叶，其苗极长，象人身之太阳经，从膀胱水  \n中，达阳气于经脉，以卫周身，故入太阳经。葛根气味较平，故发散而不伤血，根深能引水气，上达苗叶，故兼能升津液以治太阳之痉。其根色纯白，属金，又能吸水气上升，是金水相生之物，故又能引津气治阳明之燥，故入太阳阳明二经。与升麻不同，葛根根实，故升津不升气，升麻根空，有孔道以行气，故升气而不升津。  \n\n【药征】主治项背强也，旁治喘而汗出。  \n\n【用量】普通二钱至六钱。  \n\n【禁忌】多用反伤胃气，升散太过也，丹溪曰已见红密点，不可服葛根升麻，恐表虚反增斑 烂。  \n\n【吴克潜】认为葛根为解热之剂，与麻黄桂枝同为伤寒要药，然麻黄发汗解表，乃解太阳皮表之邪以退热，桂枝发汗解肌，乃调和营卫解肌腠之邪以退热，麻黄治表实（汗不得出），桂枝治表虚（汗出恶风），而葛根发汗，主治则在病将由太阳而入阳明，热甚或呕或痢，必须汗出以解之，此三药之发汗不同之处。  \n\n【倪注】葛根为升津之要药，故仲景使用于太阳痉病，与下热痢，因能升津也，口噤用之也因其升津之性也，故伤寒论中之葛根汤实为仲景先师为温病立下之处方，今之温病学家误解仲景先师无温病之识，故曰北方无温病，为南方有之，因此分出温病学，殊不知伤寒论中的葛根汤就是治疗温病的第一优先方。  \n\n【炮制】捡去杂质，劈成0.6—1 厘米厚长条块，去灰屑即得。', NULL, NULL, NULL, '葛根', NULL, '159、葛根 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632326, '4ADC21A4EFF6D0A035A8DAA316B0E491', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7789, 437, 902000616, '\n【本经原文】味甘温，主风头寒痛，风湿周痹，四肢拘挛痛，恶肉死肌，久服益气，耳目聪明，强志轻身。  ', NULL, NULL, NULL, '枲耳实', NULL, '158、枲耳实', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632327, '1BCAA923214E64C63B88369F6AD367DB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7790, 437, 902000615, '\n【本经原文】味辛温，主胸满咳逆上气，温中止血，珠汗，逐风湿痹，肠澼下利，生者尤良，久服去臭气通神明。生犍为川谷。  \n\n【性味】味辛，性温，无毒。 \n\n【主治】干姜为除寒散结要药，主温中逐寒，回阳通脉，治四肢逆冷，中寒霍乱，冷痛疝气，寒泻腹痛，开脏腑，宣脉络。  \n\n【甄权】治腰肾间疼痛冷气，破血去风，通四肢关节，开五脏六腑，宣诸络脉，去风毒冷痹，夜多小便。  \n\n【大明】消痰下气，治转筋吐泻肠脏，反胃干呕，瘀血扑损，止鼻红，解冷热毒，开胃消宿食。  \n\n【好古】主心下寒痞，目睛久赤。  \n\n【容川】干姜炮制则温而不烈，性轻而上浮，而四逆理中，则干姜不炮，取其性烈，乃能去寒，能温土中之阳，阳出则阴消，为治寒湿之药，补火之药是火能化水也，故能行血。能补 脾之火，是以土治水。  \n\n【药征】主治结滞水毒也，旁治呕吐咳，下利，厥冷，腹痛，胸痛，腰痛。  \n\n【用量】普通一钱至三钱，大剂上两许。 \n\n【禁忌】生姜干姜炮姜禁忌同，久服伤阴损目，误服劫津耗液，凡阴虚内热，阴虚咳嗽吐血，表虚有热，汗出自汗盗汗，脏毒下血，因热呕恶，火热胀痛均忌。  ', NULL, NULL, NULL, '干姜', NULL, '157、干姜  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632328, '76D34DB8F0785B6F67BDEC1B42D5A71C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7791, 437, 902000614, '\n【本经原文】味辛平，主虫毒及蛇，菜肉诸毒，恶创。  ', NULL, NULL, NULL, '肤青', NULL, '156、肤青  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632329, '0C19E9AEA9B1216159B7D9C9B33CE8C5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7792, 437, 902000613, '\n【本经原文】味辛寒，主身热，四肢寒厥，利小便，通血脉明目去翳眇，下三虫，杀蛊毒久服不饥。  ', NULL, NULL, NULL, '长石', NULL, '155、长石  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632330, '957E46ABFF47A0140D88F5B37C05DDEE', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7793, 437, 902000612, '\n【本经原文】味辛寒，主身热利胃，解烦益精，明目，破积聚，去三虫。', NULL, NULL, NULL, '理石', NULL, '154、理石  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632331, '8B32C15987FBDA256B324100A16069C2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7794, 437, 902000611, '\n【本经原文】平主明目，化铜铁落，味辛平，主风热，恶创，疡疽创痂，疥气在皮肤中，铁主坚肌耐痛。  \n\n【产地】铁精或铁落为錬铁时锤打所落之皮甲。  \n\n【性味】味辛，性平。 \n\n【主治】铁精为解热，安神，补血药，能除风热，治风痉，癫痫，善怒发狂。  \n\n【苏敬】炒热投酒中饮，疗贼风痉，裹以熨腋下，疗狐臭有验。  \n\n【用量】普通内服一厘至五厘，煎服者虽数钱亦可，近时多用以融化他药中服之。  \n\n【禁忌】铁性重坠，有碍消化，服原质者宜慎之，患肿者服之，一生须忌盐。', NULL, NULL, NULL, '铁精', NULL, '153、铁精  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632332, '82D9776264780640DDFCCEF7C5703B95', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7795, 437, 902000610, '\n【本经原文】味辛温主烂伤瘀血泄利寒热鼠瘘症瘕结气，今少用。', NULL, NULL, NULL, '殷孽', NULL, '152、殷孽  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632333, '9084DD6EBFD0D5AB06071A110E9F8144', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7796, 437, 902000609, '\n【本经原文】味辛温，主伤食不化，邪结气，恶创疽瘘痔，利九窍，下乳汁。  ', NULL, NULL, NULL, '孔公孽', NULL, '151、孔公孽  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632334, '09A52F1E6B2D6310926D6DA707E5B439', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7797, 437, 902000608, '\n【本经原文】味咸微温，主崩中漏下，破子臧中血，症瘕结气，寒热腹痛，无子，阴痿不起，补不足。  \n\n【产地】产深山山谷，或曰，惟齐山有之。  \n\n【性味】味咸，性微温，无毒。 \n\n【主治】阳起石为补命门壮阳道要药，功能疗阴痿，男女下部虚冷，补不足。\n\n【别录】疗男子阴头寒，阴下湿痒，去汗臭，消水肿，令人有子。 \n\n【甄权】补肾气，精乏腰痛，膝冷湿痹，子宫久冷，冷症寒瘕，止月水不定。\n\n【大明】治带下瘟疫，冷气，补五劳七伤。  \n\n【好古】补命门火不足。  \n\n【灵胎】助阳益气。  \n\n【用量】普通水飞用，五分至一钱。  \n\n【禁忌】凡阴虚及阳痿属于失志，以致火气闭密，不得发越而然，与崩漏由于火盛，而非虚寒者，均忌，忌羊血，凡使用火灸酒淬七次，研细水飞用，不入汤药，又石药冷热皆有毒（因不易消化），非可久服之物。为云母石之根，其山冬不积雪，夏则生云，积阳上升，故凡病人阳气下陷，阳物不举者，用以升举阳气，此以阳助阳。  \n\n【炮制】拣去杂质，捣碎，置铁锅中，煅透，趁热倒入酒渍淬，取出晾干，研粉即得。  ', NULL, NULL, NULL, '阳起石', NULL, '150、阳起石  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632335, 'A4A850E5422189E87AD36189EEF73B75', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7798, 437, 902000607, '\n【本经原文】味辛寒，主身热腹中积聚邪气，皮中如火烧，烦满水饮之，久服不饥，又名寒水石。  \n\n【产地】生于卤地积盐之下，精液渗入土中，年久至泉，结而成石，清莹如水晶，亦有带黑色者。 \n\n【性味】味辛亦做咸，性寒，无毒。 \n\n【主治】凝水石主明目固齿凉血降火，时气热盛，腹中积聚，疗汤火伤（烧研敷）。 \n\n【别录】除时气热盛，五脏伏热，胃中热，止渴，水肿，小腹痹。 \n\n【甄权】压丹石毒风，解伤寒劳复。 \n\n【用量】普通煎剂一钱至三钱。 \n\n【禁忌】性寒，虚寒之体不宜，入肾走血，除热之功与诸盐同，畏地榆，解丹石巴豆毒，制丹砂，伏玄精石。  ', NULL, NULL, NULL, '凝水石', NULL, '149、凝水石  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632336, 'A607F023C552CF69E6563126A076DD8E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7799, 437, 902000606, '\n【本经原文】味辛寒，主周痹，风湿肢节中痛不可持物，洗洗，酸消，除大热，烦满及耳聋，今名磁石。  \n\n【产地】产山中能吸铁。  \n\n【性味】味辛，性寒，无毒。  \n\n【主治】磁石为补肾强阴要药，取其能引肺气入肾，使阴阳安宅，镇惊，明目，通耳，益精。  \n\n【别录】养肾脏，强骨气，益精除烦，通关节，消痈肿鼠瘘，颈核喉痛，小儿惊痫，炼水饮之。  \n\n【甄权】补男子肾虚风虚身强，腰中不利，加而明之。  \n\n【大明】治筋骨羸弱，补五劳七伤，眼昏，除烦躁，小儿误呑针铁等，即研细末以筋肉莫令断与末同呑下。  \n\n【灵胎】补肾降火，强筋壮骨。  \n\n【用量】入煎剂二钱至四钱，水飞用三分至八分。  \n\n【禁忌】凡石药皆有毒，独磁石冲和无悍猛之气，然体重，难于消化，渍酒优于丸散，凡使火炙醋淬，研末水飞，或醋煮三日夜用，恶丹皮杀铁消金。 久则化铁，为铁之母，药性为，石属金，铁为水，故磁石本兼金水两性，而归于肾，故其主治肾，能自肾中吸引肺金之气，以归于根。  \n\n【炮制】捡去杂质，捣碎，置铁锅中，煅透，趁热倒入醋渍淬，取出晾干，研粉即得。', NULL, NULL, NULL, '磁石,慈石', NULL, '148、慈石,磁石', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632337, 'BB31C54E5295BFCB4A1C7A87DF85CE03', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7800, 437, 902000605, '\n【本经原文】味辛微寒，主中风寒热，心下逆气，惊喘口干，舌焦不能息，腹中坠痛，除邪鬼，产乳金创，又名寒水石。 \n\n【产地】生齐山山谷。产浙江江苏山东，他省亦有出产。 \n\n【性味】味甘辛，性微寒，无毒。 \n\n【主治】石膏为清凉解热要药，主治肺胃三焦气分之热，大渴热狂，能解肌发汗，又能清热止汗。\n\n【别录】除时气头痛身热，三焦大热，皮肤热，肠胃中结气，解肌发汗，止消渴烦逆腹胀，暴气喘息，咽热，亦可作浴汤。 \n\n【甄权】治伤寒头痛如裂，壮热皮如火燥，和葱煎茶去头痛。 \n\n【大明】治天行热狂头风旋，下乳，揭齿益齿。 \n\n【元素】止阳明经头痛，发热恶寒，日晡潮热，大渴引饮，中暑潮热，牙痛。 \n\n【容川】得石之性多，味虽咸而不甚，且此山之石即能生水，流而为泉，是故此石纯具水性，禀天水之寒，故能清热。 \n\n【药征】主治烦渴，旁治谵语烦躁身热。 \n\n【用量】普通三钱至五钱，大剂二三两。 \n\n【禁忌】伤寒中风太阳症，少阳症之往来寒热等均忌，真寒假热之症或因里虚引起之虚热症亦忌，有金疮下乳亦忌，胃家寒症者亦忌，恶巴豆畏铁。  ', NULL, NULL, NULL, '石膏', NULL, '147、石膏 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632338, '6DDC02DB058F02E40389570426BB540D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7801, 437, 902000604, '\n【本经原文】味辛寒，主疥瘘痂伤白秃，杀皮肤中虱，堕胎，除热，杀金银铜锡毒，镕化还 复为丹，久服神仙不死。 \n\n【产地】产山西陕西山中。 \n\n【性味】味辛，性寒，有毒。 \n\n【主治】水银为杀虫要药，主治杨梅疮毒，及皮肤诸病，润肠下死胎。 \n\n【别录】以傅男子阴，阴消无气。 \n\n【藏器】利水道，去热毒。 \n\n【大明】主天行热疾，除风，安神，镇心，治恶疮疥，杀虫，催生下死胎。 \n\n【宗奭】治小儿惊痫热潮。 \n\n【灵胎】除湿热，解疮毒。 \n\n【用量】普通多配合丸散方用，内服约数分，外用无定量。 \n\n【禁忌】水银性沉，与金银诸物同，吞服金银水银者，皆足以致命，饵服者须慎之。 ', NULL, NULL, NULL, '水银', NULL, '146、水银 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632339, '2EF73C0AC6C7A834A21A52F164427173', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7802, 437, 902000603, '【本经原文】味辛平，主恶创头秃痂疥，杀毒虫虱，身痒邪气，诸毒炼之，久服轻身，增年 不老。  \n\n【产地】产地同雄黄。  \n\n【性味】味辛性平有毒主恶疮杀虫虱，身痒，邪气诸毒，治身面白驳，散皮死肌，血气虫积 心腹痛，为外科要药，与雄黄功相仿。  ', NULL, NULL, NULL, '雌黄', NULL, '145、雌黄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632340, 'C00EE385235C9959D897073BB9D2B369', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7803, 437, 902000602, '\n【本经原文】味酸温，主妇人阴蚀，疽痔恶血，坚筋骨，除头秃，能化金银铜铁奇物。  \n\n【产地】产火山地带。 \n\n【性味】味酸，性温，有毒。 \n\n【主治】硫磺为补阳要药，主治脾胃虚寒，寒痹冷癖，命门火衰，能发汗以祛寒痰，及疏利大肠，通常性便秘，杀虫，治疮疥。\n\n【别录】疗心腹积聚，邪气冷痛在胁，咳逆上气，脚冷疼弱无力，及鼻衄，恶疮下部虫疮，止血杀疥虫。 \n\n【甄权】下气，治腰肾久冷，除冷风顽痹，寒热，生用治疥癣，炼服主虚损泄精。 \n\n【大明】壮阳道，补精骨劳损，风劳气，止嗽，杀脏虫邪鬼。 \n\n【吴普】治妇人血结。 \n\n【李珣】长肌肤，益气力，老人风秘，并宜炼服。 \n\n【容川】能燃，是水中之火也，其味酸，是得木味，水中之阳，发则为木，故味酸而能燃，又是水中之木也，为温下焦肝肾之猛药。 \n\n【灵胎】驱寒燥湿。杀虫化金。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】硫磺为救急妙药，但中病便当已，不可尽剂，畏细辛朴消，中硫磺毒，黑铅煎汤解之，或是食鸭肉可解之。  ', NULL, NULL, NULL, '石硫黄', NULL, '144、石硫黄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 633932257632341, '422AAE588E1F8C50E01AB1D8BEAAB9FA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 17:37:00', 1, 'admin', '2025-01-16 14:54:24');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7804, 437, 902000624, '\n【本经原文】味苦，平，无毒。治皮肤寒热，胃中热气。风寒湿痹。坚筋骨，令人嗜食。久服轻身。花、叶，去白虫，喉痹。一名剧草。一名三坚。一名豕首。又名马蔺子。  \n\n【产地】产我国陕西河南一带多有之，为山野自生之宿根草，实入药。  \n\n【主治】蠡实主治皮肤寒热，一切疮疖，产后血晕，寒疝诸疾，利大小便。  \n\n【别录】止心烦满，利大小便，长肌肤肥大。  \n\n【苏敬】疗金疮血内流，痈肿有效。 \n\n【大明】妇人血气烦闷，产后血晕，并经脉不止，崩中带下，消一切疮疖，止鼻衄吐血，通小肠，消酒毒，治黄病，杀蕈毒，傅蛇虫咬。  \n\n【用量】普通一钱至三钱。\n\n【禁忌】不详。', NULL, NULL, NULL, '蠡实', NULL, '166、蠡实 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634005797847109, '2663003796045CC95ECF39092848B28E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 22:36:14', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7805, 437, 902000623, '\n【本经原文】味苦，平，有小毒。治邪气腹痛，除血痹，破坚积，寒热，疝瘕，止痛，利小便，益气。一名白木。  \n\n【产地】处处有之，为多年生草本，山野自生，或种植，因芍药花美也，根做纺锤形，外淡褐色而内白色，其稍赤者名赤芍。  \n\n【性味】味苦酸，性平，无毒。  \n【主治】白芍为泻肝安脾，缓中去水要药，功能养血散瘀清热利肠，止腹痛，治痢疾，治胎产前后诸病，为女科良药。 【别录】通顺血脉，缓中散恶血，逐贼血，去水气，利膀胱大小肠，消痈肿，时行寒热，中恶，腹痛腰痛。 【大明】女人一切病，胎前产后诸疾，治风补劳，退热除烦，益气，惊狂头痛目赤，明目，肠风泻血，痔瘘，发背，疮疥。 \n\n【元素】泻肝安脾，收肺气，止泻痢，固腠理，和血脉，收阴气敛逆。 \n\n【好古】理中气治脾虚中满，心下痞，胁下痛，善噫，肺急胀逆，喘咳，太阳鼻衄，目涩肝血不足，阳维病苦寒热，带脉病苦腹痛满，腰溶溶如坐水中。（血痹即血凝于肌肤而为痹）。【容川】为春之花，而根微酸，故主能敛肝木，降火行血。苦性较轻，故白芍只微降，大黄则降力大。味苦能泻血，其色白，故又能行气分之水。 \n\n【药征】主治结实而拘挛，旁治腹痛头痛，身体不仁，疼痛腹满，咳逆下利肿脓。  \n\n【用量】普通二钱而五钱，大剂一两以上。 \n\n【禁忌】凡中寒腹痛，中寒作泄，肠胃中觉冷，均忌，反藜芦恶芒硝，鳖甲，小蓟。  ', NULL, NULL, NULL, '芍药', NULL, '165、芍药  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634005797847110, '774E0F10D1E73390DD53C1F66CDB3AF5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 22:36:14', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7806, 437, 902000622, '\n【本经原文】味辛，平，无毒。主去恶虫，除脾胃寒热，通利九窍、血脉、关节，令人不忘。一名附支。又名白通草。  \n\n【产地】生石城山谷。产于江南，多生山侧，茎入药。 \n\n【性味】味甘淡，性平，无毒。 \n\n【主治】通草为利水退热要药，主泄肺热利阴窍，舒胃气，除水肿，治五淋，下乳催生。\n\n【东垣】主利阴窍，治五淋，除水肿癃，泻肺。 \n\n【苏颂】解诸毒，虫毒。 \n\n【汪机】明目退热，下乳催生。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】虚脱之人与孕妇禁忌。 \n\n【容川】白通草象人身之油膜，故能通达油膜，上可以通乳，下可以通小便。', NULL, NULL, NULL, '通草', NULL, '164、通草  ,白通草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634005797847111, '6E9974CD40AA17B5F5B7F66CA25CF4B5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 22:36:14', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7807, 437, 902000621, '\n【本经原文】味甘，温，无毒。治中风，伤寒，头痛。温疟，发表出汗，去邪热气，止咳逆上气，除寒热，破症坚积聚。一名龙沙。 \n\n【产地】我国西北部皆有出产，生晋地。以山西大同为最良，其它如印度及西伯利亚南非洲皆有产。\n\n【性味】味苦，性温散，无毒。 \n\n【主治】麻黄为发汗解散要药，功能退热平喘利水，主伤寒表实无汗，治肺实喘逆，通利水道。  \n\n【别录】五脏邪气缓急，风胁痛，止好睡，通腠理，解肌泄邪恶气，消赤黑斑毒，不可多服，令人虚。  \n\n【甄权】治身上毒风疹痹，皮肉不仁，主壮热温疫，山岚瘴气等。  \n\n【大明】通九窍，调血脉，开毛孔皮肤。  \n\n【元素】去营中寒邪，泄卫中风热。  \n\n【纲目】散赤目肿痛，水肿风肿，产后血滞。  \n\n【容川】虽其茎直上，但却如草之丛生，故能上升又能外散，其茎空，直达而上，且无大味，纯得天轻阳之气，故专主气分。一般取其苗，以其苗细长中空，象人毛孔，而气轻扬，故能发汗，能通阳气，直走鼻皮毛，其根坚实味涩，故能止汗。  \n\n【炮制】捡去杂质，去尽木质及残根，喷淋清水，微润，切 1.5  厘米段片，晒干或烘干，去 灰即得。  \n\n【药征】主治喘咳水气也，旁治恶风恶寒，无汗，身疼，骨节痛，一身黄肿。  \n\n【灵胎】发汗止喘。  \n\n【用量】普通五分至一钱，大剂三钱。 \n\n【禁忌】平日阳虚，腠理不密之人忌之，诸虚有汗，肺虚痰嗽，气虚发喘，均忌。  \n\n【倪注】麻黄为发汗第一要药，能退热平喘利水，皆其解散之功，凡风寒初袭肌表，不得解散则发为头痛项强恶寒诸症状，发其汗则风寒得以解散，诸症自除，举凡外感初起之发热，多由汗不得出，因势利导使汗出而热解，此本经之所言去邪热也，又肺受风寒不解，则咳气上逆，用麻黄利水道，外为发汗，是故痰水因而下行，风寒因而得以宣泄，因病根解除，咳气上逆自愈，若以之点眼，可使瞳孔放大，此因其能散。今麻黄配桂枝能散营分之寒邪，配膏能泄卫分之风热，皮肉不仁，著名方剂如麻黄汤，麻杏甘石汤，大青龙汤。因麻黄根能止汗，节亦止汗，故欲发汗，则须去根与节。', NULL, NULL, NULL, '麻黄', NULL, '163、麻黄 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634005797847112, '3E2857A945D824938E1E97BB539C9BC1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 22:36:14', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7808, 437, 902000620, '\n【本经原文】味甘，温，无毒。治咳逆上气，温疟，寒热洒洒在皮肤中。妇人漏下，绝子。诸恶疮疡，金疮。煮饮之。一名干归。 \n\n【产地】我国西部皆有出产，以陕西四川为最良。 \n\n【性味】味甘苦辛，性温，无毒。 \n\n【主治】当归为补血清血要药，主一切血虚血浊，治瘘弱，痹痛，诸疮，破恶血，生新血，补女子诸不足，为调经良药。 \n\n【别录】温中止痛，除客血内塞，中风痉汗不出，湿痹中恶，客气虚冷，补五脏，生肌肉。\n\n【甄权】止呕逆虚劳寒热，下痢腹痛，齿痛，女人沥血腰痛，崩中补诸不足。 \n\n【大明】治一切风一切气，补一切劳，破恶血养新血，及症癖胃冷。 \n\n【好古】主瘘痹嗜卧，足下热痛，冲脉为痛，气逆里急，带脉为病，腹痛腰溶溶如坐水中。\n\n【容川】当归辛苦，得地火之味，其气微温，得木之性，质多油，此因得地之湿，故能助心生血，以行于肝，其功专生血。归首之性升，故主生血，尾之性降，故主行血，性温润，可以去寒结。风能胜湿，风伤血则筋燥，当归能润燥。其味辛温，火也，其汁油润，水也，一物而具二者，是水交于火所化之物也，恰与血之生化相同，故主补血。 \n\n【灵胎】补血养血，润肺润肠。 \n\n【用量】普通二钱至五钱，大剂一至二两。 \n\n【禁忌】性滑润，泄泻者慎用，脾胃薄弱者忌，用时须它药来佐。  ', NULL, NULL, NULL, '当归', NULL, '162、当归  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634005797847113, '6A50A0C0CE5C6C27FCFBA5B0DD16616F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 22:36:14', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7809, 437, 902000619, '\n【本经原文】味苦寒，主心腹结气，症瘕积聚，黄疸，溺有余沥，逐水，除痈肿，补中，明目，止泪。 \n\n【产地】产河南四川，各地山野及田畔湿地亦俱有之，根黄白色类牛蒡，甚苦，入药。  \n\n 【性味】味苦，性寒，无毒。 \n\n【主治】苦参为燥湿胜热健胃杀虫积要药，主治积聚，症瘕，恶疮，疳症，泄血中热，清湿 养阴。 \n\n【别录】养肝胆气，安五脏，除伏热，肠澼，止渴，醒酒，小便黄赤，疗恶疮下部虫。 \n\n【甄权】治热毒风，皮肌烦躁，生疮，赤癞，眉脱，除大热，嗜睡，治腹中冷痛，中恶腹痛。\n\n【弘景】渍酒饮治疥杀虫。 \n\n【苏敬】治恶虫胫酸。 \n\n【纲目】杀疳虫，炒存性，米饮服，治肠风泻血并热痢。 \n\n【括要】遍身风疹，痛不可忍，肺热生疮，遍身皆是；瘰疬结核，下部疮瘺，诸般实症用之有效。 \n\n【灵胎】清心肝火，去小肠热。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】久服损肾气，肝肾虚而无大热者忌。  ', NULL, NULL, NULL, '苦参', NULL, '161、苦参  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634005797847114, 'B4148BCF94B5DF7C0C19AFC1E32A3ED9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 22:36:14', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7810, 437, 902000679, '\n【本经原文】味甘，平，无毒。主安五脏，和心志，令人欢乐无忧。久服轻身，明目，得所欲。生山谷。一名蠲忿，一名夜合。  \n\n【产地】山中有之。皮供药用。 \n\n【性味】合欢皮味甘，性平。 \n\n【主治】为合血，消肿，止痛药，治筋骨折伤及肺痈吐脓。 \n\n【大明】煎膏消痈肿，续筋骨。 \n\n【用量】一般二至四钱。 \n\n【禁忌】无禁忌。  ', NULL, NULL, NULL, '合欢', NULL, '221、合欢  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000325, '20E7D77D08CC258398D16E0AA9851EED', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7811, 437, 902000678, '\n【本经原文】味苦，寒，无毒。治女子崩中下血，腹满，汗出，除邪，杀鬼毒，蛊疰，生山谷。一名鬼箭。又名神箭。  \n\n【产地】处处有之。 \n\n【性味】味苦涩，性寒。 \n\n【主治】为调经止痛要药，治女子崩中，产后腹绞痛。 \n\n【别录】主中恶腹痛，去白虫，消皮肤风毒肿。令阴中解。 \n\n【甄权】破陈血，能落胎。 \n\n【大明】通月水，破症结，止血崩带下，杀腹臓虫，及产后血绞腹痛。\n\n【苏敬】疗妇人血气大效。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】寒利者禁用。  ', NULL, NULL, NULL, '卫矛,鬼箭,神箭', NULL, '220、卫矛,鬼箭,神箭  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000326, '7D69DDEB422486B3FAD71DE0EC9F2E40', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7812, 437, 902000677, '\n【本经原文】味苦，平，无毒，治嗔怒，邪气，止虚汗，头风，女子阴寒肿痛。生川谷松树上。一名女萝。一名菘萝。  \n\n【产地】松树上之地衣植物。 \n\n【性味】味苦，性平。 \n\n【主治】为祛痰，涌吐药，可以吐痰涎，治温疟，项瘿及女子阴寒肿痛。 \n\n【别录】疗痰热温疟，可为吐汤，利水道。 \n\n【甄权】治寒热，胸中客热痰涎，去头疮，项上瘿瘤，令人得眠。 \n\n【用量】一般二至四钱。 \n\n【禁忌】呕家禁用。  ', NULL, NULL, NULL, '松萝,女萝,菘萝  ', NULL, '219、松萝,女萝,菘萝  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000327, '615FFD2E0E636407A5C50E05C027614D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7813, 437, 902000676, '\n【本经原文】味甘，平，无毒。治五脏邪气，安志，厌食。久服强魂魄，聪明，轻身，不老，通神明。生南海山谷。一名益智。 \n\n【产地】产我国福建四川广东等地，实形圆，故名。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】龙眼为滋养要药，主益脾长肌，养心安神，治血虚怔忡劳神健忘。 \n\n【别录】主五脏邪气，安志厌食，除蛊毒，去三虫。 \n\n【括要】主补血气，养肌肉，益虚气，除健忘，治怔忡，开胃益脾，补虚长智。 \n\n【用量】普通二至三钱。  \n\n【禁忌】甘能作胀，凡中满气膈之证均忌。  ', NULL, NULL, NULL, '龙眼', NULL, '218、龙眼  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000328, 'F18E6EF4AF4B3A285CDDF0994971CF2F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7814, 437, 902000675, '\n【本经原文】味辛，寒，无毒。治心腹痛，痈肿溃脓，止痛。生川谷。一名棘针  ', NULL, NULL, NULL, '白棘', NULL, '217、白棘  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000329, '48CC55D1FC2002A5EBB849363690BD70', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7815, 437, 902000674, '\n【本经原文】味甘，平，无毒。治痎疟，解毒，蛊疰不祥。利水道。久服轻身，耐老。生山谷。一名猳猪屎。  \n\n【产地】生衡山川谷。产我国四川及其它省山中，多生枫根下，结成块状。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】猪苓为行水渗湿要药，主肿胀腹满，热渴懊憹，治淋肿，白浊子淋，尿闭，开腠理，泻膀胱。 \n\n【甄权】解伤寒瘟疫大热，发汗，主肿胀满腹急痛。 \n\n【元素】治渴除湿，去心中懊憹。 \n\n【好古】泻膀胱。 \n\n【药征】主治渴而小便不利也。 \n\n【用量】普通钱半至三四钱。 \n\n【禁忌】猪苓利水之功多，久服必损肾气，昏人目，元素曰，淡渗大燥，能亡津液，无湿者忌之。 ', NULL, NULL, NULL, '猪苓', NULL, '216、猪苓  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000330, '739BC682B2CA6C32DAE7B7839F964193', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7816, 437, 902000673, '\n【本经原文】味酸，微寒，无毒。治妇人产乳余疾，崩中，症瘕，血闭，寒热，羸瘦，养胎。生西海川谷及山阳。一名芺华，一名陵苕。 \n\n【产地】产山野，或栽植庭园，亦名凌霄花。 \n\n【性味】味酸，性微寒，无毒（或作有毒）。 \n\n【主治】紫葳主行血通经，祛瘀血，治淋沥，清血中伏火。 \n\n【甄权】产后奔血不定，淋沥，主热风风痫，大小便不利，肠中结实。 \n\n【大明】酒齄热毒风，刺风，妇人血膈游风崩中带下。 \n\n【用量】普通一至二钱。 \n\n【禁忌】花不可进鼻闻，伤脑，花上露入目昏蒙。  ', NULL, NULL, NULL, '紫葳', NULL, '215、紫葳  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000331, '6B38A8E28DB5C990416BEF707B5EFBBB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7817, 437, 902000672, '\n【本经原文】味酸，平，无毒。治心下邪气，寒热，温中，逐寒湿痹，去三虫，久服轻身。生山谷。一名蜀枣。  \n\n【产地】产我国山东河南等地，与吴茱萸甚不相类，树实入药。  \n\n【性味】味酸，{或辛酸}，性平，或作性温，无毒。  \n\n【主治】山茱萸为滋阴助阳，养血涩精要药。主逐寒湿痹，安五脏，通九窍，暖腰膝，添精髓，治阳痿遗精，血弱体痛。  \n\n【别录】肠胃风邪，寒热疝瘕，头风，鼻塞，目黄耳聋，面疱下气，出汗强阴，益精，安五脏，通九窍，止小便利，久服明目强力。  \n\n【甄权】治脑骨痛，疗耳鸣，补肾气，兴阳道，坚阴茎，添精髓，止老人尿不节，治面上疮，能发汗，止月水不定。  \n\n【大明】暖腰膝，助水脏，除一切风，逐一切气，破症结。  \n\n【元素】温肝。 \n\n【用量】普通一钱至二至三钱。  \n\n【禁忌】命门火燥，强阳不痿者，膀胱热结，不宜用，即用，当与黄柏同功。\n\n【容川】山茱萸酸而质润，故专入肝，滋养阴血。  ', NULL, NULL, NULL, '山茱萸', NULL, '214、山茱萸  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000332, '9B804BCC4674C6361FEB52A315DC94C1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7818, 437, 902000671, '\n【本经原文】味辛，温，有毒。治风邪气，温中，除寒痹，坚齿，长发，明目。久服轻身，好颜色，耐老，增年，通神。生川谷。  \n\n【产地】椒之一种，产我国陕西甘肃，今处处有之。  \n\n【性味】味辛，性温，有毒。 \n\n【主治】秦椒主温中去寒，除风邪气，治风湿痹，喉痹吐逆，疝瘕老血。 \n\n【别录】疗喉痹，吐逆，疝瘕，去老血，产后余疾，腹痛，出汗，利五脏。 \n\n【甄权】治恶风遍身四肢，疗痹，口齿肿胀摇动，女人月闭不通，产后恶血痢，多年痢，疗腹中冷痛，生毛发，灭瘢。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】用椒红，去目，恶栝楼防葵，畏雌黄，闭口者有毒勿用。参看蜀椒条。 ', NULL, NULL, NULL, '秦椒', NULL, '213、秦椒  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000333, 'B87784E61AB4F6035D6A9CEACBBEC580', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7819, 437, 902000670, '\n【本经原文】味苦，微寒，无毒。治风寒湿痹，洒洒寒气，除热，目中青翳，白膜。久服头不白，轻身。生川谷。  \n\n【产地】生庐江川谷。产我国陕西河南等地，树皮入药。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】秦皮为收敛除热要药，主痢疾带下，男子少精，治风湿痹，目中翳膜，除肝热，补下焦。  \n\n【别录】疗男子少精，妇人带下，小儿痫身热，可作洗目汤，久服皮肤光泽肥大有子。  \n\n【甄权】痛风泪不止，作汤浴小儿身热，煎水澄清洗赤目极效。 \n\n【容川】此药象人之皮，味苦兼降湿热。故仲景用治皮肤发黄之症。\n\n【用量】一般二至五钱。 \n\n【禁忌】里寒之症不用。  ', NULL, NULL, NULL, '秦皮', NULL, '212、秦皮  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000334, 'EA308BE9C8DFDD800155D6C8AAE906AA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7820, 437, 902000669, '\n【本经原文】味苦，温，无毒。治中风，伤寒，头痛，寒热，惊悸气，血痹，死肌，去三虫。生山谷。  \n\n【产地】生交趾山谷。产我国四川河南陕西湖南等地，树皮入药，以厚肉者为良。  \n\n【性味】味苦辛，性温，无毒。 \n\n【主治】厚朴为下实散满，袪湿健胃要药，主温中益气，消痰下气，气血痹，湿霍乱，治中风伤寒头痛，反胃，冷痛，腹满喘咳，杀肠中虫。  \n\n【别录】温中益气，消痰下气，疗霍乱及腹痛胀满，胃中冷逆，胸中呕不止，泄痢淋露，除惊去留热，心烦满，厚肠胃。  \n\n【甄权】治积年冷气，腹内雷鸣虚吼，宿食不消，去结水，破宿血，化水谷，止吐酸水，大温胃气，治冷痛，主妇人虚而尿白。  \n\n【大明】健脾，治反胃霍乱转筋冷热气，泻膀胱及五脏一切气，妇人产前产后腹脏不安，杀肠中虫，明耳目，调关节。  \n\n【好古】主肺气胀满，膨而喘咳。  \n\n【药征】主治胸腹涨满也，旁治腹痛。  \n\n【容川】厚朴本皮，味比枳壳更重，故理脾气，故仲景用枳壳治心下满，用厚朴治腹痛，此为此二药轻重之别所在。厚朴行大肠之气，故肺气得泄。仲景治喘有桂枝加厚朴杏仁汤，即因于此。  \n【用量】普通七分至二钱。 \n\n【禁忌】恶泽泻磁石寒水石，忌豆，性能耗气，凡脾胃虚者忌之，孕妇无故亦忌用。  ', NULL, NULL, NULL, '厚朴', NULL, '211、厚朴  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000335, 'A7229583E06E29DBA31621BEDB199C6D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7821, 437, 902000668, '\n【本经原文】味苦，寒，无毒。治大风在皮肤中，如麻豆苦痒，除寒热结，止利，长肌肉，利五脏，益气轻身。生川泽。  \n\n【产地】生河内川泽。产陕西河南等地，周礼有云，橘逾淮而为枳，即此是也，其实成熟时，早采者为枳实，皮厚而中坚；晚采者为枳壳，皮薄而中虚，皆入药。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】枳实为破气行痰要药，主破结实，消胀满，治胸胁痰癖，心下痞痛，消食散血，去胃中湿热。  \n\n【别录】除胸胁痰癖。逐停水，破结实，消胀满，心下急痞痛逆气，胁风痛，安胃气，止溏 泄，明目。  \n\n【甄权】解伤寒结胸，主上气喘咳，肾内伤冷，阴痿而有气加而用之。  \n\n【元素】消食，散败血，破积坚，去胃中湿热。 \n\n【药征】主治结实之毒，旁治胸满胸痹，腹满腹痛。  \n\n【用量】普通八分至二钱。  \n\n【禁忌】肺气虚弱，脾胃虚，中气不运，而痰壅喘急，咳嗽不因风寒入肺气壅，及咳嗽阴虚 火炎，与一概胎前产后，均忌。  \n\n【容川】枳壳为木实，有木之质，木能疏土，故归脾胃，其味比厚朴轻，故理胃气。 ', NULL, NULL, NULL, '枳实', NULL, '210、枳实  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000336, 'B97265EC3A665A2F1861C55E346A31D3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7822, 437, 902000667, '\n【本经原文】味辛，平，无毒。治五内邪气，散皮肤骨节中淫淫行毒，去三虫，化食，逐寸 白，散腹中嗢嗢喘息。生川谷，一名芜菇。  ', NULL, NULL, NULL, '芜荑', NULL, '209、芜荑  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000337, '8C572750F852F87F96E598DBF0CD94C5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7823, 437, 902000666, '\n【本经原文】味苦，寒，无毒。治五内邪气，胃中热气，面赤，酒疱皶鼻，白癞，赤癞，疮 疡。生川谷。一名木丹。  \n\n【产地】生南阳川谷。处处有之，我国南方及四川尤多产，实又名卮子盖象卮形也。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】栀子为泻火要药，主五内邪气时热，心烦懊憹，泻三焦火，清胃脕血，治五种黄病，通小便，解消渴。  \n\n【别录】疗目赤热疮，胸心大小肠大热，心中烦闷。  \n\n【甄权】去热毒风，除时疾热，解五种黄病，利五淋，通小便，解消渴，明目，主中恶，杀蟅虫毒。  \n\n【元素】治心烦懊憹不得眠，脐下血滞而小便不利。  \n\n【丹溪】泻三焦火，清胃脕血，治热厥心痛，解热郁，行结气。  \n\n【容川】栀子味苦象心包。故能泻心包之火。性苦寒，有皮膈，象心包，内之子赤，正属心之色，其花色白，当属肺金，结子成赤，当属心火，是为从肺入心，正治心中烦热之药。心为君主之官，肺为相傅之官，以制节心火之太过，栀子花白子赤，正是以肺金而归制心火也，故仲景治心中懊憹必用栀子豆豉汤。  \n\n【药征】主治心烦也，旁治发黄。\n\n【灵胎】清胃热，泻肺火。 \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡脾胃虚弱，血虚发热，心肺无邪热，小便闭由膀胱气虚，均忌。  ', NULL, NULL, NULL, '栀子,木丹', NULL, '208、栀子,木丹  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000338, '277D2A7E154437FDBDC3BEA8AB4D1831', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7824, 437, 902000665, '\n【本经原文】味辛，温，有小毒。主温中，下气，止痛，咳逆，寒热，除湿，血痹，逐风邪，开腠理。根，温，杀三虫。久服轻身。生川谷。一名藙。  \n\n【产地】生上谷川谷。处处有之，或曰，吴地最良，故名，其子紧小，气味芳烈。  \n\n【性味】味辛，性温，有小毒。  \n\n【主治】吴茱萸为下气开郁，除风寒湿要药，主温中逐寒，驱风散热，止痛疗痹，治心腹冷痛，下焦冷气，中寒中恶，呕吐泻利，亦杀虫，治口舌生疮。  \n\n【别录】利五脏，去痰冷逆气，饮食不消，心腹诸冷绞痛，中恶心腹痛。  \n\n【甄权】霍乱转筋，胃冷吐泻，腹痛，产后心痛，治遍身瘰痹刺痛。腰脚软弱，利大肠壅气，肠风痔疾，杀三虫。  \n\n【大明】下产后余血，治肾气脚气，水肿，通关节，起阳健脾。  \n\n【容川】味辛气烈，去湿极速。 \n\n【好古】治痞满塞胸，咽膈不通，润肝燥脾。  \n\n【药征】主治呕而胸满。  \n\n【灵胎】驱肝风，逐肺寒。  \n\n【用量】普通三分至钱半。  \n\n【禁忌】多食伤神，令人起伏气，咽喉不通，动火昏目发疮，恶丹参硝石白垩，畏紫石英，凡一切阴虚之证，及五脏六腑有热无寒之人，均忌用吴茱萸。  \n\n【容川】吴茱萸辛而带苦，子性又主下降，故主降水饮，行滞气。专治肝寒之吐逆，此药虽不上头，然可以降肝胃之寒，使不上冲入头，故仲景用之治头痛如破，此为治脏腑而经脉自治也。  ', NULL, NULL, NULL, '吴茱萸', NULL, '207、吴茱萸  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000339, '7FC03654C368CAC271CA466A0596C0CF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7825, 437, 902000664, '\n【本经原文】味苦，平，无毒。治咳逆上气，溢筋急，恶疡，杀小虫。根，作汤，益气，止渴，补虚，下气。汁，治风痉。实，通神明，轻身，益气。  \n\n【产地】为暖地山中之常绿苞木。 \n\n【性味】味辛平，性寒。 \n\n【主治】竹叶为解热，祛痰，止渴，镇静药，止消喝，热狂烦闷及小儿警痫。压丹石毒。  \n\n【别录】治胸中痰热，咳逆上气。  \n\n【大明】消痰，治狂热烦闷，中风失音不语，壮热，头风，头痛，止惊悸，温痔烦闷，妊妇头旋倒地，小儿惊痫天吊。  \n\n【容川】因叶在四旁，则主四散，故能清肌中之热，竹茹象人之筋脉，则清脉络之热以和血，秉天水之寒气，故治一切热。  \n\n【用量】五钱至一两。  \n\n【禁忌】寒症忌用。  ', NULL, NULL, NULL, '竹叶', NULL, '206、竹叶  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000340, '4E2FD3333CE2D720D9130552D3CF5447', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7826, 437, 902000663, '\n【本经原文】味甘，寒，无毒。治伤中，五劳，六极，羸瘦，崩中，脉绝，补虚益气。叶，主除寒热，出汗。桑耳，平。黑者。治女子漏下赤白汁，血病，症瘕积聚，阴痛，阴阳寒热，无子。（王不留行散）  \n\n【产地】处处有之，其根皮入药。  \n\n【性味】味甘辛，性寒，无毒。  \n\n【主治】桑白皮为泻肺火行水道要药，主肺气喘满伤中，益气，开胃，消痰，解渴，治咳嗽吐血，去肺中水气，水肿腹满。  \n\n【别录】去肺中水气，唾血，热渴，水肿腹满胪胀，利水道，去寸白，可以缝金疮。  \n\n【甄权】治肺气喘满，虚劳客热，头痛，内补不足。 \n\n【大明】调中下气，消痰止渴，开胃下食，杀腹脏虫，止霍乱吐泻，研汁治小儿天吊惊痫客忤。及敷鹅口疮，大验。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肺虚无火，因风寒而嗽者均忌。  ', NULL, NULL, NULL, '桑白皮,桑根白皮 ', NULL, '205、桑根白皮,桑白皮', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000341, 'DD8556C3A43CE07532E304BA148A5019', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7827, 437, 902000662, '\n【本经原文】味甘，寒，有小毒。治下热气，益阴精，令人面悦好，明目。久服轻身，耐老。生平泽。  ', NULL, NULL, NULL, '翘根', NULL, '204、翘根  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000342, 'BF68DF5CADCB42FA1884B703BC3B21A6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7828, 437, 902000661, '\n【本经原文】味辛，温，无毒。治寒热，鼠，瘰疬生疮，破结聚气，下瘀血，除湿痹。生川泽。一名鼠蓂。又名荆芥。 \n\n【产地】多生野地，处处有之，气味芳香，茎与叶皆入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】荆芥为发表要药，功能祛风理血，发汗退热。主治寒热头疼诸风疮毒。亦为妇人胎前产后良剂。 【藏器】去邪除劳渴，冷风出汗，煮汁服之，捣烂醋和，敷疔肿毒。  \n【甄权】单用治恶风贼风，口面歪斜，遍身瘰痹，心虚忘事，益力添精，辟邪毒气，通利血 脉，传送五脏不足气，助脾胃。  \n\n【志良】主血劳，风气壅满，背脊疼痛，虚汗，理丈夫脚气，筋骨烦痛，及阴阳毒，伤寒头痛，头旋目眩，手足筋急。  \n\n【日华】利五脏，消食下气醒酒，作菜生熟皆可食，并煎茶饮之，以豉汁煎服，治暴伤寒能发汗。  \n\n【苏颂】治妇人血风，及疮疥为要药。  \n\n【用量】普通八分至二钱。 \n\n【禁忌】凡表虚有汗，血虚寒热，阴虚火炎面赤，因而头痛者均忌。 ', NULL, NULL, NULL, '荆芥,假苏', NULL, '203、假苏,荆芥', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000343, '3B4C193868DFA0DC275D5C3257C1148F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7829, 437, 902000660, '\n【本经原文】味咸，寒，无毒。治腰脊病不得着床，俛仰艰难。除热，可做浴汤。生川谷及田野。又名香苏。  \n\n【产地】处处有之。 \n\n【性味】味咸性寒。 \n\n【主治】散瘀血，镇痛药，治腰痛及杖疮。\n\n【苏敬】疗血胀下气，治杖疮捣汁涂之。  ', NULL, NULL, NULL, '爵床,香苏', NULL, '202、爵床  ,香苏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000344, '8A6EAC5C7F53217F2D96D2F8C6BCF925', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7830, 437, 902000659, '【本经原文】味苦，微寒，无毒。治头秃，恶疮，热气，疥瘙，痂廯虫，龋齿。生川谷，又名羊泉。全草可用。  \n\n【产地】处处有之。 \n\n【性味】味苦，性寒，  \n\n 【主治】为杀虫灭菌药，治疗疥廯，白秃，漆疮及蛀齿。\n\n【别录】女子阴中内伤。皮间积实。 \n\n【苏敬】主小儿惊，生毛发，捣涂漆疮。 \n\n【用量】一般二至四钱。 \n\n【禁忌】多外用，少内服。', NULL, NULL, NULL, '蜀羊泉,羊泉', NULL, '201、蜀羊泉,羊泉', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000345, '7FA0346FAD2B7FA4FD7F4F33E40C5C5B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7831, 437, 902000658, '\n【本经原文】味苦，平，无毒。治五脏邪气，寒湿痹，四肢疼酸，膝冷痛。生川谷及城郭垣 下。吴名白功草。楚名王孙，齐名长孙。  ', NULL, NULL, NULL, '王孙', NULL, '200、王孙  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000346, 'FDDBFF9B6B57E3E2D57ACC44837437B3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7832, 437, 902000657, '\n【本经原文】味辛，温，无毒。治风寒洒洒，霍乱，泻利，肠鸣上下无常处，惊痫，寒热，百疾。生川谷或山阳。  ', NULL, NULL, NULL, '女菀', NULL, '199、女菀  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000347, 'B7613B5FADEF94E718A21DC1269048CE', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7833, 437, 902000656, '\n【本经原文】味苦，寒，无毒。治大热，恶疮，痈疽，浸淫，赤熛，皮肤赤，身热。生川谷。', NULL, NULL, NULL, '积雪草', NULL, '198、积雪草  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000348, 'FE6B7B035DF65CFD8717679FA81955E1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7834, 437, 902000655, '\n【本经原文】味苦，平，无毒。治寒热，鬼疰，中风，湿痹；女子带下病，无子。生川泽，一名马屎蒿。', NULL, NULL, NULL, '马先蒿', NULL, '197、马先蒿  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000349, '92D4AFE8CB117BFD315128A43433F07A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7835, 437, 902000654, '\n【本经原文】一名鼠姑。味辛，寒，无毒。治寒热，中风，瘛瘲，痉，惊痫，邪气，除症坚，瘀血留舍肠胃，安五脏，疗痈疮。生山谷，一名鹿韭，今名丹皮。  \n\n【产地】牡丹处处皆有，庭院亦多种植之，花开美丽而大，为群花之王，色有红白紫等。其根部之皮入药。  \n\n【性味】味辛苦，性微寒（或作性温），无毒。  \n\n【主治】丹皮为理血要药，功能清伏火，凉血热，通月经，排瘀血。主治胎前产后，冷热气血之病，为女科良剂。  \n\n【别录】除时气头痛客热，五劳劳气，腰痛，风噤癫疾。  \n\n【甄权】治冷气，散诸痛，女子经脉不通，血沥腰痛。  \n\n【大明】通关腠血脉，排脓，消扑损瘀血，续筋骨，除风痹，治胎下胞，产后一切冷热血气。\n\n【元素】治神智不足无汗之谷蒸，衄血吐血。  \n\n【容川】其色味如红花，而根性主下达，与花不同，故主内及泄中下焦之血。气属阳，血属阴，瘀血阻气，则阳不入阴，蒸热汗出，宜破其血，使气得入于血中，则不壅热，丹皮主之。气通则热不蒸，此为治热之变法也。色赤味苦，泻火，即能泻血。  \n\n【灵胎】疏肝气，通经脉。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】入血凉血能行血，凡女子血崩，及经血过期不尽，均忌与行血药同用。忌蒜及芫荽铁器。  ', NULL, NULL, NULL, '牡丹皮,牡丹, 丹皮', NULL, '196、牡丹  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000350, 'F3C073E69D39BD2034A7CCB23CC2F0D2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7836, 437, 902000653, '\n【本经原文】一名颗东。一名虎须。一名菟奚。味辛，温，无毒。治咳逆上气，善喘，喉痹，诸惊痫，寒热邪气。生山谷及水傍，一名橐吾。  \n\n【产地】产我国陕西山河西北诸地，为山野多年生草，庭园亦可栽植，百草中惟此不顾冰雪，至冬即生芽而花，故名。  \n\n【性味】味辛甘，性温，无毒。 \n\n【主治】款冬花为润肺祛痰止嗽要药，主治咳逆上气，肺痿肺痈，寒热邪气。  \n\n【别录】消渴，喘息呼吸。 \n\n【甄权】疗肺气心促，急热劳咳，连连不绝，涕唾稠粘，肺痿肺痈吐脓血。  \n\n【大明】润心肺，益五脏，除烦消痰，洗肝明目，及中风等疾。  \n\n【用量】普通钱半至三钱。 \n\n【禁忌】咳逆消渴喘急，皆火炎气逆之病，款冬隆冬独秀，辛散而润，甘缓而和，故虚实寒热皆可用，无禁忌。  \n\n【容川】此药生于冬月冰雪之中，而花又在根下，乃坎中之阳象，故能引肺中阳气下行，而 为利痰止咳之要药。  ', NULL, NULL, NULL, '款冬花', NULL, '195、款冬花  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000351, 'C80C6A1D180FE53735DB81A76D7C8D80', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7837, 437, 902000652, '\n【本经原文】味辛，平，无毒．治风寒，温疟，热气，诸痫，除邪，利大小便，通腠理，利九窍。生川谷。一名解离。  \n\n【产地】产我国四川陕西及贵州，有汉防己及木防己两种根俱入药。  \n\n【性味】味辛苦，性寒，无毒。  \n\n【主治】防己为通膀胱利小便要药，主行全身祛风行水，泻下焦血分湿热，治水肿，淋病，散痈肿恶结。  \n\n【别录】疗水肿风肿，去膀胱热，伤寒热邪气，中风手脚挛急，通腠理，利九窍，止泄，散 痈肿恶结，诸瘑疥癣虫疮。  \n\n【甄权】治湿风，口面歪斜，手足拘痛，散留痰肺气喘嗽。 木防己主治男子肢节中风，毒风不语，散结气痈肿温疟，风水肿，去膀胱热。  \n\n【容川】能去湿热，属苦降之品，其形中空，纹如车轮，能外行腠理，内行三焦，能通水气。味似龙胆，能利水行。  \n\n【元素】治中下湿热肿泄脚气，行十二经。\n\n【药征】主治水也。 \n\n【用量】普通一至二钱。  \n【禁忌】凡肾虚阴虚，自汗盗汗，口舌苦干，肾虚小便不利，及产前后血虚，虽有下焦湿热，均忌。  ', NULL, NULL, NULL, '防己', NULL, '194、防己  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000352, 'D8C49E5E7BD8072B9C71DAA749F01860', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7838, 437, 902000651, '\n【本经原文】一名龙枣。味苦，微温，无毒。治乳妇衄血，中风余疾，大腹水肿，身面四肢浮肿，骨节中水，金疮，痈肿疮脓。生诸大泽旁。一名虎兰。  \n\n【产地】生于溪涧或湿地，叶类薄荷，根紫黑色，叶与子根（地笋）皆入药。  \n\n【性味】味苦甘，性微温，无毒。 \n\n【主治】泽兰为女科要药，功能行血消水，主养血气，破宿瘀，消症瘕痈肿，胎前产后诸病。  \n\n【甄权】产后腹痛，频产血气衰冷，成劳瘦羸，妇人血沥腰痛。 \n\n【大明】胎前产后百病，通九窍，利关节，养血气破宿血，消症瘕，通小肠，长肌肉，消扑损瘀血，治鼻血吐血，头风目痛，妇人劳瘦，丈夫面黄。  \n\n【灵胎】清湿热，治水肿。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】破血通积，大虚不宜。', NULL, NULL, NULL, '泽兰', NULL, '193、泽兰  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000353, 'CBB1FE250020409140E596F7A4CA6168', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7839, 437, 902000650, '\n【本经原文】味苦，寒，无毒．治瘿瘤气，颈下核，破散结气，痈肿，症瘕，坚气，腹中上下鸣，下十二水肿。生东海池泽。一名落首。  \n\n【产地】产海岛中，为藻类之产于海中者，种类颇多，入药用马尾藻。  \n\n【性味】味咸，性寒，无毒。 \n\n【主治】海藻为除热软坚要药，主瘿瘤瘰疬，治瘫肿老痰，通血脉，利小便。  \n\n【别录】疗皮间积聚，暴溃瘤气，结热，利小便。 \n\n【甄权】辟百邪鬼魅，治气急心下满，疝气下坠，疼痛卵肿，去腹中幽幽作声。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】脾家有湿者忌。 \n\n【容川】海藻昆布皆生于水中，味微咸，又具草之质，是禀水木二气而生，故能清火润肝。  ', NULL, NULL, NULL, '海藻', NULL, '192、海藻  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000354, '04267E57A63827CE8989FC5750D5FF3D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7840, 437, 902000649, '\n【本经原文】味苦，微寒，无毒。治妇人乳痉痛、七伤、带下十二病，止痛，除恶肉，止汗气。消酒，明目，治金疮。生山谷。  \n\n【产地】生山间向阳之地，今处处平原川泽亦有之，根直而柔，入药。  \n\n【性味】味苦【或作苦甘酸】，性微寒，无毒。 \n\n【主治】地榆为止血收敛要药，功能止吐血下血久痢，妇人崩带。  \n\n【用量】普通二钱至三至四钱。 \n\n【禁忌】性寒下行，脾胃虚寒作泄，白痢久而胃弱，胎产虚寒泄泻，血崩脾虚作泄，均忌，恶麦冬，丹砂，硫黄，雄黄。  ', NULL, NULL, NULL, '地榆', NULL, '191、地榆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000355, '1651CEBD2AE039373C4ADCFA4654C470', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7841, 437, 902000647, '\n【本经原文】味辛，寒，无毒．治暴热身痒，下水气，胜酒，长须发，止消渴。久服轻身。生池泽水上．一名水花或浮萍。  \n\n【藏器】捣汁服，主水肿，利小便。 \n\n【大明】治热毒，风热，热狂，熁肿毒，汤火伤，风疹。  \n\n【元素】下气，以沐浴生毛发。  \n\n【灵胎】其性清浮，治在肌表。  \n\n【用量】普通八分至二钱。 \n\n【禁忌】发汗力猛，证非大实大热者，不可轻用，表虚自汗者尤忌。  \n\n【附方】 水气洪肿——小便不利者，浮萍日干为未，每服方寸匕，日二。身上虚痒——浮萍末一钱，以黄芩一钱，用四物汤煎汤调下。  ', NULL, NULL, NULL, '浮萍,水萍,水花', NULL, '189、浮萍,水萍,水花', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000356, 'EEDC089586FDE9D44AA24BC216FEE200', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7842, 437, 902000648, '\n【本经原文】味苦，寒，无毒．治消渴，内痹，瘀血，月闭，寒热，酸疼。益气，愈聋。生平泽田野及人家垣墙间．一名土瓜。  \n\n【产地】产山东平泽田野，各地亦存栽种，多蔓生墙垣问，根及子入药。  \n\n【性味】味苦，性寒，无毒。（或作小毒）。 \n\n【主治】王瓜根主泻热，利水，行血，益气，治天行热疾，消渴，痞满，热结，黄疸变黑，妇女经闭。  \n\n【别录】疗诸邪气，热结鼠瘘，散痈肿流血，妇人带下，下乳汁不通，止小便数不禁，逐四肢骨节中水，治马谷刺人疮。  \n\n【大明】天行热疾，酒黄病，壮热心烦闷，热劳，排脓，消扑损瘀血，破症癖，落胎。  \n\n【用量】普通一至二钱。 \n\n【禁忌】能使人吐下，不宜多服。  ', NULL, NULL, NULL, '王瓜', NULL, '190、王瓜  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000357, '8A5FBF8BCE9E0F553119401E74410831', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7843, 437, 902000646, '\n【本经原文】味苦，平，无毒。治暴中风，身热，肢满，忽忽不知人。狂惑，邪气，寒热，酸疼，温疟洒洒、发作有时。生平原、川谷。 \n\n【产地】产陕西及关外，生平原川谷间，茎叶俱青，根黄白色入药。 \n\n【性味】味苦咸，性平，无毒。阳明冲任之药。 \n\n【主治】白薇为凉血退热要药，功能清虚火，除胃热，主治身热肢满，风温灼热，汗出热不退，妇人身热，伤中淋露。 \n\n【别录】疗伤中淋露，下水气，利阴气，益精。 \n\n【弘景】治惊邪风狂痣病，百邪鬼魅。 \n\n【本草】主治中风，身热支满，忽忽不知人，血虚，热淋，温疟，洗洗寒热酸痛。妇人伤中淋露，产虚烦呕。 \n\n【用量】普通一钱至二钱。 \n\n【禁忌】恶大黄，大戟，山茱，姜枣。  ', NULL, NULL, NULL, '白薇', NULL, '188、白薇  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000358, 'D1997B79182B45DF70E3C791D015678D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7844, 437, 902000645, '\n【本经原文】味苦，平，无毒。治腰背痛，强骨节，风寒湿周痹，恶疮不瘳，热气。生山谷。\n\n【产地】处处有之。 \n\n【性味】甘苦性平。功能除浊分清。 \n\n【主治】入足阳明厥阴，祛风去湿，以固下焦，补肝虚，坚筋骨，益睛明目。恶疮梅毒及淋浊。 \n\n【本草】主治风寒湿痹。腰痛久冷，关节老血。膀胱宿水，阴痿，茎痛，遗浊，痔瘘，恶疮。\n\n【别录】阴痿失溺，老人五缓，关节老血。 \n\n【甄权】冷气节痹，腰脚瘫缓不遂，手足惊挚，男子腰痛，久冷，膀胱宿水。 \n\n【用量】有黄白二种，黄长硬，白虚软，软者佳。一般用四至五钱，大剂量用一两。 \n\n【禁忌】下焦有寒之人忌用。阴虚内热者禁服。  ', NULL, NULL, NULL, '萆薢', NULL, '187、萆薢  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000359, 'F6F2BF9E4FAF8D97689DBD5D249DECEC', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7845, 437, 902000644, '【本经原文】味苦，平，无毒。治劳热邪气，五癃，闭不通，利小便水道。生山谷石上。\n\n 【产地】产我国山西安徽福建等地，多生山中石上及阴湿之地，他处亦多有之，叶入药。\n\n【性味】味甘，（或作苦），性寒，（或作平），无毒。 \n\n【主治】石苇为利尿治淋要药，主清肺火以滋源，通膀胱以利水，益精气，治淋闭。 \n\n【别录】止烦下气，通膀胱满，补五劳，安五脏，去恶风，益精。 \n\n【日华】治淋沥遗溺。 \n\n【苏颂】炒末冷酒调服，治发背。 \n\n【用量】普通一至二钱。 \n\n【禁忌】制丹砂矾石，得菖蒲滑石射干良。  ', NULL, NULL, NULL, '石苇', NULL, '186、石苇  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000360, 'B743F11667DC0EB5EC6EA0DCB8156E23', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7846, 437, 902000643, '\n【本经原文】一名地新。味辛，温，无毒。治妇人疝瘕，阴中寒肿痛，腹中急，除风头痛，长肌肤，悦颜色。生山谷。名鬼卿。  \n\n【性味】味苦辛，性温。 \n\n【主治】鬼卿为祛风寒镇痛要药，治大寒犯脑头痛齿亦痛，女人阴寒肿痛，体肤风湿。\n\n 【东垣】头面身体皮肤风湿。 \n\n【大明】治皮肤疵皯，酒皻，粉刺，癫疾。 \n\n【元素】治太阳头痛，巅顶痛，大寒犯脑，痛连齿颊。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】热病头痛，血虚头痛，均忌服。  \n\n【附方】头屑干洗—槀本，白芷等份共末，夜擦旦梳，垢自去。', NULL, NULL, NULL, '槀本', NULL, '185、槀本  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000361, 'F103CEC0B71796FE0D27CC6A394E5822', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7847, 437, 902000642, '\n【本经原文】味苦，寒，无毒。治心腹积聚，寒热邪气。通九窍，利大小便。治牛病。生山谷。一名牡蒙。  \n\n【产地】珍珠菜之地下茎谓之紫参，多产于深山溪涧之旁，色紫黑。  \n\n【性味】味苦，性寒，无毒。 \n\n【主治】紫参为破血通经要药，功能治心腹寒热积聚，产后恶露不行。\n\n【别录】疗肠胃大热，唾血衄血，肠中聚血，廱肿诸疮，止渴益精。 \n\n【甄权】治心腹坚胀，散瘀血，治妇人血闭不通。 \n\n【好古】主狂疟温疟，鼽血，汗出，治血痢。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】畏辛夷。  ', NULL, NULL, NULL, '紫参', NULL, '184、紫参  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000362, '80A949DC072218E7AB9617389C891392', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7848, 437, 902000641, '\n【本经原文】味酸，平，无毒。治热，烦满，定志，益气，利水道。产难，吞其实立产。生川泽及人家田园中，一名醋浆。又名洛神珠。灯笼草。  \n\n【产地】田园之中。 \n\n【性味】其根及苗味苦，性寒。酸浆果味酸，性平。 \n\n【主治】其苗，叶，根，茎皆为解热，排水药，治百日咳，黄疸，小便赤涩，果能催生。\n\n【别录】酸浆果主治烦热，定志益气，利水道，难产吞之，立产。 \n\n【弘景】酸浆捣汁服，治黄病多效。 \n\n【唐本】灯笼草治上气咳嗽，风热，明目，根茎花实并用。 \n\n【苏颂】酸浆果食之除热，治黄疸，尤宜小儿。 \n\n【用量】一般一钱至四钱。 \n\n【禁忌】孕妇禁忌', NULL, NULL, NULL, '酸浆,醋浆,洛神珠,灯笼草', NULL, '183、酸浆,醋浆,洛神珠,灯笼草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000363, 'A25AF97811695AB91523E84CEAC61EB4', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7849, 437, 902000640, '\n【本经原文】味苦寒，无毒，治头风，黄疸，咳逆淋漓，女子阴中肿痛。生川谷。\n\n【产地】处处有之，以四川者为良。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】白鲜皮主治头风黄疸，天行时疾。 \n\n【别录】疗四肢不安，时行腹中大热，饮水欲走大呼，小儿惊痫，妇人产后余痛。  \n\n【甄权】治一切热毒风，恶风，疮疥癣赤烂，眉发脱脆，皮肌急，壮热恶寒，解热黄，酒黄，急黄，谷黄，劳黄。 \n\n【大明】通关节，利九窍，及血脉，通小肠水气，天行时疾，头痛眼疼，其花同功。 \n\n【用量】钱半至三钱。 \n\n【禁忌】不详  ', NULL, NULL, NULL, '白鲜皮', NULL, '182、白鲜皮  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000364, 'D34152313B53B98E556C11974CE9E6EF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7850, 437, 902000639, '\n【本经原文】一名鹿肠．味苦，平，无毒。治暴热，火疮赤气，疥瘙，疽，痔，马鞍热气。生川谷。  \n\n【产地】处处有之，生川谷间。 \n\n【性味】味苦【或作咸】，性平（或作寒），无毒。 \n\n【主治】败酱草主治赤眼，障膜，弩肉，聤耳，痈肿结热，破凝聚血，化脓为水。 \n\n【别录】除痈肿，浮肿，结热，风痹不足，产后痛。 \n\n【甄权】治毒风瘰痹，破多年凝血，能化脓为水，产后诸病，止腹痛，余疹烦渴。 \n\n【大明】治血气心腹痛，破症结，催生落胞，血运鼻衄，吐血，赤白带下，赤眼障膜，弩肉，聤耳，疮疖疥癣，丹毒，排脓补瘘。 \n\n【用量】普通一二钱。 \n\n【禁忌】忌葱，性专下泄，无瘀者忌。', NULL, NULL, NULL, '败酱', NULL, '181、败酱  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000365, '322BEF5135826BEEAAE7B8D98F735158', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7851, 437, 902000638, '\n【本经原文】味苦，寒，无毒。治心腹邪气，五疸，补中益气，利九窍，通水道。一名紫丹。一名紫芙。  \n\n【产地】为山野自生之宿根草，园圃亦可栽种，产于寒地野生之根为良。  \n\n【性味】紫草味甘咸，性寒，无毒。 \n\n【主治】紫草为痧痘要药，功能凉血，活血，透发解毒，治恶疮天花，麻疹及小儿疮疖与面皻。  \n\n【别录】通水道，疗肿胀满痛，以合膏疗小儿疮及面皻。  \n\n【灵胎】淸血除邪。 \n\n【用量】普通二钱至三钱，大剂一两。 \n\n【禁忌】痘已出而红活及白陷，脾胃肠虚寒大便溏者忌服。', NULL, NULL, NULL, '紫草,紫丹,紫芙', NULL, '180、紫草,紫丹,紫芙', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000366, '4DC610478B2F68FD4CB6D00B9BF2A403', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7852, 437, 902000637, '\n【本经原文】味苦，温，无毒。治咳逆上气，胸中寒热结气，去蛊毒，痿厥，安五脏．一名 青菀。  \n\n【产地】为山野多年生草本，产我国中部，庭园亦可栽植，其花美丽，根状似细辛，其质柔轫，入药。  \n\n【性味】味苦辛，性温，无毒。  \n\n【主治】紫苑为祛痰止咳要药，主治咳逆，痰涎，吐脓血，益肺气。\n\n【别录】疗咳唾脓血，止喘悸，五劳体虚，补不足，小儿惊痫。  \n\n【甄权】治尸疰，补虚下气，劳气虚热，百邪鬼魅。\n\n【大明】调中消痰，止渴润肌肤，添骨髓。  \n\n【好古】益肺气，主息贲。  \n\n【用量】普通七分至钱半。  \n\n【禁忌】肺病咳逆喘嗽，皆阴虚肺热也，忌独用多用，即用亦须与二冬百部桑皮等苦寒药参用，方无害以其性温也。  ', NULL, NULL, NULL, '紫苑', NULL, '179、紫苑  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000367, '82713EFDDC41D6F49A2B953C5C4DBB4F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7853, 437, 902000636, '\n【本经原文】味甘，寒，无毒。治劳伤、虚羸，补中益气，除瘀血、血闭、寒热，利小便。其苗，主下水。一名兰根。一名茹根。 \n\n【产地】生于原野路傍之宿根草，产楚地，今处处皆有。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】白茅根为止血利尿要药，功能止吐血行瘀血，治消渴水肿，不伤胃气。 \n\n【别录】下五淋，客热在肠胃，止渴，坚筋，妇人崩中。 \n\n【大明】主妇人月经不匀，通血脉，淋沥。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】不宜遇铁。胃寒脾湿者忌之。 ', NULL, NULL, NULL, '茅根,兰根,茹根', NULL, '178、茅根,兰根,茹根', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000368, '5D384619941A5A8FC55DC6421DD627A9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7854, 437, 902000635, '\n【本经原文】味苦，平，无毒。治风寒湿痹，心腹邪气，利关节，止烦满。久服轻身、明目、不老。一名鲁果能。一名地椹。  \n\n【产地】产山东等地，生川泽石边，子入药。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】石龙芮主治风寒湿痹，利关节，养胃气，能强阴益精。  \n\n 【别录】平肾胃气，补阴气不足，失精茎冷，令人皮肤光泽有子。\n\n【大明】逐诸风，除心热燥。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】宜大戟为使，畏茱萸蛇蜕皮。  ', NULL, NULL, NULL, '石龙芮,地椹,鲁果能', NULL, '177、石龙芮  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000369, '25DA1BE0AA881B46561F6A5C12E6E127', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7855, 437, 902000634, '【本经原文】味苦，平，无毒。治腰背强。关机缓急，周痹，寒湿膝痛。颇利老人。一名百枝。 \n\n【产地】产山野湿地自生之宿根草，根黑色，长而多岐似狗脊，故名。 \n\n【性味】味苦甘，性微温（或作平），无毒。 \n\n【主治】狗脊为益气血，强筋骨要药，功能治肝虚肾亏，脚弱腰痛，筋肉拘急，失溺淋露。\n\n【别录】疗失溺不节，男女脚弱腰痛，风邪淋露，少气，目暗，坚脊，利俯仰，女子伤中关节重。 \n\n【甄权】男子女人毒风软脚，肾气虚弱，续筋骨，补益男子。 \n\n【灵胎】去寒湿，强筋骨。 \n\n【用量】普通钱半至三四钱。 \n\n【禁忌】肾虚有热，小水不利或短涩黄赤，口苦舌干，均忌，恶香附败酱草。  ', NULL, NULL, NULL, '狗脊', NULL, '176、狗脊  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000370, 'B4E05589664DA21E36BE576B56FA8E73', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7856, 437, 902000633, '\n【本经原文】味苦，平，无毒。治诸热，黄疸，肠澼，泄利，逐水，下血闭。恶疮，疽蚀，火疡。一名腐肠。  \n\n【产地】生秭归川谷。产山谷间，亦为园圃之多年生草，根深黄色带褐。  \n\n【性味】味苦，性平，无毒。  \n\n【主治】黄芩为清热要药，功能去心肺大小肠诸经之热，肝胆之火。主治黄疸，肠澼泄利，风热，湿热：天行热疾，女科养阴安胎。  \n\n【别录】疗痰热，胃中热，小腹绞痛，消谷，利小肠，女子血闭，淋露下血，小儿腹痛。  \n\n【甄权】治热毒骨蒸，寒热往来，肠胃不利，破壅气，治五淋，令人宣畅，解热渴。  \n\n【容川】黄芩味苦，中多空虚，有孔道，人身惟三焦；是行水气之孔道主相火，故主清相火，火逆呕苦、黄芩为正药。此药苦而色绿，故能入瞻。  \n\n【药征】治心下痞也，旁治胸胁满，呕吐下利也。  \n\n【灵胎】清热止利。  \n\n【用量】普通钱半至三钱。  \n\n【禁忌】过服损胃，血虚寒中者忌。  ', NULL, NULL, NULL, '黄芩', NULL, '175、黄芩  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000371, '59DC24BD93CCCDB51B5815444FF7FAD1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7857, 437, 902000632, '\n【本经原文】味辛，寒，无毒。治阴痿，绝伤，茎中痛，利小便，益气力，强志。一名刚前。\n\n【产地】产四川北部，据云其地有淫羊，一日百遍合，乃食此霍所至，叶为卵圆形类杏叶，入药。  \n\n【性味】味辛苦，性温（或作小寒）  \n\n【主治】淫羊霍为壮阳益精要药，功能治阳痿茎痛，坚筋骨，利小便。  \n\n【大明】治丈夫绝阳无子，女人绝阴无子，老人昏耄，中年健忘，一切冷风劳气，筋骨挛急，四肢不仁，补腰膝，强心力。  \n\n【用量】普通钱半至三钱。 \n\n【禁忌】凡虚阳易举，梦遗不止，便赤口干，强阳不痿均忌。得酒良。  ', NULL, NULL, NULL, '淫羊藿', NULL, '174、淫羊藿  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000372, '22E7D86B613DB098502CCB117E32EB74', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7858, 437, 902000631, '\n【本经原文】味辛，温，无毒。治女人漏下赤白、血闭、阴肿、寒热、风头侵目泪出，长肌肤。润泽。可作面脂。  一名芳香。一名虈。  \n\n【性味】味辛，性温，无毒。 \n\n【主治】白芷为散风表汗要药，功能通窍去湿，疗风行血，止头痛，和肠胃，烧之辟邪气。\n\n【别录】疗风邪，久渴吐呕，两胁满，头眩目痒。 \n\n【甄权】能蚀脓，止心腹血刺痛，女人沥血腰痛血崩。 \n\n【大明】治目赤努肉，去面皯疵瘢，补胎漏滑落，破宿血，补新血，乳痈，发背，一切痈疮疥癣，止痛排脓。  \n\n【元素】解利手阳明头痛，中风寒热，及肺经风热，头面皮肤风痹燥痒。  \n\n【灵胎】驱风燥湿。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】呕吐由于火，漏下赤白，阴虚火炽。病由血热所致者，均忌。恶旋覆花，制雄黄硫黄。  \n\n【容川】白芷辛香，色白入肺，入阳明陉，根性又主升，故能升散肺与阳明之风寒。  ', NULL, NULL, NULL, '白芷', NULL, '173、白芷  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000373, '719E84578527F759AEAFCADE2E5083D5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7859, 437, 902000630, '\n【本经原文】味辛，平，无毒。治伤寒烦热，淋沥邪气，疝瘕。喉痹，乳难，金疮，风痉。一名空草。 \n\n【产地】生晋地。产四川山西等地，为圆球形之根。色白入药，今浙江亦有之，称浙贝母，功用稍异。\n\n【性味】味辛苦，性平无毒。 \n\n【主治】贝母为袪痰治咳要药，功能散结泄热，润肺清火，治烦热疮疡。 \n\n【别录】疗腹中结实，心下满，洗洗恶恶，风目眩项直，咳嗽上气，止烦热渴，出汗。 \n\n【大明】消痰润心肺。末和沙糖丸含之，止嗽，烧灰油调，传人畜恶疮，敛疮口。 \n\n【容川】色白性平，利胸肺之痰气。 \n\n【药征】主治胸膈郁结痰饮。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】寒湿痰食痰嗽，湿痰在胃，恶心欲吐，痰饮作寒热，脾胃湿痰作眩，及痰厥头痛，中恶呕吐，胃寒作泄，法宜用辛温燥热者，均忌贝母。  ', NULL, NULL, NULL, '贝母,空草', NULL, '172、贝母  ,空草', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000374, '24365F5416F411FC6B285B50856BB56C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7860, 437, 902000629, '\n【本经原文】味苦，寒，无毒。治消渴，热中，除邪气。肢体浮肿。下水，补不足。益气。  \n\n一名蚳母。一名连母。一名野蓼，一名地参。一名水参。一名水浚。一名货母。一名蝭母。\n\n【产地】我国河内川谷濒河，及解州滁州多产之，为多年生草根横生，类万年青。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】知母为清凉解热要药，功能泻肺火，清胃火，下水消肿，利二便。 \n\n【别录】疗伤寒久疟烦热，胁下邪气，膈中恶，及风汗内疽，多服令人泄。 \n\n【甄权】心烦燥闷，骨热劳往来，产后蓐劳，肾气劳。憎寒虚烦。 \n\n【大明】热劳传尸疰痛，通小肠，消痰止嗽，润心肺，安心止惊悸。 \n\n【元素】凉心去热，治阳明火热，泻膀胱肾经火热，痰厥头痛，下痢腰痛，喉中腥臭。 \n\n【好古】泻火而上清肺金，滋水而下润肾燥，治命门相火有馀。 \n\n【容川】知母叶至难死。拔之犹生，即知其得水气多，故能清气分之热。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】能滑肠，泄泻者忌，阳痿及易举易痿，脾弱饮食不化，胃虚不思食，均忌，勿犯铁器，得黄相及酒良。  ', NULL, NULL, NULL, '知母,蚳母,连母,野蓼,地参,水参,水浚,货母,蝭母', NULL, '171、知母 ,蚳母,连母,野蓼,地参,水参,水浚,货母,蝭母', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000375, '07604A296CDC694DE1ED3A812E062841', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7861, 437, 902000628, '【本经原文】味甘，平，无毒。治邪气腹胀，心痛，利大小便。 补中益气。生山谷。  \n\n【产地】处处有之，生山谷中，种类颇多，以味苦者为真，白花者为良，根入药。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】百合为清凉退热要药，主润肺宁心，清热止咳，补中益气，治百合病，肺病，吐血。\n\n【别录】除浮肿胪胀，痞满寒热。通身疼痛，及乳难喉痹，止涕泪。 \n\n【甄权】百邪鬼魅，涕泣不止。除心下急满痛，脚气热咳。  \n\n【大明】安心定胆益志，养五脏，治颠邪狂叫惊悸，产后血狂运，杀虫毒气，胁痈乳痈发背 诸疮肿。  \n\n【元素】温肺止嗽。  \n\n【灵胎】补肺益气。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】中寒者勿服。   如天下之下垂，本天清之气。皆入气分。以敛肺气。  \n\n【炮制】拣去杂质，筛去灰即得。 ', NULL, NULL, NULL, '百合', NULL, '170、百合  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000376, '306F6BA779863DB98883C100AF6F32DC', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7862, 437, 902000627, '\n【本经原文】味苦，平，无毒。治寒热邪气，寒湿风痹，肢节痛。下水，利小便。一名秦瓜。\n\n【产地】产我国陕西河北河南等地，生山谷中，根做土黄色，以有罗纹相交者良。 \n\n【性味】味苦辛，性平，无毒。 \n\n【主治】秦艽为治风湿要药，功能清风热治湿热，主寒热身酸痛，黄疸酒毒，养血，荣筋，安胎。 \n\n【别录】疗风无问久新，通身挛急。 \n\n【甄权】利大小便，疗酒黄，黄疸，解酒毒，去头风。 \n\n【大明】傅尸骨蒸，治疳疾及时气。 \n\n【元素】除阳明风湿，及手足不遂，口噤牙痛，口疮，肠风泻血，养血荣筋。 \n\n【好古】泄热，益胆气。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】下部虚寒人及小便不禁者均忌。 \n\n【吴克潜】秦艽味苦能杀虫、故外科亦用之，时珍曰：阳明有湿则身体疼烦热，阳明有热则日晡潮热骨蒸，沈金鳌曰感受风寒发热，遍身疼痛，必以秦艽治之，以其能散结除邪也。 \n\n【容川】秦艽肌纹多，左右交缠。故治左右偏风，筋脉疼痛之症，利于续接经脉。  ', NULL, NULL, NULL, '秦艽', NULL, '169、秦艽  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000377, '17CF13C29EFBA8974CE52177758C0584', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7863, 437, 902000626, '【本经原文】味苦，微寒，无毒。治腹中寒热积聚，女子产乳余疾。补肾气，令人目明。一名重台。又名黑参，元参。 \n\n【产地】处处原野多产之，根直而肥大，生时本白色，切片后即变黑。 \n\n【性味】味苦，性微寒，无毒。 \n\n【主治】元参为清火退热要药，功能治一切实热，狂热，燥热，肿疡，瘰疬。 \n\n【别录】暴中风伤寒，身热又满，狂邪忽忽不知人，温疟洒洒，血瘕，下寒血，除胸中气，下水，止烦渴，散颈下核，痈肿，心腹痛，坚症。 \n\n【甄权】热风头痛，伤寒劳复，暴结热，散瘿瘤瘰疬。 \n\n【大明】治游风，补劳损，心惊烦躁，骨蒸，传尸邪气，消肿毒。 \n\n【纲目】滋阴降火，解斑毒，利咽喉，通小便血滞。 \n\n【灵胎】育阴滋水。 \n\n【用量】普通钱半至三四钱，大剂一二两。 \n\n【禁忌】凡血少目昏，停饮支满，血虚腹痛，脾虚泄泻，均忌。恶黄耆干姜、茴香山萸，反 藜芦勿犯铜铁。 ', NULL, NULL, NULL, '玄参', NULL, '168、玄参  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000378, '819CA2349701DCFF73650EB7CC7F888F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7864, 437, 902000625, '【本经原文】味苦，寒，无毒。治关格，诸癃结，小便不通。出刺，决痈肿，去翳，破胎堕 子，下闭血。一名巨句麦。  \n\n【产地】为山野河边自生之宿根草，子黑色扁平，入药。  \n\n【性味】味苦，性寒，无毒。 \n\n【主治】瞿麦为利水破血要药，主五淋，治小便癃闭，月经不通，降心火，利小肠。  \n\n【别录】养肾气，逐膀胱邪逆，止霍乱，长毛发。\n\n【大明】主五淋，月经不通，破血块排脓。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】瞿麦性猛利，善下逐，凡肾气虚，小肠无大热，胎前产后一切虚人患小水不利，及水肿鼓胀脾虚者均忌，能堕胎孕妇忌用，恶螵蛸，伏丹砂。 王执中曰五淋大抵皆属湿热，热淋用八正散（瞿麦萹蓄车前滑石甘草山栀仁木通大黄），血淋宜小蓟牛膝膏，肾虚淋宜补肾，不可独泻，老人气虚者。宜参术加木通山栀，亦有痰滞中焦作淋，宜行痰兼通利药，最忌发汗，汗之必便血。', NULL, NULL, NULL, '瞿麦', NULL, '167、瞿麦  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634197084000379, '332F46ABE79432205EDF5C7091AFAF8F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 11:34:35', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7865, 437, 902000712, '\n【本经原文】味辛，微温，无毒。主下气，杀谷，除饮食，辟口臭，去毒。辟恶气。久服通神明，轻身，耐老。生池泽。一名芥蒩。', NULL, NULL, NULL, '水苏', NULL, '254、水苏  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724933, 'E03023CF809E3709811917AA1F6029B8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7866, 437, 902000711, '\n【本经原文】味辛，温，无毒。主明目，补中不足。\n\n其茎，平，作汤，治伤寒寒热，出汗，中凤，面目肿。\n\n薤，味辛，温，无毒。治金疮疮败，轻身，不饥，耐老。生平泽。  ', NULL, NULL, NULL, '葱实', NULL, '253、葱实  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724934, 'CBF7968843112227C1E4A2A7CFFB22DF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7867, 437, 902000710, '\n【本经原文】味辛，温，无毒。主明目，温中，耐风寒，下水气，面目浮肿，痈疡。马蓼，去肠中蛏虫，轻身。生川泽。  ', NULL, NULL, NULL, '蓼实', NULL, '252、蓼实  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724935, 'A4E6EC279454C0C17F4AD6CA952D0943', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7868, 437, 902000709, '\n【本经原文】味甘，温，无毒。主益气补中。多热，令人烦。\n \n 丹黍米，味苦，微温，无毒。主咳逆，霍乱，止泄，除热，止烦渴。  ', NULL, NULL, NULL, '黍米', NULL, '251、黍米  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724936, 'EBE4B5492E19B1764C59EFF51D60D72C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7869, 437, 902000708, '\n【本经原文】味咸，微寒，无毒。主养肾气：去胃中脾中热，益气。陈粟，味苦，寒，无毒。主胃熟，消渴，利小便。', NULL, NULL, NULL, '粟米', NULL, '250、粟米  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724937, 'B65403A9EEF523760A5CBC5D11AE9BA0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7870, 437, 902000707, '\n【本经原文】味甘，平，无毒。治湿痹，筋挛，膝痛。\n\n  生大豆。平。涂痈肿，煮汁饮，杀鬼毒。止痛。\n\n  赤小豆，平。主下水，排痈肿脓血。生平泽。  \n\n【产地】黑大豆所制成，处处有之。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】大豆黄卷为清热开胃，推陈去积要药，主行水去湿，胃气结积，治湿痹筋挛膝痛。\n\n【别录】五脏不足，味气结积，益气止痛，去黑皯，润肌肤皮毛。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】恶海藻龙胆。  ', NULL, NULL, NULL, '大豆黄卷', NULL, '249、大豆黄卷  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724938, 'F742AA016C6D4BBFE9709D3871C7384D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7871, 437, 902000706, '\n【本经原文】味酸，平，无毒。主下气，除热，烦满，安心，止肢体痛，偏枯不仁，死肌，去青黑痣，恶疾。能益气，不饥。生川谷。 \n\n【产地】生汉中川谷。即梅花之实，有乌梅与白梅二种，处处有之。乌梅系采半黄之梅实，用烟熏黑，再以稻草灰淋汁润湿蒸过，白梅又叫盐梅，用大青梅实用盐腌渍，日晒夜渍，十日即成。 \n\n【性味】乌梅味酸，性平而涩：白梅味酸咸，性平。  \n\n【主治】乌梅为收敛，解热，消肿，驱虫之药，治久利，痢疾，反胃，去面痣，蚀恶肉，蚘 厥吐利，反胃膈噎。驱蛔虫。白梅与乌梅之效用相同。 \n\n【别录】去痹，利筋脉，止下痢，好唾口干。 \n\n【藏器】止渴，调中，去痰，治瘴疟。止吐逆霍乱，除冷热利。 \n\n【大明】治虚劳骨蒸，消酒毒，令人得睡，和建茶干姜为丸服，止休息痢大验。 \n\n【弘景】白梅和药点痣，蚀恶肉。水渍汁饮治伤寒烦热。 \n\n【时珍】敛肺，涩肠，止久嗽泻利，反胃咦膈，蛔厥吐逆，消肿涌痰，杀虫，解鱼毒，硫磺 毒。 \n\n【容川】乌梅极酸，能敛肝木之阳，能化蛔虫，能去坏肉，此是以木来克土，酸能收之义。\n\n【汪颖】治乳痈肿毒，杵烂贴之佳。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】多食梅肉损齿伤筋。凡风寒初起，疟痢未久者均忌，忌猪肉。  ', NULL, NULL, NULL, '梅实', NULL, '248、梅实  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724939, 'AB309DAE7405A04F9362C6650BCB824D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7872, 437, 902000705, '\n【本经原文】味咸，平，无毒。治目瞑，明目，夜视有精光。久服令人喜乐、媚好、无忧。  生川谷及人家屋间。一名蝙蝠，今名夜明砂。  \n\n 【产地】山洞之中，倒悬于洞顶之上。其屎供药用。 \n\n【性味】味辛性寒。 \n\n【主治】为散血明目要药，治障翳，青盲，夜盲，头面痈肿，疳积，瘰疬。 \n\n【灵胎】养血明日。 \n\n【苏敬】烧灰酒服可下死胎。 \n\n【日华】炒服治瘰疬。 \n\n【宗奭】治疳有效。 \n\n【时珍】治目盲障翳。 \n\n【用量】一般一钱至二钱。 \n\n【禁忌】胃肠寒之人禁忌。 右虫鱼中品十七种，旧十六种，增伏翼于此。  ', NULL, NULL, NULL, '伏翼,蝙蝠,夜明砂 ', NULL, '247、伏翼,蝙蝠,夜明砂  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724940, '1473805C4DFC1D6BAD8D510CD92F0031', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7873, 437, 902000704, '\n【本经原文】味咸，寒，有毒。治心腹寒热洒洒，血积，症瘕，破坚，下血闭，生子大良。  \n\n【产地】处处有之，多生墙壁下土中湿处，形扁小，六足，似鳖而无甲。 \n\n【性味】味咸，性寒，有毒。 \n\n【主治】蟅虫为破症瘕下血积要药，主心腹寒热，留血积聚，治乳脉不通，妇人经闭，产后血积，折伤瘀血。 \n\n【药征】主治干血，故兼治少腹满痛，及妇人经水不利。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】用皂荚菖蒲，无瘀血停留者忌，孕妇慎用。 ', NULL, NULL, NULL, '蟅虫,土鳖,地鳖', NULL, '246、蟅虫,土鳖,地鳖  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724941, 'CDA359351AB7D18E4452BB246E37FC84', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7874, 437, 902000703, '\n【本经原文】味咸，寒，有毒。治血瘀症坚，寒热，破积聚，喉咽痹，内寒无子。生川泽及人家屋间。 ', NULL, NULL, NULL, '蜚蠊,蟑螂', NULL, '245、蜚蠊,蟑螂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724942, '0E0056711A7C36755B37F12C78A978CA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7875, 437, 902000702, '\n【本经原文】味苦，微寒，有毒。主逐瘀血，破下血积，坚痞症瘕，寒热，通利血脉及九窍。生川谷。又名虻虫，寄生于牛身者为真品。名牛虻。 \n\n【产地】产于牛舍之中为上品。 \n\n【性味】味苦微寒，有毒。 \n\n【主治】活血化瘀，专攻妇女子脏之瘀，与少腹中之瘀血。  \n\n【药征】瘀血，少腹鞭满，兼治发狂瘀热喜忘，及妇人经水不利。\n\n【容川】蝱虫为飞而食血；故主行上下之血。可以攻血。 \n\n【用量】一般一钱至三钱 \n\n【禁忌】下利者忌用。', NULL, NULL, NULL, '蜚虻,虻虫, 牛虻', NULL, '244、蜚虻,虻虫, 牛虻', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724943, '5AC0E66AA39738F7FBEF3CA848E9BA7C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7876, 437, 902000701, '\n【本经原文】味苦，平，有毒。治目赤痛。眦伤，泪出，瘀血，血闭，寒热，酸痟，无子。生川泽。一名魂常。  ', NULL, NULL, NULL, '木虻', NULL, '243、木虻  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724944, '95D8608F1CD03EA6F7B840231238FD20', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7877, 437, 902000700, '\n【本经原文】味咸，寒，有小毒。治五癃，邪结气，破石淋，下血，利小便水道。生川谷及山石间。一名蜥蜴。  \n\n【产地】今之蜥蜴。处处有之 \n\n【性味】味咸性寒，有小毒。 \n\n【主治】有利尿通淋下血之效，妊妇不得服用。 \n\n【别录】主治五癃结气，利小便水道，破石淋，下血。\n\n【用量】一般一条至两条，烧灰研粉酒服。 \n\n【禁忌】有寒利者禁忌。  ', NULL, NULL, NULL, '石龙子,  蜥蜴', NULL, '242、石龙子,  蜥蜴', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724945, '086AA4DF6105D801C29CB1F95EE89866', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7878, 437, 902000699, '\n【本经原文】味咸，寒，无毒。治贼风喎僻,轶筋及脱肛，惊痫，挛缩。生池泽及阴地、沙石、垣下。一名陵蠡。', NULL, NULL, NULL, '蛞蝓,蜗牛', NULL, '241、蛞蝓,蜗牛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724946, 'A3A2DC0A65E6F25E6B61A553673B12CE', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7879, 437, 902000698, '\n【本经原文】味苦，平，有小毒。治心腹邪气，阴痿，益精，强志，生子，好色，补中，轻身。生川谷樗树上。', NULL, NULL, NULL, '樗鸡', NULL, '240、樗鸡  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724947, '869AC53B2A6E4D0E366EFEE8BC149DB8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7880, 437, 902000697, '\n【本经原文】味辛，微温，有毒。治心腹症瘕，伏坚积聚，寒热，女子崩中下血五色，小腹阴中相引痛，疮疥死肌。生南海池泽。  ', NULL, NULL, NULL, '鮀鱼甲', NULL, '239、鮀鱼甲  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724948, '0DA57EA6F0BED46846466F217261A8B3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7881, 437, 902000696, '\n【本经原文】味咸，平，无毒。治小儿惊，夜啼，去三虫，灭黑，令人面色好，男子阴易病。生平泽。  \n\n【产地】处处有之，乃蚕之病风而机殭者，入药。  \n\n【性味】味咸辛，性平，无毒。  \n\n【主治】白僵蚕为祛风化痰要药，主小儿惊痫，头风齿痛，喉痹咽肿，中风失音，治丹毒搔 痒，瘰疬结核，去皮肤中如虫行。外用灭诸疮瘢痕。  \n\n【别录】女子崩中赤白，产后腹痛，灭诸疮瘢痕，为末封疔肿，拔根极效。  \n\n【灵胎】驱风逐痰。 \n\n【用量】普通八分至三钱。 \n\n【禁忌】所治诸病，非由风寒外邪客入者，均忌。', NULL, NULL, NULL, '白僵蚕', NULL, '238、白僵蚕  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724949, '1B8C58F9C19AD3A8B3387178DA61E31F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7882, 437, 902000695, '\n【本经原文】味咸，微温，无毒。治女子漏下赤白经汁，血闭，阴蚀肿痛，寒热，惊气，症瘕，无子，生东海、池泽。  \n\n【产地】产于海滨，形如革囊，骨及肉入药。  \n\n【性味】味咸，性微温，无毒。  \n\n【主治】乌贼骨主通经络，祛寒湿，治寒热症瘕，阴蚀肿痛，赤白漏下，血枯经闭，能补肝伤疗血不足。  \n\n【别录】惊气入腹，腹痛环脐，丈夫阴中肿痛，令人有子，又止疮多脓汁不燥。  \n\n【日华】疗血崩，杀虫。 \n\n【用量】普通一钱至三钱。\n\n【禁忌】血病多热者勿用。', NULL, NULL, NULL, '海螵蛸,乌贼鱼骨', NULL, '237、乌贼鱼骨  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724950, '409C34A404F26EC8FB0EC13CAE050D4C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7883, 437, 902000694, '\n【本经原文】味咸，微温，有毒。治恶血，血瘀，痹气，破折，血在胁下坚满痛，月闭，目中淫肤，青翳，白膜。生平泽及人家积粪草中。一名蟦蛴  ', NULL, NULL, NULL, '蛴螬', NULL, '236、蛴螬  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724951, '090A83AF7C8438131FA9BFCA903AA73F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7884, 437, 902000693, '\n【本经原文】味咸，寒，无毒。治小儿惊痫，夜啼，癫病，寒热。生杨柳上。\n\n【灵胎】清火散风。即今日之蝉。  ', NULL, NULL, NULL, '蝉蜕,蚱蝉', NULL, '235、蚱蝉  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724952, '8087A10494C55655D1467B30181CCA77', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7885, 437, 902000692, '\n【本经原文】味咸，寒，有毒。治胸中邪气，热结痛，喎僻，面肿，败漆。烧之致鼠。生池泽诸水中。  \n\n【产地】处处有之，产陂泽中，八足两螯，有甲壳。  \n\n【性味】味咸，性寒，有小毒。  \n\n【主治】蟹主散血，解结，疏肝气，理经脉，利肢节，续筋骨，治热结痛，胸中邪气，面肿，妇人经血不通。  \n\n【别录】解结散血，愈漆创，养筋益气。  \n\n【用量】普通为服食之品，入药无定量。  \n\n【禁忌】能动风，有风疾人不可食，不可合柿及荆介食，发霍乱动风，孕妇忌之，中蟹毒，紫苏煎浓汁，冷服。  \n', NULL, NULL, NULL, '蟹', NULL, '234、蟹  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724953, '989BB436D3B50C41817915DDA135C133', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7886, 437, 902000691, '\n【本经原文】味咸，平，无毒。治心腹症瘕坚积，寒热，去痞，息肉，阴蚀，痔，恶肉。生池泽。  \n\n【产地】处处有之，生水中，岳州沅江所出甲有九肋者为胜。 \n\n【性味】味咸，性平，无毒。 \n\n【主治】鳖甲为益阴除热散结要药，主心腹症瘕坚积寒热，治老疟疟母，骨节间劳热，消肿下瘀，能堕胎。 \n\n【别录】疗温疟，血瘕腰痛，小儿胁下坚。 \n\n【甄权】宿食症块痃癖，冷瘕劳瘦，除骨热结实壅，下气，妇人瘘下五色，下瘀血。 \n\n【容川】鳖甲攻破肝气，去症瘕。  \n\n【用量】普通二钱至四钱。 \n\n【禁忌】妊娠及阴虚胃弱，阴虚泄泻，产后泄泻，产后饮食不消，不思食及呕恶等证均忌。  ', NULL, NULL, NULL, '鳖甲', NULL, '233、鳖甲  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724954, '407B7702C15F61FE6F177C1FA5DEC1B6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7887, 437, 902000690, '\n【本经原文】味苦，平，有毒。治惊痫，瘛瘲，寒热，邪气，癫疾，鬼精，蛊毒，肠痔。生山谷。一名蜂肠。  \n\n【产地】处处有之。 \n\n【性味】味甘咸，性平，有毒，火烧灰用。 \n\n【主治】露蜂房为解毒，杀虫药，治附骨瘫疽，瘰疬，恶疮，惊痫，癫疾，杀肠中寄生虫，兴肠道。 【别录】合乱发、蛇皮烧灰，以酒日服二方寸匕，治恶疽附骨痈，根在脏腑间，歴节肿出，疔肿恶脉，诸毒皆瘥。 \n\n【苏讼】煎水治热病后毒气冲目，炙研和猪脂涂瘰疬成瘘。 \n\n【大明】煎水漱牙齿，止风虫疼痛，又洗乳癕，蜂疔，恶疮。 \n\n【苏敬】疗上气，赤白痢，遗尿失禁，烧灰酒服主阴痿，水煮服汁下乳石毒。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】禁生用。  ', NULL, NULL, NULL, '露蜂房', NULL, '232、露蜂房  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724955, '0D60141EDD1001710BBE3BEFFFF5345A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7888, 437, 902000689, '\n【本经原文】味苦，平，无毒。治五痔，阴蚀，下血赤白，五色血汁不止，阴肿痛引腰背。酒者杀之。生川谷、田野。  \n\n【产地】山地多有之。 \n\n【性味】味苦，性平。 \n\n【主治】猬皮治五痔，泻血，阴肿痛及反胃，炙为末或烧灰服。\n\n【别录】疗腹痛疝积，烧灰酒服。 \n\n【毅明】治反胃吐食。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】禁生用。  ', NULL, NULL, NULL, '猬皮', NULL, '231、猬皮  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724956, 'AC3B9DC7F46E302EBA2423F6C5FD0A6D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7889, 437, 902000688, '\n【本经原文】味辛，寒，无毒。治面痈肿，皮肤洒洒时痛，腹中血气，破寒热积聚，除惊悸。生山谷。一名鼠法，一名石肝。', NULL, NULL, NULL, '天鼠屎 ', NULL, '230、天鼠屎  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724957, '7BDFAF1153A36F52FEA90971BB5AAC43', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7890, 437, 902000687, '\n【本经原文】味辛，平，有毒。治蛊毒，鬼疰，逐不祥邪气，破五癃，利小便。生高山平谷。', NULL, NULL, NULL, '燕屎', NULL, '229、燕屎  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724958, '231B5ED8B39C97B4EDDE787DD9016F6A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7891, 437, 902000686, '\n【本经原文】味苦，寒，无毒。治百毒，蛊疰，邪鬼，瘴气，杀钩吻，鸩羽，蛇毒，除邪，不迷惑，魇寐，外服轻身。生山谷。 \n\n【产地】产我国云南贵州四川等地，生山谷中，角入药。 \n\n【性味】味苦酸咸，性寒，无毒。 \n\n【主治】犀角为散邪清热凉血解毒要药，主伤寒时疫，发黄发斑，风毒中恶，狂言妄语，治胃中大热，痘疮黑陷，吐血下血，蓄血谵语，能消痈化脓，解毒定惊。 \n\n【别录】伤寒瘟疫头痛寒热诸毒气，令人骏健。 \n\n【药性】辟中恶毒气，镇心神，解大热，散风毒，治发背痈疽疮肿，化脓作水，疗时疾热如火，烦毒入心，狂言妄语。 \n\n【灵胎】养心开窍，解毒除邪。 \n\n【用量】普通三分至一钱。 \n\n【禁忌】恶乌头，忌盐，能消胎气，孕妇忌服，痘疮气虚无大热，伤寒阴症发躁，脉沉细，足冷，渴而饮不多，且复吐出者均忌。  ', NULL, NULL, NULL, '犀角', NULL, '228、犀角  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724959, '03DBEFF347E9C97BED3A34349B215C46', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7892, 437, 902000685, '\n【本经原文】味咸，寒，无毒。主明目，益气，起阴，去恶血，注下，辟蛊毒，恶鬼，不祥，安心气，常不魇寐。外服强筋骨，轻身。生川谷。 \n\n【产地】产非洲，我国蒙古等地。 \n\n【性味】味咸，性寒。 \n\n【主治】羚羊角为清热，明目，强筋骨，起阴气药，治伤寒，热病寒热，中风附骨痛，产后恶血动心，食噎及惊痫，能抑低血压，防止脑溢血。 \n\n【别录】疗伤寒时气寒热，热在肌肤，湿风注毒伏在骨间，食噎不通，久服强筋骨，轻身，起阴益气，利丈夫。 \n\n【孟铣】治中风筋挛，附骨疼痛，作末蜜服治卒热闷，及热毒，利血，疝气，磨水涂肿毒。\n\n【藏器】治惊悸烦闷，心胸恶气，瘰疬恶疮，溪毒。 \n\n【容川】羚羊挂树干而眠，身悬而能眠，因其筋最直，故能治筋缩抽扯之症，角尤精气之所在，故性微寒，功专舒筋，本天水之阴，以清热也。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】有寒利者禁忌。  ', NULL, NULL, NULL, '羚羊角', NULL, '227、羚羊角  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724960, 'C01B76A705DF8CDD8335C1A8F7371B94', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7893, 437, 902000684, '\n【本经原文】味咸，平，无毒。治伤中，阴痿不起，令强热大，生子，除女子带下十二疾。胆，平。主明目。一名狗精。  ', NULL, NULL, NULL, '狗阴茎,牡狗阴茎,狗精', NULL, '226、牡狗阴茎  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724961, '1A4B71D062E2B38CD6F2AA1BE3215B17', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7894, 437, 902000683, '【本经原文】味咸，温，无毒，治青盲，明目，杀疥虫，止寒泄，辟恶鬼，虎，狼，止惊悸。久服安心，益气，轻身。生川谷。', NULL, NULL, NULL, '羖羊角', NULL, '225、羖羊角', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724962, '98A3AB1106492D59BCF53078F9653813', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:24', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7895, 437, 902000682, '\n【本经原文】牛黄味苦，平，有小毒。治惊痫，寒热，热盛，狂，痉，除邪，逐鬼。生平泽。\n\n           牛角鳃，温，无毒。下闭血，瘀血疼痛，女人带下血。 \n\n          髓，补中，填骨髓，久服增年。\n\n          胆，治惊，寒热，可丸药。 \n\n【产地】牛黄生于病牛胆中，状如鸡子黄，多出陕西甘肃等地。 \n\n【性味】味苦（或作甘），性平（或作凉），有小毒（或作无毒）。 \n\n【主治】牛黄为泻热定惊，利痰清心要药，主惊痫，寒热中恶，口噤，小儿惊邪，痘疮发狂，治痰迷，径急，斑痧，疮毒，益肝胆，定魂魄。 \n\n【别录】疗小儿百病，诸痫热，口不开，大人狂癫，又堕胎，久服令人不忘。 \n\n【甄权】安魂定魄，辟邪魅，卒中恶，小儿夜啼。 \n\n【日华】主中风失音，口噤，惊悸，天行时疾，健忘虚乏。 \n\n【思邈】益肝胆，定惊神，除热止惊痢，辟恶气，除百病。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】恶龙骨龙胆，地黄常山蜚蠊，畏牛膝干漆，风热未深入者忌用。', NULL, NULL, NULL, '牛角鳃', NULL, '224、牛角鳃  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724963, '5361A554E5C8442A2E3D2AD24F46583E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:25', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7896, 437, 902000681, '\n【本经原文】味甘，温，无毒。治漏下，恶血，寒热，惊痫，益气，强志，生齿，不老。角，温，无毒。治恶疮，痈肿，逐邪恶气，留血在阴中。 \n\n【产地】鹿产山林中，处处有之，我国西北及东三省为多，其茸及角入药。 \n\n【性味】味甘咸，性温，无毒。 \n\n【主治】鹿茸为大补真阳要药，主养血益阳，强筋健骨，生精充髓，治男子虚劳，老人精衰，腰膝无力，滑精，眩晕，妇人崩瘘带下。 \n\n【别录】疗虚劳洒洒如疟，羸瘦，四肢酸痛，腰脊痛，小便数利，泄经溺血，破瘀血在腹，散石淋，痈肿，骨中热，举疽痒，安胎下气，杀鬼精物，久服耐老，不可近丈夫阴令萎。 \n\n【日华】补男子腰肾虚冷，脚膝无力，夜梦鬼交，精溢自出，女人崩中瘘血，赤白带下，炙末空心酒服方寸匕，壮筋骨。  \n\n【容川】其宿以头顾尾，能通督脉，督者肾脉，坎中一阳之主脉也，鹿生北方，得坎中一阳之气也，故其督脉极旺，而脊与脑髓极足，因而上发而生角，每年一换，初生为鹿茸，茸之精气极足，为补髓强精壮阳益血之圣药。但其性上行，凡是血逆火逆者不宜用。惟血虚火弱，阳不举，气不上者，乃为合宜。 \n\n【灵胎】补阳益血。 \n\n【用量】普通七分至钱半。  \n\n治，男子阴茎近入易于痿弱。 鹿胎—浑然元气所在，归下焦而不上行，为种子益肾补胞宫之要药。  ', NULL, NULL, NULL, '鹿茸', NULL, '223、鹿茸  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724964, '1B68915942BD7D9A63A0308D8C07F506', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:25', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7897, 437, 902000680, '\n【本经原文】味咸，平，无毒，治伤中，脉绝，阴不起，强志，益气，长肌肉，肥健，生子。眼，平。治惊痫，腹满，疟疾。悬蹄，平。治惊邪，瘛瘲，乳难，辟恶气，鬼毒，蛊疰，不祥。生平泽。 ', NULL, NULL, NULL, '白马茎', NULL, '222、白马茎  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246194724965, 'DF09E613A6AD3757BB5957A7A8D55F33', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:54:25', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7898, 438, 902000801, '\n【本经原文】味辛，温。治疽，疡，疥瘙，热气，恶疮，癞疾，死肌，堕眉，杀痔虫，去黑 子、息肉。生川谷。一名恶灰。  \n\n【产地】近山处皆有之，其石青白色，作窑烧之，则成石灰。  \n\n【性味】味辛，性温，有毒 \n\n【主治】石灰为止血要药，功能蚀恶肉，止吐血，疗金疮，又能解酸类中毒。  \n\n【别录】疗髓谷疽。 \n\n【甄权】治病疥，蚀恶肉，止金疮血甚长。 \n\n【大明】生肌长肉，吐血，白癜疬疡，瘢疵，痔瘘，瘿赘疣子，妇人粉刺，产后阴不能合，解酒酸，治酒毒，暖水臓，治气。 \n\n【用量】普通三分至一钱。 \n\n【禁忌】性燥，且能蚀肉，不可多服。  ', NULL, NULL, NULL, '石灰', NULL, '255、石灰  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634246871048262, NULL, NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:57:10', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7899, 438, 902000844, '\n【本经原文】一名野丈人，一名胡王使者．味苦，温，有毒。治温疟，狂易，寒热，症瘕积聚，瘿气，逐血，止痛，治金疮。生山谷及田野。  \n\n【产地】生嵩山山谷。处处有之，生山谷及田野，近根处有白茸，故名。  \n\n【性味】味辛苦，性温，无毒（或作小毒）。 \n\n【主治】白头翁为治痢要药，功能泄热凉血，治毒痢赤痢，下血腹痛，及妇女经闭，  \n\n【别录】治鼻衄。 \n\n【甄权】赤痢腹痛，齿痛，百节骨痛，项下瘿瘤。  \n\n【弘景】止毒痢 \n\n【容川】白头翁一茎直上如柴胡，所以能治下痢后重者，升散郁结也。其无风动摇，有风不动，色白有毛，凡毛皆得风气，采于秋月，得金木交合之气，故能熄风，从肺金以达风木之气，使木不侮土，故功在升举后重，而止痢疾，又其味苦，是治风热之妙药，仲景治产后中风，及痢疾后重者，走取其熄风火，达肝阳也。 【药征】主治热痢下重也。  \n【用量】普通钱半至三钱。 \n\n【禁忌】滞下胃虚不思食，及完谷不化，泄泻由虚寒寒热而不由湿毒者，均忌，得酒良。  ', NULL, NULL, NULL, '白头翁', NULL, '298、白头翁 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425029, '951C05820E8E3A493D31ECA11C22B59C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7900, 438, 902000843, '\n【本经原文】味辛，平，有大毒。治咳逆上气，破积聚，饮食寒热，水气，恶疮，鼠瘰，疽蚀，鬼精，蛊毒，杀飞鸟走兽。生山谷。一名续毒。  \n\n【产地】产我国山西陕西等地，叶似商陆及大黄，茎叶上有毛，其根皮黄肉白。  \n\n【性味】味辛，性平，有大毒。 \n\n【主治】狼毒主破积聚，治九种心痛。 \n\n【别录】除胸下积癖。 \n\n【大明】治痰饮症瘕，亦杀鼠。 \n\n【括要】经年癣疮生痂，搔之有黄水出，每阴雨痒甚，为末敷之效。 \n\n【用量】普通三分至钱许。 \n\n【禁忌】狼毒有毒，用之宜慎，畏密陀僧。  ', NULL, NULL, NULL, '狼毒,续毒', NULL, '297、狼毒  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425030, 'DB39260B22F367FF1EE5536247787CBB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7901, 438, 902000842, '\n【本经原文】味苦，平，无毒．治浸淫，疥瘙，疽，痔，杀三虫。生山谷。一名萹竹。  \n\n【产地】处处有之，多繁殖路旁，叶细绿。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】萹蓄草为杀虫疥，利小便要药，治湿疮浸淫，热淋涩痛，热疾黄疸。 \n\n【别录】疗女子阴蚀。 \n\n【甄权】煮汁饮小儿，疗蚘虫有验。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】无湿热者勿用。', NULL, NULL, NULL, '萹蓄', NULL, '296、萹蓄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425031, '271FA38B5B14265EABA51291C90D2E66', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7902, 438, 902000841, '  \n【本经原文】味苦、寒、无毒。治头秃，疥瘙，除热，女子阴蚀。生川泽。一名东方宿，一名连虫陆，一名鬼目。 \n\n【产地】处处有之，多生山野下湿之地，叶长似菜，故亦曰羊蹄菜，根黄白色，粗大似葫芦巴。  \n\n【性味】味苦、性寒、无毒。  \n\n【主治】羊蹄主杀虫，治疥癣，肿疡，清血热，疗肠风，便秘。\n\n【别录】浸淫疽痔，杀虫。 \n\n【大明】治癣，杀一切虫，醋磨贴肿毒。 \n\n【用量】普通二至三钱，外用无定量。 \n\n【禁忌】多食下气，令人作泻，故有人取以代大黄者。  ', NULL, NULL, NULL, '羊蹄', NULL, '295、羊蹄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425032, '14632F490A40C46B849BED9570ED9ED8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7903, 438, 902000840, '\n【本经原文】味辛，平，有毒。治水胀，疝瘕，痹，熨除痈肿，杀鬼精物。生川谷。一名䓪根。  \n\n【产地】处处有之，多生山野阴地，其根有赤白两种，赤者有毒，白者入药。 \n\n【性味】味苦（或作辛），性寒，有毒。 \n\n【主治】商陆为利水消肿要药，主治水肿，瘕疝，脚气胀满，能疏五臓，散水气，通利大小 肠，并可傅痈疮。 \n\n【别录】疗胸邪气，水肿痿痹，腹满洪，直疏五臓，散水气。 \n\n【甄权】泻十种水病，喉痹不通，薄切醋炒涂喉外良。 \n\n【大明】通大小肠，泻蛊毒，堕胎，熁肿毒，傅恶物。 \n\n【容川】商陆用根，取其内透膜膈，以导水下行。一般用苗则升，用根则降。 \n\n【用量】普通五分至一钱左右 \n\n【禁忌】虚人禁用，赤者有毒伤人，只堪贴脐，商陆入麝香少许，用以利溲水肿。', NULL, NULL, NULL, '商陆', NULL, '294、商陆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425033, '82E46C7DAE5F04BF03C1B37CDE2127A1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7904, 438, 902000839, '\n【本经原文】味辛，温，有大毒。治贼风在皮肤中淫淫痛，温疟，恶毒，诸痹。生川谷。  \n\n【产地】产我国广东广西四川一带，花冠为漏斗状，色黄似杜鹃花而大。 \n\n【性味】味辛，性温，有大毒。 \n\n【主治】羊踯躅为诸风湿痹痛药，主痛风走注，风痰湿痹，治蛊毒。 \n\n【别录】邪气鬼疰，蛊毒。 \n\n【用量】普通分许 \n\n【禁忌】羊食其草，踯躅而死，有毒之药，宜慎用之，近眼令人昏翳，其根误服，亦能杀人，中毒者，绿豆汁解之。  \n', NULL, NULL, NULL, '羊踯躅', NULL, '293、羊踯躅  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425034, 'A1CADAA5F0D90474842CC2B43D0C3E14', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7905, 438, 902000838, '\n【本经原文】一名狼牙。味苦，寒，有毒。治邪气，热气，疥瘙，恶疡，疮，痔，去白虫。生川谷。  \n\n【产地】山中处处有之。  \n\n【性味】味苦，性寒，有毒。 \n\n【主治】为解毒杀虫要药，治风搔，恶疮，驱寸白条虫。\n\n【甄权】治浮风搔痒，煎汁洗恶疮。 \n\n【大明】杀腹臓一切虫，止赤白痢，煎服。 \n\n【禁忌】内服须慎重  ', NULL, NULL, NULL, '狼牙,牙子', NULL, '292、牙子  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425035, 'BBFA7B85A0F361B189A71A4A37874D2A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7906, 438, 902000837, '\n【本经原文】味苦，寒，有毒。治伤寒，温疟，下十二水，破积聚大坚，症瘕，荡涤肠胃中留癖饮食，寒热邪气，利水道。生川谷。又名黄芫花。 \n\n【产地】为山地小灌木。花供药用。 \n\n【性味】味苦，性寒，有毒。 \n\n【主治】为排水要药，治腹水，水肿，肋膜积水及湿痰咳嗽。 \n\n【别录】疗痰饮咳嗽 \n\n【甄权】治咳逆上气，喉中肿满，蛊毒，痃癖气块。 \n\n【用量】一般一钱左右。 \n\n【禁忌】同芫花。', NULL, NULL, NULL, '荛花,黄芫花', NULL, '291、荛花  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425036, '31FFBAF0607CA8A973CBE22032639653', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7907, 438, 902000836, '\n【本经原文】一名贯节，一名贯渠，一名百头，一名虎卷，一名扁苻。味苦，微寒，有毒。治腹中邪热气，诸毒，杀三虫。生山谷。 \n\n【产地】处处有之，多自生山中溪畔，或森林阴处，根黑褐色。 \n\n【性味】味苦，性微寒，有小毒。 \n\n【主治】贯众为解毒要药，功能治腹中邪热之毒，软坚破积，及妇科诸血症。 \n\n【别录】去寸白，破症瘕，除头风，止金疮。 \n\n【苏颂】为末水服一钱，止鼻血有效。 \n\n【灵胎】解毒杀虫。 \n\n【用量】普通一钱至二钱。 \n\n【禁忌】无。 ', NULL, NULL, NULL, '贯众', NULL, '290、贯众  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425037, '3F1586D5A388AB57C17B7010106702AE', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7908, 438, 902000835, '\n【本经原文】味苦，温，有毒。治五臓邪气，心腹寒热，羸瘦，如疟状，发作有时，诸关节风湿痹痛，生川谷。  ', NULL, NULL, NULL, '茵芋', NULL, '289、茵芋  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425038, '132191634121C247C6052E4F4224824B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7909, 438, 902000834, '\n【本经原文】味苦，微寒，无毒。治皮肤热，大腹水气，四肢面目浮肿，丈夫阴气不足，生川泽。  \n\n【产地】产江湖原泽，处处有之，绿叶绿花，茎有白汁粘人，故曰泽漆。  \n\n【性味】味苦，性微寒，无毒（或作小毒）。 \n\n【主治】泽漆主治水肿脚肿，消痰退热，敷之消疣。  \n\n【别录】利大小肠，明目。  \n\n【大明】止疟疾，消痰，退热。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】赤小豆为使，恶薯蓣。  ', NULL, NULL, NULL, '泽漆', NULL, '288、泽漆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425039, 'F6781515D8D52D2B2B8C6DF2713AE75C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7910, 438, 902000833, '\n【本经原文】一名邛巨。味苦，寒，有小毒。治蛊毒，十二水，腹满急痛，积聚，中风，皮肤疼痛，吐逆。  \n\n【产地】生常山。山野或平泽自生之宿根有毒草，产江浙等地，春生红芽，茎高尺许，伤其茎，有白汁流出，根外部赤黄，内白色。 \n\n【性味】味苦性寒，有小毒。 \n\n【主治】大戟为泻脏腑水湿要药，主消水肿，袪痰涎，利大小便，泻痘毒陷。 \n\n【别录】颈腋痈肿头痛，发汗，利大小便。 \n\n【甄权】下恶血癖块，腹内雷鸣，通月水，堕胎。 \n\n【大明】泻毒药，泻天行，黄病温疟，破症结。  \n【用量】普通八分至二钱。 \n\n【禁忌】大戟力峻，取效甚捷而用之亦宜慎，反甘草，用菖蒲解之，得枣良，不损脾。  ', NULL, NULL, NULL, '大戟', NULL, '287、大戟  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425040, '166068A4C7BA8BF312BA0F119CCFD701', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7911, 438, 902000832, '\n【本经原文】一名甘根，一名连及草。味苦，平，无毒。治痈肿，恶疮，败疽，伤阴，死肌，胃中邪气，贼风，鬼击，痱缓不收，生川谷。  \n\n 【产地】山野多年生草本，庭园亦可种类，根黄白色，中含粘液颇多。 \n\n【性味】味苦辛，性寒，无毒。 \n\n【主治】白及为止血疗疮要药，功能逐瘀生新，补肺损，止吐血。 \n\n【甄权】除白癣疥虫，结热不消，阴下痿，面上皯疱。 \n\n【大明】止惊邪，血，痫疾，风痹，赤眼，症结，温热，疟疾，发背，瘰疬，肠风痔瘘，扑 损刀箭伤，汤火疮，生肌止痛。 \n\n【东垣】止肺血。 \n\n【灵胎】敛疮涩血。 \n\n【用量】普通一钱至三钱。', NULL, NULL, NULL, '白及', NULL, '286、白及  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425041, '8B812191574AD125DFE2B5793A9744BF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7912, 438, 902000831, '\n【本经原文】一名雚卢。味咸，平，有小毒。治心痛，温中，去长虫，白癣，蛲虫，蛇螫毒，症瘕，诸虫。生东海池泽及渤海。', NULL, NULL, NULL, '雚菌', NULL, '285、雚菌  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425042, '677ED746651C192624747FA2F37CBA2E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7913, 438, 902000830, '\n【本经原文】味苦，微寒，无毒。治邪气，皮肤中热，风瘙身痒，杀三虫，子，名草决明，治唇口青，生平谷道旁。一名草蒿，一名萎蒿。  \n\n【产地】产我国南方暖地田野，为草本植物，茎直立，叶作披针形，花作淡红色，茎叶皆入药，名草决明，子名青葙子，别有一种名决明子，与此名似而物殊。  \n\n【性味】味苦，性微寒，无毒。 \n\n【主治】青葙子为眼科要药，主镇肝明目，治赤障青盲翳膜。 \n\n【甄权】治肝脏热毒充眼，赤障青盲翳肿，恶疮疥疮。 \n\n【大明】治五脏邪气，益脑髓，镇肝，明耳目，坚筋骨，去风寒湿痹。\n\n【用量】普通一钱至二、三钱。 \n\n【禁忌】虚寒之人，火衰目病者不宜。  ', NULL, NULL, NULL, '青葙子', NULL, '284、青葙子,草蒿,萎蒿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425043, 'CBE9618A56855AC3C593E99E39F7D109', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7914, 438, 902000829, '\n【本经原文】味苦，平，无毒。治痈肿，疽，疮，散结气，止痛，除热，目中赤，小儿惊痫，温疟，女子阴中肿痛。生山谷。一名莬核，一名白草。 \n\n【产地】产我国湖南湖北，及北地各省亦多有之，根入药。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】白敛主散结聚，治痈疽疮毒，痔瘘血痢，生肌止痛，外用敷一切疮，并治面上粉刺赤鼻。 \n\n【别录】杀火毒。 \n\n【大明】治发背瘰疬，面上疱疮，肠风痔瘘，血痢，刀箭疮扑损，生肌止痛。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】反乌头。  ', NULL, NULL, NULL, '白敛', NULL, '283、白敛  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425044, '346F4EE54BE504451D03D6A505F65962', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7915, 438, 902000828, '\n【本经原文】一名主田。味苦，寒，有毒。治大腹疝瘕，腹满，面目浮肿，留饮，宿食，破症坚积聚，利水谷道。生川谷。 \n\n【产地】产陕西河南一带，自生山野间，为类似大戟之毒草，茎叶含乳液，切断则流白汁，其根为连珠状，多节，皮有赤色斑点，内白色。 \n\n【性味】味苦甘，性寒，有毒 \n\n【主治】甘遂为行水要药，主治身体浮肿，腹胀，囊肿，攻决痰水，利大小便。 \n\n【别录】下五水，散膀胱留热，皮中痞热气肿满。 \n\n【甄权】能泻十二种水疾，去痰水。 \n\n【药征】主利水也，旁治掣痛，咳烦，短气，小便难，心下满。 \n\n【用量】普通八分至二钱。 \n\n【禁忌】元气虚人，除伤寒水结胸不得不用外，其余水肿蛊胀，谨慎用之，恶远志，反甘草。 ', NULL, NULL, NULL, '甘遂', NULL, '282、甘遂  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425045, '69E787CC5E74F54CA4935F429E213029', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7916, 438, 902000827, '\n【本经原文】味辛，平，有毒。治疟，及咳逆，寒热，腹中症坚，痞结，积聚，邪气，蛊毒。鬼疰。生川谷。又名常山。\n\n【产地】产我国陕西河南四川等地，江浙亦有之，生于山野阴湿之处，为落叶小灌木，根名\n\n为常山，苗即为蜀漆。\n\n【性味】味苦辛，性寒，有毒。\n\n【主治】蜀漆为驱痰截疟要药，主袪老痰积饮，治新久诸疟，能引痰上行使吐，下行使下，逐水消肿，杀虫，疗蛊。（春夏用蜀漆，秋冬用常山）\n\n【别录】疗鬼蛊往来，水胀，洒洒恶寒，鼠瘘\n\n【甄权】治诸疟，吐痰涎，治项下瘤瘘。\n\n【容川】为治疟要药，痰疟是积湿而成的，常山苗能透达以吐之。\n\n【药征】主治胸腹及脐下动剧者，故兼治惊狂火逆疟疾。\n\n【用量】普通八分至三钱。\n\n【禁忌】凡真气虚者忌，忌葱菜及菘茗，得甘草吐疟痰，酒炒用良。', NULL, NULL, NULL, '蜀漆', NULL, '281、蜀漆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425046, '43FEC594A8B7AAAE388CFA6B27448943', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7917, 438, 902000826, '\n【本经原文】一名玄草。味苦，寒，有毒。治伤寒寒热，发温疟，鬼毒，胸中痰结，吐逆。生川谷。', NULL, NULL, NULL, '恒山', NULL, '280、恒山  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425047, '2AE0E3247B913E365B8EC44E4F9A33C3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7918, 438, 902000825, '\n【本经原文】一名蛇衔。味苦，微寒，无毒。治惊痫，寒热邪气，除热，金疮，疽，痔，鼠瘰，恶疮，头疡。生山谷。 \n\n【产地】产山野之地，处处有之。 \n\n【性味】味苦，微寒，无毒。 \n\n【主治】蛇含草主治痈疮，蛇咬，清热解毒。 \n\n【别录】疗心腹邪气，腹痛湿痹，养胎，利小儿。 \n\n【甄权】治小儿寒热丹疹。 \n\n【用量】普通一至二钱，外用无定量。 \n\n【禁忌】忌火。', NULL, NULL, NULL, '蛇含', NULL, '279、蛇含  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425048, '407BCD2252A5EE91B56F8CC916F48214', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7919, 438, 902000824, '\n【本经原文】一名乌扇，一名乌蒲。味苦，平，有毒。治咳逆上气，喉痹，咽痛，不得消息，散结气，腹中邪逆，食饮大热。生川谷田野。  \n\n【产地】处处有之，生于各地山中，为多年生草本，园圃亦可栽种，叶似菖蒲，其花可供玩赏。  \n\n【性味】味苦，性平，有毒。  \n\n【主治】射干清火解毒散血消痰要药，主咽喉肿痛，咳逆上气，降实火，利大肠，治积痰瘀 血，热气结毒。  \n\n【别录】疗老血在心脾间，咳唾言语气臭，散胸中热气。  \n\n【甄权】治疰气消瘀血，通女人月闭。 \n\n【大明】消痰破症结，胸膈满腹胀，气喘，痃癖，开胃下食，镇肝明目。  \n\n【元素】去胃中痈疮。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】性不益阴，凡脾胃弱，脏寒，气血虚，病无实热，均忌。\n\n【容川】射干微苦，利喉中之痰。  ', NULL, NULL, NULL, '射干', NULL, '278、射干  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425049, '56B386D72C4D8E50D74AFB8B0371B93D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7920, 438, 902000823, '\n【本经原文】一名野葛。味辛，温，有大毒。治金疮，乳痉，中恶风，咳逆上气，水肿，杀鬼疰，蛊毒。生山谷。  ', NULL, NULL, NULL, '钩吻', NULL, '277、钩吻  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425050, 'F30CB6A8DBBAAF1DB2E451C5073CAE03', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7921, 438, 902000822, '\n【本经原文】一名葱苒。味辛，寒，有毒。治蛊毒，咳逆，泄利，肠澼，头疡，疥瘙，恶疮，杀诸虫毒，去死肌。生山谷。 \n\n【产地】产我国陕西一带，各省亦多有之，生山谷中，根似葱有须而多毛。 \n\n【性味】味辛苦，性寒，有毒。 \n\n【主治】藜芦为催吐要药，主风痰上塞，用吐一切恶物，通顶发嚏（嗅之），治风痫，外用治疮疥杀虫。  \n\n【别录】疗哕逆喉痹不通，鼻中息肉，马刀乱疮，不入汤用。\n\n【甄权】主上气，去积年脓血泄利。 \n\n【灵胎】除湿泄热解毒杀虫。  \n\n【用量】普通一至二分。  \n\n【禁忌】多服引吐，损人元气，畏葱白，服之吐即止，有辛烈气味，入鼻发嚏不止，饮冷水即止，能杀蝇，亦称蝇毒，黄莲为使，反细辛芍药，人参沙参，苦参，丹参，恶大黄。  ', NULL, NULL, NULL, '藜芦', NULL, '276、藜芦  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425051, 'BDEC50D20F80C1A8BDCED68AE57FE4A1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7922, 438, 902000821, '\n【本经原文】一名筋根花，一名金沸。味甘，温，无毒。主益气，去面黑，色媚好。其根，味辛，治腹中寒热邪气，利小便。久服不饥，轻身。生平泽。  \n\n【产地】产原野湿地，各处有之，园圃亦可栽植，亦名金钱花。  \n\n【主治】旋覆花为下气祛痰健胃行水要药，主治肺胃气虚，痰水胶结，上气喘急，根能续筋断。  \n\n【别录】消胸上痰结，唾如胶漆，心胸痰水，膀胱留饮，风气湿痹，皮间死肉，利大肠，通血脉，益色泽。  \n\n【甄权】主水肿，逐大腹，开胃，止呕逆不下食。  \n\n【灵胎】降气消痰。 \n\n【用量】普通一钱至二、三钱。 \n\n【禁忌】病人涉虚者，忌多服，冷利大肠，虚寒人禁用。', NULL, NULL, NULL, '旋覆花,旋复花', NULL, '275、旋复花  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425052, '954DBFB7F8CFE5200C97EDD15B752529', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7923, 438, 902000820, '\n【本经原文】一名青蒿。一名方溃。味苦，寒，无毒。治疥瘙痂痒，恶疮，杀虱，留热在骨节间，明目。生川泽。一名青蒿，一名方溃。  \n\n【产地】处处有之，可煮饮，亦可作食，自生于河岸或海滨，茎叶气味俱芬，入药，子功用亦同。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】青蒿为清虚热要药，主治虚痨骨蒸，烦热盗汗，疟痢虚热，血中伏热，明目。  \n\n【大明】补中益气，补劳。长毛发令黑不老，兼去蒜髪，杀风毒，心痛热黄，生捣汁服并贴之。  \n\n【容川】青蒿色青味苦，正治肝胆之相火，其节中必生红虫，乃感风化而生之虫，故青蒿为去风清热之要药，人之痨虫皆因肝气相火，相煽而生，假血以成质，故必骨蒸而生痨虫，青 蒿节以虫杀虫，消瘀去蒸，借虫以攻血，借风气以散郁火也。  \n\n【用量】普通一钱至二钱。 \n\n【禁忌】产后气虚，内寒作泻，及饮食停滞，泄泻者均忌，凡产后脾胃薄弱，忌与归地同用。 ', NULL, NULL, NULL, '青蒿', NULL, '274、草蒿,青蒿', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425053, 'EC3600975C819DACF7BBD93A96E50FE9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7924, 438, 902000819, '\n【本经原文】味苦，寒，有毒。治齿痛、出虫，肉痹拘急。使人健行、见鬼。多食令人狂走。久服轻身、走及奔马。强志，益力，通神。生海滨、川谷。一名横唐。', NULL, NULL, NULL, '莨菪子', NULL, '273、莨菪子  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425054, '7345E0771EBAE0F25BF863BBF2BCFA1B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7925, 438, 902000818, '\n【本经原文】味辛，微温有小毒。治胸胁痛如刀刺，腹满，肠鸣幽幽，惊恐悸气。生山谷。\n\n【产地】生嵩高山谷。自生于山中向阳之地，处处皆有，叶似沙参，根亦相似而较白。 \n\n【性味】味苦辛。性微温：有小毒。 \n\n【主治】桔梗为宣肺祛痰要药，功能治痰壅气逆，胸胁气痛，利咽喉，治肺痈。 \n\n【别录】利五脏肠胃，补血气，除寒热风痹，温中消谷，疗喉咽痛，下蛊毒。 \n\n【甄权】治下痢，破血积气，消聚痰涎，去肺热气促嗽逆，除腹中冷痛，主中恶及小儿惊痫。\n\n【大明】下一切气，止霍乱转筋，心腹胀痛，补五劳，养气除邪辟温，破症瘕肺痈，养血排脓，补内漏及喉痹。 \n\n【元素】利窍，除肺部风热。清利头目咽嗌，胸膈滞气及痛，除鼻塞。 \n\n【药征】主治浊唾肿脓也，旁治咽喉痛。 \n\n【用量】普通八分至二钱。 \n\n【禁忌】凡攻补下焦药中勿入。气逆上升，不得下降，及邪在下焦，均忌。  ', NULL, NULL, NULL, '桔梗', NULL, '272、桔梗  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425055, 'CB6596BD44D8F9CC63C55DE3C4D60C19', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7926, 438, 902000817, '\n【本经原文】味辛，寒，无毒。治症瘕，积聚，结气，饮食寒热，破坚，逐邪，通利水道。生平泽及田野。一名大室，一名大适。 \n\n【产地】生藁城平泽。产我国河南陕西河北一带，有甜苦二种，今俱以甜者入药，且多以荠子或折蓂子混充，苦者绝少。 \n\n【性味】味辛苦，性大寒，无毒。 \n\n【主治】葶苈子为下气行水要药，功能降肺气，逐痰饮，止喘促，下膀胱水，治面目浮肿。\n\n【别录】下膀胱水伏留热气，皮间邪水上出面目浮肿，身暴中风，热沸痒，利小便，久服令人虚。 \n\n【甄权】疗肺壅土气咳嗽，止喘促，除肺中痰饮。 \n\n【容川】葶苈子多油，当能滑利，又有辛味，舆巴豆之辛有油相似，其味苦，与大黄之苦而滑润相似，故葶苈子隐含巴豆舆大黄二者之性，故能大泻肺中之痰饮脓血，性极速降，是猛 药类，故仲景配以大枣补之，入药前须要炒过，不炒则不香，不能散。 \n\n【药征】主治水病也，旁治肺痈结胸也。 \n\n【灵胎】泻肺气，利水道。 \n\n【用量】普通八分至二、三钱。 \n\n【禁忌】肿满由脾虚不能制水，小便不通，由膀胱虚无气以化者均忌，肺气虚者亦忌，宜大枣为辅、恶僵蚕。', NULL, NULL, NULL, '葶苈子', NULL, '271、葶苈  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425056, '3DCEDAF72C6B1FC042B0AA1F6555AED9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7927, 438, 902000816, '\n【本经原文】味苦，寒，无毒。主下瘀血，血闭，寒热。破症瘕积聚，留饮，宿食，荡涤肠胃，推陈致新，通利水谷，调中化食，安和五脏。生山谷。 \n\n【产地】生河西山谷。产陕西甘肃四川等处，为多年生宿根草，根黄色，带有赤色之纹，故亦曰绵纹。 \n\n【性味】味大苦，性大寒，无毒（或作有毒）。 \n\n【主治】大黄为泻实热，荡积滞要药，主血闭热结，功能下瘀破症，荡涤肠胃，推陈致新，调中化食，大便燥结，女子经闭。 \n\n【别录】平胃，下气，除痰实，肠间结热，心腹胀满，女子寒血闭、小腹痛，诸老血留结。\n\n【甄权】通女子经候，利水肿，利大小肠，贴热肿毒，小儿寒热，时疾烦热蚀脓。 \n\n【大明】通宣一切气，调血脉，利关结，泄壅滞水气，温瘴热疟。 \n\n【元素】泻诸热不通，除下焦湿热，消宿食，泻心下痞痛。 \n\n【容川】大黄味苦大寒，形大而气烈，得地火之阴味，色黄，为火之退气所发见，故能退火，专下血分之结，以味厚有烈气，味既降又得气之助，故走脾胃，下行更速更远。寒性皆下引。其纯于苦味，又有雄烈之气，以气行其苦味，则走而不守。与黄连之守而不走，正好相反。大黄是治火之药，禀地气，入后天之血分也。 \n\n【药征】主通利及结毒也，故能治胸满腹满，腹痛及便秘，小便不利，旁治发黄瘀血脓肿。 \n \n【灵胎】攻凝结，消积滞。  \n\n【用量】普通五分至三钱。  \n\n【禁忌】凡气分病，及胃寒血虚，妊娠产后，均忌。  \n\n【炮制】拣去杂质，大小分开，浸泡约一小时，捞出沥干余水，切3 毫米厚，长宽约3 厘米块片，晾干或烘干即得。 熟大黄，取大黄片，用白酒调匀，待吸收酒后，蒸约4 小时，以蒸黑为度，停火闷一夜，冷却后取出，烘干即得，酒炒至黑后，则质轻味淡，能上清头目。', NULL, NULL, NULL, '大黄', NULL, '270、大黄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425057, 'F96B07347A74394FB22E12A76DA95A0B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7928, 438, 902000815, '\n【本经原文】味苦，平，有毒。治蛊毒，邪气，鬼疰，诸毒。破症瘕，积聚，去水，下三虫。生山谷。  ', NULL, NULL, NULL, '鸢尾', NULL, '269、鸢尾  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425058, '086E69D571C84AF7F7487B794124CCD0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7929, 438, 902000814, '\n【本经原文】味苦，温，有大毒。治心痛，寒热，结气，积聚，伏梁，伤筋，瘘，拘缓，利水道。生山谷。又名虎掌，今名天南星。 \n\n【产地】产我国北地，为多年生草本，生于山野阴处，根入药。 \n\n【性味】味苦，性温，有大毒。 \n\n【主治】天南星为祛风湿豁顽痰要药。主风痰壅塞，中风口噤，治口歪眼斜，痈毒疥癣，小 儿惊风。 \n\n【别录】治阴下湿，风眩。 \n\n【甄权】主疝瘕肠痛，伤寒时疾，强阴。 \n\n【大明】蛇虫咬，疥癣恶疮。 \n\n【元素】去上焦痰，眩晕。 \n\n【好古】补肝风虚，治痰功同半夏。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】误服麻唇舌，得防风则不麻，凡使，宜以矾汤或皂角水浸，至不麻乃止，忌铁，用竹刀切，阴虚燥痰忌用。  ', NULL, NULL, NULL, '南星,天南星,虎掌', NULL, '268、虎掌  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425059, '5C0AABE7B337BB9CE8076BE98FABEAF7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7930, 438, 902000813, '\n【本经原文】味辛，平，有毒。治伤寒，寒热，心下坚，下气，喉咽肿痛，头眩，胸胀，咳逆、肠鸣，止汗。生山谷。一名地文，一名水玉。  \n\n【产地】生槐里川谷。产我国四川江浙及北地多有之，为多年生野草，根白色，入药。 \n\n【性味】味辛，性平，有毒。 \n\n【主治】半夏为除湿化痰，止呕止哕，开郁发表要药，主和胃，健脾，消积，化涎，顺气止咳，平逆止吐，治心痛，痞结，水饮，痰气，救五绝。   \n\n【别录】消心腹胸膈痰热结满，咳嗽上气，心下急痛坚痞，时气呕逆，消痈肿，疗痿黄，悦泽面目，堕胎。 \n\n【甄权】制者消痰下肺气，关胃健脾，止呕吐，去胸中痰。生者摩痈肿，除瘤瘿气。  \n\n 【大明】治吐食反胃，霍乱转筋，肠腹冷，痰疟。 \n\n【元素】治寒痰及形寒饮冷伤肺而咳，消胸中痞，膈上痰，除胸寒，和胃气，燥脾湿，治痰 厥头痛，消肿散结。  \n\n【好古】补肝风虚。 \n\n【容川】此生当夏之半，其根成于秋时，得燥金辛烈之气，故主降逆水饮，为阳明之药，此为真性。  \n\n【倪注】一般使用生半夏以止呕吐时，多加生姜以制其毒，重症病患之呕吐，唯此生半夏可治，学者当用之勿惧，今之医多不敢使用生药，因惧其毒性，实则此药又名婆婆药，意即可以让人失音，并不会致命，如果失音时，只须口含生姜片，须臾声自回。  \n\n【药征】主治痰饮呕吐也，旁治心痛逆满，咽中痛，咳悸，腹中雷鸣。 \n\n【灵胎】开肺降逆，消痰燥湿。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】一切血症及阴虚血少，津液不足之病，均忌，孕妇禁用，用姜佐则无害，反乌头，忌饴糖海藻羊血。  ', NULL, NULL, NULL, '半夏', NULL, '267、半夏 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425060, 'D115266E1BE734767F441B79F94779D1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7931, 438, 902000812, '\n【本经原文】味辛，温，有大毒。治大风，寒湿痹，历节痛，拘挛缓急，破积聚、邪气，金 疮，强筋骨，轻身，健行。生山谷。  \n\n【产地】如乌头。 \n\n【性味】味甘辛，性温热，有毒。 \n\n【主治】天雄与附子之功用略同，惟一般对下元虚寒性机能衰退者及风痰症都多用天雄。 \n\n【别录】疗头面风，去来疼痛，心腹结聚，关节重，不能步行，除骨间痛，长阴气，强心，令人勇武力作不倦。 \n\n【用量】一般一钱至三钱 \n\n【禁忌】热症之人忌用  ', NULL, NULL, NULL, '天雄', NULL, '266、天雄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425061, 'C7268593A77E4D60E050F752F8D96424', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7932, 438, 902000811, '\n【本经原文】，味辛，温，有大毒。治中风，恶风洒洒，出汗，除寒湿痹，咳逆上气，破积聚，寒热。其汁煎之，名射罔。杀禽兽。生山谷。一名奚毒，一名即子，一名乌喙。  \n\n【产地】产我国四川，故亦名川乌，与附子同种，称为附子之母。 \n\n【性味】味辛，性热，有大毒。 \n\n【主治】乌头为扶元回阳，补火退寒要药。功同附子。 \n\n【元素】主诸风，风痹血痹，半身不遂，除寒冷，温养脏腑，去心下坚痞，感寒腹痛。\n\n【好古】补命门不足，肝风虚。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】详见附子。', NULL, NULL, NULL, '乌头', NULL, '265、乌头  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425062, '2040F23424A185D755E5C99468EF3183', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7933, 438, 902000810, '\n【本经原文】味辛，温，有大毒。治风寒，咳逆，邪气，温中，金疮，破症坚，积聚，血瘕，寒湿痿躄，拘挛，膝痛，不能行步。生山谷。一名茛。  \n\n【产地】产我国四川山野，亦可种植，冬播而春生苗，其初种之根，生成小块状者曰乌头，附乌头旁生而大者即附子，又附生而变形者曰天雄，小者毒强而大者毒少，故近人多取用附 子，亦曰大附子。  \n\n【性味】味辛甘，性大热，有大毒。  \n\n【主治】附子为扶元回阳，补火退寒要药，主寒湿痿躄，症瘕积聚，命门火衰，脾胃虚寒，治寒霍乱转筋，阳气暴脱，及真寒假热，阳气欲散，疗寒痰，寒痛，阴疽。  \n\n【别录】腰脊风寒，脚气寒冷弱，心腹冷痛，霍乱转筋，下痢赤白，温中，强阴，坚肌骨，又堕胎为百药长。  \n\n【元素】温暖脾胃，除脾湿，肾寒补下焦之阳虚。  \n\n【好古】督脉为病，脊强而厥。  \n\n【容川】人身之气，生于肾中一阳，实则借鼻孔吸入之天阳，歴心系，引心火下交于肾，附 子可以振肾阳以蒸动其气。其色纯黑，味辛烈，能从下焦扶阳补气，凡极阳极阴，皆有毒，附子之烈，正因其纯是坎阳之性，可以大毒，与肉桂不同，肉桂是补火，属地二之火气也，附子是助热，热生于水中，是得天水之阳，故附子入气分以助阳，能补命门之火，是以火化水，为肾与膀胱要药，火炙则无毒，水中之阳毒，过火则散，此阴阳相引之意。今用盐腌以去毒，使附子之性不全，非正法也，举凡温药皆秉木气，唯附子是水中之阳，为温肾达阳之正药，而得木火者，为得地二之火，能秉水中之阳，是得天一之阳。  \n\n仲景用炮附子，是制其毒也，用生附是以毒追风，毒因毒用，一生一炮，有一定之理。  \n\n【倪注】炮附子可以固表虚，去肺家寒症，生附子可以去里寒，二者截然不同。医者须明辨之，方可以用之无误。临床时可见病人因表虚而至真阳外越，我辈当以炮附子为救逆之剂。如脉细无力，病人昏迷不识人，此为里寒至极，因而真阳不足，当此之时又须以生附为主。  \n\n【药征】主逐水，能治恶寒，身体四肢及骨节疼痛，或沉重，或不仁，或厥冷，而旁治腹痛 失精下利。  \n\n【灵胎】逐寒邪，回阳气。  \n\n【用量】普通一钱至三钱，大剂一至二两。  \n\n【禁忌】乌头附子，用豆腐蒸熟或黑大豆蒸熟者，谓之熟乌头熟附子，味淡而力薄，不能用以救急，生者仅去皮脐，味咸而力猛，可以救急，宜慎用之，经疏曰，一切阳证火证热证，阴虚内热，血液衰少证，均忌，忌豉汁，畏饴。 ', NULL, NULL, NULL, '附子', NULL, '264、附子  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425063, 'F3C2BECDF1A52EFBC6491E73AF76BC18', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7934, 438, 902000809, '\n【本经原文】一名石珠。味辛，平，无毒。治身痒，火疮，痈伤，白秃，疥瘙，死肌。生平泽。  ', NULL, NULL, NULL, '青琅玕,石珠', NULL, '263、青琅玕,石珠  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425064, 'AE7F6F5C9CC43BC023B9BBC07820BB41', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7935, 438, 902000808, '\n【本经原文】一名藜灰。味辛，微温。治黑子，去疣息肉，疽蚀，疥瘙。生川泽。', NULL, NULL, NULL, '冬灰', NULL, '262、冬灰  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425065, '2BB58B9BA75A240B972789C8B983E120', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7936, 438, 902000807, '\n【本经原文】味苦，温，无毒。治女子寒热，症瘕，月闭，积聚，阴肿痛，漏下，无子。生山谷。  \n\n【产地】产河南山西，今他省亦多有之，画家用之，亦名画粉。 \n\n【性味】味苦，性温，无毒。 \n\n【主治】白垩主燥湿温臓，治吐血反胃泻痢，外用治风赤烂眼，疿疹搔痒。 \n\n【别录】阴肿痛瘘下无子，泻痢。 \n\n【甄权】疗女子血结。涩肠，止痢。 \n\n【大明】治鼻红血，痔瘘泄精，男子水藏冷，女子子宫冷。 \n\n【用量】普通数分至一钱。 \n\n【禁忌】用时宜取白色者，以盐汤飞过，以免结涩入肠，不可久服，否则损五脏，令人羸瘦。  ', NULL, NULL, NULL, '白垩', NULL, '261、白垩  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425066, 'FB7C4F83ECF24C8B0FF344E045D5E4BF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7937, 438, 902000806, '\n【本经原文】味苦，寒，无毒。治大热，消渴，狂烦，除邪及吐下蛊毒，柔肌肤。一名寒石。生盐池。\n\n大盐，一名胡盐。寒，无毒。治肠胃结热，令人吐。生池泽。\n\n戎盐。主明目，目痛，益气，坚肌骨，去毒蛊。生北地。', NULL, NULL, NULL, '戎盐,卤咸,大盐', NULL, '260、卤咸 ,戎盐 ,大盐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425067, '60BC32845F7FD3F67F12BA5DC0A05EF4', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7938, 438, 902000805, '\n【本经原文】味苦，寒，无毒。治鬼疰，贼风，蛊毒，杀精物恶鬼，腹中毒，邪气，女子赤沃漏下。生山谷。一名须丸。 \n\n【产地】生齐国山谷。产各处山中，我国北方多有之，色赤。 \n\n【性味】味苦甘，性寒，【或作平】，无毒。 \n\n【主治】代赭石为镇虚祛，养阴血要药，功能避邪毒，治气逆，痰逆，反胃，血中热，血痹，血痢，女子赤白带下。 \n\n【别录】带下百病，产难胞不出，堕胎，养血气，除五脏血脉中热，血痹，血痢，大人小儿惊气入腹，及阴痿不起。 \n\n【大明】安胎健脾，止反胃，吐血，鼻衄，月经不止，肠风痔瘘泻痢，脱精，遗溺，小儿惊 痫疳疾，金疮长肉，辟鬼魅。 \n\n【用量】入煎剂钱半至三钱，水飞用五分至一钱。 \n\n【禁忌】下部虚寒及阳虚阴痿者忌，胎前慎用，畏天雄附子，凡使，醋淬，研末，水飞用。\n\n【容川】赭石重镇，其色赤，又入血分，故一名血师，因其能降血也。血为气之宅，故旋覆花代赭石汤，止噫气者，正是行血而降其气也。  ', NULL, NULL, NULL, '代赭石', NULL, '259、代赭  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425068, '8E7671072E5094607CD10A6812731FCD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7939, 438, 902000804, '\n【本绖原文】味辛，寒，无毒。治伏尸，毒螫，杀三虫。锡镜鼻，平。治女子血闭，症瘕，伏肠，绝孕。生山谷。一名解锡。   \n\n【产地】以醋蒸铅化合而成，日本产此甚多，我国亦有制出，色白，故亦曰白粉，以其为铅所化，故亦曰铅粉。  \n\n【性味】味辛，性寒，无毒。 \n \n【主治】粉锡为外用要药，作膏药，治溃疡，制妆品，除皮病。 \n\n【别录】去鳖瘕。疗恶疮，止小便利，堕胎。 \n\n【甄权】治积聚不消，炒焦止小儿疳痢。 \n\n【大明】治痈肿瘘烂，呕逆，疗症瘕，小儿疳气。 \n\n【用量】普通皆外用，内服甚少，即用，亦宜轻量。 \n\n【禁忌】粉钖用以制妆品，久用蚀血，反使面色不华，故妇女常用粉者，去粉则面黄，且少血色。 ', NULL, NULL, NULL, '粉钖', NULL, '258、粉钖  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425069, 'EFA34D72652C82E1B8D829730A62C2E8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7940, 438, 902000803, '\n【本经原文】味辛，微寒，治吐逆，胃反，惊痫，癫疾，除热，下气，炼化还成九光，久服通神明。生平泽。  \n\n【产地】产我国四川山中，各国亦多有之，色青，故又名青铅。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】铅为镇心坠痰解毒要药，主治积聚，噎膈，恶疮，性重平肝逆，能堕胎。 \n\n【大明】主镇心安神，治伤寒毒气，反胃呕哕，蛇蜴所咬，炙熨之。 \n\n【用量】内服用量宜少，外用无定量。 \n\n【禁忌】性质重坠，能碍消化，虚者慎用，孕妇忌用。  ', NULL, NULL, NULL, '铅丹', NULL, '257、铅丹,青铅  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425070, 'A640BF7AB520F36B1660877690C9D653', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7941, 438, 902000802, '\n【本经原文】味辛，大热，有毒。治寒热，鼠瘘，蚀疮，死肌，风痹，腹中坚癖，邪气，除热。生山谷。一名青分石，一名立制石，一名固羊石。', NULL, NULL, NULL, '礜石', NULL, '256、礜石,青分石,制石,固羊石 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634282896425071, '44F8A7BF8EAA2F9052087933D4F8BE97', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:23:45', 1, 'admin', '2025-01-17 16:43:55');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7942, 438, 902000860, '\n【本经原文】味辛，温，有毒。治邪气，咳逆，温中，逐骨节皮肤死肌，寒湿瘁痛，下气，久服之头不白，轻身，增年。生川谷。 \n\n【产地】椒之一种，产四川故名，今各省多有种植。 \n\n【性味】味辛，性温，有毒。 \n\n【主治】蜀椒为散寒祛湿，补火温中要药，主邪气咳逆，寒热痹痛，宣肺燥脾，治骨节皮肤 死肌，止呕逆，伏蚘虫。 【别录】除六腑寒冷，伤寒温疟，大风汗不出，心腹留饮宿食，肠澼下痢，泄精，女子字乳余疾，散风邪瘕结，水肿黄疸鬼疰蛊毒，杀虫鱼毒，开腠理，通血脉，坚齿发，明目，调关节，耐寒暑，可作膏药。 \n\n【甄权】治头风下泪，腰脚不遂，虚损留结，破血下诸石水，治咳嗽腹内冷痛，除齿痛。 \n\n【大明】破症结，开胸，治天行时气，产后宿血，壮阳，疗阴汗，暖腰膝，缩小便，止呕逆。\n\n【孟铣】益血，利五脏，下乳汁，灭瘢，生毛发。 \n\n【容川】辛温以散寒湿，能杀虫化湿。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】久服令人失明伤血脉，多忘乏气，杏仁为使，得盐味佳，中其毒者，火麻仁浆解之，闭口者有毒勿用。  ', NULL, NULL, NULL, '蜀椒', NULL, '314、蜀椒  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877381, '12A19DE09C3C668AFEC47ECDE34CA420', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7943, 438, 902000859, '\n【本经原文】一名巴菽．味辛，温，有大毒。治伤寒，温疟，寒热，破症瘕，结聚坚积，留饮痰癖，大腹水胀，荡筱五脏六腑，开通闭塞，利水谷道，去恶肉，除鬼毒、蛊疰邪物，杀 虫、鱼。生川谷。  \n\n【产地】产四川，出古之巴郡，故名，木高大，结实作房，内含之仁即巴豆。  \n【性味】味辛，性温，有毒。  \n\n【主治】巴豆为峻泻要药，主荡涤脏腑，开通闭塞，破症坚积聚，留饮痰澼，治大腹水胀，胎伤腹中，利水谷道，排恶疮脓血。 \n\n【别录】疗女子月闭烂胎，金疮脓血，不利丈夫，杀班蝥蛇虺毒，可练饵之益血脉。  \n\n【药性】治十种水肿，瘘痹落胎。 \n\n【日华】通宣一切病，泄壅滞，除风补劳，健脾开胃，消痰破血，排脓消肿毒，杀腹脏虫，治恶疮息肉，及疥癞子疮。 \n\n【元素】导气消积，去脏腑停寒，治生冷硬物所伤。 \n\n【容川】巴豆油滑，而主下降，故能利大便。味大辛故性烈，大热则悍，以悍烈行其滑利，故迅捷而不留也。 \n\n【药征】主治心腹胸膈之毒，兼治心腹卒痛，胀满吐脓。  \n\n【禁忌】凡一切汤散丸剂，切勿轻投，即不得以急证，亦须炒熟压令油极净，入分许即止，不得多用，芫花为使，畏大黄黄莲藜芦冷水，反牵牛，中巴豆毒，用冷水黄莲汁大豆汁解之效。', NULL, NULL, NULL, '巴豆', NULL, '313、巴豆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877382, '141CD06A74985F6D2A77A5C44E41C545', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7944, 438, 902000858, '\n【本经原文】一名去水。味辛，温，有小毒。治咳逆上气，喉鸣，喘，咽肿，短气，蛊毒，鬼疟，疝瘕，痈肿，杀虫、鱼。生川谷。 \n\n【产地】生淮源川谷。产我国河南以及北地山谷中，庭园亦可种植，为约三四尺之落叶灌木，花入药。 \n\n【性味】味辛（或作苦），性温，有毒（或作大毒）。 \n\n【主治】芫花为行水祛痰要药，主水肿，水饮，痰癖，利血脉，治疮毒，参看甘遂大戟等条。\n\n【别录】消胸中痰水喜唾，水肿，五水在五脏皮肤，及腰痛，下寒毒，肉毒，根疗疥疮，可用毒鱼。 【甄权】治心腹胀满，去水气寒痰，涕唾如胶，通利血脉，治恶风痹湿，一切毒风，四肢挛急，不能行步。 \n\n【大明】疗咳嗽瘴疟。 \n\n【药征】主逐水也，旁治咳掣痛。 \n\n【用量】普通七分至二钱。 \n\n【禁忌】时珍曰，饮有五，皆由内啜水浆。外受湿气，郁蓄而为留饮，芫花大戟甘遂，逐水泄热，能直达水饮巢囊隐癖之处，但可徐徐用之，取效甚捷，不可过剂，泄人元气，反甘草，能堕胎，孕妇忌用，醋制良，参看甘遂大戟条。  ', NULL, NULL, NULL, '芫花', NULL, '312、芫花  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877383, 'DDECF76F2C5FCF7E2E08BE23DC2CE48C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7945, 438, 902000857, '\n【本经原文】味苦，辛，寒，无毒。治寒热瘰，鼠瘘，头疮，破症，散瘿结气，脚肿，湿痹，轻身。生川谷。一名夕句，一名乃东。  \n\n【性味】味苦辛，性微寒，无毒。 \n\n【主治】夏枯草为瘰疬要药，主养阴血，散结毒，治目珠疼夜甚，阴肿赤白带下，消暑清湿。  \n\n【灵胎】泻湿热，散结气。\n\n【用量】普通一钱至三钱。  \n\n【禁忌】不详。  \n\n【容川】此以时为治之药，夏枯草生于冬末，长于三春，正得水木之气，遇夏则枯，因木当火令，其气退谢，故可用以退肝胆经之火。  \n\n【倪注】民间方使用单味夏枯草五钱，生鸡蛋带壳一只，用水二碗煮成一碗，将汤喝尽，去壳吃蛋，如果于健康时吃一剂，则终身不再犯扁桃腺炎。 ', NULL, NULL, NULL, '夏枯草', NULL, '311、夏枯草  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877384, 'E9ECE63EBF0DE6C32F302F6B14AA2E5A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7946, 438, 902000856, '\n【本经原文】味苦，微寒，无毒。治身皮疮热气，可作浴汤，杀牛虱、小虫、又治牛病。生川谷。  ', NULL, NULL, NULL, '牛扁', NULL, '310、牛扁  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877385, '09772B11D3E78303FB851EDD3E9C81C2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7947, 438, 902000855, '\n【本经原文】味苦，平，无毒。治久咳上气，喘逆，久寒，惊悸，痂疥，白秃，疡气，杀皮肤小虫。生川谷。', NULL, NULL, NULL, '盖草', NULL, '309、盖草  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877386, '58C14049974D997BBE6F1A1BA30E7866', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7948, 438, 902000854, '\n【本经原文】味苦，寒，无毒。治骨间诸痹，四肢拘挛、疼酸，膝寒痛，阴痿，短气不足，脚肿。生川谷。  ', NULL, NULL, NULL, '陆英', NULL, '308、陆英  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877387, '8112779DC646E404D4F8F1BFA1C22553', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7949, 438, 902000853, '\n【本经原文】一名丹草。味咸，微寒，有毒。治寒热，恶疮，大热，辟鬼气不祥。生山谷。\n\n【产地】产我国陕西，各处亦多有之，生于高山峻崖之上，四时不凋，固号长生。 \n\n【性味】味咸，性微寒，有毒。 \n\n【主治】石长生主积聚痈肿，豁痰利尿，功能散结凝排脓，治胸膈满闷，咳嗽喘满。为解毒杀虫要药。 \n\n【别录】下三虫。 \n\n【甄权】治疥癣，逐诸风，治百邪魁。 \n\n【用量】普通一钱至钱半。 \n\n【禁忌】不详。 ', NULL, NULL, NULL, '石长生', NULL, '307、石长生  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877388, '1752EFB5E92EC71CFE5C4477D99AEF77', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7950, 438, 902000852, '\n【本经原文】味苦，微寒，有毒。治惊痫，摇头。弄舌，热气在腹中，癫疾，痈疮，阴蚀，下三虫，去蛇毒。生川谷。一名蚩休。 \n\n【产地】处处有之，生于深山阴湿之地。 \n\n【性味】味苦，微寒，有毒。 \n\n【主治】蚤休主散结导热，治寒热，疟疾，癫疾，痈疽，瘰疬，解蛇毒虫（磨醋敷）。 \n\n【别录】癫疾痈疮，除蚀，下三虫，去蛇毒。 \n\n【大明】治胎风手足搐，能吐泄瘰疬。 \n\n【用量】普通五分至二钱，外用无定量。 \n\n【禁忌】以治外证，殊有功效，但其性苦寒，不宜多服，元气虚者忌之。  ', NULL, NULL, NULL, '蚤休', NULL, '306、蚤休  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877389, 'B3E81E5D63AA6311CCFB7A0204ED6700', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7951, 438, 902000851, '\n【本经原文】味苦，平，无毒。治蛊毒，女子腰腹痛，不乐，肠痈，瘰疬，疡气。生山谷', NULL, NULL, NULL, '鹿藿', NULL, '305、鹿藿  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877390, 'B0FF2F022A7B1C0B0E6D342D3224FE65', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7952, 438, 902000850, '\n【本经原文】味甘，寒，无毒。治皮肤往来寒热，利小肠膀胱气。生山谷石上。  ', NULL, NULL, NULL, '乌韭', NULL, '304、乌韭  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877391, '0DCBB8CC5A3FAA03BB560CF3F008F636', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7953, 438, 902000849, '\n【本经原文】味辛，寒，有小毒。主蚀恶肉，败疮，死肌，杀疥虫，排脓、恶血，除大风，热气，善忘，不乐。生川谷。', NULL, NULL, NULL, '蔺茹', NULL, '303、蔺茹  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877392, '284323DD5D9C42CF44755A23BD06C5F3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7954, 438, 902000848, '\n【本经原文】一名异翘，一名兰华。一名折根，一名轵，一名三廉。味苦，平，无毒。治寒热，鼠瘘，瘰疬，痈肿。恶疮，瘿瘤，结热，蛊毒。生山谷。  \n\n 【产地】生太山山谷。产山谷中及泽地，处处有之，四川产者为胜。 \n\n【性味】味苦辛，性平，无毒。 \n\n【主治】连翘为散结清火要药，主治疮疡，能清火解毒，消肿排脓，散血结气聚，去上焦热，通利小便。 \n\n【别录】去白虫。 \n\n【甄权】通利五淋，小便不通，除心家客热。 \n\n【大明】通小肠，排脓治疮疖，止痛，通月经。 \n\n【丹溪】泻心火，除脾胃湿热，治中部血证以为使。 \n\n【东垣】散诸经血结气聚，消肿。 \n\n【容川】连翘亦象心包，而质轻扬，味征苦，故轻扬上达，能清心与上焦头目之热，其无辛散之气，故不主散。 \n\n【灵胎】散郁火，治疮疡。 \n\n【倪注】此药常与银花同用，皆属味清而质轻，皆能升清气。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】连翘清而无补之药也，痈疽已溃及日久，火热由于虚，与脾胃薄弱作泄者均忌，忌火。', NULL, NULL, NULL, '连翘', NULL, '302、连翘  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877393, '376DEE5832940464765F38644530E7BF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7955, 438, 902000847, '\n【本经原文】味辛，平，有毒．治蛊毒，逐邪恶气，杀鬼，温疟，辟不祥，生山谷。一名雀瓢。  ', NULL, NULL, NULL, '女青', NULL, '301、女青  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877394, '61CF9E35102BF6578EEC7D30AFE1DF0D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7956, 438, 902000846, '\n【本经原文】味苦，寒，有毒。治熛热，身暴赤色，风水，积聚，恶疡，除小儿热，生山林川谷及田野。一名鬼桃，一名羊肠。', NULL, NULL, NULL, '羊桃', NULL, '300、羊桃  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877395, '5407508BFD9AC3268FAB32596DBF5C0E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7957, 438, 902000845, '\n【本经原文】味辛，温，有毒。主杀蛊毒，鬼疰，精物，辟恶气不详，逐邪，解百毒。生山谷。一名爵犀，一名马目毒公，一名九臼。  ', NULL, NULL, NULL, '鬼臼', NULL, '299、鬼臼  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634286036877396, '6E47B18A79BF1C4778697BDC1BA7E795', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 17:36:32', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7958, 438, 902000903, '\n【本经原文】味甘，温，有毒。治腹中邪气，去三虫，蛇螫，蛊毒，鬼疰，伏尸。生山谷。', NULL, NULL, NULL, '彼子', NULL, '357、彼子  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115269, 'E23EB5F3E7503A01DCE6704AB01ACEA0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7959, 438, 902000902, '\n【本经原文】一名水英。味甘，平，无毒。治女子赤沃，止血，养精，保血脉，益气，令人肥健，嗜食。生南海，池泽。又名芹菜。  \n\n【产地】处处有之。 \n\n【性味】味甘性平，有特殊的香味。 \n\n【主治】解热止血，健胃药，治女子血崩赤带，小儿暴热，大人酒后热。 \n\n【本经】主女子赤沃，止血养精，保血脉，益气，令人肥健，嗜食。  \n\n 【藏器】饮汁去小儿暴热，大人酒后热，鼻塞身热，去头中风热，利口齿，利大小肠。\n\n【大明】治烦渴、崩中，带下，五种黄病。 \n\n【圣惠】捣汁日服六七合，治小便出血。  ', NULL, NULL, NULL, '芹菜', NULL, '356、水斳,芹菜 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115270, 'A17F02A0BDE094CEEB10F8E508EF67CB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7960, 438, 902000901, '\n【本经原文】味苦，寒，有毒。治大水，面目四肢浮肿，下水，令人吐。生川泽。\n\n【产地】产我国山西，他省亦多有之，瓤及子入药。 \n\n【性味】味苦，性寒，有毒。 \n\n【主治】苦瓠主治水肿，利小便，通淋，治疮。 \n\n【苏敬】利石淋，吐呀嗽。囊结疰蛊，痰饮。又煮汁渍阴，疗小便不通。  \n\n 【藏器】煎汁滴鼻中出黄水，去伤冷鼻塞黄疸。 \n\n【大明】吐蛔虫。 \n\n【用量】普通二至三钱，大剂无定量。 \n\n【禁忌】服苦瓠过分吐利不止者，以黍穰灰汁解之。 ', NULL, NULL, NULL, '苦瓠', NULL, '355、苦瓠  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115271, '7604168BB9F084713AB5885612C84AF2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7961, 438, 902000900, '\n【本经原文】小豆花也。味辛，平，无毒。治痎疟，寒热，邪气，泄利，阴不起，病酒头痛。\n\n【药征】主治心中懊恼，旁治心中结痛及心中满而烦也。 \n\n【用量】不定量。 \n\n【禁忌】无。  ', NULL, NULL, NULL, '腐婢', NULL, '354、腐婢  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115272, '1AF9213BED51E40CC57766C941528878', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7962, 438, 902000899, '\n【本经原文】味甘，温，有毒。治咳逆上气，肠中雷鸣，喉痹，下气，产乳，金疮，寒心，奔豚。生川谷。今名杏仁。 \n\n【产地】生晋山川谷。杏树处处有之，有多种，以产山西河南山东一带者为胜，仁入药。 \n\n【性味】味甘苦，性温，有小毒。 \n\n【主治】杏仁为咳逆痰气要药，主咳嗽气急，能下气平喘，治风寒痰滞，能宣肺解肌，除风散寒，润燥消积，利胸膈气滞。通大肠气闭。  \n\n【别录】惊痫，心下烦热，风气往来，时行头痛，解肌，消心下急满痛，杀狗毒。 \n\n【甄权】治腹痹不通，发汗主温病角气，咳嗽上气，喘促，入天门冬煎润心肺，和酪作汤润 声气。 \n\n【元素】除肺热，治上焦风燥，利胸膈气逆，润大肠气秘。 \n\n【容川】杏仁有油，但得苦味，无辛烈之气，故降而不及。色白属金，降气行痰，气降则血降，故凡吐血必咳痰，痰为气分，因气逆而血升，故引出其血也。 \n\n【药征】主治胸间停水也，故治喘咳，而旁治短气结胸，心痛，形体浮肿。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】凡杏子性皆热，小儿多食致疮痈膈热，多食动宿疾，产妇尤忌，杏仁双仁者有毒能杀人，阴虚咳嗽，肺家有虚热痰者均忌，恶黄', NULL, NULL, NULL, '杏仁', NULL, '353、杏核仁  ,杏仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115273, '7F87829395CF982E2DBDC730C1BD7F0B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7963, 438, 902000898, '\n桃花——杀疰恶鬼，令人好颜色。 桃枭——在树不落，微温，主杀百鬼精物。 桃毛——平，主下血瘕，寒热积聚，无子。 桃蠹——杀鬼，辟邪恶不祥。生川谷。 \n\n【本经原文】味苦。平。主治瘀血。血闭瘕邪气。杀小虫。\n\n【产地】处处有之，以产河南陕西者为良，仁入药。 \n\n【性味】味苦甘，性平，无毒。主治瘀血。血闭瘕邪气。杀小虫。 \n\n【主治】桃仁为破血润燥要药，主行瘀血，消心下坚硬，治血晕血痞血积血痢，血热燥痒，蓄血发狂，通月经。 \n\n【别录】止咳逆上气，消心下坚硬，除卒暴击血，通月血，止心腹痛。 \n\n【元素】治血结血秘血燥，通润大便。破蓄血。 \n\n【孟铣】杀三虫，又每夜嚼一枚和蜜涂乎面良。 \n\n【容川】桃花红而仁味苦，皆得地火之性，仁在核中，又象人心，味苦有生气，是正入心中，故桃仁能破血，亦能生血。气属阳，血属阴，瘀血阻气，则阳不入阴，蒸热汗出，宜破其血，使气得入于血中，则不壅热，桃仁主之。 \n\n【灵胎】逐瘀血，除邪气。 \n\n【倪注】痘家勿用，因仁有生气，可令痘长。 \n\n【药征】主治瘀血，少腹满痛，兼治肠痈及妇人经水不利。 \n\n【用量】普通一钱至二至三钱。 \n\n【禁忌】生桃实多食，令人膨胀及生疮疽，与鳖同食患心痛，服术人忌之，作脯食，益颜色，肺病宜之。桃仁散而不收，泻而无补，过用或不当，能使血下不止，损伤真阴，故凡经闭由 于血枯，产后腹痛由于血虚，大便闭涩由于津液不足者均忌，双仁者有毒，不可食。 ', NULL, NULL, NULL, '桃仁', NULL, '352、桃核仁  ,桃仁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115274, '7CC8AD2217AB182C987FF1350625BD50', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7964, 438, 902000897, '\n【本经原文】味咸，温，无毒。治妇人疝瘕，小便不利，小儿中风，项强，皆宜摩之。生平泽。一名白鱼。  \n\n【产地】产湖中，即白鲤鱼也。  \n\n【性味】甘平无毒。味薄不美，故渔人时而弃之。  \n\n【主治】去水气愈肿也。  \n\n【用量】属食物类，无定量。  \n\n【禁忌】无。  ', NULL, NULL, NULL, '衣鱼', NULL, '351、衣鱼  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115275, '361C68369713E3CEF9F67E405A279B97', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7965, 438, 902000896, '\n【本经原文】一名夜光。味辛。微温，无毒。主明目，小儿火疮，伤热气，蛊毒，鬼疰，通神精。生阶地、池泽。  ', NULL, NULL, NULL, '萤火', NULL, '350、萤火  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115276, '18B5D538227C42B257073C9A3969D3AF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7966, 438, 902000894, '\n【本经原文】味辛，寒，有毒。治鬼疰，寒热，鼠瘰，恶疮，死肌，破症瘕，堕胎。生川谷。一名蚖青。  ', NULL, NULL, NULL, '地胆', NULL, '348、地胆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115277, 'F4C687D1E1157C3449C44A63615339A1', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7967, 438, 902000895, '\n【本经原文】味酸，温，无毒。治气癃不得小便，妇人月闭，血症，痫，痉，寒热，利水道。生平谷及人家地上。一名负燔，一名蝛。 \n\n【产地】处处有之，多在下湿处瓮器底及土坎中。 \n\n【性味】味酸，性温，无毒。 \n\n【主冶】鼠妇主利水道，去瘀积，治久疟寒热，妇人月闭，能堕胎。 \n\n【日华】主气癃不得小便，妇人月闭血瘕，痫痓，寒热，利水道，堕胎。 \n\n【用量】普通钱许。 \n\n【禁忌】孕妇忌之', NULL, NULL, NULL, '鼠妇', NULL, '349、鼠妇  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115278, 'E8BABA9B2EC80DD4887C789B6BF4A2FF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7968, 438, 902000893, '\n【本经原文】味辛，温，有毒。治腹中大坚症，破积聚，息肉，恶疮，白秃。生川谷。一名百足。  ', NULL, NULL, NULL, '马陆', NULL, '347、马陆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115279, 'CB6BD8CBCD41E0F16534E31E7F7B08D0', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7969, 438, 902000892, '\n【本经原文】味咸，寒，无毒。治产难，出肉中剌，溃痈肿，下哽噎，解毒，除恶疮，生平泽。一名蟪蛄，一名天蝼。 \n\n【产地】处处有之，穴地粪壤中而生，夜则外出求食，有短翅，能低飞。 \n\n【性味】味咸，性寒，无毒（或作有毒）。 \n\n【主治】蝼蛄主行水解毒，下哽噎，利二便，治大腹水肿，通石淋，疗难产，外涂出肉剌，治痈肿。  \n\n【日华】治水肿，头面肿。  \n\n【丹溪】治口疮甚效。  \n\n【用量】普通二至三钱。 \n\n【禁忌】欲利大小便，用自腰以后半截，但其性急，虚者忌之，入药取雄者（善鸣而非腹较小），去翅足炒用。  ', NULL, NULL, NULL, '蝼蛄', NULL, '346、蝼蛄 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115280, '71F55E9D85D64E69AA427C0A10850D7A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7970, 438, 902000891, '\n【本经原文】味咸，寒，有毒。治小儿惊痫，瘛瘲，腹胀，寒热，大人癫疾，狂易。生池泽。  \n一名蛣蜣。  \n\n【产地】产山区树间。  \n\n【性味】味咸，性寒。 \n\n【主治】功能通二便，治食痫，癫疾狂阳，脱肛，灸疮出血。 \n\n【时珍】治大小便不通，下利赤白，脱肛，一切痔瘘疔肿，附骨疽疮，灸疮出血不止，鼻中息肉，小儿重舌。  ', NULL, NULL, NULL, '蜣螂', NULL, '345、蜣螂  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115281, '3FBBFF9BD2E82C275ECE78C261A046B3', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7971, 438, 902000890, '\n【本经原文】味甘，平，无毒．治小儿惊痫，寒热，结气，蛊毒，鬼疰。生树枝间。一名躁舍。又名知了。今名蝉蜕。  \n\n【产地】生夏日树间。 \n\n【性味】昧甘咸性寒。 \n\n【主冶】为解热镇惊退翳之药，治小儿热惊，皮肤风热瘾疹。目生翳瘴，治小儿哑病及阴肿。\n\n【别录】治小儿惊痫，妇人生子不下，烧灰酒服，治久病。 \n\n【藏器】研末一钱，用华水调服，治哑病。 \n\n【宗奭】除目昏除翳，以水煎汁服，治小儿疮疹出不快，甚良。 \n\n【时珍】治头风眩晕，皮肤风热，痘疹作痒，破伤风，及疔肿毒疮，大人失音，小儿噤风天吊，惊哭夜啼，阴肿。 \n\n【用量】一般五分至一钱。  \n\n【禁忌】无。  \n\n【附方】 小儿惊啼——蝉蜕后半截为末，入薄荷脑少许，每服一匙蜜调下，亦治夜啼。瘾疹——皮肤起红瘢痒，蝉蜕与薄荷叶等分为末，每酒服一钱，日三。 痘后目翳——蝉蜕为末，每服一钱，日二。 小儿阴肿——蝉蜕半两煎水洗，内服五苓散，即肿消痛止。 ', NULL, NULL, NULL, '蝉蜕,知了,雀瓮', NULL, '344、雀瓮,知了,蝉蜕', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115282, '810261931924646621492862085117C6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7972, 438, 902000889, '\n【本经原文】味咸，寒，有毒。治五癃，破石淋，堕胎。肉，解结气，利水道，除热。生池泽。一名沙虱。  ', NULL, NULL, NULL, '石蚕', NULL, '343、石蚕  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115283, '44913CF0313880C41E40A1726C1458F4', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7973, 438, 902000888, '\n【本经原文】味咸，平，有毒。治目翳，鬼疰，腹痛，下血，五癃，利水道。生东海池泽。一名贝齿。又名大贝。 \n\n【产地】产海滨，壳略似三角形，口作锯齿状，有白色紫色之花者。 \n\n【性味】味咸，性平，有毒。 \n\n【主治】贝齿主散结热，利水道，治目翳，狂热，鬼疰蛊毒，搜湿毒，通五癃。 \n\n【别录】温病寒热，解肌，散结热。 \n\n【甄权】伤寒狂热。 \n\n【弘景】烧研点目去翳． \n\n【李珣】下水气浮肿，小儿疳蚀，吐乳。 \n\n【用量】普通二至三钱。 \n\n【禁忌】蜜醋浸透，虾米酒淘入药，无湿热结滞者勿用。', NULL, NULL, NULL, '贝子,贝齿,大贝', NULL, '342、贝子,贝齿,大贝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115284, 'BD4B9BAD2BE5B9411B2693DC07C999F7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7974, 438, 902000887, '\n【本经原文】味辛寒，有毒。治寒热，鬼疰，虫毒，鼠瘘，恶疮，疽蚀，死肌，破石癃。生川谷。一名龙尾。  \n\n【产地】处处有之，大豆叶上甲虫也，有黄斑文。 \n\n【性味】味辛，性寒，有毒。 \n\n【主治】斑蟊主瘰疬虫毒，治血积，蚀死肌，破石癃，堕妊娠死胎，敷鼠瘘恶疮。 \n\n【别录】血积，伤人肌，治疥癣，堕胎。 \n\n【甄权】治瘰疬，通利水道。 \n\n【日华】疗淋疾，傅恶疮，瘘烂。 \n\n【用量】普通二分至三分。 \n\n【禁忌】有毒，用时去翅足，同糯米炒熟，或麸炒过，醋煮用，亦有用米取气不取质者，生  \n用则吐泻，马刀为使，畏巴豆丹参空青，恶曾青甘草豆花，惟性猛毒，力能烂肉堕胎，体虚 者忌之  ', NULL, NULL, NULL, '斑蟊', NULL, '341、斑蟊', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115285, '2986DE3A6F1C4BA46192256CD276D23E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7975, 438, 902000886, '\n【本经原文】味咸平，有毒。主逐恶血，瘀血，月闭，破血瘕，积聚，无子，利水道。生池泽。一名至掌。 \n\n【产地】生雷泽池泽。产池泽中，处处有之，好吸附人畜肌肤而吮其血。 \n\n【性味】味咸，性平，有毒。 \n\n【主治】水蛭主逐恶血，破征积，治折伤坠扑，蓄血疼痛，堕胎通经，外治肿毒。 \n\n【别录】堕胎。 \n\n【药性】治女子月闭，欲成干血劳。 \n\n【藏器】痈肿毒肿。 \n\n【宗奭】治折伤坠蹼蓄血有功。 \n\n【容川】锐而善入，又能允血，故主攻血积。 \n\n【灵胎】逐瘀破积。 \n\n【用量】普通一至二钱。 \n\n【禁忌】破血泄结之品，不可轻服，误吞水蛭，入腹难死，久则生子，食人肝血，腹痛难忍，面目黄瘦，用田中泥一两，雄黄二钱为丸，分四服，开水下，即随大便而出，桂圆肉包烟油吞之，即下，此物畏石灰食盐。  ', NULL, NULL, NULL, '水蛭', NULL, '340、水蛭  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115286, '863B51AD3213326D1091FC41EB3A3B28', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7976, 438, 902000885, '\n【本经原文】味辛，温，有毒。治鬼疰，虫毒，啖诸蛇、虫、鱼毒，杀鬼物老精，温疟，去三虫。生川谷。  \n\n【产地】处处有之，赤足者良。  \n\n【性味】味辛，性温，有毒。 \n\n【主治】蜈蚣为驱风散结要药，主小儿惊痫，风搐脐风，治寒热积聚，堕胎，去恶血，制蛇毒。  \n\n【别录】疗心腹寒热积聚，堕胎，去恶血。  \n\n【日华】治癥瘕。  \n\n【用量】普通一至二钱。 \n\n【禁忌】蜈蚣有毒，必风气暴烈，药病相当，乃可设，或过剂，以蚯蚓桑皮解之，畏蛞蝓，被蜈蚣螫伤，捣蛞蝓涂之即止痛。', NULL, NULL, NULL, '蜈蚣', NULL, '339、蜈蚣  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115287, 'E4F3E4429536045B5BB657E3D894BD6A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7977, 438, 902000884, '\n【本经原文】味辛，平，无毒。治久聋，咳逆，毒气，出刺，出汗。生川谷或人屋间。  ', NULL, NULL, NULL, '翳螉', NULL, '338、翳螉  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115288, 'FCB6A15CAC4480C1C8D477167866C2D7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7978, 438, 902000883, '\n【本经原文】味咸，寒，无毒。治蛇瘕，去三虫，伏尸，鬼疰，虫毒，杀长虫。仍自化作水。生平土。今名地龙。 \n\n【产地】田中或韭田中及地下，处处有之。 \n\n【性味】味甘酸，性寒，无毒。 \n\n【主治】蚯蚓主解毒，傅疮，小便不通，赤白痢疾。 \n\n【藏器】主赤白久热痢，取一升炒烟尽，沃汁半升滤净饮之。 \n\n【日华】小儿阴囊忽虚热肿痛，以生甘草汁入轻粉末调涂之，以盐研傅疮去热毒，及蛇犬伤。\n\n【苏敬】傅狂犬伤，出犬毛神效。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】内服宜煎汁澄清，不必用渣。  ', NULL, NULL, NULL, '白颈蚯蚓', NULL, '337、白颈蚯蚓  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115289, '3BF1F6D266A05E2BA43BA4B928952A8B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7979, 438, 902000882, '\n【本经原文】味咸，平，无毒。治小儿百二十种惊痫，瘈瘲，癫疾，寒热，肠痔，虫毒，蛇痫。生川谷及田野。一名龙子衣，一名蛇符，一名龙子单衣，一名弓皮。 \n\n【产地】处处有之，多蜕于石上及人家墙屋间，白色如银者入药。 \n\n【性味】味咸甘，性平，无毒（或作小毒）。 \n\n【主治】蛇蜕主瘈瘲癫疾，弄舌摇头，治皮肤疥癣疮疡，明目退翳。 \n\n【别录】大人五邪，言语僻越，止呕逆，明目，烧之疗诸恶疮。 \n\n【甄权】喉痹，百鬼魅。 \n\n【日华】炙用辟恶，止小儿惊悸客热，煎汁傅疬疡，白瘢风，摧生。 \n\n【孟铣】安胎。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】性走窜，凡小儿惊痫癫疾，非外邪客忤而由肝心虚者忌用，孕妇忌之，畏磁石及酒，得火熬之良。', NULL, NULL, NULL, '蛇蜕', NULL, '336、蛇蜕  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115290, '833EA2EC48F72B7C14A4DA7F3012BF05', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7980, 438, 902000881, '\n【本经原文】味辛，微寒，有毒。治漏下赤白，寒热，破石淋，杀禽兽，贼鼠。生江湖池泽及东海。  ', NULL, NULL, NULL, '马刀', NULL, '335、马刀  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115291, '3F9CE34A38A75E3B5B5B00C0288438C8', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7981, 438, 902000880, '\n【本经原文】味辛，寒，有毒。治邪气，破症坚血，痈肿，阴疮，服之不患热病。生江湖池泽。  ', NULL, NULL, NULL, '蟾蜍,虾蟆', NULL, '334、虾蟆  ,蟾蜍', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115292, '304947ABE7A36328512FEC4ABF98AA06', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7982, 438, 902000879, '\n【本经原文】味咸，平，有毒。治鬼疰，虫毒，寒热，惊痫，癫，痉，狂走。骆驼毛，尤良。 ', NULL, NULL, NULL, '六畜毛蹄甲', NULL, '333、六畜毛蹄甲  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115293, 'CCC6F8D01B1A8434F0E7FD772172E1F2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7983, 438, 902000878, ' \n【本经原文】微温。主堕胎，令产易。生平谷。  ', NULL, NULL, NULL, '鼯鼠', NULL, '332、（鼯）鼠', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115294, '449C8F8D936A382B6A9D4E0FD891627A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7984, 438, 902000877, '\n【本经原文】味辛，温，无毒。治痈肿，恶疮，死肌，风寒湿痹，四肢拘缓不收，风头肿，气通腠理。生山谷及淮海边。一名官脂。  ', NULL, NULL, NULL, '麋脂', NULL, '331、麋脂  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115295, 'AC2FEA2D01244AE7AC9784C09704B90B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7985, 438, 902000876, '\n【本经原文】味甘，温，无毒。治惊痫，癫疾，鬼疰，虫毒，除寒热，奔豚，五癃，邪气，挛缩。悬蹄，平。主五痔，伏热在肠，肠痈内蚀。一名豚颠。  ', NULL, NULL, NULL, '豚卵', NULL, '330、豚卵  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115296, '900E604C8457C607F834D3661566E60E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7986, 438, 902000875, '\n【本经原文】味苦，温，无毒。治风寒湿痹歴节疼，除四肢厥气，膝痛。生川谷及丘冢间。一名豕椒。  ', NULL, NULL, NULL, '蔓椒', NULL, '329、蔓椒  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115297, '6B79C05B4EE15F9AC4CB8EEC08F8C59C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7987, 438, 902000874, '\n【本经原文】味苦，寒，无毒。治目痛，泪出，伤眦，消目肿。生川谷。', NULL, NULL, NULL, '栾花', NULL, '328、栾花  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115298, 'CBDC84DB217D16B03BAE4247817F757F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7988, 438, 902000873, '\n【本经原文】一名连木。味辛，温，无毒。治邪气，诸痹疼酸，续绝伤，补骨髓。生山谷。  ', NULL, NULL, NULL, '药实根', NULL, '327、药实根  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115299, '856EA2D7471B84D7060E7BD3245DD221', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7989, 438, 902000872, '\n【本经原文】治寒热，瘰疬疮。生田野。今少用。 \n\n【产地】处处有之。 \n\n【性味】味苦性寒，有微毒，其皮味苦性寒，无毒。 \n\n【主治】解毒，破积杀虫药，治瘰疬，疝瘕腹胀，天花黑陷，疥癣有虫。皮可治热毒及疳虫。\n\n 【大明】治水肿腹胀满。 \n\n【苏敬】下血及碎肉，除疝瘕积冷，九蒸酒渍，服三合。 \n\n【别录】鼠李皮治身皮热毒。 \n\n【孟铣】治口疳蛀齿，及疳虫蚀人脊骨者，煮浓汁灌之良。  ', NULL, NULL, NULL, '鼠李', NULL, '326、鼠李  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115300, '399D1B706D5A19A94553FE6D5465E98E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7990, 438, 902000871, '\n【本经原文】味辛，寒，无毒。治身皮肤中热，除邪气，止遗溺。生川谷及田野故丘墟地。  \n可作浴汤。  ', NULL, NULL, NULL, '溲疏', NULL, '325、溲疏  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115301, 'D7EA7544385B6FE772158EBF1B83679B', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7991, 438, 902000870, '\n【本经原文】一名凌泉，一名大就。味苦，平，有毒。治蛊毒，鬼疰，鬼魅，邪气在臓中，除咳逆，寒热。生山谷。', NULL, NULL, NULL, '黄环', NULL, '324、黄环  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115302, 'F46496D247B58D999A86A85E4721EFE9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7992, 438, 902000869, '\n【本经原文】一名鬼目。味辛，平，有毒。主养肾气，内伤阴衰，利筋骨皮毛。实，杀虫毒，破积聚，逐风痹。生山谷。', NULL, NULL, NULL, '古南', NULL, '323、古南  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115303, '1E0B503725C06C87756B93ED7B18E812', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7993, 438, 902000868, '\n【本经原文】味苦，寒，无毒。治热，去三虫。花、叶，捣敷猪疮。饲猪，肥大三倍。生山谷。  \n\n【产地】生河内山谷。生山区。 \n\n【性味】味苦，性寒。 \n\n【主治】梓白皮能解热，杀虫，亦治反胃疮疥，梓实为排水利尿药，治浮肿有效。 \n\n【别录】疗目中疾，主吐逆胃反，小儿热疮，身头烦热，蚀疮，煎汤浴之，并捣敷。\n\n【大明】煎汤洗小儿壮热，一切疮疥，皮肤搔痒。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】寒症忌用。  ', NULL, NULL, NULL, '梓白皮', NULL, '322、梓白皮  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115304, '594FF619F30BB77130ED348ED1E8944D', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7994, 438, 902000867, '\n【本经原文】味苦，寒，无毒。治恶蚀疮着阴。皮，治五痔，杀三虫，花，主敷猪疮，饲猪，肥大三倍。生山谷。  \n\n【产地】产山区。  \n\n【性味】桐叶及桐木皮俱味苦，性寒。  \n\n【别录】桐木皮疗奔豚气病。 \n\n【甄权】桐木皮治五淋，沐发去头风，生发滋润。  \n\n 【时珍】桐叶消肿毒，生发，桐木皮治恶出疮，小儿丹毒，煎汁涂之。  \n\n【用量】一般三钱至五钱。  \n\n【禁忌】无。  \n\n【附方】 手足浮肿——圣惠方，桐叶煎汁渍之，并饮少许，加小豆良。肘后方：削桐木煮汁洗，并饮少许。 发落不生——桐叶一把，麻子仁三升，米泔煮汤去渣，日日洗之。（肘后） 眼见诸物——禽虫飞走，乃肝胆之疾，青桐（紫花者）花，酸枣仁，元明粉，羌活各一两为末，每服二钱，水煎和渣服，日三。（经验方）  ', NULL, NULL, NULL, '桐叶', NULL, '321、桐叶  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115305, 'DB88A830AD8085B2C8EA16A41975121A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7995, 438, 902000866, '\n【本经原文】一名雷矢。味苦，寒，有小毒。主杀三虫，逐毒气，胃中热，利丈夫，不利女子。作膏摩，除小儿百病。生山谷土中。 \n\n【产地】产我国河南陕西湖北等地，生土中，为竹之余气所结，故亦曰竹苓。 \n\n【性味】味苦（或作咸），性寒，有小毒（或作无毒）。 \n\n【主治】雷丸为消积杀虫要药，主除皮中热结，逐毒气，杀诸虫，作摩膏治小儿百病。 \n\n【别录】作摩膏除小儿百病，逐邪气恶风汗出，除皮中热结，积虫毒，白虫寸白，自出不止，久服令人阴痿。 \n\n【甄权】逐风，主痫狂走。 \n\n【用量】普通一至二钱。 \n\n【禁忌】不利女子，多服令人阴痿。  ', NULL, NULL, NULL, '雷丸', NULL, '320、雷丸  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115306, 'BDE28058C3A25125DAC25BFBCDD5952C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7996, 438, 902000865, '\n【本经原文】味辛，温，有毒。治风头，痈肿，乳痈，疝瘕，除结气，疥瘙，杀虫、鱼。生山谷。  \n\n【产地】处处有之。  \n\n【性味】味辛性温有毒。  \n\n 【主治】消肿，杀虫要药，治痈肿，瘰疬，疥癣，白秃，头风痛及皮肤麻痹。 \n\n【别录】疗喉痹不通，乳难，头风痒，可用沐，勿内服。 \n\n【甄权】治风疽疝气肿坠，凝血，治瘰疬，除风湿，不入汤服，主头疮白秃，杀虫，与白蔹，赤小豆为末，鸡子白调之如糊，敷毒肿，干更易之。 \n\n【用量】无定量。  \n\n【禁忌】只可做沐汤及外敷药，不可内服。  ', NULL, NULL, NULL, '莽草', NULL, '319、莽草  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115307, '34A1E7E40B8D1AAF19D356A5F946CF8E', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7997, 438, 902000864, '\n【本经原文】味酸，平，无毒。治大腹水肿，面目四肢浮肿，利小便水道，根，治齿断肿，龋齿，坚齿。生高山川谷及丘陵。一名爵李。  \n\n【产地】产我国陕西甘肃等地，他处亦多有之，其树虽似李树，而结子小若樱桃，核仁入药。  \n\n【主治】郁李仁为润燥破血，泄气行水要药，主大肠气滞，关格不通，治大腹水肿，四肢浮肿，破结气，利水道。  \n\n【孟铣】破癖气，下四肢水，酒服四十九粒，能泻结气。  \n\n【甄权】阳中结气，关格不通 \n\n【大明】泄五脏膀胱急痛，宣腰胯冷脓，消宿食下气。  \n\n【元素】破血润燥。 \n\n【东垣】专治大肠气滞，燥湿不通。\n\n【宗奭】研和龙脑点赤眼。  \n\n【禁忌】性专下降，善导大肠燥结，利周身水气，然下后多令人津液亏损，燥结愈甚，乃治标救急之药，非可常用，津液不足者忌用之。  ', NULL, NULL, NULL, '郁李仁', NULL, '318、郁李仁  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115308, '17E7052D2AACA1CF5FF406AB4009A901', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7998, 438, 902000863, '\n【本经原文】味苦，寒，有小毒。治温疾，伤寒，大热，烦狂，杀三虫，疥，疡，利小便水道。生山谷。今名金铃子。又名川楝子。苦楝子。  \n\n【性味】金铃子味苦，性微寒，其皮味苦，性微寒，有小毒。 \n\n【主治】为解热，利尿，镇痛要药，治妇女白带，疝气及心腹诸痛症。苦楝皮杀虫治疥癣，亦可为蔬菜杀虫药。  \n\n【别录】苦楝皮治疣虫，利大小肠。  \n\n【东垣】入心及小肠，止上下腹痛。  \n\n【括要】泻膀胱，治诸疝虫痔，能入肝舒筋，导小肠，膀胱之热，为疝气要药。\n\n【用量】一般一钱至三钱。  \n\n【禁忌】胃虚寒者禁之。', NULL, NULL, NULL, '楝实,金铃子,川楝子,苦楝子', NULL, '317、楝实,金铃子,川楝子,苦楝子 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115309, '1F8A3AC93E430325EC001C9D65597768', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7999, 438, 902000862, '\n【本经原文】味苦，寒，无毒。治风水，黄疸，面热黑。叶，治马疥，痂疮。实，主溃痈，逐脓血。生川泽。一名柳絮。  \n\n【产地】江南一带，生湖畔河堤处。  \n\n【性味】柳絮，柳枝，柳叶，柳根皆味苦，性寒。  \n\n【主治】柳絮为祛湿，解热，止痛药，治黄疸，湿痹,金疮及脚气。柳叶可疗疥，洗漆疮，解热毒，止痛。柳枝及根白皮能解热，止痛，消肿。  \n\n【别录】主痂疥，恶疮，金疮，实主溃脓，逐脓血，子汁疗渴。  \n\n【甄权】主止血，治湿痹，四肢挛急膝痛。 \n\n【日华】煎膏续筋骨长肉止痛，主服金石人大发热闷，汤火疮毒入腹闷热，及疔毒。  \n\n【苏敬】柳枝与根主治痰热淋疾，可为浴汤，洗风肿疮疡，煮酒漱齿痛。\n\n【时珍】煎服治黄疸，白浊，酒煮熨诸肿痛，去风，止痛，消肿。  \n\n【附方】 金疮出血——柳絮封之即止。 脚多汗湿——柳絮着鞋袜内穿之。 眉毛脱落——柳叶阴干为末，以姜汁在铁器内调膏，夜夜抹之。 黄疸初起——柳枝煮浓汁半升，顿服。 乳痈妒乳——初起坚紫，众疗不愈，柳根皮熟捣，火温棉裹慰之，冷更易，一宿消。  \n\n【用量】一般一钱至三钱。\n\n【禁忌】寒症忌用。  ', NULL, NULL, NULL, '柳花,柳絮', NULL, '316、柳花,柳絮  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115310, '61EEF10F831346A21C443BE08273FED2', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8000, 438, 902000861, '\n【本经原文】味辛，咸，温，有小毒。治风痹，死肌，邪气，风头，泪出，利九窍，杀精物。生川谷。 \n\n【产地】皂树处处有之，结实名皂荚，以肥而多脂为良，其刺亦可入药。 \n\n【性味】味辛咸，性温，有小毒。 \n\n【主治】皂荚为通窍搜风拔毒杀虫要药，主风痹死肌，消痰涎，破坚症，治肠痈腹痛，溃散疮疡。 \n\n【别录】疗腹胀满，消谷，除咳嗽，囊结，妇人胞不落，明目益精，可为沐药不入汤。 \n\n【甄权】破坚症腹中痛，能堕胎，又将浸酒中取尽其精，煎成膏涂帛，贴一切肿痛。  \n【大明】通关节，头风，消痰杀虫，治骨蒸，开胃，中风口噤。  \n\n【宗奭】溽暑久雨时，合苍术烧烟辟瘟疫邪湿气。  \n\n【汪机】烧烟熏久痢脱肛。\n\n【用量】普通一钱至三钱。  \n\n【禁忌】药性颇峻，中病即止，凡由阴虚火炎，煎熬成痰，热极生风，至卒然仆蹶，不可遽用稀涎，耗其津液，致经络无以营养，为拘挛偏废之病，孕妇亦忌，畏空青人参苦参，伏丹砂粉霜硫黄磠砂。  \n\n皂角刺——即皂树刺，味辛性温，无毒，主通关窍，消痈疽，搜风，杀虫，治风疠，腹内生疮，妇人妒乳，胎衣不下。功同皂荚而力更锋锐，能直达病所，通风涎咽喉阻塞、治痈疽未 溃均妙，痈疽已溃者、气虚者与孕妇均禁用。  ', NULL, NULL, NULL, '皂荚', NULL, '315、皂荚  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634627000115311, '33AB01DCA588DBEBA0349E910F1B8814', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:43:55', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8001, 439, 902001028, ' ——治吐血，下血，胃家损伤之重症者。今人称伏龙肝。  \n\n【产地】乡下土灶烧之多年者佳，新土无效。 \n\n【性味】味甘性温平，功能补土利湿，修补胃壁之损伤。 \n\n【主治】胃出血，呕吐血，大便黑等。 \n\n【仲景】黄土汤用之，治疗便血吐血等。 \n\n【用量】一般三钱至五钱。 \n\n【禁忌】无。  ', NULL, NULL, NULL, '伏龙肝', NULL, '28、灶心土  ,伏龙肝', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443141, '3F9D65A7E60298CF431BB5863A0343CD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8002, 439, 902001027, ' ——养心除烦，利溲止血。  \n\n【产地】处处有之，北方者为良。 \n\n【性味】味甘，性平，微寒，无毒。 \n\n【主治】小麦主除客热，养心气，为服食滋养之品。 \n\n【别录】主除客热，止烦渴咽燥，利小便，养肝气，止漏血唾血，令女子易孕。  \n\n【思邈】养心气，心病宜食之。\n\n【宗奭】煎汤饮治暴淋。  \n\n【素问】麦属火，心之谷也。  \n\n【圣惠方】小麦饭治疗烦热少睡多渴。  \n\n【用量】普通二至三钱。 \n\n【禁忌】脾虚作胀者，不甚相宜，入药，宜完用，皮肉不可分拆，拆则性温，明面不能消热止烦也。  \n\n【附录】 浮小麦——麦之性轻，入水浮起者，味咸性寒无毒，主益气除烦。治盗汗自汗，骨蒸虚热，妇人劳热。 麦苗——味辛性寒，主消酒毒，暴热，酒疸目黄，并捣汁日饮。  ', NULL, NULL, NULL, '小麦', NULL, '27、小麦 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443142, 'D942432EF73344F647104ED076FBE644', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8003, 439, 902001026, '\n——辛能散气，甘调中，温开胃，化水谷，消积滞。  \n\n【产地】处处有之，乃以青篙苍耳野蓼自然汁杏仁泥赤小豆未和白面，如造酱法酿制者，药铺多于伏日为之。  \n\n【性味】味甘，性温，无毒。  \n\n【主治】神曲为消食化痰要药，主化水谷宿食，行气调中，健脾开胃，治症结胀满，泄泻痢疾。  \n\n【本草】痰逆症结，泻利胀满：回乳下胎，治目病。  \n\n【药性】主化水谷宿食症结积滞，健脾暖胃。  \n\n【元素】养胃气，治赤白痢。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】脾阴虚胃火盛者忌之，虚胀者亦不宜，又能落胎，孕妇宜少食。 ', NULL, NULL, NULL, '神曲', NULL, '26、神曲  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443143, 'D8E14998DF1372D1DDAD6DDC73C0A7EF', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8004, 439, 902001025, '\n——长于降气，下痰止嗽，治肺气壅实，胸膈逆满。  \n【产地】山野多年生草，根死似细辛而大。白色，坚直易折，嘉谟曰，似牛膝短小柔软，能弯者为白微，长坚易折者为白前。  \n\n【性味】辛苦味甘，性微温，无毒。 \n\n【主治】白前为下气降痰要药，主治咳逆上气，肺病痰喘。  \n\n【别录】主胸胁逆气，咳嗽上气，呼吸欲绝。  \n\n【大明】主一切气，肺气烦闷，贲豚肾气。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】肺虚哽气者忌。  \n\n【吴克潜】白前能祛痰而利肺气，寇氏称其能保定肺气，治嗽多用。以温药相左尤佳，而时 珍谓其性无补益，虽寇氏称其能保肺气，但其功能专于降气，气降故痰亦下，故惟肺气壅实，兼有痰凝塞者，用之无不奏效，若虚者则不宜，之二说者，可并存也，盖惟其泻肺不补，而痰乃能降，气乃能平，惟其祛痰降气，而肺乃得保，气乃得安，正可以互相发明也。 ', NULL, NULL, NULL, '白前', NULL, '25、白前  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443144, '7B7E1E62A983838968E9BA594B818A0F', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8005, 439, 902001024, ' ——调中助阳，散血生肌，泄下焦太肠气滞。  \n\n【产地】处处有之，叶似韭而阔，多白而无实，入药去青留白。 \n\n【性味】味辛苦，性温，无毒。 \n\n【主治】薤白为滑利散结要药，主胸痹剌痛，泄痢后重，温中助阳，下气散血，除寒热，治带下。 \n\n【本经】主金疮，疮败。 \n\n【别录】归骨，除寒热，去水气，温中散结气，作羹食利病人，诸疮中风寒水气肿痛，捣涂之。  \n\n 【日华】煮食耐寒，调中补不足，止久痢冷泻。 \n\n【东垣】治泄痢下重，能泄下焦阳明气滞。 \n\n【思邈】心病宜食之，利产妇。 \n\n【孟铣】治女人带下赤白，作羹食之，骨哽在咽不去者，食之即下。 \n\n【苏敬】白者补益，赤者疗金疮及风，生肌肉。 \n\n【宗奭】与蜜同捣，涂汤火伤甚速。 \n\n【药征】主治心胸痛而喘息咳唾也，旁治背痛，心中痞。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】发热病不宜多食，不可与牛肉同食，令人作症瘕。  ', NULL, NULL, NULL, '薤白', NULL, '24、薤白  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443145, 'C34D3226224252995BF9DA7693EAFC37', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8006, 439, 902001023, ' ——主止血行血。  \n\n【产地】即大红帽之纬也。 \n\n【性味】烧炙后用，味苦辛。 \n\n【主治】主要用于止血行血。 \n\n【用量】一般五分至一钱。 \n\n【禁忌】忌与活血化血之药同用。  ', NULL, NULL, NULL, '新绛', NULL, '23、新绛  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443146, '2F4E2C49A8193713F2654AAE4101B889', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8007, 439, 902001022, '\n【产地】木通古名通草，多自生山野，庭园亦可栽植，各省有之，茎入药。 \n\n【性味】味辛苦（或作辛甘）性平，无毒。 \n\n【主治】木通为导湿热，利小便要药，主降心火，清肺热，化津液，止大渴，治淋沥，水肿。  \n【别录】疗脾疽常欲眠，心烦哕，出音声，治耳聋，散痈肿诸结不消，及金疮恶疮，鼠瘘踒折，齆鼻息肉，堕胎。 \n\n【甄权】治五淋，利小便，开关格，治人多唾，主水肿浮大。 \n\n【孟铣】利诸经脉寒热不通之气。 \n\n【士良】理风热小便数急痛，小腹虚满，宜煎汤并葱饮有效。 \n\n【大明】安心除烦，止渴退热，明耳目，治鼻塞。通小肠下水，破积聚血块，排脓，治疮疖，止痛推生下胞，女人血闭，月候不匀，天行时疾，头痛目眩；羸劣，乳结，下乳。 \n\n【藏器】利大小便，令人心宽下气。 \n\n【李珣】主诸痿疮，喉痹咽痛，浓煎含咽。 \n\n【冬垣】通经利窍，导小肠火。 \n\n【用量】普通七分至二钱。 \n\n【禁忌】凡精滑不梦自遗，及阳虚气弱，内无湿热者忌，孕妇禁用', NULL, NULL, NULL, '木通', NULL, '22、木通  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443147, '0DADDDB01EA2B56974BEE5ADFFCF62BA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8008, 439, 902001021, '\n【产地】产四川广东及台湾琉球等地，为多年生之宿根草，根茎似芋，内暗褐色或黄色，其香能及远。 \n\n【性味】味辛苦，性寒，无毒。 \n\n【主治】郁金为凉血破瘀要药，功能开血中之郁，泄血中之热，治吐血。溺血，恶血留积，失心癫狂。 \n\n【唐本】主血积下气，生肌止血，破恶血，血淋，尿血，金疮。 \n\n【甄权】单用治女人宿血气心痛，冷气结聚，温醋摩傅之，亦治马胀。 \n\n【丹溪】治吐衄，妇人倒经，痘毒入心。 \n\n【元素】凉心。 \n\n【东垣】治阳毒入胃，下血频痛。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡病属真阴虚极，阴分火炎，迫血妄行，溢出上窍，而非气分拂逆，肝气不平，以致伤肝吐血者，均忌。  ', NULL, NULL, NULL, '郁金', NULL, '21、郁金  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443148, '401A0711C25F32F17CAAB62E39C86EAD', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8009, 439, 902001020, '\n【产地】处处有之。  \n\n【性味】猪胆汁味苦性寒，无毒。 \n\n【主治】主清心明目，凉肝胆，治目赤目翳，小儿疳瘦，著名方剂有猪胆汁方。（用猪胆汁和醋少许，灌入谷道中，少顷大便出宿垢），治阳明热结于下，大便不通者。  \n\n【禁忌】寒实者禁忌。', NULL, NULL, NULL, '猪胆', NULL, '20、猪胆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443149, '9C1B36C8DB660B89D2FFECB982F93609', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8010, 439, 902001019, ' ——本经无记载。  \n\n【产地】处处有之。  \n\n【性味】味甘性平。  \n\n【主治】镇心安脏，益气补血。清咽开音，散热定惊。止嗽止痢，利产安胎。用醋煮食，治赤白久利。胎衣不下，吞卵黄二三枚，解发刺喉，令吐即下。取蛋壳，细研，调以麻油，擦痘毒神效。  \n\n【用量】一般一日二三枚。\n\n【禁忌】多食另人滞闷。  ', NULL, NULL, NULL, '鸡子黄 ', NULL, '19、鸡子黄  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443150, '96BA76AFE4886DE271E4AE13CEDF9528', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8011, 439, 902001018, ' ——本经无记载。  \n\n【产地】产我国湖广一带，山野自生，庭园亦可栽植，茎高二三尺，根作团块。 \n\n【性味】味甘，微苦，性温，无毒。 \n\n【主治】三七为散瘀定痛要药，功能散一切恶血，保一切新血，治血瘀成肿成痛，外敷能消肿止血。为云南白药之主药。 \n\n【日华】金鱼将死，入山漆叶（三七叶）汁于鱼口，即活，无名疮疖，捻叶敷之。  \n\n【倪注】举凡内外伤，诸烂疮，乳痈等都可以用，镇痛止血。\n\n【用量】普通钱半至三钱，大剂一两左右。 \n\n【禁忌】无。  ', NULL, NULL, NULL, '三七', NULL, '18、三七  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443151, '401DB2C6B2842E4F8421BF63F5FEA2AB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8012, 439, 902001017, ' ——本经无记载。  \n\n【性味】味咸性大寒。 \n\n【主治】为解热药，治消渴，奔豚气逆。 \n\n【别录】李根白皮治消渴，止心烦，逆奔豚气。 \n\n【孟铣】将之炙黄煎汤，日再饮之，治女人卒赤白带下。\n\n【甄权】治脚下气，主热毒烦躁，煮汁服止消渴 \n\n【用量】一般三钱至五钱。 \n\n【禁忌】津液不足者忌。  ', NULL, NULL, NULL, '甘李根白皮', NULL, '17、甘李根白皮  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443152, '88C93477A682AA9E22682FE36046AD13', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8013, 439, 902001016, ' ——粳：硬也，糯：懦也、补脾清肺。  \n\n【产地】我国东南诸省。粳乃稻米之总称，有早中晚三收，晚者得金气多，性凉，尤能清热。俗话：北粳凉，南粳温，白粳凉，红粳温，新米食之，动气。陈米佳，冲淡可以养胃。煮汁  \n\n煎汤，取其调胃，利小便，去湿热，除烦渴之功。 \n\n【性味】甘凉，得天地中和之气，色白入肺。 \n\n【主治】和胃补中，除烦清热，煮汁止渴。 \n\n【仲景】以清热补不足。 \n\n【张文潜】粥能畅胃气，生津液，每晨空腹食之，所补不细。与脏腑相宜者唯此最佳。 \n\n【用量】可以日常服用。 \n\n【禁忌】无禁忌。  ', NULL, NULL, NULL, '粳米', NULL, '16、粳米  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443153, 'BAE5B2EF9536CCB645292CF70B137BDE', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8014, 439, 902001015, ' ——行手足阳明，入手太阴而为阳明主药、故治头面诸疾。  \n\n【产地】处处有之，根有轮节或隆起，外面色淡黄褐，气味甚香。\n\n【性味】味辛，（或作甘）性温，无毒。色白入肺。  \n\n【主治】白芷为散风发表要药，功能通窍去湿，疗风行血，止头痛，和肠胃，烧之辟邪气。\n\n【别录】疗风邪，久渴，吐呕，两胁满，头眩目痒。 \n\n【甄权】能蚀脓，止心腹血刺痛，女人沥血腰痛血崩。 \n\n【大明】治目赤努肉，去面皯疵瘢，补胎瘘滑落，破宿血，补新血，乳痈，发背，一切痈疮 疥癣，止痛排脓。  \n\n【元素】解利手阳明头痛，中风寒热，及肺经风热，头面皮肤风痹燥痒。  \n\n【用量】普通五分至钱半。 \n\n【禁忌】呕吐由于火，瘘下赤白，阴虚火炽，病由血热所至者，均忌，恶旋覆花，制雄黄硫黄。  \n\n【吴克潜】白芷为肺胃大肠三经气分药，亦入三经血分，擅散风去湿之功，配白芷治偏正头风，齿痛，带下者，成方颇多。 ', NULL, NULL, NULL, '白芷', NULL, '15、白芷  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443154, 'ACF60623385DBAEFD6AF428901DCB284', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8015, 439, 902001014, '\n【产池】产西南热地及西藏等处，为树中流出之脂液，凝结成块者，入药。 \n\n【性味】味苦辛，性微温，无毒。 \n\n【主治】乳香为活血伸筋要药，主通行周身经络，去风散瘀，活血定痛，托疮毒，消痈疽。\n\n【别录】主风水毒肿，去恶气，伏尸，痈疹痒毒。 \n\n【之才】治不眠。 \n\n【大明】下气，益精，补腰膝，治肾气，止霍乱冲恶，中邪气心腹痛疰气，煎膏止痛长肉。\n\n 【元素】补肾，定诸经之痛。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】痈疽已溃，不宜服，诸疮脓多时，未宜遽用。', NULL, NULL, NULL, '乳香', NULL, '14、乳香  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443155, '356EAB5C72C3C12C8D60037648B0E3CA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8016, 439, 902001013, '\n【产地】产我国南部热地，为树中流出之脂液，凝结成塽者，入药。 \n\n【性味】味苦辛，性平，无毒。 \n\n【主治】没药为散血消肿定痛生肌要药，主破血止痛，治折伤瘀血，消肿毒。 \n\n【开宝】主破血止痛，疗金疮杖疮，诸恶疮，痔瘘，卒下血，目中翳晕痛肤赤。  \n\n 【李珣】堕胎，产后心腹血气痛，并入丸散服。 \n\n【大明】破症瘕宿血，损伤瘀血，消肿痛。 \n\n【好古】心胆虚，肝血不足。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】凡骨节痛，胸腹胁肋痛，非由血瘀而由血虚者，产后恶露去多，腹中虚痛者，痈疽已溃者，目赤肤翳非血热甚者均忌。 \n\n【吴克潜】打扑跌损，皆伤筋络，气血不行，瘀痈作痛，乳香没药，皆能止痛消肿生肌，故二药多相兼而用。  ', NULL, NULL, NULL, '没药', NULL, '13、没药  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443156, '634E0C846318FFC6B62F7301DCCAD1C5', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8017, 439, 902001012, '\n——现无资料可查（出于王不留行散中）。', NULL, NULL, NULL, '蒴翟细叶', NULL, '12、蒴翟细叶  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443157, 'A0751AF153697E8E189D47B68F095BFA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8018, 439, 902001011, '\n——（鸡矢白散）  \n【产地】处处有之。为鸡食砂岩后排出之大便中，色白者。\n\n【性味】味苦，性微寒，无毒。  \n\n【主治】主行水消积，治鼓胀，疗转筋入腹，破石淋，利二便，下气破血，治伤寒寒热中风贼风风痹白虎风，贴风痛头痛，止遗溺，灭瘢痕，小儿客忤惊啼，解金银毒，酒服疗乳妒乳 痈乳头破裂，外敷秃疮耳疮瘰疬。  \n\n【素问】治臌胀。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】酒服最佳。 ', NULL, NULL, NULL, '鸡矢白', NULL, '11、鸡矢白  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443158, '6F638CB7BEBF6A71A5615D8D5301F99A', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8019, 439, 902001010, '\n【产地】处处有之，为一般食物调味之用。 \n\n【性味】色黑味咸，无毒，形如心，色如肾，味咸入肾，故治火中之木，令水火相济。\n\n【主治】主治心中懊憹也，旁治心中结痛及心中满而烦也。 \n\n【倪注】经方中之栀子豆豉汤主治心中懊憹，一般多用于病愈后之失眠烦躁。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】多无禁忌。  ', NULL, NULL, NULL, '豉', NULL, '10、豆豉,香豉  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443159, '8F53941E8A8314D0F2ECEF07D811ADB7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8020, 439, 902001009, '\n【产地】处处有之，山野最宜种植，树高大可作木材，叶侧生者入药，名侧柏叶。  \n\n【甄权】治冷风历节疼痛，止尿血。 \n\n【大明】灸罯冻疮，烧取汁涂头，黑润鬓发。 \n\n【苏颂】傅汤火伤，止痛减瘢，服之疗蛊痢，作汤常服杀五脏虫，益人。  \n\n【禁忌】畏菊花诸石，忌面，得酒良，焙干用。 \n\n侧柏子壳——和鸡子清调服，解砒霜毒。 \n\n侧柏子枝节——治风痹，历节风，疗虫疥。 \n\n侧柏油——外用治诸癣痈毒，游丹秃疮，头面耳部黄水疮，杀虫虱。\n\n侧柏根皮——主凉血，生毛发，治火灼烂疮。 ', NULL, NULL, NULL, '柏叶,侧柏叶', NULL, '9、柏叶（侧柏叶）  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443160, 'E9B06C5F1FFDEA50012C4A1399E958B7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8021, 439, 902001008, ' ——补中益气。  \n\n【产地】处处有之，乃以米麦制成者。 \n\n【性味】味甘，性温，无毒。 \n\n【主治】饴糖为滋润肺脾，健胃补中要药，主补虚冷，益气力，治胃气枯燥，脾弱不运。 \n\n【别录】主补虚乏，止渴，去血。 \n\n【思邈】补虚冷，益气力，止肠鸣咽痛，治唾血，消痰，润肺止嗽。 \n\n【孟铣】健脾胃补中，治吐血，打损瘀血者熬焦酒服，能下恶血，又伤寒大毒嗽，于蔓青薤汁中煮一沸，顿服之良。 \n\n【宗奭】脾弱不思食人多用，能和胃气，亦用和药。  \n\n【禁忌】丹溪曰，饴属土，成于火，大发湿中之热，多食助脾风，能生胃火，此损齿之因，凡中满呕吐，酒病、牙疳，肾病及湿热证，不得轻投。  ', NULL, NULL, NULL, '饴糖', NULL, '8、饴糖 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443161, 'A3DF301E5659A846066F7CC718B1CBA6', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8022, 439, 902001007, '——本经无记载。  \n\n【产地】处处有之，为一年生之草本，叶之背面皆紫者佳，有香气。茎叶与子皆入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】紫苏为发表散寒解毒要药，功能降气化馾，发汗祛寒，主伤风寒热霍乱，肺气喘急，心腹胀满，安胎，妇人胎前宜之。 \n\n【别录】主下气，除寒热，其子尤良。 \n\n【孟铣】除寒热，治一切冷气。 \n\n【日华】补中益气，治心腹胀满，止霍乱转筋，开胃下食，止角气，通大小肠。 \n\n【苏颂】通心经，益脾胃。煮饮尤胜，与橘皮相宜。 \n\n【苏敬】下气消缓，虚者宜之，主安胎。 \n\n【用量】叶梗普通八分至二钱，苏子钱半至三钱。 \n\n【禁忌】凡阴虚因发寒热，或寒头痛者，宜敛宜补，不可用苏叶，火升作呕者亦忌，惟可用子，忌鲤鱼，同食发恶疮。 【容川】紫苏色红味辛香，能散血分肌肉中之寒，枝叶披离，故主散之性多，而主升之性少。苏子——主上气咳逆冷气，及腰脚中湿气，风结气，调中止霍乱，消五膈呕吐反胃，消痰止嗽，利大小便，治肺气喘急。   苏叶——主发散，盂铣曰苏子与苏叶同功，发散风气宜用叶，清利上下宜用子，近世多用以发散风寒，至化痰之力，则不如子也。主散气分之热，如喉为气之海。 苏梗——主顺气表散，汪昂曰，叶发汗散寒，梗顺气安胎，子开郁降气，消痰定喘。  ', NULL, NULL, NULL, '紫苏', NULL, '7、紫苏  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443162, '9E3DC67EF009C57E9788C7D03AFFAFCA', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8023, 439, 902001006, '——本经无记载。  \n\n【产地】生田野间，处处有之，陈久者良，有香味。 \n\n【性味】味苦，性征温，无毒。 \n\n【主治】艾叶为炙百病要药，并可作煎剂，主暖子宫，调经，止血，安胎。 \n\n【弘景】捣汁服止伤血，杀蚘虫。 \n\n【苏敬】主衄血下血脓血痢水，煮及丸散任用。 \n\n【甄权】止崩血肠痔，血搨金疮，止腹痛安胎，苦酒作煎治癣甚良，捣汁饮，冶心腹一切冷 气鬼气。 \n\n【大明】治带下，霍乱转筋，痢后寒热。 \n\n【好古】治带脉为病，腹胀满，腰溶溶如坐水中。 \n\n【容川】艾叶味苦而气温，其茸又能发火，是以能温肝补火，禀母木火之气，能入血室，女人经痛，乃凝血作痛，艾叶可去血室中之冷气也。补火之药是火能化水也，故能行血。 \n\n【用量】普通数分至钱半，炙用无定量。 \n\n【禁忌】妇女血热而月经超前者，宜慎用之。', NULL, NULL, NULL, '艾叶', NULL, '6、艾叶  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443163, 'A8294089ECAFAC3DD04257893469C4FB', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8024, 439, 902001005, '——本经无记载。  \n\n【产地】处处有之，以紧小者为良。  \n\n【性味】味辛（或作甘酸）性平，无毒。  \n\n【主治】赤小豆为行水散血，消肿解毒要药，主排痈肿脓血，水气肿账，治脚气，利小便，疗一切痈疽恶疮发背，内外可用。  \n\n【别录】疗寒热，热中消渴，止泄痢，利小便，下腹胀满，吐逆卒澼。  \n\n【甄权】治热毒，散恶血，除烦满，通气，健脾胃，令人美食，捣末同鸡子白涂一切热毒痈肿，煮汁洗小儿黄烂疮，不过三度。  \n\n【士良】缩气行风，坚筋骨，抽肌肉。  \n\n【孟铣】散气，去关节烦热，令人心孔开，暴痢后气满不能食者，煮食一顿即愈，和鲤鱼煮食，甚治脚气。  \n\n【日华】解小麦热毒，煮汁解酒毒，解衣粘缀。  \n\n【容川】赤小豆发芽，则能透达脓血。  \n\n【用量】普通钱半至三至四钱。  \n\n【禁忌】合鱼鲊食成消渴，作酱，同饭食成口疮，久服则降令太过，津血渗泄、令人肌瘦身重。  \n\n【容川】黏涩又味甘，能填补止泻利。  ', NULL, NULL, NULL, '赤小豆', NULL, '5、赤小豆  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443164, 'F2D66BBC4EC8D4AFE88DC3A5B0DC55D7', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8025, 439, 902001004, '——本经无记载。  \n\n【产地】生原野，处处有之，种类甚多，取大腹深灰色，空中作圆网者，入药。  \n\n【性味】味缺，性微寒，有小毒。 \n\n【主治】蜘蛛主口瘑，瘰疬，结核，治蜈蚣蜂虿螫伤，宜外用，内服治干霍乱呕吐，脱肛，小儿大腹疳。  \n\n【别录】小儿大腹丁奚，三年不能行者。  \n\n【弘景】蜈蚣蜂虿螫人，取置咬处吸其毒。  \n\n【苏敬】主蛇毒，温疟，止呕逆霍乱。  \n\n【苏颂】取汁涂蛇伤，烧啖治小儿腹疳。  \n\n【日华】斑者治疟疾疔肿。  \n\n【用量】普通一至二钱。  \n\n【禁忌】有毒之物，可外用，少内服。凡使，去头足用，落在饮食中者不可食，畏蔓青雄黄，被蜘蛛咬中毒者，（一）用大篮汁一碗，入雄黄麝香少许，搽患处，仍服其汁。（二）用艾叶烧烟熏之。（三）羊乳灌之。（四）雄黄末敷之。  ', NULL, NULL, NULL, '蜘蛛', NULL, '4、蜘蛛  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443165, '988AA279AC1476E1AD173D6012B43B41', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8026, 439, 902001003, ' ——本经无记载。  \n\n【产地】产我国北地，今处处有之，园圃亦可栽植，为两年生之草本植物，花开色红，故名。\n\n【性味】味辛，性温，无毒。 \n\n【主治】红花为活血行瘀要药，主暴吐紫血，（紫则有瘀），产后血晕，痘疮血热有毒，（血行则毒解），治月经不调，腹中结块。  \n\n【开宝】主产后血运口噤，腹内恶血不尽，绞痛，胎死腹中，并酒煮服，亦主蛊毒。  \n\n【丹溪】多用破血，少用养血。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】忌沉香麝香，能使红花变色，可下死胎，孕妇忌用，过用红花，能使血行不止而毙。  \n\n【容川】色赤自入血分，味苦专能泄血，而花性专主轻扬，上行外走，故能泄肌肤脉络在外在上之血，有谚云：治风先治血，血行风自灭，血足则肝阳不动，而风自熄。观仲景之红蓝花酒，治风气百疾，则知治风先治血的道理。色红能生血，而味苦，又能泻血。  \n\n番红花——红花之产于新疆者，味甘性平无毒，主活血开郁，治心忧气闷，惊悸，伤寒发狂今多用为开胃行经之品。  \n\n藏红花——红花之产于西藏者，性味同红花，以入滚水内色如血，可冲四次不变色者为真，主活血通经治吐血（各种痞结冲汤服，忌食油荤盐），功用最良。 \n\n土红花——红花之产于福建者，根叶入药，味甘，性微寒，无毒，（或作有毒）治劳热瘴疟，骨节疼痛。  ', NULL, NULL, NULL, '红花', NULL, '3、红花  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443166, '0D8A7E7B4D122DB301C4E90E202AE431', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8027, 439, 902001002, '\n【产地】产我国广东等地，其实六棱，又名诃黎勒。 \n\n【性味】味苦酸涩，性温，无毒。 \n\n【主治】诃子为涩肠治痢，保肺调气要药，主胸膈结气，心腹胀满，消痰，化食，通津，开胃，治心腹虚痛，肠风下血，崩带，胎漏，久痢，虚嗽。  \n\n 【唐本】主冷气。 \n\n【甄权】破胸膈结气，通利津液，止水道，黑髭发。  \n\n 【大明】消痰下气，化食开胃，除烦治水，调中止呕吐，霍乱心腹虚痛，奔豚肾气，肺气喘 息，五膈气，肠风泻血，崩中带下，怀孕漏胎，及动胎欲生，胀闷气喘，痢人肛门急痛，产妇阴痛，和蜡烧烟熏之及煎汤熏洗。 \n\n【萧柄】下宿物，止肠澼久泄赤白痢。 \n\n【苏敬】治痰嗽咽喉不利，合三数枚殊胜。 \n\n【丹溪】实大肠，敛肺降火。 \n\n【用量】普通一至二钱。 \n\n【禁忌】气虚宜缓缓少用，以此虽涩肠，而又泄气也，凡咳嗽痢疾初起者，均忌。  ', NULL, NULL, NULL, '诃黎勒', NULL, '2、诃黎勒（诃子）  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443167, 'E454CBB92DF7AC9574D87F309AFE044C', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8028, 439, 902001001, ' ——即戎盐，补肾，泻血热。  \n\n【产地】产于我国内陆青海之盐。 \n\n【性味】甘咸而寒。入肾经。 \n\n【主治】助水脏，平血热，坚骨固齿，明目乌发。 \n\n【别录】治目痛赤涩，吐血溺血，齿舌出血。 \n\n【炮制】不假煎炼，方棱，明莹，色青者良， \n\n【用量】普通五分至一钱。 \n\n【禁忌】多食伤肺，走血，渗津，发渴。凡血病，哮喘，水肿，消渴人为大忌。  ', NULL, NULL, NULL, '青盐', NULL, '1、青盐  ,戎盐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 634636941443168, 'E59F6EFADFDF3CAD10470A0A9E894BA9', NULL, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 17:24:22', 1, 'admin', '2025-01-17 17:24:21');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8029, 440, 905001001, NULL, NULL, NULL, NULL, NULL, NULL, '        金匮是延续伤寒论而来的，属于杂病范畴之内，每个章节讨论不同的病，但是其辨证的基础还是以伤寒论为主，本次伤寒与金匮的解说与书籍的撰写，我采用许多过去历代的经方大师如江阴曹颖甫撰写的《伤寒发微》与《金匮发微》，四川唐容川撰写的《中西汇通医书五种》，陆九芝、傅青主、戴天章著，秦伯未、林直清校定《世补齐医书全集》，江忍庵增批，林直清勘的《徐灵胎医书全集》等等，经方也因为这些历代名家的研究与发扬，才能流传至今，这些名家也因此而流芳百世。 \n\n        每当想起唐朝名医孙思邈时，我就会发出会心的一笑，因为他是先写出《千金要方》一书，当时他以为这将是经典之作，数年之后他看到了汉朝张仲景所写的《伤寒杂病论》，大为惊讶于经方，于是将《千金要方》做了许多修正，也就是后来的《千金翼方》，足证历代名医都将经方视为唯一的最高指导原则，也就是说不知道使用经方的中医，是不配被称为中医的，更不配被称为名家或是国手，所以要发扬中医学，就必须发扬经方，唯经方才是真正能够代表我国的正统医学。 \n\n       经方的辨症论治法，不但极其科学，治疗效果迅速，好处比西方医学不知超过多少，比方说西方医学制造出许多吓人的病名，许多病人一听到自己得到某种病后，当时就已然吓傻了，心慌焦虑随之而来，完全失去斗志，任由西医药与病魔的宰割，使得绝大多数的病人是因为西医药的过度治疗与心理的惊吓而死亡的，并不是因为病而死的。\n\n        反观中医学的辨症法，中医学不立病名，是因为立病名，会让疾病的定义变为更狭隘，符合于老子所谓的名可名非常名，中医学讲究同症同治，就是不受到病名的限制，立下病名对于病情非但是于事无补，有时病名立得过多，连西医自己都搅乱掉了，而西医认为不立病名是无法说服众人的，于是各种奇怪的病名充斥，试问西医师，那种病是被你们治好的呢，答案是没有一个病被他们真正的治好。而经方依据的辨症法则，只要医师使用得当，就可以很迅速的让病人恢复过来，无论医师是面对何种西医所谓的病，只要症状一样就可以使用同方来治疗，当病人只知道自己的症状，不知道自己的病名时，病人必然无惧于任何症状，在一开始与疾病作战时，病人的这种心理就已经胜利了，加上由训练精良的医师来施治，怎会治不好呢？ 现在临床上遇到最大的问题，就是病人被西医制造的病名先吓住后，中医再动手治疗，也就是说中医尚未开始治病时，就已经先输一着，治疗上就倍增困难，中药什么药都有，就是没有大胆丸，心理上的恐惧却往往是病人的致命伤所在，时常是无知胜于有知，这里的有知，指的是半个有知，如果是全有知，当然最好，但是病人怎么可能都是全知呢？ \n\n        这次的人纪教学，将在金匮讲授完毕后全部结束，而我的临床经验医案传承，将利用地纪来撰写，所有地纪中提出应用的处方都来自经方，所以我暂时不再另外写一本专门介绍我实际临床案例的书籍，可能以后有变化也不一定，但是目前尚无此打算，就请大家拭目以待地纪著作的完成。 \n\n                漢唐中醫 漢唐中醫 倪海厦 倪海厦\n                谨记于 05/20/2007 佛罗里达州自家书房', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648687262867525, '6D93656000A52C2AB260930056A1802F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 10:15:16', 1, 'admin', '2025-02-28 09:06:23');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8030, 441, 905002010, '       这是说按照前面所说的用$f{四逆汤}后吐利停了，再服用$f{桂枝汤}发汗后，病人的脉已正常了，本来应该就好了，但是出现吃饭后肠胃好像\n不消化的现象时，这是因为病体刚才恢复过来，肠胃之气尚虚故也，稍事休息一阵，就会自己好的，这是不需要处方治疗的。', NULL, NULL, NULL, NULL, NULL, '10、利发汗小烦者，以新虚不胜谷气故也 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961698373, 'F2EB94136A3C3C02A7059E7A3008D2E2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8031, 441, 905002009, '        遇到吐到已经无可吐，下利到已经无可利的阶段时，病人必虚汗出不止，因为里阴已极虚，无法固阳，因而仅存之阳外出，故可见汗出，此时四肢已经无阴可以滋润，又无阳可以伸屈，所以四肢会拘急不解，脉当是微细欲绝，这是通脉四逆汤加猪胆汁汤证。', NULL, '通脉四逆加猪胆汁汤', NULL, NULL, NULL, '9、吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，$f{通脉四逆加猪胆汁汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961698374, 'ACF8F48E7D1BC3E8B944CC23FD15D5AC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8032, 441, 905002008, '       里阳不守而上浮，就会呕吐而且汗出。阴寒内结，就会下利而恶寒。这是水气盛血衰之症，于是造成四肢拘急而且冰冷的现象，这是$f{四逆汤}证。\n\n     病家又吐又下利，照理说应该津液已经失去，然而小便还有，又出大汗，甚至于还下利出未消化的食物，这是里真寒、外假热的症状，其脉微小欲绝之象，此为脉症相合，易治之症，是标准的$f{四逆汤}证。', NULL, '四逆汤', NULL, NULL, NULL, '8、吐利汗出 发热恶寒， 四肢拘急， 手足厥冷者，$f{四逆汤}主之。既吐且利，小便复利，而大汗出，下利清谷，内寒外热，，脉微欲绝者$f{四逆汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961698375, 'CC8173957F1BA4C8613A1AC14AC84ABF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8033, 441, 905002007, '      这里是说里症之吐利好了以后，如果病家还有身痛等表症时，我们就该帮他解表，解表用桂枝汤就可以了。', NULL, '桂枝汤', NULL, NULL, NULL, '7、吐利止而身痛不休者当消息和解其外，宜$f{桂枝汤}小和之。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961698376, 'D7600A37B470E41B698D6D9DD5879CE4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8034, 441, 905002006, '      病人霍乱吐利不止时，出现头痛、发热、身体疼痛、病家多热又欲饮水者，给予五苓散。如果是寒多而不饮水者，表示里寒湿重，此时给予理中丸服。 \n\n     伤寒治则是当有表症时，必先解表，而今有伤寒症但兼具吐利时，就不可解表。五苓散之功在能将表之寒水引回体内，再自小便排出，使得新水能取代旧水，故能止渴。理中丸能去里寒湿同时补足肠胃的津液，是治疗肠胃寒湿之主要处方。', NULL, '五苓散,理中丸', NULL, NULL, NULL, '6、霍乱头痛，发热，身疼痛，热多欲饮水者，$f{五苓散}主之，寒多不用水者，$f{理中丸}主之 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961698377, '708AD0C695754BD7FBB4131AE544A8DE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8035, 441, 905002005, '      如果下利停止，病人又出现恶寒脉微小无力，之后又开始下利时，就表示病人血寒了，此时救逆的处方就是四逆加人参汤了。\n\n      四逆汤是温阳救逆第一方，功能起死回生，多使用于心脏衰竭之危症时。此处之失血，并不是真的贫血，而是血寒，所以不用当归、川芎、白芍之类的补血药物。', NULL, '四逆加人参汤', NULL, NULL, NULL, '5、利止，恶寒脉微，而复利，亡血也，$f{四逆加人参汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961702469, 'B7A965C915DF8813660E38C26BD032B8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8036, 441, 905002004, '      下利之症如转热后，大便必硬。如果大便硬而胃口好，这是回到阳明证，表示自己会痊愈的，不需要治。\n\n     但是如果病人没有胃口，就要等十三日，之后病人能开始吃食物以后就会好了。如果没好，就表示病不在少阳与阳明，可能已经入里了。', NULL, NULL, NULL, NULL, NULL, '4、下利后，当便鞭，鞭则能食者愈。今反不能食，到后经中颇能食，复过一经能食，过之一日当愈。不愈者，不属阳明也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961702470, '6766B978EA8B74A5689A953E341154CC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8037, 441, 905002003, '       伤寒之症如脉微涩者，这是$f{四逆汤}证，病家是因为心阳不振，导致寒水不能气化造成血寒于体内，病原是来自霍乱，而今有伤寒之症，因此用麻黄汤之类无法治好，失治后三周左右，病由阳入太阴，就会下利，此时还有上热未去，无法给予热药，故不可施治。\n\n       等到阳热自回后，大便转燥而利止，即排出矢气，这时就是阳明证，其便必硬，二周内会好，这是因为阳明经尽止于二周。', NULL, NULL, NULL, NULL, NULL, '3、伤寒，其脉微涩者，本是霍乱，今是伤寒，，却四五日至阴经，阳转入阴，必利，本呕下利者，不可治也。欲似大便而反失气，仍不利者，此属阳明也，便必鞭，十三日愈。所以然者， 经尽故也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961702471, 'A735EAB714A7D87D111396EEBA78A29B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8038, 441, 905002002, '       这段的目的是要后学者能区分出太阳伤寒与霍乱是不同的，如果出现$m{表里并病}时，应$m{先治里症}，然后$n{再解表症}。像发热、头痛、身疼、恶寒这些是太阳伤寒无疑，而现在兼有呕吐与下利，这是$m{表里皆病}的现象，这也可以称之为『霍乱』。\n\n        遇到这种情形时，要先治霍乱之吐下症，等到吐利好了，如果出现发热等太阳证时，再去治表。', NULL, NULL, NULL, NULL, NULL, '2、问曰：病发热，头痛，，恶寒，吐利者，此属何病\n\n     答曰：此名霍乱霍乱自吐下，又利止复更发热也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961702472, 'A94A86D92995E19DC9C65CCA38DCE2B1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8039, 441, 905002001, '        霍乱之名始见于《汉书·严助传》，其言夏月暑时呕泄霍乱之病相随属者是也。\n\n       此病南方为患，北方罕见，盖因地气之湿，遇天之阳气外张，互相蒸之，逼人汗泄太过，导致血热而燥渴，于是在饱食之后又食冷物，于是湿热不得外出，宿食不化，浊气上升故吐，清气下降故泄，肠胃不适，因而吐泄不止，由此可知霍乱之名，就是指吐泄不止之证也。', NULL, NULL, NULL, NULL, NULL, '1、问曰：病有霍乱者何？\n\n     答曰：呕吐而利 是名霍乱。  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648751961702473, 'FE41C681631581181E0C13AEF9078913', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:38:31', 1, 'admin', '2025-02-28 09:24:46');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8043, 442, 905003001, '        从这段可知治肝有三个重点，补用$n{酸}，助用$n{焦苦}，益用$n{甘味}。所以治疗肝病经方中就有三个方子。补它的时候用酸，如乌梅丸。助的时候用焦苦，像吴茱萸汤。吴茱萸性燥，是很焦苦的药，它能够止呕。如果是『甘味之药调之』像小建中汤之类。这是治疗肝虚的时候用的三个法则，肝实的时候就不能用。\n\n        肝实在伤寒论介绍厥阴篇的时候，病人出现下利，有时呕吐就是肝实热发炎，就是肝肿起来，肝实热里面发炎的东西『热』往外走，进入大肠，拉出来都便浓血，又臭，伤寒里面就出方了，它叫『白头翁汤证』，白头翁可以止痢，可以止腹痛。白头翁加黄柏、秦皮，还有黄连，都是寒凉的药，后面陆续会跟大家介绍。\n\n      实热症的话用凉药，虚症用刚刚讲的三个方剂。所以我们治疗肝病，不管他是西医讲的名词肝硬化或肝癌，基本上我们处方的时候就在这几种方子里，这是张仲景以肝来举例子。『无实实，无虚虚，补不足，损有余。是其义也。余藏准此。』依此类推。\n\n     诸位要了解所谓：上工治未病，这个就是张仲景的原意。比如说肝出现问题时，我们应该先去实脾，这是最基本的法则。就是我们不让肝病继续传入脾脏，也就是把病局限在肝里面，不让它再传经，这是张仲景一个来自内经的观念，就是上工治未病，我们中医的最高阶段就是上工治未病，而西医是治已病。就好像一对夫妻要准备离婚了，到律师事务所去签字时，此时就是叫做『病已沉』。其实在离婚之前就已经有很多症状，显示如果继续恶化下去必将面临离婚，有症状的时候律师（西医）不会出面，中医会出面。「有症状了！」所以我们就开始动手。所以中医是辨症论治，这叫做上工治未病，如果要等到生病后才开始治疗就太慢了！内经的经义比西医学更广，西医学只限于局部在脏腑里面。\n\n      但是像『小建中汤为治肝补脾不二法门』这不是法则，误用之则大误病情矣。小建中汤只是用它的甘味来调脾胃，并不是用小建中汤来治肝病，因为『盖肝知本味酸，而中含有胆液则苦『胃实为生血之原』我介绍伤寒论时有提到，血的来源是脾胃。当我们肠胃吸收了食物以后『肝胆之液，渗入胃』，胃里面有三样东西：肝的酸、胆的苦、还有脾脏的甜与胰脏的黏液。如果太冷了，我们肝受到寒后，就会吐酸，所以呕酸的时候我们用燥来止呕。病人会呕酸就是肝液外出，我们用吴茱萸汤来治疗。如果肝热则吐胆汁，热则吐苦味。「老师，为什么我早上起来嘴巴苦苦的？」这就是胆汁上逆，是小柴胡汤证，诸位现在很熟稔了。\n\n      如果苦味很严重时，小柴胡汤里面黄芩就要重用、半夏也要重用、半夏能够降逆止呕，就是说胆汁往上逆时，我们需要用半夏把它往下降下去，所以小柴胡汤能和胃气。\n\n    『湿胜则肝胆不调』中医最难让人家去了解的，就是『气』，实际上什么叫气？西医看不到气，只看到一个循环系统，不管是我们的淋巴腺循环系统或者是血液循环系统，西医看不到是气在推动这个循环系统，它的原动力就是中医讲的气。\n\n      肝胆的气不够好，就是肝胆的原动力量不够了。肝本身是我们身上最大解毒的脏，西医医学里面也是这样讲，我们吃进很多东西，如果肝功能不是很正常时，代谢系统就不会很好，结果解毒的功能就不能完全发挥出来。\n\n      中医的观念，这种状况就叫做『郁』，气郁在肝里面，肝没有办法蠕动。正常时我们身体会把全身的血液，与身上残余的毒素，通通带回肝里面，然后经过肝脏解毒过以后再释放出来，进入我们的心脏。肝气郁久了以后，会造成食物残毒停留在这里，囤积久了就会生出湿。生湿出来后病人就容易有恶心。其实胃本身没有问题，而是肝藏湿气郁结积聚于此，压迫到胃，所以会恶心，自然就吐了很多湿液出来。有的时候早上起来刷牙时，会有恶心，就是因为里湿太盛造成的。\n\n       所以一般病人只要有呕，大部分都是有湿在里面。诸位看『湿胜则肝胆不调，故多呕。』湿囤积在身体里面太久以后，我们身体的环境就改变了，非常容易生虫，不要说是我们吃进\n去食物里面有菜虫，不用吃到菜虫，只要猪肉丢在那边，也会生虫的，只因为湿太盛了。所以如果我们肠胃消化不好时，食物在我们身体里面就会停留过久，坏掉的食物也会生虫的。补肝用酸，助用焦苦，此时可用乌梅丸。\n\n      中医有苦的药，像黄连、黄芩等，而苦的药都是寒凉的药，主泄、主向下走。只有乌梅丸，张仲景出了这个处方，他用的方法不是苦寒，而是利用苦温。因为温能化湿，只有温才能把湿化掉，所以乌梅丸里面有『以乌梅之酸，细辛、干姜、蜀椒、桂枝、附子之温，及黄连、黄柏之苦燥，而后胃温湿化，肝胆之郁，方得条达。』\n\n      胃受到温药以后湿被排掉了，这个时候湿被排出来，于是整个虫的生态环境就被改变掉了，虫才会出来，于是肝郁能够条达。中医的观念里面肝脏是木，树木要能开花，花要开的很好，才能够结果实，基本上它要能得到很多很新鲜的空气，它的生态环境要很好才行。乌梅丸就是能够让你身体里面那棵树长得很好，那棵树的名字叫肝，肝就是木。\n\n     中医的湿分为两种情形，一种是有蛔虫病，身体里面生有蛔虫，严重的时候就呕吐，因为里湿太盛于是吐出来很多虫，还有大虫、小虫之分，还有虫卵。还有一种就是久痢，无时无刻不在下利，很久都治不好，大部分这种下利是当我们到了有瘴疠的地方，比如说到了中国云贵高原这一带，或者是西南边陲一带，我碰过一个案例，一个美国人，他是作防卫系统的，美国在巴西有个基地，他就到南美洲去，在那个基地待了两年，他是设计外围警卫系统的工程师，那两年是什么都没得到，但是一回来就得到下利，我用所有能治下利的处方都治不好，这时就要靠乌梅丸。\n\n      台湾的乌梅丸不纯，因为乌梅必须要先蒸过，先把乌梅泡在醋里面泡一个晚上，让醋渗透进去，酸才能入肝，然后再用米饭来蒸它，蒸完以后再把乌梅里的核拿出来才能入药，小孩子平常没事时就可以吃乌梅丸，一般小孩子吃十五粒，大人大概吃二十五粒，有一种状况不能吃，就是下利便浓血时不要吃，其他通通可以吃，对肝病的人来说，乌梅丸可以专门用来补肝的。\n \n       张仲景已经告诉大家该怎么做，只是外面的乌梅丸不纯，所以我们只有靠自己来做，我们自己做的乌梅丸，你放在嘴巴里时是又酸又苦，因为黄连用了四两在里边，很苦，可是苦能驱虫，解毒驱虫的力量很强，里面的蜀椒就是杀虫的，这个是治肝胆湿热很好用的处方。\n\n        第二个就是吴茱萸汤，大家看『胃中虚寒，干呕，吐涎沫。』吐涎沫出来时，我们开吴茱萸汤，吴茱萸汤方就是吴茱萸加生姜还有人参、甘草。吴茱萸汤也是专门治疗胃下垂时用的处方。胃下垂在中医的观念里面，下垂就是功能不好了，中医叫做胃寒，为什么会寒？因为肝脏功能不好才引起胃寒，由于肝把胃压迫到，胃就没办法动，结果就是胃下垂了，很多长年喝酒的人，就会造成肝脏的负担，进一步就造成胃下垂，此时吴茱萸汤很好用。实际上吴茱萸就是入肝经的药。\n\n     此处不是用酸来补肝，这是寒湿初起之时，所以肝脏未虚，肝脏有虚的时候就要靠乌梅丸，肝脏虚掉的人体内较易生虫，而且会有长久的下利。如果肝没有虚，就只需要助胃阳而止呕，这时就用吴茱萸汤。吴茱萸的性很热很燥，如果要用甘味来调肝，就是专指建中汤而言，以上的三个方法，就是乌梅丸证，小建中汤证，还有吴茱萸汤证，这些都是治肝于未病时用的。\n\n      肝实热的话会有下利后重，所谓下利后重，就是上完厕所之后还是想再上一次，肛门感觉很灼热，大便出来很腥臭，有下利未尽的感觉，就是所谓白头翁汤证，这就跟我们这里说的又不一样了。\n\n    『若不问虚实而概用建中汤以治肝补脾不病胀懑即病烦躁。』所以我们要分出很多不同的状况，不仅仅是说肝病发出来后，我们赶快就用小建中汤去实脾，现在外面的中医就是这样做的，结果造成越吃腹水就越胀大，所以我们需要临症来决定如何使用，乌梅丸非常的好用，但是我讲的乌梅丸是真正的乌梅丸，外面的乌梅丸拿起来咬下去没有味道，我们自己制做的你不用咬，只要放在嘴巴里时你就会想赶快把它吞下去，待在嘴巴里会很难过。当你都感到难过，虫吃到就更难过，虫一碰到辛辣的东西就往下逃，逃后再碰到苦的把它泄下去，整个生态环境改掉了。 平常我们吃乌梅丸的时机会选在晚上睡觉前吃，吃了以后早上起来上厕所时就会很愉快。\n\n      只有一种状况就是遇到病人下利便浓血时不要吃，因为下利便浓血是里面太热了，乌梅丸里有一大堆蜀椒干姜细辛热性的药在里面，病人里热已经很盛了，如果再加热药入内，只会造成流血更多。除了这种明明就是白头翁汤证，你给他吃到乌梅丸才会有问题，其他都不会有问题的，就算没有虫也可以吃它，所以乌梅丸是很好用的丸剂。', NULL, NULL, NULL, NULL, NULL, '1、问曰： 上工治未病， 何也  \n\n     师曰： 夫治未病者， 见肝之病， 知肝传脾， 当先实脾，四季脾王不受邪，即勿补之。\n\n    中工不晓相传，见肝之病，不解实脾惟治肝也。\n\n    夫肝之病，补用酸，助用焦苦， 益用甘味之药调之。肝虚则用此法，实则不任用之。  \n\n    经曰： 无实实， 无虚虚， 补不足， 损有余。 是其义也。余藏准此  。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648784895668293, '860E69EEC3D98F28F7ADF2DE624BCD3F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 16:52:32', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8044, 442, 905003002, '      简单讲这整段的内容就是分三个，我帮诸位整理一下就很简单 了。中医的观念，你会生病，不外三种。\n\n      一种是虫蛇刀伤，当然现在还加上枪伤，这种是属于外科治症。\n\n   其他一个是内因，一个是外感。\n\n   内因就是喜怒忧思悲恐情志造成的病，像后面讲的百合汤证就是其中一种。\n\n  外感是因为风寒暑湿燥热而致病的，这些就是造成我们一个人生病的主要原因。\n\n      为什么我常常跟大家讲「要有平常心」。比方说，妈妈坐在那边烦恼儿子闹同性恋，如果你烦恼后的第二天他就不闹同性恋，这个烦恼我们就可以做。问题是你没有办法解决！所有人都在 那边哀声叹气的怨叹，实际上于事无补，而且不但是于事无补，反而造成自己身体障碍更多，然后让更多人都担心，这是恶性循环。\n\n      基本上一个人如果能够有个观念「我不贪」，你的病就已经去掉百分之八十了，譬如说做婆婆的你，媳妇才一进门你就贪了，什么叫贪？你希望媳妇帮你煮饭洗衣服烧菜。结果媳妇没做，你就很难过很生气，你就开始忧、就开始悲、就开始思、就开始怒，这就是后来很多病的来源。很多病源就是我常讲的「这是婆婆病，这是媳妇病」，其实都是因为生气才出来的。这是小人特有的病，小人的屎尿会比一般人多许多，诸如此类的我后面会慢慢跟各位介绍，\n\n     为什么有个人会像狗一样走到哪里都要上厕所，而且上厕所的时候一次分十几个地方，一个地方小一点，这也是有原因的。读中医学时如果能将我国的风鉴之术加进去，对一个人我们就可以看得很清楚。\n\n     至于外感风邪，我们为什么要去练功夫？为什么要练像八段锦、太极拳、易筋经？目的就是要外练筋骨皮，练的很勤快，就是要让风寒不能入侵身体，\n\n    为什么要练打坐？就是要练心，不要受到喜怒忧思悲恐，过喜、过忧、过悲、过恐都不好。\n\n    至于刀伤枪伤这没有办法，就是要靠自己小心主动去避免发生了。\n\n   伤寒金匮里面都是跟各位介绍内因外感，实际上所有的病因，不管你生什么病，都只来自这几种，张仲景的意思就是这样。我们在前面介绍针灸时，还有伤寒时没有跟诸位讲过，在介绍金匮时，我打算一堂课教诸位一个动作，这是文式易筋经。\n\n     第一个是按蹻式，可以帮我们把外感去掉，这个没有内因，做按蹻式时，心要保持平稳。按蹻式，蹻脉的蹻。以下所有的易筋经有一个基本动作都是一样的，就是下盘动作都是一样的，自肚脐以下叫下盘，早上起来到公园里面去，不要站在你家床上面，我们脚要直接站在地下面，吸到地气，打赤脚，五个脚指要像鸡爪一样抓在地上，抓的很紧，然后屁股肚脐以下整个肌肉绷的紧紧的，连屁股的肉都绷紧，肛门自然而然会提肛，上半身是放松的，松和紧刚好上身和下身是极端的，以下所有的动作下盘都是一样的。还有上面的动作、眼睛的动作、嘴巴的动作，诀窍就在这里。我如果不告诉你这个诀窍，你做到的只是形，你做不到神，做到形的时候做了半天冒了一身大汗，回到家后你还是你。如果你做到神的时候，做一个动作下来就有效，在呼吸的时候，你会感觉到你肺没有呼吸，是手掌在呼吸，气会很强，如果你做对后就会有这种感觉，如果你做完了在那边喘了半天，你等于是在跑步，这种叫做劳动，你并没有真正的做到运动，因为方法不对。  \n\n       易筋经平常我不太敢练，因为越练精神就越好，我的精神已经很好了，平时只要睡上五个小时就够了，再练下去就不用睡觉了，所以我不敢练，可是我们到五六十岁练的时候你体格就会很好。我今天头发到现在还黑的，这跟我练易筋经很有关系，而且不要花钱，真正的中国功夫是不需要利用外力来练，譬如说我们去举石锁，或者是举重之类，这是练习外家功夫的，这个外力练不好就会伤到你。刀伤外伤都没伤到你，结果你举这个东西然后伤到，是不划算的。\n\n      按蹻式第一个动作就是我们背要挺直，眼睛要瞪怒，眼睛睁开很大，千万不要两眼微张，平常你们听课时这样微张看我就好了，这样看才能用心听，不要用力看，耳朵用力就好了，心在用力，眼睛要瞪怒，舌头顶在上颚，牙齿咬的紧紧的，很凶的样子。不要管呼吸，自然呼吸感觉舒适就好，下盘要绷紧。按蹻式的动作就是这样子，心里好像在想，手按在桌子上要跳起来的感觉。脸部的动作做好，手这样按下去时全身同时绷紧，不必做很大的下按距离，短短的一寸距离就够了，要做到所谓的「寸劲」，就是只有一寸的距离来出力。寸劲就是劲力发出去的时候只需要有一寸的距离就够了，你看一般人打人手挥出去是没有力量的，因为在远处就用力了，结果真正打下去时就没有力量了。寸劲就是原本是松的，在刹那之间将力量聚集在一起打下去。所以平时上半身是松的，往下压时立刻绷紧就是按蹻，好像人要跳起来一样，同一个动作做四十九下，做这四十九下的中间，肚脐以下绷得紧紧的。做完以后全身再放松开来，下堂课我再教大家第二个动作。今晚开始练，练完晚上睡不着觉我不管的。因为这是九阳神功，阳气很旺，手臂很硬，肌肉会绷得很紧。这是文式易筋经，文式有十二个动作。\n\n      内因没有办法避免，只有常常听我讲课保持心情愉快就好了，功夫要自己去练。张仲景认为说，一般人会得到这几种病，如果我们能够『服食节其冷热，苦酸辛甘，不遣形体有衰，病则无由入其腠理。腠者，三焦通会元真之处。』就是不要受到这些虫蛇的外伤，也不要受到情绪的影响，也没风寒暑湿燥热的影响，常常练功夫强身，偶尔得到风寒时，我们用针或按摩方式让病毒跑出去，或泡热水，这样子的话任何的病毒都没有办法进到你身体。这就是中医认为可以让一个人长年不病的方法，我们不能说长生不老，但是至少让你活到长命百岁，平安的寿终正寝。『三焦通会元真之处』所谓三焦，诸位都学过是体内连系各部位的油网。\n\n      『胸中三焦系统发出乳糜水液，出肌腠流成汗，故曰通会元真。』我们的胸腔里面，我们所有的汗水来源，都靠我们的胃阳，我们东西吃到胃里面去以后，会流出汗，就是因为胃里面很热，胃一热起来的时候，水一进入胃，就立刻进入我们的三焦系统，然后再从此系统发散到皮肤表面就是在流汗，这是正常汗水出来的管道。\n', NULL, NULL, NULL, NULL, NULL, '2、夫人禀五常 因风气而生长，风气虽能生万物，亦能害万物，如水能载舟，亦能覆舟。若五藏元真通畅，人即安和，客气邪风， 中人多死， 千般疢（chèn ） 难， 不越三条 。\n\n    一者 皮肤所中，经络受邪入藏府，为外所因也；\n\n   二者，四肢九窍，血脉相传，壅塞不通，为内所因也；\n\n  三者，房室金刃虫兽所伤。 \n\n    以此详之， 病由都尽。 若人能养慎 ，不令邪风干忤经络 适中经络，未流传府藏，即医治之，四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遣形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处。理者，是皮肤藏府之文理也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648793503801413, '9FF9E1B25F5C601FE093636A24347386', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 17:27:34', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8045, 442, 905003003, '       张仲景说到鼻头，我常建议当中医师需要学一点相术，所谓鼻头 就是要看印堂位，在相书上面写，印堂叫做疾厄宫，所以看到疾厄宫 有一个横纹，这个人一定有痛，身体里面常常痛，像头痛，胃痛之类， 所以疾厄宫最好不要有横纹。有的人有这个横纹，但是无痛时，就表 示他在四十一岁时命运一定不好，事业上遇到很大的阻力，遇到很多 灾难是非的事情，于是事业停滞不前。譬如说：上校应该升少将了， 结果没升上去，你看看他的鼻头，他就是这里有一个横纹。你可以问 问他当年没升上去的原因是什么？「哎唷，我那年生肝病，所以没升 上去。」刚好是四十一岁那一年出现横纹。\n\n      中医的四诊心法提到望闻 问切部分，包括医宗金鉴里面写的望诊写的都不够详细，诸位需要参考些相书才会比较完整。我给大家介绍像宫笃相法、神相铁关刀、冰 鉴、麻衣相术、柳庄相法等，这些好书是诸位可以做为参考的书，大 家也可以参考我着作的天纪，关于看疾厄的部分我写得很清楚。\n\n         仲师 说印堂这边是青色的，代表腹中痛。很多小孩子印堂青青的一块，就 是肠胃里面太冷，肠寒就是腹太寒了。常见到爸爸妈妈要喂小孩子吃 东西，喂了半天结果是「我不要吃。」跑掉了。爸妈说：『这小孩子真 不好养啊！』 一般爸爸妈妈看到的是形，我一看小孩子印堂是青的， 他当然不吃。这是中医所谓的寒，就是肠胃蠕动太慢。肠子里面静脉 的血回流回心脏的力量不够，于是造成肠子蠕动太慢，这时候我们要 用小建中汤。为什么小建中汤能够去他的肠寒？如果桂枝用三钱的 话，白芍就用六钱，白芍是桂枝的两倍，目的就是要让肠子蠕动，因 为白芍性酸能收敛所以能够止腹痛，让腹部静脉里瘀积的血流回到心 脏里面，然后再加点饴糖在里面，让汤药停在胃肠里面，如此就能够 把肠中的寒去掉。所以你一看这个人鼻头是青色的就代表有腹痛，肚 痛。有的爸妈不会观察，父母抱着小孩子时，你问他：『小孩子几岁 了？ 』『才十个月大。』『他会不会讲话？ 』『当然不会讲话！』『你知不 知道小孩子肚子痛？ 』『他从来没说过他肚子痛啊！』你看这个爸妈多 糊涂？小孩子当然不会告诉你肚子痛，还有的小孩子他会讲话，可是 他根本不想跟你讲，他想去玩，肚痛根本不会死人的，爸妈的脑海里 面是一直想要他吃东西，他脑海里面是一直想要玩，两个人是鸡同鸭 讲。你拿东西给他吃，当然不吃，然后你就说他皮，说他不好养，事 实上他是根本没有胃口。小建中汤喝下去以后胃口会大开，此时你不 需要去喂他，他自己就会跑到饭锅里面自己去抓饭吃，会有这种现象 的。\n\n      『苦冷者死』什么叫苦冷？如果这个印堂的部分整个冰掉了，甚 至于摸下去有点水水的感觉，这是相书上面的疾厄宫。鬓角这个地方 相书上叫做命宫，就像我们排八字有命宫是一样的，重病的时候整个 印堂的地方都青冷掉。\n\n       『鼻头色微黑者有水气』这个人如有水肿，印 堂这边就黑黑的，黑色主的是肾脏，表示肾脏功能已经很差了，像尿 毒病患，不要说是印堂，整个脸都会是黑的，尤其整个天庭的地方都 会是黑色的，而且黯黯的没有反光，这已经是尿毒了。尿毒病患如果给西医洗肾，不但更黑，还会出现黄色，后面会介绍到为什么洗肾不 好。\n\n       『色黄者，胸上有寒；色白者，亡血也』如果印堂这里整个是苍 白的，表示这个人失血，一般病人手术以后或者是出车祸大量失血， 这里都可以看到白色的，表示失血失很多，这是中医的望诊。如果颜 色太黄了，代表胸腔有寒，因为胸腔里有寒的时候，我们的脾脏的黄 色营养就没有办法上去完成土生金，胸腔里面本来就是诸阳的通路， 全身的阳气通通汇集到这里，因此胸腔里面会很热，当胸里面的热不 够时，就表示脾脏没有办法土生金，就是脾脏肿起来了，脾脏出问题 时，第一时间病人的印堂就会黄起来。「老师，如果没有在印堂黄， 在鼻头上黄？ 」这表示那个人会有横财，要发财了，如同股票赚钱或 是中乐透奖之类，此时你不要跟他说：「你胸上有寒。」不要看错，此 黄非彼黄。\n\n      『设微赤非时者，死。』如果看到鼻头有赤色，表示有心脏 病，如果是赤在两印中间偏右或偏左时，这个表示是痔疮发作，千万 不要跟他说你要发心脏病死啦，这只是痔疮，我讲的印堂就是在山根 位，就是鼻头的最上端。\n\n      如果你看到『鼻头微赤，非时者，死』什么 叫非时？青、赤、黄、白、黑依序是春、夏、长夏、秋、冬。你在冬 天应该看到比较暗一点，怎么看到红色的呢？这就叫做时节和病人的 气色正好反。如果冬天你看到眉毛下面红红的，这是红鸾星动，你却 在那边说：『是痔疮！』就不对了。所以我们一定要把时运，就是一个 人的命运跟我们望诊的疾病要分开来。心脏有问题的时候，除了印堂 有红赤以外，还有眼珠，眼珠子内侧近鼻根处这边，诸位可以看到有 一条线一定在左眼内侧。这个一条像眼翳一样生的很大，红红的在左 眼这个地方，这就告诉你，此病人已经有心肌梗塞了，或是心脏血管 堵塞住了，这时可以看到眼翳很重。这个翳不是白内障的翳，是心脏 动脉血管堵塞可以看到的表现。我诊所里面有一次来了一个病人，他 花了五千块美金去检查，西医终于查到说：「你有心脏动脉血管堵 塞。」。同学们上个月跟我去美国看到的案例，我们碰到两个，一个是 开刀开两次以后第二次就马上堵回来，一个是做了心导管还是堵回来 没有用，他花了五千美金去做检查，而他进来诊所，还没有讲第一句 话，我一看他眼睛就告诉他：「你是不是有动脉血管堵塞？ 」他说：「你怎么知道？ 」才不到两秒钟，中医的望诊就是让我们能够站在外 面而知道里面藏的是什么，\n\n      『其目正圆者，痉，不治。』 一个人眼睛瞪 得很大闭不起来，眼瞪圆而不动，这代表阳气浮在上面。就是阳已经 要离开身体了，表示人已经快死掉了。我前面介绍厥阴证时有提到， 一个人但坐不得卧，烦躁，眼睛瞪很大，你想想他的阳亢到了什么程 度？连眼睛想闭都闭不起来，全家人都在睡觉时，他一个坐在那边瞪 大眼，这表示已经快要死了。脑膜炎发高烧的时候，病人也会痉，当 筋抽起来时，眼睛都瞪得很大，你如果跟病人说：「不要难过，眼睛 闭起来吧。」他不会管你的，他眼睛就是瞪很大，不但瞪很大，而且 眼珠子还往上跑这是很危险的，表示病毒已经进入脑部了。诸位，到 这种阶段我们经方都可以治，用针灸、用经方，治疗起来都不会很难 的，而经方用的急救药物反而更便宜。\n\n      『又色青为痛』你看到病人的脸色发青，他说：『我肚子痛得脸 色发青。』痛就是青色。\n\n     『色黑为劳』你看那个人脸上黑黑暗暗的，就 是『劳症』，这是中医的观念，色黑为劳症，我上次有讲过一些关于 劳症。还有相书上面讲，色黑是无欲，已经没有性欲了，无法行房事。\n\n     『气色赤为风』脸上红赤代表有风。\n\n    『色黄者便难，色鲜明者有留饮。』 色黄者便难诸位都知道，因为脾主运化，发黄表示脾脏有问题，大便  就跟着会有问题。这个便难不一定说是大便不通，下利也是属于大便  不正常。\n\n    『气色鲜明者，有留饮。』我们人身上有水饮梗在胸腔里面， 或者是梗在下焦，只要身体内某处有留饮时，一般脸色都是光光亮亮  的，你说：『人家脸色气色真好！』其实人家是有留饮，或是胸腔里面  有积水，所以我们要区分清楚。当脸上光光亮亮，但脸上整个光是散  的，平常我们正常的人，光色是从皮肤下面隐隐发出来的，如同珍珠  一般，所谓鲜明就是脸肿起来，脸颊是虚胖，代表身上有留饮。当身上有留饮的时候，此留饮到底是在胸腔里面？还是心脏有积水？还是  在脾脏？还是在组织上面？还是腹部有积水？ 中医都有一套辨症的  方式。在这里张仲景开始先给大家一个很简单的概念。', NULL, NULL, NULL, NULL, NULL, '3、问曰：病人有气色见于面部，愿问其说 ？\n\n  师曰：鼻头色青，腹中痛，苦冷者死；鼻头色微黑者，有水气； \n\n  色黄者，胸上有寒 ； 色白者，亡血也 ；设微赤，非时者死。其目正圆者，痉，不治。\n\n 又色青为痛，\n\n 色黑为劳，\n\n 色赤为风，\n\n 色黄者，便难，\n\n 色鲜明者，有留饮。  \n\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 648795425124421, '05FB6FB22E8CC0446BFB03A852F72B68', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 17:35:23', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8046, 442, 905003011, '     『寸脉洪大而滑』，寸脉指的是上焦，就是上焦受病了。\n\n     『洪则为 实』实就是血实，血实的时候代表血液充满在血管里面，整个血管都膨胀起来，脉是又洪又实，实就是脉很重、很硬。\n\n    『滑则为气』如果 是滑脉，滑讲的是气实，就是气充饱了，像气球一样，鼓胀得很厉害。 如果气和血两个在血管里面流动的时候太强盛了，\n\n   『实气相抟，血气入藏即死』这就类似是高血压，脑溢血的现象。我们的气是在血管外 的网膜上面走，血在血管里面走。如果气和血通通是实的时候，血管 会绷起来，里面的血太过充满，一下子就破裂掉了。如果入脏，这个 脏指的就是「脑」，也就是入脑，就是脑溢血，就很危险了。\n\n     如果按 照张仲景的意思，这个时候反正是死症，就可以开脑，把瘀血拿出来， 说不定还可以救，这是他的观念。如果是入脑，就会死亡。如果是入腑，就是进入三焦，进入消化系统，就会好的。\n\n   『此为卒厥』，就是突然发生昏迷的现象，如何区分 呢？张仲景就说了：『唇口青身冷，为入藏』当我们看病人外表时， 如何知道病是入脏还是入腑？如果这个病人的嘴唇发青，又身冷就表 示入脏了。嘴唇为什么发青？是因为脑部缺氧，血里面已经没有氧气 了，此时血的颜色就会变黑，于是嘴唇的颜色就会发青，身体就冷掉 了，『入脏』是死症。如果是『气血相抟』，血往上冲，脉很实的时候， 此时病人就会『身和汗自出』自己流汗出来，表示热有地方宣泄。像 高血压的病人，热没有地方宣泄，就危险了。\n\n       我的逻辑是：假设降血 压的药有用，你可没有像孙运璇那么高的官，连前行政院长孙运璇都 中风了，你还不中风吗？我的意思是想告诉你，你绝对没有他一样每 天都有医护人员在旁边照顾，每天提醒他吃药控制血压，护士二十四 小时的照顾，还给他吃控制心脏的药，结果又如何？还是中风了。\n\n       中医的观念里面是血气相抟血太热，造成血热的原因是什么？ 中 医观念里面是「血里面的水不够了」。而西医所有降血压的药都跟利尿剂有关，你不相信你吃一颗看看，吃完后小便量很多，血压因此下降了，可是西药降到的是形，第二次再回来的时候血会更热。我讲「热」 就是膨胀得很快，胀得很快，越来越强。所以大家吃高血压药来降血  压时，心里想的是可以预防中风，结果后来还是昏厥，还是中风了。 诸位你要相信，你绝对不会有孙运璇大，孙运璇都这样于倒下去了， 你该记取教训，不要再走同一条路，要换条路走。\n\n       我们在中风之前是有预兆的，前面已经说过了，我就不再细说了。像如果你的手前三个 手指头持续的麻，两个月以内你就有机会得到中风。如果脚前面足阳 明胃经从足三里到解溪那一带会麻时，表示两个礼拜以内就有机会中 风。\n\n       中风之前遇到这种麻的现象，请赶快灸足三里。灸到有疤痕让它 起水泡，这个时候我们再看他还有什么症状，如果脉很洪大，病人燥 是白虎汤证。白虎汤吃下去，把津液补足，血里面的水份经过补足后， 血压就正常了，血管就不会爆满了，所以你吃了降血压药根本是逼着 血往上冲，所以吃西医的降血压药，结果还是照样中风就是因为这样。 你也可以反面过来思考，真理就是正面看是这样子，反面看也是对的。 你跑到西医院去问已经中风病人，你问他：「先生你中风之前有没有 吃降血压药？ 」「有啊！」「那你为什么还会中风？ 』『当时因为正在打 麻将，听牌是单钓二饼，结果被我以海底捞月方式自摸，当时太兴奋， 所以就中风了。』因为人的情绪是无法掌握的，有时会突然很兴奋。\n\n        降血压药只能控制到形，没有办法控制到心神，而一个人的喜怒忧思 悲恐都会造成你血液循环加速。所以病人如果开始吃降血压的药来控 制血压时，连情绪都不能随意的波动，必须要像和尚一般的心如止水 才可以的。 \n\n      但是如果你能够控制你的情绪像无欲的出家人一般的话， 基本上你是不需要血压药，因为你的血压一定很稳定。 需要血压药代 表你的情绪不稳，可能是你的太太或者是你的家人跟你吵架，或者是 你的佣人偷了你一支名贵的手表或者偷了你的钱，你一气之下就中风 了，诸位可以去问，一定是这样子。', NULL, NULL, NULL, NULL, NULL, '11、问曰：寸脉洪大而滑，，洪则为实、滑则为气 ，实气相抟 ，血气入藏即死 ，入府即愈 ，此为卒厥 ，何谓也？\n\n      师曰：唇口青身冷，为入藏，即死；如身和汗自出，为入腑， 即愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584261, 'A974A9432658E95AF421EB7921D480BB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8047, 442, 905003010, '    『厥阳独行』，这个怎么解释？什么叫做厥阳独行？这句话是来 自内经。\n\n     张仲景说『此为有阳无阴，故称厥阳。』就是纯阳没有阴的。 我们身体里面，阴阳是交合互相支援的，如果哪一天阴没有了，只剩 下纯阳就是很危险的症状。阴阳。一定要相辅相成的。诸位看曹颖甫 讲的『油灯将灭，火必大明。』他形容的非常好，他说『故昔人有甘 温清大热之法。内经所谓劳者温之也，然补血养阴正不可少。』像这 种情形，我们看到外表显现的是阳症，而事实上病人是因为体内的阴 严重不足才看到了纯阳症。\n\n      比如你看到病人是阳症，出现热、眼睛红 赤、病人口渴、脉数，你看到的症状都是阳症，实际上他之所以会那 么热是因为里面阴虚掉了，这个就叫做『厥阳独行』，我们北派中医 就要利用甘、温之法来治。病人吃了甘温的药反而真正能够清除此大 热，这就是用甘温清大热的正确时机。你如果说：「老师，此人是壮热，我们应该用苦寒的药才对。」此时如果开苦寒的药给病人，想去除病家的燥热，结果药吃下去后病人却死了，因为苦寒或寒凉的药会把阴降得更低。因此我们辨症的时候一定要看清楚，病人的热是真热 还是假热。\n\n     大家也可以用很简单的辨症法来做区分，可以要求病人「你 舌头伸出来我看看！」 一伸出来，干干燥燥，舌胎都翻起来了，此时 你就不用想说此人到底是真热假热？ 当然是真热，看舌头最清楚，如果你还在怀疑说：「我再检查看看，到底对不对？ 」会失去治病的时机。像我们练习打坐就是要阳气能够潜入阴中，使阴阳互动互生，这 就是为什么我们在打坐的时候，津液自舌头下方的地方一直冒出来， 这就表示阴阳是和谐的，表示你身体是正常的。', NULL, NULL, NULL, NULL, NULL, '10、问曰：经云 ：厥阳独行 ，何谓也？\n\n       师曰 ：此为有阳无阴 ，故称厥阳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584262, 'A9C8E7665326C9B3277B0169D15664A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8048, 442, 905003009, '      这一条辨讲的是如何运用脉诊来做诊断依据。我们脉上面有寸、 关、尺。如果是寸脉-指的就是上焦，就是表。寸脉是浮，代表病在表。如果是尺脉浮起来的话，而尺是指下焦指的是里，我们就可以知 道病是在里，『腰痛背强不能行，必短气而极也。』像是腰痛无法走路， 呼吸短促等里病。\n\n      平常我们要检查病人的脉，查浮脉的时候一定是摸寸的脉，因为肺主皮毛。寸脉浮起来就是感冒了，就是麻黄汤证，桂枝汤证，或是葛根汤证。如果寸脉的浮脉透过关再透到尺部时，脉形一直向下透下来，就表示说病由上而往下，表示表热已经传入里了，太阳表热有时会传少阳，有时又会进入阳明。会进入里是因为失治造成，或是病人 本身一向肠胃就不是很好的缘故，如果进入中焦肝胆部位就会出现少阳证，有时会从太阳一直进入阳明成为里实热之证。\n\n      如果跑到膀胱里 面去，就会造成小便不利，如何知道病已经进入膀胱了？ 当病人出现 腰背强时，代表病毒是顺着皮肤表面上在走，当它顺着脊髓的足太阳 膀胱经一直下去跑到我们的肾脏里面，再进入膀胱泌尿系统时，就会 『短气而极』，此时小便就会淋痢刺痛不顺畅了。', NULL, NULL, NULL, NULL, NULL, '9、师曰：病人脉，浮者在前，其病在表；浮者在后，其病在里， 腰痛背强不能行 ，必短气而极也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584263, 'BEE1BC44BA596272AD4D62B01C47E1C8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8049, 442, 905003008, '    『师曰：冬至之后，甲子夜半，少阳起』这是正常的时节，我们 在二十四个节气里面，有十二个节、十二个气，加起来一共有二十四个节气。\n\n    从冬至那一天开始算，离冬至最近的甲子日，那天晚上的半夜子时就是大地阳气回头之起时。地气回温之初始时，是少阳生，这是正常的时节。 所以『阳始生，天得温和』。\n\n       如果在这个时候，刚刚在地下的阳一生出来，天气就开始转温了。实际上这时天气应该还寒 的，因为阳是生在地下，应该没有感觉，结果在冬至之后，第一个甲子日那天如果感觉到天气热起来，这就是不该热而热，叫做$n{未至而至}， 这是因为『以得甲子，天未温而和者』。\n\n      但是如果甲子日那一天，天气『为至而不至，反而更冷，这就是$n{该至而不至}。气以得甲子日而天大寒不解，此为至而不去』整个都冰封起来了，这是以甲子日那一天为主的计算法。\n\n    『而天温如盛夏五六月时，此为至而太过也。』如果甲子日那一天应该是要很冷的，结果变成大热，这叫做「冬行夏令」， 在我们人身上就会产生很多出乎意料的问题。节气如此改变时。就称 为气『太过』。\n\n      太过的节气会造成什么问题呢？举个例给大家听，金匮里就讲了，譬如说夏天的时侯我们该要流汗，冬天的时候没有汗， 因为汗由小便排掉。结果你在冬天的时候汗大量流失，而这大汗的原因呢，可能你是做苦力的，或者其它的原因造成你的身体丧失了很多汗。冬天应该是收藏，结果你在冬令的节气里面汗失了很多，到了来年春天的时候得到温病。我跟大家讲过了，温病就是当身体津液伤到时，同时间得到感冒于是就变成温病。所以一般小孩子，运动量很大， 一天到晚都在流汗，于是一得到感冒就是葛根汤证，还来不及使用桂 枝汤或是麻黄汤之类，一看就知道是葛根汤证。起因就是因为病人得 病当时是在身体津液丧失过多之下得到的病。\n\n     所以张仲景在这段里面 说「出方是临症来开立的」，我们看病人是太阳、阳明还是少阳，看病人是津液丧失得病的，或者是有表寒而病。张仲景的意思简单地说 就是节气的变化出现太过与不及时，人都容易得到病的。\n', NULL, NULL, NULL, NULL, NULL, '8、问曰：有未至而至，有至而不至，有至而不去，有至而太过， 何谓也？\n\n      师曰： 冬至之后， 甲子夜半，少阳起，少阳之时， 阳始生， 天得温和，此为未至而至也； 以得甲子，而天未温和者，此为至而不至也； 以得甲子而天大寒不解，此为至而不去也 ；以得甲子而天温如盛夏五六月时，此为至而太过也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584264, 'EF4308C6A1BBF9DD54ED3242B1E4F22F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8050, 442, 905003007, '      这里是说我们中医要求必须要脉色相符。一般正常人的脉象「春、 夏、长夏、秋、冬」，春季正常的脉是弦脉，夏天的脉是洪脉，长夏的脉是缓脉，秋天的脉是浮脉，冬天的脉是沉脉，这是四季正常时应 该有的脉象，从我们寸口部位的脉来决定。\n\n      所以寸口是代表胸腔，上焦阳气之位。你摸病人寸口脉时，当你的指头轻轻的触碰到皮肤的表 面时，一摸到皮肤就摸到脉，这就是浮脉。如果当时正好是秋天就是正常人的脉，如果你在秋天摸到洪脉我们春夏秋冬是相生的，木火土 金水。秋天脉应该是摸到浮脉，结果摸到洪脉，脉形壮大，脉来得很洪，就是秋季却摸到夏天的脉，这就叫做相克的脉，如果你是秋天摸 到缓脉或者沉脉，这是相生的脉。相生的脉出现表示很容易治疗，相克的脉就难治了。\n\n       还有除了脉象以外，我们还要注意病人的气色。春天应该看到青色，夏天应该看到红色，长夏的时候看到黄色，秋天看到白色，冬天看到黑色，这是正常的四季的颜色。在冬天的时候你看到病人的气色，比较黑一点是好的，但是如果摸他的脉却是洪脉，脉不符合季节，就叫做色脉不符。\n\n     张仲景就是这个意思，不需要全部讲完，大家可以依此类推，张仲景的观念讲究临症施治，所以没有办法开立一个处方，就能够应付所有色脉不合的现象。\n\n     当冬季时节到了， 有病人脸上出现异常红色时，就表示这个人有心脏病，不然就是刚吃完当归生姜羊肉汤，否则冬季是不该有脸色红的，\n\n     如果是夏天，看到 这个人脸黑黑的，表示这个人有肾脏病，因为夏天脸色应该比较红润， 怎么会看到黑色的呢？这就是气色和季节不符，夏天时你如果到洗肾 中心的门口一看，一票全部都是黑的，所以如果看到脸全部都是黑的， 就是尿毒了。如果有个人他是陪尿毒病人来洗肾的，而这个人的印堂 是黑色的，表示这个人将要出车祸死掉了。所以死有很多种方法，我们不用摸脉，一看就知道此人将死于意外的。\n\n     人死之前两个礼拜可以 看到气色，这就是为什么要讲望气。出事前绝对是可以一看就知道了， 我一再跟诸位讲过，人平常不管是白天或是晚上，刹那之间看到一个人脸上暗暗的，好像是整棵树瞬间枯掉。有时候是头发没有出油，整个头发都膨起来。这表示是没有病，是意外、横祸，或者是凶杀、横 死，出事前都可以看到这种气色。\n\n      当看到这种气色时，马上把黄历翻开来看一看，离今天最近的节或者是气是哪天。比如说现在来看的话十月五号是立冬，国历的十月十五是农历的九月二十八，十月五号是立冬，立冬当天开始算起第七天，到七天时异动之间就会发生事故， 因为色出现的时候不见得是当场出现，你当场就看到，可能是两个礼 拜中间的某一天被你看到，所以在下一个节或气时就会出事，这个部分中医学就没有办法帮他避灾了，但是可以用易经来起一课看看吉凶如何，这部分学者最好自己找方法来解决。', NULL, NULL, NULL, NULL, NULL, '7、师曰：寸口脉动者，因其王时而动，四时各随其色，非其时， 色脉皆当病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584265, '409692337AD3E339706F3DBC1CF5B42B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8051, 442, 905003006, '     如果是『吸而微数，其病在中焦实也。』如果是因为食物堵在肠 胃里面，这就叫『中焦实』。因为食物堵到了，造成病人呼吸很快， 气下不去是因为我们上焦本是受气，下焦是纳气，所以我们时常要练 习气纳丹田，气应该要纳到下焦里面。气因为能够直接到下焦，所以 我们正常人的下焦应该是热的，因为氧化的过程不单单在胸，还要一直往下走，有丹田在使得我们男人的精很热，小便很热，这都是因为下焦能够纳气。当你有食物堵在中焦，造成气下不去，遇到这种情形， 如果是中焦实，很简单，用承气汤把它攻出来就好了。\n\n     如果肠胃是$m{{虚者}，很难治，表示阻隔不在肠胃里面，可能长了别的东西，很严重。\n\n      如果是『在上焦者其吸促；在下焦者其吸远，此皆难治。呼吸动摇振 振，不治。』像这种如果是上膈堵到，更接近于鼻子，于是就会呼吸 更急促，如果病在下焦，就是肾脏功能有问题，诸位会发现到病人一 直吸一直吸，因为下焦主纳气，下焦生病已经不能纳气了，所以病人 就一直在吸，吸完还是纳不了气，就会有这种奇怪的现象。所以我们知道，如果吸气吸的很长，就是这个人肾脏有问题，打坐的除外，打坐是吸气吐气都很长，因为打坐的心法就是在练呼吸之间不让耳朵听到声音。这种就比较难治，并不是不治，只是病比较深了。有实证时， 病都比较好治，只要把实去掉就好了，虚症就比较难治。\n\n    『呼吸动摇振振，不治。』这种就是很危险的症状，一般来说我们看到癌症末期 的时候都可以看到，『呼吸动摇振振，其人必大肉痿陷，大骨枯槁。 午后微热，死在旦夕。虽使扁鹊复生，无能为役矣。』诸位看癌症末 期，癌细胞把人身上的营养都收走，人都变成很瘦，大骨枯槁，脸都黑黑的，然后午后还微热。为什么午后微热？就是我们人的胃气只剩 下一点点，只有在午后热出来一下下，就是快要死了，病人只剩一点 元气了。一般来说遇到这种情形，就赶快把遗言交代一下。这是望诊。', NULL, NULL, NULL, NULL, NULL, '6、师曰：吸而微数，其病在中焦实也。当下之则愈。虚者不治。 在上焦者其吸促；在下焦者其吸远，此皆难治。呼吸  动摇振振 ，不治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584266, '142D9AABAE6C78B0E264F73DE371A56A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8052, 442, 905003005, '      这就是我们中医的望诊法，看病人呼吸的动作来决定病在哪里。 金匮讲的症状比较多。如果一个人没办法呼吸，必须要摇肩才能感觉 到吸满一 口气，这叫做『悬饮』，就是肺里面有积水，就是十枣汤证， 后面还会再介绍到悬饮。你不要回家去煮十个枣子给他吃就完了，不知道的人还真的会去吃那十个枣子！\n\n     如果是『息引胸中上气者』，「啊！ 我不能深呼吸！」 一吸气就往上冲，就要咳嗽，这就表示胸腔里面有 痰，大部分我们看到如果胸腔有痰，又兼有表症时，像是表寒里寒时 就用小青龙汤，如果是表寒里热就是大青龙汤证，我们会依此来决定 怎么使用。如果咳嗽时只有『黄痰』，就是没有表症只有咳嗽的人， 我们会用到皂荚丸。皂荚丸是去胸腔里面烟油、烟痰最好的，吃下去 之后第二天大小便出来，大便出来都黑黑的，痰都从大便排出来。\n\n      『息张口短气者，肺痿唾沫。』什么叫张口短气？ 因为病人靠鼻子吸气都 不行了，表示病人的肺已经整个缩小了。肺本来很大，结果它缩小变 成两个像气不足般的汽球，中医叫肺痿，西医叫肺萎缩。当肺脏萎缩 变小后，由于空间容纳不足，病人很想深呼吸一 口，可是吸不进啊！ 因为肺缩小，症状就是一直吐涎沫，表示肺脏已经萎缩掉了。『息张口短气者，肺痿吐沫。』在我们后面会介绍到射干麻黄汤证，因为肺 必须要靠麻黄把它打开来，后面会再跟诸位介绍。\n', NULL, NULL, NULL, NULL, NULL, '5、师曰 ：息摇肩者，心中坚 ；息引胸中上气者 ，咳 ；息张口短 气者 ，肺痿吐沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584267, '28837CE0B50F1A64536BCC1A6C278E2B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8053, 442, 905003004, '       中医会让人比较诟病的地方，就是什么叫做『寂寂然』、『喑喑然』、 『啾啾然』？ \n\n    『无病之人，语声如平时，虽高下疾徐不同，决无特异 之处。寒湿在骨节间，发为酸痛。』在这句话旁边大家就写上附子汤证。骨节间发为酸痛就是寒湿，体内寒引起的下利，我们要用甘草干姜汤。骨节痛的部分，因为是虚寒、寒湿在肌肉关节里面造成的痛， 我们就用$f{附子汤}。\n\n        寒湿在骨节中间，病人之所以不想讲话，是因 为当寒湿很盛的时候人会很虚弱，元气都没了，讲话声音就会很细， 病人也不能转动，一转动就会很痛，\n\n      『喜惊呼者』，因为病人不能动， 一动就痛，这种病就是没有练易筋经造成的，这就是属于骨节间的病。 我们只要一听到病人说：『啊！你不要动我』一动他就痛，就表示他 骨节间有病，这就叫寒湿在骨节中间，\n\n       如果『语声喑喑然，不彻心者， 你看他说：『心膈间为肺，湿痰阻于肺窍，故语声喑喑然不能澈。』寒 痰在嘴巴里面，讲话不能大声，一大声就要咳、喘不过气来，因为有 痰在，如果是热实，就是大小陷胸汤证，记不记得伤寒论中的大陷胸 汤与小陷胸汤，轻症时，像一般抽烟抽很多的咳喘，重症时，如抽鸦 片、以前抽大烟等，抽多了造成胸腔里面黄痰很多，这是皂荚丸证， 抽烟抽得多我们也可以用小陷胸汤。如果是热实结胸，这是因为病人 有太阳伤寒表症时，结果被人误下造成，整个痰堵在胸腔里面，此时 就是大陷胸汤证了。如果是寒实，我们就要用三物小白散。\n\n       『语声啾 啾然细而长者，头中痛。』头痛的人，他讲话声音不能大，一大声他就头痛欲裂，需要小声讲。你问他说：「先生你讲话大声一点好不好？ 」 「我不能大声啊，我一讲大声头就痛。」此时你先看看他的相，如果长的嘴巴尖尖的、唇不闭齿，舌头又尖尖的，此人善言人之是非，就不要帮他治。他本来就喜欢讲人家是非，为了不要让他再讲所以不帮他治疗，因为他一讲大声头就会痛，这个是老天爷给他的天惩。我就  不教你如何治他的头痛，你让他来找我治，你看我怎么修理这种喜爱  搬弄是非的人。', NULL, NULL, NULL, NULL, NULL, '4、师曰：病人语声寂寂然，喜惊呼者 ，骨节间病；语声喑喑然不彻者 ，心膈间病 ；语声啾啾然细而长者 ，头中痛。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649376984584268, '5E80216EECD464CEEC356767179664C8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 09:01:45', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8054, 442, 905003013, '       为什么张仲景要一句话讲完这一切？『从口入者，宿食也』，就 是吃到不干净的食物而生病。\n\n     『五邪中人，各有法度』，五邪就是我们 讲的风寒暑湿燥热。临证上我们中医在治病的时候，依照一个观念就 是「阴阳表里虚实寒热」。比如说我们看到寒湿在关节上，我们开的 药就是能够去寒去湿的药，这样才能去掉关节内的寒湿。如果寒湿是 在身体里面，我们开去寒去湿的药就必须让它能够停留在身体里面。 如果是谈论病，张仲景没有讲的这么详细。谈论病干嘛呢？西医是最 喜欢弄一个病名出来，你没什么病时，就想办法给你一个病名。「医 生先生，我现在得到的是斑疹伤寒怎么办呢？ 」「没办法，只有把你 烧死掉，然后把你的一切物品通通都烧掉。」西医立的疾病名词很多， 中医不立名，只看症。临症在治疗的时候我们没有这么复杂的，我们 不管是什么病，我们只在乎症的变化。', '（1）哕：音“月”，即呃逆。\n\n（2）咽：音“噎”，即哽咽。\n\n（3）六微：是指六腑之病。\n\n（4）五劳：是指五脏之劳，包括肺劳、心劳、肝劳、脾劳，肾劳。\n\n（5）七伤：指食伤、忧伤、饮伤、房室伤、饥伤、劳伤、经络营卫气伤。\n\n（6）六极：指气极、血极、筋极、骨极、肌极、精极，极，作“疲”字解，是疲极劳损的意思。\n\n（7）妇人三十六病：指十二症、九痛、七害、五伤、三痼。\n\n（8）（问曰：阳病十八），……不在其中：把各种疾病总起来分为两类：阳病和阴病。所谓阳病，是指人体躯壳以外的病证，头、项、腰、脊、臂、脚等六者，病兼上下而在外，故通谓之阳病；所谓阴病，是指人体躯壳以内的病证，咳、上气、喘、哕、咽、肠鸣、胀满、心痛、拘急等九者，病兼脏腑而在内，故通谓之阴病。在外的阳病中，有营病、卫病，营卫交病的不同，这是一病而有三，其三六得一十八病，所以说“阳病十八”；在里的阴病中，有虚病、实病的区别，这是一病而有二，其二九得一十八病，所以说“阴病十八”。另外，除阳病和阴病以外，还有五脏之病和六微之病，也就是邪气中於脏腑，气血失调所引起的脏腑病证。五脏之病和六微之病都各具有十八，其皆为风、寒、暑、湿、燥、火等六淫之邪所中。然脏腑之受邪，又各有气分、血分、气血并受之三端，其六而三之，则为十八病，以十八之数推算，则五脏合得九十病，六微合得一百八病。至於五劳七伤六极，是起居饮食情志所生，妇科三十六病，是月经产乳带下之疾，均非六淫外感所致，所以说不在其中。\n\n（9）清邪居上，……食也：根据病邪的性质定立不同名目。清邪：谓雾露之邪，是本之於天，故居於上部。浊邪：为水湿之邪，是本之於地，故居於下部。大邪：即指漫风之邪，漫风虽大而力散，故中於表分。小邪：即是户牖隙风，隙风虽小而力锐，故中於里分，䅽饪之邪：䅽读“馨”(xin)，即为饮食之邪，饮食从口而入，进入中焦，故伤於脾胃。\n\n（10）五邪中人，……脾胃：已知其邪气有清浊大小之不同，人身有上下表里之区别，同时邪气袭人所中部位，也有一定规律可循，这就是所谓“各有法度”。如风为阳邪而中於午前；寒为阴邪而中於午后；湿气重浊而伤於下部；雾气轻清而中於上部；胃主纳食，脾主运化，故饮食不节，则伤脾胃。\n\n（11）极寒伤经，极热伤络，经脉在里为阴，络脉在外为阳，寒气归阴，所以寒极则伤经；热气归阳，所以热极则伤络。', NULL, NULL, NULL, NULL, '13、问曰： 阳病十八 ，何谓也？ 师曰： 头痛 ，项腰脊臂脚掣痛。\n\n      阴病十八 ，何谓也？\n\n     师曰： 欬上气喘哕咽肠鸣胀满心痛拘急。 五藏病各有十八， 合为九十病；人又有六微，微有十八病，合为一百八 病。五劳七伤六极 ，妇人三六病，不在其中。清邪居上 ，浊邪居下 ，大邪中表，小邪中里，谷饦之邪，从 口入者 ，宿食也。 五邪中人 ，各有法度 ，风中于前， 寒中于后，湿伤于下 ，雾伤于上，风令脉浮 ，寒令脉 急 ，雾伤皮腠，湿流关节 ，食伤脾胃，极寒伤经，极热伤络。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649420929843269, '844538467D4BEA957B8DC4DF7BAB4536', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 12:00:34', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8055, 442, 905003012, '    『问曰：脉脱入藏即死，入府即愈，何谓也？ 』什么叫脉脱？就 是没有脉了。反关脉是例外的。如果你摸病人的脉：「哎呀，老师， 他没有脉！」但是他却好好坐在你前面，此时你应该要摸摸外侧这边，他的脉如果跑到列缺到偏历一带，这叫做「反关脉」。\n\n      反关脉的人非 富即贵，坐在你面前的是大富大贵之人。他怕医师勒索他的钱，他一 定穿着破破烂烂的来。你看完之后：「嗯！先生，这个药很贵喔，大 概要两百万。」「小意思！」这是逃不过我们行家的眼睛，一般中医都被形绑到了，我们千万不要被形绑到。所以你不要说：「老师！他脉 脱则死！」，人家他是大富大贵的人，所以遇到脉脱时，你要前后多摸 一下。\n \n        师曰「不是一种病是这样子，而是所有的病都是这样子」。举例说明，譬如说浸淫疮，我们身上的疮，不管是疮家或是你有麻木的 感觉，如果这个麻木或者这个疮像是破伤风之类的，下管是什么疾病， 如果病毒浸入身体的方向，由四肢末梢往身体方向侵入，就表示很危险。若由身体往四肢方面走就是病在退。「譬如浸淫疮，从口起流向四肢者，可治；从四肢流来入口者，不可治。病在外者可治，入里者难治。」表面上是看到这样的症状，后面会向诸位介绍到斑疹伤寒。 比方说过去西医碰到因为斑疹伤寒而死亡的是要将尸体烧毁的。我们 北派还是有方法可以治，南派是治不好的，斑疹伤寒开始的时候先发疹子，刚开始发一两颗没有感觉，一个礼拜后病人壮熟，然后全身发 疹子发透，发到四肢末梢去，传染性很强。一般西医遇到这种情形就 马上将这个病人隔离起来，然后把所有病人的房子衣物等都烧掉。\n\n       前面这段是讲杂病的一个基本概念，后面才分科分类。如果『以痈疽言』就是身体里面化脓了，或者是里面长东西。如果是长了肿瘤 或者是里面化脓时，『肿痛色红者』都可以治。如果是『平陷色白不甚痛者』都是难治，所以我们需要看病人肿起来的部位，表面上看是红肿的，这种症状我们不用担心。如果表面是平平的，颜色是白的， 还凹一个洞下去，这就是坏病。红就是发炎，就是热，所以有发炎的 现象出现，基本上都是很好治疗的，西医也知道很好治，这表示你的免疫系统很强，你有抵抗力才会发炎。如果不发炎，表面上苍白的而且不怎么痛然后慢慢凹下去，这就是癌症，是很危险的症状，非常不好治。\n', NULL, NULL, NULL, NULL, NULL, '12、问曰：脉脱入藏即死 ，入府即愈 ，何谓也？\n\n       师曰 ：非为一病 ，百病皆然。譬如浸淫疮，从口起流向四肢 者，可治；从四肢流来入口者，不可治。病在外者可 治 ，入里者难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649420929843270, 'E34EEA26FE3654E7C396066674C7AD46', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 12:00:34', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8056, 442, 905003018, '       他这举例了『如渴者与猪苓汤，余皆仿此。』所以大家将来要做 像牛顿一样的发明家，诸病就在里面。脏就是藏在里面，不一定是脏， 是病藏在里面，譬如说藏在大肠里面你用承气汤，张仲景就是这个意 思。要『随其所得而攻之』。猪苓汤是一个很好的利尿剂，我在前面 伤寒论已经跟各位介绍过如何使用此汤了。好，我们现在开始进入正 式的金匮。', NULL, '猪苓汤', NULL, NULL, NULL, '18、夫诸病在藏，欲攻之 ，当随其所得而攻之，如渴者舆$f{猪苓汤} ，余皆仿此。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649475879530565, '3B2EA2AF5E1642A334866EF404F30557', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 15:44:09', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8057, 442, 905003017, '      这就是所谓的「除中」，本来病患已经不吃食物了，突然之间又吃的很多，这时病人会发热。「除中」就是胃气没有了，这时候突然 会吃东西，就是很危险的症状。', NULL, NULL, NULL, NULL, NULL, '17、病者素不应食 ，而反暴思之 ，必发热也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649475879530566, '7B5089C44FD3CC2203A3DBD0456C35E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 15:44:09', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8058, 442, 905003016, '       譬如说：心脏本身是很热的脏，如果病人的症状就是恶热，这就好治疗，反之如果心脏病人会恶寒，就是病了。\n\n        肝，本身就是比较寒的脏，所以厥阴篇里面肝脏最冷的，肝就恶寒，所恶的一定跟它的属性是相同的，就可以治好。\n\n       脾脏就是指湿，脾脏本来就是湿的脏，湿太盛了也下行。\n\n       肺脏本来是燥的病，如果太燥了，肺脏也会受不了。\n\n      这个条辨还有一个重点，我们在开药给病人吃的时候有两个现象。一 个现象诸位学过了，吃下去药后头会昏，人会昏昏的，代表中病了； 还有一种状况，中药之所以叫做药，不叫做食物，就是因为它难吃。 你什么时候听过中药好吃的对不对？好吃的一般我们都叫做食物。不叫做药。而当你拿很苦的药给病人吃的时候，病人居然说「哇！这个 药真好吃！」于是一直吃下去，这也是药到病除的现象了。', NULL, NULL, NULL, NULL, NULL, '16、师曰 ：五藏病各有得者，愈 ；五藏病各有所恶，各随其所不喜者为病。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649475879530567, 'CF5A752C92AEFF024CF81F9D60749487', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 15:44:09', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8059, 442, 905003015, '     『病痼疾』，就是本来就有的老病，『加以卒病』新病又来了，这 时一定要先治他的新病，再去治他的痼疾。金匮还没有正式开始，这 是我们中医治病的基本原则。', '本条为论新久同病的先后治疗原则。\n\n（1）痼疾：是痼久难治的旧病，痼，音“固”。\n\n（2）卒病：卒然而得的新病。\n\n（3）当先治其卒病，后乃治其痼疾也：旧病加新病，如何治疗？同样，也是要首先分析疾病的先后缓急，然后才施以相应的治疗措施。由于旧病病势较缓，病根深固而难以速愈，新病病势较急，病情轻浅而易以祛除，不治则病势发展加重。所以在旧病新病同时存在的情况下，先治其新病，后治其旧病。新病除，旧病解，则疾病痊愈。\n\n先治新病，后治旧病，这是治疗的一般原则。但是，临床上，新病和旧病往往是相互影响的，所以在先治新病的同时，某些情况下要兼顾旧病，而不可偏颇。如一味治其新病，则会产生变证。例如，久患淋病之人，又感受了外感邪气，如果只先治外感而发汗，忘记了“淋家不可发汗”的禁戒，就会引起便血的变证。', NULL, NULL, NULL, NULL, '15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649475879530568, 'A769A24F9211B10DE3A48FD5D3FB0040', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 15:44:09', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8060, 442, 905003014, '      什么时候要先救里，什么时候要先救表？『师曰：病医下之，续 得下利清谷下止，身体疼痛者，急当救里；后身体疼痛，清便自调者， 急当救表也。』各位读过伤寒论后都知道，当被攻下以后，这个人已 经里虚掉了，又继续在下利，下利代表肠胃的津液都跑光了。\n\n      此时如果病人有表症时，我们开发表药给病人，发表的药就是利 用肠胃的津液来流汗。结果病家肠胃已经空虚，正在下利中，你还跟 他说：「我先用发表的药试看看。」 一剂下去结果造成病人表也虚了， 于是病人更虚，所以吃完你的桂枝汤后就躺在那边不能动了。于是你 对老师说，「老师，桂枝汤有这么厉害！」结果自此以后桂枝汤就不敢用了，南派中医就是这样想，所以看到麻桂如见蛇蝎般，只因为辨症不清而痛失名方。', NULL, NULL, NULL, NULL, NULL, '14、问曰 ：病有急当救里救表者 ，何谓也？\n\n     师曰：病医下之，续得下利清谷不止 ，身体疼痛者 ，急当救里 ；后身体疼痛 ，清便自调者，急当救表也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649475879530569, '157C2A1D18DCA9D1EC426671FCA6A8B7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 15:44:09', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8061, 443, 905004003, '      也就是表汗流太多，有的时候出汗的原因是小孩子太皮，还有医 生开的发汗药开太强造成的。\n\n      比如说你看到一位小孩子生病，一看： 「老师，他是葛根汤证。」结果你把葛根汤的葛根、麻黄、桂枝开的 很强、你忘了开生姜、甘草、大枣。这一剂下去以后就开始抽筋，晚 上像开始发癫痫一样，整个身体都角弓反张起来，这是你造成的痉病， 发汗不能太过。\n\n       所以说我们在开给病人吃发汗药的时候，张仲景特别 提醒说：『不要尽剂』就是你第一碗喝下去：「嗯，没感觉。」再喝第 二碗。「嗯，发汗了！」就停下来，不要再喝了。老妈妈舍不得药，认 为倒掉太可惜了于是：「反正中药温和无所谓嘛！」于是就喝下去，结 果发痉，害我们更忙，因为津液伤到了。\n\n   「太阳病，发汗太多，因致痉。」就是我们在伤寒论介绍过的真武汤证。发汗太多的话，就是真武汤证。\n\n     如果发汗太多还没有成痉：「老师，我开麻黄桂枝下去，病 人发汗很多但还没有成痉。」这时候赶快用桂枝加附子汤，就是桂枝 汤加炮附子来收表，如果已经变成痉病，就很危险了，赶快用真武汤。 如果是『发热必拘急』，手脚都筋挛起来，痉病已经成形了，这时候 就是附子汤证。诸多此类的痉都是因为津液枯竭造成的。\n\n     所谓痉的症状，就是抽筋，整个身体都拘挛起来，然后病人整个身体向后弯过去， 胸腔张的很大，肚子整个凹下去，然后嘴巴咬得很紧，眼睛往上吊， 这就是痉。', NULL, NULL, NULL, NULL, NULL, '3、太阳病 ，发汗太多 ， 因致痉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649491698446405, '18DB3D5EAE9E57471A28FCEEE2E4144F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 16:48:31', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8062, 443, 905004002, '       诸位记不记得我们在读伤寒论太阳篇时，遇到太阳病如果是发热 脉浮而缓，就是桂枝汤证。\n\n    如果浮而紧，就是麻黄汤证。如果是太阳 病发热，项背强几几然，就是葛根汤证。现在是太阳病在发热的时候， 一摸到病人的脉，不浮、沉又细，代表里虚寒了。沉脉代表是里症， 细脉代表里寒很盛。身体里面的寒很盛，代表我们整个脏腑功能都变 差了，中医叫做寒太盛，这个时候容易造成痉病，难治。痉病的成因 就是水不足，当人身上的水分不够了，就会产生筋挛，开始壮热、大 热。\n\n       当里寒很盛的时候，我们水喝到胃里面去它不会补充水，因为里 寒很盛，水一下去就被排掉了，水分补充不到时就会出现问题，这就 是痉病的成因。所有的痉病不管是刚痉、柔痉，包括后面还有一个大 承气汤证。诸位在阳明篇就学过大承气汤证，所有的这几个证，通通 是因为伤到津液引起的，就是津液不足了。', NULL, NULL, NULL, NULL, NULL, '2、太阳病 ，发热 ，脉沉而细者 ，名曰痉 ，为难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649491698450501, '933EB89A97DF7838F889EDE123950213', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 16:48:31', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8063, 443, 905004001, '        同样是痉，中医分两个。一个是刚，一个是柔。刚，简单讲是无 汗。柔就是有汗。张仲景开的两个方子，一个是葛根汤，一个是栝萎 桂枝汤。得到痉病的时候就这两个处方。后面我们会讲到，我们一个 条辨一个条辨看下去。', NULL, NULL, NULL, NULL, NULL, '1、太阳病，发热 、无汗 、反恶寒者 ，名曰刚痉。太阳病发 热汗出 ，而不恶寒 ，名曰柔痉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649491698450502, '5E1D3063A64F76A856228CF7FBBEBC32', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 16:48:31', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8064, 443, 905004007, '      接到前面这个病，当『其脉如蛇』，如果病人突然腹部胀大起来， 『为欲解。』『脉如故，反伏弦者，痉。』为什么会胀大？平常本该在 上面的热，当热宣泄不出去时，有时热会反而往下走，突然出现烧退， 热会阻在中焦这里，于是造成腹部整个膨胀起来，此时代表湿热已经 进入中焦了，没有在上面。热一旦进入中焦，表示这个病一定会好， 为什么？ 因为热极必返，所以这热会慢慢往下走。『脉如故，反伏弦 者，痉。』但如果脉还是没有变动，还是很弦，表示还会再发痉病。\n\n       所以如果遇到发痉的病时，我们要将湿热往下导引，后面会介绍一些方法。『夫痉脉，按之紧如弦，直上下行。』你摸到痉病的脉时就是所 谓脑膜炎的脉，此时必有高热，这时脉跳起来会很硬，然后上下直行 的。因为血太热会伤到津，血里面要有一定的水分，血失去津液时就 会过热，如此就会伤到我们的经络，伤到我们的血脉神经，所以太热 也不行。就好像我们将生肉丢在滚水里面一煮就白掉了，太热会伤到 肌肉。如果将猪血拿起来倒在汤里面一下子就煮熟了，所以太热也会 伤到血。', NULL, NULL, NULL, NULL, NULL, '7、暴腹胀大者，为欲解。脉如故，反伏弦者，痉，夫痉脉， 按之紧如弦 ，直上下行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649503051726917, 'C45132033C4B7F09274894931BE7122B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 17:34:43', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8065, 443, 905004006, '      为什么会发生这种现象？ 当我们得到表症时。也就是病毒刚进入 我们的皮肤表面时，毛孔会因此闭起来，就不会流汗了。没有流汗我 们需要用药去发汗，发掉「病毒」就是所谓的解表。一般身发热时， 我们有两种去热的方法。一种是利用发汗来解，一种是利用小便来解。 如果小便很通畅，这个热就有地方宣泄，如果小便也没有了，这个热就会亢在里面，如往下走，小便又出不来，想走皮肤表面时又出不来， 于是就闷在里面。\n\n     世界上所有的热都是往上走，你有没有听过热往下走？热往下走就不会有火山爆发，热气球会升上去而不是冷气球，孔明灯也是利用热气才上的去，所以热的性就是往上走，当热冲到头上来后，整个人就会呈现出脑膜炎的症状。头在晃，眼睛红赤的，此时病人的津液已经很枯竭了，你又给他发汗药，一发汗，就造成血里面的水更不够了，于是脉就变弯了，你摸到的脉，脉就这样子扭曲的， 因为脉里面的水分不够，就会变成这个样子，这是很危险的，前面谈到现在就是告诉我们发汗要有方法，一定要确定病人可以发汗再使用发汗的药，就不会有问题。\n', NULL, NULL, NULL, NULL, NULL, '6、病者，身热足寒，颈项强急，恶寒，时头热，面赤目赤， 独头动摇 ，卒口噤 ，背反张者，痉病也。若发其汗 ，其脉如蛇。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649503051726918, '30A2A61A57F0CD1200B12AFACC5CC98B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 17:34:43', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8066, 443, 905004005, '       张仲景在伤寒论有讲过，有几种状况是不能发汗的。疮家本来身上就生有很多脓疮，会生疮的人基本上本身就是血不足了，血足的话怎么会有疮呢？我们的抵抗力是藏在血液里面，血足就没疮，血不足才是疮家。这个时候你给他发汗药，于是变成水也不够了，结果血就更不够，病人反而会虚掉，血没有办法去滋养我们的肌肉、筋脉，也会造成痉。\n\n     遇到这种疮家得痉的话怎么办呢？就是张仲景在伤寒论介绍的，『$f{芍药甘草附子汤}证』。芍药这个药，在这里跟诸位再讲一次， 如果血中有湿阻时，就是用芍药的时机。芍药分白芍与赤芍二种，实际上真正我们在用时这两个是相通的。\n\n       如果硬要严格去区分的话，赤芍比较着重在外面，疮家用的，白芍比较着重在里面，治疗脾脏用的，实际上这两个功能差不多。\n\n       如果血中有湿阻，什么叫做血中有湿阻？就是皮表生疮流脓流出黄水、脓水这样滴滴答答黏黏的出来，这个就是湿。湿堵在血里面造成血液循 环不流畅，这个时候用芍药甘草附子汤，就要重用芍药甘草。你说： 「老师，芍药用二钱。」这种剂量只能清清牙齿，芍药要用一两以上才够，大剂的下去救他，你们不要开太轻，这是一般我开的芍药甘草附子汤。 如果疮家遇到南派的话，很可能会开像浮萍、薄荷、陈皮等， 很清凉的药给你吃，我们北派开芍药甘草附子汤就好。\n\n      常常有人半夜 如果『腿不得伸』，腿在抽筋，就是该使用芍药甘草附子汤，张仲景在伤寒论是这样讲的。如果是疮家的人，疮流脓化脓水出来又痒又发 炎时，光是芍药甘草附子汤就只能去他的痛，还要加些固表药物，湿才会去掉，同时要加一些解毒的药，寒凉的药在里面。因为病人有发 炎，西医讲发炎，就是中医讲的热，所以要加一些去热的药，像黄芩、 黄连此时都可以用的。所以黄芩黄连常常被我们混合芍药一起用，可以去病的湿热阻隔。反过来，如果遇到女孩子的白带很多，是不是也会用芍药？芍药对腹痛最好，所以四物汤里面一定要重用芍药，南派就是用四物汤重用芍药用对了，其他的都还不对。后面还有很多方子 要给诸位看。', NULL, NULL, NULL, NULL, NULL, '5、疮家 ，虽身疼痛 ，不可发汗，，汗出则痉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649503051726919, '4E1FA9AA870C3123667E9A3ABC24FEA8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 17:34:43', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8067, 443, 905004004, '       得到太阳表风病的时候，我们讲『$f{桂枝汤}』是去风，如果你没有 开去风的药，反而先开攻下药物，开攻下药物就是所谓的承气汤。攻下的药会把肠胃里面的营养排出去， 胃是生血之源，结果被排掉后， 这成血的源头没了，已经因为误攻下，使得血的源头没了，这个时候 你又开发汗的药，于是病人又发热，这种就会造成拘急症状出现了。', NULL, NULL, NULL, NULL, NULL, '4、夫风病 ，下之则痉 ，复发汗 ，必拘急。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649503051726920, '17B7AD8CE00147FB17DAEBC5BAAF5A58', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-28 17:34:43', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8068, 443, 905004010, '       前段说的是有汗，就是表虚掉了，所以我们必须用$f{栝蒌桂枝汤}去解。现在是无汗，没有汗的时候，小便反少。我刚刚讲过，如果一个人没有汗，小便很多。你说：「老师啊！我的体质很奇怪喔，我就是长年不出汗。」「你小便多吗？ 」「我一天十几次小便。」这就与流汗是 一样的，汗水跟小便是同源。如果小便也少了，又没有汗，这个热是不是就闷在身体里面呢？于是就会发刚痉。\n\n      这个时候病毒就会进入我 们的脊髓神经，跑到脑部去，于是就开始发痉。而$n{刚痉}跟$m{柔痉}是不一 样的，一个是柔痉$m{有汗}。一个是刚痉$n{无汗}，记住我的话。\n\n     临症上看就是这样子， 有汗，$f{栝蒌桂枝汤}，无汗，$f{葛根汤}，千万不要弄错。这时病人的病情是非常紧急，所以绝对不能在此时出错，更且我们开的是经方，病人服后是一剂就知，生死是立竿见影的，所以我一再跟大家讲，你只要记得，有汗就是桂枝汤，有汗同时又有柔痉时就加入栝蒌根，讲的这样明白再记不住，我也没有办法了。\n\n       由于这种症状的发生是因为热在 体内没有办法宣泄出去，于是热就只能往上冲，结果热到病人整个脑部，造成头上壮热难耐。气上冲胸口就是整个胸部都胀起来，肚子却很小，也因为热气往上冲，\n\n     于是『口噤不得语』，就是病人的牙齿咬得很紧的意思。当病人发痉病的时候，要注意预防病人会把舌头咬断 掉，所以一定要把病人的舌头撑开来，千万不要让病人咬到自己的舌头。\n\n    『欲作刚痉』，这也是葛根汤证。欲作刚痉跟已经刚痉都是葛根 汤证，欲作刚痉之时「老师他还没作刚痉啊！那就下吃葛根汤了！等到出现刚痉后再吃。」你如果是这样想，就大错特错了。刚痉时当然 是要立刻给病人吃葛根汤，千万不要有疑虑。「老师，欲作才是！」张 仲景是说欲作时可用，那刚痉时该怎么办呢？不能看着病人等死，还是要用葛根汤的。\n\n      使用葛根汤时要特别注意剂量该用多少，必须要重用葛根，才是真正的葛根汤，如果葛根是四钱，桂枝、炙甘草、芍药都是二钱，这时候麻黄是三钱，桂枝芍药都是减量，重用葛根、再来是麻黄、再来才是桂枝的剂量，你如果说：『老师！剂量开太过了！』 葛根汤的剂量是有原因的，因为麻黄要靠桂枝才会到达皮表，之后麻黄再把皮肤毛孔打开来汗就出来了，如果麻黄开得少，桂枝开得多于麻黄，结果桂枝到了肌理后，麻黄还在后面，汗就发不出来。所以麻黄的剂量一定要开的重于桂枝的剂量，同时要再加强葛根的剂量，如果葛根开二钱，麻黄开四钱，结果病人喝药后就无法将体内的津液提 升到太阳经上，仲景先师重用葛根的剂量， 目的就是要让葛根先行， 开出最大剂量的就是葛根。葛根下去把肌肉里面的水先发出来，发出。 来以后还没有到皮肤表面，这时麻黄就跟着来了，麻黄一到，毛孔就开了，加上桂枝跟着过来，将肌理中的积汗一推就把这些积汗通通顶出来了。这就是仲师的四三二一黄金比例。 \n\n        如果你开了二三四，葛根还没有去清，桂枝已经先去了，桂枝顶了半天汗没有出来，病人就会头昏。『怎么发汗发不出来？ 』好不容易麻黄到了，流一点点汗出来，结果表汗去了些，但是囤积在肌肉里面的汗，还是没有尽去，就会造成汗流出来，后项却还是几几然的， 病人还是有壮热。所以仲师开立处方的时候，他的技巧很多是出在剂量上面，更厉害的是我们临床上去看时，他的这个剂量病人喝下去后， 可以把病人得病的病毒与残留的余毒一起排出体外，而不会伤害到好的津液。\n\n      然后他还设计一个方子，这个津液发出去的时候因为是从肠胃里面发出去的，发完津液以后如果小便没了，就代表水没有回到胃里面来，我们水出去是要回头的，不是要让体内的水全部出去，如果是这样，葛根汤下去就完了，因为病人脱水了，为了让正常的津液不受损耗，所以后面加有生姜、甘草、大枣，这样设计处方的目的，就是预防万一水发散太过，无法回头，这些药可以刺激肠胃产生津液， 还有也可以吃五苓散来收敛表水，使水马上回到肠胃里面来。所以经方的设计方式，不单是处方内容简单，药物选用是俯拾可得，连剂量都设计得完美无缺。', NULL, NULL, NULL, NULL, NULL, '10、太阳病 ，无汗，小便反少 ，气上胸 ， 口噤不得语 ，欲作刚痉 ，$f{葛根汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649739902582853, '8EBBDA7F78E927EC1BE33B36BB860893', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 09:38:28', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8069, 443, 905004009, '『太阳病其证备』当所有太阳病的症状都有了，如果病人却『身体强，几几然，脉反沉迟，此为痉』。如果不是『脉反沉迟者』而是 『$m{浮紧}』就是伤寒论中的$f{葛根汤}证，项背强几几—葛根汤。如果『脉反沉迟，此为痉』。\n\n      病人表现的外症与太阳症一样，唯脉症不同，这 就是$f{栝蒌桂枝汤}证了，诸位在上面写一个『柔痉』。柔痉是有汗，当病人表虚的时候一定会有汗。如果表实，病人必是无汗。表实的话我们要用$f{葛根汤}，病人发痉病，就是现代所谓脑膜炎之类的病，西药麻黄素也有发汗去热的功能，可是西医知道要去热，但他们没有区分无 汗跟有汗。\n\n       张仲景把痉病分无汗跟有汗，无汗的话是表实，这要用葛根汤来去除表实，当病人表虚掉时，葛根汤就不行用了，有汗我们必须要用栝蒌桂枝汤。\n\n       栝蒌根桂枝汤，就是桂枝汤加栝蒌根而已。栝蒌根在神农本草经 里面，是一个专门生津止渴，能够解经热—热在血脉神经里面时用的药。对西医来说，就是：「这个可以降血糖。」所以糖尿病的人我们常常会用栝蒌根。\n\n       过去北派的医师讨论过：「这个栝蒌根既然能生津解渴，栝蒌根跟葛根的性应该是差不多。」因为葛根汤是用桂枝汤加麻黄再加葛根而成的，如果把麻黄拿掉就只是桂枝汤加葛根而已。那就不一定非要用栝蒌根用葛根也可以，实际上这两味药稍有不同，完全相同的话通通用葛根算了，葛根专门是治疗项背强几几然使用的，就是可以升提我们太阳经的表寒水。\n\n      我们人身上有水和血，汗流出去的时候应该要从背后流出去，结果有一天它没有流出去，因为风寒进来将太阳寒水束住了，项背中于风，所以我们中医有一句话叫做「神仙也怕脑后风」。哪天你坐在那边打麻将，背后面对着风吹，打完一圈牌就变成葛根汤了，再两圈牌就成为麻黄汤了，病情会越来越强，这就是神仙也怕脑后风。这个风寒进来，表被束到了，造成应该要流出体外的汗没有流出去，水停在皮表跟肌理之间。\n\n      因为它已经离开汗腺 了，所以无法回头，你叫水往哪里走？没有办法，水性本是向下的， 所以它就慢慢渗到肌肉里面去，渗到背上，背就变的很硬很紧，这是 因为汗水陷在肌里，所造成的几几然症状。\n\n      此时就要靠葛根把它升提起来然后发散出去。葛根汤里面有加麻黄，目的就是当陷在肌理中的 汗被葛根升提离开肌肉后，碰到麻黄将毛孔（玄府）打开，于是汗就流出来表就解了。\n\n      栝蒌根就不是这样，栝蒌根就好像直接把水倒在血里面去，因为那血脉神经是全身性的，葛根只是专门针对项背这一带， 两个都是生津，但是葛根着重于升津，栝蒌根偏向于生津。栝蒌根二两，你不要真的开二两，六钱就足够了。桂枝三钱，芍药三钱，桂枝芍药等量一样，吃完药以后喝热稀饭，来帮助药力发散，如同喝桂枝汤后就要『啜热粥发之』。就是因为栝蒌根能够清除我们身上所有血脉神经的热。所以糖尿病的病人，临床上看时，都是因为有热在血脉神经里面造成的问题，就是血太浓，血里面水分不够了，这栝蒌根下去血糖就会下降，因此栝蒌根很好用的。', NULL, '栝篓桂枝汤', NULL, NULL, NULL, '9、太阳病其证备 ，身体强 ，几几然 ，脉反沉迟 ，此为痉， $f{栝篓桂枝汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649739902582854, '28E31501B8CCA75EF299234C7AAEF017', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 09:38:28', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8070, 443, 905004008, '        有些人每天都在烧艾绒，看艾草没有烧完就让它继续烧，只是为 了节省一点不要浪费，暴殄天物，结果因此起了一个灸疮。在这种状 况之下发生痉病，就很难治，所以一旦有灸疮就要赶快把它弄好。如 果得到痉病又同时『灸疮』，就很『难治』。张仲景这里没有出方，后 世很多医生就想到很多方子。\n\n       有灸疮或者是疮家发高热时，我们要如 何才能把高热退掉？还有脑膜炎到了后期西医都束手无策时，此时中 医该怎么做呢？我们刚才讲过，痉病本身的成因就是因为血管里面的 水份不够造成的。发痉的时候病人角弓反张，全身拘急起来，根本无 法抓住病人。如果你是西医，在这个时候硬替他打点滴进去，葡萄糖 注射液在这个时候产生效果，一下子把血里面的水补足了。虽然不是 从肠胃进去，但是补足之后，体温就退了。\n\n      可是西医往往在这种状况 下，他是没有办法替病家打葡萄糖，因为病人会乱动，手足燥扰，只 能眼看着他死掉。所以大家要记得，如果你有葡萄糖在旁边，你又知 道他是津液伤到了，才会发高热『但热不寒』，这个时候如果你能将 葡萄糖打进去也是好的，做为急救用有何不可。\n\n        还有一种方法，就是 遇到有灸疮的人，过去一些医家有的用蝉衣。明末清初一个名医，姓 傅，叫做傅青主，在他的方剂里面，「男人科」，专门看男人的那种病。 过去医家有分科，男人科里面有一个方子，就是用蝉衣还有黄酒。蝉 就是我们的「知了」，你收集一堆，拿个一钱左右，不要生病的时候 再去收集，中药行就有得买。你把它的头和足去掉，只留身体就可以了，把它磨碎以后，跟黄酒两碗混合在一起，不要掺水，然后煮成一 碗，这个时候一口气喝下去。 此时病人发汗很奇怪，这两个药在身体 里面时，脑膜炎的高熟就会退掉，这是专门用在疮家又得到痉病时， 像小孩子有时候头或身上长有疖子，也是一种疮家。\n\n      本来要给病人发 汗，结果一看「唉唷！疮家不可汗！」而病人已经在发痉了，此时再 给他发汗药是不是更痉？这个时候我们就用这个方剂。孩子在发汗出 来后热会退掉，汗出来时摸他全身，会有黏答答的感觉。如果是打点 滴来退热的话，就会从背后一直到脚上面，整个发起白白一粒一粒的 疹子，摸上去感觉很粗糙，大概点滴打两个小时以后也会有这种现象， 热就退掉了，脑膜炎病毒都跑出来，跑到皮肤表面上来。', NULL, NULL, NULL, NULL, NULL, '8、痉病有灸疮 ，难治。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649739902582855, '079081FB76E7D9F7072C522BDD6733DF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 09:38:28', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8071, 443, 905004011, '       这个就是我们前面介绍过的，有种脑膜炎的症状必须使用大承气 汤来治，如果你问说：「老师，到底他是括蒌桂枝汤？还是葛根汤？ 还是大承气汤？ 」这就要靠辨症来做决定，病人得到的症状是什么？ 『胸满口噤、卧不着席』「老师，他说的都一样？ 」，$n{唯有脚挛急，必齘 xiè齿}不一样。\n\n    什么叫『齘齿』？ 就是牙齿咬到绷得很紧，还有 一个检查的方法，就是你把病人的嘴巴拉开来一看，他舌苔上面黄黄 的。还有再问问旁边的人：「他几天没大便了？ 」如果病人的亲人说 病人本身就有严重的便秘，就是大承气汤证了，大承气汤，诸位都学 过了。你说：「老师，到了这种阶段『卧不着席』大承气太峻了。我 们用调味承气，小承气。」这就是医师不明病情发展，无法确定病人 的需要，会耽误病人，这个时候救急需要『急下存阴』。这就是脑膜 炎发病除了是我们身上血里面的水不够之外，还有一种就是大便堵在肠子里面。如果大便的臭气跑到心脏这边来，就变成奔豚，就是桂枝加桂汤。如果跑到脑部去了，给西医检查，西医会说「无菌性的脑膜 炎」。为什么？西医只能查到细菌或是病毒感染，查不到大便的臭气， 他也不会闻一下，结果很多人因为失治而死掉。\n\n        我告诉你们大承气厉害到什么程度，大承气喝下去以后，病人大便还没有出来，烧就已经退了，小孩子就已经开始玩耍了。大概这种现象在喝完药后的二十分钟到半个小时就可以看到了，如果病人没有这种现象，一定是你开错处方。治病，时机很重要，当病人急需要时， 你还在那边怀疑犹豫，是不可以的。刚刚讲的痉病到现在，就是三个 处方在治疗，经方家治疗脑膜炎看似简单，我们只有三个处方在使用， 无汗有汗就分两个，西医没有分的，然而病人死在西医手上的却很多。 大承气汤证还有一个直接的确诊方法，就是利用腹诊。', NULL, '大承气汤', NULL, NULL, NULL, '11、痉为病 ，胸满口噤 ，卧不着席 ，脚挛急 ，必齘齿 ，可与$f{大承气汤}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649748970188869, 'A971C94EC31C93E41F37C4E55CC55374', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 10:15:22', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8072, 443, 905004020, '       麻黄加术汤跟麻杏薏甘汤这两个处方都因为病人无汗，才会用到麻黄。现在讲到的防己黄耆汤呢，大家看，第一是脉浮。「老师啊，  浮脉代表病在表。」代表太阳中风，病在表，此时如果感觉到身体有  很沉重感时，身重代表湿盛。湿盛的人一定感到全身很沉重。劳症的人也会常常感觉身体很重，因为湿在血管里面积累造成的。 这种人打高尔夫球，打完一个球洞的时候他就全身不能动了，为什么？ 因为身重，所以病人很容易疲劳，就是湿很盛之人。\n\n        此处仲师写的脉浮代表风，身重代表湿。『汗出恶风者』汗出来代表表虚了，表虚了才会流汗，此时风吹来时就很难过，这就是防己黄耆汤证了。大家看看处方内容，其中有防己、炙甘草、白术、黄耆，由于这是表虚的时候产生的风湿的症状。\n\n        防己跟白术，白术能去湿我们就不要再重复讲了，当病在皮肤表面上的时候就是麻黄加术汤证，进入肌肉时候变成麻杏薏甘汤证，进入血脉、血管的外围的时候就是防己黄耆汤证了。湿在不同位置上仲师用的剂量深浅就不一样，张仲景真的很厉害。如果在血管的外面，还没有进入血管，进入血管里面就是桂枝芍药知母汤证。 \n\n        在血管外面时病人呈现的现象就是表虚掉了，因为湿不在表。为什么会表虚掉？ 因为我们的血脉带来我们的免疫系统的营养，我们的（气）能量，结果能量没有达到皮肤表面，当然会表虚，所以会流失掉很多 津液。这个时候我们要用防己，防己能够排除血管外面膜中的湿，防己长得样子像车轮一样，中间一个洞，呈放射状，防己因为长成这个样子，所以防己就会绕着血管外面走，它能够去血管外面的湿。\n\n       为什么要用黄耆呢？ 因为黄耆本身功能是补气的。它跟附子不一样。炮附子是固表的，一吃下去，汗就停止流了。所以我们遇到桂枝汤证的病 人，如果被医师开发表药太多，造成病人汗漏不止，呈现出脱水的时 候，此时我们就用桂枝汤加炮附子，不用黄耆，黄耆是补气的药，将病人的气加强起来固表，而炮附子很猛烈，能很迅速的将毛孔收敛起 来、所以炮附子是紧急的时候使用的。随便给炮附子，会使本来的风湿需要发汗来发掉湿，结果炮附子一下去，病人就会从防己黄耆汤证， 变成麻黄加术汤证，湿跑到肌肉外面但是无法出表，因为被炮附子固到了。当你晓得这个病在这里的时候，我们一剂防己黄耆汤下去，病 人也会得汗则解。\n\n      白术甘草去里湿，主要的症状是身重，就是全身关 节重。因为湿性是沉着、黏着的，所以就会停留在关节里面，或是停 留在身体下腹部位。因为湿都在里面，就会附着在血管的旁边，这就 是里湿了，所以从这三个汤方可以看得很清楚如何使用它们的时机。\n\n      麻黄加术汤，专治寒湿在表。寒湿在肌肉上面就是麻杏薏甘汤。如果到了血脉神经上面的话就变成防己黄耆汤。此时主要的症状就是表虚 了，表虚的话一定会有汗这时我们就会到用防己黄耆汤。\n\n这是告诉我们如何依据症状去区分它？如何去使用它。', NULL, '防己黄耆汤', NULL, NULL, NULL, '20、风湿 ，脉浮 ，身重 ，汗出恶风者 ，$f{防己黄耆汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280517, 'FF4AC9D4850545E1F0C387F2DCD8E564', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8073, 443, 905004019, '     如果到了黄昏的时候病情会加重，这个中医就叫作风湿。这个病是因为伤于『汗出当风』。所以流了汗千万不要正面吹到风，或者是 『久伤取冷所致也』，就是你时常坐在很潮湿的地方，这种情形发生于坐在牢里面的人最多了，从牢里面出来的人得到风湿，大部分都是麻杏薏甘汤证，或者外岛当兵回来得到风湿的，也是麻杏薏甘汤证。 这种症是湿已经渗到关节里面去了，引起的痛，也是属于寒湿的一种。\n\n        麻杏薏甘汤和麻黄加术汤这两个治疗风湿处方，症状看起来很类 似，但是有个差异，临床上看的时候最清楚，麻黄加术汤就是痛，皮 肤表痛，麻杏薏甘汤有个特徵，病人的痛是在关节中，特别是皮肤表 面上黑黑的，所以当中医看到病人皮肤特别干燥又兼有风湿关节痛 时，就是麻杏薏甘汤证了。\n\n        这两个症有一个区别，就是湿所在的位置 不一样。一个是在皮肤表皮之下，一个在表皮的第二层的地方。\n\n       为什 么要用薏仁？ 因为薏仁能够进入中焦，能够进入脾脏，薏仁能够去湿。 「老师，中焦的湿白术也可以去除，为什么一定要选用薏仁？ 」这就 是我常常讲的，张仲景用麻杏薏甘汤的薏仁有两个功能，第一个，凡是仁剂一定可以通利大便，可以让湿往下焦走。薏仁还有一个特殊的功能，它能够收表湿，治疗皮表太湿所引起的皮肤病。像有的小孩子 皮肤化脓，长了很多疮在上面。疮生出来后就产生很多脓水，此时我 们就可以加薏仁进去，因为薏仁能够收敛表湿。所以皮肤科的药我们常常用薏仁，还有连翘，记不记得麻黄连翘赤小豆汤证，伤寒论中有 介绍过。\n\n        薏仁就是平常吃的四神汤。你有没有听过有人吃薏仁死掉， 没有对不对还有人把它拿来当饭吃。因为它的淀粉质很多，所以对肠胃功能很好，又好吸收，一般来说湿在中焦的人平常肠胃消化都不是很好，你把麻黄汤里面的桂枝拿掉改成薏仁，就是麻杏薏甘汤。如果是麻黄、杏仁、桂枝、甘草的话就是麻黄汤，而麻黄汤会发汗发太快， 结果造成风去了湿还是没去，如果把桂枝拿掉，因为桂枝可以提升麻黄到表上，麻黄如果没有桂枝的话，麻黄就无法到表，所以吃下去之 后也只是发出微微的一层汗。很细的一层汗，比例按照书上看就可以 了。这是麻杏薏甘汤跟麻黄加术汤不同之处。\n\n       还有一个，麻杏薏甘汤常常使用于当气候要变之前：「老师、外面气候阴雨了。」只要一遇到阴天，关节就开始酸了，就是麻杏薏甘汤了。因为它治疗的湿是在第二层，这湿会跟环境相感应，空气中湿度一增加病家就知道，因为直接接触于表，湿在表就会难过。薏仁在后面治湿的处方中会用到很多， 有时也用在治疗肠子里面的湿，后面我还要讲到薏苡附子败酱散，所以有很多特殊的用途。', NULL, '麻黄杏仁薏苡甘草汤', NULL, NULL, NULL, '19、病者 ，一身尽疼，发热 ， 日晡所剧者 ，名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280518, '7C782D3E4F44967C0FDBB43C737FAD32', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8074, 443, 905004018, '        麻黄加术汤用在哪里呢？ 当你检查到病人的寒湿是停留在皮表上面的时候，就会用到麻黄加术汤。\n\n      「老师，如何查到寒湿在表？ 」 这的确是个问题，仲师就讲了你看「湿家，身烦疼，可与麻黄加术汤，发其汗为宜，」因为本来病人就有湿在里面，平常的湿运动流汗后就好了，湿在身体里面平常是没有什么感觉的，一旦得到麻黄汤证，寒将表束住了，就会产生痛，原因是身体上的湿没有办法从皮肤表面散 出来，这个湿是源自肺再到皮肤表面，当皮肤表面上受到寒时，要让病人的毛孔打开来去寒，一定要靠麻黄汤，而麻黄汤一下去就会发汗， 但是如果遇到湿家，张仲景前面有讲过，湿家发汗时会让风去湿没去， 对不对？所以要加白术在里面。白术是去湿的，麻黄汤是去表寒用的。\n\n      如果是里寒湿就不要靠这个药，这样大家就会区分出来了，所以查到病人有表寒湿的话一定是无汗的现象，当病人已经有麻黄汤证，我们知道需要发汗，但是如果你遇到病人是麻黄汤证，全身骨节酸痛，然 后你又发觉他湿很盛；这时你就不要单纯的开个麻黄汤，要加白术在里面。麻黄加术汤还有个地方也需要使用，就是黄，皮肤发黄的时候， 黄，暗黄、阴黄的时候我们也会用到麻黄加术汤，为什么？ 因为我们人本身的肺里面是湿热的，湿在上焦在肺里面的时候，肺本身是体热宣泄的地方，当肺里面湿太盛时，热就闷在里面出不来，热出不去了 后，肺本身主气，正常人的皮肤也在呼吸的，当肺里面的津液出不去， 外面的气又进不来，就是因为被湿挡到了，湿慢慢的就闷在里面，于 是造成湿热闷在肺里面没有办法发散出来，结果病人就会发黄，这个 时候也是麻黄加术汤证。', NULL, '麻黄加术汤', NULL, NULL, NULL, '18、湿家 ，身烦疼，可与$f{麻黄加术汤}，发其汗为宜 ，慎不可以火攻之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280519, 'BE0645C8C9CC2A382B8100CA1877AA61', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8075, 443, 905004017, '     『湿家，病身上疼。发热面黄而喘，头痛鼻塞而烦』。我们在刚开始时如何就知道这个病人是属于湿家？很简单「舌头伸出来我看 看。」 一看，此人舌头黄黄的，厚厚的，舌苔很黏厚，嘴巴里面口水 很多、很黏，这就是属于湿家。\n\n       如果病人是『面黄而喘，头痛鼻塞而烦，其脉大自能饮食，腹中和，无病。』这自能饮食，就表示腹中和， 就是代表说中焦下焦没有病，\n\n     『病在头中寒湿。』有这种症状的话我们就知道，病人的湿是在脑和鼻子的中间，就是眼睛额头之间，湿在这 个地方就会产生鼻塞的现象。由于湿的性很黏腻，所以会把鼻子堵到， 病人会喘得呼吸不过来，只好用嘴巴来呼吸。遇到这种情形时我们知 道湿是存在鼻子里面，类似西医说的鼻窦炎，鼻蓄脓等等使用很多名辞。\n\n     『内药鼻中则愈。』仲师认为此时药要直接放到鼻子里面去，效果最好。因为病人只有湿累积在鼻子里面，我们只需要去鼻子里的湿就 可以了。如果用嘴巴将药喝下去，结果药跑到肚子里去，治疗上就会慢许多，不如直接从鼻子将药喷进去。所以我们在治疗鼻窦炎时，除 了下针之外，平常不需要使用内服处方，应该使用喷剂。如果我们用 针治，穴道可以选用迎香穴，如果是鼻子有流脓，鼻水、鼻涕很多， 我们就灸上星，这也是鼻科的大穴。百会、前顶都可以用来治疗鼻病。 背后的风池、肺俞等穴也可以治鼻病，因为肺开窍在鼻子。\n\n       迎香穴这两个穴道你针扎下去的时候，如果当场鼻塞的现象没有 通畅，表示没有扎到迎香，所以如果针下去没有感觉你不要怀疑针灸术不对，而是你太差了，是针下的不对。如果帮病人扎迎香扎完后效 果不彰，可以加针和髎去辅助迎香，这是手阳明大肠经的穴道。足少阳胆经的风池穴，督脉上的上星、前顶、百会等通通可以下针帮助治 疗，膀胱经上的肺俞，用俞募穴互相配合来治疗也很好的。你也可以 配些辛辣的喷鼻药，直接喷到鼻子里面。如果是一般的流鼻水，鼻水像水龙头一样流出来，就不需要用喷鼻药。回家你们大家自己用菖蒲 粉就可以，选用石菖蒲就很好用。菖蒲长在石头上的就叫做石菖蒲， 菖蒲如果长在水里面的就叫做水菖蒲。石菖蒲我们可以拿来喷鼻子的，喷进去以后会感觉到很呛鼻，于是就会一直打喷嚏，水就跟着一 起流出来，直到流干为止，辛夷花也有这种效果。\n\n       如果是脓鼻涕的话力量就不够强了，需要将矾石跟麝香二药配在 一起，专门用来治疗鼻窦炎，效果非常好。当然喷的中间很难过，药散在鼻腔里是很辛辣的，病人会一直打喷嚏，但是宁可难过一下也不 要开刀，你知道为什么不要开刀？ 因为到现在为止还没有人的鼻窦炎 是因为开刀而开好的。许多病人在开完刀后，人都还躺在病床上，鼻子又塞了，没有用的，主要原因是西医不知道湿的源头在哪里。喷鼻药能够让鼻窦部位变得很干燥，因为麝香跟矾石的交互作用。\n\n       而水菖蒲呢，过去在用水菖蒲的时候，是把菖蒲先风干，晒干，等到干了以 后就放在仓库里面储存起来。大多是什么时候用，大家你知道吗？是用在水肿。病人水肿肿到皮肤都变透明的，整个皮肤都因此绷的很紧。 这个时候我们把干燥的水菖蒲拿出来，用火烧，菖蒲像稻草一样，烧 过以后会变成灰，再将灰混合些麻油涂在皮肤上。涂上去以后让病人躺下，等一下病人就会开始小便，积水就会被排出来。', NULL, NULL, NULL, NULL, NULL, '17、湿家，病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大， 自能饮食，腹中和无病，病在头中寒湿 ，故鼻塞 ，内药鼻中则愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280520, '3AA0A51520F8CA28BE17F61BEE69BBB0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8076, 443, 905004016, '      这段话的意思是当天气阴雨不止，空气很潮湿时，此时医师开出发大汗的药物给病人服用之后，这会让风气去了，但是湿气还是存在。\n\n       为什么会如此呢？ 因为当病人发汗时毛孔会张开来，正好遇到气候是阴雨绵绵，这会让湿又跑回身体里面去。『\n\n      若治风湿者，但微微似欲汗出者，风湿俱去也。』所以我们开给风湿病人吃发表的药时，病人应该是出现全身微汗表示病去，而不是大汗淋漓，因为大汗表示迅速出汗，而湿行是很慢的，因此会造成风去了，而湿还是停在身体里面， 如果是微汗出而且摸上去有很黏的感觉，才表示湿出来了，所以我们 运动完得到的汗，跟我们洗完澡以后得到的汗摸起来是不一样的，运动完的汗是黏黏的，很湿，因为你动了，湿就出来。洗澡后流的汗， 滑滑的，就不会这样，这两个是不一样的汗出。\n\n      大家现在看金匮就晓得，仲师虽然分出很多篇，但是基本上方子还是以桂枝汤为主，中医治疗风与湿，如果只是单纯的表风，就是太阳中风，光用桂枝汤就可以去掉了，但是如果我们要治疗风湿的时候就不同了，我们也是用发汗法，张仲景在这里就特别提出来，发汗要发汗得很有技巧。你如果发汗汗太多，结果汗出来，风跑掉了，湿还没跑掉，因为病人不单单 是风症。\n\n     『但风气去，湿气在』所以不会好。『若治风湿者，但微微似 欲汗出者，风湿俱去也。』这个病人感觉到说好像要出大汗，结果你 一摸病人感觉只是出了微微一层汗，这才是完全的发出来了、所以处 方的剂量要控制得很好，这是中医治疗风湿的一个标准的原则。过去大家学的伤寒论讲的都是纯表风，桂枝汤就是去风的，遇到风湿病人时该怎么处理呢？后面会区分出几种状况，分别使用几种不同的处 方，处方为什么要区分呢？ 因为湿出现在不同的位置上，所以要使用不同的处方。', NULL, NULL, NULL, NULL, NULL, '16、风湿相抟（应为『抟 tuán』非『搏』，后文同此），一身尽疼痛，法当汗出而解，值天阴雨不止，医云：此可发其汗， 汗之病不愈者，何也？\n\n       盖发其汗 ，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，但微微似欲汗出者，风湿俱去也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280521, 'A78F42908D068E0C44FD2B6A4AEC0427', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8077, 443, 905004015, '       湿家不可攻下，对于湿家我们要去湿的唯一选择就是利用温化来 利小便将湿排除，记住这个原则。如果使用攻下法，会造成额上微汗 出，也就是有一点点汗出来，不是大汗淋漓，如果是微汗出代表阳已经绝。因为病人被攻下以后造成他的阳气没了，就会出现此一状况。 \n\n       我们所谓阳气，我再重复跟大家讲一次，就是我们吃在胃里面的营养食物，本应该提供营养给我们身体用的，结果这个食物被湿堵到了， 你应该去湿才对，结果你去攻下，一攻下后肠胃里面的营养没有了， 本来病人已经没有吸收到营养，又被你攻掉，肠胃的津液更少了，这就比较危险。如果攻下了以后，病人出现小便利，就是小便一直不断的出来，照理说湿家的话小便应该不利的；现在反而小便利了，这就是阳已经虚脱了。如果下利下止者，就是里阴脱了。所以当一个人被吊死时，在断气的刹那间，小便大便会一起出来，小便出来叫做阳脱， 大便出来就叫阴脱，这就是阴阳两脱之症，见到这些症状时表示病人已经死了。', NULL, NULL, NULL, NULL, NULL, '15、湿家下之，额上汗出，微喘，小便利者，死；若下利不止者 ，亦死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280522, '82D28AA0751C9BABCC7A32B09CB11700', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8078, 443, 905004014, '       这个湿家，但头汗出的现象很待别。因为我跟我妈妈在一起的时间不多，有一次我妈妈得到葛根汤证，当时我刚好去钓鱼回来，室内比较黑暗，一进门我爸说：「你妈妈感冒发烧你去看看她。」当时我进 到房间摸我妈的脉，再加上一问，就知道她得到葛根汤证。我说：「我去拿药。」我到诊所去拿药。吃下去葛根汤以后就好了，第二天脸变桃子脸，那种脸是不用去拉皮的，整个脸就像刚整形过美容拉皮，皱纹都没有了，整个脸肥肥的很大一个，就是变成大头小身体，她原来头就很大，现在头更大！然后脸红红的像桃子一样，我说：「你舌头伸出来我看看」，一看那舌头是黄黄厚厚的，湿家！湿家之人我们开葛根汤下去取汗的时候，发汗后不单是把表邪去掉，原来停在中焦的 湿，也同时被我发到脸上面来了。\n\n        葛根把中湿带到整个脸上面，如果 湿是在下焦，我们利小便就好了，如果湿在皮肤表面，我们发汗就好 了，但是湿在中焦就会造成但头汗出的现象，她平时头上就容易出汗， 汗会像雨水一样滴下来，时常看她头发整个都湿的。半夜又加上室内光线较暗，于是我没有注意看，这疏失是在我身上。结果她的葛根汤 证是没了，可是中焦的湿被我发到脸上去，所以给湿家发汗的时候要 特别小心。\n\n       张仲景立方的时候开出桂枝汤加白术茯苓，就怕遇到病人 原本是湿家。如果病人是湿和热都有的话，除了加入白术茯苓之外， 你还需要增加一些去热的药，像黄芩、黄连之类。如果遇到寒湿就要 加白术、附子，就是将术附汤，加在桂枝汤里面。当时我如果开的是 葛根汤加白术、茯苓就不会发生这种情况了。\n\n       平素就有背项强的人，同时又有里寒湿。里寒湿很盛的人一旦遇 到温热就会感觉很舒服，所以他会想比较靠近火，烤一烤很舒服。先生你如果有很重的风湿你烤一烤会很舒服的。如果遇到这种病人，你用攻下法，因为湿家的病人，本来就是肠胃的功能不是很正常，脾胃比较寒的人，就是蠕动比较缓的、吸收不好的才容易成湿，这是最早期湿家的表症。湿如果进入肝脏了，就要用乌梅丸。此条是说，一般 我们遇到脾胃比较寒湿的病人，如果使用攻下的药来攻，而攻下的药都是属于寒凉的药，寒药再遇到胃气的寒，就会变成哕，打嗝，变成茯苓四逆汤证了。\n\n        如果遇到胸腔素有寒之人，或者是舌上苔很厚的病家，此时开攻 下的药物就会造成病人胸满，小便不利，病人并没有因为你攻大肠而症状好转，他的病变是在三焦淋巴系统里面，结果你去攻大肠，这是如同鸡同鸭讲，这个药跟症完全不对。\n\n      舌上如有厚苔者，苔很黄浊， 『以丹田有热，胸上有寒』如果遇到这种情形，下寒上热的病人，『渴欲得饮而不能饮』嘴巴很口渴想喝也喝不下去，就是『则口燥烦也。』 这种都是只有湿才会造成的。湿在身体里面的时候，你就常常会有恶 心的感觉，就已经表示你有湿囤积在体内，如果这个湿停在四肢关节上时，就会造成酸痛，湿停在不同的地方，病人就会出现各种不同的症状。\n\n        造成这种症状的原因有可能是工作的环境或者是医生的误诊， 就像我这样子一剂葛根汤，就让我妈变成上热下寒，脸红的像个桃子 脸，下面小便变少，必须赶快去解热，否则会口渴不能饮，这是因为 湿家本来就有停水很久没有去，然后才成为湿的，例如我们平常喝水到胃里面，胃是最热的，水一下去就变成气上来了。如果胃寒掉了水就会停在那边，停久了就变成湿。因为湿最早是出自水饮，所以素有积湿的人如果湿是停在上焦，会让胸腔里面很寒喝不下水，因为里面 水湿已经很多了，所以根本就喝不下去，于是病人就出现『口燥烦』， 就是又心烦又口渴又想喝水，喝水又喝下下去的奇怪现象。', NULL, NULL, NULL, NULL, NULL, '14、湿家 ，其人但头汗出 ，背强欲得被覆向火 ，若下之早， 则哕 ，或胸满，，小便不利 ，舌上如胎者 ，以丹田有热 ，胸上有寒 ，渴欲得饮而不能饮 ，则口燥烦也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280523, 'C80CA9DF32C2AD4D3BA5FF01516A34C6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8079, 443, 905004013, '       平常中湿很盛的人，有时候并没有病痛的。我常常要求病人说「你 将舌头伸出来让我看看」一看，舌苔呈现很厚，我不管你是黄的厚还是白的厚，也就是说不管你是寒湿还是热湿，反正都是湿！这个时候 你可能没有病，坐在那边好好的，可是你已经有湿在身体里面了，遇到这种情形的时候这种人就叫做湿家。\n\n     湿家得到病如果『 一身尽疼， 发热，身色如熏黄也』。这个是属于阴黄。\n\n     当我们得到太阳证后，如果你没有湿，就很正常的出现太阳症候，也就是单纯的$f{桂枝汤}证。湿家在得到太阳病之前，本来体内就有湿囤积，当表受邪后，里热要出 去，就是中医讲的阳，西医讲的免疫系统，想要出去跟病邪相抗，结果被湿挡到了，病毒因为湿阻而无法进入体内，于是就会停在湿的外 面，我们的阳气被阻在里面，正气与邪气站在两边，中间给湿阻到了。 这个时候热散不出，我们体内的热是因为被表症激发起来的热，结果热发不出去，造成熏黄。\n\n       这时我们就要用麻黄汤加白术。麻黄加术汤 在后面会开方子给大家，此处我们先不讲方子。麻黄加术汤吃下去了以后，这个处方专门用在阴黄证。\n\n       我们中医将黄区分为阴黄与阳黄， 阴黄是黎黑的，就是看起来病人是黑黑黄黄的，这就是湿家，「舌头 伸出来！」舌苔很黄表示体内很热。那是因为湿停留在四肢的肌肉上 面，这个时候我们要用?黄加术汤来发表。\n\n       麻黄加术汤吃下去以后病 人是出微汗，就是微微出一点点汗，然后你摸他的汗，是黏答答的如果是湿在关节里面，你要是想把湿从小便排出去，这距离就会太远了， 不可能做到的，只有直接从表来用汗解。我们身上很多管道可以被利 用来排除病邪，而仲师也都考虑到了「这个离毛孔比较近，我们就叫病从毛孔出去。」麻黄加术汤，是专门给病人出现阴黄的时候用的。', NULL, NULL, NULL, NULL, NULL, '13、湿家之为病 ，一身尽疼 ，发热 ，身色如熏黄也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280524, 'FCCF0E8B910BB97F04CE4A7159A02D69', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8080, 443, 905004012, '        中湿就是中焦里湿很盛，叫中湿，也叫做湿痹。湿痹的症候有哪 些呢？怎么知道有湿痹？\n\n       病人的主症，第一个是小便不利，大便反快。 这个时候当利小便。\n\n      为什么会有湿在身体里面呢？ 中湿之人从哪里来 的？这有两种情形。\n\n      一种是天气太热造成的，我们在逛街买东西时， 却热的一身汗，流汗时是没有心情看的，看到什么东西都不喜欢。为 了避免流汗，于是就跑到冷气间里面。在外面逛街很热，流汗流很多， 突然进入冷气间，表一下子被冷气束到了，于是汗水停在体内没有出 去，长年累月以后体内就生湿了，然后再慢慢的渗到关节里面，这是 第一种。\n\n      第二种，发生于劳力之人，夏天时工作造成身体很热，到了 晚上，天气很凉快，工人吃完饭洗个冷水澡后，就躺在外边乘凉，晚 上半夜的时候又当风，因此体内的湿就无法散出体外，这也会生湿。 还有就是妈妈们容易得到中湿，妈妈在全家人都睡了以后，还在那边 洗衣服弄得一身汗，汗出以后再去洗澡，之后休息一下，这时就当风而坐，风吹到身体感觉得很凉快，此时她的汗还是继续在出来，于是造成寒气束到表，这也是会造成湿气停在体内。这两种状况其实是一 样，只是来源不一样，结果都造成湿渗在身体里面。\n\n        当湿渗在关节里面，这湿又没有办法渗出去时，湿气就会慢慢的 囤积起来，如果过多的湿停在关节中间，关节就会痛，累积在肌肉里面，肌肉就会酸。\n\n       这种渗在关节里面的湿，会跟外面的气候相呼应， 气候一变冷的时候，湿就会反应说：「我在这里」，所谓同气相求，此时病人就会感觉到酸痛了，去湿要靠温化才能去除。因此病人一接近热，就感觉酸痛减轻了。\n\n      所以风湿关节炎发生酸痛的时候只要一接近热，一烤火就会很舒服，气候一变，要开始下雨了或者外面环境一改变病人马上就感觉开始酸痛了，这是因为湿跟环境相通所造成的。\n\n     湿， 性很黏腻，很浑浊，堵到三焦以后小便就没有办法正常的排出去了， 为什么会这样呢？ 当湿渗在三焦里面会影响到脾脏，当三焦油网里面都是湿时，三焦是决渎之官，水道出焉。\n\n     结果水就跑到大肠里面去了， 这个原本是要从小便排出的水，结果排出下去，于是就从大肠走，结果大便拉出来都是稀的。\n\n    遇到这种情形，就是中医所认定的湿痹症侯， 这个时候我们当利他的小便。如何利小便呢，像五苓散，真武汤等。 简单区分这种治湿的方法，我们平常在治湿的时候，如果遇到湿停在皮肤表面，四肢关节上面我们是发汗来解。如果湿是在身体里面的话， 我们是利小便来解。后面会介绍到几个发汗的方子还有利小便的方 子。', NULL, NULL, NULL, NULL, NULL, '12、太阳病，关节疼痛而烦，脉沉而细者，此名中湿，亦名湿痹。湿痹之候 ，小便不利 ，大便反快 ，但当利其小便。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649775506280525, '9623D00CA2F23AD96BFB51DDBF18D572', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 12:03:20', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8081, 443, 905004021, '        诸位在伤寒论是不是也读到过这一段，仲师就是要再提醒我们， 什么是湿？如果单纯只是有湿症，病家就会抱怨身体不能转侧，不呕， 代表没有少阳证，不渴，代表没有阳明证。\n\n       此处的『脉浮虚而涩者』 这里讲解的就比伤寒论更深入一些。脉浮虚，浮代表病在表，意指表虚，涩脉，代表血不足，如果是芤脉，根本就是已经失血了。这条辨就是说当我们知道病人有表虚，又同时见到病家有血不足的状态之 下，得到风湿时如何处理。\n\n       临床上我们在用药时，这个方中牵涉到一个药叫做白芍，一般南派的医生的观念认为说：「芍药，补血的。」所 以四物汤里面会用到芍药。而经方家的观念不是这样的，芍药性酸， 主收敛又能活阴血。所以芍药可以攻瘀、活血。所以芍药能够止腹痛， 如果病人出现血虚时，我们经方家是绝对不会去用芍药的，因为芍药味酸，而且带苦味，故主泻下。所以芍药在我们经方家使用时是被归类为攻血剂。\n\n        例如张仲景用芍药甘草汤，去治疗腿不得伸曲。如果我们把桂枝汤中的白芍拿掉，桂枝汤本来是要解除病在肌理时用的，现在用炮附子来代替芍药，是因为我们知道是寒湿停留在肌肉中，才造成病人身体烦疼，不能自转侧，而去寒就要靠附子。所以将桂枝汤中的白芍拿掉，改成炮附子、『附子三枚炮去皮』炮用。\n\n       经方中『阳旦所以用生附者，所以助里阳而泻在表之水气也』用熟附的话主要是取其『助表阳而温化其湿也』所以治湿，大部分我们是用苦温化湿法，我前面有跟诸位介绍过为什么要吃乌梅丸，因为乌梅丸就是苦，而且温，苦温能够泻肝胆的郁热，就是有湿阻在肝胆里面，酸的东西对肝非常的补。现在大家看到这个条辨以后就了解到， 因为病人是表虚，所以我们用桂枝，桂枝能走表，而里面的寒很盛时， 我们必须用附子去除寒，因此不需要用到芍药。\n\n      炙甘草、大枣、生姜 都能够温助里阳的。炮附子药性很热，能够让表阳旺起来。\n\n     如果遇到病人有『大便坚，小便自利』此时就把桂枝拿掉，加白术与附子，就是白术附子汤。为什么把桂枝换掉变成白术，同样的是风湿相抟，因为这二个处方都是去里湿用的；不同的状况就用不同的处方，当病人的舌苔又白又厚，然后摸到脉是虚而无力又涩，病人会流汗出，但是汗流出来照样身体很沉重，全身关节酸痛，这表示湿是积在肌肉之中， 此时就是桂枝附子汤证了。这个术附汤也是里湿很盛用的，里湿盛但却是在不同的位置。\n\n        病人的症状是『大便坚，小便自利』，这个大便坚的原因，是因为有湿隔在中焦，造成肠子里面的津液就不够了。这 个时候我们必须开个去湿的处方，而湿是我们身上非常难去除的一样东西，如果我们开一个处方直接攻下，有时候攻下的力量太快，结果湿没有去掉，反而让肠胃里面的营养都跑掉了。所以此时张仲景就主张用术附汤，看看术附汤里面的内容，就是白术、附子，还有生姜、 甘草、大枣。因此术附汤，就是能够直接进入脾脏将里湿逼进三焦油 网系统中。然后再到皮肤表面一路直接发出去。\n\n       术附汤喝下去的时候，诸位看，『上五味，以水三升，煮取一升， 去滓，分温三服。一服觉身痺。半日许再服。三服都尽，其人如冒状， 勿怪。即是术附并走皮中，逐水气』说明服后头会昏。\n\n      『商昼云：若药勿暝眩，厥疾弗瘳（chōu）。』吃了药，如果病人没有头昏，这个 病不会好。（注：服后头会昏）就表示药开得很恰当。\n\n        仲师说：『篇中大剂每分温三服，独于白术附子汤。特别讲到这个症状。』言一服觉身痺，痺者，麻木之谓。下面写到『凡服附子后，不独身麻，即口中额上俱麻，否则药未中病，即为无效』药就不会有效，这里说的就是 使用附子的剂量问题，有的人吃附子吃下去，处方只开了两钱三钱他吃下去没感觉，就是等于病人根本没有吃到附子，所以我们不是说要 病人他一定要吃得很多，不是这个意思，而是比如说一个汤剂，熬好 以后分成三碗，第一碗喝下去后，没有什么感觉，隔三个小时再喝第 二碗还是没有感觉，就代表药力没到。\n\n      如果说：「那我明天再喝」，这是不行的，因为药力还停在那边，只是没到而己，你必须要追击，那就再把第二碗喝下去，喝下去如果头昏就停药。如果喝到一半就开始麻，那一半就停掉。如果喝完第二碗还是没感觉，再等三个小时后还 是没感觉，你就让病人再喝第三碗。如果你停下来，到第二天才再喝 第三碗，等于是重新再来过一次了，重来的时候，表示之前的病并没有进展。\n\n       很多的医生不了解这一点，一看喝下去病情却没有进展，第二天就更换处方，这就错了。南方温病派的中医处方中的寒药热药，没有像经方这么强的，南方温病派使用的药，你吃到好坏都没感觉。如果我们开真正的经方，伤寒论、金匮中的方子，吃下去不是一就是零。 病人如果没有好，当天就会有反应。一定有相反，逆症的反应。\n\n         所以 如果病人吃了那么大剂下去没有感觉，代表你这个方子是正确的，只是剂量不够，或病人服的方法不对。吃下去全身开始好像中毒了，就是药力达到病灶了，可以停掉。如果你说：『老师我舍不得。』再熬， 再喝下去，就会太过了，因为那是药。不叫做食物，食物还可以撑下 去，药硬撑的喝下去，吐都吐不出来，怎么办？\n\n       特别在介绍术附汤时 要再提醒大家一次，术附汤的剂量是很重要的。白术一两，附子一枚， 如果平常我们$n{一枚生附重量差不多有一两二钱到三钱}。而经过$m{炮炙以 后，差下多只剩下三钱半，一枚生附子只剩三钱半重}。\n\n       所以如果将白术跟附子放在此地的剂量上来说的话，就等于要重用白术，然后靠附子把白术推到表面上。\n\n      为什么要重用白术？ 因为白术可以将脾脏里的湿，还有三焦湿和肌肉的湿，全部推到皮肤表面上出来，所以要重用。 附子差不多三钱半，炙甘草差不多二钱，生姜使用两片三片的就够了， 红枣约六个，这是桂枝附子汤跟白术附子汤两个区分的地方。当里寒湿出来以后，同时要预防肠胃津液会跟着耗损，所以在使用发表药的 同时要加草姜枣来补足丧失的津液。\n\n     被发出去的汗在皮肤表面上都是黏黏的，就是真正的湿，这些不要的湿要把它排出去，真正好的津液 还是慢慢会回流到身体肠胃里面来。肠子里面得到津液后，肠胃就开始蠕动，大便出来后，就不会那么硬了，张仲景这个条辨中立了两个 方子，就是怕一些医师看到病人有湿积，又同时看到病人大便很硬， 结果就去攻大便，本来里面就已经很寒很湿了，然后被你一攻下，病 人成为又虚又寒又湿，实际上他的大便不出来原因是因为湿堵在那边 了，使得肠胃的津液没有办法正常的分泌，才造成大便很硬。\n\n        当吃了 白术附子汤之后，寒湿就会从汗解，汗解完了以后，正常的津液就会回到肠胃中，这个时候大便就软掉了。如果需要攻下时，病人一定会 有烦躁，舌头很黄很焦的等症状。然后你再问他大便如何？如果他己经五天不大便了，此时如果你还给他白术附子汤吃，岂非在害人中， 此际就要赶快先将大便清出来，五天不大便，这个大便是很可怕的。 比如将一个便当放在太阳底下晒五天，你就知道会如何了。像曹颖甫， 唐容川等经方家对于生附、炮附使用上都如家常便饭般的在用的。而温病派呢，看到生附就逃走了。他们一直错误的在认定「生附怎么可以用？ 」他们不知道有多么好用。\n', NULL, '桂枝附子汤,去桂枝加白术汤', NULL, NULL, NULL, '21、伤寒八九日，风湿搏相 ，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利 ，$f{去桂枝加白术汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649828958269509, 'A7F084A179BD41D19EA22122C9F26708', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 15:40:50', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8082, 443, 905004025, '       瓜蒂散是吐剂，当病人本身就有里热，因为中暑的病人平常运动就流汗流得很多，因此热经常是呈现浮在身体里面的状态。\n\n     这时没有表症，单纯是里热，此时病人因为有里热而将身体浸泡在冷水中，想去热，然后又饮用大量的冷水，结果外用浸泡冷水造成身体疼痛，喝下许多冷水在胃中又无法气化，加上体内又因为津液不足而很燥热难耐，此时就要用这瓜蒂散。\n\n       瓜蒂这个药，如果是喷在鼻子里面，会造成打喷嚏。如果是含在嘴巴里面，就会想吐。病人喝下就会吐出许多冷水，我们不用麻黄发汗为什么？ 因为他本来身体里面就有浮热，加上本身津液又已经伤到了，所以我们绝对不可以再用麻黄汤去给他发表。\n\n       也就是说这是因为病人津液不够了才产生的热，你再用麻黄汤发汗就会更伤津液，这个时候用瓜蒂散最好。诸位你有没有感觉到，每次你吐完的时候都会流汗。如果你不相信，等一下下课到旁边，我抠你喉咙让你吐，吐完后你再摸摸身体，就会发现身上都是汗。人吐会出汗，就是利用吐法让病人发汗，不要用药去发汗，因为病人津液已 经伤到。\n\n       如果表热跟里热加在一起，成为高热的时候人参瓜蒂散也没有用的，就要靠白虎人参汤下去救热，所以白虎人参汤喝下去病人也会流汗，热就会整个退掉。\n\n      如果病人没有表热，只是身体里面的浮热，感觉闷闷的，按脉又没有很浮，病人又感觉昏昏沉沉的，有一点发烧又不是很烧，你想想这怎么办？只有让他轻微的发一点汗，把热消掉就可以了，此时可用瓜蒂散下去，吐出水后，病家皮肤会发一点点表汗， 这个浮热就会离开身体。\n\n       所以病的深浅轻重张仲景都考虑的很清楚， 绝对不能让病人身体在有里虚的时候还在给他攻下，因此仲师就跟你说下利不止者死，他的目的就是提醒你，病人因为有里虚所以不能攻。 当病人身体很虚弱时，我们又需要去发此人的汗时，该怎么办呢？可以用一点点瓜蒂散来取吐得微汗，张仲景的意思就在这里。', NULL, '瓜蒂汤', NULL, NULL, NULL, '25、太阳中暍，身热疼重 ，而脉微弱，此以夏月伤冷水，水行皮中所致也 ，一物$f{瓜蒂汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649843817664581, '057F2852C8110FA25B9F177DB298AC6C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 16:41:18', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8083, 443, 905004024, '      『太阳中热者，喝是也』就是中暑了。\n\n     『汗出恶寒，身热而渴， 白虎加人参汤主之。』白虎人参汤本来的目的就是为了要补足血里面 丧失的津液，津液丧失就会有壮热的症状出现，临床上我们中医的白虎人参汤证，就是西医说的脑膜炎引发的高热现象，同时可见病人流 出许多汗，然后病人感觉身体较冷，但是体热却很高，大便又很正常， 又没有发痉，此时如果遇到发痉的病人，如果是刚痉就是—葛根汤证。\n\n     柔痉的话就是—瓜蒌桂枝汤证。如果都没有发痉，也不是承气汤证时， 那就是白虎人参汤证了。所以白虎人参汤一样可以治疗脑膜炎引起的高热。\n', NULL, '白虎加人参汤', NULL, NULL, NULL, '24、太阳中热者 ，暍是也 ，汗出恶寒 ，身热而渴 ，$f{白虎加人参汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649843817664582, 'F1768A3F5D0ED962F1EB19BD76FE3BD5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 16:41:18', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8084, 443, 905004023, '       什么叫中喝？就是中暑。在过去中暑的状况很多，现在中暑状况比较少，但是还是有。\n\n       为什么以前中暑比较多？ 因为以前哪有什么冷 气，我们现在是家家都有泠气，在外面很热时就进屋去吹冷气，所以中暑的现象比较少见，风疹的现象却比较多，讲到风疹，麻黄加术汤 就可以去掉风疹。因为麻黄汤专治寒湿在皮肤表面上，比如说你在洗完热水澡后，身体在流汗，一出来吹到冷空气，皮肤会很痒，或者洗完澡没什么感觉，躺在被窝里面被子一盖就很痒，这就是因为你汗水没有透发，汗水停留在皮肤表层下面，汗离开了汗腺，但是没有离开毛孔，就会停在毛孔、皮肤表面和汗腺中间的地方。\n\n        这个就是麻黄加术汤证。因为麻黄加术汤被设计成为刚好在这个接近皮表位置的湿， 服后发微汗，如果用麻黄汤发汗会太过，结果会伤到正常的津液。如果晚上吃麻黄汤，皮肤不痒啦！因为汗都发出来了所以不痒，但是早上起床后就变成大承气汤证。因为肠胃的津液都给麻黄汤发光了，不是麻黄汤证，却用麻黄汤必将太过，所以必须要知道方剂的主功能所在，开处方时才会很能运用自如，这种中暑虽然以前较多，现在比较少，但是还是会用到，要不然有一天走在沙漠里，你看到一个人中暑： 「惨了！这个人中暑了。」此时你就不会处理了。\n\n      关于中暑，张仲景立有两个方子，就可以治疗中暑。一个是白虎人参汤，一个是瓜蒂散。\n\n   『太阳中喝 』就是中暑了，『发热恶寒，身重 而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳， 身即热，口开前板齿燥：「前面板齿指两个大门牙很干燥。」若发其汗， 则恶寒甚；加温针，则发热甚；数下之，则淋甚。』会得到太阳中暑的人，就是因为他在大太阳底下运动或是做劳力工作的时候，身体出大汗津液丧失很多，就是在丧失津液的状况之下又得到表症，那么热的天就会得到表热，外面产生的热，再加上里面本来就很热，津液本来就不够了，这就叫做中暑。\n\n       所以表热和里热在相抗，病人就变成大热，大热的状况之下会出现病人发热、恶寒。\n\n     为什么会恶寒呢？ 因为 表水都没了，就是表虚掉了，所以病人会怕冷。所以这里的恶寒并不是直正像麻黄汤证的表寒，是因为里热太高了。\n\n    『身重而疼痛』，『脉弦细』这就代表病家的表虚掉了，\n\n    『芤迟』代表血也虚掉了。因为血 里面的水丧失很多，此时会有一个症状很特殊，就是小便完后头会这样摇一下，为什么会这样？ 因为病人水不够，当体内水不够的时候， 全身互相都有神经性的反射作用，在水不够的状态之下，你一小便， 头就会这样动一下，因为反射，这就是告诉你里水不足了。\n\n   『手足逆冷，小有劳』一动，身体会很热？\n\n  『前板齿燥』这个就是我们体内津液丧失过多了。\n\n    此时『若发其汗』你再发汗的话，病人就完了，『则恶寒甚』就会感觉身体寒冷。 \n\n   如果此时再加上『温针，则发热甚』。『数下之，则淋甚。』这里就是说如果此时你再去攻下，结果病人因为肠胃的津液已经没有了，小便 就会很浓浊，这就是病人已经处在极虚的状态之下：是坏症。\n\n    这段简言之，就是如果病人出现表热兼有里热的现象，就是中暑了。', NULL, NULL, NULL, NULL, NULL, '23、太阳中暍，发热恶寒 ，身重而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳 ，身即热 ， 口开前板齿燥 ；若发其汗 ，则恶寒甚 ；加温针 ，则发热甚； 数下之， 则淋甚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649843817664583, '30664E45DB723F679D31C834B0CD3CC4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 16:41:18', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8085, 443, 905004022, '     甘草附子汤证代表湿已经渗到关节里面去了，湿如果在内脏里面、在中焦里面、在上焦，诸位现在都会治了。\n\n     如果是湿在皮肤关节里面呢？如果靠白术附子汤，可以把肌肉里面的湿排出去，但是关节里面的湿还在，这个时候就要靠甘草附子汤。\n\n     甘草附子汤跟刚刚前面提到不一样的就是，它不是全身微肿，是湿停在关节的地方会肿得很大，这个时候，我们知道是湿渗在关节里面，使得病人呼痛。尚未碰到他，他就喊痛：「啊！你不要碰我！不要靠近我！」为什么？ 因为很痛，你一靠近他，他以为你要摸他，就会感觉更痛，关节表面整个红肿起来，这就是所谓的甘草附子汤证。 风寒与湿直接渗在关节里面造成的痛就是要靠这个方子。\n\n       如果给西医治，有些西医会用开刀方式， 把里面的湿拿出来。因为红肿又痛到受不了，脚都不能弯，于是病人就同意开刀。开刀时拿出来的都是黄水，拿完以后再缝起来，从此就 变成『鹤膝风』，膝盖就会肿成圆球般大，然后病人的小腿骨细细的， 多难看，我就治过这样病的，有位小孩子来看腿病，他膝盖就是有风湿病，才十岁啊！就被西医开刀开成这样子。来诊所的时候脚是这样弯起来拿着柺杖进来，进来时我看到他两观是黑的，我问病人说：「你有气喘？ 」「对啊」。我们治疗你这个风湿大约需要两个礼拜，而气喘一个礼拜就好了，恢复的更快。两个礼拜以后他外婆跑来找我，她说： 「我现在抓不到我的孙子了。」这就是中医经方的效果，我使用的处方就是甘草附子汤。\n\n      炙甘草，附子两枚。我们在用甘草附子汤的时候，附子跟白术差不多是等量。比如说：我们附子用五钱。白术就用五钱。甘草附子汤中附子下重手不要害怕，因为这个附子有桂枝在里面配合，此时附子一下去不会停在固定一处，桂枝会把附子带到关节去，附子就因为有桂枝而能渗透到四肢的关节里面去，附子走肾，所以能走骨节，打进关节里面要靠附子。然后白术进去收敛湿气，所以一定要重用桂枝。 你如果是你开了白术附子跟桂枝，忘了开炙甘草，结果造成风去，湿未去，因为炙甘草有减缓药力行走的速度，就好像跟其他药说「等一 下！桂枝你等一下，要等到湿通通清完，你们再一起走。」因此这处方的剂量非常严谨。\n\n       所以以后大家开处方的时候，比如说炙甘草二钱， 炮附子两钱，白术两钱，桂枝就四钱，桂枝要加倍。仲师又说上四味药。水来煮，比如说六碗水煮三碗，温服一升，一天吃三次，如果初服得到微汗，感觉很舒服了，病就解了，就不要再喝了，就能吃东西。\n\n     如果『汗出复烦者』就是流了汗以后病人还是很烦躁，风湿还是很痛， 就表示说病并没有去，那就再喝，『宜服六七合为妙。』就是再喝它就是了。\n\n     曹颖甫解释『身微肿，似当用麻黄以发汗，仲师弃而不用者， 正以湿邪陷入开节，利用缓攻也。』就是湿邪如果在表的话，我们要靠麻黄去发汗，湿邪在关节里面，此时用桂枝才是对症的，所以张仲景开治疗风湿的处方时，因为湿在不同的位置上，处方就不同，在$n{皮肤表面上的时候—麻黄加术汤}，$m{湿在肌肉里面—麻杏薏甘汤}，进入到 血脉旁边、在下焦、在我们的三焦网膜里面的时候、还有进入关节的时候通通不一样，所以经方里分出很多种的不同处方来治疗风湿。\n\n       西医学风湿就是风湿，就已经讲完了，真是很粗糙。如果说：「老师， 中医讲的不科学。」你就错了。我一直在跟诸位讲，什么叫真理？就 是由繁而简。繁进入简单的阶段，就代表他已经懂了。\n\n      比如我们在讲痉病的时候，就是西医所谓的脑膜炎，诸位知不知道西医光是讨论脑膜炎的书有多厚？张仲景两三个条辨就讲完了，而且不但讲完了，还治疗完了，处方也已经开完了，厉不厉害？所以我们大家要以身为中国人为荣。', NULL, '甘草附子汤', NULL, NULL, NULL, '22、风湿相抟，骨节疼烦 ，掣痛不得屈伸 ，近之则痛剧 ，汗出短气，小便不利，恶风不欲去衣 ，或身微肿，$f{甘草附子汤} 主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 649843817664584, '0C42A2E0FCB0295168BD3AA98190E048', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 16:41:18', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8086, 444, 905005001, '        什么叫百合病？你看他上面写『其病也。意欲食，复不能食』 是想吃都不行，既吃不下，又不想吃。\n\n     『常默默然』病人都是安安静静的都不讲话。\n\n    『欲卧不能卧』想睡觉又睡不好，想要走路又没有力 气。\n\n    『饮食或有美时，或有不欲闻食臭时』有的时候很想吃，闻到食物的味道后又不想吃。\n\n   『如寒无寒』看起来好像很冷，你问他冷，他又说没有。\n\n   『如热无热， 口苦，小便赤』。嘴巴又有点苦，小便是黄色的， 看似热症其实又不是。\n\n   『诸药不能治，得药则剧吐利』服用各类的药 又不舒适。\n\n    有时候『如有神灵者』就是突然看到什么神仙怪物之类的异象。\n\n    摸他的脉，稍微有一点数。每次小便的时候就会头痛，『六十 日乃愈』这需要六十天才会好。\n\n  『若溺时头不痛，淅淅然者，四十日 愈；若溺快然，但头眩者，二十日愈。其证或未病而预见，或病四五 日而出，或病二十日或一月后见者，各随证治之。』你说仲师讲的是 什么呢？他讲的是神经衰弱症。\n\n        这个发生在很多的太太妈妈身上，她 们时常制造出许多世界上原本不存在的问题， 比方说，「媳妇重要还 是妈妈重要？ 」可是这不能讲出口，因为心知这是不对的，但是她还是要去表现出很多动作。儿子一回家，两个人拿两双拖鞋在那边，看 儿子会穿谁拿的。日久以后，就有忧，而忧能伤到肺。\n\n        每天在那边想一些有的没有，我常讲，世界上的问题本来都很简单，可是被人想复 杂了。所以很多人有神经衰弱，因此常常生病，生完病以后还是没好。 然后你给他吃小柴胡汤，他吃下去也吐。吃什么药都不好。如果病比较深时，病人小完便就会头痛，但是六十天后慢慢会好。这是病比较深的，因为忧能伤肺，肺主魄、肺藏魄。\n\n        我们的血里面有两样东西， 一个是魄，一个是魂。忧能伤肺，魄就没有办法存在血里面。所以『如 有神灵者』就是肺魄不守。魂不能归肝，就是当肝血伤到后，人会虚弱，在肺气肝血两虚的状态下，这种虚又不是真虚，你真的开补气、 补血的药给他，他身体又不接受，吃完后又将药物吐掉，怎么做都没 有办法帮助他。\n\n       当魂不守的时候，病人就不能睡觉。我们人的睡眠是魂要归肝，人才能睡着。神经衰弱、歇斯底里的人，如果是比较严重 的，他小便一小完「哇，头很痛啊!」为什么？ 因为他身上津液不足， 所以我们在大病之后会看到这种情形。还有一些妇人，一天到晚都在担心子女，或者是一天到晚在喝下午茶，然后专门议论人家长短，自 己没有中心主见，自己也不知道自己想要什么，这种人很多，大部分 都有神经衰弱。\n\n       这种状况之下，张仲景就说：「如果六十天，小便头会痛。」小便头痛，就是病比较重，六十天会好。\n\n      如果『若溺时头不痛，淅淅然者， 四十日愈』就是小便的时候，感觉到耳朵好像有东西在吹，这种感觉， 四十天会好，因为比较轻些。\n\n     如果小便很快、头眩者，二十天就会好。 这是大病之后我们可以看到的。\n\n     这个症候中医叫做『百合病』。因为『百合』就是什么样的症状都有，也可以说他什么样的症状都没有， 你说他没病，他去医院检查他真是没有病，然而他又全身不舒服，如果做到这种人的儿子，那你就要拜我为师了，学会如何使用百合地黄汤，喝下去就好了。\n\n     后面的百合地黄证又分几种，第一种是纯百合证。还有一种是， 本来是百合证，结果被你误汗，还被你误下、误吐，于是再区分为四个方子。\n\n     第一个是纯百合证。『百合病，不经吐下发汗，病形如初者，百合地黄汤主之。』这是最初的条辨，就是单纯的百合病，单纯的百合证就是百合地黄汤证。\n\n     如果百合病被发汗了，就是原本是百合病， 结果被医师误汗了，我们就用百合知母汤。\n\n     百合病如果被误攻下了， 就是百合滑石代赭汤。\n\n     百合病如果被误吐，就是百合鸡子汤。\n\n   「老师， 为什么这些条辨不放在前面去？ 」这不能怪仲师，因为以前是用竹简 做成书的，而门槛又很高，走过去的时候小徒弟不小心勾到门槛，一 摔倒，竹简散开来，怕师父骂。只有赶快收回去，结果就弄错了。现在我将介绍的第一个处方就是百合地黄汤。', NULL, NULL, NULL, NULL, NULL, '1、论曰：百合病者 ，百脉一宗 ，悉致其病也。意欲食 ，复不能食 ，常默默然 ，欲卧不能卧 ，欲行不能行，饮食或有美时 ，或有不欲闻食臭时 ，如寒无寒 ，如热无热 ， 口苦，小便赤，诸药不能治，得药则剧吐利 ，如有神灵者 ，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅淅然者，四十日愈；若溺快然， 但头眩者 ，二十日愈。其证或未病而预见 ，或病四五日而出 ，或病二十日或一月后见者 ，各随证治之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 650456390742085, '88EA2CD7CDD48811B95F5F4DE133B25C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-03 10:13:52', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8087, 444, 905005002, '        百合七枚。诸位到中药店买百合，百合色白，入肺。百合也可以 拿来炒菜煮汤吃。张仲景为什么要用百合？这个百合滚了以后，你如果要煮百合桂圆汤，你最好先煮桂圆，先将桂圆煮熟了，等味道出来汤变浓了以后，再把百合丢下去。百合一放下去，水一滚就关火。你 说：「老师，滚久一点。」滚久了，百合就不见了，变成百合汁，黏黏稠稠的，百合一下就化掉了，所以百合是现在所有食物里面最好消化 的。张仲景一看这个人什么东西都吃不下去，必须找一种最好消化的食物，要比米饭还好消化的，如果连百合都不能消化，病人就危险了。\n\n       百合这个药的性有一点黏黏腻腻的，能够停在肠胃里面增加肠胃 的津液，也因此能够让大便排出去。百合里面淀粉质很多，又能补充 我们的营养。百合入肺，就是说百合这个药能够增加肺的津液。\n\n       为什 么要加生地黄？ 因为一个人情绪忧郁太久，会内生伏热，因为气被郁闷到，没有办法很正常的运转，于是热就会停在下焦，这个时候热会伤到血分，所以用生地黄来治。诸位看到药房里买的生地，你不要以为生地这个药会很明亮，我告诉你，它黏黏的，黑黑的。拿到白的就 是药房在骗你，拿到面粉做的给你。\n', NULL, '百合地黄汤', NULL, NULL, NULL, '2、百合病，不经吐下发汗，病形如初者，$f{百合地黄汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 650459795193925, '740A0CC45C410C636A7F81CEC7778A86', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-03 10:27:43', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8088, 444, 905005003, '       百合病本来就是因为津液不够了，身体很虚，结果医生一看他发热，以为是太阳表症，于是给予发汗药，造成津液被伤到，就是肠胃的津液没了，肺的津液也没了，这个时候病人的身体是在很虚的状态之下，我们开很强的药下去病人身体会不接受，于是病人就会吐掉又拉掉，此时只有靠百合下去把肺的津液先补足，又因为它的黏性与容易消化，因此可以停留在肠胃中，然后靠知母去消除病家的烦躁，因 为知母是除烦的圣药，这就是白虎汤里面有知母的原因。\n\n       百合要拿来做药的话需要先用水来洗净百合，洗完以后再泡一个晚上，看到白的泡沫出来以后，然后再用泉水来煎，泉水就是阴水。中医认为阴水这 个水是未经过太阳晒过，所以它能够把虚热去掉。你说：「老师我真的去挖泉水来煮百合。」这也不必要了，因为自来水已经就是阴水了， 泡自来水就可以。', NULL, '百合知母汤', NULL, NULL, NULL, '3、百合病 ，发汗后者 ，$f{百合知母汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 650506094362693, 'DBFD6EF1A2577D6B476AB4F50B64CB02', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-03 13:36:06', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8089, 444, 905005004, '          百合病人被误攻下后，就要用百合滑石代赭汤。\n\n         诸位知道代赭石， 代赭石是涩剂，呈现紫色的，止肠痢用的。\n\n        为什么要加滑石？滑石是通利小便的。当病人被误攻下后产生下利不止时，如果要止利的话， 就要用涩剂，再加入利小便的药，把水从小便排出来，不要让水从大便走。因为如果水从大便走的话，身体的营养都会被排掉，小便一旦被排出后，这个利就会自动停止，同时百合会将丧失的津液再补回身体之内。', NULL, '百合滑石代赭汤', NULL, NULL, NULL, '4、百合病 ，下之后者 ，$f{百合滑石代赭汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651268283179077, 'DFA2BBCBD3F828F07B965881EFD3572A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-05 17:17:28', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8090, 444, 905005012, '        过去西医有一种病，名字叫做斑疹伤寒，中医就叫阳毒。这类阳毒常见于战争的时候，在战场上，还有牢狱里面，或在船舱里面，还有落后的地方，也常常会看到。\n\n       为什么会造成这样子？西医到现在只知道这个病毒传染的很快，世上比痲疯病传染的速度还要快的就是这个，被传染到就是死。西医到现在还不知道它真正的原因是什么，但是看到这个病的时候，第一个动作就是：赶快将病人隔离开来。\n\n        斑疹病发起来的时候，是从肚子这边开始发生，如果我们中医看到斑疹是红色的，十生一个死。如果看到这个斑疹是黑色的，十死一生，也就是说黑色的最危险。西医知道此病的传染力很强，没有任何西药可以治它。所以遇到这种状况的时候，赶快就把病人所有触碰过的东西通通集中起来，一把火烧掉。\n\n        如果这个传染病发现在战争的时候，久战的士兵身上被传染到的 时候，这感染会漫延得到很快，发病时是从身体肚子部位一直蔓延到 四肢上面，速度很快，之后一两个礼拜人就走了，此时它就被叫做「战争伤寒」。如果发生在监牢里面的时候就叫做「牢狱伤寒」。在船舶上： 「船舶伤寒」。想想看这些地方的共同点。第一个，病人都是表不固， 因为他们的饮食都不能很正常。第二个，都被局限在一定的范围，没有很自由的活动空间，也因此大部分都会得到这种病。\n\n          中医过去一个叫阳毒，一个叫阴毒。阳毒，主要症候是『面赤斑 斑如锦纹，咽喉痛』。阴阳毒都有咽喉痛、吐脓血。体内里面太热了就是阳毒，就是所谓的升麻鳖甲汤证。\n\n         如果你看到『面色青』『身痛 如被杖』好像被鞭子毒打一顿的样子。为什么会有这种感觉呢？ 因为 血都的流动速度减缓了，就是血将停止流了，由于病人血液循环不流畅，因此病人全身感觉到就好像被鞭子抽打般的疼痛。\n\n         如麻黄汤证也有身体疼痛的症状，这是因为表被寒束住，造成太阳寒水无法正常循 环全身，因此产生疼痛感一样，但是太阳症是表水不通，这里的阴毒是血液循环不通，二者完全不同。\n\n       临床上在用这里的处方时，有包括疱疹，就是所谓的带状疱疹。发生带状疱疹的地方就好像被鞭子打一 样，很疼痛，此时我们都可以用到这些方剂。 方剂里面有鳖甲、雄黄、 升麻，在本草里面有介绍过升麻，我上次说到麻黄升麻汤，升麻除了升提津液的作用，升麻也是解毒用，能解百毒。这个时候选用鳖甲是因为鳖甲本身并没有毒性，但是鳖甲的性很刚烈而且坚忍，又由于鳖 甲是入肝经，当鳖甲遇到当归时，由于鳖甲本身能直入血的最深处， 当归跟鳖甲混在一起的时候，就可以跑到肝里面去了，进入肝后肝脏 会变的很刚硬很坚强，而肝脏就不会受到病毒的损害。所以首先将病人的命先保住，张仲景很知道如何灵活运用鳖甲。\n\n        我们使用鳖甲的时候只要手指一片大，约三钱就可以了。然后发散病毒出去的就要靠几个解毒药，靠升麻、甘草，甘草本身就解百毒， 蜀椒的性很辛、很热，也能解湿毒，蜀椒和雄黄都是阳性的药，蜀椒入肺，我们后面将会介绍的大建中汤就会用到蜀椒，蜀椒是阳性的药， 所以走阳、走气、走气分、走表。斑疹伤寒这些病毒都在表上面，所 以他开的鳖甲当归先去固肝，不要让病人在毒未解除时先死掉，使用这些升麻、甘草、雄黄，都是解毒的药。你千万不要把雄黄加热以后吃下去，这会造成你不是死在阴毒，而是死在砒霜毒，人被毒死的时 候，其症状是舌头会伸出来，肥肥大大，舌苔是青色的，皮肤都是红 色的，这就是被毒死的。\n\n       如果是遇到阴毒，就是脸色发青、病人有高热，发起来的斑是黑黑的，这个时候我们晓得，这个毒是在血分不在气分，这个时候就要把蜀椒跟雄黄取出不用。\n\n       病人此时是不需要阳药，因为是病毒是在血分，就是血被凝固到了，所以此时需要将雄黄、蜀椒拿掉，雄黄、蜀椒被取出后就是升麻鳖甲当归甘草，就这四味药。临床上除了现在看到西医讲的斑疹伤寒，过去还有人在瘴疠区得到此类疾病，就是在我 国西南一带云南贵州这些地方的瘴气中得到这种病，其传染的速度非常之快。如果大家都会用这个处方，就可以救很多人。西医到现在完全没有办法治疗。\n\n        『升麻近人多以为升提之品』所以我们有麻黄升麻汤，有寒热互 结症状出现时，就是麻黄升麻汤。『在本经则主解百毒』在神农本草 经里面注『解百毒』。『甘草亦解毒』甘草也是解毒。『鳖甲善攻，当归和血』这两个，一个破它的血，一个和它的血。实际上当归和鳖甲， 最主要鳖甲的性是刚而且坚，护卫肝脏的，不要让这个病毒进去。当 然我们后面会介绍很多，大家会逐渐对伤寒谕的条辨更加了解，也同 时在读金匮的时候会更了解为什么会这样子。诸位再看下章的疟病。', NULL, '升麻鳖甲汤,升麻鳖甲汤去雄黄蜀椒', NULL, NULL, NULL, '12、阳毒之为病 ，面赤斑斑如锦纹 ，咽喉痛 ，唾脓血 ，五日可治，七日不可治，${升麻鳖甲汤}主之。阴毒之为病，面目青， 身痛如被杖 ，咽喉痛 ，五日可治，七日不可治，${升麻鳖甲去雄黄蜀椒}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946053, 'B12A1B17E3724C0CAD95CA833203BBB0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8091, 444, 905005011, '       『病者脉数，无热』就是摸到病人的脉很数，但是却没有发热， 这就是辨症。有热的话还好，代表病在表。\n\n        如果病人『微烦，默默但 欲卧，汗出。初得之三四日，目赤如鸠眼』看过鸠眼没有？就是眼睛 红红的，眼白部位全部是红色的，只有眼珠是黑色的。\n\n     『七八日， 目四皆黑』眼睛这里四周整个眼框都变成褐黑色的。如果病人能够吃， 表示脓已成，不管病人是腹膜炎、胆结石以后破裂掉了，或是盲肠炎失治，结果阑尾破掉了，变成腹膜炎。或者是外伤伤到了，身体里面 发炎，或是三焦网膜上发炎，我们身体内会产生一薄膜，会把这些炎 症固定在一个地方，这是我们人体的一个自动保护机制。在没有破又 快要破的时候会很痛，像急性盲肠炎，下腹部会很痛，如果来不及开刀，阑尾就会破裂掉，破掉后病人会说：「哎呀!不痛了。」于是可以 吃东西了。\n\n        这个时候时常连医师在检查，包括护士在内有时候都会产生误诊。西医看：「没有啊，病人不痛啦，都好啦。」病人送到医院后， 已经不痛了，其实是已经转腹膜炎了。实际上，你摸他肚子原来痛的地方，整个是滚烫的。此时中医一看就知道，张仲景就告诉你，你看病人眼睛周围是黑的，就代表里面已经化脓了，不痛的原因是因为已经破掉了。所以如果是我们中医看诊就不会错了，我们在阑尾点附近找寻压痛点，出现强烈压痛现象，就代表腹部有化脓了。\n\n      一看眼袋是黑的，就确定是里面发炎了。再一摸脉，脉是很数的，代表里面是热 的。病家没有表症，但是脉跳得很数，就代表里面有热，没有发烧就是没有表症，结果也表示里面已经化脓了，这种情形发生时，就是赤豆当归散。当归赤小豆散我们在使用的时候，这个当归是生用，赤小豆从药房买回来以后，需要把它放在水里面浸两三天，等到它发芽， 赤小豆要发芽后用。一般我都是先发一些芽以后冷冻储存起来，以备不时之需用。\n\n       为什么要发芽？ 因为我们脓成的时候，在身体里面、腹 膜里面它的渗透里很强，渗在四周旁边。如果直接用赤小豆来去脓的 话只能将中间的脓排除，四散在旁边的脓就没有办法清干净，所以仲师要让赤小豆发芽以后用，这就是技巧了。\n\n        当归本身就是入血分，能够把赤小豆带到血里面去，然后赤小豆 就可以去它的湿。大家看，脓已经成了就会湿湿黏黏，赤小豆能够同 时去湿去热，一旦化脓后就必然伤到血，所以要用当归造血，让新的 血过来，让它补病家丧失的血，当归赤小豆散是我们中药里面很有名的专门治疗腹膜炎用的处方。如果是给西医治疗腹膜炎，病人就只能 躺在病床上不要动，然后每天给你打抗生素，连动都下能动，一动就剧痛。\n\n          以前我一位学生就是护士，她就是得到腹膜炎躺在病床上躺了一个月，她说：「早知道就用当归赤小豆散，药房才卖十五块钱一付。」 平常你的诊所就要先将赤小豆发好芽，等到有病人得到腹膜炎后再去泡会太慢，然后是：「老师这个赤小豆孵不出来!」紧张死了。「老师这个病，是否一定要等到有脓的时候才可以用？ 」对!譬如说在先前  还没有化脓的时候，我们有尚未化脓的治法。这是脓成后专用的，如何分辨病人的脓已成就是要看症。所以当病人胃口很好，可以正常的吃饭，但是眼睛四周却黑黑的，然后摸病家的脉是数的，可是又没有表热，就表示已经化脓了。赤小豆我用的很多，不但能够去热而且能够解毒，腹膜炎产生的毒素它能够把它解掉，是治疗腹膜炎很有名的药，凡是遇到溼热的毒，张仲景通通会使用到赤小豆。', NULL, '赤小豆当归散', NULL, NULL, NULL, '11、病者脉数，无热微烦，默默但欲卧 ，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也， $f{赤小豆当归散}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946054, 'B68D95564EBFF8C78416D52BCE94D9E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8092, 444, 905005010, '       狐惑病，就是寄生虫引起的病。这种虫，有的时候可能是血丝虫， 可能是肠子里面的蛔虫，有的时候可能是性病的毒。我们中医不管它 是什么病毒，我们只管如何辨症。\n\n      『状如伤寒』就是看起来很像伤寒， 看起来像麻黄汤证，病人会恶寒发热。\n\n      『默默欲眠』就是想睡觉目又不得闭，眼不得闭是因为病毒跑到肝脏里面去了。『卧起不安』\n\n        如果跑到喉咙上面就会『蚀于喉』，张仲景称为『惑』。\n\n       『蚀于阴』就是阴部长了性病，会看到阴部破损掉了，这些就是西医讲的性病。蚀于阴叫做狐病。\n\n        吃东西吃不下『恶闻食臭』，闻到食物味道胃里面就难过。 \n\n        有时候『乍赤、乍黑、乍白』脸色常常在变化，这种就是属于性病之类的疾病。\n\n       如果是蚀于上部，就是喉咙受到这种病毒侵害的时候，会连声音都变掉了，像有的梅毒病人到末期时连声音都改变了。如果是这样子的话，第一个蚀在喉部时，我们要用甘草泻心汤。蚀在下部则 咽干，用苦参汤洗之。如果是蚀在肛门的话，用雄黄来薰它。\n\n       甘草泻心汤，诸位过去都学过，有心下痞时就会用到甘草泻心汤， 还有就是用在治疗性病时也会用到甘草泻心汤。上次我在美国，讲心脏动脉血管堵塞案例时，当时我第一眼看到他，就知道是甘草泻心汤证。诸位看甘草泻心汤的方子，炙甘草、黄芩、干姜、人参、半夏、 黄连、大枣。这个处方里面没有大黄攻下的药，结果病人吃下去却上 了五、六十次厕所。因为体内所有阻塞住的浊物完全被排出来，我们中医是辨症论治，只因为病人东西吃不下去，胃里面难过，而选用甘车泻心汤来治疗，没想到结果竟然如此。\n\n       苦参汤，平常不要光用苦参来煮，我们还要加一些东西在里面。我们用苦参的时候，一般是用药汤来洗患处，洗阴部，洗男人的生殖器，苦参我们用四两，因为要煮汤水。还需要加一些槐木，再加一些狼牙草等一起煮，我们后面还会介绍。两个都差不多四两，用来清洗患处，阴部给性病腐蚀到的地方。 如果您不幸是零号，肛门受到的伤害会比较严重，这个时候就要用雄黄。将雄黄放在瓦片上，然后在下面生火加热，雄黄加热过后会变成砒霜。\n\n         过去铁匠师父打铁的时候不管他打的是马口铁或是打剑、打铁锹，无论打什么东西，如果想要提高铁的纯度，就要把铁里面杂质去掉，方法就是泡在砒霜水里面。一泡下去，铁中的杂质就会被去掉， 所以它对铁的腐蚀力量很强。你如果用铁锅在下面，雄黄在上面一烧 「啵!」铁锅就会出现一个洞，穿过去了。\n\n        所以我们平常烧雄黄一定 是用瓦片，就是屋上的瓦，你拿一块瓦放在一边先加热，然后用另外 两片瓦把它夹着，让中间有一个小孔。然后要薰的人拿着一块布，千 万不要去闻那个味道，那不是给你闻的，病人就蹲在上面，用布把身体盖好，头露出来，然后在后面的布弄一个小孔，再将雄黄倒上去， 此时一股青烟就会往上冒，你自己也不要闻那个烟，会中毒的，烟往 上冒燻到肛门，肛门腐烂掉的部位受到此烟一燻就会止痛，伤口就会恢复过来了。当然不一定是零号，别的原因造成肛门整个腐蚀掉通通 可以用。平常雄黄如果要加热用的时候，那个烟是又青又黑，闻了以 后就会感觉到好像有人勒到你的脖子，呼吸都会呼不过来，这表示你 中毒了。', NULL, '甘草泻心汤,苦参汤', NULL, NULL, NULL, '10、狐惑之为病，状如伤寒，默默欲眠 ， 目不得闭 ，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭 ，其面目乍赤 、乍黑、乍白，蚀于上部则声嚘，甘草赤、乍黑 、乍白 ，蚀于上部则声嚘 ，$f{甘草泻心汤}主之。蚀于下部则咽干， $f{苦参汤}洗之。蚀于肛者 ，$u{雄黄}熏之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946055, '9FE720006FE8BC44A1C225125721DA82', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8093, 444, 905005009, '         这个就是告诉你，所谓百合病，就是病家本身的津液已经虚掉， 身体是持续处在虚的状态之下。所以有时候当身体虚的时候，你看到的是热，好像是阳症，这时你不要开去热的药给他，要用滋阴法，我们要开些滋阴的药，来养阴液，然后再加些去热的药才可以。\n\n       但是你又不可以开太强的去热药，强力去热的药像石膏、知母、 黄苓、黄连，尤其像黄连是很强的去热药。这种病人本身就虚弱，你说他没病他又有病，说他有病他又没病。你如果开很热的药下去他受不了的。或者开很凉的药也受不了的，所以要在临证再决定用什么方法来治疗。', NULL, NULL, NULL, NULL, NULL, '9、百合病，见于阴者 ，以阳法救之；见于阳者 ，以阴法救之。 见阳攻阴 ，复发其汗 ，此为逆 ；见阴攻阳 ，乃复下之， 此亦为逆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946056, '6F3E077AC9E85931367A8D3CE1AA3332', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8094, 444, 905005008, '      当百合病人如果变成发热，一直没有好，这个时候我们就要更换为百合滑石散。要靠滑石，把热从小便利掉。滑石本身是利尿剂。原因也有可能是病人本身有百合病又兼到有膀胱结石或者是肾结石。中医讲的热，诸位有一个观念就是『发热者』就是发炎，有破损了，才产生热。\n\n       这时百合用炙过，就是用火烧过，或是在锅子里面干炒过。 比例是用百合一两，滑石就要用三两，将这两味药捣成散剂来服。『方 寸匕』就是一个汤匙而已，一天吃三次。如果吃了百合滑石散后有点 下利时就可以停药，因为表示药到了。', NULL, '{百合滑石散', NULL, NULL, NULL, '8、百合病变发热者 ，$f{百合滑石散}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946057, 'FB9AF0B78B681DF55D655E2F67EE4F83', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8095, 444, 905005007, '       如果你用百合洗方，洗完了还是照样渴。渴的时候病人水喝下去就下利出去，或是小便流失掉了，反正就是身体不受，渴症本是很简单治的，像是用栝蒌根或是用白虎人参汤之类都可以治渴，如果服用后照样还渴，表示身体已经不受。\n\n        遇到这种渴不解者，我们就要栝蒌、 牡蛎并用。张仲景只有在这个方子中栝蒌牡蛎并用。『渴不解者』口渴的要死，喝水都不能够解渴。栝蒌根，诸位都很了解栝蒌根本身是 味苦又是性寒的药，能够生津止渴。牡蛎咸味、性寒，但是它能够把上焦因渴而造成的虚热导引到下焦来，让虚热从小便走掉，再利用栝蒌根来增加病人的津液，这几个都是百合病的变方。', NULL, '栝蒌牡蛎散', NULL, NULL, NULL, '7、百合病 ，渴不解者 ，$f{栝蒌牡蛎散}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946058, 'CA5BDF36CECB70F5A066FEE5762B1985', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8096, 444, 905005006, '       如果百合病到了一个月都没有好，结果病人出现口渴，这个时候渴的处理方式就得用百合洗方，洗方就是我们想让百合的药力从皮肤毛孔渗进去。就是把百合泡水，泡了一个晚上以后来洗身，洗完以后吃煮饼。\n\n       这里所谓煮饼，指的是淡面，白的面，越清淡越好，不用加什么盐巴『勿以咸豉也』。\n\n       如果你加很重的盐巴进去，吃下去没有用， 因为咸会把水分散掉。用洗方的目的就是要我们不去攻，因为病家身体里面已经是虚的。虚掉的程度已经到连药都不接受了的阶段，所以我们尽量想别的方法让津液能够进入体内，你看张仲景考虑得多细腻。', NULL, '百合洗方', NULL, NULL, NULL, '6、百合病 ，一月不解 ，变成渴者 ，$f{百合洗方}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946059, '53714D0A9763732183201CF48A5BA085', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8097, 444, 905005005, '        百合病之人，如果被误吐，怎么办呢？吐了以后会伤到胃的津液， 我们就用鸡子黄，就是鸡蛋黄，蛋黄放在百合汤里面搅和以后，后面说煎五分，其实是不要煎的，一煎以后就变成蛋花汤了，就是百合蛋 花汤。我们是用鸡子黄，就是鸡蛋黄黏黏的下去到胃里面，如果被吐 后用这个鸡蛋黄去补胃因吐而失去的津液，此时所有的方子都不能 用，因为病家不受，这就是百合证。\n\n        临床上看的时候就是西医讲的神经衰弱症，看到都是百合证。有的时候扶病人在路上走，他会左右晃荡晃荡的这样子。家里面只要有一个人这样子就很累了，一天到晚在那边胡思乱想。\n\n        我们为什么不叫他神经衰弱，我们叫它做百合呢？ 因 为西医就是看不出来怎么回事，所以只好罵你神经病，可是又怕你受 的伤害很大，幼小的心灵受到伤害，他就说你是：「神经衰弱」，这样比较好听一点，其实就是在骂你神经病。\n\n        西医没什么药可以治疗神经衰弱。只有中药有，张仲景出了那么多方子，还预防到怕你这个神经 衰弱病人，因为吃坏肚子或被医生误治后，如何做补救都考虑到了。', NULL, '百合鸡子汤', NULL, NULL, NULL, '5、百合病 ，吐之后者 ，$f{百合鸡子汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651576107946060, '239AF498E931D7E05E0DBAD8385C82F5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 14:10:00', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8098, 445, 905006005, '        这个是寒痰所造成的饮症，平常我们的痰饮分为两种，大部分是属于热痰饮，像抽烟的人，或者是过去吸食鸦片的，大部分都是热痰， 吐出来很浓稠很黄的胶痰。\n\n        如果遇到寒痰堵到，寒疟讲的就是寒痰， 临床上看就是痰饮，中医叫做『牝疟』，是蜀漆散证。\n\n       蜀漆的另外一个名称又叫做常山苗，它祛痰的力量非常的强。吃下去的话浊痰会很容易的咳出来，而且是整块的出来。\n\n       云母石，把它打碎以后，先烧个两天两夜，先炙过烧过就是要去它的天然毒性。金石类的药物使用前都要炼过，炼过以后才能去掉它的毒性，把我们需要的药性留下来，就是取它们的阳性。这里的龙骨，实际上我认为是跟牡蛎弄错了，应该要用过牡蛎比较好。\n\n       因为这是寒疟，而牡蛎能够攻坚把胶痰打散， 所以蜀漆散这个药是专门治寒痰用的。\n\n       寒痰停于心胸之间，『心』讲的就是胃，就是心下腹部中间这一 带，大家看这个云母石，『云母石本经主治中风寒热，如在舟车，是 为止眩晕镇风阳之品』而牡蛎，中医用牡蛎来治咳逆，专门去痰水。 当痰哽在胸胃中间的时候，如果是热痰，我们可以用皂夹丸来祛痰。\n\n       寒痰的话要把痰从口中吐出来，蜀漆吃下去，病人的积痰是得吐则解的。牡蛎味咸，本身又能够止咳，能够降逆，所以应该不是用龙骨， 龙骨比较着重在潜阳，我们的桂枝汤加龙骨牡蛎就是如此，其中加了 云母石，云母石是一个镇晕眩的药，为什么要这样使用呢？ 因为如果 是水隔在中焦，也会造成头眩，这是苓桂术甘汤证。\n\n      如果中焦不是水隔到，是痰隔到了，苓桂术甘汤下去就没有效果，这个时候我们要先把痰去掉，不去掉病人头昏不会好。这种头昏，必须要靠云母石，专 门通利中膈，才能解决头昏的问题。所以寒痰隔在中焦的时候，病人 也会有眩晕的现象，这个时候就要靠云母石。你看，上三味把它捣为散来吞服，就是服药粉，不要煮成汤剂来吞服。\n\n        中医过去对疟证有一个观念，就是所有的疟都有痰，临床上看到 有往来寒热，无论是间日疟、隔日疟、一日疟都有，所以有句话叫做 『无痰不疟』。\n\n       因此不管病人的痰到底是寒痰还是热痰，当我们在决 定处方怎么设计时，无论是什么处方通通都会加入祛痰的药，也因为 痰所在的位置不太一样，我们加进去祛痰的药和处方就稍有区分，这些是在临床上检查病人后再决定如何使用。\n\n      像我在治疗心脏时，我们有一个病人，心包被痰哽到，无论怎么咳也咳不出来，就一直哽在里 边，造成连呼吸时胸口也会痛，查又不是心脏病，可是痰哽在这边又很难受。我就开了桂枝汤加蜀漆龙骨牡蛎救逆汤，当蜀漆下去后，一 下就咳出痰来，好大的一粒出来，连续咳出好几颗来，从此胸腔气闷 就四散开了。\n\n       临床上开处方时不能写蜀漆，写常山就可以了。蜀漆药房买不到， 就用常山苗来代替。其实蜀漆跟常山苗不一样，可是因为没有真正的蜀漆，所以现在都用常山苗来取代它，实际上两者是不一样的药物。\n', NULL, '蜀漆散', NULL, NULL, NULL, '5、疟多寒者 ，名曰牝疟 ，$f{蜀漆散}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651625584803909, 'F2B9D431F4E93657FE00F2169767EE8F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:31:20', 1, 'admin', '2025-03-07 10:01:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8099, 445, 905006004, '        瘅疟和温疟不一样，温疟，你看『时呕』，『脉如平，身无寒，但热，骨节烦疼』就是说热是在肺里面，所以我们感觉到并没有在肠胃里面。前面条辨说的瘅疟，是发生在胃里面，所以是小柴胡汤加入白虎汤。\n\n       这里说的是治温疟的主方，石膏、知母、甘草、粳米这是白虎，加了桂枝。温疟的病本来是来自太阳经热，后来部分已经进入阳明成 热了，部分又进入肺。而瘅疟大部分还停留在肠胃里面。所以两个疟 看起来很类似，实际上，症状稍有不同，应该分开来看。\n\n        在临床上只要记得，但热不寒就是阳明证。然而到底该是白虎加 重还是桂枝加重，这个时候就要看他的太阳证有多少，太阳证少，阳明证多，就一定是加重使用白虎。如果是脉浮的话，就是太阳证多， 阳明证少，此时就用重用桂枝。', NULL, '白虎加桂枝汤', NULL, NULL, NULL, '4、温疟者 ，其脉如平，身无寒 ，但热 ，骨节烦疼 ， 时呕， $f{白虎加桂枝汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651625584803910, '95D385225137494CC09848303F7F7D0E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:31:20', 1, 'admin', '2025-03-07 10:01:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8100, 445, 905006003, '       什么叫阴气孤绝呢？第一个，病人失津，就是津液丧失了。比如 说被吐、下、汗，使得津液都流光了。第二个，亡血，不但津液丧失 了，血也不足了，这种状况就是阴气完全没有了。这个时候就会出现 『阳气独发，则热而少气』，病人表面上看是发热，但是这种都是属于虚热。\n\n    『手足热而欲呕，名曰瘅疟』，这种疟，看起来像是阳明证， 属于但热不寒，是因为热闷在里面产生的。\n\n     『若但热不寒者，邪气内藏于心』就是在胃的地方，外面这个热，又潜伏在我们的肌肉关节中 间，一样是属于疟的一种。造成病人越来越瘦，上吐下泻，然后忽冷忽热，这就是疟毒，如果这种病毒停在胃里面，然后又停在我们的肌 肉中间，这就叫做瘅疟，\n\n    『令人消铄肌肉』。临床上遇到这种情形的时候，我们一定会用到小柴胡汤。「老师，病人是但热不寒，但是同时津液也伤到了，所以兼有失津。」此时小柴胡汤就需要加白虎之类， 这就是张仲景的想法。', NULL, NULL, NULL, NULL, NULL, '3、师曰： 阴气孤绝，，阳气独发 ，则热而少气 、烦冤 ，手足热而欲呕，名曰瘅疟；若但热不寒者 ，邪气内藏于心，外舍分肉之间 ，令人消铄肌肉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651625584803911, '0C0C6FB841EC2E3ADE919E956403FAF2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:31:20', 1, 'admin', '2025-03-07 10:01:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8101, 445, 905006002, '       疟病之后如果结成一块停在腹中，症状如癥瘕，如果发生在三焦 淋巴系统里面，我们可以用小柴胡汤把它和解出来。\n\n       张仲景说：「结成一块的时候这叫做疟母。」就是长在肚子这边，像痞块样，绷起来硬梆梆的，必须赶快治，『以月一日发，当以十五日愈』一般来说半个月会好，如果没有好的话，应该『当月尽解』，此时当使用鳖里煎丸。伤寒论里面以麻黄升麻汤的汤剂内使用药物最多，金匮里面以鳖甲煎丸证的汤剂内使用药物最多。一般疟病会集中在一起成为疟母， 多发生在病愈之后。\n\n        一般来说疟会聚集在一个地方的只有寒疟会，热疟不会，热是会四散的，寒的疟才会凝固，凝聚在一个地方。\n\n       大家看处方内容，鳖甲， 这个我们刚刚介绍过，中间这个是鼠妇，鼠妇这个药本身是在妇科里面用的，专门治疗月经闭经，可以消血癥，就是有血块停留在子宫里造成阻塞，就会产生女子闭经，这时我们会用到鼠妇。\n\n       鼠妇是很毒的药，一般用量很小，这里是做成丸剂。石苇这个药在本草里面讲，专门治劳热，劳热就是虚热。平常我们都不会用到这个药，只有鳖甲煎丸，我们才会用到。紫葳这个药跟鼠妇是一样，也是专门治疗这种癥闭。\n\n      经方里面用来攻坚的药物，像鼠妇、紫葳这种药物就是在攻坚。 还有『方中用桃仁蟅虫蜣螂鼠妇之属』目的是要破除瘀血，因为疟母 在腹腔里会聚集在一处地方。\n\n       中医的观念里面是认为，这种疟病会突破我们的肠壁，当疟病在三焦油网、淋巴系统里面跑的时候，就会出现忽冷忽热的症状，如果突破出来，疟病就会凝聚在一起，就会影响我们的血液循环造成血管会破裂掉，血会瘀阻在一个地方，加上病人 痰会很多，造成里面整个都是血和痰混在一起，临症上看到就是这样， 所以会选用到很多祛痰的药。像这类瘀血，流出血管到了我们的组织 中间，又碰到痰，这痰本来就是很容易滋生病毒，病毒是最容易生存 在这种湿稠稠的地方，它最喜欢待在这样环境里面，再碰到瘀血停在 这里，瘀血又供给这些病毒营养，所以就形成一个很大的硬邦邦的块状物。\n\n       遇到这种情形，西医也是只有开刀进去把它挖出来。中医就是用鳖甲煎丸。鳖甲煎丸非常不好制做，因为很多药已经找不到了。葶苈是用来涤痰的，后面我们肺痈会介绍到葶苈子。\n\n      『君鳖甲以攻痞』 硬块，鳖甲不但可以护卫肝，而且也可以攻血。\n\n      『又参用小柴胡汤以清少阳』所以大部分疟疾我们都是小柴胡汤的加减。\n\n     『干姜桂枝以温脾，阿胶芍药以通血，大黄厚朴以调胃，赤硝瞿麦以利水而泄湿』赤硝，就是芒硝。这里用丸剂，要用丸剂就是能够取它的药缓力重。如果用汤剂，走得太快，没有办法完全让药渗到疟母的地方，由于这种症状我们看到并不是很多，临床上我们治疗这类病时，很可能我们不容易把这个鳖甲煎丸做成，所以实际上我们必须用针灸配合处方来治疗它。\n\n       一般我们看到这种堵在肚子里的气块，按照张仲景的陈述，病人 会往来寒热，所以我们选穴下针很重要。\n\n       我记得我在讲针灸的时候， 像外关穴可以通利三焦，血的**穴『委中穴』我讲过是专门治疗霍乱、 疟疾的穴位，然后利用小柴胡汤来做加减，你可以用加入一些攻血的药和攻痰的药在里面。现在药房还可以买到的像蜀漆就是很好的祛痰 的药，葶苈子是攻水的药。还有祛血攻血的药，像桃仁、红花，都可 以加在小柴胡汤里面供用。下针的话外关、委中穴就可以了。如果没 有这个鳖甲煎丸，我们可以用我们的方法来制作药丸，当然时间会拖 长一点，还是会好转的。', NULL, '鳖甲煎丸', NULL, NULL, NULL, '2、疟病结为癥瘕 ，如其不差 ，当云何？\n\n       师曰：此名疟母， 急治之。 以月一日发 ，当以十五日愈 ；设不差 ，当月尽解， 宜$f{鳖甲煎丸}。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651625584803912, '52CC61203971D4DC41F5B7E8BA9F1B65', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:31:20', 1, 'admin', '2025-03-07 10:01:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8102, 445, 905006001, '       『师曰：疟脉自弦，弦数者多热』弦脉就是少阳的脉，我们摸到病人出现弦脉，大部份都有往来寒热，忽冷忽热的现象。不管是少阳证还是疟疾，只要是忽冷忽热就是，\n\n      『弦数者』数就表示热，\n\n     『弦迟者 多寒』脉迟者就是寒，但是弦脉是一样的，弦脉就是摸到的脉呈现细 细的直直的，像吉他、钢琴的弦一样，很细直。\n\n     『弦小紧者下之差』 当脉是弦而且紧，就代表是半表半里，如兼有阳明证时，必须攻下， 就是所谓的大柴胡汤证。\n\n      如果脉出现『弦迟者可温之』就是所谓的四逆汤证，四逆汤本身就是温中用的。\n\n     『弦紧者可发汗』如脉是弦而且紧，就要利用针灸了。\n\n      如果『浮大者可吐之』当脉出现浮大时，表示胃中有宿食不消，就得用吐法取吐解病。\n\n      如果是『弦数者』弦而且很数，代表说身体里面是往来寒热，但是数又代表热，是由风发的，这时要看他以『饮食消息止之』临症上，一般我们都是从脾胃上着手开始治疗。\n\n     所有的疟症治法，无论往来寒热，首先要强健病家的脾胃， 就是所谓的饮食消息，比如说病家食物吃太少，我们就开健脾整胃的药。如果吃东西会下利，我们就开止利的药，去调他肠胃就可以了。', NULL, NULL, NULL, NULL, NULL, '1、师曰：疟脉自弦 ，弦数者多热 ，弦迟者多寒 ，弦小紧者下之差 ，弦迟者可温之 ，弦紧者可发汗 、针灸也，浮大者 可吐之 ，弦数者 ，风发也， 以饮食消息止之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651625584803913, '3C05A84253738E6F2133D3FC016D3123', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:31:20', 1, 'admin', '2025-03-07 10:01:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8103, 445, 905006008, NULL, NULL, '柴胡桂姜汤', NULL, NULL, NULL, '8、《补充》$f{柴胡桂姜汤}    治疟寒多微有热，或但寒不热。（服一剂如神）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651868973998149, '33F46BE4BAA69CCDCF62D947C26C00B7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 10:01:41', 1, 'admin', '2025-03-07 10:01:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8104, 445, 905006007, '附《外台秘要》柴胡去半夏加栝楼汤,治疟病发渴者，亦治劳疟。', NULL, '柴胡去半夏加栝蒌汤', NULL, NULL, NULL, '7、《补充》$f{柴胡去半夏加栝蒌汤}    治疟病以发渴者，亦治劳疟。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651868973998150, '036D2B53A4024E46802D1DF687F1AE23', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 10:01:41', 1, 'admin', '2025-03-07 10:01:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8105, 445, 905006006, '附《外台秘要》治牡疟。', NULL, '牡蛎汤', NULL, NULL, NULL, '6、《补充》$f{牡蛎汤}   治牝疟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651868973998151, '5A0D0BE744B31D4260C92DEC8EB8DFD2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 10:01:41', 1, 'admin', '2025-03-07 10:01:40');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8106, 446, 905007002, '       『寸口脉浮而紧』。寸口脉代表胸、代表上焦、代表胸阳、代表 肺、代表心脏，这是寸口脉。寸口脉如果是浮而紧，\n\n      『紧则为寒，浮 则为虚』。浮脉再深入一层的观念，中医认为『气行脉外』『血行脉内』。 浮脉的意思是如果你摸上去感觉脉跳得很大，但是脉的里面很小，就 是说脉的外侧比较大，里面比较小。就是气比较旺，血衰掉了，正常 的脉是脉里面很洪大才对，你只摸到他的浮脉代表气脉，没有摸到血 脉，浮则为虚，就是血虚掉了。\n\n     『寒虚相抟』大家都知道紧脉就是寒脉，当寸脉是浮脉而且又是紧脉时，我们知道病人是寒虚相抟，这就代表邪在皮肤。\n\n    『浮者血虚』浮脉就是血虚。所谓『络脉空虚』我们人体皮肤最表面是孙络，再里面一层是络，再深的靠近我们筋骨血脉 旁边的就是经，经是最大条的。但是比较深的，再浅一点是络，在皮 肤表面上是孙络，好像树枝密密麻麻的一样。如果『络脉空虚』就是经的血还足够，但络脉的血不够，\n\n   『贼邪不泻，或左或右，邪气反缓， 正气即急，正气引邪，喎僻不遂。』这意思就是说，如果邪是在右边 的时候造成气血不通，左边的血是好的，结果左边的气血会把右边的 气血牵引过来，于是就造成右边瘫痪掉了。\n\n     『邪在于络』就是说风邪只是停留在络上面，不在经上面，病人感觉到的是『肌肤不仁』就是麻木不仁感。\n\n      如果『邪在于经』到了血脉神经很深的地方时，病人感觉到的是『即重不胜』，就是四肢感觉到很沉重。\n\n      如果邪跑到腑里面 去，主症是『不识人』。\n\n     血入腑，就是邪进入脑部，影响记性，必不识人。\n\n     如果『邪入于藏』藏就是属于心脏这个部分，我们藏神的，心开窍在舌，『舌则难言』就是讲不出话来，\n\n    『口吐涎沫』这是我们用外症、表面症状来判断这个病在哪里了，现在诸位了解我们中医有分中风在络上面，在经上面，在血脉，在腑里面，所以我们下手治症的时候治法都不太一样。\n\n      但是所有中风的病人除了在经、在脉、在络上面的这类中风，一年两年找中医治尚没有关系。但是如果病情入腑入脏后，已经半身不遂了，嘴巴讲不出话，这种情形一旦超过一个月后再来找我们就没有用了，可是西医往往就让病家两三个月后再来找我们，这时已经失去治病的时机，而这病是不会立即产生死亡的，因此造成许多病人长年卧榻的悲剧。\n\n     『世传中风不语用黄耆防风各数两，煎汤』用汤药的热气来薰病人全身，也就是利用黄耆跟防风的药气，这个汤叫做『黄风汤』。\n\n       经方的观念里面，处方的时候，是以养血补正气，来预防中风，黄耆可以固表，是非常好预防中风的药，防风也是补正气固表的。党参就是补气的。当归，川芎是能入血分的药，也都是很好的补血药，补气补血药物同在一方中，当病家的气血足了，就不会中风。\n\n      中医的观念和西医的观念是不一样的，西医是看片段的病况来做决定。所以只看到片段的『中风引起的脑淤血』，脑部出血了，于是就想尽办法事先将你血压降下来，希望不要让你脑部充血，可是他们不了解光降血压是 没有用的，只是降到形没有神，人不是植物，人都有喜怒忧思悲恐的， 情绪起伏大时，会造成你血往上走，药物只是降到形，所以没有用， 如果要吃西医降血压的药，想要有效的话，基本上你必须要去闭关， 到庙里去打坐，然后一个月、两个月都不要见到亲朋好友，从此以后 你就一直闭关在那边，才不会中风。\n\n       可是你如果有办法闭关远离亲人 的话，你也不需要降血压的药，因为你不会中风了。今天的课介绍完 以后诸位将有很多方剂可以使用，在治疗中风上帮忙很大。', NULL, NULL, NULL, NULL, NULL, '2、寸口脉浮而紧，紧则为寒，浮则为虚 ，寒虚相抟 ，邪在皮肤 ，浮者血虚，络脉空虚，贼邪不泻 ，或左或右 ，邪气反 缓 ，正气即气即急 ，正气引邪 ，喎僻不遂。\n\n       邪在于络 ，肌肤不仁 ；邪在于经，即重不胜 ；邪入于府 ，即不识人 ；邪入于藏 ，舌则难言 ，口吐涎沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651898737344581, 'DFAC74041097C5AB2B770D709FF2AABA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 12:02:47', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8107, 446, 905007001, '       所谓痹的定义就是感觉是麻木不仁。中医有风痹，有血痹，后面都有介绍。血痹与虚劳的病脉放在一起。一般来说风痹，就是肌表麻 木不仁没有感觉，皮肤会变得很粗糙，有的人半身不遂，有的人但臂不遂，中医把这个所有中风归类为气血两虚。\n\n       如果我们气血很足，中风了，就是桂枝汤证或是麻黄汤证或是葛根汤证。\n\n       当病人本身气血两虚时得到中风时，就会有中风的症状了，所以中医在治疗中风时，我们都是把病人血补足，或是把气补足，一般都是在这个角度上面着手。 \n\n       现代许多人，认为吃降血压药就可以预防中风，但是现在许多人吃了降血压的药，结果还是中风，很多证据显示西药是无法预防你得到中风的，量血压并不代表可以帮你预防中风，因为血压是会受到心情影响的，我们不可以将之做依据来判断此人是否中风。\n\n        像『但臂不遂者』，这是虚劳。中医过去认为是房劳，房事太多， 或者是工作太操劳造成了气血两虚以后，有的人是直接瘫痪掉了，也有人是从背后上来，从督脉上来会造成整个手臂都麻掉了，中医通通归之为痹，是属于风痹。\n\n       脉是微脉，微脉代表血虚掉了，就是脉很细弱。\n\n      数脉代表风脉，所以病人是血虚又得到风的现象，这就是中风。\n\n      中风的时候可以针药供施来治疗，例如一个临床案例，用麻黄汤外加防风、党参、当归、川芎、熟地然后找针家来针手足三里、曲池、 委中、肩井、合谷、环跳、跗阳、丰隆、蠡沟等穴，病人有伤寒的现象，因为表有寒症，但是又同时兼有里虚，因此开麻黄汤的同时还需要加入很多补虚的药进去，像党参、当归、川芎、熟地都是补气补血 的药，防风能够补表，帮助麻黄来解风。\n\n       下针的话，我们有中风七大穴。以前很有名的经方家曹颖莆先生就是专用汤剂处方，需要针灸时是找另外针医来针的，过去很少有一个医师同时懂药又懂针。\n\n       遇到中风病人我们下针的手法，第一个原则，是先补健侧，第二 个动作是泻患侧，就是好的那边，我们用补的方法下针，用补的手法作捻转或是插提。坏的那边，用泻的手法进针，用泻的手法作捻转， 第三个原则是选穴，我们选的穴位是肩髃、曲池、外关这是手上三个中风大穴，脚上三个中风大穴是环跳、风市、阳陵泉。再加上背针， 就是针风府穴。\n\n        如果病人舌强不语，嘴巴不会讲话，就需要针百会穴， 这是针灸治疗中风时我们时常在扎的穴道，这些都是治疗中风的基本穴道。\n\n        其他穴道的选用，大家可以临症来做取捨。比如说加足三里，可以加强病家的胃气，灸足三里可以预防第二次的中风。因为中风本来就是气血两虚，气血两虚就是因为肠胃吸收不好才会有的症状，这个 时候我们针下足三里胃经的本穴，让病人的肠胃吸收变好，因此灸此穴就可以预防病人第二次的再中风。\n\n        出现中风先期症状时中医可以预 防，中风了以后我们去治疗也可以预防他第二次再中风。先期中风的是有先兆的，像我们手脚会麻，表示两个月以内会有机会中风，如果脚前面足三里，足阳明胃经会麻，两个礼拜以内就会中风。\n\n        中风前就已经有肌肤不仁的现象，这个时候就应该要开始动手了。如果这个时候脚麻或者手麻你跑去找西医，西医就要病人去看外科，检查看看你有没有风湿。或是去验血，验完血出来看到你在外面已经中风躺下去了，中医知道这是将要中风的预兆，并不是什么风湿关节炎引起的麻木。\n\n        临床在急救中风时，如果病人已经昏迷过去，我们的针法又不一 样。刚才讲的是用在治疗中风以后的穴位选取，急救的时候我们下针下百会、人中、十宣放血然后再扎涌泉，把病人当成脑溢血来治。如果病人在然谷穴那边有瘀青筋一块浮起来，就在然谷穴直接放血，百会也放血，十宣也放血，这是中风昏迷时的急救法。\n\n        如果这套针法针 下去病人还没醒过来怎么办？在内经里面有说明治法，大家记住要在病人左额角位的地方，拿剪刀把这块一寸方圆的头髮剪下来，拿火一烧，变成黑黑焦焦的，烧成粉。然后把针管拿出来，当成发焦散，把它直接吹到病人的耳朵里面去，人就会醒过来，这个是攻脑部瘀血的利器。一喷进去的时候，鼻子会出血，当鼻血一出来，脑部的瘀血就会整个跟着一起从鼻子出来。这是我们治疗植物人的绝佳治法。\n\n', NULL, NULL, NULL, NULL, NULL, '1、夫风之为病 ，当半身不遂 ，或但臂不遂者，此为痹，脉微而数 ， 中风使然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651898737344582, 'EE9125F7CC69EBA5AC197C86369B4EC2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 12:02:47', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8108, 446, 905007008, '       『寸口脉沉而弱』寸脉位出现脉沉在骨边，表示病在骨，因为沉脉就是讲骨头有病，而肾脏就是主骨。弱脉出现，是主筋病。\n\n      『沉即  为肾，弱即为肝，汗出入水中，如水伤心，历节黄汗出，故曰历节。』 中医讲的历节，起因都是肝肾两虚，病在筋骨之间游荡，就叫做历节。\n\n       历节病在临床上看类似于西医说的痛风与风湿病。实际临床上大家可以看到有三种不同的症状。第一种，中医叫做风痹。风痹的主要症状  是麻又痛，连皮肤都会又痛又麻。第二是血痹，血痹的主要症状是『麻而不痛』，单纯只有麻的感觉，没有痛症。风痹有专治风痹的汤， 痹有专治血痹的汤，像黄耆五物汤就是治疗血痹的。第三种就是历节病，而历节的主要症状是『但痛不麻』，这是中医用外在的症状来区分的。\n\n         西医临床上看到很多痛风或是风湿都有这种症状。像你开『甘草附子汤』给病人的时候，而这处方只是治疗风痹，当风寒湿相混合在一起时，病人会有各种不同的症状出现，如果是只痛不麻的话，我们就把他当成历节在治疗，治历节的处方有乌头汤，或是大乌头煎等。 如果是血痹，就是黄耆五物汤证，血痹的主要症状就是麻，纯麻的感觉，那种麻是很顽固的麻，有的麻十几年来都在麻，黄耆五物汤专门  治疗麻的症状，麻是非常不易被治好的，而这是血痹特有的症状，也就是血虚。\n\n      现在讲的历节，它的起因中医认为是肝肾两虚，有一天肾脏的新陈代谢功能不是很好，它没有办法把废物排泄出去时，由于水生木，因此所有的脏东西会因此而进入肝脏，如果此时肝脏本身又虚 了，脏东西到了肝里面等待分解时，肝没有办法把它排出来，这个时候脏的物质就会沉积在身体里面，也就是所谓尿酸沉积在身体里面， 逐渐的沉积日久以后，就会囤积在骨头旁边，因为尿酸是呈结晶状， 挤在骨头旁边当然会很痛，痛起来的时候，就感觉脚好像放在油锅里 面，烫而且肿，那种滚烫的感觉很痛，脚背也肿起来，常常发生在脚 背还有脚关节的地方。最严重的痛会持续两个礼拜以上，一般痛一个 礼拜到两个礼拜慢慢就会消除掉。哪种人会得到这类的病呢？诸位看 下段的说明。\n', NULL, NULL, NULL, NULL, NULL, '8、寸口脉沉而弱 ，沉即主骨 ，弱即主筋 ，沉即为肾 ，弱即为肝 ，汗出入水中 ，如水伤心 ，历节黄汗出 ，故曰历节。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651961713930309, '8589EBC34B26F45DC369003594DF2558', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 16:19:02', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8109, 446, 905007007, '       头风摩散，这个药专门是治疗偏头痛，头痛欲裂，然而一定要有热症在头上面出现时才用，像眼赤红，同时头痛又痛的很厉害。\n\n      这种状况之下我们用炮附子做粉跟盐合用，比如说你拿一茶匙的炮附子粉剂，然后拿一茶匙的盐巴，两个等量将之混合在一起，然后加入水和一和，直接涂在头痛的地方，这就是专门治疗强烈头痛的外敷药，这头风摩散，就比较像张仲景的处方。张仲景很少用到石类的药，像紫石英就很少用到。张仲景一般最多只使用到赤石脂、禹粮石这类石药。\n\n       接下来我跟大家介绍三个方剂，大家可以补注在这里，或是做在笔记里面，这第一个处方是从千金要方里面摘录出来的，这三个就比 较像经方了。\n\n      第一个，我们叫『千金三黄汤』千金三黄汤主症手足拘急，同时病人全身骨节痠痛，病人也会烦热，情绪烦躁。然后心乱恶寒怕冷，病人有这种症候，然后又终日不欲食，没有胃口。遇到这种情形的中风，大家就用$n{千金三黄汤}，千金三黄汤是$u{麻黄}、$u{黄耆}、$u{黄芩}，然后再加$u{独活}还有$u{细辛}。\n\n      像这种心乱恶寒，寒很盛的时候，我们可以用细辛来壮里阳。有虚热在上焦时，治烦热，就用黄芩。黄耆作用在固表虚，麻黄用来发病人的肺阳，可以将病人全身骨节痠痛去掉，独活 就是协助麻黄去发表汗，当麻黄遇到细辛时，细辛会把麻黄拉住。所以伤寒论少阴证时，我们使用麻黄附子细辛汤，病人吃了麻黄附子细辛汤反而不会流汗，只会让小便量增加，少阴证就得解了。\n\n     麻黄遇到细辛，细辛从下面把麻黄拉下来，于是就不会发表汗发太多，这些药配合在一起药就很强。如果你说：「老师！我们平常都喜欢加甘草。」 一旦加甘草下去就不叫三黄汤了，所以不可以随便加甘草。我们在急救中风时，病家已经都这样危急，结果你还在那边缓攻，甘草就是缓攻，所以外面南派的中医，什么药都加有甘草，这会害死人的。\n\n       第二个方子是很有名治疗中风的处方，方名叫做『$n{小续命汤}』， 平常我们看到中风，十之八九都是在小续命汤上面做加减，小续命汤源出于外台秘要。\n\n       这个处方里是麻黄桂枝并用，处方很大胆，这就很厉害了。平常中风如果我们会用到麻黄桂枝，一定是用在比较深度中风的病人才会用到麻黄桂枝。一般中风的人是不会用到麻黄桂枝的， 而这里会用到麻黄桂枝，一定是张仲景的原方才有可能，张仲景敢这样用因为还有加别的药在里面，用到麻黄时担心病人会汗发太多，所以一定会用到杏仁。杏仁跟麻黄并用，前面就已经出现在麻黄汤里， 麻黄跟杏仁用等量，就是说如果开了麻黄三钱，杏仁就开三钱来配合麻黄的量，这样就绝对不要担心肺的津液会被麻黄伤到，不要担心汗流太多。桂枝跟炙甘草，都是健脾整胃，把虚寒的脾胃补起来。这个时候如果我们加入当归川芎，只遇到病人血虚掉，就用当归来补血， 川芎是活血用的，川芎一下去，能够让我们补进去的血运送到全身四肢关节上去，所以用川芎。平常得到中风的病人，多半兼有痰涎壅塞 的现象，积在胸腔里面的痰，会使胸腔里面太热，所以最后再加了石膏，石膏在此是要去里热的。\n\n        「老师，此处为什么不用涤痰的药？ 」 我告诉大家，因为病人已经虚了，所以不加。过去的金元四大家，就是指金朝、元朝时期的名家。金元四大家所有的观念里面，谈到中风， 就是痰饮跟风火，就是风火相交，痰痈很多。所以他们开的药都是去火祛痰的药，我们北派很不赞成这样子，因为我们临床上看的时候摸 到病人的脉都是气血两虚，我们在补气补血的同时，还需要把病人寒与热一起排掉，因此一定会有去寒去热的药并用在同一处方里，所以你们会看到石膏跟干姜在一起合并使用。所以炙甘草、干姜来温补中 气，让他的肠胃的功能恢复起来，整个处方用起来，就是所谓的小续命汤。麻黄,杏仁,桂枝,炙甘草,干姜,当归,川芎,石膏\n\n       小续命汤的剂量该用多少呢，就要看病人有多重了。像比较强壮 的人，麻黄可以开到五钱以上，桂枝开八钱以上，遇到体型较瘦的， 麻黄可以开两钱，病人体格如果更小，麻黄用一钱，如此决定加减， 只要麻黄跟杏仁是等量在使用，就不会失津。在这个方子里面的炙甘草跟干姜是要去健中、健脾胃，所以甘草的量就会比较多，比如说甘草五钱，干姜三钱。当归我们一般使用的时候是五钱的量，当归和川芎我们可以等量使用。为什么等量使用？ 因为当归是补血的，川芎是活血的，它可以将当归带到全身四肢末梢去。你说：「老师，这个病人的血实在太虚了，我想当归用到一两。」当然可以，大剂的可以用一两，川芎也可以用到一两。石膏在这里用五钱就足够了，强壮的体格用五钱，平常用三钱就可以了。如果病人有壮热出现的时候，石膏就要加重。热的原因，就是阳往上走，阳往上走的症状，西医称为脑充血。就是浮阳停在脑部上面，无法下来。这时我们使用降热的药， 就要靠石膏了。\n\n       小续命汤证主要的症状跟刚刚千金三黄汤不一样，也同样是有手足不仁，但是兼有口不能言，这就比较重了。然后不知痛 处，你问他哪里痛？病人连痛处都不晓得在哪，此时病人的神志有点 不清楚了。同时出现四肢拘急，全身绷紧不得转侧。需要翻转时，都要靠家人帮忙翻转。很多中风病患躺在病床不能动，结果造成褥疮， 经久不愈。吃小续命汤的时候要注意一点，这个药吃下去以后，病人要采坐姿，坐在那边，得汗则解。\n\n      如果遇到说：「老师，他没汗啊？ 」 没汗就再吃，因为药没有到位，等到药到位了就会得汗，采坐姿，得汗就会好，可以停药了，这是我们最常用的治疗中风的方子，我常常  在这个方子里面做加减，这个处方非常好用。\n\n       临床上用这个处方几乎都可以将十之八九以上中风的病人救回来。\n\n      最后还有一个复方，就是前面诸位学过的『术附汤』。白术、附子、生姜、甘草、大枣，这五  味药组成的术附汤。我们在使用的时候，病人一定要有风症，风虚头眩，也是中风的现象，头昏，非常的昏眩，眼睛都不能张开，吃东西都没有味道了。这时我们要靠生姜甘草大枣去健脾胃，我们靠白术附  子，白术去通利他的三焦去湿，靠附子来去寒，这就是术附汤证。用汤剂的时候，我们用甘草或炙甘草都没有关系，病人有里虚的时候我们用炙甘草是最好。\n\n       所以以后大家遇到中风病患时，前面的侯氏黑散  你不需要使用，还是记住这三个方子更好用，尤其是小续命汤。小续命汤内容真像出自于张仲景的手法，过去从汉朝到现在，麻黄桂枝一起用在虚症上面，绝对是没人敢用，南派的看到麻桂如看到蛇蝎般，咸认为：「吃了会死掉。」当病进入脏后不借用麻桂是攻不出来的，像舌强不语，就表示病中脏了，进入人体很深的地方。这个时候要大剂的药攻下去才会对病情有所帮助，病人虚掉时我们使用很强力的药在里面，只要注意攻补兼施的药一起放在处方里面，就不会有问题，而 这个方子设计的非常的好，这个可能比你学别的还有用。\n', NULL, '头风摩散方', NULL, NULL, NULL, '7、$f{头风摩散方}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651961713930310, '5498545FE86D7CFDD623599DB6157030', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 16:19:02', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8110, 446, 905007006, '       像风引汤，我用的也是不多，我很怀疑这些方子都不是张仲景开 的。如果是张仲景处方的话，为什么要叫『侯氏黑散』？ 为什么不是叫做『张氏白散』呢？他一定会用张氏之名。\n\n      诸位再看风引汤，专治热瘫痫，就是热症中风，完全是里热症，里面很热的时候，又遇到表风。里面本身就虚，虚久后产生的虚热，此时表又受到风。我们除了开补虚的药，还要同时开去热的药，也还要再开去表风的药，药力一定区分为这三种，你看大黄是去里热实的，像干姜、龙骨、桂枝、牡蛎这种都是补里虚的，还要加上去热的药，像石膏，就是去热的药。\n\n       为什么要用寒水石、滑石、赤石脂、白石脂、紫石英这种涩剂，一般我们使用涩剂时，是因为石头的药都是比较涩，而病人身体里面有虚热的时候，大便时会有下利，肚子会痛，像肠鸣下利般，食物是不会停在肠胃里面。所以就需要加进去很多涩剂像赤石脂、紫石英、白石脂等。', NULL, '风引汤', NULL, NULL, NULL, '6、$f{风引汤}，治除热瘫痫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651961713930311, 'F7E8B8A68FD0691BFEBF1EE338422538', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 16:19:02', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8111, 446, 905007005, '        侯氏黑散『治大风四肢烦重心中恶寒不足者』。『菊花、白术、防 风、桔梗、黄芩、细辛、干姜、人参、茯苓、当归、川芎、牡蛎、矾 石、桂枝』。\n\n        侯氏黑散这个方子绝对不是张仲景立的，一定是后人借他的名立进去的，此方的目的是填补。\n\n        为什么叫填补？这个方子的观 念是，病人身体里面虚掉了，结果造成表风进来补里虚的位置，就是当中风进来的时候和病人的里虚没有完全接在一起，中间就有很多间隙产生，间隙的产生是病人的气和血没有办法沟通，于是产生半身麻痺，这个侯氏黑散就是能够慢慢的把空虚的部分填补起来。\n\n       这是一些外面其他医生设计的药，不是仲师原方。我们临床上用的不多，我没有用过这个药来治疗中风。制作法是将这十四味杵为散状，就是弄成粉剂样。『方寸匕』就是一个汤匙的，一天吃一次，刚开始服前二十天用温的酒来喝，一切的鱼肉大蒜都不要吃，常吃冷的食物。吃了两个月以后即『药积腹中不下』，让药力慢慢的渗进去里虚的位置。要让药力停滞不下的话必须要冷食，一吃热食药力就下来了。所以要冷食目的就是让药不要跑掉，让药尽量囤在身体里面慢慢渗进去。实际上这种方子都没有我们后面的方子好用，后面会跟大家介绍外台秘要里的处方，那些方子还比较像张仲景立的方子，可能就是我国千年以 来，失落的经方。', NULL, '侯氏黑散', NULL, NULL, NULL, '5、$f{侯氏黑散}治大风四肢烦重心中恶寒不足者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651961713930312, 'C466EB96694F61EE99C63D762054A134', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 16:19:02', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8112, 446, 905007004, '       当你摸到病人的脉很浮，表示病还停留在表，没有走里，所以同样是中风，如果出现脉很浮，代表风邪仍然在表上，这种中风很好治。 有的时候病人是气血两虚，摸脉时病人的脉沉得很深，这表示风在很里面，中医诊断中风可以从脉症中探知。\n\n     『病如狂状』就是还没有到发狂，看起来好像狂，也就是说病人的情绪很烦躁。\n\n     『妄行独语不休』就是一个人在那边到处走来走去， 自言自语，这种就是气血两虚的状态下引起的。\n\n      中医认为，风入肝，肝脏本身就是风脏。如果一个人中风，当风进入身体后，由于跟肝的属性是相同的，所以会直接连到肝，肝受到风干扰而出现问题时症状一定是『动』。\n\n      所以入肝就叫『诸风掉眩』也就是动症，病人会动来 动去，像西医说的柏金森氏病般在那边动个不停。柏金森氏病症状很特殊，病人一动一晃的不停，甚至于连眼珠子都在晃。我们知道动症起因是肝受到风的影响，所以连眼珠子都会晃动。\n\n       肝主怒，怒能伤肝， 本身肝有问题的话就会有暴怒的现象，所以出现『如狂状』。这种状 况之下，中医的基本观念，就是要把表邪去掉，同时将体内的气血补足，因为里面虚寒才造成这样子，治此病并不是从肝脏入手，所以仲师用防己地黄汤。\n\n      防己、甘草、桂枝、防风这些药的比例，防己、甘 草是一，桂枝是三。你不要开一分、三分，这种轻剂量治疗牙齿中风可以用，治疗中风的人需要大剂的药，使用三钱五钱一剂都不为过， 比例要知道。同时像防己本身能够去湿，中气不足的时候用甘草。桂枝和甘草补中，都能够补中阳不足，让脾脏开始运化。防己和防风， 都能够去风。这处方是遇到病人的风邪直接进在皮表，停在经上面的 时候使用的，是最浅的处方。这四味药先用酒泡过，泡完以后再绞它的汁用，汁里面就有药跟酒在里面。生地黄，也要大剂的用，剂量用两，差不多用到二两到三两才够量。\n\n        遇到体格比较大的病人，使用四两以上都没关系。地黄生的时候是黏答答的、黑黑的，你把它放在锅里蒸熟，好像蒸米一样，隔水蒸， 不要浸水。蒸熟了以后把它拿起来绞汁。把生地黄绞成生地黄汁，然后跟刚刚前面已经绞成汁的四味药，混合在一起，喝下这个汁，才是 真正的防己地黄汤。地黄汁必须是绞汁的，把它蒸熟的，不是煮熟的， 利用地黄来补病家的血不足。靠桂枝甘草来健中，来加强病人的肠胃功能，然后开一点防己防风去风。如果你说：「老师啊，去风我们可以用很大剂的表药。」此处是行不通的，因为病人本来就虚，你不能开太强的发表药，一旦发汗发太过的话，会造成本来肠胃津液就不足的状况下，又再被发掉了。我们又需要再补足病人肠胃的津液，这是多此一举，如果是遇到比较强壮体格的人得到感冒，就是单纯的桂枝汤证。\n\n       可是现在是遇到的是中风的人，病人本来就是因为里虚所以才会中风，一般里虚不足的时候，我们需要补里虚的同时要解表，开的解表药一定不是像麻黄汤桂枝汤之类的强药，必定是选用比较缓和的药。\n\n      哪些药会比较缓和呢？像瓜蒂，取吐法后，病人也会因吐而流汗， 前面百合病也有跟大家介绍过，不需要用很强的麻黄汤等。比如说已经中风的病人，你给他喝麻黄汤，本来他的肠胃津液就已经虚掉，这 下肠胃津液就更干了。造成病人因表汗过多而表虚，里津不足里又虚 掉，这只会使病情更坏，所以开发表药时我们要看时机使用。', NULL, '防己地黄汤', NULL, NULL, NULL, '4、$f{防己地黄汤}   治病如狂状 ，妄行独语不休，无寒热，其脉浮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651961713930313, '5E0D94CAC204723DCBD77F575F61DBFD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 16:19:02', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8113, 446, 905007003, '      『寸口脉』如果『迟而缓』，脉跳得很慢、很迟，脉来一息一至、 二至，这是『迟则为寒』。寒都是很迟的脉，缓则为虚，缓的意思是 脉很弱，就是摸上去感觉脉跳起来的力量很弱，所以这是指又寒又虚 了。\n\n     『营缓则为亡血，卫缓则为中风』就是血脉缓的话就表示病人失血，气脉缓的话就表示病人中风了。\n\n    『邪气中经，则身痒而瘾疹；心 气不足，邪气入中，则胸满而短气』这个意思就是说，如果一个人是气虚掉，于是风邪等外感进入我们皮肤表面上，我们会感到皮肤身痒， 出瘾疹，就是发红疹。但是如果遇到本身是心气不足的病人时，邪气 就会进入病人内脏，而第一个受到影响的将会是肺，因为病人本就虚 了，寒进来就会束在肺上面，把肺缩小了，这个时候你想要大力呼吸， 它又无法大力呼吸，于是就会感觉到胸腔很胀满，气短。一般来说像 这种风疹，身痒而瘾疹，我们都是用麻黄加术汤来治疗。前面我们已 经介绍过此方，麻黄汤加白术在里面，专门用来治皮肤痒疹。', NULL, NULL, NULL, NULL, NULL, '3、寸口脉迟而缓 ，迟则为寒 ，缓则为虚； 营缓则为亡血， 卫缓则为中风 ；邪气中经，则身痒而瘾疹；心气不足 ，邪气入中 ，则胸满而短气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 651961713930314, 'BED05F2CCB110417EB0CC3B2D5FDC3E4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 16:19:02', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8114, 446, 905007013, '       矾石汤你千万不要拿起来喝，喝了后你身上的津液通通会沉淀下 来，血也沉淀了。\n\n       明矾怎么可以吃？矾石汤是『脚气冲心』用的。我 们平常有香港脚或是糖尿病等，造成脚溃烂掉或流脓，毒气一直往上冲很难过。这个时候你拿矾石，最好找到自然的矾石比较好，自然的矾石我们加热后烧出来还是白色，人工制造的矾石，与天然的成份都一样，但是烧出来颜色比较黑，这两个不太一样，选用自然的矾石比较好。这是泡脚汤。\n\n        明矾你用二两都没有关系，用浆水，就是用自来 水来煮过，煎三五沸，滚了以后化掉了就可以停火了，你不需要：「老师，三碗水熬成一碗。」那矾石就不见了。水滚一下化掉就可以用， 把脚浸泡下去就好了。矾石这个药性很干燥又涩，就是因为性燥又涩， 所以我做的麝香矾石散，可以喷到鼻子里，因为矾石是很干燥的燥剂， 可以将鼻窦中的湿涕清干，而脚有湿气会黏答答的，这时就可以用矾石汤来泡脚。如果是脚气，像湿很盛，我们可以内服桂枝芍药知母汤， 配合针灸针三皇穴，就是阴陵泉、地机、三阴交，同时针专门去掉脚湿肾经的水泉穴，扎完针后，将脚泡在矾石汤里面，如此治疗脚气效果非常好。包括香港脚，还有更严重的，像脚整个烂掉，毒气一直往上冲，都可以使用它。矾石能够收敛湿气，专门去湿解毒。如果只是感觉很轻微痒痒的，就不需要用到此方。', NULL, '矾石汤', NULL, NULL, NULL, '13、$f{矾石汤}治脚气冲心', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652221993439301, '39FD9FB7BE6FF9110A6D0F6B9806C54E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:58:07', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8115, 446, 905007012, '       『病历节，不可屈伸，疼痛』痛的很厉害，病人没有抱怨麻木。 我们最常用的方子就是这乌头汤。乌头汤是治疗历节重症用的，还有另一个更重的处方，我们此处说的是乌头汤。\n\n        乌头汤内容是麻黄、芍 药、黄耆、炙甘草等量。诸位先看里面乌头的制法，乌头五枚，就是搅碎了以后『以蜜二升煎取一升即出乌头』。\n\n        乌头和附子在本草里面是同科的本草，本草经说乌头植物下面的根茎上，生了一些块茎附着 在根茎上面，就是『附子』。一般附子是三年采收，第四年的时候把茎拿下来用，就是『乌头』。如果到了五年以上，使用整个茎时，这个就叫做『天雄』。\n\n       天雄是壮阳药，在神农本草经里面是壮阳最强的 药物了。我们经方里面所选用的药物都是出自于神农本草经，当然我 们还有一些像阳起石等很多的壮阳药，但天雄是我们经方里面最强的。\n\n        现在要用乌头，乌头跟附子是同科的，也是很热的药，药本身的毒性非常之强，而去乌头的毒有两个方法，第一个，我们先把乌头放在锅子里面，放水二碗，然后煮成一碗，之后要把乌头渣滤掉，然后拿一碗蜂蜜，倒下去跟这乌头汁混合后一起再熬，熬成一碗之后就可以用了，这就是乌头蜜，此时乌头蜜的颜色是很暗的，而且很浓很甜， 鸟头汤是很甜的药。\n\n        如果遇到『酒客不喜甘』，病人平时就喜欢喝酒， 这种人在喝鸟头汤时，就会感觉很难过，还有中湿很盛的人也都不喜 欢吃甜的东西。其他像麻黄、芍药、黄耆、甘草等，千万不要给病人用三两，大部分都是三钱，如果痛得厉害的话就加重到五钱。麻黄、 芍药、黄耆、甘草都是等量的用。将这四味药以水六碗煮二碗，把药渣拿掉，留一碗在锅中，再放入鸟头蜜一汤匙，就是刚熬的鸟头蜜， 混和起来，再煮一次，煮成八分这样子，然后就可以喝。喝下去以后， 如果『不知』就是没感觉，就再喝。如果出现头昏、手麻就立刻停下 来，不可以尽剂，这就是鸟头汤的正确服用方法，像膝胫、足踝部位、 四肢关节肿胀疼痛等症状出现时皆可用。\n\n        乌头汤证是治疗寒湿历节的正治法，之所以要用麻黄不用桂枝就是因为桂枝力量不够，要靠麻黄的阳使药力透达到四肢上面，白芍可以让被寒湿堵到的四肢关节末稍要回流心脏的血液流回心脏，黄耆是 走表的药，能固表，不让外感的风再进来，炙甘草是因为怕麻黄喝下 去以后，会造成肠胃津液的丧失，所以甘草下去，可以立刻将肠胃津 液补足。\n\n        我们一般药在胃里面，等药力达到四肢时，必会耗时很久， 乌头很快的就可以把药运送到四肢上，乌头药性极热，所以去寒力很 强，可是如果光用乌头下去又有毒，跑的又快，所以用蜂蜜去缓它的 速性，蜂蜜不但可以把鸟头的毒解掉大部分，同时蜂蜜可以告诉乌头： 「你慢一点，你是很好的药，但是要慢一点，不要走的那么急，那么快。」这样速度减缓下来后，就可以把深入关节中的历节风湿去掉。', NULL, '乌头汤', NULL, NULL, NULL, '12、病历节 ，不可屈伸 ，疼痛 ，$f{乌头汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652221993439302, 'D288700A2773B14822070759B2198AF8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:58:07', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8116, 446, 905007011, '     『味酸则伤筋，筋伤则缓，名曰泄』就是如果长期都吃太酸的食物会伤筋，如果长期都吃太咸的食物会伤骨，\n\n     『骨伤则痿』就是四肢 会萎缩掉，这个名曰『枯』。如果是筋伤到，加上骨又伤到，就是『枯泄相抟』中医叫『断泄』。\n\n      『营气不通，卫不独行，营卫俱微』就是气血两虚，『三焦无所御，四属断绝』结果造成『身体羸瘦，独足肿大， 黄汗出，胫冷，假令发热，便为历节也。』所以说，如果没有发热， 只发黄汗，就是我们前面说的黄汗，它与此处说的历节的病因是一样 的。如果病人燥热，关节很热很痛，病人跟你陈述说脚好像放在油锅里面炸那么热，这就是但热不寒，一定是历节了，这些都是可以帮助我们了解历节的原因，是出在肝肾两虚的状态，寒湿下注下来，才会造成这样的，可以治疗历节的汤方就是现在要介绍的『乌头汤』。', NULL, NULL, NULL, NULL, NULL, '11、味酸则伤筋，筋伤则缓，名曰泄。咸则伤骨，骨伤则痿，名曰枯 ；枯泄相抟 ，名曰断泄。营气不通 ，卫不独行 ，营卫俱微 ，三焦无所御，四属断绝 ，身体羸瘦，独足肿大 ，黄汗  出 ，胫冷 ，假令发热 ，使为历节也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652221993439303, 'A75A7F653B971E0C3702E04AA37C3500', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:58:07', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8117, 446, 905007010, '        这个处方是治疗阴虚的主要处方之一，专门是用在阴虚的病人身 上。这段是说，只要病人身体很瘦弱，两个脚肿起来，这就是气血两虚的人。身体很瘦又全身关节痛。这一定是脾脏虚掉，脾主四肢，主肌肉。\n\n       『头眩短气』是因为血虚掉，头就没有办法受到正常的血的供 养，造成头会昏眩。短气的原因是因为里湿太盛，这种状况出在病人本身是虚，同时湿又很盛，又兼有寒。\n\n       『温温欲吐』这感觉就是胃里面很难过，想吐又吐不出来，就是温温欲吐。有这种症状的病人，多是在身体里面三焦油网部分受到湿的侵估，就会出现这种现象。\n\n        中医的名词是『胃中有伏热』，正常的热是应该沉在下面，寒在上面，所以热本身是被寒收敛在下面，热不该浮上来，有一天，病人里寒太盛， 这个热没有办法待在下焦，只好往上跑，于是热浮在上面，寒在下面， 变成上热下寒这个样子。也就是我们讲的三焦气虚的状态之下，三焦气会虚，就是因为脾胃本身无法正常吸收营养，影响到三焦也没有办 法完全运化营养，三焦无法运化时会让里湿更盛，加上脾阳不足，四肢关节就会空虚，里虚加上湿停滞太久，于是湿就逐渐累积于关节之中，造成四肢关节都会肿大疼痛。\n\n        我们治疗历节第一个处方，就是桂枝芍药知母汤。大家现在都该知道，桂枝芍药是健脾的，但是桂枝芍药知母汤中桂枝用四，芍药用三，桂枝稍微重一点， 目的是要让药走到四肢。甘草、麻黄、附子， 用麻黄跟着桂枝，是因为桂枝可把麻黄的药力推到皮肤表面上。白术是去湿用的，防风能祛风去痛，附子在此的目的是去寒。所以这个桂枝芍药知母汤里面白术、知母、防风等量大剂的用，甘草、麻黄、附子按照经方的比例等量用，但是稍微少一些，然后再重用生姜。开立 桂枝芍药知母汤处方时要记得，要重用生姜，平常我们生姜两片就好， 但是在这个处方中生姜要加重到五片，因为生姜到了胃里面去以后， 生姜产生的热是散开的，不像干姜是温中。这里是要把胃里面的胃阳散到三焦网膜上面，所以需要重用生姜。\n\n        临床上这个药方我时常在用， 什么样状况的病人用到最多的桂枝芍药知母汤呢？就是糖尿病的病 人，中医讲的是症状。\n\n        西医说糖尿病的病人有一种是得到了就会很胖， 越吃越胖。有一种呢，越来越瘦，体重直线下降，瘦的就是桂枝芍药 知母汤证，到最后阶段西药无法继续控制血糖后，病人到后来身体很瘦，但是脚却变成肥大。\n\n       中医认为「男怕脚肿，女怕头肿」，就是男人身体一直瘦，唯独脚肿起来，这是很危险的症状，此时就是桂枝芍药知母汤证。这种汤剂喝下去的时候，表面上看起来我们是在治疗历 节风，同时又兼治病人气血两虚的身体，我们用补虚去寒去湿的药， 还有固表的药同时一起来。这个处方因为桂枝的加重，比芍药加重一个比例，所以能够走表。这个药吃下去以后，病人关节痛就会减轻， 然后血糖降得很快，时常可见血糖从三百多降到一百多，过去我用过很多次，效果是立竿见影的。\n\n       『所谓不通则痛也。』不通的原因是因为里虚掉了，所以说『身体尪羸者，统血之藏久虚。』统血之脏就是脾脏，久虚掉就是脾脏没有办法统血，这个时候因为血没有办法充分供应到四肢肌肉上面，才造成全身关节都会痛。\n\n       『脚肿如脱者，寒湿下注』所以桂枝芍药知母汤是常被经方家用来补虚治湿于同时的处方。\n\n        诸位看看案例。有一个孕妇怀孕八个月，先生把她带来求诊，自述『病人身重，将腹中小儿压毙。』『把小孩子压死掉了以后，结果『妻病腹痛，乃求医』医生开药来帮忙堕胎。而此妇人，本来就是属于身体血虚的人，这个时候我们用攻下死胎的药物会导致血更虚，因为攻胎药大部分都是破血的药。病家体虚，结果湿毒留在腹里面不去，日久乃旁溢到四肢上面，结果造成病人肚子里面有死血，『寒湿并居』 造成『因病历节』。\n\n        中医的历节的观念，诸位记得『但痛不麻』只有痛，而关节都肿起来，时常可见整个手指头的关节，还有身上有关节 的地方都肿起来。尤其是妇人很多都有这问题。\n\n       『手足拘挛，入夜手足节骱剧痛』，痛风的病人就是中医讲的历节，大部分都是晚上发， 入夜的时候痛得最厉害，因为她是虚症，病又在阴，所以晚上的时候痛得最厉害，白天比较好，这是阴寒无疑。\n\n        如果用原方就是『每两折为二钱』再用『用熟附块四钱』，喝了两剂后如果没有感觉，就要改用生附，我要跟诸位讲这个例子的原因是当有一天遇到炮附子下去推不动病情的时候，就该把炮附改为生附，最严重的状况，我会生附、 炮附并用，炮附会走表，生附是温里。炮附吃下去以后，药马上就会到皮肤上面，关节就可以通畅无阻了，所以这样使用是非常的厉害。\n', NULL, '桂枝芍药知母汤', NULL, NULL, NULL, '10、诸肢节疼痛 ，身体尪羸 ，脚肿如脱 ，头眩短气 ，温温欲吐 ，$f{桂枝芍药知母汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652221993439304, '778F0B73D07547AD5AEA66F3F970BD9A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:58:07', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8118, 446, 905007009, '       『趺阳脉浮而滑』这讲的就是胃脉。第一种会得到历节的原因就  是，当汗流得很多时，立刻进到冷水里面，这会使得人体汗出不透， 跟前面说的黄汗是同源的。第二种引起中风历节的原因，是『趺阳脉』 就是所谐胃脉，在冲阳穴位的脉。\n\n       『浮而滑，滑则榖气实，浮则汗自出。』『谷气实』代表胃中有实，就是有宿食停在里面，此时就会摸到  趺阳脉不但滑，而且实。\n\n        这里的太阴脉讲的是我们的脾脏，如果是弱脉表示血虚，而脾主四肢，主肌肉，当脾脏功能不好时，固表能力就不够。这个时候风进 入体内，正好遇到此人血不足，而血不足的原因，可能肠胃吸收不是很好，生血的过程不是很好，这也会造成疼痛如掣。\n\n         还有一种疼痛， 就是『盛人脉涩小，短气，自汗出，历节疼，不可屈伸』什么叫盛人？ 这里的盛人，过去说的就是有钱人，家里环境很好的，每天都大口酒 大口肉的吃，然后妻妾又很多，\n\n      『脉涩小』是因为运动很少，养尊处优，于是脾阳不伸，没有办法到达四肢，肉很多只是外表看起来比较 实，其实是中干，因为这些都是吃很厚腻的食物产生出来的肥脂，并没有固表能力，都是肥油在里面，这个时候脉就比较短小，\n\n      『短气， 自汗出』。平常喝酒喝的很多的人，身体里面湿就会很盛。喝酒后感觉是身热，但是到身体里面就变成湿。因为平常没有运动，又近女色， 喝酒又喝得多，结果表虚掉里面又湿，这又是一个很容易得到历节病的原因。\n\n        现代人得到则是因为吃西药过多伤到肝肾，加上喝酒喝多了伤肝，近女色过多了又伤肾，这也是肝肾两虚的原因，这种『历节疼， 不可屈伸，此皆饮酒汗出当风所致。』所以本身身体是虚的，加上运动量又少，以致表虚掉，风就容易进来，然后风与湿混合在一起，就成为风湿。一般经常喝酒的人，我们时常用苍术泽泻来解酒，苍术很燥可以把体内的湿去掉，以上这些都是造成历节病的种种原因。', NULL, NULL, NULL, NULL, NULL, '9、趺阳脉浮而滑，滑则谷气实，浮则汗自出。太阴脉浮而弱 ，弱则血不足 ，浮则为风 ，风血相抟 ， 即疼痛如掣。\n盛人脉涩小 ，短气 ，自汗出 ，历节疼 ，不可屈伸 ，此皆饮酒汗出当风所致。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652221993439305, '6733CE44D433039516D253E7E42F8AAC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:58:07', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8119, 447, 905008003, '     『平人』，就是指正常人。人好好的看起来都没有病，结果摸他的脉却很数大，这就是劳症，如脉出现极虚也是劳症。脉大代表里面是中空的，所谓劳症就是正常人稍微劳动一下就感觉很累，所以不能动， 一动就累。\n\n        比方说一般人打高尔夫球连打三十六个洞，而此人打完第 一个洞就没力气了，必须睡一天，这就是劳症。平常很正常，胃口也很好，吃了很多食物，然而吃完还是很累，身体还是吃不胖，有劳症的人是不会胖的。如果减肥要成功，就想尽办法把你变成劳症，而劳症还不容易得到的，因为劳的原因很多，后面会跟诸位介绍。\n\n       多数时劳症表面上是看不出来的，因为他根本就是正常人，这段是说有两种状况我们可以从脉象上查觉到劳症，一个是脉大，一个是脉虚。', NULL, NULL, NULL, NULL, NULL, '3、夫男子平人脉大为劳 ，脉极虚亦为劳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652330704437317, 'DBBEFE6402F6E3166DA6F2D5D5E9104F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 17:20:28', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8120, 447, 905008002, '        血痹的症状，阴阳俱微，寸部与尺部的脉都很微弱，这是气血两虚的状态。\n\n      『寸口关上微』寸脉和关脉都是很微弱，『尺中小紧』代表阴血不足，尺代表阴，寸代表阳，尺中小紧表示下焦不足。\n\n     『外证』 可以看到是『身体不仁，如风痹状』身体不仁，没有讲痛，就是只有麻木，全身都有可能出现麻木。有时候手臂麻，有时候脚麻，不一定 的。\n\n    『黄耆桂枝五物汤主之。』黄耆桂枝五物汤的处方，就是把桂枝汤里面的甘草拿掉改成黄耆，同样是桂枝汤，你把甘草拿掉，换成黄耆， 就叫做黄耆桂枝五物汤。\n\n       这个处方的重点就是黄耆、芍药、桂枝是等量，生姜要加重，如果只加两片，就没有效了，麻还是会照麻。生姜加重到五片、六片，很辣，桂枝已经很辣了，这是因为要利用辛甘发散为阳，才能够让黄耆的药力从肠胃发散到四肢上去。气血两虚的症状会有麻痺的现象，用黄耆是因为它能够通透皮表，所以能够去麻。 桂枝汤之所以要有桂枝白芍就是要增加脾脏的功能。脾脏的功能强起来，气血就会兴盛。所以黄耆桂枝五物汤吃下去后胃口会开，胃口一 开吃了食物，血就被补足了。\n\n       伤寒论里经方的正治法，一般是不赞成给病人吃太多的补药，除非是病人很虚弱，我们才会给他，否则的话 我们都不会给病人补药，我们宁可将病人的脾胃强壮起来，让病人感觉饿，可以吃，然后让他的肠胃能够吸收食物，这是最好根治补虚的方法。治疗血痹，用的最多的就是这个处方。\n', NULL, '黄耆桂枝五物汤', NULL, NULL, NULL, '2、血痹 ，阴阳俱微 ，寸口关上微，尺中小紧，外证身体不仁 ，如风痹状 ，$f{黄耆桂枝五物汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652330704437318, '9664C337786EDDB5C9314BFA2CD73C0D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 17:20:28', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8121, 447, 905008001, '      『血痹之病，从何得之？ 』张仲景就说：『夫尊荣人』就是家里面 养尊处优的有钱人，他只在乎如何享受，结果『骨弱，肌肤盛』就造成骨头很弱，肌肤很盛，因为他缺少运动。这个时候如果再加上『疲劳汗出』，其实这说的就是行房事后流汗当风，因阳虚而导致『卧不时动摇』睡在那边动来动去，再加上睡时又被微风吹到身体，这个时候得到的就是血痹。\n\n       『但以脉自微涩在寸口，关上小紧，宜针引阳气， 令脉和紧去则愈。』如果病人得到只是比较轻微的血痹，就是只发现寸口脉微涩，而寸口上有涩脉也代表血虚掉，因此这个人等于是气血、 精血两虚的时候得到了痹症，手臂肩膀都会麻，讲痹症就多是麻木， 少有痛症，我们可以用针灸治疗他。\n', NULL, NULL, NULL, NULL, NULL, '1、问曰 ：血痹之病 ，从何得之？\n\n     师曰 ：夫尊荣人，骨弱 ，肌肤盛 ，重因疲劳汗出 ，卧不时动摇，加被微风 ，遂得之。但以脉自微涩在寸口，关上小紧 ，宜针引阳气 ，令脉和紧去则愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 652330704437319, '40EA4CDC42863C1DDFAE9F4FD385B71D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 17:20:28', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8122, 447, 905008009, '       你遇到一位正常的男人，一切都好好的，但是你摸他的脉时「咦？ 怎么脉重按就没有，那么虚、那么弱。」不仔细找还找不到，就代表此人的气虚掉了。\n\n      气一但虚掉，表就不固，不该流汗时却会流汗出来， 就是『喜盗汗也』，身体在很虚弱的状况之下才会有盗汗。所谓盗汗 的定义就是说，有时候醒到都会盗汗。你运动跑步后会流汗是正常的， 但是如果你坐着不动都会流汗，就是盗汗，有的人晚上睡觉时都会出一身汗。当然如果你作梦梦到有人追杀你，于是出一身冷汗，这没什么问题。\n\n      如果没事而早上起来的时候床上都是湿的，就是严重的盗汗， 这已经是代表气血两虚了，这个时候照样可以使用桂枝龙骨牡蛎汤， 不是只有用在失精家。中医的观念认为我们身体的津液、精、血这三样是同源的，所以可以用同样的治法来治，千万不要死脑筋说：「老师!失精家我记得如何治了，但是亡血家与失津者就不知道如何治 了。」其实都是一样的诊断，也是一样的治法。所以遇到盗汗很严重 的人，我们用桂枝龙骨牡蛎汤也一样可以将他治好。', NULL, NULL, NULL, NULL, NULL, '9、男子平人脉虚弱细微者 ，喜盗汗也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653032813432901, 'AD9EE5354843CB557D9F7BE2489325F9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-10 16:57:21', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8123, 447, 905008008, '        举凡精不固与精不足都属于失精家，这就是所谓虚劳的病人，\n\n       『少腹弦急』这个弦急是因为肾阳伤到造成的，少腹里面感觉到好像有一 条筋在拉扯，这是因为水不能生木，肝主筋，今肝木无水来滋润，故筋急，而肝的筋是直接络在少腹。一般我们如果有少腹痛时，多因脾 脏过寒导致，此时经方家都会重用白芍来止腹痛。现在这个情形用白芍是没有用的，因为病人是『筋急』，这是因为肝虚掉了。\n\n     『阴头寒』就是甚至于会感觉到阴部前头都是冷冰的，此际必兼有头昏眩，『髮落』就是连头髮都掉下来。『脉极虚芤迟』代表说里面阴精极度伤到了。下利『清毂，亡血失精』，就是东西吃下去，肠胃里太寒导致吸收功能不好，于是吃下去的东西尚未消化，就通通拉出来了，这就是下利清谷。病家本来血就不够了，现在再加上津液一直往外漏，如此不但元气无法恢复，加上病人的津液又不断的丧失，无 疑是雪上加霜。\n\n       病人处在这种状态时，我们开立处方时，第一个就要顾虑到脾脏，让脾胃能够正常的吸收营养。第二个要去固肾脏，固他的元精。\n\n     虚劳的症状就是『脉得诸芤动微紧，男子失精，女子梦交』女人、男人都会有这种现象，这就是『桂枝龙骨牡蛎汤主之。』桂枝龙骨牡蛎汤内 容是桂枝、芍药、生姜等量用，也就是很简单的桂枝汤加龙骨牡蛎， 但是在这里把生姜加重，龙骨牡蛎也要加重，一般我在处方时用到桂枝龙骨牡蛎汤的时候，基本的剂量上是桂枝三钱、白芍三钱、生姜三 片起跳。\n\n       如果遇到很严重的失精家时，龙骨牡蛎就不会只用三钱，开个五钱、一两的都不为过。给病人吃多一点，只好不坏。而龙骨与牡蛎，牡蛎能够补骨能够滋肾阴，龙骨能够固敛肾阳，如此阴精就不会遗漏了。牡蛎的用途很多，像是但头汗出时，牡蛎能够把头汗降下来。 浮阳在上面是因为下焦阴虚，牡蛎能滋阴，所以牡蛎可以将此浮阳降下。牡蛎味咸，故又可以攻坚。\n\n       当我们三焦、淋巴系统不通利的时候， 比如说在淋巴腺上有长肿瘤，我们就可以靠牡蛎来攻坚。牡蛎又可以生精，不要让阳精往外泄时，需要靠龙骨来收敛阳。但已经泄出去的精要靠牡蛎去把它补回来，龙骨只是固涩精不外流用的，桂枝汤用来健脾胃促进营养的吸收，对于失精家我们经方家最常用的处方就是桂枝龙骨牡蛎汤，这也是专门用来治虚劳的处方。\n\n       尤其此方用于年轻人效果很明显，有的年轻人偶尔遗精还没有关系，可是严重的时候必须用药来帮助他们，这时桂枝龙骨牡蛎汤一剂下去，时常是第二天气色 就变回来了，为什么会如此快，因为年轻人还是纯阳之体。如果遇到七十几岁的老先生，你一剂下去是不会立即就看到效果，时常是石沉大海，吃下去没什么感觉，所以要连续好几剂才行。我之所以强调年轻人一服下去，马上就看得到明显的改变，换句话说就代表这个处方是对的，西医对这种病是绝对没有办法，又不能拿个橡皮筋把阴茎扎 起来，得到这病是很痛苦的。年龄大的人可能要吃好几剂，你也可以加重剂量给他们吃，没有关系。\n\n       这里跟大家提出来，我们如果再深入了解一点，病人失精，临床 上看有三种症状，我在此比较一下让大家更明瞭。第一种症状比较浅， 是有梦乃遗，就是做了梦以后才会遗精出来，这个病况最浅，一剂知 二剂己，就是一剂就好了。第二种比较重，无梦而遗，睡觉中间没有作梦，就会遗精出来，这就比较深了。第三种最重，醒时亦遗，这是 最深最重了，剂量要随症轻重而做些加减，基本上桂枝龙骨牡蛎汤是非常好用的一个方剂。', NULL, '桂枝龙骨牡蛎汤', NULL, NULL, NULL, '8、夫失精家，少腹弦急 ，阴头寒 ， 目眩 ，髮落，脉极虚芤迟 ，为清谷 ，亡血失精。脉得诸芤动微紧 ，男子失精 ，女子梦交 ，$f{桂枝龙骨牡蛎汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653032813432902, '6DFA68EC4D89514DB0D96829417B1141', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-10 16:57:21', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8124, 447, 905008007, '       这里说如果是『脉浮弱』浮脉代表气脉，脉浮起来时表示气上浮， 就是意味病人的表虚掉了。涩脉代表血不足，也代表病人的精血不够， 代表里虚掉了，有这种现象的病人一定不会生子，因为『精气清冷』， 这种男人不容易生小孩，也就是说有劳症的人不容易怀孕，而我们中药里有处方可治，诸位看下面这个方子。\n\n       这个方子一剂知二剂已，有没有效，你们自己去试看看就晓得了。所以如果十七、八岁的小孩居然面色薄白，这就是他在刚开始发育的期间，生理的反应造成晚上睡觉时他会梦遗。如果只是偶而遗个一、两次是很正常的，没有多大关系，因为满则溢。但是如果很严重时，人就会虚掉，此时可见他脸上的气色整个是薄白的，精神萎靡不振，这就是桂枝龙骨牡蛎汤证了。', NULL, NULL, NULL, NULL, NULL, '7、男子脉浮弱而涩 ，为无子，精气清冷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653032813432903, 'DBAFE3482AE18F66F84F33D17C5EED74', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-10 16:57:21', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8125, 447, 905008006, '        『劳之为病』有劳症的病人，得到病的时候『脉浮大』，加上『手足烦』手足会同时有烦燥的现象。\n\n        『春夏剧，秋冬差』这种烦燥在春 夏时节症状会加重，而到了秋冬就好了，主因是因为有劳症的人，本身就有阴虚，一般阳会浮起来。当春夏时气候比较热，于是身体里面的虚热跟外面的太阳的热碰在一起，病人就觉得很难过，冬天的话会比较好，因为外面冷，寒会制热。\n\n         还有劳症很严重的人，就会有『阴 寒精自出』的现象。\n\n        张仲景是用很简单的方式告诉诸位，得到劳症的人，大部分都是上热下寒，就是肚脐以上是热的，以下是寒的，肚脐是阴阳的分界点。 下面是阴寒，阴寒就代表没有动能，不会蠕动了，新陈代谢不好。上面却太热，太过亢了。正常人是阴在上面，阳在下面，这样子阳才不会浮起来，我们的动能才能潜藏，就是所谓的潜阳，中医观念上是阳不在乎多，但是在乎要能潜。所以如果病人阳热在上面，无法下潜， 这个热就会跑到四肢上去，此时身体的下焦却是阴寒聚集之处，就会造成『精自出』，\n\n        这时病人会有几种情形出现，男人的话，代表会遗精、梦交等，就是晚上作梦梦里面在交合。还有年龄大的人很多都会有精自出的现象，因为阳虚而没有办法控制，精就会自动遗漏出来， 这种症状非常痛苦，用中药治疗很快就会治好的。\n\n         还有『痠削不能行』，为什么会这样，因为下焦虚寒精就会自泄出来。女人没有精，一旦发生在女子身上时，白带就会很多，一直滴漏出来，这也会造成人虚掉，这种现象发生时，会影响到晚上都不能睡觉。因为肾脏主骨，病人的肾精遗漏过多，骨头就会有酸感。这里所『痠削不能行』就是病人感觉到的是骨头酸而不是肌肉酸，所以有人长年得到劳症没有治好，到头来就会变成遗精。这精一直出来，病 人会受不了的，当然会很难过，每天精神萎靡，我们有中药可以去固他的阳虚，也有中药可以补足他的阴虚等等。', NULL, NULL, NULL, NULL, NULL, '6、劳之为病，其脉浮大 ，手足烦，春夏剧，秋冬差 ，阴寒精自出 ，痠削不能行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653032813432904, 'AD82C06AD4F3A8ECDA5CF11B513EA6EA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-10 16:57:21', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8126, 447, 905008005, '      这里提出劳症特有的几种症状，仲师将之分类出来。男子如有『脉虚沉弦』，虚脉就是你摸到脉的时候有一点点脉，稍微重按又没有了， 就叫做虚脉。或是脉很沉，要摸到骨边才有，重按又没有了。或是摸  到脉细细一根，其状如弦，这也是虚脉。\n\n        也就是说虚、沉、弦三种脉， 都代表里面气血两虚了。第一个情形是，病人并没有寒热现象。你问他：「会不会冷啊？会不会热？ 」他说：「没有。」\n\n        『短气里急』就是病人有时候走动一下就会呼吸很难过，然后肚子常常胀痛，\n\n        『小便不利』 小便次数多，量很少。\n\n        『面色白』苍白的气色。常常头会昏眩。\n\n          还有  『兼衄』就是时常会流鼻血。一般来说，像小便不利，这是肾脏功能出现问题了。\n\n         脸色白的话，代表脾脏功能有问题，因为我们脸上的气色是从脾胃功能来的。像流鼻血，是肝本身有问题。我们为什么要讨论这些症状呢？主要原因就是要告诉诸位，一般出现这种情况时，就表示此人的肝心脾肺肾五脏都虚掉了，可是你看他时又好像都很正  常，但却是五脏同时都虚掉了，这就是劳症，『此为劳使之然。』这是  肝心脾肺肾同时出现虚症时就会有这些症状。', NULL, NULL, NULL, NULL, NULL, '5、男子脉虚沉弦，无寒热，短气里急，小便不利，面色白， 时目瞑 ，兼衄 ，少腹满 ，此为劳使之然。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653032813432905, 'F239151A9D87F41458C7A5B3F268751F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-10 16:57:21', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8127, 447, 905008004, '      『男子面色薄主渴及亡血』，『卒』就是猝然之间，发生『喘悸』， 『脉浮者』就代表『里虚』，这是一种望诊。\n\n        所谓『男子面色薄』就是你看他的脸色很青冷。比如说，天气热时，我们应该脸红光满面， 而他看来白白的，面色苍薄。\n\n       和相书上的「郎君面」不一样。什么叫郎君面？就是脸看起来油光光的，没有皱纹。此人「没有涂油啊？怎 么脸油油？ 」，这就是郎君面，郎君面相的格局不好，不够脚踏实地。\n\n      此处的『面色薄。』跟郎君面是没有关系的，这个面色薄代表身体气血不足了。\n\n     『主渴』就是病人感觉到很口渴，这时不管此人是糖尿病引起的渴还是什么其他的病造成的渴，只要病人有渴的现象就代表津液不足，而虚的人为什么会渴呢？ 因为里阴虚掉了以后阳会更盛，有一些病人就是又虚又热，而实际上这个热是因为阴虚而来的虚热，不是实热。\n\n      实热的话我们就要用白虎汤或是承气汤来攻，主渴的虚热是不一样的，没有东西你怎么去攻？这个时候病人产生的虚热还是有很 高的温度，一样会把津液蒸发掉的，所以病人会口渴。遇到这种情形 时，我们补虚的药要开，去热的药也要开，如果只开了去实热的药， 结果大承气汤下去后，热是去掉了，但是虚会更盛，所以虚症是绝对 不可以用攻法。\n\n       如果病人是实热，就是实而且壮热，结果你开成去虚热的药，如 开了补药下去，于是实会更实，中医学就是要会看阴阳、表里、虚实、 寒热，也就只是这样辨症而已。\n\n       突然发生『喘悸』就是病人突发喘的时候，就表示是气不足。为什么会如此呢？ 当人体里虚掉的时候，肠胃功能一定不好，脾土就不能生金，肺里面的津液都是靠胰脏、脾脏来供应，脾脏吸收了营养再交给肺，当脾脏功能有问题时，病人就会卒喘，所以是气不足，才造成这样子。\n\n       悸，中医又叫做『血虚』，所以一个是气虚，一个是血虚。有动悸的症状就是心脏的力量不够，才会产生动悸，中医叫做血虚。\n\n     『脉浮』因为脉的外面就是气，你摸到是气脉，没有摸到血脉，阳就是气，血就是阴，血不够了，阳就浮上来，于是就会摸到脉很大很浮，实际上病人是血虚掉了。', NULL, NULL, NULL, NULL, NULL, '4、男子面色薄主渴及亡血 ，卒喘悸 ，脉浮者 ，里虚也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653032813432906, '918BED3EB3455B40E12BC1AE1E72E37F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-10 16:57:21', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8128, 447, 905008013, '       『虚劳里急』有虚劳症的病人都会有腹急痛的症状，\n\n        『衄』就是 流鼻血，吐血。悸，就是心动悸。\n\n        『腹中痛』，肚子痛。『梦失精，四肢痠疼，手足烦热，咽干口燥，小建中汤主之。』小建中汤本身专门是用在病人有表阳虚的时候。\n\n         伤寒论里面从头到尾就只有两个补虚的方子，里阴虚时，张仲景用炙甘草汤来补之，表阳虚时用小建中汤来补之。产生表阳虚是因为病人心脏的血量不足而造成的，由于肠胃吸收功能不好，没有办法将食物化生成血运送到心脏里面，这个时候就会出现心动悸的现象。当人阳虚的时候，里阳会浮上来，所以我们看 到好像有热在上面，实际上是里寒很盛，才逼着阳往外出。阳虚的时 候，阳会浮上来，没有办法继续停在中焦、下焦这边，当然血会逆经， 于是就会从鼻子流血出来。\n\n        『腹中痛』指肚子痛，这是肠胃里面消化不好。如果里阳虚，做梦就会失精、无法固守。表阳虚的时候太阳寒水也不能固阳，会造成肌理津液丧失。\n\n        『四肢痠疼，手足烦热，咽干口燥』，看到病人好像是热症，因为有咽干口燥，实际上是阳虚，而不是实热。所以我们遇到 不管是桂枝汤证或是麻黄汤证，可能是大青龙、小青龙汤证时，凡遇到有表阳虚时，就先要把肚子痛治好，也就是要先使用小建中汤。\n\n         如果遇到病人出现脉结代时，无论是什么病症，我们应该先把里阴补足， 这就是使用炙甘草汤的时机了。\n\n         炙甘草汤服下去以后，要等到病人的脉恢复正常后，再去看他还有什么其它症状再去治疗。\n\n          经方中医只有分阳虚跟阴虚，当看到虚症病人又有桂枝汤证时，我们知道光是开桂枝汤给病人是没有效的。\n\n          所以常常小孩子发烧开葛根汤给他们吃，结果两个孩子中，一个好了， 一个却没好，这不是你开错处方，而是这个小孩在得到感冒前，原本身体就已经虚掉了。此子必然平常就不太喜欢吃东西，因为肠胃消化不是很好，这个时候我们应该先用小建中汤将他的表阳虚补足。补足后，肠胃功能就会恢复正常，此时吃任何食物都会变得很好吃，体力加强以后，感冒自然而然就好了。\n\n          所以本来都是葛根汤证的，结果一个小孩子吃了葛根汤以后好了，另外一个就要给他小建中汤才可以治 好同样的感冒，这就是这条辨的重点所在。小建中汤也时常被用在治 疗肺病上，上次我跟诸位介绍，治肝，我们时常用苦温化湿法，像乌梅丸、吴茱萸汤等，最浅的治肝处方就是小建中汤了。\n\n          所以遇到肝病 的病人，我们给病人吃小建中汤就是怕肝木克到土，就是肝肿大压迫到脾脏，小建中汤能够健脾阳。所以说如果我们将小建中汤放在减肥药里面，结果效果正好相反，它不是减肥药，而是增胖药，因为它建脾阳功能非常强。所以从这里可以知道，我们开减肥药时绝对不会用 到小建中汤，这是常识，药性是相反的。综合上述可知小建中汤是经 方中医们专门用来治疗劳症里的『虚劳里急』特有症状时所使用的。', NULL, '小建中汤', NULL, NULL, NULL, '13、虚劳里急，悸衄腹中痛，梦失精，四肢痠疼，手足烦热，， 咽干口燥 ，$f{小建中汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653313994948677, '8FDA4D1B6EAFD3E0CEE7786A5E6A3828', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-11 12:01:29', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8129, 447, 905008012, '     『脉弦而大，弦则为减，大则为芤』，脉摸到弦脉，大部分都是有水饮的脉，就是身体里面有水气。大脉，就是脉形中间是空的，这是失血的脉，\n\n     『减则为寒』就是水饮脉出现表示是里寒。\n\n     『芤则为虚， 虚寒相抟，此名为革』如果遇到病人的脉是沉、弦、小、细，这种的 脉型中医称做『革脉』。\n\n       如果是妇人被摸到这种脉就会『半产漏下』， 就是很容易流产。如果是男人，就表示此人『亡血失精』，这种就是利用脉症来做辨症。\n\n       所以有的人说：「老师我没有病啊!你看我精神很 好，上课啊，什么都很好，可是我一怀孕就流产，外表看起来却还是很壮的。」这种成因就是虚寒相抟，这时候我们开补虚的药，还有去寒的药加在一起就可以了。\n\n      中医如何分辨病人是气虚还是血虚呢？简单说如果病人脉浮大，就是血虚，如果是脉微细，就是气虚。遇到气虚时我们要开补气的药，像黄耆、人参、党参这类就是补气的药。补血的药像当归、川芎等，这都是补血的药。去寒的药也要开在里面， 像干姜、附子这类去寒的药，这是我们用脉症来做区分。而一般亡血失精的人可以用天雄散来治疗，切忌使用寒凉滋阴之类的药物。\n\n       天雄散是治疗阳虚的，不是治阴虚。阳虚就是代表身体里面阴寒很盛，这时是看不到热症的，如果是阴虚的话，就可以看到热症，但是看到的是虚热。\n\n       如果病人是失精家，再遇到这种表里都寒的时候， 就是要用天雄散的时机。天雄的意思就是吃下去天天都雄壮威武，故名叫天雄，天雄药力比附子强很多，附子是三年收成，而它是五年才 收成。你到药房去买天雄，药房会告诉你天雄就是附子，一定会得到这个答案的。按照神农本草经，三年、四年、五年都不一样，第五年 采收才是天雄。天雄散就是用散剂，『天雄三两炮』如果散剂的话我们可以用这个比例，三两就三两没有关系，白术八两、桂枝六两、龙骨三两。经方里面写的是龙骨，但实际用的是牡蛎，牡蛎可能比龙骨还更恰当一点。如果你将龙骨牡蛎都放进去用，也没有关系，原文上有一点失去方义，其实是可以用牡蛎的。将这四味药杵为散，用酒服， 半个汤匙，『半钱匕』就是我们平常喝汤的汤匙平匙量。一天吃三次， 饭前空腹吃。\n\n       吃完了以后，如果没感觉到改变，就是还有亡血失精， 这个时候就要增加剂量。这个药在经方里面，是属于很强的补阳药， 主治症状还包含阳不举，如果服了天雄散后仍然不举，表示天雄散没有用了，此时我们就需要用到像阳起石，肉蓰蓉等，还可以再加一些鹿茸，这几味都是我们中药里面一般的壮阳的药。但是如果你光吃这种药，结果就是全身汗毛都举起来了，就是那个地方不举，所以要靠一些药把它带到它该去的地方。\n\n        你如果将这壮阳复方放在天雄散里面一起吃，效果就非常的好，还可以放到桂枝龙骨牡蛎汤里面也可以。 这类药千万不要单味的用，要用复方，它才会进入到我们肾脏去。这几个药都是等量的比例在用的，也可以把鹿茸拿去泡酒，然后一边喝鹿茸酒，一边服天雄散也可以，这些都是中药里面比较强的壮阳药， 一般是阳虚时才会用到。如果阳没有虚而是阴虚，吃这类壮阳药，就会越吃越热，反而没有用。\n\n        阴虚的话，病人一定会看到阳亢的症状， 所谓阳亢就是上焦热下面是寒的，也是属于失精家。阳虚和阴虚治法不一样，阳虚是看不到阳症，只看到阴症，比如你问病人说会不会口 渴？病人回答说不渴时，就是阳虚了。如果是阴虚，就会很渴，因为上面的阳热是虚热，所以只要问病人口渴不渴大概就晓得了。阳虚的人脸色一定晃白，因为阴寒很盛，舌苔也是白的。\n\n        阴虚的人阳会亢在上面，会看到黄色舌苔。或者是脸色红润一点，或是眼睛红肿，可以看到血丝都蹦出来。天雄散，大家可以在旁边写上『里阳虚』。后面是当看到表阳虚时，我们就用小建中汤。这里是里阳虚，因此天雄散里面的药通通是走里的药，还有一个药叫做锁阳，也是属于壮阳的药。\n\n如果每天练易筋经之类的气功，是不需要这些壮阳的药，保证你 很壮。', NULL, NULL, NULL, NULL, NULL, '12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚， 虚寒相抟 ，此名为革 ，妇人则半产漏下 ，男子则亡血失精。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653313994948678, '484C896D357547B7F8EC092BBBB7EA00', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-11 12:01:29', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8130, 447, 905008011, '       如果一个病人的脉出现沉、小、迟，来的很慢，一息才一至、两至，中医叫做『脱』，就是元气虚脱，是很危险的症状，病人稍微走 快一点就会喘，这是虚劳至极的现象。\n\n       手脚冰冷，『腹满，甚则溏泄， 食不消化也』这种症状也都表示病人是在极度虚弱的状态之下。大家 看到后就可以知道此处的手脚冰冷、腹满、溏泄等，就是四逆汤证， 是很危险的。', NULL, NULL, NULL, NULL, NULL, '11、脉沉小迟，名脱气，其人疾行则喘喝，手足逆寒，腹满， 甚则溏泄 ，食不消化也。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653313994948679, 'D5C6BAE1DC1DEEB67A5782024F913AC5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-11 12:01:29', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8131, 447, 905008010, '        五、六十岁以后的人，如果被摸到脉是大的，也代表是劳症，这 种中年以后得到劳症的人会有哪些症状出现呢？就是『痹侠背行』。 因为督脉是诸阳之会，中年以后本身气血开始衰了，结果又有劳症在身上，会让整个脊椎骨，就是整个督脉，一直麻木下来，跟西医讲的 「脊髓神经麻痺 」很类似。\n\n        而中医是说病人的整个脊髓都麻掉，由于 督脉是诸阳之会，当阳虚时，就会产生这种症状，所以劳症我们要赶 快治好，不要等到五、六十岁以后再治疗就更麻烦，有时劳病人还会跟有『肠鸣』的症状。\n\n        什么叫『马刀侠瘿者』？ 马刀是弯型的，像个蚌壳一样弯的，而这个外面像马刀形状的坚节，在腋下淋巴节聚集的地方，可以摸到一块块的肿疖，侠瘿就是甲状腺腺体都肿起来了。中医说：「劳症要不早治好的话，等到五、六十岁就会有这种现象。」所以这种病起因就是因为劳症没有治好后而得到的。\n\n        因为劳症的人大部分都是虚热症，虚热在上方一直蒸热，直到津液干掉，当我们人体的正常水份被消耗掉以后，就会造成许多坚块慢慢的累积在三焦系统里，而腋下部位是胸阳刚出来的地方，下巴就是指甲状腺，如果阻塞到就会成为硬块，中医就叫做『瘰历』，如果已经破掉了，流脓出来的话，中医有另外一个名称，叫做『鼠瘻 』。\n\n       为什么叫鼠瘻？ 因为它整个像老鼠一样，很大，绷起来了，已经不规则，然后破个洞，一直流脓出来。这种症状归其原因，中医认为是因为长期有劳症未被治好而得到的。所以很多这种病过去没有被认定是疾病，因为西医学根本没有劳症之说，凡有劳症的人去检查身体，千篇一律都是「很好啊， 你没有病。」「可是我每天都很累啊？ 」「你没有病啊？ 」这种对话是 很常见的。实际上此时中医就已经认为有症状了，摸他的脉就可以知道，还有看一些外症也可以知道。\n\n       『外证见马刀侠瘿，则脉见弦大，时医以为小柴胡证，其实不然。 马刀之状，若长形小蚌，生于腋下，坚硬如石。』『成脓溃烂』，这个 中医就叫做鼠瘻。『侠瘿生于颈项，连连如贯珠。』『初起用旱烟?中烟 油涂之』过去是用旱烟?里面的烟油涂之，三天就好了。\n\n        内服的药，多施以小柴胡汤，如果遇到坚块很大时，就没有什么用了。但是我们可以用小柴胡汤来做一个加减，后面会跟诸位介绍， 有很多特殊攻坚的药，可以加进去，尤其像是牡蛎就非常好用，凡是 堵在淋巴系统内的肿瘤都可以用它来攻坚。', NULL, NULL, NULL, NULL, NULL, '10、人年五六十，其病脉大者，痹侠背行。若肠鸣马刀侠瘿者 ， 皆为劳得之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653313994948680, 'F413B3D78ADA5C8E995E76D3D1716080', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-11 12:01:29', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8132, 447, 905008019, NULL, NULL, '灸甘草汤,獭肝散', NULL, NULL, NULL, '19、方剂补充《千金翼》$f{灸甘草汤}  治虚劳不足汗出而闷，脉结悸，行动如常， 不出百日，危急者十一日死。\n\n    《肘后》$f{獭肝散}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653678017425477, 'DFD87845E45BC6E473211215435E8346', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:42:42', 1, 'admin', '2025-03-12 12:42:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8133, 447, 905008018, '       虚劳里还有一种症状， 比较麻烦严重的就是『五劳极虚羸瘦，腹满不能饮食，食伤忧伤饮伤房室伤飢伤劳伤』，这段可以知道做运动要慢慢做，不要做成劳动，成为劳伤。\n\n     『经络荣卫气伤，内有干血』， 造成『肌肤甲错』。『肌肤甲错，两目黯黑，缓中补虚，大黄蟅虫丸主 之』。大家可以将『肌肤甲错』写成第一，将『两目黯黑』写成第二， 有这两个主要症状，就代表说体内有干血。张仲景说的『内有干血』 内指的是在肝里，只要体内有干血，不管是在哪个位置上，病家都会两眼圈黑黑的，还有『肌肤甲错』，就是皮肤上面出现脱皮，掉下白 色粉末状的皮屑，一拍就好像干面包屑一样掉下来。有时候出现在妇人小腿上面，也有的人生在背后面，皮肤会像蛇皮一样脱落下来。只要冬天一到，就开始脱皮，春天夏天就此较好，这就是所谓的『肌肤甲错』。\n\n       张仲景写『内有干血』这是非常高明的解释词句、因为临床上看的时候，体外症状都一样，在身体结构学上， 比如说胃、脾脏、 肾脏、肝脏、赡、小肠、膀胱，所有的脏，它的下方都是静脉血管聚集最多的地方，上面就是动脉。而病人的内有干血，有时候堵在这边， 有时候堵在那边都不一样，还有一种状况是内脏都没堵，全部的瘀血都是积在下腹腔内，我讲的是曲骨位，下焦腹膜的地方，有时囤积许多瘀血在此，而这是在脏腑之外网膜之内，血瘀在这里以后，慢慢的就会累积起来，这些瘀血是来自内伤，像五劳七伤之类。\n\n       仲师前面写 的『食伤忧伤』，如忧伤，饮伤，房室伤，肌伤，劳伤等都是伤，有时候是被打伤造成的瘀血，而这些体内的瘀伤，我们在身体外面可以看到一些症状。比如说，人虚掉的时候反而会流鼻血，血会因阳虚而逆经走，外症就是流鼻血，流鼻血就是表面上可以看到的症状。但如果是在身体里面血离经的时候，就没法看到身体里面是哪里出血，可是身体里面有出血，并不是像大动脉血管出血那么危险，只是一些脏腑下面的血自静脉中渗出来。\n\n        渗出来的血到血管外面以后，会到三焦网膜，或者停在腹膜的下方，或者在脏的下方，此时张仲景就判断是内有干血，他没办法讲出是在何处出血，因为每个人都不一样，但是无论干血停在哪里，你只要看到体外的这些症状，如眼睛周围黑黑的， 或是皮肤干燥，一到冬天就开始脱皮等等，都表示内有干血了，此时就要吃些『缓中补虚』的药物了。\n\n       这个大黄蟅虫丸有攻、有补，是攻补俱兼的药物，大家看看处方内容，大黄、黄芩、甘草、桃仁、杏仁、芍药，干地黄是补血的，芍药敛血，所以病人有肚子痛，或者是需要破血时，我们一定会用到芍药，病人如果有劳伤在，身体里面就会有瘀血，此时一定会有内热的现象出现，治疗内热我们需要加一点去热的药在里面，比如说阴虚内热，当你遇到病人正好是六味地黄丸证，而此丸剂是补阴用的，此时增加补阴的药就不会有反作用。\n\n       但是如果要用到桂附八味丸，病人同时又有热症出现时，你就要在桂附八味丸里面加一点黄芩、黄连，就是去热的药跟补虚的药同时使用如此就不会热了，大黄在此的作用是通瘀，后面的药像蟅虫、水蛭、蛴螬、虻虫，这些都是攻瘀破血的药。 \n\n       过去中医称这种病，叫做『干血劳』，主因是身体里有干的瘀血， 日久而成劳症。这个药是丸药，采用丸药的缓性，让药物慢慢进入人体 内，把已经成为血块的瘀血慢慢让它化掉，化成血水以后，就可以渗透进肠壁管里，或者是进入膀胱。由小便或是大便排出来。\n\n       此方里用 的干漆是毒药，干漆是漆树的树皮『 一两烧令尽』，干漆拿起来是黏答答的，如果用手这样摸它，再张开时手指就黏住了，干漆必须要烧过才能用，烧的时候要使用瓦片或是铁板之类放在火上来烧的。将干漆放在上面一烤，就会有青烟冒起来，此时千万不要去闻它，很毒的。 \n\n       虻虫、水蛭在伤寒论时都说过了。\n\n      跻螬，过去我们用的跻螬，有人认为就是『地鳖虫』，也有人认为是刚生出来的蝉，身体还在壳里面， 还没有蜕掉外壳的蝉，蜕掉后外壳就是蝉蜕，蝉蜕是我们拿来治疟疾与皮肤病用的。如果它在壳里面就还会蠕动，这时就有人把它当成蛴螬来用。\n\n        还有人找它的方式是将我们以前灶里面的大锅子，翻转过来底下一票黑黑的虫，长的像蟑螂一样跑得很快，这就是蛴螬，又名叫地鳖虫，而谈到蟅虫时，也是这个说法。所以地鳌虫也有人说就是蟅虫。过去蛴螬跟蟅虫两种药，在本草里面扯不清楚，但是都是会咬血的虫。\n\n        在这里大家看看就好，因为这是汉朝留下来的药方，我们有时 候到这个药房去买蟅虫时，药房说就是地鳖虫，有时候我们要买蛴螬， 药房就会说没有统一使用的蛴螬。实际上临床用的时候我们不需要用这些药，因为张仲景不懂针灸，他不了解针灸的效果有多好。现代我们需要使用虫剂时，不要说蟅虫跟蛴螬不容易弄到，光是虻虫、水蛭， 你想弄到真正的虻虫、水蛭都很难了。\n\n       此时遇到有干血的时候怎么处理呢？大家记住，当病人身体里面有干血时、在膈俞上面会有压痛点， 因为隔俞是血的会穴，所以第七椎有压痛点出现时，我们就知道此人体内有干血劳，这是第一个症侯。第二个，如果病人是男子，你问他： 「你过去做什么的？ 」「我是练功夫的。」就可能有内伤在体内。再问 他：「你呼吸时会不会有痛，出现在固定的一个部位？ 」因为有干血的地方一定有痛，表示里面有瘀血。\n\n       得到干血劳的多半是女子，而且大部分的女子都是在左腹下方这一带痛，因为人的左边是血，右边是气。\n\n       如果是在肚子左侧，我们可以用灸治，因为脾主腹，可以在脾的募穴『章门』灸，然后在小肠的募穴『关元穴』再灸，近取穴部份完全用灸治，不需要扎针，热灸产生的热一下去，干血就化掉了，任何东西碰到热就化掉。脚下我们可以下针，有干血的人，三阴交一定会有压痛点，而血海可以消导瘀血止痛经。背上第七椎不要扎针，也是用灸的，灸他的膈俞，让血液循环加速，这是我们针灸并治干血劳的方法。\n\n        如果是胸腔有内伤，不要扎三阴交跟血海，需要用公孙与内关， 来打通病人的冲脉跟阴维脉。公孙与内关可以行气来治内伤的部分， 然后使用小柴胡汤加桃仁、红花。这是治疗胸腔有瘀血的活血化瘀法。 \n\n       下焦部位的瘀血，就是指肚脐以下，如果是妇人科，就不需要用这些药，可以选用大剂的白芍，如白芍一两、炙甘草一两，这样用药可以强到连双腿的静脉曲张都可以把它收敛起来，然后再加一些和解的药 进去，像川芎等，这是我们经方家时常在使用的治疗干血劳的方法。 \n\n       因为这大黄蟅虫丸的处方，我们历代经方家一直到现在，代代都认为它不合用，因为找不齐药。以前在大陆上也不容易找到这些药，再加上还有一些名称上的错误，产生的原因我想是因为方言造成的，中国人的方言繁多是举世皆知的。\n\n      使用白芍、川芎就可以活血化瘀，但是一定会加当归，加当归的目的是把不足的血再补足，然后靠白芍来破血，绝对不能开很大剂的破血药，否则会造成瘀血被攻出来，但是却停留在组织外面而没有排出来，于是内脏被药物伤到，所以此处用白芍，再用当归、川芎，然后加些炙甘草下去，让瘀血慢慢的被和解出来。其他破血的部分我们可以用针灸来行气活血，这是临床上用的最简单的方剂。\n\n       当然这个要用大剂的才有用，比方说川芎是一两，当归就是一两，可以大剂的用。如果你问说：「老师，可以加桃仁吗？ 」 当然可以加桃仁，桃仁跟红花不一样，红花破血的力量很强，桃仁比较着重走三焦，但是桃仁的油脂很多，所以女子吃多了就会长青春痘， 这是它唯一的缺点。红花比较着重在血分里面走，破瘀血的力量很强， 所以红花不能吃多，重用红花时可以堕胎。我们如果遇到妇女胎死腹中，我们才会大剂的使用红花，也就是一两、二两的开。如果你开大剂破血的药，却不同时开些补血的药，病人一吃身体就会虚掉，因为它会把好的血也同时破坏掉。\n\n        中医使用很多虫类来做为药物，像虻虫、水蛭、蛴螬、蟅虫这些 虫的天性就是会咬破血，可以用做攻瘀血的药。瘀血干掉时我们靠白芍、干漆、桃仁，来把它破出来的。咬破血块的部分就是要靠虫的药， 当然像这个虻虫、水蛭、蛴螬、蟅虫是不会受到野生动物保护法的保护，使用它们没有什么关系，只是非常不容易取得真正的药材。大家看看这里有二个也是很好用的处方。\n\n', NULL, '大黄蟅虫丸', NULL, NULL, NULL, '18、五劳极虚羸瘦，腹满不能饮食，食伤忧伤饮伤房室伤飢伤劳伤 ，经络荣卫气伤 ， 内有干血 ，肌肤甲错 ，两目黯黑， 缓中补虚 ，$f{大黄蟅虫丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653678017425478, 'A97830632937CF0E4476D098D0A537DD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:42:42', 1, 'admin', '2025-03-12 12:42:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8134, 447, 905008017, '       酸枣仁汤多是用在一般老年人身上，睡觉只能睡两三个小时后就 醒过来，然后再也睡不着，这就是虚劳不能眠的症状，此时就可以用酸枣仁汤。\n\n       酸枣仁汤中有甘草、知母、茯苓、川芎等药在内，川芎这个药，本身是活血药，可以入血分，酸枣仁最主要的作用是养肝，酸味的药入肝，能够在肝里面养血。肝血足的时候，我们身体血的存量就会增加，于是就没有人会睡不着了，虚劳不足的人常常晚上担忧受怕，因此肝血就会受到耗损，当肝血不足时，它能把肝血补足。由于血还要同时供应给全身用，这就要靠川芎，有了川芎，血就会入脑再回归到肝里面，还有像妇人的经血跟肝脏也有十足的关系。所以在妇科治症里，常常都会加些川芎在处方里，像四物汤里面也都会有川芎。 \n\n       为什么要用甘草、知母呢？ 因为虚烦的人，一定会有热在上焦，因此 白虎汤里用到知母，就是专门作为除烦去热用的。如果只是热、渴、 不烦，就是石膏症。\n\n       如果是烦，就是知母，知母本来就是清胃热除烦用的。到底怎么才叫做烦呢？就是你看了此人觉得很讨厌，你想帮他又帮助不了他，实在不知怎么应付他，跟他讲什么都没用时，这就是烦躁。\n\n        酸枣仁汤中会使用甘草，是因为有虚热的人，肠胃消化就不会很好，必然会有很多食物的残渣停在胃里面，此时就要甘草来化解宿食产生的毒素。酸枣仁完全入肝脏，对于老年人虚劳不得卧的症状，帮助最大。\n\n      还有就是生产后有时也会有虚劳症状，还有就是开完刀以后也会有，大都是因为失血过多，于是造成的失眠。像身体比较强壮的，心胸又开朗，两眉间分的很开，或是眉毛很高的人，这种人开完刀照样睡。因为他天生就是不会忧烦的人。而两眉毛靠得很近的，或五官都挤在一起的人，不开刀时就已经睡不着了，开完刀后更睡不着，因为心事太多造成的。所以人在越虚的状况之下就越是睡不着，此刻大家就要想到用『酸枣仁汤』，喝下去会很好睡的。这酸枣仁汤也是『病后调摄之方治也』，所以大病以后睡不着的人，大部分都是酸枣仁汤证。', NULL, '酸枣仁汤', NULL, NULL, NULL, '17、虚劳虚烦不得眠 ，$f{酸枣仁汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653678017425479, '1A64BF48D1D2CAC5742F9318566F0A0A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:42:42', 1, 'admin', '2025-03-12 12:42:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8135, 447, 905008016, '      薯蓣就是淮山，也就是山药，薯蓣丸现在很少人制作，有几个药方如射干麻黄汤、乌梅丸、薯蓣丸都是属于方剂内容很多的药，张仲景很少开那么多的药在同一方中使用。\n\n     此处为什么开那么多药在一个方子之内呢？就是他认为平时就容易生病的人，本就是虚劳不足，所以没事就常常感冒发烧，当这次感冒好了，不多时又感冒了。遇到这种情形的病家就适合用薯蓣丸。薯蓣丸制造过程非常的麻烦，像里面的药如薯蓣、人参、白术、茯苓、甘草、当归、干地黄、芍药、川芎、 麦门冬、干姜、阿胶、大枣、桔梗、杏仁、桂枝如此多的放在一方内， 再加上神麯、豆黄卷、柴胡、白蔹都是同属于发散少阳三焦油网用的， 其他的药诸位都知道了，它是桂枝汤、各种建中汤、理中汤通通把它混在一起，是一个复方。\n\n      实际上我们不需要去做这个药，因为平常就在吃六味地黄丸，体内虚劳补足以后就可以了，病家有桂枝汤证出现时，我们就用桂枝汤来发表。出现柴胡汤证时、就用柴胡汤来和解。 时常用一些解表药，一段时间以后，病人就不会有虚劳里不足的症状 了。所以现在用的不多，这个药方，大家可以放在旁边做参考，现在几乎没有用这个药，我甚至怀疑此方不是出自张仲景原方，而是有人假借他的名声，把此方放置在这里目的是想更能说服人使用它，当然 现在已不可考了。', NULL, '薯蓣丸', NULL, NULL, NULL, '16、虚劳诸不足 ，风起百疾 ，$f{薯蓣丸}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653678017425480, '62861406811DFC4962DF11F14D987BCC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:42:42', 1, 'admin', '2025-03-12 12:42:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8136, 447, 905008015, '         『八味肾气丸』又名『金匮肾气丸』，又名『桂附八味丸』。主治所有的虚劳不足，此处讲的都是指肾阳不足和肾水不足。\n\n          如果是肾水不足，我们就用六味地黄丸。水就是阴，水是津液，我们的内脏本身都有一定的津液在里面，如果肾太干燥了，我们就用六味地黄丸。「老师你怎么知道肾水干燥？ 」你可以看病人的头髮，头髮干干的，或是有耳鸣等都代表肾气不能固守，就是肾水不足，这时候就要用六味地黄丸。但是六味地黄丸要记得它的剂量。\n\n        八味肾气丸，仲师原来并没有写方子在这里，而是写在妇人杂病篇里面，我在这里先跟大家解释 一次，后面就可以加快速度了。\n\n       金匮肾气丸也就是肾气丸，大家看地黄的剂量是八，山药、山茱萸四，泽泻、丹皮、茯苓三，桂枝、炮附是一。诸位把下面的桂枝跟炮附子先去掉，上面的六味就叫做六味地黄丸。\n六味地黄丸里面要重用地黄，所以它才被称为地黄丸，跟山药、 山茱萸还有泽泻、丹皮、茯苓，这些药是三补三泻的合用处方。所谓三个补，就是地黄、山茱萸、山药，山药就是淮山，也叫『薯蓣』， 下段我会介绍薯蓣丸，讲的就是淮山，这是三个补药。三泻是指泽泻、 丹皮还有茯苓。这六味药配合得非常好，但是剂量要弄清楚，一般药房制作时都是等量在用，这是外行话，稍微研究一下也知道不是用等量。张仲景用补药时的剂量都会比较重些，而此处用的最重是地黄， 因为它能补肾阴。\n\n        尤其是地黄生用的时候会直接入血分，补阴的力量非常强，而当归是补脾胃的血，还有妇科血虚时用的，跟地黄的药性不一样，地黄是补肾脏这一带的阴血。山茱萸这个药是补肝脏的，滋养肝的阴虚。淮山就是山药，主要是要增润脾脏津液用的，这几个药用在一起是希望同时能够把脾肾肝的阴津壮起来，能够嘉惠到肾脏。 就好像麦门冬，麦门冬可以润肺，如果肠胃里面太燥了，我们可以再加一点甘草、生姜、红枣下去把肠胃润起来。\n\n        中药里面有很多药都可以配合使用，这三个药合用的目的就是要滋润肾脏的阴。同时也要注意三泻，因为中医的观念里面认为说『补能恋邪』，如果光吃补药， 没有加入清除的药，于补到的同时也会固守肾脏里面的浊物排不出 去，肾脏里面本来就有很多浊物，日久会变成肾结石之类的实积，堆在里面无法排出去，因为考虑到这个，所以仲师加了泽泻、丹皮、茯 苓进去。泽泻本身能利肾疏肝，能够把这二个脏洗得很干净。\n\n       丹皮的作用是活血化瘀，所以大家吃了六味地黄丸后感觉到大便变得很通 畅，原因就是有丹皮在里面，像金匮的肠痈篇会介绍到『大黄牡丹皮汤』重用到丹皮，大家学过以后从此遇到急性盲肠炎就不用上西医院开刀了，如果大家以为急性盲肠炎开刀就会好，你就错了，实际上开完刀还是有问题在里面的，等到我讲到肠痈篇时会再跟大家做详细的解释，听完后从此你就不会再去开刀了，丹皮活血化瘀的力量很强。\n\n         茯苓可以利湿，把浊湿从小便消导出来，这就是茯苓之功。伏苓能够利中焦，泽泻能够走下焦、走肾脏、走肝脏。这六味药搭配在一起， 补泻兼具是很完美的组合，所以使用上就百无禁忌了，因为里面没有加入热性的药。有一种状况下需要用到桂附，当肾阳不足时我们要把肾阳补起来，就一定要用到阳药，炮附子本身可以温补肾阳，将肾阳壮起来。\n\n      为什么要用桂枝呢？这是因为加强肾脏功能的同时，必须要强化心脏，如此才能够将肾阳补回。心脏、肾脏之间本身有大动脉连系着，要让心脏血往下走肾水往上走，也就是要将心阳往下降，肾阴 往上升，心肾相通的这个部分就要靠桂枝了。\n\n       后面妇科篇里面有许多地方我们也会用到桂枝，太阳病处方中用到桂枝的地方也最多，像桂枝汤，很多医师开完桂枝汤给病人后，病情恢复就好了，没有深入去 想过它。经过我看过各家的注解以后，我发现到，张仲景非常优秀， 他高明在他已经了解到桂枝实际上可以壮心阳，就是让心脏强起来， 可是桂枝的壮心跟附子的壮心是不一样的。附子的壮心是能够让心脏 搏动的很快，于是使得心脏产生的热力能够透达到四肢末梢去。桂枝的壮心不是这样，桂枝也可以壮心能够让心脏跳起来，但是却是让心 脏产生的胸阳往下走。\n\n       桂枝味厚入血分，气辛香主发散，为阳药，也因为如此所以妇科里我们常常用到桂枝，就是因为它能够让上焦的血化生成乳液变成乳汁后，靠着桂枝的作用，将之导入冲脉，进入下焦后变成月经排出来。所以我们退奶的药里面一定会加桂枝进去。所以所谓的桂枝可以将胸阳往下导，就是将乳汁往下导，这乳汁经过小肠的火一烤，马上就变成月经了，介绍妇科时我还会再强调一下。\n\n       我们身上的津液来源在内经中说是来自心脏，实际上津液的来源是肠胃，但是肠胃的津液能够通达到四肢皮肤表面上，就是靠心脏帮助的力量。所以说桂枝服下去以后，心脏功能会被加强起来，于是津液马上就跑到四肢上去，否则身体要如何才能把肠胃的津液送达到皮 肤表面上去呢？肠胃本身并没有办法走表，必须要加强心脏的功能才行做到，因此必须要有桂枝。只要桂枝一服下去，津液马上就会发散到四肢、发散到身上，病人就开始流汗。\n\n        桂枝要同时配合芍药等量的使用，主要原因是如果病家汗水发出去太多，结果却不能回头，就会产生其他问题。张仲景很聪明，坏的排出去后，好的还要再回来，就好像派部队出去作战，部队打完了仗后，部队还是要回来的。这部队回来就要靠白芍把它通通收敛回来，所以白芍性酸主收敛，在本草经里面主要功能就是收敛，收敛就是收藏的意思。\n\n       一般我们补虚用六味地黄丸就好了，如果病人有虚热或者是实热，此时如果用桂附八味丸，病人就会更热，吃完后，嘴脣会干裂， 口中燥渴，又便秘等这些症状出现。就表示里热过剩。所以如果遇到纯阳虚的病人，此时你看到的都是阴寒的症状，这时你开桂附八味丸给病人；效果就会非常好。\n\n       但是如果是有虚热，像本来病家就有口燥咽干的现象，这是表阳虚，不是里阳虚，这个时候你开桂附一下去， 吃了喉咙就会痛，所以使用桂附时必须要先看清楚哪些人才可以用， 像是因肾阳不足而腰酸背痛的人、年龄大的人、虚寒的人桂附就非常的好用，张仲景使用桂附第一个地方是用在虚劳症里面诸不足的时候 用的。还有一个地方也在用，像下消糖尿病，当男子不能挺举时，张仲景处方也是以桂附八味丸为主来做加减。所以在金匮里有几个地方 我们可以看到仲师在使用桂附八味丸，此药的名称很多，但是药的内容都是一样的，这是治疗虚劳里急的药方中一个常用处方。\n', NULL, '八味肾气丸', NULL, NULL, NULL, '15、虚劳腰痛 ，少腹拘急 ，小便不利者 ，$f{八味肾气丸}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653678017425481, '581DB612CF313036F2FBCC51B260638D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:42:42', 1, 'admin', '2025-03-12 12:42:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8137, 447, 905008014, '        这黄耆建中汤就是小建中汤里加黄耆。我们有『黄耆建中汤』还有『当归建中汤』，为什么要加黄耆？ 因为黄耆入气分，属于气药。\n\n        黄耆跟当归，这两个是一个补气一个补血。很多人都误解以为人参是 主气，实际上人参是补足肠胃津液用的。我一直跟大家说心下痞症就是指肠胃炎，张仲景在所有治疗肠胃科的药里面都放人参进去，就是 担心病人发汗过多，使得肠胃津液丧失时，这时就要在桂枝汤中加点人参进去，来把津液补足。\n\n        而实际上我们遇到病家气不足时，就要靠黄耆来补足气。黄耆建中汤证本身除了病家必有的小建中汤证以外， 还要加上气虚的症状。小建中汤症最明显的症候是肚子痛，因为肠胃虚寒掉。\n\n        仲师说：『虚劳里急，诸不足』，就是全身都出现不足的症状时，同时有那么多的虚症，要怎么加药进去呢？仲师之意是只要加黄耆一味药就好了。而当归建中汤是用在同样有里急、有腹痛、同样有阳虚，可是在阳虚的同时这个病人的血也虚掉了。\n\n        当归建中汤与黄耆建中汤还有另外一个主要的辨症，就是用两手同时摸病家的脉，由于人体$m{左边主血}，$n{右边主气}，当左手的脉变细小无力时，就是当归建中汤证。如果是右手的脉很弱时，就要用黄耆建中汤，如果两手的脉同时都弱了，就不必如此细分，直接开小建中汤给病人就可以了。\n\n       诸位看『黄耆建中汤是小建中汤内加黄耆』，就是要重用黄耆，大家开小建中汤的时候千万不要忘掉白芍量是桂枝的两倍。\n\n     『若气短胸满者加生姜』，气短胸满的原因是因为我们的小建中汤喝下去了以后，如果遇到病人中焦原来就有积水在，妨碍到气机流行， 建中汤的目的是要将中气建立起来，可是肠胃里还有积水未退，此时就要加重生姜，因为生姜有散去肠胃积水的功能。后面还有枳实桂枝生姜汤证等，治疗胸痞时都会用到生姜。\n\n     『腹满者去枣加茯苓一两半』， 腹满是因为有湿聚在肚子里面，小建中汤是治里寒就是肠胃虚掉的时候用的。当人的肠胃虚掉后，湿就一定会停积下来，如果湿没有去掉， 日久就变成留饮，就是水越来越多了。留饮再没有去掉的话，就变成溢，就是水满出来了。张仲景说有湿的时候还可以用小建中汤，如果变成留饮，小建中汤就没有用了，需要加一点茯苓进去，茯苓可以把 这个湿排出来。如果变成溢饮的话，张仲景就会用十枣汤，因为水太 多而且已经进入肺了，此时唯有十枣汤才可以把积水排出来。\n\n     『疗肺虚损不足，补气加半夏三两』半夏在这里有一点要注意，后面会再跟大家再重新强调，张仲景用$m{半夏的原则}是，只要$n{有渴就把半夏拿掉}。 病人没有渴症时，就会用到半夏。\n\n       我们在治疗湿症时，光是开燥剂去湿是不够的，因为里面仍有许多浊痰未去，所以说我们都会加半夏入内，因为半夏可以把浊痰同时清掉，这时候半夏不需要加很多。因为病人已经有渴症了。如果这个时候你没有加半夏把这个浊痰去掉，就会造成湿去浊痰没去。也就是本来停在湿里面的脏痰没有排掉，只有湿被排掉，以后日子久了，病人就会开始慢慢咳嗽，胸腔里面就会出现痰饮咳嗽，痰的产生其实是之前没有被排掉，遗留下来的问题，所以痰看起来并不是很干净的痰。\n', NULL, '黄耆建中汤', NULL, NULL, NULL, '14、虚劳里急 ，诸不足 ，$f{黄耆建中汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653678017425482, '1DA7FB04ECC8BB6EA55F82E01730A51B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:42:42', 1, 'admin', '2025-03-12 12:42:41');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8138, 448, 905009007, '       射干麻黄汤是小青龙的变方，跟小青龙很类似。小青龙汤专门治 疗气喘『寒喘』用，射干麻黄汤专门治疗『寒饮』用。\n\n       肺里面寒，如果是虚寒，就用甘草干姜汤。\n\n      如果是寒中带点『水饮』就是射干麻黄汤证。\n\n      什么叫做饮呢？饮就是已经有积水了，也就是我们所说的实症， 如果只是饮，就是还没有溢出来的水气，跟『溢饮』不同，只是『水饮』，表示病人肺里水气很多，就好像一个碗里面有很多水气但是眼睛看不到。\n\n      如果肺里面已经有积水，这时射干麻黄汤就没用了，因为用此药的时机已过。只是水饮的阶段，尚未成溢饮，这个时候我们肺的气泡旁边充满了很多水，不是肺膜里面有水，也不是肺里面有积水， 遇到这种情形就是射干麻黄汤证。\n\n       此时病人主要症状是呼吸时，可以听到喉咙里面有水的声音，咕噜咕噜样的水声，张仲景形容说喉中像水鸡声般，表示这类水饮尚未成为溢饮。\n\n       怎么知道有溢饮呢？有溢饮时眼袋都会肿起来，脸会有浮肿，这就是溢饮了，此时整个胸腔里面都是水，溢饮不单单是水在肺里，甚至胸膜肋膜里面都会有积水，一 般西医只能直接在肋膜上抽水，但是抽完后水又会再来，肺里面有积水光靠抽水是没有用的，只能应急，不能根治。\n\n       像肋膜有积水就是所谓的溢饮，溢饮时射干麻黄汤是没有用的。越重的病出现时，经方家用的药反而就越少，溢饮是十枣汤证，此药吃下去三个小时之内就可以将积水清除干净。这里说的是寒饮在肺里面产生的咳嗽，就是射干麻黄汤证。\n\n       大家看此方是将小青龙汤里的芍药与甘草取出，留下麻黄、 生姜、细辛、大枣、半夏、五味子，加入射干、紫苑、款冬花，款冬花这个药，本身就是专门止咳用的，尤其是水饮的咳嗽，大部分都会用到款冬花。\n\n       如果是有痰的咳嗽，我们会用杏仁，杏仁只能祛痰无法 去水，要把水去掉，必须使用款冬花。溢饮的状况之下，肺的气泡会呈现出持续扩张不收缩的状态，扩张就造成『咳而上气』，才会喘不 过气来，因为里面有积水，要把里面的水排掉，就要靠射干。射干能够排水，紫苑能够降逆、下气，就是能让肺泡收缩起来，五味子能够把里面的水气整个排下去，这几个药一直都是配在一起用的。\n\n     细辛是 去寒咳用的，因为病人里寒很盛。肺里面的寒会盛，原因很简单，是 因为肠胃的功能不好了，才会这样，这时候加入生姜、红枣是因为肺 里面有留饮的时候基本上都是来自胸膈，胸膈有湿气下去，就会造成 水气上下不交，于是水气就会慢慢累积起来，日久就变成留饮留在中焦一带，因此水气才会停留在肺里面。生姜能够把横膈这一带的水气 发散掉，所以生姜可以止呕散水。\n\n       如果是脾胃中寒，我们就要靠干姜。 生姜发散，能够将中膈水气去掉，让上下焦能够通利，药性跟干姜是不同的。大家仔细看，射甘麻黄汤中的生姜剂量，看用的有多重就了 解仲师的想法了。平常生姜二片就够了，而这里仲师特别加重生姜的量，其目的是除了止呕以外，还要打散中焦水气用的。\n\n        此处用麻黄是因为它能够让肺扩张，让表寒发表发掉，就是让很多病毒被发汗发掉。所以说张仲景是个预防医学家，一点都不为过。\n\n        留饮留在身体里面，如果不赶快把它去掉的话，造成肺里面的水气过多，于是病毒很容易滋生在里面，日久就会产生别的病变，反而更危险。\n\n        所以仲师用麻黄下去把将水气发表发出去，利用最近的路线将病毒发出去，所以这个方子对『咳而上气』，类似西医讲的『肋膜炎』 或胸腔里有很深的咳嗽，或带有水气的寒性气喘特别有用。\n\n      有浊痰的咳嗽与热性气喘就没有用了。如果射干麻黄汤服下去，病人发汗，小 便也排出来，结果还是没有好，还有但坐不得卧，就是当你还在熬药的时候，病人的病情已经变成十枣汤证。如果你认为药不对了，需要赶快转用十枣汤，其实诸位也不要心急，病情不会变化得如此之快。 就是因为预防病情再进一步，造成失治，所以会再加入半夏来去水。\n', NULL, '射干麻黄汤', NULL, NULL, NULL, '7、咳而上气 ，喉中水鸡声 ，$f{射干麻黄汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653749534801989, '7696507CFEAF9713B7B4C4E6D1B7C654', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:33:42', 1, 'admin', '2025-03-13 17:17:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8139, 448, 905009006, '        肺痿现在诸位都有观念了，简言之就是肺虚。肺痈就是肺实，虚则补之，实则泻之。\n\n        如果是肺痿，『吐涎沫而不咳』，表示肺萎缩掉， 病人一直只吐涎沫而不咳嗽。\n\n     『其人不渴』，诸位看不渴就是寒，热的话就是渴。\n\n     『不渴，必遗尿』，因为肺是管津液，肺在上焦，当肺虚掉 时就不能治水，因为金生水，我们的肺实际上跟我们的膀胱是相通的。 所以有的时候咳嗽没好，一咳嗽，小便就跟着出来，这就是肺可以治水的表现，是治小便的水。\n\n     当肺虚掉后就不能再治水了，于是小便就会遗尿。有时我们看病时，病人抱怨说：「我小便失禁。」中医一看， 此君是下焦寒造成的，就是真武汤证，如果看到是上焦寒，真武汤就没有用了，因为不对症，病人明明是上寒，你给他壮下热，所以就没有用，吃真武汤只是让下焦阳更壮而已，跟天雄散一样，吃了很壮， 可是病人还是照样会遗尿，因为是肺寒引起的遗尿，这就是所谓的『以上虚。不能制下』，上焦肺气虚，所以不能制下，『此为肺中冷，必眩』， 肺中如果有寒时，第一个症状就是头昏。第二个症状，口吐很多涎沫， 这个涎沫都不是浓浊的，是白白的如泡沫状。可以让病人把舌头伸出 来看，舌苔的前半段是苍白的，肺家寒症就是这种舌苔。\n\n    『甘草干姜 汤以温之；若服汤已渴者，属消渴。』甘草干姜汤在这里又出现了， 炙甘草与干姜，是治疗上焦虚寒时用的。还有有一种情况也是属于肺家虚寒，有寄生虫在内，我们后面会介绍到大建中汤证，大建中汤也是肺家虚寒的一种，但是是有虫的症状。如果单纯只是肺的虚寒，甘草干姜汤就可以解决了。\n\n       张仲景不单是名医，而且心慈，大家想想看甘草、干姜这二味药， 你说要花多少钱买？这厉不厉害呢？西医看到 X 光照片说：「哎呀! 肺脏已经萎缩掉了，空间变小了。」然后你问该怎么办，答案是「没办法」。其实用甘草跟干姜就可以治好了，可是他们不会去用的。「这两味药怎么可能会治好？ 」如此病人就完了。\n\n        如果是肺痿，上虚吐涎沫、头晕眩的时候，就有小便遗尿。张仲景的上虚不能治水有两种情形。\n\n        一种是『厥』，就是如果遇到病人有昏迷的现象，这类肺病都很危险的，时常是一发病就走掉了。如果遇到厥盛，就是有昏迷的现象的时候，要加倍用干姜。如果是『痿』比较严重的时候，就是没有昏迷的现象，炙甘草要加倍的用。\n\n      『甘草干姜汤方为专治肺痿』而设，中医分寒热来决定如何选用药物。虚寒时我们就要用温药。厥，除了讲昏迷的现象以外，手脚冰冷很严重也是属于厥症，此时干姜就要加倍用，如果没有手脚冰冷，甘草加倍就好 了。', NULL, '甘草干姜汤', NULL, NULL, NULL, '6、肺痿 ，吐涎沬而不咳者 ，其人不渴 ，必遗尿 ，小便数。  所以然者，以上虚不能制下故也。此为肺中冷，必眩多涎唾，$f{甘草干姜汤}以温之 ；若服汤已渴者 ，属消渴。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653749534801990, '8CD8BCE153207B46A2229EBBD0D2F7DA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:33:42', 1, 'admin', '2025-03-13 17:17:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8140, 448, 905009005, '       如果病人出现『喘而燥』，就称为『肺胀』。中医所谓的肺胀临床看就是西医讲的肺气肿。肺气肿的原因很多，比如我们居住在工厂附 近，又刚好是棉花工厂，或刚好住在地毯工厂旁边，棉絮很多，或是住在空气污浊的地方，像是煤炭工厂旁边等，以前很多矿工得到肺气肿，都是因为空气里面不干净才得到。\n\n        还有老师们写黑板产生的粉笔灰，老师吸多了也会造成肺气肿。此处的肺胀就是现代的肺气肿，肺胀主要症状是持续着吸的状态，没有办法呼。\n\n       吸入后病人的肺可以张开。却不会缩小将空气挤压出来，于是就胀在那个地方，所以吸气就会变得很短。\n\n       张仲景出二方来治疗；第一是当病人肺胀到还可以平卧时，这是一个处方。如果已经不能平卧了，就用另外一个处方。实际上虽说只是短短的一篇，但是他却写的很详细，后面在介绍风水篇时会详加介绍给诸位听。', NULL, NULL, NULL, NULL, NULL, '5、上气喘而躁者 ，此为肺胀 ，欲作风水 ，发汗则愈。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653749534801991, '8D62FC4194864A03EE05A8861459A5ED', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:33:42', 1, 'admin', '2025-03-13 17:17:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8141, 448, 905009004, '       这根本已经是死症。为什么是死症呢？脸孔浮肿起来，代表我们 讲的『阳已虚』。\n\n       阳虚掉后阳气就会整个往上走，到了肺上面还无治 疗时，阳气就会整个冲到头面上来，造成脸浮肿起来。\n\n     『肩息』代表病人的呼吸系统已经不行了，心肺即将衰竭，必须要摇动肩膀才能够深吸一 口气，因为呼吸变困难了。\n\n       如果此时病人脉变成很浮、很大、 很壮的时候，就代表阳脱了。我们人体里的动能与人体的精神即将要 离开身体时就会出现这些现象，这都是不治之症。\n\n       如果『又加利』， 病人大小便都失禁，表示阴又虚掉了；阳虚掉后造成阴再虚掉，当然就是死症。所以当我们看到一个病人阳气在上面，脸都红红的，下面还是在下利，这都是很危险的症状，代表五脏六俯已经不受食物或是药物。为什么说这种一定死症？ 因为此时所有的动能都往上走，病人 连肠胃的蠕动都没有了，这个时候病人喝东西下去立刻就下利出去， 你想这样子可不可怕？这不是快死掉了吗？心肺、脾胃通通衰竭下去，都已经没有功能了。\n', NULL, NULL, NULL, NULL, NULL, '4、上气，面浮肿，肩息，其脉浮大，不治，又加利，尤甚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653749534801992, '6D6D0E2FC5D5F8CC68F8AB80C0A81D71', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:33:42', 1, 'admin', '2025-03-13 17:17:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8142, 448, 905009003, '     『脉浮而数』如果摸到病人寸脉位，脉浮而数，浮就是风，病人  有表风，数就是热，而浮，也代表有表虚，故有汗出。\n\n    『数则恶寒，  风中于卫，呼气不入；热过于营，吸而不出。风伤皮毛，热伤血脉。 风舍于肺，其人则咳，口干喘满；咽燥不渴多吐浊沫，时时振寒。热 之所过，血为之凝滞，蓄积痈脓，吐如米粥。始萌可救，脓成则死。』 这里讲的就是肺脓疡，就是肺化脓、肺痈的原因。会得到肺痈是因为  当病人有表症时，没有及早被治好，才会发生的疾病，如果一开始病  毒在表上就被去除掉，也就没有肺痈的问题。\n\n       西医对病毒的归类。看起来讲的好像很详细，实际上归类并不详细的。西方医学说肝病的人  是滤过性病毒、急性肝炎也是滤过性病毒，感冒也是滤过性病毒，肠炎也是滤过性病毒感染，脑膜炎也是滤过性病毒跑到脑里面造成的， 反正西医都是用滤过性病毒一个病名就将所有疾病都一起带过去。而实际上归类并无法帮忙治病，因为只知道有病毒存在，可是西医不晓 得怎么去掉它们，只想到要如何去杀死它们。\n\n       中医在看诊时遇到这种情形，最重要的观念就是我们事先就知道，这是因为胸腔里面的瘀热没有发散出去所造成的疾病，热闷在里面，就会越来越热，于是就化脓了，简单讲就是这样。所以我们遇到感冒的时候，一定要赶快把病人肺里的热同时一起去掉，否则以后就会有这些后遗症出现。\n\n       肺是诸阳之会，全身所有的阳通通会聚到这里，我们嘴巴里面会有口水升上来，就是肠胃的津液经过肺以后，再到了口中。如果肺有问题的时候，口就会很干，因为肺本身已经很热，津液到肺后就被气化掉了。\n\n       胸阳的地方本来就很热的，现在加上病热没有被排掉，热就会成为壮热，这就是仲师最重要的观念所在。\n\n       如果肺里面太热时，病人就会『口干喘满；咽燥』。如果病人此时反而不渴，就是肺里面已经化脓了，此时肺里面会有很多黏液停在里面，所以病人不觉得口渴。\n\n      如果病人是咽燥口渴，兼有壮热时，这是最标准的阳明经证，表示是因为血里面的水不够了才造成的壮热，这时候我们就要靠人参白虎汤 下去，这就不是因为肺里面的津液不足造成的病，这条辨里讲的是肺里面津液不足时，病人会有的病象，所以渴是一个主要区分的症状， 阳明证必有渴。\n\n      吐浊沫出来就是肺的气管里面的黏液一直排出来，『时时振寒。热之所过，血为之凝滞』就是太热了，血太热也会成为瘀血， 所以也不动了。这个时候，停留在肺里面的病毒就会慢慢的把肺里面的一些肺泡、一些组织逐渐的腐蚀掉，当组织坏死掉后就会化脓。\n\n      刚开始的时候『吐如米粥』，吐出来的痰像白米粥一样。所谓米粥，就是肺炎的病人吐一口痰在地上，过了两、三个小时后，这口痰会变的好大一团泡沫，因为里面都是病毒。『脓成则死』就是吐出来的痰， 像血块一样，掉在水里面就沉下去了。\n\n       浮在水上都没有毒，这是物性， 这痰会沉到水底，表示这毒有多厉害。如果你说：「老师，仲师说脓成则死，我们就不要治，等等看病人会不会死？ 」张仲景虽然如此说， 但是还是出方来治疗。所以现在大家了解到，当肺中积热过久，没有办法完全去掉的时候，有一天就会转化成这样子，这在现代西方医学来说就是肺癌了。\n', NULL, NULL, NULL, NULL, NULL, '3、问曰：病咳逆，脉之，何以知其为肺痈？ 当有脓血吐之则死， 其脉何类？\n\n    师曰：寸口脉浮而数，浮则为风 ，数则为热；浮则汗出 ，数则恶寒，风中于卫，呼气不入；热过于营，吸而不出。 风伤皮毛，热伤血脉。风舍于肺，其人则咳 ， 口干喘满 ；咽燥不渴多吐浊沫 ，时时振寒。热之所过，血为之凝滞，蓄积痈脓，吐如米粥。始萌可救，脓成则死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653749534801993, 'EFAA5582B3FF3C08D6631507588B93E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:33:42', 1, 'admin', '2025-03-13 17:17:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8143, 448, 905009002, '       『寸口脉数，其人咳』，寸口就是讲胸阳上焦的部位，此处的脉如果跳得很数，就代表胸里面很热，数脉就是热脉。\n\n       『其人咳』有咳 嗽，如果有咳嗽同时『口中反有浊唾涎沫者』，吐出来很浓的痰，『师曰：为肺痿之病』，这一种就叫做肺脏萎缩的病。\n\n        浓痰实际上就是肺里面的黏液，我们的气管里面有很多黏膜，黏膜上有很多黏液在。当病人肺里面太热的时候，这黏液的浓稠度就会增加，造成有很多痰液停留在里面，越来越满。\n\n       如果看到吐出很多黏液来，而且很污浊，这表示病人肺的组织已经发炎坏死掉，所以才咳出这些浊痰，一般肺炎病久了都会有这种现象出现，这就叫做肺痿。\n\n        肺痿有时表症看不很清楚时，就需要将衣服拉起来看，如果看到病人肋骨骨缝中间的肉都陷下去，这就是肺脏已经萎缩掉，结果造成肋骨突出来，而肋骨中间的凹缝就变得很深，你的指头可能都可以放到肋 骨里面去。所谓『胸高』，就是息很高，永远是这样绷张的状态之下， 肋骨旁边的肉整个凹下去，可以看到排骨的排列，肋骨本身是不会真的凹下去，我指的是中间的肉，衣服拉开来后看到像洗衣板一样的样 子就对了，临床上可看到左边会比右边来的较饱满？如果是左边凹下去，这表示心脏没力了，因为心脏在左边之故，右胸代表是肺，如果整侧都凹下去，这时候你再看他右耳，耳朵中间点的左右两侧是肺点， 一看耳中肺点出现红红的颜色，红就代表有热。\n\n        临床上要会变通，看 耳朵也可以帮助诊断，我们有很多检查方法可以使用，大家千万不要忘掉。\n\n        张仲景说如果『口中辟辟燥咳，即胸中隐隐痛，脉反滑数，此为肺痈』。肺里面化脓的情形有二种，第一种是正准备化脓，另一种是已经化脓。如何利用症状去区分病人是已经化脓还是准备化脓。由于已经化脓和准备化脓，这二种通通属于肺痈，也就是里面有痈脓了， 这种病情的主要症状就是嘴巴里面一直在咳，可见脓血被咳出来，肺里面也一直发出咻咻的声音出来，然后嘴巴里面很燥、很渴，胸里面会隐隐作痛，这个时候寸口脉也是数脉，但是兼有滑脉。\n\n      『咳唾脓血。 脉数虚者为肺痿，数实者为肺痈。』，同样是数，如果是实热的话，就是肺痈。所谓实就是，不但数，重按都按得到脉，就是里面已经化脓 了。如果是肺痿，是虚症，重接后脉就没了，因为是虚脉，『脉数虚者为肺痿』。简言之实热的话就是肺痈，虚热的话就是肺痿，仲师就是这个意思。\n', NULL, NULL, NULL, NULL, NULL, '2、问曰： 寸口脉数 ，其人咳， 口中反有浊唾涎沫者何？\n      师曰：为肺痿之病。若口中辟辟燥咳 ，即胸中隐隐痛，脉反滑数，此为肺痈 ，咳唾脓血。脉数虚者为肺痿 ，数实者为肺痈。\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653749534801994, 'C408236D0E8823C89264551F1625F5BD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:33:42', 1, 'admin', '2025-03-13 17:17:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8144, 448, 905009001, '       在讲这个之前，大家要先了解，光是说出一个热在上焦，你马上要连想到「寒在上焦怎么办？ 」也就是我们后面要介绍的大建中汤证， 如果是寒在中焦就是小建中汤证，寒在下焦就是桂附八味丸证，慢慢的要让大家都能够很熟练的运用这些经方。\n\n       现在这里说的是热症，我们要求病人说：「先生，请您将舌头伸出来让我看看。」这个舌头的诊断方式是这样的，我们将舌头分成三段来看，舌头最里面就是上焦，舌头的中央是中焦，舌尖的部位就是下焦。如果你舌头最里面黄黄的，就代表上焦有热，如果是中间黄黄的，就是中焦有热，如果黄苔出现又厚又黏就是湿热重症，如果是舌头前面的舌苔很黄厚，就是有溼热在下焦。这个湿热在下焦很可能就是膀胱炎、尿道炎、或者是肛门痔疮等等，这些是舌诊的一部份，舌头上一看，就可以知道热在哪里。\n\n        脉诊中的寸、关、尺也是代表上、 中、下焦的不同位置。如果你摸到一个病人的脉，寸脉跳得很数，但是尺脉却摸不到，这就表示病人是下寒上热，知道病人有下寒，我们就要开去下寒的药像附子、细辛就是了。\n\n      上热我们就要开去热的药，把去上热的药和去下寒的药合并在一个处方中，就是治上热下寒最好用的处方了，这个就是我们经方家开处方的技巧。\n\n      张仲景也要求我们用这种开方技巧才行治病，现在看到病人得到肺痿，表示是上焦太热了。热在上焦，是因为汗发掉以后，热没有去， 还是停留在肺中，日久就造成肺痿。\n\n      举例说像大青龙汤证与麻黄汤证， 大青龙汤是有表寒里热的症状同时出现时用的，如果你开错，应该要开大青龙的，结果你只看到病人表寒很重，没注意到病人同时有里热症，于是就开出麻黄汤，结果麻黄汤吃下去后，表寒是解掉了，但是里热却还在，当肺里面没有津液供给时，肺里面就会过热，这种就是由于汗出过多而造成肺痿。\n\n       第二种情形是『或从呕吐』，有时候呕吐吐太多，土来不及生金，使得中焦津液丧失。土必须要生金，因为肺的津液来源是靠中焦给的，如果肠胃的津液因吐而没有了，这也会造成肺太热，中医讲的热就是『炎』，就是发炎了。\n\n       第三种情形是『或从消渴』，消前面有讲过，就是水喝下去就从小便出来，人体根本不吸收，当然没有办法把水气化给肺，简单讲就是肺的源头没了。肺里的水是从肠胃来的，所以当你被汗、或被吐、 或者从消渴，还有『小便利数』『或从便难』等。\n\n        当病人小便利数， 水都排掉了，当然会大便难，因为津液已经自小便被排除掉了，无论是以上哪一个原因，结论都是因为肺里津液不够了、才产生肺痿，张仲景的意思就是这样。\n\n       当病人本来就有大便难的问题时后，然后『又被快药下利』，就是本来就大便很难，津液不足了，结果医师没看到病人是因为津液不足而便秘，于是选用承气汤来攻下，攻下去以后， 如果病家津液自己流回胃中，就不会有口渴现象，如果病人口渴，代表说病人津液丧失了，这时赶快用白虎汤，去帮助病人补足所丧失的 津液，如果你来不及，是隔了一个礼拜去看他，这时病人就可能转成肺痈了。\n\n        我们开处方给病人时，一定要断症精准，很多现在所谓的肺炎， 就是我们这里讲的肺痈，其实都是因为医师失治才造成的问题。肺炎就是因为感冒没有好，拖延时日才引发的，如果一个人得到感冒，碰到我们经方家，一剂汤药就可以解决，但是也只有我们经方家可以做得到，一般温病派的中医是不行的。\n\n      他们看到病人得到感冒，明明就是麻黄汤证，这汗要靠麻黄才能发表发出来，结果他开出像连翘金银花板篮根之类的药，这是很平和的药。再加上开一点像栀子、柴胡之类一些的药，于是就寄望病家能因此而发汗。然后又怕病人不发汗， 还要求病人用被子将病人全身盖住。如果汗仍不出来，就再加一点葱 在里面给你发汗，弄了半天病人还是不发汗。当表寒强时，非要靠麻黄才能将汗发出来，结果因为不知用麻黄而导致病人不发汗。\n\n       很多肺病的起因，都是最初得到感冒时，医师失治没有将感冒治好，结果日久就转成肺炎。如果现在到处都是经方家的话，大家这辈子就再也遇不到肺炎的病人，我们诊所治疗感冒时都是使用桂枝、葛根、麻黄等汤剂，一剂病就去掉了，当然以后就不会有什么大病，我 一直在鼓励病人以后小病就来找我们，不要耽误时机。一个医院或是诊所看病，应该是病人越来看，病就越轻才对，哪有说越看病越多？ 病情变得越重？西医希望每个人都要有一张病床，这是天方夜谭，这 是什么医学？大家都生病都躺在那边，然后官员说请世界各国来看一 看，我们国家有多照顾百姓，因为每个人都有一张病床，这不是笑话 是什么？\n\n        感冒病毒本来只进入表，停留在皮肤上面，如果用汗法，一发汗它就跑出来。可是如果你来不及发汗，它就已经进入肺里面去了，这就是肺炎的原因之一。还有一种是，病毒一部分进入肺里面，一部分停在皮表上，这时我们就要表里并解，我们会需要用到小青龙汤或大青龙汤来将表症与里症同时去掉，结果医师开错药，又开成去表的药， 没有同时解里，于是表去掉了，里面的病毒还停在肺脏没有去掉，一段时间后就转成肺炎了。\n\n       仲师讲了半天意思就是因为『重亡津液，故 得之。』大家看到此处就会想：「老师，这样子看来后面的处方我们虽然还没看到，张仲景一定想了很多补足津液的方式去治疗。」对的! 西医补足津液的方式就是打点滴，可是打点滴的津液不是从病人胃里面进去的，会有一时之效。中医经方家会用白虎汤来补充失去的津液， 尤其遇到出现高热的会更有效。\n', NULL, NULL, NULL, NULL, NULL, '1、问曰：热在上焦者 ， 因咳为肺痿 ，肺痿之病 ，从何得之？\n \n     师曰 ：或从汗出，或从呕吐 ，或从消渴，小便利数 ，或从便 难 ，又被快药下利 ，重亡津液 ，故得之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 653749534801995, 'BE29D24382B5DF7DE720A20F9ECF567C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:33:42', 1, 'admin', '2025-03-13 17:17:45');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8145, 448, 905009015, NULL, NULL, '桂枝去芍药加皂荚汤', NULL, NULL, NULL, '15、《千金》$f{桂枝去芍药加皂荚汤}方 治肺痿吐涎沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408389, '366CCE5F2A17FC4E64BFE10802574C65', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8146, 448, 905009014, NULL, NULL, '甘草汤', NULL, NULL, NULL, '14、方剂补充《千金》$f{甘草汤} 方  治喉痛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408390, 'B0A3EA20EE611BF44EEA64D2B8CB85CF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8147, 448, 905009013, '          肺胀就是肺气肿，前面说的是肺脓疡、肺痿。\n\n          肺胀，『其人喘』 喘得很厉害，『目如脱状，脉浮大者，越婢加半夏汤主之。』同样是『咳 而上气』，咳而上气就是肺胀的主要症状，病人的胸腔胀起来，持续的呈现只能在吸气的状态之下，这就是肺气胀。\n\n      肺胀气的时候如果病人是『烦躁而喘，脉浮者，心下有水，小青龙加石膏汤主之。』这里有两个方子在治疗肺气胀，就是肺氧肿。越婢汤里有麻黄、石膏，诸 位知道肺胀在里面的时候，热会很重，当热很盛的时候我们会用麻黄、 石膏，这两味大家最热了。\n\n        这里为什么张仲景要加半夏？越婢汤还特 别要加半夏，就是因为病人肺胀的原因是来自中焦脾胃，中焦脾胃受到痰阻，没有办法把津液完全交给肺，于是肺就胀起来，这个时候我们要将中焦横膈地方的痰去掉，所以要加入半夏。\n\n       读到金匮这里后我 们就看懂神农本草经里面一再写到半夏能够降逆，这个什么叫做 『逆』？ 就是有痰阻在横膈膜上，肺气无法下降，于是造成气逆。\n\n       平常我们呼吸的时候横膈膜下降，吐气的时候横隔膜上升，这是正常的， 结果病人无时无刻不管吸气吐气横膈膜都绷紧在上面下不来，此时只有半夏能够把横隔膜往下降，半夏的功能就在这里。\n\n        现在我们大家应该了解到神农本草经里在讲半夏能降逆的意思 了，越婢汤可以加半夏，小青龙汤呢？也有半夏，都用到半夏。主要原因就是『咳而上气，烦躁而喘，脉浮者，心下有水』，心下有水气 的话，病人咳嗽的时候喉咙一定会痒，这叫做水气，你一咳它就散一 下，所以喉咙里面会很痒。\n\n         如果『咳而上气』没有痒，眼睛瞪的很大， 变成圆圆的，黑珠子在中间，这叫做『目如脱状』好像眼珠子要掉出来了的感觉。黑珠在下白区在上面包着，如果这个人没有咳而上气、 没有气喘，这种眼睛叫『暴光』。暴光的人非常的凶，而且恶，这种人做过牢，一般从牢里出来的眼睛都是暴光的。如果他说。「我告诉 你我没有做过牢喔，我是好人喔。」他越告诉你他是好人，然后眼睛 就越暴光，人就越坏。\n\n       像释迦摩尼佛看你时的眼睛是瞇瞇眼，这是好的。眼睛瞪着这么 大干嘛，这是暴光。我们眼睛如果是这样子，叫下三白。这样子，叫上三白。法官在办案子时问犯人说：「你有没有杀人啊？ 」「我没有杀 人!」白珠子在上面或是在下面的，都是杀人犯的眼睛。杀过人以后眼睛都会充满血丝，一看就知他是兇手，眼露凶光。这种除外，如果他没有咳而上气，就是坏人，不是病，干万不要误以为说：「老师， 他是越婢加半夏汤证。」看相跟看病都分不出来，也就不用当医师了。 \n\n     『目如脱状』，『脉浮大』一定是寸脉浮大，为什么会浮？这代表病在肺里面太热了，我们用麻黄就是要开表解热，石膏清里热，石膏是最凉的药，能够清上焦的热。所以气喘咳嗽，不用麻黄的话病人是不会好的。大家看张仲景，多少方子都用到麻黄，后面的小青龙还是以麻黄为主，许多地方大部分都在用麻黄。\n\n        温病派的医生，就是现在外面的中医，麻黄都不敢开，因为担心麻黄太强了，所以药房里面麻黄都用不掉，只有我们经方家在用，但是我们是很少数的中医，所以用量 也很有限。\n\n       小青龙加石膏，小青龙汤里面有麻黄、姜、辛、五、草、 半，但是就没有石膏在内，因为小青龙汤证是表寒里寒，舌头伸出来， 舌苔是白厚的，表示里寒很盛，里寒是不会口渴的，小青龙汤证就无口渴，咳嗽时喉咙很痒。\n\n       大青龙汤证咳嗽也会痒，但是嘴巴很渴，舌苔很黄。而小青龙汤证除了有里寒还有表寒，就是病人有恶寒现象， 所以小青龙汤证的脉一定比较浮紧。除了小青龙汤证的表寒里寒以 外，如果病人同时有肺胀的状态，就是有表寒的状态之下持续有肺气胀、肺气肿的现象存在，我们就要用小青龙加石膏。\n\n        平常是不会得到肺气肿的，大都是外来的因素造成，比方说住在排废气的工厂旁边或 者做矿工的或是水泥工等，这类居住环境都容易引起肺气肿，还有我们抽烟也会容易肺气肿，这时可以在小青笼汤里面加点石膏就可以治疗肺气胀了。\n\n       小青龙汤加石膏，能够清上焦的热，石膏除了清热以外， 最主要是清除肺里面的浊。肺里面太脏了，当肺里面因为有淤积的浊 物，才产生的热的时候，我们一定要靠石膏，石膏就是白虎。还有的人有内伤，像是车祸撞伤，断掉的肋骨插到肺脏里面去以后，把肋骨接回去，结果还是有肺气肿。所以肺受到伤害也会有肺气肿，造成肺持续的扩张，这时都可以用到这个药方。\n\n        大家一定要会区分病人到底是越婢汤加半夏证还是小青龙汤加石膏证，后面要介绍的奔豚气病又会重新再介绍一遍。我们有大便引起的奔豚，有水在下面往上冲起来引起的奔豚，就不是伤寒论讲的这么简单了。\n\n        奔豚完了以后讲胸痹，治疗心脏病，胸痛，心脏病。 胸痹讲完的话心脏病你都会治疗了，就剩下一种绞心痛。\n\n        绞心痛西医已经不治了。遇到真正的心脏病时，西医根本无法治疗，可是我们还是可以治疗。绞心痛有一种就是真正的心脏病，就是瓣膜堵塞或先天生下来已经有缺陷，这种状况我们没办法将病人完全治好，但是可以治到不发心脏病的阶段，其他的通通可以治疗，在胸痹篇里面都会介绍给大家。\n', NULL, '越婢加半夏汤,小青龙加石膏汤', NULL, NULL, NULL, '13、咳而上气 ，此为肺胀 ，其人喘 ， 目如脱状 ，脉浮大者， $f{越婢加半夏汤}主之。肺胀，咳而上 气，烦躁而喘，脉浮者，心下有水，$f{小青龙加石膏汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408391, '69666D0C7664BA05D6F32508DE6375C5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8148, 448, 905009012, '       使用桔梗甘草汤时，比例上桔梗要用一，甘草用二，病人已经化脓，仲师说过脓成则死，这是很危险的时候，绝对不可以用轻剂量一 钱二钱的用，必须用重剂到桔梗一两，甘草二两，加重剂量给病人吃， 排脓汤吃下去，就能够把脓清出来，此时煮法是放进六碗水煮成二碗， 分温再服，病人服后会吐脓血就对了。\n\n        因为肺的组织整个都烂掉了， 就会吐血出来。一般西医遇到肺有脓时就直接去抽脓，病人会很难过。 中医的排脓汤喝下去以后，脓也会被排出来，之后就转成麦门冬汤证了，当病人转成麦门冬汤证后，就表示快要好了。\n\n       多数时我看到大部分的都会转为麦门冬汤证，如果不是麦门冬汤，而是射干麻黄汤证， 就用射干麻黄汤，你需要临症决定，不过不太可能是射干麻黄汤证， 大部分都是麦门冬汤。\n\n       肺脓被排出去以后，同时因为肺的组织也腐烂 掉很多，使得肺整个萎缩上来，这就是标准的麦门冬汤证了。千万要记得，如果你的麦门冬汤里面没有加半夏，就不叫麦门冬汤，以前为了加不加半夏而吵翻，像经方家曹颖甫、唐容川等意见都不一样，他们在吵的就是半夏的使用时机。\n\n        反对者的重点是：「渴怎么可以用半 夏？ 」其实用半夏是取其有降逆之性，可以让胸脯、横膈膜稍微降下来，肺气才有机会重新扩张，这里不靠半夏是不行的。排脓汤从肺结核到脓胸等，我们都可以使用。我们北派经方家，遇到越重的病，我 们用的药就越少，药味少，剂量重，就是经方的特色。\n\n        如果是实寒，所谓的实寒也可以讲寒实。所谓实，就代表有东西挡到，脓胸的痛是热挡到造成的。\n\n       如果是寒堵到而结实，就是三物小白散证。诸位看这个处方名字很好听，叫做三物小白散，事实上最凶的就是它，此药是桔梗、贝母、跟巴豆三味药所组成。因为桔梗、贝 母、巴豆都是白色的，所以名白散。因为这个药很强，只需要吃一点点剂量就好了，所以用小来做名称，这就是三物小白散名字的起因了。\n\n         堵到上焦的寒实。就是三物小白散证。如果是堵在下焦的寒实，就是大黄附子细辛汤证。如果上焦是实热，就是我们的桔梗甘草汤证。\n\n        如果是痰堵在中焦造成的实，就是我们的大陷胸汤证，大家千万不要弄错。如果肺已经化脓，你还使用大陷胸汤就失治了，这时就要靠桔梗甘草汤。\n\n       经方大师曹颖甫，有一次治一个上海浦东陈姓病人，其症状 『胸中痛，咯痰腥臭如米粒』，咳出来一粒粒白色状的痰，其实就是肺结核。初诊时他一看：「糟糕，已经变成脓胸了。」就是已经变成肺脓疡了，这个时候，他用桔梗一两，甘草五钱。其实甘草用得太轻了， 甘草应该用到二两，甘草是解百毒的，又可以和中，但他用的太轻了。 五剂下去胸痛止，止了以后，二诊，他发现肺里面还有许多尚未被清除的像白米的痰，于是用葶苈大枣泻肺汤来去痰水，如果在一开始时就重用甘草，可能就不需要用到葶萨大枣泻肺汤，『五剂而如米粒之脓尽』。第三诊再用千金苇茎汤，因为病人咳出黄浊的痰，于是『五剂而腥臭尽』。\n\n        然而『岂知病根未拔，九月初十日复来』看到腥臭又跟以前一样，这时候再用桔梗甘草汤加冬瓜仁、昆布、海藻、大小蓟来消毒，用犀黄丸九钱，就是犀角地黄丸，犀角是南派用药，所以曹颖甫还是受到南方温病派的一些影响，这里寒凉的药就是犀角，其实还不如用石膏来得更好。\n\n        这里要讲就是这干金苇茎汤了，千金苇茎汤是出自千金要方一书，此书是唐朝名医孙思邈所写的，当他写完千金要方以后，他才看到：「咦？汉朝有个叫张仲景写了伤寒杂病论，写 的很好。」当他看完伤寒杂病论一书后，受到极深的刺激，于是赶快再补写一个千金翼方，就是希望他之前写的千金要方像长了羽翼。\n\n         孙思邈的干金苇茎汤方有四味药，苇茎、薏仁、桃仁、冬瓜仁这四味药。 苇茎就是芦苇的茎，薏仁去湿、桃仁去热活血，能够将痰攻下，冬瓜仁可以宣肺。\n\n        因为病家没有表症，我们用的药就比较缓，像白前、冬瓜仁等比较缓的药来发汗。如果病人没有表症且病人的肺里面都是脓，而你随便就用麻黄来发表的话，结果脓胸一定更严重，因为肺被麻黄打开了。 \n\n       西医遇到结核病时是没有办法的，病人恍惚、面黄肌瘦，整个人都瘦掉了。如果你要瘦很简单，你找个肺结核病人，等他一咳，再打 个喷嚏出来，你赶快去多吸几口，于是就得到肺结核，以后人就瘦掉、 就黄掉了，再也胖不起来了。\n\n      病人的脉是大脉，脉形中间是空的，也就是劳脉，这是结核病的脉诊，结核病西医是无治的。\n\n     我们辨症的方式很简单，看是虚热在里面？还是实热在里面？还是虚寒在里面。只此几个辨症，而就这几方子加减而已。吃对处方，药一下去很快就好转了，同时我们可以在这些方子里面做加减。西医叫结核病人有三黄： 小便黄、皮肤黄、还有眼睛黄。\n\n       黄是脾脏的原色，我们除了用入肺的 药以外，还要有健脾的药一起开在里面，黄就会退掉。病人胃口大开， 精神就恢复了，结核病是可以治疗的，只是你要治他，也要离他远一 点，不然他吐口痰在你家的烟灰缸里，过一段时间，菸灰缸里就有满满的一泡痰在那里。他只吐一小口痰，就变的很大块，因为里面有结 核菌在里面。', NULL, '桔梗汤', NULL, NULL, NULL, '12、咳而胸满 ，振寒，脉数咽干 ，不渴 ，时出浊唾腥臭 ，久久吐脓如米粥者 ，为肺痈，，$f{桔梗汤}主之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408392, 'F2DD1F1FBDCA3E8F2547FED350CD714A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8149, 448, 905009011, '       葶苈大枣泻肺汤是用在肺痈初期时，或是在肺痈进行到中期时都是葶苈大枣泻肺汤证。\n\n       如果已经成脓，此汤就来不及了。葶苈子是属于苦寒的药，涤痰效果很好，属于涤痰的峻药。肺痈一般来说就是肺里面化脓了，类似西医讲的肺脓疡。越重的病，经方用的药反而越简 单。\n\n        先把红枣汤熬好以后，再把葶苈子放在红枣汤里面，再熬一下， 就成药了，然后一次喝下去，葶苈子喝下去的时候病人会吐，因为葶苈子是属于催吐药。\n\n        临床上看的时候，病人喉咙很小，而葶苈子一下去病人一咳，就吐出痰一大块，很腥臭的痰。葶苈子可以将这些脓痰清除干净。病人吃了不想吐都不行一直到吐完为止。强壮的人，用五 钱，瘦子的话，用三钱就可以了。使用时机是已经快要成脓，但是还没有成脓的状态之下的时候用的。\n\n       如果出现『咳而胸满』，再加上咳嗽喘息，然后又有振寒、发冷的现象，表示里面已经化脓。\n\n      脓的范围已经把整个肺包住了，而肺是诸阳之会，因此阳气就没有办法达到皮肤表面上面，所以病人会怕冷，实际上怕冷是病邪挡到了，像麻黄汤证，寒束到表也会有恶寒现象，脓成后也会有怕冷的现象。\n\n       如果你误解以为这里的恶寒是麻黄汤证，于是开麻黄汤给病人，这下就不得了 了，会有更糟的现象出现。病人有的症状，如脉跳得很快，喉咙很干燥，如果是麻黄汤证的话病人不会有咽干，因为肺里面化脓了，很热， 才造成喉咙很干燥。\n\n       当喉咙干燥时表示病人津液不够，此时还用麻黄汤来让病人发表，让病家丧失津液，一定不合理。所以大家要看清楚， 麻黄汤证必有全身骨节痠痛，无咽干的症状，而脓胸没有这些症状， 就只是恶寒而已，千万不要跟麻黄汤证弄混，麻黄汤证完全是用发表 药，后面的桔梗汤是里药。\n\n        病人嘴巴不口渴的时候，又吐出很臭的脓痰，像脓血一样，并不是浊痰。\n\n       皂夹丸吐出来痰很黄很黏的，像胶一样。\n\n      这个脓痰是很浓稠的痰，如果此时不治好，再一段时间，就会吐得像米汁一样，就已经真正成脓了，这时就是西医说的肺癌了。\n\n      如果吐的很浊很臭的，还是要用葶蘑子来攻它，就是葶苈大枣泻肺汤证，如果已经全部成脓，吐出来的痰全部都会像米水一样，白白的颜色呈泡沫状，这就完全进入肺痈了，这个时候就是张仲景所说的桔梗甘草汤证，桔梗甘草汤由两味药组成，用桔梗与甘草二味药而已。\n\n       上次在介绍伤寒论的时候我就 跟大家讲过，经方中有两个排脓汤，第一个，就是这里的桔梗甘草汤， 是专门治疗肺痈用的。第二个排脓汤是当归赤小豆散主治中焦腹膜炎，就是胆结石造成胆管破裂，变成腹膜炎，还有盲肠炎治疗太慢转变成腹膜炎，这是下焦腹膜炎，讲到肠痈篇我再跟各位详细介绍当归赤小豆散的用法。\n', NULL, '葶苈大枣泻肺汤', NULL, NULL, NULL, '11、肺痈 ，喘不得卧 ，$f{葶苈大枣泻肺汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408393, 'A14387C8FE3E7058F2E12A179382AAE7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8150, 448, 905009010, '      诸位在麦门冬汤旁边写一个『肺痿，虚热用之』。肺痿是寒症， 诸位都知道要用甘草干姜汤。如果肺痿是虚热，就是麦门冬汤证。虚热，也会有肺痿，肺痿如果是因寒引起，可以看到病人口吐涎沫，嘴巴不渴，这就是寒症，我们要用甘草干姜汤。如果是虚热，代表肺的津液没了，二者的病因是相同的。\n\n       当肺里面的津液变的很干燥的时候 肺会收缩起来，同样的原因，但是一个是寒一个是热，都会造成肺火上逆的现象，这种状态之下，肺因为津液干燥，『火逆上气、咽喉不 利』，肺萎缩也会使横膈膜缩上来，横膈一被牵动就会影响到我们吞东西。\n\n        我们中医认为半夏、生姜能够止呕，就是半夏一下去，横隔就往下降，能够让你吞东西就不会恶心。\n\n     『咽喉不利』就是吞嚥食物都 有困难，喝水都喝不下去，此时『止逆』的同时；也需要把这个肺痿去掉，就是麦门冬汤证了。\n\n     此方内有人参、甘草、粳米、大枣就是要 补足肠胃的津液。张仲景认为，肺痿虚热的原因很简单，就是开始于肠胃的津液不足，病人可能是发汗发太多了，导致肠胃津液的不足， 所以第一个动作就是先把肠胃津液补足。\n\n        这里加入半夏，前面有讲过燥不能用半夏，现在这里燥要用半夏， 原因是避免病人还有浊痰在肺里面，靠半夏把肺里面与横膈膜清除干净以后，使得新生出来肠胃的津液才能去补肺，交给肺的同时加入麦门冬，麦门冬是中药里面非常好的润肺的药物，当肺的津液不够时， 我们要靠麦门冬来润肺。\n\n        肺萎缩掉后气会上逆，要让胸隔下降，就要靠半夏，把胸膈降下来。加了粳米下去是因为得了重病的人一定一段时间没有吃东西，所以光把肠胃的津液补足是不够的，还同时要给病 人一点营养。\n\n        张仲景真的很聪明，他加粳米下去，所以他连病因都考虑到了。吃了麦门冬汤就算病人有几天都没吃饭，也可以将营养补足。 如果你光是麦门冬汤没有加粳米，病人吃完后，肚子会很饿，而且已经好几天没有吃东西，病人是不懂得病后需要调养。\n\n      张仲景就是怕碰到病人才恢复，肠胃功能还没有完全很好的时候，就开始大吃特吃一 些很难消化的东西，结果就发生肠胃发炎、下利等等。当肠胃功能尚未恢复正常时，吃到不干净的东西，排又排不掉，于是会在肠胃里腐烂掉，自然会变成肠炎。仲师就是怕这样子，所以说干脆用粳米给病 人吃下去，吃完药也不很饿，逐渐的吃进一点清淡的食物，让体力慢慢的恢复。\n', NULL, '麦门冬汤', NULL, NULL, NULL, '10、火逆上气 ，咽喉不利 ，止逆下气者 ，$f{麦门冬汤}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408394, '100B74B97EF20EDAD61829E3F82C42B4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8151, 448, 905009009, '       这里把两个处方放在一起，其实这两个都是治疗肺气肿的处方， 如果，『咳而脉浮者，厚朴麻黄汤主之。』『咳而脉沉者』浮指病在表， 沉指病在里，如果单纯是有痰饮在肺里，没有表症，我们就用泽漆汤。\n\n        如果同时有表症与里症，我们在祛痰的同时就要发表。所以厚朴麻黄汤中，有加厚朴、麻黄、石膏。把麻黄石膏杏仁放在一起就是麻杏甘石，不要放甘草，如果只为解除肺热，用麻杏甘石汤就可以了。此处因为有水在里面，而甘草会蓄水，所以我们只用半夏去利水。用干姜、细辛是因为里寒很盛，选用小麦这个毂类是因为肠胃的津液不足，我们就用小麦，这是有表症兼有里症就会用到此方。\n\n        这个时候为什么不用生姜、甘草、大枣，是因为他的病在肺在里面，我们加发表的药， 使用麻黄时就已经有杏仁在里面，这个时候你不需要再加甜腻的药在里面，因为甘的药会增加痰水，所以用一点小麦，把胃里面津液补足就好，淡淡的没有味道下去就可以了。\n\n       如果此时用甜味的药，很多药会跟着甜味跑，于是药就跑到脾胃里面，脾主甘，脾脏要是吃到甜的， 就会一直吸收，于是药力就会被分散掉。此处的五味子是敛咳用的。 所以厚朴麻黄汤，本身不但能够开胃和表，最主要是使用于当肺有病又兼有表症时用的。\n\n        泽漆汤是用在没有表症，只有里症时用的，此时是有肺水在里面造成的肺气肿。\n\n       用半夏是治水，里面有紫参，紫参可以用紫根取代， 有另外版本是用紫菀，是专门『开郁结』，紫根本身并不能够利水， 而是当肺有气郁在这里使用。\n\n       这里的气郁和水积不太一样，如果是水积到的话，呼吸会有水声。没有水声，只是胸口很闷，紫根能够让胸口郁气散开来。\n \n      生姜能够去饮，白前能够宣肺。\n\n      白前这个药，类似麻黄，但是没有麻黄这么强。\n\n      麻黄可以从肺一直开到皮表毛孔上去，而 白前是直接停在肺上面，将肺脏打开来，使肺的气不会那么闷。\n\n      甘草是安脾脏用，黄芩能去上热，能够泻热、泻肺热。\n\n     人参可以补气、补 肺的。\n\n      这个处方叫泽漆汤，当然是以它为主力，泽漆又叫做『大戟』。 \n\n     大家记得十枣汤里面，有三味药，甘遂、芫花、大戟。张仲景说脉沉， 就是到了悬饮阶段，这是十枣汤证，此时脉就变的很弦。弦就是水脉， 代表水已经从肺组织里溢出来了。我们的肺跟我们的胸孔膜是叠在一 起的，那里有很多间隙，就是我们中医说的『水巢』，这就是积水的地方。水会积到这里，就是因为肺泡有水堵到，这个时候就要靠大戟 了，泽漆汤也可以叫做大戟汤。\n\n       简言之肺里面有积水，如果是在气管上面诸位就可以看到射干麻黄汤证，主症是呼吸有水鸡声。如果是在肺泡里面，我们就用泽漆汤， 因为泽漆汤，能够清除这里的水饮，让肺气往下降，同时此方又可以和胃，把肠胃的功能补足，同时把肺水清掉，又能将肺气往下降。\n\n       这个泽漆汤证的主要症状是咳、脉沉，沉脉代表有水积在肺泡里面。连续几个处方都治咳，而且都有水积之症，所以大家要记得其深浅不一， 而要用不同的处方。\n\n       所以泽漆汤又比射干麻黄汤来的更强，来的更重。 泽漆汤的后面说，『三升以东流水五斗煮取一斗五升』，你千万不要去找东流水，你拿罗盘来测，从东方来的水叫东流水，不需要这么麻烦的。这是中国以前的阴阳五行的学说误导人的，反正都是水，无所谓 的。\n\n      这个泽漆汤服下去后，大部分的水会从嘴巴吐出来，还有小便利出来。十枣汤吃下去后，小便都来不及利了，水会从大肠一路泻出来， 水一去掉，胃口就大开了。和胃的药像生姜、甘草、人参、桂枝能够行阳，能够和胃的。\n\n     降逆的药像半夏能够利水，又能把肺气往下降。 其它的像白前开肺。有水以后就有炎，所以张仲景常常用黄芩，用黄芩就是因为肺里面有不正常的水溢出在外面，不在水道系统里面，这种环境都是最容易让病毒滋生在里面，所以他每次一剂药方开出后， 都会加一些消炎药在里面。黄芩这种是属于消炎药，中医讲的『去热药』，与西医讲的消炎药是同样意思，免得说把病治好了以后，结果肺里面还遗留些病毒在里面。\n\n       张仲景会知道这样做，都是靠临床经验出来的。所以做为一位好医师要会瞻前顾后，自己处方自己心里面要了解，治疗这病后又跑出其他的病来，就是处方不够周密完善，就是有一部分问题你没有考虑到所造成的。', NULL, '厚朴麻黄汤,泽漆汤', NULL, NULL, NULL, '9、咳而脉浮者，$f{厚朴麻黄汤}主之。咳而脉沉者，$f{泽漆汤}主 之。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408395, '518D58767ED989ADAF46F2F3D9279A1D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
INSERT INTO `BookBody` (`BookBodyId`, `BookInfoId`, `ReceiptNo`, `SectionNote`, `SectionVideoMemo`, `FangJi`, `FangJiZhujie`, `BieMing`, `SectionVideoUrl`, `SectionText`, `SectionTerm`, `JingMai`, `TeDian`, `ShiCi`, `ShiYi`, `Notes`, `ZhuZhi`, `ZhenJiu`, `AiJiu`, `PeiWu`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8152, 448, 905009008, '       『咳逆上气，时时唾浊，但坐不得眠』，病人这是已经到了但坐 不得眠的阶段了，『皂荚丸主之』。\n\n         刚刚讲的是水饮停留在肺里面，而皂夹丸证是浓痰、浊痰停积肺中造成的但坐不得卧。皂夹丸平常用到的不多，以现代来说，只有像遇到抽烟抽得很重的人才会用到皂夹丸。 \n\n        在民国初年时，抽鸦片的人用的最多。那种胶痰吐出来，硬硬的一块， 整块黄黄黏黏的，就是热痰、浊痰之类，此类的痰只有皂夹丸才能去掉。\n\n      不要开错方子，千万不是：「老师，咳出来有痰，我们用射干麻 黄汤。」结果原本是热痰，被你弄成胶痰，因为水被排掉痰却没去， 于是痰就变得干干硬硬的，所以辨症不能出错，本来是一个很简单的麻杏甘石汤，结果被你用射甘麻黄汤一发表，汗被发掉，结果变成皂夹丸证。\n\n        过去我们有个方子叫桂枝汤去芍药加皂夹，此方证常出现在当小孩子的运动量很大，流汗流得很多，而小孩子原本就有心脏病，所以有胸满的症状，当出现桂枝汤证时，病人咳嗽又有痰，此时痰已经是浓痰了，就是因为津液已经被他的好动先发散掉，现在因为有胸满， 所以我们不能加芍药，芍药会增加胸满，遇到心脏病人必须将芍药拿掉，要去浓痰，只好加一枚皂夹，一起熬在汤剂里面，一剂下去就可以全部清除掉，所以大家只要看到黄痰都可以使用皂夹。如果皂夹是加在桂枝汤里面，由于桂枝汤里本来就有大枣，此时大枣就要加重一点，因为大枣可以缓和皂荚的硷性，否则就会伤胃。\n\n         皂夹丸制作方式是，『八两刮去皮酥炙』。酥炙就是说先把它烤焦， 再把皂夹表面皮被烤黑的部分刮掉再入药。『枣膏和汤服三丸， 日三 夜一服』，一天吃四次，这个都是要饭后吃，睡觉前再吃。吃皂夹丸的时候，因为它是硷性的药，到胃里面会跟胃酸中和掉，这个时候需要熬得很浓的红枣汤，来配合吞服这皂荚丸，就不怕伤到胃。\n\n         为什么要饭后吃？所有要入胸膈的药、入上焦的药都让病人饭后吃，使药能停留在上焦，这样就可以清出很多的黄胶痰，从大便排出去。所以如果你到医院去看病人，才走到门口就听到病人的咳嗽声或是呼吸声是像有人在拉锯子一样。你问：「老师，他是水饮还是痰饮？ 」你只要将门打开来一看，病人床边还摆着一包烟，就知道是『痰饮』，如果病人从不抽烟，多是水饮。痰声跟水声是完全不一样的，痰声好像在拉锯子般，水饮声是「咕噜咕噜」的像鸡在叫，你可以听的很清楚， 很好区分的。\n\n', NULL, '皂荚丸', NULL, NULL, NULL, '8、咳逆上气 ，时时吐浊 ，但坐不得眠 ，$f{皂荚丸}主之。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 654099508408396, '812BAA21072425EFED91B70C11E0ECAB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:45', 1, 'admin', '2025-03-13 17:17:44');
